INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(1, 2, 'Ayam Bumbu Bawang', 'Resep ayam goreng sederhana dengan marinasi bumbu bawang yang gurih dan meresap.', '[\"1 dada ayam fillet, cuci bersih, potong kecil2\", \"1 buah jeruk nipis\", \"Bumbu marinate:\", \"5 siung bawang putih\", \"1 sdt lada hitam\", \"secukupnya Gula dan garam\", \"Minyam goreng\"]', '[\"Kucuri ayam dengan air jeruk nipis, kemudian marinate dengan bumbu halus selama 3 jam di kulkas\", \"Panaskan minyak, goreng ayam sampai matang dan kecoklatan\", \"Sajikan hangat dengan nasi putih.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', '', '2025-10-23 15:09:44', '2025-11-09 16:10:24'),
(2, 2, 'Ayam Woku Manado', 'Resep Ayam Woku Manado yang lezat dan mudah dibuat.', '[\"1 Ekor Ayam Kampung (potong 12)--2 Buah Jeruk Nipis--2 Sdm Garam--3 Ruas Kunyit--7 Bawang Merah--7 Bawang Putih--10 Cabe Merah--10 Cabe Rawit Merah (sesuai selera)--3 Butir Kemiri--2 Batang Sereh--2 Lembar Daun Salam--2 Ikat Daun Kemangi--Penyedap Rasa--1 1/2 Gelas Air--\"]', '[\"Cuci bersih ayam dan tiriskan. Lalu peras jeruk nipis (kalo gak ada jeruk nipis bisa pake cuka) dan beri garam. Aduk hingga merata dan diamkan selama 5 menit\", \"biar ayam gak bau amis.--Goreng ayam tersebut setengah matang\", \"lalu tiriskan--Haluskan bumbu menggunakan blender. Bawang merah\", \"bawang putih\", \"cabe merah\", \"cabe rawit\", \"kemiri dan kunyit. Oh iya kasih minyak sedikit yaa biar bisa di blender. Untuk sereh nya di geprek aja terus di buat simpul.--Setelah bumbu di haluskan barulah di tumis. Jangan lupa sereh dan daun salamnya juga ikut di tumis. Di tumis sampai berubah warna ya 👌--Masukan ayam yang sudah di goreng setengah matang ke dalam bumbu yang sudah di tumis\", \"dan diamkan 5 menit dulu. Biar bumbu meresap. Lalu tuangkan 1 1/2 Gelas air. Lalu tambahkan penyedap rasa (saya 3 Sdt\", \"tapi sesuai selera ya) koreksi rasa dan Biar kan sampai mendidih--Setelah masakan mendidih\", \"lalu masukan daun kemangi yang sudah di potong potong. Masak lagi sekitar 10 menit. And taraaaaaaaaaaaaaa..... jadi deh Ayam Woku Manadonya.--Oh iyaa kalo mau di tambahkan potongan tomat merah juga bisa ko. Sesuai selera aja yaa buibuuuu 👌👌👌--\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', '', '2025-10-23 15:17:49', '2025-11-09 16:10:13'),
(3, 2, 'Gurame Saus Padang', 'Resep Gurame Saus Padang yang lezat dan mudah dibuat.', '[\"Bahan utama:--1 ekor gurame--Bumbu untuk saus:--4 siung bawang putih (cincang halus)--3 siung bawang merah (cincang halus)--15 bh cabai merah (giling) banyaknya cabai sesuai selera ya😊--7 buah cabai rawit iris tipis (sesuai selera)--1/2 bawang bombang iris--Saus tiram--Saus tomat--Garam--Gula--Lada--1 bh wortel iris tipis memanjang (opsional)--1 buah tomat potong dadu (opsional)--1 batang irisan daun bawang--1 ruas jahe ukuran kecil iris tipis--Tepung maizena--250 ml air--Bumbu untuk menggoreng ikan :--Tepung beras--Tepung terigu--Garam--Jeruk nipis/ lemon--Minyak sayur--\"]', '[\"Cuci bersih ikan gurame yang akan dimasak. Setelah itu lumuri ikan dengan air perasan jeruk nipis/lemon diamkan beberapa menit untuk menghilangkan bau amisnya--Campur tepung terigu\", \"tepung beras dan garam menjadi satu\", \"kemudian lumuri ikan dengan tepung tersebut lalu goreng hingga matang lalu tiriskan. Pastikan minyak yang digunakan sudah panas ya biar ikannya tidak lengket😊.--Tumis bawang merah bawang putih hingga harum\", \"kemudian masukan cabai yang sudah giling\", \"aduk rata--Tambahkan bawang bombay\", \"saus tiram saus tomat dan jahe\", \"aduk sebentar lalu tambahkan 250ml air--Kemudian tambahkan garam dan gula sesuai selera.--Masukkan irisan cabai rawit dan daun bawang dan tomat. Aduk rata. Kemudian tambahkan larutan maizena agar saus mengental--Jika tidak ada tepung maizena. Diamkan beberapa menit hingga kandungan air menyusut dan saus terlihat mengental--Tes rasa. Jika sudah pas. Sajikan dan gurame saus padang siap disantap!😊--\"]', 'http://localhost:8080/assets/gurame-saus-padang-1.jpg', 'approved', '', '2025-10-23 15:18:12', '2025-11-22 11:00:51'),
(4, 2, 'Sate Kambing', 'Resep Sate Kambing yang lezat dan mudah dibuat.', '[\"Bahan-bahan :--500 gr Daging kambing--Daun pepaya--Bumbu yang dihaluskan :--4 siung bamer--4 siung baput--2 cm jahe--1 sdt ketumbar--1/2 sdt lada bubuk--1/2 sdt Garam--1 sdm air asam jawa--Bahan sambel kecap :--Kecap manis sesuai selera (aku pake bango)--Cabe rawit--Bamer--Tomat--Jeruk limau--\"]', '[\"1. Cuci bersih daging kambing\", \"potong\\\" kotak\", \"bungkus didalam lapisan daun pepaya (30menit)--2.setelah 30 menit\", \"keluarkan daging dr daun pepaya\", \"campurkan dengan bumbu yang sudah dihaluskan\", \"diamkan 15 menit--3. Susun daging pada tusuk sate kurlen 4-5 potong per tusuk--4. Bakar (bisa pakai arang / teflon)--5. Bolak balik sate hingga benar\\\" matang--6. Sajikan dengan sambal kecap--\"]', 'http://localhost:8080/assets/sate-kambing-1.jpg', 'approved', '', '2025-10-23 15:18:52', '2025-11-22 11:00:11'),
(5, 2, 'Beef Teriyaki', 'Resep Beef Teriyaki yang lezat dan mudah dibuat.', '[\"250 gr daging sapi--1 siung bawang bombai--5 siung bawang putih--1 sachet saus teriyaki (sy pk yg saor*, bsa diganti saus tiram)--1 sdm kecap manis--secukupnya garam--secukupnya lada--secukupnya gula--secukupnya penyedap rasa--\"]', '[\"Potong kecil-kecil memanjang daging sapi, lalu cuci bersih--Tambahkan garam dan lada diamkan selama kurleb 15 menit--Iris bawang bombai dan bawang putih--Tumis bawang bombai dan bawang putih, setelah harum masukkan daging--Tumis daging sebentar lalu tambahkan saus teriyaki, kecap manis, garam, lada, gula dan penyedap rasa, beri air sedikit--Tutup wajannya agar panasnya merata--Tunggu sampai daging matang, lalu garnish sesuai selera--Beef teriyaki siap untuk disantap--\"]', 'http://localhost:8080/assets/beef-teriyaki-1.jpg', 'approved', '', '2025-10-23 15:19:15', '2025-11-22 10:59:17'),
(6, 2, 'Martabak tahu pedas kulit lumpia', 'Resep Martabak tahu pedas kulit lumpia yang lezat dan mudah dibuat.', '[\"12 lembar kulit lumpia--4 buah tahu putih--2 batang daun bawang (iris halus)--1 batang daun seledri (iris halus)--3 btr telur (sy pakai 2 aja krn agak besar)--1 sdm terigu + 2 sdm air (sbgai lem kulit lumpia)--Sckpnya minyak utk menggoreng--Bumbu halus :--3 siung bawang putih--1/2 bks lada/merica bubuk--Sckpnya garam gula dan kaldu bubuk--3-4 cabe merah kriting iris serong--2 buah wortel agak kecil parut kasar--\"]', '[\"Haluskan tahu putih campur semua bahan kecuali kulit lumpia (icip rasa)--Ambil 1 lbr kulit lumpia beri 1 sdm adonan tahu ditengahnya lalu lipat (seperti amplop) dgn rapi, lalu beri lem disetiap sisisnya spy tdk terbuka pd saat digoreng, lakukan hingga habis--Panaskan minyak diatas wajan dgn api sedang cenderung kecil, goreng martabak sampai kecoklatan angkat dan tiriskan (abaikan wajannya yg sdh mulai jelek ya 😁)--Martabak tahu pedas kulit lumpia siap dihidangkan--Selamat mencoba\", \"😘😘--\"]', 'http://localhost:8080/assets/martabak-tahu-pedas-kulit-lumpia-1.jpg', 'approved', '', '2025-10-23 15:19:42', '2025-11-22 10:58:22'),
(7, 2, 'Orak arik telur buncis', 'Resep Orak arik telur buncis yang lezat dan mudah dibuat.', '[\"1 buah telur--10 buncis--3 bawang merah--2 bawang putih--6 cabe rawit--1 sdm kecap manis--Penyedap (garam gula atau penyedap lainnya)--\"]', '[\"Haluskan bawang merah\", \"bawang putih dan cabai--Iris buncis sesuai selera--Tumis bumbu halus hingga harum--Masukan buncis hingga agak layu--Masukan penyedap--Masukan telur\", \"lalu campur dengan buncis di orak arik hingga rata.. tunggu sebentar lalu di orak arik lagi.. supaya matangnya sempurna 👌(biar ga amis)--Masukan kecap manis--Masukan air sedikit biarkan menyusut dan meresap--Koreksi rasa--Jadi deh.. selamat menikmati 😇--\"]', 'http://localhost:8080/assets/orak-arik-telur-buncis-1.jpg', 'approved', '', '2025-10-23 15:20:07', '2025-11-22 10:57:19'),
(8, 2, 'Orek tempe manis pedas super simple', 'Resep Orek tempe manis pedas super simple yang lezat dan mudah dibuat.', '[\"Tempe (saya beli 3000 saja)--3 buah cabe gendot--3 buah cabe keriting--3 buah cabe rawit merah--2 siung bawang merah--1 siung bawang putih--Kecap--Saus tiram--Saus tomat--Kaldu bubuk--Garam--Gula--\"]', '[\"Potong2 tempe sesuai selera lalu goreng sebentar.--Tumis duo bawang dan semua cabe (cabe bisa sesuai selera ya pedesnya suka segimana) sampai harum. Masukkan tempe\", \"kecap\", \"saus tiram\", \"saus tomat\", \"kaldu bubuk\", \"gulgar\", \"dan tambahkan air satu gelas belimbing. Aduk2 dan tutup wajan.--Saat air sudah menyusut dan kuah kecap mengental. Cek rasa. Klo sudah oke. Matikan api. Sajikan. (Klo aku suka airnya sedikit sekali 😋). Selamat mencoba !--\"]', 'http://localhost:8080/assets/orek-tempe-manis-pedas-super-simple-1.jpg', 'approved', '', '2025-10-23 15:20:29', '2025-11-22 10:56:15'),
(9, 2, 'Lumpia udang kulit tahu', 'Resep Lumpia udang kulit tahu  yang lezat dan mudah dibuat.', '[\"50 gram ayam potong kotak kecil--200 gram udang besar potong kecil--1 lembar daun bawang iris halus--1/2 sendok teh garam halus/sesuai selera--1/2 sendok teh gula--1/4 sendok teh merica bubuk--1 sendok teh kecap ikan--1 sendok teh saus raja rasa--1 sendok teh saus tiram--1 sendok teh minyak wijen--1 sendok makan tepung sagu--1 sendok teh tepung terigu--1 butir telur ambil bagian putihnya saja, kocok lepas--2 lembar kembang tahu kering / kulit tahu direndam sebentar--\"]', '[\"Campur ayam & udang dengan semua bumbu & daun bawang\", \"aduk rata. Sesudah rata masukkan tepung sagu\", \"terigu & putih telur. Aduk rata.--Isikan ke lembaran kulit kembang tahu & lipat seperti melipat lumpia\", \"sambil dipadatkan agar rapi & bentuk agak pipih jangan terlalu bulat. Olesi putih telur diujung lipatan agar merekat rapat.--Kukus sekitar 15 menit hingga matang. Angkat dinginkan. Siap digoreng dengan api kecil sebentar. Anakku suka digoreng agak lama dengan kuning telur kocok sisa adonan tadi. Nanti jadi ada kayak jala2 crispynya yang gurih & kering. Angkat & tiriskan jika sudah digoreng matang.--Sajikan dengan dipotong diagonal (potong 2 serong). Siap disantap dengan saus sambal botol yang biasanya saya rebus dengan bawang goreng\", \"cabe rawit iris\", \"gula & sedikit air. Selamat mencoba.--\"]', 'http://localhost:8080/assets/lumpia-udang-kulit-tahu-1.jpg', 'approved', '', '2025-10-23 15:21:07', '2025-11-22 10:55:30'),
(10, 3, 'Ayam goreng tulang lunak', 'Resep Ayam goreng tulang lunak yang lezat dan mudah dibuat.', '[\"1 kg ayam (dipotong sesuai selera jangan kecil2 ya)--2 batang serai (memarkan)--4 lembar daun jeruk--7 butir bawang putih (haluskan)--1 sdm ketumbar (haluskan)--3 ruas jari Laos (haluskan)--3 ruas jari kunyit (haluskan)--2 butir kemiri (haluskan)--secukupnya Garam--Secukupnya Air (tuk ukep ayam)--Secukupnya Minyak goreng--\"]', '[\"Haluskan bumbu2nya (BaPut, ketumbar, kemiri, kunyit, Laos, garam) hingga halus, sisihkan--Campur kan bumbu halus tadi dengan ayam yg sudah dicuci bersih dan sudah dipotong didalam panci presto\", \"Uleni sampai tercampur rata\", \"--Tambahkan air hingga ayam tenggelam semua\", \"Masukkan serai dan daun jeruk nya kedalam rendaman ayam\", \"Tutup panci presto rebus/ ukep presto sampai kurleb 45 menit\", \"Dengan api sedang\", \"--Setelah proses ukep presto selesai, tunggu suhu dingin ruang\", \"Lalu goreng ayam dengan minyak goreng api sedang sampai ayam berwarna kecoklatan\", \"--Matang dan sajikan ayam selagi hangat bersama nasi putih, sambal dgn perasan jeruk nipis, lalapan\", \"--\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', '', '2025-10-23 15:24:27', '2025-10-26 07:21:51'),
(11, 3, 'Ikan Kembung Bakar Teflon', 'Resep Ikan Kembung Bakar Teflon yang lezat dan mudah dibuat.', '[\"1/2 kg ikan kembung sate, bersihkan--1 buah jeruk sate/jeruk kunci--1 sdm garam halus--2 sdt lada bubuk--1 sdm ketumbar bubuk--\"]', '[\"Kucuri ikan dengan jeruk, diamkan 5 menit--Lumuri ikan dg garam, lada dan ketumbar bubuk, simpan d kulkas sekitar 30 menit--Bakar d atas teflon yg d olesi mentega/ butter tipis dengan api yg kecil--Balik untuk membakar kedua bagian ikan\", \"--Sajikan dengan cocolan sambal kecap--\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', '', '2025-10-23 15:25:16', '2025-10-26 07:21:55'),
(12, 3, 'Rabeg Kambing', 'Resep Rabeg Kambing yang lezat dan mudah dibuat.', '[\"1 kg daging kambing bagian paha beserta tulang--Bumbu halus--100 gr cabe--7 siung bawang putih--8 siung bawang mersh--7 butir kemiri--2 cm jahe--1 ruas kunyit--1/2 sdt klabet--1/2 sdt jinten--Bumbu lain--1 batang sereh--3 lembar daun salam--2 cm kayu manis--5 butir cengjeh--3 kapulaga hijau--5 sdm kecap manis--Garam--Gula--Pelengkap--Acar--Bawang goreng--\"]', '[\"Tumis bumbu halus hingga harum. Masukan bumbu bumbu lain kecuali kecap.--Masukan daging kambing. Aduk sampai daging terbalut bumbu dan berubah warna--Pindahkan tumisan daging ke panci. Tambahkan air. Beri kecap gulz dan garam. Masak sampai daging empuk dan air tinggal sedikit--Sajikan dengan nasi dan pelebgkap--\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', '', '2025-10-23 15:25:30', '2025-10-26 07:21:59'),
(13, 3, 'Rendang Sapi', 'Resep Rendang Sapi yang lezat dan mudah dibuat.', '[\"1 kg daging sapi--4 butir kelapa untuk 2L santan kental--Bumbu dihaluskan :--200 gram Cabe merah--1/2 cm Jahe--2 sdm ketumbar sangrai--10 butir kapulaga--10 butir cengkeh--2 butir bunga lawang--1 buah biji pala--13 butir bawang merah--7 butir bawang putih--25 buah cabe rawit (jika suka pedas)--3 cm lengkuas dipipihkan--2 buah serai dipipihkan--3 lembar daun jeruk--3 lembar daun salam--2 lembar daun kunyit--1/2 sdm garam (tambahkan jika kurang asin)--1 sdt kaldu bubuk (optional)--\"]', '[\"Potong daging berlawanan dari seratnya--Peras santan dari 4 butir kelapa tua menjadi 2 liter--Haluskan bumbu--Tuang santan dan bumbu ke dalam wajan anti lengket, masak hingga mendidih--Kemudian masukkan daging, garam dan kaldu\", \"Masak dengan api kecil sambil sesekali di aduk agar tidak gosong--Sampai tahap ini dinamakan kalio, teruskan memasak hingga daging mulai mengering dan kehitaman--Rendang siap dinikmati--\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', '', '2025-10-23 15:25:45', '2025-10-26 07:22:03'),
(14, 3, 'Batagor (Bakso Tahu Goreng) ala rumahan anti gagal', 'Resep Batagor (Bakso Tahu Goreng) ala rumahan anti gagal yang lezat dan mudah dibuat.', '[\"Bahan batagor--3 kotak ukuran kecil tahu kuning--5 sdm tepung terigu--1/2 sdm mentega (supaya kriuk2)--2 buah bawang putih--Garam (secukupnya)--Merica (secukupnya)--Air putih matang (secukupnya)--Bahan saus--2 sdm saus cabe (saya pake indofo**)--1/2 siung bawang putih--2 cabe rawit (sesuai selera ya karna suami saya gak suka pedas)--Kecap (secukupnya)--Air matang (secukupnya)--\"]', '[\"Haluskan tahu kuning, bawang putih, garam merica (hingga lumat)--Tambahkan mentega, tepung terigu kedalam adonan tahu dan beri air hingga lembek tapi jangan sampai encer ya\", \"Koreksi rasa--Siapkan wajan dengan minyak, goreng adonan yang telah dibuat\", \"(Saya pake 2 sendok buat bikin kecil2)\", \"Angkat dan tata di mangkuk\", \"--Haluskan bawang putih, cabai rawit--Tumis bawang putih dan cabai yang sudah di haluskan hingga harus\", \"--Masukkan saus, kecap, garam\", \"Koreksi rasa--Batagor dan sausnya siap untuk dinikmati 🤤--\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', '', '2025-10-23 15:26:04', '2025-10-26 07:22:07'),
(15, 3, 'Terik ayam tempe telor', 'Resep Terik ayam tempe telor yang lezat dan mudah dibuat.', '[\"4 sayap ayam--4 buah telor--1/2 papan tempe--Bumbu halus:--5 siung bawang merah--4 siung bawang putih--2 butir kemiri--1/2 sdm ketumbar--secukupnya Garam--Bumbu lain:--2 cm lengkuas--1 lembar daun salam--1 batang sereh--secukupnya Gula jawa--Bawang goreng--Minyak untuk menumis--1 bungkus santan kara--secukupnya Air--5 buah cabe rawit--\"]', '[\"Cuci sayap ayam kemudian sisihkan. Rebus telur dan kupas. Sisihkan. Potong tempe sesuai selera. Sisihkan.--Panaskan minyak langsung di dalam panci. Tumis sereh\", \"daun salam\", \"dan lengkuas. Setelah beberapa saat masukkan bumbu halus. Tumis sampai berbau harum. Kemudian masukkan air dan gula jawa dan cabe rawit. Jika air sudah mendidih\", \"masukkan sayap ayam dan telor. Masukkan tempe belakangan. Tunggu beberapa saat sampai ayam empuk (karena pakai sayap ayam\", \"jadi tidak begitu lama). Jika ayam sudah empuk masukkan santan kara. Tunggu beberapa saat. Sesuaikan rasa. Matikan api\", \"dan taburkan bawang goreng.--Terik siap dinikmati dengan nasi hangat dan kerupun 😁--\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', '', '2025-10-23 15:26:19', '2025-10-26 07:22:11'),
(17, 3, 'Bakso Ayam Udang Keto', 'Resep Bakso Ayam Udang Keto yang lezat dan mudah dibuat.', '[\"400 gr ayam giling--250 gr udang kupas--3 telur ayam utuh kocok--30 ml minyak goreng--1/2 sdt baking powder--secukupnya garam, lada--2 sdm bawang goreng haluskan--secukupnya Bawang merah & putih--1/2 sdt minyak wijen--Karageenan secukupnya (pengenyal)--Es batu 8 keping kotak--\"]', '[\"Campur semua bahan dalam food processor\", \"kecuali daun bawang dan minyak goreng.--Tuang dalam baskom lalu taburi daun bawang dan minyak goreng\", \"uleni rata (gunakan sarung tangan). Lalu simpan 2 jam dlm kulkas.--Panaskan minyak di wajan dgn api sedang. Bulatkan adonan dengan menggunakan dua sendok. Lalu goreng sampai matang. Adonan akan mengembang saat di wajan\", \"tapi kembali kempes stelah diangkat.--\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', '', '2025-10-23 15:27:23', '2025-10-26 07:22:22'),
(18, 4, 'Ayam cabai kawin', 'Resep Ayam cabai kawin yang lezat dan mudah dibuat.', '[\"1/4 kg ayam--3 buah cabai hijau besar--7 buah cabai merah rawit--3 siung bawang putih--2 siung bawang merah--secukupnya Gula--secukupnya Garam--1/4 buah tomat merah--secukupnya Air--secukupnya Minyak goreng--\"]', '[\"Panaskan minyak di dalam wajan. Setelah minyak panas masukkan ayam yang sudah dipotong dadu. Goreng hingga matang. Lalu tiriskan.--Haluskan bawang putih\", \"bawang merah\", \"cabai hijau dan merah\", \"tomat.--Panaskan minyak didalam wajan. Setelah minyak panas\", \"masukkan bumbu yang sudah halus. Tunggu sampai wangi. Masukkan ayam yang sudah di goreng. Tambahkan air\", \"gula dan garam. Tunggu sampai bumbu meresap di ayam. Sajikan.--\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', '', '2025-10-23 15:33:32', '2025-10-26 07:22:27'),
(19, 4, 'Mujaer asam pedas manis', 'Resep Mujaer asam pedas manis yang lezat dan mudah dibuat.', '[\"1/2 kg ikan mujaer (stok gurame habis)--2 buah Wortel potong korek api--1 siung bawang bombai--7 siung bawang putih--13 cabai rawit--4 siung bawang merah--2 sendok makan Saos tomat--2 sendok makan Saos tiram--Garam--Merica--100 ml air matang--Jahe--Jeruk nipis--\"]', '[\"Bersihkan ikan sampai benar-benar bersih. Kerat-kerat dagingnya. Beri garam\", \"merica\", \"potongan jahe perasan jeruk nipis\", \"dan 2 siung bawang uleg. Diamkan 10 menit--Uleg 5 bawang putih yang tersisa. Potong bawang bombai dan dan bawang merah dan cabai rawit.--Goreng ikan mujaer hingga matang\", \"lalu sisihkan.--Tumis bawang merah dan bawang bombai hingga wangi\", \"masukkan bawang putih uleg. Tumis hingga wangi.--Masukkan wortel\", \"tambahkan air. Aduk-aduk. Tunggu hingga wortel hampir matang.--Masukkan saos tomat dan saos tiram. Beri perasan jeruk nipis. Aduk-aduk Koreksi rasa. Jika sudah pas\", \"masukkan ikan\", \"aduk sebentar saja.--Siap disajikan.--\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', '', '2025-10-23 15:34:04', '2025-10-26 07:22:31'),
(20, 4, 'Gulai kambing', 'Resep Gulai kambing yang lezat dan mudah dibuat.', '[\"500 gram daging kambing--Bumbu :--sesuai selera Santan--2 btng serai,memarkan--5 lembar Daun Salam,jeruk--sesuai selera Cabe--2 btr Cengkeh--Bumbu halus:--5 siung bawng merah--4 siung bwng putih--5 butir kemiri--2 cm kunyit--2 cm jahe--2 cm lengkuas--1 sdt ketumbar--Mrica,pala,garam,gula seckpnya--\"]', '[\"Rebus dgng kambing dgn jahe krng lbh 20 menit lalu buang airnya,cc bersih--Tumis bumbu yg sudah dihaluskn,,masukn semua bahan Dan bumbu--Rebus sampe empuk--Terakhir masukn santan,tes rasa,,,--Sajikan dimangkok,yumm ✌️--\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', '', '2025-10-23 15:34:15', '2025-10-26 07:22:37'),
(21, 4, 'Tongseng daging sapi pedas', 'Resep Tongseng daging sapi pedas yang lezat dan mudah dibuat.', '[\"300 gr daging sapi (iris tipis panjang)--Bumbu halus :--7 siung bawang merah--4 siung bawang putih--2 cm jahe--1,5 cm kunyit--3 bh kemiri--5 cabe merah keriting--Bumbu pelengkap :--2 batang sereh--2 daun salam--2 daun jeruk--5 bh cabe rawit merah utuh--Toping--1 bh tomat besar (iris sedang)--Kol secukupnya menurut selera (iris sedang)--\"]', '[\"Tumis bumbu halus dengan sedikit minyak\", \"tumis sampai matang dan mengental. Lalu masukkan daging sapi yang telah dipotong2 tadi. Lalu masukkan bumbu pelengkap. Tumis daging dengan bumbu sampai daging sapi berubah warna dan agak mengeluarkan minyak.--Masukkan air secukupnya sekitar 1\", \"5 liter biarkan mendidih sebentar lalu kecilkan api dan tutup panci. Tunggu sampai daging empuk..--Setelah daging empuk masukkan kol dan tomat\", \"masak sebentar saja agar tekstur kol agak crunchy.. angkat lalu sajikan--\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'pending', '', '2025-10-23 15:34:27', '2025-10-23 15:34:27'),
(22, 4, 'Sayur Sutace (sop tahu ceker)', 'Resep Sayur Sutace (sop tahu ceker) yang lezat dan mudah dibuat.', '[\"1/2 kg ceker ayam--4 buah wortel ukuran sedang--6 buah wortel--sesuai selera Kol--sesuai selera Daun bawang--sesuai selera Seledri--4 buah tahu kuning--Garam--Gula putih--Penyedap rasa (ma**ko)--Lada bubuk--Jeruk nipis--2 siung Bawang Putih--2 siung Bawang merah--\"]', '[\"Bersihkan ceker, lau rebut selama 3-4 menit pakai jeruk nipis biar gk terlalu bau--Tiriskan ceker--Potong2 tahu, lalu goreng set mateng, tiriskan--Potong2 sayurr, cuci hingga bersihh\", \"--Haluskan bawang merah dan bawang putih\", \"--Panaskan sedikit minyak masukan bawang yg sudah di haluskan, oseng2 hingga tercium wangi--Masukan sayurr, tampahkan air, garam, gula putih dan penyedap rasa secukupnya\", \"--Tunggu hingga sayur hampir matang, masukan ceker, dan tahu\", \"--Tutup wajan hingga kaldu meresap kedalam ceker dan tahu\", \"--Setelah matang, tuang ke mangkok, siap di santappp 😊😊--\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'pending', '', '2025-10-23 15:34:45', '2025-10-23 15:34:45'),
(23, 4, 'Telur Kornet', 'Resep Telur Kornet yang lezat dan mudah dibuat.', '[\"1/2 kaleng kornet--2-3 buah bawang prei--2 buah telur--1 sdm tepung terigu--secukupnya Cabe rawit--2 jumput Garam--1/2 sdt Merica--1/2 sdm Saus tiram--\"]', '[\"Campur kornet\", \"telur\", \"bawang prei dan cabe yg sudah di iris tipis. Tambahkan garam merica saos tiram secukupnya dan tepung terigu. Goreng 1 sdm dulu setelah matang baru cek rasa. Dirasa sudah pas. Adonan siap di goreng.😊--\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', '', '2025-10-23 15:34:58', '2025-11-15 14:48:15'),
(24, 4, 'Penyet Tempe Sambel Korek Kemangi', 'Resep Penyet Tempe Sambel Korek Kemangi yang lezat dan mudah dibuat.', '[\"2 buah tempe--1 genggam Daun kemangi--15 cabe rawit--2 siung bawang putih--Gula--Garam--\"]', '[\"Iris tempe jd beberapa potong, bumbui dg bawang putih dan garam\", \"Goreng sampai kering--Ulek cabe rawit dan 1 siung bawang putih ukuran besar tambah gula garam sesuai selera--Setelah halus tuang minyak goreng panas bekas goreng tempe td--Penyet tempe diatas sambel dan beri daun kemangi--Tempe penyet siap disantap 😋😋😋--\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'pending', '', '2025-10-23 15:35:11', '2025-10-23 15:35:11'),
(25, 4, 'Udang ala pop corn', 'Resep Udang ala pop corn yang lezat dan mudah dibuat.', '[\"1/4 kg udang basah ukuran sedang--1 bungkus kobe tepung ayam super crispy--secukupnya Air matang--Minyak untuk menggoreng--\"]', '[\"Buang kepala dan cangkang udang.--Cuci bersih udang.--Tepung bumbu dibagi jadi 2 adonan. Adonan basah dan adonan kering.--Masukkan udang ke dalam adonan tepung bumbu kering\", \"gulirkan ke dlm tepung sambil ditekan2. Lalu masukkan ke dalam Tepung bumbu adonan basah gulirkan lagi sambil di tekan2\", \"lalu masukkan lagi di adonan tepung bumbu kering Sambil ditekan2 agar tepung menempel sempurna.--Panaskan minyak goreng. Lalu goreng udang sampai kuning keemasan.--Angkat dan tiriskan.--Sajikan selagi hangat 😊--\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'rejected', 'Instruksi kurang jelas.', '2025-10-23 15:35:58', '2025-10-26 06:04:56'),
(26, 4, 'Ayam Geprek', 'Resep Ayam Geprek yang lezat dan mudah dibuat.', '[\"250 gr daging ayam (saya pakai fillet)\", \"Secukupnya gula dan garam\", \"50-100 gr tepung ayam serbaguna\", \"Secukupnya lalapan (kemangi,kol,timun)\", \"Secukupnya minyak panas\", \"❤sambal korek\", \"Secukupnya cabe rawit merah dan bwg putih\"]', '[\"Goreng ayam seperti ayam krispi\", \"Ulek semua bahan sambal kemudian campur dengan minyak panas bekas goreng ayam\", \"Geprek ayam kemudian campur dengan sambal,sajikan dengan lalapan ❤\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', '', '2025-10-23 16:23:16', '2025-10-26 06:02:33'),
(31, 2, 'semur daging sapi', 'semur daging sapi enak pisan', '[\"1kg daging\"]', '[\"rebus daging\"]', 'http://localhost:8080/assets/semur-daging-sapi-1.jpg', 'rejected', 'resep tidak jelas, bahan bahan dan langkah langkah tidak jelas', '2025-11-09 14:54:22', '2025-11-15 15:01:33'),
(34, 4, 'Gurame Asam manis', 'Resep Gurame Asam manis yang lezat dan mudah dibuat di rumah.', '[\"1/2 kg ikan gurame\", \"2 buah wortel (potong seperti batang korek api)\", \"Bumbu\", \"5 siung bawang merah\", \"4 siung bawang purih\", \"1 bh tomat\", \"Cabe besar (selera brp j)\", \"Cage kecil (selera brp j)\", \"2 sacet Saos sambel\", \"Saos tomat (q pakek Saos botolan)\", \"Bahan tambahan\", \"Tepung maezena\", \"Kunir\", \"Garam, gula, merica ladaku\"]', '[\"Uleg kunir sama garam kasih air lalu guraminya d rendam, diem in sekitar 10menitan lalu goreng gurame\", \"Untuk Saos asam manis nya, gongso semua bumbu sampek harum, masukan wortel setelah itu kasih Saos Dan garam gula merica ladaku, rasain setelah pas rasanya baru masukan tepung meizena yg sudah d cairkan dengan air setelah mengental angkat\", \"Tata gurame d atas piring siram saosnya Dan siap di santaaap...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(35, 3, 'Asam padeh ikan tuna', 'Nikmati kelezatan Asam padeh ikan tuna dengan resep sederhana ini.', '[\"1/2 kg ikan tuna\", \"6 siung bawang merah\", \"4 siung bawang putih\", \"2 ruas kemiri\", \"2 batang serai\", \"2 ruas kunyit\", \"2 ruas laos\", \"4 lembar daun jeruk\", \"1 lembar daun kunyit\", \"2 buah asam Kandis\", \"4 buah belimbing hulu\", \"6 buah cabai merah (bisa disesuaikan)\", \"10 buah cabai rawit (bisa disesuaikan)\", \"3 gelas air\", \"2 sendok garam\", \"1/2 sendok gula\"]', '[\"Haluskan bumbu (cabai merah, kemiri, bawang, kunyit, Laos)\", \"Tumis bumbu sampai berubah warna\", \"Tambahkan air\", \"Masukkan serai yg sudah di geprek, daun kunyit, daun jeruk, asam Kandis, belimbing hulu, dan cabai rawit utuh (tdk dihaluskan dan tdk dipotong)\", \"Tunggu sampai mendidih\", \"Setelah mendidih, masukkan ikan tuna (sudah dicuci bersih dan diberi air perasan jeruk)\", \"Kemudian beri garam dan gula secukupnya\", \"Tunggu sampai air sedikit berkurang dan mengental\", \"Asam padeh ikan tuna siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(36, 2, 'Avocado Tuna Salad', 'Avocado Tuna Salad - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 kaleng Tuna Chunks\", \"2 butir telur rebus\", \"3 buah kentang rebus\", \"2 buah avocado\", \"2 buah bawang merah\", \"12 biji zaitun\", \"1 buah timun\", \"Sebongkol daun salada/lettuce\", \"secukupnya Garam & merica\"]', '[\"Campur semuanya dalam baskom, kecuali biji zaitun, telur rebus. Lalu tambahkan garam & merica\", \"Tuang dalam piring saji, atur irisan telur & biji zaitun. Siap disajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(37, 3, 'Lele Asam Manis', 'Resep Lele Asam Manis ala rumahan yang dijamin menggugah selera.', '[\"1/2 kg Lele Segar\", \"180 ml air\", \"3 sdm kecap manis\", \"1 sdm margarine/minyak\", \"1/2 sdt saus tiram (optional)\", \"Bumbu halus :\", \"6 siung bawang merah\", \"5 siung bawang putih\", \"4 cabe merah (bisa lebih sesuai selera)\", \"2 buah kemiri\", \"1 sdt garam (sesuai selera)\", \"1/2 sdt penyedap rasa (sesuai selera)\", \"1/2 sdt gula pasir (sesuai selera)\"]', '[\"Cuci bersihbikan, lalu goreng ikan lele agak matang tapi jangan sampai renyah. Tiriskan\", \"Sambil menunggu, haluskan semua bumbu di atas.\", \"Panaskan wajan dengan margarin.\", \"Masukkan bumbu halus ke dalam wajan sampai harum. Tambahkan kecap, saus tiram dan air\", \"Setelah berbau harum, barulah ikan lele dimasukkan.\", \"Tunggu sampai bumbu meresap serta tes rasa. Setelah air tnggal sedikit, angkat dan sajikan.. Semoga membantu..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(38, 2, 'Pempek kulit ikan tenggiri', 'Sajian Pempek kulit ikan tenggiri yang praktis dan lezat untuk dinikmati bersama.', '[\"500 gr kulit ikan tenggiri halu\", \"200 cc air matang\", \"1 sdt garam\", \"1 sdt Penyedap/ kaldu jamur\", \"1/2 sdt merica\", \"1/2 sdt gula\", \"60 ml santan kental\", \"5 siung bawang putih\", \"5 siung bawang merah\", \"350 gr sagu tani\", \"2 sdm terigu\", \"100 gr sagu untuk balur\"]', '[\"Aduk ikan tambahkan air sedikit demi sedikit bersamaan dgn garam\", \"Masukkan terigu bersama santan\", \"Masukkan sagu\", \"Balurin tangan dgn sagu bentuk adonan dgn sendok makan\", \"Letakkan di piring yg ditabur sagu\", \"Goreng minyak panas sampai mengembang\", \"Dinginkan\", \"Potong2 lalu goreng\", \"Siap menggoyang lidah sajikan dgn cuko\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(39, 2, 'Tumis Tongkol Petai', 'Cara membuat Tumis Tongkol Petai yang enak dan praktis untuk keluarga.', '[\"2 bungkus tongkol\", \"2 cabe gendot\", \"2 papan petai\", \"2 cabe rawit\", \"2 bh cabe merah\", \"3 bh b. Merah\", \"3 bh b. Putih\", \"2 lembar daun salam\", \"Secukupnya garam\", \"Secukupnya gula putih\"]', '[\"Cuci bersih ikan tongkol, goreng sebentar\", \"Iris b. Merah, b. Putih, cabe merah, cabe rawit, cabe gendot. Tumis\", \"Masukan petai, tambahkan sedikit air. Masukan garam, gula pasir. Cek rasa. Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(40, 4, 'Ikan Patin pedas manis', 'Sajian Ikan Patin pedas manis yang praktis dan lezat untuk dinikmati bersama.', '[\"500 gr ikan patin\", \"5 siung bawang merah iris tipis\", \"4 siung bawang putih iris tipis\", \"1/2 bawang bombay ukuran kecil iris tipis\", \"Cabai merah keriting (sesuai selera) iris tipis\", \"Cabai rawit setan (sesuai selera) biarkan utuh\", \"1 ruas lengkuas digeprek\", \"2 lembar daun jeruk\", \"2 sendok makan kecap\", \"3 batang bawang daun iris tipis\"]', '[\"Ikan patin yang sudah dicuci bersih, dilumuri garam kemudian digoreng setengah kering\", \"Tumis irisan bawang merah, putih, bombay dan cabai sampai dengan harum\", \"Masukkan ikan yang sudah digoreng sebelumnya, kemudian tambahkan sedikit air\", \"Masukkan kecap, lengkuas, daun jeruk, garam dan gula. Koreksi rasa\", \"Biarkan sampai dengan meresap ke dalam daging ikan, setelah benar2 meresap terakhir masukkan irisan bawang daun dan cabai rawit setan, kemudian angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(41, 2, 'Gurame tahu tauco', 'Gurame tahu tauco dengan cita rasa segar khas laut.', '[\"1 ekor gurame\", \"1 buah tahu kotak\", \"1 buah jeruk nipis\", \"1 buah bawang bombay\", \"3 siung bawang putih\", \"1 jari jahe\", \"3 buah cabe hijau besar buang biji\", \"2 buah cabe merah besar\", \"5 sdm tauco\", \"Kecap asin\", \"Kecap manis\", \"Saos tiram\", \"Minyak wijen\", \"1 sdt Angciu\"]', '[\"Balurin gurame dgn jeruk nipis goreng\", \"Goreng tahu kotak 2\", \"Tumis bawang 2 ngan masukkan tauco\", \"Masukkan kecap dll\", \"Tambahkan sedikit air\", \"Siap disajikan test rasa kurang asin tambah garam ya kl tauconya asin gak usah pake garam lg\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(42, 3, 'Ikan Patin', 'Resep praktis Ikan Patin yang bisa dicoba di rumah.', '[\"5 potong Ikan patin\", \"1 buah Jeruk nipis\", \"1 buah Tomat uk. sedang\", \"3 buah Cabai hijau keriting (boleh lebih)\", \"2 buah Cabai rawit/ cengek (boleh lebih)\", \"1 batang serai (geprek)\", \"1/2 ruas Lengkuas (geprek)\", \"Bumbu-bumbu dihaluskan\", \"8 siung Bawang merah\", \"2 siung Bawang putih\", \"5 buah Kemiri\", \"1 sdt Kunyit bubuk\", \"1 buah Cabai merah besar\", \"Nb: Jika hoby pedas, tambahkan cabai sesuai selera masing-masing 😊\"]', '[\"Cuci bersih dan lumuri ikan dengan garam, perasan jeruk nipis selama 15 menit.\", \"Potong dan iris-iris tomat, cabai merah kecil, cabai rawit hijau dan lengkuas (geprek).\", \"Haluskan bumbu - bumbu seperti bawang merah, bawang putih, kemiri, kunyit, cabai merah besar.\", \"Tumis bumbu-bumbu halus serta cabai, serai, lengkuas dan tomat.\", \"Kemudian masukkan ikan patin. Aduk-aduk rata dan masukkan air 250 ml. Aduk2 tercampur smw dan diamkan hingga air menyusut (bumbu-bumbu meresap). Masukkan garam, test rasa.\", \"Angkat dan Sajikan...😄\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(43, 3, '2. Gulai Ikan Kakap Merah khas Padang', 'Sajian 2. Gulai Ikan Kakap Merah khas Padang yang praktis dan lezat untuk dinikmati bersama.', '[\"2 ekor Ikan Kakap merah ukuran agak besar, potong 2\", \"1/2 papan Tempe\", \"Bumbu Halus :\", \"10 siung Bawang merah\", \"5 siung Bawang putih\", \"4 cm Jahe\", \"4 cm Kunyit\", \"Bahan tambahan :\", \"2 sdm Cabe giling halus\", \"2 lbr Daun kunyit\", \"8 lbr Daun jeruk\", \"2 btg Sereh\", \"4 lbr Daun salam\", \"4 bh Asam kandis\", \"Daun ruku ruku segenggam (bisa diganti daun kemangi)\", \"15 butir Rawit merah\", \"200 ml Santan kara\", \"500 ml Air\"]', '[\"Tumis bumbu halus, cabe giling halus, daun kunyit, daun jeruk, daun salam, sereh dan asam kandis.\", \"Masukkan santan cair (santan kara sebagian besar cairkan dengan air 500 ml sisanya di masukkan terakhir), daun ruku ruku dan cabe rawit.\", \"Masukkan ikan, tempe, tunggu hingga mendidih kurang lebih 15 menit dengan api kecil.\", \"Masukkan sisa santan kara yang masih kental, aduk2 sampai mendidih kembali.\", \"Matikan api dan siap di sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(44, 4, 'Gurame crispy asam manis ala amih fatih', 'Gurame crispy asam manis ala amih fatih dengan cita rasa segar khas laut.', '[\"Bumbu ikan :\", \"1 ekor ikan gurame fillet\", \"1 buah jeruk nipis\", \"1 sdt lada bubuk\", \"1/2 sdt garam\", \"1 siung bawang putih\", \"1 pack tepung serbaguna pedas\", \"1 buah telur kocok lepas\", \"Saus :\", \"1 buah bawang bombay iris\", \"1 buah bawang putih iris\", \"1 buah wortel potong sesuai selera\", \"1 sdm saus tiram\", \"5 sdm saus tomat\", \"6 sdm saus sambal\", \"secukupnya Gula\", \"secukupnya Garam\", \"secukupnya Lada\", \"secukupnya Air\"]', '[\"Cuci bersih ikan gurame filletnya\", \"Campurkan sampai merata ikan dengan perasan jeruk nipis, bawang putih, garam, lada\", \"Diamkan 15-20 menit\", \"Siapkan mangkok berisi telur yg sudah di kocok\", \"Siapkan tepung serbaguna\", \"Bila ikan sudah meresap, ambil ikan tersebut celupkan ke dalam telur lalu baluri dengan tepung serbaguna.\", \"Panaskan minyak untuk menggoreng. Masukan ikan yg sudah dilumuri tepung, goreng dengan api sedang sampai warna berubah kecoklatan\", \"Angkat dan sisihkan dulu\", \"Selanjutnya panaskan minyak untuk menumis.\", \"Masukkan bawang putih, bawang bombay. Masak hingga harum\", \"Lalu masukkan saus tiram, saus tomat, saus sambal, air secukupnya. Aduk hingga rata\", \"Masukkan gula, garam, lada, tes rasanya apakah sudah sesuai.\", \"Masukkan wortel hingga matang.\", \"Aduk terus supaya tidak gosong\", \"Bila sudah matang angkat dan taruh di mangkok.\", \"Sajikan ikan dengan dicocol saus asam manisnya atau disiram di atas ikannya\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(45, 4, 'Balado Tongkol & Tahu', 'Cara membuat Balado Tongkol & Tahu yang enak dan praktis untuk keluarga.', '[\"1 buah ikan tongkol sedang (iris menjadi 10 Bagian)\", \"5 buah tahu ukuran lecil\", \"2 lembar daun jeruk\", \"secukupnya Gula & garam\", \"Bumbu halus :\", \"5 buah bawang merah\", \"2 buah bawang putih\", \"10 Cabe Merah\", \"5 cabe rawit\", \"1 buah tomat\", \"1 buah Gula merah ukuran sedang\"]', '[\"Bersihkan tongkol yang sudah di iris. Goreng sampai matang.\", \"Potong dadu tahu (ukuran kecil), goreng hingga kering.\", \"Tumis bumbu yang sudah dihaluskan hingga wangi, masukkan daun jeruk, gula dan garam. Masukan air secukupnya.\", \"Masukkan tongkol & tahu yang sudah digoreng. diamkan hingga mendidih & bumbu meresap.\", \"Sajikan dan siap dihidangkan. 😉\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(46, 2, 'Balado Ikan Sarden', 'Cara membuat Balado Ikan Sarden yang enak dan praktis untuk keluarga.', '[\"5 ekor ikan sarden\", \"Jeruk nipis\", \"secukupnya Garam\", \"Bumbu balado\", \"15 buah Cabe keriting\", \"5 siung bawang merah\", \"1 buah tomat\", \"secukupnya Garam + gula + penyedap rasa\"]', '[\"Bersihkan ikan lalu lumuri dengan jeruk nipis dan garam dan biarkan 5 menit sampai garam meresap\", \"Goreng ikan sampai garing.lalu tiriskan\", \"Untuk membuat bumbu balado. Haluskan semua bumbu lalu tumis sampai masak dan keluar minyak.\", \"Masukan garam gula dan penyedap rasa lalu koreksi rasa\", \"Masukan ikan goreng tadi ke dalam bumbu balado, aduk sebentar lalu tiriskan.\", \"Dan jadi ikan sarden balado\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(47, 4, 'Ikan Nila (saos pedas asam manis)', 'Sajian ikan nikmat: Ikan Nila (saos pedas asam manis) yang mudah dibuat.', '[\"1 ekor ikan nila ukuran jumbo\", \"1 ons Selada\", \"3 batang buncis (di potong panjang)\", \"1 buah kentang (di bagi 4)\", \"1/2 wortel (di potong korek api)\", \"Bahan saos :\", \"1 bawang bombay ukuran kecil\", \"3 siung bawang putih\", \"7 sdm saos sambal\", \"5 sdm saos tomat\", \"3 sdm saos tiram\", \"1 sdt garam\", \"1 sdt lada / merica bubuk\", \"Minyak goreng\", \"4 gelas air\"]', '[\"Panas kan minyak goreng\", \"Masukkan ikan nila sampai terendam seluruhnya\", \"Goreng sampai kecoklatan dan matang\", \"Angkat dan tiriskan\", \"Rebus kentang wortel dan buncis dengan 3 gelas air dan 1/2 sdt garam\", \"Angkat dan tiriskan rebusannya\", \"Cara membuat saos :\", \"Geprek dan cincang bawang putih, iris bawang bombay\", \"Tumis bawang putih dan bawang bombay dengan sedikit minyak sampai harum\", \"Masukkan saos tomat, saos sambal, dan saos tiram\", \"Masukkan segelas air\", \"Masukkan 1/2 sdt garam dan lada/merica bubuk\", \"Masak hingga mendidih\", \"Tata ikan dalam piring sesuai selera, letakkan ikan nila yg sudah di goreng dan siram dengan saos pedas asam manis\", \"Selesai\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(48, 3, 'Sarden kangkung 😘', 'Sajian Sarden kangkung 😘 yang praktis dan lezat untuk dinikmati bersama.', '[\"1 kaleng ikan sarden(botan)\", \"1 gengam kangkunng (pucuknya saja, cuci bersih)\", \"4 siung bawangputih(iris)\", \"5 siung bwng mrah(iris)\", \"sesuai selera Cabe rawit\", \"1 btng daun bwang(iris)\", \"1 btng sereh(gprek)\", \"2 ruas jari jahe(geprek)\", \"2 lbar daun jeruk\", \"secukupnya Garam\", \"secukupnya Royco\", \"secukupnya Gula\", \"secukupnya Kecap\", \"secukupnya Air\", \"Minyak untuk menumis bumbu\", \"1 kaleng ikan sarden(botan)\", \"1 gengam kangkunng (pucuknya saja, cuci bersih)\", \"4 siung bawangputih(iris)\", \"5 siung bwng mrah(iris)\", \"sesuai selera Cabe rawit\", \"1 btng daun bwang(iris)\", \"1 btng sereh(gprek)\", \"2 ruas jari jahe(geprek)\", \"2 lbar daun jeruk\", \"secukupnya Garam\", \"secukupnya Royco\", \"secukupnya Gula\", \"secukupnya Kecap\", \"secukupnya Air\", \"Minyak untuk menumis bumbu\"]', '[\"Tumis semua bumbu sampai harum, masukan ikan sarden, tambahkan air, lalu royco,gula,garam,dan kecap, setelah men ddih, masukan kangkunh, masak sampai kangkung matang, tes rasa lalau angkat dan sajikan\", \"Nikmat d makan dengan nasi hangat\", \"Nikmat d makan dengan nasi hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(49, 2, 'Bandeng presto', 'Sajian Bandeng presto yang praktis dan lezat untuk dinikmati bersama.', '[\"3 kg bandeng,bersihkan\", \"Bumbu halus :\", \"3 ruas jari kunyit\", \"5 buah bawang merah\", \"7 buah bawang putih\", \"1 ruas jahe\", \"1/2 sdt ketumbar\", \"Secukupnya garam\", \"Bumbu cemplung\", \"2 ruas lengkuas\", \"2 lembar daun salam\", \"1 batang serai\", \"2 lembar daun jeruk\", \"Secukupnya air\", \"Secukupnya kocokan telur\"]', '[\"Susun bandeng dalam panci presto.tambahkan bumbu halus dan bumbu cemplung.tambah kan air secukupnya sampai smua ikan terendam.\", \"Masak selama 1,5 jam.dinginkan.potong2 dan goreng dengan balutan telur\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(50, 4, '1. Pesmol Ikan Kerapu', 'Cara membuat 1. Pesmol Ikan Kerapu yang enak dan praktis untuk keluarga.', '[\"3 ekor ikan kerapu potong 2\", \"Bumbu halus :\", \"8 siung Bawang merah\", \"4 siung Bawang putih\", \"3 cm Jahe\", \"3 cm Kunyit\", \"6 butir Kemiri\", \"Bumbu pelengkap :\", \"6 lbr Daun jeruk\", \"4 lbr Daun salam\", \"1 btg Sereh\", \"Lengkuas 3 cm (digeprek)\", \"Cabe rawit 15 bh (sesuai selera)\", \"1 bh Tomat kecil\", \"1 bh Wortel kecil\", \"2 btg Daun bawang\", \"Jeruk nipis 1 butir (ambil airnya)\", \"Air 100 ml (dapat ditambah jika ingin agak berkuah)\", \"Garam\", \"Gula\"]', '[\"Bersihkan ikan kerapu, beri garam, goreng kering\", \"Tumis bumbu halus, daun jeruk, daun salam, sereh dan lengkuas sampai harum.\", \"Masukkan wortel dan cabe rawit masak sampai wortel dan cabe agak lunak.\", \"Masukkan air, air jeruk nipis, garam dan gula. Masak sampai mendidih.\", \"Masukkan ikan yang sudah di goreng.\", \"Masak sampai air agak menyusut, masukkan tomat dan daun bawang. Masak sebentar.\", \"Angkat dan sajikan 😉\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(51, 2, 'Mujair bumbu pepes', 'Resep Mujair bumbu pepes yang lezat dan mudah dibuat di rumah.', '[\"5 bh mujair uk sedang\", \"5 btr bawang merah\", \"2 siung bawang putih\", \"1 cm jahe\", \"2 btr kemiri\", \"1 sdt kunyit halus\", \"7 bh cabe rawit\", \"1 lbr daun kunyit sobek sobek\", \"1 bh tomat potong kecil kecil\"]', '[\"Haluskan semua bumbu kecuali kunyit dan daun kunyit,\", \"Tumis semua bumbu dengan 4 sdm minyak beri air sedikit aduk,biarkan bumbu sampai matang,\", \"Bila bumbu sudah matang, masukkan ikan yg sudah dibersihkan,aduk sampai ikan terbalut bumbu, diamkan sesaat, beri tomat dan air 1 gls masak ikan sampai matang dan kuah mengering dengan membalik 1x, tutup,koreksi rasa, sajikan mujair bumbu pepes hangat ataupun dingin\", \"Met mencoba yaa\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(52, 3, 'Ikan dencis bumbu sarden pedas nyemek-nyemek', 'Resep praktis Ikan dencis bumbu sarden pedas nyemek-nyemek yang bisa dicoba di rumah.', '[\"9 ekor ikan dencis sebesar setengah telapak tangan yg digoreng\", \"9 butir telur puyuh yg sudah di rebus\", \"1 ons terong ungu (ganti tahu/kentang) di goreng layu\", \"Bumbu halus :\", \"1 ons cabe merah\", \"15 butir cabe rawit\", \"1 butir kemiri\", \"2 ons tomat merah\", \"7 siung bawang putih\", \"10 siung bawang merah\", \"1/2 sdt merica putih\", \"Bumbu yg di iris-iris :\", \"1 ons tomat merah\", \"6 butir cabe rawit belah dua\", \"5 buah cabe merah besar\", \"2 ons bawang bombay\", \"1 lembar daun jeruk koyak jadi dua\", \"Minyak untuk menumis\", \"200 ml Air\", \"secukupnya Garam\", \"Gula diabetasol setengah bungkus (opsi,, bisa pake gula biasa)\", \"1/2 sdm saus cabe\", \"Penyedap (opsi)\"]', '[\"Haluskan semua bumbu halus, sehalus-halusnya. Tumis hingga benar-benar tanak.\", \"Masukkan ikan dan terong yg sudah di goreng. Telur belakangan yaaa!\", \"Masukkan bumbu yg diiris, gula, garam, saus, penyedap.\", \"Masukkan air serta daun jeruk.\", \"Ketika hampir tanak masukkan telur.\", \"Setelah tanak, angkat dan sajikan 😊☺️\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(53, 2, 'Sambal ikan Lele', 'Sambal ikan Lele - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1/2 kg ikan lele (cuci bersih potong jd beberapa bagian)\", \"10 buah cabe merah keriting\", \"5 buah cabe rawit\", \"2 buah tomat ukuran sedang\", \"4 siung bw.merah\", \"3 siung bw.putih\", \"2 biji kemiri\", \"1 cm jahe\", \"1 cm Terasi bakar\", \"1 bauh Jeruk sambal kecil\", \"secukupnya Gula merah\", \"Garam\", \"Sedikit pucuk daun kemangi\"]', '[\"Cuci bersih ikan lele (tips biar lele gak licin waktu mencuci tambahkan sedikit air panas dan air utk mencuci agar lendir berkurang) potong mjd beberapa bagian.\", \"Balut ikan dengan bumbu racik ikan goreng beri sedikit perasan jeruk nipis. (Klo gaada bisa pake lada&garam)\", \"Rebus cabai dan tomat hingga layu(agar mudah di haluskan). Sembari menunggu haluskan bw.merah,bw putih,kemiri,jahe,trasi bakar dan gula merah. Lalu haluskan bersama cabai dan tomat yg sudah di rebus. Beri irisan jeruk sambal.\", \"Goreng lele sampai kering. Lalu tiriskan\", \"Tumis sambal/bumbu yg sudah di haluskan sampai harum dan matang (lebih enak pakai minyak bekas menggoreng ikan lele) beri sedikit garam, Masukan kemangi dan lele yg sudah di goreng.\", \"Tes rasa dan sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(54, 3, 'Ikan cucut sambal pedas pake pete', 'Resep Ikan cucut sambal pedas pake pete ala rumahan yang dijamin menggugah selera.', '[\"3 ikan cucut ukuran sedang\", \"5 butir pete\", \"2 butir bawang merah\", \"1 butir bawang putih\", \"1 butir tomat\", \"1 lembar daun salam\", \"3 butir cabe keriting\", \"3 butir cabet rawit (sesuai selera)\", \"Garam, penyedap & gula putih secukup nya\"]', '[\"Rendam dahulu ikan cucut kurang lebih sampe 15 menit agar tidak terlalu asin bila d masak\", \"Goreng ikan cucut smpe setengah mateng\", \"Ulek cabe keriting,cabe rawit,bawang merah,bawang putih, dan tomat sampe halus\", \"Tumis bumbu tersebut hingga harum\", \"Lalu campurkan garam penyedap gula salam dan pete,bisa d tambah kan air secukup nya\", \"Masukan ikan cucut sampe bumbu nya meresap\", \"Lalu hidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(55, 2, 'Nila Goreng Sambal Matah', 'Sajian ikan nikmat: Nila Goreng Sambal Matah yang mudah dibuat.', '[\"Fillet Nila\", \"Jeruk Lemon\", \"Bumbu Kuning Halus\", \"Ketumbar\", \"Merica\", \"Garam\", \"Daun Jeruk\", \"Cabe Rawit Merah\", \"Cabe Rawit Hijau\", \"Bawang Merah\", \"Minyak\", \"Bahan Membuat Bumbu Kuning Halus:\", \"3 Siuang Bawang Merah\", \"2 Siung Bawang Putih\", \"1 Kunyit\"]', '[\"Siapkan nila fillet (bisa diganti dengan dori/gurame), lumuri dengan perasan jeruk lemon minimal 15 menit.\", \"Lumuri dengan bumbu kuning halus, ketumbar bubuk, merica dan garam. Bila tidak ada bumbu kuning siap pakai, bisa membuat dari bawang merah 3, bawang putih 2, kunyit 1 lalu diblender. Diamkan selama 15-30 menit.\", \"Goreng ikan hingga matang lalu sisihkan.\", \"Iris daun jeruk, serai, cabe rawit merah, cabe rawit hijau, bawang merah. Lalu siram menggunakan minyak panas, aduk dgn sedikit ditekan. Lalu tuang ke atas ikan. Siap disajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(56, 4, 'Salmon (tetelan) Teriyaki', 'Nikmati kelezatan Salmon (tetelan) Teriyaki dengan resep sederhana ini.', '[\"250 gr tetelan salmon mentah\", \"1/2 bagian jeruk lemon (peras airnya, sisihkan dgn buahnya)\", \"2 ruas jahe (kupas, cuci bersih & digeprek)\", \"500 gr jamur kuping (cuci bersih & iris tipis)\", \"7 batang baby corn (cuci bersih & iris tipis)\", \"1/4 bagian paprika hijau (cuci bersih & iris tipis)\", \"6 cabe rawit (cuci bersih & iris kecil-kecil)\", \"5 sdm kecap manis\", \"1 sdm saus tiram Saori\", \"3 sdm saus teriyaki Saori\", \"1 siung bawang bombay kecil (cuci bersih & iris tipis)\", \"4 butir bawang putih (cuci bersih, digeprek & iris tipis)\", \"6 butir bawang merah (cuci bersih & iris tipis)\", \"2 sdt garam\", \"2 sdt lada putih\", \"1/4 sdt lada hitam\", \"750 ml air\", \"1 ruas ibu jari lengkuas (kupas, cuci bersih & digeprek)\", \"3 sdm minyak goreng\"]', '[\"Panaskan 500 ml air. Masukkan air perasan jeruk lemon, buah lemon pasca diperas & 1/2 ruas jahe. Biarkan sampai mendidih.\", \"Masukkan tetelan salmon, rebus hingga matang & bau amis menghilang (sekitar 20-25 menit dengan api sedang). Tambahkan 1 sdt garam & 1 sdt lada putih.\", \"Matikan kompor, tiriskan salmon yang sudah matang.\", \"Panaskan minyak goreng dengan api sedang. Tumislah bumbu (bawang putih, bawang merah, bawang bombay) hingga berbau harum. Masukkan paprika hijau & cabe rawit, tumis hingga baunya menyatu.\", \"Tambahkan kecap manis,saus teriyaki & saus tiram. Masukkan tetelan salmon matang, tumis bersama bumbu hingga berubah warna kecoklatan (tanda sudah menyatu dengan bumbu).\", \"Masukkan irisan jamur kuping & baby corn, tumis hingga jamur layu & baby corn menyatu dengan bumbu. Tambahkan 250 ml air, tunggu sampai jamur & baby corn matang.\", \"Kecilkan api ketika air sudah makin surut, masukkan 1,5 ruas jahe & 1 ruas lengkuas. Tambahkan 1 sdt garam, 1 sdt lada putih & 1/4 sdt lada hitam.\", \"Matikan api & pindahkaan masakan dari teflon ke piring saji. Tetelan salmon teriyaki siap disajikan bersama nasi merah hangat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(57, 3, 'Dadar telor ikan tongkol', 'Resep praktis Dadar telor ikan tongkol yang bisa dicoba di rumah.', '[\"1 ikan tongkol\", \"2 butir telor\", \"1 ikat daun bawang\", \"1/2 sdt garam\"]', '[\"Goreng ikan tongkol setengah matang lalu suwir²\", \"Potong² bawang daun lalu campur semua kocok jadi satu dalam wadah\", \"Goreng sesendok² klo dah kuning keemasan angkat lalu tiriskan, soap disajikan sebagai lauk sayur asem cucok banget\", \"Bisa jg langsung digoreng jadi satu pas nanti dipotong² sesuai selera, selamat mencoba moms 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(58, 3, '31. Lele Goreng Krenyes No Amis', 'Resep 31. Lele Goreng Krenyes No Amis ala rumahan yang dijamin menggugah selera.', '[\"1/2 kg lele sayat sisinya\", \"1 buah jeruk nipis\", \"Minyak goreng secukupnya untuk menggoreng lele\", \"Bumbu halus\", \"3 siung bawang putih\", \"2 siung bawang merah\", \"1 cm ruas kunyit\", \"1 sdt ketumbar bubuk\", \"secukupnya Garam\"]', '[\"Bersihkan lele dan buang isinya, lalu Haluskan bumbu yg ada lalu tambahkan sedikit air\", \"Masukkan lele kedalam bumbu lalu tambahkan perasan air jeruk nipis k seluruh bagian lele\", \"Diamkan lele -+30 menit\", \"Panaskan minyak di penggirengan lalu goreng lele hingga bener2 kering\", \"Angkat lele lalu tiriskab\", \"Siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(59, 2, 'Pindang patin', 'Buat Pindang patin yang nikmat dengan langkah-langkah mudah ini.', '[\"1 kg ikan patin\", \"7 buah cabe rawit merah\", \"7 buah cabe merah keriting\", \"5 siung baput\", \"5 siung bamer\", \"1 sendok makan lada\", \"4 buah kemiri\", \"5 buah cengkeh\", \"2 buah trasi (sy pke abc)\", \"3 lembar daun salam\", \"4 lembar daun jeruk\", \"3 batang serai\", \"3 buah tomat\", \"1 sendok teh asam jawa\", \"2 ruas jahe (sebesar ibu jari dewasa)\", \"2 ruas lengkuas\", \"1 ikat kemangi\", \"2 batang daun bawang\", \"2 sendok kecap manis\", \"1 buah gula merah\", \"secukupnya Garam\", \"secukupnya Penyedap rasa\", \"1 sendok teh gula putih\"]', '[\"Bersihkan ikan patin,potong\\\" sesuai selera.sisihkan\", \"Haluskan baput,lada,kemiri,cengkeh,trasi.\", \"Potong\\\" cabe rawit,cabe merah,tomat,daun bawang,jahe,bamer.serai dan lengkuas digeprek\", \"Tumis bamer sampai harum.kemudian masukan bumbu yg sudah dihaluskan.tumis sampai harum,masukan serai,lengkuas,cabai,daun salam,daun jeruk,kecap,asam jawa,aduk rata\", \"Masukan ikan patin,garam,penyedap rasa,gula merah n putih,aduk rata.\", \"Tambahkan air sesuai selera.masak kira\\\" 15 menit\", \"Setelah 15 menit dan dirasa sdh matang masukan daun bawang,tomat & kemangi.aduk rata\", \"Koreksi rasa,angkat & sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(60, 3, 'Pepes Aceh ikan tongkol', 'Pepes Aceh ikan tongkol - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1/2 kg anak ikan tongkol\", \"2 btg serai, rajang halus\", \"Segenggam cabe rawit utuh utk taburan\", \"1 tangkai daun temurui (ambil daunnya)\", \"Segenggam belimbing wuluh, potong serong\", \"5 lbr daun jeruk, rajang\", \"2 sendok mkn bawang goreng\", \"Bumbu ygdihaluskan🍀\", \"20 bh cabe Rawit (pedas sesuai selera)\", \"Seruas kunyit\", \"2 genggam asam sunti\", \"7 siung bawang merah\", \"4 siung bawang putih\", \"1/2 sendok jinten\", \"Penyedap (optional)\"]', '[\"Cuci bersih ikan,kucuri dgn jeruk nipis dan garam\", \"Haluskan bumbu, lalu tumis bumbu hingga harum beri sedikit garam, gula dan penyedap\", \"Campur bumbu yg sdh ditumis td ke dlm ikan, aduk rata\", \"Tambahkan, rajangan sereh, belimbingwuluh, cabe rawit,daun temurui dan bawang goreng, aduk hingga bumbu merata\", \"Bungkus dgn daun pisang ikan yg sdh dibumbui td, lalu kukus hingga matang.\", \"Terakhir panggang pepes di teflon sebentar sambil dibolak balik, Angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(61, 4, 'Tuna Tepung Siram Saus', 'Resep Tuna Tepung Siram Saus ala rumahan yang dijamin menggugah selera.', '[\"1/2 kg ikan tuna\", \"1 bawang bombai\", \"1 bks Tepung sebaguna\", \"2 lbr daun salam\", \"Saus tomat\", \"Saus sambal\", \"5 bawang merah\", \"3 bawang putih\", \"3 cabai keriting\", \"sesuai selera Lada bubuk\", \"Penyedap makanan\", \"Garam\", \"Gula\", \"200 ml air\"]', '[\"Potong ikan seperti dadu, baluri tepung yang sudah di beri air sedikit\", \"Goreng tuna Tepung hingga matang\", \"Iris duo bawang dan cabai serta iris kasar bawang bombai\", \"Tumis bumbu iris sampai harum, masukkan saus tomat, saus cabe, lada bubuk, iris an bawang bombai garam, gula, penyedap, dan air. Biarkan sampai mendidik lalu masukkan Tina tepung yang sudah di goreng. Diamkan sebentar dan siap di hidangan :)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(62, 2, 'Ikan Dencis Bumbu Kuning Cabe Rawit', 'Cara membuat Ikan Dencis Bumbu Kuning Cabe Rawit yang enak dan praktis untuk keluarga.', '[\"500 gr ikan dencis\", \"secukupnya Daun prei\", \"secukupnya Garam\", \"🌸Bumbu halus\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"secukupnya Kemiri (kira2 3 buah)\", \"kunyit seujung ruas jari (sedikit saja)\", \"jahe sedikit saja\", \"Iris 🌸 Bumbu\", \"secukupnya Cabe rawit\", \"tomat setengah buah, potong dadu\"]', '[\"Ikan di bersihkan, di siangi. Lalu cuci bersih\", \"Panaskan minyak (sampai benar-benar panas). Goreng ikan dengan deep fry agar tidak lengket di penggorengan.\", \"Blender bumbu halus (bawang putih, bawang merah, kemiri, jahe)\", \"Cabe rawit di iris belah dua dan tomat di potong dadu\", \"Tumis bumbu halus sampai matang dan harum.\", \"Setelah matang dan harum, masukkan cabe rawit dan tomat.\", \"Jangan tambahkan garam dan gula.\", \"Tambahkan sedikit air, cek rasa apakah garam dan gula sudah pas.\", \"Masukkan ikan dencis yang telah goreng. Ratakan dengan bumbu. Tambahkan irisan daun prei.\", \"Ikan dencis bumbu kuning cabe hijau siap di hidangkan..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(63, 4, 'Bandeng Keropok', 'Resep Bandeng Keropok yang lezat dan mudah dibuat di rumah.', '[\"2 bandeng ukuran sedang\", \"Bumbu halus:\", \"1 sdt ketumbar\", \"1 bw putih\", \"1/2 sdt garam\", \"Secukupnya air(utk mencairkan bumbu halus)\", \"Minyak (utk menggoreng)\", \"Sambal:\", \"6 cabe rawit(selera pedasnya)\", \"1 bw putih\", \"1/2 sdt terasi\", \"1 iris jeruk nipis\", \"2 sdm kecap manis\", \"3 cabe rawit iris halus\"]', '[\"Bersihkan bandeng, dikerat agak banyak kemudian dibalur dengan bumbu halus yg sdh dicampur air, diamkan 10 mnt spy bumbu meresap.\", \"Setelah bumbu meresap,goreng jng terlalu kering. Sisihkan\", \"Utk sambal, haluskan cabe, bw putih&terasi\", \"Campur sambal dengan kecap manis, tambah perasan jeruk nipis&cabe iris.aduk rata.\", \"Penyajian: tambahkan sambal diatas bandeng goreng ketika akan dihidangkan. Selamat mencoba.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(64, 2, 'Nila goreng sambal matah', 'Resep Nila goreng sambal matah ala rumahan yang dijamin menggugah selera.', '[\"3 ekor ikan nila, ukuran sedang\", \"2 siung bawang putih\", \"1 ruas jari kunyit\", \"1 sdt ketumbar halus\", \"secukupnya Garam\", \"Minyak untuk menggoreng\", \"Sambal matah:\", \"10 siung bawang merah\", \"30 biji cabe rawit apa aja\", \"1 buah jeruk nipis\", \"secukupnya Royco\", \"secukupnya Minyak goreng panas\"]', '[\"Cuci bersih ikan.\", \"Uleg bawang putih dan kunyit, lalu lumuri ikan dgn bawang putih dan kunyit yg sudah halus tdi, tambah ketumbar dan garam secukupnya, diamkan slama 30 menit agar meresap k ikan.\", \"Setelah 30 menit lalu goreng ikan.\", \"Menunggu ikan matang kita bikin sambal matahnya, iris tipis bwang merah dan cabe rawit piringkan,\", \"Iris dua bagian jeruk nipis, (klo yg doyan asem sih boleh satu biji jeruk nipis\'a), lalu peras k dlam irisan bawang dan cabe tdi, masukan royco dan tuangkan mnyak goreng yg panas, atau yg sedang d pakai menggoreng ikan, kira\\\"3/4 sendok makan, lalu tekan\\\" cabe dan bawangnya.\", \"Ikan goreng sambal matah siap d sajikan.😉\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(65, 2, 'Sop Ikan Patin', 'Resep Sop Ikan Patin yang lezat dan mudah dibuat di rumah.', '[\"1/2 kg ikan patin\", \"4 siung bawang merah\", \"3 siung bawang putih\", \"secukupnya Lada\", \"seruas jahe\", \"seruas kunyit\", \"seruas lengkuas\", \"salam sereh\", \"daun jeruk\", \"daun bawang\", \"daun sledri\", \"tomat\", \"secukupnya wortel\", \"secukupnya garam\", \"secukupnya gulpas\", \"secukupnya bubuk kaldu\", \"jeruk nipis\"]', '[\"Cuci bersih ikan patin lumuri dengan garam dan jeruk nipis\", \"Iris tipis bamer dan baput\", \"Tumis bamer, baput, daun salam, sereh, daun jeruk, jahe kunyit dan lengkuas yang dimemarkan\", \"Masukkan air ke dalam tumisan bumbu secukupnya. masak hingga air mendidih\", \"Masukkan gula garam bubuk kaldu, daun bawang, seledri, koreksi rasa\", \"Masukkan ikan patin dan tomat\", \"Masak hingga matang\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(66, 3, 'Steak Tenggiri perdana', 'Steak Tenggiri perdana dengan cita rasa segar khas laut.', '[\"250 gr tenggiri fillet\", \"1 siung bawang putih haluskan\", \"1 bh jeruk nipis ambil airnya\", \"1 sdm minyak wijen\", \"lada\", \"garam\", \"Bahan saos :\", \"2 siung bawang putih haluskan\", \"1 bh bawang Bombay kecil iris\", \"1 sdm kecap ikan\", \"1 sdm kecap manis\", \"1 sdt saos tiram\", \"1 sdm minyak wijen\"]', '[\"Cuci bersih ikan kemudian marinasi dg bumbu,diamkan selama 15mnt atau sampai bumbu meresap lalu panggang diteflon dg api kecil #ga punya grill😁 panggang sampai matang\", \"Sambil menunggu ikan matang,kita buat saosnya, panaskan minyak lalu tumis bawang putih sampai harum,lalu masukkan secara bersamaan sikecap2 tadi\", \"Setelah ikan matang,tata dipiring saji dan siapkan utk menu makan malam...😃 sajikan bersama sayuran rebus sesuka hati 😄\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(67, 3, 'Otak-otak ikan tengiri', 'Otak-otak ikan tengiri - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1/4 ikan tengiri\", \"200 gr tepung terigu\", \"50 gr tepung kanji\", \"3 siung bawah putih\", \"5 siung bawang merah\", \"2 batang daun bawang\", \"1 shacet masako rasa sapi\", \"1 butir telur ayam\"]', '[\"Giling daging ikan tengiri sampai halus (sesuai selera)\", \"Giling bawang merah dan putih\", \"Sisir daun bawang tipis-tipis\", \"Kocok telur dalam wadah\", \"Campurkan bahan ke 4 dalam wadah\", \"Aduk hingga rata, campurkan masako,garam,gula.\", \"Setalah tercampur semua, masukan ke adonan kedalam plastik. Jika sudah gunting ujung plastik.\", \"Siapkan air mendidih, masukan adonan yg d plastik dengan cara pencet perlahan plastik hingga membentuk lonjong.\", \"Jika sudah mengapung, tiriskan\", \"Tunggu 3-5 menit, otak-otak siap untuk di goreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(68, 3, 'Gulai ikan mas kacang panjang', 'Nikmati kelezatan Gulai ikan mas kacang panjang dengan resep sederhana ini.', '[\"2 ekor ikan mas, bersihkan. Beri jeruk nipis dan garam\", \"Secukupnya kacang panjang\", \"1 sachet santan instan\", \"secukupnya Air\", \"Bumbu halus:\", \"4 bawang merah\", \"2 bawang putih\", \"2 kemiri\", \"1/2 sdt ketumbar\", \"Salam,sereh,daun jeruk,jahe geprek,laos geprek\", \"Sedikit minyak untuk menumis\", \"secukupnya Gula garam\", \"Tambahan\", \"5 bawang merah utuh yg kecil\", \"10 cabe rawit utuh\", \"1 biji asam kandis\"]', '[\"Haluskan bumbu lalu tumis dengan sedikit minyak sampai harum. Masukkan salam,sereh,daun jeruk,jahe,laos. Beri air secukupnya dan santan sachet. Aduk² agar tidak pecah sampai mendidih\", \"Masukkan ikan, kacang panjang, dan bahan pelengkap. Beri gula garam. Tes rasa. Masak sampai semua matang\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(69, 2, 'Pindang Serani Ikan Patin', 'Sajian Pindang Serani Ikan Patin yang praktis dan lezat untuk dinikmati bersama.', '[\"500 gr ikan patin\", \"1 bh jeruk nipis\", \"4 bh bawang merah, potong tipis\", \"3 bh bawang putih, potong tipis\", \"1 ruas jahe, bakar, geprek\", \"1 ruas lengkuas, bakar, geprek\", \"1 ruas kunyit, bakar, geprek\", \"1 batang serai, geprek\", \"3 lembar daun jeruk\", \"2 lembar daun salam\", \"2 ikat daun kemangi\", \"2 bh tomat merah\", \"10 bh cabe rawit\", \"secukupnya air, garam, gula\"]', '[\"Cuci bersih ikan patin. Lumuri dengan jeruk nipis, diamkan sebentar, bilas hingga bersih.\", \"Tumis bawang merah, bawang putih, jahe, lengkuas, kunyit, serai, daun jeruk, daun salam hingga harum. Tambahkan air, tunggu hingga mendidih.\", \"Masukkan potongan tomat dan cabe, bumbui dengan garam dan gula secukupnya, tes rasa. Masukkan ikan patin, tunggu hingga matang (jangan sering diaduk). Terakhir masukkan daun kemangi.\", \"Sajikan dengan taburan bawang goreng.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(70, 4, 'Ikan tongkol bumbu kuning sunda', 'Resep praktis Ikan tongkol bumbu kuning sunda yang bisa dicoba di rumah.', '[\"2 ikan tongkol, potong sesuai selera\", \"10 cabe merah\", \"15 cabe rawit/ sesuai selera\", \"2 ruas kunyit\", \"1 ruas jahe\", \"2 butir kemiri\", \"4 siung bawang putih\", \"6 siung bawng merah\", \"1 batang sereh / geprek\", \"3 lembar daun salam\", \"1 buah tomat\", \"semuanya di uleg yaaaa\"]', '[\"Goreng ikan tongkol set mateng\", \"Tumis bumbu yg sudah dihaluskan : jahe, kunyit, bawang, kemiri, cabe merah, daun salam & sereh\", \"Aduk sampai matang & harum, lalu kasih air sedikit & cek rasa\", \"Setelah rasa sudah pas, masukan ikan tongkol yg sudah digoreng lalu tumis hingga air sedikit meresap\", \"Daaaannn siap disajikaannn😉😉🙏\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(71, 4, 'Gurame saos mangga', 'Sajian ikan nikmat: Gurame saos mangga yang mudah dibuat.', '[\"1 ekor gurame\", \"1 jeruk nipis\", \"5 sdm saos tomat\", \"1 sdm saos tiram\", \"2 cabe kriting haluskan\", \"1 ruas jahe\", \"1 bawang bombay\", \"1 wortel\", \"1 mangga muda\", \"1 gelas air\", \"Gula\", \"Garam\", \"Larutan maizena\"]', '[\"Balurin ikan dgn jeruk nipis + sedikit garam\", \"Goreng dlm minyak panas\", \"Tumis bombay dan jahe sampai harum\", \"Masukkan saos tomat dan saos tiram\", \"Tuang air dan saos tomat saos tiram\", \"Bumbuhi garam gula lada\", \"Kentalkan dgn maizena\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(72, 4, 'Spageti Tuna Pedas', 'Buat Spageti Tuna Pedas yang nikmat dengan langkah-langkah mudah ini.', '[\"1 bungkus fettucini/spagetti\", \"1 kaleng tuna\", \"2 buah tomat, buang biji\", \"10 cabe rawit (atau sesuaikan)\", \"1 buah bawang bombay\", \"3 siung bawang putih\", \"secukupnya Garam\", \"secukupnya Minyak goreng\", \"Air untuk merebus\", \"secukupnya Oregano/italian herbs\", \"Merica bubuk\"]', '[\"Rebus spagetti hingga aldente, tambahkan garam dan minyak goreng. Tiriskan.\", \"Panaskan minyak goreng, tumis bawang bombay dan bawang putih hingga harum.\", \"Masukan spagetti bersama dengan tuna, tomat, dan cabe. Bumbui dengan garam, oregano. Aduk hingga rata lalu sajikan selagi hangat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(73, 2, 'Ikan Kembung Goreng Saus Kecap Pedas', 'Sajian ikan nikmat: Ikan Kembung Goreng Saus Kecap Pedas yang mudah dibuat.', '[\"1 ekor ikan kembung goreng\", \"Resep saus :\", \"2 siung bawang putih\", \"1 buah cabe besar\", \"5 buah cabe rawit potong kecil (optional)\", \"1 sdm kecap manis\", \"1/2 sdm bubuk kaldu ayam/sapi\", \"1 sdm kecap ikan\", \"1/3 sdm lada putih\", \"2 sdm minyak goreng\", \"secukupnya Air putih\"]', '[\"Goreng ikan kembung segar, kemudian jika sudah masak, angkat dan tiriskan.\", \"Tumis bawang putih, cabe besar, dan cabe rawit dengan minyak panas sampai setengah layu dan harum, kemudian tambahkan sedikit air putih.\", \"Setelah itu masukan kecap manis, lada, kecap ikan, dan bubuk kaldu ayam/sapi dan aduk rata.\", \"Setelah itu masukan ikan kembung goreng yang ditiriskan tadi, masak beberapa saat hingga bumbu kecap meresap ke ikan. Jika sudah meresap matikan api dan pindahkan di piring.\", \"Siap disajikan dengan nasi hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(74, 2, 'Sup Ikan Mujaer', 'Nikmati kelezatan Sup Ikan Mujaer dengan resep sederhana ini.', '[\"1 ekor ikan mujaer\", \"1 ruas jari jahe (di geprek)\", \"secukupnya Royco ayam\", \"1/2 sdt merica bubuk\", \"1 bh bawang bombay\", \"2 sdm minyak untuk menumis\", \"1 batang seledri (iris)\", \"1 batang daun bawang (iris)\", \"Bumbu halus :\", \"4 siung bawang putih\", \"1 sdt garam\", \"secukupnya Pala\"]', '[\"Rebus ikan ± 3 menit agar mudah dipisahkan dari duri dan kepala\", \"Tumis bawang bombay, bumbu halus dan jahe geprek dengan minyak goreng.\", \"Masukkan bumbu yg telah di tumis ke dalam air kaldu ikan beserta ikan yg telah di pisahkan dari durinya.\", \"Masukkan merica bubuk\", \"Masukkan daun bawang dan seledri\", \"Aduk-aduk sambil cek rasa, tambahkan royco secukupnya.\", \"Siap disajikan dengan taburan bawang goreng lebih nikmat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(75, 4, 'Tuna Asam Manis', 'Resep praktis Tuna Asam Manis yang bisa dicoba di rumah.', '[\"200 gram tuna fillet\", \"1 siung bawang putih cincang (untuk rendaman)\", \"1 siung bawang putih (iris tipis)\", \"1/2 siung bawang bombay (iris tipis)\", \"2 buah cabai merah (iris menyerong)\", \"1/2 buah wortel (iris tipis panjang-panjang)\", \"2 buah tomat besar\", \"1 sdm saus sambal\", \"secukupnya Tepung serbaguna\", \"secukupnya Garam\", \"secukupnya Merica\", \"secukupnya Gula\", \"Kaldu ayam bubuk secukupnya (bisa diskip jika tidak suka)\", \"1/2 sdt tepung maizena (larutkan dengan sedikit air matang)\", \"Minyak untuk menggoreng dan menumis\"]', '[\"Potong tuna hingga ketebalan 1,5 cm. Lumuri dengan 1 sdm tepung serbaguna, bawang putih cincang, sedikit garam, dan sedikit air. Biarkan selama 15 menit sampai bumbu meresap.\", \"Taruh tepung serbaguna di piring terpisah. Gulingkan tuna yang sudah direndam tadi pada tepung serbaguna, lalu goreng dengan minyak panas dan api sedang. Ulangi langkah satu persatu sampai tuna habis. Tiriskan.\", \"Jus tomat: parut tomat, lalu saring agar kulit dan bijinya tidak terbawa. Bisa juga tomat diblender dengan air sedikit, lalu saring. Sisihkan dahulu.\", \"Tumis bawang putih, bawang bombay, cabai, dan wortel sampai layu dan harum.\", \"Masukkan jus tomat yang tadi dibuat. Lalu tambahkan sedikit air, gula, garam, merica, saus sambal, dan kaldu ayam bubuk. Koreksi rasa. Masak hingga mendidih.\", \"Tambahkan larutan maizena sedikit demi sedikit sampai saus agak kental. Jika kekentalannya dirasa cukup, jangan tambahkan semua.\", \"Masukkan tuna yang sudah digoreng tadi. Aduk sebentar, lalu sajikan dengan nasi hangat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(76, 4, 'Lele sambal kemangi delecious', 'Resep Lele sambal kemangi delecious yang lezat dan mudah dibuat di rumah.', '[\"5 lele\", \"daun kemangi\", \"bawang merah\", \"bawang putih cabe besar\", \"cabe kecil\", \"tomat\", \"terasi\", \"royco\", \"garam\"]', '[\"Lele di bersihkan dahulu lalu digoreng sampai matang\", \"Buat sambalnya semua bahan tadi kecuali daun kemangi di ulek\", \"Daun kemangi di cuci dulu\", \"Siapkan ulekan biar enak kalau di ulek ketimbang di blender\", \"Sambalnya di taruh di ulekan bersama lele goreng dan daun kemangi ditaruh pinggirnya\", \"Siap disajikan dech ;)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(77, 3, 'Cireng isi tongkol suwir pedas', 'Buat Cireng isi tongkol suwir pedas yang nikmat dengan langkah-langkah mudah ini.', '[\"♚ Bahan cireng\", \"250 gram tapioka/kanji\", \"20 gram terigu\", \"20 gram santan bubuk\", \"2 siung bawang putih parut\", \"Secukupnya garam\", \"Secukupnya air\", \"♚ Bahan isian\", \"Abon sapi/ ayam (me: tongkol suwir pedas)\"]', '[\"Pertama rebus air secukupnya,\", \"Siapkan wadah campur 250gr tapioka, 20gr terigu, 20gr santan bubuk, bawang putih yg telah diparut dan garam aduk rata.\", \"Tambahkan air yg sudah mendidih sedikit-sedikit, aduk dengan sendok.. Bila sudah agak dingin ulen dengan tangan hingga kalis.\", \"Setelah itu gilas adonan agak tipis, beri isian, bentuk sesuai selera.\", \"Goreng dalam minyak bnyak dengan api sedang hingga kecoklatan.. Angkat dan sajikan.\", \"Bisa diisi dengan sosis, bakso, ayam suwir..\", \"Untuk resep tongkol suwir pedas bisa dilihat pada postingan sebelumnya. Happy cooking 😄😍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(78, 3, 'Pepes kakap fillet', 'Pepes kakap fillet dengan cita rasa segar khas laut.', '[\"1/4 kakap fillet\", \"2/3 butir kelapa muda parut\", \"5 Bj cabe rawit merah/setan\", \"4 bj cabe keriting di potong potong\", \"5 Bj bawang merah\", \"4 siung bawang putih\", \"5 butir kemiri\", \"secukupnya Garam\", \"secukupnya Gula pasir\", \"sesuai selera Penyedap rasa\", \"Daun salam\", \"Lengkuas iris tipis tipis\", \"Daun pisang untuk membungkus\"]', '[\"Haluskan cabe rawit merah, bawang merah, bawang putih, kemiri, gula pasir dan garam, tambahkan sedikit penyedap rasa.\", \"Campurkan bumbu halus, kelapa muda parut dan potongan cabe keriting lalu aduk hingga rata\", \"Kemudian masukkan kakap fillet ke dalam campuran bumbu tadi, lalu aduk aduk sampe rata\", \"Setelah itu siapkan daun pisang, taruh potongan daun salam dan lengkuas lalu taruh kakap fillet yang sudah tercampur bumbu diatasnya. Lalu gulung membentuk seperti lontong\", \"Setelah semua terbungkus, lalu di kukus kira kira 30 menit\", \"Setelah matang kemudian di bakar.\", \"Pepes siap di hidangkan\", \"Selamat mencoba dan terima kasih.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(79, 3, 'Bandeng kecil bumbu acar', 'Bandeng kecil bumbu acar dengan cita rasa segar khas laut.', '[\"500 gr bandeng kecil\", \"3 siung bawang putih\", \"7 siung bawang merah\", \"2 batang cabe merah besar buang bijinya\", \"1 ruas jahe\", \"2 ruas kunyit\", \"Kemiri potong setengah\", \"1 sendok teh Ketumbar\", \"1 ruas Laos\", \"1 lembar daun jeruk\", \"2 lembar daun salam\", \"1 sendok teh garam\", \"1 sendok teh gula\", \"1/2 sachet Masako ayam\", \"Wortel 2 batang potong panjang\", \"Ketimun 2 batang potong panjang\", \"1 sendok makan Cuka\"]', '[\"Cuci bersih bandengnya,lalu beri perasan jeruk lemon dan juga garam,tunggu 2menit lalu goreng smp kering,sisihkan\", \"Potong wortel dan juga ketimun memanjang lalu cuci bersih,sisihkan\", \"Haluskan bumbu bawang merah,bawang putih,ketumbar, kemiri,jahe,kunyit,cabe merah besar,garam dan juga gula\", \"Tumis bumbu sampai harum masukkan laos,daun jeruk dan daun salam,lalu masukkan potongan ketimun dan wortel beri air\", \"Setelah mendidih masukkan bandengnya n beri masako dan juga cuka\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(80, 2, 'Sarden homemade simple', 'Sajian ikan nikmat: Sarden homemade simple yang mudah dibuat.', '[\"6 buah ikan sarden ukuran sedang\", \"2 buah tomat ukuran sedang\", \"4 btr bwg merah\", \"2 siung bwg putih\", \"1 sdm saos sambal/tomat\", \"1 buah jeruk nipis\", \"Garam, gula\", \"Secukup ny Penyedap\", \"Tambahkan cabai jika ingin pedas\"]', '[\"Cuci bersih ikan sarden, lalu buang kepalanya,kmudian kucuri dgn air jeruk nipis agar tdk amis, diam kan sebentar\", \"Iris semua bumbu, lalu tumis sebentar. Potong2 tomat, masukakan jika bumbu sudah layu.\", \"Aduk2 lalu tambah kan air, saos garam gula dan penyedap. Jika sudah mendidih masukkan ikan sarden. Jangan di aduk2 terus agar ikan tidak hancur. Aduk jika ingin membalik ikan nya saja, tes rasa.\", \"Biarkan hingga air menyusut dan ikan di rasa cukup matang, kuah ny jgn terlalu banyak\", \"Angkat dan sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(81, 2, 'Lele Goreng Renyah', 'Resep Lele Goreng Renyah ala rumahan yang dijamin menggugah selera.', '[\"3 ekor lele\", \"Garam\", \"Cuka\", \"Minyak goreng\", \"Bahan dihaluskan:\", \"6 siung bawang merah\", \"4 siung bawang putih\", \"Ketumbar\", \"1 cm Kunyit\"]', '[\"Bersihkan lele\", \"Haluskan bumbu, tuang bumbu halus tsb k mangkok/piring, beri 1 sendok teh cuka, beri air 1 gelas, beri garam secukupnya\", \"Rendam lele pada adonan tersebut minimal 10menit agar bumbu meresap.\", \"Panaskan minyak, lalu goreng lele sampai berwarna kecoklatan\", \"Angkat lele & sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(82, 3, 'Tim Ikan Kerapu', 'Tim Ikan Kerapu - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"2 ekor ikan kerapu (ukuran sedang)\", \"2 buah jamur shitake (rendam +- 1jam)\", \"Sedikit daun seledri\", \"1 batang Bawang pre, iris serong\", \"Jeruk nipis\", \"Garam\", \"Bumbu :\", \"2 buah cabe merah, buang biji, potong serong\", \"2 cm jahe, potong lidi\", \"6 siung bawang putih, cincang\", \"3 sdm minyak wijen\", \"2 sdt kecap asin\", \"2 sdt kecap ikan\", \"1/2 sdt merica\", \"Bahan pelengkap :\", \"2 siung bawang putih cincang\", \"1 sdm minyak wijen\"]', '[\"Bersihkan ikan, buang kotoran diperutnya (pastikan bersih agar tidak amis dan pahit). Sayat miring di bagian badan sekitar 2 sayatan. Lumuri ikan dengan air jeruk nipis dan garam. Diamkan 30 menit / hingga meresap.\", \"Jamur shitake setelah tidak keras, diiris memanjang.\", \"Campur semua bahan bumbu. Aduk hingga rata\", \"Bilas ikan, taruh dipinggan tahan panas. Lumuri dengan bumbu yang telah dicampur tadi secara merata, sampai di bagian dalam ikan. Tambahkan jamur shitake dibagian pinggir-pinggirnya. Tambahkan bawang pre dan daun seledri di atasnya. Lalu steam/tim/kukus ikan 20-30 menit.\", \"Sambil menunggu ikan matang, siapkan bahan pelengkap. Panaskan sedikit minyak goreng, masukkan bawang putih yang telah dicincang, goreng sambil diaduk sampai menguning. Matikan api. Biarkan bawang putih sambil disiram-siram minyak panas, sampai warna kecoklatan lalu angkat. Campur dengan minyak wijen.\", \"Setelah ikan telah matang dan siap dsajikan, tuangkan bahan pelengkap diatas ikan tim. Sajikan dengan nasi hangat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(83, 3, 'Pindang bandeng kecap', 'Sajian ikan nikmat: Pindang bandeng kecap yang mudah dibuat.', '[\"1 ekor bandeng sedang\", \"4 bh bawang merah\", \"3 bh bawang putih\", \"3 bh cabe\", \"1 ruas jahe\", \"1 ruas lengkuas\", \"1 ruas kunyit (sy pake kunyit bubuk)\", \"Sereh\", \"2 daun salam (remas2)\", \"2 daun jeruk\", \"1 buah tomat sedang\", \"Royco rasa ayam\"]', '[\"Bersihkan sisik ikan kemudian siangi buang bagian perutnya,lalu potong jadi 4bagian dan lumuri dengan gaeam dan jeruk nipis\", \"Iris semua bawang,jahe,lengkuas,cabe.panaskan minyak tumis semua bahan sampe harum masukan daun slam,daun jeruk dan sereh\", \"Masukan air beri kecap,garam,kunyit bubuk,gula,penyedap. Bila sudah mendidih masukan ikan biarkn sampe ikan matang jangan lupa masukan potongan tomat,,terakhir cicipi jika sudah pas matikan api dan sajikan :)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(84, 2, 'Lele sambel kemangi terasi', 'Buat Lele sambel kemangi terasi yang nikmat dengan langkah-langkah mudah ini.', '[\"3 ekor lele besar\", \"Tahu\", \"Kemangi secukupnya ambil daunya\", \"15 biji Lombok rawit\", \"1 Tomat\", \"1/2 sdt garam\", \"1 sdt gula\", \"Secuil terasi\", \"seperlunya Lalapan\"]', '[\"Goreng lele dan tahu sampai kering kecoklatan dengan bumbu kuning biar ga amis. Sisihkan\", \"Campur semua bahan untuk sambelanya kecuali kemangi.. Uleg jadi satu setelah halus uleg sebentar jangan sampai halus untuk kemanginya..\", \"Siap di hidangkan dengan nasi hangat 😊😊😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(85, 4, 'Spageti saus Sarden Balado Keju', 'Spageti saus Sarden Balado Keju dengan cita rasa segar khas laut.', '[\"150 gr Spagethi\", \"Sarden rasa Balado dalam kemasan\", \"Keju cheddar parut (pakai versi melted pun boleh)\", \"bumbu:\", \"1 siung bawang putih (cincang halus)\", \"Jahe (seukuran ibu jari) parut\", \"1 buah Tomat (dihaluskan)\", \"Cabai merah (potong serong)\", \"1 buah Jeruk nipis (jika suka)\"]', '[\"Rebus spageti sampai matang atau al dente\", \"Tumis bumbu sampai harum (kecuali jeruk nipis)\", \"Masukan sarden, lalu keju parut masak sampai matang.\", \"Angkat sarden, tuangkan pada spageti. Lalu beri sedikit jeruk nipis.\", \"Spageti siap dihidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(86, 3, 'Gurame Asam Manis Seadanya', 'Resep Gurame Asam Manis Seadanya ala rumahan yang dijamin menggugah selera.', '[\"6 ekor gurame asap\", \"10 butir cabe rawit\", \"2 siung bawang merah\", \"2 siung bawang putih\", \"1 sdm saos tomat\", \"1 sdm saos cabe\", \"1/2 sdm kecap manis\", \"1 sdt kecap ikan\", \"secukupnya gula,garam,lada,penyedap\", \"secukupnya air\"]', '[\"Goreng ikan gurame sampai kering\", \"Iris2 bawang merah,bawang putih dan cabe rawit,kemudian tumis hingga layu\", \"Kemudian masukkan sedikit air,saos tomat,saos cabe,kecap manis dan kecap ikan. Aduk rata\", \"Kemudian masukkan gula,garam,lada dan penyedap. Test rasa\", \"Kalau sudah pas,masukkan ikan guramenya dan masak sampai air menyusut.\", \"Dan siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(87, 4, 'Ikan Tenggiri Pesmol Segar', 'Resep Ikan Tenggiri Pesmol Segar ala rumahan yang dijamin menggugah selera.', '[\"500 gram ikan tenggiri (rendam dengan air perasan jeruk nipis dan garam)\", \"secukupnya cabai rawit\", \"1 buah tomat\", \"secukupnya air perasan jeruk nipis\", \"Bahan bumbu halus:\", \"5 siung bawang merah\", \"5 siung bawang putih\", \"1 batang kunyit\", \"7 buah kemiri\"]', '[\"Goreng ikan tenggiri lalu sisihkan\", \"Tumis bahan halus yang sudah diblender hingga matang, tambahkan garam dan kaldu jamur\", \"Masukan tomat potong dan cabai rawit\", \"Masukan ikan yang sudah di goreng dan perasan jeruk nipis untuk mendapatkan rasa segar dan asam sesuai selera\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(88, 2, 'Ikan tongkol kemangi', 'Cara membuat Ikan tongkol kemangi yang enak dan praktis untuk keluarga.', '[\"3 bungkus ikan tongkol\", \"Cabe rawit merah dan hijau (sesuai selera)\", \"1 ruas kunyit\", \"1 ruas jahe\", \"1 buah kemiri\", \"4 bawang merah\", \"2 bawang putih\", \"2 ikat daun kemangi\", \"1 batang serai\", \"1 lembar daun salam\", \"Secukupnya garam, gula dan penyedap\"]', '[\"Ikan tongkol saya rendam dengan air panas sebentar lalu di tiriskan\", \"Goreng ikan tongkol setengah matang\", \"Cuci daun kemangi dan bahan bumbu lainnya\", \"Haluskan bawang merah, bawang putih, jahe, kunyit, kemiri. Untuk cabe tdk saya haluskan pakai bulat utuh\", \"Tuang sedikit minyak utk menumis. Tumis bumbu yg telah dihaluskan sampai harum. Masukan garam, gula dan penyedap. Masukan daun salam dan batang serai.\", \"Masukan ikan tongkol dan daun kemangi. Jangan lupa cabe rawit utuh dimasukan. Tes rasa dan siap di sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(89, 2, 'Ikan pesmol nila', 'Buat Ikan pesmol nila yang nikmat dengan langkah-langkah mudah ini.', '[\"500 gram ikan nila\", \"7 bawang merah\", \"5 bawang putih\", \"1 tomat kecil\", \"2 Kemiri\", \"Ketumbah\", \"2 ruas kunyit\", \"2 Daun Salam\", \"1 tangkai Sereh\", \"1 cabe merah\", \"2 batang bawang daun\"]', '[\"Cuci ikan rendam dngan garam dan sedikit cuka (agar gak bgtu bau amis) ganti jeruk nipis jga bisa sedikit aja\", \"Goreng ikan sampai kering\", \"Haluskan bumbu bawang merah, bawang putih, kemiri, ketumbar, kunyit. Kemudian potong cabe, tomat, dan bawang daun\", \"Tumis bumbu dan cabe yg sudah d haluskan dengan minyak goreng hingga harum. Beri air sesuai dengan selera tunggu sampe air sedikit meletup-letup bru masukan bawang daun dan tomat, kemudian masukan ikan yg sudah d goreng diamkan selama -/+ 5 menit sampai air sedikit mengering\", \"Ikan siap d sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(90, 3, 'Mangut Lele (tanpa santan)', 'Cara membuat Mangut Lele (tanpa santan) yang enak dan praktis untuk keluarga.', '[\"4 ekor lele\", \"1 ruas lengkuas\", \"1 batang sereh\", \"2 lb daun salam\", \"5 buah cabe rawit\", \"Bumbu halus:\", \"4 siung bawang merah\", \"3 siung bawang putih\", \"3 buah cabe merah\", \"1 ruas jahe\", \"1 ruas kunyit (bakar)\", \"3 butir kemiri (sangrai)\", \"Garam, gula, penyedap (r*yco)\", \"Air\"]', '[\"Goreng kering lele. Sisihkan.\", \"Tumis bumbu halus sampai matang. Masukan sereh, daun salam & lengkuas.\", \"Masukan air. Tambahkan garam, gula & penyedap. Koreksi rasa hingga pas.\", \"Masukan cabe rawit. Masukan lele. Tunggu sampai air menyusut & bumbu meresap.\", \"Angkat & sajikan selagi hangat! 😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(91, 4, 'Ikan Tongkol Kemangi Kuah Santan', 'Buat Ikan Tongkol Kemangi Kuah Santan yang nikmat dengan langkah-langkah mudah ini.', '[\"1/4 ikan tongkol /pindang tongkol\", \"1 buah terong (saya skip)\", \"Tahu (saya ganti dgn tempe)\", \"1 ikat kemangi\", \"1 ruas lengkuas\", \"3-4 lembar daun salam\", \"1 sachet santan instan\", \"Garam\", \"Gula\", \"Secukupnya kunyit bubuk (tambahan dari saya)\", \"🍆 Bumbu iris :\", \"3 siung bawang putih\", \"3 siung bawang merah (tambahan dr saya)\", \"1 buah bawang bombai (saya 1/2)\", \"1 buah tomat\", \"Secukupnya cabai rawit utuh\", \"1 buah cabai merah besar (saya skip)\", \"1-2 buah cabai hijau (saya skip)\"]', '[\"Cuci bersih ikan tongkol,rebus sebentar lalu goreng. Kalau pakai ikan pindang tongkol, cukup di goreng saja ya bun.\", \"Potong2 tempe sesuai selera, lalu goreng, sisihkan.\", \"Panaskan minyak, tumis bawang merah, bawang putih hingga wangi dan kekuningan. Masukkan bawang bombai, aduk rata. Lalu masukkan daun salam dan lengkuas. Tambahkan air secukupnya.\", \"Masukkan santan instan, tambahkan garam, gula,kunyit bubuk, aduk rata dan koreksi rasa. Masukkan ikan dan tempe.\", \"Setelah mendidih, masukkan cabe rawit utuh. Tunggu agak kuah menyusut, lalu tambahkan tomat dan kemangi. Aduk sebentar lalu matikan kompor. Siap di sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(92, 3, 'IKAN GURAME SAMBEL JELETOT.... BY. Dapoer Linggar', 'Resep IKAN GURAME SAMBEL JELETOT.... BY. Dapoer Linggar yang lezat dan mudah dibuat di rumah.', '[\"1 ekor ikan gurame potong 4\", \"1 batang sereh geprek\", \"1 lembar daun jeruk\", \"1 buah tomat potong kasar\", \"2 bungkus terasi yang sudah di bakar lalu haluskan\", \"Garam\", \"Gula pasir\", \"blok Kaldu\", \"1 lembar daun salam\", \"Minyak untuk menumis\", \"10 buah cabe rawit merah utuh\", \"Ruas lengkuas geprek\", \"Bumbu iris :\", \"15 buah cabe rawit merah iris\", \"10 buah bawang putih iris\", \"20 buah bawang merah iris\"]', '[\"Goreng ikan hingga kering\", \"Tumis bumbu iris beserta sereh, lengkuas, daun salam, daun jeruk, terasi... tumis hingga harum dan layu\", \"Masukan tomat lalu aduk rata. Kemudian masukan ikan yang sudah di goreng, garam, gula dan kaldu blok\", \"Masak hingga ikan bercampur bumbu... Test rasa kemudian di angkat...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(93, 2, 'Lele Goreng Gurih', 'Resep Lele Goreng Gurih ala rumahan yang dijamin menggugah selera.', '[\"1/2 kg lele isi 7\", \"Secukupnya minyak goreng\", \"bumbu marinasi :\", \"5 siung bawang putih\", \"1 sdt ketumbar\", \"1/2 ruas kunyit\", \"Secukupnya garam\", \"Secukupnya air\"]', '[\"Cuci bersih lelenya. Sisihkan\", \"Haluskan bumbu marinasi\", \"Setelah halus, tambahkan air secukupnya di bumbunya dan tuangkan ke wadah lele\", \"Bolak balik lele sampai bumbunya merata.\", \"Masukkan kulkas diamkan semalaman\", \"Besoknya tinggal dgoreng. Yummy\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(94, 4, 'Nila Pedas Manis', 'Nila Pedas Manis dengan cita rasa segar khas laut.', '[\"secukupnya Garam\", \"4 biji cabe rawit\", \"1 siung bawang putih\", \"5 siung bawang merah\", \"1/2 potong gula merah kelapa\", \"sedikit terasi\", \"1 biji tomat\", \"1/2 kg ikan nila\", \"secukupnya kecap\", \"secukupnya air\", \"2 daun salam\", \"1 siung serai\", \"2 daun jeruk\", \"2 cm kunir\"]', '[\"Cuci bersih ikan nila\", \"Siapkan wajan n minyak dipanaskan, goreng ikan nila hingga matang\", \"Siapkan bumbu-bumbu sebagian ditumbuk sebagian di iris\", \"Iris serai dan daun jeruknya\", \"Goreng bumbu yg udah dihaluskan kemudian tambahkan air hingga mendidih tambahkan bumbu yg sudah di iris tadi\", \"Tambahkan ikan nila yg sudah digoreng tadi\", \"Tunggu hingga bumbunya meresap ke ikan nila\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(95, 2, 'Acar Ikan Nila', 'Resep praktis Acar Ikan Nila yang bisa dicoba di rumah.', '[\"3 ekor ikan nila ukuran sedang\", \"1 buah wortel\", \"1 buah timun (saya gapake)\", \"Bumbu:\", \"7 butir bawang merah\", \"4 butir bawang putih\", \"4 butir kemiri\", \"1 ruas jahe\", \"1 ruas kunyit\", \"1/2 sdt ketumbar\", \"1 ruas laos memarkan\", \"Daun salam\", \"Jeruk nipis\", \"2 buah cabe merah belah 2\", \"Garam\", \"Gula\", \"Merica\", \"Air\", \"Minyak\"]', '[\"Marrinete ika dengan garam, merica dan jeruk nipis. Diamkan\", \"Goreng ikan setengah matang. Tiriskan\", \"Haluskan bumbu, tumis hingga harum tambahkan laos dan daun salam. Tambahkan air 100 mL\", \"Masukkan wortel yg dipotong korek api (alumate) tunggu hingga layu.\", \"Seasoning, masukan ikan yang telah digoreng dan cabe yg telah dibelah 2. Tunggu 5 menit. Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(96, 2, 'Pindang Tongkol Bumbu Tomat', 'Sajian Pindang Tongkol Bumbu Tomat yang praktis dan lezat untuk dinikmati bersama.', '[\"2 ekor pindang tongkol\", \"1 bh tomat, potong\\\"\", \"3 btr bawang merah, cincang kasar\", \"2 siung bawang putih, cincang kasar\", \"3 bh cabe rawit mrh, iris bulat\", \"1 sdm kecap manis\", \"Garam, gula, penyedap sckpnya\"]', '[\"Bersihkan pindang tongkol, buang kepala, ekor dan tulangnya. Goreng setengah matang, sisihkan.\", \"Tumis bw mrh, bw pth sampai harum, masukkan cabe dan tomat, aduk\\\" masukkan pindang, beri kecap, garam, gula dan penyedap, tuang sedikit air, masak hingga air menyusut, koreksi rasa, angkat dan sajikan,,,,\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(97, 3, 'Roti goreng isi tuna', 'Cara membuat Roti goreng isi tuna yang enak dan praktis untuk keluarga.', '[\"roti tawar\", \"2 biji telor ayam (kocok lepas)\", \"serbuk roti (secukupnya)\", \"isian :\", \"150 gr tuna kaleng\", \"2 siung bawang putih (cincang)\", \"3 siung bawang merah (iris)\", \"1/2 bowang bombai (iris)\", \"8 buah rawit (boleh gak pake kalo buat anak) (iris)\", \"secukupnya lada & garam\"]', '[\"Panaskan minyak dan tumis bawang putih dan merah sampai harum, kemudian masukan bawang bombai dan rawit\", \"Setelah itu masukan ikan tuna (tumis sambil dihancurkan) tambahkan garam dan lada.. biarkan sebentar setelah itu angkat\", \"Untuk kulitnya : potong roti bagian pinggirnya lalu potong segitiga, habis itu isi roti dengan isian ikan tuna, pipihkan dibagian tepi agak isian tidak keluar, lalukan sampai roti & isian habis\", \"Panas kan minyak dengan api sedang, masukan roti ke telur lalu gulingkan ke serbuk roti, goreng hingga warna kecoklatan..\", \"Selamat mencoba 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(98, 4, 'Ikan mas bakar terasi', 'Buat Ikan mas bakar terasi yang nikmat dengan langkah-langkah mudah ini.', '[\"Bahan :\", \"2 ekor ikan mas, di kerat-kerat\", \"1/2 sendok makan air jeruk nipis\", \"1/2 sendok makan garam\", \"1 sendok makan air asam jawa\", \"3 sendok makan kecap manis\", \"3 sendok makan minyak sayur untuk menumis\", \"Bumbu halus :\", \"6 butir bawang merah\", \"3 siung bawang putih\", \"3 buah cabai merah besar\", \"4 buah cabai merah keriting\", \"2 buah cabai rawit merah\", \"1/2 sendok makan ketumbar\", \"2 sendok teh terasi\", \"2 cm jahe\", \"1 sendok teh garam\"]', '[\"Lumuri ikan mas dengan jeruk nipis & garam. Diamkan 15 menit.\", \"Panaskan minyak. Tumis bumbu halus sampai harum. Masukan air asam jawa. Angkat. Tambahkan kecap manis aduk rata.\", \"Oleskan ikan dengan bumbu. Diamkan lagi 10 menit.\", \"Bakar ikan sambil dioles sisa bumbu sampai matang.\", \"Sajikan dengan sambal kecap.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(99, 2, 'Tuna Tahu Bumbu Merah 🐟', 'Nikmati kelezatan Tuna Tahu Bumbu Merah 🐟 dengan resep sederhana ini.', '[\"🐟 Bahan Utama:\", \"250 g Ikan tuna\", \"6 buah Tahu berkulit potong dadu (tahu biasa juga boleh asal digoreng dulu yaa setengah matang)\", \"🐟 Bumbu Halus:\", \"3 siung Bawang putih\", \"1 siung Bawang merah (Sy pakai bawang bombay, karena di sini ga ada)\", \"5 buah Cabe merah (selera)\", \"3 buah Cabe rawit (selera)\", \"🐟 Bumbu Pelengkap:\", \"2 lembar Daun salam\", \"2 cm Lengkuas geprek\", \"Secukupnya air\", \"1 sdm Gula merah\", \"2 sdm kecap manis\", \"Secukupnya Garam\", \"Secukupnya Gula merah\", \"Secukupnya minyak goreng\"]', '[\"Bersihkan, potong, dan goreng ikan tuna.\", \"Haluskan duo bawang, cabe rawit, dan cabe merah besar.\", \"Panaskan minyak. Tumis bumbu halus, daun salam, dan lengkuas sampai keluar minyak dan berbau harum. Tambahkan air.\", \"Masukkan ikan tuna dan tahu.\", \"Tambahkan kecap manis, gula merah, dan garam.\", \"Aduk sesekali ya biar ikannya ga hancur. Pastikan apinya tidak terlalu besar karena ada gula, mudah gosong.\", \"Biarkan bumbu meresap dan air menyusut sambil koreksi rasa\", \"Tuna tahu bumbu merah siap dihidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(100, 4, 'Sup Gurame Honje', 'Sup Gurame Honje dengan cita rasa segar khas laut.', '[\"2 Ekor Ikan Gurame\", \"5 Siung Bawang Merah\", \"5 Siung Bawang Putih\", \"2 Tangkai Bunga Honje/ Kecombrang\", \"2 buah wortel\", \"1 Ruas Lengkoas\", \"1 Ruas Jahe\", \"2 Lembar Daun Salam\", \"2 Buah Jeruk Nipis\", \"1 Sdm Garam\", \"Penyedap Rasa\", \"2 1/2 Gelas Air\"]', '[\"Cuci ikan gurame sampai bersih dan di berikan perasan jeruk nipis + garam. Diamkan selama 5 menit agar tidak bau amis\", \"Iris tipis bawang merah, bawang putih dan daun honje/ kecombrang. Untuk laos, jahe dan batang honje/ Kecombrangnya di geprek aja ya. Dan jangan lupa juga untuk iris cabai rawit + wortel nya.\", \"Kukus ikan gurame terlebih dahulu selama 20 menit, kenapa harus di kukus dulu ? Biar ikannya tidak rontok saat di jadikan sup.\", \"Sambil menunggu ikan di kukus, mari kita tumis bahan bahannya seperti bawang merah bawang putih, lengkoas jahe dan daun salam lalu si daun honje/ Kecombrang. Tumisnya jangan lama lama sampai harum saja, lalu masukan wortel dan tambahkan air 2 1/2 gelas rebus hingga wortel matang.\", \"Setelah 2 menit mengkukus ikan, barulah ikan tersebut di angkat dan di cemplungkan ke dalam wajan yang berisikan bumbu + wortel. Oh iyaa sebelum masukan ikan ke wajan, ada baiknya kasih penyedap rasa (saya 2 sdt, ini sesuai selera) koreksi rasa jangan lupa ya buibu :)\", \"Sambil menunggu bumbu meresap ke ikan, masukan irisan cabai rawit dan biarkan selama 5 menit biar pedesnya keluar. Hehehehe\", \"And taraaaaaaaaaa, this is it !!! Ikan Gurame Honje/ Kecombrang siap di hidangkan. Wangi dan menggugah selera 👌👌👌👌\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(101, 2, 'Ikan Tongkol Bumbu Kuning', 'Ikan Tongkol Bumbu Kuning dengan cita rasa segar khas laut.', '[\"1 ekor ikan tongkol ukuran kecil, potong jadi 4\", \"1 buah jeruk nipis\", \"3 lembar daun salam\", \"3 lembar daun jeruk\", \"1 batang sereh, ambil bagian putih, geprek\", \"1 buah tomat merah, belah 4\", \"secukupnya Garam, gula\", \"Merica bubuk secukupnya (skip)\", \"Penyedap rasa (optional)\", \"Cabe rawit utuh sesuai selera (skip)\", \"Bumbu halus :\", \"5 siung bawang merah\", \"4 siung bawang putih\", \"1 ruas kunyit\", \"3 cm jahe\", \"5 biji kemiri\"]', '[\"Cuci bersih ikan tongkol. Beri perasan jeruk nipis dan garam. Diamkan kurleb 20-30 menit. Setelah itu, cuci bersih lagi dan goreng ikan tongkol hingga sedikit kering. Angkat\", \"Panaskan wajan, beri sedikit minyak. Tumis bumbu halus hingga harum. Masukkan daun salam, daun jeruk, sereh dan beri sedikit air, aduk rata.\", \"Masukkan ikan. Masak hingga air mendidih. Beri garam, gula putih dan penyedap rasa. Aduk rata. Biarkan hingga air berkurang dan bumbu meresap. Koreksi rasa\", \"Setelah air berkurang, tambahkan potongan tomat. Aduk rata hingga tomat sedikit layu. Angkat dan hidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(102, 2, 'Sarden ABC Masak Kemangi', 'Sarden ABC Masak Kemangi dengan cita rasa segar khas laut.', '[\"1 kaleng besar sarden abc ekstra pedas\", \"1 genggam daun kemangi\", \"10 buah cabe rawit,potong serong\", \"6 siung bawang merah,iris tipis\", \"3 siung bawang putih,iris tipis\", \"1 buah tomat,potong dadu\", \"200 ml air\", \"3 sdm minyak goreng\", \"Secukupnya garam dan gula pasir\"]', '[\"Panaskan minyak goreng,masukkan cabe dan duo bawang,tumis hingga harum\", \"Masukkan sarden dan air,aduk pelan.Tambahkan tomat,garam dan gula pasir. Masak hingga mendidih dan air sedikit menyusut. Tes rasanya.\", \"Masukkan kemangi,aduk pelan. Matikan api\", \"Sajikan😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(103, 4, 'Tongkol sarden pete uendesss', 'Resep Tongkol sarden pete uendesss yang lezat dan mudah dibuat di rumah.', '[\"6 ekor tongkol / pindang\", \"2 buah tomat kecil\", \"sebungkus Pete\", \"Bumbu halus :\", \"6 buah bawang merah\", \"3 siung bawang putih\", \"2 cabe merah\", \"15 cabe rawit\", \"Gula / garam secukupnyaa\", \"Penyedap rasa (boleh skip)\", \"secukupnya Air mateng\", \"Minyak untuk menggoreng dan menumis\"]', '[\"Cuci tongkol / pindang pluss potong sesuai seleraa\", \"Goreng setengah matang\", \"Haluskan bumbu\", \"Tumis bumbu + pete + cabe merah + tomat yang sudah dipotong kecil2 (sesuai selera)\", \"Masukkan air secukupnya\", \"Setelah harum masukkan ikan pindang / tongkol yang sudah digoreng setengah matang tadi\", \"Tambahkan gula pasir & garam secukupnyaa\", \"Cek rasaaa\", \"Kalau udahh ok tunggu mendidih angkat dan sajikaaaan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(104, 3, 'Mujaer Bumbu Kuning Kemangi', 'Buat Mujaer Bumbu Kuning Kemangi yang nikmat dengan langkah-langkah mudah ini.', '[\"Ikan mujaer goreng\", \"1 ikat kemangi\", \"5 siung bawang merah\", \"4 siung bawang merah\", \"1 cm kunyit\", \"1 sdt ketumbar\", \"2 butir kemiri\", \"1 buah tomat potong\", \"10 buah cabe rawit\", \"2 buah cabee merah\", \"3 lembar daun jeruk\", \"2 lembar daun salam\", \"2 batang serai geprek\", \"2 cm lengkuas geprek\", \"secukupnya Gula\", \"secukupnya Garam\", \"secukupnya Merica\", \"secukupnya Penyedap rasa\"]', '[\"Blender : bawang merah, bawang putih, ketumbar, cabe rawit, dan cabe merah.\", \"Tumis bumbu halus hingga harum dengan tomat, lengkuas, serai, daun salam, dan daun jeruk.\", \"Masukkan ikan mujaer yang sudah digoreng. Masak hingga bumbu merata.\", \"Trakhir masukkan faun kemangi.\", \"Siap dihidangkan.\", \"Semoga bermanfaat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(105, 3, 'Sop Ikan Nila Kemangi', 'Cara membuat Sop Ikan Nila Kemangi yang enak dan praktis untuk keluarga.', '[\"1 kg Nila (ukuran sedang)\", \"Bumbu\", \"Jahe (2 ruas jahe di geprek)\", \"1 ruang kunyit (haluskan)\", \"Lengkuas (1 ruas di geprek)\", \"Serai (3 di geprek)\", \"Bawang merah besar 2 butir iris kasar\", \"Bawang putih 2 iris kasar\", \"3 lembar Daun jeruk\", \"1 ukuran sedang Tomat hijau\", \"1 sendok Air asem jawa\", \"Daun bawang (iris miring)\", \"Cabai seseuai selera (potong miring)\", \"Garam (secukupnya)\", \"secukupnya Gula putih\", \"secukupnya Perasan jeruk nipis\", \"secukupnya Air\"]', '[\"Lumuri ikan dengan perasan air jeruk nipis\", \"Masukan isrisan bawang merah bawang putih, serai, jahe, kunyit, jahe, lengkuas garam, gula, dan air asama kedalam panci yang sudah berisi air\", \"Setelah mendidih masukkan ikan, dan tomat\", \"Setelah setengah matang, masukan daun kemangi dan irisan daun bawang\", \"Croschek rasa\", \"Siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(106, 4, 'Pampis tongkol', 'Sajian Pampis tongkol yang praktis dan lezat untuk dinikmati bersama.', '[\"400 gram ikan tongkol kukus\", \"1 batang sereh\", \"4 lembar daun jeruk\", \"1 ikat daun bawang\", \"1 ikat kemangi(Sy ga pake)\", \"Bumbu halus:\", \"10 bwg merah\", \"3 siung bwg putih\", \"2 cm jahe\", \"2 cm kunyit\", \"3 cabe merah\", \"10 cabe rawit\", \"Minyak untuk memumis\", \"secukupnya Garam gula\"]', '[\"Suwir2 ikan yg sdh dikukus\", \"Tumis bumbu halus, sereh, daun jeruk sampai harum\", \"Masukan ikan suwir, garam, gula, ketika hampir matang masukan daun bwg dan kemangi\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(107, 4, 'Bandeng suwir sambel korek', 'Sajian ikan nikmat: Bandeng suwir sambel korek yang mudah dibuat.', '[\"1,5 ekor ikan bandeng\", \"2 bawang putih\", \"15 cabe rawit\", \"secukupnya Garam gula\", \"3 sdm Minyak panas\"]', '[\"Goreng ikan bandeng. Tunggu agak dingin lalu suwir2.\", \"Uleg kasar baput dan cabe, tmbahkan garam gula, siram dg minyak panas sisa buat goreng ikan tdi.\", \"Campur rata dengan ikan bandeng yg sdh disuwir2 td.\", \"Sjikan dengan syur2 pelengkapnya, sayang sya kmarin gak ada kemangi, dtambah kemangi semakin mantap. Selamat mencoba.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(108, 3, 'Hot Tuna Puffs Super Simple', 'Sajian ikan nikmat: Hot Tuna Puffs Super Simple yang mudah dibuat.', '[\"1 kaleng tuna tomat dalam saos pedas\", \"2 lembar puff pastry instan\", \"1,5 sdt gula\", \"3 siung bawang putih haluskan tumis sebentar\", \"secukupnya keju mozzarela parut\", \"oregano buat taburan\"]', '[\"Taburi pastry dg sedikit tepung, biarkan dalam suhu kamar selama 20 menit, potong masing2 jd 8 bagian segitiga.\", \"Campurkan gula dan bawang putih dg tuna, aduk hingga rata.\", \"Olesi sekeliling pinggir lembar puff pastry dg air (lebih bagus lagi dg putih telur kalau ada), rekatkan satu bagian hingga membentuk kantung segitiga, isi dg 1-1,5 sdt tuna dan mozzarela secukupnya. Tutup pinggir bagian yg lain, tekan dg garpu bagian2 yg direkatkan tadi.\", \"Tata dlm loyang olesi atasnya dg sedikit air (lebih bagus kalau ada kuning telur yg dikocok), taburi oregano secukupnya.\", \"Panggang dg suhu 200 derajat Celcius selama 20 menit atau atau sesuaikan dg oven masing2. Sajikan dg mayonaise bila suka. Yummy!\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(109, 3, 'Bali ikan Bandeng', 'Resep praktis Bali ikan Bandeng yang bisa dicoba di rumah.', '[\"1/4 ikan bandeng\", \"5 buah cabai merah besar\", \"10 buah cabai rawit\", \"3 siung bawang putih\", \"2 siung bawang merah\", \"2 cm Lengkuas\", \"2 cm Kunyit\", \"1 cm Jahe\", \"2 lembar Daun jeruk\", \"2 lembar Daun salam\", \"1 batang Serai\", \"3 butir Kemiri\"]', '[\"Bersihkan ikan bandeng kemudian potong menjadi 2 bagian, jika tidak suka di potong todak masalah sesuai selera\", \"Kemudian tambah dengan garam dan lumuri jeruk nipis 2 sdm, biarkan 10 menit supaya meresap\", \"Siapkan bumbu halus yaitu cabai merah, cabai rawit, bawang merah, bawang putih, kunyit,lengkuas,jahe, kemiri kemudian haluskan semua bumbu\", \"Setelah 10 menit goreng ikan sampai matang\", \"Tumis bumbu yang sudah halus dengan minyak goreng secukupnya, masukkan daun jeruk, daun salam dan serai\", \"Masukkan ikan yang sudah digoreng bersama dengan bumbu yang sudah matang dan ditumi bersama sekitar 10 menit tambah air sedikit dan diamkan supaya bumbunya meresap...trimakasih\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(110, 2, 'Pais Patin Banjar', 'Pais Patin Banjar dengan cita rasa segar khas laut.', '[\"1/2 kg ikan patin\", \"Daun pisang\", \"1 biji Tomat\", \"1 biji cabe hijau\", \"Bumbu halus :\", \"5 siung bawang putih\", \"8 siung bawang merah\", \"1 ruas jari kunyit\", \"1 ruas jari laos\", \"1 batang serei\", \"1 sdt garam\", \"1 sdt penyedap\", \"3 buah kemiri\"]', '[\"Haluskan seluruh bumbu halus dengan cara diulek (agar tekstur bumbunya masih ada)\", \"Bersihkan ikan patin, lumuri dengan bumbu halus, tunggu 15 menit sampai bumbu meresap\", \"Sambil menunggu bumbu meresap, panaskan daun pisang diatas kompor agar layu dan tidak pecah saat dilipat. Potong potong memanjang tomat dan cabe hijau\", \"Stelah 15 menit tata ikan patin diatas daun pisang bersama bumbu, taburi tomat dan cabe hijau diatasnya, kemudian bungkus\", \"Kukus patin yang sudah dibungkus selama 15 menit\", \"Setelah matang, pais patin yang sudah dikukus di bakar lagi sampai kering (aku bakarnya pke teplon). Pais patin siap dinikmati\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(111, 4, 'Nasi goreng tempe salmon', 'Nasi goreng tempe salmon - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"nasi\", \"ikan salmon yg sdh di goreng\", \"tempe yg sdh di goreng dn di remas kecil2\", \"garam\", \"bawang putih\", \"bawang merah\", \"2 sendok mkn minyak goreng\", \"cabai bisa tmbhkn klo mau pedes\"]', '[\"Cincang bumbu bawang putih bawang merah dn (cabai bl prlu)\", \"Lalu tumis dgn 2.sendok mkn minyak goreng.\", \"Tumis hingga aroma harum lalu masukkn nasi.aduk2.msukn tempe yg sdh remuk dn salom..\", \"Aduk di orak arik hingga stengh mateng.jgn lp tmbhkn garam secukupnya..orak arik krg lbih 10 mnit..angkt dn hidangkn d piring saji..bs di hias dgn tomat atau mntimun ssuai selera anda..selmt mncoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(112, 4, 'Dory Fish Popcorn 🐟', 'Resep Dory Fish Popcorn 🐟 ala rumahan yang dijamin menggugah selera.', '[\"1 lembar ikan Dory\", \"1 bh jeruk nipis\", \"🌹Bahan adonan basah\", \"2 sdm tepung bumbu (ex:sajiku)\", \"1/2 sdt garlic powder\", \"Secukupnya lada\", \"🌹Bahan pelapis\", \"5 sdm tepung terigu\", \"1 sdm tepung maizena\", \"Secukupnya Kaldu jamur\"]', '[\"Bismillah 🙏🏻\", \"Cuci bersih ikan dory, lumuri perasan jeruk nipis, diamkan selama 5 menit\", \"Ambil wadah kedap udara, tambahkan adonan basah lalu tambahkan air sedikit demi sedikit sambil d aduk\\\" (adonan basah jgn terlalu encer)\", \"Bilas ikan dory yg sudah d lumuri jeruk nipis, potong2 sesuai selera, tuang ke wadah adonan basah lalu tutup wadah, diamkan d dlm kulkas selama 30 menit sampai 1 jam\", \"Ambil dory dari kulkas, ambil satu\\\"ikan lalu gulung\\\" ke adonan tepung kering, lalu goreng sampai matang\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(113, 2, 'Sambal Sarden', 'Resep praktis Sambal Sarden yang bisa dicoba di rumah.', '[\"3 ekor ikan sarden segar\", \"3-4 bawang merah\", \"2 cabe merah\", \"3 cabe rawit\", \"1 tomat merah besar\", \"Secukupnya garam, gula, bumbu racik sajiku (ikan goreng), air\"]', '[\"Bersihkan ikan, lumurin bumbu racik sajiku u/ ikan goreng, diamkan agar bumbu meresap (me : masukkan kulkas supaya cepat meresap)\", \"Haluskan bumbu, (bawang merah, cabai merah, cabai rawit, garam, gula beri sedikit penyedap rasa), iris dadu tomat merah nya, sisihkan\", \"Goreng ikan sampai kering dan matang\", \"Tumis bumbu yg sudah dihaluskan sampai harum.... Tambahkam sedikit air, masukkan irisan tomat, cicipi rasa, bila sudah pas masukkan ikan nya... Aduk2 supaya meresap, lalu angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(114, 3, 'Tumis tuna', 'Nikmati kelezatan Tumis tuna dengan resep sederhana ini.', '[\"1 kaleng tuna\", \"1 bawang bombay iris lembut\", \"3 siung bawang putih geprek\", \"2 iris jahe\", \"sedikit daun bawang\", \"minyak untuk menumis\", \"garam\", \"gula\", \"kecap asin\"]', '[\"Tumis bawang jahe dan bawang bombay\", \"Lalu masukkan tuna, beri bumbu, penyedap rasa dan aduk sampai matang dan beri daun bawang tes rasa.\", \"Matang hidangkan selamat mencoba by soimut\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(115, 4, 'Pecak Lele', 'Cara membuat Pecak Lele yang enak dan praktis untuk keluarga.', '[\"500 gr lele\", \"jeruk nipis\", \"secukupnya garam\", \"Bahan bumbu sambal:\", \"3 buah cabe merah (sesuai selera)\", \"3 siung bawang merah\", \"3 buah kemiri\", \"1 sdt terasi\", \"secukupnya Garam\", \"secukupnya Gula pasir\"]', '[\"Bersihkan lele, lumuri dengan garam dan jeruk nipis, diamkan kurleb 15 menit\", \"Goreng lele hingga matang\", \"Ulek bahan2 sambal, hingga halus, tambahkan sedikit air hangat\", \"Koreksi rasa. masukan lele goreng ke dalam sambal, kemudian pecak atau ulek kasar\", \"Pecak lele sangat cocok dinikmati dengan nasi hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(116, 3, 'Ikan Tongkol Suwir Pedas', 'Sajian Ikan Tongkol Suwir Pedas yang praktis dan lezat untuk dinikmati bersama.', '[\"1 ekor ikan tongkol\", \"secukupnya garam\", \"2 lembar daun jeruk\", \"1 buah jeruk nipis\", \"100 ml air\", \"1/2 sdt gula pasir\", \"1/2 sdt kaldu bubuk\", \"seperlunya minyak goreng\", \"Bumbu Ikan yang Dihaluskan:\", \"3 siung bawang putih\", \"10 buah cabe merah besar\", \"6 butir bawang merah\", \"10 buah cabe rawit merah\"]', '[\"Pertama, kita bersihkan terlebih dahulu ikan tongkol yang sudah anda persiapkan.\", \"Untuk membuat ikan tongkol suwir, pertama setelah ikan didiamkan selama waktu yang telah ditentukan, silahkan panaskan minyak dalam wajan.\", \"Lalu goreng ikan tongkol kedalamya hingga berwarna keemasan, namun perhatikan jangan sampai bagian dalam yakni bagian daging ikan menjadi kering. Sebab hal ini akan membuat daging ikan sulit disuwir-suwir\", \"Setelah digoreng dan matang, silahkan angkat ikan dari penggorengan dan biarkan minyaknya menetes terlebih dahulu.\", \"Baru setelah itu, ambil bagian daging ikan dan suwir-suwir setelah daging ikan dingin, lalu masukkan dalam wadah dan sisihkan sementara.\", \"Kemudian, panaskan minyak secukupnya dalam wajan dan tumis bumbu yang telah dihaluskan bersama dengan daun jeruk hingga tumisan ini mengeluarkan aroma yang harum dan sedap.\", \"Tuangkan air kedalamnya bersama dengan bumbu yakni garam, kaldu bubuk dan gula pasir secara merata dan masak sampai tumisan bumbu ini mengental dan meletup-letup.\", \"Masukkan ikan tongkol yang sudah di suwir kedalamnya, aduk merata dan masak hingga daging ikan tercampur dengan bumbu ini. Masak hingga mngering dengan menggunakan api yang kecil.\", \"Setelah ikan mengering, silahkan angkat ikan dan sajikan dalam piring saji.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(117, 4, 'Woku Kepala Tongkol', 'Woku Kepala Tongkol - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"2 kepala ikan tongkol dibelah 2\", \"Jeruk Ikan / jeruk sambal\", \"Minyak makan untuk menumis\", \"sesuai selera penyedap rasa\", \"300 ml air\", \"Bumbu :\", \"2 batang serai digeprek\", \"5 lembar daun jeruk\", \"Iris halus :\", \"5 buah bawang merah\", \"2 batang daun bawang\", \"Haluskan :\", \"2 siung bawang putih\", \"3 buah cabai keriting\", \"7 buah cabai rawit\", \"5 buah kemiri\", \"2 ruas jari jahe\", \"2 ruas jari kunyit\"]', '[\"Sebelum menyiapkan bumbu, lumuri kepala ikan dengan air jeruk lalu diamkan\", \"Panaskan minyak makan, masukkan bawang merah,tumis hingga layu\", \"Masukkan bumbu halus sampai beraroma dan setengah matang, kemudian masukkan serai, daun jeruk dan daun bawang sampai agak layu kemudian masukkan penyedap rasa\", \"Masukkan kepala ikan, aduk dengan bumbu selama 1 menit, tambahkan air dan aduk sebentar lalu tutup, biarkan sampai air mendidih\", \"Koreksi rasa setelah itu tutup kembali, biarkan kurang lebih 10 menit.\", \"Kepala ikan siap dihidangkan\", \"Note : masak ikan dengan api sedang\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(118, 4, 'Chilli Tuna Puff Kilat Super Yummy 😙', 'Chilli Tuna Puff Kilat Super Yummy 😙 dengan cita rasa segar khas laut.', '[\"1/2 pack Kulit puff instant saya merk.Edo\", \"Bahan Isian\", \"1 Kaleng Tuna in oil pedas saya merk Kingfisher\", \"3 siung bawang putih digoreng ambil minyaknya aja\", \"secukupnya Boncabe/chili flakes\", \"secukupnya Garam\", \"secukupnya lada\", \"secukupnya Gula\", \"2 butir Telur Rebus potong2\"]', '[\"Langkah\", \"1.Tumis chili tuna chunk dengan minyak bawang disusul jagung pipil,lalu masukkan gula+garam+merica/lada hitam sesuai selera.\", \"2.Terakhir,taburi Chili Flakes/Boncabe dan Parsley cincang,aduk rata,sisihkan\", \"3.Potong puff seperti di foto step2,isi dengan telur rebus+tuna,lalu lipat,pipihkan samping2nya menggunakan ujung garpu supaya tidak bocor\", \"4.Oles kuning telur,semprot saus+parsley\", \"Panggang dengan suhu kurleb 200 derajat sampai keemasan dan kokoh sekitar 18 menit atau sesuaikan oven sendiri\", \"Enjoyyy\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(119, 2, 'Shirataki Tuna', 'Resep praktis Shirataki Tuna yang bisa dicoba di rumah.', '[\"200 gram Mie Shirataki\", \"Tuna in Oil (Saya pakai merek King Fisher) - karena lagi diskon\", \"3 siung Bawang Putih\", \"3 buah Cabai Merah Keriting\", \"1 buah Bawang Bombay\", \"secukupnya Garam\", \"Bisa tambah cabai rawit merah biar lebih pedas\"]', '[\"Rebus mie shirataki sebentar kemudian tiriskan\", \"Buka kaleng tuna sedikit saja. Keluarkan minyaknya ke penggorengan. Panaskan minyaknya sampai airnya hilang.\", \"Masukkan bawang putih dan bawang bombay. Masak hingga harum.\", \"Masukkan cabai. Masak sampai layu.\", \"Masukkan tuna. Campurkan sampai rata. Masukkan garam. Aduk kembali.\", \"Setelah tercampur rata, masukkan mie shirataki. Aduk sampai merata.\", \"Sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(120, 2, 'Tumis sarden banten + tahu', 'Sajian Tumis sarden banten + tahu yang praktis dan lezat untuk dinikmati bersama.', '[\"1 kaleng sarden banten\", \"2 tahu potong dadu\", \"1 siung bawang putih\", \"3 siung bawang merah\", \"2 buah tomat kecil hijau\", \"4 buah cabe rawit (klo yg skanya pedes iya tambahin lgi cabenya)\", \"Penyedap rasa\"]', '[\"Cuci bahan: bawang, cabe, tomat, kemudian iris.\", \"Setelah itu goreng tahu hingga sedikit berkulit dan jngan terlalu garing\", \"Tumis bahan no. 1 hingga harum\", \"Kemudian masuk\'n kuah sarden aduk dengan tumisan td, tambah sedikit air\", \"Setelah itu masukkan tahu aduk dan kemudian masuk\'n ikan sardennya aduk dan jngan lupa tambahkan masako aduk kembali tunggu beberapa menit.\", \"Makanan siap di sajikan😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(121, 3, 'Tenggiri Rica Rica', 'Nikmati kelezatan Tenggiri Rica Rica dengan resep sederhana ini.', '[\"1/2 kg ikan tenggiri\", \"Bumbu yg dihaluskan\", \"10 bawang merah\", \"4 bawang putih\", \"15 cabai kriting\", \"10 cabai rawit (kalo suka pedas bisa ditambah)\", \"5 cabai merah besar (kalo tidak ada boleh tambahin cabe kritingnya)\", \"3 lembar daun jeruk\", \"2 lembar daun salam\", \"2 batang serai (geprek)\", \"1 buah jeruk nipis (diperas)\", \"Air (50ml)\"]', '[\"Bumbui ikan dengan bumbu ikan lalu goreng, matang dan tiriskan (jika memakai ayam, rebus ayam, matang, bumbu dengan lada dan garam, lalu goreng menguning angkat)\", \"Tumis semua bumbu yg sudah diulek atau diblender, dan masukkan daun jeruk, salam, dan serai, sudah wangi dan matang semua bumbu, masukkan air dan perasan Jeruk nipis\", \"Koreksi rasa, dan selamat mencoba mommy2 😍😍😍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(122, 2, 'Bandeng Cabe Ijo', 'Bandeng Cabe Ijo - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1/2 kg ikan bandeng, bersihkan\", \"3 buah tomat hijau, potong2 (saya skip)\", \"10 cabe rawit ijo, potong2\", \"5 cabe ijo besar, potong2\", \"3 cabe ijo keriting, potong2\", \"100 ml air\", \"Garam gula lada\", \"bumbu halus :\", \"8 bawang merah\", \"3 bawang putih\", \"3 butir kemiri\", \"1 cm jahe\"]', '[\"Bersihkan ikan bandeng, potong2. Goreng & sisihkan\", \"Tumis bumbu halus, kemudian tambahi air.\", \"Masukan ikan goreng & trio cabe + tomat hijau. Bumbui garam gula lada. Aduk rata. Tes rasa\", \"Hidangkan dengan nasi putih panas..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(123, 2, 'Acar Gurame Pedas #olahan ikan', 'Cara membuat Acar Gurame Pedas #olahan ikan yang enak dan praktis untuk keluarga.', '[\"4 ekor gurame ukuran sedang, kerat2\", \"1 buah jipang, potong korek api\", \"2 buah wortel.,potong korek api\", \"10 siung bawang merah, potong jd 2\", \"Sepotong jeruk nipis\", \"Mix cabe, rawit, hijau, merah, potong jd 2(sesuai selera)\", \"Bumbu halus :\", \"7 bawang putih\", \"1 ruas jahe\", \"2 ruas Kunyit\", \"7 butir kemiri utuh\", \"1/2 sdt merica\", \"Bumbu pelengkap\", \"2 batang serai, memarkan\", \"2 sdm cuka makan\", \"1 1/2 sdm gula pasir\", \"1 sdm garam, (peres)\", \"1 sdt kaldu jamur\", \"Bumbu goreng ikan : 1 siung bawang putih, seruas kunyit, 1 sdt garam\"]', '[\"Bersihkan ikan, buang insang dan kotoran lalu kerat2, lumuri dengan jeruk nipis. Diamkan 5 menit, siapkan bumbu halus perendam ikan, beri 2 sendok air.\", \"Cuci bersih ikan, lumuri bumbu perendam sampai rata. Sembari menunggu kita panaskan minyak goreng, goreng kering\", \"Kupas dan potong korek api wortel dan jipang, beri sedikit garam kemudian remas2, cuci bersih dan tiriskan\", \"Ulek bumbu halus, panaskan minyak, tumis bumbu halus dengan serai.\", \"Setelah matang tambahkan air sedikit, masukkan cabai tambahkan merica, gula, garam, kaldu jamur dan cuka. Tunggu hingga mendidih cek rasa, biasanya kalau kuahnya mengering nanti asin sendiri jd takaran garam jgn terlalu bnyk. Masukkan ikan, taburi sayur diatasnya lalu tutup dan madak dg api kecil.\", \"Tunggu 3 mnit, balik ikan agar meresap di semua sisi, masukkan potongan bawang merah, tungu 5 menit lg sampai sayuran mulai layu dan kuah menyusut. Koreksi rasa sesuai selera. Siap disajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(124, 2, 'Sup Patin Gurih', 'Nikmati kelezatan Sup Patin Gurih dengan resep sederhana ini.', '[\"1/2 kg ikan patin\", \"2 cm jahe, memarkan\", \"3 buah tomat\", \"1 ltr air\", \"1 sdm kecap ikan\", \"1 sdm air jeruk nipis\", \"Cabe rawit utuh\", \"Garam gula\", \"bumbu halus :\", \"3 cabe merah besar\", \"8 bawang merah\", \"3 bawang putih\"]', '[\"Cuci bersih ikan, potong2. Sisihkan\", \"Tumis bumbu halus. Masukan jahe + air, didihkan\", \"Masukan ikan, biarkan matang. Tambahkan kecap ikan + tomat + cabe rawit\", \"Bumbui garam-gula-lada. Aduk rata. Tuangi air jeruk nipis\", \"Didihkan sekali lagi. Tes rasa.\", \"Angkat & segera hidangkan..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(125, 2, 'Tumis ikan kembung', 'Sajian ikan nikmat: Tumis ikan kembung yang mudah dibuat.', '[\"1/2 kg ikan kembung dipotong\", \"1/2 sachet saos tiram\", \"2 biji bawang putih\", \"1/4 bawang bombay\", \"1/2 cabe merah\", \"1 cabe hijau gendot\", \"secukupnya penyedap rasa\"]', '[\"Goreng bumbu sampai baunya harum\", \"Masukan ikan dan kasih sedikit air\", \"Masukan saos tiram,penyedap rasa\", \"Masak dengan api kecil dan biarkan sampai bumbu meresap ke ikannya\", \"Angkat dan sajikan,mudah bukan?\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(126, 3, 'Somay ikan tuna', 'Nikmati kelezatan Somay ikan tuna dengan resep sederhana ini.', '[\"1/4 ikan tuna\", \"1/4 tepung sagu\", \"100 gram tepung terigu\", \"1 bungkus merica bubuk\", \"1 bungkus penyedap rasa\", \"2 batang daun bawang\", \"4 bawang putih\", \"1 telur\", \"2 labu siam\", \"pelengkap:\", \"1 tahu putih\", \"2 kentang\", \"kol\", \"3 telur rebus\", \"bumbu kacang:\", \"1/4 kacang tanah\", \"4 cabe merah\", \"5 cabe rawit\", \"4 bawang putih\", \"bawang goreng\", \"minyak goreng,gula,garam,penyedap rasa\"]', '[\"Cuci ikan tuna blender dengan bawang putih beri sedikit air sampai halus\", \"Parut labu siam (pake parutan keju)remas\\\"sampai keluar air campurkan tepung sagu,terigu,merica,telur,penyedap rasa dan ikan tuna yg sudah d blender aduk\\\" sampai kalis\", \"Siap kan panci rebus air sampai mendidih masukan adonan somay,bentuk sesuai selera tunggu sampai adonan mengapung angkat lakuksn sampai habis\", \"Goreng kacang tanah,cabe, dan bawang putih halus kan(blender)\", \"Tumis bumbu kacang dengan sedikit minyak aduk\\\"sampai harum dan beri air 2 gelas,beri gula,garam,penyedap rasa tunggu sampai mendidih masukan bawang goreng aduk\\\" trs koreksi rasa angkat\", \"Siapkan kukusan msukan somay yg sudah d rebus,tahu,telur,kol dan kentang kukus kira\\\" 20 menit sampai kol dan kentang matang\", \"Tata somay,kentang,tahu,telur,kol,dan bumbu kacang beri perasan jeruk limo selamat mencoba di jamin ga kalah sama somay bandung😀\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(127, 4, 'Tomyam (jawa) ikan patin sederhana dan praktis', 'Resep Tomyam (jawa) ikan patin sederhana dan praktis ala rumahan yang dijamin menggugah selera.', '[\"1 kg ikan patin potong sesuai selera\", \"10 bh blimbing wuluh potong jd 4\", \"2 bh tomat potong sesuai selera\", \"25 bh cabe rawit (10 dihaluskan 15 diutuhkan)\", \"3 bh cabe merah\", \"6 siung bawang merah\", \"6 siung bawang putih\", \"1 bh jeruk nipis\", \"3 lbr daun jeruk\", \"2 btg serai\", \"1 ruas laos\", \"1 ruas kunyit\", \"1 ruas jahe\", \"5 tangkai daun bawang merah\", \"1 ltr air\", \"secukupnya Garam\", \"secukupnya Gula pasir\"]', '[\"Cuci bersih ikan patin lalu lumuri dgn air jeruk nipis\", \"Haluskan cabe,bawang merah,bawang putih,kunyit,jahe,daun jeruk\", \"Geprek lengkuas,sereh\", \"Rebus air kalau sdh mendidih masukan ikan patin biarkan selama 5 menit agar ikan matang\", \"Masukan bumbu yg sdh dihaluskan,sereh,laos\", \"Masukan tomat,blimbing wuluh,garam,gula pasir,cabe utuh\", \"Koreksi rasa\", \"Biarkan mendidih lalu masukan daun bawang merah trs angkat\", \"Tomyan ikan patin siap dinikmati\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(128, 2, 'Balado ikan cakalang dan telur', 'Sajian ikan nikmat: Balado ikan cakalang dan telur yang mudah dibuat.', '[\"1/2 kg ikan cakalang (3 ekor)\", \"4 btr telur rebus\", \"1 butir jeruk nipis\", \"Bumbu halus :\", \"8 siung bawang merah\", \"3 siung bawang putih\", \"5 buah cabe merah\", \"10 buah cabe rawit merah (sesuai selera)\", \"1 sdm bubuk cabe (optional)\", \"3 lbr daun jeruk\", \"Secukupnya terasi\", \"Secukupnya gula pasir dan garam\"]', '[\"Bersihkan ikan cakalang. Potong jadi 2 bagian. Lumuri dengan jeruk nipis dan garam lalu goreng. Sisihkan.\", \"Haluskan semua bumbu kecuali daun jeruk.\", \"Panaskan minyak. Tumis bumbu halus dan daun jeruk sampai berbau harum. Tambahkan air kira kira setengah gelas. Aduk sampai air menyusut.\", \"Masukkan telur rebus. tambahkan gula garam. Aduk rata.\", \"Setelah bumbu mengental dan berminyak masukkan ikan cakalang yang sudah digoreng. Koreksi rasa.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(129, 3, 'Pempek Adaan Tenggiri', 'Nikmati kelezatan Pempek Adaan Tenggiri dengan resep sederhana ini.', '[\"120 ml air\", \"5 siung bawang merah dicacah\", \"1 sendok teh garam halus\", \"1 butir telur\", \"1/4 sendok teh gula\", \"2 sendok makan tepung terigu\", \"250 gram tepung sagu/tapioka\", \"Minyak goreng\", \"250 gram daging ikan tenggiri yg sudah dihaluskan\"]', '[\"Campur air dan daging ikan aduk rata.\", \"Masukkan garam, gula pasir, telur, bawang merah aduk rata.\", \"Masukkan tepung terigu Dan tepung sagu aduk sampai semua adonan benar2 menyatu.\", \"Panaskan minyak goreng, bentuk bulat dengan 2 buah sendok langsung masukakn ke dalam minyak panas.\", \"Goreng sampai berwarna kuning kecoklatan.\", \"Sajikan dengan kuah cuka.\", \"Resep kuah cuka ada Di Resep saya sebelumnya; Pempek Palembang Ikan Tenggiri.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(130, 4, 'Ikan Kembung Sarden', 'Sajian ikan nikmat: Ikan Kembung Sarden yang mudah dibuat.', '[\"1/2 kg ikan kembung segar\", \"1 biji tomat\", \"6 siung cabe merah\", \"4 siung bawang merah\", \"2 siung bawang putih\", \"secukupnya Saos, sasa, garam, gula\"]', '[\"Bersihkan ikan, kemudian potong sesuai selera.\", \"Haluskan semua bumbu kasar. Tomat iris saja.\", \"Tumis bumbu yang sudah dihaluskan, masukkan tomat.\", \"Masukkan ikan, tambahkan air hingga ikan tenggelam.\", \"Tambahkan saos, sasa, gula, garam secukupnya.\", \"Tunggu sampai mendidih pertama, cicipi kuah kalau sudah pas, kecilkan api kompor. Tunggu hingga ikan tidak tenggelam lagi.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(131, 2, 'Salmon panggang oven dengan bayam dan jagung mashed potatoes', 'Nikmati kelezatan Salmon panggang oven dengan bayam dan jagung mashed potatoes dengan resep sederhana ini.', '[\"120 gr salmon\", \"1 kentang ukuran sedang\", \"Bayam (secukupnya)\", \"Jagung butir (secukupnya)\", \"100 ml susu putih lowfat\", \"Untuk bumbu :\", \"7 butir bawang putih\", \"2 butir bawang merah\", \"1 cabai\", \"1 sedok teh garam\"]', '[\"Rendam salmon ke dalam air yg dicampur dengan sedikit bawang putih tumbuk dan 1/2 jeruk lemon\", \"Tumbuk semua bahan bumbu, tiriskan. 1/2 bumbu untuk mashed potato dan sisanya untuk salmon\", \"Untuk bayam jagung mashed pototoes: Rebus kentang, jagung dan bayam lalu tiriskan. Lalu ulek sesuai selera mau lembut atau lebih kasar.\", \"Panaskan susu, masukan 1/2 bumbu (tambahkan garam dan sedikit msg kalau lagi engga diet ya :p) lalu campuran mashed potato aduk rata sampai mengental. Tiriskan.\", \"Untuk salmon : Oleskan salmon dengan 1/2 bumbu dan sedikit olive oil lalu bungkus pada aluminum foil. Panggang selama kurang lebih 30 menit 200’c.\", \"Hidangkan salmon dengan mashed potatoes..... Selamat menikmati\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(132, 4, 'Asam padeh (asam pedas)patin tahu', 'Nikmati kelezatan Asam padeh (asam pedas)patin tahu dengan resep sederhana ini.', '[\"Ikan patin 1 ekor potong jd 6 bagian atau sesuai selera\", \"Tahu sutra potong sesuai selera\", \"Lengkuas 2cm geprek\", \"Sereh 1 bh geprek\", \"Cabe giling halus lebkur 3 sendok makan atau sesuai selera\", \"Saya pke cabe giling dr padang udah jelas pedas g perlu rawit lg\", \"1 lembar Daun salam\", \"2 lembar Daun jeruk\", \"1 bh Jeruk nipis\", \"secukupnya Garam\", \"1 bh Asam kandis\", \"2 gelas air\", \"Bumbu halus :\", \"5 siung Bawang merah\", \"3 siung Bawang putih\", \"2 cm Jahe\", \"3 bh Kemiri\", \"Rawit bwt nmbah padas kalo pke cabe kriting jawa\"]', '[\"Cuci ikan patin lalu lumuri dg jeruk nipis dan garam lebkur 15 menit lalu bilas kembali\", \"Masak bumbu halus yang telah dberi air dan masukkan sereh lengkuas daun salam dan daun jeruk,tunggu hingga mndidih\", \"Lalu masukkan ikan patin masak sebentar dan masukkan tahu\", \"Lalu masukkan asam kandis dan garam\", \"Tunggu kuah agak kental, cicipi rasa, kalau kurang pedas bs tmbah cabe dan masak sbntar\", \"Jangan sering di aduk ya, tar patin nya bs ancur\", \"Setelah matang kluarkan asam kandis agar kuah tdk trlalu asam atw jd pahit\", \"Siap dihidangkan dan dnikmati 😉\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(133, 2, 'Pindang ikan patin', 'Resep Pindang ikan patin ala rumahan yang dijamin menggugah selera.', '[\"1 kl ikan patin\", \"3 gelas air\", \"5 cabe merah\", \"2 lembar daun salam\", \"1 ibujari kunyit\", \"1 ibujari jahe\", \"secukupnya Laos\", \"2 serai\", \"2 tomat merah\", \"2 ikat daun kemangi\", \"4 siung bawang putih\", \"4 siung bawang merah\", \"sesuai selera Garam,gula putih\"]', '[\"Bersihkan ikan patin dipotong2\", \"Haluskan semua bumbu cabe, bawang merah putih, kunyit, jahe,\", \"Masak air sampai mendidih masukan bumbu halus,masukan ikan patin\", \"Masukan daun salam, serai laos digeprek, tomat dibelah jadi 4 masukan semua, tambah garam dan gula penyedap rasa\", \"Tes rasa..... Jika sudah enak dilidah masing2 masukan daun kemangi sebwntar saja lalu angkat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(134, 4, 'Patin Masak Kuning Belimbing Wuluh', 'Cara membuat Patin Masak Kuning Belimbing Wuluh yang enak dan praktis untuk keluarga.', '[\"1 ekor ikan patin\", \"5 buah belimbing wuluh\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"3 buah kemiri\", \"1 buah jeruk nipis\", \"10 buah cabe rawit\", \"1 buah cabe merah\", \"1 buah tomat\", \"2 batang Serai digeprek\", \"1 buah laos digeprek\", \"1 cm kunyit\", \"1 cm jahe\", \"2 lembar daun salam\", \"3 lembar daun jeruk\", \"secukupnya Garam\", \"secukupnya Gula\", \"secukupnya Penyedap rasa\", \"secukupnya Merica\", \"secukupnya Air\"]', '[\"Cuci bersih ikan patin dan potong dalam beberapa bagian. Lumuri dengan jeruk dan diamkan beberapa saat.\", \"Bumbui ikan patin dengan garam dan merica. Sisihkan agar bumbu meresap. Lalu goreng sampai matang.\", \"Blender : bawang merah, bawang putih, cabe rawit, cabe merah, kemiri, kunyit, jahe, tomat dan tambahkan sedikit air.\", \"Tumis bumbu halus dengan minyak secukupnya sampai harum. Tambahkan laos, serai, lengkuas, daun jeruk, daun salam, dan belimbing wuluh. Tambahkan air dan biarkan hingga mendidih.\", \"Masukkan ikan patin yang telah digoreng. Tambahkan gula dan penyedap. Masak hingga bumbu kuning meresap merata.\", \"Siap dihidangkan.\", \"Semoga bermanfaat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(135, 2, 'Pecak bandeng pedes dower ala bunda nay', 'Buat Pecak bandeng pedes dower ala bunda nay yang nikmat dengan langkah-langkah mudah ini.', '[\"2 ekor ikan bandeng\", \"15-20 pc cabe rawit merah\", \"3 siung bawang merah\", \"1 siung bawang putih\", \"Setengah ruas jahe\", \"Penyedap rasa\", \"Gula\", \"5 buah jeruk limo\"]', '[\"Cuci bersih ikan bandung lumuri garam sedikit dan bakar\", \"Haluskan semua bumbu\", \"Tumis bumbu halus hingga harus\", \"Tambahjan sedikit air\", \"Peras jeruk limo\", \"Jika rasa sudah pas angkat bumbu dan siram ke bandeng yg sudah di bakar\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(136, 4, 'Pindang Bandeng', 'Resep praktis Pindang Bandeng yang bisa dicoba di rumah.', '[\"2 kg ikan bandeng (saya pilih yg fresh di pasar)\", \"10 siung bawang merah\", \"4 siung bawang putih\", \"2 batang sereh\", \"3 cm lengkuas\", \"3 cm jahe\", \"5 lembar daun salam\", \"10 sdm kecap manis (bisa disesuaikan selera)\", \"3 sdm air asam jawa kental\", \"1 sdt garam\", \"3 sdt gula pasir\", \"7 rawit merah\", \"1 buah tomat\", \"2 buah jeruk nipis (untuk melumuri ikan)\"]', '[\"Ikan bandeng dipotong 4 bagian, cuci bersih kemudian lumuri dengan jeruk nipis dan garam, sisihkan.\", \"Bakar semua bumbu kecuali daun salam, geprek-geprek semua, masukkan ke panci presto yang sudah diisi air, tambahkan semua bumbu kemudian koreksi rasa, baru masukkan bandengnya.(tomat dan rawit saya masukkan setelah matang ya)tidak ikut dipresto.\", \"Untuk mendapatkan tulang lunak waktu masing-masing panci presto dapat berbeda-beda, saya membutuhkan 2 jam, dari presto mendesis.\", \"Untuk yang tidak menggunakan panci presto cukup sampai bumbu meresap saja ke ikan ya, ditandai dengan daging ikan yang menghitam karena kecap...selamat mencoba😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(137, 3, 'Pepaya tongkol santan bumbu rajang', 'Buat Pepaya tongkol santan bumbu rajang yang nikmat dengan langkah-langkah mudah ini.', '[\"150 gr pepaya muda parut (cuci dgn sedikit garem tiriskan)\", \"Ikan tongkol (me pake yg sudah difillet dalam mika)\", \"1/2 santan kara\", \"Bumbu rajang (iris):\", \"10 cabe hijau keriting\", \"3 cabe merah keriting\", \"7 bawang merah\", \"4 bawang putih\", \"2 cm lengkuas\", \"1/2 sdm saori tiram\", \"Secukupnya gula putih\", \"Secukupnya royco ayam\", \"10 irisan gula merah\", \"secukupnya Air putih\", \"secukupnya Minyak goreng\"]', '[\"Belah jd 2 ikan tongkol lalu goreng sebentar angkat sisihkan\", \"Tumis semua bumbu rajang (iris hingga sedikit layu masukkan pepaya parut, garem,gula pasir,gula merah,saori tiram,royco ayam aduk hingga rata tercampur tambahkan air menutupi pepaya tes rasa tggu hingga mendidih masukkan santan kara dan ikan tongkol nya. Aduk rata biarkan hingga sedikit berkurang airnya.\", \"Bila pepaya sdh terlihat layu angkat pindah kepiring saji\", \"Siap dihidangkan. Met mencoba ya\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(138, 4, 'Klotok cabe ijo', 'Resep Klotok cabe ijo ala rumahan yang dijamin menggugah selera.', '[\"3 ekor ikan klotok (goreng lalu suwir)\", \"1/2 papan tempe iris kotak2 kecil (goreng sisihkan)\", \"2 siung Bawang putih  (iris kasar)\", \"5 siung bawang merah (iris kasar)\", \"5 buah cabe ijo\", \"Segenggam cabai rawit (doyan pedes)\", \"Rajarasa\", \"Kecap manis\", \"Royco\"]', '[\"Tumis semua bumbu hingga layu tambahkan rajarasa, kecap manis, royco beri air sedikit tes rasa\", \"Setelah rasa pas masukkan tempe oseng hingga air sedikit menyusut lalu masukan klotok\", \"Angkat dan Siap disandingkan dng nasi hangat bunda 😄\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(139, 4, 'Asem Asem Patin', 'Buat Asem Asem Patin yang nikmat dengan langkah-langkah mudah ini.', '[\"1 ekor ikan patin\", \"2 buah tomat hijau(potong dadu)\", \"1 buah tomat merah(potong dadu)\", \"1 genggam rawit merah(utuh)\", \"5 buah cabai merah(iris serong)\", \"1 sdm asam mateng/ asam jawa\", \"1 buah jeruk nipis\", \"secukupnya Daun kemangi\", \"Bumbu halus:\", \"1 ruas kunyit\", \"5 siung bawang merah\", \"2 siung bawang putih\", \"1 ruas jahe (geprek)\", \"1 btg sereh (geprek)\", \"2 lbr daun jeruk\", \"2 lbr daun salam\", \"1 1/2 ltr air\", \"secukupnya Minyak\", \"secukupnya Gula dan garam\", \"Penyedap(optional)\"]', '[\"Potong ikan sesuai selera. Cuci bersih lalu kucuri dgn jeruk nipis diamkan 5 menit, goreng setengah matang,tiriskan.\", \"Tumis bumbu halus masukan sereh,jahe,daun jeruk,daun salam,garam,gula,penyedap.tunggu sampai aromanya keluar.\", \"Panaskan air masukan bumbu yg sdh di tumis,ikan,cabai merah iris,asam,cabai rawit utuh dan matikan kompor masukan tomat merah,tomat hijau dan daun kemangi.\", \"Selamat mencoba, sajikan selagi hangat bunn..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(140, 4, 'Sop ikan tenggiri', 'Sop ikan tenggiri dengan cita rasa segar khas laut.', '[\"500 gr ikan tenggiri\", \"Daun bawang\", \"Daun sop\", \"Bawang goreng\", \"Bumbu yg dihaluskan\", \"1 sdt lada halus\", \"3 siung bawang putih..\"]', '[\"Bersihkan ikan, sisihkan lumuri dengan jeruk nipis\", \"Tumis bumbu halus\", \"Masak air 500 ml samppai mendidih, masukan bumbu, masukan ikan\", \"Setelah matang sajikan dengan daun sop, daun bawang, bawang goreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(141, 2, 'Crispy Dory Steak', 'Cara membuat Crispy Dory Steak yang enak dan praktis untuk keluarga.', '[\"Steak:\", \"2 buah fillet ikan dori\", \"secukupnya Garam\", \"secukupnya Lada\", \"1 buah jeruk nipis\", \"Tepung bumbu qreezpy\", \"Minyak untuk menggoreng\", \"150 ml air untuk baluran ikan\", \"Saute vegetables dan kentang:\", \"1 buah jagung\", \"1 buah wortel\", \"10 buah buncis\", \"1/2 buah bawang bombay\", \"2 siung bawang putih\", \"Gravy atau saus:\", \"2 siung bawang putih\", \"1/2 buah bawang bombay\", \"2 sdm kecap asin\", \"2 sdm tepung terigu\", \"400 ml air kaldu ayam\", \"Sejumput lada hitam\", \"Secukupnya garam\"]', '[\"Dory steak: peras jeruk nipis pada fillet dori untuk hilangkan bau amis.\", \"Bubuhkan sedikit lada dan garam pada dua sisi fillet yang sudah pada posisi suhu ruangan (bukan fillet beki). Diamkan 10 menit.\", \"Buat adonan basah dari tepung qreezpy. Balurkan pada ikan dori.\", \"Setelah dibalur dengan adonan basah, lapisi dengan tepung kering dan cubit cubit untuk menghasilkan tekstur krispi.\", \"Goreng dengan minyak hinggak coklat keemasan.\", \"Saute vegetables: tumis bawang bombay kemudian bawang putih. Masukkan sayuran dan tambahkan lada serta garam. Kita tidak perlu terlalu menonjolkan rasa pada sayur. Cukup rasa tipis supaya tidak mengalahkan rasa ikan dan gravy nya.\", \"Kupas kentang dan rebus hingga matang. Potongan kentang sesuai selera. Jika ingin digoreng pun optional. Saya rebus kentang dalam menu.\", \"Gravy: tumis bawang bombay dan bawang putih dengan sedikit minyak. Setelah wangi masukkan tepung terigu dan aduk rata. Masukkan kaldu dan bumbui dengan lada hitam juga garam. Cek rasa sambil aduk terus hingga mendapat kekentalan gravy yang diinginkan.\", \"Sajikan crispy dory steak dengan, kentang, sayuran tumis dan gravy. Saus sambal bolen ditambahkan (optional).\", \"Selamat mencoba.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(142, 2, 'Tenggiri kuah asam pedas', 'Resep Tenggiri kuah asam pedas yang lezat dan mudah dibuat di rumah.', '[\"500 gram ikan tenggiri, potong bulat\", \"1 buah jeruk nipis, ambil airnya\", \"2 buah tomat hijau, potong kasar\", \"2 batang serai, memarkan\", \"3 cm jahe, memarkan\", \"4 cm kunyit, bakar lalu memarkan\", \"5 buah belimbing wuluh, belah 2\", \"10 buah cabe rawit utuh\", \"5 buah  cabe merah keriting, iris serong\", \"10 buah cabe rawit, iris serong\", \"1 batang daun bawang, potong kasar\", \"750 ml air\", \"secukupnya Garam, gula & lada bubuk\", \"Bumbu iris tipis:\", \"6 butir bawang merah\", \"3 siung bawang putih\"]', '[\"Cuci bersih ikan, lumuri air jeruk nipis, diamkan 15 menit, cuci kembali sampai bersih, sisihkan.\", \"Rebus air dalam panci hingga mendidih.\", \"Tumis bumbu sampai wangi, masukkan cabe, daun jeruk, kunyit, serai & jahe, aduk2 sampai layu, tuang tumisan bumbu kedalam panci berisi air mendidih, bumbui garam & gula, masukkan ikan, masak sampai mendidih kembali.\", \"Masukkan belimbing wuluh & cabe rawit utuh, masak sampai bumbu meresap, tes rasa, sebelum diangkat masukkan irisan tomat hijau, matikan api, taburi daun bawang sajikan. (Boleh taburi daun kemangi bila suka)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(143, 2, 'Tongkol suwir (pampis) asem manis', 'Cara membuat Tongkol suwir (pampis) asem manis yang enak dan praktis untuk keluarga.', '[\"2 ikan tongkol basah\", \"6 bawang merah\", \"2 bawang putih\", \"5 cabe merah besar\", \"2 lbr daun salam\", \"1 bh jeruk nipis\", \"Gula merah, bumbu penyedap\", \"secukupnya Air\"]', '[\"Cuci bersih ikan tongkol, beri perasan jeruk nipis, diamkan 15 menit (biar terasa asemnya) lalu goreng dan disuwir\", \"Iris bawang merah, bawang putih, cabe\", \"Tumis bumbu iris dan daun salam smp harum. masukkan suwiran ikan, gula merah, bumbu penyedap, air secukupnya supaya bumbu meresap (jng terlalu byk air)\", \"Cek rasa... Selesai\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(144, 2, 'Guleli pala nila no kolestrol', 'Resep Guleli pala nila no kolestrol ala rumahan yang dijamin menggugah selera.', '[\"3 kepala ikan nila (klw mw buang mulut,sy sih dibuang)\", \"1 bh daun bawang (potong sesuai selera)\", \"3 buah tomat (belah 2 aja)\", \"1 buah asam potong\", \"2 buah sre (digeprek aja ya bun)\", \"15 buah cabe rawit (jgn diapa2in)\", \"Bahan diblender:\", \"20 bh bawang merah\", \"8 bh bawang putih\", \"2 bh kunyit\", \"1 ruas jari jahe\", \"1 sendok teh ketumbar\", \"Stengah sendok teh merica bulat\", \"5 buah kemiri\", \"2 bh cabe merah\", \"secukupnya Minyak goreng\", \"secukupnya Garam\", \"secukupnya Air\"]', '[\"Tumis bumbu yg di blender sampai harum,mskkan sre\", \"Stelah harum mskkan 1 cangkir kecil air,tunggu sampai mendidih2,mskkan tomat dan asam potong,kemudian kepala ikan nila,tunggu sampai mendidih lagi lalu tambahkan 3 gelas @ir agar bumbu meresap\", \"Stelah mendidih2 mskkan garam secukupnya,stelah tu cabe rawit taburi dr atasnya sj\", \"Masak sampai air berkurang n jgn lp dirasa2 ya bun, biar cocok dgn selera\", \"Tunggu 5 mntan,angkat dan sajikan di piring saji dengan ditaburi daun bawang dr atasnya trus dgn kuahnya lagi\", \"Slamat mencoba bunda☺\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(145, 2, 'Lele bumbu kuning', 'Buat Lele bumbu kuning yang nikmat dengan langkah-langkah mudah ini.', '[\"2 ekor lele\", \"4 buah cabe merah (tingkat pedas sesuai selera)\", \"5 siung bawang merah\", \"2 siung bawang putih\", \"Ketumbar bubuk (secukupnya)\", \"5 buah Kemiri\", \"2 lembar daun jeruk\", \"Kunyit\", \"Lengkuas\", \"Santan (Saya pakai santan bubuk)\", \"Air\", \"Minyak goreng\"]', '[\"Bersihkan lele, lumuri garam, diamkan sebentar, lalu digoreng\", \"Haluskan bawang merah, bawang putih, kunyit, kemiri, garam, ketumbar, dan daun jeruk\", \"Uleg kasar cabe merah, Lengkuas jangan sampai terlalu halus.\", \"Panaskan sedikit minyak di wajan, tumis bumbu yang sudah dihaluskan sampai wangi\", \"Masukkan air Dan lele yang sudah digoreng. Masukkan santan sedikit Demi sedikit sambil Terus di aduk\", \"Tunggu air sedikit menyusut agar bumbh menyerap.\", \"Siap disajikan bersama nasi selagi panas\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(146, 2, 'Mujair saus pedas manis', 'Sajian Mujair saus pedas manis yang praktis dan lezat untuk dinikmati bersama.', '[\"1 ekor ikan mujair sedang\", \"2 siung bawang putih\", \"1 buah bawang bombay\", \"1 batang serai\", \"1 buah tomat besar\", \"2 batang daun bawang\", \"5 buah cabai rawit\", \"3 buah cabai merah\", \"2 sdm saus tomat\", \"1 sdm saus tiram\", \"secukupnya Garam\", \"secukupnya Gula\"]', '[\"Siapkan ikan mujair yang telah dicuci bersih dan dilumuri jeruk nipis. Lalu goreng diminyak panas sampai matang. Tiriskan.\", \"Potong2 bawang bombay, bawang putih, serai, cabai. Tumis diminyak panas, setelah harum masukkan potongan cabai dan tomat. Masak sampai tomat lunak dan tambahkan saus tomat dan saus tiram.\", \"Koreksi rasa menggunakan garam dan gula. Lalu potong2 daun bawang dan masukkan.\", \"Letakan ikan mujair diatas piring lalu tuangkan saus pedas manis diatasnya\", \"Siap disantap mantappp\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(147, 4, 'Tongkol tahu kuah santan', 'Resep Tongkol tahu kuah santan yang lezat dan mudah dibuat di rumah.', '[\"4 ikan tongkol pisahkan tulangnya dan goreng\", \"1 bungkus santan kara\", \"1 kotak tahu\", \"4 buah cabe hijau iris\", \"Bumbu halus\", \"4 siung bawang putih\", \"6 siung bawang merah\", \"4 buah cabe besar\", \"6 buah cabe rawit\", \"1 ruas kunyit\", \"Bumbu pelengkap\", \"1 ruas lengkuas\", \"2 lembar daun jeru\", \"2 lembar daun salam\", \"1 sdt garam\", \"Merica,penyedap rasa,asam jawa secukup nya\", \"2 gelas blimbing air\"]', '[\"Tumis bumbu halus tambahkan sedikit asam jawa dan masukan bumbu pelengkap\", \"Masukan santan instan dan air masukan potongan tahu dan tongkol yg sudah digoreng masukan irisan cabe hijau\", \"Aduk hingga mendidih dan masukan garam merica penyedap rasa tes rasa siap disajikan😀\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(148, 2, 'Lele sambal simpel', 'Resep Lele sambal simpel yang lezat dan mudah dibuat di rumah.', '[\"1/2 kg lele segar\", \"5 buah cabai merah kriting\", \"2 buah cabai rawit\", \"2 buah tomat\", \"2 bungkus terasi Abc\", \"4 butir kemiri\", \"5 siung bawang putih\", \"5 siung bawang merah\", \"Garam\", \"Gula pasir\", \"Penyedap (opsional)\", \"Air\"]', '[\"Goreng lele hingga kering\", \"Haluskan semua bumbu : cabai, bawang putih, bawang merah, kemiri, terasi, garam, penyedap, tomat, gula pasir.\", \"Tumis bumbu halus setelah harum masukkan lele dan beri sedikit air, tunggu hingga bumbu meresap.\", \"Lele sambal siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(149, 4, 'Dorang bumbu woku', 'Resep Dorang bumbu woku yang lezat dan mudah dibuat di rumah.', '[\"3/4 kg ikan dorang(isi 7 ekor,setelapak tangan@ekornya)\", \"Jeruk nipis\", \"Bumbu halus:\", \"10 siung bawang merah\", \"5 siung bawang putih\", \"3 butir kemiri sangrai\", \"3 cm jahe\", \"3 cm kunyit\", \"2 buah cabe merah buang biji(sesuai slera y bun,ini u/bocah 😊)\", \"(Bs dtmbh caberawit)saya skip\", \"Bumbu geprek /rajang:\", \"1 btg sereh\", \"4 lmbr daun jeruk buang tengahnyaa\", \"4 lmbr daun salam\", \"Tambahan :\", \"1 ikat kemangi\", \"1 bh daun bawang rajang kasar\", \"1 buah tomat iris dadu\", \"Garam\", \"Gula\", \"sedikit penyedap\", \"Air\", \"Minyak untk menumis\"]', '[\"Bersihan ikan,buang kotoran ikan,di seset biar bumbu bs mresap,\", \"Lumuri dg air jeruk nipis,diamkan 15-30menit,sambil menyiapkan bahan\", \"Blendr bumbu halus,tambhkan minyak untk memblendrnya\", \"Goreng ikan stgah matang(tips agar tidak meledak2:siapkan wajan yg sudah dberi garam dan minyak tlbh dahulu,bru nyalakan kmpor),sisihkan\", \"TUmis bumbu yg sudah dhaluskan,sampai harum\", \"Masukkan bumbu geprek/rajang,tumis sampe harum\", \"Tambhkan air,diamkan sampe meletup2,lalu masukan ikan\", \"Tambhkan,gula,garam,sdkit penyedap,koreksi rasa\", \"Masukkan bahan tambahan,diamkan sampe matang dan berbau harum..\", \"Selesai,slamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(150, 2, 'Ikan gabus asem pedas ala mamais', 'Sajian ikan nikmat: Ikan gabus asem pedas ala mamais yang mudah dibuat.', '[\"2 ekor ikan kembung besar cuci bersih kucuri jeruk nipis..goreng sebentar\", \"4 blok tahu potong kotak kecil goreng matang\", \"1 ruas laos geprek\", \"1 sere geprek bag putih\", \"1 cabe merah besar iris serong\", \"5 cabe rawit iris tipis2 (biar kerasa pedesnya)\", \"2 tomat sedang iris\", \"1 sdt air asam jawa / pake blimbing wuluh bisa (gpape gapapa-cuma kecutnya agak kurang)\", \"1 sdm saus tiram\", \"1/2 sdt garam\", \"Sejumput gula\", \"1/4 sdt lada bubuk\", \"Kaldu bubuk\", \"150 ml air\", \"Bumbu halus :\", \"2 sdm bumbu dasar kuning (sudah pernah upload - search aja bumbu kuning di profile saya)\"]', '[\"Tumis bumbu halus..bareng ama bawang merah, laos, sere, harum..masukkan cabe2an. Aduk rata..masukkan ikan..tahu, tomat..aduk rata..tuang air..masukkan saus tiram..bumbui garam gula lada bubuk kaldu bubuk..tes rasa..tunggu sampe air sat dan bumbu meresap..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(151, 3, 'Pesmol gembung (non msg)', 'Pesmol gembung (non msg) - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1/2 kg ikan gembung besar\", \"1/4 kg minyak goreng\", \"bumbu halus:\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"2 cm jahe\", \"1 butir kemiri\", \"1 sdm kunyit bubuk\", \"garam\", \"gula\", \"1 batang sereh di geprek\", \"15 butir cabe rawit utuh\", \"1/4 butir kelapa parut\"]', '[\"Bersihkan ikan,,potong jadi dua,,lalu goreng kering\", \"Ulek semua bumbu halus...tumis dgn sedikit minyak.lalu tambahkan sereh,gula,garam,cabe rawit utuh\", \"Masukan santen yg 1 x perasan saja ya,,supaya kental bun.\", \"Koreksi rasa,masukkan ikan nyaa..msaak sampai agak sat yaaa..lalu angkat..siaap di santap.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(152, 4, 'Kembung masak tauco', 'Buat Kembung masak tauco yang nikmat dengan langkah-langkah mudah ini.', '[\"3 ekor ikan kembung belah 2 lalu goreng\", \"5 bawang merah iris\", \"3 bawang putih iris\", \"4 cabe ijo besar iris serong\", \"5 cabe merah keriting iris serong\", \"5 cabe rawit merah iris serong\", \"1 papan pete\", \"Daun salam\", \"Sereh\", \"Lengkuas\", \"Jahe\", \"50-100 ml air\", \"2 sdm tauco\", \"sedikit Gula dan garam\", \"1/2 buah tomat\"]', '[\"Panaskan minyak, tumis semua bumbu2 hingga layu dan harum\", \"Tambahkan tauco, air, gula dan garam aduk rata\", \"Masukkan ikan kembung yang sudah digoreng, tomat dan pete aduk pelan hingga tercampur rata\", \"Cek rasa, sajikan dengan nasi hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(153, 2, 'Ikan Lele Goreng Balado', 'Resep Ikan Lele Goreng Balado ala rumahan yang dijamin menggugah selera.', '[\"2 ekor ikan lele jumbo\", \"8 siung bawang merah\", \"6 siung bawang putih\", \"sesuai selera Cabe merah keriting\", \"sesuai selera Cabe rawit hijau\", \"1 ruas kunyit\", \"1 ruas jahe\", \"2 lembar daun jeruk\", \"Garam\", \"Gula\", \"secukupnya Air\", \"Minyak goreng\", \"1 buah tomat\"]', '[\"Cuci bersih ikan lele, lalu potong sesuai selera\", \"Beri garam ikan lele (dikoleh koleh)\", \"Goreng ikan lele sampai agak mengering\", \"Halus kan bumbu2 kecuali daun jeruk dan tomat\", \"Tumis bumbu halus sampai harum, masukkan tomat yg dipotong sesuai selera lalu masukkan daun jeruk\", \"Tumis sampai matang lalu tambahkan gula garam dan sedikit air\", \"Setelah agak surut, masukkan ikan dan aduk sampai rata, cek rasa lalu matikan kompor setelah bumbu meresap\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(154, 2, 'Ikan nila goreng sambal dabu dabu', 'Cara membuat Ikan nila goreng sambal dabu dabu yang enak dan praktis untuk keluarga.', '[\"1 ekor ikan nila ukuran kecil\", \"Bahan halus untuk ikan :\", \"4 siung bawang putih\", \"1 sdm kunyit bubuk\", \"1 sdt ketumbar bubuk\", \"Secukupnya garam\", \"Secukupnya minyak goreng\", \"Bahan sambal dabu dabu :\", \"20 biji cabe, iris tipis\", \"2 buah tomat, iris tipis\", \"4 siung bawang merah, iris tipis\", \"5 sdm minyak kelapa, iris tipis\", \"1 buah jeruk limau\", \"Secukupnya garam\"]', '[\"Bersihkan ikan dan lumuri dgn jeruk\", \"Uleg smua bumbu halus, kecuali minyak\", \"Kmudian lumuri ikan dgn bumbu halus tadi + minyak goreng dikit. Diamkan beberapa menit agar menyerap\", \"Untuk sambal dabu dabu campur smua irisan kmudian tambah garam dan minyak kelapa\", \"Goreng ikan, kemudian ditaburi sambal dabu dabu. Jadi deh\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(155, 3, 'Kembung Kuah', 'Resep Kembung Kuah ala rumahan yang dijamin menggugah selera.', '[\"2 ekor ikan kembung (saya potong jd 2)\", \"Bumbu Halus:\", \"2 siung bawang putih\", \"4 siung bawang merah\", \"Pelengkap:\", \"2 cm lengkuas geprek\", \"2 cm kunyit geprek\", \"2 cm kencur geprek\", \"3 biji asem jawa\", \"3 lembar daun salam\", \"1 batang sereh geprek\", \"Sejumput ketumbar\", \"Gula, Garam\", \"Peresan jeruk nipis (buat rendam ikan sebentar?\"]', '[\"Rendam ikan kembung dgn perasan jeruk nipis untuk menghilangkan bau amis. Kasih garam dikit. Lalu goreng sebentar.\", \"Tumis bumbu halus bersama pelengkap sampai wangi. Masukan ikan kembung. Tumis sebentar, tambahkan air matang.\", \"Masak sampai mendidih. Tambahkan gula garam, koreksi rasa. Selesai deh 😉\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(156, 3, 'Mangut lele asam pedas', 'Mangut lele asam pedas - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1/2 kg lele ukuran kecil\", \"Secukupnya minyak untuk menggoreng dan menumis\", \"2 gelas air\", \"1 bungkus santan kara\", \"Bumbu lele goreng:\", \"3 bawang putih\", \"1/2 sdt ketumbar\", \"Seruas jari kunyit\", \"Garam\", \"Bumbu halus:\", \"8 bawang merah\", \"6 bawang putih\", \"15 cabe rawit\", \"5 cabe merah kriting\", \"Seruas jari jahe\", \"Seruas jari kunyit\", \"2 biji kemiri\", \"1/2 sdt mrica(aku pake mrica asli bkn bubuk)\", \"1/2 sdt garam\", \"1 sdt gula pasir\", \"Pelengkap:\", \"Sejempol lengkuas geprek\", \"2 helai daun jeruk\", \"2 helai daun salam\", \"1 batang serai geprek\", \"Penyedap(royco)\", \"Seiris jeruk nipis\"]', '[\"Bersihkan lele\", \"Uleg bumbu utk menggoreng lele, lalu lumurkan ke lele dan diamkan beberapa saat\", \"Goreng lele setengah matang\", \"Sambil menunggu semua lele digoreng, siapkan bumbu halus, lalu uleg atau blender\", \"Kalau sudah siap lele dan bumbu, siapkan wajan beri 2sdm minyak untuk menumis\", \"Tumis bumbu dgn api kecil, hingga daun\\\" layu dan berbau harum\", \"Jika dirasa sudah matang, masukan lele lalu aduk\\\" hingga bumbu merata\", \"Lalu tambahkan 2gelas air, ungkep hingga mendidih agar bumbu meresap\", \"Jika sudah mendidih, tambahkan penyedap dan jerus nipis\", \"Lalu Masukkan santan kara, aduk\\\" hingga merata tunggu sampai mendidih\", \"Jika sudah mendidih tambahkan kemangi, lalu koreksi rasa\", \"Jika sudah pas, angkat dan sajikan untuk keluarga tercinta\", \"Selamat memasak semuanya😘\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(157, 3, 'Pizza sardin', 'Pizza sardin dengan cita rasa segar khas laut.', '[\"Bahan doh\", \"1 cup terigu\", \"80 ml susu hangat\", \"1 tsp yiest\", \"1 tsp gula\", \"1/2 tsp yiest\", \"1/2 tsp gula\", \"1/4 tsp garam\", \"3 tbsp minyak sayur\", \"Bahan sardin\", \"3 biji ikan sardin pisahkan dari sos nya\", \"1/2 biji bawang holand cincang\", \"bumbu halus\", \"2 bawang putih\", \"1 bawang merah\", \"2 biji cabe rawit\", \"garam dan gula\", \"Bahan tambahan\", \"3 tbsp sos tomat\", \"mozarela chees secukuo nya\"]', '[\"Kita buat bahan doh.satukan susu hangat dan yiest beri secubit gula dan terigu aduk rata biarkan aktif.satukan tepung gula garam aduk rata masukan bancuhan yiest aduk rata masukan minyak uli sampai kalis rehatkan 30 menit tutup dengan kain bersih ya\", \"Kita buat ikan sardin. pisahkan ikan dari duri dan carik carik.tumis bumbu halus sampai wangi masukan bawang holand aduk rata masukan ikan aduk rata koreksi rasa bila dah ok matikan api\", \"Siapkan loyang olesi sedikit minyak pipihkan adonan di loyang sampai rata dan tusuk tusuk dengan garfu sampai rata oven dgan suhu 180 - 20 menit\", \"Keluarkan adonan dan olesi sos tomat beri ikan sardin dan tabur keju mozarela ikut selera bakar hingga matang\", \"Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(158, 2, 'Kepala Ikan Bawal Kuah Kuning', 'Nikmati kelezatan Kepala Ikan Bawal Kuah Kuning dengan resep sederhana ini.', '[\"2 kepala ikan bawal ukuran besar\", \"1 bh jeruk nipis\", \"2 bh tomat hijau, iris\", \"5 bh cabe rawit, iris\", \"1 batang serai, memarkan\", \"Secukupnya air\", \"Bumbu Halus :\", \"5 butir bawang merah\", \"3 siung bawang putih\", \"1 cm jahe\", \"1 cm kunyit\", \"1 butir kemiri\", \"Secukupnya garam, gula, kaldu bubuk\"]', '[\"Cuci bersih ikan, kucuri air jeruk nipis, diamkan sesaat (saya skip step ini)\", \"Haluskan semua bahan bumbu halus. Panaskan minyak, lalu tumis bumbu halus hingga harum. Masukkan air dan semua bahan lain. Tambahkan garam, gula, kaldu bubuk. Tunggu mendidih, koreksi rasa. Selesai\", \"Sajikan 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(159, 3, 'Ikan Nila Goreng Saos Padang', 'Resep praktis Ikan Nila Goreng Saos Padang yang bisa dicoba di rumah.', '[\"2 ekor ikan nila agk besar\", \"1 bh jeruk nipis utk kucuran ikan\", \"I bks bumbu racik ikan goreng\", \"1 siung bawang bombay iris tipis\", \"2 lmbr daun jeruk\", \"8 siung bawang merah iris tipis\", \"8 siung bawang putih iris tipis\", \"10 bh cabe merah kriting iris tipis\", \"7 bh cabe rawit iris tipis\", \"1 bh daun bawang iris tipis jg\", \"1 sdt masako campur air hangat 1 gelas kecil\", \"1 stengah sdm saos tiram\", \"4 sdm saos sambal\", \"2 sdm saos tomat\", \"Secukupny margarin\", \"Secukupny minyak zaitun klo ada\"]', '[\"Cuci ikan stelah bersih lumuri perasan jeruk nipis dan bumbu racik ikan goreng, diamkan 10 mnt, lalu goreng hingga matang, tiriskan\", \"Iris smua bumbu, bawang bombay, bawang merah n putih, cabe rawit n cabe merah n daun bawangnya\", \"Siapkan wajan n margarin, tumis smua bumbu iris tadi, aduk hingga harum, masukkan air kaldu, saos tiram, saos sambal, saos tomat n beberapa tetes minyak zaitun, aduk terus sampai mendidih n meletup letup.. Koreksi rasa ya bun.. Angkat\", \"Siapkan ikan diatas piring lalu siram dgn saos yg sudah matang tadi.. Siap disajikan bun\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(160, 4, 'Mayo Hot Sarden', 'Resep praktis Mayo Hot Sarden yang bisa dicoba di rumah.', '[\"Bahan Utama\", \"1 kaleng sarden \\\"King Fisher Rasa Saus Sambal\\\"\", \"1 buah kentang iris dadu\", \"1 sdt Mayonaise\", \"1 sdt bon cabe level 15\", \"100 ml air atau secukupnya\", \"5 sdm minyak goreng\", \"1 siung bawang merah, potong halus\", \"1 siung bawang putih, geprek dan potong halus\", \"secukupnya Garam\", \"secukupnya Gula\", \"Bumbu halus\", \"1 slice jahe di potong haluskan\", \"1 slice kunyit di potong haluskan\"]', '[\"Masukkan 5 sdm minyak goreng, dan goreng kentang dadu hingga setengah matang\", \"Kemudian Tambahkan bawang merah,bawang putih serta bumbu halus, tumis hingga harum\", \"Masukkan sarden kaleng, tambahkan air 100 ml atau secukupnya sesuai selera\", \"Tambahkan garam, gula, bon cabe, dan mayonaise\", \"Masak hingga harum dan matang\", \"Angkat dan sajikan dengan toping mayonaise...\", \"Selamat menikmati dan mencoba😁\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(161, 4, 'Suwir tongkol brokoli', 'Resep Suwir tongkol brokoli yang lezat dan mudah dibuat di rumah.', '[\"1 bh brokoli\", \"2 bh ikan pindang tongkol (bisa beli tongkol yg udah potongan)\", \"Bumbu :\", \"1 bh kecil bawang bombay\", \"5 siung bwang putih\", \"4 siung bawang merah\", \"1 bh cabe merah\", \"1 bh tomat\", \"secukupnya Gula\", \"secukupnya Garam\", \"secukupnya Lada\", \"secukupnya Air\"]', '[\"Cuci tongkol terlebih dahulu.\", \"Setelah itu suwir2 tongkol.\", \"Potong2 brokoli\", \"Iris tipis2 bumbu\", \"Siapkan wajan dengan minyaj secukupnya untuk menumis\", \"Masukkan bumbu kedalam wajan untuk ditumis. Tunggu sampai bumbu mengeluarkan aroma\", \"SEtelah itu masukkan tongkol dan beri air secukupnya.. tunggu hingga mendidih.\", \"Lalu masukkan brokoli. Tunggu hingga brokoli agak empuk\", \"Tambahkan gula garam dan air secukupnya.\", \"Selesai\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(162, 3, 'Ikan Mujair Sambal Pete', 'Sajian ikan nikmat: Ikan Mujair Sambal Pete yang mudah dibuat.', '[\"5 ekor ikan mujair, cuci bersih kemudian lumuri jeruk nipis\", \"3 buah terong ungu, potong sesuai selera\", \"2 lembar pete, kupas dan bagi dua\", \"3 lembar daun salam\", \"5 lembar daun jeruk\", \"1 buah tomat merah, potong sesuai selera\", \"1 sdt garam\", \"1 sdt merica\", \"1/4 sdt gula\", \"300 ml air\", \"Bumbu halus:\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"3 biji kemiri\", \"10 biji cabe merah keriting\", \"5 biji cabe rawit merah\"]', '[\"Goreng ikan sampai kering, kemudian sisihkan\", \"Goreng terong, kemudian sisihkan\", \"Panaskan minyak goreng, masukkan pete, daun salam, dan daun jeruk\", \"Masukkan bumbu halus, garam, merica, gula, kemudian tumis sampai berubah warna\", \"Masukkan ikan goreng dan terong, aduk merata\", \"Tambahkan air, aduk sampai air berkurang dan bumbu meresap\", \"Masukkan tomat, kemudian aduk merata\", \"Koreksi rasa sesuai selera\", \"Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(163, 3, 'Ikan kembung balado', 'Sajian ikan nikmat: Ikan kembung balado yang mudah dibuat.', '[\"5 ekor ikan kembung\", \"1 bks bumbu racik ikan goreng\", \"Bumbu halus :\", \"10 biji cabe merah keriting\", \"15 biji cabe rawit merah\", \"7 siung bawang merah\", \"6 siung bawang putih\", \"1 buah tomat merah\", \"2 cm lengkuas (geprek)\", \"1 batang sereh (geprek)\", \"2 lbr daun salam\", \"2 lbr daun jeruk (boleh tdk pakai)\", \"1 bks terasi kecil\", \"secukupnya Garam\", \"Gula\", \"Penyedap\", \"Minyak goreng\", \"20 ml Air\"]', '[\"Cuci bersih ikan,lalu rendam dlm bumbu racik diamkan selama 10 menit\", \"Haluskan semua bumbu, sy uleg. tumis bumbu masukan daun salam, daun jeruk, sereh dan lengkuas jika sudah harum tambahkan air sekitar 20 ml lalu masukan ikan dan tunggu hingga matang.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(164, 3, 'Asem asem lele', 'Nikmati kelezatan Asem asem lele dengan resep sederhana ini.', '[\"1/2 kg lele\", \"4 siung baput\", \"4 siung bamer\", \"Santan\", \"secukupnya Cabe\", \"Air asam jawa\", \"Tomat\"]', '[\"Potong2 lele sesuai keinginan (cari lele yg ukuran agak besar) kemudian goreng setengah matang\", \"Baput, bamer, cabe diiris kecil kemudian tumis sampai harum\", \"Tambahkan air secukupnya kemudian tunggu hingga mendidih (api kecil saja ya)\", \"Masukkan santan sambil diaduk supaya tidak pecah ya bun\", \"Masukkan lele yg sudah digoreng tadi kedalam nya, tutup sebentar supaya bumbu meresap\", \"Tambahkan air asam jawa, masukkan irisan tomat, aduk aduk sebentar\", \"Siap santap!\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(165, 4, 'Tongkol Suwir', 'Resep Tongkol Suwir ala rumahan yang dijamin menggugah selera.', '[\"1 ekor ikan tongkol panggang, suwir-suwir\", \"8 siung bawang merah\", \"2 siung bawang putih\", \"5 buah cabe keriting (optional)\", \"1 siung kunyit\", \"5 lembar daun jeruk,sobek-sobek\", \"1 serai,digeprak\", \"1 cm jahe,digeprak\", \"secukupnya Pandan\", \"secukupnya Garam & gula\", \"Minyak untuk menumis\"]', '[\"Haluskan bawang merah, bawang, kunyit & cabe. Sisihkan.\", \"Panaskan minyak, masukkan bumbu halus & rempah2. Tumis hingga harum.\", \"Masukkan suwiran ikan. Aduk terus hingga kering. Beri garam & gula secukupnya.\", \"Angkat & dinginkan.\", \"Cocok dimakan dengan nasi panas, nasi kuning atau bubur.\", \"Suwiran ini bisa juga ditambahkan saat membuat nasi goreng.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(166, 3, 'Ikan selar bumbu sarden', 'Nikmati kelezatan Ikan selar bumbu sarden dengan resep sederhana ini.', '[\"1/4 ikan selar\", \"3 buah bawang merah\", \"2 buah bawang putih\", \"1 tomat ukuran besar\", \"2 daun salam\", \"2 daun jeruk\", \"Seruas jahe\", \"1 buah serai\", \"1 sdt kaldu ayam non msg\", \"3-4 sdm saos tomat homemade\"]', '[\"Bersihkan ikan dengan jeruk nipis, diamkan sebentar.\", \"Kukus ikan bersama jahe geprek dan daun salam kurleb 5 menit\", \"Uleg semua bahan, bisa juga di blender kemudian tumis semua bahan\", \"Tambahkan saos tomat, beri gula garam, kaldu ayam non msg secukupnya, masukan ikan selar yang sudah di kukus, (jangan bolak balik ikan, entr bisa hancur) tutup sebentar, biarkan bumbu mengental dan meresap\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(167, 4, 'Cekodok sarden', 'Sajian ikan nikmat: Cekodok sarden yang mudah dibuat.', '[\"1 kaleng besar sarden rasa saus tomat\", \"2 cup tepung terigu\", \"1 sdt baking powder\", \"1 telur ayam\", \"1/2 wortel\", \"Secukupnya daun bawang\", \"1 cabe merah\", \"2 bawang putih\", \"2 bawang merah\", \"1 ruas jahe\", \"Gula garam merica\", \"Secukupnya air es\"]', '[\"Rajang halus daun bawang, cabe merah dan wortel\", \"Haluskan duo bawang dan jahe lalu campurkan bersama bahan lainnya.\", \"Tambahkan tepung b powder, telur, sarden (beri sedikit saos dari kaleng) dan bumbu. Aduk bersama air es (harus air dingin ya) hingga cukup kental jangan terlalu encer.\", \"Goreng di api kecil hingga matang.\", \"Biasanya ambil adonan pake tangan lalu dikucurkan ke minyak hingga membentuk bulatan. Namun saya hanya pake sendok.\", \"Setelah matang teksturnya garinh di luar namun terasa kenyel\\\".. Agar lebih terasa ikannya jangan terlalu dihancurkan ya cukup dibejek aja sampe agak kecil.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(168, 4, 'Ikan kembung rica rica', 'Sajian Ikan kembung rica rica yang praktis dan lezat untuk dinikmati bersama.', '[\"5 ekor ikan kembung\", \"Bumbu ikan :\", \"3 bawang putih giling\", \"1 jeruk nipis\", \"2 cm kunyit giling\", \"Garam\", \"Bumbu halus :\", \"2 bawang putih\", \"4 bawang merah\", \"1 cm jahe\", \"1 cm kunyit\", \"1 bawang bombay\", \"iris Cabe rawit\", \"1 daun salam\", \"Daun bawang batangnya saja\", \"Saori saos tiram\"]', '[\"Bumbui ikan dengan jeruk nipis + bumbu halus untuk ikan dan garam. Diamkan 15 menit\", \"Tumis bumbu halus + bawang bombay dan cabe rawit serta daun salam. Masukkan saos tiram dan beri air sedikit. Tambahkan daun bawang. Koreksi rasa\", \"Campurkan ikan dengan sambel rica rica\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(169, 3, 'Ikan Sarden Kalengan', 'Cara membuat Ikan Sarden Kalengan yang enak dan praktis untuk keluarga.', '[\"1 kaleng sarden, buka, kucurin air jeruk kunci / lemon diamkan beberapa saat\", \"3 lbr daun salam, sobek\\\"\", \"3 lbr daun jeruk, sobek\\\"\", \"1 ruas lengkuas, kupas keprek\", \"1 ruas jahe, kupas keprek\", \"1 btg serai ambil putih memarkan\", \"2 siung bawang putih, iris tipis\", \"3 butir bawang merah, iris tipis\", \"2 sdm gula pasir\", \"1/2 sdt garam\", \"1 batang daun bawang iris serong\", \"1 bh cabe merah, buang biji iris serong sy gak pakai\", \"1 btr telor buat dadar rawis kali ini gak pakai, abis\", \"2 sdm minyak\"]', '[\"Panaskan minyak, tumis bawang putih dan merah hingga harum, masukkan serai, salam, lengkuas, daun jeruk tumis hingga layu\", \"Masukkan sarden aduk rata, didihkan\", \"Setelah mendidih tambahkan gula, dan garam, jika menggunakan cabe masukkan, dan didihkan, tabur daun bawang dan telur rawis jika pakai\", \"Angkat, sajikan berteman nasi hangato\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(170, 3, 'Tuna Lapis Oat', 'Resep praktis Tuna Lapis Oat yang bisa dicoba di rumah.', '[\"Tuna potong bulat\", \"secukupnya garam\", \"secukupnya merica\", \"secukupnya pala bubuk\", \"secukupnya garlic powder\", \"jeruk nipis / lemon\", \"pelapis :\", \"secukupnya tepung terigu\", \"1 buah telur yang dikocok\", \"secukupnya Oat\"]', '[\"Lumuri Tuna dengan jeruk nipis/lemon, garam, garlic powder, merica bubuk dan pala bubuk. diamkan kurang lebih setengah jam.\", \"Lalu lapisi dengan tepung terigu, celup kedalam telur, lalu guling-gulingkan tuna diatas Oats\", \"Goreng tuna berbalut tadi pada minyak yang banyak dan panas hingga keemasan. lalu angkat. siap dihidangkan. cocol dengan mayo atau sambal tomat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(171, 4, 'Nila panggang kemangi nyemek,', 'Resep praktis Nila panggang kemangi nyemek, yang bisa dicoba di rumah.', '[\"3 bj Ikan Nila panggang +tahu di goreng dulu\", \"5 siung Bawang putih ,\", \"5 siung Bawang merah\", \"2 bj Lombok besar\", \"10 bj Lombok kecil\", \"5 bj Lombok ijo ale\", \"secukupnya Daun kemangi\", \"Tomat di tirisi\"]', '[\"Semua bumbu di tiris,\", \"Siapin wajan, ksih minyak sedikit\", \"Trs masukkan bumbu yg udah di tiris,\", \"Di gongso krg lbih 5 mnit, tambahin penyedap rasa sesuai selera+gula+garam\", \"Kemudian santan di masukkan, pake kara bs 1 atau 2 bungkus kl suka kental\", \"Kasih air krg lbih 2 gelas\", \"Diamkan krg lbih 10 mnit, smbil di bolak balik ikannya,\", \"Lumayan lunak ikannya, mulai masukkan daun kemangi\", \"Trs matikan kompor, dan siap saji, selamat mencoba 👍👌\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(172, 4, 'Pempek tengiri', 'Pempek tengiri dengan cita rasa segar khas laut.', '[\"300 gr daging tengiri\", \"150 ml air es\", \"1 sdt garam\", \"1/2 sdt gula\", \"3 siung bawang putih\", \"250 gr tepung sagu\"]', '[\"Daging tengiri yg udah digiling campur dgn bawang putih yg udah dihaluskan, tambahkan gula garam.\", \"Tambahkan air sedikit demi sedikit.\", \"Tambahkan tepung sagu sedikit demi sedikit jangan dihabisin untuk olesan pada saat membentuk pempek 😊 Adonan emang lengket ya\", \"Panaskan air setelah mendidih rebus pempek yg udah dibentuk.\", \"Kl udah mengapung biarkan 10 menit agar masak ampe dalemnya ya.\", \"Angkat dan tiriskan, bisa lgs dimakan atau digoreng dl 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(173, 2, 'Nila Goreng Gurih', 'Sajian Nila Goreng Gurih yang praktis dan lezat untuk dinikmati bersama.', '[\"1/2 kg Ikan Nila Segar\", \"Air Jeruk Nipis (1bh)\", \"1/2 scht Lada bubuk\", \"3 siung Bawang Putih geprek\", \"secukupnya Garam\", \"Minyak Goreng\"]', '[\"Bersihkan Ikan Nila belah melalui Punggung ke arah perut jangan putus, seperti bikin ikan asin. Rendam dengan air jeruk nipis selama 5 menit. Bersihkan kemudian beri Lada, garam, bawang aduk rata diamkan kembali 10 menit. Goreng hingga matang, angkat tiriskan.\", \"Hidangkan dengan Sambal kesukaan keluarga.\", \"Berikut lalapannya.. 👍😉\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(174, 3, 'Ikan tongkol masak lemak kemangi', 'Nikmati kelezatan Ikan tongkol masak lemak kemangi dengan resep sederhana ini.', '[\"10 ptg ikan tongkol (sy beli sdh matang)\", \"1 bh santan (sy pakai kara ukuran kecil)\", \"secukupnya Air\", \"Bumbu yg di haluskan :\", \"10 bh cabe merah besar\", \"5 bh bawang merah\", \"3 siung bawang putih\", \"3 bh kemiri\", \"1/2 ruas jari jahe\", \"secukupnya Garam\", \"secukupnya Penyedap rasa\", \"secukupnya Gula pasir\", \"Bumbu pelengkap :\", \"1 btg serai\", \"3 lbr daun salam\", \"1/2 ruas jari lengkuas\", \"secukupnya Cabe rawit\", \"sesuai selera Daun kemangi\"]', '[\"Goreng ikan 1/2 matang\", \"Haluskan bumbu2, kecuali daun salam, serai, lengkuas\", \"Tumis bumbu,masukan daun salam, serai, lengkuas hingga matang\", \"Masukan ikan, santan,cabe rawit dan sdkt air\", \"Masak hingga santan mendidih, saat mau di angkat, masukan daun kemangi\", \"Note : jika tdk suka pedas jgn di tambahkan cabe rawit\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(175, 3, 'Tuna Steamed', 'Resep Tuna Steamed yang lezat dan mudah dibuat di rumah.', '[\"100 gram tuna fillet\", \"100 gram buncis\", \"Lemon di slice tipis\", \"1/2 butir bawang bombay di cincang\", \"1 sdt oregano\", \"1 sdt lada\", \"1 sdt garam\", \"1 sdt olive oil\", \"1 lembar alumunium oil\"]', '[\"Saya rebus sebentar untuk buncis nya biar klo di kukus empuk\", \"Ambil alumunium oil, tata buncis, beri olive oil, beri tuna yg sudah dilumuri lada + garam di kedua sisinya, next beri oregano, bawang bombay + lemon bungkus,lalu kukus 8 - 10 menit.\", \"Hidangkan, rasany gurih gak amis. Klo suka pedas bisa taburi bon cabe atau cabe bubuk.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(176, 2, 'Gulai ikan tongkol', 'Sajian ikan nikmat: Gulai ikan tongkol yang mudah dibuat.', '[\"1/2 kg ikan tongkol\", \"1 ikat kacang panjang\", \"1 ikat daun kemangi\", \"1/2 papan tempe potong2\", \"2 lbr daun jeruk\", \"2 bh sereh\", \"2 bh daun salam\", \"Bumbu halus :\", \"5 bh bawang merah,\", \"3 bh  bawang putih,\", \"jahe,\", \"kunyit,\", \"3 bh  kemiri,\", \"8 bh  cabe,\", \"Garam, gula, penyedap\"]', '[\"Cuci bersih dan potong ikan sesuai selera\", \"Cuci bersih dan potong2 sayuran\", \"Potong2 tempe sesuai selera\", \"Tumis bumbu halus dgn sedikit minyak panas, masukkan daun jeruk, sereh, daun salam, lalu aduk2 hingga harum\", \"Masukkan air, garam, gula, penyedap secukupnya lalu didihkan\", \"Setelah mendidih masukkan potongan ikan, kacang panjang dan tempe. Lalu didihkan kembali\", \"Terakhir masukkan kemangi dan hidangkan. Selamat menikmati 😊😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(177, 2, 'Tuna sambal goreng', 'Resep Tuna sambal goreng yang lezat dan mudah dibuat di rumah.', '[\"1 kaleng tuna sambal goreng\", \"1 buah bawang bombay\", \"5 cabe rawit (sesuai selera)\", \"2 lembar daun jeruk\", \"Secukupnya garam, gula dan penyedap\"]', '[\"Sebelumnya cuci bawang bombay, daun jeruk dan cabe rawitnya. Kemudian Iris bawang bombay, daun jeruk dan cabe rawit\", \"Tuang sedikit minyak utk menumis bawang bombay dan cabe rawit. Tumis hingga harum\", \"Masukan tuna kaleng nya, tambahkan garam, gula dan penyedap secukupnya. Tuang sedikit air. Dan masukan irisan daun jeruk.\", \"Tes rasa dan siap dihidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(178, 4, 'Balado tongkol dan terong (torong)', 'Nikmati kelezatan Balado tongkol dan terong (torong) dengan resep sederhana ini.', '[\"250 gr Pindang tongkol\", \"2 pcs Terong\", \"secukupnya Garam\", \"secukupnya Gula\", \"Bubuk kaldu rasa ayam\", \"Bumbu halus:\", \"secukupnya Cabe keriting merah\", \"secukupnya Cabe rawit\", \"2-3 pcs Cabe merah tanjung besar\", \"8 siung Bawang merah\", \"4 siung Bawang putih\"]', '[\"Pertama cuci bersih semua bahan (terong dan semua bumbu)\", \"Goreng terung dan pindang tongkol jika suka (saya tidak digoreng tongkolnya :D) lalu sisihkan\", \"Tumis bumbu halus dengan sedikit minyak hingga masak sempurna (ditandai dengan keluarnya minyak dan bumbu menyusut)\", \"Masukkan gula garam dan bubuk kaldu secukupnya. Masak sebentar\", \"Koreksi rasa kemudian sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(179, 3, 'Mangut Ikan Gabus', 'Resep praktis Mangut Ikan Gabus yang bisa dicoba di rumah.', '[\"1 kg ikan gabus segar bersihkan sisik nya\", \"1 buah jeruk nipis\", \"10 cabe hijau teropong (boleh lebih)\", \"5 cabe rawit (boleg lebih)\", \"6 siung bawang merah\", \"5 siung bawang putih\", \"3 buah kemiri\", \"700 cc santan kental (sy pakai santan dari parutan kelapa)\", \"1 ruas batang serai memarkan\", \"1 buah lengkuas memarkan\", \"2 buah daun jeruk purut\", \"1 buah jahe memarkan\", \"1 sdt garam\", \"Gula merah secukup nya\", \"300 cc minyak goreng\"]', '[\"Bumbui ikan gabus dg garam kemudian Lumuri ikan dg air jeruk nipis diamkan selama 15 mnt.\", \"Goreng ikan dg minyak panas sampai kering..\", \"Haluskan bawang merah+bawang putih+kemiri... cabe diiris tipis..\", \"Bila sudah bumbu halus campurkan lengkuas+batang serai+daun jeruk memarkan saja\", \"Parut kelapa ambil santan kental nya kurleb 700 ml\", \"Panaskan 4 sdm minyak goreng tumis bumbu yg dihaluskan sampai wangi. Tambakan cabe,garam,gula merah lalu masukan santan. Aduk terus santan hingga mendidih. Masukan ikan gabus tadi.. Aduk2 jangan sampai santan pecah.. Lalu koreksi rasa..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(180, 4, 'Kembung pesmol', 'Kembung pesmol dengan cita rasa segar khas laut.', '[\"1/2 kg ikan kembung\", \"Bahan halus\", \"10 siung bawang merah\", \"3 siung bawang putih\", \"5 butir kemiri\", \"2 siung kunyit\", \"1 ruas jahe seujung jari\", \"2 sendok gula pasir\", \"1 SM cuka\", \"1/2 buah tomat\", \"Bahan kasar\", \"2 ruas sereh\", \"3 daun salam\", \"2 buah wortel (iris tipis memanjang)\", \"15 butir cabai rawit\", \"1 buah tomat\"]', '[\"Bumbui ikan segar dengan garam goreng,\", \"Blender semua bumbu halus, ditumis hingga wangi, kemudian ksh air sedikit kurleb 50 ml air, jika sudah matang masukkan semua bumbu kasar dan ikan yg sudah digoreng, koreksi rasa dan matikan api\", \"Selamat mencoba🙏🏻🙏🏻\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(181, 3, 'Nugget Ikan Tuna', 'Sajian ikan nikmat: Nugget Ikan Tuna yang mudah dibuat.', '[\"💦1/4 ikan tuna (Stock Frozen) bisa ikan dori\", \"5 siung bawang putih (agak banyak untuk ngilangin bau amis)\", \"Keju parut\", \"1 bh Wortel parut\", \"tepung panir\", \"1/4 sdt lada (bisa skip)\", \"kaldu ayam\", \"1 btr telur ayam\"]', '[\"Blender ikan tuna yg sudah di cuci bersih dengan bawang putih dan 1 telor ayam sampai halus.\", \"Pindahkan adonan ke wadah bersih tambahkan Lada dan kaldu ayam lepas tu campurkan tepung panir, aduk rata lalu masukkan wortel dan keju. aduk hingga rata.\", \"Siapkan kukusan, lalu masukkan adonan ke dalam loyang / tupperware. lalu kukus kurled 20menit.\", \"Setelah matang, angkat diamkan sampai dingin lalu potong sesuai selera kemudian baluri dengan telor ayam dan tepung panir ulangi sampai adonan habis.\", \"Jika sudah masukkan ke dalam frezzer, dan bisa di goreng kapan saja.😊\", \"Selamat Mencoba.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(182, 3, 'Spageti tuna keju', 'Buat Spageti tuna keju yang nikmat dengan langkah-langkah mudah ini.', '[\"1 pc spageti\", \"200 gr ikan tuna segar\", \"3 bawang putih\", \"5 bawang merah\", \"5 buah cabe merah keriting\", \"1 tomat\", \"secukupnya Seledri & daun bawang\", \"secukupnya Garam\", \"secukupnya Merica\", \"Minya goreng\", \"sesuai selera Keju\"]', '[\"Rebus spageti hingga matang. Lalu tiriskan\", \"Iris semua bumbu untuk ditumis\", \"Siapkan wajan beri sedikit minyak.. Tumis bumbu yang telah diiris beserta tuna, lalu tambahkan sedikit air,\", \"Tumis hingga asat. Tambahkan spageti yg telah ditiriskan, aduk2 sebentar tambahkan potongan saledri dan daun bawang\", \"Angkat dan sajikan.. beri sedikit parutan keju\", \"Masakan siap disantap\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(183, 4, 'Tongkol balado simpel', 'Tongkol balado simpel - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"Cabai merah\", \"Cabai rawit/cabai setan\", \"Bawang merah\", \"Ikan tongkol tanpa tulang. Biasanya 3rb/bungkus\", \"Gula\", \"Garam\", \"Royco\"]', '[\"Rebus semua cabai\", \"Giling rebusan cabai dengan bawang merAh\", \"Tumis bumbu halus hingga wangi, lalu masukan garam gula royco secukupnya\", \"Masukkan ikan jika ke dalam tumisan, aduk-aduk hingga ikan menjadi hancur\", \"Aduk terus hingga bumbu meresap ke dalam ikan\", \"Sajikan dengan nasi hangat dan kerupuk\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(184, 4, 'Nuget ikat patin ala mbak Am', 'Resep Nuget ikat patin ala mbak Am ala rumahan yang dijamin menggugah selera.', '[\"2 ekor ikan patin\", \"Merica bubuk\", \"Penyedap rasa\", \"Garam\", \"Wortel (parut pakai patutan keju)\", \"5 siung bawang putih (haluskan)\", \"2 butir telur\", \"Minyak untuk menggoreng\"]', '[\"Kukus ikan patin tanpa bumbu\", \"Setah dikukus, pisahkan ikan patin dari durinya\", \"Blender(haluskan) ikan patin tanpa air\", \"Campurkan ikan patin yang sudah halus, penyedap rasa, garam, merica bubuk dan parutan wortel\", \"Tambahkan putih telur\", \"Kukus hingga matang\", \"Diamkan sampai dingin, lalu potong nuget sesuai selera\", \"Panaskan minyak\", \"Celupkan nuget ke kocokan telur lalu baluri dengan tepung panir\", \"Goreng sampai kecoklatan\", \"Selamat mencoba 😘\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(185, 3, 'Nila Goreng Cabe Ijo', 'Nikmati kelezatan Nila Goreng Cabe Ijo dengan resep sederhana ini.', '[\"6 ekor Ikan nila\", \"1 Tepung sajiku ayam kentucky\", \"30 Cabe rawit\", \"10 Bawang putih\", \"secukupnya Minyak goreng\", \"secukupnya Penyedap\", \"secukupnya Garam\"]', '[\"Belah ikan jgn sampai lepas, cuci bersih, beri garam dan jeruk nipis agar tidak amis. lalu baluri tepung sajiku basah, goreng.\", \"Goreng sebentar cabai rawit dan bawang putih, lalu giling kasar atau sesuai selera dengan sedikit minyak bekas goreng, tambah garam dn penyedap secukupnya.\", \"Sajikan ikan nila goreng dengan sambal ijo dan nasi panas.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(186, 4, 'Tongkol Balado Rawit', 'Resep praktis Tongkol Balado Rawit yang bisa dicoba di rumah.', '[\"650 Gram Ikan Tongkol\", \"15 Cabe Merah Keriting\", \"15 Cabe Rawit Merah\", \"7 Buah Bawang Merah\", \"5 Siung Bawang Putih\", \"1 Ruas Jari Jahe\", \"2 Ruas Jari Lengkuas\", \"2 Lembar Daun Salam\", \"1 Buah Tomat\"]', '[\"Goreng Setengah Matang Ikan, Jangan Terlalu Kering Nanti Keras.\", \"Haluskan Cabe Merah Keriting, Cabe Rawit Merah, Bawang Merah, Bawang Putih, Tomat & Jahe.\", \"Setelah Bumbu Halus, Lalu Tumis Bumbu Beserta Lengkuas, Daun Salam. Sampai Harum.\", \"Setelah Harum Masukkan Ikan Lalu Masak Hingga Meresap.\", \"Angkat & Sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(187, 3, 'Tuna Goreng Crispy Saus Teriyaki', 'Resep praktis Tuna Goreng Crispy Saus Teriyaki yang bisa dicoba di rumah.', '[\"20 potong tuna iris kotak (rendam dengan air jeruk nipis)\", \"1 sachet tepung crispy ayam\", \"1 sachet saus teriyaki\", \"1 buah bawang bombay\"]', '[\"1 sachet tepung bagi dua, buat yg basah dan pisahkan yang kering... tuna yang sudah direndam air jeruk nipis masukan kedalam tepung yang diencerkan aduk rata\", \"Lalu masukan ketepung kering lakukan smpai tuna habis, kemudian goreng dengan api sedang udah kecoklatan angkat ga usah lama2\", \"Tumis bawang bombay sampai harum, masukan tuna yg sudah digoreng, beri saus teriyaki aduk rata. Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(188, 4, 'Tongkol suwir pedas manis💓', 'Buat Tongkol suwir pedas manis💓 yang nikmat dengan langkah-langkah mudah ini.', '[\"250 gr ikan tongkol\", \"Bumbu:\", \"8 siung bawang merah\", \"6 siung bawang putih\", \"2 biji asam jawa\", \"sesuai selera Cabe rawit,cabe merah besar,cabe hijau besar\", \"1 buah tomat\", \"1 sdt garam\", \"1 sdm gula merah sisir\", \"1/2 sdt penyedap\", \"1 sdt kecap manis\", \"200 ml air\"]', '[\"Goreng ikan tongkol sampai matang. Lalu suwir suwir buang tulangnya.\", \"Tumis bawang merah,bawang putih,cabe,asam jawa sampai harum. Tambahkan air,irisan tomat,garam,gula merah,kecap,penyedap,tes rasa,,bila sudah oke masukan suwiran tongkol. Biarkan meresap,sisakan sedikit airnya supaya tidak terlalu kering.😍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(189, 2, 'Tumis terong+ sarden', 'Cara membuat Tumis terong+ sarden yang enak dan praktis untuk keluarga.', '[\"2 bh terong ungu\", \"1 kaleng sarden\", \"5 bh Cabe merah\", \"5 bh Cabe rawit\", \"2 siung Bawang merah\", \"1 siung Bawang putih\", \"Jahe di geprek\", \"5 bh Cabe hijau  di iris\", \"Garam\", \"Gula\"]', '[\"Potong2 terong ukuran kecil.. Taruh di wadah lalu cuci dgn air garam\", \"Ulek cabe merah,bawang merah,bawang putih\", \"Lalu panas kan minyak diwajan... Tumis bumbu yg sdh dihaluskan, masukan jahe dan cabe hijau..tambahkan garam, gula lalu masukkan terong aduk2 tambahkan air lalu tutup wajan..\", \"Lalu masukkan sarden aduk2 lg sampe rata lalu tutup kembali wajan... Koreksi rasa dan matikan api...siap dihidangkan...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(190, 2, 'Ikan tongkol balado', 'Resep Ikan tongkol balado yang lezat dan mudah dibuat di rumah.', '[\"10 buah ikan tongkol iris\", \"2 lembar daun jeruk\", \"minyak untuk menumis\", \"garam\", \"bumbu halus:\", \"4 bawang merah\", \"2 bawang putih\", \"15 cabe merah keriting\", \"10 cabe rawit setan (selera)\", \"1/2 tomat besar\", \"gula merah\"]', '[\"Goreng sebentar ikan tongkol\", \"Dalam penggorengan terpisah, tumis bumbu halus, masukkan daun jeruk dan garam hingga berubah warna\", \"Masukkan ikan tongkol yg sudah digoreng tadi\", \"Koreksi rasa, sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(191, 3, 'Lodeh Tongkol Tahu Pedas', 'Cara membuat Lodeh Tongkol Tahu Pedas yang enak dan praktis untuk keluarga.', '[\"10 potong tongkol\", \"1/2 buah tahu\", \"🌸Bumbu Halus:\", \"7 Bawang Merah\", \"4 Bawang Putih\", \"3 buah Kemiri\", \"2 cm Kunyit\", \"1/2 sdt merica\", \"1/2 sdt ketumbar\", \"1 buah cabe merah\", \"10 buah cabe kecil (selera)\", \"Secukupnya garam gula\", \"1 sachet santan kara\", \"2 lembar daun salam\", \"1 buah daun serai geprek\"]', '[\"Goreng tongkol dan tahu (potong2)\", \"Haluskan bumbu halus, tumis bumbu halus + daun serai + daun salam sampai harum\", \"Masukan tongkol dan tahu, tambahkan air (+- 500 ml) dan santan kara\", \"Tambahkan cabe rawit utuh (selera), didihkan dengan api sedang, sesekali diaduk agar santan tidak pecah\", \"Jika air mulai susut, tes rasa dan kematangan, (bisa ditambahkan air lg jika dirasa kuah msh kurang matang)\", \"Sajikan dengan taburan bawang merah goreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(192, 3, 'Ikan tongkol cuwe cabe ijo', 'Ikan tongkol cuwe cabe ijo dengan cita rasa segar khas laut.', '[\"Ikan tongkol potong 5 keranjang, bersihkan\", \"Bumbu:\", \"10 butir Bawang merah\", \"7 butir Bawang putih\", \"10 bh Cabe ijo besar\", \"5 bh Cabe rawit ijo\", \"5 bh Tomat ijo\", \"Laos, Daun salam dan daun jeruk\", \"secukupnya Saos tiram, kecap manis, garam, gula merah dan pasir\"]', '[\"Bersihikan ikan tongkol dg cara disiram air panas dan diamkan selama 15menit, lalu cuci bersih lagi dg air biasa secara hati2 agar tidak hancur\", \"Goreng ikan tongkol sampe matang\", \"Iris bawang merah dan putih\", \"Potong serong cabe ijo besar dan cabe rawit\", \"Potong2 tomat ijo menjadi 4 bagian\", \"Tumis rajangan bawang merah, lalu bawang putih.. sampe harum, baru masukkan irisan cabe, salam, laos dan daun jeruk\", \"Masukkan cuwe tongkol yang sudah digoreng ke dalam tumisan bumbu\", \"Tambahkan air secukupnya... Lalu diaduk2. Stlh mendidih baru tambahkan saos tiram, kecap manis, gula dan garam sesuai selera tingkat kemanisannya\", \"Terakhir masukkan potongan tomat hijau\", \"Matikan api dan masakan siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(193, 4, 'Ikan tuna asam manis', 'Nikmati kelezatan Ikan tuna asam manis dengan resep sederhana ini.', '[\"Secukupnya ikan tuna, kalo aku beli yg udah di plastikin di tukang sayur\", \"Secukupnya bawang bombay\", \"3 siung bawang merah\", \"2 siung bawang putih\", \"Secukupnya air\", \"Secukupnya gula\", \"Secukupnya garam\", \"Secukupnya saos sambal abc\", \"Secukupnya saori saus tiram\"]', '[\"Tumis bawang merah bawang putih dan bawang bombay. Tumis hingga harum.\", \"Masukan air secukupnya, lalu masukan saos sambal abc sesuai selera ya. Abis itu aduk lalu masukan gula garam secukupnya dan terakhir masukan saori saus tiram nya secukupnya aja.\", \"Jika sudah menyatu bumbu nya masukan ikan tuna yg sudah di goreng terlebih dahulu dan dipotong potong kecil biar gampang saat makan nya.\", \"Ketika ikan sudah menyatu dengan bumbu nya, tunggu sampai kuah nya agak menyusut jadi agak kental.\", \"Jika sudah, matikan api kompor lalu hidangkan dan ikan tuna asam manis siap di santap.\", \"Mudahkan cara buat nya selamat mencoba semua nya ❤️\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(194, 2, 'Pepes (Pais) Patin', 'Resep Pepes (Pais) Patin yang lezat dan mudah dibuat di rumah.', '[\"Bumbu :\", \"10 bawang merah\", \"6 bawang putih\", \"5 kemiri\", \"1/2 terasi\", \"1 buah cabe merah besar\", \"secukupnya Gula\", \"secukupnya Garam\", \"secukupnya Penyedap\", \"secukupnya Lada\", \"Isian :\", \"3 buah cabe merah besar\", \"1 buah cabe hijau besar\", \"2 buah tomat\", \"Daun pisang (panaskan ke api)\", \"3 potong ikan patin\", \"6-8 tusuk gigi\"]', '[\"Gabung / jadikan satu bahan bumbu yang sudah disipkan\", \"Haluskan bumbu menggunakan cobek/blender\", \"Siapkan daun pisang yang sudah dipanaskan dengan api agar tidak mudah sobek\", \"Taruh satu potongan ikan patin diatas daun, lumuri dengan bumbu yang sudah dhluskan dan masukan irisan cabe dan tomat\", \"Gulung daun dan sematkan dengan tusuk gigi\", \"Kukus kurleb 10 menit\", \"Panggang kurleb 10 menit\", \"Pepes selesai dan siap untuk dihidangkan 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(195, 4, 'Oseng tongkol pedas', 'Nikmati kelezatan Oseng tongkol pedas dengan resep sederhana ini.', '[\"500 gram ikan tongkol, ambil daging nya saja\", \"2 buah cabe hijau besar\", \"5 buah cabe rawit merah\", \"1 buah bawang bombay\", \"4 siung bawang merah\", \"3 siung bawang putih\", \"1 sdt kaldu bubuk\", \"1 1/2 sdt gula pasir\", \"1/2 buah tomat\", \"secukupnya Minyak goreng\"]', '[\"Potong2 ikan tongkol, kemudian goreng setengah matang. Angkat dan tiriskan\", \"Iris bawang bombay, bawang putih, bawang merah, tomat, cabe rawit, cabe hijau.\", \"Siapkan wajan bri minyak, setelah panas masukkan bawang putih, bawang merah, bawang, cabe rawit, cabe hijau..\", \"Setelah matang, masukkan ikan tongkol, beri gula pasir, kaldu, aduk hingga merata\", \"Test rasa, kmudian masukkan tomat, aduk sebentar. Angkat dan siap di sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(196, 4, 'Bandeng Presto Balado', 'Bandeng Presto Balado dengan cita rasa segar khas laut.', '[\"2 bandeng presto (goreng setengah matang)\", \"3 siung bawang putih\", \"6 siung bawang merah\", \"2 buah cabe merah besar\", \"1 iris jahe\", \"100 ml air\", \"Minyak untuk menumis\", \"secukupnya Garam\", \"secukupnya Gula pasir\"]', '[\"Uleg/blender duo bawang cabe merah dan jahe. Tumis hingga matang,\", \"Masukan air tunggu hingga mendidih, masukan garam dan gula pasir tes rasa..masukan bandeng yg sudah di goreng masak hingga air surut..angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(197, 2, 'Pindang asem tongkol', 'Pindang asem tongkol dengan cita rasa segar khas laut.', '[\"1 ekor ikan tongkol bisa ikan selar\", \"1 bulat gula merah\", \"secukupnya Asem\", \"secukupnya Cabe rawit\", \"secukupnya Garam\", \"secukupnya Air\", \"Sere\"]', '[\"Air,asam, gula merah, sere di tata kemudian masak sampai menggolak\", \"Kemudian masukan ikan,garam dan cabe rawit kemudian masak sampai matang angkat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(198, 2, 'Ikan tongkol cue tumis cabe', 'Buat Ikan tongkol cue tumis cabe yang nikmat dengan langkah-langkah mudah ini.', '[\"ikan tongkol cue\", \"segenggam cabe ijo\", \"segenggam cabe rawit\", \"bawang putih\", \"bawang merah\", \"1 sendok saus tiram\", \"garam\", \"gula\", \"kaldu bubuk\"]', '[\"Iris semua bahan2 cabe, bawang merah dan bawang putih. di resep ini saya sengaja potongan bawang besar2 supaya bisa digigit.\", \"Goreng ikan tongkol cue sebentar saja jgn sampai terlalu kering.\", \"Tumis bawang merah bawang putih, lalu masukan cabe.\", \"Masukan ikan tongkol, beri gula, garam, kaldu bubuk, dan saus tiram. masak sebentar. koreksi rasa.\", \"Matikan api lalu sajikan dengan nasi hangat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(199, 2, 'Chunky Tuna ala Dee🌸', 'Sajian Chunky Tuna ala Dee🌸 yang praktis dan lezat untuk dinikmati bersama.', '[\"130 gr chunky tuna kaleng\", \"2 siung bawang putih cincang kasar\", \"1/2 bawang bombay kecil cincang kasar\", \"1 btg kecil bawang daun iris kecil\", \"2 cabe rawit merah iris kecil\", \"2 sdm minyak goreng\", \"Secukupnya garam, lada, royco, gula pasir\", \"1/2 sdt italian herbs(bisa diskip)\", \"1 sdt minyak ikan\"]', '[\"Siapkan bahan\", \"Panaskan minyak.. tumis bawang putih, bawang bombay, bawang daun dan cabe rawit.. setelah layu masukan chunky tuna.. tambahkan kecap ikan, garam, lada, royco, sedikit gula pasir.. aduk sampai semua matang tambahkan italian herbs.. jangan lupa test rasa yaa👍😊\", \"Isian chunky tuna siap deeh👍😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(200, 4, 'Pesmol Gurame', 'Cara membuat Pesmol Gurame yang enak dan praktis untuk keluarga.', '[\"1 ekor gurame (ikan nila)\", \"2 buah mentimun, potong korek\", \"2 buah wortel, potong korek\", \"sesuai selera Cabai rawit\", \"6 buah jeruk nipis, peras airnya\", \"2 lembar daun jeruk\", \"2 lembar daun salam\", \"Gula pasir\", \"Garam\", \"Merica\", \"Bumbu halus:\", \"7 siung bawang merah\", \"3 siung bawang putih\", \"5 butir kemiri\", \"2 batang serai\", \"1 ruas jahe\", \"1/2 ruas kunyit\", \"1 ruas lengkuas\"]', '[\"Kerat ikan dan lumuri dengan jeruk nipis. Diamkan 15 menit\", \"Goreng garing ikan. Sisihkan\", \"Tumis bumbu halus, jika sudah harum tambahkan sedikit air\", \"Masukkan daun jeruk, daun salam, air jeruk nipis, gula pasir, garam, merica. Tes rasa\", \"Terakhir tambahkan wortel, mentimun, cabai rawit\", \"Masak hingga meresap, sisakan airnya sedikit\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(201, 3, 'Ikan sarden campur telur ala anak kosan', 'Nikmati kelezatan Ikan sarden campur telur ala anak kosan dengan resep sederhana ini.', '[\"1 kaleng sarden (boleh merk apa saja)\", \"1 butir telur\", \"1 buah bawang bombay\", \"Secukupnya penyedap rasa dan gula\"]', '[\"Iris tipis bawang bombay, lalu tumis hingga wangi. Lalu masukan telur, orak-arik tambahkan sedikit penyedap rasa.\", \"Kemudian masukan ikan sarden, tambahman sedikit air. Lalu tambahkan sedikit penyedap rasa dan gula. Tes rasa. Tunggu sebentar hingga kental, hidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(202, 4, 'Mangut Ikan Phe (pari)', 'Resep Mangut Ikan Phe (pari) yang lezat dan mudah dibuat di rumah.', '[\"1 japit ikan phe (Ikan pari diasap)\", \"9 butir bawang putih\", \"9 butir bawang merah\", \"4 helai kemangi\", \"5 sdm sun kara (ini sesuai selera sih)\", \"5 biji cabe rawit utuh\", \"garam, lada, gula dan penyedap rasa\"]', '[\"Cuci ikan phe potong dadu sisihkan.\", \"Iris tipis bawang merah dan bawang putih. Lalu goreng dengan minyak hingga harum.\", \"Masukkan ikan phe yg dipotong dadu tumis hingga ikan agak kecoklatan.\", \"Tambahkan air hingga semua ikan terendam. Tunggu 5-10 menit.\", \"Masukkan sun kara sebanyak 5 sdm. Sesuai kekentalan yg diinginkan. Tambahkan kemangi, cabe rawit dan masukkan garam, gula lada secukupnya. Aduk sebentar. Angkat siap dihidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(203, 4, 'Sarden kuah asam', 'Sajian ikan nikmat: Sarden kuah asam yang mudah dibuat.', '[\"3 ikan sarden besar (bisa memakai ikan tongkol)\", \"6 buah belimbing wuluh\", \"10 siung bawang merah\", \"5 siung bawang putih\", \"15 cabe rawit\", \"8 buah pete\", \"1/2 ruas jari laos (geprek)\", \"Secukupnya garam\", \"Secukupnya gula\", \"Secukupnya minyak goreng\", \"3 gelas air\", \"Bumbu halus :\", \"5 siung bawang merah\", \"4 siung bawang putih\", \"7 cabe merah\", \"3 butir kemiri\"]', '[\"Cuci semua bahan hingga bersih\", \"Goreng ikan setengah matang. Lalu pisahkan daging dengan durinya. Sisihkan\", \"Blender semua bumbu halus. Sisihkan\", \"Iris serong cabe, iris tipis bawang merah bawang putih, iris tebal pete dan belimbing wuluh. Sisihkan\", \"Goreng bawang merah dan bawang putih setengah layu, masukkan cabe, pete, belimbing wuluh, laos, aduk. Masukkan bumbu halus yg sudah di blender, tambahkan air lalu garam, gula. Aduk hingga mendidih\", \"Masukkan ikan yg sudah di goreng tadi. Tunggu sebentar. Matikan kompor. Sarden kuah asem siap di nikmati.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(204, 4, 'Gabus asin sambal pete', 'Resep Gabus asin sambal pete ala rumahan yang dijamin menggugah selera.', '[\"4 Papan pete\", \"250 gram Ikan asin gabus\", \"10 Siung Bawang merah\", \"1 Siung Bawang putih\", \"100 gram Cabai rawit\", \"5 Buah Cabai merah\", \"1 Buah Tomat\", \"2 Buah jeruk Limo\", \"1 Sendok kecil Gula putih\", \"secukup Royco ayam\", \"secukupnya Garam\"]', '[\"Kupas pete, belah dua\", \"Rendam ikan gabus asin dengan air panas kurang lebih 5 menit. Tiriskan. Goreng kering. Sisihkan\", \"Haluskan kasar semua bumbu, kecuali jeruk limo\", \"Tumis pete dengan minyak agak sedikit banyak, kira-kira 5 sendok makan, masukan bumbu yang telah dihaluskan, lalu Masukan ikan yang telah digoreng tadi. Tambahkan garam gula dan royco.\", \"Terakhir tambahkan perasan jeruk limo. Angkat sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(205, 3, 'Gurame crispy saus tiram brokoli', 'Cara membuat Gurame crispy saus tiram brokoli yang enak dan praktis untuk keluarga.', '[\"1 ekor gurame\", \"2 Tepung kobe\", \"1 brokoli\", \"2 jeruk nipis\", \"Bahan saus :\", \"5 cabe setan\", \"3 siung bawang putih\", \"3 siung bawang merah\", \"1 cm jahe\", \"2 bawang bombay\", \"2 saset saus tiram\", \"saset Mentega\", \"Kecap\", \"Lada bubuk\", \"Garam\", \"Penyedap rasa (royco ayam)\", \"Air (disesuaikan sendiri)\"]', '[\"Bersihkan ikan dari kotoran dan sisik lalu villet ikan (pisahkan antara tulang dan daging) setelah itu lumuri dengan garam secukupnya dan perasan jeruk nipis. Diamkan beberapa menit\", \"Selagi menunggu. Siapkan bahan untuk sausnya. Iris semua bahan untuk saus. Bawang merah. Putih. Jahe. Bombay\", \"Siapkan bahan untuk goreng ikannya. Siapkan tepung kobe seperti cara penggunaan yg ada di kemasannya. Lakukan seperti dikemasan. Lalu goreng di atas minyak yg cukup banyak hingga kecoklatan lalu angkat dan tiriskan\", \"Membuat saus. Tumis semua bahan saus hingga wangi lalu masukan mentega saset aduk lagi dan tambahkan saus tiramnya\", \"Setelah cukup mendidih tambahkan air sesuaikan takaran anda sendiri dan masukan brokoli. Aduk sampai sekiranya mengental\", \"Setelah saus matang. Siram ikan yg tadi sudah digoreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(206, 2, 'Ikan bawal sambel mata+kecap ala bumill aziiipppp', 'Ikan bawal sambel mata+kecap ala bumill aziiipppp dengan cita rasa segar khas laut.', '[\"1/2 kg ikan mujair\", \"7 bawang merah\", \"7 cabe setan\", \"1/2 buah tomat\", \"2 buah jeruk nipis\", \"secukupnya Garam\", \"secukupnya Kecap\", \"Minyak sayur untuk menggoreng\"]', '[\"Buang isi ikan dan cuci bersih, kemudian lumuri dengan jeruk nipis dan garam.\", \"Simpan di kulkas selama 10 menit atau sampai hilang bau amis.\", \"Panas minyak sayur kemudian masukan ikan mujair goreng sampai kering.\", \"Sambil menunggu ikan matang iris cabe, bawang dan tomat. Tumis sebentar\", \"Jika ikan sudah matang siapkan di wadah lalu taburkan irisan cabe,bawang, tomat tadi lalu beri taburan kecap..\", \"Ikan bawal sambel mata+kecap ala bumill...😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(207, 2, 'Ikan kembung balado maknyos', 'Resep Ikan kembung balado maknyos yang lezat dan mudah dibuat di rumah.', '[\"5 ekor ikan kembung\", \"secukupnya Minyak\", \"Bumbu yang dihaluskan :\", \"15 pcs cabai merah\", \"5 pcs cabai rawit orange\", \"4 siung bawang merah\", \"3 siuang bawang putih\", \"1 buah tomat ukuran sedang\", \"2 buah kemiri sangrai\", \"Tambahan :\", \"2 helai Daun jeruk\", \"1 pcs Jeruk nipis\", \"1 sendok teh Gula merah\", \"Penyedap rasa (royko/masako)\"]', '[\"Cuci ikan hingga bersih lalu peraskan jeruk nipis.\", \"Goreng ikan sampai agak kekuningan, angkat lalu tiriskan.\", \"Ulak semua bumbu sampai halus.sebelumnya sangrai kemiri hingga beraroma.\", \"Panaskan minyak masak bumbu yg sudah dihaluskan hingga agak mencoklat.masukan daun jeruk,gula merah,serta bumbu penyedap lainnya. cicipi sesuai selera.\", \"Masukan ikan yg sudah digoreng sampai bumbu merata.\", \"Siap dihidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(208, 3, 'Fillet gurame saos pedas manis', 'Cara membuat Fillet gurame saos pedas manis yang enak dan praktis untuk keluarga.', '[\"1 ekor ikan gurame ukuran besar\", \"1 buah jeruk nipis\", \"(fillet ikan potong kotak) sisakan kerangka ikannya\", \"1 bungkus tepung sajiku\", \"Bahan saos\", \"4 sdm saos tomat\", \"2 sdm saos sambel\", \"1 sdm saori saos tiram\", \"1 buah bawang bombai potong memanjang\", \"3 siung bawang merah\", \"2 siung bawang putih\", \"2 buah cabe merah, potong serong\", \"4 buah cabe rawit potong halus\", \"1 sdm maizena, larutkan dengan air\", \"1 batang daon bawang potong serong\", \"1/4 gelas air\", \"1/2 sdt merica bubuk\", \"1/4 sdt garam\"]', '[\"Lumuri ikan yg sudah difillet dengan jeruk nipis diamkan\", \"Tuang satu bungkus tepung sajiku tambahkan air\", \"Celup ikan kedalam tepung sajiku, goreng hingga kekuningan\", \"Goreng kerangka ikan yg sudah difillet\", \"Cara memasak saos\", \"Panaskan minyak, masukkan bawang bombai, bawang merah, putih masak hingga wangi\", \"Masukkan saos tomat saos sambal dan saori aduk hingga rata\", \"Masukkan cairan maizena,merica dan air\", \"Masukkan cabe rawit dan cabe merah\", \"Tambahkan garam,aduk hingga kental, masukkan daun bawang\", \"Tata fillet ikan diatas kerangka nya,siram dengan saos\", \"Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(209, 2, 'Nasi Goreng Cakalang', 'Resep Nasi Goreng Cakalang yang lezat dan mudah dibuat di rumah.', '[\"2 biji bawang putih\", \"2 biji bawang merah\", \"4 biji cabe merah\", \"1/4 nasi putih\", \"2 sdm mentega/ minyak kelapa secukupnya\", \"1/4 ikan cakalang\", \"1/4 sdm garam (tergantung keinginan)\", \"1/4 sdm penyedap rasa (masako)\", \"Kecap Manis\"]', '[\"Tumbuk bersamaan bawang putih, bawang merah dan cabe\", \"Panaskan mentega/minyak kelapa secukupnya kemudian masukan bawang putih, bawang merah dan cabe sampai harum dan kemerahan\", \"Tambahkan sedikit garam dan penyedap rasa sesuai selera, juga ikan cakalang (sudah di goreng, kemudian di robek2)\", \"Masukkan nasi (ukuran terserah, sesuai kemampuan perut)\", \"Buat nasi, bumbu dan ikan tercampur sampai rata lalu tambahkan sedikit kecap\", \"Angkat dan taruh disajikan di atas piring. Selesai deh...\", \"Bisa tambahkan telur ceplok untuk pelengkap 😍 dijamin enak nasi goreng nya. Selamat mencoba 😇🙏\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(210, 4, 'Tongkol Balado', 'Tongkol Balado - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 kg ikan tongkol potong2 saya jadinya 6 potong kepalanya saya gak pakai, dan saya sudah bumbui kuning\", \"50 gr daging sapi potong dadu\", \"Bumbu Halus\", \"10 cabe merah keriting\", \"4 cabe merah besar\", \"12 buah bawang merah\", \"1/4 sdt terasi matang\", \"1 sdt garam\", \"1 sdt masako sapi\", \"1/2 sdt gula pasir\", \"2 sdt cuka masak\", \"Minyak sayur secukupnya untuk menggoreng ikan dan menumis sambal\"]', '[\"Goreng ikan tongkol yang sudah dibumbui kuning, saya ambil stokan yg sudah saya bumbui dari freezer, sisihkan\", \"Ulek kasar atau pakai blender cabe, bawang, terasi dan garam saya mah pake blender aja udh gak sanggup ngulek\", \"Panaskan minyak goreng lalu goreng daging, ini harus bgt ya pake daging krn kata nenek saya yg bikin sedep sambalnya ini ya minyak bekas goreng daging, dikit aja dagingnya gak harus banyak kok\", \"Hasilnya kurleb kaya gini ya garingnya ini kebetulan ada stokan yg td buat sambal mah dikit bgt hehehe\", \"Tumis cabe yg sudah dihaluskan dengan minyak bekas menggoreng daging\", \"Kalau sudah mulai menyatu dan mulai mengeluarkan minyak masukan gula masako dan cuka masak\", \"Aduk kembali sampai warna cabe agak tua seperti gambar ini yang artinya sambalnya sudah matang jgn sampai gosong ya\", \"Masukan ikan dan daging\", \"Aduk rata lalu matikan api, boleh ditest rasa kalau ada yg kurang bisa ditambahkan\", \"Angkat sajikan deh siap disantap dengan nasi yang baru matang dr rice cooker dijamin gak bakalan mau jauh2 dr rice cooker hehehe\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(211, 4, 'Ikan Kembung Goreng Saus Tauco', 'Resep Ikan Kembung Goreng Saus Tauco ala rumahan yang dijamin menggugah selera.', '[\"2 ekor ikan kembung goreng\", \"150 gr buncis potong kecil\", \"1 buah cabe hijau\", \"1 buah tomat\", \"1 buah daun bawang potong kecil\", \"2 siung bawang putih\", \"4 buah cabe rawit (optional)\", \"1 sdm saus tauco asin\", \"1/2 sdm saus tiram\", \"1/3 sdm lada\", \"1/2 sdm kecap manis\", \"1 sdm tepung maizena\", \"Ai putih\", \"2 sdm minyak goreng\"]', '[\"Goreng ikan kembung sesuai bumbu untuk menggoreng, angkat kemudian tiriskan ikan.\", \"Potong kecil bawang, tomas, cabe kemudian tumis sampe harum dan setengah layu. Kemudian tambahkan air putih secukupnya\", \"Setelah itu tambahkan saus tauco, saus tiram, kecap manis, lada, dan tepung maizena (larutkan dalam air). Masak hingga mendidih dan mengental. Setelah itu tambahkan potongan buncis yg sudah dipotong, masak sebentar hingga berubah warna. Tidak perlu menambahkan garam, karena saus sudah asin dan memberi rasa gurih.\", \"Jika saus sudah mengental dan rasanya pas, susun ikan kembung yg sudah digoreng, kemudian tuangkan saus tsb ke atas ikan dan taburi dengan potongan daun bawang.\", \"Siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(212, 3, 'Bawal bakar pedas', 'Nikmati kelezatan Bawal bakar pedas dengan resep sederhana ini.', '[\"2 ekor ikan bawal ukuran besar\", \"Bumbu halus :\", \"4 siung bawang putih\", \"2 ruas jahe\", \"secukupnya Garam\", \"Bumbu olesan :\", \"5 buah kemiri\", \"4 siung bawang putih\", \"4 siung bawang merah\", \"10 buah cabe merah keriting\", \"15 buah cabe rawit\", \"1 ruas jahe\", \"1 ruas kunyit\", \"Secukupnya merica bubuk\", \"1 buah tomat ukuran sedang\", \"Secukupnya gula garam\", \"1 batang sereh keprek untuk mengoleskan (pengganti kuas)\"]', '[\"Cuci bersih ikan, rendam dengan bumbu halus (bawamg jahe garam)\", \"Panaskan minyak, tumis bumbu oles yang sudah dihaluskan sampai harum.\", \"Siapkan bara api, dan bakar ikan yang sudah direndam. (Olesi panggangan dengan minyak agar ikan tidak lengket).\", \"Apabila ikan sudah setengah matang, olesi dengan bumbu oles yang sudah ditumis menggunakan sereh.\", \"Tunggu sampai ikan benar- benar matang sempurna dan angkat.\", \"Bawal bakar pedas siap dihidangkan, selamat mencoba 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(213, 4, 'Ikan patin asam padeh (pedas)', 'Cara membuat Ikan patin asam padeh (pedas) yang enak dan praktis untuk keluarga.', '[\"5-7 ons ikan patin (potong sesuai selera)\", \"10 siung bawang merah (di geprek aja)\", \"4 siung bawang putih (di geprek aja)\", \"3 sdm bumbu kuning (bisa dibeli langsung dipasar)\", \"1/2 sdm bawang putih giling halus (ini juga ada yg ready di pasar)\", \"5 sdm cabe merah giling halus (ini sesuai selera)\", \"5 bh cabe ijo (dibelah dua aja)\", \"5 bh asam kandis (asam jawa)\", \"2 helai daun salam\", \"2 helai daun jeruk\", \"2 helai daun kunyit\", \"1 batang sereh (dibersihkan dan di geprek)\", \"secukupnya Garam\", \"1-2 ltr air\"]', '[\"Sebelumnya ikan patin dibersihkan dulu, direndam pake jeruk nipis sebentar, trus cuci lagi, bentuk potongan ikan patin juga sesuai selera\", \"Masukan air, bawang merah, bawang putih, bumbu kuning, cabe merah, cabe ijo,aduk rata. Ini dimasak dengan api besar\", \"Tambahkan daun daunan dan asam kandis, tunggu hingga mendidih, dan cicipi rasanya, lalu baru tambahkan garam\", \"Setelah bumbu mendidih, baru tambahkan ikan patin ke dalam nya, lalu kecil kan api, tunggu hingga mendidih lagi, dan tunggu hingga ikan benar benar matang, sekitar 10-15 menit.\", \"Lalu cicipi kembali, tambahkan garam jika kurang pas. Kalau udh pas, matikan api, lalu hidangkan\", \"Jika ingin mendapatkan hasil yang lebih mantap lagi, setelah dimasak, matikan api. Lalu diamkan sekitar beberapa jam, setelah itu panaskan kembali dengan api kecil. Dan hidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(214, 3, 'Bandeng Masak Santan Pedas', 'Resep Bandeng Masak Santan Pedas yang lezat dan mudah dibuat di rumah.', '[\"1 kg ikan bandeng\", \"10 bj tahu kulit\", \"1 bks santan instan\", \"Bumbu:\", \"7 siung Bawang merah\", \"5 siung Bawang putih\", \"5 buah Cabe merah keriting\", \"10 buah Cabe rawit setan\", \"3 buah Tomat hijau\", \"Salam, sereh, lengkuas\", \"Gula, garam, kecap\"]', '[\"Goreng ikan bandeng sampai setengah matang (boleh juag sampai kering sesuai selera)\", \"Tumis semua bumbu iris sampai harum\", \"Masukkan ikan dan tahu, tambahkan air\", \"Masukkan gula garam dan kecap, test rasa\", \"Masak sampai air menyusut dan bumbu meresap\", \"Tambahkan santan instan, masak sampai mendidih. Lalu sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(215, 3, 'Gulai Ikan Gurami', 'Gulai Ikan Gurami - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 kg Ikan Gurami\", \"250 ml Santan\", \"15 buah Cabe Rawit\", \"3 siung Bawang Merah\", \"2 siung Bawang Putih\", \"1 ruas jari Jahe\", \"2 ruas jari Lengkuas\", \"1 batang Sereh\", \"1 ruas jari Kunyit\", \"3 lembar Daun Jeruk\", \"1 keping Asam Gelugur\", \"2 sdm Minyak goreng\", \"50 ml Air\", \"Garam\"]', '[\"Haluskan cabe rawit, bawang merah, bawang putih, jahe, dan kunyit beri sedikit garam. Memarkan lengkuas dan sereh.\", \"Panaskan wajan dan minyak goreng, tumis bumbu halus, lengkuas, sereh, dan daun jeruk hingga harum. Tambahkan air kemudian masukkan ikan yang sudah dipotong-potong. Diamkan kira-kira 5 menit hingga bumbu meresap.\", \"Masukkan santan, aduk-aduk pelan dengan api sedang, masak hingga ikan matang. Koreksi rasa. Kemudian siap siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(216, 4, 'Sarden Pindang Tongkol Bumbu Iris', 'Resep Sarden Pindang Tongkol Bumbu Iris ala rumahan yang dijamin menggugah selera.', '[\"4 ekor Pintang tongkol goreng buang durix potong\\\" selera\", \"🐌 Bumbu Iris :\", \"4 siung Bawang merah\", \"3 siung Bawang putih\", \"1000 Cabe hijau ale Rp\", \"8 bh Cabe rawit\", \"5 btg Bunga bawang pot. 1 cm\", \"2 bh Tomat\", \"2 sdm Saos tomat\", \"2 sdm Saos sambal\", \"Secukupnya Gula, garam & royco\", \"Sedikit kecap manis\", \"Secukupnya Air\"]', '[\"Tumis bumbu iris aduk\\\" smp harum\", \"Masuk pindang, Air, gula, garam & royco masak smp mendidih & meresap\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(217, 2, 'Salmon Cream Blackpepper', 'Cara membuat Salmon Cream Blackpepper yang enak dan praktis untuk keluarga.', '[\"secukupnya salmon\", \"1 jamur shitake (boleh skip)\", \"1/2 dus fettucini (merk bebas)\", \"3 cabe rawit merah\", \"1 sendok lada hitam bubuk\", \"250 ml susu full cream\", \"secukupnya keju parut\", \"secukupnya daun bayam (boleh skip)\", \"secukupnya bawang bombay\", \"secukupnya bawang putih\", \"secukupnya margarin\", \"secukupnya penyedap jamur (bisa diganti dengan yg lain atau garam)\"]', '[\"Bersihkan salmon lalu potong dadu. sisihkan.\", \"Rebus pasta terlebih dahulu kurleb 7menit lalu sisihkan.\", \"Panaskan wajan. masukkan margarin lalu bawang bombay dan putih diamkan hingga wangi lalu masukkan salmon aduk hingga matang, lalu masukkan susu full cream dilanjut dengan keju. diamkan dahulu hingga mendidih. setelah itu masukkan bayam dan juga jamur shitake, aduk rata. lalu masukkan blackpepper dan juga penyedap. setelah itu aduk terus agak tidak menggumpal. karena aku suka yg kental (tanpa kuah ku diamkan sampe mengental) jika suka berkuah, koreksi rasa laku matikan kompor\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(218, 2, 'Sushi tuna pedas', 'Nikmati kelezatan Sushi tuna pedas dengan resep sederhana ini.', '[\"1 tuna kaleng\", \"4 lembar nori yg besar\", \"1 buah ketimun\", \"1 buah wortel\", \"1/2 kol\", \"7 buah cabe rawit merah\", \"2 bawang putih\", \"Maseko kaldu jamur secukup nya\", \"Garam\", \"Gula\", \"Minyak untuk menumis\", \"3 centong nasi\", \"Cuka/jeruk nipis\"]', '[\"Membuat isian tuna pedas : cingcang bawang putih, potong cabe rawit merah, lalu panaskan minyak dan tumis bawang putih dan cabe lalu masukan tuna kaleng beri sedikit garam dan kaldu jamur, koreksi rasa\", \"Nasi untuk sushi : nasi panas campur dgn cuka klo ngk ada bisa ganti jeruk nipis (klo aku) lalu beri garam dan gula, lalu aduk\", \"Timun potong memanjang, wortel potong seperti korek api, dan iris tipis kol\", \"Lalu letakan nasi di atas nori tipis2 sampai nori tertutup nasi, lalu susun isian timun, tuna, wortel dan kol, lalu gulung setelah itu potong.. dan sajikan.. dpt di nikmati dgn mayones\", \"Nb : pisau dalam keadaan basah dan pisau harus tajam agar mudah memotong nya\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(219, 2, 'Balado Ikan pari asap', 'Buat Balado Ikan pari asap yang nikmat dengan langkah-langkah mudah ini.', '[\"500 gr ikan asap apa aja (saya ikan pari)\", \"3 sdm minyak untuk menumis\", \"secukupnya Air\", \"secukupnya Gula putih/jawa\", \"10 buah cabe merah\", \"5 buah cabe rawit\", \"4 siung bawang putih\", \"5 siung bawang merah(iris tipis)\", \"1 cm jahe\", \"2 lmbar daun jeruk\", \"secukupnya Garam\", \"secukupnya Penyedap rasa\"]', '[\"Cuci ikan pari asap tiriskan n sisihkan\", \"Haluskan cabe,bawang putih dan jahe\", \"Panaskan minyak,Goreng irisan bawang merah sampai kekuningan lalu sisihkan sedikit buat taburan\", \"Masukkan bumbu halus,daun jeruk,tumis sampai bau harum\", \"Masukkan ikan pari,garam,penyedap,gula dan air secukupnya\", \"Tutup dan masak dg api kecil kurleb 10 menit sampai air tinggal sedikit (karna sy gx suka terlalu kering)\", \"Tes rasa dan setelah pas...taraaa...balado ikan pari asap siap disantap\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(220, 2, 'Sarden Balado', 'Cara membuat Sarden Balado yang enak dan praktis untuk keluarga.', '[\"1 kaleng sarden mackerel\", \"1 ons cabe keriting, giling halus\", \"3 siung bawang merah, iris tipis\", \"1 buah tomat, potong memanjang\", \"1/2 buah jeruk nipis, ambil airnya\", \"secukupnya Garam\", \"secukupnya Minyak untuk menggoreng\", \"Tambahan :\", \"3 buah kentang, potong memanjang\"]', '[\"Siapkan bahan-bahan yang dibutuhkan\", \"Pisahkan ikan sarden dengan sausnya.\", \"Goreng ikan sarden sampai harum kecoklatan. Hati-hati pada waktu menggoreng, lebih baik ditutup\", \"Gunakan minyak bekas menggoreng ikan. Tumis bawang sampai harum, masukkan tomat, dan cabe giling\", \"Masukkan saus sarden, aduk sampai mendidih\", \"Masukkan air jeruk nipis, masak sampai matang, cicip rasa...\", \"Di penggorengan terpisah, goreng kentang sampai matang\", \"Masukkan ikan dan kentang ke dalam saus sarden, bolak balik sebentar sampai semua terlumuri saus\", \"Siap di sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(221, 3, 'Ikan kuwe merah merona', 'Ikan kuwe merah merona - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"4 ekor ikan kuwe ukuran sedang\", \"2 buah tomat (potong 4 bagian)\", \"5 cabai merah (belah memanjang)\", \"2 lembar daun salam\", \"1 ruas lengkuas (geprek)\", \"1 batang serai (simpul, geprek)\", \"1 sdm air asam jawa\", \"2 gelas air (gelas belimbing)\", \"minyak untuk menumis\", \"haluskan :\", \"3 siung bawang putih\", \"4 siung bawang merah\", \"3 buah Cabai rawit\", \"1/2 sdt ketumbar\", \"1/2 ruas kunyit\", \"1/2 ruas jahe\", \"sejumput garam\"]', '[\"Cuci bersih ikan kuwe, kerat. kemudian rendam di air bumbu (air+bawang putih, garam)\", \"Goreng ikan hingga setengah matang.\", \"Haluskan bumbu halus.\", \"Panaskan minyak. tumis bumbu halus, masukan tomat cabai, lengkuas, serai daun salam\", \"Aduk rata, tunggu hingga wangi.\", \"Masukan air asam jawa, aduk sebentar dan tambahkan ikan yg sudah di goreng. cek rasa.\", \"Masukan air. aduk balik ikan tunggu hingga kuah menyusut dan mengental..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(222, 4, 'Ikan mas terbang sambal dabu-dabu', 'Resep praktis Ikan mas terbang sambal dabu-dabu yang bisa dicoba di rumah.', '[\"1 ekor ikan mas\", \"1 buah lemon\", \"Garam\", \"Lada\", \"Bawang putih bubuk\", \"7 cabe merah\", \"1 buah tomat merah\", \"5 bawang merah\"]', '[\"Bersihkan ikan mas dari sisik dan kotoran dengan membelah sedikit dibagian perutnya\", \"Potong ikan mas bagian kanan dan kirinya dipotong dari bagian ekor ke kepala jangan sampai putus. Cuci bersih dalam air mengalir.\", \"Masukkan ikan yang telah bersih ke dalam wadah lalu taburi dengan garam, lada, dan bawang putih. potong lemon menjadi 2 bagian, setengah bagiannya peras kemudian Balur ke ikan. Tunggu hingga 15 menit sembari kita siapkan sambal dabu-dabu.\", \"Potong bawang merah, cabai merah dan tomat. Masukkan ke dalam mangkuk kecil.\", \"Peras setengah lemon yang tersisa, tuangkan pada irisan sambal. Beri sedikit garam dan gula. Lalu aduk merata.\", \"Panaskan sedikit minyak. siram ke sambal lalu aduk hingga rata. Sambal dabu-dabu sudah siap dihidangkan.\", \"Panaskan minyak dalam wajan panci. (Minyaknya banyak agar ikan tercelup semua) Goreng ikan dengan memegang kepala ikan hingga ikan tercelup sempurna. Tunggu hingga ikan matang lalu angkat.\", \"Taruh ikan terbang di atas piring, kemudian siram dengan sambal dabu-dabu.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(223, 4, 'Patin Asam Pedas', 'Nikmati kelezatan Patin Asam Pedas dengan resep sederhana ini.', '[\"1 Ekor Ikan Patin\", \"2 Buah Tomat\", \"5 Buah Cabe Rawit\", \"1 Buah Jeruk Nipis\", \"3 Siung Bawang Merah\", \"2 Siung Bawang Putih\", \"500 ml Air\", \"Secukupnya Gula dan Garam\", \"Secukupnya Penyedap rasa\", \"Secukupnya Merica bubuk\", \"Secukupnya Daun Kemangi\"]', '[\"Bersihkan ikan patin dan potong-potong.\", \"Belah tomat menjadi 4 bagian, potong jeruk nipis dan ambil airnya,\", \"Cincang halus bawang merah dan putih kemudian goreng.\", \"Didihakan air masukkan ikan patin masak sampai empuk.\", \"Masukkan potongan tomat, irisan cabe, gorengan bawang serta perasan air jeruk, bumbui dengan gula, garam, penyedap rasa, dan merica bubuk. koreksi rasa.\", \"Masak sampai matang taburi daun kemangi, hidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(224, 3, 'Mangut Lele & Tempe', 'Buat Mangut Lele & Tempe yang nikmat dengan langkah-langkah mudah ini.', '[\"1/2 kg lele (goreng)\", \"1 papan tempe (potong)\", \"3 siung bawang putih\", \"4 siung bawang merah\", \"2 butir kemiri sangrai\", \"Seruas kunyit bakar\", \"2 bh cabe merah\", \"Secukupnya cabe rawit\", \"1 bh kencur\", \"2 lbr daun salam\", \"500 ml santan sedang\", \"Secukupnya air\", \"Gula garam kaldu bubuk\"]', '[\"Haluskan duo bawang, kemiri, kunyit, kencur, cabe merah, cabe rawit (optional). Kemudian tumis bumbu halus dan tambahkan daun salam.\", \"Masukkan air secukupnya. Beri gula garam kaldu bubuk. Tunggu mendidih\", \"Masukkan santan, aduk2 agar santan tdk pecah.\", \"Koreksi rasa.\", \"Masukkan lele & tempe. Masak dg api kecil agak lama agar bumbu meresap.\", \"Masukkan cabe rawit utuh.\", \"Angkat & sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(225, 3, 'Garang asem patin', 'Resep praktis Garang asem patin yang bisa dicoba di rumah.', '[\"1 ekor ikan patin potong jadi 4\", \"3 siung bawang putih\", \"3 butir kemiri\", \"1/2 sdt ketumbar\", \"Daun bawang\", \"1 buah bawang bombay\", \"3 buah tomat\", \"5 buah cabai rawit merah\", \"5 buah cabai hijau\", \"300 ml Santan kelapa\", \"Daun salam dan lengkuas\"]', '[\"Goreng ikan setengah matang/sesuai selera\", \"Haluskan bawang putih, ketumbar, dan kemiri lalu tumis bersama dengan daun salam dan lengkuas yang di geprek.\", \"Potong tomat, daun bawang, bawang bombai dan cabai. Masukan kedalam tumisan bumbu halus tunggu sampai layu lalu tambahkan santan. Beri garam, gula secukupnya, tes rasa, setelah mendidih angkat.\", \"Siapkan daun pisang yang muda untuk membungkus, isi masing masing satu potong siram dengan kuah lalu bungkus dan kukus ± 20 menit\", \"Garangasem sudah siap di hidangkan dengan nasi hangat 😍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(226, 3, 'Pepes Tuna Kemangi', 'Buat Pepes Tuna Kemangi yang nikmat dengan langkah-langkah mudah ini.', '[\"1/2 kg tuna potong kecil2\", \"Bumbu\", \"7 butir bawang merah\", \"5 siung bawang putih\", \"2 butir kemiri\", \"3 cabe besar\", \"2 cabe kecil(jika suka pedas ditambahin aja)\", \"1 buah tomat\", \"1 ruas jahe\", \"2 ruas kunyit\", \"1 sdt terasi bakar\", \"Secukupny garam\", \"Pelengkap\", \"Kemangi\", \"Daun salam\", \"Daun pisang\"]', '[\"Haluskan semua bumbunya\", \"*\", \"*\", \"*kukus hingga matang\", \"*bakar 10menit\", \"Slamat menikmati😊😄\", \"Campur bumbu +ikan tuna+ kemangi+daun salam\", \"Bungkus dg daun pisang\", \"Kukus hingga matang\", \"Panggang selama 10 menit\", \"Angkat dinginkan sajikan dg nasi panas 😁\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(227, 4, 'Lele kuah pedas', 'Resep Lele kuah pedas ala rumahan yang dijamin menggugah selera.', '[\"500 gr ikan lele\", \"10 siung bawang merah\", \"3 siung bawang putih\", \"2 bj cabe merah besar\", \"25 bj cabai rawit\", \"3 lembar daun jeruk\", \"1 ruas lengkuas\", \"65 ml Santan kara\", \"2 gelas air\", \"1 bks kaldu jamur (optional)\", \"secukupnya Gula & garam\"]', '[\"Cuci bersih lele dan kerat\\\" bagian samping nya\", \"Rendam dalam air garam 30 mnt\", \"Goreng lele sampai agak kering. Tiriskan dr penggorengan\", \"Haluskan semua bumbu kecuaki daun jeruk dan lengkuas\", \"Tumis bumbu yg sdh dihaluskan sampai harum lalu masukkan lengkuas & daun jeruk\", \"Masukkan lele yg sdh digoreng.\", \"Tambahkan santan kara dan air\", \"Aduk rata lalu masukkan gula garam dan kaldu jamur\", \"Koreksi rasa dan tunggu mendidih\", \"Matikan api dan siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(228, 2, 'Ikan bawal sauce padang', 'Resep Ikan bawal sauce padang ala rumahan yang dijamin menggugah selera.', '[\"1 ekot ikan bawal sedang...bersihkan\", \"3 buah cabe merah keriting...haluskan\", \"3 buah cabe rawit merah....iris2\", \"4 siung bawang merah...cincang halus\", \"1 siung bawang putih cincang halus\", \"1 siung bawang bombay ukuran sdang....iris\", \"1 saset sauce tiram\", \"4 saset sauce cabe ekstra pedas\", \"2 saset sauce tomat\", \"1 sdt tepung maizena\", \"secukupnya air\", \"secukupnya minyak goreng\"]', '[\"Setelan ikan di bersihkan beri garam dan air jeruk nipis...diamkan selama 10 menit...kemudian ikan goreng sampai setengah kering.....angkat dan tiriskan.\", \"Tumis bawang merah dan bawang putih sampe harum, masukin cabe merah halus tumis sampai matang...masukan bawang bombay, sauce tiram, sauce cabe, sauce tomat dan tambahkan air secukupnya.\", \"Masukan ikan yg sudah di goreng...aduk rata tunggu sampai meresap, jangn lupa tes rasa....jangn lupa masukan cabe rawit merah yg sudah di iris.\", \"Sudah mantap angkat dan sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(229, 4, 'Ikan gembung goreng bumbu', 'Resep praktis Ikan gembung goreng bumbu yang bisa dicoba di rumah.', '[\"2 ekor ikan gembung\", \"2 sdm tepung beras\", \"1 sdt ketumbar bubuk\", \"1/2 sdt Lada bubuk\", \"Garam\", \"Kaldu jamur\", \"👉 bumbu halus\", \"3 siung bawang putih\", \"1/2 ruas jahe\", \"1/2 ruas kunyit\"]', '[\"Bersihkan ikan, sisit2. Campur kan semua bahan balur ke ikan hingga merata. taruh di wadah tertutup diam kan selama 15 - 30 menit.\", \"Goreng ikan dengan api kecil hingga matang.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(230, 4, 'Kari Gulai Gurame', 'Sajian ikan nikmat: Kari Gulai Gurame yang mudah dibuat.', '[\"6 ekor ikan gurame bersihkan dan goreng\", \"2 sdm bumbu kari/gulai instant\", \"2 lembar daun jeruk purut\", \"1 batang serai memarkan\", \"1 buah santan instant (saya pake KARA)\", \"Secukupnya garam\", \"Secukupnya gula\", \"2 buah kapulaga\", \"2 cm kayu manis\", \"1 sdt kaldu bubuk\", \"6 buah cabai rawit dihaluskan\", \"1/2 buah jeruk nipis\", \"300 ml air\"]', '[\"Siapkan wajan dan sedikit minyak untuk menumis. Tumis bumbu kari instant sampai harum.\", \"Masukkan daun jerut purut, serai, kayu manis dan kapulaga. Tumis hingga harum. Masukkan air tunggu hingga mendidih.\", \"Masukkan garam, gula, cabai rawit halus dan perasan air jeruk nipis. Terakhir masukkan santan.\", \"Tunggu kuah santal mendidih. Masukkan ikan gurame yang sudah di goreng ke dalam kuah. Balik balik agar meresap bumbunya. Tutup selama 5 menit. Sajikan beraama nasi panas.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(231, 3, 'Dori Fillet Bawang Goreng', 'Cara membuat Dori Fillet Bawang Goreng yang enak dan praktis untuk keluarga.', '[\"1 buah ikan dori fillet\", \"1 buah jeruk nipis\", \"Tepung bumbu serbaguna (sy pk Sasa)\", \"Secukupnya garam dan air es\", \"Bawang Goreng :\", \"15 siung bawang merah\", \"1 sdm terasi sisir\", \"6 buah cabe kecil\", \"Minyak goreng\", \"secukupnya Garam\"]', '[\"Karena saya pakai dori frozen, jadi saya tunggu hingga benar2 mencair dan segera mencucinya bersih.\", \"Potong dori sesuai selera, taburi garam secukupnya dan beri perasan jeruk nipis. Diamkan 15menit.\", \"Buat tepung basah dan tepung kering. Cairkan tepung basah dg air es.\", \"Celupkan dori ke dalam tepung basah, kemudian tepung kering. bisa diulang\", \"Goreng dalam minyak panas.\", \"Bawang Goreng : iris agak tebal bawang merah, cabe dan sisir tipis terasi.\", \"Panaskan minyak agak banyak, masukkan bawang merah, cabe dan terasi. tambahkan garam.\", \"Aduk hingga bawang merah layu, Angkat\", \"Hidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(232, 3, 'Ikan Gurame Acar Kuning', 'Sajian ikan nikmat: Ikan Gurame Acar Kuning yang mudah dibuat.', '[\"2 Ekor Ikan Gurame (Potong Jadi 2)\", \"1 Buah Timun\", \"5 Buah Cabe Merah\", \"10 Buah Cabe Rawit\", \"2 Batang Serai\", \"3 Lembar Daun Jeruk\", \"3 Lembar Daun Salam\", \"1 bungkus penyedap rasa ayam\", \"Daun Bawang\", \"Jeruk Nipis\", \"Bumbu Halus\", \"10 Buah Bawang Merah\", \"8 Buah Bawang Putih\", \"3 Buah Kemiri\", \"1 Sdt Merica\", \"2 Ruas Kunyit\", \"2 Ruas Jahe\", \"Secukupnya Garam\"]', '[\"Lumuri Ikan yg sudah di bersikan dan di potong dengan jeruk nipis + garam selama 15 menit\", \"Goreng ikan jangan terlalu garing. yg penting matang (Goreng di minyak panas, agar tidak lengket)\", \"Tumis Bumbu Halus + Serai yg sudah di geprek + daun salam + daun jeruk + cabe merah + cabe Rawit + daun bawang (yg sudah di potong2)\", \"Ketika tumisan sudah harum dan matang. masukkan timun yg sudah di potong bentuk persegi panjang (tanpa biji)\", \"Masukkan garam + penyedap rasa\", \"Kalau sudah pas. masukkan ikan gurame yg sudah di goreng\", \"Aduk sampai rata.\", \"Siap dimakan!\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(233, 2, 'Sup Ikan Patin', 'Nikmati kelezatan Sup Ikan Patin dengan resep sederhana ini.', '[\"2 ekor ikan patin (bagian kepala dan ekor saja)\", \"6 siung bawang merah\", \"2 siung bawang putih\", \"10-15 Cabe rawit\", \"1 buah tomat besar\", \"Kunyit\", \"Jahe\", \"Laos\", \"1 batang Serai\", \"2 lembar daun salam\", \"3 lembar daun jeruk\", \"secukupnya daun bawang + seledri\", \"secukupnya garam, gula dan penyedap\"]', '[\"Bersihkan ikan, lumuri dengan garam dan air jeruk nipis (asam jawa/cuka makan secukupnya), diamkan selama 15-30 menit. Lalu dibilas.\", \"Iris duo bawang, cabe rawit, tomat, daun bawang dan seledri. Sisihkan.\", \"Geprek kunyit, jahe, laos dan serai. Sisihkan.\", \"Tumis duo bawang hingga sedikit layu. masukkan cabe rawit, daun salam, daun jeruk, tomat, kunyit, jahe, laos dan serai. Masak hingga harum.\", \"Masukkan air, tunggu mendidih baru masukkan ikan.\", \"Setelah 15 menit balik ikan, lalu masukkan irisan daun bawang + seledri.\", \"Tambahkan garam, gula dan penyedap secukupnya. Masak hingga matang.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(234, 2, 'Tim ikan kakap merah ala fe\'', 'Nikmati kelezatan Tim ikan kakap merah ala fe\' dengan resep sederhana ini.', '[\"2 ekor ikan kakap merah\", \"1 sendok teh merica\", \"1 sendok teh garam\", \"1 buah jeruk nipis peras airnya\", \"2 lembar daun bawang iris serong\", \"1 lembar daun jeruk iris\", \"1 buah wortel potong korek api\", \"5 buah cabe rawit setan utuh\", \"5 buah belimbing wuluh iris serong\", \"Bumbu cair :\", \"1 sdm saus raja rasa\", \"1 sdm saus perendam seafood lee kum kee\", \"1 sdm saus tiram\", \"1 sdm kecap asin\", \"1 sdm kecap ikan\", \"1 sdm minyak wijen\", \"secukupnya Garam\", \"secukupnya Gula\", \"secukupnya Olive oil untuk menumis\", \"Bumbu iris :\", \"1 siung bawang bombay kecil\", \"3 siung bawang putih geprek lalu cincang\", \"1 ruas jari jahe bakar sebentar, kupas, geprek, cincang\"]', '[\"Lumuri ikan kakap yang sudah dicuci bersih dengan garam, merica dan air jeruk nipis sebentar lalu cuci bersih dan kukus hingga matang. Buang air kukusan yang ada didalam mangkok jika muncul.\", \"Sesudah matang, beri sebagian daun bawang diatas ikan kukus. Tutuo kukusan. Simpan sebagian untuk ditumisan.\", \"Tumis bumbu yang diiris halus dengan 1 sendok makan olive oil hingga harum. Masukkan semua bumbu cair. Tambahkan wortel, belimbing wuluh, cabe2an.\", \"Jika perlu tambahkan air. Koreksi rasa. Lalu siramkan diatas ikan kukus tadi. Taburkan sisa daun bawang diatasnya.\", \"Kukus sebentar ikan dengan bumbu kuahnya sekitar 5 menit saja agar bumbu meresap.\", \"Sajikan hangat dengan nasi putih.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(235, 4, 'Ikan mas cabe ijo ala fe\'', 'Resep Ikan mas cabe ijo ala fe\' yang lezat dan mudah dibuat di rumah.', '[\"4 ekor ikan mas sedang\", \"1 sendok teh garam\", \"1 buah jeruk nipis peras airnya\", \"1 bungkus tempe potong2\", \"Bumbu ulek halus :\", \"7 siung bawang merah iris tipis\", \"5 siung bawang putih iris tipis\", \"1 ruas kecil kencur\", \"Bumbu tidak diulek :\", \"5 cabe hijau keriting iris serong\", \"5 cabe rawit setan utuh\", \"1 iris lengkuas geprek\", \"1 lembar daun salam\", \"3 lembar daun jeruk\", \"1/2 sendok teh garam\", \"1 sendok teh gula\", \"1/2 sendok teh kaldu bubuk instant jika suka\"]', '[\"Lumuri ikan dengan garam & air jeruk nipis lalu goreng setengah kering. Tiriskan.\", \"Tumis bumbu halus dengan bumbu lain yang tidak diulek hingga harum lalu tambahkan air. Beri gula, garam & kaldu bubuk jika suka sesuai selera. Koreksi rasa. Masukkan tempe potong & ikan. Aduk rata & diamkan di api kecil hingga air berkurang.\", \"Matikan api. Hidangkan. Siap disantap dengan nasi & kerupuk.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(236, 3, 'Pancake Kimchi Tuna', 'Cara membuat Pancake Kimchi Tuna yang enak dan praktis untuk keluarga.', '[\"1 cup terigu (+-120gr)\", \"1/3 cup tepung beras (+- 40g)\", \"1 cup kimchi\", \"1/2 kaleng tuna\", \"1/2 biji bawang bombay\", \"1/2 sdt garam\", \"Secukupnya air\", \"Secukupnya minyak untuk menggoreng\"]', '[\"Siapkan semua bahan. Untuk 1 cup kimchi pas 1 kemasannya.\", \"Keluarkan kimchi dari kemasannya, potong kecil-kecil. Untuk tunanya juga di benyek-benyek dengan garpu. Cincang bawang bombay. Kemudian semua bahan dicampur jadi satu, tuang air sedikit demi sedikit hingga menjadi adonan kental. Seperti adonan untuk bikin gorengan.\", \"Panaskan wajan, tambahkan sedikit minyak, seperti untuk menggoreng telur dadar tapi sedikit lebih banyak. Sendokan adonan ke wajan, tipiskan. Ukuran pancakenya sesuai selera aja. Setelah bagian bawahnya mulai matang & terlihat coklat, balik. Masak hingga mateng. Angkat. Sajikan..😊.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(237, 3, 'Ikan lele masak kuah', 'Nikmati kelezatan Ikan lele masak kuah dengan resep sederhana ini.', '[\"1/2 kg ikan lele(dpt 2 yg gede)\", \"jeruk nipis\", \"minyak goreng\", \"bumbu lumuran\", \"1 sdt ketumbar\", \"seruas kunyit\", \"4 siung bawang putih\", \"garam\", \"bumbu iris\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"5 buah cabe rawit (sesuai selera)\", \"1/2 tomat yg kecil\", \"santan kelapa (kara)\", \"kecap (kecap abc)\", \"gula (gula merah)\"]', '[\"Cuci bersih ikan,potong2 sesuai selera,lumurin perasan jeruk nipis dan bumbu lumuran ikan,sisihkan\", \"Panaskan minyak dan goreng ikan sampai matang dan kering,sisihkan\", \"Panaskan minyak,tumis bumbu iris sampai bau harum,tambahkan air sedikit buat matengin bumbu,,,\", \"Masukan santan kelapa,aduk merata kemudian masukan ikan dan tambahkan kecap,gula,garam\", \"Masak sampai matang dan koreksi rasa\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(238, 4, 'Sarden + sosis', 'Sajian ikan nikmat: Sarden + sosis yang mudah dibuat.', '[\"1 kaleng sarden kecil\", \"2 sosis So nice ayam\", \"3 bawang merah\", \"2 bawang putih\", \"3 cabe rawit merah\", \"1 sdm Gula pasir\", \"secukupnya Air\", \"secukupnya Blue band\"]', '[\"Potong2 bawang merah putih, sarden dan cabe.\", \"Buka sarden\", \"Panaskan blue band dan masukan bawang + sosis masukan cabe dan beri gula pasir lalu siram menggunakan air. Tunggu hingga masak masukan sarden dan tunggu hingga matang.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(239, 4, 'Bawal Pedas Merah ala Nani', 'Sajian ikan nikmat: Bawal Pedas Merah ala Nani yang mudah dibuat.', '[\"1 kg ikan bawal, cuci bersih\", \"1 buah tempe, potong sesuai selera(g pke jg gpp)\", \"Bumbu1:\", \"4 buah bawang putih\", \"1,5 cm kunyit\", \"1/2 sdt garam\", \"50 ml air\", \"Bumbu 2:\", \"10 siung bawang merah\", \"5 siung bawang putih\", \"15 buah cabe rawit atau sesuai selera\", \"3 buah cabe merah besar\", \"1 buah tomat, potong jd 4 (utk menghilangkan amis)\", \"1 sdt garam\", \"1 sdt gula\", \"1 cm lengkuas\", \"2 lembar daun jeruk purut\", \"secukupnya Daun kemangi\", \"50 ml santan kental\", \"500 ml Air panas\"]', '[\"Baluri ikan bawal dengan bumbu 1 yg sudah dihaluskan. Simpan dlm kulkas +-1 jam. Goreng hingga matang. Tiriskan\", \"Goreng bawang merah, putih, cabai besar, rawit. Tiriskan lalu haluskan dengan garam\", \"Tumis bumbu halus sbentar. Beri air. Masukkan lengkuas, daun jeruk purut dan tomat. Tunggu sampai mendidih\", \"Masukkan ikan bawal, tempe dan gula. +- 5 menit. Masukkan daun kemangi.\", \"Tunggu +-5 menit, masukkan santan. Aduk2 +- 1 menit. Koreksi rasa.\", \"Selamat mencoba 😘😘\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(240, 4, 'Ikan tongkol segar kuah merah', 'Ikan tongkol segar kuah merah dengan cita rasa segar khas laut.', '[\"1 ekor ikan tongkol segar\", \"3 lembar daun salam\", \"1 sereh (geprek)\", \"1 buah jeruk nipis\", \"2 lembar daun jeruk\", \"Secukupnya gula dan garam\", \"3 siung bawang merah (iris)\", \"1/2 buah bawang bombay (iris)\", \"Bumbu halus :\", \"7 siung bawang merah\", \"4 siung bawang putih\", \"2 buah tomat\", \"3 butir kemiri\", \"4 cm jahe\", \"7 buah cabe merah\", \"3 buah cabe rawit (optional)\"]', '[\"Cuci ikan, lumuri dengan jeruk nipis, biarkan beberapa saat, bilas.\", \"Setelah bilas beri garam, aduk rata, lalu goreng, angkat, sisihkan.\", \"Tumis bumbu halus, masukkan daun salam, sereh, daun jeruk, bawang merah iris dan bawang bombay iris. Tumis hingga harum.\", \"Masukkan ikan yang sudah digoreng. Aduk rata. Tambahkan air. Beri gula, garam. Tunggu hingga mendidih, koreksi rasa. Sajikan 😊. Selamat menikmati.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(241, 4, 'Gule lele plus2', 'Resep Gule lele plus2 ala rumahan yang dijamin menggugah selera.', '[\"500 gr ikan lele\", \"1 sachet bumbu gulai instan\", \"1 santan kara kecil\", \"2 buah tahu\", \"1 papan tempe\", \"1 genggam buncis\", \"2 biji tomat\"]', '[\"Bersihkan ikan lele,goreng.sisihkan\", \"Tahu goreng,setengah matang.sisihkan\", \"Rebus bumbu gulai dg 500 ml air.setelah mendidih masukan tempe\", \"Setelah mendidih kembali,masukan tahu,buncis dan tomat.\", \"Tunggu mendidih lagi.setelah mendidih masukan ikan lele dan santan.\", \"Tes rasa,apabila dirasa kurang,dapat ditambah bumbu penyedap.tunggu mendidih kembali\", \"Setelah mendidih matikan kompor.sajikan dengan nasi putih.\", \"Enak dimakan sewaktu masih hangat,😘😉\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(242, 3, 'Ikan kembung kuah santan', 'Sajian ikan nikmat: Ikan kembung kuah santan yang mudah dibuat.', '[\"10 ekor ikan kembung (bisa diganti ikan lainnya)\", \"1 buah tomat merah, potong2\", \"2 buah daun jeruk\", \"1 buah jeruk nipis\", \"600 ml santan (saya pakai 2 santan kara 65ml ditambah 370ml air)\", \"3 lembar daun salam\", \"Secukupnya garam\", \"Secukupnya gula\", \"Bumbu halus :\", \"4 bh cabe merah\", \"6 siung bawang merah\", \"2 siung bawang putih\", \"2 kemiri\", \"4 cm kunyit\", \"2 cm jahe\"]', '[\"Cuci ikan, lalu kucuri dengan jeruk nipis. Biarkan beberapa saat, bilas.\", \"Setelah bilas, beri 1 1/2 sdt garam, aduk, lalu goreng.\", \"Tumis bumbu halus hingga wangi, tambahkan daun jeruk, aduk. Setelah itu masukkan santan.\", \"Bila santan mulai mendidih, masukkan ikan dan tomat. Beri garam dan gula. Koreksi rasa.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(243, 2, 'Sarden Tomat', 'Buat Sarden Tomat yang nikmat dengan langkah-langkah mudah ini.', '[\"1 kaleng ikan sarden tanpa bumbu\", \"2 buah tomat\", \"1 buah cabai paprika\", \"3 siung bawang putih\", \"1/8 sendok teh Garam\"]', '[\"Bawang putih dikupas dan dirajang tipis-tipis. Demikian juga paprika, rajang kecil-kecil.\", \"Potong tomat menjadi 4 atau 8 bagian.\", \"Jika tersedia microwave, panaskan rajangan bawang putih dan paprika, dan tomat ke microwave. Set ke level medium dan nyalakan kurang lebih 3 menit. Jika tidak ada microwave, langsung ke langkah 4.\", \"Tumis bawang putih, paprika, dan tomat dengan minyak sedikit dan api kecil. Aduk-aduk sehingga tomat mencair seperti saos. Bila perlu tambahkan air sedikit.\", \"Masukkan ikan sarden ke dalam tumisan. Campurkan tumisan bawang putih, paprika, tomat ke ikan sarden. Tambahkan garam secukupnya (kira-kra 1/8 sendok teh)\", \"Masak sampai kira-kira 5 menit, sampai terasa gurih dan agak pedas.\", \"Masakan selesai dan siap disajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(244, 2, 'Ikan nila goreng praktis', 'Cara membuat Ikan nila goreng praktis yang enak dan praktis untuk keluarga.', '[\"1 kg Ikan nila\", \"1 buah jeruk nipis/lemon\", \"secukupnya Garam\", \"Minyak untuk menggoreng\"]', '[\"Bersihkan Ikan nila di sayat-sayat lalu tiriskan supaya sisa air tidak terlalu banyak\", \"Perasi jeruk nipis keseluruh bagian ikan nila. Lalu taburkan juga garam keseluruh bagian ikan. Diamkan sekitar 1 jam. Lalu goreng dengan minyak panas. Siap disantap selagi panas\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(245, 2, 'Mujair nyat-nyat khas Bali', 'Sajian Mujair nyat-nyat khas Bali yang praktis dan lezat untuk dinikmati bersama.', '[\"2 ekor ikan mujair yg sudah di panggang\", \"Minyak goreng\", \"1 Buah jeruk nipis\", \"15 cabe rawit\", \"2 cabe merah besar\", \"1 cm kunyit\", \"1 cm kencur\", \"1 buat tomat ukuran besar\", \"4 siung bawang putih\", \"8 siung bawang merah\", \"secukupnya Terasi\", \"1 Sdm kacang tanah goreng\", \"1 Sdt lada bubuk\", \"1 Sdt garam\", \"1 Sdt gula pasir\", \"200 ml air matang\"]', '[\"Ulek halus kunyit, kencur, kacang, bawang putih,cabe merah besar,terasi\", \"Masukan cabe rawit,bawang merah ulek kasar, iris tomat tipis lalu ulek kasar\", \"Tumis bumbu hingga matang, masukan air, biarkan agak mendidih masukan garam, landa, gula pasir, dan sedikit perasan jeruk nipis, masukan ikan lalu kecilan api biarkan bumbu meresap,lalu sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(246, 4, 'Gulai ikan gabus panggang', 'Resep praktis Gulai ikan gabus panggang yang bisa dicoba di rumah.', '[\"600 gr ikan gabus\", \"5 siung bawang putih\", \"5 siung bawang merah\", \"Bawang bombay\", \"1 ruas kunyit\", \"1 ruas jahe\", \"1/2 sdt ketumbar\", \"2 btr kemiri\", \"Serai, daun jeruk\", \"1 sachet kara 65ml\", \"Garam\", \"Gula\", \"Penyedap\", \"1 buah jeruk nipis\", \"1 buah cabe\", \"1 buah tomat\"]', '[\"Potong ikan jd 3bagian. Cuci bersih.beri garam dan jeruk nipis. Lalu panggang sampai kecoklatan\", \"Iris bawang bombay.Ulek cabe,kunyit, ketumbar,bawang merah, bawang putih, kemiri dan jahe.\", \"Tumis bumbu halus. Tambah serai dan daun jeruk.masukan santan. Tambah gula,garam,penyedap.masukan ikan yg sudah d bakar.cek rasa.beri irisan bawang bombay dan tomat.aduk sebentar. Angkat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(247, 2, 'Tongkol suwir', 'Cara membuat Tongkol suwir yang enak dan praktis untuk keluarga.', '[\"2 ikan tongkol\", \"15-20 cabai hijau (sesuai selera)\", \"5 buah cabai keriting\", \"15 bawang merah\", \"2 bawang putih\", \"2 buah tomat\", \"Minyak untuk menumis\", \"secukupnya Garam\", \"bila perlu Penyedap rasa\"]', '[\"Rebus/kukus ikan tongkol yg sudah dibersihkan, sampai masak (kurleb 10menit)\", \"Iris cabai ijo dan bawang merah, tomat, sisihkan. Kemudian haluskan bawang putih dan cabai keriting, tambahkan garam\", \"Suwir\\\" ikan yg telah dimasak tadi dan sisihkan\", \"Kemudian tumis bumbu halus sampai harum dan masukkan tomat, cabai dan bawang tadi\", \"Tambahkan suwiran ikan, jangan lupa cek rasanya. Jika butuh penyedap rasa bisa ditambahkan.\", \"Masak sampai tercampur rata dan hidangkan\", \"Selamat mencoba 😘\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(248, 4, 'Tumis sarden telur ceplok ala fe\'', 'Tumis sarden telur ceplok ala fe\' dengan cita rasa segar khas laut.', '[\"1 kaleng sarden makarel besar\", \"3 butir telur diceplok\", \"5 siung bawang merah iris tipis\", \"3 siung bawang putih iris tipis\", \"5 buah cabe rawit merah iris serong\", \"5 buah cabe hijau keriting iris serong\", \"1 lembar daun salam remas\", \"1 iris lengkuas geprek\", \"1 iris jahe geprek\", \"1 sendok makan gula aren/jawa iris\", \"100 ml air\"]', '[\"Buka kaleng sarden ukuran besar. Sisihkan. Sebaiknya pakai kaleng ukuran besar karena ukuran ikannya juga besar.\", \"Tumis semua bumbu, bawang merah, bawang putih, salam, lengkuas, jahe dengan sedikit olive oil hingga harum. Masukkan aneka cabe iris. Beri air. Masukkan gula. Aduk rata. Koreksi rasa. Saya tidak tambahkan garam karena sarden sudah cukup asin tapi jika merasa kurang asin boleh silahkan tambahkan garam sesuai selera. Jika suka penyedap silahkan. Saya tidak pakai.\", \"Masukkan semua isi 1 kaleng sarden, aduk rata. Masukkan telur ceplok aduk rata. Aduk hingga air berkurang & bumbu terserap sempurna.\", \"Matikan api. Siap disajikan sebagai lauk dengan nasi & kerupuk. Selamat mencoba.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(249, 2, 'Ikan nila kuah', 'Resep praktis Ikan nila kuah yang bisa dicoba di rumah.', '[\"2 ekor ikan nila\", \"Jeruk nipis\", \"Bumbu halus\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"2 ruas kunyit (dibakar)\", \"4 bh cabe merah besar (3 bh dihaluskan 1 bh di potong2)\", \"2 bh cabe rawit (sesuai selera)\", \"1 ruas jahe\", \"3 butir kemiri (disangrai)\", \"Bahan tambahan\", \"1 ruas lengkuas (memarkan)\", \"1 batang sereh (memarkan)\", \"3 lembar daun salam\", \"3 lembar daun jeruk\", \"2 bh tomat uk kecil (potong2)\", \"Secukupnya garam\", \"Secukupnya air\", \"Secukupnya minyak goreng\", \"Penyedap rasa (me:skip)\"]', '[\"Potong2 ikan nila 1 ekor potong jd 2. Beri perasan jeruk nipis dan garam diamkan sekitar kurleb 10 menit. Setelah itu cuci bersih\", \"Blender bumbu halus\", \"Panaskan minyak kemudian tumis bumbu halus setelah tercium aroma harum masukkan bumbu tambahan kecuali tomat serta masukkan potongan cabe merah besar.aduk2\", \"Tambahkan air lalu masukkan ikan nila hingga terendam seluruh ikan nila\", \"Aduk perlahan, setelah ikan agak matang masukkan tomat dan beri garam\", \"Cek kematangan ikan nila dan test rasa\", \"Siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(250, 4, 'Iwak lundu betu\'up a.k.a tumis ikan keting #herinwidodo', 'Resep Iwak lundu betu\'up a.k.a tumis ikan keting #herinwidodo ala rumahan yang dijamin menggugah selera.', '[\"1 kg ikan lundu potong kepala\", \"10 siung bawang putih\", \"7 siung bawang merah\", \"3 batang serai\", \"20 buah cabe rawit\", \"1 ruas kunyit\", \"3 buah cabe merah iris serong\", \"3 buah cabe hijau iris serong\", \"2 buah tomat potong2\", \"5 lembar daun jeruk\", \"Secukupnya minyak\", \"Secukupnya air\", \"Secukupnya garam\", \"1 sdt asam jawa tanpa biji\"]', '[\"Haluskan bawang merah, bawang putih, serai, kunyit, cabe rawit, asam jawa\", \"Panaskan minyak, masukkan daun jeruk nipis, lalu masukkan bumbu halus\", \"Tumis spi harum, lalu masukkan ikan lundu, aduk rata lalu tutup wajan sampai mendidih\", \"Tambahkan garam, potongan cabe dan tomat, aduk rata lalu tutup kembali\", \"Paskan rasa, iwak lundu betu\'ip siap disantap menyertai nasi putih panas\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(251, 4, 'Pindang tongkol kuah santan', 'Sajian Pindang tongkol kuah santan yang praktis dan lezat untuk dinikmati bersama.', '[\"Bahan utama :\", \"2 ekor ikan tongkol (goreng setengah matang dan potong2 sesuai selera) me beli yg sudah matang\", \"Bahan pelengkap/bumbu :\", \"2 buah serai (geprek kasar kepalanya)\", \"5 lembar daun salam\", \"1 buah lengkuas (di iris kemudian di geprek kasar)\", \"3 buah cabai hijau besar (di iris)\", \"5 siung bawang merah\", \"5 butir kemiri\", \"5 buah cabai merah keriting\", \"5 buah cabai rawit merah (cabe Jawa) sesuai selera..me suka pedas\", \"1 sdt garam (secukupnya)\", \"1/2 bungkus kaldu penyedap rasa ayam (sesuai selera)\", \"2 buah kunyit\", \"65 ml santan kental (kara yg kecil)\", \"2 gelas 1/2 air minum (gelas belimbing)\"]', '[\"Haluskan/ulek semua bahan bumbu jd satu bersama garam kecuali cabai hijau, daun salam, serai dan lengkuas yg sudah di geprek\", \"Tumis bumbu yg sudah di haluskan​ hingga setengah matang kemudian masukkan cabai hijau iris, daun salam, serai dan lengkuas yg sudah di geprek/memarkan masak hingga berubah warna sedikit kecoklatan\", \"Lalu masukkan air aduk rata kemudian masukkan ikan tongkol yg sudah di goreng setengah matang masak hingga mendidih\", \"Setelah matang/tercium aromanya tambahkan bumbu penyedap rasa secukupnya sambil di cicipi (jgn sampai keasinan)\", \"Terakhir masukkan santan aduk2 sebentar (kurang lebih 2 menit) agar santan tidak pecah kemudian angkat dan sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(252, 3, 'Tuna kecap dengan buncis dan terong goreng', 'Resep Tuna kecap dengan buncis dan terong goreng yang lezat dan mudah dibuat di rumah.', '[\"200 grm tuna potong kecil dadu, goreng\", \"1 terong ungu potong kecil panjang oreng\", \"15 buncis potong panjang, goreng\", \"1/2 tomat besar\", \"10 cabe hijau\", \"5 cabe merah\", \"2 bawang merah\", \"2 bawang putih\", \"5 sendok makam kecap\", \"Secukupnya garam, merica, gula\", \"1 daun salam\", \"3 sendok makan minyak goreng\"]', '[\"Iris bawang merah, bawang putih, cabe merah, cabe hijau, dan potong dadu tomat.\", \"Panaskan minyak, lalu tumis bahan yang telah di iris dan masukkan daun salam. Tunggu hingga layu dan harum.\", \"Masukkan kecap, garam, merica dan gula, jika terlalu kering tambahkan air sedikit saja.\", \"Jika telah mendidih, masukkan tuna, buncis dan terong yang telah di goreng. Aduk2 hingga semua kecampur dan matikan api kompor.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(253, 3, 'Gurame Kecap', 'Sajian ikan nikmat: Gurame Kecap yang mudah dibuat.', '[\"5 ekor ikan gurame\", \"2 buah tomat\", \"5 siung bawang putih\", \"1 siung bawang bombay\", \"5 siung bawang merah\", \"2 cm jahe keprek\", \"1 batang serai\", \"3 lembar daun salam\", \"1 sdt merica\", \"5 sdm kecap manis\", \"1 sdm saus tiram\", \"5 biji cabai rawit potong kecil kecil\", \"Secukupnya daun kemangi\", \"Secukupnya gula\", \"Secukupnya garam\", \"250 ml air\"]', '[\"Bersihkan ikan lalu lumuri garam secukupnya. Diamkan lalu goreng. Tiriskan\", \"Haluskan bumbu bawang merah, bawang putih, merica. Tumis bersama irisan bawang bombay sampai harum. Masukkan potongan tomat\", \"Masuk kan 250 ml air. Biarkan hingga mendidih. Masukkan daun salam, serai, cabai rawit dan jahe keprek. Masukkan juga gula, garam, saus tiram dan kecap. Aduk sampai harum.\", \"Setelah mendidih, masukkan ikan gurame yang sudah di goreng tadi. Balik balik agar bumbu meresap dan ikan berwarna hitam pekat.\", \"Masukkan daun kemangi diatasnya. Tutup wajan selama 10 menit. Bolak balik ikan nya SECARA PERLAHAN agar tidak hancur dan meresap. Matikan kompor.\", \"Selesai, siap sajikan dengan nasi panas. Mak nyusss\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(254, 4, 'Kakap goreng asam saus bawang', 'Resep Kakap goreng asam saus bawang yang lezat dan mudah dibuat di rumah.', '[\"1 kg ikan kakap\", \"Bawang merah\", \"Bawang putih\", \"Bawang bombay\", \"Cabe gendot dan rawit (optional)\", \"Wortel\", \"Garam\", \"Gula\", \"Lada bubuk\", \"Penyedap rasa\", \"Saos sambal\", \"Tepung maizena\", \"Jeruk nipis\"]', '[\"Cuci bersih ikan kakap kemudian lumuri dengan jeruk nipis dan garam. Tunggu 10menit kemudian goreng kering. Sisihkan.\", \"Iris tipis bawang merah dan bawang bombay Jika ingin pedas tambahkan cabe gendot dan cabe their sesuai Selera. Cincang halus bawang putih.\", \"Iris wortel dengan posisi memanjang.\", \"Tumis bawang merah putih bombay dan cabe yang sudah dirajang tunggu hingga harum kemudian tambahkan garam Gula penyedap rasa Dan lada bubuk kemudian masukkan saos sambal. Aduk-aduk.\", \"Masukkan irisan wortel\", \"Masukkan 1 sendok makan tepung maizena yang sudah diencerkan\", \"Aduk2 kemudian tes rasa. Apabila terlalu kental tambahkan Air hingga mencapai kekentalan yang diinginkan. Beri perasan jeruk nipis jika suka.\", \"Kalo sudah dirasa cukup matang angkat kemudian siramkan ikan kakap yang sudah digoreng tadi.\", \"Selesai. Ada rasa pedes manis dan asem seger dari jeruk nipis. Silahkan disantap dengan nasi hangat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(255, 2, 'Pindang Tongkol Goreng Telur', 'Pindang Tongkol Goreng Telur - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 pack ikan pindang tongkol (isi 5)\", \"1 butir telur\", \"1 sdm tepung terigu\", \"1/2 sdt lada bubuk\", \"secukupnya garam\", \"minyak goreng\"]', '[\"Cuci bersih ikan, kemudian potong dua\", \"Siapkan wadah, campurkan terigu dan telur yang dikocok lepas. Beri lada bubuk dan garam saja karena ini ikannya sudah agak asin.\", \"Masukkan ikan ke adonan telur terigu, gulingkan hingga ikan dilumuri telur. Goreng hingga matang. Done!\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(256, 3, 'Baso ikan tuna', 'Cara membuat Baso ikan tuna yang enak dan praktis untuk keluarga.', '[\"250 gram ikan tuna filet\", \"4 siung bawang putih(haluskan)\", \"1 butir telor\", \"4 sdm tepung sagu\", \"Seujung sdt soda kue\", \"secukupnya Merica\", \"1 bks Royco ayam\"]', '[\"Cincang halus ikan tuna\", \"Campurkan dengan bawang putih yg telah di haluskan,kemudian masukan merica,royco,telur,tepung sagu dan soda kue.\", \"Uleni hingga kalis dan mudah di bentuk.sisihkan\", \"Rebus air hingga mendidih,bentuk adonan kemudian masukan dlm air yg telah mendidih.\", \"Tunggu hingga baso mengapung,kemudian tiriskan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(257, 3, 'Gurame panggang teplon bumbu padang*', 'Resep Gurame panggang teplon bumbu padang* ala rumahan yang dijamin menggugah selera.', '[\"1 ekor ikan gurame besar (bisa ikan apa saja)\", \"Bumbu yg dihaluskan :\", \"10 buah bawang merah\", \"5 buah bawang putih\", \"2 buah kemiri\", \"1 buah kunyit seukuran kelingking\", \"1 buah jahe 2cm\", \"5 buah Cabe merah kriting\", \"4 buah cabe rawit\", \"5 butir merica\", \"Tambahan :\", \"1 buah Lengkuas geprek\", \"1 buah Serai geprek\", \"3 lembar daun salam\", \"2 lembar daun jeruk\", \"1/2 kara Santan\", \"2 sendok Kecap\", \"Perasa :\", \"Masako sapi\", \"Garam\", \"Gula\"]', '[\"Tumis bumbu yg sudah dihaluskan.\", \"Lalu masukan bumbu tambahan dan perasa\", \"Masukan santan dan kecap\", \"Test rasa\", \"Belah ikan menjadi 2, bakar ikan diteplon menggunakan bumbu yg telah ditumis td... Siap, lalu sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(258, 4, 'Dory Salted Egg', 'Dory Salted Egg - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"Bahan ikan:\", \"250 g ikan dori\", \"1 butir telur (kocok lepas)\", \"Tepung maizena\", \"Bahan saus:\", \"4 butir kuning telur asin\", \"100 ml susu cair\", \"2 sdm mentega\", \"4 siung bawang putih cincang\", \"Segenggam daun bawang\", \"Sejumput daun parseley\", \"10 lbr daun kari\", \"secukupnya Lada\", \"secukupnya Garam\", \"Secukupnya gula\"]', '[\"Potong potong dori, lalu baluri dengan telur, kemudian tepung maizena\", \"Goreng ikan dori yg sudah dibaluri hingga kecoklatan, lalu angkat dan sisihkan\", \"Panaskan mentega, tumis daun kari, bawang putih hingga harum\", \"Masukan daun bawang, daun parseley tumis hingga layu\", \"Masukan kuning telur asin yg sudah dihaluskan dan telah dicampur dengan susu\", \"Tambahkan garam, lada dan gula secukupnya\", \"Aduk2 hingga saus mengental, lalu matikan api\", \"Setelah saus setengah dingin masukan ikan dori tepung lalu aduk2 hingga tercampur\", \"Sajikan dan selamat menikmati\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(259, 2, 'Tuna / Tongkol suwir pete', 'Sajian Tuna / Tongkol suwir pete yang praktis dan lezat untuk dinikmati bersama.', '[\"2 bh tongkol ukuran sedang (boleh tuna/ ikan yg teksturnya sama)\", \"Bumbu halus :\", \"5 bh bawang merah\", \"4 bh bawang putih\", \"5 bh cabe besar\", \"10 bh cabe rawit (bagi yg gasuka pedes boleh skip/ sesuai selera)\", \"3 bh tomat ukuran sedang\", \"secukupnya Terasi, garam, gula\", \"Bahan pelengkap:\", \"1 ikat daun kemangi\", \"100 gr pete (sesuai selera)\"]', '[\"Goreng ikan setengah matang, tunggu dingin lalu suwir2 (buang kepala dan durinya)\", \"Haluskan bumbu lalu tumis dg 3sdm minyak, setelah harum masukkan pete yg sudah dikupas\", \"Lalu masukkan ikan yg sudah disuwir\", \"Tes rasa, apabila kurang boleh ditambah garam,gula dan penyedap lg.. aduk sampai agak kering\", \"Terakhir masukkan kemangi aduk sebentar sampai layu, angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(260, 2, 'Sarden abc pedas', 'Sarden abc pedas - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 kaleng kecil sarden abc pedas\", \"3-4 buah cabe rawit setan\", \"2 buah cabe merah\", \"2 siung bawang merah\", \"2 siung bawang putih\", \"1 buah tomat kecil\", \"1 cm lengkuas\", \"1/2 cm jahe\", \"Sedikit minyak untuk menumis\", \"Sedikit air\"]', '[\"Potong tipis2 bawang merah n putih, cabe rawit n cabe merah. Geprek laos dan jahe\", \"Panaskan minyak dalam wajan\", \"Tumis bumbu yg telah di iris sampai halus\", \"Masukkan sekaleng sarden dan masukkan potongan tomat\", \"Tambahkan sedikit air, aduk sampai rata\", \"Tunggu sebentar. Sarden siap di sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(261, 4, 'Ikan kembung mandi bumbu balado', 'Nikmati kelezatan Ikan kembung mandi bumbu balado dengan resep sederhana ini.', '[\"7 ekor ikan kembung ukuran sedang\", \"6 siung bawang merah\", \"4 siung bawang putih\", \"Segenggam cabe rawit\", \"3 buah tomat besar\", \"Segenggam cabe merah besar\", \"Secukupnya garam\", \"Secukupnya penyedap\", \"Secukupnya minyak untuk menumis\", \"1 buah jeruk nipis\", \"2 lembar daun salam #saya skip, lagi gak ada\"]', '[\"Bersihkan ikan, buang sisiknya. Cuci lalu lumuri dengan perasan jeruk nipis, sisihkan\", \"Rebus cabe, bawang dan tomat hingga empuk biar gampang ngulek 😀 + gak gampang basi\", \"Goreng ikan hingga matang\", \"Setelah bumbu matang lalu ulek dan tumis hingga harum.tambahkan penyedap,garam dan sedikit gula pasir, tambahkan sedikit air.aduk hingga mendidih,masukan ikan lalu aduk sampai bumbu meresap\", \"Angkat, siap dinikmati\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(262, 2, 'Ikan tongkol kemangi bumbu kuning', 'Buat Ikan tongkol kemangi bumbu kuning yang nikmat dengan langkah-langkah mudah ini.', '[\"1 1/2 ekor ikan tongkol ukuran sedang\", \"2 ikat kemangi\", \"Bumbu halus :\", \"4 siung Bawang merah\", \"2 siung Bawang putih\", \"5 bh cabe rawit hijau\", \"5 bh Kemiri\", \"1 ruas jari jahe\", \"1 ruas jari kelingking kunyit\", \"Bahan tambahan\", \"2 bh daun salam\", \"1/2 bh sereh\", \"Secukupnya Cuka\", \"10 buah rawit\", \"200 ml air\", \"secukupnya Gula, garam dan lada\"]', '[\"Tumis bahan halus hingga harum, masukkan sedikit demi sedikit air hingga habis, tambahkan salam sereh dan bumbu pelengkap/tambahan lainnya\", \"Setelah mendidih masukkan ikan tongkol, setelah bumbu meresap tambahkan kemangi\", \"Masak hingga kemangi layu\", \"Sajikan dengan nasi hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(263, 2, 'Ikan Kembung Kecap', 'Ikan Kembung Kecap dengan cita rasa segar khas laut.', '[\"2 ekor ikan kembung banjar\", \"1 buah jeruk nipis\", \"2 siung bawang putih\", \"3 siung bawang merah\", \"3 buah cabe merah keriting (bisa diganti dg cabe hijau besar)\", \"3 buah cabe rawit hijau\", \"1 ruas lengkuas\", \"2 lembar daun salam\", \"1 buah tomat\", \"1 sdt garam\", \"0,5 sdt gula pasir\", \"0,5 sdm gula jawa\", \"secukupnya Kecap manis\", \"secukupnya Air\", \"Minyak goreng\"]', '[\"Bersihkan ikan dan lumuri dengan jeruk nipis. Sisihkan.\", \"Iris tipis bawang merah dan bawang putih. Iris agak tebal cabe merah keriting. Geprek salam. Potong tomat menjadi 8 bagian. Serut gula jawa.\", \"Goreng ikan sesuai selera (saya goreng matang)\", \"Tumis cabe merah keriting sebentar baru masukkan bawang merah, bawang putih dan lengkuas, tumis hingga harum. Tambahkan air secukupnya. Masukkan daun salam, gula jawa, gula pasir, garam, dan tomat. Tes rasa. Terakhir masukkan ikan yang telah digoreng, masak sebentar hingga air agak menyusut. Tes rasa kembali.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(264, 2, 'Pecak Ikan Mujaer', 'Pecak Ikan Mujaer - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1/2 kg ikan mujaer/ikan mas/ikan gurame\", \"Jeruk nipis\", \"Daun kemangi\", \"secukupnya Gula,garam\", \"2 buah tomat ijo\", \"2 lembar daun jeruk\", \"secukupnya Minyak goreng\", \"Bumbu halus:\", \"1 ons kacang tanah goreng\", \"5 bawang merah\", \"3 bawang putih\", \"3 cabe merah kriting\", \"10 cabe rawit merah\", \"1 ruas kencur\"]', '[\"Bersihkan ikan,lumuri air jeruk nipis dan garam,tunggu 3 menit lalu goreng kering\", \"Sangrai semua bumbu halus dengan sedikit minyak goreng,lalu ulek ato blender\", \"Siapkan wajan,beri minyak sedikit tumis bumbu halus sampai harum dan matang,masukan daun jeruk dan tomat ijonya\", \"Beri sedikit air,tunggu sampai mendidih,lalu masukkan gula dan garam\", \"Cicipi rasa,lalu masukkan ikan yg sudah digoreng. Masak sampai medidih dan ikan sedikit layu dan masukkan daun kemangi. Lalu angkat dan sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(265, 4, 'Asam padeh ikan tongkol', 'Resep Asam padeh ikan tongkol ala rumahan yang dijamin menggugah selera.', '[\"1/2 ikan tongkol\", \"Jeruk nipis\", \"4 lb daun sereh\", \"Laos\", \"4 bh asam kandis\", \"2 batang kacang panjang\", \"1 kentang\", \"secukupnya Air\", \"Bumbu halus:\", \"8 bh cabe merah kriting\", \"4 bh cabe rawit merah\", \"4 siung bawang merah\", \"3 siung bawang putih\", \"Seruas kunyit\", \"Seruas jahe\", \"4 bh kemiri\", \"Garam\", \"Penyedap jamur\"]', '[\"Cuci bersih ikan tongkol beri perasan jeruk nipis sisihkan\", \"Blender semua bumbu halus\", \"Tumis bumbu halus sampai harum, beri air, masukkan ikan tongkol, daun salam, laos yang ditumbuk dan asam kandis\", \"Masukkan kacang panjang dan kentang yang telah dipotong, masak sampai ikan empuk\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(266, 4, 'Ikan mas goreng', 'Sajian ikan nikmat: Ikan mas goreng yang mudah dibuat.', '[\"4 ekor ikan mas\", \"3 siung bawang putih\", \"1 ruas jahe\", \"1 ruas kunyit\", \"Secukupnya ketumbar\", \"Secukupnya garam\", \"Secukupnya minyak untuk menggoreng\"]', '[\"Bersihkan ikan, buang sisiknya. Cuci\", \"Haluskan bumbu, lalu campurkan ke ikan yg sudah dibersihkan. Tunggu 15 menit agar bumbu meresap\", \"Goreng ikan dalam minyak yg banyak hingga garing. Siap santapppp\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(267, 2, 'Ikan Patin Asam Manis', 'Sajian Ikan Patin Asam Manis yang praktis dan lezat untuk dinikmati bersama.', '[\"1 ekor ikan patin, potong dadu, buang tulangnya\", \"1/4 kg tepung terigu\", \"Garam\", \"Lada bubuk\", \"Bumbu saus :\", \"5 sachet saos cabai\", \"10 sachet saos tomat\", \"1 butir bawang bombai\", \"1/4 gelas air\"]', '[\"Untuk ikannya cuci bersih terlebih dahulu, tambahkan garam dan 1/2 bungkus lada.. Diamkan\", \"Setelah itu balur ikan satu per satu dengan tepung..\", \"Goreng ikan yang telah dilumuri tepung\", \"Untuk bumbunya, masukkan saus tomat, saus cabe, irisan bawang bombai, dan air masak hingga mendidih. Koreksi rasa, jika kurang asin tambahkan sedikit garam\", \"Ikan patin asam manis siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(268, 4, 'Brengkes Baung Tempoyak Simpel', 'Cara membuat Brengkes Baung Tempoyak Simpel yang enak dan praktis untuk keluarga.', '[\"500 gr (1 ekor) baung, potong 5 bagian\", \"Bumbu2:\", \"3-4 sdm tempoyak\", \"2-3 sdm cabe kriting giling\", \"1 sdm kunyit halus\", \"1 btg serai, potong2 kecil, memarkan\", \"Garam, gula pasir\", \"secukupnya Kemangi\", \"Pembungkus : daun pisang & tusuk gigi\"]', '[\"Campur semua bumbu, aduk rata, Cek rasa\", \"Setelah dirasa pas, Masukkan ikan kedlm bumbu, aduk2, diamkan\", \"Masukkan kemangi, aduk\", \"Siapkan daun, tata ikan, beri bumbu & kemangi\", \"Beri tusuk gigi diujung2nya, lakukan sampai ikan habis semua dibungkus (me: jd 2 bgks). kukus 30 menit\", \"Angkat & sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(269, 3, 'Aglio olio Udang Tuna', 'Resep praktis Aglio olio Udang Tuna yang bisa dicoba di rumah.', '[\"1 buah Bawang bombay rajang kasar\", \"4 siung Bawang putih cincang kasar\", \"5 buah cabe merah iris\", \"20 buah rawit merah iris\", \"150 gr udang bersihkan dan kupas\", \"200 gr tuna kaleng original\", \"50 gr dada ayam cincang haluskan\", \"500 gr spaghetti Laf*nte rebus dgn minyak sedikit hingga aldente\", \"Perasa jamur + garam secukupny\", \"Olive oil secukupnya untuk menumis😘\"]', '[\"Olive oil panaskan lalu Tumis duo bawang + cabe sampe harum\", \"Masukkan udang tumis bareng bawang sampai merah dan stengah mateng + tuna + dada ayam sampe harum\", \"Masukkan garam + perasa jamur/ayam\", \"Tes rasa\", \"Bila dirasa pas masukkan spaghetti 😘 aduk dan campur sebentar😍\", \"Silahkan mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(270, 2, 'Ikan mujaer bumbu kuning', 'Buat Ikan mujaer bumbu kuning yang nikmat dengan langkah-langkah mudah ini.', '[\"1 kg ikan mujaer\", \"7 biji Cabe merah\", \"7 biji Cabe rawit merah\", \"3 siung Bawang merah & bawang putih masing-masing\", \"2 biji kemiri\", \"1 bungkus santan kara kecil\", \"Untuk penyedap saya pake magic lezat\", \"Kunyit,jahe,lengkuas,daun salam,sereh\", \"secukupnya Garam & gula\", \"Jeruk nipis untuk menghilangkan bau amis\", \"Minyak goreng\"]', '[\"Bersihkan ikan kemudian diperasi jeruk nipis dan diamkan\", \"Semua bumbu saya rebus agar lebih mudah nguleknya\", \"Kemudian ikan digoreng sampe kering\", \"Bumbu yg udah direbus diulek ditambah kunyit dan jahe\", \"Tumis bumbu dengan minyak sampe harum tambahkan air,santan kara,daun salam,lengkoas,sereh dan magic lezat plus gula + garam\", \"Cek rasa\", \"Biarkan kuah santan meresap kedlm ikannya dan kemudian angkat\", \"Selesai dan selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(271, 2, 'Sambel tomat ikan nila', 'Sambel tomat ikan nila dengan cita rasa segar khas laut.', '[\"Ikan nila 1/2 kg\", \"Cabe merah\", \"Cabe rawit\", \"Bawang merah\", \"Bawang putih\", \"Jahe, serai\", \"Garam\", \"Gula merah\", \"Tomat\", \"Penyedap rasa\"]', '[\"Goreng ikan nila, lalu tiriskan\", \"Uleg bawang merah, bawang putih, cabe merah, cabe rawit, jahe, tomat, garam, gula merah\", \"Serai di geprek\", \"Tumis bumbu sampai harum dan tomat sampai layu,\", \"Icip2 rasa\", \"Lalu masukkan ikan nila yg sudah di goreng tadi, jadi deh. 🤗\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(272, 4, 'Ikan kembung bakar', 'Resep Ikan kembung bakar ala rumahan yang dijamin menggugah selera.', '[\"5 ikan kembung\", \"7 buah cabe kriting merah\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"1 sereh\", \"1 ruas jari kunyit\", \"secukupnya jahe & lengkuas\", \"secukupnya garam, gula, penyedap\", \"3 sdm santan instan\"]', '[\"Cuci bersih ikan, kasih air jeruk 5 menit dan kasih garam\", \"Haluskan semua bumbu\", \"Campurkan bumbu dan kara, lalu campurkan ikan\", \"Diamkan 1 jam supaya bumbu meresap\", \"Bakar ikan d teplon anti lengket..\", \"Selesai...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(273, 3, 'Chili Tuna Corn Puff', 'Buat Chili Tuna Corn Puff yang nikmat dengan langkah-langkah mudah ini.', '[\"1 kaleng chili tuna chunk (saya pake merek ayam brand)\", \"2 siung bawang putih\", \"2 lembar Kulit puff pastry instan (saya pake edo)\", \"1 buah Jagung manis pipil\", \"1 sachet bon cabe\", \"1 buah telur rebus\", \"Secukupnya garam, gula dan merica\", \"Secukupnya Parsley (karena ga ada saya ganti oregano)\", \"Kuning telur untuk olesan\"]', '[\"Iris tipis bawang putih lalu goreng ambil minyaknya saja..masukkan chili tuna, kemudian jagung pipil tambahkan garam, gula, merica dan bon cabe\", \"Gilas kulit puff pastry instan kemudian potong menjadi 4 bagian..isi dengan tuna dan telur rebus\", \"Lipat menjadi segitiga lalu pipihkan pinggirnya menggunakan garpu\", \"Terakhir oleskan kuning telur, taburi oregano dan beri saos sambal.. Panggang selama 18 menit dengan suhu 200 derajat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(274, 2, 'Gurame Goreng Tauco', 'Resep Gurame Goreng Tauco yang lezat dan mudah dibuat di rumah.', '[\"I ekor Ikan Gurame\", \"6 sendok Tauco\", \"3 sendok tepung maizena\", \"Bumbu iris :\", \"1 ruas Jahe\", \"6 siung bawang merah\", \"4 siung bawang putih\", \"1 buah cabe merah keriting\", \"6 buah cabe rawit\", \"2 buah cabe hijau\", \"1/2 buah tomat merah\", \"2 buah tomat hijau\"]', '[\"Fillet bagian daging ikan jangan sampai putus.\", \"Cuci bersih kemudian rendam dengan air jeruk (10menit) cuci bersih lagi. Tiriskan.\", \"Panaskan minyak di Panci untuk menggoreng ikan (minyak penuh sampai menutupi semua ikan,agar ikan garing dan renyah). Goreng ikan sampai kecoklatan. Angkat dan tiriskan.\", \"Panaskan minyak,tumis semua bumbu iris. Masukan tauco dan tambahkan air.\", \"Larutkan tepung maizena kemudian masukkan ke dalam tumisan tauco. Aduk cepat sampai mengental.\", \"Saya tidak menambahkan garam karna tauco sudah asin. Tapi sesuai selera ya mom. Cek rasa.\", \"Siapkan ikan di wadah/piring besar. Guyur ikan dengan saus tauco.\", \"Siap disajikan. Selamat makan enak\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(275, 2, 'Balado kembung terong pete', 'Sajian Balado kembung terong pete yang praktis dan lezat untuk dinikmati bersama.', '[\"3 ekor ikan kembung (@ dipotong 2)\", \"1 buah terong (dipotong kecil2)\", \"1 papan pete\", \"20 buah cabai rawit merah\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"1 buah tomat (di iris kecil2)\", \"secukupnya Minyak goreng\", \"secukupnya Garam\", \"secukupnya Penyedap rasa\"]', '[\"Panaskan minyak, Goreng ikan kembung dan terong sampai matang.\", \"Goreng pete sebentar.\", \"Uleg/blender cabai, bawang merah, dan bawang putih (uleg kasar), lalu tumis dgn sedikit minyak goreng sambal tersebut, beri garam dan penyedap rasa secukupnya, masukkan irisan tomat ke dlm sambal.\", \"Setelah cabai matang masukkan ikan, terong dan pete yg sdh digoreng tadi. Aduk hingga rata.\", \"Koreksi rasa, lalu sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(276, 2, 'Ikan bakar kembung', 'Buat Ikan bakar kembung yang nikmat dengan langkah-langkah mudah ini.', '[\"500 gr ikan kembung\", \"air perasan jeruk nipis..garam untuk marinasi ikan nya ya.\", \"7 siung bawang merah\", \"3 siung bawang putih\", \"cabe merah kira kira aja y mam..klu saya paling 3biji.\", \"3 butir kemiri\", \"ruas jari jahe se\", \"kunyit seruas jari\"]', '[\"Marinasi ikan dengan perasaan jeruk nipis diam kan selama 15m.\", \"Ulek bumbu atau blender juga bisa y...sampai halus..\", \"Lalu tumis bumbu sampai harum dengan minyak 2 sdm..lalu oles kan diatas ikan..masukkan ikan y ke tempat pembakaran...dan oles lg bumbu yg masih tersisa...\", \"Bakar sampai matang...dan siap untuk di hidangkan..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(277, 2, 'Nila bakar', 'Sajian Nila bakar yang praktis dan lezat untuk dinikmati bersama.', '[\"6 ekor ikan nila\", \"3 bh bawang putih\", \"1 sdt garam\", \"Secukupnya minyak goreng\", \"Bumbu bakar:\", \"1 sdt tumbar\", \"9 bh cabai merah keriting\", \"3 bh bawang putih\", \"3 bh bawang merah\", \"1 sdt garam\", \"3 bh daun jeruk\", \"2 sdm air asam jawa\", \"3 sdm gula merah\", \"3 sdm kecap\", \"1 gelas air\"]', '[\"Bersihkan ikan dari sisik dan kotoran, kerat bagian luar agar bumbu meresap\", \"Bumbui dengan bawang dan garam.\", \"Goreng sebentar dalam minyak panas.\", \"Haluskan bumbu bakar.. Rebus dengan segelas air sampai mendidih dan mengental.. Tes rasa..\", \"Celupkan ikan goreng kedalam bumbu.. Lalu bakar..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(278, 3, 'Sarden ABC Ceplok Telor Ekstra Pedas', 'Sajian ikan nikmat: Sarden ABC Ceplok Telor Ekstra Pedas yang mudah dibuat.', '[\"1 Kaleng Sarden ABC Ekstra Pedas\", \"2 buah telur bebek\", \"1/2 kol sobek kecil\", \"3 batang daun bawang\", \"1 st garam\", \"1 st gula putih\", \"Penyedap rasa\", \"Bumbu iris\", \"2 siung bawang merah\", \"2 siung bawang putih\", \"1 buah bawang bombay\", \"6 buah cabe ijo keriting iris\", \"10 buah cabe setan iris\"]', '[\"Oseng bawang merah, bawang putih & bawang bombay, sampai harum\", \"Masuk kan irisan cabe n oseng sampe matang\", \"Masuk kan kol iris tumis sampai layu, lalu masuk kan sarden Abc...\", \"Beri sedikit air, ceplokan telor diamkan sampai mendidih dan... masuk kan irisan daun bawang...\", \"Aduk sampai matang hidangkan....\", \"Semoga bermanfaat...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(279, 2, 'Asam manis pedas ikan asin tenggiri', 'Sajian ikan nikmat: Asam manis pedas ikan asin tenggiri yang mudah dibuat.', '[\"500 gr ikan asin tenggiri\", \"150 gr bawang merah\", \"5 siung bawang putih\", \"Cabe merah besar\", \"sesuai selera Cabe rawit\", \"Air asam jawa\", \"Gula merah\", \"secukupnya Gula pasir dan garam\"]', '[\"Potong ikan asin seukuran ruas jari,rendam selama 20 menit,lalu cuci bersih dan goreng sampai mateng kecoklatan,angkat dan tiriskn\", \"Iris bawang merah, bawang putih,cabe,rendam asam jawa dengan air dan peras ambil airnya\", \"Tumis bawang merah, bawang putih sampai layu dan wangi,masukan air asam jawa,Gula merah,gula pasir secukupnya\", \"Masukan ikan yang sudah digoreng,irisan cabe, tambahkan air sebanyak sama rata dengan ikannya,biarkan air menyusut dan aduk\", \"Koreksi rasa dulu ya,jika kurang asin bisa tambah garam,pas kan rasanya sesuai selera\", \"Matikan api,pindah kan masakan kepiring saji dan sudah siap dihidangkn bersama nasi putih anget\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(280, 2, 'Mangut ndas manyung', 'Resep Mangut ndas manyung yang lezat dan mudah dibuat di rumah.', '[\"4 buah kepala manyung\", \"1/2 buah kelapa parut yg diambil santannya\", \"5 siung bawang putih\", \"8 buah bawang merah\", \"1 cm kencur\", \"2 cm jahe\", \"2 cm lengkuas\", \"3 lbr daun salam\", \"5 lbr daun jeruk\", \"1 ruas kunyit\", \"10 buah cabe merah kriting (rebus sebentar)\", \"1 genggam cabe rawit setan\", \"3 buah kemiri\", \"1/2 sdt merica\", \"1 sdt garam\", \"2 sdt gula\"]', '[\"Kukus sebentar kepala manyung selama 5menit\", \"Haluskan semua bumbu kecuali daun-daunan dan lengkuas\", \"Tumis bumbu halus sekalian daun salam, daun jeruk, dan lengkuas. Jika sudah kering dan harum tambahkan santan\", \"Jika sudah mendidih masukkan kepala manyung, tambahkan garam dan gula. Tunggu mendidih kembali dan siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(281, 3, 'Lele mandi kecap', 'Cara membuat Lele mandi kecap yang enak dan praktis untuk keluarga.', '[\"4 potong lele goreng\", \"3 kotak tahu,potong kecil2\", \"5 bawang merah\", \"4 bawang putih\", \"5 sdm kecap\", \"7 cabe rawit\", \"Sedikit bawang bombai,iris tipis\", \"Sedikit air\"]', '[\"Tumis irisan bawang dan cabai sampai keriiing. Lalu masukkan tahu\", \"Tambahkan kecap dan masukkan penyedap bila suka.tambahkan air sedikit lalu masukkan lele.\", \"Masak sampai lele jd melunak krn air kecap. Saya masaknya agak nyemek2 kering gitu bund. Sajikan hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(282, 3, 'Sup Ikan gurame', 'Buat Sup Ikan gurame yang nikmat dengan langkah-langkah mudah ini.', '[\"1 ekor ikan gurame\", \"Bumbu :\", \"3 siung bawang merah (di iris)\", \"2 siung bawang putih (di iris)\", \"1 ruas jahe (di iris)\", \"3 buah tomat hijau (di iris)\", \"Asam jawa (secukupnya)\", \"1 sendok teh Kecap ikan\", \"1 ikat kemangi\"]', '[\"Cuci bersih ikan dan rendam dengan air jeruk 15 menit,lalu sisihkan(saya langsung minta di Fillet di tukang ikannya jadi ga repot)\", \"Panaskan minyak. Tumis semua bumbu iris hingga harum (bawang merah,bawang putih,jahe)\", \"Tambahkan air,tunggu sampai mendidih kemudian Masukan ikan. Rebus sebentar (10 menit)\", \"Masukan kecap ikan,air asam jawa,tomat,garam dan penyedap rasa. Cek rasa\", \"Matikan api. Kemudian masukan kemangi.\", \"Sup siap disajikan. Sajikan selagi hangat. Seperti di foto sup nya saya taburi bawang putih cincang yg di goreng kering. Sesuai selera ya mom.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(283, 4, 'Pempek Adaan Ikan Tuna', 'Sajian Pempek Adaan Ikan Tuna yang praktis dan lezat untuk dinikmati bersama.', '[\"400 gram ikan tuna giling\", \"200 gram sagu/tapioka\", \"1 bks santan kara\", \"1 btr telur ayam\", \"1 sdt garam (optional)\", \"1/2 sdt gula (optional)\", \"1 siung bawang merah\", \"1 btg daun bawang\", \"Secukupnya Merica (boleh jga ga dipakai)\"]', '[\"Pertama-tama siapkan Ikan, campurkan dengan santan kara, santannya aku tambahkan dengan air hingga kekentalan sedang hingga 250ml, aduk2 hingga rata. Masukkan Garam gula merica dan daun bawang berserta bawang yang sudah dicincang sebelumnya. Aduk aduk hingga semua tercampur rata. Masukkan telur, aduk lagi hingga tercampur rata.\", \"Selanjutnya kita campurkan sagu sedikit demi sedikit sambil dia aduk, kalau saya pakai spatula. sampai dia tercampur rata. Lalu panaskan minyak, bentuk menggunakan sendok yang sebelumnya diberi minyak makan biar tidak terlalu lengkat dan mudah untuk membentuknya bisa juga dibentuk menggunakan tangan kayak buat pentol bakso. cuma saya pakai sendok. hehe makanya bentuknya belum sempurna. hehhe\", \"Goreng pempek sampai terlihat mengapung di penggorengan dan terlihat mengembang, angkat dan tiriskan\", \"Pempek siap dihidangkan 💕 (apabila kurang jelas bisa chat langsung ya bu ibu. hehhe)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(284, 3, 'Bandeng asem kuning', 'Resep Bandeng asem kuning yang lezat dan mudah dibuat di rumah.', '[\"2 ekor bandeng segar\", \"secukupnya Asam jawa\", \"3 lembar Daun jeruk\", \"Bumbu halus:\", \"5 buah bawang merah\", \"4 buah bawang putih\", \"2 buah kemiri\", \"2 ruas kunyit\", \"1 sdm Ketumbar\", \"2 ruas lengkuas di geprek\", \"8 buah cabe rawit (bisa di biarkan utuh kalau tidak suka pedas)\", \"Garam dan penyedap\"]', '[\"Cuci bersih bandeng\", \"Didihkan air secukupnya setelah mendidih masukkan bumbu yg sudah dihaluskan dan kemudian masukkan bandeng.\", \"Setelah mendidih masukkan daun jeruk dan asam. Setelah itu taburi garam dan penyedap, koreksi rasa\", \"Angkat. Dan bandeng asem kuning bisa dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(285, 2, 'Omelete tuna ala bunda jkb', 'Resep praktis Omelete tuna ala bunda jkb yang bisa dicoba di rumah.', '[\"5 Telur ayam size jumbo\", \"Tuna kaleng 1\", \"Kol iris tipis 3 genggam\", \"Bawang daun iris 3 batang\", \"secukupnya Garam\", \"1 sdt Bawang putih bubuk\", \"1/2 sdt Merica bubuk\", \"1/2 sdt Baking powder double action\", \"2 sdm Terigu\", \"Sausnya :\", \"5 sdm saus tomat\", \"1 sdt Gula\", \"secukupnya Garam\", \"secukupnya Air\", \"3 sdm Maizena cair\", \"1 Bawang bombay\", \"3 Bawang putih\"]', '[\"Campur semua bahan, kocok rata dengan whisk\", \"Siapkan teflon dengan minyak lumayan banyak sekitar 10 sdm, lalu tuang kocokan telur. Masak dengan api kecil. Tutup wajan\", \"Setelah atasnya kering, balik telur perlahan dan masak hingga matang kecoklatan\", \"Cara buat saus ; tumis bombay dan bawang putih iris sampai wangi, masukkan saus tomat, garam, gula dan airs secukupnya\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(286, 3, 'Lempah kuning ikan darat bangka', 'Sajian ikan nikmat: Lempah kuning ikan darat bangka yang mudah dibuat.', '[\"1 ekor ikan gabus\", \"2 ekor ikan baung\", \"1 ekor ikan lele\", \"1 buah nanas\", \"Bumbu\", \"3 jari lengkuas\", \"2 jari kunyit\", \"1 jari kencur\", \"25 buah cabe rawit\", \"1 siung bawang putih\", \"7 buah bawang merah\", \"10 butir lada\", \"Sedikit belacan\", \"secukupnya Garam\"]', '[\"Bersihkan ikan..potong sesuai selera,,tiriskan\", \"Haluskan semua bumbu\", \"Bersihkan nanas..iris tipis\", \"Masukkan bumbu ke panci tambahkan air,,dan nanas..sampai mendidih lalu masukkan ikan..tutup panci..-+20menit..tes rasa..setelah dirasa udah pas matikan kompor..selasaiii..\", \"Nb: airnya dikit aja..uuups makannya bisa khilaf nih..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(287, 3, 'Tongkol Mini Sambal Ijo', 'Sajian ikan nikmat: Tongkol Mini Sambal Ijo yang mudah dibuat.', '[\"1 kg tongkol kecil\", \"bumbu halus\", \"8 buah bawang merah\", \"3 siung bawang putih\", \"8 buah cabe ijo besar\", \"1 buah tomat ijo\"]', '[\"Bersihkan ikan lalu cuci sampe bersih, stelah itu taburi garam dan penyedap. Kemudian goreng, gorengnya jgn trlalu kering\", \"Tumis bumbu yg udaah dihaluskan hingga layu stelah airnya menyusut tuangkan sdijit minyak masukkan lg 1 sdt garam, penyedap, gula aduk2 masukkan ikannya yg udah digoreng td aduk lg merata..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(288, 3, 'Pindang ikan patin cabai rawit', 'Resep praktis Pindang ikan patin cabai rawit yang bisa dicoba di rumah.', '[\"1/2 kg ikat patin\", \"Kacang panjang\", \"Bumbu ulek:\", \"Cabai rawit\", \"Bawang merah\", \"Bawang putih\", \"Kemiri\", \"Jahe\", \"Kunyit\", \"Lengkuas (digeprek)\", \"3 lembar Daun salam\", \"Asem jawa\"]', '[\"Masak air pada wajan, masukan bumbe ulek, ikan patin, dan kacang panjang.\", \"Tambahkan, sdikit asem, garam, penyedap rasa, dan sedikit gula.\", \"Tunggu sampai matang, dan bumbunya meresap\", \"Angkat lalu sajikann👌\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(289, 2, 'Cakalang suwir', 'Buat Cakalang suwir yang nikmat dengan langkah-langkah mudah ini.', '[\"1 ekor ikan cakalang/tongkol yg diasap/bakar,suwir2\", \"Bumbu halus:\", \"20 siung bawang merah\", \"8 siung bawang putih\", \"2 ruas jari jahe\", \"20 buah Cabe rawit campur cabe keriting (sesuai selera)\", \"Secukupnya Penyedap/gula\"]', '[\"Tumis bumbu halus dgn minyak agak banyak\", \"Setelah wangi masukkan ikan suwir\", \"Masukkan gula/penyedap.masak dgn api sedang sambil diaduk.\", \"Klu agak kering bisa tambahkan minyak.\", \"Masak sampai bumbunya meresap dan agak kering,cek rasa.angkat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(290, 3, 'Telur Ikan Kakap Bumbu Kecap Simple', 'Telur Ikan Kakap Bumbu Kecap Simple - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"Telur Ikan Kakap\", \"Cabe Merah\", \"Cabe Jablay\", \"2 Jeruk Nipis\", \"Garam\", \"Penyedap Rasa\", \"Kecap\", \"4 siung Bawang merah\", \"3 siung Bawang Putih\"]', '[\"Cuci bersih Telur ikan Kakap.. Dan potong\\\".. Lalu taburi dengan perasan jeruk nipis agar tidak amis.. Taburkan garam\", \"Panaskan minyak, dan goreng telur ikan kakap nya sampai agak kecoklatan dan tiriskan\", \"Tumis bumbu bawang merah, putih, cabe sampai harum, tambahkan penyedap rasa dan sedikit garam\", \"Setelah harum masukan telur ikan kakap goreng dan diberi kecap sesuai selera\", \"Siap dihidangkan 😀\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(291, 3, 'Nila Bakar Pedas Manis', 'Resep praktis Nila Bakar Pedas Manis yang bisa dicoba di rumah.', '[\"1/2 kg ikan nila segar\", \"2 btr gula merah\", \"2 sdt ketumbar\", \"3 btr kemiri\", \"5 siung bawang putih\", \"3 siung bawang merah\", \"3 cabai merah\", \"1/2 sdt garam\", \"1 sachet kecap manis\", \"1 sdm penyedap rasa\", \"Perasan air jeruk\", \"100 ml air\"]', '[\"Cuci bersih ikan nila, kemudian baluri dengan perasan air jeruk agar bau amis hilang.\", \"Uleg halus bawang putih, bawang merah, cabai, ketumbar, garam, kemiri dan penyedap rasa. Sampai halus.\", \"Masak air hingga mendidih, masukkan bumbu halus, kecap, gula merah. Lalu masukkan ikan nila. Tunggu sampai bumbu meresap sempurna.\", \"Siapkan alat pembakar/panggang. Dan susun rapi ikan nila untuk di bakar/panggang.\", \"Sajikan dengan beberapa lalapan dan sambal.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(292, 2, 'Sop Salmon', 'Sop Salmon - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"100 gr salmon fillet\", \"100 gr tahu putih\", \"3 siung bawang putih cincang\", \"2 siung bawang merah cincang\", \"2 sdm bawang bombay cincang\", \"secukupnya Garam dan gula\", \"2 cm jahe (geprak)\"]', '[\"Didihkan 500ml air\", \"Masukkan bawang merah,bawang putih, bawang bombay, jahe.\", \"Masukkan salmon dan tahu (tidak perlu minyak krn salmonnya nanti mengeluarkan minyak)\", \"Tambahkan gula dan garam secukupnya. Masak sampai mendidih.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(293, 2, 'Pepes ikan kembung mantapp', 'Sajian Pepes ikan kembung mantapp yang praktis dan lezat untuk dinikmati bersama.', '[\"6 ekor ikan kembung\", \"2 papan petai\", \"6 lembar Daun pisang untuk membungkus ikannya\", \"12 biji tusuk gigi\", \"4 sdm minyak goreng\", \"12 lembar daun salam\", \"12 lembar daun jeruk lemo\", \"1 bh jeruk nipis\", \"#bumbu yang di haluskan :\", \"10 siung bawang merah\", \"4 siung bawang putih\", \"2 ruas laos/lengkuas\", \"1 ruas kunyit kuning pekat\", \"secukupnya Gula merah\", \"1/2 ruas jahe\", \"2 btg sere\", \"secukupnya Terasi udang\", \"1 biji kemiri\", \"8 bh cabe rawit (ulek kasar)\", \"10 bh cabe kriting\", \"secukupnya Asam jawa\"]', '[\"Bersikan ikannya lalu lumuri ikan dengan jeruk nipis diamkan selama 5 menit.agar ikan tidak amis.\", \"Bumbu yang telah halus campukan dengan minyak goreng dan petai\", \"Kemudian ikan yang di diamkan tadi bungkus dengan daun pisang gabungkan daun salam.daun jeruk lemo beserta petai dan bumbu yang telah di haluskan.\", \"Bungkus semua sematkan dengan tusuk gigi.\", \"Selamat mencoba semoga resep saya bermanfaat untuk penikmat kulener..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(294, 2, 'Kembung Kuah Asam', 'Sajian ikan nikmat: Kembung Kuah Asam yang mudah dibuat.', '[\"2 ekor ikan kembung\", \"1 buah lemon\", \"Garam\", \"2 lembar daun salam\", \"1 batang sereh\", \"1 ikat kemangi\", \"Lada bubuk\", \"Kaldu bubuk\", \"Penyedap rasa\", \"Air asam jawa\", \"2 gelas air\", \"Bumbu iris :\", \"6 siung bawang merah\", \"3 siung bawang putih\", \"3 buah cabe merah keriting\", \"6 buah cabe rawit merah\", \"1 ruas jahe\", \"1 ruas kemiri\"]', '[\"Cuci bersih ikan. Taburi garam dan perasan jeruk lemon. Sisihkan.\", \"Tumis bumbu iris hingga layu dan matang. Masukkan daun salam dan sereh. Tumis lagi hingga harum.\", \"Tambahkan air. Masak hingga air mendidih. Taburi garam, lada, kaldu bubuk, dan penyedap rasa. Masukkan air asam jawa. Koreksi rasa.\", \"Setelah air mendidih. Masukkan ikan. Tunggu hingga ikan matang di kedua sisinya.\", \"Tambahkan daun kemangi. Tunggu hingga kemangi layu.\", \"Kembung kuah asam siap dinikmati.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(295, 4, 'Bandeng bumbu kecap', 'Sajian ikan nikmat: Bandeng bumbu kecap yang mudah dibuat.', '[\"1 ekor bandeng besar(potong 6)\", \"2 lembar daun salam\", \"1 ruas lengkuas geprek\", \"Bawang goreng\", \"1 bks ladaku yg 1000\", \"Secukupnya penyedap\", \"Secukupnya kecap\", \"Sedikit gula putih\", \"Secukupnya air\", \"# bumbu yg dihaluskan\", \"3 butir kemiri\", \"2 siung bawang putih\", \"Secukupnya garam\"]', '[\"Goreng bandeng sampai kering, tiriskan\", \"Tumis bumbu halus, daun salam dan lengkuas sampai harum\", \"Masukkan air, tambahkan penyedap, gula, lada dan kecap masak sampai mendidih\", \"Masukan ikan bandeng, aduk pelan tunggu sampai air sedikit surut (mencek-mencek)\", \"Matikan kompor dan taburi dengan bawang goreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(296, 4, 'Lele Bakar Kecap', 'Buat Lele Bakar Kecap yang nikmat dengan langkah-langkah mudah ini.', '[\"500 gr lele sedang (me:besar tnp kepala)\", \"Bumbu instan ikan goreng\", \"2 siung bawang putih\", \"secukupnya Lada bubuk\", \"secukupnya Gula merah\", \"Kecap manis (me:bang*)\", \"sedikit Minyak goreng\", \"Air cuka\"]', '[\"Cuci bersih lele tanpa kepala lalu lumuri dg air cuka/air jeruk nipis. Sy punya lele yg sebesar lengan jd potong\\\" selebar 1 jari. Jika pakai yg ukuran sedang, lelenya utuhkan saja.\", \"Bumbui dg bumbu ikan goreng, diamkan 10 menit. Siapkan bakaran olesi ikan yg akan dibakar dg minyak/ margarin, bakar bolak balik sampai setengah matang.\", \"Haluskan bawang putih, lada,gula merah, beri air sedikit dan kecap manis. Aduk rata. Koreksi. Oleskan ke lele bakar tadi sampai matang merasuk. Sajikan dg sambal terasi lalapan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(297, 4, 'Ikan laut jamur tiram kuah tomyam', 'Buat Ikan laut jamur tiram kuah tomyam yang nikmat dengan langkah-langkah mudah ini.', '[\"6 potong ikan laut, boleh ikan apa aja tergantung selera\", \"1 ons Jamur , dibanyakin juga boleh\", \"6 siung Bawang merah\", \"4 siung Bawang putih\", \"5 lembar Daun jeruk\", \"1 batang Serai\", \"10 buah Cabe merah , buang bijinya kalau ga kuat pedas\", \"2 buah Tomat  belah 4\", \"2 lembar Daun salam\", \"1 ruas Jahe\", \"1 ruas Kunyit\", \"1 SDM Garam / sesuai selera\", \"secukupnya Penyedap rasa\", \"1/2 sdt Gula\", \"3 gelas Air\", \"2 sdm Margarin\", \"2 sdm Cuka makan\"]', '[\"Blender bumbu (bawang merah, bawang putih, kunyit, jahe, cabe merah)\", \"Panaskan margarin, tumis bumbu halus sampai wangi\", \"Masukkan air, tambahkan daun jeruk, daun salam, dan serai\", \"Tunggu sampai kuah mendidih, masukkan gula, garam, penyedap rasa\", \"Setelah rasanya oke, masukin ikan, jamur dan tomat. Kalau mau kelihatan cantik, boleh di masukkan cabe merah yg udah dibelah dua. Berhubung di rumah ada yg maag jadinya dibuang bijinya dulu biar g kumat maagnya\", \"Tunggu sekitar 10 menit, masukkan air cuka supaya rasanya lebih endesssss.\", \"Setelah dirasa matang, boleh dihidangkan disantap bersama keluarga di rumah 😍😘\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(298, 2, 'Fettuccini Hot Spicy Tuna', 'Buat Fettuccini Hot Spicy Tuna yang nikmat dengan langkah-langkah mudah ini.', '[\"100 gr fettuccini\", \"3 siung bawang putih, cincang\", \"1 siung bawang bombay, iris\", \"2 buah cabai merah, iris tipis\", \"2 buah cabai hijau, iris tipis\", \"3 potong tuna asap, rendam air hangat, potong2 sesuai selera\", \"2 sdm saus sambal extra hot\", \"1/2 sdm saus tiram\", \"secukupnya Garam & gula\", \"secukupnya Minyak goreng\", \"Air untuk merebus\"]', '[\"Rebus fettuccini dengan air mendidih yang diberi kira-kira 1 sdm minyak goreng dan sejumput garam hingga al dente. Tiriskan.\", \"Tumis bawang putih & bawang bombay hingga harum. Masukkan potongan tuna dan cabai. Masak hingga matang.\", \"Masukkan fettuccini, beri saus sambal dan saus tiram. Tambahkan garam & gula. Tes rasa. Sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(299, 3, 'Sup kemangi ikan patin', 'Sup kemangi ikan patin - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"10 potong ikan patin segar\", \"3 ikat daun kemangi\", \"10 siung bawang merah\", \"5 siung bawang putih\", \"20 buah cabe ijo\", \"4 buah tomat ijo\", \"2 buah daun bawang\", \"2 buah serai\", \"5 lembar daun jeruk\", \"3 lembar daun salam\", \"3 cm laos\", \"1 bungkus masako rasa sapi\", \"2 sdm garam\", \"3 sdm minyak goreng\", \"Kurang lebih 1000 ml air\"]', '[\"Tumis Irisan bawang merah, bawang putih, cabe hijau, Laos, daun serai yang dimemarkan, daun salam, daun jeruk dan tomat\", \"Tambahkan air, tunggu sampai mendidih\", \"Masukan ikan patin segar yang sudah dicuci bersih dan daun bawang, aduk sampai rata\", \"Tambahkan garam dan masako\", \"Tambahkan daun kemangi yang sudah dicuci bersih, aduk.. tunggu sampai matang\", \"Koreksi rasa, angkat dan sajikan untuk keluarga tercinta ❤\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(300, 4, 'Patin Kuah Asam', 'Sajian Patin Kuah Asam yang praktis dan lezat untuk dinikmati bersama.', '[\"1 ekor ikan patin, ukuran sedang\", \"1 buah timun krai, potong\", \"Kubis secukupnya, potong (bisa ditambahkan jika suka)\", \"5 buah asam\", \"1 buah tomat hijau\", \"1 buah jeruk nipis\", \"Secukupnya garam\", \"Secukupnya gula\", \"Penyedap rasa\", \"1.5 liter air\", \"Bumbu halus\", \"10 biji cabe rawit, bisa ditambah jika suka pedas\", \"2 ruas kunyit\", \"1/2 ruas jahe\", \"1/2 ruas lengkuas\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"Secukupnya ketumbar\", \"5 butir kemiri\", \"Secukupnya jinten\"]', '[\"Potong dan cuci ikan patin, lalu lumuri dengan air jeruk nipis agar tidak bau amis, diamkan beberapa saat lalu cuci kembali hingga bersih.\", \"Panaskan air hingga panas, masukkan timun krai dan kubis hingga layu. setelah itu masukkan bumbu halus, tomat dan asam. Setelah itu masukkan ikan patin hingga bumbu meresap pada ikan dan mendidih sempurna.\", \"Masukkan gula, garap dan penyedap rasa. Koreksi rasa. Siap dihidangkan\", \"NB : jangan sering diaduk agar ikan tidak hancur.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(301, 3, 'Sarden tongkol praktis', 'Cara membuat Sarden tongkol praktis yang enak dan praktis untuk keluarga.', '[\"3 bungkus ikan tongkol (saya beli sudah di bungkus kecil2)\", \"1 lembar sereh\", \"2 lembar daun salam\", \"1 ruas jahe (geprek)\", \"5 buah bawang merah\", \"3 buah bawang putih\", \"1 buah bawang bombay (iris kecil2)\", \"8 buah cabe rawit (optional)\", \"4 buah cabe keriting\", \"1 buah tomat yang kecil\", \"Garam\", \"1 sendok kecil gula putih\", \"Royco (optional)\"]', '[\"Bersihkan tongkol (hati2 hancur)\", \"Goreng tongkol yang sudah dibersihkan setengah matang saja\", \"Blender/uleg bumbu yang sudah disiapkan(bawang merah, bawang putih,cabe rawit, cabe keriting, tomat)\", \"Jika sudah halus tumis semua bumbu, kemudian masukkan sereh, salam, jahe, bawang bombay\", \"Tunggu sampai harum, tambahkan sedikit air, dan masukkan garam, gula, royco\", \"Jika sudah mendidih koreksi rasa\", \"Jika dirasa rasa sudah pas masukkan ikan tongkol yang sudah digoreng tadi\", \"Aduk2 hingga air tersisa sedikit dan bumbu ikan tongkol meresap\", \"Makanan siap disajikan, selamat mencoba 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(302, 4, 'Balado Ikan kembung', 'Buat Balado Ikan kembung yang nikmat dengan langkah-langkah mudah ini.', '[\"1/2 kg ikan kembung\", \"15 buah cabe merah\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"1 buah tomat (ukuran sesuai selera)\", \"Garam\", \"Gula\", \"bila suka Penyedap\", \"1 buah Jeruk nipis\", \"Minyak goreng\"]', '[\"Cuci bersih ikan,lalu lumuri dengan jeruk nipis n garam. Diamkan sejenak sambil menyiapkan sambalnya.\", \"Untuk sambalnya,uleg atau haluskan cabe, bawang merah,bawang putih,terakhir tomat\", \"Cuci ikan yang telah dilumuri jeruk dan garam tadi agar saat digoreng tidak lengket.\", \"Goreng ikan hingga kuning kecoklatan.\", \"Tuang sedikit minyak goreng untuk menumis sambal, lalu masukkan garam dan gula sesuai selera (bila suka,beri sedikit penyedap).\", \"Setelah ditumis matang, matikan kompor dan aduk rata ikan dengan sambal. Selamat mencoba 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(303, 2, 'Gulai ikan nila', 'Gulai ikan nila - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1/2 kg ikan nila\", \"santan klapa/kara\", \"secukupnya wortel\", \"Bumbu:\", \"7 siung bawang merah\", \"2 siung bawang putih\", \"secukupnya ketumbar\", \"jahe\", \"kunyit\", \"kemiri\", \"lengkuas\", \"serai\", \"daun jeruk\", \"daun salam\"]', '[\"Bersihkan dan goreng ikan nila terlebih dahulu, potong dadu panjang wortel\", \"Tumbuk sampai halus bawang merah, putih, jahe, kerumbar, kemiri, kunyit\", \"Setelah ikan slsai d goreng, tumis bumbu sampai harum tambahkan daun jeruk, salam, lengkuas geprek dan serai geprek..\", \"Masukkan wortel, dan santan, aduk sampe mendidih, masuk kan ikan nila, royco, garam, dan gula secukupnya...\", \"Selamat mencoba.. ini tidak pedas jika pengen pedas tinggal tambah cabai...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(304, 4, 'Ikan Tongkol Sambalado #15', 'Ikan Tongkol Sambalado #15 dengan cita rasa segar khas laut.', '[\"1 ikan tongkol\", \"Bumbu halus :\", \"3 bawang putih\", \"5 bawang merah\", \"10 keriting merah / sesuaikan\", \"5 rawit / sesuaikan\", \"1 tomat\", \"Seruas kunyit (boleh skip)\", \"Pelengkap :\", \"Air\", \"Garam\", \"Gula jawa / pasir\", \"Daun jeruk\", \"Penyedap rasa\"]', '[\"Cuci bersih ikan tongkol lalu potong potong sesuai selera, kemudian rebus..\", \"Setelah direbus goreng ikan tongkol setengah matang saja.. Sambil nunggu goreng ikan kita siapkan saja bumbu yang mau kita haluskan..\", \"Setelah goreng ikannya selesai selanjutnya goreng dulu bumbu yang mau kita haluskan.. Tidak usah terlalu matang, setengah matang saja cukup, kemudian dihaluskan boleh ditumbuk boleh di blander, kalau saya diblander..\", \"Setelah halus. Kita panaskan sedikit minyak lalu masukkan sambal / bumbu halus tadi.. Tumis sampai berbau wangi kemudian masukkan daun jeruknya.. Dilanjut air sedikit.. Jangan lupa di aduk kemudian tambahkan gula, garam dan penyedap rasa..\", \"Test rasa, jika masih kurang bisa ditambah lagi bumbunya.. Dan jika sudah enak selanjutnya masukkan ikan tongkol yang sudah digoreng tadi.. Aduk hingga semua ikan terlumuri sambal..\", \"Setelah selesai, ikan tongkol sambalado siap untuk dinikmati..\", \"Selamat mencoba 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(305, 3, 'Tongkol Granat 💥', 'Resep Tongkol Granat 💥 yang lezat dan mudah dibuat di rumah.', '[\"4 ekor Ikan Tongkol ukuran sedang, kukus, suir2\", \"1 buah Tomat, iris\", \"5 buah cabai merah, iris\", \"25 buah cabai rawit merah, iris\", \"15 buah cabai rawit hijau\", \"5 siung Bawang Putih\", \"10 siung Bawang Merah, iris\", \"5 lembar Daun Jeruk, sobek2\", \"1 sdm Saos Tiram\", \"1 sdm Royco\", \"1 sdt Gula Pasir\", \"secukupnya Garam\", \"secukupnya Air\", \"Minyak utk menumis\"]', '[\"Panaskan Minyak, tumis bawang merah dan bawang putih sampai layu.\", \"Masukan irisan tomat dan cabai, masak sampai matang.\", \"Masukan ikan tongkol yg sudah di suir, daun jeruk, cabai rawit hijau dan semua bumbu.\", \"Masukan air. Masak sampai mengering. Test rasa. Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(306, 4, 'Ikan tongkol tahu bumbu kuning', 'Ikan tongkol tahu bumbu kuning - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 bngkus pindang tongkol(goreng)\", \"4 buah tahu(potong goreng)\", \"1 buah santan kara\", \"Bumbu halus:\", \"2 buah kemori\", \"2 siung bawang putih\", \"5 siung bawang merah\", \"10 buah cabe rawit\", \"1 ruas kunyit,sereh,laos,daun salam\", \"1/2 sdt ketumbar&lada\", \"Secukup ny air,royco,gula,minyak goreng\"]', '[\"Tumis bumbu halus,sereh,laos,daun slm,smpe harum+kan royco,gula.\", \"Masukan santan kara&sdikit air.masukan pindang tongkol &tahu.masak sampe mndidih.tes rasa klo sdh pas...angkat....siap d sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(307, 2, 'Tongkol goreng sambal mentah', 'Nikmati kelezatan Tongkol goreng sambal mentah dengan resep sederhana ini.', '[\"1 buah pindang tongkol ukuran sedang, bersihkan kulitnya\", \"1 siung bawang putih, haluskan\", \"Sambal mentah:\", \"2 siung bawang merah iris tipis\", \"Cabai rawit sesuai selera iris tipis\", \"1 buah tomat buang isinya potong dadu\", \"Irisan jeruk lemon\", \"Sejumput garam\", \"Bahan Sambal kecap :\", \"3 sdm kecap manis\", \"Sesuai selera cabai rawit dipotong serong\"]', '[\"Pindang tongkol yang sudah dibersihkan, dipotong-potong. Rendam di bawang putih yang sudah dihaluskan beri garam dan air Secukupnya, kira-kira 5 menit.\", \"Goreng tongkol dalam minyak yang sudah dipanaskan sampai kuning kecoklatan. Sisihkan.\", \"Bahan Sambel mentah campur jadi satu.\", \"Bahan Sambel kecap campur jadi satu.\", \"Sajikan tongkol goreng dengan sambal mentah dan sambal kecap, dipadukan dengan nasi panas emm yummy😋😋😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(308, 4, 'Tongkol suwir kemangi', 'Resep Tongkol suwir kemangi yang lezat dan mudah dibuat di rumah.', '[\"2 pindang ikan tongkol (suwir)\", \"1/2 ikat kemangi seribuan (ambil daunnya saja)\", \"8 siung bawang merah (iris)\", \"4 siung bawang putih (iris)\", \"6 cabe rawit merah/sesuai selera (iris)\", \"1 cabe merah besar (iris)\", \"1 buah tomat (potong2)\", \"Garam\", \"Gula\", \"Minyak goreng untuk menumis\"]', '[\"Tumis bawang merah dan bawang putih sampai wangi dengan minyak yg agak banyak sekalian untuk menggoreng tongkol\", \"Masukkan cabe dan tomat, lalu masukkan ikan tongkol aduk rata, tambahkan garam dan gula lalu koreksi rasa\", \"Masukkan kemangi, aduk rata, masak sampai kemangi layu, angkat dan sajikan dengan nasi hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(309, 2, 'Ikan Tuna fillet goreng tepung x bumbu rempah', 'Ikan Tuna fillet goreng tepung x bumbu rempah dengan cita rasa segar khas laut.', '[\"1 ekor ikan tuna ukuran sedang\", \"Tepung terigu\", \"Minyak goreng\", \"Jeruk nipis\", \"Bumbu yg dihaluskan :\", \"3 siung bawang putih\", \"2 siung bawang merah\", \"secukupnya ketumbar\", \"secukupnya merica (saya pakai bubuk)\", \"1 sendok teh garam\", \"1 ruas jari kunyit\"]', '[\"Fillet ikan tuna, pisahkan duri2 yg ikut terpotong, lalu lumuri dengan jeruk nipis peras\", \"Balurkan bumbu halus pada ikan yang telah difillet sampai merata\", \"Diamkan di dalam kulkas selama 15-30 menit\", \"Gulingkan dalam tepung terigu sampai permukaan ikan tertutup tepung seluruhnya\", \"Goreng dalam minyak panas sampai berwarna kuning kecoklatan\", \"Angkat, tiriskan, dan siap disajikan 👌,, disantap dengan sambal terasi biar lbh maknyus 👍🏻\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(310, 2, 'Ikan bandeng bumbu acar', 'Sajian ikan nikmat: Ikan bandeng bumbu acar yang mudah dibuat.', '[\"1 ekor ikan bandeng\", \"4 buah timun ukuran sedang\", \"2 batang wortel lokal\", \"Bumbu halus :\", \"8 buah bawang merah\", \"3-4 buah bawang putih\", \"2 butir kemiri\", \"1/2 ruas jahe\", \"1 ruas kunyit\", \"1/2 sdt lada butir\", \"1 lembar daun salam,sobek\", \"1 batang sereh,geprek\", \"1 ruas langkuas,geprek\", \"5 buah blimbing wuluh\", \"Garam\", \"Gula merah\"]', '[\"Siangi ikan,cuci bersih beri garam + sdkit cuka..diamkan 15menit lalu goreng sampai setengah kering\", \"Siapkan bumbu\\\",blimbing wuluh potong bulat.. wortel timun potong korek api\", \"Siapkan wajan,beri minyak goreng..tunggu hingga minyak panas,tumis bumbu halus hingga harum..\", \"Masukan bumbu geprek,beri garam gula dan sedikit air..tes rasa,masak kurleb 5 menit\", \"Masukan ikan bandeng yg sudah di goreng..terakhir masukan timun wortel,aduk\\\"...masak 10 menit,angkat sajikan...😊😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(311, 3, 'Ikan tongkol pindang bumbu rica-rica daun jeruk', 'Resep Ikan tongkol pindang bumbu rica-rica daun jeruk ala rumahan yang dijamin menggugah selera.', '[\"3 ekor ikan tongkol pindang\", \"I ons  cabe kecil\", \"3 biji cabe besar\", \"3 buah tomat\", \"6 butir bawang putih\", \"6 Butir bawang putih\", \"secukupnya Jahe\", \"secukupnnya Daun jeruk\"]', '[\"Ikan tongkol pindang kita belah di buang tulang tenganya di bagi menjadi 4 bagian\", \"Setelah di cuci ikannya kita goreng dulu\", \"Bahan bumbunya cabe kecil, cabe besar, tomat kita rebus dulu. Klo di rebus biar cabenya pedesnya terasa\", \"Setelah di rebus cabenya kita ulek sama tomat, baru masukan jahe, bawang putih. Bawang merah di rajang saja\", \"Kita goreng bawang merah dulu.. Setelah agak kuning bawngny masukan cabe yg sudah di ulek setelah bener2 bumbuny agak mateng kasih air secukupnya saya kasi raiko sedikit saja, baru masukkan ikan tongkolnya sama daun jeruk masak sampek airny agak sat sedikit. Trus di sajikan dech.. Ma\' nyuss.. Pedesnya\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(312, 3, 'Perkedel tongkol pedas', 'Sajian Perkedel tongkol pedas yang praktis dan lezat untuk dinikmati bersama.', '[\"2 tongkol\", \"1 butir telur\", \"6 cabe rawit\", \"secukupnya Garam,micin\"]', '[\"Cuci bersih tongkolnya buang duri lagu suwir suwir.\", \"Taruh dalam wadah campur dengan potongan cabe rawit kemudian masukkan telur kocok merata.\", \"Panaskan wajan yg berisi minyak lalu goreng hingga berwarna kecoklatan.\", \"Kalau matangnya sudah pas angkat dan tiriskan.\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(313, 2, 'Mujahir Sambel Pepecak', 'Sajian ikan nikmat: Mujahir Sambel Pepecak yang mudah dibuat.', '[\"1 kg ikan mujahir\", \"1 bungkus racik ikan goreng\", \"Bahan sambal:\", \"Segenggam cabe (boleh di mix sesuai selera)\", \"1 ruas jahe,di geprek\", \"3 siung bawang merah\", \"1 buah jeruk limau\", \"Secukupnya garam,penyedap dan air panas\"]', '[\"Cuci ikan sampe bersih,bumbui dengan racik ikan goreng.sisihkan\", \"Untuk sambalnya,uleg kasar bawang merah dan cabe,tambahkan garam,penyedap dan jahe yg sudah d geprek\", \"Siram dengan air panas,beri perasan jeruk limau.\", \"Goreng ikan yg sudah disisihkan tadi\", \"Nikmati selagi ikanya belum dingin\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(314, 2, 'Sempol \"kece\" Tenggiri', 'Resep praktis Sempol \"kece\" Tenggiri yang bisa dicoba di rumah.', '[\"150 gr tenggiri, diletakkan, blender\", \"2 sdm terigu (sy pakai tepung crispy)\", \"2 sdm kanji/tapioka\", \"1 butir telur, kocok\", \"1 batang daun bawang (prey), belah 2, iris tipis\", \"Tusuk sate, potong 2\"]', '[\"Blender ikan + 1/3 telur.\", \"Tuang di wadah, campur dgn daun bawang & tepung sedikit demi sedikit. (Sambil mendidihkan air)\", \"Ambil adonan sdikit, bentuk pada tusuk sate, lgsg masukkn dlm air mendidih.\", \"Setelah mengapung, angkat.\", \"Panaskan minyak. Celup Sempol kukus dlm telur kocok, lalu goreng.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(315, 3, 'Tuna Goreng Krispy menu 1y+', 'Sajian Tuna Goreng Krispy menu 1y+ yang praktis dan lezat untuk dinikmati bersama.', '[\"250 gr ikan tuna fillet (buang durinya)\", \"5 SDM terigu\", \"2 SDM tepung beras\", \"1 butir telur\", \"1 sdt ketumbar bubuk\", \"1 sdt garam\", \"Sejumput kecil merica halus\", \"Secukupnya minyak untuk menggoreng\"]', '[\"Campur semua bahan kecuali telur\", \"Bagi 2 adonan untuk adonan kering dan basah\", \"Campurkan telur dan sedikit air untuk adonan basah, kira2 jangan terlalu encer.\", \"Pukul2 daging ikan hingga gepeng dan lunak\", \"Panaskan minyak.\", \"Celupkan fillet ikan ke dalam adonan basah hingga rata\", \"Gulingkan ke dalam adonan kering jika perlu di remas2 hingga menempel sempurna.\", \"Goreng dalam minyak panas dengan api sedang hingga kuning keemasan. Siap disajikan. 😌\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(316, 3, 'Suwir tongkol kemangi', 'Resep Suwir tongkol kemangi ala rumahan yang dijamin menggugah selera.', '[\"1 ekor ikan tongkol kukus\", \"4 sdm tepung terigu\", \"1/2 sdt garam\", \"Secukupnya kemangi\", \"Secukupnya minyak goreng untuk menumis\"]', '[\"Suwir daging ikan tongkol (ukuran sesuai selera)\", \"Panaskan minyak diwajan untuk menumis ikan\", \"Tumis ikan sampai lumayan mengering\", \"Masukan tepung dan garam, aduk hingga ikan kering\", \"Masukan daun kemangi sampai layu\", \"Siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(317, 4, 'Gulai Ikan Nila Tempoyak (Asam Durian)', 'Sajian ikan nikmat: Gulai Ikan Nila Tempoyak (Asam Durian) yang mudah dibuat.', '[\"1/2 kg Ikan Nila\", \"1 Ons Cabe merah + rawit\", \"Daun Kunyit\", \"sedikit Kunyit giling\", \"Tempoyak (Asam Durian) kurang lebih 1/2 Ons atau sesuai selera\", \"Secukupnya Air\", \"secukupnya Garam dan gula\"]', '[\"Bersihkan ikan nila sampai bersih dan beri asam dan garam secukupnya\", \"Siapkan Kuali Blender Cabe dan masukkan kedalam kuali\", \"Capurkan Tempoyak dan kunyit ke dalam cabe aduk2 sampai tidak ada gumpalan\", \"Tambahkan Air Secukupnya dan daun kunyit aduk dan tunggu sampai mendidih dan kuah agak mengental\", \"Setelah kuah mengental masukkan ikan nila\", \"Tambahkan Garam dan gula secukupnya\", \"Aduk sampai matang dan koreksi rasa\", \"Gulai tempoyak siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(318, 4, 'Ikan mujaer bumbu rujak hot', 'Ikan mujaer bumbu rujak hot dengan cita rasa segar khas laut.', '[\"3 ekor Ikan mujaer\", \"Daun pisang untuk mmbungkus\", \"1 buah jeruk nipis untuk menghilangkan bau amis\", \"3 lmbr daun salam\", \"Bumbu ulek kasar\", \"3 buah tomat\", \"3 buah cabe merah besar\", \"10 buah rawit merah\", \"1 bungkus bon cabe level 30 (boleh skip)\", \"secukupnya Garam\", \"secukupnya Penyedap rasa\"]', '[\"Cuci ikan, lumuri dgn jeruk nipis sisihkan\", \"Siapkan daun pisang, tata daun salam ikan dan tutup ikan dgn bumbu semat pkai lidi\", \"Siap kan. Kukusan biar mendidih kukus ikan td 30menit\", \"Sajikan dgn nasi hangat jk kurang pedas tabur bon cabe\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(319, 3, 'Acar Ikan Tongkol', 'Acar Ikan Tongkol dengan cita rasa segar khas laut.', '[\"1/2 kg ikan tongkol\", \"1 buah bawang Bombay\", \"1/2 perasan jeruk nipis\", \"1 buah tomat\", \"1 buah serai\", \"1 lembar daun salam\", \"1 lembar daun jeruk\", \"10 buah cabai hijau utuh\", \"Secukupnya minyak goreng\", \"Secukupnya air\", \"Bumbu:\", \"7 siung bawang merah\", \"5 siung bawang putih\", \"1 ruas kunyit\", \"1/2 sdt lada\", \"2 buah kemiri\", \"Secukupnya garam dan gula pasir\"]', '[\"Cuci bersih ikan dan potong lalu goreng setengah matang\", \"Haluskan bumbu sampe halus, tumis dengan sedikit minyak goreng\", \"Masukan serai, daun jeruk, daun salam, cabai hijau dan jeruk nipis dan masukan ikan tongkol, aduk merata\", \"Tambahkan air secukupnya, masukan tomat dan bawang Bombay, koreksi rasa\", \"Aduk merata, tunggu matang, letakan di atas piring saji dan siap dinikmati\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(320, 2, 'Oseng Ikan Asin Klotok', 'Buat Oseng Ikan Asin Klotok yang nikmat dengan langkah-langkah mudah ini.', '[\"3 ekor ikan asin klotok, suwir2\", \"2 tomat, iris\", \"3 bawang merah, iris\", \"2 bawang putih iris\", \"15 cabe rawit (sesuai selera), iris\", \"3 sdm kecap manis\", \"1 sdm gula pasir\", \"1/4 sdt garam\"]', '[\"Tumis seluruh bumbu iris.\", \"Masukkan ikan asin klotok. Orak arik sebentar.\", \"Tambahkan air, gula, garam, dan kecap. Tunggu hingga matang dan air sedikit asat.\", \"Hidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(321, 4, 'Gurame Asam Manis', 'Sajian Gurame Asam Manis yang praktis dan lezat untuk dinikmati bersama.', '[\"1 ekor Gurame ukuran besar *filet, kepala & badan jangan dibuang\", \"1 buah jeruk nipis\", \"1/2 buah nanas *potong kecil\", \"3 buah ketimun *potong panjang\", \"3 buah bawang putih *haluskan\", \"2 buah bawang merah *haluskan\", \"1 buah bawang bombai *iris tipis\", \"1 buah tomat *boleh skip\", \"4 sdm saos tomat\", \"4 sdm saos sambal\", \"1 sdm kecap manis\", \"1 sdm saos tiram\", \"1 sdm kecap asin\", \"secukupnya garam, gula & lada bubuk\", \"secukupnya air\", \"secukupnya minyak utk menumis\", \"4 sdm tepung terigu\", \"1 sdm tepung tapioka\"]', '[\"Cuci ikan, potong2 dagingnya.. beri pesan jeruk nipis, diamkan 10 menit lalu cuci kembali\", \"Campur tepung terigu, tapioka, garam, lada bubuk & air secukupnya., aduk rata. taruh daging ikan pada adonan tepung, bolak balik hingga tepung rata lalu goreng pada minyak panas. terakhir kepala & badan ikan beri adonan tepung juga goreng hingga kecoklatan\", \"Tumis bawang merah, bawang putih, bawang bombay, tumis hingga harum kemudian masukan saos tomat, saos sambel, saos tiram, kecap asin, kecap manis, garam & gula aduk rata, kemudian beri sedikit air setelah tercampur rata & mengental masukan irisan ketimun & nanas.. aduk rata kembali setelah itu angkat\", \"Tata ikan, letakan badan ikan lalu taruh diatasnya daging ikan yg sdh di goreng.. siram dengan saos asam manis\", \"Selamat Mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(322, 2, 'Ikan nila goreng balado', 'Resep praktis Ikan nila goreng balado yang bisa dicoba di rumah.', '[\"1 kg ikan nila\", \"1 ons cabe merah keriting\", \"7 siung bawang merah\", \"2 siung bawang putih\", \"Sedikit jahe\", \"1/2 bh jeruk nipis\", \"secukupnya Garam, gula\", \"Minyak goreng\"]', '[\"Ikan nya dipoton jadi 2, bagian kepadanya dibelah, cuci bersih.\", \"Haluskan bawang putih dan jahe beserta garam lalu lumuri pada ikan, diamkan kurleb 30 menit.\", \"Giling kasar cabe dengan bawang merah.\", \"Goreng ikan yg sudah dibumbui tadi dalam minyak panas dgn api sedang hingga berwarna kecoklatan dan bagian luarnya garing.\", \"Tumis cabe dan bawang merah yg di giling kasar dgn minyak bekas menggoreng ikan tdi, kecilkan api kompor, tambahkan perasan jeruk nipis, koreksi rasa. Lanjut dgn api kecil hingga ga ada lgi air dlm tumisan cabe.\", \"Terakhir lumuri ikan goreng dgn cabenya, Siap disajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(323, 2, 'Ikan Pari Panggang', 'Nikmati kelezatan Ikan Pari Panggang dengan resep sederhana ini.', '[\"600 gr ikan pari, bersihkan, potong2, kucuri air jeruk nipis\", \"200 ml santan kental\", \"1 lbr daun kunyit, simpulkan\", \"2 lbr daun salam\", \"1 batang sereh, geprek\", \"1 potong asam kandis\", \"Minyak utk menumis\", \"Secukupnya garam dan merica bubuk\", \"Bumbu halus:\", \"5 buah cabe merah\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"1 butir kemiri yg sudah digoreng\", \"1/2 sdt ketumbar\", \"1 ruas jari kunyit\", \"1 ruas jari jahe\", \"1 ruas jari lengkuas muda\"]', '[\"Tumis bumbu halus, daun kunyit, daun salam, sereh, asam kandis, hingga harum dan matang. Tuang santan kental, aduk hingga berminyak.\", \"Masukkan potongan ikan pari. Bubuhi garam dan merica bubuk. Jika sudah 3 menit, balik sekali saja. Sesudah 2 menit, matikan api.\", \"Panggang di atas bara sambil dioles sisa bumbu. Suami saya suka sisa bumbunya yg masih berupa kuah gitu untuk dimakan bareng nasi.\", \"Sajikan dgn nasi hangat, kuah sisa bumbu, lalapan dan sambal kecap.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(324, 2, 'Ikan nila siram tauco', 'Ikan nila siram tauco - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 ekor ikan nila\", \"100 gr cabe hijau\", \"7 siung bawang putih\", \"5 siung bawang merah\", \"1 bh tomat sedang di iris\", \"1 bngkus tauco mikado\", \"secukupnya Garam,gula\"]', '[\"Bersihkan ikan,lalu kasih garam halus..kmdian goreng\", \"Bawang putih,bawang merah,ccabe hijau d iris halus ya\", \"Tumis bawang n cabe smpe harum,kemudian masukan tomat.lalu masukan tauco ny ksh air sdkt ya..tmbhkan gula n garam,koreksi rasa ya.masak smpe agak kental ya\", \"Tata ikan d ats piring..stlh tauco ny masak.siram di atas ikan td..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(325, 3, 'Tongkol asam padeh', 'Tongkol asam padeh - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"8 potong ikan tongkol\", \"100 gram cabe keriting\", \"7 buah cabe rawit merah\", \"10 siung bawang merah\", \"5 siung bawang putih\", \"1 buah tomat\", \"1 ruas jahe\", \"1 ruas lengkuas\", \"2 lembar daun salam\", \"2 lembar daun jeruk\", \"1 batah sereh\", \"4 buah asam kandis (apabila kurang asam bisa ditambahkan)\", \"1 bungkus penyedap rasa (optional)\", \"secukupnya garam\", \"secukupnya air\"]', '[\"Blender halus, cabe merah keriting, cabe rawit, bawang merah, bawang putih, lengkuas, tomat, jahe sampe benar2 halus\", \"Tumis bumbu halus, masukkan daun salam, daun jeruk, sereh,asam kandis, jika sudah wangi masukkan air\", \"Jika air sudah mendidih, masukkan bumbu penyedap, garam, aduk lalu masukkan ikan. jangan terlalu sering mengaduk ikan karna mudah hancur, masak sampai air agak menyusut dan kuah mengental, koreksi rasa dan tambahkan bumbu yg dirasa kurang.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(326, 2, 'Pepes ikan mas', 'Buat Pepes ikan mas yang nikmat dengan langkah-langkah mudah ini.', '[\"1 kg ikan mas ukuran sedang (isi 3)\", \"1 butir jeruk nipis\", \"secukupnya Garam\", \"6 btng sereh, potong 2,ngeprek\", \"secukupnya Daun salam\", \"2 ikat daun kemangi\", \"1 bh tomat besar, potong-potong\", \"6 bh cabe keriting, iris serong (opsional)\", \"Daun pisang dan tusuk gigi\", \"Bumbu halus:\", \"5 siung bawang putih\", \"6 siung bawang merah\", \"1 ruas kunyit\", \"4 bh kemiri\", \"1/2 cm jahe\", \"1 1/2 sdt garam\"]', '[\"Bersihkan ikan, lumuri dg jeruk nipis dan garam. Biarkan 10-15 menit. Cuci bersih\", \"Lumuri ikan dg bumbu halus. Biarkan 15 menit.\", \"Siapkan daun pisang, susun daun salam, sereh, cabe, irisan tomat, daun kemangi lalu ikan. Ulangi, bngkus ikan lalu semat dg tusuk gigi\", \"Kukus kurleb 1,5jam-2jam setelah air mendidih. Dinginkan.\", \"Agar ikan tdk terlalu berair, panggang diatas teflon. Membuat bumbu makin meresap\", \"Pepes ikan mas siap disajikan. Mak nyos.😍😍😀🤤\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(327, 3, 'Bawal Asam Manis', 'Cara membuat Bawal Asam Manis yang enak dan praktis untuk keluarga.', '[\"2 ekor bawal air tawar\", \"Bumbu halus :\", \"3 cm jahe\", \"2 buah kencur\", \"2 cm kunyit\", \"3 siung bawang putih\", \"5 siung bawang merah\", \"5 buah cabai merah keriting\", \"2 lembar daun jeruk\", \"1 batang serai memarkan\", \"2 lembar daun salam\", \"1 bungkus asam jawa\", \"1 sdm gula putih\", \"2 buah tomat ceri (potong besar)\", \"250 ml air\", \"Garam, penyedap\"]', '[\"Panaskan minyak. Tumis bumbu halus sampai harum. Setelah harum, masukan salam dan serai. Tumis lagi sampai harum dan kecoklatan.\", \"Tuangkan air. Tambahkan garam, penyedap dan gula. Setelah air mendidih, seduh asem dan tuangkan air asem nya. Koreksi rasa. Asem dan pedas manisnya bisa disesuaikan dg selera.\", \"Masukan potongan tomat dan ikan. Masak sampai ikan matang. Siiap disantap bersama nasi hangat..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(328, 2, 'Bandeng pindang', 'Sajian ikan nikmat: Bandeng pindang yang mudah dibuat.', '[\"1 kg bandeng potong jd beberapa bagian\", \"3 siung Bawang merah iris tipis\", \"2 siung Bawang putih iris tipis\", \"8 cabe rawit\", \"secukupnya Asam jawa\", \"Daun bawang potong2\", \"secukupnya Garam\", \"secukupnya Air putih\"]', '[\"Siapkan panci sayur diatas kompor tuang air tunggu sampai mendidih\", \"Setelah mendidih masukan bawang putih, bawang merah, cabe, garam, asam, gula, daun bawang aduk2 masukan bandeng tunggu smp mendidih dan kuah berkurang koreksi rasa,,siap di sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(329, 4, 'Oseng cucut cabe gendot', 'Oseng cucut cabe gendot - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"250 gr asin cucut rendam dgn air panas sebentar\", \"5 bh cabe gendot potong2 sesuai selera\", \"1/2 bh tomat potong bagi 6\", \"5 siung bawang merah iris halus\", \"2 siung bawang putih iris halus\", \"2 lbr daun salam\", \"2 ruas laos\", \"secukupnya Gula merah\", \"secukupnya Garam,kaldu jamur\", \"secukupnya Air matang\"]', '[\"Tiriskan asin cucut lalu goreng hingga matang sisihkan dulu.\", \"Tumis bawang merah+bawang putih hingga harum+tomat aduk2+air matang secukupnya+daun salam+laos+asin cucut+cabe gendot masak hingga matang.\", \"Kecilkan apinya+garam(jika asin cucutnya masih terasa asin kurangi/batasi pemakaian garamnya)+gula merah dan kaldu jamur secukupnya masak2 sebentar lalu angkat.\", \"Sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(330, 2, 'Tuna Pindang Koyong', 'Nikmati kelezatan Tuna Pindang Koyong dengan resep sederhana ini.', '[\"1 kg Ikan Tuna\", \"5 siung Bawang Putih\", \"10 siung Bawang Merah\", \"3 ruas jari Kunyit\", \"2 ruas jari Jahe\", \"2 ruas jari Lengkuas\", \"2 batang Sereh\", \"5 lembar Daun Jeruk\", \"5 biji Cabai Rawit\", \"3 biji Cabai Merah Besar\", \"2 buah Tomat\", \"1/2 sdt Merica Bubuk\", \"Gula\", \"Garam\", \"Penyedap Rasa\", \"1 liter Air Bersih\"]', '[\"Iris semua bumbu kecuali sereh, daun jeruk dan tomat\", \"Tumis bawang putih, bawang merah, sereh, daun jeruk, lengkuas, kunyit, jahe, cabai rawit dan cabai merah sampai layu\", \"Masukkan air tambahkan gula, garam dan penyedap rasa. Masak sampai air mendidih\", \"Masukkan ikan, masak sampai ikan matang. Cek rasa lalu masukkan potongan tomat\", \"Tuna pindang koyong siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(331, 2, 'Bandeng masak pindang serani', 'Bandeng masak pindang serani - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 ekor bandeng\", \"1 papan daun bawang\", \"secukupnya Air\", \"2 sdm minyak untuk menumis bumbu\", \"Bumbu yang dihaluskan\", \"1/2 sdt merica\", \"2 butir kemiri\", \"1 cm kunyit\", \"secukupnya Garam\", \"Bumbu yg diiris\", \"2 Siung bawang putih\", \"4 Siung bawang merah\", \"Cabe secukupnya sesuai selera\", \"Bumbu lain\", \"1/2 cm jahe geprek\", \"1 Batang serai geprek\", \"secukupnya Gula pasir\"]', '[\"Potong-potong ikan,lalu cuci hingga bersih.sisihkan dl\", \"Haluskan bumbu halus\", \"Potong-potong bumbu iris.lalu sisihkan\", \"Panaskan minyak lalu tumis bumbu iris,uratannya bawang putih,bawang merah lalu cabe.klo dah layu masukan bumbu halus.tumis kembali hingga harum.\", \"Lalu masukkan air secukupnya.saya kasih dua gayung kecil\", \"Setelah air mendidih.masukkan ikan.tunggu ikan matang ato mendidih.masukkan gula pasir.\", \"Terus masukkan potong daun bawang.aduk2 kembali.cek rasa,klo sudah pas.tunggu mendidih lagi.dan siap dihidangkan kan\", \"Dah jadi.selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(332, 4, 'Ikan nila saus asam manis', 'Buat Ikan nila saus asam manis yang nikmat dengan langkah-langkah mudah ini.', '[\"1 ekor ikan nila(sekitar 400gr)\", \"secukupnya Garam,merica, ketumbar bubuk\", \"1 buah jeruk nipis\", \"5 sdm tepung terigu\", \"1 sdm tepung maizena\", \"Saus asam manis:\", \"1 buah bawang Bombay\", \"2 buah wortel kecil, potong korek api\", \"15 biji cabe rawit\", \"1 buah cabe merah\", \"secukupnya Gula garam merica\", \"1 sdt tepung maizena (larutkan)\", \"1 sdm saus tomat\", \"1 buah tomat potong dadu\"]', '[\"Cuci& bersihkan ikan.kucuri air jeruk nipis.diamkan sebentar agar meresap.cuci kembali.\", \"Lumuri ikan dengan garam, merica, ketumbar bubuk.simpan dalam kulkas kurleb 1 jam\", \"Campur tepung terigu dan maizena.balurkan rata pada ikan.goreng pada minyak panas& banyak.sampai kuning keemasan\", \"Buat saus; tumis bawang putih & bawang Bombay sampai harum.masukkan cabai tumis lagi.masukkan wortel beri sedikit air.masukkan tomat,saus tomat garam gula merica.tes rasa.aduk sampai mendidih.tuang maizena.aduk2\", \"Masukkan ikan goreng aduk sebentar sampai rata.matikan api\", \"Atau bisa juga saus disiramkan ke ikan doreng setelah api dimatikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(333, 4, 'Balado mujair tahu terong', 'Cara membuat Balado mujair tahu terong yang enak dan praktis untuk keluarga.', '[\"4 ekor mujair\", \"1 buah tahu\", \"1 buah terong\", \"Bumbu halus :\", \"5 buah cabai merah\", \"10 siung bawang merah\", \"5 siung bawang putih\", \"2 buah tomat\", \"2 lembar daun jeruk\", \"1 buah serai\", \"secukupnya Masako\", \"secukupnya Garam\", \"secukupnya Gula\", \"Minyak goreng secukupnya untuk menumis\", \"secukupnya Air\"]', '[\"Bersihkan mujair lalu goreng sisihkan\", \"Potong tahu menjadi 5 bagian goreng sisihkan\", \"Bersihkan terong potong sesuai selera goreng sisihkan\", \"Haluskan cabai merah, bawang merah, bawang putih, tomat\", \"Tumis bumbu halus hingga harum dengan sedikit minyak goreng\", \"Masukkan daun jeruk dan serai\", \"Saat bumbu sudah matang dan harum masukkan mujair goreng, tahu goreng dan terong goreng\", \"Tambahkan sedikit air supaya bumbu lebih meresap\", \"Masukkan masako, garam dan gula secukupnya\", \"Tunggu air mulai mengering\", \"Setelah air kering tes rasa\", \"Masakan sudah pas sesuai selera matikan api angkat masakan siap di nikmati\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(334, 3, 'Tongseng daging sapi', 'Nikmati kelezatan Tongseng daging sapi dengan resep sederhana ini.', '[\"500 gram Daging sapi\", \"Santan (boleh pakai kara 1 bungkus/ kelapa parut 1/2 buah)\", \"Bawang merah 12 siung (6 siung untuk bawang goreng)\", \"8-10 siung Bawang putih\", \"1/4 Kubis\", \"2 buah Tomat\", \"5 pcs Daun bawang\", \"6 cm Kunyit\", \"5 cm Jahe\", \"6 cm Lengkuas\", \"3 lembar Daun salam\", \"3 lembar Daun jeruk\", \"5 pcs Kemiri\", \"1 sdt Ketumbar\", \"1 sdm Kecap\", \"2 pcs Cabai merah\", \"10 pcs Cabai rawit\", \"secukupnya Garam\", \"secukupnya Penyedap rasa\", \"1 bungkus Merica bubuk ladaku\"]', '[\"Cuci daging sapi dan potong kecil-kecil sesuai selera.\", \"Masukkan daging sapi dalam air mendidih dan masak hingga empuk.\", \"Lembutkan baput,bamer,kunyit,kemiri,ketumbar,dan cabai merah.\", \"Tumis bumbu yang sudah dilembutkan tadi dan daun salam, daun jeruk, lengkuas,jahe, cabai rawit utuh,ladaku. Tumis hingga baunya harum.\", \"Potong memanjang tomatnya, kubis dan daun bawang potong sesuai selera.\", \"Masukkan bumbu tersebut yang sudah ditumis tadi kedalam rebusan daging yang sudah empuk. Lalu masukkan kubis,daun bawang dan tomat serta santan.\", \"Masukkan juga garam,kecap dan penyedap rasa.\", \"Cek rasa. Kalau sudah mendidih dan rasa sudah pas, TONGSENG DAGING SAPI SIAP DISAJIKAN. Taburi bawang goreng saat penyajiannya\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(335, 2, 'Beef black pepper spaghetti', 'Beef black pepper spaghetti - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"220 gram spaghetti la fonte, rebus sampai al dente\", \"1 ons daging sapi, iris lawan arah\", \"Bahan perendam daging:\", \"secukupnya Saus tiram\", \"secukupnya Kecap asin\", \"secukupnya Soda kue\", \"Bumbu black pepper instant (merk my taste)\", \"1 siung baput besar cicang kasar\", \"1/2 babom potong kotak\", \"2 helai Daun bawang potong 2cm\", \"secukupnya Kecap asin\"]', '[\"Setelah spaghetti al dente beri sedikit minyak supaya tdk menempel\", \"Daging yg sudah di marinated digoreng 3/4 mateng dgn sedikit minyak. Sisihkan\", \"Tumis babom dan baput sampai harum layu. Masukkan bumbu black pepper instant lalu masukkan spaghetti dan daging sapi. Aduk rata. Beri sedikit kecap asin. Dan daun bawang. Aduk rata. Koreksi rasa bila perlu.\", \"Sajikan dengan cinta\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(336, 4, 'Carbonara Linguine smooked beef', 'Carbonara Linguine smooked beef dengan daging sapi empuk dan bumbu kaya rasa.', '[\"Pasta linguine (bisa pasta lain) sesuai selera +/- 200gr\", \"3 strip smooked beef potong kecil-kecil\", \"Keju parmesan atau sering saya ganti cheddar\", \"1/4 bagian awang bombay kecil\", \"1 siung kecil awang putih (selera)\", \"Susu full cream / cooking cream\", \"1 butir telur\", \"Lada, garam\", \"Daun basil\", \"2 sdm margarin\"]', '[\"Rebus pasta dengan sedikit garam lalu sisihkan\", \"Parut keju cheddar banyaknya sesuai selera lalu sisihkan\", \"Potong kasar dan agak besar bawang bombay. Potong halus bawang putih.\", \"Panaskan 2 sdm margarin lalu tumis bawang bombay dan bawang putih sebentar jangn sampai berwarna coklat.\", \"Masukan smooked beef yang sudah di slice lalu tumis sampai agak matang.\", \"Saya lebih senang menggunakan susu tapi bisa juga dengan cooking cream jika ingin tekstur berat dan kental, versi saya akan gunakan susu full cream +/- 200 ml\", \"Masukkan 3/4 keju pada susu yang mulai mendidih. Sisakan 1/4 dari yang sudah di parut untuk taburan. Aduk rata\", \"Masukkan pasta, lalu tambahkan seasoning lada dan garam sesuai selera. Aduk rata sampai agak kental, terakhir kecilkan api lalu masukkan 1 butir telur ke atas masakan dan aduk cepat sampai merata jangan sampai putih telur matang duluan. Telur akan membuat tekstur saus carbonara semakin kental. Ingat langsung aduk rata jangan sampai matang duluan karena panas yang di hantarkan.\", \"Terakhir setelah bercampur rata dan aroma keluar matikan kompor dan masukkan 2 helai kecil daun basil lalu aduk kembali. Tempatkan di piring lalu taburi keju parut / parmesan. Semoga bermanfaat dan disukai.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(337, 3, 'Semur Jantung Sapi', 'Nikmati kelezatan Semur Jantung Sapi dengan resep sederhana ini.', '[\"1/5 kg jantung sapi\", \"▪️bumbu halus ▪️\", \"5 siung bawang putih\", \"4 siung bawang merah\", \"1 sdt ketumbar\", \"1 sdt lada putih\", \"4 butir cengkeh / 1/4 sdt cengkeh\", \"secukupnya Garam\", \"secukupnya Pala\", \"1/4 sdt jinten\", \"1/4 sdt jahe bubuk atau 1 cm jahe biasa\", \"2 buah kemiri\", \"▪️bumbu tambahan ▪️\", \"1 sdm kecap inggris atau sesuai selera\", \"1 sdt saori teriyaki\", \"secukupnya Royco\", \"1 buah gula merah\", \"Kecap secukupnya atau sesuai selera\", \"secukupnya Vetsin\", \"secukupnya Gula putih\", \"Air putih 500 ml atau di sesuaikan dengan banyaknya jantung yang akan di masak\", \"Bawang bombay 1 buah (ukuran di kira-kira saja)\", \"Delmonte barbeque sauce 3 atau 4 sdm\", \"(Opsional) 4 buah cabe hijau kecil\"]', '[\"Potong-potong jantung sapi dan lumurkan delmonte barbeque sauce kemudian diamkan di dalam kulkas hingga menyerap\", \"Ulek bumbu halus yang sudah di sebutkan di atas\", \"Potong-potong bawang bombay\", \"Kemudian, tumis bumbu halus hingga wangi dan bau kemiri tidak tercium\", \"Masukan bawang bombay kedalam katel\", \"Kemudian masukan jantung yang udah di diamkan teraebut dan aduk rata\", \"Tambahkan air\", \"Tambahkan saori saos teriyaki\", \"Masukan gula merah\", \"Tambahkan kecap manis\", \"Tambahkan royco\", \"Tambahkan vetsin\", \"Tambahkan gula putih\", \"Tambahkan kecap inggris\", \"(Opsional) kalau kurang pedes, bisa di tambahin cabai hijau kecil di iris-iris\", \"Tunggu hingga air aga saat, dan kemudian bisa di hidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(338, 4, 'Daging sapi cincang taousi cah buncis', 'Hidangan daging sapi istimewa: Daging sapi cincang taousi cah buncis.', '[\"1 ons daging sapi (cincang)\", \"1/4 buncir atau kira2\", \"bumbu\", \"bawang putih\", \"taousi hitam\", \"lada bubuk\", \"garam\", \"gula pasir\", \"royco kaldu sapi atau ayam\", \"minyak wijen\", \"kecap asin\"]', '[\"Cincang daging sapi di beri bumbu kecap asin minyak wijen gula tepung kanji secumput aduk rata diamkan dulu biar meresap\", \"Potong panjng buncis.cincang bawang putih dan tousi\", \"Tumis daging cincang yg sudah di bumbuin aduk sdh agk matang angkt siaihkn\", \"Kasih minyak dikit di wajan tumis bawang dan tousi yg di cincang tumis sampi harum dan masukan buncis kasih sedikit garam dan gula aduk dan ksh sdikit air tutup biarkan matang\", \"Lalu terakhir masukan daging cincang yg sdh di tumis tadi campur kdlm wajan buncis tumis bentr angkt\", \"Tumia buncis daging sapi cincang siap di hidangkan..silakn mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(339, 3, 'Sayur asem kacang merah daging sapi', 'Resep Sayur asem kacang merah daging sapi ala rumahan yang dijamin menggugah selera.', '[\"1/4 kg kacang merah\", \"1/4 kg daging sapi\", \"5 siung bawang merah\", \"2 siung bawang putih\", \"2 buah cabe merah\", \"1 butir tomat\", \"Asam jawa\", \"1 Batang daun bawang\", \"Gula merah\", \"Garam\", \"Sedikit bumbu masak\", \"2 lembar salam\"]', '[\"Rebus kacang merah sampai empuk sisihkan\", \"Rebus daging sampai empuk potong kotak kecil\", \"Iris semua bumbu\", \"Panaskan 1 liter kaldu bekas rebusan daging tadi tambahkan air kalau kurang, setelah mendidih tambahkan kacang merah, daging, bumbu yg sdh diiris, garam secukupnya, gula merah secukupnya, sedikit gula pasir biar gurih, bumbu masak sy pakai royco rasa sapi sedikit saja, 2 lembar daun salam biarkan bumbu meresap sekitar 10-15 menit. Angkat hidangkan sayur kacang merah siap disantap. Selamat mencoba...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(340, 4, 'Orak arik telur daging sapi', 'Buat Orak arik telur daging sapi yang nikmat dengan langkah-langkah mudah ini.', '[\"1/2 kg Daging sapi\", \"Bawang putih 1 bungkul cincang halus\", \"Telur 5 biji kocok beri sedikit garam\", \"Minyak wijen\", \"Penyedap rasa\"]', '[\"Tumis bawang putih sampai harum masukkan daging sapi tumis\", \"Masukkan telur yg sudah dikocok lepas aduk2 beri sedikit air\", \"Masukkan minyak wijen dan penyedap rasa tunggu agak mengental angkat dan sajikan selamat mencoba 😄😄\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(341, 4, 'Se\'i Sapi Khas Kupang', 'Sajian Se\'i Sapi Khas Kupang yang praktis dan lezat untuk dinikmati bersama.', '[\"1 daging Se\'i Sapi\", \"2 siung Bawang merah\", \"4 siung Bawang putih\", \"1/4 Bawang Bombay\", \"13 buah cabai rawit (sesuai selera)\", \"2 buah cabai merah keriting (sesuai selera)\", \"1 ikat kecil kemangi, siangi\", \"1/2 buah tomat\", \"secukupnya lada bubuk\", \"secukupnya saos tiram\", \"secukupnya kecap manis\", \"sedikit minyak goreng\", \"secukupnya garam\", \"secukupnya gula\", \"secukupnya air\"]', '[\"Iris daging se\'i Sapi nya tipis-tipis atau sesuai selera\", \"Iris tipis bawang merah, bawang putih, bawang Bombay, cabai, dan tomat.\", \"Tumis bawang merah, bawang putih, dan bawang Bombay, sampai harum.\", \"Masukkan cabai, setelah matang masukkan tomat\", \"Bisa beri sedikit air, biarkan sampai bumbu matang dan air mendidih dan menyusut. (ini bisa di skip) bila tidak ingin ada airnya\", \"Masukkan daging Se\'i Sapi nya, tambahkan lada bubuk, gula, garam, saos tiram, dan kecap manis. Aduk rata\", \"Masak Se\'i sebentar saja ±5 menitan agar daging tidak keras. masukkan daun kemangi. Aduk rata\", \"Tes rasa\", \"Siap di sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(342, 3, 'Beef steak saus jamur', 'Cara membuat Beef steak saus jamur yang enak dan praktis untuk keluarga.', '[\"1/4 kg daging sapi\", \"1/4 kentang\", \"7 buah buncis\", \"2 buah wortel\", \"Marinated\", \"Secukupnya merica bubuk\", \"Secukupny lada hitam\", \"Bikin saos steakny\", \"2 sdm mentega\", \"1 ons jamur kancing\", \"1 buah bawang bombay\", \"4 sdm saus tiram\", \"Secukupnya penyedap rasa\", \"Secukupnya gula\", \"1 sdt tepung maizena\", \"Secukupnya garam\"]', '[\"Cuci bersih daging sapi, lalu iris iris menjadi beberapa bagian tergantung selera, lalu marinated daging sapi, diam kn bberapa menit sampai bumbu meresap.\", \"Rebus sayuran wortel dan buncis.\", \"Goreng kentang di lumuri terigu / bisa juga d rebus yah bunda\", \"Masak daging sapi bisa d bakar, bisa juga pakai teflon anti lengket yah bunda, sampai berubah warna dan kelihatan matang\", \"Bikin saus ny : panaskan wajan lalu cairkan mentega, tumis bawang bombay hingga harum lalu masukan potongan jamur aduk rata hingga layu, masukan saus tiram, aduk rata lalu beri sedikit air masak hingga mendidih, tambahkan gula, garam dan penyedap rasa sesuai selera yah bunda aduk sampai merata, masukan tepung maizena yang telah di larutkan, aduk hingga rata masak hingga mengental.\", \"Lalu sajikan daging sapi di atas piring beserta sayuran dan kentangny siram dengan saos jamur ny dan beef steak saos jamur siap disajikan\", \"Selamat mencoba bunda\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(343, 3, 'Tumis Daging Sapi', 'Hidangan daging sapi istimewa: Tumis Daging Sapi.', '[\"500 gr daging sapi\", \"1 bh bawang bombay\", \"1 siung bawang putih\", \"1 ruas jahe\", \"5 bh cabe ijo besar\", \"5 bh cabe ijo keriting\", \"1 sdm saus tiram\", \"1/2 sdt garam, gula pasir, merica bubuk\", \"Saus marinasi:\", \"2 sdm kecap manis\", \"1 sdm kecap asin\", \"1 sdm minyak wijen\"]', '[\"Rendam daging dalam kecap manis, kecap asin dan minyak wijen.\", \"Diamkan dalam kulkas minimal 1jam, lebih lama lebih enak.\", \"Iris serong cabe. Geprek jahe. Cincang halus bawang putih. Potong besar bawang bombay.\", \"Panaskan minyak goreng tumis bawang putih dan bawang bombay sampai harum kemudian masukkan jahe dan cabe ijo.\", \"Kemudian masukkan daging yg sudah dimarinasi beserta seluruh sausnya. Aduk rata.\", \"Tambahkan saus tiram. Aduk rata.\", \"Lalu bubuhkan garam, gula pasir dan merica bubuk.\", \"Beri secukupnya air supaya daging matang sempurna dan empuk serta tidak gosong.\", \"Masak sampai kuah berkurang sesuai selera. Koreksi rasa.\", \"Tumis daging sapi siap dihidangkan untuk makan siang bersama keluarga tercinta. 😋😋😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(344, 3, 'Bola-Bola Kornet Sapi', 'Resep praktis Bola-Bola Kornet Sapi yang bisa dicoba di rumah.', '[\"1 kaleng kornet sapi (merk kornetku)\", \"1 sachet tepung bakwan (pake 1/2 nya)\", \"Minyak\"]', '[\"Campur satu kaleng kornet dengan tepung setengahnya aduk rata..\", \"Bentuk bola-bola goreng sampai berubah warna.. jangan terlalu lama... sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(345, 2, 'Sayur sop daging sapi no MSG no Gula', 'Cara membuat Sayur sop daging sapi no MSG no Gula yang enak dan praktis untuk keluarga.', '[\"1/4 daging sapi (potong kotak2)\", \"sesukanya wortel\", \"1 buah kentang\", \"sesukanya kol\", \"seledri\", \"bawang daun\", \"1 buat tomat besar\", \"bumbu :\", \"merica butir ulek\", \"bawang merah (sesukanya)\", \"3 siung bawang putih (geprek)\", \"secukupnya garam\", \"air matang\"]', '[\"Tumis bawang putih dengan margarin\", \"Goreng bawang merah\", \"Rebus daging sapi yg sudah d potong2 sampai empuk\", \"Masukan bwng putih yg sudah d tumis\", \"Lalu masukan kol.. wortel.. kentang.. sampai empuk, tambahkan merica\", \"Dan terakhir masukan tomat, seledri, daun bawang dan garam.. tes rasa dan masukan bawang goreng. lalu aduk dan siap disajikan..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(346, 3, 'Asem asem daging sapi', 'Sajian Asem asem daging sapi yang praktis dan lezat untuk dinikmati bersama.', '[\"1/4 kg daging sapi, cui lalu potong kecil2\", \"100 gram buncis poton2\", \"2 buah wortel, kupas lalu potong potong\", \"1 buah tomat iris2\", \"Bumbu2\", \"Asam jawa secukupnya sampai didapat rasa asam yg diinginkan\", \"4 siung bawang merah iris\", \"4 siung bawang putih iris\", \"1/2 bawang bombay iris\", \"6 buah cabai hijau besar iris\", \"4 buah cabai merah keriting iris\", \"1 lembar Daun salam\", \"Laos geprek\", \"Kecap manis\", \"Garam\", \"Gula\", \"Penyedap rasa\"]', '[\"Rebus daging sampai empuk... Sisakan air rebusan untuk kuah\", \"Tumis bawang merah bawang putih bawang bombay hingga harum dan layu\", \"Masukkan cabai daun salam dan laos\", \"Setelah harum masukkan buncis dan wortel aduk2 lalu tmbhkan kecap manis\", \"Masukkan tumisan ke dalam air rebusan daging\", \"Tambahkan asam jawa\", \"Tambahkan garam gula dan penyedap lalu cek rasa\", \"Masak sampi mendidih dan sayuran empuk\", \"Terakhir masukkan tomat\", \"Matikan api\", \"Asem2 daging siap disajikan\", \"Tumis bawang merah bawang putih bawang bombay hingga harum dan layu\", \"Masukkan cabai daun salam dan laos\", \"Setelah harum masukkan buncis dan wortel aduk2 lalu tmbhkan kecap manis\", \"Masukkan tumisan ke dalam air rebusan daging\", \"Tambahkan asam jawa\", \"Tambahkan garam gula dan penyedap lalu cek rasa\", \"Masak sampi mendidih dan sayuran empuk\", \"Terakhir masukkan tomat\", \"Matikan api\", \"Asem2 daging siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(347, 4, 'Spicy Beef Teriyaki (uenakk)', 'Nikmati kelezatan Spicy Beef Teriyaki (uenakk) dengan resep sederhana ini.', '[\"300 gr sapi lulur dalam (di iris agak tipis)\", \"selera Cabai rawit\", \"1 buah bombay (ukuran sedang)\", \"1 buah daun bawang/pere\", \"2 sdm mentega\", \"1 sdm madu\", \"Bumbu marinasi :\", \"4 siung bawang putih (parut)\", \"1 cm jahe (parut)\", \"1 sdm mirin (tidak ad boleh skip)\", \"2-3 sdm saus/kecap teriyaki\", \"1 sdt garam\", \"1 sdt gula\", \"1 sdt merica bubuk\"]', '[\"Marinasi daging yang yg sudh dipotong dengan bumbu2 yang saya cantumkan. Diamkan di kulkas selama 1 jam. (referensi foto ini)\", \"Siapkan wajan, beri mentega, lalu daging yg sudh di marinasi boleh dituang (hidupkan api yang sedang)\", \"Test kematangan dengan cara menusuk dengan garpu. Jika sudah empuk, boleh di masukkan bawang bombay dan madu\", \"Jika sudah matang, masukkan daun bawang/pere dan cabai rawit\", \"Lalu icip2 rasa jika ad yg kurang (biasanya garam atau gula)\", \"Masakan siap dihidangkan :) semoga suka ya teman2\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(348, 2, 'Steak sapi parud keju', 'Sajian Steak sapi parud keju yang praktis dan lezat untuk dinikmati bersama.', '[\"Bagian has sapi 2 potong ukuran ketebalan 10 inchi\", \"Bumbu rendaman sapi :\", \"secukupnya Ketumbar\", \"secukupnya Lada hitam\", \"3 siung Bawang putih\", \"secukupnya Garam / penyedap / kaldu jamur\", \"secukupnya Air\", \"Bahan sausnya:\", \"Delmonte saus tomat\", \"Delmonte saus cabe\", \"Bawang putih iris 1 siung\", \"Bawang Bombay iris secukupnya\", \"Garam / penyedap / kaldu jamur\", \"secukupnya Air\", \"sesuai selera Tepung maizena\", \"sesuai selera Keju parutan\", \"Bahan salad :\", \"Brokoli\", \"Jagung\", \"Wortel\"]', '[\"Sayuran salad d rebus secukupnya jangan terlalu matang pisahkan dan tiriskan\", \"Bawang putih, ketumbar, lada hitam dan garam, penyedap dhaluskan lalu air sedikit campur, lalu sapi masukan k rendaman bumbu nya tersebut. Masukan ke kulkas sblm d bakar\", \"Buatlah sausnya terlebih dahulu, goreng bawang putih dan bawang Bombay sampai wangi lalu delmonte saus cabe dan tomat beri air sedikit lalu penyedap dan bila ingin kental sesuai selera beri tepung maizena yg sudah diberi air sedikit dan campurkan kedalam Katel\", \"Bakar daging sampai warna kecoklatan dan tidak keluar darah lagi\", \"Sajikan daging dilumuri saus dan salad di pinggirny, juga diparuti keju sesuai selera\", \"Bila ingin kenyang di sajikan bersama nasi\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(349, 4, 'Lumpia isi daging sapi & kol', 'Resep praktis Lumpia isi daging sapi & kol yang bisa dicoba di rumah.', '[\"1/2 bongkol kol iris halus\", \"200 gr daging sapi giling\", \"1 batang daun bawang iris halus\", \"2 sdm minyak goreng\", \"5 sdm air\", \"Kulit lumpia\", \"Putih telor\", \"Merica\", \"Garam\", \"Bumbu cincang halus:\", \"2 bawang merah\", \"2 bawang putih\", \"1 liter minyak goreng untuk goreng lumpia\"]', '[\"Tumis bumbu cincang dgn 2 sdm minyak, masukan daging sapi aduk rata sampai daging berubah warna lalu masukan kol, daun bawang, air, garam dan merica. Masak sampai air surut dan kol matang.\", \"Angkat dari kompor, diamkan di suhu ruang sampai benar2 dingin.\", \"Setelah dingin, bungkus lumpia dgn isian, gulung. Rekatkan ujung dgn putih telor. Lakukan sampai isian habis.\", \"Panaskan minyak goreng, goreng lumpia sampai kecoklatan\", \"Angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(350, 4, 'Beef black pepper', 'Hidangan daging sapi istimewa: Beef black pepper.', '[\"500 gram daging sapi has dalam (iris)\", \"2 buah bawang bombay (potong kotak)\", \"2 buah paprika hijau (potong kotak)\", \"4 siung bawang putih (geprek & cacah)\", \"3 sdm lada hitam kasar\", \"5 sdm kecap manis\", \"4 sdm saus tiram\", \"sesuai selera Gula & Garam\"]', '[\"Aduk rata irisan daging dengan 1 sdm lada hitam, 2 sdm kecap manis & 2 sdm saus tiram. Diamkan selama minimum 30 menit.\", \"Setelahnya tumis daging dengan sedikit minyak hingga matang, lalu sisihkan.\", \"Tumis bawang putih, bawang bombay & paprika hingga harum.\", \"Masukan tumisan daging\", \"Tambahkan 3 sdm kecap manis, 2 sdm saus tiram & 2 sdm lada hitam. Aduk hingga semua bahan tercampur.\", \"Tambahkan garam & gula sesuai selera.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(351, 4, 'Oseng Tetelan Sapi', 'Resep Oseng Tetelan Sapi ala rumahan yang dijamin menggugah selera.', '[\"1/4 kg tetelan sapi\", \"500 ml air\", \"2 lbr daun salam\", \"secukupnya Garam\", \"secukupnya Gula\", \"Minyak goreng secukupnya untuk menumis\", \"Bumbu halus :\", \"100 g cabe merah keriting\", \"30 g cabe rawit merah (boleh ditambah kalo mau lebih pedas)\", \"50 gr bawang merah\"]', '[\"Rebus tetelan sapi bersama daun salam hingga empuk. Angkat, potong +/- 1 cm, sisihkan.\", \"Rebus atau kukus bahan bumbu halus, lalu ulek kasar.\", \"Tumis bumbu yang telah diulek kasar dengan minyak goreng secukupnya.\", \"Beri garam dan gula secukupnya (lebih baik dirasa ya).\", \"Masukkan tetelan yang telah direbus, aduk rata.\", \"Tambahkan 100 ml air rebusan tetelan.\", \"Koreksi rasa. Jika air sudah susut, matikan kompor.\", \"Siap disajikan dengan nasi hangat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(352, 2, 'Tongseng sapi', 'Resep Tongseng sapi ala rumahan yang dijamin menggugah selera.', '[\"200 gram daging sapi\", \"65 ml santan (kara)\", \"50 gram kubis\", \"1 buah tomat\", \"5 bawang merah\", \"2 bawang putih\", \"3 buah kemiri\", \"5 buah cabe rawit\", \"gula merah\"]', '[\"Cuci bersih daging sapi yang sudah di siapkan\", \"Haluskan bawang merah, bawang putih, jahe, kunyit dan kemiri sisihkan\", \"Panaskan wajan,beri sedikit minyak lalu tumis bumbu halus hingga harum,lalu masukkan daging sapi tumis hingga berubah warna,masukkan santan dan tuang air secukupnya tunggu hingga mendidih\", \"Bumbui dengan garam,gula merah,merica bubuk,kecap tes rasa,jika sudah pas rasanya tunggu hingga mendidih tambahkan tomat iris,kubis dan cabe rawit iris,lalu tunggu air hingga sedikit menyusut,jangan terlampau habis airnya,jika sudah angkat sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(353, 4, 'Soto Daging Sapi Lobak& Wortel', 'Nikmati kelezatan Soto Daging Sapi Lobak& Wortel dengan resep sederhana ini.', '[\"250 gr Daging Sapi\", \"2 Buah Wortel kupas, iris bulat tipis\", \"2 Buah lobak kupas, iris bulat tipis\", \"1 Batang sereh memar\'kan\", \"1 Batang Daun Bawang iris halus\", \"1 Batang Daun Seledri iris halus\", \"Garam secukup\'nya\", \"Gula Pasir secukup\'nya\", \"1500 ml Air\", \"1 sdt Bawang Goreng\", \"2 sdm Minyak Sayur\", \"~Bumbu Halus~\", \"5 siung Bawang Merah\", \"3 siung Bawang Putih\", \"1/2 sdt Merica butiran\"]', '[\"Didih\'kan Air hingga mendidih, masukan Daging yg sudah dicuci,rebus smp empuk, angkat tiriskan potong kotak\'\'.Air rebusan Daging td disaring, untuk selanjutnya dimasak lg,separuh air rebusan Aku pk merebus lobak, biar aroma lobak\'nya ngk pekat\", \"Panaskan minyak, tumis bumbu halus smp harum,didihkan lg sisa air rebusan daging,masukan sereh, wortel,daging sapi,lobak.Tambah\'kan garam &gula pasir,daun bawang, seledri. tes rasa.\", \"Angkat, sajikan dngn taburan bawang goreng&pelengkap lain\'nya\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(354, 4, 'Tumis buncis cah daging sapi', 'Hidangan daging sapi istimewa: Tumis buncis cah daging sapi.', '[\"250 gr baby buncis\", \"100 gr daging sapi giling\", \"3 siung bawang putih\", \"50 ml air\", \"4 sdm minyak untuk menumis\", \"2 sdm saus tiram\", \"sejumput gula\", \"lada bubuk\", \"garam\"]', '[\"Tumis bawang putih hingga harum, masukan daging giling lalu tumis hingga matang\", \"Masukan buncis, air, saus tiram, gula, garam dan lada.. masak -+10 menit..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(355, 4, 'Kornet Sapi', 'Resep praktis Kornet Sapi yang bisa dicoba di rumah.', '[\"1/2 kaleng Kornet Sapi (ukuran sedang)\", \"3 sdm Tepung Terigu\", \"1 buah Telor Ayam\", \"Lada Bubuk\", \"Garam\", \"Masako\"]', '[\"Campur terigu dan telor dahulu, aduk hingga rata. jangan ada gumpalan trigu.\", \"Lalu masukann kornet setengah kaleng yg ukuran sedang, sedikit masako, garam, dan lada bubuk aduk hingga rata.\", \"Siapkann minyak yg sudah dipanaskan, lalu goreng. tunggu hinggs kecokltan dan tiriskan.\", \"Siap dimakan untuk lauk ❤\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(356, 2, 'Bakso Sapi', 'Resep Bakso Sapi ala rumahan yang dijamin menggugah selera.', '[\"500 gr daging sapi tanpa lemak\", \"150 gr es batu/7bh ice cubes\", \"1 btr putih telur\", \"100 gr tapioka\", \"1 sdt nutrijell/agar2 plain\", \"Bumbu :\", \"6 bh bawang putih goreng, haluskan\", \"4 bh bawang merah goreng, haluskan\", \"1 sdt lada bubuk\", \"1 sdm garam\", \"2 sdt gula pasir\", \"1 sdm kaldu bubuk\"]', '[\"Giling daging+es batu sehalus mungkin. Tambahkan bumbu-giling, putih telur-giling hingga semua bahan tercampur rata.\", \"Masukkan ke dlm freezer kurleb 30menit.\", \"Keluarkan dr freezer lalu masukkan tapioka+nutrijel sedikit demi sedikit sambil diaduk rata dan diuleni. Uleni jgn kelamaan spy tidak keras.\", \"Masukkan adonan ke freezer 5menit. Kemudian didihkan air di panci besar jgn smpai bergejolak lalu kecilkan apinya, cetak bakso bulat2 hingga mengapung. Angkat\", \"Bila perlu masukkan bakso ke dlm wadah yg berisi air es utk menghentikan proses masak. Spy tetap kenyal dan tdk lembek.\", \"Utk dijadikan Frozen Food:\", \"Tiriskan bakso dan diamkan hingga benar2 dingin. Tata dalam wadah jgn bertumpuk, masukkan ke dlm freezer 1-2jam, lalu masukkan ke wadah kedap udara/plastik klip per porsi. Tahan 2bln jika kondisi freezer sangat dingin.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(357, 2, 'Bakso Sapi & Udang cah Paprika', 'Hidangan daging sapi istimewa: Bakso Sapi & Udang cah Paprika.', '[\"6 butir bakso sapi dibelah dua\", \"10 Udang merah kupas\", \"2 buah Paprika ukuran medium iris kasar\", \"1 Tomat buah (beef steak tomato) iris kasar\", \"2 siung Bawang putih iris halus\", \"1/2 Bawang Bombay ukuran besar\", \"1 sdt Angciu (arak china)\", \"2 sdt Saus Tiram\", \"1 sdt Saus Sambal ABC\", \"1 sdt Saus Tomat\", \"1/2 sdt Kecap ikan\", \"1/2 sdt Royco rasa sayuran\", \"4 batang Daun Bawang iris kasar\", \"1/2 cup Air matang\", \"Sejumput Garam\", \"1/2 sdt Cabai kering (bila suka)\", \"1,5 Minyak Goreng\"]', '[\"Tumis bawang putih, bombay, irisan paprika & bakso. Hingga paprika sedikit melunak. Tuangkan angciu sambil aduk. Masukkan kecap & saus. Aduk rata.\", \"Tuangkan air hangat perlahan. Taburkan bumbu-bumbu bubuk. Masukkan irisan tomat bersama udang. Masak sebentar. Jangan sampai udang over cooked & mengeras. Tabur cabai kering (optional).\", \"Tambahkan irisan daun bawang. Aduk rata. Matikan api. Hidangkan segera\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(358, 2, 'Sukiyaki beef enoki dan tahu', 'Resep Sukiyaki beef enoki dan tahu ala rumahan yang dijamin menggugah selera.', '[\"3 lembar daging beef slice (sy beli di supermarket yg sdh slice2an ya)\", \"1/2 pack jamur enoki, potong bagian bawahnya\", \"1 kotak tahu kuning\", \"3 sdm saos tiram\", \"1 sdm kecap manis\", \"Secukupnya garam, gula, kaldu jamur, merica\", \"Secukupnya air\", \"1 siung bawang putih\", \"1/4 buah bawang bombay\"]', '[\"Rajang bawang putih dan bawang bombay. Potong2 tahu jd kotak2 kecil. Lalu potong2 jg daging slice menjadi bagian yg lebih kecil\", \"Panaskan minyak dalam teflon. Stlh itu tumis bawang putih dan bawang bombay hingga harum. Stlh harum, masukkan daging hingga berubah warna\", \"Masukkan jamur enoki dan tahu, lalu masukkan bumbu2 yg ada. Tambahkan sedikit air. Lalu cek rasa hingga sesuai dgn keinginan. Hidangkan😁\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(359, 2, 'Sop Tulang Sapi (sederhana)', 'Sop Tulang Sapi (sederhana) dengan daging sapi empuk dan bumbu kaya rasa.', '[\"Bahan :\", \"500 gr tulang sapi\", \"1.5 liter air\", \"1 ruas jahe\", \"1/4 buah pala\", \"2 buah wortel\", \"secukupnya Lada bubuk\", \"Garam\", \"Penyedap rasa sapi\", \"Daun bawang\", \"Pelengkap :\", \"Irisan cabe rawit\", \"Bawang goreng\", \"Jeruk nipis\"]', '[\"Rebus Tulang tambahkan jahe, sampai keluar kaldu atau sampai airnya berkurang, kemudian masukan pala, bawang putih, lada, garam dan penyedap rasa\", \"Kemudian masukan wortel yang sudah di iris2 dan daun bawang, tunggu sampai matang.\", \"Sajikan dengan bahan pelengkap\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(360, 4, 'Bistik Rolade Sapi', 'Bistik Rolade Sapi - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 stik rolade sapi/ayam (potong2)\", \"1/2 bawang bombay (iris2)\", \"2 sendok makan kecap asin (saya 1 sdm)\", \"2 sdm saos sambal (saya 1 sdm)\", \"1 sachet saos tiram\", \"secukupnya Air\", \"3 sdm kecap manis (saya 1 sdm)\", \"secukupnya Gula pasir\", \"Bumbu halus ; (saya dipotong)\", \"4 siung bawang merah\", \"2 siung bawang putih\", \"1/2 sdt lada bubuk\", \"Secukupnya garam\", \"Bahan pelengkap :\", \"Wortel (rebus)\", \"Buncis (rebus)\", \"Kentang (goreng)\"]', '[\"Siapkan rolade potong2.. goreng setengah matang\", \"Tumis bumbu halus dan bawang bombay sampai harum..masukkan rolade + kecap asin + saos tiram + kecap manis + saos sambal aduk rata...tambah kan air matang..aduk rata..tes rasa.. jangan lupa tambah kan gula pasir aduk tes rasa kembali..😄\", \"Biarkan air smp agak menyusut...angkat\", \"Sajikan 😍 alhamdulillah si kecil makan sampai nambah 3x 😲😲😲😂😂😂😂\", \"Selamat mencoba mom... 😄😍😘\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(361, 2, 'Mie Goreng Sapi Brokoli', 'Resep Mie Goreng Sapi Brokoli ala rumahan yang dijamin menggugah selera.', '[\"Mie telur kering Cap Burung Dara\", \"50 gram daging sapi cincang\", \"1/4 brokoli\", \"2 buah kemiri, haluskan\", \"1/4 sdt bubuk ketumbar\", \"secukupnya Lada\", \"secukupnya Kecap manis\", \"secukupnya Kecap asin\", \"1 sdt saus tiram\", \"1 siung bawang putih\", \"1 siung bawang merah\"]', '[\"Rebus mie telur hingga matang. Angkat & tiriskan.\", \"Bersihkan brokoli, rendam di air garam. Rebus sebentar. Angkat & tiriskan.\", \"Tumis bawang merah & bawang putih.\", \"Masukkan daging sapi giling. Tambahkan saus tiram, kecap asin, kecap manis, dan lada. Aduk rata.\", \"Masukkan mie yang sudah direbus. Aduk rata. Tambahkan lada, kecap manis & kecap asin.\", \"Masukkan kemiri dan ketumbar bubuk. Aduk rata.\", \"Mie siap disajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(362, 3, 'OVERNIGHT SOFT BUN ROTI ISI BAKSO SAPI sistem biang', 'Resep praktis OVERNIGHT SOFT BUN ROTI ISI BAKSO SAPI sistem biang yang bisa dicoba di rumah.', '[\"Bahan biang (bikin kira2 16jam sebelum) :\", \"150 gr tepung cakra\", \"150 cc air hangat kuku\", \"1/4 sdt ragi instan\", \"Adonan utama :\", \"250 gr tepung cakra\", \"100 gr tepung segitiga\", \"8 gr ragi\", \"80 gr gula pasir\", \"1 butir telur utuh+1 kuning telur\", \"40 cc susu cair\", \"80 gr butter\", \"6 gr garam\", \"Filling baso sapi :\", \"2 bungkus kornet sapi original/400gr daging sapi cincang\", \"1 bawang bombay iris tipis\", \"2 butir bawang merah iris kasar\", \"1 helai daun bawang iris tipis (boleh skip)\", \"Kecap manis\", \"Saos tiram\", \"Kecap asin\", \"Merica\", \"Gula garam\", \"Air\", \"Minyak wijen\", \"Olesan : bread crumb\", \"Putih telur\"]', '[\"Aduk semua bahan biang jd satu pakai sendok. Diamkan suhu ruang 1 jam lalu tutup clingwrap dan masukkan kulkas lbh kurang 14-18 jam. (Jgn lbh dr 18 jam, kl aku sekitar 16jam)\", \"Dalam bowl masukkan tepung, ragi, gula pasir. Aduk rata disusul masukkan telur+susu cair. Tuang cairan pelan2 sesuaikan kondisi tepung, jgn kelembekan. Tambahkan adonan biang dr kulkas lalu ulen semua sampai kalis.\", \"Masukkan butter+garam lalu ulen lagi sampai kalis elastisssssss.\", \"Diamkan sampai mengembang 2x lipat lalu bulat2kan @40gram. Diamkan lagi 10 menit sambil siapkan isian fillingnya.\", \"Filling baso sapi : tumis bawang2an sampai harum. Tambahkan daging/kornet. Masak sampai berubah warna. Masukkan air secukupnya bersama bumbu lainnya. Masak sampai meresap tp jgn terlalu kering ya. Biarkan sedikit juicy. Tiriskan.\", \"Bentuk sesuai selera adonan yg sudah dibulat2kan. Beri isian baso sapi, masukkan ke loyang. Lalu diamkan lagi sekitar 1 jam.\", \"Oles permukaan dg putih telur lalu taburi bread crumb. Panggang suhu 180° lebih kurang 12-15 menit tergantung besar kecil roti. Angkat. Kalo suami sukanya pake sambel pedes makannya..hihii.\", \"Hasilnya empuk moms. Sampe besoknya juga masih empuk. Ini foto setelah 1x24 jam.\", \"Edisi bikin lagi nih moms. Suami ketagihan..hihii. Bikin 1/2 kg dapetnya 3 loyang ukuran 22 cm ya lbh kurangnya. Isian bebas, mau diganti cokelat atau kosongpun gk masalah. Cusss\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(363, 2, 'Lidah Sapi Cabe Hijau', 'Cara membuat Lidah Sapi Cabe Hijau yang enak dan praktis untuk keluarga.', '[\"1/3 Lidah Sapi (iris tipis), nggak tau brp gram\", \"1 buah Bawang Bombay ukuran kecil\", \"3 siung Bawang Merah\", \"2 siung Bawang Putih\", \"2 buah Cabe Hijau Besar\", \"2 buah Cabe Hijau Keriting\", \"Garam\", \"Kecap\", \"Saus Tiram\"]', '[\"Rebus lidah hingga empuk, iris tipis\", \"Tumis semua bumbu hingga harum. Masukkan lidah\", \"Tambahkan garam, kecap & saus tiram. Koreksi rasa\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(364, 3, 'Beef Yakiniku ala RHpawonalit', 'Beef Yakiniku ala RHpawonalit dengan daging sapi empuk dan bumbu kaya rasa.', '[\"150 gr daging sapi sengkel, bekukan iris motong serat tipis\", \"1/2 bh bawang bombay, iris panjang\", \"5 btg asparagus potong serong, bisa diganti daun bawang\", \"2 sdm minyak untuk menumis\", \"1 siung bawang putih cincang halus\", \"Bumbu saus :\", \"1 cm jahe, cincang halus\", \"1 sdm kecap asin\", \"1 sdt kecap manis\", \"21/2 sdt gula pasir\", \"1/4 sdt lada bubuk\", \"1/2 sdt minyak wijen\", \"50 ml air kaldu sapi (1sdt kaldu bubuk +air)\", \"secukupnya Ekstra air agar berkuah\"]', '[\"Tumis bawang putih dan bawang bombay hingga harum\", \"Masukkan daging sapi, masak hingga daging berubah warna\", \"Tuang saus,masak sampai matang dan meresap\", \"Sajikan dengan nasi hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(365, 3, 'Rendang Daging Sapi Kentang', 'Resep Rendang Daging Sapi Kentang ala rumahan yang dijamin menggugah selera.', '[\"750 gr daging sapi, potong potong\", \"1000 ml santan encer\", \"1000 ml santan kental\", \"5 lmbr daun jeruk\", \"1 btg sereh, memarkan\", \"4 buah kentang, kupas, potong2\", \"Bumbu Halus\", \"1 ons cabe merah\", \"2 cm kunyit\", \"12 siung bawang merah\", \"5 siung bawang putih\", \"2 cm lengkuas\", \"Secukupnya garam dan gula\"]', '[\"Rebus santan encer, daun jeruk, sereh dan bumbu halus, masak hingga mendidih\", \"Masukkan daging yang sudah di potong potong, masukkan garam dan gula secukupnya, masak hingga santan kental\", \"Masukkan santan kental, setelah santan udah mulai berkurang, masukkan kentang, masak hingga rendang nya agak mengering dan berminyak, angkat dan sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(366, 4, 'Sayur Nangka Kelapa Sengara, iga sapi...enakkk', 'Cara membuat Sayur Nangka Kelapa Sengara, iga sapi...enakkk yang enak dan praktis untuk keluarga.', '[\"2 mangkok sayur nangka muda yg telah di rebus\", \"stengh kilo iga sapi yg telah di potong2\", \"seruas lengkuas geprek\", \"3 batang sereh gwprek\", \"3 lembar daun jeruk\", \"3 lembar daun salam\", \"4 btr cengkeh\", \"1 buah pala..pecah jd 2 bagian boleh jg pake pala bubuk\", \"seruas kayu manis\", \"1 butir kelapa parut. bagi dua bagian\", \"bagian pertama sengara sampai harum lalu haluskan\", \"bagian kedua di buat santan\", \"bumbu halus :\", \"8 bawang merah\", \"6 bawang putih\", \"2 ruas kunyit\", \"stengh sdkt teh merica\", \"8 buah cabe keriting\", \"2 ruas jahe\", \"1 buah sereh ambil pthnya\", \"sdkt ketumbar\"]', '[\"Masak iga sapi sampai lembek..air rebusan yg sisa sdkt jgn di buang\", \"Tumis bumbu halus hingga wangi\", \"Masukan nangka bersama iga sapi yg td sdh lembek dgn sisa air rebusan iga..tambahkan garam..lalu masukan daun jeruk,salam, lengkuas,sereh, pala, cengkeh..masak sampai mendidih lalu masukan bumbu halus...aduk2..\", \"Lalu masukan kelapa sengara... masukan penyedap..santan...aduk2..biarkan memdidih.. koreksi rasa...biarkan sayur mendidih agak lama agar bumbunya meresap...bila kuah sdh agak mengental angkat...sajikan dgn taburan bawang goreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(367, 3, 'Beef Yakiniku', 'Buat Beef Yakiniku yang nikmat dengan langkah-langkah mudah ini.', '[\"100 gram daging sapi has iris tipis\", \"1/4 bawang bombay iris tipis\", \"1 buah bawang putih iris\", \"1 buku jari kelingking jahe peprek\", \"1/4 buah paprika hijau / merah kali ini saya pake yg merah adanya di kulkas itu doang heheh, iris\", \"150 ml kaldu dashi\", \"3 sdt soy sauce\", \"1 sdt gula pasir\", \"Sejumput lada bubuk\", \"1 sdm olive oil\"]', '[\"Dalam mangkok Campur irisan daging, bawang bombay, bawang putih dan jahe\", \"Lalu tambahkan, soy sauce, gula dan lada aduk rata pakai tangan kalau bisa bisa merata dan terserap, tutup dengan cling wrap dan simpan dalam kulkas selama 30 menit\", \"Panaskan olive oil di panci atau wajan lalu masukan daging yg sudah dimarinasi tadi, tumis hingga berubah warna dagingnya\", \"Sebelumnya kita siapkan dulu kaldu dashi, kalau saya dari 1 bungkus serutan ikan bonito / bonito flakes di didihkan dengan 150ml air lalu disaring hingga didapatkan kaldu spt gambar diatas, atau bisa juga beli dashi kering dilarutkan dengan air panas, karena dirumah ada stok bonito flakes jd saya pakai aja ini, ini mnrt saya wajib pakai ya kalau mau hasil rasanya mendekati japanese resto\", \"Setelah daging sudah berubah warna masukan kaldu dashi, didihkan hingga daging empuk\", \"Setelah daging empuk dan air menyusut masukan paprika didikan lagi sampai kuah berkurang atau nyemek2\", \"Siap disajikan dengan nasi panas gak pake lama makannya si ucil kalau lauk favoritenya mah 🎉 mamak juga gak senewen nyuapinnya jdnya hihihi 💃\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(368, 4, 'Sop daging sapi rempah', 'Sop daging sapi rempah dengan daging sapi empuk dan bumbu kaya rasa.', '[\"1/2 kg daging sapi\", \"2 buah kentang ukuran sedang\", \"4 buah wortel ukuran sedang\", \"8 buah buncis\", \"secukupnya Kol\", \"3 batang seledri\", \"1 batang daun bawang\", \"2 sdm garam\", \"1/2 sdt gula\", \"1 bks royco ayam\", \"Bawang goreng untuk taburan\", \"Bumbu yang dihaluskan:\", \"8 siung bawang putih\", \"1 sdm lada putih\", \"1/2 sdt jintan\", \"Bumbu tambahan:\", \"5 cengkeh (buang ujungnya)\", \"3 kapulaga\", \"1 batang kayu manis\", \"3 pekka\", \"4 lembar daun salam (diremas)\", \"3 lembar daun jeruk (diremas)\", \"3 batang serai (memarkan)\", \"1 ruas lengkuas (geprek)\", \"2 ruas jahe (geprek)\"]', '[\"Cuci bersih daging yg sudah di potong dadu kemudian taburkan garam dan remas\\\".\", \"Didihkan air untuk merebus daging, rebus sampai ½ matang, jika sudah angkat dah buang airnya.\", \"Rebus kembali air di panci tnggu hingga mendidih. Masukkan kembali daging, bumbu halus dan bumbu tambahan lainnya. Tak lupa garam, gula dan royco. Tutup panci hingga daging empuk\", \"Masukkan wortel dan kentang tunggu hingga ½ matang, kemudian masukkan buncis seledri dan daun bawang aduk rata dan tnggu sampai semua sayuran matang. Jika sudah masukkan kol aduk sebentar tes rasa dan matikan api.\", \"Taburi dengan bawang goreng\", \"Sop daging rempah siap dihidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(369, 4, 'Daging sapi lada hitam simple', 'Sajian Daging sapi lada hitam simple yang praktis dan lezat untuk dinikmati bersama.', '[\"1/2 kg Daging sapi\", \"1 Paprika merah\", \"1 Paprika hijau\", \"2 Cabai merah besar\", \"1 Bawang bombay\", \"3 siung Bawang putih\", \"1 sdm Kecap\", \"1/2 sdm Kecap asin\", \"secukupnya Royco sapi\", \"3 sdm Lada hitam\", \"secukupnya Minyak goreng\", \"secukupnya Garam\", \"secukupnya Vitsin\", \"Air setengah cup aqua gelas\"]', '[\"Untuk hidangan aku kali ini pake daging yg direbus terlebih dahulu. Kalau sdh empuk sisihkan.\", \"Daging yg sudah empuk lalu dipotong tipis tapi agak melebar -+ 4cm an.. lalu aku gepuk biar bumbu meresap.\", \"Siapkan wajan untuk menumis. Tumis bawang putih cincang dan bawang bombay hingga harum. Masukkan paprika yg sdh dipotong dadu dan cabai merah besar. Aduk rata\", \"Masukkan air dan kecap manis dan asin. Aduk lagi.. masukkan lada hitam dan bumbu secukupnya..\", \"Lalu masukkan daging.. diamkan 2 menit dengan ditutup wajannya. Test rasa. Angkat dan sajikan..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(370, 2, 'Empal serundeng daging sapi', 'Hidangan daging sapi istimewa: Empal serundeng daging sapi.', '[\"1 kilo daging sapi\", \"3 lembar daun salam\", \"3 lembar daun jeruk\", \"1 sdm asam jawa, rendam pakai 50ml air\", \"1/2 butir kelapa muda parut\", \"1 ruas jahe digeprek\", \"1 liter air untuk merebus daging\", \"Bumbu Halus\", \"5 buah cabe keriting\", \"10 buah bawang putih\", \"1 sdt ketumbar\", \"1/2 sdt jinten\", \"3 ruas lengkuas\", \"1 ruas jahe\", \"2 batang serai\", \"1 sdm garam\", \"2 sdm gula merah (saya pakai 1 bulet kecil)\"]', '[\"Rebus daging dengan air, daun salam, jahe geprek sampai empuk\", \"Setelah empuk, potong2 sesuai serat lalu digepuk/geprek sampai tipis.\", \"Campur bumbu halus, daging, daun jeruk dan air asam jawa. Remas2 dan diamkan selama 30 menit\", \"Pindahkan ke dalam wajan, tuang 300ml air kaldu bekas merebus daging tadi. Masak dengan api kecil sambil diaduk terus.\", \"Setelah air menyusut, masukkan kelapa muda parut. Aduk terus sampai benar2 kering.\", \"Empal serundeng siap untuk disantap\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(371, 4, 'Beef Mushroom Puff Pastry', 'Cara membuat Beef Mushroom Puff Pastry yang enak dan praktis untuk keluarga.', '[\"Kulit Puff Pastry\", \"2 siung bawang putih\", \"1 buah bawang bombay\", \"200 gr daging sapi cincang\", \"100 gr Jamur\", \"1 sdm saus tomat\", \"1 sdt gula\", \"1 sdt bubuk pala\", \"Secukupnya garam dan lada\"]', '[\"Tumis bawang putih dan bawang bombay yang sudah diCincang halus dan dipotong kecil hingga harum.\", \"Masukkan daging cincang hingga matang, masukkan jamur.\", \"Beri saus tomat, bubuk pala, gula dan garam juga lada secukupnya.\", \"Setelah isian matang, pipihkan & bentuk pastry menjadi kotak persegi lalu isi dengan daging cincang jamur + keju sesuai selera. Lipat samping menjadi bentuk segitiga, rekatkan pinggirnya menggunakan garpu. Beri olesan kuning telur, bubuk parmesan, dan bubuk oregano diatasnya.\", \"Panggang selama 40menit dalam suhu 180derajat (sesuai oven masing2 ya..)\", \"Selamat mencoba!\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(372, 4, 'Cah kangkung sapi', 'Cah kangkung sapi dengan daging sapi empuk dan bumbu kaya rasa.', '[\"2 ikat kangkung\", \"300 gr daging sapi\", \"1 gelas kecil air\", \"Bumbu\", \"2 siung bawang putih\", \"3 siung bawang merah\", \"10 biji cabai (sesuai selera aja ya)\", \"2 sendok makan kecap manis\", \"Lengkuas\", \"Daun salam\", \"Garam\", \"Minyak\"]', '[\"Rebus daging kemudian potong tipis2 saja\", \"Potong2 kangkung sesuai selera lalu cuci bersih\", \"Iris semua bumbu kemudian panaskan minyak,tumis sampai agak layu\", \"Masukkan daging yg sudah di iris tipis lalu beri air,tunggu hingga mendidih masukkan kangkung\", \"Aduk2 hingga kangkung agak layu msukkan kecap,garam lalu cek rasa tunggu hingga kangkung matang dan matikan api\", \"Cah kangkung sapi siap di hidangkan,ini sengaja kuahnya banyak ya...\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(373, 3, 'Tongseng daging sapi by adilly_kitchen', 'Tongseng daging sapi by adilly_kitchen dengan daging sapi empuk dan bumbu kaya rasa.', '[\"1/4 daging sapi\", \"1/2 buah kol (iris kasar)\", \"2 batang daun bawang (iris kasar)\", \"1 bngks santan kara\", \"Bumbu halus:\", \"7 siung bawang merah\", \"4 siung bawang putih\", \"3 butir kemiri\", \"1 sdt ketumbar\", \"1 ruas jari kunyit\", \"6 buah cabe merah\", \"Bahan tambahan:\", \"1 sdm kecap manis\", \"1 sdt garam\", \"1 sdt gula\", \"1 bnkgs ladaku\", \"2 ruaslengkuas (geprek)\", \"1 batang sereh (geprek)\", \"10-15 buah cabe rawit merah (sesuai selera)\", \"1 ruas jahe (geprek)\"]', '[\"Pertama2 iris daging tipis2, lalu rebus terlebih dahulu hingga agak empuk dengan tambahan jahe 1 ruas yg telah d geprek.Airnya jgn d buang.\", \"Tumis bumbu halus beserta lengkuas dan sereh hingga keemasan dan harum. Masukkan daging, aduk rata. Beri sedikit demi sedikit air kaldu daging sapi td, kemudian tambahkan ladaku,garam, gula dan kecap lalu santan. Jika kurang gurih bisa ditambahkan penyedap rasa. Aduk2 terus supaya santan tidak pecah.\", \"Jika daging sudah empuk, matikan api.\", \"Tongseng daging sapi siap untuk disajikan. 😍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(374, 3, 'Tumis kulit sapi', 'Resep Tumis kulit sapi ala rumahan yang dijamin menggugah selera.', '[\"1/4 kulit sapi\", \"3 siung bawang merah\", \"2 siung bawang putih\", \"1 ruas jahe\", \"1 ruas kunyit\", \"2 butir kemiri\", \"1 sendok garam\", \"1 sendok penyedap rasa\", \"1/2 sendok gula pasir\", \"1 sendok merica bubuk\", \"2 lembar daun salam\", \"2 lembar daun jeruk\", \"2 buah cabe ijo\", \"2 buah cabe merah\", \"1 buah tomat hijau\"]', '[\"Cuci bersih kulit sapi lalu rebus sebentar buang air nya\", \"Haluskan bumbu bawang merah,bawang putih,kunyit,jahe,kemiri,garam,merica\", \"Iris tipis bawang daun,cabe merah,cabe hijau dan tomat\", \"Tumis bumbu halus hingga harum kemudian masukan bahan yg telah di iris tambahkan air secukup nya kemudian masukan kulit sapi tambahkan penyedap rasa\", \"Tunggu sampai air larut kemudian test rasa 😁 selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(375, 4, 'Tongseng Sapi Empuk', 'Sajian Tongseng Sapi Empuk yang praktis dan lezat untuk dinikmati bersama.', '[\"500 gr daging sapi (potong kecil)\", \"1 buah bawang bombai (iris tipis bentuk setengah lingkaran)\", \"2 L air\", \"3 sdm minyak untuk menumis\", \"Bahan Blender:\", \"10 siung bawang merah\", \"5 siung bawang putih\", \"5 cm jahe\", \"1 sdt ketumbar\", \"6 buah kemiri\", \"1 sdt kunyit bubuk (atau 3cm kunyit segar)\", \"Bahan Penyedap:\", \"2 buah sereh\", \"5 lembar daun jeruk\", \"3 lembar daun salam\", \"3 buah cabai rawit (tusuk bagian tengah atau iris)\", \"1 sdt kaldu sapi bubuk\", \"Secukupnya garam\", \"Bahan Topping (per porsi):\", \"3 lembar daun kobis (iris tipis)\", \"1 buah tomat ukuran kecil (potong tebal)\", \"3 lembar daun bawang (iris tebal memanjang\", \"1 sdm kecap manis\", \"Bawang goreng untuk taburan (opsional)\"]', '[\"Di panci besar, panaskan minyak. Tumis bawang bombai hingga layu. Masukkan “bumbu blender”, tumis hingga kental.\", \"Masukkan daging sapi. Tumis hingga daging setengah matang (daging berubah warna dari merah menjadi coklat).\", \"Masukkan air dan “bumbu penyedap” (kecuali garam). Aduk rata. Biarkan mendidih. Setelah mendidih, tutup panci. Rebus hingga air menyusut menjadi setengah lebih.\", \"Cicipi air kaldu. Jika kurang asin, tambahkan garam sesuai selera. Matikan api. Kaldu tongseng sudah jadi.\", \"Jika akan menyajikan per porsi, panaskan wajan terpisah. Masukkan sekitar 1 centong daging dan 2 centong kuah. Panaskan hingga mendidih. Masukkan kubis. Aduk hingga kubis layu. Beri kecap manis. Aduk rata. Terakhir, matikan api, lalu masukkan irisan tomat dan daun bawang. Sajikan di piring cekung. Taburi dengan bawang goreng (opsional).\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(376, 2, 'Asem Pedes Iga Sapi', 'Resep praktis Asem Pedes Iga Sapi yang bisa dicoba di rumah.', '[\"500 gr Iga Sapi\", \"2 liter Air Bersih\", \"7 siung Bawang Putih\", \"10 siung Bawang Merah\", \"3 ruas jari Kunyit\", \"2 ruas jari Lengkuas\", \"2 ruas jari Jahe\", \"5 lembar Daun Jeruk\", \"2 batang Sereh\", \"3 biji Cabai Merah Besar\", \"10-15 biji Cabai Rawit\", \"1 sdt Merica Bubuk\", \"3 buah Tomat / Blimbing Wuluh\", \"Gula\", \"Garam\", \"Penyedap Rasa\"]', '[\"Masak air sampai mendidih, rebus iga sambil sesekali dibuanh buih nya yg berwarna coklat (supaya tidak bau). Masak hingga cukup empuk, matikan api.\", \"Iris-iris bawang putih, bawang merah, kunyit, lengkuas, jahe, cabai merah dan cabai rawit\", \"Panaskan minyak, masukkan sereh dan daun jeruk. Lalu masukkan bawang merah, bawang putih, kunyit, lengkuas dan jahe masak sampai harum\", \"Masukkan cabai merah dan cabai rawit masak sampai layu\", \"Masukkan tumisan bumbu kedalam rebusan iga sapi tadi, tambahkan merica bubuk, garam, gula dan penyedap rasa.\", \"Masak hingga daging empuk, terakhir masukkan tomat yang masing-masing sudah dipotong menjadi 4 bagian. Masak sebentar lalu matikan api\", \"Asam pedas iga sapi siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(377, 3, 'Rendang daging sapi istimewa', 'Resep praktis Rendang daging sapi istimewa yang bisa dicoba di rumah.', '[\"1 kg daging sapi, iris memotong serat\", \"2 bh kentang, kupas potong dadu\", \"1 liter santan encer\", \"1 liter santan kental\", \"5 sdm kelapa parut sangrai, haluskan\", \"Bumbu halus :\", \"10 siung bawang merah\", \"15 siung bawang putih\", \"5 cm kunyit, kupas\", \"3 cm jahe, kupas\", \"1 ggm cabe kering, rendam\", \"6 bh cengkeh\", \"1 sdm ketumbar\", \"8 bj kemiri\", \"Bumbu utuh :\", \"5 cm lengkuas, kupas geprek\", \"2 btg serai, ambil tengahnya geprek\", \"3 bh bunga lawang\", \"2 lbr daun salam\", \"2 lbr daun jeruk\", \"1 bh gula merah\", \"2 sdm gula pasir\", \"1 sdm garam\", \"1 sdm masako sapi\"]', '[\"Masak daging sapi dg santan encer sampai menyusut\", \"Haluskan bumbu lalu masukan ke rebusan daging sapi bersama bumbu utuh\", \"Aduk terus agar bumbu tercampur rata\", \"Masukan kelapa parut sangrai dan gula garam masako. Aduk lagi\", \"Saat santan mulai menyusut lagi masukan santan kental n kentang.\", \"Masak sampai benar2 menyusut dan mengeluarkan minyak\", \"Selamat mencoba bunda..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(378, 3, '👉 Sambal Goreng Hati sapi dan tempe 👈 #Ketopad', 'Nikmati kelezatan 👉 Sambal Goreng Hati sapi dan tempe 👈 #Ketopad dengan resep sederhana ini.', '[\"Bahan A :\", \"500 gr hati sapi\", \"1 papan tempe\", \"Bahan B : 👉 Haluskan\", \"1 buah cabe merah besar (suka pedas bisa tambah rawit)\", \"8 siung bawang merah\", \"3 siung bawang putih\", \"2 butir kemiri sangrai\", \"1 cm lengkuas\", \"1 lembar daun jeruk\", \"1/2 buah tomat\", \"Secukupnya himsalt / sea salt\", \"Bahan C ;\", \"1 Bombay kecil cincang\", \"1 lembar daun jeruk\", \"1 batang sereh geprek\", \"100 ml santan kental\"]', '[\"Cuci bersih hati sapi rebus 1/2 matang,tiriskan iris kotak kotak kecil\", \"Iris Tempe kotak kotak kecil\", \"Goreng hati sapi hingga matang.\", \"Goreng Tempe hingga berwarna kuning\", \"Tumis Bahan B yang sudah di haluskan hingga harum dan matang lalu sisihkan\", \"Di wajan tumis Bombay hingga layu dan harum\", \"Lalu masukkan bumbu halus yang sudah di tumis bersama daun jeruk dan sereh geprek\", \"Aduk rata tambahkan santan icip rasa lalu masukkan hati sapi dan Tempe yang sudah di goreng, masak dengan api kecil hingga santan dan bumbu meresap rata.\", \"Matikan api Sambal goreng siap di angkat dan di nikmati\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(379, 4, 'Rawon daging sapi', 'Buat Rawon daging sapi yang nikmat dengan langkah-langkah mudah ini.', '[\"1 kg daging sapi campur tetelan sedikit\", \"2 liter air\", \"Bumbu halus :\", \"8 keluwek\", \"10 siung bawang merah\", \"4 siung bawang putih\", \"4 buah kemiri\", \"1 sdm ketumbar\", \"1 ruas jahe\", \"1 ruas kunyit\", \"1 ruas lengkuas\", \"1 sdt jinten\", \"1 sdm lada halus\", \"Secukupnya Garam gula\", \"5 lembar daun jeruk\", \"Bumbu pelengkap :\", \"2 batang sereh\", \"3 lembar daun salam\", \"Garam gula. Dan penyedap\", \"Bahan pelengkap :\", \"kecambah\", \"Kerupuk\", \"Sambal\"]', '[\"Rebus daging dengan api kecil sampai empuk (me kurleb 1jam) angkat tiriskan setelah dingin potong2 sesuai selera airnya simpan untuk campuran rawon\", \"Sangrai duo bawang ketumbar jinten kunyit kemiri sampai harum\", \"Pecahkan keluwek ambil isinya lalu rendam air panas\", \"Uleg semua bahan bumbu halus lalu masukkan keluwek uleg sampai merata\", \"Tumis bumbu halus sampai harum masukkan salam sereh aduk rata masukkan daging aduk aduk sampai bumbu meresap\", \"Masukkan air kaldu rebusan daging tambahkan air biasa sampai kurleb 2ltr biarkan matang dan meresap\", \"Tambahkan garam gula dan penyedap sampai rasa nya pass\", \"Sajikan. Dengan bahan pelengkap siap disantap\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(380, 2, 'Beef steak with bbq sauce', 'Resep Beef steak with bbq sauce yang lezat dan mudah dibuat di rumah.', '[\"500 gr daging sirloin (sy beli lgsg d supermarket ya)\", \"Daun thyme (sy beli yg sdh pack)\", \"secukupnya Garam\", \"1/2 bungkus saus bbq delmonte\", \"1/2 cup jamur kancing (sy pakai yg kalengan narciscus itu)\", \"1/4 buah bawang bombay\", \"6 siung bawang putih\", \"250 gr kentang (sy pakai yg frozen)\", \"Secukupnya air\", \"Butter\", \"Kaldu jamur\", \"1/2 sdt oregano\"]', '[\"Marinasi daging dgn garam, merica dan thyme. Lalu diamkan di dalam kulkas krg lebih 1jam.\", \"Utk saus : rajang bawang bombay. Potong jamur menjadi 2. Stlh itu, panaskan butter di teflon, lalu tumis bombay hingga harum. Stlh itu masukkan jamur, tumis sebentar. Masukkan saus delmonte dan air secukupnya. Lalu masukkan garam, merica, kaldu jamur dan oregano sedikit. Tes rasa sesuai dgn yg di inginkan\", \"Geprek bawang putih (tdk pakai kulit). Lalu panaskan butter di teflon, taru daging yg sdh di marinasi ke dalam teflon, masukkan bawang putih dan daun thyme. Masak hingga matang\", \"Kentang : saya goreng menggunakan air fryer. Stlh matang, di campur dgn sedikit garam\", \"Sajikannn~\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(381, 2, 'Japanese Beef Curry with Instant Roux', 'Buat Japanese Beef Curry with Instant Roux yang nikmat dengan langkah-langkah mudah ini.', '[\"1 bungkus Japanese Curry Instant, sy pakai brand Golden Curry tipe Mild\", \"350 gram daging sapi, potong kotak selebar 2 cm\", \"2 buah wortel, potong serong bergantian selebar 2 cm\", \"3 buah kentang, potong kotak bagi 8\", \"3 butir bawang bombai, iris tipis\", \"8 buah jamur kancing putih, iris tipis\", \"2 butir bawang putih, cincang halus\", \"2 ruas jahe, diserut halus\", \"1 liter air\", \"2 sdt garam\", \"2 sdm saus tomat\", \"3 sdm olive oil, untuk menumis\", \"2 lembar daun salam\", \"1/2 sdt lada hitam, untuk daging\", \"1/2 sdt garam, untuk daging\", \"2 sdm fresh milk\", \"1 sdm kecap inggris\", \"1/4 buah apel, diserut halus (optional)\"]', '[\"Potong daging kemudian balurkan dengan garam dan lada hitam kemudian sisihkan. Diamkan selama 10 menit.\", \"Panaskan olive oil kemudian masukkan bawang bombai, tumis sampai harum\", \"Masukkan garam dan tumis sekitar 2 menit, kemudian masukkan jahe, bawang putih dan saus tomat. Tumis sekitar 3 menit.\", \"Masukkan daging dan tumis sampai daging berubah warna / setengah matang. Kemudian masukkan jamur, wortel dan kentang, tumis selama 2 menit.\", \"Tuang air dan rebus sampai mendidih dengan api besar. Buang lemak yang mengambang. (Air harus menutupi sayuran)\", \"Masukkan daun salam, tutup panci dan didihkan dengan api kecil sampai daging / sayuran menjadi empuk.\", \"Jika daging dan sayuran sudah empuk, masukkan curry instant. Pastikan curry tidak menggumpal. Masak dengan api besar sampai curry mengental.\", \"Tuang susu dan kecap inggris, aduk rata. Kemudian tambahkan apel, aduk dan masak sekitar 2 menit. Angkat dan sajikan selagi panas.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(382, 2, 'Rendang daging sapi', 'Rendang daging sapi - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 kg daging sapi\", \"santan (1buah kelapa)\", \"1 lembar daun salam\", \"1 lembar daun jeruk\", \"1 lembar dUn kunyit\", \"secukupnya garam\", \"2 sendok mkn gula\", \"bumbu halusnya\", \"1 ons cabe merah keriting\", \"6 siung bawang merah\", \"4 siung bawang putih\", \"1 ruas jahe\", \"1 ruas lengkuas\", \"2 batangsereh\"]', '[\"Cuci daging kemudian potong sesuai selera\", \"Masukan daging ke dlm wadah, lalu lumuri daging dgn garam\", \"Blender semua bumbu halus kemudian campur daging dgn bumbu halus tsb, santan, dan sedikit gula, daun salam, daun jeruk, dan daun kunyit, lalu aduk hingga tercampur semua.\", \"Masak daging dgn api sedang,, sesekali di aduk2 sampai air menyusut.\", \"Tusuk daging dgn garpu untuk mengetahui daging udh empuk atau blm, klu bLm tambahkan lg air sampai daging empuk\", \"Rendang sapi siap di santap,,,yummmiii\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(383, 2, 'Sapi tumis wortel saus tiram pedas nikmat', 'Resep Sapi tumis wortel saus tiram pedas nikmat yang lezat dan mudah dibuat di rumah.', '[\"1,5 kg daging sapi\", \"1 bombay\", \"3 siung bawang putih\", \"1 ruas jahe di geprek\", \"2 lmbr daun jeruk\", \"1 btg serai\", \"secukupnya Garam\", \"secukupnya Saus tiram\", \"Irisan wortel (optional)\", \"2 bh cabe merah dan cabe hijau\", \"5 bh rawit\", \"1 bh tomat\", \"secukupnya Kecap inggris buat merendam\"]', '[\"Rendam daging dengan kecap inggris dan saus tiram sekitar 1 jam biar meresap\", \"Tumis semua bahan tadi bawang putih, bombay, jahe, masukkan irisan wortel beri air\", \"Setelah itu masukkan lagi saus tiram, garam, tomat,daging pokoknya masukin semua bahan lalu cek rasa setelah itu tunggu sampai matang\", \"Lalu setelah dirasa cukup matikan kompor dan hidangkan\", \"Selamat mencoba ya bunda\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(384, 4, 'Bakso sapi home made', 'Bakso sapi home made - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"300 gr daging sapi giling\", \"1 butir telur\", \"2 siung bawang putih\", \"2 balok kecil es batu\", \"1/4 sagu/tapioka\", \"1 sendok baking powder\", \"secukupnya Garam\", \"secukupnya Lada\", \"secukupnya Gula\", \"secukupnya Kaldu jamur\", \"secukupnya Tetelan\", \"Pelengkap:\", \"Bihun jagung\", \"Sawi ijo\", \"Seledri daun bawang\", \"Bawang goreng\", \"Sambal\"]', '[\"Masukan daging giling, telur, bawang putih, es batu, garam, lada, dan gula ke dalam blender sampai halus.\", \"Taruh ke dalam wadah kering dan masukan baking powder dan sagu. Aduk sampai kalis.\", \"Siapkan panci berisi tetelan sapi dan air, diamkan sampai mendidih.\", \"Kalau sudah aplikasikan ke tangan macem bikin bola2 (kalo aku kadang gede kadang kecil hahahaha) lalu cemplungin ke dalam panci yg berisi kaldu sapi.\", \"Setelah bakso mengapung, dan dirasa baksonya sudah matang, masukan seledri dan daun bawang yg sudah dipotong\", \"Setelah matang bisa diracik sendiri. Selamat mencoba :)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(385, 4, 'Lidah Sapi Saus Inggris', 'Resep Lidah Sapi Saus Inggris yang lezat dan mudah dibuat di rumah.', '[\"500 gram lidah sapi\", \"4 siung bawang putih diiris halus\", \"1 buah bawang bombay diiris halus\", \"5 cm kayu manis\", \"2 buah cengkeh\", \"Secukupnya saus inggris (worcestershire sauce), kecap manis, saus tomat, garam, merica bubuk, pala bubuk, gula\", \"1,5 liter air untuk merebus lidah sapi\", \"Secukupnya minyak goreng atau margarin\"]', '[\"Presto lidah sapi selama 20 menit dengan air kira-kira 1,5 liter. Setelah itu potong-potong sebesar dadu. Sisihkan.\", \"Tumis bawang putih, bawang bombay, kayu manis, dan cengkeh sampai harum. Masukkan lidah sapi. Aduk-aduk sampai rata.\", \"Tambahkan air kaldu sisa merebus lidah sedikit demi sedikit lalu masukkan saus inggris, kecap manis, merica bubuk, pala bubuk, garam, dan gula.\", \"Masak hingga bumbu meresap dan lidah menjadi empuk.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(386, 4, 'Brokoli tumis daging sapi', 'Brokoli tumis daging sapi dengan daging sapi empuk dan bumbu kaya rasa.', '[\"1/4 kg daging sapi\", \"1 bongkah brokoli uk besar\", \"5 siung bawang putih geprek cincang kasar\", \"1 ruas jahe geprek\", \"1 sdt merica bubuk\", \"2 sdt garam\", \"1 sdt gula\", \"1 sdm minyak wijen\", \"1 sdt kecap inggris (boleh skip kalo ga ada)\"]', '[\"Rebus daging dengan menggunakan bawang putih sampai empuk dan ada kaldunya. Angkat dinginkan dan iris sesuai selera\", \"Tumis bawang putih dan jahe hingga harum\", \"Masukkan brokoli, dan irisan daging, aduk2. Masukkan kecap inggris, minyak wijen, gula, garam, aduk aduk.\", \"Tuangkan kaldu sapi sedikit demi sedikit hingga brokoli matang. Krn ini tumisan jadi saya sisakan kuah tumisannya tidak terlalu banyak. Maka dari itu, tuangkan kaldunya hanya supaya brokoli matang (jangan kebanyakan)\", \"Cek rasa, kalo sudah pas siap dihidangkan. Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(387, 4, 'Tumis keciwis cah sapi ala bunda jkb', 'Cara membuat Tumis keciwis cah sapi ala bunda jkb yang enak dan praktis untuk keluarga.', '[\"100 gr Keciwis sekitar\", \"100 gr Daging sapi iris tipis\", \"5 iris Bawang merah\", \"3 iris Bawang putih\", \"7 iris Cabe rawit merah\", \"2 sdm Saus tiram\", \"secukupnya Garam\", \"1 sachet Gula diabetasol\"]', '[\"Tumis daging sapi sampai berubah warna, masukkan bumbu iris, aduk sampai wangi. Tambahkan sedikit air dan garam gula serta saus tiram. Koreksi rasa\", \"Masukkan daun keciwis, aduk sebentar sampai layu. Angkat dan hidangkan selagi hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(388, 4, 'Oseng Koyor Sapi', 'Oseng Koyor Sapi - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 kg daging koyor sapi\", \"5 siung bawang merah, iris\", \"2 siung bawang putih, iris\", \"3 buah cabe rawit merah (boleh ditambah bila suka)\", \"2 buah cabe merah keriting, iris\", \"1/2 buah tomat, belah jadi 2\", \"2 lembar daun salam\", \"2 lembar daun jeruk\", \"1 buah sereh, geprek\", \"1 ruas jahe, geprek\", \"1 ruas lengkuas, geprek\", \"1 sdm gula merah cair\", \"1 sdt merica bubuk\", \"1 sdm kecap manis\", \"2 sdm minyak sayur\", \"Secukupnya gula pasir\", \"Secukupnya garam\", \"Secukupnya penyedap rasa (apabila suka)\", \"150 air kaldu\", \"1 liter air (untuk merebus daging & kuah kaldu)\"]', '[\"Rebusan daging (I): Potong daging koyor kecil-kecil. Siapkan air dingin ke dalam panci rebusan. Masukkan irisan daging. Masak sampai air mendidih dan kotoran terangkat. Buang airnya tiriskan daging\", \"Rebusan daging (II): Siapkan panci yang sudah terisi 1Liter air dingin. Masukkan daging beserta sejumput garam dan merica. Rebus daging sampai empuk.\", \"Panaskan minyak ke dalam wajan dan masukkan irisan bawang merah dan bawang putih. Tumis hingga setengah matang\", \"Masukkan irisan cabe, salam, daun jeruk, jahe geprek, sereh geprek, laos geprek, dan tomat. Masak hingga bumbu harum\", \"Masukkan daging koyor sapi yang telah direbus. Masak daging hingga bumbu tercampur. Tambahkan gula, garam, merica, penyedap rasa, kecapa manis kemudian masak kembali\", \"Masukkan air kaldu. Masak sampai matang dan air menyusut.\", \"Koreksi rasa\", \"Oseng daging koyor siap dihidangkan. Sajikan dengan taburan bawang goreng untuk menambah kenikmatan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(389, 2, 'Sambel goreng kentang santan+ ati sapi 👍', 'Resep praktis Sambel goreng kentang santan+ ati sapi 👍 yang bisa dicoba di rumah.', '[\"1/4 kentang\", \"1/4 ati sapi\", \"2 lembar daun salam\", \"1 batang serai (keprek)\", \"1 ruas lengkuas (keprek)\", \"1/2 bungkus kara ukuran 65ml campur dengan 100ml air\", \"Bumbu halus :\", \"150 gr cabe merah keriting/secukupnya\", \"50 gr cabe rawit setan/secukupnya\", \"3 butir kemiri\", \"7 siung bawang merah\", \"2 siung bawang putih\", \"1/2 buah tomat ukuran sedang\", \"Untuk rebusan ati :\", \"Seruas jahe\", \"2 lembar daun salam\"]', '[\"Rebus ati sapi,jahe dan daun salam kurang lebih 30 menit,setelah matang,potong dadu ati sapi\", \"Potong dadu kentang dan goreng hingga matang\", \"Siapkan minyak untuk menumis,tumis bumbu halus tambahkan daun salam,lengkuas,serai,garam dan penyedap rasa tumis hingga harum dan matang,(koreksi rasa)\", \"Masukan santan dan air ke tumisan..aduk2,masukan ati sapi dan kentang\", \"Aduk merata,tutup wajan, dan kecilkan api..tunggu sampai santan surut..aduk2 lagi dan sajikan😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(390, 2, 'Sambal Kentang + Bakso Sapi', 'Resep praktis Sambal Kentang + Bakso Sapi yang bisa dicoba di rumah.', '[\"1/2 kg Kentang\", \"1/2 bungkus Bakso Sapi\", \"2 helai Daun Salam\", \"Gula Merah\", \"Bumbu Halus:\", \"6 buah Bawang Merah\", \"4 buah Bawang Putih\", \"1/4 kg Cabai Merah\", \"4 buah Cabe Rawit\", \"1/2 iris Tomat\"]', '[\"Kupas kentang lalu potong dadu, kemudian goreng dan tiriskan.\", \"Haluskan semua bumbu, lalu tumis dengan sedikit minyak. Beri garam, gula merah sedikit dan masukan daun salam\", \"Masukan bakso dan kentang. Aduk aduk. Kemudian koreksi masakan lalu sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(391, 4, 'Beef mashroom', 'Buat Beef mashroom yang nikmat dengan langkah-langkah mudah ini.', '[\"1/4 daging sapi potong dadu\", \"1/4 jamur tiram potong sesuai selera\", \"1 buah jagung pipil atau serut kasar menggunakan pisau\", \"2 bks kecil putih telur yg sudah di rebus potong dadu\", \"1 buah bawang bombay ukuran sedang potong memanjang\", \"1 batang daun bawang potong serong\", \"1 buah tomat besar potong memanjang\", \"1/2 sdm maizena larutkan dengan sedikit air\", \"1 bks saos tiram\", \"1/2 sdt gula pasir atau sesuai selera\", \"1 bks penyedap rasa sapi\", \"5 sdm minyak goreng\", \"1 buah kuning telur larutkan bersama tepung maizena\", \"sedikit merica\"]', '[\"Panaskan 5sdm minyak goreng.masukan bawang bombay.daun bawang dan tomat yg sudah diiris.tumis sampai harum\", \"Masukan daging sapi.tambahkan sedikit garam dan merica.lalu beri sdikit air agar daging sapi bisa matang sempurna.tunggu sampai air mulai berkurang dan daging mulai empuk.\", \"Masukan jagung serut disusul jamur tiram dan putih telur.masak sampai semua bahan matang.\", \"Masukan saos tiram.penyedap rasa.merica dan tmbahkan sedikit gula pasir atau sesuai selera.aduk sampai rata.masukan larutan tepung maizena yg sudah di campur kuning telur.cek ras.masak sampai kuah meletup letup lalu angkat.\", \"Beef mashroom siap sihidangkan dengan nasi panas.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(392, 2, 'Hati sapi + kentang puedes', 'Resep Hati sapi + kentang puedes yang lezat dan mudah dibuat di rumah.', '[\"1/2 kg hati sapi potong agak tipis\", \"1/2 kentang\", \"3 siung bawang merah\", \"3 siung bawang putih\", \"7 buah cabai merah kriting\", \"1/2 ons cabe rawit\", \"1 1/2 sdt garam\", \"1 sdt garam\", \"secukupnya Micin\", \"secukupnya Kecap manis\", \"2 batang serai\", \"3 lbr daun salam\", \"5 lbr daun jeruk\", \"1 ruas jahe\", \"secukupnya Kunyit bubuk\", \"Minyak untuk menumis\"]', '[\"Potong tipis hati sapi dan kentang sisihkan. Haluskan bumbu cabe, bawang merah, bawang putih, sampai halus. Geprek jahe dan serai sisihkan.\", \"Panaskan 3 sdm minyak goreng, tumis bumbu halus + daun salam, daun jeruk, jahe, serai aduk rata sampai harum tambahkan kunyit bubuk dan masukan hati sapi aduk rata tambahkan 1 gelas air putih tutup biarkan mendidih.\", \"Setelah mendidih masukan kentang, garam, gula, micin aduk rata tutup panci hingga kentang masak tambahkan kecap manis aduk rata koreksi rasa. Bila dirasa udah pas makan api dan biarkan dingin\", \"Ati sapi kentang siap di hidangkan kan bersama nasi putih.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(393, 3, 'Dendeng sapi bumbu kecap', 'Resep Dendeng sapi bumbu kecap yang lezat dan mudah dibuat di rumah.', '[\"1 bungkus dendeng sapi\", \"3 buah bawang merah\", \"2 buah bawang putih\", \"secukupnya Garam\", \"1 sendok kecil gula pasir\", \"secukupnya Lada bubuk\", \"secukupnya merica bubuk\", \"kecap manis\", \"bumbu royco (ayam)\", \"secukupnya air matang\", \"minyak goreng\"]', '[\"Potong dendeng sesuai selera kl saya dadu besar2\", \"Lalu goreng setengah matang / sebentr dan tiriskan\", \"Potong halus bawang merah dan bawang putih\", \"Siapkan wajan dan beri sedikit minyak\", \"Tumis bawang merah dan bawang putih hingga bau wangi\", \"Lalu tambahkan sedikit garam,rocyo ayam,lada bubuk\", \"Aduk2 lalu masukkan dendeng yg sudah ditiriskan td\", \"Lalu aduk2 dan tambahkan sedikit merica bubuk\", \"Lalu masukkan kecap manis dan sedikit air matang\", \"Lalu tambahkan sedikit gula pasir\", \"Lalu tes rasa dan siap disajikan dlm keadaan hangat\", \"NB : utk yg suka pedas bisa ditambahkan cabe rawit merah\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(394, 2, 'Soto Sapi Kuah Bening', 'Sajian Soto Sapi Kuah Bening yang praktis dan lezat untuk dinikmati bersama.', '[\"1/2 kg daging tetelan sapi\", \"1 buah lobak ukuran besar, cuci bersih dan iris seuai selera\", \"1 batang serai, keprek\", \"Seujung kelingking jahe, keprek\", \"Secukupnya selederi, cincang\", \"2 biji kapulaga\", \"3 biji cengkeh\", \"Secukupnya kayu manis\", \"Secukupnya bawang pre, iris besar atau sesuai selera\", \"Air(sesuai kebutuhan yaa)\", \"Bumbu halus :\", \"2 siung bawang putih\", \"1 siung bawang merah\", \"Secukupnya merica\", \"Secukupnya ketumbar\", \"Secukupnya pala\", \"Secukupnya jintan\", \"Sedikit minyak untuk menumis\", \"Secukupnya Garam\", \"Secukupnya Kaldu bubuk rasa sapi\"]', '[\"Cuci bersih daging lalu rebus daging(Buang air rebusan pertama biar kuah gak keruh) Masukkan lagi air dan rebus kembali daging hingga empuk dan berkaldu\", \"Setelah daging empuk dan berkaldu... Keluarkan daging dan iris\\\" sesuai selera... Masukkan kembali ke air rebusan... Tambahkan lagi air nya jika di rasa kurang\", \"Rebus lagi daging... Dan masukkan serai jahe kapulaga cengkeh dan kayu manis...\", \"Sambil menunggu aroma keluar dari rebusan daging.. Siapkan wajan panaskan sedikit minyak lalu tumis bumbu halus... Setelah wangi masukkan bumbu halus dalam rebusan daging..\", \"Masukkan lobak dalam rebusan daging tunggu hingga lobak empuk\", \"Setelah lobak empuk masukkan daun pre dan daun seledri..\", \"Masukkan garam dan kaldu bubuk... Test rasa...\", \"Dan siap sajikan dengan sambal atau pelengkap lainnya(di warung biasanya si ibuk penjual nambahin lada bubuk dan kecap asin di mangkok saji) 😄😄😄 Dimakan hangat\\\" tambah enak ya... 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(395, 2, 'Pepes Tahu Daging Sapi', 'Pepes Tahu Daging Sapi - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"2 buah tahu putih ukuran besar, rendam air panas 1/2 jam\", \"100 gram daging sapi cincang\", \"6 siung bawang putih\", \"7 butir bawang merah\", \"3 buah cabe merah besar\", \"10 buah cabe rawit merah\", \"1 ruas kecil kencur\", \"secukupnya Garam\", \"secukupnya Gula\", \"Penyedap rasa\", \"Daun pisang untuk membungkus\", \"Minyak goreng untuk menumis daging\"]', '[\"Tumis daging cincang hingga matang. Sisihkan.\", \"Haluskan bawang putih, bawang merah, cabe, dan kencur. Beri garam dan gula.\", \"Haluskan tahu putih. Campur dengan tumisan daging dan bumbu halus. Beri penyedap rasa. Jangan lupa tes rasa.\", \"Taruh 1 sdm adonan tahu ke daun pisang. Gulung lalu semat dengan tusuk gigi.\", \"Kukus pepesan hingga matang. Biasanya selama 30 menit.\", \"Sajikan dengan nasi putih dan sayur bayam.\", \"Daging sapi bisa diganti pake teri nasi. Kalo pake teri garam dikurangi biar gak terlalu asin.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(396, 2, 'Beef stew dan mashed potatoes', 'Cara membuat Beef stew dan mashed potatoes yang enak dan praktis untuk keluarga.', '[\"500 gr daging sapi (potong dadu)\", \"Lobak / kentang (potong dadu jangan terlalu kecil)\", \"2 buah Tomat besar  potong2\", \"Wortel (potong jgn terlalu kecil)\", \"1 bawang bombay (potong dadu)\", \"2 blok Kaldu sapi\", \"1 sdt thyme\", \"1/2 sdt oregano\", \"1/2 atau 1 sdt cayenne powder / klo ga ada pakai cabai bubuk\", \"1 sdm garam\", \"1 sdt lada\", \"500 ml air\", \"Minyak utk menggoreng\", \"Untuk mash potatoes :\", \"5 buah kentang ukuran sedang\", \"2 sdm Butter\", \"secukupnya Susu cair\"]', '[\"Panaskan 2 sdm minyak goreng utk menggoreng daging sampai matang kira2 10 menit, lalu masukan bawang bombay, di aduk terus sampai bagian bawah panci terlihat agak gosong. Lalu tambahkan air yang sudah di campur bersama kaldu blok yang sudah di tambahkan thyme, oregano, cayenne powder, garam dan lada.\", \"Masukan lobak terlebih dahulu, tunggu kira2 45 menit lalu masukan wortel dan tomat.\", \"Masak dengan api kecil +- 3 -4 jam\", \"Untuk membuat mash potatoes :\", \"Rebus kentang yang sudah di potong kotak selama 20 menit. Setelah matang, tiriskan lalu tumbuk kentang sampai halus. masukan butter dan juga susu. Beri garam dan lada. Koreksi rasa.\", \"Selesai :)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(397, 2, 'Tumis Jamur bakso sapi.', 'Sajian Tumis Jamur bakso sapi. yang praktis dan lezat untuk dinikmati bersama.', '[\"10 bakso sapi potong tipis2.\", \"200 grm jamur kancing.. (sesuai slera)\", \"3 siung bawang putih\", \"5 siung bawang merah\", \"10 cabe rawit\", \"Daun bawang secukupnya\", \"1 buah tomat\", \"sesuai selera Gula garam\", \"3 sdm kecap manis\", \"1 sdm saus tiram (jika ada)\"]', '[\"Cuci bersih smua bumbu..iris2...\", \"Cuci bersih jamur..iris2..bakso sapi iris tipis\", \"Nyalakan api sedang..tumis bumbu sampai harum...\", \"Masukkan bakso sapi iris aduk2..kmudian masukkan jamur..aduk rata..beri gula garam..sdikit air..tggu sampai matang..beri kecap manis..saus tiram..\", \"Stelah matang angkat sajikan...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(398, 2, 'Tongseng Sapi', 'Resep Tongseng Sapi ala rumahan yang dijamin menggugah selera.', '[\"500 gram daging sapi\", \"3 lembar kol. Iris kasar (sy g pake. Stok kosong 😂)\", \"1 buah tomat. Potong2\", \"750 ml santan\", \"8 biji cabe rawit merah utuh\", \"1/2 ruas lengkuas. Geprek\", \"1 batang sere. Geprek\", \"2 lembar daun salam\", \"3 cm kayu manis\", \"2 sdm kecap manis\", \"Secukupnya garam. Gula dan kaldu bubuk\", \"Secukupnya air\", \"Bumbu halus 👇\", \"6 siung bawang merah\", \"4 siung bawang putih\", \"4 biji cabe merah keriting\", \"2 butir Kemiri\", \"2 sdt ketumbar butiran\", \"1 sdt merica butiran\", \"1/2 ruas kunyit\"]', '[\"Rebus daging sapi. Tambahkan sedikit garam. Rebus daging hingga setengah matang. Potong2\", \"Tumis bumbu halus. Lengkuas. Sere. Daun salam. Dan kayu manis hingga harum dan matang\", \"Masukkan daging yg dah dipotong. Aduk2. Kemudian masukkan secukupnya air. Tambahkan kecap manis. garam. Gula dan kaldu bubuk. Masak sampai daging empuk dan bumbu meresap\", \"Tambahkan santan. Dan cabe utuh. Masak sampai matang. Jangan lupa tes rasa ya... 😂\", \"Sebelum diangkat masukkan tomat dan kol. Aduk2 dan angkat\", \"Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(399, 4, 'Daging Sapi Lada Hitam', 'Daging Sapi Lada Hitam - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1/2 kg Daging sapi\", \"Bumbu Tumis:\", \"10 butir bawang putih\", \"1 1/2 cm Jahe\", \"Bumbu Tambahan :\", \"2 sdm kecap manis\", \"1/2 sdm masako\", \"1 1/2 sdm gula pasir\", \"5 sdm lada hitam\", \"Bumbu Rendam Daging :\", \"2 sdm minyak goreng\", \"4 sdm saos tiram\", \"3 sdm kecap manis\", \"Garnish:\", \"7 buah cabe merah besar (buang bijinya lalu potong kotak)\", \"7 buah cabe hijau (buang bijinya lalu potong kotak)\", \"1 buah bawang bombay ukuran besar potong kotak2\", \"3 sdm air + 1 sdt tepung maizena\"]', '[\"Potong tilis memanjang daging, lalu rendam dengan bumbu rendaman dagunh selama 1 jam sampai meresap.\", \"Tumis bumbu halus sampai harum.\", \"Masukkan daging. Tambahkan 5 sdm. Lalu tutup pancinya.\", \"Setelah air berkurang sedikit. Tambahkan kecap 2 sdm. Lalu tambahkan masako. Lalu gula pasir. Lalu masukkan bahan garnish.\", \"Aduk rata, lalu tambahkan 5 sdm lada hitam.\", \"Setelah kuah menyusut. Masukkan larutan tepung maizena. Aduk rata. Lalu masak hingga kuat agak mengental dan matang.\", \"Sajikan dengan nasi hangat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(400, 2, 'Sop Iga Sapi', 'Resep praktis Sop Iga Sapi yang bisa dicoba di rumah.', '[\"1 ons iga sapi\", \"2 bungkus sop2an\", \"2 butir kentang\", \"Bahan yg di haluskan :\", \"5 butir bawang merah\", \"3 butir bawang putih\", \"secukupnya Pala\", \"secukupnya Kemiri\", \"Sahang\", \"Air\", \"Minyak untuk menumis\", \"Garem\", \"Penyedap rasa\", \"Taburan bawang goreng\"]', '[\"Cuci iga sapi lalu rebus dlu supaya empuk sebentar saja lalu buang airnya\", \"Tumis bumbu yg di halusi lalu masukan ke air yg baru lalu masukan iganya kentang dan wortel\", \"Kalo sudah rada lama baru kita masukan daun bawang dan lainnya penyedap rasa garam\", \"Kalau sudah jadi taburi bawang goreng siap santap\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(401, 2, 'Tumis Beby buncis, daging sapi', 'Buat Tumis Beby buncis, daging sapi yang nikmat dengan langkah-langkah mudah ini.', '[\"Buncis beby\", \"Daging sapi giling 4 sendok makan(sesuaikan selera)\", \"3 biji Bakso sapi\", \"5 cabe rawit (di tambah boleh,sesuai selera masing\\\")\", \"6 cabe merah keriting\", \"3 buah bawang putih\", \"5 buah bawang merah\", \"2 biji kemiri\", \"1 sdm Saus tiram\", \"Kecap manis\", \"Gula, garam, lada (secukupnya)\"]', '[\"Siangin dulu buncisnya di buang kepala sama buntutnya,\", \"Goreng cabe, merah, cabe rawit, bawang putih, sampe agak layu\", \"Ulek cabe, kemiri bawang putih sampai halus. iris tipis-tipis bawang merah.\", \"Tumis bawang merah sampai harum, masukan bumbu ulek, tumis sebentar, masukan daging sapi giling aduk\\\" sampai berubah warna, tambahkan saus tiram.\", \"Masukan buncis, tambahkan kecap manis, garam, gula lada secukupnya. Masukan air satu gelas, tumis\\\" samapai agak asat airnya cobain, kalo sudah pas angkt n sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(402, 2, 'Sup Daging Sapi', 'Cara membuat Sup Daging Sapi yang enak dan praktis untuk keluarga.', '[\"250 gram daging sapi, potong kecil-kecil\", \"10 batang kacang panjang, potong panjang 4 cm\", \"8 siung bawang putih, memarkan\", \"800 ml air\", \"2 sdm minyak wijen (pilih yang terbuat dari 100% minyak wijen)\", \"Secukupnya garam\", \"Secukupnya merica bubuk\", \"Sejumput pala bubuk\", \"Secukupnya margarin untuk menumis\"]', '[\"Lelehkan margarin. Tumis bawang putih hingga wangi. Masukkan air, tunggu hingga mendidih.\", \"Masukkan daging. Rebus kurang lebih 8 menit atau hingga empuk dengan api sedang.\", \"Masukkan kacang panjang. Aduk. Rebus 1 menit dengan campuran daging agar warna hijau segarnya bertahan.\", \"Masukkan merica, garam, pala, dan minyak wijen. Aduk sebentar. Matikan api.\", \"Sajikan selagi hangat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(403, 3, 'Kalio Daging Sapi', 'Hidangan daging sapi istimewa: Kalio Daging Sapi.', '[\"1/2 kg daging sapi\", \"1/4 kg kentang (opsional)\", \"1 batang serai (memarkan)\", \"3 cm lengkuas (memarkan)\", \"1 lembar daun kunyit\", \"2 lembar daun salam\", \"3 lembar daun jeruk\", \"2 buah cengkeh\", \"3 cm kayu manis\", \"3 buah kapulaga\", \"2 buah kembang lawang\", \"200 ml santan kental, 400 ml santan encer(sy pakai kara 200ml)\", \"Bumbu halus :\", \"6 siung bawang merah\", \"2 siung bawang putih\", \"5 buah cabe merah keriting\", \"5 buah cabe merah besar\", \"4 buah kemiri (sangrai)\", \"1 sdt ketumbar (sangrai)\", \"1/2 sdt jinten (sangrai)\", \"3 cm kunyit (bakar)\", \"2 cm jahe\"]', '[\"Tumis bumbu halus dan semua rempah hingga harum, masukkan daging aduk2, masukkan santan encer dan air sambil sesekali diaduk2 dg api kecil.\", \"Saat daging sudah mulai empuk, masukkan santan kental dan kentang sambil terus diaduk2 hingga matang dan air tinggal sedikit\", \"Kalau pakai santan instan, saya masukinnya saat daging udah empuk. Kalau dari awal malas ngadukinnya terus😁\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(404, 4, 'Sate Goreng Sapi', 'Resep Sate Goreng Sapi yang lezat dan mudah dibuat di rumah.', '[\"200 gram daging sapi\", \"Bumbu halus:\", \"1 sdt garam\", \"4 siung bawang putih\", \"3 biji kemiri\", \"1/2 sdt ketumbar\", \"1/2 sdt lada halus\", \"Bumbu goreng:\", \"1 buah tomat hijau\", \"1 lembar daun salam\", \"2 lembar daun jeruk\", \"2 siung bawang putih\", \"4 siung bawang merah\", \"5 biji cabai rawit (atau sesuai selera)\", \"Bumbu lain:\", \"2 sdm kecap manis\", \"1/3 butir gula merah, sisir halus\", \"2 sdm air asam jawa\", \"1,5 sdm margarin\"]', '[\"Rebus daging sapi hingga empuk\", \"Haluskan bumbu halus, campur dengan bumbu lain, tes rasa\", \"Setelah daging sapi empuk, potong kotak/dadu, campur dengan bumbu yang tadi telah disiapkan. Sisihkan\", \"Siapkan bumbu goreng, tumis bawang merah hingga layu\", \"Tambahkan bawang putih, cabai, daun salam dan daun jeruk\", \"Setelah aroma keluar, masukkan daging yang telah dibumbui tadi beserta bumbunya. Tumis hingga bumbu merata\", \"Tambahkan tomat. Tes rasa dan keempukan daging. Jika daging kurang empuk bisa ditambahkan air dan dimasak hingga air habis\", \"Setelah rasa dan tingkat keempukan pas, sate goreng sapi siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(405, 4, 'Rawon Iga Sapi ala Atha', 'Resep Rawon Iga Sapi ala Atha ala rumahan yang dijamin menggugah selera.', '[\"1 kg Iga sapi\", \"Daun bawang (iris kecil)\", \"Bumbu halus:\", \"3 bh kluwek, incipin jng sampe pait\", \"6 bawang merah\", \"4 bawang putih\", \"1 sdt Lada\", \"1 sdt Ketumbar\", \"1 telunjuk Kunyit\", \"1 ruas Jahe\", \"Bumbu cemplung:\", \"1 btng serai\", \"5 lbr daun jeruk\", \"1 iris laos\", \"Senyum dan cinta 😍\"]', '[\"Rebus iga sapi 40 menit\", \"Haluskan semua bumbu\", \"Tumis bumbu yg sdh dihaluskan sampai harum,masukan bumbu cemplung\", \"Tuang tumisan bumbu kedalam rebusan daging iga\", \"Biarkan mendidih 5 menit,masukan garam,gula,kaldu sapi bubuk.\", \"Masukan irisan daun bawang,sajikan pakai cinta dan senyum 😍 pasti lebih nikmat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(406, 4, 'Sapi saus tiram + bakso + lada hitam', 'Sapi saus tiram + bakso + lada hitam - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1/4 daging sapi\", \"1 bks bakso sapi (isi 10 kecil2)\", \"Saus tiram\", \"3 sdm Kecap manis\", \"1 1/2 sdm Kecap asin\", \"secukupnya Bawang bombay\", \"secukupnya Lada hitam\", \"Paprika (bisa diganti cabai merah/hijau)\", \"Sedikit air (air kaldu sapi dr rebusan tadi)\"]', '[\"Potong dadu daging sapi\", \"Rebus hingga empuk (jangan di buang airnya)\", \"Rebus bakso 1/2 matang\", \"Tiriskan daging sapi & bakso\", \"Masukan daging sapi dan bakso dalam wadah\", \"Masukan saus tiram kecap manis kecap asin dan lada hitam ke wadah yg sdh ada sapi & baksonya\", \"Aduk2 tunggu 1 - 2 jam agar meresap, lebih baik semalaman simpan di lemari es\", \"Iris bawang bombay paprika/cabai merah/cabai hijau (jangan terlalu tipis)\", \"Tumis irisan bawang & paprika / cabai\", \"Masukan daging sapi & bakso yg telah di bumbui tadi\", \"Tambahkan air rebusan sapi atau bisa juga air biasa jika tdk ingin rasanya terlau pekat dgn sapi\", \"Biarkan hingga mengental\", \"Koreksi rasa jika kurang manis bisa tambahkan kecap, jika ke asinan bisa tambahkan air, jika lada hitam kurang berasa bisa di tambahkan lagi\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(407, 3, 'Bekal sehat dengan beef BBQ', 'Bekal sehat dengan beef BBQ dengan daging sapi empuk dan bumbu kaya rasa.', '[\"secukupnya Daging sapi\", \"1 buah Egg tofu\", \"Garam\", \"Saus Barbeque de monte\", \"1/2 sdt Oregano\", \"Selada\", \"Buncis\", \"Tomat\", \"Mayonaise maestro\"]', '[\"Daging dipotong potong lalu direbus kasi garam dikit\", \"Setelah empuk angkat kemudian rendam menggunakan saus de monte barbeque semaleman dan setegah sendok oregano\", \"Panggang daging tetep beri olesan saus de monte BBQ. Agar lebih enak\", \"Tofu dipotong dan digoreng aja\", \"Sayuran direbus seperti buncis yg lain dipotong mentah aja\", \"Cocolan mayonaise maestro\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(408, 4, 'Pare ayam daging sapi', 'Resep Pare ayam daging sapi ala rumahan yang dijamin menggugah selera.', '[\"2 buah pare ayam\", \"200 gr daging sapi (potong dadu)\", \"2 cm jahe(iris korek api)\", \"2 siung bawang putih (cincang)\", \"1 sdm saos tiram\", \"1 sdm kecap hitam\", \"1 sdm kecap asin\", \"1 sdm kecap manis\", \"gula dan garam\"]', '[\"Potong agak tebal pare lalu taburi garam,remas remas hingga layu,bilas air,tiriskan.\", \"Tumis jahe dan bawang putih hingga wangi masukkan daging sapi,aduk rata bumbui saos tiram,kecap asin,kecap hitam,kecap manis aduk aduk hingga tercampur rata.\", \"Masukkan pare aduk rata,tuang air bumbui gula dan garam.biarkan daging empuk dan pare matang.\", \"Kecilkan api dan biarkan kuah surut.\", \"Matikan api dan siap di sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(409, 4, 'Rawon Sapi', 'Buat Rawon Sapi yang nikmat dengan langkah-langkah mudah ini.', '[\"250 gr daging sapi\", \"Bumbu halus :\", \"6 biji keluwek pecahkan ambil isinya\", \"12 siung bawang merah\", \"3 siung bawang putih\", \"3 butir kemiri\", \"1 sdt Ketumbar\", \"1 sdt Lada\", \"1/2 sdt Jinten\", \"Bumbu pelengkap:\", \"2 lembar daun jeruk\", \"2 lembar daun salam\", \"1 batang serei\", \"Seruas Lengkuas\", \"2 buah Kapulaga\", \"Kayumanis\", \"Garam,gula,penyedap rasa\", \"Bahan pelengkap :\", \"Bawang goreng\", \"Kecambah\", \"Kentang goreng tipis\", \"Sambal\", \"Kerupuk udang\"]', '[\"Sangrai kemiri dan ketumbar, Uleg semua bumbu halus, lalu tumis sampai matang dan wangi masukan daging. Tumis sebentar masukan air dan bumbu pelengkap, tambahkan garam,penyedap rasa. Tes rasa deh udah pas atau blm😊😉\", \"Tinggal foto deh maunya gmn 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(410, 2, 'Daging sapi masak kecap', 'Daging sapi masak kecap dengan daging sapi empuk dan bumbu kaya rasa.', '[\"1/2 kg daging sapi\", \"1 siung bawang bombay ukuran besar\", \"2 siung bawang merah\", \"2 batang daun bawang\", \"1 buah cabe merah\", \"Secukupnya kecap\", \"Minyak goreng\", \"Secukupnya saus cabe\", \"Secukupnya kaldu sapi\", \"Secukupnya garam\", \"Secukupnya gula\", \"Air bekas rebusan daging\"]', '[\"Rebus daging sampe empuk,potong sesuai selera\", \"Iris bawang bombay dan bawang merah lalu tumis,sampe harum\", \"Masukan daging dan air rebusan\", \"Setelah setengah mendidih masukan semua bumbu\", \"Sebelum di angkat masukan irisan daun bawang dan cabe merah\", \"Siap di sajikan..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(411, 2, 'Beef steak 🥩 simple #keto', 'Resep Beef steak 🥩 simple #keto ala rumahan yang dijamin menggugah selera.', '[\"300 gr daging sirloin sapi\", \"Bahan lain :\", \"secukupnya garam + lada hitam\", \"1 sdm butter\", \"Tambahan isi :\", \"irisan Tomat + paprika\", \"secukupnya Mayonaise\"]', '[\"Tusuk2 daging pakai garpu lumuri dgn garam dan lada hitam secukupnya (simpan 1 jam) biar meresep\", \"Tumis butter\", \"Bulak balik daging hingga matang sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(412, 3, 'Nasi Kebuli Daging Sapi', 'Hidangan daging sapi istimewa: Nasi Kebuli Daging Sapi.', '[\"3 gelas beras\", \"1 bungkus bumbu instan kare (merk bamboe)\", \"1/4 kg Daging Sapi\", \"10 buah kapulaga\", \"7 buah bunga lawang/pekak\", \"1 batang kayu manis\", \"2 lembar salam\", \"1 bungkus kara segitiga\", \"1/2 bawang bombay\"]', '[\"Tumis bumbu kare dan bahan lainnya sampai wangi\", \"Rebus daging sapi agar lunak\", \"Setelah daging lunak campurkan dgn tumisan bumbu\", \"Masukan kedalam magicom dan campur dengan beras tunggu sampai matang\", \"Beri tambahan santan\", \"Setelah matang beri tambahan sambal korek dan irisan timun juga tambahkan emping\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(413, 4, 'Tongseng sapi simple', 'Tongseng sapi simple dengan daging sapi empuk dan bumbu kaya rasa.', '[\"250 gram daging sapi\", \"Kol\", \"Tomat\", \"Daun bawang dan seledri\", \"Santan\", \"Masako, gula jawa, kecap\", \"Bumbu yang dihaluskan (bumbu kira2 saja sesuai selera)\", \"Bawang merah\", \"Bawang putih\", \"Jahe\", \"Kunyit\", \"Ketumbar,merica,kemiri\", \"Cabe\", \"Daun salam, daun jeruk, lengkuas di geprek dan sereh\"]', '[\"Tumis bumbu yg dihaluskan sampe harum lalu tambahkan daun jeruk daun salam lengkuas dan sereh\", \"Masukan daging sapi sampe berubah warna lalu tuang air santan sampe mendidih.. Tambahkan masako gula jawa dan kecap.. Dan koreksi rasa\", \"Tunggu nyampe kuah agak menyusut lalu tambahkan kol daun bawang seledri dan tomat\", \"Siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(414, 4, 'Sop bening daging sapi', 'Cara membuat Sop bening daging sapi yang enak dan praktis untuk keluarga.', '[\"500 gr daging sapi kualitas rendah\", \"4 buah kentang\", \"100 ons buncis\", \"5 lemar kol putih\", \"4 buah wortel\", \"2 helai daun seledri\", \"2 helai daun bawang\", \"Merica\", \"Penyedap\", \"Garam\", \"Air\", \"Gula pasir\"]', '[\"Potong2 semua sayuran tergantung selera\", \"Iris kasar daun bawang dan seledri\", \"Rebus terlebih dahulu daging sapi yang telah di potong kecil sampai agak lunak\", \"Tambahkan kentang dan wortel terlebih dahulu tunggu beberapa menit tambahkan kol dan buncis aduk rata\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(415, 4, 'Sapi semur panggang teflon', 'Sapi semur panggang teflon - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1/4 kg daging sapi\", \"Lemon\", \"bumbu halus\", \"5 butir bawang merah\", \"4 butir bawang putih\", \"5 buah cabai merah\", \"Ketumbar\", \"Kunyit\", \"2 butir Kemiri\", \"1 buah pala\", \"BUMBU GEPREK (cuma digeprek aja bahannya)\", \"2 ruas jari jahe\", \"1 batang serai\", \"Daun salam\", \"bumbu penyedap\", \"secukupnya garam\", \"Gula putih halus\", \"Lada hitam (ganti lada putih boleh)\", \"secukupnya Penyedap rasa\", \"secukupnya Gula merah\"]', '[\"Cuci bersih daging sapi dan tambahkan perasan lemon, diamkan kurang lebih 10 menit untuk menghilangkan bau anyir\", \"Uleg bumbu halus sesuai dengan bahan yang tadi disebutkan di atas\", \"Tumis bumbu halus sampai harum kemudian tambahkan bumbu geprek. Beri bumbu penyedap dan koreksi rasa. Nambahin gula merahnya sedikit demi sedikit ya bunn sampai rasanya pas.\", \"Setelah bumbu matang, angkat dan masukkan daging sapi yang tadi ke dalam bumbu tumisan. Ini saya sebut langkah memarinasi daging sapi (diamkan selama kurang lebih 30 menit). Karena ga punya Palu khusus daging, jadinya saya tumbuk tumbuk pakai ulegan (coet).\", \"Panaskan teflon, tambahkan mentega dan kemudian grill daging sapi yang telah dimarinasi sampai matang.\", \"Daging sapi semur panggang siap disajikan. Bisa disajikan langsung atau dipotong2 dulu. Karena saya ngga ada pisau steak, jadinya saya potong2 supaya mudah dimakannya. Dan saya sajikan bersama dengan mash potato sambal dabu.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(416, 2, 'Sop iga sapi sayuran', 'Sop iga sapi sayuran dengan daging sapi empuk dan bumbu kaya rasa.', '[\"500 gram iga sapi\", \"1 buah wortel\", \"2 buah kentang\", \"10 buah buncis\", \"50 gram kol\", \"1 batang daun bawang\", \"1 ruas kayu manis\", \"2 buah kapulaga\", \"2 buah bunga pekak\", \"3 buah cengkeh\", \"Garam dan kaldu\", \"Lada\", \"👉 bumbu halus\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"1 ruas jahe\", \"2 buah kemiri\", \"👉pelengkap\", \"Seledri\", \"Bawang goreng\", \"Jeruk\", \"Sambal\"]', '[\"Cuci bersih iga sapi lalu rebus hingga empuk kurleb 1 jam (di cek aja ya, sy presto biar cepat 30 menit). Buang air nya ya, karna banyak lemak nya. Kalo suka lemak bisa buat kaldu. Dan siap kan sayur potong sesuai selera.\", \"Rebus kembali air beserta iga sapi, kapulaga,kayu manis, bunga pekak dan cengkeh. Lalu Tumis bumbu halus hingga harum masukan kedalam rebusan iga.\", \"Masukan kentang dan wortel masak hingga empuk, masukan juga garam,kaldu dan lada bubuk. Tambahkan kol aduk2 hingga layu lalu masukkan buncis dan daun bawang aduk angkat dan sajikan dengan bahan pelengkap.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(417, 3, 'Oseng2 Kulit Sapi & Tahu', 'Resep Oseng2 Kulit Sapi & Tahu yang lezat dan mudah dibuat di rumah.', '[\"500 gram kulit sapi\", \"4 biji tahu\", \"2 keris pete (di iris sesui selera)\", \"5 biji bawang merah\", \"2 siung bawang putih\", \"1/2 biji bawang bombai\", \"7 biji cabe ijo\", \"5 biji cabe merah\", \"4 biji cabe rawit\", \"1 lembar daun salam\", \"2 lembar daun jeruk\", \"1 shacet saus tiram\", \"secukupnya Kecap, garam, & gula\"]', '[\"Rebus kulit sapi hingga 5-7 menit, tiriskan dan lumuri minyak goreng agar tidak menyatu\", \"Tumis bawang merah, bawang putih, bawang bombai, daun jeruk, dan daun salam hingga harum\", \"Masukkan cabe, aduk sebentar, kemudian masukkan kulit sapi, tahu, saus tiram, kecap, garam dan gula\", \"Tunggu beberapa menit, kemudian angkat dan hidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(418, 3, 'Rolade kornet sapi', 'Rolade kornet sapi - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1/2 kaleng besar kornet sapi\", \"3 butir telur\", \"2 sdm terigu\", \"secukupnya susu cair\", \"lada halus\", \"garam\", \"margarin\", \"plastik wrap untuk menggulung\", \"1 butir telur untuk panir\", \"minyak untuk menggoreng\"]', '[\"Terigu dilarutkan dengan sedikit susu cair.jangan terlalu cair.\", \"Tambahkan telur,garam dan lada halus lalu kocok.\", \"Siapkan wajan untuk membuat dadar.Olesi dengan margarin\", \"Buat 2 buah dadar telur ukuran besar\", \"Alasi talenan dengan plastik wrap\", \"Taruh dadar telur diatas plastik wrap tadi, beri kornet diatasnya.lalu gulung dengan plastik wrap.\", \"Pastikan menggulungnya sangat ketat,lalu simpan di freezer selama 20 menit.\", \"Siapkan minyak goreng dalam wajan.\", \"Potong gulungan telur kornet tadi,lalu celupkan ke kocokan telur panir.\", \"Goreng hingga matang.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(419, 3, 'Lodeh kikil sapi', 'Resep Lodeh kikil sapi yang lezat dan mudah dibuat di rumah.', '[\"1/4 kikil sapi potong kotak cuci bersih\", \"10 buah tahu sumedang belah bagi 2\", \"6 bh kacang panjang potong\\\" cuci bersih kemudian rebus sebentar\", \"5 bh cabe hijau potong\\\"\", \"65 ml santan kental\", \"2 sdm gula putih\", \"1 sdm penyedap rasa sapi\", \"secukupnya merica bubuk\", \"2 lmbr daun salam\", \"1 jari lengkuas memarkan\", \"secukupnya air\", \"secukupnya minyak goreng\", \"Bumbu halus\", \"5 siung bawang merah\", \"2 siung bawang putih\", \"1 bh cabe merah\", \"2 butir kemiri\", \"1 sdt ketumbar\", \"secukupnya gula merah\"]', '[\"Tumis bumbu halus sampe harum tandanya bumbu udah matang beri air sedikit,masukan daun salam dan lengkuas\", \"Masukan cabe hijau,kikil sapi,kacang panjang,tambahkan air lagi aduk terus masukan tahu sumedang,gula putih,penyedap dan merica bubuk tes rasa ya\", \"Setelah airnya mulai mendidih masukan santan,aduk terus jangan sampe santan pecah\", \"Setelah 2 x mendidih baru matikan kompor\", \"Lodeh kikil siap di sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(420, 2, 'Toge cah daging sapi cincang teriyaki simple', 'Hidangan daging sapi istimewa: Toge cah daging sapi cincang teriyaki simple.', '[\"1 ons Toge\", \"1 ons Dagibg sapi cincang\", \"4 biji Cabe rawit\", \"4 siung Bawang putih\", \"Minyak 2 sendok utk menumis\", \"2 batang Daun bawang\", \"2 sendok Saus teriyaki\", \"1 sendok Kecap asin\", \"1 sendok Kecap ikan\"]', '[\"Panaskan minyak Cincang bawang putih daging cincang dan bawang daun lalu tumis\", \"Masukan tauge dan cabe rawit\", \"Beri bumbu kecap dan koreksi rasa lalu angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(421, 2, 'Beef crispy steak sauce mushroom', 'Resep Beef crispy steak sauce mushroom ala rumahan yang dijamin menggugah selera.', '[\"2 potong daging sapi sedang\", \"1 cup jamur kancing\", \"1 buah wortel potong korek\", \"5 buncis potong panjang\", \"1 buah bawang Bombay\", \"3 siung bawang putih\", \"3 buah kentang sedang\", \"1 kotak uht full cream\", \"1 sdt saori saus tiram\", \"Secukupnya gula\", \"Secukupnya merica bubuk\", \"1/2 sdt kecap asin\", \"Secukupnya bubuk cabe\", \"3 sendok tepung sasa serbaguna cairkan\", \"3 sendok tepung\"]', '[\"Geprek sampai tipis daging sapi,marinasi dengan bubuk cabai,garam Dan saori.\", \"Cuci bersih kentang,tidak perlu dikupas Karena lebih enak pakai kulit,potong wedges lalu goreng sampai matang sisihkan.\", \"Wortel Dan buncis direbus sebentar,lebih enak setengah matang saja,sisihkan.\", \"Campurkan daging sapi ke tepung basah,lalu gulingkan ke tepung kering,ulangi lagi 2 Kali lalu goreng kurang lebih 5 menit nolak balik,sisihkan.\", \"Untuk Bahan sauce potong kecil bawang putih Dan bawang Bombay, tumis sampai, masukan jamur tumis sampai harum, setelah harum masukan Susu uht yg 100 ml aja,lalu masukan saori,merica bubuk,kecap Asin,Dan gula,koreksi Rasa.\", \"Jika dirasa sudah enak bisa disajikan lengkap dengan, daging,Sayur Dan kentang.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(422, 3, 'Sambel Goreng Hati Sapi Endesss', 'Sambel Goreng Hati Sapi Endesss - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 kg hati sapi, rebus hingga empuk lalu potong sesuai selera\", \"bumbu cemplung :\", \"2 batang sereh, geprek\", \"4 lembar daun jeruk, sobek\", \"2 ruas lengkuas, geprek\", \"1 sdt asam jawa\", \"bumbu dihaluskan :\", \"10 buah cabe rawit\", \"7 buah cabe merah keriting\", \"10 siung bawang merah\", \"6 siung bawang putih\", \"3 buah kemiri\", \"1 sdm ketumbar bubuk\", \"1 sdt merica bubuk\", \"2 ruas jahe\", \"bahan tambahan :\", \"65 ml santan kental instan\", \"secukupnya air\", \"secukupnya minyak untuk menumis bumbu\", \"secukupnya garam\", \"secukupnya gula pasir\"]', '[\"Panaskan minyak, tumis bumbu halus hingga harum, masukkan bumbu cemplung, biarkan sejenak hingga mengeluarkan minyak\", \"Masukkan hati sapi, aduk rata. tambahkan air secukupnya. masukkan garam dan gula pasir. aduk rata. tutup sejenak hingga bumbu meresap.\", \"Lalu masukkan santan kental, aduk rata. biarkan hingga tanak atau matang bumbu meresap. angkat, sajikan. jangan lupa cek rasa. selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(423, 3, 'Rendang Sapi Simple', 'Sajian Rendang Sapi Simple yang praktis dan lezat untuk dinikmati bersama.', '[\"300 gram daging sapi tanpa lemak\", \"200 gram iga sapi\", \"1 sct  Bumbu indofood rendang\", \"1 sct  santan kara\", \"1/2 butir kelapa parut\", \"2 batang sereh\", \"3 lembar daun salam\", \"3 biji kapulaga\", \"1 biji bunga\", \"1000 ml air\", \"Bumbu halus:\", \"4 siung bawang putih\", \"7 siung bawang merah\", \"5 butir kemiri utuh\", \"1 sdt ketumbar bubuk\", \"15 buah cabai merah keriting\", \"3 cm laos\", \"1 cm jahe\"]', '[\"Cuci bersih daging sapi kemudian potong sesuai selera\", \"Tumis bumbu halus dan bumbu indofood kemudian masukan kapulaga, bunga lawang, sereh geprek dan daun salam hingga harum\", \"Kemudian masukan potongan daging sapi dan masukan perasan kelapa parut dan santan kara aduk2\", \"Masukan 1000ml air dan aduk2 rata kemudian biarkan hingga air menyusut dengan menggunakan api kecil\", \"Aduk2 rendang agar tidak gosong biarkan hingga air menyusut dan daging empuk sekitar 1.5jam\", \"Angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(424, 4, 'Tumis Sawi sendok pete daging sapi', 'Tumis Sawi sendok pete daging sapi dengan daging sapi empuk dan bumbu kaya rasa.', '[\"5 biji Tahu pong\", \"6 biji Tahu pong\", \"Sawi sendok 2 unting\", \"Brokoli\", \"Daging sapi\", \"5 biji Cabe keriting merah/hijau\", \"3 siung Bawang merah\", \"3 siung Bawang putih\", \"1 biji Laos yang kecil\", \"secukupnya Gula\", \"secukupnya Garam\", \"3 sdt Minyak goreng untuk menumis\", \"secukupnya Penyedap rasa royco\", \"secukupnya Saori saos tiram\"]', '[\"Cuci sayuran terlebih dahulu (sawi sendok brokoli) setelah di cuci potong2 sayuran\", \"Cuci daging sapi setelah di cuci lalu rebus daging sapi hingga empuk setelah di rebus daging sapinya lalu potong sesuai selera\", \"Cuci cabe merah/hijau kritingnya dan cuci bawang merah bawang putih setelah di cuci cabenya lalu potong2 sesuai selera\", \"Setelah di cuci bawang merah bawang putih lalu di cincang\", \"Geprek laosnya hingga setengah gepeng\", \"Kupas pete selah di kupas lalu di cuci setelah itu di potong di bagi dua\", \"Siapkan wajan untuk menumis\", \"Masukan minyak goreng 3 sendok teh ke dalam wajan tunggu hingga panas sedikit\", \"Masukan cabe kriting bawang merah bawang putih\", \"Tumis bawang merah bawang putih sebentar saja\", \"Lalu masukan laos yang telah di geprek\", \"Masukan garam dan gula secukupnya dan masukan bumbu penyedap rasa\", \"Aduk2 aduk hingga merata\", \"Masukan air secukupnya sesuai selera\", \"Masukan pete\", \"Masukan daging sapi, dan aduk2 hingga campur bumbunya tunggu sebentar\", \"Setelah itu masukan tahu pong dan sayurannya aduk aduk sebentar jangan sampai lonyot ya sawinya.setelah matang angkat dan tiriskan ke wadah bisa mangkuk bisa piring\", \"Mudah kan ibu2 kakak2 silahkan mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(425, 4, 'Tongseng Iga dan Kikil Sapi', 'Tongseng Iga dan Kikil Sapi - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 Kg Iga dan Kikil Sapi\", \"1/2 kol\", \"2 tomat segar\", \"2 Sendok Santan kental (saya pakai Kara)\", \"Secukupnya Minyak goreng\", \"1 sdm gula merah\", \"2 lt air\", \"Bumbu Geprek\", \"5 lbr daun Jeruk\", \"2 lbr daun salam\", \"2 btg serai\", \"1 ruas jahe\", \"1 ruas lengkuas\", \"Bumbu Halus\", \"10 siung Bawang merah\", \"6 Siung bawang Putih\", \"1/2 sdt Merica\", \"1 sdt Ketumbar\", \"1 Kemiri (bisa ditambah kl suka)\", \"1 ruas kunyit\", \"4 buah Cabe merah (atau lebih)\", \"6 cabe rawit (atau lebih)\"]', '[\"Masukkan iga dan kikil ke dlm air yg menjelang mendidih 10 menit, lalu buang.\", \"Didihkan air baru dan masukkan iga dan kikil,tutup presto hingga cukup empuk (15-20 menit sejak presto bunyi) dan sisihkan\", \"Tumis bumbu halus bersama bumbu geprek hingga harum dan masukkan gula merah, aduk.\", \"Masukkan iga dan kikil beserta air rebusan secukupnya,masak hingga air menyusut dan tambahkan santan, aduk-aduk agar tidak pecah\", \"Masukkan kol dan tomat, jangan terlalu lama di atas api.angkat dan sajikan\", \"Taburi bawang goreng.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(426, 2, 'Brokoli siram sapi lada hitam', 'Sajian Brokoli siram sapi lada hitam yang praktis dan lezat untuk dinikmati bersama.', '[\"1/4 daging sapi\", \"1 kuntum brokoli\", \"1 buah bawang bombay iris kotak\", \"500 ml Air kaldu sapi\", \"2 siung bawang putih cincang\", \"1 sdm bubuk lada hitam\", \"1 ruas jahe geprek\", \"1 sdm Saos tiram\", \"1 sdm saos tomat\", \"1 sdm kecap manis\", \"Gula\", \"Garam\"]', '[\"Rebus daging sapi, tiriskan lalu iris\", \"Siangi brokoli, rendam dengan air garam kurang lebih 10 menit, lalu rebus sebentar saja kemudian tiriskan\", \"Tumis bawang putih dan bawang bombay sampai harum\", \"Masukkan saos tiram, saos tomat, dan kecap manis, bubuk lada hitam, air kaldu, jahe, gula dan garam\", \"Masukkan daging, masak hingga daging empuk dan kuah menyusut\", \"Tes rasa.\", \"Tata brokoli diatas mangkuk lalu siram sapi lada hitam diatasnya\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(427, 4, 'Jamur tiram sapi saus teriyaki', 'Hidangan daging sapi istimewa: Jamur tiram sapi saus teriyaki.', '[\"1/2 kg daging sapi\", \"1/4 kg jamur tiram\", \"1 siung bawang bombay ukuran besar\", \"2 siung bawang merah\", \"1 buah tomat merah\", \"2 buah cabai merah\", \"Secukupnya daun bawang\", \"Secukupnya seledri\", \"Secukupnya royco sapi\", \"Secukupnya garam\", \"Secukupnya gula\", \"Secukupnya merica\", \"Secukupnyaa kecap manis\", \"Secukupnya saos teriyaki instan\", \"Secukupnya saus cabai\", \"Secukupnya mentega\", \"Secukupnya air bekas rebusan daging sapi\"]', '[\"Rebus daging sapi setengah matang,buang air nya lalu rebus kembali hingga matang dan empuk,sambil menunggu matang dan empuk kita bersihkan jamur tiram dan potong memanjang.\", \"Potong semua bahan, bawang bombay,bawang merah di potong kotak,daun bawang,seledri dan tomat d potong,cabe d potong serong\", \"Setelah daging matang dan empuk,di potong berbentuk dadu ukuran sedang.\", \"Selanjutnya kita panaskan mentega dan tumis bawang bombay dan bawang merah,setelah harum dan matang masukan daging yg sudah d potong,lalu tambahkan air bekas rebusan daging.\", \"Di rasa sudah menyerap lalu masukan jamur tiram nya,lalu masukan semua bumbu,royco,garam,gula,merica,saus cabe,kecap dan saus teriyaki,,kemudian tes rasa\", \"Bila sudah cukup dan jamur mulai matang masukan daun bawang,seledri,cabe dan tomat..aduk sebentar..\", \"JAMUR TIRAM SAPI SAUS TERIYAKI siap di hidangkan dengan nasi panas.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(428, 2, 'Sop iga sapi segar', 'Buat Sop iga sapi segar yang nikmat dengan langkah-langkah mudah ini.', '[\"1 kg iga sapi\", \"10 bh bakso sapi\", \"3 bh sosis, potong bulat\", \"2 bh wortel\", \"kol\", \"3 batang seledri\", \"2 batang daun bawang\", \"2 bh tomat\", \"5 butir cengkeh\", \"1 batang kayu manis\", \"secukupnya garam, merica\", \"secukupnya kaldu bubuk\", \"bumbu halus :\", \"8 siung bawang merah\", \"6 siung bawang putih\", \"1/2 butir pala\"]', '[\"Cuci bersih iga sapi lalu rebus selama 15 menit, lalu buang air rebusannya supaya lemak dan kotoran2nya hilang\", \"Rebus kembali iga dengan 2 liter air slama kurang lebih 1 jam atau sampai iga menjadi empuk\", \"Sambil menunggu rebusan iga, ulek halus bahan utk bumbu sop (bawang merah, bawang putih dan pala)\", \"Tumis bumbu halus dengan sedikit minyak sampai keluar aromanya, lalu masukkan cengkeh dan kayu manis, tumis sebentar\", \"Setelah iga empuk, masukkan tumisan bumbu halus ke dalam rebusan iga, lalu masukkan wortel, bakso, sosis dan kol lalu tambahkan garam, merica, kaldu bubuk secukupnya, aduk rata sambil tes rasanya\", \"Setelah rasanya pas, masukkan daun seledri, irisan daun bawang dan terakhir tomat, aduk sebentar lalu matikan api\", \"Sop iga siap disajikan bersama taburan bawang goreng, bagi yg suka pedas bisa disajikan bersama irisan cabe rawit dan kecap asin\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(429, 2, 'Gulai Padang Ati Sapi', 'Resep Gulai Padang Ati Sapi ala rumahan yang dijamin menggugah selera.', '[\"1 kg ati sapi potong potong sesuai selera\", \"air\", \"2 sdm cuka/ vinegar\", \"1 liter santan\", \"Bahan :\", \"secukupnya minyak goreng\", \"3 lembar daun jeruk\", \"3 lembar daun salam/ bay leave\", \"secukupnya garam dan gula\", \"Bumbu yang dihaluskan :\", \"4 siung bawang putih\", \"8 siung bawang merah\", \"10 buah cabai Hijau/ merah (saya menggunakan cabe hijau)\", \"3 cm jahe\", \"3 cm kunyit\", \"3 butir kemiri\", \"1 sdm ketumbar\", \"1 sdm Jintan\", \"2 cm lengkuas\", \"1 batang serai\"]', '[\"Menyiapkan Ati sapi : rendam dulu ati dengan air cuka selama 10 menit, setelah direndam cuci sampai bersih. Rebus ati dengan air dengan api kecil serta masukkan daun salam dan 2 sdm cuka. sesudah masak, Angkat dan tiriskan.\", \"Siapkan wajak dan panaskan minyak goreng secukupnya. tumis bumbu yang dihaluskan sampai harum, masukkan daun jeruk dan bay leave.\", \"Masukkan santan, Aduk sampai mendidih dan aduk aduk agar santan tak pecah.\", \"Masukkan hati masak sampai santan mengental. tambahkan garam dan gula, cicipi.\", \"Angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(430, 2, 'Lapis daging sapi', 'Sajian Lapis daging sapi yang praktis dan lezat untuk dinikmati bersama.', '[\"750 daging sapi (khas dalam)\", \"3 lembar daun salam\", \"5 lembar daun jeruk\", \"2 batang serai, memarkan\", \"1 cm kayumanis\", \"2 butir cengkih\", \"1 sdm gula merah, sisir\", \"1 sdm air asam jawa\", \"3 sdm kecap manis\", \"Secukupnya garam\", \"750 ml air (boleh tambah bila daging belum empuk)\", \"Bumbu halus:\", \"10 butir bawang merah\", \"6 siung bawang putih\", \"2 cabe merah, buang biji\", \"1 jempol lengkuas muda\", \"4 cm kunyit\", \"1 sdm ketumbar sangrai\", \"5 butir kemiri, Goreng\", \"1/4 buah pala\", \"1/2 sdt merica butiran\"]', '[\"Tumis bumbu halus sampai wangi, masukkan daun salam, serai, daun jeruk, cengkih, kayumanis, aduk rata, masukkan daging, aduk2 sampai berubah warna.\", \"Setelah daging berubah warna bumbui garam, gula merah, air asam & kecap manis, aduk sampai rata lalu tuangi air, masak sampai daging empuk dan bumbu meresap, angkat dan sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(431, 3, 'Kwetiau Sapi Goreng', 'Kwetiau Sapi Goreng - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"500 gram kwetiau basah, siram air panas, tiriskan (kalau menggunakan kwetiaw kering, direbus hingga lembut, tiriskan dan beri minyak sayur biar tidak lengket)\", \"250 gram daging sapi has dalam (kalau suka, boleh dicampur usus sapi)\", \"Bakso daging, iris tipis\", \"150 gram caisim, siangi, potong-potong kurang lebih 3 cm\", \"250 gram taoge, buang akar\", \"4-5 butir telur, kocok lepas\", \"secukupnya Daun bawang dan seledri\", \"Bumbu halus:\", \"10 siung bawang putih\", \"1 cm jahe\", \"5 butir bawang merah\", \"1 sdt garam\", \"Penyedap rasa (Boleh diskip)\", \"Saus:\", \"2 sdm kecap manis\", \"2 sdt kecap asin\", \"1/2 sdt merica bubuk\"]', '[\"Rebus daging sampai matang, iris tipis-tipis.\", \"Panaskan minyak dalam wajan, tumis bumbu halus hingga harum.\", \"Masukkan Daging, bakso dan telur kocok, aduk sampai telur berbutir-butir.\", \"Tuang campuran saus, caisim, dan kwetiau.\", \"Aduk campuran kwetiau hingga rata.\", \"Terakhir masukkan taoge dan daun bawang, aduk hingga rata dan semua bahan matang. Pastikan taoge masih kelihatan segar dan matang.\", \"Sajikan dengan taburan bawang goreng dan irisan daun seledri.\", \"Selamat mencoba.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(432, 4, 'Japan beef teriyaki', 'Cara membuat Japan beef teriyaki yang enak dan praktis untuk keluarga.', '[\"200 gr daging sapi tanpa lemak (sesuai selera) potong dadu\", \"secukupnya garam, garlic powder, knor, minyak wijen, lada\", \"5 siung bawang putih cincang\", \"1/2 bawang bombay (karena ga begitu suka, jd ini takarannya selera)\", \"1 sdm blue band\", \"secukupnya olive oil/ minyak sayur\", \"biji wijen secukupnya\", \"saus teriyaki,aku pake merk tai hua\"]', '[\"Tuang sapi ke dalam mangkok, taro garlic powder, garam, lada, knor, minyak wijen secukupnya.. aduk sampai rata.. tutup mangkok dengan plastik seperti gambar saya.. diamkan 30-40 menit\", \"Panaskan minyak+bawang putih.. tumis hingga harum (jangan sampai coklat) lalu masukan sapi.. tumis hingga mencoklat\", \"Masukan saus teriyaki.. aduk lalu tutup panci sekitar 3 menit (api sedang saja supaya ga gosong dibawah) buka lalu tambahkan bawang bombay.. aduk merata.. tutup lagi api sedang.. tambahkan air sedikit saja sekitar 5 sendok agar tidak kental\", \"Ketika sudah matang masukan biji wijen kering.. aduk hingga merata.. dan taro biji wijen diatas sajian supaya menarik untuk di foto😂\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(433, 3, 'Resep Daging Sapi Kuah Pedas', 'Resep Daging Sapi Kuah Pedas dengan daging sapi empuk dan bumbu kaya rasa.', '[\"500 gr Daging Sapi\", \"6 bh Bawang Merah\", \"5 bh Bawang putih\", \"2 bh Lombok keriting\", \"20 bh Cabe rawit\", \"4 lmbr Daun Jeruk\", \"1 lmbr Daun Salam\", \"Sejumput Jahe bubuk\", \"Sejumput lengkuas bubuk\", \"secukupnya Air rebusan daging\", \"secukupnya Garam\", \"secukupnya Gula\", \"1/2 blok Maggi Kaldu Sapi (jika suka)\"]', '[\"Rebus daging dengan daun salam sampai empuk. Jika sudah empuk,air sisa rebusan daging disimpan.\", \"Ulek kasar bawang merah, bawang putih, jahe, lengkuas, cabe keriting n cabe rawit\", \"Siapkan minyak panas secukupnya lalu tumis bumbu sampai harum dan juga daun jeruk. Bisa juga tambahkan kentang goreng, krece atau pete. Lalu,angkat dan sisihkan.\", \"Jika daging sudah empuk angkat n potong kecil/tipis sesuai selera. Panaskan kembali minyak goreng untuk menggoreng daging sampai setengah kering. Kemudian,masukan kembali bumbu yg ditumis.\", \"Masukan garam, gula dan Maggi Blok Sapi. Setelah itu, masukkan air sisa rebusan daging ke tumisan daging sesuai keinginan. Aduk kemudian tes rasa.\", \"Selamat mencoba😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(434, 3, 'Thai Spicy Basil Beef', 'Thai Spicy Basil Beef - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"500 gram daging sapi sirloin atau has dalam\", \"5 siung bawang putih, cacah halus\", \"2 butir bawang merah, cacah halus\", \"3 buah cabai rawit merah, cacah kasar (boleh ditambah)\", \"1 buah paprika merah kecil, iris memanjang\", \"1/2 buah bawang bombay, iris memanjang\", \"1 sdm kecap ikan\", \"1 sdm saus tiram\", \"1 sdm kecap manis\", \"secukupnya Merica\", \"2 genggam daun kemangi\", \"Bumbu perendam:\", \"1 sdm kecap asin\", \"secukupnya Merica\", \"1 sdt kaldu ayam atau jamur bubuk\"]', '[\"Bersihkan serat dan lemak daging. Pukul-pukul dan iris memanjang berlawanan serat.\", \"- Rendam daging dalam bumbu perendam selama minimal 30 menit.\", \"- Panaskan minyak dalam wajan, tumis daging sebentar saja hingga berubah warna. Tiriskan.\", \"- Tambahkan minyak dan tumis bawang putih dan bawang merah hingga harum.\", \"- Tambahkan paprika dan cabai. Masak sebentar.\", \"- Masukkan bawang bombay dan masak hingga setengah matang.\", \"Masukkan daging. Bumbuhi dengan kecap ikan, saus tiram, kecap manis dan merica secukupnya.\", \"- Masak sebentar hingga meresap dan matang.\", \"- Koreksi rasa.\", \"- Terakhir tambahkan daun kemangi. Matikan api.\", \"- Sajikan dengan nasi putih dan telur mata sapi.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(435, 2, 'Beef Teriyaki Lada Hitam', 'Hidangan daging sapi istimewa: Beef Teriyaki Lada Hitam.', '[\"1/4 kg daging sapi iris tipis\", \"2 siung bawang putih parut\", \"1 siung bawang merah parut\", \"1 siung bawang bombay iris\", \"2 bungkus saori teriyaki\", \"Secukupnya lada hitam bubuk\", \"Secukupnya minyak untuk menumis\", \"Secukupnya air\", \"2 buah cabai hijau gendut\", \"3 buah cabai merah keriting\", \"Secukupnya masako sapi\"]', '[\"Rebus terlebih dahulu daging yang telah dicuci ke dalam air yang mendidih hingga kira2 empuk.\", \"Tumis bawang putih dan merah hingga harum. Masukkan daging dan saori teriyaki lalu tambahkan air. Aduk merata.\", \"Masukkan cabai, masako dan lada hitam. Aduk merata hingga tercium aroma pedas cabai.\", \"Masukkan bawang bombay sebentar lalu angkat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(436, 2, 'Beef Black Pepper (daging lada hitam) simple', 'Cara membuat Beef Black Pepper (daging lada hitam) simple yang enak dan praktis untuk keluarga.', '[\"daging has dalam 250 gr potong dadu\", \"bahan marinasi:\", \"1 sdm minyak wijen (aslinnnya ga pake)\", \"2 sdm kecap manis\", \"1 sdt madu\", \"4 sdm saus tiram\", \"1/2 sdt lada hitam\", \"bahan untuk tumis:\", \"4 siung bawang putih cincang\", \"1 buah bawang bombay potong dadu/ iris\", \"3 helai kacang panjang (aslinya paprika hijau, sy pas ga punya)\", \"3 buah cabe keriting (aslinya paprika merah, sy pas ga punya)\", \"secukupnya air\", \"1 sdt lada hitam\", \"3 sdm mentega\"]', '[\"Campurkan daging dengan semua bahan marinasi diamkan kira2 1 jam\", \"Siapkan bahan2 untuk ditumis\", \"Panaskan mentega, tumis bawang putih dan bawang bombay hingga harum\", \"Masukkan daging dan saus marinasi, tambahkan air secukupnya. tunggu hingga daging matang dan kuah mengental\", \"Masukkan kacang panjang dan cabe merah\", \"Tambahkan lada hitam sedikit2 sambil koreksi rasa\", \"Hasilnya beef black pepper nya enak walau tanpa gula dan garam. saya suka banget\", \"Sajikan diatas nasi panas\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(437, 4, 'Daging Sapi Kelem', 'Buat Daging Sapi Kelem yang nikmat dengan langkah-langkah mudah ini.', '[\"300 gr daging sapi has dalam\", \"Secukupnya air\", \"2 sdm minyak goreng\", \"1 sdm air asam jawa\", \"💜 Bumbu Halus 💜\", \"3 siung bawang merah\", \"2 siung bawang putih\", \"1/2 sdm ketumbar butiran\", \"1/2 sdt merica butiran (tambahan dari saya)\", \"2 sdm gula merah\", \"3 sdm kecap manis\", \"1 sdm saos tiram\", \"Secukupnya garam dan gula pasir\", \"💜Bumbu cemplung💜\", \"1 lembar daun salam\", \"1 ruas jari lengkuas, geprek\"]', '[\"Rendam daging dengan bumbu halus semalaman di chiller\", \"Rebus daging+bumbu halus, daun salam, lengkuas dan air asam dengan secukupnya air hingga daging empuk\", \"Rebus terus hingga air menyusut dan bumbu meresap. Masukkan minyak goreng. Tumis-tumis sampai mengental\", \"Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(438, 3, 'Kulit sapi Bumbu santan kering', 'Buat Kulit sapi Bumbu santan kering yang nikmat dengan langkah-langkah mudah ini.', '[\"500 gr kulit sapi\", \"1 bks kara santan\", \"2 batang daun kemangi\", \"4 butir kemiI\", \"4 sihung bawang merah\", \"2 sihung bawang putih\", \"2 ruas kunyit ukuran kecil\", \"4 buah cabe gendol\", \"2 buah cabe merah\", \"secukupnya Terasi\", \"Gula pasir\", \"Penyedap\", \"Garam\", \"Air\", \"Minyak\"]', '[\"Haluskan kunyit,kemiri,bawang putih,bawang merah,cabe merah sampai halus\", \"Rebus kulit sapi sampai empuk\", \"Tumis bumbu halus lalu tambahkan kulit sapi yg telah di rebus\", \"Masukkan bahan lainnya aduk sampai merata tambahkan air secukupny\", \"Menjelang di angkat tambahkan cabai gendol dan daun kemangi\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(439, 2, 'Tetelan sapi huh hah', 'Buat Tetelan sapi huh hah yang nikmat dengan langkah-langkah mudah ini.', '[\"Tetelan sapi (udah direbus)bisa juga langsung\", \"5 buah bawang merah\", \"3 buah bawang putih\", \"10 cabai rawit(sesuaikan ya)\", \"Daun salam\", \"1 ruang lengkuas geprek\", \"1/2 bawang bombay iris\", \"Minyak goreng\", \"Kecap,Lada, saori\", \"Garam,gula,penyedap\"]', '[\"Haluskan bawang merah,bawang putih, cabai, garam, gula dan penyedap\", \"Tumis bumbu yg sdh dihaluskan tambah daun salam dan lengkuas yg sdh di geprek smpai matang..\", \"Masukkan tetelan kasih kecap,saori lada dan nawang bombay..\", \"Test rasa dan sajikan..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(440, 2, 'Daging sapi lada hitam', 'Resep Daging sapi lada hitam ala rumahan yang dijamin menggugah selera.', '[\"500 gr daging has sapi\", \"1 buah bawang bombay\", \"5 siung bawang putih\", \"5 buah cabe kriting\", \"7 buah cabe setan\", \"totole/penyedap/garam\", \"saori lada hitam / lada hitam\", \"untuk memarinasi daging :\", \"sesuai selera lada putih\", \"6 sdm kecap manis\", \"5 sdm saus tiram\", \"minyak wijen (opsional)\"]', '[\"Cuci lalu iris daging/potong dadu sesuai selera, tambahkan kecap manis + saus tiram + lada lalu aduk dan remas remas setelah itu masukan ke dalam kulkas selama 15 menit\", \"Iris bawang bombay + cabe dan cincang bawang putih\", \"Tumis bawang lalu masukan daging sapi yang sudah dimarinasi, tambah kan air -+ 2 gelas belimbing diamkan sampai sedikit airnya,\", \"Lalu tambahkan saori lada hitam dan cabe aduk rata dan koreksi rasa, setelah pas siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(441, 4, 'Empleng daging sapi kentang', 'Buat Empleng daging sapi kentang yang nikmat dengan langkah-langkah mudah ini.', '[\"2 buah kentang (kentang hongkong ukurannya sebesar ubi)\", \"1/2 bawang bombay\", \"20 HKD daging sapi di cacah\", \"1 butir telur\", \"Bumbu daging sapi\", \"1 sdt kecap asin\", \"1/8 sdt gula\", \"1 sdt aci\", \"Bumbu\", \"1/3 sdt garam\", \"1 sdt kecap asin\", \"1/2 sdt gula\", \"secukupnya Aci\", \"Minyak goreng\"]', '[\"Kentang buang kulitnya. Cuci bersih, lap kering, parut kasar\", \"Bumbui daging sapi\", \"Bumbui daging sapi\", \"Bawang bombay cacah halus, tumis biarkan dingin\", \"Bawang bombay cincang halus, tumis sampai harus.Tunggu dingin\", \"Daging, kentang, telur dan bumbu aduk rata,di buar jadi lempengan daging kentang.Goreng debgan api kecil.Sampai kedua belahnya menjadi kuning mas.Hidangkan\", \"Daging, kentang, telur, bumbu, bawang bombay campur rata.Buat jadi lempengan daging kentang\", \"Panaskan minyak, goreng dengan api kecil hingga kedua belah nya kuning mas dan matang.Angkat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(442, 3, 'Hati💓 Sapi Masak Kecap', 'Resep Hati💓 Sapi Masak Kecap ala rumahan yang dijamin menggugah selera.', '[\"250 gr hati sapi\", \"Bumbu halus :\", \"7 siung bawang merah\", \"6 siung bawang putih\", \"5 butir kemiri\", \"2 buah cabe merah besar\", \"1 ruas jahe\", \"1 ruas laos\", \"Sedikit jinten (bisa skip)\", \"jika suka Cabe rawit\", \"2 lembar Daun salam\", \"secukupnya Gula\", \"secukupnya Garam\", \"secukupnya Kecap manis\", \"secukupnya Air dan minyak goreng\", \"250 ml santan kanil\"]', '[\"Cuci bersih hati sapi,rebus sampai matang lalu potong sesuai selera.\", \"Haluskan semua bumbu halus, tumis dg sedikit minyak setelah wangi masukkan hati sapi,beri air secukupnya. Aduk\\\" lalu beri santan masak lagi hingga mengeluarkan minyak, kental menyusut, lalu beri gula, garam, kecap manis, bisa beri gula merah jika suka. Koreksi rasa, jika sudah pas, matikan api sajikan.\", \"Nb. Kecap, gula, garam, terakhir memasukkan nya, karna khawatir jika dimasukkan diawal, saat menyusut kuahnya keasinan, atau kemanisan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(443, 3, 'Beef balado', 'Beef balado dengan daging sapi empuk dan bumbu kaya rasa.', '[\"Daging sapi bagian apa saja (saya pakai khas dalam)\", \"5 siung bawang merah\", \"5 siung bawang putih\", \"3 buah cabe merah besar\", \"5 buah rawit merah (kalo gak suka pedes boleh skip)\", \"2 buah kemiri\", \"2 lembar daun jeruk\", \"1 batang serai (geprek)\", \"2 lembar daun salam\", \"sisir Gula merah\", \"Penyedap rasa\", \"2 sdm air jeruk nipis\", \"1 bks merica bubuk\"]', '[\"Daging sapi di rebus terlebih dahulu (saya pakai presto 25 menit)\", \"Haluskan bawang merah, bawang putih, kemiri, cabe merah, cabe rawit.\", \"Panaskan minyak lalu tumis bumbu halus dengan batang serai geprek dan daun salam\", \"Setelah bumbunya wangi masukan 250ml air matang, lalu masukan daun jeruk dan daging sapi yang sudah di rebusm\", \"Setelam mendidih masukan penyedap rasa, gula merah, merica bubuk, dan air jeruk, tutup wajan diamkan sampai airnya menyusut\", \"Setelah menyusut koreksi rasa, jika sudah pas angkat masakan lalu plating 😘😘\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(444, 4, 'Sapi Garo Rica tanpa kentang', 'Resep praktis Sapi Garo Rica tanpa kentang yang bisa dicoba di rumah.', '[\"Daging sapi spesial potong sesuai selera\", \"Bumbu haluskan :\", \"6 siung bawang putih\", \"10 cabe merah keriting\", \"5 cabe rawit\", \"1 ruas jahe\", \"1 ruas lengkuas\", \"1 ruas kunyit\", \"2 Daun salam\", \"1 btg serai memarkan\", \"secukupnya Garam\", \"secukupnya Lada\", \"secukupnya Penyedap rasa\", \"Minyak sayur\", \"secukupnya Air\"]', '[\"Panaskan minyak, tumis bumbu bumbu halus tadi, diulek yaa, ga pake blender2 biar rasanya enak. sampai harum, kemudian tambahkan daun salam, serai. tambahkan air, garam, lada secukupnya...\", \"Terakhir masukan daging tunggu sampai empuk dan air meresap koreksi rasa pedas,gurih. Setelah empuk.. sajikan hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(445, 4, 'Semur Hati Sapi', 'Nikmati kelezatan Semur Hati Sapi dengan resep sederhana ini.', '[\"1/2 kg hati sapi\", \"3 siung bawang putih\", \"8 siung bawang merah\", \"5 biji kemiri\", \"1 ruas kunyit\", \"1 royco\", \"1/2 bungkus ladaku\", \"1 bunga lawang, kapolaga\", \"Sedikit pala\", \"3 gelas air\", \"sesuai selera Kecap manis\", \"1 sdt gula pasir\", \"Daun jeruk dan daun salam\"]', '[\"Cuci hati sapi lalu rebus 20 menit, setelah itu potong kotak\", \"Blender semua bumbu kecuali daun jeruk, salam, bunga lawang dan kapolaga\", \"Tumis bumbu, masukan daun jeruk, salam, bunga lawang dan kapolaga, aduk2\", \"Lalu masukkan hati sapi dan beri air, kecap, royco dan ladaku, aduk2\", \"Biarkan sampe airnya berkurang (jangan sampe saat) sambil diaduk\", \"Setelah mateng dan airnya berkurang, matikan kompor\", \"Nanti airnya akan meresap sendiri\", \"Sajikan dengan kerupuk udang sabagai pelengkap\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(446, 2, 'Beef Steak', 'Nikmati kelezatan Beef Steak dengan resep sederhana ini.', '[\"1.5 cm Sirloin steak\", \"Bumbu :\", \"1 sdm Mustard\", \"2 sdm Bumbu barbeque\", \"1/2 sdt Garam\", \"sejumput Gula\", \"Lada hitam sejumput (pewangi)\", \"1/2 sdt Lada putih\", \"1 sdm Minyak goreng\", \"Saus :\", \"Sisa bumbu\", \"Bawang bombay\", \"Jamur champignon (optional)\"]', '[\"Marinade per slice : daging Sirloin 1.5 cm + mustard + bumbu barbeque + garam + gula + lada hitam + lada putih....tes rasa ya\", \"Per slice sirloin yang sudah di bumbui masukan dalam plastik 1kg, lipat rapi dan simpan dalam kulkas semalaman. Ketika akan di masak, usahakan daging dalam keadaan suhu ruangan\", \"Panaskan teflon dengan api sedang, masukan sedikit minyak setelah panas taruh sirloin. Medium well waktu memasak 2 sampai 2.25 menit per sisi daging. Hati hati sama cipratan minyak nya.\", \"Sisa saus yang ada di teflon masukan bawang bombay (sedikit / banyak optional) tambahkan potongan jamur tumis sampai layu. Biasa nya di sisa saus di buat aga medok untuk garam gula lada nya\", \"Sajikan sirloin nya di siram atau di pisah dari saus nya tambahkan saus sambal....nyuuummm...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(447, 3, 'Sop iga sapi kekinian', 'Resep Sop iga sapi kekinian yang lezat dan mudah dibuat di rumah.', '[\"1/2 kg Iga sapi\", \"15 buah Baso sapi\", \"3 Wortel\", \"secukupnya Daun bawang\", \"5 Bawang merah\", \"7 Bawang putih\", \"Garam\", \"Gula\", \"Lada\", \"Bubuk cabe\", \"1 bh jeruk nipis\", \"2 buah Tomat\"]', '[\"Cuci bersih lalu Rebus daging sapi/iga sapi sampai air susut, buang busanya\", \"Tumis bawang merah dan bawang putih yg sdh dihaluskan sampai harum kmd masukkan baso dan potongan tomat (saya pilih tomat yg sudah matang2)\", \"Beri garam, lada, gula, bubuk cabe ke tumisan aduk rata dan tuang ke rebusan daging\", \"Masukkan potongan wortel aduk aduk rata, koreksi rasa kmd stlh wortel empuk, masukkan daun bawang dan perasan jeruk nipis menambah nikmat dan kesegaran\", \"Sajikan sop iga sapi kekinian dengan sambal goreng dan nasi hangat tentunya mengundang selera makan yang memandangnya, mari makan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(448, 4, 'Rawon sapi maknyos', 'Buat Rawon sapi maknyos yang nikmat dengan langkah-langkah mudah ini.', '[\"1/2 kilo daging sapi dicampur tulangan dan daging babat\", \"1 batang sereh di geprek\", \"4 helai daun salam\", \"5 helai daun jeruk\", \"secukupnya Garam\", \"1500 ml air\", \"Asem jawa yang sudah diberi air\", \"Bumbu halus :\", \"2 lombok besar\", \"Kira2 2 cm kunyit\", \"2 cm jahe\", \"2 cm lengkuas\", \"2 biji keluek rendam air hangat agar lunak\", \"1/2 sendok teh jintem\", \"1/2 sendok teh ketumbar\", \"secukupnya Garam\"]', '[\"Rebus daging, kemudian buang air rebusan pertama. Lebih baik babat direbus secara terpisah. Daging dipotong dadu.\", \"Tumis bumbu halus di campur dengan sereh yg sudah di geprek, daun salam,daun jeruk dan air asem jawa.\", \"Tuang air kedalam tumisan, aduk rata. Kemudian masukkan semua daging. Aduk hingga tercampur rata, dan jangan lupa ditambahkan garam.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(449, 4, 'Sambel Ati Sapi', 'Sambel Ati Sapi - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1/2 Kg Ati Sapi\", \"3 Buah Kentang\", \"2 Papan Pete\", \"2 Cm Lengkuas (Di Geprek)\", \"Secukupnya Santan (Bisa di ganti air)\", \"Garam\", \"Gula\", \"Lada Bubuk\", \"Bumbu Halus\", \"10 Buah Cabe Merah (Boleh Di Tambah)\", \"15 Buah Cabe Rawit\", \"3 Buah Bawang Putih\", \"4 Buah Bawang Merah\", \"2 Buah Kemiri\"]', '[\"Rebus Ati Sapi, Setelah itu potong potonh dadu\", \"Goreng kentang yg sudah di potong potong\", \"Tumis bumbu halus dan lengkuas sampai harum (Minyak nya agak banyak biar ada kuah)\", \"Sudah harum, masukkan ati sapi dan santan\", \"Lalu masukkan kentang yg sudah di goreng dan pete\", \"Tambah garam, lada dan gula secukupnya\", \"Cicip dan tunggu sampai santan meresap.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(450, 3, 'Gulai tahu + kikil sapi', 'Resep Gulai tahu + kikil sapi yang lezat dan mudah dibuat di rumah.', '[\"1 bungkus tahu kulit\", \"1 bungkus kikil sapi\", \"1 ruas kunyit\", \"1 ruas laos geprek\", \"6 cabai merah\", \"sereh geprek\", \"1 lembar daun salam\", \"1 lembar daun jeruk\", \"3 siung bawang putih\", \"1 siung bawang merah\", \"ketumbar\", \"2 biji kemiri\", \"royco\", \"garam\", \"1/4 gula merah\", \"santan (kl saya pake santan kara bunda biar cepet 😂)\"]', '[\"Rebus dulu ya bunda kikilnya sampai mendidih\", \"Potong dadu tahu kulitnya\", \"Rebus kunyit dan cabai agar empuk saat di uleg\", \"Uleg bumbu bawang putih, bawang merah, kemiri, ketumbar, lalu kunyit dan cabai merah yg sdh di rebus td\", \"Tumis bumbu sampai harum dan masukan lengkuas, salam, sereh, dan daun jeruk\", \"Tambahkan air 4 gelas tunggu sampai setengah mendidih masukan kara dan gula merah\", \"Tunggu sampai mendidih dan masukan kikil terlebih dahulu kurleb 5menit lalu masukan tahu kulit\", \"Tambahan royco, garam\", \"Tunggu sampai kurleb 15menit cek rasa..\", \"Siapkan wadah untuk penyajian..\", \"Happy cooking bunda 😊 kl berhasil jgn lupa recook ya bunda 😃\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(451, 2, 'Sop Kaki sapi rempah', 'Buat Sop Kaki sapi rempah yang nikmat dengan langkah-langkah mudah ini.', '[\"1 kg kaki sapi (sya beli yg sdh di potong2 di psr tradisional)\", \"1/2 sdm garam\", \"1 sdt gula\", \"2 siung bawang putih\", \"2 lbr daun salam\", \"1 btg sereh lalu geprek\", \"1 liter air\", \"Rebus kaki sapi beserta bumbu di atas dlm presto selama 15 mnit\", \"Setelah 15 menit matikan panci tunggu sampai uap panasnya hilang\", \"Baru buka pancinya (bagi pemula harap hati2 ya)\", \"Selanjutnya siapkan\", \"4 batang wortel iris kotak kotak ukuran sedang\", \"2 buah kentang iris kotak ukuran sedang\", \"1 batang brokoli ukuran sedang potong sesuai selera\", \"4 lbr kol sobek2 sesuai selera\", \"2 buah tomat iris kotak besar\", \"2 batang seledri iris halus\", \"2 batang daun bawang iris halus\", \"Bumbu:\", \"3 siung bawang putih halus kan\", \"1 siung bawang bombay cincang halus\", \"1 sdt merica\", \"5 biji cengkih\", \"1 sdt pala bubuk\", \"1 ruas kayu manis (kira2 3cm) / 1sdt\", \"1 blok kaldu sapi maggi\", \"1 sdt gula\", \"secukupnya Garam\"]', '[\"Rebus semua sayuran dengan air 500ml sampai empuk (kol dan brokoli dimasukan terakhir ya)\", \"Tumis semua bumbu dengan 3sdm minyak sampai harum..\", \"Setelah sayuran empuk masukan kaki sapi yang sudah di presto beserta kaldunya\", \"Masukan bumbu yang sudah di tumis lalu tunggu sampai mendidih\", \"Tambahkan kaldu blok, garam dan gula aduk rata\", \"Terakhir tambahkan seledri dan bawang daun\", \"Matikan api lalu masukan potongan tomat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(452, 2, 'Rawon sapi', 'Resep Rawon sapi yang lezat dan mudah dibuat di rumah.', '[\"250 gr daging sapi\", \"1 ruas lengkuas (geprek)\", \"3 lembar daun salam\", \"Sereh (geprek dan simpulkan)\", \"Penyedap (royco sapi)\", \"Gula\", \"Garam\", \"Secukupnya air untuk merebus daging\", \"Bumbu halus\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"2 butir kemiri\", \"2 ruas jahe\", \"1,5 ruas kunyit\", \"1 butir kluwak\", \"Bahan pelengkap\", \"Daun bawang\", \"Tomat\", \"Toge\", \"Bawang goreng\", \"Sambal\", \"Kerupuk\"]', '[\"Cuci bersih daging sapi, rebus 10 menit, buang air\'y lalu rebus lagi kira-kira 15 menit sampai daging empuk. Atau bisa ditambahkan sdikit baking soda pada rebusan pertama agar daging lebih empuk. Potong\\\" daging lalu masukkan kembali ke air rebusan.\", \"Tumis bumbu halus. Setelah tercium harum lalu masukkan lengkuas,daun salam dan sereh. Tambahkan air kaldu rebusan sedikit (agar tidak gosong) kemudian masukkan ke dalam rebusan air daging.\", \"Masukkan bumbu penyedap, gula, garam, dan bumbu pelengkap. Tes rasa dan sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(453, 3, 'Beef Stroganoff Creamy', 'Sajian Beef Stroganoff Creamy yang praktis dan lezat untuk dinikmati bersama.', '[\"400 gr daging sapi\", \"100 gr jamur kancing\", \"1 buah bawang bombay ukuran besar\", \"20 gr butter\", \"1/2 sdm tepung kanji\", \"Bumbu:\", \"5 sdm pasta tomat/saus tomat\", \"180 gr sour cream (200ml)\", \"Secukupnya garam dan lada\", \"200 ml air\", \"2 sdt bubuk kaldu sapi\"]', '[\"Potong memanjang bawang bombay, potong jamur kancing menjadi empat bagian\", \"Potong daging menjadi ukuran 1 suap\", \"Panaskan 5gr butter pada wajan lalu tumis daging, tambahkan garam dan lada secukupnya\", \"Jika daging sudah berubah warna, angkat dan sisihkan\", \"Panaskan sisa butter (15gr) dan tumis bawang bombay hingga layu\", \"Setelah layu, tambahkan jamur kancing dan tumis hingga semua berubah warna menjadi kecoklatan\", \"Kemudian tambahkan daging yang telah disisihkan tadi, aduk rata\", \"Tuang air, kaldu bubuk dan pasta tomat, aduk rata dan tunggu 5 menit\", \"Campur tepung kanji dan sour cream lalu masukkan ke wajan, aduk rata\", \"Tunggu hingga kuah benar-benar mengental baru matikan api\", \"Beef stroganoff siap disajikan bersama nasi\", \"Tips: jika takut daging akan keras atau alot, rebus daging terlebih dahulu. Air sebusan daging dapat dijadikan pengganti air dan kaldu bubuk\", \"Tips: jika ingin warna lebih gelap atau rasa lebih kuat kurangi jumlah sour cream\", \"Tips: sour cream bisa diganti plain yoghurt ditambah air jeruk nipis\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(454, 2, 'Semur daging sapi ala Hongkong (Ngau lam)', 'Nikmati kelezatan Semur daging sapi ala Hongkong (Ngau lam) dengan resep sederhana ini.', '[\"50 HKD Daging sapi (ngaulam)\", \"1 buah lobak merah\", \"2 sdm saus Chu hou paste\", \"1 sdm gula batu, 1/2sdt garam\", \"1 sdt kecap hitam (lou jau)\", \"1 sdt kecap asin\", \"4 siung bawang putih\", \"4 siung bawang merah\", \"2 lembar jahe\", \"Sedikit minyak untuk menumis\"]', '[\"Rebus daging sapi yang sudah di potong dengan air panas buang airnya.Tiriskan\", \"Cairkan 2 sdm chu hou paste dengan 1/2 mangkok kecil air.\", \"Tumis bawang putih, bawang merah yang sudah di keprek.Masukkan jahe, masukan daging, lalu masukkan chu hou paste.Tiriskan\", \"Rebus air 1000 ml di panci, masukkan daging sapi, masukkan kecap hitam, kecap asin, garam rebus dengan api kecil 1 jam\", \"Masukkan lobak merah, lalu rebus lagi 30 menit. Matikan api, hidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(455, 3, 'Bakso Sapi Keto #keto #ketopad #ketofy #ketofastosis', 'Hidangan daging sapi istimewa: Bakso Sapi Keto #keto #ketopad #ketofy #ketofastosis.', '[\"500 gr daging sapi\", \"250 gr lemak / gajih sapi\", \"150 ml putih telur (sekitar 4 telur)\", \"8 siung bawang putih\", \"6 sdm bawang merah goreng\", \"2 sdm bawang putih goreng\", \"1 sdm himalayan salt (sesuai selera)\", \"2 sdt lada putih / merica (sesuai selera)\", \"2 sdt kaldu sapi bubuk (Royco)\", \"2 sdm minyak kelapa (Barco)\", \"Air untuk merebus bakso\"]', '[\"Potong potong daging & lemak\", \"Giling daging & lemak dengan food processor\", \"Pindahkan gilingan daging ke baskom, masukkan gilingan daging tersebut ke dalam freezer, biarkan sampai setengah beku\", \"Haluskan (uleg) bumbu-bumbu. Bawang putih, bawang merah goreng, bawang putih goreng, kaldu sapi bubuk, garam & merica\", \"Masukkan es batu, daging giling setengah beku yang telah dipotong-potong, putih telur, bumbu halus. Giling sampai halus lembut seperti pasta. Terakhir masukkan minyak barco, giling lagi sampai rata (Adonan cenderung lembek yaa)\", \"Pindahkan ke wadah, banting-banting sekitar 10-15kali. (Agar adonan homogen) kemudian tutup menggunakan cling wrap, masukkan ke kulkas semalaman. Agar adonan tidak terlalu lembek dan bisa dibentuk\", \"Siapkan es batu untuk menjaga tangan kita agar tetap dingin saat membentuk bakso\", \"Bentuk adonan daging menjadi bulat2\", \"Bisa juga isi bakso dengan keju\", \"Bisa juga diisi dengan telur\", \"Didihkan air, kemudian matikan api. Masukkan bakso2 tersebut. Setelah adonan daging habis dibentuk, nyalakan api (kecil)\", \"Jika bakso sudah mengapung, berarti sudah matang\", \"Angkat dan tiriskan\", \"Yummy....... walaupun teksturnya tidak sekenyal bakso bertepung 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(456, 4, '3.SOTO BENING daging sapi', 'Hidangan daging sapi istimewa: 3.SOTO BENING daging sapi.', '[\"1/4 Daging sapi\", \"Bawang merah\", \"Bawang putih\", \"Kemiri\", \"Ketumbar\", \"Jahe\", \"Daun bawang\", \"Kentang\", \"Tomat\", \"Sambal\", \"Kerupuk\", \"Bawang goreng\", \"Bihun\", \"Salam sereh laja\", \"Jeruk nipis\", \"Kol\"]', '[\"Rebus daging yg sudah dipotong2+salam sereh laja\", \"Haluskan bumbu bawang merah bawang putih jahe dikit kemiri ketumbar.. Lalu tumis sampai Wangi.masukN ke rebusan daging. Beri garam+gula secukupnya *selesai*\", \"Buat sambal; re bus cabe n rawit haluskan bersama gargul n beri air soto. *Selesai*\", \"Pelengkap; bawang daun kol sisir halus. tomat potong2.bihun direbus 3 mnt.kentang potong tipis cuci air garam lalu goreng.*selesai*\", \"Saran penyajian siapkan mangkok masukan bihun kol bawDaun tomat siram air soto yg panas +daging beri kentang goreng bawang goreng krupuk jangan lupa sambal n perasan jeruk nipis..\", \"Siap santaaap....\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(457, 4, 'Spaghetti Aglio Olio grill beef spice tomat sauce', 'Cara membuat Spaghetti Aglio Olio grill beef spice tomat sauce yang enak dan praktis untuk keluarga.', '[\"180 gr spaghetti\", \"180-200 gr beef tenderloin\", \"50 gr sauce bolognaise instant\", \"5 buah cabe rawit iris halus\", \"1 bungkus bumbu aglio instant\", \"1 sdm Margarin\", \"2 siung bawang putih cincang\", \"Bawang Bombai cincang\", \"secukupnya Garam\", \"secukupnya Lada hitam\", \"5-10 gr Keju parut\"]', '[\"Didihkan air, setelah panas masukan spaghetii dan margarin aduk jangan sampe patah\", \"Setelah setengah matang (aldente) angkat tiriskan, dinginkan spaghetti dalam air es, tiriskan.\", \"Balurkan beef garam dan lada hitam, setelah itu panggang beef sampai ke taraf medium well setengah matang, angkat\", \"Panaskan lagi spaghetti sebentar angkat. lalu panaskan teflon masukan margarin tumis bawang putih cincang, bawang bombai, masukan spaghetti tadi dan bumbu instan aglio, cabe rawit iris, keju parut,garam,lada secukupnya Aduk rata...\", \"Panaskan sauce bolognaise angkat. Lalu siapkan piring untuk disajikan\", \"Spaghetti diatasnya beef dan hiasan sedikit keju parut dan sauce bolognaise. Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(458, 2, 'Creamy Beef Fettuccine ala resto (simple, tapi enak)', 'Resep Creamy Beef Fettuccine ala resto (simple, tapi enak) yang lezat dan mudah dibuat di rumah.', '[\"40 gram Fettuccine /Spaghetti (kira2 cukup utk 2 porsi)\", \"100 gram daging sapi cincang\", \"8-10 butir Jamur merang/kancing iris tipis\", \"100 ml susu cair encer (saya pakai susu ultra plain biru)\", \"Keju cheddar atau Edame, parut kasar\", \"Sejumput Oregano\", \"Bubuk cabe\", \"Lada bubuk\", \"2 siung Bawang putih, geprek, cincang kasar\", \"1/2 Bawang Bombay sedang, bagi 2,iris kasar\", \"2 sdm Saus tomat\", \"1 sdm Saus sambal atau sesuai selera\", \"Gula garam\"]', '[\"Rebus pasta dalam 400-500ml air mendidih selama 10menit. Pasta akan mengembang, jadi air harus bisa merendam pasta seluruhnya. Beri sejumput garam. Tanda pasta matang adalah air terserap dan pasta bisa mudah kita putus dengan jari\", \"Lelehkan margarine, tumis bawang putih dan bawang bombay hingga layu dan harum, masukkan daging cincang masak hingga berubah warna, susul masukkan jamur cincang, aduk2 dan taburi Lada, garam, gula, lalu masukkan susu cair, saus tomat dan saus sambal\", \"Masak hingga mendidih, beri sejumput oregano, tambahkan air bila terlalu kental. Kemudian masukkan pasta yg sudah al dente, taburi keju parut, aduk sebentar dan koreksi rasa dengan garam gula. Bila sudah gurih dan pas, angkat di piring dengan jepitan sambil di putar. Pasta akan tersaji rapih di piring, tuang sisa saus\", \"Sajikan panas dengan taburan keju (bubuk cabe bila suka). Saya lupa naruh gratter jadi kejunya diiris tipis. Hehe.. Enak juga kok\", \"Tips : creamy sauce akan meresap ke dalam pasta dengan memasukkan pasta matang ke dalam saus. Hati2 memasak saus karna susu akan mengental lebih cepat daripada air dan saus bisa jadi kering\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(459, 3, 'Gulai Iga Sapi Lezaat 💋', 'Gulai Iga Sapi Lezaat 💋 - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1/2 kg Iga sapi\", \"1/4 kg babat, usus, tetelan\", \"1 sachet bumbu Gule Instan\", \"secukupnya Bawang Goreng\", \"1 santan kara kecil\", \"💞 Bumbu Halus :\", \"7 siung bawang merah\", \"4 siung bawang putih\", \"1 serai geprek\", \"1 ruas jari lengkuas geprek\", \"3 lembar daun salam\", \"15 buah cabe rawit\", \"5 buah cabe merah\", \"1 ruas jari kunyit\", \"1 ruas jari jahe geprek\"]', '[\"Rebus iga dan tetelan selama 30 menit (sampai empuk)\", \"Uleg semua bumbu halus dan campur hingga rata\", \"Siapkan wajan untuk menumis bumbu halus + bumbu instan sampai harum dengan sedikit minyak goreng\", \"Siapkan panci dengan berisi air hampir penuh, tunggu hingga mendidih\", \"Masukkan campuran bumbu, aduk aduk\", \"Masukkan iga sapi dan juga tetelan yang sudah direbus ke dalam panci tersebut\", \"Tunggu 15 menit hingga mendidih\", \"Tambahkan santan kara dan bumbu tambahan (masako, gula, garam sesuai selera) aduk terus 15 menit agar santan tidak pecah\", \"Test rasa sambil terus diaduk aduk\", \"Siap disajikan dengan tambahan bawang goreng dan sambal kacang kecap plus jeruk nipis yang segaaar\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(460, 3, 'Lidah Sapi Saus Keju ala bundakeia', 'Lidah Sapi Saus Keju ala bundakeia - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 kg lidah sapi matang, iris sesuai selera\", \"1 siung bawang bombay, iris tipis\", \"5 siung bawang putih, cincang kasar\", \"3 sdm margarine\", \"2 sdm saus tomat/pasta tomat\", \"200 cc susu cair\", \"40 gr keju chedar, parut\", \"secukupnya Garam, lada putih, pala bubuk\"]', '[\"Panaskan margarine, tumis bawang bombay & bawang putih sampai harum\", \"Masukkan susu cair, aduk rata, diamkan hingga agak mendidih\", \"Masukka saus tomat, garam, lada putih & pala secukupnya, aduk rata, masak hingga mendidih\", \"Masukkan lidah sapi yang telah dipotong, aduk rata.\", \"Terakhir masukkan keju parut, aduk rata. Masak hingga saus sedikit asat & mengental.\", \"Siap disajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(461, 2, 'Tumis daging sapi brokoli ala d\'kost', 'Resep praktis Tumis daging sapi brokoli ala d\'kost yang bisa dicoba di rumah.', '[\"250 gram daging sapi kualitas bagus\", \"1 buah brokoli potong kecil2\", \"1 buah bunga kol potong kecil\", \"1 buah wortel ukuran sedang potong kecil\", \"1 sdm saos tiram\", \"Secukupnya garam\", \"Secukupnya merica bubuk\", \"1 ruas jahe (cincang halus)\", \"2 siung bawang putih (cincang halus\", \"3 siung bawang putih iris tipis\", \"1/2 bawang bombay ukuran besar\", \"2 sdm kecap manis\", \"500 ml air putih\", \"200 ml air kaldu sapi didapat dr air rebusan\"]', '[\"Cuci bersih daging sapi,panaskan air masukan daging sapi dengan bawang putih cincang halus dan jahe halus tunggu sampai mendidih dan air berkurang,setelah matang angkat sapi dan potong dadu air rebusan jgn di buang\", \"Panaskan minyak goreng tumis bawang bombay, bawang putij sampai harum\", \"Masukan brokoli, kembang kol,wortel tumis sampai agak layu kemudian masukan daging sapi aduk2 lagi\", \"Setelah itu masukan air kaldu sisa rebusan bumbui dgn garam, gula putih,saos tiram,merica bubuk sampai kuah surut kemudian tambahkan kecap manis aduk lagi tunggu sampai kuah berkurang\", \"Dan jadilah tumisnya angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(462, 3, 'Ice cream Susu sapi', 'Nikmati kelezatan Ice cream Susu sapi dengan resep sederhana ini.', '[\"1 lt Susu sapi\", \"30 gr tepung maizena\", \"200 gr gula pasir\", \"1 sachet skm putih\", \"1/2 sdm SP\", \"Pasta rasa2 sesuai selera (saya pakai strawberry Dan anggur)\"]', '[\"Masak Susu, gula, skm, Dan tepung maizena yang sudah dilarutkan terlebih dahulu dg air hingga meletup letup. Dinginkan adonan lalu masukkan ke freezer hingga beku\", \"Kerok adonan yang sudah beku dg garpu. Tambahkan sp yg sdh ditim lalu mixer +/- 15 menit hingga adonan menjadi lembut Dan mengembang\", \"Bagi adonan menjadi Dua. Tambahkan pasta sesuai selera. Masukkan freezer hingga beku.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(463, 2, 'Beef Lasagna', 'Nikmati kelezatan Beef Lasagna dengan resep sederhana ini.', '[\"Lasagna instan (me : San Remo)\", \"Italian herbs\", \"Mozarella untuk topping\", \"Saus merah :\", \"350 gr Daging sapi cincang\", \"1 bawang bombay dipotong dadu\", \"5 siung bawang putih cincang/parut\", \"1 kaleng pasta tomat (me : Del Monte)\", \"1 sachet saus bolognaise La Fonte\", \"200 ml air\", \"Garam\", \"Gula\", \"Merica\", \"Saus putih :\", \"500 ml susu cair\", \"3 sdm tepung terigu\", \"3 sdm margarine / butter\", \"1/2 bagian keju ukuran 170gr\", \"Garam\", \"Merica\"]', '[\"Saus merah : tumis bawang putih + bawang bombay hingga harum. Lalu masukkan daging cincang, masak hingga daging berubah warna. Masukkan pasta tomat, saus bolognaise, air, masak hingga matang. Masukkan garam, gula, italian herbs. Sisihkan.\", \"Saus putih : cairkan margarine/butter dengan api kecil, masukkan terigu, aduk cepat hingga berwarna keemasan, masukkan setengah bagian susu, aduk hingga rata. Masukkan sisa susu, masukkan keju parut, aduk rata hingga keju larut, matikan api, sisihkan. Jangan terlalu lama memasak saus putih. (bechamel akan lebih kental dalam suhu ruang)\", \"Dalam pinggan tahan panas, tuang sedikit saus putih, kemudian di atasnya saus merah, kemudian lasagna. Ulangi tiap lapisan hingga ketinggian yg diinginkan, lapisan paling atas tutup dengan keju mozarella.\", \"Panggang dalam oven suhu 180c, selama 30 - 40 menit. (Kalau mau lebih cepat matang, Lasagna instant bisa direbus terlebih dahulu sekitar 1 menit sebelum digunakan)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(464, 2, 'Pizza Sosis Sapi Keju Simple dgn teflon', 'Buat Pizza Sosis Sapi Keju Simple dgn teflon yang nikmat dengan langkah-langkah mudah ini.', '[\"6 biji sosis sapi (sya pake merek champ)\", \"Keju quick melt\", \"Keju biasa\", \"Saos tomat\", \"250 grm tepung trigu\", \"2 sendok ragi instan\", \"1/2 sendok gram\", \"Air hangat\", \"Mentega\", \"5 sendok Minyak makan\"]', '[\"Siapkan tempat untuk adonan. Masukan tepung,ragi,garam, minyak makan, air hangat sedikit demisedikit(klo lengket di tangan, siapkan minyak saja). Klo sudah kalis simpan selama 30 menit tutup dgn kain basah. Tunggu hingga mengembang.\", \"Jika sudah mengembang bagi menjadi 3 bagian dan siapkan teflon yg ada tutupx untuk memangang.\", \"Teflon di olesi margarin, kemudian masukan adonan tekan2 sampai pipih ke smua pinggiran teflon, taruh keju yg di potong2 ke pinggir adonan dan bungkus dgn adonan kemudian tusuk2 dengan garpu kesemua bagian kecuali bagian keju yg di tutupi\", \"Masukan saos tomat, sosis, dan keju(kalau mau tambah bawang bombai dan jamur juga ok)\", \"Pangang dengan api kecil, jaga sampai masak dan sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(465, 3, 'Sayur sop baso sapi', 'Nikmati kelezatan Sayur sop baso sapi dengan resep sederhana ini.', '[\"250 gr baso sapi\", \"1 pcs wortel\", \"1 pcs kentang (agak besar)\", \"5 pcs buncis\", \"2 batang daun sop/seledri\", \"1 batang daun bawang\", \"Sedikit kembang kol\", \"secukupnya Air\", \"3 siung bawang putih\", \"1/2 sdt merica bubuk\", \"Garam\", \"Gula\"]', '[\"Potong2 sayur semuanya, cuci dan tiriskan\", \"Haluskan bawang putih tadi, lalu tumis.\", \"Kasih air secukupnya, masukkan bakso sampai mengapung lalu masukkan sayur yg sudah d potong2. Tunggu mendidih\", \"Masukkan potongan daun sop dan daun bawang. Serta masukkan merica bubuk garam gula\", \"Tes rasa. And siap d sajikan selagi hangat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(466, 4, 'Tulang sapi masak kecap', 'Nikmati kelezatan Tulang sapi masak kecap dengan resep sederhana ini.', '[\"1/2 kg tulangan sapi\", \"secukupnya Cabe rawit\", \"secukupnya Cabe merah\", \"4 siung bawang merah\", \"1 buah tomat\", \"Penyedap rasa\", \"Sedikit gula putih\", \"1 ruas bawang daun\", \"1 bungkus kecil kecap bango\"]', '[\"Cuci tulangan hingga bersih,lalu rebus tulangan kira-kira 1 jam dan sisa kaldu rebusan jangan di buang.\", \"Cabe merah iris serong,cabe rawit biarkan satuan, tomat potong menjadi 4 bagian lalu bawang merah potong dadu.\", \"Panaskan minyak sayur secukupnya kemudian masukan tulangan yang sudah di rebus kasih sedikit kaldu nya kemudian masukan cabe,tomat,bawang sambil aduk2 kemudian kecap manis,royco rasa sapi dan gula putih sedikit sambil aduk dan air kaldu sedikit meresap lalu cicipi. Hidangkan dech😋😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(467, 4, 'Gulai Tetelan Sapi', 'Resep praktis Gulai Tetelan Sapi yang bisa dicoba di rumah.', '[\"500 gr tetelan sapi\", \"1 buah sereh keprek\", \"3 lembar daun salam\", \"4 lembar daun jeruk\", \"3 butir cengkeh\", \"2 sendok makan air asam jawa (dari 3 daging buah asam jawa diberi air panas)\", \"1,5 liter santan (atau 1300 ml air + 1 kotak kara 200 ml)\", \"Garam dan gula\", \"Bumbu halus :\", \"10 buah cabe keriting\", \"8 butir bawang merah\", \"4 siung besar bawang putih\", \"4 butir kemiri\", \"3 cm kunyit\", \"4 cm jahe\", \"4 cm lengkuas\", \"1 sendok makan ketumbar bubuk\", \"1 sendok teh lada bubuk\"]', '[\"Tumis bumbu halus dengan minyak goreng, masukkan daun salam, daun jeruk, sereh dan cengkeh aduk hingga wangi, masukkan tetelan aduk rata\", \"Masukkan santan, aduk-aduk sesekali agar santan tidak pecah, jika sudah mendidih kecilkan api sedikit, masukkan air asam jawa, masak hingga matang dan kuah mengental, beri garam, gula, koreksi rasa\", \"Sajikan dengan bawang goreng jika ada\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(468, 2, 'Daging sapi & tahu masak santan', 'Cara membuat Daging sapi & tahu masak santan yang enak dan praktis untuk keluarga.', '[\"300 gr daging sapi, cuci bersih\", \"4 buah tahu uk.biasa, potong sesuai selera\", \"2 btg sere, memarkan\", \"1 lembar daun salam\", \"2 lembar daun jeruk\", \"sesuai selera Cabe rawit merah utuh\", \"1 sdt Kaldu bubuk sapi\", \"secukupnya Gula garam\", \"65 ml santan kara\", \"secukupnya Air kaldu sapi\", \"Bumbu halus:\", \"2 siung besar bawang putih\", \"5 siung besar bawang merah\", \"4 buah cabe merah keriting\", \"7 buah cabe rawit merah/orange\", \"2 butir kemiri\", \"2 cm jahe\", \"2 m lengkuas\", \"1/2 sdt ketumbar bubuk\", \"1/2 sdt kunyit bubuk\", \"1/2 sdt lada bubuk\"]', '[\"Rebus daging sapi selama 15 menit, kemudian potong2 sesuai selera sisihkan.\", \"Tumis bumbu halus dg minyak secukupnya bersama daun salam, sere dan daun jeruk. Tumis beserta cabe utuh juga hingga matang/layu dan harum.\", \"Masukan air kaldu sapi secukupnya (sesuaikan saja sedikit banyaknya kuah ya😊). Kemudian masukan potongan tahu putih dan potongan sapi tadi..\", \"Masak sekitar 10 menitan, bumbui gula, garam dan kaldu bubuk sapi, aduk rata. Terakhir masukan santan kental kara kemasan 65 ml, aduk rata kembali hingga mendidih lalu matikan api.\", \"Taruh dimangkuk saji... sajikan dg nasi hangat... dan selamat mencoba😄😄\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(469, 2, 'Burger with Homemade Beef Patty', 'Resep Burger with Homemade Beef Patty ala rumahan yang dijamin menggugah selera.', '[\"250 gr Daging sapi giling\", \"1 butir telor ayam\", \"2 sdm Tepung panir\", \"1 bh bawang bombay diiris kotak kecil\", \"Bawang putih tumbuk kasar\", \"secukupnya Garam\", \"secukupnya Merica\", \"secukupnya Oregano\"]', '[\"Tumis bawang bombay dan bawang putih sampai harum, angkat lalu sisihkan\", \"Kocok telur lalu masukkan daging giling dan tumisan bawang, aduk rata\", \"Campur adonan dengan tepung roti, lalu bentuk bulat2\", \"Masukkan daging burger di kukusan yg sdh diberi alas alumunium foil yg diberi mentega. Masak hingga matang.\", \"Beef patty alias daging burger siap diolah ☺\", \"Jika ingin membuat burger, keluarkan beef patty dr kulkas lalu goreng memakai mentega dg api kecil supaya panasnya merata 👌👌\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(470, 4, 'Bakso hati dan daging sapi', 'Hidangan daging sapi istimewa: Bakso hati dan daging sapi.', '[\"Sekitar 1/4 kg  hati sapi\", \"2 sdm daging sapi giling (mmg sy stok utk anak)\", \"8 kotak es batu serut...bs jg blender\", \"1 butir telur ayam kampung\", \"Sekitar 1 sdm  ketumbar bubuk\", \"1/2 sdk teh baking powder\", \"1 sdm  Sekitar merica bubuk\", \"3 siung bawang putih yg gde haluskan\", \"Tepung tapioka\", \"Air utk merebus\", \"Garam dan gula\", \"1 sdm Bawang putih bubuk\"]', '[\"Rebus hati sapi sd matang kmdn blender\", \"Dlm wadah besar atau blender campur daging giling...aduk...campur bumbu2 ketumbar, lada, bawang putih bubuk, telur...aduk.tambhkan batu es...aduk\", \"Tambahkan tepung tapioka sd bs dibentuk bakso...tambahkan baking powder, garam dan gula...cicipi rasa...hanya dicicip diujung lidah saja kmdn kumur2 dan buang\", \"Didihkan air dgn api kecil..Bentuk adonan dgn tangan...cemplungkan k dlm air...rebus dgn api besar sd bakso mengapung...\", \"Angkat...bs diolah dan disimpan...sisa air rebusan bs utk kaldu mengolah berbagai makanan...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(471, 3, 'Bakso Sapi Kenyal Pakai Blender', 'Resep Bakso Sapi Kenyal Pakai Blender yang lezat dan mudah dibuat di rumah.', '[\"250 gr daging sapi giling\", \"50 gr daging ayam giling (boleh di skip)\", \"1 butir putih telur\", \"4-5 buah es batu kotak kecil\", \"3 sdm tepung kanji/tapioka (munjung)\", \"2 sdt bawang putih bubuk (2 siung bawang putih, dihaluskan)\", \"1 sdm bawang merah goreng\", \"1 sdt garam\", \"1/2 sdt merica bubuk\", \"1/2 sdt kaldu jamur/penyedap rasa\", \"1/2 sdt baking powder\", \"secukupnya air\"]', '[\"Masukkan ke blender putih telur, bawang putih bubuk, bawang goreng, garam, merica bubuk, penyedap rasa dan baking powder, kemudian blender sebentar\", \"Masukkan daging sapi dan ayam, blender lagi sampai tercampur. Masukkan es batu dan tepung tapioka, blender hingga merata hingga adonan bertekstur seperti pasta (tidak terlalu lembek). Pindahkan ke dalam baskom\", \"Panaskan air hingga mendidih, kemudian matikan api, bentuk bakso dan dimasukkan ke air yang sudah di rebus, jangan lupa oles sedikit minyak di tangan/sendok yang dipakai membentuk bakso agar tidak terlalu lengket. Lakukan hingga adonan habis, hingga mengapung semua adonan bakso yang sudah dibentuk, jika sudah mengapung semua, nyalakan api hingga mendidih dan pastikan semua bakso sudah mengapung (tanda jika bakso sudah matang), rebus kira-kira 5 menit kemudian angkat dan masukkan ke dalam air es\", \"Rendam hingga bakso dingin/sekitar 3 menitan, buang air dan tiriskan baksonya. Bakso siap diolah atau segera simpan di freezer untuk stok. Selamat mencoba 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(472, 2, 'Sayur Asem Lamur Sapi (lemak sapi)', 'Resep Sayur Asem Lamur Sapi (lemak sapi) ala rumahan yang dijamin menggugah selera.', '[\"Secukupnya lamur sapi\", \"1 bungkus sayur asem (beli dipasar)\", \"1 Daun salam\", \"2 bawang putih iris\", \"3 bawang merah iris\", \"2 cabe merah potong kasar\", \"Air\", \"Secukupnya Garam\", \"Secukupnya gula\", \"Secukupnya penyedap (optional)\"]', '[\"Tumis duo bawang,cabe,daun salam sampe harum. Masukkan lamur sapi. Kemudian masukkan sayur dan tumis sampai layu.\", \"Masukkan air, garam,gula,penyedap.\", \"Setelah sayuran mulai matang masukkan tomat. Cek rasa dan masak sampai matang\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(473, 4, 'Beef & Vegetable Japanese Curry Rice', 'Beef & Vegetable Japanese Curry Rice dengan daging sapi empuk dan bumbu kaya rasa.', '[\"1/2 bawang bombay\", \"200 gr daging sapi, potong kotak2\", \"2 buah kentang\", \"1 buah wortel\", \"Buncis\", \"Jamur\", \"2 blok (1/2 paket) japanese curry block\", \"Minyak sayur\", \"1 sdm shoyu\", \"1 sdm saos tomat\", \"2 piring nasi (saya pakai nasi putih mix merah)\", \"700-800 ml air\"]', '[\"Iris bawang bombay, potong2 kentang, wortel, buncis dan jamur. Potongan jangan terlalu kecil supaya tidak hancur saat proses memasak. Sayuran juga boleh pakai yang lain (misalnya brokoli), di sini saya pake sayuran sisa :)\", \"Panaskan minyak di dalam panci, masukkan bawang bombay. Masak sampai bawang melunak.\", \"Masukkan sayur2an & kentang. Sayur2an dan kentang ditumis dulu supaya nantinya tidak mudah hancur (tips dari Akari Papa and it works!)\", \"Masukkan daging sapi, masak sampai warna daging sudah tidak merah lagi.\", \"Tambahkan air, masak hingga mendidih. Sendokkan buih2 yang berwarna putih dan buang. Rebus kira2 20 menit.\", \"Tambahkan curry blok, aduk2 hingga mencair. Masukkan shoyu & saos tomat. Masak lagi 5-10 menit.\", \"Biasanya saya selalu simpan di kulkas semalaman dan makan keesokan harinya, katanya sih bumbu lebih meresap jadi rasanya lebih enak! Selamat mencoba! 😋😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(474, 3, 'Daging sapi barbeque', 'Daging sapi barbeque dengan daging sapi empuk dan bumbu kaya rasa.', '[\"1/4 kg Daging sapi\", \"1 Sachet saori barbeque\", \"1/2 Bawang bombay\", \"3 Cabe (pake paprika lebih ok)\", \"secukupnya Gula garam\"]', '[\"Simpan daging sapi dalam freezer dan potong tipis tipis saat beku\", \"Tumis bawang bombay dan cabe yang sudah dipotong potong sebelumnya sampai harum\", \"Masukan daging sapi\", \"Tambahkan saori barbeque\", \"Koreksi rasa dan tambahkan Gula Garam sesuai selera\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(475, 4, 'Sapi Lada Hitam', 'Sapi Lada Hitam - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"400 gram irisan daging sapi\", \"3 sdt lada hitam bubuk\", \"1 buah jagung, di sisir\", \"15 buncis potong 4 - 5\", \"2 buah cabe hijau besar, iris serong\", \"2 buah tomat hijau, belah 6 bagian\", \"1 buah bawang bombay, iris besar\", \"3 sdm kecap manis\", \"2 sdm saus tiram\", \"2 Daun salam\", \"secukupnya gula merah\", \"secukupnya garam\", \"secukupnya gula\", \"secukupnya minyak\", \"160 ml air\", \"Bumbu Halus:\", \"4 siung bawang merah\", \"3 siung bawang putih\", \"1 ruas jahe, kupas dan bakar\"]', '[\"Tumis bumbu halus hingga wangi (api sedang)\", \"Masukan irisan daging (perbesar api, sambil di aduk 2-3 menit)\", \"Masukan kecap manis, saus tiram, gula merah, garam, gula, lada hitam, jahe, daun salam, air, cabe hijau (kecilkan api)\", \"Masukan bawang bombay, aduk\", \"Masukan buncis, jagung dan tomat hijau (perbesar api, aduk dan tutup wajan selama 2 - 3 menit agar air menyusut)\", \"Tes rasa, kalau ingin agak pedas bisa tambahkan 1 sdm abon cabe 😊......nnyyuuummmm\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(476, 3, 'Iga sapi & ayam bakar madu', 'Cara membuat Iga sapi & ayam bakar madu yang enak dan praktis untuk keluarga.', '[\"1/2 kg iga sapi\", \"1/2 ayam (bagian paha potong 4)\", \"1 sachet madu (kalo eyke sih madurasa)\", \"Kecap manis\", \"2 sdm margarin\", \"1/2 sdm ketumbar\", \"2 siung bawang merah\", \"3 siung bawang putih\", \"1/2 bawang bombay (ukuran kecil)\", \"1/2 bijipala\", \"1 cm jahe\", \"1 lbr daun salam\", \"2 lbr daun jeruk\", \"Garam\", \"1 bks lada bubuk\", \"Untuk bahan oles:\", \"3 sdm kecap manis\", \"2 sdm madu\", \"3 sdm minyak goreng\"]', '[\"Cuci bersih iga & ayam\", \"Rebus daging sapi menggunakan panci biasa dulu gausah terlalu lama hanya untuk menghilangkan darahnya aja lalu Presto iga sapi selama 15 menit dari bunyi (kalo ayamnya ga di presto ya karna nanti hancur)\", \"Ulek semua bahan bumbu halus.. Iris bawang bombay\", \"Tumis bumbu halus dan bawang bombay nya menggunakan margarin.. masukkan juga daun salam & daun jeruknya hingga harum\", \"Bila daging sudah dipresto slama 15 menit tunggu uap di dalam nya hilang baru buka tutup nya\", \"Tuangkan kurang lebih 500ml air kaldu daging ke tumisan\", \"Tes rasa\", \"Masukkan ayam nya dulu ya biar 1/2 empuk (agar iga sapinya ga clopot dari tulangnya haha ga cucooo ah pas di foto kalo dagingnya clopot dari tulangnya 😂😂)\", \"Tuang 2 sdm madu & secukupnya kecap sesuai selera.. Baru masukkan iga sapi nya\", \"Sambil menunggu air rebusannya sat trus diaduk\", \"Bila airnya sudah sat pindah ke wadah lain\", \"Iga sapi & ayam dioles pakai bumbu oles\", \"Bila panggangan sudah panas tata ayam & iga sapi panggang sambil dibolak balik agar ga gosong 😁😁\", \"Panggang sesuai keinginan.. Bila sudah dipanggang semua angkat & sajikan dengan sambal goreng terasi\", \"Resep sambalnya ada diresep eyke sebelumnya ya... 😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(477, 4, 'Lasagna beef', 'Resep praktis Lasagna beef yang bisa dicoba di rumah.', '[\"250 gr beef giling\", \"6 lembar Lasagna lembaran (la fonte)\", \"Loyang 25×25 cm\", \"Saus bolognese la fonte\", \"1/2 btg Keju chedar\", \"1 batang Keju mozzarella\", \"250 cc Susu ultra\", \"1 biji Bawang bombay\", \"2 sdm tepung terigu 2\", \"2 biji cengkeh\", \"secukupnya Pala\"]', '[\"Saus bolognese : tumis bombay sampai harum kmd masukan beef gilingnya tumis sampai matang, tambahkan saos lafonte bolognese tmbh kan air 150 cc aduk rata.\", \"Saus bechamel : tumis 3sdm butter atau mentega masukan tepung terigu aduk merata kmd masukan susu sampai cairan mengental tdk mengumpal..mskan keju chedar, lada grm cengkeh pala sisihkan dlm 1 wadah\", \"Memasak lasagna: lumuri loyong dg saus bechamel sampai rata\", \"Susun lasagna mentah selembar tuangkan sambil ratakan scr berurutan saus bechamrl.saus la fonte.saus bechamel, keju mozzarela.lakukan sampai 3 susun\", \"Lapisan teratas tuangkan saus bechmael n la fonte taburi keju mozzarela\", \"Panggang dlm oven 180°c selama 15 - 20 mnt\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(478, 3, 'Sop Kaki Sapi', 'Resep Sop Kaki Sapi ala rumahan yang dijamin menggugah selera.', '[\"12 potong kaki sapi\", \"2 buah wortel ukuran besar\", \"2 batang daun bawang\", \"2 batang seledri\", \"2 siung bawang putih\", \"5 buah tomat ukuran kecil\", \"500 ml air bersih\", \"1 sdt merica\", \"1 sdt penyedap rasa\", \"1/2 sdt garam\"]', '[\"Rebus kaki sapi hingga empuk, dan ini memakan waktu lama karena saya pake panci biasa. Pastinya akan lebih cepat jika menggunakan panci presto. Tiriskan. Sisihkan (Air rebusannya jangan dibuang, sesudah didinginkan dan disaring, air kaldunya akan kita tuangkan kembali).\", \"✔️Iris serong bawang daun. ✔️Kupas dan cuci bersih wortel, lalu dipotong-potong. ✔️Belah 4 tomat. ✔️Lepaskan kol dari batangnya. ✔️Potong-potong seledri dengan ukuran agak besar dan bagian batang daunnya dibiarkan utuh.\", \"Panaskan wajan, beri sedikit minyak goreng. Tumis bawang putih dan bawang daun hingga layu, lalu tuangi air bersih.\", \"Sesudah mendidih, masukkan seledri dan kaki sapinya lalu tuangkan air kaldu yang sudah disaring.\", \"Jika sudah mendidih kembali, masukkan wortel dan beri bumbu-bumbu berupa merica, garam, dan penyesap rasa. Aduk-aduk sembari koreksi rasa.\", \"Masukkan tomat. Tunggu sebentar saja kemudian angkat. Sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(479, 2, 'Terik daging dan hati sapi', 'Terik daging dan hati sapi - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1/2 kg daging sapi\", \"1/2 kg hati sapi\", \"1/2 butir kelapa, ambil 300ml santan kental saja\", \"Bumbu halus\", \"5 buah bawang merah\", \"5 buah bawang putih\", \"2 sdm ketumbar bubuk\", \"5 buah kemiri\", \"1/4 kg gula merah\", \"2 sdm gula pasir\", \"1 ruas jari laos, geprek\", \"3 buah daun salam\", \"1 ltr Air\", \"secukupnya Garam dan penyedap\"]', '[\"Cuci bersih daging dan hati. Potong tipis daging sapi. Hati dipotong kotak2.\", \"Haluskan bawang merah, bawang putih dan kemiri\", \"Tumis bumbu yang sudah dihaluskan, masukkan ketumbar, laos dan daun salam. Tumis sampai harum.\", \"Masukkan daging dan hati sapi, air, gula merah, gula, garam dan penyedap. Masak sampai empuk.\", \"Setelah daging empuk masukkan santan kental. Masak kembali dampai santan matang. Cicipi kembali koreksi rasa jika perlu.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(480, 3, 'Bola-bola sapi', 'Resep praktis Bola-bola sapi yang bisa dicoba di rumah.', '[\"250 gr daging sapi giling\", \"1 buah telur\", \"3 sdm terigu\", \"Garam\", \"Merica\", \"Kecap manis\", \"Saos Tiram\", \"Minyak goreng\", \"1 buah bawang bombay\", \"1 buah bawang putih\"]', '[\"Campur daging giling dengan telur, terigu, bawang putih yang sudah dihaluskan, dan garam. Aduk2 lalu bentuk bulat2.\", \"Rebus bulatan daging tadi hingga matang.\", \"Rajang bawang bombay, tumis bawang bombay, tambahkan garam, merica, masukkan daging tadi ke dalam tumisan. Tambahkan kecap manis dan saos tiram. Serta sedikit air dari rebusan tadi.\", \"Rebus hingga bumbu meresap. Koreksi rasa. Sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(481, 4, 'Beef Teriyaki AlaTane', 'Nikmati kelezatan Beef Teriyaki AlaTane dengan resep sederhana ini.', '[\"Daging Sapi\", \"Lada\", \"Saus Teriyaki\", \"Bawang Merah\", \"Bawang Putih\", \"Bawang Daun\", \"Daun Salam\", \"Secukupnya Air\", \"Minyak\", \"Kecap\", \"Garam\", \"Penyedap Rasa\"]', '[\"Rebus terlebih dahulu daging sampai empuk.\", \"Iris bawang merah, putih, bawang bombay, serta bawang daun.\", \"Setelah daging empuk, angkat dan tiriskan.\", \"Panaskan minyak.\", \"Tuang semua bahan yg diiris tadi. Setelah harum, masukan saus teriyaki, garam, air, lada putih, kecap, daun salam, secukupnya sesuai selera.\", \"Setelah itu, aduk rata. Lalu, masukan daging yg tadi sudah direbus.\", \"Aduk rata, diamkan beberapa menit hingga bumbu mengental, dan daging lebih empuk.\", \"Lalu, sajikan dan siap disantap. Yummy!!!\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(482, 3, 'Sapi lada hitam maknyusss', 'Sapi lada hitam maknyusss - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1/4 daging sapi has dalam kualitas bagus, potong kotak kecil2\", \"1 buah bawang bombay iris bagi menjadi 8 bagian\", \"2 buah cabai merah besar / paprika merah secukupnya iris kotak\", \"2 buah cabai hijau besar / paprika hijau secukupnya iris kotak\", \"1 ruas jahe iris tipis memanjang seperti korek api\", \"1 sdm minyak utk menggoreng daging\", \"Bumbu lumuran utk daging :\", \"1 sdm kecap asin\", \"1 siung bawang putih cincang\", \"1 sdt minyak wijen\", \"1 sdt lada hitam\", \"Bumbu utk menumis :\", \"1 sdm saus tiram\", \"1/2 sdt gula\", \"1/2 sdt garam\", \"1/2 sdt kaldu bubuk\", \"2 sdm kecap manis\", \"1/2 sdm tepung maizena larutkan dgn 50 ml air\", \"2 sdm minyak utk menumis\"]', '[\"Cuci bersih daging, lalu lumuri daging dgn bumbu hingga rata, diamkan minimal 30 menit didalam kulkas, lalu ambil 1 sdm minyak, goreng daging sampai matang, angkat tiriskan\", \"Ambil 2 sdm minyak tumis bawang bombay dan jahe sampai harum kecoklatan, masukkan cabai merah dan hijau aduk2, lalu masukkan daging yg sdh digoreng, masukkan saus tiram, gula, garam, kaldu bubuk, kecap manis, aduk2 rata, masukkan larutan maizena, aduk2 biarkan sampai menyusut, kalau dirasa sdh kental, angkat, sajikan. Selamat menikmati 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(483, 2, 'Nasi Goreng Buntut Sapi', 'Nasi Goreng Buntut Sapi - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"2 piring nasi putih\", \"3 potong Buntut sapi\", \"1 sdm mentega\", \"10 buah cabe rawit\", \"Secukupnya garam\", \"Secukupnya kaldu bubuk\", \"Secukupnya kecap manis\", \"Bumbu halus :\", \"4 siung bawang merah\", \"2 siung bawang putih\", \"2 buah cabe merah\"]', '[\"Siapkan semua bahan. Potong Buntut sapi sesuai selera dan pisahkan dari tulangnya. Iris cabe rawit dan sisihkan\", \"Haluskan bumbu halus, panaskan mentega lalu tumis bumbu halus hingga matang dan harum. Masukan potongan Buntut sapi dan irisan cabe rawit lalu aduk hingga rata\", \"Setelah bumbu rata, masukkan nasi dan aduk lagi hingga nasi benar-benar terpisah dan tidak ada yang membulat. Tambahkan garam dan kaldu bubuk secukupnya lalu koreksi rasa\", \"Jika rasa sudah pas, tambahkan kecap manis dan aduk lagi hingga merata dan kecap menjadi matang. (mengaduk nasi dilakukan secara cepat agar bagian bawahnya tidak gosong). Setelah itu Nasi goreng Buntut sapi siap disajikan dengan taburan bawang goreng diatasnya (bagi yang suka)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(484, 4, 'Soto Sapi Bandung', 'Resep Soto Sapi Bandung yang lezat dan mudah dibuat di rumah.', '[\"400 gram daging sapi (saya kebetulan yang bagian brisket)\", \"1 buah lobak ukurang sedang\", \"Untuk bumbu halus :\", \"5 buah bawang merah\", \"3 buah bawang putih\", \"1 sdt garam\", \"1/2 sdt gula\", \"Sedikit merica\", \"Bumbu lainnya (banyak nya bisa disesuaikan selera) :\", \"1 buah batang sereh\", \"4-5 buah daun jeruk\", \"2 ruas Jahe\", \"Secukupnya garam, gula, merica, penyedap bila perlu\", \"1,5 sdm kecap manis\", \"Bahan pelengkap soto :\", \"Nasi hangat\", \"Irisan tomat\", \"Irisan jeruk nipis/limau/lemon\", \"Irisan timun\", \"Irisan daun bawang dan seledri\", \"Irisan daun seledri (saya agak susah nyari yg mirip disini)\", \"Bawang merang goreng\", \"Sambal sederhana untuk soto :\", \"3 buah bawang merah\", \"4 buah cabe rawit/cabe merah\", \"1 buah bawang putih\", \"Sedikit garam, gula, minyak goreng, penyedap\"]', '[\"Potong daging sapi besarnya sesuai selera (saya potong kecil-kecil supaya dagingnya lebih cepat matang)\", \"Cuci daging sapi kemudian rebus (saya pakai panxi biasa) sekitar 20-30 menit (sampai kotoran dan lemaknya keluar, ciri-cirinya air menjadi sangat keruh). Kemudian buang airnya, tiriskan dulu dagingnya selagi pancinya dibersihkan pakai air sebentar supaya lemak yg masih menempel dipanci hilang). Masukan lagi dagingnya ke dalam panci dan beri lagi air secukupnya (kalau saya sekitar 2-2,5 liter air) dan lanjut masak lagi sampai daging matang dan lembut\", \"Selagi daging direbus, bersihkan kulit lobak putih kemudian iris tipis semuanya\", \"Ulek atau blender kasar bumbu halus, kemudian tumis sampai harum dan tambahkan sereh dan jahe yang sudah digeprek terlebih dahulu dan juga daun jeruk. Ikut tumis 1-2 menit dengan bumbu halus\", \"Masukan bumbu yg sudah ditumis ke dalam panci yg berisi daging, kemudian aduk dan bumbui dengan bumbu lainnya spt garam gula merica kecap manis. Ketika daging sudah empuk baru masukan irisan lobaknya dan masak sampai lobaknya matang (saya memang ingin biar lobaknya tidak terlalu obercook) sambil dikoreksi lagi rasanya\", \"Sambil menunggu lobak matang, kita bisa buat sambal untuk sotonya. Ulek semua bahan sampai agak halus.\", \"Siapkan bahan-bahan pelengkap soto spt timun, tomat, jeruk, daun bawang, bawang goreng\", \"Ambil mangkuk dan soto siap dihidangkan dengan bahan pelengkap :)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(485, 4, 'Baked macaroni beef and cheese', 'Sajian Baked macaroni beef and cheese yang praktis dan lezat untuk dinikmati bersama.', '[\"200 gram macaroni\", \"300 gr daging sapi giling\", \"100 gr udang besar\", \"300 ml saos jamur\", \"300 ml saos pasta siap pakai\", \"1 paket keju mozarella\", \"1 butir Bawang bombay\", \"Almunium foil buat cetakan\", \"Bumbu\", \"1 sdm Saos tiram\", \"sdt Garam set\", \"sdt Mrica bubuk set\", \"Minyak olive\"]', '[\"Rebus macaroni dgn sdkit garam dan minyak\", \"Selagi d rebus kita siapkan bahan\", \"Setelah macaroni matang +-15 menit angkt triskn\", \"D samping itu aku buat cetakan alumuniumfoil krna klu bli mahall😁😁\", \"Lalu kita masak semua bahan jd satu kecuali keju yaa tumisnya menggunakkan olive oil ya klu ga da skip aj\", \"Setelah matang tungkan macaroni kedalam saos yg kita masak tadi..jgn d ksh air y bun dan masukan ke dalam cetakn taburi keju\", \"Lalu panggan +-5 menit 200° angkat siap sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(486, 3, 'Oseng\" sapi cabe gendot', 'Oseng\" sapi cabe gendot dengan daging sapi empuk dan bumbu kaya rasa.', '[\"1/2 kg daging sapi\", \"10 buah cabe gendot\", \"20 buah cabe rawit merah\", \"5 buah cabe merah keriting\", \"5 siuang bawang putih\", \"5 siung bawang merah\", \"1 buah bawang bombay (yg kecil)\", \"1 ruas lengkuas\", \"2 lembar daun salam\", \"1 sendok makan saus tiram\", \"secukupnya Garam\", \"secukupnya Gula putih\", \"secukupnya Penyedap rasa\"]', '[\"Potong\\\"cabe gendot jd 4 bagian bt yg besar klo cabe\'y kecil jd 2 bagian aja.potong\\\" jg daging sapi sesuai selera bunda y\", \"Potong\\\"semua bumbu\\\" kecuali daun salam.\", \"Tumis semua bumbu yg sdh dipotong\\\"& daun salam secara bersama\\\" sampai layu & harum.\", \"Kemudian masukan daging sapi aduk rata.tambahkan air,gula putih,garam,penyedap rasa,saus tiram,aduk rata.masak hingga daging empuk\", \"Setelah daging empuk masukan cabe gendot aduk rata & tunggu sampe cabe gendot sedikit layu,koreksi rasa.\", \"Oseng\\\" siap untuk disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(487, 4, 'Semur Daging Sapi Bahan Simpel', 'Resep praktis Semur Daging Sapi Bahan Simpel yang bisa dicoba di rumah.', '[\"1/4 kg daging sapi potong potong\", \"Garam\", \"Gula\", \"1 sdm kecap asin\", \"Kecap manis sepuasnya\", \"1 buah kentang potong potong besar, cuci kemudian goreng\", \"Bumbu halus :\", \"10 siung bawang merah\", \"5 siung bawang putih\", \"1 biji pala\", \"1 sdt merica\"]', '[\"Tumis bumbu halus sampai harum\", \"Masukan daging sapi yg sudah dipotong potong dan cuci bersih aduk sampai daging berubah warna\", \"Tambahkan kecap asin, kecap manis, garam, gula dan air secukupnya. Aduk sampai rata\", \"Tutup wajan, setelah mendidih kecilkan api\", \"Masak sampai daging empuk, cicipi. Masukan kentang goreng. Masak sampai kuah menyusut dan bumbu meresap. Sajikan semur dengan taburan bawang goreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(488, 4, 'Sop kerewedan sapi simple', 'Sop kerewedan sapi simple - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1/4 kerewedan sapi\", \"1 bks bumbu sop (me : saji**)\", \"1 bks Masako sapi\", \"600 ml air\", \"Secukupnya garam dan minyak\", \"(Bahan iris)\", \"5 lembar kol\", \"3 bh wortel\", \"2 btg seledri dan daun bawang\", \"2 siung bawang merah & putih\", \"1/2 bh tomat\"]', '[\"Rebus kerewedan pake garam, cuci, ulangi sampe baunya hilang. (Saya 3 kali rebus)\", \"Potong kerewedan sesuai selera. Sisihkan\", \"Tumis bawang merah & putih. Kalo udah harum masukan air.\", \"Masukan kerewedan, wortel, kol.\", \"Tambahkan bumbu sop, Masako sapi, dan secukupnya garam. Koreksi rasa.\", \"Masukan seledri, daun bawang dan tomat. Tunggu sebentar sampe daunnya layu.\", \"Sajikan selagi hangat. Happy cooking mommy❤\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(489, 4, 'Lodeh Tempe Mix Kulit Sapi / Cecek (Bahasa Jawa)', 'Cara membuat Lodeh Tempe Mix Kulit Sapi / Cecek (Bahasa Jawa) yang enak dan praktis untuk keluarga.', '[\"2 Buah Tempe Berukuran Besar\", \"1 Bungkus Kulit Sapi\", \"20 Cabe Rawit\", \"13 Siung Bawang Merah\", \"5 Siung Bawang Putih\", \"Secukupnya Ketumbar, Kunyit, Kencur, Lengkuas, Kemiri\", \"2 Lembar Daun Jeruk\", \"1 Ikat Bawang Daun\", \"Secukupnya Garam, Gula Dan Penyedap Rasa\", \"1 Buah Santan Kemasan (Saya Pakai KARA)\"]', '[\"Cuci kulit sapinya terlebih dahulu\", \"Kemudian potong2 sesuai selera lalu sisihkan\", \"Potong2 tempe menjadi beberapa bagian (jangan terlalu kecil)\", \"Cuci semua bumbu kemudian haluskan semua bumbu dan geprek lengkuas\", \"Masukkan semua bumbu kedalam penggorengan bersama dengan daun jeruk\", \"Setelah itu masukkan tempe dan kulit sapi, aduk hingga bumbu merata dan diamkan kurang lebih 15 menit\", \"Jika sudah lunak dan bumbu meresap, masukkan daun bawang dan santan kara lalu tambahkan air secukupnya\", \"Kalau sudah mendidih tambahkan gula dan penyedap rasa\", \"Setelah dirasa pas, masakan sudah bisa untuk dihidangkan :)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(490, 2, 'Tongseng Daging Sapi', 'Resep Tongseng Daging Sapi ala rumahan yang dijamin menggugah selera.', '[\"1/2 Kg Daging Sapi\", \"1/4 Kol (Potong Sesuai Selera)\", \"1/2 Liter Santan\", \"3 Lembar Daun Jeruk\", \"2 Helai Serai\", \"2 Cm Lengkuas\", \"1 Buah Tomat (potong kecilkecil)\", \"5 Buah Cabe Rawit\", \"5 Buah Cabe Merah\", \"1 Liter Air\", \"2 Sdm Kecap Manis\", \"1 Bungkus Penyedap Rasa Sapi\", \"Bumbu Halus\", \"5 Buah Bawang Putih\", \"7 Buah Bawang Merah\", \"5 Buah Kemiri\", \"3 Cm Jahe\", \"5 Cm Kunyit (Dibakar Terlebih Dahulu)\", \"1 Sdt Lada\", \"1 Sdt Ketumbar\", \"Sedikit Garam\"]', '[\"Rebus Terlebih Dahulu daging sapi. sampai matang lalu potong kecil-kecil\", \"Di panci yg terpisah, Masak air dan santan dengan api kecil aduk-aduk\", \"Masukkan bumbu halus, Daun Jeruk, Lengkuas, Serai dan garam. aduk sampai mendidih\", \"Di wajan yg terpisah, Tumis bawang merah, cabe rawit dan cabe merah sampai harum\", \"Lalu masukkan daging yg sudah setengah matang dan di potong kecil kecil\", \"Lalu masukkan kol yg sudah di potonh2 sampai kol layu\", \"Tambahkan kan kecap\", \"Lalu masukkan olahan santan ke dalam tumisan, aduk terus sampai mendidih, agar santan tidak pecah\", \"Masukkan potongan tomat\", \"Lalu tambahkan penyedap rasa sapi, gula dan garam\", \"Cicip\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(491, 2, 'Dimsum mash potato beef cheese', 'Cara membuat Dimsum mash potato beef cheese yang enak dan praktis untuk keluarga.', '[\"3 buah kentang ukuran kecil\", \"1 sachet kornet\", \"Keju quick melt\", \"3 buah bakso sapi\", \"Seledri\", \"Daun bawang\", \"3 siung bawang putih\", \"2 siung bawang merah\", \"1 /² sdt lada\", \"1 sdt garam\", \"1 /² sdt gula pasir\", \"Kulit pangsit\", \"1 buah telur ayam\"]', '[\"Kupas kentang, cuci bersih lalu potong ukuran sedang.\", \"Didihkan air, lalu masukkan kentang. Masak hingga empuk\", \"Sambil menunggu kentang, haluskan bawang merah dan putih, lalu tumis hingga harum\", \"Iris kecil daun bawang serta seledri. Kemudian potong dadu bakso dan keju\", \"Ambil telur dan pisahkan kuningnya untuk adonan, dan putihnya untuk melumasi dimsum\", \"Setelah kentang empuk, hancurkan sampai halus. Masukkan kuning telur, kornet, daun bawang, daun seledri, dan tumisan bumbu. Uleni sampai membentuk adonan\", \"Siapkan kulit pangsit. Isi kulit dengan adonan lalu letakkan keju serta bakso di dalamnya. Bentuk sesuai selera. Untuk merekatkan kulitnya bisa diolesi dengan putih telur. Kemudian kukus sekitar 20menit. Dan siap disajikan dengan saus\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(492, 3, 'Tumis kentang daging sapi', 'Buat Tumis kentang daging sapi yang nikmat dengan langkah-langkah mudah ini.', '[\"Bumbu :\", \"1 sdm gula\", \"1 sdt garam\", \"Penyedap (optional)\", \"1 sdm kecap\", \"1 sdm saos sambal\", \"1/4 sdt merica bubuk\", \"Bahan :\", \"1/4 kg daging sapi\", \"1 buah kentang sedang\", \"3 siung bawang merah\", \"2 siung bawang putih\", \"2 lembar daun salam\", \"2 cm lengkuas\", \"1 buah tomat kecil\", \"3 buah cabe merah keriting\", \"3 buah cabe hijau keriting\", \"Segenggam cabe rawit merah campur hijau\", \"1 batang daun bawang\"]', '[\"Cuci daging lalu potong dadu.\", \"Rebus daging sampai empuk.\", \"Iris semua bahan.\", \"Potong-potong kentang.\", \"Goreng kentang sampai berwarna sedikit keemasan. Kalau tidak suka di goreng, kentang boleh di rebus. Sesuai selera saja.\", \"Tumis sampai harum semua bumbu kecuali tomat dan daun bawang. Tambahkan air kaldu secukupnya sisa dari merebus daging. Masukan daging dan kentang. Beri garam, gula, penyedap, kecap, merica bubuk dan saos sambal. Setelah air sisa sedikit lalu masukan tomat dan daun bawang. Voilaaa selesaiii 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(493, 4, 'Asam padeh gulai daging sapi', 'Resep praktis Asam padeh gulai daging sapi yang bisa dicoba di rumah.', '[\"500 gram daging sapi tanpa lemak\", \"5 buah kentang potong-potong sedang\", \"Bumbu asam padeh untuk 500 gram daging (bisa beli di pasar yg sudah jadi)\", \"1 bungkus bumbu gulai instant merk Indofood\", \"1 lembar daun kunyit\", \"Minyak untuk menumis\", \"secukupnya Air\", \"Bawang goreng\"]', '[\"Tumis bumbu halus asam padeh dengan minyak secukupnya sampai wangi, kemudian masukan bumbu gulai instant Indofood. Aduk-aduk hingga wangi.\", \"Masukan daging, aduk hingga rata dengan bumbu\", \"Masukkan daun kunyit, aduk-aduk.\", \"Masukkan air kemudian aduk dan tunggu hingga daging mulai empuk. Masak dengan api kecil.\", \"Setelah daging empuk, dan air mulai mengental masukan potongan kentang. Masak hingga matang. Koreksi rasa dan sajikan dengan taburan bawang goreng.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(494, 3, 'Tumis buncis bakso sapi', 'Nikmati kelezatan Tumis buncis bakso sapi dengan resep sederhana ini.', '[\"250 gr buncis muda, bersihkan, cuci. potong-potong\", \"5 buah bakso sapi, potong-potong\", \"3 buah cabe merah keriting, cuci, potong serong\", \"4 siung bawang merah, iris tipis\", \"3 siung bawang putih, iris tipis\", \"1 ruas lengkuas, cuci lalu geprek\", \"1 lembar daun salam\", \"secukupnya Garam\", \"secukupnya Gula pasir\"]', '[\"Panaskan wajan, tuang minyak sayur sedikit. Tumis irisan bawang merah, bawang putih, cabe merah kriting, lengkuas, daun salam. Aduk-aduk sampai wangi.\", \"Tuang potongan buncis dan bakso sapi, aduk-aduk sebentar. Tambahkan garam dan gula pasir secukupnya. Aduk kembali.\", \"Tambahkan sedikit air matang, aduk-aduk. Diamkan sebentar agar bumbu meresap.\", \"Setelah air agak mengering angkat, sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(495, 4, 'Sambal Goreng Hati Sapi', 'Sambal Goreng Hati Sapi - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"300 gr hati sapi segar\", \"5 buah cabai merah besar\", \"3 buah cabai merah keriting\", \"3 sdm minyak goreng\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"2 butir kemiri\", \"1 lembar daun salam remas sedikit\", \"2 lembar daun jeruk remas sedikit\", \"1 batang serai geprek\", \"2 cm lengkuas geprek\", \"2 sdm santan kental instan\", \"secukupnya gula pasir, garam, lada bubuk, kaldu bubuk, ketumbar\", \"1500 ml air\"]', '[\"Cuci bersih hati sapi potong beberapa bagian lalu rebus dalam panci sampai matang kurang lebih 15 menit\", \"Angkat, potong dadu 1cm lalu sisihkan\", \"Blender : cabai, minta goreng, kemiri, bawang merah dan bawang putih\", \"Tumis bumbu halus tersebut hingga harum dan berubah warna sedikit memerah, masukan daun salam, daun jeruk, lengkuas, serai\", \"Masukan hati sapi\", \"Masak sampai keluar minyak lebih banyak\", \"Masukan gula, garam, ketumbar, kalo bubuk, lada, santan dan sedikit air\", \"Masak kembali sampai air susut, hati sapi terlihat empuk dan bumbu meresap sempurna kurang lebih selama 5 menit\", \"Angkat dan sajikan\", \"Bisa sebagai masakan pendamping opor, tambahkan petai bila suka\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(496, 2, 'Asem-Asem Iga Sapi #ketopad', 'Sajian Asem-Asem Iga Sapi #ketopad yang praktis dan lezat untuk dinikmati bersama.', '[\"1/2 kg iga sapi\", \"1.5 lt air\", \"2 Lembar daun salam\", \"2 lembar daun jeruk\", \"3 sdm kecap tropicanaslim\", \"Secukupnya himsalt\", \"Secukupnya penyedap\", \"1 batang serai geprek\", \"3 sdm air asem jawa\", \"Bumbu lainnya :\", \"15 bh cabe hijau(patah2 kan)\", \"5 bh cabe merah besar(patah2kan)\", \"7 bh cabe rawit merah dan hijau\", \"6 bh belimbing wuluh(potong jadi 3 bagian)\", \"1 bh tomat hijau besar(potong jadi 8 bagian)\", \"Bumbu ulek :\", \"3 siung bawang putih\", \"6 siung bawang merah\"]', '[\"Presto iga sapi sekitar 15-20 mnt.. matikan api..\", \"Setelah itu buka tutup prestonya.. nyalakan api.. masukkan daun salam,daun jeruk dan serai\", \"Tumis bumbu ulek sampai harum\", \"Masukkan tumisan bumbu ke dalam rebusan iga lalu aduk rata\", \"Bumbui dengan kecap tropicanaslim,himsalt,dan penyedap lalu aduk rata..\", \"Tambahkan potongan tomat, belimbing wuluh dan air asem jawa..koreksi rasa..\", \"Terakhir masukkan cabe hijau,cabe merah dan duo rawit.. masak sebentar sajah\", \"Matikan kompor\", \"Siap di santap selagi panas\", \"Selamat mencoba🙏🙏\", \"📝untuk fase induksi skip tomat dan belimbing wuluhnya ya\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(497, 2, 'Beef Black Pepper Cepat Gampang', 'Buat Beef Black Pepper Cepat Gampang yang nikmat dengan langkah-langkah mudah ini.', '[\"150 gram daging sapi\", \"3 bawang putih\", \"1/2 bawang bombay ukuran sedang\", \"2 cabe hijau besar\", \"2 cabe merah kecil\", \"1/2 sachet saus lada hitam (saori)\", \"Gula\", \"Garam\", \"secukupnya Air\", \"1 sdt minyak wijen\"]', '[\"Iris tipis daging, rendam dengan saus lada hitam (saori), kurang lebih 6 jam, simpan di kulkas.\", \"Cincang bawang putih dan iris kasar bawang bombay. Bagi dua cabe hijau besar dan buang isinya, potong sesuai selera.\", \"Panaskan minyak wijen, tumis bawang putih hingga harum, lalu masukkan bawang bombay tunggu sedikit layu. Kemudian masukkan rendaman daging, tumis hingga berubah warna, tambahkan air sedikit demi sedikit.\", \"Tambahkan gula dan garam sesuai selera, koreksi rasa dan kematangam daging.\", \"Sajikan. Selamat mencoba. Oya, karena makan malam saya nggak makan sama nasi, saya ganti dengan kentang goreng dan wortel rebus. 💕\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(498, 3, 'Paru sapi rica rica', 'Resep Paru sapi rica rica ala rumahan yang dijamin menggugah selera.', '[\"1/2 kg paru sapi\", \"Bumbu geprek:\", \"1 btg serai\", \"2 lbr daun salam\", \"2 lbr daun jeruk\", \"Bumbu halus :\", \"6 bawang merah\", \"2 bawang putih\", \"1 ruas kunyit\", \"2 ruas jahe\", \"1 sdt ketumbar\", \"1 buah tomat\", \"5 cabai keriting\", \"10 cabai rawit merah\", \"1/2 sdt mrica\", \"secukupnya Garam n gula\", \"Pelengkap :\", \"Kemangi\"]', '[\"Cuci bersih paru, rebus sebentar tiriskan dan potong2\", \"Tumis bumbu halus, masukkan bumbu geprek n tambahkan sedikit air masak hingga mendidih\", \"Kemudian masukkan paru tambahkan garam n gula masak hingga matang\", \"Tambahkan kemangi, koreksi rasa. N matikan api\", \"Paru sapi rica2 siap di hidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(499, 3, 'Asem-asem tetelan sapi', 'Buat Asem-asem tetelan sapi yang nikmat dengan langkah-langkah mudah ini.', '[\"250 gram tetelan sapi\", \"1 1/2 kantong plastik buncis (saya beli per kantong Rp 3000,-)\", \"2 cm lengkuas\", \"2 lbr daun salam\", \"2 buah tomat merah potong2\", \"8 butir bawang merah iris tipis\", \"3 siung bawang putih iris tipis\", \"10 buah cabe rawit utuh\", \"2 sdm kecap manis\", \"1 1/2 butir gula merah\", \"2 sdm asam jawa larutkan dng 1 gelas air\", \"Secukupnya garam\", \"Secukupnya air\", \"1 bungkus royco sapi\"]', '[\"Cuci buncis lalu potong tipis2 serong\", \"Cuci bersih tetelan kemudian potong kecil2\", \"Rebus tetelan dengan api kecil (airnya kira2 1/2 panci)\", \"Setelah tetelan matang matikan kompor. Kemudian mskkan buncis & tambahkan air. Masak kembali.\", \"Masukkan daun salam, lengkuas, tomat, bawang merah & putih, garam, kecap manis, gula jawa & cabe rawit utuh.\", \"Aduk2 sampe gula larut & kemudian masukkan air asam jawa. Terakhir tambahkan royco. Tes rasa jika rasa s dh pas matikan kompor. Dan asem2pun siap dinikmati.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(500, 2, 'Soto Seger Daging Sapi', 'Nikmati kelezatan Soto Seger Daging Sapi dengan resep sederhana ini.', '[\"400 gr daging sapi\", \"2 liter air\", \"2 lembar daun salam\", \"4 lembar daun jeruk\", \"1 batang serai,geprek\", \"1 ruas jari lengkuas, geprek\", \"1 sdm gula pasir\", \"1 batang daun bawang\", \"1 1/2 sdm garam\", \"1 sdm kaldu sapi bubuk/kaldu jamur juga bisa\", \"1/2 buah tomat,potong-potong\", \"1 sdm minyak untuk menumis bumbu\", \"bumbu halus\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"1 sdt lada bubuk\", \"1 sdt ketumbar bubuk\", \"1 cm jahe(sekitar 1/2 ruas jari ya)\", \"3 buah kemiri,sangrai\", \"Bahan Pelengkap :\", \"2 sdm daun seledri\", \"1 buah jeruk nipis\", \"secukupnya bawang goreng untuk taburan\"]', '[\"Didihkan air, masukan daging. rebus sampai empuk. angkat, potong-potong. Nah kalau mau lebih cepat bisa dagingnya di masak dengan presto. Ambil air kaldunya sekitar 1500 ml. Sisihkan. (Simpan kaldu di panci lain,bukan panci bekas merebus tadi ya)\", \"Haluskan bumbu, kemudian panaskan minyak di wajan/teflon dan tumis bumbu halus dengan daun salam,daun jeruk,lengkuas, kemiri dan serai sampai harum dan agak kering\", \"Tuang bumbu yang sudah ditumis kedalam kuah kaldu, masak hingga mendidih, tambahkan gula,garam,kaldu bubuk,irisan tomat dan daun bawang\", \"Sebelum disajikan saring kuah sotonya tadi,agar bumbu yang kurang halus tidak ikut termakan. Soalnya biasanya pasti gk enak banget lagi asik makan eh ada bumbu yang kasar gitu,atau malah asik makan eh jadi sibuk ngebuang bumbu sisa geprekan(lengkuas,serai,dan daun-daunan itu) dari piring...\", \"Penyajian : Tata nasi di mangkok, beri irisan daging dan tauge siram dengan kuah soto, taburi dengan daun seledri dan daun bawang\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(501, 2, 'Roti kasur isi daging sapi', 'Hidangan daging sapi istimewa: Roti kasur isi daging sapi.', '[\"500 gram tepung terigu cakra\", \"50 gram tepung maizena\", \"1 sachet ragi instan\", \"1 sachet susu bubuk\", \"120 ml susu cair\", \"4 sdm gula pasir\", \"3 sdm butter cair\", \"1 butir telur\", \"Bahan olesan :\", \"2 sdm susu cair\", \"1 sdm butter cair\", \"Bahan isian:\", \"100 gram daging sapi cincang\", \"1 buah wortel potong dadu kecil\", \"1 buah bawang bombai iris tipis\", \"2 siung bawang putih cincang\", \"1/2 sdt garam\", \"1 sdt gula\", \"1 sdm saos tiram\", \"3 sdm kecap manis\", \"Secukupnya minyak\", \"Secukupnya wijen buat taburan\"]', '[\"Cairkan ragi instan bersama susu cair tunggu 10 menit hingga berbuih2, tambahkan gula pasir aduk hingga larut\", \"Campurkan tepung terigu dan tepung maizena tambahkan susu bubuk masukan cairan ragi aduk rata\", \"Mulai ulenin adonan tambahkan telur lalu butter cair setelah Kalis, tutup adonan tunggu 30 menit hingga mengembang\", \"Selama menunggu buat bahan isian : tumis bawang putih & bombai lalu masukan daging giling & wortel masak hingga daging berubah warna masukan bumbu garam, gula, lada, kecap manis, saos tiram & bumbu penyedap, masak hingga matang angkat dan sisihkan\", \"Setelah adonan mengembang dibagi menjadi bulatan2 kecil ditimbang 35gr\", \"Isi adonan bulatkan kembali susun dalam loyang, olesi dengan susu cair beri taburan wijen lalu tunggu mengembang kembali selama 30 menit\", \"Panaskan oven 180 derajat masukan adonan roti panggang selama 30 menit\", \"Keluarkan roti lalu oles dengan butter lalu panggang kembali selama 15menit setelah matang angkat & dinginkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(502, 2, '🍲Dimsum/Siomay Daging Sapi🍲', 'Resep 🍲Dimsum/Siomay Daging Sapi🍲 ala rumahan yang dijamin menggugah selera.', '[\"Secukupnya Kulit Pangsit Siap Pakai\", \"350 Gram Daging Sapi Cincang\", \"2 Batang Daun Bawang, iris halus\", \"5 Sdm Tepung Tapioka / Sagu\", \"1 Sdm Tepung Terigu\", \"1 Siung Bawang Putih, haluskan\", \"1 Sdm Kecap Asin\", \"1 Sdm Minyak Wijen\", \"1 Butir Telur\", \"1/2 Sdt Lada Putih Bubuk\", \"Secukupnya Garam\", \"1 Sdt Gula Pasir\", \"Bahan Saus Sambal Dimsum :\", \"50 Ml Air Matang\", \"2 Sdm Saus Sambal\", \"3 Sdm Saus Tomat\", \"2 Sdm Gula Pasir\", \"Secukupnya Cuka\"]', '[\"Taruh daging cincang dalam mangkuk/baskom. Beri bumbu2 : bawang putih halus, saus tiram, kecap asin, minyak wijen, lada putih bubuk, gula pasir dan telur. Tambahkan daun bawang dan wortel parut, tapi sisakan sedikit wortel parutnya ya utk taburan bagian atas dimsum. Aduk rata. Masukkan tepung tapioka dan terigunya, aduk rata lagi. Tes rasa asinnya. Bila kurang asin, baru tambahkan garam. Aduk rata.\", \"Ambil selembar kulit pangsit. Basahi jari kita dgn air lalu usapkan ke permukaan kulit pangsit agar kulit pangsit lebih elastis saat dibentuk (langkah ini boleh di skip)\", \"Taruh kira2 sesendok makan adonan isi dimsum di bagian tengah kulit pangsit. Lalu kita bentuk dimsumnya dgn cara pertemukan keempat ujung kulit pangsit dan rekatkan keempat sisinya sambil kmd keempat ujungnya dilipat ke arah luar (atau bs juga digunting ujung2nya spy rapi). Hiasi bagian atas dimsum dgn sedikit wortel parut. Ulangi langkah ini sampai adonan dimsum habis.\", \"Didihkan air dalam panci pengukus dgn api sedang. Kukus dimsum +/- 25 menit atau hingga matang. Angkat tiriskan dan taruh di piring saji.\", \"Taruh semua bahan saus sambal dimsum dlm mangkuk saus sambal. Aduk rata dan tes rasa. Siap disajikan.\", \"Selamat menikmati dimsum/siomay dgn saus sambalnya 🍲☕🍵😍👍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(503, 4, 'Mun Tahu Daging Sapi', 'Resep Mun Tahu Daging Sapi ala rumahan yang dijamin menggugah selera.', '[\"250 gr Daging Sapi cincang\", \"2 buah tahu sutera\", \"3 siung bawang putih, cincang halus\", \"2 batang daun bawang, potong2\", \"4 cm jahe, geprek\", \"3 sdm minyak wijen\", \"1 sdm saos tiram\", \"1 sdm kecap manis\", \"1 sdt kecap maggi\", \"1 sdt saos raja rasa\", \"1 sdt garam\", \"Secukupnya gula, merica/lada\", \"Secukupnya kaldu jamur/maggi blok\", \"2 sdm maizena (di larutkan dengan air)\", \"Secukupnya air\"]', '[\"Panaskan minyak wijen lalu tumis bawang putih yg telah di cincang halus dan jahe yg telah di geprek sampai harum\", \"Masukan daging cincang, aduk sebentar sampai agak berubah warna. Lalu tambahkan air sedikit (kurang lebih 100-200cc)\", \"Masukan tahu sutera yg telah di cincang dan daun bawang yg sudah dipotong2.\", \"Masukan saos tiram, kecap manis, kecap maggi, saos raja rasa, garam, gula, merica/lada, kaldu jamur. Lalu aduk. Tambahkan larutan maizena, aduk sampai matang dan mengental.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(504, 2, 'Sate Daging Sapi Rempah', 'Cara membuat Sate Daging Sapi Rempah yang enak dan praktis untuk keluarga.', '[\"250 gr daging sapi impor yg sedikit lemak,potong dadu\", \"2 sdm margarin palmia garlic\", \"Bumbu halus\", \"3 siung bawang merah\", \"2 siung bawang putih\", \"3 butir kemiri,sangrai\", \"1 1/2 sdt ketumbar,sangrai\", \"1/4 sdt jinten\", \"1 ruas jari lengkuas\", \"1 batang serai, ambil bagian putihnya,potong-potong\", \"1 ruas jari jahe\", \"1 ruas jari kunyit\", \"bumbu pelengkap :\", \"1/2 sdt merica bubuk\", \"2 sdm air asam jawa\", \"3 sdm kecap manis\", \"1 sdm gula jawa\", \"1 sdt kaldu bubuk\"]', '[\"Siapkan semua bahan. campurkan bumbu halus dengan bumbu pelengkap dalam 1 tempat(mangkok),aduk rata\", \"Rendam potongan daging sapi kedalam bumbu halus yang telah dicampur bumbu pelengkap selama kurang lebih 1-3 jam. Perendaman ini sangat penting ya untuk membuat bumbu meresap kedalam serat-serat daging.\", \"Setelah itu, tusuk potongan daging dengan menggunakan tusukan sate dan bakar diatas bara api atau grill pan. karena saya kurang jago menyalakan bara api jadi rata-rata saya memasakan dengan grill pan hehehe... oleskan permukaan grill pan dengan margarin.\", \"Sesekali oleskan sisa bumbu tunggu beberapa saat lalu oleskan juga margarin pada sate,panggang hingga daging berubah warnanya menjadi kecoklatan dan kering. angkat dan hidangkan.\", \"Sate ini bisa dihidangkan dengan bumbu kacang atau sambal kecap atau pakai acar. saya sukanya makan pakai acar jadi ada rasa asem segernya.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(505, 3, 'Lodehan Daging sapi', 'Cara membuat Lodehan Daging sapi yang enak dan praktis untuk keluarga.', '[\"200 gr Daging sapi, potong kotak\", \"2 wortel,iris serong\", \"10 buah buncis,iris serong\", \"5 Tahu pong,potong 2 bagian\", \"1 batang daun bawang\", \"200 ml santan dri kelapa parut\", \"1 cm lengkuas, geprek\", \"2 daun salam\", \"5 Cabe rawit merah utuh\", \"Bumbu Halus ;\", \"4 bawang merah\", \"3 bawang putih\", \"1 kemiri\", \"1 cm kunyit\"]', '[\"Persiapan bahan\", \"Haluskan bumbu\", \"Rebus daging sapi sampai empuk, sisihkan\", \"-tumis bumbu halus,daun salam dan lengkuas, beri sedikit air rebusan daging spya tdk kering\", \"Masukan daging, wortel, buncis, biarkan sampai masak\", \"Lalu masukan tahu dan cabe utuhan, beri air rebusan daging lagi spya, matang dan bumbu meresap\", \"Terakhir masukan santan dan daun bawang, aduk trus pelan2 spya santan tdk pecah\", \"-matikan kompor setelah agak menyusut kuahnya\", \"Selamat mencoba😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(506, 4, 'Bihun goreng + bakso sapi', 'Bihun goreng + bakso sapi dengan daging sapi empuk dan bumbu kaya rasa.', '[\"2 bihun\", \"bakso\", \"4 siung bawang putih\", \"3 siung bawang merah\", \"cabai merah (selera)\", \"kecap\", \"ladaku\", \"1 sdt garam\", \"1 sdt gula pasir\", \"1/2 bungkus royco sapi\", \"daun bawang\"]', '[\"Ulek bumbu bawang merah dan bawang putih hingga lembut\", \"Siapkan wadah untuk melembekan bihunnya, dan rebus air lalu tuang ke bihun\", \"Tumis bumbu hingga harum, masukan cabai merah, daun bawang, dan bakso tumis sebentar\", \"Masukan bihun yg sudah di siram air tadi, lalu oseng sbntr.\", \"Tambahan kecap, garam, gula pasir, dan royco\", \"Aduk sebentar lalu icip rasanya\", \"Kalau sudah pas siapkan wadah untuk di sajikan 😊\", \"Happy cooking bundaa 😄\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(507, 4, 'Broccoli cah daging sapi cincang', 'Resep praktis Broccoli cah daging sapi cincang yang bisa dicoba di rumah.', '[\"1 kuntum broccoli (besar)\", \"100 gram daging sapi cincang\", \"1 buah bawang bombai\", \"2 siung bawang putih\", \"2 buah cabe paprika hijau/ kuning\", \"1 ruas jahe\", \"1 sdm saos tiram\", \"1 sdt garam\", \"1 sdt gula\", \"1 sdm minyak wijen\", \"Secukupnya minyak\", \"Sedikit air\"]', '[\"Broccoli cuci & siangi, bawang bombai & paprika iris2, bawang putih cincang halus, jahe digeprek\", \"Panaskan minyak tumis bawang putih & bombai lalu masukan daging giling & jahe setelah matang masukan paprika & broccoli nya\", \"Beri bumbu garam, gula, saos tiram, minyak wijen & beri air tunggu hingga mendidih & matang\", \"Koreksi rasanya jika sudah pas angkat dan siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(508, 4, 'Balado kulit sapi pedasss', 'Resep Balado kulit sapi pedasss ala rumahan yang dijamin menggugah selera.', '[\"1/4 kg kulit sapi\", \"3 buah cabe tanjung besar\", \"4 siung bawang putih\", \"3 siung bawang merah\", \"1/2 sdm garam\", \"1/4 potong Gula merah\", \"7 buah cabe gendot\", \"1 buah tomat\", \"Secukupnya air\"]', '[\"Cuci bersih kulit sapi, potong2 kecil, rebus sebentar, sisihkan.\", \"Haluskan bumbu2 kecuali tomat dan cabe gendot.\", \"Tumis hingga harum beri sedikit air. Masukkan kulit nya aduk2 ungkep. Tambahkan tomat dan cabe aduk rata ungkep lg tunggu meresap. Tes rasa.\", \"Masakan ini sy lebih suka pedas manis gt. Selera msg2 ya.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(509, 4, 'Beef Teriyaki 🐮', 'Resep Beef Teriyaki 🐮 yang lezat dan mudah dibuat di rumah.', '[\"250 gr daging sapi\", \"4 siung bawang putih\", \"1 sdm saori saus teriyaki\", \"1 sdm margarine\", \"Minyak goreng\", \"1 sdm kecap manis\", \"1/2 sdm saori saus tiram\", \"1/2 sdt lada bubuk\", \"Secukupnya gula pasir\", \"Penyedap rasa\", \"1/2 siung bawang bombay\", \"1 buah cabe merah besar\", \"Air\"]', '[\"Cuci bersih daging, iris tipis2. Haluskan bawang putih, marinasi daging dengan bawang putih dan saus teriyaki diamkan dlm kulkas slama 1 jam agar meresap. Potong2 bawang bombay dan cabe merah\", \"Panaskan minyak dan margarine masukan daging smpai kluar airnya lalu msukan kecap, saus tiram,lada bubuk,sedikit gula dan penyedap rasa tambahkan 3/4 gelas air biarkan mendidih sampai sisa sdkit air.\", \"Masukan potongan bawang bombay dan cabe aduk rata lalu koreksi rasa dan daging jika kurang empuk bsa tmbah air kmbali diamkan smpai air mengental, dan siap disajikan.👌\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(510, 4, 'Daging sapi teriyaki', 'Resep praktis Daging sapi teriyaki yang bisa dicoba di rumah.', '[\"1/4 kg daging sapi\", \"Bumbu\", \"3 siung bawang putih\", \"3 siung bawang merah (pengganti bawang bombay)\", \"secukupnya Garam\", \"Bumbu lainnya\", \"Saus teriyaki\", \"Saus tiram\", \"Penyedap rasa\", \"Irisan daun bawang\", \"Irisan tomat\", \"secukupnya Lada bubuk\"]', '[\"Daging sapi yang sudah terlebih dahulu direbus kemudian campur dengan saus teriyaki dn lada putih bubuk secukupnya. Diamkan selama 30 menit agar meresap ke dalam daging.\", \"Cincang bawang putih, lalu tumis bersama bawang merah dan garam secukupnya sampai harum.\", \"Setelah tumisan bumbu sudah harum, masukkan daging sapi yang telah diungkep dengan lada bubuk dan saus teriyaki. Tambahkan sedikit air.\", \"Tambahkan sedikit saus tiram kedalam masakan. Cicip rasa.\", \"Setelah rasa sudah sesuai selera, sajikan dalam tempat sajian serta tabur irisan tomat dan daun bawang. Hidangan siap di nikmati..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(511, 3, 'Beef Enoki Teriyaki', 'Beef Enoki Teriyaki - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"250 gr daging sapi lembaran tipis\", \"1 bungkus jamur enoki\", \"1 bungkus bumbu teriyaki pronas\", \"1 sdt minyak wijen\", \"1 sdt mentega\"]', '[\"Potong batang jamur enoki, ambil beberapa batang dan gulung dengan lembaran daging, tusuk dengan tusuk gigi atau tusuk sate. lakukan hingga habis.\", \"Balur daging dengan minyak wijen (jgn terlalu banyak, karena bau minyak wijen sangat kuat).\", \"Tuang bumbu teriyaki dalam wadah tertutup, masukkan daging, dan rendam daging dalam bumbu selama beberapa jam agar meresap.\", \"Siapkan teflon atau pemanggang, oles dengan sedikit mentega. panggang daging sambil dioleskan dengan sisa saus teriyaki rendaman daging sebelumnya. balik daging sampai matang di dua sisinya.\", \"Sajikan selagi hangat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(512, 3, 'Daging Sapi Rica Rica (resep asli turun temurun)', 'Buat Daging Sapi Rica Rica (resep asli turun temurun) yang nikmat dengan langkah-langkah mudah ini.', '[\"600 gr daging sapi (sy pake has dalam)\", \"2 batang sereh\", \"6 lembar daun jeruk\", \"2 buah tomat (uk besar)\", \"2 buah kentang, goreng 3/4 matang. (boleh pake atau gak)\", \"Bahan yg dihaluskan :\", \"15 butir bawang merah\", \"2 buah cabe merah besar\", \"20 buah cabe rawit\", \"3 butir kemiri\", \"2 jempol jahe\", \"1 jempol kunyit\", \"secukupnya Garam, gula, lada\"]', '[\"Siapkan bahan, tomat potong2 kecil, sereh geprek, nah klo sy biasa untuk mempersingkat waktu, jahe,kunyit dan kemiri sy ulek halus, trus bawang merah, cabe merah dan rawit sy blender kasar.\", \"Sambil mempersiapkan bumbu, daging sapinya direbus dulu sampai setengah empuk, atau bisa di presto kurleb 10 menit aja, setelah itu daging bisa dipotong2 sesuai selera, air rebusan daging dipake buat tumisan nanti ya.\", \"Tumis semua bumbu (kecuali tomat), masak sampai harum.\", \"Masukkan tomat, tumis lagi hingga bumbu setengah matang dan tomat layu.\", \"Masukkan daging sapi, aduk-aduk hingga bumbu tercampur, lalu tambahkan garam, gula, lada.\", \"Masukkan air rebusan daging sapi secukupnya, aduk lalu masak hingga bumbu dan air meresap.\", \"Terakhir masukkan kentang, aduk rata, koreksi rasa jika kurang bisa ditambahkan garam, gula, dll, aduk2 sebentar.\", \"Sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(513, 3, 'Soto daging sapi#masakan rumahan', 'Buat Soto daging sapi#masakan rumahan yang nikmat dengan langkah-langkah mudah ini.', '[\"500 grm daging sapi\", \"1 sdm tumbar\", \"1 sdm lada\", \"3 batang Sereh\", \"8 buah bawang merah\", \"4 siung bawang putih\", \"7 buah kemiri\", \"4 helai daun jeruk purut\", \"Kunyit,jahe,kencur secukup nya\", \"2 sdm bawang goreng untuk taburan\", \"2 sdm minyak goreng\", \"Garam + bumbu kaldu secukup nya\", \"1,1 /2 liter air\"]', '[\"Siapkan bahan nya,halus kan bumbu” nya kecuali Sereh dan daun jeruk,Sereh d geprek\", \"Tumis bumbu halus,sereh dan daun jeruk,tumis hingga harum,kemudian masukan daging sapi,tumis hingga daging berubah warna nya,lalu masukan air,masak hingga daging lunak, dan bumbui dengan garam dan bumbu kaldu,jika sudah matang,koreksi rasa,matikan api angkat dan tuang soto kedalam mangkok saji,taburi dengan bawang goreng\", \"Sajikan dengan toping sesuai selera\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(514, 3, 'Rawon Daging Sapi khas Jawa Timur', 'Resep Rawon Daging Sapi khas Jawa Timur ala rumahan yang dijamin menggugah selera.', '[\"500 gr daging sapi yg ada lemaknya (tetelan 250 daging 250)\", \"Bumbu Halus:\", \"4 buah kluwek pecahkan ambil bagian dalamnya\", \"10 bawang merah\", \"2 bawang putih\", \"3 kemiri\", \"Seruas jahe\", \"Seruas kunyit\", \"1 sdt ketumbar\", \"1 sdt lada\", \"1/2 sdt jinten\", \"Bumbu pelengkap:\", \"2 lembar daunsalam\", \"2 lembar daun jeruk\", \"2 batang serai\", \"Seruas lengkuas\", \"Kayumanis\", \"2 buah kapulaga\", \"10 buah cabai rawit utuh\", \"Gula\", \"Garam\", \"Bahan pelengkap:\", \"Kecambah\", \"Bawang goreng\", \"Kerupuk\"]', '[\"Sangrai ketumbar jinten duo bawang jahe kunyit.\", \"Lalu haluskan bersamaan dgn kluwek.\", \"Lalu tumis dgn sereh lengkuas salam daun jeruk kayumanis kapulaga.\", \"Setelah harum tambahkan air sedikit masukan daging aduk2 lalu tambahkan air\", \"Rebus daging sampai empuk.\", \"Lalu masukan cabai rawit utuh dan taburan bawang goreng.\", \"Sajikan dimangkuk dengan kecambah dan kerupuk. Hmmm yummyyy... selamat mencoba..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(515, 2, 'Beef lasagna kukus', 'Resep Beef lasagna kukus yang lezat dan mudah dibuat di rumah.', '[\"4 lembar lasagna sheet, me : sanremo\", \"1 sdt minyak goreng\", \"1/2 sdt garam\", \"Keju cheddar parut\", \"Keju kraft quick melt parut\", \"Oregano\", \"sheet Air untuk merebus lasagna\", \"Cup aluminium foil\", \"Bahan saos keju 👇\", \"500 ml susu full cream UHT, me : ultra milk\", \"2 sdm tepung terigu\", \"2 sdm butter / margarine\", \"2 sdm keju cheedar\", \"1 sdm keju quick melt, me : kraft\", \"2 sdm keju oles, me : procis\", \"1/2 sdt pala bubuk\", \"Oregano (optional)\", \"Bahan saos daging 👇\", \"100 gr daging sapi giling\", \"2 buah bawang bombay ukuran kecil\", \"1 bungkus saos instan lafonte bolognise\", \"1/2 sdt pala bubuk\", \"1/2 sdt merica bubuk\"]', '[\"Rebus lasagna dengan ditambah minyak dan garam, sampai aldente\", \"Buat saos keju nya : lelehkan butter atau margarine, masukkan tepuing terigu aduk cepat sampai larut, tuang susu, aduk jangan sampai menggumpal, tambahkan perkejuan nya, tambahkan merica dan pala bubuk, aduk sampai mengental, masukkan oregano aduk2 sebentar, matikan api, sisihkan.\", \"Buat saos daging : tumis bawang bombay sampai layu, masukkan daging sapi giling aduk sampai berubah warna, masukkan saos instan, tambahkan merica dan pala bubuk, jika sudah meletup2 test rasa dan matikan\", \"Panaskan dandang\", \"Olesi cup aluminium foil dengan mentega, susun dengan urutan lasagna sheet - saos keju - saos daging, diulang sampai lasagna sheet ke empat dan terakhir setelah saos daging taburi keju cheedar parut lalu taburi keju kraft quick melt, taburi oregano.\", \"Kukus sampai keju meleleh, amgkat, sajikan dengan saos sambal.\", \"Enak banget\", \"Selamat mencoba dan selamat ketagihan ya...hihihi\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(516, 2, 'Sup Brenebron Daging Sapi Endesss', 'Buat Sup Brenebron Daging Sapi Endesss yang nikmat dengan langkah-langkah mudah ini.', '[\"250 gram daging sapi, potong dadu dan cuci bersih\", \"150 gram kacang merah aka kacang brenebron, rendam 3 jam\", \"2 buah kentang, kupas lalu potong dan cuci bersih\", \"3 batang wortel, kupas lalu potong dan cuci bersih\", \"1 buah tomat, cuci dan potong potong\", \"2 batang seledri\", \"2 batang daun bawang\", \"secukupnya bawang goreng\", \"secukupnya air\", \"1 sdm minyak sayur\", \"bumbu di haluskan :\", \"4 siung bawang putih\", \"1 sdt pala bubuk\", \"1 sdt merica\", \"secukupnya garam\", \"secukupnya gula pasir\"]', '[\"Tumis bumbu hingga harum, masukkan ke dalam panci dan beri air. masukkan daging sapi. rebus hingga setengah empuk. lalu masukkan kacang merah, wortel dan kentang. biarkan hingga empuk. koreksi rasa. masukkan tomat,daun bawang dan seledri.\", \"Jika sudah enak angkat. beri bawang merah goreng. sajikan selagi hangat. you wanna try !\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(517, 4, 'Pepes tahu tetelan sapi', 'Buat Pepes tahu tetelan sapi yang nikmat dengan langkah-langkah mudah ini.', '[\"20 buah tahu putih ukuran keciL\", \"500 gr tetelan sapi\", \"1 cabe merah\", \"6 cabe rawit biarkan utuh\", \"1 buah bawang bombay\", \"1 batang daun bawang\", \"3 sihung bawang merah\", \"2 sihung bawang putih\", \"1 bks kara santan\", \"5 helai daun salam\", \"Merica bubuk\", \"Gula pasit\", \"Penyedap\", \"Garam\", \"Daun pisang\", \"Tusuk gigi\"]', '[\"Iris semua bawang Dan cabe merah kecuali cabai rawit campur menjadi satu semua bahan ke tahu yang telah di hancurkan\", \"Potong2 dadu kecil tetelan sapi lalu tambahkan ke adonan tahu tadi\", \"Panaskan kukusan smapai panaS\", \"Ambil adonan tahu sesuai Selera lalu bungkus dg daun pisang lalu semat dg tusuk gigi\", \"Masukkan ke dlm kukusan yg telah di panaskan. Sampai matang\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(518, 2, 'Pindang tulang sapi', 'Buat Pindang tulang sapi yang nikmat dengan langkah-langkah mudah ini.', '[\"500 gr tulang sapi\", \"2 lmbr daun salam\", \"1 btng serai\", \"2 cm Laos (di geprek)\", \"1 bh tomat (potong 4) / air asam jawa 1 sdm\", \"Royco sapi / garam\", \"Bumbu halus :\", \"3 siung bawang putih\", \"7 siung bawang merah\", \"1 cm jahe\", \"1 cm kunyit bakar\", \"10 bh cabe rawit merah\"]', '[\"Rebus tulang sapi (sy pakai presto) sampai air berkurang 1/2 + laos\", \"Tumis bumbu halus + daun salam + serai\", \"Masukan tumisan kedalam air rebusan tulang, masukan irisan tomat (bisa di ganti air asam jawa) + Royco sapi\", \"Hidangkan selagi hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(519, 3, 'Beef yakiniku 3 bahan [ balita suka ]', 'Buat Beef yakiniku 3 bahan [ balita suka ] yang nikmat dengan langkah-langkah mudah ini.', '[\"100 gr daging has dalam (tenderloin)\", \"20 gr bombay iris dadu tipis\", \"50 gr bombay iris memanjang\", \"1 siung bawang putih\", \"1 sdm kecap kikkoman\", \"1/2 sdm gula semut (organic coconut sugar)\", \"1 sdm olive oil (unt menumis)\", \"100 cc air\"]', '[\"Iris tipis daging/ iris sesuai selera. sisihkan. iris dadu dan iris memanjang bombay serta geprak bawang putih, sisihkan.\", \"Panaskan olive oil, tumis bawang putih dan bombay iris dadu hingga harum-layu 1 menit di api sedang.\", \"Kecilkan api, masukan daging yg sudah diiris-iris, tumis hingga berubah warna, lalu tambahkan kikkoman. sekalian di bumbui dengan gula semut/ gula palem/ gula aren. aduk rata.\", \"Tambahkan air, koreksi rasa, biarkan bumbu meresap ke daging, 5-10 menit.\", \"Terakhir masukan bombay iris memanjang, aduk sebentar lalu matikan api.\", \"*selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(520, 4, 'Bola bola daging sapi giling saus tomat yummy (diet gm hari ke 5) || magic com', 'Cara membuat Bola bola daging sapi giling saus tomat yummy (diet gm hari ke 5) || magic com yang enak dan praktis untuk keluarga.', '[\"Bahan bola bola daging sapi giling\", \"500 gram daging sapi giling\", \"1 butir telur\", \"3 butir bawang putih\", \"Secukupnya bubuk jinten\", \"Secukupnya bubuk ketumbar\", \"Secukupnya bubuk lada\", \"Sejumput penyedap rasa (blh di skip)\", \"Secukupnya garam\", \"Bahan saus tomat\", \"4 butir tomat merah besar\", \"2 butir bawang putih\", \"4 butir bawang merah\", \"10 cabai rawit setan (sesuai selera ya bun)\", \"3 sendok makan saus tomat abc (blh d skip)\", \"Sejumput bubuk lada dan jinten\", \"1 seat sauri saus tiram\", \"4 sendok makan margarin\", \"1/2 sendok teh gula\", \"Secukupnya garam\", \"Secukupnya penyedap (boleh d skip)\"]', '[\"Per tama kita cambur semua bahan bola bola sapi giling (klo tadi aku campur tempe hehe 1 potong kecil ga usah pake juga enk ko) bentuk sesuai selera\", \"Panas kan magic com beri 2 sendok margari.. dan bolq bola sapi yg sdh di bentuk di masukan ke magic com dan tutup..\", \"Setelah smua bola bola sapi matang smua.. sisihkan trlebih dahulu... lanjt ngerubus tomat\", \"Tomat yg tlah di rebus di taruh k gelas dan tekan tekan agar halus (lbh cpt menggunakan blender)\", \"Tumis bawang putih,bawang merah,cabai(bisa di potong bsa d haluskan sesuai selera) setlah harum masukan tomat yg sdh di haluskan.. dan beri air sedikit aja.. beri saus tomat garam,gula,penyedap saus tiram,jinten bubuk,lada bubuk.. dan tunggu higga mendidik.. masukan bola bola sapi nya nunggu hingga adak surut... ehmm.. jadi dehh\", \"Jangan lupa ya selama memasak magicom slalu ke adaan cook.. kalo sy..sy ganjal tisuu.. ketika memasak juga harus di tutup jika ingin mengaduk baru di buka.. lalu di tutup lagi..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(521, 3, 'Gulai kepala sapi', 'Nikmati kelezatan Gulai kepala sapi dengan resep sederhana ini.', '[\"700 gr kepala sapi\", \"3 sdm minyak goreng\", \"3 btr  kapolaga\", \"3 btr cengkih\", \"4 cm kayu manis\", \"5 cm lengkuas iris tipis dan memarkan\", \"2 btg serai memarkan\", \"4 lbr daun jeruk\", \"1 liter  santan dati 3/4 btr kelapa\", \"1 sdt air asam jawa\", \"Secukupnya gula garam sesuai selera\", \"Bumbu halus:\", \"5 bh cabai merah\", \"10 bh bawang merah\", \"4 siung bawang putih\", \"4 btr kemiri bulat, sangrai\", \"2 cm jahe\", \"2 cm kunyit, bakar/goreng\", \"2 sdm ketumbar sangrai\", \"1 sdt jinten sangrai\", \"1/2 sdm merica sangrai\", \"1/4 sdt adas\"]', '[\"Didihkan air, lalu rebus kepala sapi kurang lebih 10 menit, buang air rebusan lalu cuci daging. Rebus kembali hingga setengah empuk (saya presto 15 menit dari suara memdesis). Lalu potong potong ukuran sesuai selera. Masukan kembali kedalam air rebusan. Sisihkam\", \"Tumis bumbu halus hingga benar bena matang, tuang kedalam rebusan daging bersama bumbu rempah.\", \"Masak daging hingga empuk. Kalau air menyusut tambahkan lagi air panas secukupnya.\", \"Masukan santan dan air asam jawa, masak hingga hingga mendidih dan santan berminyak. Koreksi rasa.\", \"Siap dihidangkan bersama nasi, sambal rawit dan acar\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(522, 2, 'Sapi Cah Kailan', 'Resep Sapi Cah Kailan ala rumahan yang dijamin menggugah selera.', '[\"200 grm Daging Sapi iris tipis\", \"2 Ikat Kailan Iris +/- 10 cm\", \"3 sdm Saus Tiram\", \"1 sdt kecap inggris\", \"1 sdt lada bubuk\", \"5 bawang putih Geprek\", \"2 bawang putih dihaluskan/bubuk\", \"2 sdm minyak Wijen\", \"2 sdm Oliv Oil\", \"1 cm Jahe Geprek\", \"Garam,Kaldu Jamur(totole),gula\", \"1/4 bawang bombay,potong memanjang\", \"1 gelas belimbing air\", \"Tepung meizena yg dilarutkan dengan sedikit Air\"]', '[\"Marinasi Daging dengan bawang putih halus,kecap inggris,lada bubuk,saus tiram,garam,jahe,oliv oil,minyak wijen..masukan Freezer +/- 15 menit.\", \"Panaskan Minyak Sayur,sedikit oliv oil,sedikit minyak wijen dan sedikit margarin, Masukan Bawang Putih Geprek dan bawang Bombay sampai harum, masukan daging yg telah di marinasi\", \"Tuangkan Air dan masak sampai sedikit berkurang dan daging Empuk, masukan Kailan,dan tepung meizena yg sdh dilarutkan air.\", \"Sajikan Pakai Cinta dan senyum ya,,pasti Lebih nikmat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(523, 4, 'Beef Blackpaper sederhana', 'Sajian Beef Blackpaper sederhana yang praktis dan lezat untuk dinikmati bersama.', '[\"1/4 kg daging sapi (rebus lalu tiriskan)\", \"2 siung bawang putih (di cincang)\", \"1 siung bawang merah (di cincang)\", \"2 bawang bombay (potong memanjang)\", \"1 cabe kriting (iris serong)\", \"Cabe rawit (sesuai selera)\", \"1/2 sendok makan ladaku\", \"secukupnya Air\", \"Bumbu blackpaper (saya pakek merk saori saos blackpaper)\", \"Daun bawang (iris kecil”)\", \"Tambahan:\", \"Brokoli + wortel di potong kecil lalu di kukus\"]', '[\"Panaskan teflon beri sedikit minyak goreng, tunggu sampai panas\", \"Masuk kan semua bumbu yang sudah di di siapkan\", \"Tunggu hingga harum\", \"Masukkan daging yang sudah di iris\", \"Masukan saos blackpaper dan tambahkan ladaku dan daun bawang\", \"Beri sedikit air\", \"Tunggu hingga mendidih\", \"Koreksi rasa dan sajikan bersama nasi hangat\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(524, 4, 'Tumis Beef Burger (menu balita 1y+)', 'Sajian Tumis Beef Burger (menu balita 1y+) yang praktis dan lezat untuk dinikmati bersama.', '[\"2 lbr Beef Burger siap pakai, potong korek api\", \"1 bh wortel ukuran kecil, potong korek api\", \"1 sdm makaroni mentah\", \"2 btg Daun Seledri, cincang\", \"1 siung Bawang putih, cincang\", \"2 siung Bawang merah, iris\", \"1 sdm kecap manis\", \"1 sdt saus tomat botolan\", \"1/4 sdt Saori saus tiram\", \"secukupnya Garam\", \"secukupnya Gula\"]', '[\"Tumis Bawang putih, bawang merah, dan Beef Burger hingga harum, tambahkan 1 gelas air\", \"Masukkan wortel dan makaroni, masak hingga air setengah menyusut\", \"Tambahkan daun seledri, kecap manis, Saori saus tiram, saus tomat botolan, garam, dan gula secukupnya, koreksi rasa\", \"Masak hingga air habis dan semua komponen matang\", \"Tumis Beef Burger siap dinikmati\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(525, 3, 'Bubur Sayuran dan Daging Sapi', 'Bubur Sayuran dan Daging Sapi dengan daging sapi empuk dan bumbu kaya rasa.', '[\"Beras putih.Tapi kali ini saya pakai beras merah\", \"Brokoli, cincang\", \"Wortel,cincang\", \"Paprika, cincang\", \"Bawang bombai, cincang\", \"Bawang putih,cincang\", \"Daging Sapi, cincang\", \"Minyak Wijen\", \"Nori (opsional)\", \"Wijen (opsional)\"]', '[\"Tumis daging sapi dengan minyak Wijen di panci.\", \"Setelah kecoklatan masukkan bawang putih dan bombai.\", \"Setelah harum masukkan beras.\", \"Aduk2 beberapa saat\", \"Masukkan semua sayuran termasuk paprika.\", \"Masukkan air.\", \"Masak sampai jadi bubur.\", \"Setelah masak angkat.Tuang ke mangkok.\", \"Remek Nori.Taburi bubur dengan nori dan wijen.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(526, 4, 'Sop kacang merah daging sapi', 'Resep praktis Sop kacang merah daging sapi yang bisa dicoba di rumah.', '[\"300 gram Daging sapi dipotong2 dadu\", \"Kacang merah (sesuka hati mau berapa banyak)\", \"4 siung Bawang merah\", \"4 siung bawang putih\", \"1 butir kemiri\", \"1 batang Serai di memarkan\", \"Jahe di iris2\", \"Daun bawang diiris2\", \"Daun sop\", \"Wortel\", \"Bunga Kol\", \"Macaroni\", \"Garam\", \"Penyedap rasa\", \"Lada bubuk\"]', '[\"Rebus kacang merah terlebih dahulu (airnya harus agak banyak yaa karena kacang merah masaknya agak lama sampe kacangnya jadi lembek kalau ditusuk)\", \"Sambil menunggu kacang merah masak, kita bikin bawang gorengnya dulu\", \"Dari 4 siung bawang merah tadi ambil 2 siung saja lalu iris tipis-tipis\", \"Kemudian panaskan minyak secukupnya dan goreng sampai agak kecoklatan dan garing\", \"Angkat dan tiriskan\", \"Setelah itu buat bumbu halusnya ya,1 butir kemiri, 4 siung bawang putih dan 2 siung bawang merahy dihaluskan (blender lebih baik)\", \"Setelah itu panaskan sedikit minyak dan tumis bumbu halus tadi bersama dengan serai yang sudah dimemarkan dan jahe yang sudah di iris2.\", \"Jika kacang merah sudah matang, masukkan irisan daging sapi, wortel, bunga kol, macaroni dan bumbu yang sudah di tumis tadi\", \"Tambahkan garam,lada bubuk, penyedap rasa secukupnya sesuai selera\", \"Tunggu hingga daging sapi matang\", \"Taburkan daun bawang,daun sop dan bawang goreng\", \"SOP SIAP DISAJIKAN, hmmm.. selamat menikmati yaa bro sist. Semoga suka.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(527, 4, 'Tumis Sawi Asin Daging Sapi', 'Resep Tumis Sawi Asin Daging Sapi ala rumahan yang dijamin menggugah selera.', '[\"1 bungkus/bonggol sayur asin, cuci, iris sedang\", \"250 gr sapi has luar, iris iris agak tipis\", \"3 siung bawang putih\", \"1 buah bawang bombay ukuran kecil\", \"Bumbu2:\", \"1 sdm kecap maggi\", \"1 sdt kaldu jamur\", \"1/2 sdt jahe bubuk\", \"1 sdm kecap manis (sesuaikan selera)\", \"1/2 sdt gula pasir\", \"1 sdt minyak wijen\"]', '[\"Tuang sedikit minyak, tumis bawang putih dan bawang bombay hingga harum\", \"Masukkan daging sapi iris, aduk2 hingga berubah warna\", \"Beri jahe bubuk, kecap maggie, kaldu jamur, aduk rata\", \"Masukkan irisan sawi asin, aduk2, beri gula pasir, kecap manis. Terakhir masukkan minyak wijen. Aduk rata. Koreksi rasa.\", \"Jika rasa sudah pas, daging dan sawi asin sudah matang merata, matikan api. Angkat dan sajikan\", \"Note: 1. jika mau pakai jahe segar juga boleh, kupas jahe seukuran ibu jari, geprek. Setelah matang sayurnya, keluarkan jahe.\", \"Note : 2. Silakan disesuaikan jumlah bumbu2nya sesuai selera kita yah.. 🙋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(528, 4, 'Kwetiau rebus daging sapi', 'Resep Kwetiau rebus daging sapi ala rumahan yang dijamin menggugah selera.', '[\"100 gr kwetiau\", \"50 gr daging sapi\", \"1 btr telur\", \"100 gr kol\", \"10 batang sawi\", \"3 siung bawang putih\", \"1 bh bawang bombay uk. Kecil\", \"5 bh cabe rawit merah\", \"1 sdt minyak wijen\", \"4 sdm minyak goreng\", \"2 sdm saus tiram\", \"secukupnya Garam\", \"secukupnya Penyedap rasa\", \"secukupnya Air\"]', '[\"Cuci bersih kwetiau. Cincang halus bawang putih. Iris kol dan sawi dan bawang bombay. Potong tipis daging sapi\", \"Panaskan minyak masukka telor beri sedikit garam sambil di aduk lalu angkat\", \"Panaskan minyak goreng, tumis bawang putih dan bawang bombay sampai harum, lalu masukkan daging biarkan hingga berubah warna\", \"Masukkan kol, sawi, cabe rawit biarkan sampai layu. Beri air putih secukupnya, masukkan saus tiram, minyak wijen, garam penyedap rasa\", \"Koreksi rasa. Masukkan kwetiau dan telor (tingkat kematangan kwetiau sesuai selara). Matikan kompor. Kwetiau rebus daging sapi siap di hidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(529, 2, 'Bulgogi daging sapi simpel', 'Resep Bulgogi daging sapi simpel ala rumahan yang dijamin menggugah selera.', '[\"1/4 kg daging sapi\", \"1 buah bawang bombay diiris\", \"2 sdm Madu\", \"2 sdm kecap manis\", \"secukupnya Garam/ kecap asin\", \"4 siung bawang putih\", \"Sedikit merica bubuk\", \"Sedikit lada hitam bubuk\", \"optional Cabai\", \"Mentega untuk menggoreng\", \"Daun bawang dan wijen untuk pelengkap\"]', '[\"Rebus daging tambahkan sedikit garam, tunggu sampai empuk\", \"Sambil menunggu daging, ulek bawang Putih sampai halus. Campurkan dengan bawang bombay iris. Tambahkan kecap dan madu.\", \"Setelah daging sudah matang, masukkan ke air dingin untuk menghilangkan panasnya. Lalu diiris tipis2. Campurkan dengan bumbu ulek dan bawang bombay td\", \"Beri merica bubuk dan lada hitam, tambahkan saos tiram dan kecap asin/garam. Saya pakai kecap asin supaya tdk pakai penyedap/micin. Aduk merata semuanya. Diamkan beberapa saat sampai kira2 meresap\", \"Krn saya pakai cabai, saya iris cabai dulu. Panaskan mentega, oseng cabai sampai harum. Lalu masukkan adukan daging sebumbunya. Tinggal dioseng hingga merata. Cek rasa\", \"Beri daun bawang dan wijen kalau ada biar makin cantik. Siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(530, 4, 'Baso Sapi Pedas Manis', 'Hidangan daging sapi istimewa: Baso Sapi Pedas Manis.', '[\"250 gr baso sapi\", \"Bumbu iris :\", \"3 siung bawang merah\", \"2 siung bawang putih\", \"1 buah bawang bombay\", \"3 buah cabe rawit\", \"Bumbu pelengkap :\", \"1 sdm saus tiram\", \"3 sdm saus sambal (saya pakai indofood sambal pedas manis)\", \"1 sdm kecap manis\", \"1 sdt garam\", \"1/2 sdt lada bubuk\", \"1/2 sdt gula\", \"2 sdm margarin untuk menumus\"]', '[\"Tumis bawang merah, bawang putih, bawang bombai, dan cabe rawit sampai harum, masukkan baso aduk rata\", \"Tambahkan saus tiram, saus sambal, dan kecap. Beri garam, lada, dan gula. Aduk rata sambil koreksi rasa\", \"Tambahkan sedikit air agar sedikit berkuah. Masak sampai mendidih\", \"Angkat dann Baso Sapi Pedas Manis siap disajikan.. Happy cooking\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(531, 4, 'Tumis buncis daging sapi', 'Sajian Tumis buncis daging sapi yang praktis dan lezat untuk dinikmati bersama.', '[\"1/2 kg buncis\", \"1/4 kg daging sapi\", \"Bawang merah\", \"Bawang putih\", \"Cabai rawit merah\", \"Cabai merah keriting\", \"Gula merah\", \"Garam\", \"Penyedap\", \"Minyak untuk menumis\"]', '[\"Siangi buncis,cuci bersih dan potong serong\", \"Iris daging sapi kecil - kecil\", \"Semua bumbu di iris halus\", \"Panaskan minyak dan tumis bumbu sampai harum\", \"Masukkan daging sapi.masak sampai berubah warna,tambahkan air sedikit saja\", \"Masukkan buncis,tambahkan gula,garam,dan penyedap masak sampai matang\", \"Koreksi rasa dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(532, 4, 'Rawon Daging Sapi', 'Resep Rawon Daging Sapi ala rumahan yang dijamin menggugah selera.', '[\"250 gr Daging Sapi\", \"2 Batang Sereh dan di Geprek\", \"4 Lembar daun jeruk\", \"1 Ruas Jahe\", \"1 Ruas Lengkuas\", \"Air Secukupnya (Agak banyak karna nnti menyusut)\", \"Penyedap Rasa 1 bungkus (Rasa Sapi)\", \"Garam\", \"Daun Seledri\", \"Bumbu Halus\", \"5 bawang putih\", \"6 bawang merah\", \"1 Ruas Kunyit (Kecil aja)\", \"3 Buah Cabe merah\", \"1 Buah Kluwek (Isinya)\", \"3 Buah Kemiri\", \"1/2 Sdt Merica\"]', '[\"Tumis Bumbu Halus Sampai Harum dan Warna nya berubah\", \"Masukkan Sereh, Jahe, Lengkuas dan daun jeruk yg sudah di geprek. Lalu daging. Sampai bumbu nya menyerap\", \"Tambahkan Air, Sampai mendidih. tambahkan Garam dan Penyedap rasa. cicip\", \"Jika Sudah pas. tunggu sampai daging nya matang dan empuk. lalu tambahkan daun seledri dan bawang goreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(533, 3, 'Sapi lada hitam', 'Resep Sapi lada hitam yang lezat dan mudah dibuat di rumah.', '[\"1/4 kg daging sapi (boleh kurang boleh lebih)\", \"1 buah bawang bombay\", \"1 sachet saori saus lada hitam\", \"2 buah cabe hijau besar (boleh di ganti paprika)\", \"1 sachet royco sapi\"]', '[\"Cuci daging sampai benar-benar bersih, lalu potong sesuai selera. Kalo saya dipotong kecil-kecil biar ga ribet motong lagi pas mau makan.\", \"Iris tipis bawang bombay dan cabe hijau\", \"Panaskan wajan, lalu tumis bawang bombay hingga layu, lalu masukan daging yg sudah dipotong. Lalu masukan saori saus lada hitam, dan royco sapi. Cicip rasa, jika sudah sesuai, tumis sampai warna daging kecoklatan.\", \"Setelah warna daging berubah, masukan potongan cabai. Sengaja di masukan terakhir agar cabai tidak trlalu layu.\", \"Setelah daging sudah empuk. Masakan siap di hidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(534, 3, 'Pokcoy Baso Sapi', 'Resep Pokcoy Baso Sapi yang lezat dan mudah dibuat di rumah.', '[\"2 ikat pokcoy potong sesuai selera, ga dipotong jg ga masalah\", \"4 buah baso sapi, potong sesuai selera\", \"3 siung bawang putih digeprek\", \"2 buah cabe merah (jika ingin pedas)\", \"1 sdt Minyak goreng untuk menumis\", \"Garam, air, kaldu jamur\"]', '[\"Tumis bawang putih serta cabe merah\", \"Masukkan pokcoy dan baso, beri garam, kadu jamur, lalu tambahkan sedikit air jika kepingin ada kuahnya 😊\", \"Diamkan sesaat, jgn terlalu lama, koreksi rasa, sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(535, 4, 'Sop daging sapi', 'Buat Sop daging sapi yang nikmat dengan langkah-langkah mudah ini.', '[\"Daging sapi, boleh pake balungan/iga\", \"2 buah Kentang\", \"2 Buah Wortel\", \"Seldri\", \"3 Butir Bawang Putih\", \"8 Butir Bawang Merah\", \"Lada bubuk\", \"Kaldu sapi bubuk\", \"(Untuk sambal)\", \"Cabe keriting hijau\", \"Sedikit terasi\", \"Garam Dan Penyedap\", \"secukupnya Air\"]', '[\"Potong-potong Daging Dan Rebus daging sampai empuk.\", \"Sambil Menunggu Daging Empuk, Potong-Potong Dadu Kentang Dan Wortel. Lalu Rebus Dalam Wadah Yang Berbeda (Jadi Kuah Tidak Bau Sayur).\", \"Potong 4 Bawang merah Dan 3 Bawang Putih Untuk Di Goreng.\", \"Geprek 1 Bawang Putih Dan 4 Bawang Merah Untuk Di Masukkan Ke Kuah.\", \"Setelah Empuk Masukan Bawang Merah Dan Bawang Putih Yg tidak di goreng ke kuah.\", \"Tunggu sebentar. Lalu masukan Kentang Dan Wortel Yang Sudah Di Rebus.\", \"Masukan Kaldu Dan Lada Bubuk secukupnya. Beri Sedikit Bawang Goreng. Dan Cek Rasa.\", \"Setelah di Angkat ke Wadah Beri Irisan Sledri Dan Bawang Goreng Di Atasnya.\", \"Untuk Sambel Rebus Cabai Hijau Dan Bakar Sedikit Terasi Sedikit Garam Dan Penyedap. Haluskan.\", \"Siap Di Nikmati 😉😘\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(536, 2, 'Beef Teriyaki ala Rumahan', 'Resep Beef Teriyaki ala Rumahan ala rumahan yang dijamin menggugah selera.', '[\"1/4 kg Daging Sapi Semur (Beli di Super Market)\", \"1 buah Bawang Bombay\", \"1 SDM Mentega / Butter\", \"Secukupnya Minyak Goreng (untuk menumis)\", \"Secukupnya Air\", \"Bumbu Marinade :\", \"6 SDM Saus Teriyaki (saya pakai Saori)\", \"1 SDM Saori Saus Tiram (Hayo baca nya sambil Nyanyi ya..) :)\", \"1 SDM Lada Putih Bubuk\", \"2 SDM Kecap Manis\", \"2 SDM Minyak Wijen\", \"2 Ruas Jari Jahe (Parut Halus)\", \"2 Siung Bawang Putih (Parut Halus)\", \"1 SDT Kecap Asin\"]', '[\"Pertama, cuci bersih daging yang sudah di beli tadi. Daging Semur sudah berbentuk dadu jadi kita tidak perlu memotong nya lagi. Lalu masukan kedalam Wadah / Mangkuk\", \"Kedua, Kita akan Memarinade daging sapi tadi, untuk mengawali kita masukan Saus teriyaki, lalu Saus Tiram, Berikutnya Kecap Manis, Kecap Asin, Minyak Wijen, Lada Bubuk. Aduk hingga daging terendam oleh saus tadi..(Ingat cuma daging yang direndam, Rasa Kangen mu Jangan) hehe Next masukan Bawang Putih & Jahe. Aduk kembali hingga rata\", \"Jika semua sudah, kini tutup wadah berisikan daging sapi tsb menggunakan Plastik Wrap & Diamkan dalam Kulkas sekitar 2-3 Jam\", \"Tips : masukan sendok teh / sendok kecil kedalam rendaman daging agar daging nantinya menjadi mudah empuk.\", \"Taaaaaraaaaa....setelah menunggu lama sampai kelaparan akhirnya daging yg sudah dibumbui siap di masak man teman....\", \"Siapkan Teflon/Penggorengan. Masukan Minyak & Mentega lalu Tumis Bawang Bombay Hingga Harum & Setengah Layu\", \"Jika sudah tercium bau harum...kemudian masukan semua daging yang sudah di bumbui tadi dan tumis sedikit hingga rata. Masukan Air Secukupnya Lalu masak menggunakan Api Kecil sampai matang & bumbu meresap\", \"Koreksi Rasa & Jika sudah matang, Siap untuk di Sajikan menggunakan Nasi Anget..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(537, 2, 'Beef Macaroni Teflon', 'Resep praktis Beef Macaroni Teflon yang bisa dicoba di rumah.', '[\"100 g macaroni (saya pake yg bentukk spiral\", \"1 sachet korned beef\", \"125 ml susu cair\", \"1 butir telor, dikocok dgn sedikit air\", \"3 lembar keju slice, potong kotak\", \"1 buah tomat, diparut/potong kotak kecil-kecil\", \"Bumbu:\", \"1 butir bawang putih, diparut\", \"1 buah bawang bombay(ukuran kecil), diparut\", \"2 sdm saus tomat\", \"1 sdt lada, garam, gula, bubuk pala, oregano\", \"Kurang lebih 20-30 ml air\", \"2 sdm margarin untuk menumis\"]', '[\"Rebus macaroni hingga aldente, sisihkan\", \"Panaskan margarin, masukkan bawang putih dan bawang bombay aduk-aduk hingga harum\", \"Tambahkan tomat parut dan saus tomat, tambah sedikit air aduk\", \"Masukkan corned beef, macaroni, susu, aduk rata\", \"Tambahkan lada, garam, oregano, bubuk pala, cicip rasa. Matikan api, angkat.\", \"Panaskan teflon, tuang macaroni ke atas teflon, tuangkan telur secara merata di atas permukaan.\", \"Tata potongan keju slice di atas telur hingga menutupi permukaan.\", \"Panggang dengan api kecil hingga matang.\", \"Angkat, sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(538, 3, 'Soto Daging Sapi', 'Resep Soto Daging Sapi ala rumahan yang dijamin menggugah selera.', '[\"1 kg daging sapi, rebus sampai empuk, potong dadu\", \"bahan kuah :\", \"kaldu air rebusan daging\", \"2 batang daun prei, cincang\", \"bumbu halus :\", \"6 siung bawang merah\", \"5 siung bawang putih\", \"1 butir kemiri\", \"1/2 cm jahe\", \"secukupnya kunyit bubuk\", \"secukupnya ketumbar bubuk\", \"secukupnya lada putih\", \"secukupnya garam\", \"secukupnya gula pasir\", \"3 lembar daun salam\", \"4 lembar daun jeruk\", \"2 batang serai, geprek\", \"secukupnya minyak untuk menumis\", \"pelengkap :\", \"nasi putih hangat/lontong/ketupat\", \"soun jagung, rendam sebentar sampai layu, tiriskan\", \"krupuk udang\", \"sambal\", \"jeruk nipis\", \"bawang merah goreng\", \"seledri cincang\"]', '[\"Siapkan kaldu sapi rebusan daging, masukkan daging sapi yang sudah di rebus sampai empuk potong dadu\", \"Blender bumbu halus (kecuali daun salam, daun jeruk dan serai)\", \"Panaskan minyak secukupnya, masukkan bumbu halus, aduk sampai keluar wanginya, masukkan daun salam, daun jeruk dan serai, masak sampai layu, matikan api\", \"Masukkan bumbu halus ke dalam kuah kaldu, tambahkan irisan daun prei, tambahkan gula, garam, lada bubuk secukupnya, icipi sampai rasanya pas, masak sampai mendidih, matikan api\", \"Tuang ke mangkuk saji bersama pelengkapnya dan nasi putih hangat (opsi : boleh pakai lontong atau ketupat) ❤\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(539, 4, 'Beef+Sausage Teriyaki w/ Salad', 'Cara membuat Beef+Sausage Teriyaki w/ Salad yang enak dan praktis untuk keluarga.', '[\"1/4 kg Daging Sapi\", \"3 buah Sosis Ayam/Sapi (additional)\", \"2 sdm Minyak sayur\", \"1 buah Bawang bombay (sedang)\", \"2 buah Bawang putih\", \"2 sdm Saos Teriyaki\", \"1 sdm Mentega\", \"secukupnya Garam\", \"Bahan Marinate:\", \"2 sdm Kecap asin\", \"2 sdm Kecap manis\", \"secukupnya Lada bubuk\", \"1 sdm Minyak sayur\", \"Bahan Salad:\", \"1 buah Wortel\", \"1/2 buah Jagung\", \"secukupnya Mayonaise\", \"Boncabe (additional)\"]', '[\"Potong daging sapi dan sosis sesuai selera. Masukkan bahan marinate. Aduk. Sambil nunggu bahan meresap ke daging.\", \"Potong jagung dan wortel sesuai selera. Lalu rebus sebentar. Angkat dan tiriskan. Tambahkan mayonaise dan boncabe.\", \"Iris tipis bawang putih dan bawang bombay. Lalu panaskan minyak.\", \"Tumis bawang putih dan bawang bombay. Masukkan daging dan sosis yang sudah di marinate.\", \"Tambahkan mentega, saos teriyaki dan garam. Jangan lupa koreksi rasa.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(540, 3, 'Krengseng tulang sapi', 'Sajian Krengseng tulang sapi yang praktis dan lezat untuk dinikmati bersama.', '[\"1/2 kg tulang sapi\", \"1 sdm petis\", \"2 sdm kecap manis\", \"Bumbu yg dihaluskan:\", \"4 siung bawang merah\", \"2 siung bawang putih\", \"1 sdm merica\", \"1 buah tomat\", \"5 cabe rawit (sesuai selera masing²)\", \"3 cabe merah\", \"Kunyit\", \"Jahe\", \"Secukupnya gula merah dan garam\"]', '[\"Tumis bumbu halus sampai harum\", \"Masukkan tulang/daging sapi dan tumis sampai pucat\", \"Tambahkan air panas dan kecap, aduk rata lalu tutup. Tunggu sampai air sedikit menyusut (kurleb 40menit kalo tulang, 30menit kalo daging)\", \"Baru masukkan petis, aduk² sampai rata\", \"Tutup kembali dan sekali² diaduk agar tidak gosong. Tunggu sampai air menyusut sesuai selera masing². Jangan lupa cek rasa yaa. Trus sajikan...😘😘\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(541, 3, 'Simple Spicy Beef Curry -keto #ketopad', 'Resep Simple Spicy Beef Curry -keto #ketopad yang lezat dan mudah dibuat di rumah.', '[\"200 gr daging sapi\", \"300 gr lemak sapi\", \"1 bungkus bumbu kari instant merk ‘Bamboe’\", \"1 sdt himalayan salt\", \"Secukupnya bawang goreng\", \"Secukupnya irisan cabe rawit\", \"1 sdm cabai bubuk\"]', '[\"Rebus daging sapi hingga empuk jangan buang air rebusannya, sisihkan\", \"Di panci berbeda rebus lemak sapi kemudian buang air rebusannya berkali-kali hingga benar2 sudah tak ada aroma bau sapi nya, tiriskan, cuci dengan air bersih, tiriskan kembali\", \"Di panci habis merebus daging tadi beserta kaldunya, tambahkan secukupnya air, masukkan lemak sapi kedalamnya, tambahkan air bila perlu hingga merendam seluruh daging dan lemak\", \"Masukkan bumbu kari instant, cabe bubuk, irisan cabe rawit, dan santan, lalu masukkan garam, aduk rata, cicipi rasanya, bila kurang asin, tambahkan lagi garamnya\", \"Masak diatas api kecil sampai mendididih, biarkan mendidih hingga 5 menit, matikan api, taburi dengan bawang goreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(542, 2, 'Gulai Nangka Lemak Sapi ala Fm', 'Resep praktis Gulai Nangka Lemak Sapi ala Fm yang bisa dicoba di rumah.', '[\"800 gram nangka muda, yang sudah bersih dari kulit, cuci bersih\", \"santan dari 1 butir kelapa ukuran sedang kurleb 1,5 liter\", \"1 liter air bersih\", \"secukupnya cabe rawit  giling halus\", \"secukupnya cabe merah  giling halus\", \"Secukupnya bawang merah , giling kasar\", \"secukupnya bawang putih, giling kasar\", \"secukupnya jahe giling halus\", \"secukupnya kunyit  giling halus\", \"secukupnya lengkuas , geprek\", \"secukupnya sereh , geprek\", \"secukupnya daun kunyit\", \"secukupnya daun salam\", \"secukupnya daun jeruk\", \"secukupnya garam\", \"lemak sapi ,\", \"secukupnya minyak untuk menumis bumbu\"]', '[\"Panaskan minyak, goreng bawang hingga harum, masukkan bumbu halus serta daun pelengkap, aduk rata, tuang lemak sapi, aduk rata. Tambahkan nangka aduk rata, lalu tuang air bersih masak hingga nangka empuk.\", \"Setelah nangka empuk masukkan santan kelapa, masak hingga santan menyusut, cicipi rasa, tambahkan garam dan penyedap rasa jika suka.\", \"Kalo saya lebih suka setelah mendidih beberapa kali, apinya dikecilkan, (di sangai) hingga setengah jam, agar gulai ga gampang basi.\", \"Happy cooking all\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(543, 3, 'Serundeng Sapi', 'Serundeng Sapi dengan daging sapi empuk dan bumbu kaya rasa.', '[\"1/4 kg tetelan sapi\", \"1/4 buah kelapa muda parut\", \"6 siung bawang merah\", \"4 siung bawang putih\", \"2 sdt ketumbar\", \"3 sdt garam\", \"2 bulat kecil gula merah\", \"4 lembar daun salam\", \"2 buah tomat\", \"Lengkuas\", \"Royco sapi\"]', '[\"Rebus tetelan sapi hingga empuk dan airnya jgn dibuang krn utk kaldunya\", \"Iris2 daging sapi sesuai selera\", \"Haluskan bumbu yg sudah disiapkan\", \"Campurkan bumbu yg sudah halus sampe merata serta campurkan air kaldu sisa rebusab daging td dan masukkan potongan tomat serta daun salam dan lengkuas\", \"Aduk2 dan tunggu smpe kering dan kecoklatan kurang lebih 1,5jam dgn api sedang\", \"Cicipi hinga rasanya pas, dan angkat serta sajikan dgn nasi hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(544, 3, 'Bistik bola daging sapi', 'Resep Bistik bola daging sapi ala rumahan yang dijamin menggugah selera.', '[\"250 g daging sapi\", \"2 sdm tepung terigu\", \"2 sdm tepung tapioka\", \"1 buah kentang\", \"bumbu:\", \"2 siung bawang putih\", \"4 siung bawang merah\", \"2 buah sereh\", \"3 cm lengkuas\", \"1/2 buah tomat\", \"100 ml santan kelapa\", \"secukupnya merica\", \"secukupnya kecap manis\", \"secukupnya garam gula\"]', '[\"Haluskan daging (me:blender),kemudian tambahkan tepung terigu dan tepung tapioka,tambahkan sedikit air,garam dan merica.Diaduk jadi seperti adonan bakso.\", \"Siapkan air mendidih di panci,ambil bulatan daging pake sendok,masukkan ke panci.tunggu mengambang,angkat dan tiriskan\", \"Potong kentang jadi dadu,goreng sebentar.sisihkan.\", \"Haluskan bumbu bawang merah,bawang putih.tumis hingga harum.masukkan daun salam,dan sereh serta lengkuas yg digeprek.tambahkan air,masukkan bola daging dan kentang.\", \"Tunggu mendidih,tambahkan kecap,tomat,beri gula garam merica sesuai selera.tes rasa.masukkan santan kelapa.\", \"Tunggu agak mengental,matikan api dan siap dihidangkan:)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(545, 2, 'Beef Oseng Kecap', 'Resep Beef Oseng Kecap ala rumahan yang dijamin menggugah selera.', '[\"200 gr daging sapi segar\", \"2 bh cabai merah besar (optional)\", \"5 btr bawang merah\", \"3 btr bawang putih\", \"5 sdm kecap manis\", \"1 sdm saus tiram (optional)\", \"1/4 sdt lada bubuk\", \"1/4 sdt penyedap rasa sapi (optional)\", \"1/2 sdt gula pasir\", \"2 sdm minyak goreng\"]', '[\"Cuci dan potong daging dengan ketebalan menyesuaikan selera, rebus hingga air mendidih, angkat, tiriskan\", \"Iris bawang merah, bawang putih dan cabai merah\", \"Tumis bawang dan cabai hingga harum, tambahkan kecap manis, saus tiram dan gula\", \"Masukkan daging sapi yang sudah direbus dan ditiriskan, aduk hingga seluruh daging merata terbalut bumbu. Tambahkan penyedap dan lada bubuk, aduk kembali kemudian masak dengan api kecil 5 menit\", \"Cicipi rasa, boleh ditambah garam jika ingin, jika rasa sudah pas, biarkan hingga bumbu benar meresap lalu angkat dan hidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(546, 4, 'Beef Bowl (牛丼)', 'Resep Beef Bowl (牛丼) ala rumahan yang dijamin menggugah selera.', '[\"10 helai daging sapi slice ala shabu-shabu\", \"1/2 buah bawang bombay\", \"Secukupnya coca cola (ini eksperimen, kalau kecap asin ditambah gula biar gurih. Maka kalau coca cola ditambah garam agar gurih)\", \"Secukupnya garam\", \"Secukupnya wijen\", \"Secukupnya penyedap rasa\", \"1 buah cabe\", \"Secukupnya daun bawang\"]', '[\"Siapkan bahan-bahan\", \"Iris-iris bawang bombay.\", \"Tumis bawang bombah dengan sekit minyak. Kemudian masukkan secukupnya coca cola. Dan rebus sampai bawang bombay layu. Masukkan garam dan penyedap rasa.\", \"Masukkan daging dan irisan cabe, tumis sampai daging masak dengan warna kecoklatan.\", \"Masukkan wijen secukupnya.\", \"Siapkan nasi di dalam mangkuk dan tuangkan tumisan daging di atasnya. Tambahkan irisan daun bawang. Dan siap disantap.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(547, 2, 'Bakso Urat Daging Sapi', 'Resep Bakso Urat Daging Sapi yang lezat dan mudah dibuat di rumah.', '[\"1/2 kg daging sapi\", \"1 ptg dada ayam\", \"10 siung bawang putih, haluskan\", \"4 sdm tepung Tapioka\", \"1 sdm royko rs ayam\", \"1 sdm garam\", \"1 btr telur\"]', '[\"Bahan-bahan\", \"Halus kan daging sapi dan daging ayam.. jika tidak ada cooper bs pake blender.. sedikit demi sedikit\", \"Setelah ayam dan daging halus.. campurkan semua bahan.. ulen dgn tangan sampai tercampur\", \"Didih kan air untuk merebus bakso.. setelah mendidih.. matikan\", \"Cetak bakso dgn tangan.. masuk kan k air panas td.. lakukan sampai habis\", \"Setelah habis.. rebus kembali hingga semua bakso mengapung.. matikan\", \"Angkat bakso lalu tiris kan..\", \"Selesai.. 😄\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(548, 4, 'Bakso urat daging sapi', 'Bakso urat daging sapi - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"500 gr daging sapi\", \"1 sdm bawang merah goreng\", \"2 sdm bawang putih goreng\", \"1/2 sdt baking powder\", \"2 sdt garam\", \"1 sdt gula\", \"1 sdt merica\", \"4 sdm penuh tepung sagu\", \"1 putih telur\", \"150 ml es batu\", \"1 sdt royco beef\"]', '[\"Masukan daging dan bawang kedalam food processor giling sebentar.\", \"Lalu masukan bahan lainnya giling, lalu terakhir masukan putih telor dan es batu\", \"Didihkan air di panci besar.\", \"Lalu bentuk bakso, dan cemplungkan ke dalam air yang masuh menyala apinya.\", \"Lalu angkat bakso yang sudah mengambang, dan siap untuk di setok.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(549, 3, 'Sambal goreng kentang ati sapi', 'Cara membuat Sambal goreng kentang ati sapi yang enak dan praktis untuk keluarga.', '[\"3 Sdm sambal goreng (Lihat resep sambal goreng)\", \"1 Batang Sereh\", \"2 Lembar Daun salam\", \"2 Lembar Daun jeruk (Buang tulang nya yg ditengah)\", \"100 Ml Santan sedang\", \"3 Buah Kentang (Potong sesuai selera, cuci bersih)\", \"100 Gram Hati sapi (Potong sesuai selera, sy potong dadu)\", \"Secukupnya Minyak goreng\", \"Bumbu rebusan hati sapi :\", \"1 Ruas Jahe (Digeprek)\", \"1 Ruas Lengkuas (Digeprek)\", \"1 Batang Sereh\", \"2 Lembar Daun salam\"]', '[\"Cuci bersih hati, tusuk2 hati dengan garfu supaya darahnya keluar.\", \"Rebus hati dengan bumbu rebusan hati hingga empuk. Angkat, tiriskan lalu potong sesuai selera.\", \"Siapkan wajan dengan api kecil. Lalu goreng kentang hingga matang kemudian setelah selesai goreng hati hingga matang (Jangan terlalu lama supaya gk keras).\", \"Siapkan wajan dengan api kecil. Tumis sambal goreng lalu masukkan sereh, daun salam, daun jeruk hingga harum.\", \"Setelah itu masukkan hati sapi, kentang, santan, garam dan gula. Aduk rata, biarkan hingga santan menyusut atau kering.\", \"Siap disajikan dan dinikmati.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(550, 4, 'Beef Steak with Mushroom Sauce', 'Beef Steak with Mushroom Sauce - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"4 potong daging (saya belinya di hypermart)\", \"Secukupnya garam dan merica hitam\", \"Bahan saus :\", \"1 siung bawang putih, cincang halus\", \"1/2 buah bawang bombay, cincang halus\", \"2 sdm butter\", \"Sesuai selera jamur champignon, iris tipis\", \"2 sdm tepung terigu\", \"100 ml susu UHT\", \"300 ml kaldu sapi (atau air putih + kaldu sapi bubuk)\", \"1 sdm keju parut (saya pakai keju cheddar)\", \"Sesuai selera gula, garam dan merica bubuk\", \"Pelengkap :\", \"3 buah kentang, potong wedges, goreng\", \"Secukupnya mix vegetables (saya wortel, jagung dan buncis)\"]', '[\"Lumuri tiap potongan daging dengan garam dan blackpepper sebelum dipanggang\", \"Panggang daging masing-masing sisinya sesuai tingkat kematangan yang diinginkan (saya manggang di teflon aja)\", \"Saus: Panaskan butter, kemudian tumis bawang putih dan bombay sampai layu dan wangi. Tambahkan jamur iris, tumis sebentar.\", \"Masukkan tepung terigu, aduk hingga bergumpal. Aduk-aduk terus sebentar agar terigunya masak.\", \"Tuang campuran susu cair dan air kaldu sedikit demi sedikit sambil terus diaduk sampai terlihat adonan saus yang licin.\", \"Tambahkan keju parut. Aduk hingga keju larut. Tambahkan garam, gula dan merica bubuk. Aduk-aduk sampai meletup-letup. Cicipi dan koreksi rasanya\", \"Pelengkap: Tumis sebentar mix vegetables dengan butter/margarin. Tambahkan garam dan merica bubuk secukupnya\", \"Sajikan daging steak dengan pelengkapnya dan dituang saus\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(551, 3, 'Krengsengan daging sapi pedas tanpa petis', 'Buat Krengsengan daging sapi pedas tanpa petis yang nikmat dengan langkah-langkah mudah ini.', '[\"1 kg Daging sapi (bgian Has)\", \"10 bh bawang Merah\", \"4 bh bawang putih\", \"15 bh cabe rawit (optional)\", \"2 bh cabe merah\", \"1 sdt merica\", \"3 sdm kecap manis\", \"secukupnya Bubuk kaldu\", \"Garam,gula secukupx\", \"1 cm jahe\", \"1 cm laos\", \"1 bh serai\", \"2 btr kemiri\"]', '[\"Potong \\\" daging sesuai selera,sisihkan\", \"Haluskan bawang merput,cabe,dan kemiri\", \"Tumis bumbu halus masukkan bumbu yg tdk di haluskan td,kemudian masukkan daging\", \"Aduk\\\" hinggga rata sampai bumbu meresap,tmbhkan sedikit air\", \"Tunggu sampai daging empuk,,masukan kecap manis,lada,garam,gula,dan penyedap rasa\", \"Aduk \\\"sampai rata dan di icip\\\" dl klu di rasa sdh pas,,,\", \"Siap hidangkan\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(552, 4, 'Sambal Goreng Hati Sapi Kentang', 'Resep praktis Sambal Goreng Hati Sapi Kentang yang bisa dicoba di rumah.', '[\"250 gr hati sapi\", \"250 gr kentang kupas,potong dadu\", \"1 batang serai geprek\", \"3 lembar daun jeruk\", \"2 ruas jari lengkuas geprek\", \"1 sdm air asam jawa\", \"1 sdm kaldu jamur/kaldu sapi bubuk\", \"1 sdt lada putih halus\", \"Secukupnya garam,gula\", \"30 ml santan kental\", \"Secukupnya air\", \"Secukupnya minyak goreng\", \"Bumbu halus\", \"7 buah cabe merah kering(versi gk pedas)\", \"Atau\", \"150 gr cabe merah keriting segar(versi pedas)\", \"7 siung bawang merah\", \"5 siung bawang putih\", \"3 buah kemiri sangrai\", \"1 sdt ketumbar sangrai,haluskan\", \"Secukupnya bawang goreng\"]', '[\"Siapkan semua bahan dan bumbu\", \"Rebus hati sapi di air mendidih dengan 2 lembar daun salam hingga matang (sekitar 10 menit)\", \"Angkat lalu potong kotak kotak,\", \"Goreng kentang hingga matang, angkat dan sisihkan\", \"Lalu goreng hati sapi sebentar saja sekitar 1 menit,jangan sampai kering\", \"Panaskan sedikit minyak kemudian tumis bumbu halus bersama dg serai,daun jeruk,lengkuas. Tumis hingga harum dan matang\", \"Tuang air putih dan air asam jawa ke tumisan tadi, aduk rata tunggu hingga mendidih, lalu tambahkan kaldu bubuk,merica,gula garam,aduk rata.\", \"Masukan hati sapi aduk rata,tunggu hingga air sedikit menyusut dan tes rasa (dicicipin yah) jika ada yang kurang bisa ditambahkan lagi.\", \"Setelah rasanya pas masukan kentang aduk rata sebentar,lalu angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(553, 4, 'Daging sapi cincang (isian roti goreng)', 'Daging sapi cincang (isian roti goreng) dengan daging sapi empuk dan bumbu kaya rasa.', '[\"300 gr daging sapi cincang\", \"1 bh bawang bombang cincang halus\", \"3 btr bawang merah iris halus\", \"1 btg daun bawang,iris halus\", \"1 sdm saus tiram\", \"1 sdm kecap asin\", \"secukupnya Kecap manis\", \"secukupnya Merica hitam,merica putih\", \"secukupnya Garam,gula,air\", \"1 sdm tepung terigu,dilarutkan dg air sebagai pengental\"]', '[\"Tumis bawang bombay dan bawang merah sampai harum dan matang.\", \"Masukkan daging cincang,aduk rata dan masak sampai daging berubah warna\", \"Tambahkan saus tiram,kecap asin,kecap manis,garam,gula,merica aduk rata\", \"Tambahkan air secukupnya,masak sampai bumbu meresap,cicipi dan koreksi rasanya\", \"Sebelum air menyusut tambahkan larutan terigu,masak sampai mengental (tapi tidak kering)\", \"Sebelum diangkat,masukkan daun bawang,aduk rata. Angkat dan siap dijadikan isian roti goreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(554, 3, 'Soto Sapi', 'Nikmati kelezatan Soto Sapi dengan resep sederhana ini.', '[\"200 gr Daging Sapi\", \"1 sdm Merica ( Bisa bedaTergantung selera\", \"7 siung Bawang Putih\", \"1 ruas Jahe\", \"1/2 ruas Kunyit\", \"2 Lembar salam\", \"1 Serai\", \"2 biji cengkeh\", \"sedikit Kayu manis\", \"1 royco sapi\", \"secukupnya Garam\", \"secukupnya gula\", \"Tauge\", \"Kol\", \"Seledri\"]', '[\"Rebus Daging sapi hingga Lunak (airnya jangan dibuang)\", \"Kupas Bawang putih haluskan bersama Merica, Kunyit, garam, gula Setelah itu Tumis bersama cengkeh, jahe (geprek) dan kayu manis hingga Harum\", \"Masukkan Air rebusan daging sapi kedalam tumisan bumbu\", \"Cuci salam dan serai masukkan kedalam kuah soto\", \"Tunggu hingga mendidih\", \"Setelah mendidih Sajikan bersama Kol seledri dan tauge jangan luoa taburi bawang goreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(555, 2, 'Soto Bandung (Daging sapi & lobak)', 'Nikmati kelezatan Soto Bandung (Daging sapi & lobak) dengan resep sederhana ini.', '[\"1/4 daging sapi\", \"1 buah lobak\", \"1 liter air\", \"Bumbu Halus\", \"4 siung bawang merah\", \"4 siung bawang putih\", \"Rempah-rempah\", \"1 lembar daun salam\", \"1 batang sereh\", \"1 potong lengkuas\", \"2 sdt garam\", \"1 sdt penyedap rasa (aku pake kaldu jamur)\", \"Bahan pelengkap\", \"Kacang kedelai goreng\", \"bawang daun + seledri\", \"sambel\"]', '[\"Rebus daging sapi sampai empuk\", \"Haluskan duo bawang, lalu tumis\", \"Masukan tumisan bumbu bawang ke rebusan daging sapi, tambahkan rempah2\", \"Masukan lobak yang sudah direbus\", \"Masukan garam dan penyedap, lalu koreksi rasa\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(556, 4, '11. Asem asem kikil sapi pedas', '11. Asem asem kikil sapi pedas dengan daging sapi empuk dan bumbu kaya rasa.', '[\"1/4 kg kikil sapi (yg sudah direbus lalu potong dadu -+1cm)\", \"2 buah wortel\", \"1/4 kg baby buncis\", \"2 lembar daun salam\", \"2 cm lengkuas\", \"5 siung bawang putih\", \"3 siung bawang merah\", \"1/2 siung bawang bombay\", \"7 biji cabe rawit\", \"2 biji cabe merah besar\", \"2 biji cabe hijau besar\", \"20 ml air asam jawa\", \"5 sdm kecap manis\", \"1 sachet penyedap rasa (me pakai masako sapi)\", \"1 sachet lada bubuk\", \"3 sdm saos raja rasa\", \"1 buah tomat\", \"500 ml air\", \"secukupnya Gula\", \"secukupnya Garam\", \"secukupnya Minyak goreng\"]', '[\"Cuci bersih kikil sapi lalu rebus hingga empuk, setelah empuk angkat dan tiriskan, potong bentuk dadu -+1cm\", \"Kupas dan potong baby buncis dan wortel bentuk dadu -+1cm juga lalu cuci bersih\", \"Iris bawang merah, bawang putih, bawang bombay dan cabai\", \"Panaskan penggorengan dan tambahkan minyak\", \"Tumis bawang merah, bawang putih, bawang bombay hingga harum setelah harum masukkan cabai, daun salam, lengkuas\", \"Setelah itu masukkan wortel dan baby buncisnya tambahkan air agar mudah empuk\", \"Lalu masukkan kecap manis, saos rajarasa merica bubuk, penyedap rasa, gula, garam dan asem jawa lalu koreksi rasa\", \"Tunggu hingga semua bahan empuk dan bumbu sudah mulai meresap lalu tambahkan potongan tomat\", \"Angkat dan siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(557, 2, 'SOP iga sapi by anggi', 'SOP iga sapi by anggi - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"300 gr iga sapi\", \"Paket SOP bungkusan(aku beli 3000 sudah kumplit sayuran)\", \"Seruas kayu manis(boleh skip)\", \"Bumbu halus :\", \"3 siung bawang putih\", \"1 sdt lada bulat\", \"seujung jari Jahe\", \"1/4 biji pala\", \"Garam,kaldu bubuk rasa sapi(masako/Royco)\", \"Bumbu rebusan iga :\", \"2 lembar daun jeruk\", \"2 lembar daun salam\", \"Jahe seruas jari\"]', '[\"Rebus iga sapi dengan,daun salam,daun jeruk,jahe..(1 jam 1/2,biar empuk)\", \"Tumis bumbu halus sampai harum\", \"Jika sudah 1 jam 1/2,masukan tumisan bumbu kedalam panci iga.\", \"Aduk2,masukan kentang dan wortel yg sudah di potong 2.\", \"Tunggu sesaat,masukan buncis,daun bawang,daun seledri,garam dan kaldu bubuk\", \"Sekiranya wortel sudah tdk terlalu keras,matikan kompor..tambahkan potongan tomat, sop iga sapi sudah siap di hidangkan 😊\", \"Tips agar SOP lebih sedap di anjurkan taburkan bawang goreng.. happy cooking bunda💙\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(558, 4, 'Tongcon (Tongseng Sapi Mercon)', 'Nikmati kelezatan Tongcon (Tongseng Sapi Mercon) dengan resep sederhana ini.', '[\"200 gram daging sapi\", \"1/4 buah kol ukurang sedang, iris kasar\", \"1 buah tomat ukuran sedang, iris kasar\", \"2 lembar daun salam\", \"3 lembar daun jeruk\", \"1 batang serai, geprek\", \"5 sdm kecap manis\", \"secukupnya Garam\", \"secukupnya Gula\", \"secukupnya Merica\", \"secukupnya Penyedap\", \"15-20 buah cabe rawit, potong kasar\", \"750 ml air\", \"Haluskan:\", \"6 siung bawang merah\", \"3 siung bawang putih\", \"2 buah kemiri\", \"1 jari jahe\", \"1 ruas jari kunyit\"]', '[\"Tumis bumbu halus. Kemudian masukkan daun salam, daun jeruk, serai. Tumis hingga harum\", \"Masukkan air, tunggu hingga mulai mendidih\", \"Masukkan kecap, garam, gula, merica, penyedap. Aduk hingga mendidih.\", \"Masukkan daging. Masak hingga daging empuk dan air agak menyusut.\", \"Masukkan cabe rawit, kol dan tomat. Tes rasa.\", \"Masak hingga kol layu\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(559, 2, 'Rendang Daging Sapi', 'Resep Rendang Daging Sapi yang lezat dan mudah dibuat di rumah.', '[\"500 grm daging sapi, bersihkan potong2\", \"2 btg Sereh, memarkan\", \"1000 ml santan kental (3 btr kelapa)\", \"1000 ml santan encer (perasan santan kental)\", \"5 lbr daun jeruk purut\", \"1 lbr daun kunyit, dihiris2\", \"Bumbu Halus :\", \"250 grm cabe merah\", \"2 cm kunyit\", \"4 siung bawang putih\", \"4 cm lengkuas\", \"10 btr bawang merah\", \"1 cm jahe\", \"Secukupnya garam dan gula\"]', '[\"Rebus santan cair, daun jeruk, Sereh, daun kunyit, dan bumbu halus, masak hingga mendidih.\", \"Masukkan daging yg sudah d potong2, beri garam, gula, masak hingga santannya kental.\", \"Kemudian masukkan santan kental, masak hingga hampir kering. Aduk2 hingga rendang kecoklatan dan berminyak.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(560, 2, 'Sop buntut/kikil/daging sapi', 'Sop buntut/kikil/daging sapi - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 kg buntut sapi\", \"3 buah wortel\", \"3 ruas jahe\", \"8 buah cengkeh\", \"3 sdm merica bubuk\", \"Gula putih\", \"Garam\", \"Haluskan :\", \"6 siung bawang putih\", \"3 siung bawang merah\", \"2 butir pala\", \"1/2 butir bawang bombay, tumis\", \"Daun bawang\", \"Seledri\", \"Tomat\"]', '[\"Rebus buntut sapi hingga empuk,\", \"Tumis bumbu halus, tambahkan bawang bombay, masukkan ke dalam rebusan buntut sapi\", \"Tambahkan potongan wortel, jahe, cengkeh. Setelah empuk masukkan tomat, irisan bawang daun dan seledri. Gula, garam, merica dan penyedap, tes rasa. Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(561, 4, 'Tumis Jagung Muda Sapi Cabe Ijo', 'Hidangan daging sapi istimewa: Tumis Jagung Muda Sapi Cabe Ijo.', '[\"10 butir jagung muda\", \"daging sapi (lupa gramnya, tapi gampangnya dilihat perbandingannya dengan jagung muda, kira-kira porsi daging sapi : jagung = 1:3)\", \"1 tangkai cabe hijau besar (kalo kurang pedas, tambahkan rawit iris)\", \"3 siung bawang putih\", \"2 siung bawang merah\", \"1/4 buah bawang bombay, iris\", \"secukupnya garam\", \"secukupnya minyak goreng\"]', '[\"Daging sapi direbus. Setelah matang, potong dadu atau sesuai selera. Angkat.\", \"Jagung muda iris memanjang.\", \"Bawang putih geprek cincang, bawang merah iris tipis. Tumis bawang putih, bawang merah, bawang bombay, dan cabe hijau ke dalam wajan hingga harum.\", \"Masukkan jagung muda ke dalam wajan. Tumis hingga setengah matang, lalu masukkan daging dadu ke dalam wajan. Tambahkan air supaya tidak asat, lalu aduk hingga jagung matang (lemas). Tambahkan garam, aduk dan cek rasa.\", \"Angkat dan sajikan! Mudah kan?\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(562, 3, 'Nasi Kebuli Daging Sapi (Magic Com)', 'Cara membuat Nasi Kebuli Daging Sapi (Magic Com) yang enak dan praktis untuk keluarga.', '[\"4 cup beras (sy beras biasa)\", \"1/4 kg daging sapi, potong dadu\", \"500 ml air (sesuaikan dgn beras, nasi kebuli mawur)\", \"Bumbu Halus :\", \"4 siung bawang putih\", \"6 siung bawang merah\", \"2 ruas kunyit\", \"1/2 sdt lada bubuk\", \"1/2 sdt ketumbar bubuk\", \"secukupnya garam\", \"Bumbu Lain :\", \"4 sdm bubuk kari\", \"1 bungkus bumbu kari instan (indofood)\", \"2 batang kayu manis\", \"4 sdm minyak sayur\", \"3 sdm margarin\"]', '[\"Rebus daging sapi hingga empuk, buang airnya.\", \"Haluskan bawang merah & bawang putih. Tumis bersama dgn margarin, lada bubuk, ketumbar bubuk, kunyit bubuk, bumbu kari instant & bubuk kari. Aduk rata.\", \"Tambahkan air, aduk rata & masak hingga mendidih.\", \"Masukkan daging sapi, aduk lagi & masak hingga 1/2 matang. Matikan kompor.\", \"Cuci bersih beras. Lalu masukkan daging sapi berserta kuahnya. Aduk rata. Nyalakan tombol cook. Biarkan hingga matang. Sajikan. 😃\", \"Ini nih bubuk kari\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(563, 3, 'Asem - asem daging sapi', 'Hidangan daging sapi istimewa: Asem - asem daging sapi.', '[\"500 gr daging sapi,\", \"Bumbu ;\", \"10 siung bawang merah, ulek\", \"5 siung bawang putih, ulek\", \"8 buah cabai hijau, potong\", \"6 buah cabai merah, potong\", \"20 buah cabai rawit merah/hijau, potong, (sesuai selera pedasnya\", \"3 buah tomat hijau, potong\", \"6 buah belimbing wuluh, potong\", \"Daun salam - jeruk\", \"2 batang serai, memarkan\", \"1 sdm asam jawa, larutkan air\", \"5 sdm kecap manis\", \"5 cm gula merah\", \"secukupnya Garam\"]', '[\"Rebus daging sapi sampai empuk, sampai keluar kaldunya. Lalu masukan daun salam-jeruk dan serai, lanjutkan merebus\", \"Tumis bumbu ulek, dan juga cabai, sampai harum, masukan ke dalam rebusan daging,\", \"Bumbui dengan kecap manis, gula merah, garam, boleh tambah lada sedikit, dan juga bumbu penyedap (opsional),\", \"Masukan tomat, belimbing wuluh, dan air asam, masak sambil dicocokan rasanya.\", \"Sajikan hangat, dengan nasi dan sambal mentah, hmmm nyam nyam 😋😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(564, 2, 'Soto daging sapi', 'Buat Soto daging sapi yang nikmat dengan langkah-langkah mudah ini.', '[\"1/4 daging sapi potong dadu\", \"1 batang sereh (geprek)\", \"1 helai daun jeruk\", \"1 helai daun salam\", \"2 cm kunyit (bakar dulu)\", \"1 sdt ketumbar\", \"1 butir kemiri\", \"1 sdt Merica bubuk\", \"1/2 bagian pekak\", \"2 cm batang kayu manis\", \"1 butir kapulaga (blh skip jk tidak suka aromanya)\", \"1 helai cengkeh\", \"1/4 sdt jintan\", \"2 cm jahe (geprek)\", \"(bisa beli bumbu soto yg msh berupa rempah yg dikemas 1 kemasan)\", \"5 buah bawang merah\", \"5 buah bawang putih\", \"2 buah bawang putih(iris dan goreng untuk taburan)\", \"2 batang daun bawang iris\", \"2 sdm gula pasir\", \"4 sdt garam\", \"Air secukupnya kurleb 1,5 liter\", \"1/2 bungkus kaldu bubuk sapi (bisa diganti penyedap lain)\", \"Cabai rebus + jeruk nipis + kecap untuk pelengkap sajian\"]', '[\"Haluskan : bawang merah,putih,kapulaga,cengkeh,pekak,jintan kemiri,ketumbar,kunyit (saya pake blender)\", \"Tumis bumbu halus hingga harum,masukkan daun salam+daun jeruk wangi+sereh+jahe+kayu manis\", \"Masukkan daging tutup panci hingga mendidih\", \"Bumbui gula,garam,merica bubuk,kaldu bubuk,cek koreksi rasa\", \"Terakhir masukkan irisan daun bawang\", \"Sajikan bersama pelengkap dan taburi bawang goreng,boleh ditambah soun / kecambah sesuai selera\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(565, 3, 'Daging Sapi Cah Jamur Pete', 'Daging Sapi Cah Jamur Pete - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"3 siung bawang putih\", \"200 gr daging sapi\", \"50 gr jamur enoki\", \"100 gr pete\", \"1 sdm minyak jagung\", \"2 sdm saus tiram\", \"1/2 sdm lada bubuk\", \"2 sdm tepung maizena\", \"1/3 sdm garam dapur\", \"Air putih\"]', '[\"Potong kecil bawang putih, kemudian tumis dengan minyak jagung, sambil ditambahkan saus tiram dan 50 ml air putih.\", \"Kemudian masukan daging sapi yg sudah dipotong, masak hingga berubah warna dan agak lembut, sambil masukan bumbu garam dan lada.\", \"Setelah daging agak lembut, tambahkan jamur enoki, pete, dan tepung maizena yg dilarutan ke dalam air. Masak hingga mengental.\", \"Jika sudah mengental, cek rasa apakah sudah pas. Jika sudah pas matikan api.\", \"Siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(566, 2, 'Iga Sapi Cah Tahu', 'Iga Sapi Cah Tahu - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"250 gr iga sapi\", \"5 buah tahu\", \"Bumbu\", \"3 rawit merah\", \"3 cabe mersh besar\", \"4 siung bawang putih\", \"2 bawang merah\", \"1 bawang bombay kecil iris2\", \"2 butir kemiri\", \"1 sdm kecap\", \"secukupnya Gula\", \"Garam secukupnya minyak goreng secukupnya\", \"secukupnya Air\", \"Penyedap/ kaldu bubuk\", \"2 lbr daun salam,1 btg sereh geprek\", \"5 cabe hijau besar iris2 serong\"]', '[\"Rebus daging iga sampai empuk angkat dan potong besar kecilnya menurut selera, potong tahu jadi dua serong sisihkan\", \"Uleg duo cabe,duo bawang kemiri sampai halus lalu panasksn minyak goreng masukan bawang bombay sampai harum,lalu bumbu halus aduk masukan dagingnya lalu tahu tambahkan gula garam, kasih air kira2 bumbunya meresap,tambahkan sereh,daun salam tambahkan kecap, penyedap rasa lalu terakhir masukan irisan cabe hijau besar dsn tes rasanya bila sudah pas matikan api dan siap disajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(567, 2, 'Daging Sapi & Brokoli Saus Teriyaki', 'Daging Sapi & Brokoli Saus Teriyaki dengan daging sapi empuk dan bumbu kaya rasa.', '[\"250 gr daging has dalam, iris tipis\", \"1 kuntum brokoli ukuran sedang, siangi\", \"1/2 butir bawang bombay, iris memanjang\", \"4 siung bawang putih, cincang\", \"1 ruas jahe, parut\", \"3 sdm saus teriyaki\", \"1 sdm saus tiram\", \"1 sdm kecap manis\", \"secukupnya gula, garam, lada bubuk\", \"secukupnya air\", \"butter / margarin untuk menumis\"]', '[\"Aduk jadi satu saus teriyaki, saus tiram, kecap manis, bawang putih, dan jahe.\", \"Rendam daging dengan campuran saus, simpan dalam lemari es (minimal 30 menit)\", \"Panaskan margarin, tumis daging sebentar. Tuang sedikit air.\", \"Tambahkan gula, garam, dan lada. Masak hingga daging matang sempurna. Boleh tambahkan air jika air habis tetapi daging belum matang.\", \"Setelah daging matang dan air menyusut, masukkan bawang bombay dan brokoli. Masak sebentar hingga matang\", \"Selamat mencoba! 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(568, 3, 'Sop Daging Sapi (Weekend Special)', 'Sop Daging Sapi (Weekend Special) dengan daging sapi empuk dan bumbu kaya rasa.', '[\"1/4 daging sapi\", \"2 Wortel\", \"2 kentang\", \"1 buah tomat\", \"5 siung bawang merah (Iris)\", \"2 siung bawang putih (iris and geprek)\", \"1 batang saledri & Daun bawang\", \"1/2 potong kayu manis\", \"3 buah cengkeh\", \"1/4 Biji pala (bubuk juga gpp)\", \"Secukupnya lada putih\", \"Secukupnya garam\", \"Secukupnya kaldu sapi\", \"Secukupnya gula\"]', '[\"Bersihkan daging kemudian tiriskan, siapkan panci rebus anti lengket supaya pinggir panci ga hitam dan lengket terkena air rebusan daging. Kemudian panaskan air secukupnya selama 5 menit, setelah itu Masukan daging satu persatu ke dalam panci rebusan\", \"Setelah semua daging masuk kemudian tambahkan sedikit bawang merah iris, bawang putih geprek, 3 buah cengkeh dan 1/4 biji pala kedalam panci rebusan tadi (ala saya supaya daging nya ada berasa sedikit rempah and air rebusan tidak bau), busa2 hasil rebusan di angkat. Rebus 10-15 menit\", \"Sambil menunggu rebusan daging agak empuk, potong2 sesuai selera wortel dan kentang nya. Cuci bersih2 and rendam 1 menit dalam air yg ditaburi sedikit garam.\", \"Tumis Sisa bawang merah, bawang putih, tomat,kayu manis, saledri daun bawang, lanjutkan Masukan kentang dan wortel ke dalam tumisan tadi. Diemkan 30 detik kemudian masukan air aqua(air matang) dan rebus kurang lebih 5 menit.\", \"Kemudian masukkan rebusan daging tadi beserta air kaldu daging yg sudah di saring (ampas nya dibuang), tambahkan garam secukup nya, lada putih sesuai selera serta sedikit gula putih (efek gurih krna tidak pake mecin)\", \"Tumis rebus bersamaan sampe empuk dan skali coba rasa apakah sudah pas untuk campuran nya.\", \"Pindahkan ke dalam mangkok besar dan siap untuk di nikmati bersama Keluarga.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(569, 4, 'Sop bakso sapi', 'Resep Sop bakso sapi ala rumahan yang dijamin menggugah selera.', '[\"5 lembar kol\", \"1 wortel besar\", \"1 bungkus bakso sapi\", \"1 tangkai bawang daun dan seledri\", \"1 siung bawang putih dan merah\", \"Ladaku\", \"Garam\", \"Mssako\"]', '[\"Haluskan bumbu\", \"Siapkan air di atas kompor, masukan bumbu dan bakso\", \"Rebus sampai bakso empuk\", \"Masukan wortel, tunggu beberapa mrnit lalu masukan kol\", \"Tambahkan garam, masako, lada secukupnya, untuk menambah rasa bisa tambahkan garam\", \"Yang terakhir masukan daun bawang dan seledri dan matikan api\", \"Beri bawang goreng untuk menambah aroma wangii....\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(570, 2, 'Dendeng Lemak Sapi', 'Cara membuat Dendeng Lemak Sapi yang enak dan praktis untuk keluarga.', '[\"1/2 kg Daging sapi berlemak/ Daging Rawon\", \"6 siung bawang putih\", \"2 butir kemiri\", \"1 sdm ketumbar bulat\", \"1 sdm garam\", \"1/4 sdt lada bulat\", \"1/2 sdt gula putih\", \"1 sdm kecap manis\", \"3 cm lengkuas\", \"100 ml air\"]', '[\"Potong daging selebar, setebal dan sepanjang 2 ruas jari\", \"Haluskan ketumbar, lada, kemiri, garam dan bawang putih\", \"Tumis bumbu halus, lengkuas sampai harum, masukkan daging, masukkan kecap manis dan gula, aduk hingga rata, tambahkan air, aduk\", \"Masak hingga air menyusut, tes rasa\", \"Dendeng lemak bisa langsung digoreng, atau disimpan di frezer, jadi bisa sewaktu-waktu digoreng buat lauk\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(571, 3, 'Lapis Daging Sapi', 'Lapis Daging Sapi dengan daging sapi empuk dan bumbu kaya rasa.', '[\"1 kg daging sapi potong sesuai selera\", \"30 mL kecap manis\", \"2 L air panas\", \"4 lbr daun salam\", \"Bumbu yang dihaluskan:\", \"10 buah cabe merah\", \"20 buah bawang merah\", \"10 buah bawang putih\", \"2 buah kemiri\", \"1/2 buah pala\", \"2 jari laja/lengkuas\", \"1 jari jahe\", \"1/2 sdt merica bubuk\", \"1/2 sdt ketumbar bubuk\", \"secukupnya Garam\"]', '[\"Tumis semua bumbu hingga matang dan harum. Setelah matang, matikan api nya\", \"Campurkan daging, kecap dan daun salam hingga bumbu benar-benar merata (kalo saya sambil diremas)\", \"Masak kembali daging dgn api kecil dan ditutup. Sesekali bolak balik daging agar tidak gosong\", \"Setelah 10 menit, masukkan air panas dan masak hingga daging empuk\", \"Jika dirasa kurang empuk, mom bisa tambahkan air panas kembali\", \"Angkat dan Sajikan... (Bisa menggunakan panci presto agar lebih cepat empuk)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(572, 2, 'Sop daging/ buntut/ iga sapi spesial full rempah-rempah by mimi', 'Sop daging/ buntut/ iga sapi spesial full rempah-rempah by mimi - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 kg daging/ buntut / iga sapi\", \"3 buah kentang\", \"4 buah wortel\", \"1 btg seledri\", \"1 btg daun bawang\", \"5 siung bawang merah (digeprek)\", \"4 siung bawang putih (digeprek)\", \"1 cm jahe (digeprek)\", \"1 buah pala\", \"2 buah bunga lawang\", \"4 butir kapulaga\", \"1 btg kayu manis\", \"4 btg cengkeh\", \"1 sendok teh lada (bubuk)\", \"secukupnya Garam, Penyedap rasa\", \"Bawang goreng\"]', '[\"Kupas dan cuci bersih semua bahan\", \"Panas kan air hingga mendidih, kemudian masukkan daging / buntut/ iga sapi ke dlm air mendidih tersebut.\", \"Tumis bawang merah & bawang putih yg sudah di geprek hingga harum. Angkat, kemudian masukkan ke dlm rebusan daging.\", \"Masukkan juga bumbu2 lain, seperti jahe yg sudah digeprek, pala, bunga lawang, kapulaga, kayu manis, cengkeh, lada, penyedap rasa + garam. Masak hingga empuk sesuai selera.\", \"Jk tingkat keempukan daging sudah sesuai keinginan, selanjutnya masukkan wortel & kentang dlm masakan daging.\", \"Jk wortel & kentang sudah matang, masukkan irisan daun bawang & seledri dlm masakan, masak sebentar saja.\", \"Koreksi rasa trlebih dahulu, jk telah sesuai silakan unt disajikan. Jgn lupa ditaburi bawang goreng.\", \"Selamat memasaaaaakkk 😉😄\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(573, 3, 'Oseng daging sapi terong tomat', 'Resep praktis Oseng daging sapi terong tomat yang bisa dicoba di rumah.', '[\"1 buah terong ungu\", \"2 ons daging sapi, potong2\", \"1 buah tomat\", \"3 siung bawang putih, geprek, rajang\", \"3 siung bawang merah, rajang\", \"1 cabe merah, buang biji\", \"Daun bawang pre, boleh skip\", \"Garam\", \"Gula\", \"Lada\", \"1 sdm saus tiram\", \"150 ml air\", \"Minyak goreng\"]', '[\"Potong2 daging, bumbui dengan garam, gula, saus tiram. Diamkan minimal 15 menit (di kulkas lebih baik).\", \"Goreng terong hingga matang, sisihkan\", \"Goreng daging hingga setengah matang. Masukkan bawang putih, bawang merah, cabe dan tomat. Tambahkan garam, gula, lada. Koreksi rasa\", \"Masukkan terong dan daun bawang, aduk rata. Apabila tomat sudah layu dan daging matang, Tambahkan air.\", \"Biarkan hingga air menyusut. Test rasa, siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(574, 4, 'Mun Tahu Sapi', 'Cara membuat Mun Tahu Sapi yang enak dan praktis untuk keluarga.', '[\"2 bungkus tofu (tahu Jepang), potong kotak-kotak\", \"200 gram daging sapi giling\", \"2 siung bawang putih, rajang halus\", \"2 cm jahe, rajang halus\", \"secukupnya Lada putih\", \"secukupnya Lada hitam\", \"secukupnya Saus tiram\", \"secukupnya Minyak goreng\", \"secukupnya Minyak wijen\", \"secukupnya Kecap ikan\", \"1 sdt tepung maizena\"]', '[\"Tumis daging sapi giling hingga matang. Aduk rata.\", \"Masukkan lada hitam, jahe dan bawang putih. Aduk rata.\", \"Masukkan tofu, air putih, saus tiram, lada, minyak wijen, dan kecap ikan. Aduk rata.\", \"Tambahkan tepung maizena cair untuk mengentalkan kuah. Aduk rata hingga mendidih. Sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(575, 2, 'Steak sapi ala Cechille', 'Resep Steak sapi ala Cechille ala rumahan yang dijamin menggugah selera.', '[\"200 gram daging sapi( saya potong jadi dua\", \"Lada hitam\", \"Garam\", \"Butter\", \"Daun parsley\", \"Tomat\", \"Mayonise\", \"Tabasko\", \"Saus sambal\"]', '[\"Cuci daging sapi yang sudah di potong jadi dua\", \"Lumuri daging dengan lada hitam dan garam.diamkan 5 menit saja. Terus panggang daging sapi di atas teplon dengan butter dan jangan lupa apinya harus besar ya.Setelah selesai lalu rebus kentang kasih garam setelah airnya sedikit kentangnya di lempar ke atas ke bawah agar meresap dan terasa enak.setelah airnya habis matikan api dan goreng sampai matang.untuk saus nya pakai mayonise dan saos sambal di campur jangan lupa pakai tabasko agar enak. Steak nya rias ya mudah bukan😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(576, 4, 'Bakso Sapi Goreng', 'Bakso Sapi Goreng - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"150 gram daging sapi giling\", \"1/2 cup tepung sagu\", \"3 siung bawang putih (cincang halus)\", \"1 siung bawang merah (cincang halus)\", \"1 sdt garam\", \"1/2 sdt gula\", \"1/2 sdt lada\", \"1 sdm minyak\", \"1 sdm air dingin\"]', '[\"Campurkan semua bahan. Uleni.\", \"Bentuk bulat dan goreng dengan api kecil selama 15 menit sambil diaduk.\", \"Bakso sapi goreng siap dihidangkan ditemani saus sambal. Yummy.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(577, 2, 'Sapi Teriyaki', 'Resep Sapi Teriyaki ala rumahan yang dijamin menggugah selera.', '[\"250 g daging sapi has dalam (iris tipis)\", \"1 sdm saus teriyaki\", \"1 sdm tepung sagu\", \"2 bh bawang putih\", \"1 bh bawang bombay\", \"400 g labu air\", \"1 bh daun bawang (iris serong)\", \"1 sdm kecap manis\", \"1 sdm angciu\", \"secukupnya gula, garam dan lada\", \"seujung jahe geprek\"]', '[\"Marinate daging sapi dengan saus teriyaki dan tepung sagu (diamkan sekitar 15 menit)\", \"Tumis bawang putih, jahe dan daun bawang sampai wangi. masukkan daging sapi, aduk sampai berubah warna\", \"Beri air secukupnya, tutup sampai mendidih, masukkan labu air dan bumbu lainnya (kecuali daun bawang), tutup lagi. tunggu sampai labu air lunak. koreksi rasa. masukkan daun bawang. angkat, sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(578, 3, 'Gulai tunjang (gulai kaki sapi)', 'Resep praktis Gulai tunjang (gulai kaki sapi) yang bisa dicoba di rumah.', '[\"1/4 kaki sapi\", \"500 gr santan\", \"Bumbu halus :\", \"1 ruas lengkuas\", \"1 ruas jahe\", \"1 ruas kunyit\", \"3 butir kemiri\", \"5 siung bawang merah\", \"1 siung bawang putih\", \"1 ons cabe merah keriting\", \"Secukupnya garam\", \"Pelengkap :\", \"2 lembar daun salam\", \"1 lembar daun kunyit\", \"2 buah asam kandis\", \"1 batang serai, geprek\"]', '[\"Didihkan air masukkan tunjang/kaki sapi, beri garam. Didihkan kembali kecilkan api, masak hingga tunjang agak empuk. Angkat sisihkan.\", \"Haluskan bumbu. Masukkan bumbu dalam air sisa rebusan tunjang, tambahkan santan dan pelengkap, didihkan. Setelah mendidih masukkan tunjang kedalam bumbu, masak hingga bumbu meresap dan tunjang empuk. Koreksi rasa. Jika sudah okey... angkat sajikan.\", \"Sajikan... hmmmm sedapnya... gak cukup 1 potong nih... 😂\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(579, 3, 'Tumis kikil / kulit / kaki sapi \"sunda rasa\"', 'Resep praktis Tumis kikil / kulit / kaki sapi \"sunda rasa\" yang bisa dicoba di rumah.', '[\"600 gr kaki sapi (kmrn beli kaki 1,5kg pas bikin mie kocok)\", \"secukupnya air\", \"3 siung bawang putih\", \"3 siung bawang merah\", \"1 cm kunyit iris\", \"1 siung bawang bombay\", \"secukupnya daun bawang\", \"3 batang serai geprek\", \"2 cm jahe geprek\", \"secukupnya gula merah, garam, kecap manis\", \"1 sachet saos tiram\", \"minyak secukupnya untuk menumis\"]', '[\"Didihkan air, masukan kaki sapi lalu cuci bersih lagi.. kemudian didihkan lagi kurleb 30 menit tambahkan serai geprek. sisihkan\", \"Tumis semua bumbu kecuali daun bawang sampai harum\", \"Masukan kaki dan air kaldunya boleh ditambahkan air lagi biar bisa lebih empuk lagi\", \"Tambahkan gula merah, garam, saus tiram, kecap, merica tes rasa lalu biarkan sampai empuk meresap\", \"Setelah kuah berkurang masukan daun bawang, aduk\", \"Siap dihidangkan.. saya makan dengan acar nanas timun. segeerr\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(580, 3, 'Homemade beef pizza', 'Hidangan daging sapi istimewa: Homemade beef pizza.', '[\"250 gr tepung terigu cakra\", \"6 gr ragi\", \"1/2 sdt gula\", \"1/2 sdt garam\", \"1 sdt minyak zaitun atau 40gr mentega\", \"15 gr susu bubuk\", \"150 ml air hangat kuku\", \"1 butir telur utuh\", \"Topping:\", \"Saus bolognese siap pakai\", \"Smoke beef\", \"Beef sausage\", \"Bawang bombay iris tipis\", \"Keju cheddar\", \"Keju mozarella\", \"Mayonaise\", \"Saus tomat\"]', '[\"Campurkan ragi, gula dan sedikit air hangat. Tunggu sampai berbuih tanda ragi aktif, +/- 10 menit.\", \"Masukkan tepung terigu, susu dan telur utuh. Uleni hingga setengah kalis. Kemudian masukkan mentega/minyak zaitun, uleni lagi. Terakhir masukan garam. Uleni hingga benar2 kalis.\", \"Buat bulatan. Diamkan 45 menit sampai dgn 1 jam, hingga adonan mengembang 2x lipat.\", \"Kempiskan adonan dgn cara dipukul utk mengeluarkan udara di dalam adonan. Bentuk adonan di dalam loyang yg sdh diolesi mentega. Tusuk2 adonan agar tidak bergelembung ketika dipanggang. Diamkan 10 menit.\", \"Beri topping suka suka. Selain topping yg saya sebutkan di resep, kdg saya tambahkan paprika, jamur, pepperoni etc. Suka suka aja hehehe.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(581, 3, 'Daging sapi cincang cah cabe hijau/paprika dan jagung muda', 'Resep praktis Daging sapi cincang cah cabe hijau/paprika dan jagung muda yang bisa dicoba di rumah.', '[\"250 gr daging sapi giling\", \"1 buah paprika hijau ukuran sedang potong memanjang, buang biji\", \"8 buah jagung muda potong serong\", \"3 siung bawang putih cincang halus\", \"1/2 buah bawang bombay (alt.) saya tdk pakai\", \"2 sendok teh tausi\", \"2 sendok makan saus tiram (sy pake cap panda)\", \"1 ruas jahe iris2 (jgn terlalu banyak krn nanti rasanya jd dominan)\", \"secukupnya Kecap asin\", \"secukupnya garam, gula, lada, penyedap\", \"Minyak goreng untuk menumis\", \"1/2 sendok teh sagu diaduk dengan air 4-5 sendok makan\", \"1 sendok teh minyak wijen (jgn kebanyakan)\"]', '[\"Agar makannya mudah, saya rebus dahulu paprika dan jagung muda yg sdh diiris krg lebih 5 menit dr air mendidih. Tutup\", \"Sambil menunggu rebusan empuk, daging giling dibumbui, kasi garam, lada, kecap asin dan saus tiram secukup nya. Diamkan kurleb 5-10 menit. (Boleh jg ga usah didiamkan)\", \"Panaskan minyak goreng, masukan bawang putih cincang tumis hingga harum tp jgn terlalu kering\", \"Masukan daging giling yg sdh meresap, oseng2, jika sdh agak berubah warna masukan tausi lalu paprika dan jagung muda yg sdh ditiriskan.\", \"Kasi bumbu, garam, gula, lada dan penyedap\", \"Masukan air sagu, aduk2 agar mengental. Jika krg kuah bs tambahkan air sedikit. Lalu tes rasa. Simple dan mudah. Selamat mencoba. 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(582, 3, 'Tongseng sapi pedas', 'Hidangan daging sapi istimewa: Tongseng sapi pedas.', '[\"1/2 kg daging sapi\", \"1/4 kg paru sapi\", \"1/4 kg hati sapi\", \"sesuai selera Garam\", \"Gula merah\", \"Kecap manis\", \"1 sachet santan kara\", \"Bumbu halus :\", \"10 btr kemiri\", \"5 siunh bawang merah\", \"5 siung bawang putih\", \"1 ruas jahe\", \"1 ruas kunyit\", \"1 sdt lada hitam\", \"5 bj bunga lawang\", \"5 bj kapulaga\", \"1 sdt merica bubuk\", \"Bumbu utuh :\", \"2 btg serai\", \"1 sdm cengkeh\", \"1 potong kayu manis\", \"Daun salam daun jeruk\", \"Pelengkap : kol, tomat\"]', '[\"Presto daging sapi, sisihkan brsama kaldunya\", \"Rebus sampai empuk sendiri2 paru dan hati, buang airnya\", \"Tumis bumbu halus, masukkan daging, paru dan hati sapi yg telah di presto.\", \"Tambahkan air kaldu dari daging\", \"Masukkan bumbu utuh cengkeh kayu manis sereh dan daun salam jeruk,\", \"Masukkan santan kara, garam,gula merah dan kecap. Manis. Tunggu hingga bumbu meresap\", \"Masukkan tomat\", \"Terakhir masukkan kol. Atau kol Dipisah.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(583, 4, 'Daging sapi jagung wortel bumbu saos tiram', 'Resep praktis Daging sapi jagung wortel bumbu saos tiram yang bisa dicoba di rumah.', '[\"1/4 Daging sapi (sudah di cincang dan di bentuk memanjang)\", \"1 buah wortel di potong memanjang\", \"1 buah jagung manis di serut\", \"2 siung bawang merah\", \"4 siung bawang putih\", \"Penyedap rasa secukupny\", \"1 sdm saori saos tiram\", \"2 sdm saos tomat\", \"2 sdm saos sambal\", \"1 sdm kecap manis\", \"Sejumput gula putih\"]', '[\"Goreng daging api kecil hingga coklat keemasan\", \"Iris bawang merah, bawang putih dan wortel\", \"Angkat daging yang sudah di goreng, panaskan minyak dengan api sedang, tumis bawang putih dan bawang merah sampai harum\", \"Masukan wortel dan air secukupnya,aduk sampai tekstur wortel setengah matang\", \"Masukan saori, saos tomat, saos sambal, kecap,gula putih dan penyedap rasa\", \"Masukan daging dan jagung tes rasa\", \"Taraaaaaa.. Masakan simple tapi enak siap di hidangkan dengan nasi panas😍😍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(584, 2, 'Empal daging sapi & paru goreng', 'Cara membuat Empal daging sapi & paru goreng yang enak dan praktis untuk keluarga.', '[\"1/2 kg daging sapi\", \"1/2 kg paru sapi\", \"1 buah kelapa santan ukuran besar\", \"1 sdm ketumbar\", \"5 butir kemiri\", \"5 siung bawang merah\", \"4 siung bawang putih\", \"1 cm jahe\", \"3 btg serai\", \"4 lbr daun salam\", \"1 bks kecil asam kandis\"]', '[\"Cuci bersih daging & paru dicampur garam cucinya agar menghilangkan darah nya\", \"Ulek bumbu halus kecuali serainya di geprek\", \"Tuang santan kelapa encernya dulu aduk2\", \"Masukkan bumbu halus.. Serai.. Daun salam & asam kandis\", \"Sambil terus diaduk bumbu nya masukkan daging & paru sapi\", \"Tuangkan lagi santan kental nya\", \"Sambil diaduk agar tidak lengket dibawahnya\", \"Masak daging & paru sapi sampai sat santan nya\", \"Bila sudah sat santannya angkat daging & paru sapi ke wadah lain\", \"Geprek2 daging & paru sapi\", \"Bila sudah digeprek semuanya.. Simpan dikulkas\", \"Tapi kalo mau langsung di goreng juga gapapa sih 😅😅\", \"Setelah digoreng taburkan bawang goreng diatasnya..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(585, 4, 'Galantin daging sapi', 'Resep Galantin daging sapi yang lezat dan mudah dibuat di rumah.', '[\"150 gram daging sapi giling\", \"100 gram daging ayam giling\", \"75 gram tepung panir\", \"2 butir telor\", \"1/2 merica\", \"1 sdm gula pasir\", \"2 siung bawang putih\", \"1 sdm tepung maizena\"]', '[\"Campurkan semua bahan galantin kedalam wadah\", \"Test rasa dengan menggoreng secuil adonan n cicipin rasa\", \"Bagi adonan menjadi dua bagian bungkus dengan daun pisang/ plastik, membentuk dengan adonan memanjang seperti lontong besar\", \"Kukus galantin kurang lebih 30 menit hingga mateng,angkat n dinginkan\", \"Buka bungkusny lalu potong potong sesuai selera\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(586, 4, 'Homemade Beef Burger', 'Nikmati kelezatan Homemade Beef Burger dengan resep sederhana ini.', '[\"Patty:\", \"1/2 kg daging sapi giling\", \"1 bh bawang bombay\", \"1 sdm bbq sauce\", \"1/2 sdt garam\", \"1/2 sdt merica\", \"2 sdm tepung roti\", \"50 cc susu cair\", \"Pelengkap:\", \"slice Cheese cheddar\", \"Selada\", \"Tomat\", \"Mayonnaise\", \"Saus tomat/bbq\", \"Burger bun (beli jadi)\"]', '[\"Campur tepung roti dgn susu cair. Biarkan tepung roti melunak.\", \"Campur daging giling, bawang bombay cincang, bbq sauce, garam, merica dan tepung roti. Aduk sampai rata.\", \"Bagi menjadi 4 patty. Ambil 1 bagian, bentuk bulat kemudian pipihkan. Kalau mau lebih padat bisa dilempar2 ke telapak tangan supaya udaranya hilang.\", \"Panaskan wajan teflon, beri sedikit butter. Letakkan patty di atas wajan, masak dengan api sedang +- 5mnt. Balik, masak sisi yg lain +- 5 menit juga. Jangan ditekan2 nanti jusnya keluar dari patty.\", \"Angkat, resting +- 5 menit. Susun dengan bahan pelengkap yg lain. Siap dinikmati 👌🏼\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(587, 3, 'Pizza Beef Mozarella Teflon', 'Hidangan daging sapi istimewa: Pizza Beef Mozarella Teflon.', '[\"Adonan :\", \"10 Sdm Terigu protein tinggi (saya Cakra Kembar)\", \"1 Sdm Mangarin (saya Blue Band)\", \"1 Sdm Minyak sayur\", \"1/2 Sdt Garam\", \"1/2 Sdt Baking soda\", \"1/2 Sdt Permifan\", \"75 Ml Air Panas (saya air dispenser)\", \"Topping :\", \"3 Lembar Daging sapi burger (diganti sesuai selera)\", \"100 Gr Keju mozarella iris tipis (saya Greenfields)\", \"2 Sdm Saus tomat (sesuai selera)\", \"2 Sdm Saus cabai (sesuai selera)\", \"1 Buah Bawang bombai iris\", \"Memasak pizza:\", \"1/2 Sdm Margarin\", \"Menumis daging :\", \"1 Sdm Minyak sayur\"]', '[\"Masukan semua bahan adonan ke wadah, aduk dan uleni sampai kalis\", \"Tutup adonan dengan plastik wraping atau lap dan diamkan 30 menit\", \"Tumis daging yang sudah di iris selama 2-3 menit, sisihkah\", \"Balur wajan dengan margarin\", \"Bentuk adonan menjadi lingkaran tipis seukuran wajan, tusuk2 dengan garpu di setiap permukaan\", \"Balur dengan saus tomat dan cabai\", \"Taburkan daging dan bawang bombai\", \"Tutup permukaan dengan lembaran mozzarella\", \"Masak selama 25 menit dengan api kecil hampir padam dan tutup dengan penutup wajan\", \"Setelah matang iris pizza menjadi beberapa bagian dan siap dinikmati\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(588, 4, 'Brokoli Cah Sapi', 'Resep praktis Brokoli Cah Sapi yang bisa dicoba di rumah.', '[\"150 gr daging sapi (aku pake bagian inside)\", \"1 buah brokoli\", \"1/2 bawang bombay - cincang kasar\", \"5 siung bawang putih - cincang halus\", \"3 cm jahe - iris tipis\", \"2 sdm larutan tepung maizena\", \"2 sdm saus tiram\", \"5 buah cabe rawit merah - iris\", \"100 gram jamur merang\"]', '[\"Iris daging sesuai selera. kemudian rebus sampai keluar air dagingnya, tunggu sampai tiris, setelah tiris, tambahkan lagi 1 gelas air panas. Rebus lagi sampai tiris kembali. (Sisakan sedikit air daging utk kaldu). Kemudian tumbuk daging dengan ulekan agar daging empuk.\", \"Rebus brokoli dengan air garam selama 4 menit. Kemudian angkat, masukan langsung ke air es batu. Diamkan.\", \"Iris jamur merang sesuai selera. Kemudian cuci, dan rebus dengan air garam selama 5 menit.\", \"Tumis bawang bombay, bawang putih, jahe, aduk sbentar, baru masukan jamur merang. Aduk lagi sampai bawang berwarna keemasan.\", \"Masukan daging, dan masukan air yg habis dipakai rebus brokoli tadi sebanyak setengah gelas. Aduk lg. Masukan saus tiram, cabe rawit merah iris dan kaldu daging. Tambah kan garam lada merica kemudian saus tiram.\", \"Baru masukan brokoli. Aduk2 lagi, kemudian masukan larutan tepung maizena. Masak lg sbentar, tes rasa. Jadi deh.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(589, 3, 'Buncis tumis daging sapi', 'Buncis tumis daging sapi - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"200 gr daging sapi has, potong2\", \"1 ikat buncis, potong2\", \"1 sdm maizena\", \"1 btr bawang bombay, iris\", \"3 siung bawang putih, cincang\", \"1 ruas jahe, iris\", \"2 sdm saus tiram\", \"2 sdm kecap manis\", \"secukupnya merica, garam, air panas\"]', '[\"Balur daging saus tiram, kecap manis, merica, maizena aduk jadi satu diamkan sebentar\", \"Tumis.bawang putih, bawang bombay, jahe sampai wangi\", \"Masukkan daging, aduk rata, biarkan sebentar, tambahkan air panas secukupnya, masak hingga daging empuk, masukkan buncis, garam, koreksi rasa\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(590, 4, 'Asem-asem iga sapi', 'Resep Asem-asem iga sapi yang lezat dan mudah dibuat di rumah.', '[\"500 gram iga sapi\", \"5 buah bawang merah\", \"3 siung bawang putih\", \"1 buah bawang bombai kecil\", \"3 buah cabe ijo besar\", \"2 buah cabe merah besar\", \"3 buah cabe rawit merah (dipotong2)\", \"3 buah tomat yg mengkal\", \"1 genggam cabe rawit (utuh)\", \"2 cm lengkuas\", \"2 sdm minyak goreng\", \"secukupnya gula & garam\", \"1 sdt lada bubuk\"]', '[\"Cuci bersih iga sapi, rebus kurang lbh 5 - 10 menit, matikan api, angkat, buang airnya, cuci lg.\", \"Rebus lg iga sapi dg 2 liter air sampai empuk.\", \"Sementara itu tumis semua bumbu yg sdh dipotong2 tipis. Tumis hingga bau langunya hilang & masukkan ke dlm rebusan daging iga. Tambahkan cabe rawit utuh.\", \"Tambahkan gula, garam, merica bubuk. Tes rasa. Masak hingga mendidih.\", \"Setelah itu kecilkan api kompor & lanjut masak kurang lbh 15 menit agar bumbu meresap ke dlm daging iga.\", \"Angkat & siap dihidangkan hangat. Yuumm.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(591, 2, 'Presto tulang sapi bakso dan hati sapi bumbu semur', 'Hidangan daging sapi istimewa: Presto tulang sapi bakso dan hati sapi bumbu semur.', '[\"1 tempat tupperware bakso tulang sapi plus kuah bakso\", \"200 gram hati sapi\", \"1 batang serai geprek\", \"2 buah bunga pala\", \"2 biji cengkeh\", \"1 lembar kayu manis\", \"Sedikit jinten hitam\", \"1 ruas jahe geprek\", \"1 ruas lengkuas geprek\", \"Bumbu halus:\", \"7 siung bawang merah\", \"5 siung bawang putih\", \"6 buah cabe merah besar\", \"6 buah chili padi\", \"1 bungkus kerisik\", \"3 buah kemiri\", \"1 sdt ketumbar bubuk\", \"Secukupnya garam dan penyedap\", \"Secukupnya kecap\", \"Secukupnya air\", \"Sedikit minyak menumis\", \"200 ml santan ayam brand\"]', '[\"Siapkan semua bahan. Cuci bersih dan sisihkan.\", \"Potong2 bumbu lalu blender sampai halus. Kemudian panaskan kuali dan tumis semua bumbu hingga harum.\", \"Masukkan bumbu dalam presto yang sudah ada kuah bakso tulang dan juga hati. Kemudian aduk rata.\", \"Tutup presto dan nyalakan api besar.setelah berbunyi desis dan berputar dari lubang presto. Maka kecilkan api. Dan tunggu presto selama kurang lebih 20 menit.\", \"Masakan siap disantap.jangan lupa cicipi terlebih dahulu.biar makin eundeuss...😉😉😉\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(592, 4, 'Oseng sawi asin daging sapi', 'Oseng sawi asin daging sapi dengan daging sapi empuk dan bumbu kaya rasa.', '[\"Bahan :\", \"3 ikat sawi asin\", \"100 gram daging sapi, iris tipis\", \"10 buah cabai rawit\", \"5 butir bawang merah\", \"3 butir bawang merah\", \"secukupnya Garam, gula, merica, kecap manis dan saus tiram\"]', '[\"Potong2 sawi asin, sisihkan\", \"Iris bawang merah, bawang putih dan cabai\", \"Tumis bawang merah dan bawang putih sampai harum\", \"Masukkan irisan daging sapi tuang sedikit air\", \"Masukkan sawi asin dan irisan cabai\", \"Beri garam, gula pasir dan merica secukupnya\", \"Tuang kecap manis dan saus tiram\", \"Cicipi dan siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(593, 4, 'Sup Iga Sapi', 'Nikmati kelezatan Sup Iga Sapi dengan resep sederhana ini.', '[\"500 gr tulang iga sapi\", \"2 buah wortel\", \"1 buah kurma kering\", \"4 buah jamur kering, rendam lalu iris panjang\", \"secukupnya Daun seledri\", \"secukupnya Garam\", \"Penyedap bila suka (sya tidak pakai)\"]', '[\"Cuci bersih tulang iga lalu potong\\\", titiskan...masak air -+2 liter sampai mendidih masukkan semua bahan rebus selama 2 jam tambahkan garam.tes rasa terakhir masukkan seledri.siap disajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(594, 2, 'Bakso sapi blender + kuah', 'Bakso sapi blender + kuah dengan daging sapi empuk dan bumbu kaya rasa.', '[\"500 gram daging sapi tanpa lemak\", \"150 gram es batu, hancurkan\", \"bisa juga menggunakan air es super dingin)\", \"50 ml putih telur\", \"3 siung bawang putih, iris tipis, digoreng\", \"3-5 siung bawang putih, haluskan\", \"2 sdt garam (15 gram)\", \"1/2 sdt soda kue (bisa juga baking powder)\", \"100 gram tepung sagu tani/tapioka\", \"Air dalam panci untuk merebus bakso\", \"Bahan kuah :\", \"3000 ml air\", \"300 gr tulang sapi (bagian lutut)\", \"200 gr tetelan sapi\", \"Garam,merica,kaldu sapi bubuk (masako)\", \"Daun seledri dan daun bawang besar\", \"3 siung bawang putih,goreng lalu keprak\", \"2 sdm bawang merah goreng\"]', '[\"Bakso : Potong-potong daging agar lebih mudah dihaluskan. Masukkan dalam blender daging atau food processor (FP) beri setengah bagian es batu. Giling hingga halus. Masukkan putih telur, bawang putih goreng, bawang putih halus, garam dan sisa es batu. Giling lagi hingga benar-benar halus.\", \"Masukkan tepung sagu tani/tapioka dan soda kue (atau baking powder), giling lagi hingga menjadi adonan pasta yang lembut dan mulus.\", \"Didihkan air dalam panci untuk merebus. Setelah mendidih, matikan api (atau pakai api yang kecil sekali agar air jangan bergolak mendidih cukup hanya panas saja).\", \"Ambil segenggam adonan bakso kemudian kepalkan tangan dan tekan jemari hingga adonan menyembul keluar dari sela ibu jari dan telunjuk, celupkan sendok ke air (tujuannya agar sendok tidak lengket ke adonan) kemudian angkat bulatan adonan dengan sendok dan masukkan ke dalam air panas dalam panci. Lakukan hingga adonan habis. Biarkan bakso sampai mengambang, kemudian nyalakan/besarkan sedikit apinya dan masak kembali dengan air mendidih kecil selama 5 menit agar bakso matang sempurna.\", \"Siapkan air dingin dalam wadah/baskom, angkat bakso yang sudah matang dari panci dan masukkan ke dalam air dingin. Biarkan hingga dingin. Tiriskan dan bakso siap dipakai.\", \"Bakso fresh tanpa pengawet hanya tahan seharian saja di suhu ruang, tahan seminggu dalam suhu kulkas/chiller dan tahan hingga 2-3 bulan dalam suhu beku/freezer\", \"Cara membuat kuah bakso : Rebus semua bahan minimal 90 menit dengan api kecil,cicipi dan koreksi rasa. Angkat dan sisihkan.\", \"Sajikan bakso bersama kuah,mie kuning,mie putih,daun bawang,sawi,bawang goreng,kecap,sambal rawit,saos tomat,saos sambal..mantapp!!\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(595, 3, 'Beef teriyaki ala ho*kben', 'Sajian Beef teriyaki ala ho*kben yang praktis dan lezat untuk dinikmati bersama.', '[\"Daging sapi seperempat\", \"2 bawang putih\", \"1 cm jahe\", \"Merica (saya pake ladaku)\", \"Saos teriyaki\", \"Kecap manis\", \"Garam\", \"1/2 bawang bombay\"]', '[\"Iris daging sapi tipis2, campurkan bawang putih dan jahe yg sudah d parut, garam, merica, saos teriyaki 3 sendok makan, kecap manis 2 sendok makan, aduk rata, diamkan 1,5 jam..\", \"Panaskan minyak, masukkan daging yg sudah d campur dengan bumbu.. Tunggu berubah warna kemudian masukkan air agar daging matang sempurna secukupnya..\", \"Tes rasa, waktu sudah d masukkan air saya tambahkan lagi merica, saos teriyaki dan kecap manis karena menurut saya rasanya kurang..\", \"Tunggu hingga air menyusut..\", \"Masukkan bawang bombay yg sudah d iris tipis, aduk2 sebentar sampai bawang bombay layu..\", \"Siap disajikan :)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(596, 4, 'Nasi Kebuli Sapi Magic com', 'Nasi Kebuli Sapi Magic com dengan daging sapi empuk dan bumbu kaya rasa.', '[\"3 cup beras *saya pakai beras perak\", \"1/4 kg daging sapi pilih yang mudah empuk&potong dadu\", \"3 sdm margarine\", \"1 bks bumbu kare instan\", \"3 ruas jari kayu manis\", \"Secukupnya air *saya pakai air kaldu rebusan daging\", \"3 sdm bubuk kari\", \"Bumbu Halus:\", \"4 siung bawang putih\", \"6 butir bawang merah\", \"1 ruas jari kunyit\", \"1/2 sdt merica bubuk\", \"1 sdt ketumbar bubuk\", \"Pelengkap:\", \"Telur dadar\", \"Irisan timun\", \"Kerupuk emping\", \"Sambel\"]', '[\"Cuci bersih daging kemudian rebus hingga mendidih buang air rebusan nya&bilas hingga bersih kemudian rebus kembali hingga daging empuk,sisihkan\", \"Panaskan margarine tumis bumbu halus hingga harum\", \"Tambahkan bubuk kari,kayu manis&bumbu kari instan aduk rata\", \"Kemudian masukan daging beserta air rebusan nya\", \"Masak hingga bumbu meresap ke daging\", \"Campurkan tumisan daging dengan beras yang telah di cuci aduk rata kemudian tekan tombol cook magic com di tengah proses memasak aduk nasi supaya bumbu nya merata *untuk takaran air nya bisa di sesuaikan seperti kita memasak nasi biasa\", \"Begini penampakan nasi setelah matang\", \"Sajikan nasi kebuli dengan pelengkap 😊\", \"Nb:bila tidak punya bubuk kari bisa kita siap kan sendiri rempah pengganti blender hingga halus 👉 2 butir pekak/bunga lawang,2 buah kapulaga ambil biji nya saja,5 butir cengkeh,1/2 sdt jintan,2 sdt kayu manis bubuk\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(597, 3, 'Asem Asem Buncis Daging Sapi', 'Buat Asem Asem Buncis Daging Sapi yang nikmat dengan langkah-langkah mudah ini.', '[\"300 gr Buncis\", \"300 gr Daging Sapi (bagian Blade, minta iris tipis)\", \"1/2 buah Wortel, potong korek (saya pakai wortel yg import, jadi besar)\", \"5 siung Bawang Merah, iris\", \"3 siung Bawang Putih, iris\", \"6 buah Cabe Merah Keriting, iris\", \"4 cm Lengkuas, geprek\", \"4 lembar Daun Salam\", \"4 buah Belimbing Wuluh, iris\", \"1 sdt Air Jeruk Nipis\", \"Garam\", \"Gula\", \"Kaldu Jamur\", \"Kecap Manis\", \"Bawang Goreng (untuk taburan)\", \"Air\"]', '[\"Tumis duo bawang, cabe, lengkuas dan daun salam sampai layu\", \"Masukkan daging, masak hingga berubah warna\", \"Masukkan belimbing wuluh dan wortel, aduk rata. Tambahkan air jeruk nipis, garam, gula, kaldu jamur dan kecap. Koreksi rasa\", \"Masukkan buncis. Aduk sebentar, tambahkan air. Masak hingga matang\", \"Hidangkan dengan taburan bawang goreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(598, 4, 'Kalio Hati Sapi Simple', 'Kalio Hati Sapi Simple - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"500 gr hati sapi\", \"5 siung bawang merah\", \"4 siung bawang putih\", \"5 butir kemiri\", \"3 cabe rawit atau sesuai selera\", \"1 ruas jahe\", \"1 ruas lengkuas\", \"2 lembar daun salam\", \"1 sdt lada bubuk\", \"Secukupnya garam, gula dan kaldu jamur\"]', '[\"Cuci bersih hati sapi, buang air rebusan pertama. Ganti air lagi dan rebus hingga matang. Tiriskan. Setelah dingin, potong sesuai selera.\", \"Blender semua bumbu kecuali daun salam. Tumis hingga harum, masukkan daun salam, tambahkan air.\", \"Masukkan hati sapi, tambahkan air lagi. Tutup wajan hingga bumbu meresap dan air menyusut. Masukkan santan, lada bubuk, garam, gula dan sedikit kaldu jamur. Aduk rata. Masak hingga semua bumbu meresap dan kuah mengental. Angkat dan sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(599, 4, 'Sapi Lada Hitam (Beef Blackpepper)', 'Hidangan daging sapi istimewa: Sapi Lada Hitam (Beef Blackpepper).', '[\"250 gr daging sapi has dalam, iris tipis berlawanan dengan serat\", \"3 bh bawang putih, cincang halus\", \"2 bh bawang merah, cincang halus\", \"1/2 bh bawang bombay, iris tipis\", \"1/2 bh paprika merah (dapat diganti cabe merah), iris memanjang\", \"1/2 bh paprika hijau (dapat diganti cabe hijau), iris memanjang\", \"Secukupnya lada hitam (bubuk/butiran)\", \"Secukupnya air matang (lebih baik menggunakan kaldu sapi)\", \"Bahan marinasi:\", \"7 sdm saos tiram\", \"2 sdm kecap asin\", \"2 sdm kecap manis\", \"Secukupnya lada hitam bubuk\"]', '[\"Rebus daging sapi dengan api sedang hingga empuk (simpan kaldu sapi untuk bahan tumis)\", \"Lumuri daging sapi yang telah direbus dengan bahan marinasi. Lalu diamkan 1-2 jam (lebih baik lagi semalaman) dan simpan di dalam kulkas\", \"Setelah daging sapi di marinasi, tumis bawang putih dan bawang merah hingga berbau sedap\", \"Masukkan daging yang telah dimarinasi dan diikuti dengan air sedikit demi sedikit\", \"Diamkan hingga air mengental\", \"Masukkan bawang bombay, paprika merah, paprika hijau, dan lada hitam. Kemudian aduk-aduk hingga tercampur rata\", \"Cicipi dan koreksi rasa\", \"Sapi lada hitam siap dihidangkan ditengah keluarga ❤\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(600, 3, 'Daging Sapi Tumis Bawang Bombay', 'Nikmati kelezatan Daging Sapi Tumis Bawang Bombay dengan resep sederhana ini.', '[\"250 gram daging sapi (tanpa lemak)\", \"5 siung bawang putih\", \"6 siung bawang merah\", \"6 buah cabe merah\", \"1 buah bawang bombay\", \"1/2 buah tomat\", \"4 sdm kecap manis\", \"2 sdm saos tiram\", \"1 sdm merica\", \"1 buah jeruk nipis\", \"secukupnya Garam\", \"secukupnya Air\", \"Minyak sayur (saya menggunakan minyak zaitun)\"]', '[\"Baluri daging sapi yang telah dipotong dengan jeruk nipis selama 1 jam\", \"Goreng daging sapi (jangan terlalu kering), lalu tiriskan\", \"Tumis bawang merah, bawang putih, dan bawang bombay yang telah diiris-iris hingga harum\", \"Masukkan cabe merah yang telah diiris memanjang\", \"Masukkan tomat yang telah diiris\", \"Tambahkan air secukupnya, tunggu hingga mulai mendidih\", \"Masukkan daging sapi goreng\", \"Tambahkan kecap manis, saos tiram, dan garam\", \"Tutup kuali dan biarkan bumbu meresap pada daging\", \"Terakhir, tambahkan merica dan aduk kembali masakkan\", \"Koreksi rasa, lalu hidangkan pada mangkuk atau piring\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(601, 4, 'Beef teriyaki plus tofu+salad', 'Buat Beef teriyaki plus tofu+salad yang nikmat dengan langkah-langkah mudah ini.', '[\"200 gr daging sapi, potong tipis memanjang\", \"3 buah tahu (1 tahu potong jadi 3)\", \"1 buah wortel besar (parut pake parutan yg model korek api)\", \"1/4 kubis (iris tipis memanjang)\", \"2 bks saori teriyaki\", \"2 sdm kecap manis\", \"1 sdm kecap asin\", \"secukupnya Garam gula merica bubuk\", \"200 ml air\", \"secukupnya Mayonaise\", \"1/2 bks tepung sajiku\", \"2 siung bawang putih geprek\", \"1/2 siung bawang bombay besar iris tipis\", \"1/2 sdm tepung maizena, beri sedikit air (utk pengental)\"]', '[\"Rendam daging dengan 1sdm kecap manis (1sdm nya buat dikuah nanti), kecap asin, garam dan merica secukupnya. Diamkan 30 menit biarkan meresap.\", \"Cuci bersih wortel dan kubis yang sdh dipotong2, rendam dengan air garam 15 menit. Bilas dengan air matang 2x. Lalu campur mayonaise sesuai selera, Sisihkan.\", \"Larutkan tepung sajiku dgn air (biarkan agak kental), masukkan tahu lalu goreng. Setelah tahu matang, sisihkan.\", \"Tumis bawang putih dan bawang bombay hingga wangi dan layu. Masukkan daging yg sdh direndam tadi. Biarkan beberapa saat sampai minyaknya keluar dan berubah warna.\", \"Masukkan air, saos teriyaki, kecap manis, garam, gula, merica bubuk lalu aduk rata. Biarkan sampai mendidih dan daging benar2 matang.\", \"Setelah daging benar2 matang, jangan lupa koreksi rasa dan tambahkan bila ada yg kurang. Jika sdh pas, masukkan larutan maizena. Aduk rata hingga kuah mengental.\", \"Matikan kompor dan siap disajikan dengan nasi hangat 😍😍. Selamat mencoba!!\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(602, 2, 'Nasi daging sapi bumbu bawang', 'Nasi daging sapi bumbu bawang - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 porsi nasi\", \"75 gr daging sapi has dalam, iris tipis memotong serat\", \"1 bawang bombay kecil, iris iris\", \"1 siung bawang putih\", \"1 ruas kecil jahe\", \"1 batang sereh, ambil bagian putih nya, geprek\", \"1 sdt maizena\", \"Sedikit Garam, Lada bubuk, gula pasir\", \"1 sendok makan kecap manis\", \"1 sendok makan kecap asin\", \"1 sendok makan margarin\", \"1 sendok makan minyak goreng\", \"1 sendok makan minyak wijen\", \"1 cangkir air panas\", \"2 lembar selada\"]', '[\"Haluskan bawang putih dan jahe. Campur rata dlm wadah bersama kecap manis, kecap asin, margarin, garam, gula, Lada bubuk, maizena dan daging. Diamkan 10 menit\", \"Panaskan minyak goreng dan minyak wijen. Tumis daging bersama perendam nya. Aduk rata sampai daging berubah warna. Tambahkan air panas, aduk rata.\", \"Setelah air menyusut, masukan bawang bombay. Aduk rata sampai bombay agak layu. Cicipi, koreksi rasa. Matikan kompor.\", \"Tata nasi di mangkok. Letakan daun selada dan daging di atas nasi. Nikmati.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(603, 3, 'Resoles beef moza', 'Nikmati kelezatan Resoles beef moza dengan resep sederhana ini.', '[\"Bahan Kulit Resoles\", \"1 Cup Susu Cair\", \"1 buah telur\", \"2 Cup Tepung Terigu Serbaguna (aq pakai segitiga biru)\", \"2 tbsp butter yang dilelehkan\", \"Bahan Isian Resoles\", \"500 gram Daging Sapi Cincang\", \"3 Batang Wortel\", \"2 Siung Bawang Bombay\", \"2 batang daun bawang\", \"4 buah telur rebus\", \"1 Kotak keju Moza\", \"2 buah Kentang Rebus yang dihaluskan\", \"2 sdt garam\", \"1 sdt merica\", \"4 batang seledri\", \"1/2 cup susu cair\", \"Bahan Menggoreng Resoles\", \"1 Buah telur\", \"1 cup tepung roti\", \"Minyak goreng\"]', '[\"Membuat kulit resoles\", \"Campurkan semua bahan untuk membuat kulit resoles diaduk sampai rata.\", \"Cetak menggunakan teflon sedang. Aq pakai teflon kualik jadi lebih mudah. Oh yea jangan lupa apinya kecil aja.\", \"Bahan isian. Tumis bawang bombay cincang, kemudian setelah harum masukan wortel cincang.\", \"Masukkan 500 gram daging cincang masak sampai daging agak kecokelatan. Masukkan garam\", \"Masukkan kentang rebus kemudian masukan 1/2 cup susu cair\", \"Tunggu sampai airnya sedikit kemudian masukan seledri dan daun bawang.\", \"Masukan merica bubuk. Kemudian diaduk sampai rata\", \"Setelah jadi kulit resoles semua sekarang ambil satu kulit resoles kemudian diolesi telur\", \"Masukan isian resoles yang sudah dimasak kedalam kulit resoles\", \"Masukan keju moza dan telur rebus\", \"Digulung dan diolesi telur\", \"Masukan ke dalam tepung roti\", \"Setelah semua ready goreng dengan minyak panas dan sampai terendam.\", \"Hidangkan dengan cocolan saus atau dengan cabe rawit\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(604, 3, 'Semur Lidah Sapi', 'Cara membuat Semur Lidah Sapi yang enak dan praktis untuk keluarga.', '[\"500 gr Lidah sapi\", \"Secukupnya air kaldu rebusan lidah sapi\", \"1 buah tomat, iris\", \"40 ml kecap manis, sesuaikan selera\", \"sedikit pala/ bubuk pala\", \"sesuai selera bawang goreng\", \"✔ Bumbu halus\", \"1 sdt merica\", \"6 butir kemiri\", \"4 siung bawang putih\"]', '[\"Rebus lidah sapi hingga empuk atau presto selama 20 menit, sisihkan kaldunya.\", \"Bersihkan lidah sapi dari permukaannya yg kasar, potong sesuai selera\", \"Tumis bumbu halus hingga harum dan kemiri matang kecoklatan, tambahkan air kaldu\", \"Masukan lidah sapi yang telah dipotong dan tambahkan kecap juga tomat dan pala, aduk sesekali hingga bumbu meresap dan kuah mengental diatas api sedang.\", \"Taburkan bawang goreng, semur lidah sapi siap dihidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(605, 2, 'Sop kikil sapi dengan pastel ubi', 'Sop kikil sapi dengan pastel ubi dengan daging sapi empuk dan bumbu kaya rasa.', '[\"300 gr kikil sapi\", \"10 butir telur puyuh (optional)\", \"200 gr bakso (optional)\", \"1 buah Wortel\", \"2 buah Kentang\", \"100 gr Buncis\", \"1 bks Mie jagung\", \"secukupnya Daun bawang\", \"secukupnya Korket ubi atau pastel ubi\", \"Bumbu kuah :\", \"5 siung bawang putih\", \"1 bks Merica bubuk\", \"2 cm jahe\", \"3 bh Kemiri\", \"secukupnya minyak goreng\", \"secukupnya Penyedap rasa\", \"secukupnya Garam\", \"Bahan cabe  :\", \"20 bh Cabe rawit merah\", \"2 siung Bawang putih\", \"secukupnya Garam\"]', '[\"Iris kikil kotak, rebus kurang lebih 5-10 menit smpai empuk. Tiriskan kikil.\", \"Iris wortel, kentang, dan buncis, cuci bersih\", \"Rebus telur puyuh dan kupas\", \"Blender bumbu Atau di uleg, dan tumis smpai harum. Masukkan ke dalam air mendidih.\", \"Masukkan irisan sayur wortel dan kentang dulu, stelah itu masukan buncis, bakso dan telur puyuh yg sudah matang dan kikil aduk rata masukkan penyedap rasa dan garam. Tes rasa.\", \"Mie jagung di rendam dengan air suhu ruangan sampai lembut.\", \"Sajikan dengan pastel atau korket ubi,mie jagung, taburkan irisan daun bawang dan bawang goreng, tuang kuah sop kikil yg sudah matang.\", \"Lebih enak di tambah dengan jeruk limau,kecap manis, dan cabe rawit blender.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(606, 2, 'Beef Teriyaki Simple ala Annisa Ellen', 'Nikmati kelezatan Beef Teriyaki Simple ala Annisa Ellen dengan resep sederhana ini.', '[\"250 gr Daging sapi\", \"1 buah Bawang bombay\", \"3 buah Cabe merah (bisa sesuai selera)\", \"1 buah Bawang putih\", \"2 buah Bawang merah\", \"1 sachet Saori saos tiram\", \"1 sendok teh lada bubuk\", \"1 sendok makan kecap manis\", \"1 sendok makan kecap asin\", \"Larutan maizena\", \"👌🏻Tips cara membuat rendaman daging :\", \"Campurkan 1 sendok teh lada bubuk, 1 sendok makan kecap manis dan 1 sendok makan kecap asin, lalu aduk secara merata\", \"👌🏻Tips cara membuat larutan maizena :\", \"Tambahkan 1 sendok tepung maizena lalu tambahkan 1 sendok air dingin (air es), lalu aduk sampai rata\"]', '[\"Cuci bersih daging sapi dan potong-potong tipis agak memanjang, lalu daging yang sudah dipotong di campurkan ke rendaman daging, setelah di campurkan semuanya di aduk secara merata lalu daging di masukkan ke dalam kulkas (lemari es) selama kurang lebih 15 menit agar bumbunya meresap ke dalam daging\", \"Setelah itu potong bawang bombay memanjang, bawang putih di cincang, bawang merah di potong memanjang, dan cabe merah di potong memanjang\", \"Panaskan minyak secukupnya ke dalam wajan, masukkan bawang bombay, bawang merah, bawang putih dan cabe merah. Lalu aduk secara merata sampai berwarna kecoklatan dan harum\", \"Masukkan daging yang sudah di rendam di dalam kulkas (lemari es), aduk sampai merata, jangan lupa tambahkan saori saus tiram. Lalu bisa di tambahkan air sesuai selera dan yang terakhir masukkan larutan maizena kedalam wajan dan aduk secara merata. Tunggu sampai wanginya harum dan agak mengental, lalu angkat dan di tiriskan.\", \"Selesai dan masakan siap untuk di sajikan😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(607, 4, 'Nasi goreng beef teriyaki', 'Cara membuat Nasi goreng beef teriyaki yang enak dan praktis untuk keluarga.', '[\"2 porsi nasi putih aku pakai nasi kemarin\", \"1 mangkok kecil beef teriyaki\", \"2 siung bawang merah iris halus\", \"2 cabai keriting iris2\", \"3 cabai rawit gila iris2\", \"secukupnya Kecap asin\", \"secukupnya Kecap manis\", \"secukupnya Garam\", \"Minyak utk menumis\"]', '[\"Tumis bawang merah dan duo cabai sampai layu n harum\", \"Masukkan nasi dan beef teriyaki sisa. Tambahkan kecap asin, kecap manis dan sedikit garam. Aduk rata ya. Koreksi rasa bila perlu.\", \"Tata di piring dan sajikan dengan cinta\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(608, 2, 'Beef & Tofu Sauce Teriyaki Pedas', 'Buat Beef & Tofu Sauce Teriyaki Pedas yang nikmat dengan langkah-langkah mudah ini.', '[\"1/4 Daging Sapi Yang sudah direbus\", \"1 Bungkus Tofu Telur\", \"5 Sdm Sauce Teriyaki\", \"3 Siung Bawang Putih\", \"9 Cabai rawit pedas aku biasa pakai cabai j*blay 😀 / Selera\", \"sesuai selera Garam & Penyedap rasa\", \"Minyak Goreng untuk menggoreng & menumis\", \"Air Putih / Air Kaldu\"]', '[\"Potong2 Daging & tofu sesuai selera.\", \"Cincang 3 siung bawang putih yang sudah dikupas kulitnya\", \"Iris tipis cabai rawit supaya pedasnya terasa kalau mau ditambah paprika dan bawang bombay its ok\", \"Panaskan minyak goreng di wajan untuk menggoreng tofu telur\", \"Goreng tofu telur yang sudah dipotong2 hingga sedikit kecoklatan dan angkat lalu tiriskan (saya selalu digoreng untuk menghindari hancur tofunya pd saat di masak teriyaki)\", \"Sisakan minyak goreng sedikit untuk menumis bawang putih yg sudah dicincang dan langsung ditumis karna masih panas minyaknya tunggu hingga wangi sebentar lalu masukkan cabai dan paprika jika ditambah\", \"Tambahkan air putih secukupnya agar tidak lengket pada saat dimasukkan sauce teriyaki\", \"Masukkan sauce teriyaki dan paprika, bawang bombay jika pakai\", \"Tunggu hingga agak menggolak, jika sudah masukkan masukkan potongan daging & tofu yang sudah digoreng aduk sebentar agar menyatu dengan api sedang dan tunggu menggolak serta harum lalu angkat dan hidangkan di piring / mangkuk sedang\", \"Enak dimakan selagi hangat karna wanginya yang menggoda.\", \"Selamat mencoba....\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(609, 2, 'Cah Brokoli dan Daging Sapi', 'Hidangan daging sapi istimewa: Cah Brokoli dan Daging Sapi.', '[\"3 bonggol kecil brokoli\", \"200 gram daging sapi, potong panjang tipis\", \"3 siung bawang putih\", \"secukupnya Garam\", \"secukupnya Merica\", \"Penyedap rasa bila suka secukupnya\", \"5 sdm saus tiram\", \"1 sdm tepung maizena\", \"secukupnya Air\", \"Minyak untuk menggoreng\"]', '[\"Rendam daging dengan saus tiram dan maizena, aduk rata, diamkan selama kurang lebih 3 jam dalam kulkas. Panaskan minyak, setelah panas masukan daging. Aduk-aduk sampai dagingnya matang dan tidak ada lagi bagian daging yang merah.\", \"Setelah harum masukan bawang putih lalu aduk-aduk sampai harum. Baru masukan air.\", \"Didihkan, lalu masukan bumbu-bumbu, tes rasa. Lalu masukan brokoli.\", \"Aduk-aduk sampai rata. Sebentar saja sampai brokolinya matang.\", \"Angkat, sajikan.\", \"TIPS: Agar warna brokoli hijau dan cantik, blanch atau rebus sebentar selama 1 menit didalam air panas. Lalu angkat. Warnanya saat dimasak akan jadi hijau cantik. Untuk menghindari ulat, sesaat setelah brokoli dipotong rendam sebentar dalam air garam\", \"Saya juga disini masak brokoli dengan bonggolnya. Caranya buang tangkai-tangkainya, lalu kupas bagian luarnya yang agak keras, lalu potong sesuai selera.\", \"Semoga bermanfaat 😊😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(610, 4, 'Balado bakso sapi', 'Buat Balado bakso sapi yang nikmat dengan langkah-langkah mudah ini.', '[\"Bakso sapi\", \"Cabe merah/hijau\", \"Bawang merah\", \"Bawang putih\", \"Garam\"]', '[\"Belah 4 bakso jgn putus\", \"Goreng sampai merekah\", \"Uleg bumbu balado...cabe bawang merah n bawang putih ksh garam sckp rasa..\", \"Tumis bumbu uleg pake minyak bekas goreng bakso...stlh harum n matang..mskkn bakso nya...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(611, 3, 'Mesere daging sapi', 'Resep praktis Mesere daging sapi yang bisa dicoba di rumah.', '[\"250 grm daging sapi\", \"1 liter air utk merebus daging\", \"5 siung besar bawang putih\", \"3 butir bawang merah\", \"3 buah cabe besar\", \"5 buah cabe rawit merah\", \"1/2 ibu jari terasi kualitas bagus\", \"2 biji asam kandis\", \"3 lembar daun jeruk purut\", \"secukupnya Garam royco dan diabetasol\", \"secukupnya Minyak goreng /barco\"]', '[\"Dg 1 liter air rebus daging sapi dan sisa kan kaldu hingga empuk dan potong2 mengikuti serat memanjang lalu suwir kasar..sisihkan\", \"Ulek semua bumbu kecuali garam royco diabetasol daun jeruk dan asam..sisihkan\", \"Panaskan penggorengan dan tumis bumbu ulek hingga harum dan masukkan daging sapi suwir dg ditambahkan kaldu..aduk2 spy bumbu tercampur dg daging\", \"Tambahkan garam royco diabetasol daun jeruk dan asam kandis..aduk2 dan tggu hingga air menyusut tp jgn sampai kering..\", \"Matikan kompor dan sajikan dlm piring saji\", \"Mesere daging sapi siap dinikmati\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(612, 4, 'Soto Daging sapi khas Jawa Timur', 'Buat Soto Daging sapi khas Jawa Timur yang nikmat dengan langkah-langkah mudah ini.', '[\"500 gr daging sapi (saya pakai 250 gr sengkel, 250 gram tetelan)\", \"Bumbu halus:\", \"10 siung bawang merah\", \"6 siung bawang putih\", \"1 ruas jahe\", \"2 sdt (ceper) ketumbar sangrai\", \"4 kemiri sangrai\", \"2 ruas jari kunyit bakar\", \"secukupnya Garam\", \"secukupnya Gula\", \"1/2 sdt merica bubuk\", \"Penyedap jamur secukupnya (optional)\", \"Pelengkap:\", \"Daun bawang, seledri\", \"Tauge rebus\", \"Bawang goreng\", \"Kerupuk udang\", \"Jeruk nipis\", \"Sambel:\", \"30 biji cabe rawit merah dikukus atau direbus sampai matang lalu dihaluskan, tambahkan sedikit air panas\"]', '[\"Didihkan air kurleb 1,5 liter, masukkan daging.. rebus 5 menit buang airnya, ganti baru. Rebus kembali daging sapi sampai empuk\", \"Tumis bumbu halus sampai harum, masukkan daun jeruk dan sereh,tumis sampai harum\", \"Masukkan bumbu ke dalam rebusan daging, tambahkan garam, gula, merica,penyedap jamur. Koreksi rasa.. masak hingga daging benar-benar empuk dan bumbu meresap. Siap disajikan. Beri pelengkap\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(613, 2, 'Beef broccoli jagung muda pedas', 'Resep praktis Beef broccoli jagung muda pedas yang bisa dicoba di rumah.', '[\"1/4 kg daging sapi has dalam\", \"3 siung bawang putih (cincang halus)\", \"1 siung bawang bombay yg kecil (iris memanjang)\", \"1 bonggol brokoli\", \"3 buah jagung muda\", \"5 buah cabe rawit merah\", \"5 buah cabe rawit hijau\", \"1 sdm mentega\", \"2 sdm minyak sayur\", \"Bahan marinasi:\", \"2 sdm kecap manis\", \"2 sdm kecap asin\", \"2 sdt minyak wijen\", \"1 bngkus ladaku\"]', '[\"Langkah pertama adalah potong2 tipis daging sapi. Letakkan didalam wadah, lalu masukkan bahan marinasi seperti kecap manis, kecap asin, minyak wijen dan ladaku. Aduk2 hingga rata, dan letakkan d dalam kulkas kurleb 2 jam supaya bumbu meresap.\", \"Potong2 sayuran dan cuci hingga bersih. Sisihkan\", \"Iris2 bombay dan bawang putih.\", \"Siapkan teflon, tambahkan 2 sdm minyak sayur. Jika sudah panas masukkan bawang putih, tumis hingga harum. Kemudian masukkan daging, aduk2 kurleb 1 menit kemudian masukkan irisan cabe rawit dan sayuran, aduk2 hingga rata lalu masukkan bawang bombay dan mentega. Aduk2 hingga rata, diamkan kurleb 2 menit lalu matikan kompor. (Saya suka sayur yg masih garing, jd masaknya tidak trlalu lama).\", \"Beef broccoli jagung muda pedas siap untuk disajikan 🤗🤗\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(614, 4, 'Sumsum Sapi ala Alia', 'Resep Sumsum Sapi ala Alia yang lezat dan mudah dibuat di rumah.', '[\"1 Tulang Sapi\", \"1/4 kg daging sapi bag tetelan/sengkel\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"secukupnya kaldu jamur\", \"2 tangkai daun bawang (potong2 2cm)\", \"2 butir kapulaga\", \"2 butir cengkeh\", \"1 cm kayu manis\", \"secukupnya lada putih\", \"secukupnya garam\", \"1 cm Jahe,geprek\"]', '[\"Rebus air smp mendidih,masukkan tulang sapi dan daging, rebus sampai lemak terangkat,lalu buang air rebusan pertama\", \"Rebus kembali air smp mendidih,lalu masukkan tulang sapi dan daging sampai empuk dan keluar minyaknya\", \"Masukkan jahe,kapulaga,cengkeh dan kayu manis\", \"Haluskan bawang merah dan putih,lalu tumis sebentar,masukkan kedlm rebusan tulang sapi. diamkan sampai benar2 empuk\", \"Masukkan kaldu jamur, garam dan lada,jg daun bawang. koreksi rasa.\", \"Diamkan lagi smp bnr2 meresap kaldunya,icipi lalu matikan api. sajikan dgn potongan cabai rawit dan tomat merah\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(615, 3, 'Mie Siram Sapi (#PR_AnekaMieKuah)', 'Sajian Mie Siram Sapi (#PR_AnekaMieKuah) yang praktis dan lezat untuk dinikmati bersama.', '[\"200 gr daging sapi, iris tipis, rebus hingga empuk\", \"1 Bks mie burung dara, rebus, tiriskan dan beri sedikit minyak\", \"6 buah bakso sapi, iris\", \"1 butir telur\", \"1 ikat sawi hijau / sosin, potong-potong\", \"2 siung bawang putih, geprek, cincang\", \"1/2 sdt saus tiram\", \"1 sdt kecap asin\", \"1/2 sdt minyak wijen\", \"secukupnya Garam\", \"secukupnya Gula pasir\", \"secukupnya Merica bubuk\", \"Kaldu jamur secukupnya (optional)\", \"1 sdm maizena, larutkan dengan sedikit air\"]', '[\"Panaskan wajan. Beri sedikit minyak. Orak arik telur hingga matang, tambahkan bawang putih, tumis hingga harum. Masukkan bakso, sawi hijau dan daging sapi. Beri air, tutup. Biarkan mendidih dan sawi hijau matang\", \"Tambahkan garam, gula, merica, kecap asin, kaldu, minyak wijen. Aduk rata. Koreksi rasa. Setelah rasa pas, masukkan larutan maizena. Biarkan mendidih. Matikan api\", \"Penyajian. Tata mie dalam piring, siramkan kuah sayuran dan daging. Dapat disajikan bersama acar timun, wortel atau acar cabe rawit\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(616, 4, 'Sup iga sapi', 'Buat Sup iga sapi yang nikmat dengan langkah-langkah mudah ini.', '[\"1/2 kg iga sapi\", \"250 gr brokoli\", \"200 gr wortel\", \"200 gr kentang\", \"Secukupnya daun bawang pre dan seledri\", \"3 siung bawang merah\", \"3 siung bawang putih\", \"secukupnya Merica\", \"secukupnya Bawang goreng\", \"Garam\", \"Penyedap rasa/kaldu\"]', '[\"Haluskan bawang merah, bawang putih, dan merica.\", \"Iris wortel, brokoli, kentang, kubis, daun bawang pre, dan seledri.\", \"Tumis bumbu halus hingga harum, tambahkan air sesuai selera.\", \"Masukkan iga yg sebelumnya sudah di rebus, tambahkan bahan yg sudah di iris.\", \"Tambahkan kaldu, garam, dan sedikit gulam\", \"Masak hingga matang, kemudian taburi dengan bawang goreng. Hidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(617, 3, 'Mie Daging Sapi Lezat #pr_anekamiekuah', 'Cara membuat Mie Daging Sapi Lezat #pr_anekamiekuah yang enak dan praktis untuk keluarga.', '[\"Bahan :\", \"300 gram daging sapi cincang\", \"1 siung bawang bombay, cincang halus\", \"3 siung bawang merah, iris\", \"1 helai daun bawang, iris tipis\", \"1/2 sdt merica putih bubuk\", \"1/2 sdt merica hitam bubuk\", \"Secukupnya Kecap manis\", \"2 sdm saos tiram\", \"1 sdm Kecap asin\", \"Secukupnya garam, kalo dirasa kurang asin\", \"Secukupnya gula pasir, untuk penyeimbang rasa\", \"Secukupnya air\", \"1 sdt terigu, larutkan dgn sedikit air\", \"Minyak bawang :\", \"300 gram kulit ayam\", \"6 siung bawang putih, geprek\", \"100 ml minyak goreng\", \"Kuah :\", \"1,5 liter air kaldu rebusan ceker dan tulang ayam\", \"3 siung bawang putih geprek\", \"Secukupnya merica bubuk\", \"Secukupnya garam\", \"Secukupnya kaldu bubuk\", \"1 batang daun bawang, potong\", \"Pelengkap :\", \"Mie telur rebus\", \"Kecap asin\", \"Sawi ijo rebus\", \"Baso sapi rebus\", \"Mentimun\", \"Saus sambal\", \"Kecap\", \"iris Daun bawang\", \"Bawang merah goreng\"]', '[\"Buat daging kecap : tumis bawang bombay dan bawang putih sampai wangi, daging sapi cincang masak sampai berubah warna. Masukkan air dan bumbu2. Masak sampai menyusut air menyusut, lalu beri larutan terigu. Aduk lagi sampai rata. Selesai.\", \"Buat minyak bawang : dalam wajan teflon masak kulit ayam sampai kering, beri minyak dan bawang putih, biarkan sampai wangi dan menguning bawangnya. Sisihkan.\", \"Buat kuah : didihkan air kaldu beri bumbu lalu daun bawang (saya pake presto selama 7 menit)\", \"Penyajian : ambil 1 sdm minyak bawang, 1 sdm kecap asin, sedikit merica bubuk. Taruh sawi ijo, mi basah, aduk rata. Beri toping daging kecap, baso dll. Sajikan dgn pelEngkap.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(618, 4, 'Tetelan Sapi Tempe Masak Kecap Cabe Hijau', 'Buat Tetelan Sapi Tempe Masak Kecap Cabe Hijau yang nikmat dengan langkah-langkah mudah ini.', '[\"250 gr tetelan daging sapi\", \"1 papan tempe\", \"Bumbu:\", \"8 siung bawang merah\", \"4 siung bawang merah\", \"100 gr cabe hijau besar\", \"1 lembar daun salam\", \"1 batang sereh\", \"2 cm lengkuas\", \"5 sdm kecap manis\", \"1 sdm gula pasir\", \"1 sdt garam\", \"1/2 bungkus kaldu bubuk (opsional)\"]', '[\"Rebus tetelan sapi sampai empuk, tiriskan, potong dadu.\", \"Potong dadu tempe lalu goreng sampai layu.\", \"Iris bawang merah, bawang putih, dan cabe hijau. Memarkan sereh dan lengkuas.\", \"Tumis bawang merah dan putih hingga layu, masukkan cabe hijau, lengkuas, daun salam, dan sereh. Aduk hingga harum.\", \"Masukkan tempe dan tetelan sapi, aduk sebentar, masukkan kecap manis dan sedikit air, aduk hingga meresap.\", \"Terakhir, masukkan gula, garam, dan kaldu bubuk. Aduk rata. Matikan kompor dan sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(619, 3, 'Tongseng tetelan sapi santan', 'Tongseng tetelan sapi santan dengan daging sapi empuk dan bumbu kaya rasa.', '[\"1/4 gram tetelan sapi\", \"1/4 bagian kol putih\", \"5 batang wortel lokal\", \"1 batang daun bawang\", \"2 batang serai\", \"2 buah tomat\", \"7 biji cabai setan\", \"3 lembar daun salam\", \"1 ruas lengkuas\", \"1 bungkus santan kara\", \"Bumbu halus :\", \"4 butir kemiri\", \"4 siung bawang merah\", \"2 siung bawang putih yg kecil\", \"sedikit Ketumbar\", \"3 sendok makan kecap, saya pakai bango\", \"Minyak goreng secukupnyaa\"]', '[\"Haluskan bumbu, tumis sampai matang masukan air dan tetelan rebus sampai empuk\", \"Masukan wortel, saya rebus 15 menit setelah tetelan direbus\", \"Setelah keliatan empuk masukan kol, dan bumbu lainnya masukan santan,kecap koreksi rasa\", \"Saya tambah airnya biar kuahnya banyak 😁😁 setelah mendidih pastika matang, koreksi rasa,matikan kompor siap di hidangkan... Selamat mencobaa 😊😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(620, 2, 'Nasi Goreng Terasi Kornet Sapi Pedas', 'Resep praktis Nasi Goreng Terasi Kornet Sapi Pedas yang bisa dicoba di rumah.', '[\"sesuai selera Nasi putih\", \"Kornet sapi sesuai selera (bisa pake yg kalengan)\", \"3 siung Bawang putih\", \"3 siung Bawang merah\", \"sesuai selera Terasi udang\", \"sesuai selera Cabai\", \"secukupnya Royco\", \"secukupnya Garam\"]', '[\"Haluskan bawang merah, bawang putih, cabai dan terasi udang.\", \"Tumis bumbu yang sudah dihaluskan.\", \"Jika sudah harum, masukkan mornet sapi secukupnya. Lalu tumis lagi sebentar.\", \"Masukkan nasi putih ke dalam tumisan. Aduk hingga rata.\", \"Tambahkan garam dan royco secukupnya ke dalam gorengan nasi.\", \"Jika sudah, silakan cek rasa.\", \"Terakhir, siap untuk disajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(621, 3, 'Sapi Lada Hitam - Chef Steby Rafael', 'Cara membuat Sapi Lada Hitam - Chef Steby Rafael yang enak dan praktis untuk keluarga.', '[\"500 gr daging sapi has dalam, iris tipis melawan serat\", \"3 sdt lada hitam bubuk\", \"10 sdm saus tomat\", \"1 sdm maggie seasoning\", \"1 sdm kecap inggris\", \"1 sdm gula pasir\", \"1/2 sdt mentega\", \"1/2 sdm dark soya sauce\", \"1 sdm arak masak (shaoxing)\", \"1 buah bawang bombay, potong kotak\", \"1/2 buah paprika merah, potong kotak atau wajik\", \"1/2 buah paprika hijau, potong wajik\", \"5 siung bawang putih, cincang\"]', '[\"Panaskan 2 sdm minyak pada wajan denga api besar, (wajan harus sangat panas) tumis daging hingga berubah warna sebelum berair, sisihkan\", \"Gunakan kembali wajan tsb, panaskan 1 sdm minyak untuk menumis, lalu tumis bawang bombay dan bawang putih hingga wangi dengan api sedang, lalu masukan potongan paprika, tumis lagi hingga paprika agak lembut\", \"Sitam dengan arak masak dan bahan lainnya lalu setelah tercampur rata, tambahkan mentega dan aduk rata kembali hingga mentega lumer (saus akan lgsung terlihat mengkilap😉)\", \"Masukan daging yg di tumis tadi lalu aduk hingga merata dan saus meresap kurang lebih 3 menit\", \"Sajikan hangat dengan di garnis irisan cabai yang di rendam di air dingin dan daun piterseli segar\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(622, 2, 'Rendang Daging Sapi Bumbu Instan Bamboe', 'Rendang Daging Sapi Bumbu Instan Bamboe - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 kg Daging Sapi\", \"4 siung Bawang Putih\", \"8 siung Bawang Merah\", \"3 butir Kemiri\", \"60 butir Cabe Rawit Merah (yg ga suka pedas bisa dikurangi)\", \"1 sachet Masako Sapi\", \"2 sachet Bamboe Bumbu Rendang\", \"200 ml Kara Santan Kelapa\", \"4 lembar Daun Jeruk\", \"Secukupnya Air untuk Merebus\", \"Secukupnya Minyak untuk menumis\"]', '[\"Rebus potongan daging sapi sampai empuk dan air tersisa sebanyak 2 gelas belimbing\", \"Sambil menunggu daging sapi matang...Haluskan bawang putih, bawang merah, kemiri, daun jaruk dan cabe rawit merah lalu tumis hingga berubah warna dan harum\", \"Masukkan bamboe bumbu rendang dan kara santan kelapa aduk-aduk hingga rata (lupa difoto🤦🏼‍♀️)\", \"Tuangkan daging sapi berserta air yang tersisa aduk-aduk sampai santan mengental dan berubah warna kecoklatan, tambahkan masako ratakan. Cek rasa, angkat dan siap di sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(623, 4, 'Beef Bulgogi', 'Hidangan daging sapi istimewa: Beef Bulgogi.', '[\"250 gram tenderloin\", \"1 buah paprika iris kotak\", \"2 sdm margarin utk menumis\", \"Bahan marinasi:\", \"3 siung bawang putih uleg halus\", \"1 cm jahe uleg halus\", \"1/2 bawang bombay iris melintang\", \"2 sdt saos tiram\", \"1 sdt kecap manis\", \"1 sdt lada hitam\", \"1 sdt madu\", \"Secukupnya garam\", \"Secukupnya gula\", \"Bahan pelengkap:\", \"2 batang daun bawang iris tipis\", \"1 sdt wijen\"]', '[\"Potong tipis tenderloin. Masukan bahan marinasi. Aduk rata. Masukan dalam wadah tertutup.\", \"Diamkan dalam kulkas (saya semalaman)\", \"Panaskan margarin. Masukan tenderloin yg sudah dimarinasi.\", \"Tumis hingga daging matang dan bumbu meresap sempurna. Jangan lupa cek rasa dan masukan paprika.\", \"Angkat, taburi wijen dan daun bawang diatasnya, sajikan dg nasi panas-panas.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(624, 3, 'Beef Sausage Mozarrella Quiche', 'Hidangan daging sapi istimewa: Beef Sausage Mozarrella Quiche.', '[\"3 beef sausage (atau sesuai selera)\", \"Mozzarella cheese\", \"Onion / Bawang bombay\", \"Daun bawang\", \"Merica hitam / putih (selera)\", \"Mix herbs (opsional - selera)\", \"3 butir telur\", \"Susu low fat - biar lebih sehat 😉\"]', '[\"Panaskan oven dengan setting api atas bawah selama 5-10 menit\", \"Dalam wajan api sedang dan sedikit minyak (atau margarine) tumis onion sampai harum, lalu masukkan iris an sosis dan tumis. Tambahkan garam (tidak perlu jika memakai margarine), merica dan mixed herbs untuk aroma khas (jika ada). Sisihkan di mangkuk (suhu ruang).\", \"Kocok telur dan campurkan susu. Aduk sampai bercampur merata.\", \"Iris daun bawang dan masukkan ke tumis an bahan isian (yg sudah tidak panas) bersama dengan Mozarrella parut. Aduk2 supaya tercampur merata.\", \"Masukkan kocokan telur dan susu (bagi rata) ke cetakan muffin. Masukkan bahan isian ke masing2 cetakan dan taburkan Mozarrella di atas nya.\", \"Panggang di oven pada suhu sekitar 175 celcius selama kurang lebih 25 - 30 menit sampai berwarna emas kecoklatan\", \"Sajikan dengan cantik dan nikmati 😁😉\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(625, 4, 'Pindang Iga Sapi Khas Palembang', 'Pindang Iga Sapi Khas Palembang dengan daging sapi empuk dan bumbu kaya rasa.', '[\"1 kg iga sapi, potong sesuai selera\", \"Air secukupnya utk merebus\", \"Bumbu halus (saya digongseng dulu) :\", \"8 bh bawang merah\", \"5 bh bawang putih\", \"4 cm kunyit\", \"3 cm jahe\", \"3 cm lengkuas\", \"3 cm serai ambil bagian putihnya\", \"5 bh cabe rawit merah\", \"5 bh cabe merah\", \"Bahan pelengkap :\", \"2 btg serai, geprek\", \"1 ruas jari lengkuas, geprek\", \"1/2 ruas jari jahe, geprek\", \"1 btg daun bawang, iris memanjang\", \"3 sdm air asam jawa\", \"1 bh tomat, belah 6\", \"1/2 sdm gula merah bisa diganti gula putih\", \"secukupnya Garam dan merica\", \"15 bh cabe rawit merah, buang buntut\", \"1 sdm kecap manis\"]', '[\"Cuci bersih iga, kemudian rebus iga, beri air secukupnya sampai iga tenggelam, rebus hingga iga agak empuk, tiriskan, untuk kaldunya diamkan bbrp saat, jika sudah dingin buang lemaknya\", \"Tumis bumbu halus dengan sedikit minyak, masukkan serai, jahe, lengkuas, daun salam, tumis sampai harum\", \"Tambahkan air biasa sebanyak 750 ml, kemudian masukkan air asam jawa, garam dan merica, biarkan hingga mendidih\", \"Kemudian masukkan iga, tambahkan 750ml kuah rebusan iga terlebih dahulu lemak sudah dibuang\", \"Tambahkan kecap manis dan gula merah, aduk rata, biarkan iga sampai empuk, jika air menyusut boleh ditambahkan air sisa rebusan\", \"Setelah iga empuk masukkan cabe rawit, aduk rata, masukkan potongan tomat, aduk rata lagi kemudian koreksi rasa, biarkan mendidih lagi, masukkan daun bawang, aduk rata, matikan kompor jika sudah mendidih kembali\", \"Angkat dan sajikan, pindang iga khas palembang ini sungguh segar dan kaya akan bumbu, nikmat dengan ditemani nasi hangat\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(626, 3, 'Empal Sapi Asin', 'Nikmati kelezatan Empal Sapi Asin dengan resep sederhana ini.', '[\"500 Gr daging sapi\", \"6 Siung bawang putih\", \"1 Sdm ketumbar\", \"Garam\", \"Gula(sedikit)optional\"]', '[\"Haluskan bawang putih dan ketumbar dg garam,rebus daging masukkan bumbu,rebus hingga daging empuk...asatkan air.\", \"Goreng dg minyak goreng asal kecoklatan angkat.😉endes di maem ama sup.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(627, 2, 'Sapi Masak Rica😋', 'Resep Sapi Masak Rica😋 yang lezat dan mudah dibuat di rumah.', '[\"250 gr daging sapi bagian rendang\", \"1 bawang bombay 》iris tipis\", \"2 cabe merah besar》iris serong\", \"2 lembar daun salam\", \"2 lembar daun jeruk\", \"1 batang sereh》memarkan\", \"1 sdm minyak wijen\", \"2 sdm kecap manis\", \"1 sdt kecap asin\", \"1 sdt garam\", \"1 sdt gula\", \"150 ml air\", \"1 batang daun bawang》potong kasar\", \"bumbu halus :\", \"4 bawang merah\", \"2 bawang putih\", \"5 cabe merah rawit\", \"3 cabe merah keriting\", \"2 cm kunyit\", \"1 sdt ketumbar bubuk\", \"3 sdm air\"]', '[\"Potong sapi menjadi dadu 2x2 cm》memarkan dengan cobek hingga tipis (agar daging empuk)\", \"Panaskan 2 sdm minyak di wajan》tumis bumbu halus, daun salam dan jeruk, sereh, bawang bombay, dan cabe hingga wangi dan matang》beri daging》aduk rata hingga daging berubah warna》beri minyak wijen, kecap manis dan asin, garam dan gula》aduk rata》beri air》aduk rata》tutuplah wajan, masak dengan api kecil hingga daging empuk dan kuahnya menyusut selama 15 menit》cicipi》beri daun bawang》angkat\", \"Enyak enyak enyakk 😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(628, 2, 'Oseng koyor sapi sederhana', 'Resep praktis Oseng koyor sapi sederhana yang bisa dicoba di rumah.', '[\"250 grm koyor sapi (beli yang udah rebus dari pasar)\", \"10 biji cabai hijau besar\", \"10 biji cabai rawit\", \"4 siung bawang putih\", \"secukupnya Garam, penyedap rasa, gula\", \"1 sdm kecap manis\", \"sesuai selera Jagung manis\", \"1 sdm blueband\", \"1 bks ladaku\", \"secukupnya Air\"]', '[\"Cuci koyor dan direbus 5 menit, buang airnya, lalu potong sesuai selera.\", \"Iris bawang, cabai, dan sisir jagung manis.\", \"Tumis bumbu yang sudah diris menggunakan blueband tunggu hingga harum.\", \"Masukan koyor sapi,jagung sisir dan tambah air jangan terlalu banyak, masukan kecap, garam, gula, lada dan koreksi rasa.\", \"Jika sudah kering angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(629, 4, 'Sop iga sapi, berempah', 'Hidangan daging sapi istimewa: Sop iga sapi, berempah.', '[\"1/2 kg iga sapi\", \"2 btg wortel, potong2\", \"2 bh kentang, potong2\", \"2 btg daun bawang, iris\", \"2 btg daun seledri, simpulkan\", \"6 btr bawang merah\", \"4 siung bawang putih\", \"1/2 sdt lada\", \"1 ruas jahe, geprek\", \"4 btr cengkeh\", \"4 btr kapulaga\", \"1/2 biji pala, geprek\", \"4 btr bunga lawang\", \"garam, sedikit gula\"]', '[\"Rebus iga sapi, masak hingga air mendidih, buang busa yang ada, masukkan daun seledri, rempah2 lain\", \"Tumis 2 bawang + lada yang telah dihaluskan hingga harum,masukkan dlm rebusan daging\", \"Masak terus hingga daging empuk dan matang, cicipi rasa, masukkan kentang, wortel, beri daun bawang jika disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(630, 3, 'Daging sApi bumbu LapIs', 'Hidangan daging sapi istimewa: Daging sApi bumbu LapIs.', '[\"1/4 daging sapi iris tipis digebuk biar cepet lunak\", \"4 potong tahu iris segitiga goreng setengah matang\", \"Penyedap rasa aq pake Magic\", \"Kecap manis\", \"Sereh\", \"Daun salam\", \"Gula merah\", \"200 ml air\", \"Bumbu halus\", \"5 butir bawang merah\", \"3 butir bawang putih\", \"5 kemiri\", \"secukupnya Ketumbar\", \"secukupnya Merica\", \"Garam\", \"Gula\"]', '[\"Halus kan smua bumbu halus taruh dalam wadah\", \"Masukan irisan daging yg sdh diiris dan digebuk td dalam wadah bumbu dan tambah kan kecap manis sambil diremas2 biar bumbu meresap.diamkan 10mnt\", \"Panaskan minyak tata daging yg sdh dicampur dalam wdah td masukan ke wajan. Tambah air krg lbh 200ml. Ungkep daging krg lbh 15mnt tambahkan sereh geprek.daun salam. Dan gula merah.penyedap Tunggu daging biar empuk\", \"Tambahkan tahu goreng dan biar kan bumbu meresap\", \"Tes rasa dan siap di hidangkan😍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(631, 4, 'Brokoli cah daging sapi', 'Resep praktis Brokoli cah daging sapi yang bisa dicoba di rumah.', '[\"1 buah brokoli\", \"100 gr daging sapi\", \"1 buah bawang putih,cincang halus\", \"1 cm jahe,cincang halus\", \"2 buah cabe merah keriting,iris serong\", \"1 sdm saus tiram\", \"1 sdt minyak wijen\", \"Secukupnya air\", \"1/4 sdt lada bubuk\", \"Secukupnya garam,gula pasir\"]', '[\"Siapkan bahan.rebus brokoli diair mendidih selama 1 menit dan tiriskan.\", \"Tumis bawang putih,jahe dan cabe hingga harum.masukkan daging sapi aduk hingga berubah warna, tambahkan sedikit air,saus tiram,minyak wijen,lada bubuk,garam dan gula pasir.masak hingga mendidih dan koreksi rasa.jika sudah pas masukkan brokoli aduk rata dan sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(632, 2, 'Sup Tomat Daging Sapi', 'Buat Sup Tomat Daging Sapi yang nikmat dengan langkah-langkah mudah ini.', '[\"1/4 kg daging sapi\", \"2 buah tomat,potong2 kecil\", \"1/2 buah bawang bombay\", \"2 bawang putih,geprek\", \"garam seckpnya\", \"Sedikit pala bubuk\", \"Sedikit merica bubuk\", \"1 sdm kaldu jamur\", \"3 tangkai daun seledri\", \"secukupnya Sayuran, wortel, kentang, kacang kapri\", \"Sosis, bakso,potong2\"]', '[\"Daging sapi potong dadu, rebus\", \"-Setelah daging empuk, masukan tomat,wortel,kentang sampai empuk. Dan tomat hancur\", \"Tumis Irisan bawang putih dan bawang bombay dgn margarin,Lalu masukan tumisan bawang tadi ke kuah daging\", \"Tambahkan garam, kaldu jamur, merica dan pala bubuk\", \"Masukan jg sosis, bakso\", \"Kemudian Irisan daun seledri dan taburkan di atasnya\", \"Tunggu sampai matang, koreksi rasa dan siap untuk dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(633, 4, 'Sop Iga Sapi - Kacang Merah', 'Nikmati kelezatan Sop Iga Sapi - Kacang Merah dengan resep sederhana ini.', '[\"1 kg iga sapi (potong sesuai selera)\", \"1/2 kg kentang\", \"1/2 kg wortel\", \"1/2 kg kembang kol\", \"2 biji tomat sayur\", \"Daun bawang secukupnya (sesuai selera)\", \"5 siung bawang putih\", \"1/2 biji buah pala (haluskan)\", \"Kayu manis\", \"Cengkeh\", \"Lada hitam\", \"Garam\", \"Mitcin (opsional)\", \"Kaldu instan\", \"secukupnya Air\"]', '[\"Cuci bersih iga sapi. Tiriskan. Rebus dengan air secukupnya. Tunggu sampai mendidih dan empuk.\", \"Buang air rebusan iga sapi. Ganti dengan air baru. Rebus lagi, ditambahkan dengan bumbu2 (bawang putih, pala, kayu manis, cengkeh, lada hitam, garam, mitcin, kaldu instan).\", \"Sembari menunggu iga sapi menjadi lebih empuk. Rebus kacang merah sampai empuk. Tiriskan.\", \"Cek rasa rebusan iga sapi yg sudah dibumbui.\", \"Setelah rasa pas, sesuai dengan selera. Masukkan kacang merah & kentang. Tunggu sampe tingkat ke-empuk-an sudah sesuai dengan selera.\", \"Kemudian masukkan wortel & kembang kol.\", \"Terakhir. Masukkan tomat & daun bawang.\", \"Hidangkan panas2. Ditambah dengan sambal tomat. Dan buah.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(634, 4, '.Sate Kambing', 'Resep .Sate Kambing yang lezat dan mudah dibuat di rumah.', '[\"Bahan-bahan :\", \"500 gr Daging kambing\", \"Daun pepaya\", \"Bumbu yang dihaluskan :\", \"4 siung bamer\", \"4 siung baput\", \"2 cm jahe\", \"1 sdt ketumbar\", \"1/2 sdt lada bubuk\", \"1/2 sdt Garam\", \"1 sdm air asam jawa\", \"Bahan sambel kecap :\", \"Kecap manis sesuai selera (aku pake bango)\", \"Cabe rawit\", \"Bamer\", \"Tomat\", \"Jeruk limau\"]', '[\"1. Cuci bersih daging kambing, potong\\\" kotak, bungkus didalam lapisan daun pepaya (30menit)\", \"2.setelah 30 menit, keluarkan daging dr daun pepaya, campurkan dengan bumbu yang sudah dihaluskan, diamkan 15 menit\", \"3. Susun daging pada tusuk sate kurlen 4-5 potong per tusuk\", \"4. Bakar (bisa pakai arang / teflon)\", \"5. Bolak balik sate hingga benar\\\" matang\", \"6. Sajikan dengan sambal kecap\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(635, 4, 'Sayur tulang kambing', 'Nikmati kelezatan Sayur tulang kambing dengan resep sederhana ini.', '[\"1.5 kg tulang sumsum kambing(direbus dahulu)agar bau amis hilang\", \"Kacang panjang\", \"Pepaya muda\", \"10 buah Cabe rawit\", \"2 buah Cabe merah besar\", \"2 buah Cabe hijau besar\", \"5 bawang putih\", \"5 bawang merah\", \"2 miri\", \"Garam\", \"1 bungkus masako\", \"1/2 sendok makan Gula putih\", \"Minyak goreng\", \"Irisan potongan bawang merah 5 siung\", \"Irisan potongan bawang putih 5 siung\", \"Santan kelapa\"]', '[\"Haluskan bawang merah 5 siung dan 5 bawang putih beserta cabe rawit dan miri.\", \"Panaskan kompor ksh sedikit minyak goreng, masukkan irisan cabe besar merah, hijau serta bawang putih dan merah sampai setengah matang\", \"Lalu masukkan cabe,miri,bawang merah dan bwang putih yg telah di haluskan,tumis sampai matang\", \"Masukkan sedikit air pada tumisan tadi...lalu masukkan sayuran beserta tulang sumsum kambing yg sudah di rebus tadi\", \"Terakhir masukkan santan, garam, 1bungkus masako, gula putih..tunggu sampai mendidih aduh terus agar santannya tidak pecah.\", \"Matikan kompor...sayur tulang kambing siap di hidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(636, 4, 'Sop Kaki Kambing', 'Sajian Sop Kaki Kambing yang praktis dan lezat untuk dinikmati bersama.', '[\"4 kaki kambing\", \"2-3 buah kentang, potpng dadu besar\", \"3-4 batang daun bawang, iris 2 cm\", \"2-3 L air panas\", \"2-3 sdm minyak utk menumis\", \"Bumbu halus:\", \"4 buah bawang merah\", \"8 buah bawang putih\", \"1 sdm garam\", \"1 sdt lada bubuk\", \"1/2 sdt pala bubuk\", \"Bumbu lainnya:\", \"5 buah cengkeh\", \"4 buah kapulaga india\", \"1 batang kayu manis\", \"2 buah star anise\", \"4 lembar salam koja (bay leaves)\"]', '[\"Bakar kaki kambing utk menghilangkan bulu2 halus dan baunya. Kerok sesekali lalu celupkan ke air panas mendidih. Lakukan hingga kaki benar2 bersih. Lalu potong2 sesuai selera.\", \"Panaskan minyak, tumis bumbu halus hingga harum. Masukan air panas dan bumbu lainnya. Masak hingga mendidih.\", \"Masukan kentang dan kaki kambing. Masak hingga kentang matang dan kaki kambing empuk.\", \"Masukan sisa bahan. Masak 3-4 menit lalu matikan api. Sajikan hangat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(637, 2, 'Kari kambing ala bundo', 'Sajian kambing spesial: Kari kambing ala bundo yang menggugah selera.', '[\"Daging kambing ½ kg, potong-potong, lumuri dengan sedikit bumbu halus dan biarkan 15 menit\", \"10 siung bawang merah, iris halus\", \"1 buah tomat, potong tipis\", \"6 butir cengkeh\", \"3 buah peka\", \"5 buah kapulaga\", \"9 siung bawang putih, iris halus\", \"500 ml santan dari 1 butir kelapa (1,5 bungkus segitiga santan kemasan)\", \"150 ml susu cair\", \"500 ml air\", \"3 ruas jari kayu manis\", \"2 lembar daun jeruk purut buang tulangnya\", \"10 lembar daun kari\", \"1 sdt  Garam dan gula sedikit hanya untuk menambah rasa\", \"secukupnya Minyak goreng\", \"Bumbu halus:\", \"1/2 sendok teh jinten, sangrai\", \"1 sendok teh adas, sangrai\", \"10 siung bawang merah\", \"15 buah cabai merah\", \"10 buah cabai rawit merah\", \"6 siung bawang putih\", \"1 sendok makan ketumbar, sangrai\", \"2,5 cm/ 1 ruas jari  jahe\", \"5 cm/ 2 ruas jari  kunyit (diameter kecil)\", \"2,5 cm/ 1 ruas jari  lengkuas\"]', '[\"Tumis hingga harum bawang merah iris, bawang putih, kayu manis, cengkeh, peka, kapulaga kemudian masukkan bumbu halus, masukkan daun jeruk dan daun kari,\", \"Masukkan daging kambing dan buah tomat, masak hingga daging kambing berubah warna dan keluar airnya\", \"Tambahkan air, masak hingga setengah matang\", \"Masukkan santan dan susu cair, masak hingga matang atau empuk.\", \"Daging kari kambing siap dihidangkan bersama acar, roti pratha dan es thai tea.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(638, 2, 'Tongseng kambing presto', 'Tongseng kambing presto dengan daging kambing empuk tanpa bau prengus.', '[\"250 gram iga kambing / daging kambing\", \"200 gram kol\", \"bumbu halus :\", \"4 siung bawang merah\", \"4 siung bawang putih\", \"1 ruas kunyit bakar\", \"3 buah kemiri sangrai\", \"1 sdt ketumbar sangrai\", \"1/2 sdt jinten\", \"2 buah cabe merah besar\", \"1 ruas jahe\", \"bumbu tambahan:\", \"4 lembar daun jeruk\", \"2 batang sereh\", \"1 ruas lengkuas\", \"2 batang daun bawang\", \"2 buah tomat\", \"5 buah cabe rawit merah\", \"2 sdm santan kara\", \"secukupnya gula garam\"]', '[\"Potong daging kambing sesuai selera, cuci bersih kemudian masukan ke panci presto.\", \"Masukan bumbu halus yg sudah ditumis, tambahkan air, sampai daging kambing terendam semua... tambahkan daun jeruk, sereh, lengkuas, masak sesuai petunjuk panci presto.. (me: 20 menit dari keluar uap pertama)\", \"Sambil menunggu, rajang halus daun bawang, belah 4 tomat, potong kasar kol, cairkan santan dengan 300ml air.\", \"Setelah 20 menit, matikan kompor, tunggu sampai uap habis.\", \"Buka tutup panci, beri santan, kol, daun bawang, dan tomat, cabe rawit sesuai selera, aduk rata.. beri gula garam.. koreksi rasa.. masak sampai mendidih.. angkat dan sajikan..\", \"Beri taburan bawang goreng.. makan dengan nasi hangat... 😋😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(639, 4, 'Telor dadar otak kambing', 'Telor dadar otak kambing - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"Otak kambing\", \"2 butir telor ayam\", \"Penyedap masako\", \"3 siung Bawang merah\", \"1 siung Bawang putih\", \"Daun bawang secukupnnya\", \"Cabe rawit 3 biji adanya\", \"Garam\", \"1 lembar Daun salam\", \"Jahe kunyit seujung jari kelingking dikit aja\", \"Minyak untuk numis\"]', '[\"Cuci otak. Kambing smpe bersih cuci semua bumbu\", \"Geprek jahe kunyit dan campurkan ke otak kambing jgn lupa daun salam lalu kukus sekitar 15 menit kurg lbh\", \"Bawang merah putih cabe daun bawang di iris ya ke mangkok lain campur semua bahan kecuali salam buang aja krna itu bekas kukusan aduk bersama telor otak kambing\", \"Lalu goreng smpe. Kekuningan ya\", \"Angkat tiriskan siap di santap pake nasi anget sedapp selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(640, 3, 'Sate kambing siram sambal bawang kecap', 'Resep praktis Sate kambing siram sambal bawang kecap yang bisa dicoba di rumah.', '[\"Bumbu daging\", \"1 kg daging kambing\", \"1,5 sdt ketumbar\", \"1 bungkus royko\", \"1 sdt gula\", \"1,5 sdt bawang putih bubuk(3 siung bawang putih)\", \"2 sdm minyak goreng\", \"secukupnya Garam\", \"secukupnya Kecap\", \"Untuk kuah\", \"3 siung bawang merah\", \"6 buah cabe rawit\", \"secukupnya Kecap\"]', '[\"Potong2 daging lalu masukkan bumbu daging...diamkan selama 1/2 jam\", \"Tusuk2 sate\", \"Lalu di bakar\", \"Untuk kuah tinggal di potong2 saja bawang merah dan cabe rawit siramkan kecap sesui selera lalu di tekan2 degn sendok\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(641, 4, 'Gule kambing pedas #keto', 'Resep praktis Gule kambing pedas #keto yang bisa dicoba di rumah.', '[\"500 gr iga kambing\", \"250 gr daging kambing dengan lemak\", \"Bumbu halus\", \"3 cm Jahe\", \"5 siung bawang putih\", \"10 siung Bawang merah\", \"1 sdm garan\", \"4 cm kunyit (bakar)\", \"3 butir cengkeh (sangrai)\", \"2 buah pekak/kembang secang/star anis (sangrai)\", \"4 butir kapulaga\", \"1/2 sachet stevia (kalo suka)\", \"1 st lada bubuk\", \"kemiri (sangrai/goreng)\", \"10 cabe merah keriting\", \"15 cabe rawit setan (kalo suka)\", \"Bahan tambahan\", \"2-3 lembar daun jeruk\", \"1 lembar daun kunyit (ikat)\", \"2 batang serai\", \"2-3 daun salam\", \"2 sdm air Asam kandis\", \"1 liter santan cair (1/2 sachet kara yg 65ml)\", \"1 liter santan kental (1.5 sachet kara 65ml)\", \"2 liter Air\", \"secukupnya Minyak goreng\"]', '[\"Rebus daging dan iga kambing dalam 1 liter air kalo mau empuk di presto 30 menit\", \"Setelah empuk buang airnya u menghilangkan bau prengus, rebus lagi kambing dalam 1 liter air\", \"Sambil menunggu daging kambing mendidih, panaskan minyak secukupnya, tumis bumbu halus, tambahkan daun jeruk, daun kunyit, daun salam + sereh masukan ke dalam rebusan daging\", \"Setelah mendidih masukan santan cair, aduk2 sampai mendidih lagi biar santan tidak pecah, setelah mendidih dan bumbu meresap masukan santan kental aduk2 jangan sampai santan pecah sampai mendidih.. icip2 rasa tambah asam kandis jika di rasa sudah cukup matikan api\", \"Gule kambing siap di hidangkan, tambah bawang goreng + kecap manis (kalo suka) +tomat + emping 😘 atau sesuai selera\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(642, 4, 'Sate Kambing Maranggi', 'Cara membuat Sate Kambing Maranggi yang enak dan praktis untuk keluarga.', '[\"1 kg daging kambing potong agak besar karena daging mudah empuk\", \"Secukupnya tusukan sate\", \"Secukupnya kecap manis\", \"1/4 nanas uk kecil atau 1/8 nanas uk sedang\", \"Bumbu dihaluskan :\", \"8 bawang putih\", \"5 bawang merah\", \"1 sdm ketumbar\", \"1 sdm gula merah\", \"1/4 sdt garam\", \"Bahan sambal kecap :\", \"10 bawang merah, potong2 kecil\", \"20 cabe rawit, potong kecil\", \"2 tomat merah besar, potong kotak kecil\", \"1 bh jeruk sambal\", \"Secukupnya kecap manis\"]', '[\"Parut nanas, kemudian peras dan saring airnya. Letakkan di piring ceper. Sisihkan.\", \"Lumuri daging yg sudah dipotong agak besar (sekitar 2x2) dengan bumbu halus dan 2 sdm kecap, diamkan sebentar (sekitar 2 jam) dlm refrigator agar bumbu meresap.\", \"Rangkai daging dgn menusuk daging dgn tusukannya\", \"Letakkan telapak tangan pada air nanas, tipis2, kemudian tempelkan telapak tangan pd sate, lakukan merata pd semua sate, bolak balik. Cukup lakukan sekali agar daging tdk hilang cita rasanya.\", \"Panaskan arang utk bakaran sate\", \"Bakar sate setengah matang, kemudian balur dgn kecap manis yg dicampur mentega dan bakar lagi hingga matang.\", \"Cara Membuat Sambal Kecap : Campur semua bahan, tambahkan perasan jeruk sambal.\", \"Sajikan sate kambing dgn siraman sambal kecap.\", \"Catatan, karena daging mudah empuk, hati2 saat membakarnya agar daging tdk lepas dr tusukannya saat membakar.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(643, 4, 'Soto babat kambing madura', 'Sajian kambing spesial: Soto babat kambing madura yang menggugah selera.', '[\"Jeroan kambing babat,usus campur\", \"Bumbu halus ;\", \"Bawang putih\", \"Bawang merah\", \"Merica\", \"Bumbu yg di iris ;\", \"Jahe\", \"Lengkuas\", \"Kunyit\", \"Daun jeruk\", \"Daun salam dan sereh sy gak pake karna lg kehabisan stok\", \"Bahan pelengkap ;\", \"Soun\", \"Toge\", \"Bawang daun dan seledri\", \"Bawang putih dan merah goreng\", \"Garam dan royco sapi\", \"Sambel uleg\", \"Jeruk nipis\"]', '[\"Bersihkan babat dan usus lalu rebus sampai empuk, lalu iris bumbu kemudian jahit pada benang, kemudian kupas bawang\", \"Lalu tumis bumbu iris dan bumbu halus\", \"Rebus air pada panci\", \"Setelah bumbu sudah wangi lalu masukkan babat yg sudah diiris, ini trik saya agar babatnya gak bau\", \"Kemudian masukkan bumbu dan babat pada panci yg airnya sudah mendidih lalu kasih garam dan royco sapi\", \"Tes rasa, kemudian masukkan bawang daun seledri dan bawang goreng\", \"Tata nasi lalu soun kemudian toge lalu kuah dan babatnya, siap dihidangkan, oya jangan lupa kasih jeruk nipis dan sambel ulek biar tambah nampoll\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(644, 4, 'Oseng-oseng tulang kambing pedas', 'Sajian Oseng-oseng tulang kambing pedas yang praktis dan lezat untuk dinikmati bersama.', '[\"1 kilo tulang kambing yang sudah di potong kecil\", \"2 siung bawang putih\", \"5 siung bawang merah\", \"1/4 cendok teh lada putih\", \"8 buah cabe rawit atau sesuai selera\", \"Minyak goreng\", \"Kecap manis\", \"Garam\"]', '[\"Rebus tulang yang sudah di potong kecil selama 20mnt,sambil menunggu daging di tulang lunak,kita siapkan bumbunya\", \"Bawang merah,bawang putih,cabe di haluskan setelah bumbu halus dan daging dalam tulang lunak kita sangrai bumbu yang sudah halus supaya menambah aroma,terus masukan tulang yang sudah di rebus aduk supaya bumbu merata,terus tuangkan kecap secukupnya\", \"Setelah masak kita sajikan di atas piring lebar lalu taburi denga lada bubuk,selamat mencoba dan selamat menikmati\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(645, 2, 'Tongseng kambing', 'Resep Tongseng kambing ala rumahan yang dijamin menggugah selera.', '[\"1 kg daging kambing muda\", \"1/2 buah kubis\", \"2 bungkus santan kara ukuran kecil (65ml)\", \"500 ml air panas\", \"Bumbu merebus daging:\", \"4 lembar daun salam\", \"secukupnya Air\", \"Bumbu halus:\", \"12 siung bawang merah\", \"6 siung bawang putih\", \"12 buah cabe merah\", \"12 buah cabe rawit (sesuai selera)\", \"1 sdt mrica\", \"1 sdt ketumbar\", \"3 buah kemiri\", \"1 ruas jari jahe\", \"1 ruas jari kunyit\", \"Bumbu lainnya :\", \"2 ruas jari lengkuas\", \"3 batang sereh (memarkan)\", \"3 lembar daun salam\", \"3 lembar daun jeruk\", \"secukupnya Garam\", \"4 sdm Kecap manis\", \"sedikit Gula\", \"10 sdm minyak goreng untuk menumis\", \"1/2 lada bubuk (sebagai kolerasi rasa)\", \"Bumbu pelengkap:\", \"5 siung bawang merah (iris tipis goreng)\", \"10 buah cabe rawit (potong2)\", \"2 buah tomat (potong menyisir)\"]', '[\"Jangan mencuci daging agar tidak mau, potong2 daging kambing berbentuk dadu atau ukuran sesuai selera. Daging langsung direbus menggunakan air dan daun salam hingga empuk. (Bisa juga di tambah kan bawang merah. Bawang putih. Garam sesuai selera). Buang air bekas rebusan. Lalu tiriskan daging\", \"Cuci dan kupas semua bahan\", \"Sangrai ketumbar. Miri. Kunyit\", \"Haluskan bawang merah. bawang putih. Cabe merah. Cabe rawit. Jahe. Kunyit. Kemiri. Mrica dan ketumbar\", \"Potong2 kubis seperti potongan untuk sayur sup\", \"Potong potong bahan pelengkap (cabe dan tomat). Goreng juga bawang merah yang di iris tipis pada minyak\", \"Panaskan minyak goreng, tumis bumbu halus, lengkuas, sereh, daun salam dan daun jeruk. Tumis hingga harum\", \"Masukkan daging kambing, tumis hingga bumbu tercampur rata\", \"Masukkan air panas, aduk2, biarkan air berkurang kurang lebih 1/3 bagian. Kemudian masukkan santan dan kecap. Lalu aduk hingga rata\", \"Masukkan kubis, tomat dan potongan cabe. Rebus sambil d aduk hingga kubis agak layu\", \"Masukkan garam dan gula (koreksi rasa)\", \"Matikan api.\", \"Tongseng kambing siap di hidangkan\", \"Jangan lupa tambahkan bawang yg sudah d goreng tadi\", \"TIPS. Agar daging kambing lebih cepat empuk baluri daging parutan nanas. Diamkan selama 5 sampai 15 menit\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(646, 2, 'Oseng kambing kecap asam manis simple', 'Sajian Oseng kambing kecap asam manis simple yang praktis dan lezat untuk dinikmati bersama.', '[\"1/4 kg daging kambing,potong sesuai selera\", \"5 siung bawang merah\", \"2 siung bawang putih\", \"Secukupnya kecap manis\", \"Secukupnya gula merah\", \"Secukupnya garam\", \"Secukupnya asam kanji\", \"2 gelas air\", \"Secukupnya cabe rawit (jika suka)\"]', '[\"Haluskan bawang merah,bawang putih, cabe (bila suka pedas),asam kanji.\", \"Aduk bersama kambing dan biarkan hingga bumbu meresap\", \"Panaskan minyak lalu masukan kambing yang sudah dibumbui,ungkep hingga stengah matang\", \"Tuang air, kecap, garam dan gula.aduk dan terus masak hingga matang\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(647, 4, 'Tongseng Kambing', 'Resep Tongseng Kambing ala rumahan yang dijamin menggugah selera.', '[\"1/2 kg daging kambing campur tulang\", \"Secukupnya minyak untuk menumis\", \"1 liter air\", \"500 ml santan\", \"3 lbr daun jeruk\", \"2 lbr daun salam\", \"1 buah serai memarkan\", \"3/4 bungkus bumbu gulai siap pakai\", \"Secukupnya kecap manis\", \"Haluskan :\", \"1 sdm ketumbar sangrai\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"1/2 sdt garam\", \"Secukupnya merica butiran\", \"Pelengkap:\", \"Daun bawang\", \"Kol\", \"Tomat\", \"Bawang merah goreng\"]', '[\"Panaskan minyak, tumis bumbu halus, bumbu gulai, salam, serai, daun jeruk. Masukkan daging kambing, aduk. Beri air, masak sampai empuk. Tambah santan, kecap, masak sampai matang.\", \"Menjelang matang masukkan kol dan tomat. Tutup wajan sebentar saja. Angkat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(648, 2, 'Tongseng Kambing Enak', 'Nikmati kelezatan Tongseng Kambing Enak dengan resep sederhana ini.', '[\"400 gr daging kambing\", \"Daun salam\", \"2 cm lengkuas\", \"2 batang serai\", \"3 bungkus Kara santan, encerkan dengan 700ml air\", \"Bumbu Halus;\", \"5 siung bawah merah\", \"4 siung bawang putih\", \"1 ruas kunyit, dibakar\", \"3 kemiri, sangrai\", \"1 sdt ketumbar\", \"1/2 sdt lada\", \"2 cm jahe\", \"Bumbu tumis ;\", \"2 siung bawang merah, iris\", \"3 siung bawang putih, geprek\", \"20 buah cabe rawit merah, iris (tergantung selera pedasnya)\", \"Kecap (sesuai selera manisnya)\", \"3 tomat hijau/ 1 tomat merah\", \"Garam\"]', '[\"Didihkan air, lalu rebus daging kambing dengan daun salam sampai empuk, tidak pakai presto +- 60 menit. Setelah empuk, angkat, potong-potong,\", \"Rebus santan, bumbu halus, lengkuas, serai, daun salam, jangan sampai pecah santan, setelah mendidih, sisihkan.\", \"Tumis bawang merah, putih, cabai rawit, dan daging, sampai harum\", \"Beri garam, sedikit lada, lalu masukan kecap, masukan kuah santan, cocokan rasa.\", \"Masak hingga kuah mengental, 3 menit sebelum diangkat masukan tomat, nikmati dengan nasi hangat dan acar bawang.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(649, 2, 'Balado kentang dan ati kambing', 'Sajian kambing spesial: Balado kentang dan ati kambing yang menggugah selera.', '[\"Ati kambing\", \"2 buah kentang\", \"Sambal balado\", \"4 cabe merah\", \"6 cabe rawit\", \"4 siung bawang merah\", \"1 siuang bawang putih\", \"1 buah tomat uk besar\", \"Daun salam\"]', '[\"Kukus hati kambing terlebih dahulu, lalu d goreng\", \"Kupas kentang potong sesuai selera bersihkan dan goreng\", \"Blender bahan untuk sambal balado\", \"Tumis sambal balado sampai mengeluarkan minyak masukan ati dan kentang.tambahkan garam dan gula.selesai\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(650, 3, 'Tongseng Kambing ala Mey', 'Tongseng Kambing ala Mey - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1/4 kg daging kambing, iris tipis\", \"Bumbu uleg :\", \"3 bh baput\", \"1 bh kemiri\", \"1 sdt ketumbar\", \"10 bh cabe kriting merah\", \"secukupnya Garam, gula & kecap manis\", \"3 lbr kol, iris\", \"1 btg daun bawang, iris\", \"3 sdm minyak sayur\", \"3 gls air\"]', '[\"Tumis bumbu uleg, sampai harum dan benar2 mateng\", \"Masukkan irisan daging kambing, aduk rata, tambah air, tutup, masak sampai daging matang dan lembut\", \"Masukkan garam, gula & kecap manis, aduk, biarkan sampai kuah menyusut & kental\", \"Terakhir masukkan kol & daun bawang, aduk rata, masak sebentar, lalu matikan api\", \"Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(651, 4, 'Kambing goreng simple with kecap cabe', 'Resep Kambing goreng simple with kecap cabe ala rumahan yang dijamin menggugah selera.', '[\"Secukupnya daging kambing potong dadu kayak sate (saya -+200gr)\", \"2 sdt bawang putih bubuk(bisa bawang putih biasa di geprek)\", \"2 sdt garam(suami suka asin)garam disesuaikan rada asin gpp ya\", \"Secukupnya merica halus\", \"Bumbu kecap:\", \"Kecap\", \"Cabe rawit\", \"Bawang goreng\"]', '[\"Godok air dalam panci sampai mendidih masukan daging dan bumbu semua\", \"Godok sampai air sat(habis)sampai daging benar2 empuk ya..masak dgn api kecil aja biar cpt empuk dan ga alot\", \"Setelah daging empuk airnya habis masukan minyak sy td 2-3 sdm\", \"Aduk sebentar sampai harum..\", \"Matikan kompor\", \"Siapakan kecap,cabe rawit iris,sedikit bawang goreng aduk rata\", \"Masukan daging tadi kedalam kecap cabe..siap hidangkan\", \"Rasa nya kayak sate gt hehe enak simple selamat mencoba😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(652, 4, 'Nasi goreng kari kambing', 'Buat Nasi goreng kari kambing yang nikmat dengan langkah-langkah mudah ini.', '[\"250 gr daging kambing potong kecil-kecil\", \"2 porsi nasi\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"sesuai selera Cabe rawit\", \"1 btg wortel kecil potong dadu\", \"1 batang daun bawang\", \"1 sdm bubuk kari\", \"1/2 sdt merica bubuk\", \"1 pucuk sdt pala bubuk\", \"secukupnya Kecap manis\", \"secukupnya Garam\", \"Minyak goreng\"]', '[\"Iris tipis bawang merah putih, cabe rawit\", \"Tumis bumbu iris, masukkan wortel, lalu daging kambing sampai daging berubah warna\", \"Masukkan nasi, aduk rata..\", \"Tambahkan garam, merica, lada.. Aduk rata.\", \"Tambah kecap manis, aduk rata.\", \"Koreksi rata\", \"Terakhir masukkan irisan daun bawang aduk rata..sampai daun agak layu\", \"Siap di hidangkan!!\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(653, 3, 'Sop kambing', 'Sajian kambing spesial: Sop kambing yang menggugah selera.', '[\"1/2 kg daging kambing\", \"2 bh wortel uk sedang (potong)\", \"2 btg daun bawang (potong)\", \"2 btg daun seledri (biarkan utuh)\", \"1/2 buah tomat (potong2)\", \"Bumbu :\", \"2 siung bawang putih (iris tipis)\", \"4 siung bawang merah (iris tipis)\", \"1/3 buah biji pala (geprek)\", \"2 cm kayu manis (geprek)\", \"2 buah kapulaga putih\", \"1/2 sdt lada bubuk\", \"Kaldu sapi bubuk (royco)\", \"secukupnya Garam\", \"Pelengkap :\", \"Bawang goreng\", \"Jeruk nipis\", \"Sambal\"]', '[\"Masukan daging kambing tanpa dicuci kedalam air yg sdh mendidih. Rebus sampai keluar buih\", \"Angkat dan ganti air nya dgn air yang baru. Lanjutkan merebus hingga daging lunak.lalu angkat daging dan potong2 sesuai selera.lalu masukan lagi kedalam panci\", \"Sambil menunggu daging lunak, tumis duo bawang hingga harum\", \"Masukan tumisan bawang kedalam panci. Tambahkan biji pala, kapulaga, kayu manis, lada bubuk. Lalu beri kaldu bubuk dan garam\", \"Masukan juga wortel, jika wortel sdh empuk,,,,masukan daun bawang seledri dan tomat\", \"Koreksi rasa\", \"Untuk sambalnya,,,,rebus cabai rawit lalu uleg.\", \"Hidangkan sop kambing bersama pelengkap bawang goreng, perasan jeruk nipis dan sambal\", \"Selamat mencoba 😊😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(654, 3, 'Sup Kambing Akar Teratai', 'Sup Kambing Akar Teratai dengan daging kambing empuk tanpa bau prengus.', '[\"1 batang akar teratai, iris\", \"🐑 Rebus sampai empuk, buang airnya :\", \"1 kg daging kambing, potong (sy bagian paha)\", \"1.5 L air\", \"2 sdm garam\", \"1/2 telapak jahe, iris tipis\", \"🍲 Kuah Sup :\", \"1.5 L Air\", \"8 bh cengkeh\", \"5 siung garlic, geprek\", \"3 bh bunga lawang\", \"3 bh cardamom/kapulaga hijau\", \"2 jempol jahe, iris\", \"1 batang kayu manis\", \"1 bh pala, geprek\", \"1/2 sdt jinten\", \"1.5-2 sdm garam\", \"1/2 sdm kaldu bubuk\", \"1/2 sdm merica bubuk\", \"🍀 Pelengkap :\", \"6 batang seledri, iris\", \"1 bh lemon, iris (untuk kucuran, bikin kuah jadi seger)\"]', '[\"Masak semua bahan kuah hingga mendidih, tambahkan daging, masak hingga empuk, baru masukkan akar lotus, hingga matang.\", \"Matikan api, masukkan seledri. hidangkan dengan perasan jeruk lemon. segaar.\", \"Sup Kambing bumbu rempah & akar lotus siap di santap.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(655, 2, 'Steak Daging Kambing Crispy ala-ala', 'Cara membuat Steak Daging Kambing Crispy ala-ala yang enak dan praktis untuk keluarga.', '[\"Daging Kambing (difillet)\", \"1 sdt merica bubuk\", \"1 sdt bubuk bawang putih (bisa pakai 2 siung bawang putih, diulek)\", \"4 sdm tepung serbaguna\", \"2 sdm tepung tapioka\", \"1 butir putih telur\", \"Untuk Saus Lada Hitam :\", \"1 sdm margarine\", \"1/2 buah bawang bombay (dicincang)\", \"2 sdm tepung terigu (cairkan dgn 1/4 gelas agar tdk menggumpal)\", \"250 ml air matang\", \"1 sdt lada hitam\", \"1/2 bungkus Penyedap rasa\", \"1 sdm kecap manis\", \"1 sdm saus tiram\", \"1 sdm saus tomat\", \"Gula pasir sckpnya\", \"Bahan pelengkap:\", \"Jagung rebus, buncis rebus, wortel rebus\", \"Brokoli rebus, kentang goreng\"]', '[\"Cuci bersih daging, rebus sampai empuk, masukkan 1 sdt garam. Setelah matang, tiriskan\", \"Celupkan daging ke dlm putih telur yg sdh dicampur merica bubuk & bawang putih bubuk, celupkan ke tepung, lalu celupkan lagi ke dlm putih telur. Terakhir celupkan lagi ke tepung sambik di cubit2 supaya tepung crispy saat digoreng. Goreng ke minyak panas, tunggu hingga kecoklatan. Tiriskan.\", \"Untuk sausnya: Panaskan margarin, masak bawang bombay hingga wangi. Masukkan tepung terigu aduk rata, masukkan air matang, lada hitam, saus tiram, saus tomat, kecap manis, penyedap rasa, gula secukupnya, aduk-aduk, angkat.\", \"Steak daging kambing crispy siap disajikan dengan bahan pelengkap. 👌\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(656, 3, 'Bacem Kambing Goreng', 'Buat Bacem Kambing Goreng yang nikmat dengan langkah-langkah mudah ini.', '[\"1 L air (kurleb)\", \"600 gr kambing, bagian iga atau paha sama enaknya\", \"#blender :\", \"1/2 bonggol garlic\", \"1/2 bh bombay besar (ganti bawang merah gpp)\", \"1 sachet/ 1 sdm  ketumbar bubuk\", \"2 sdm daging asam (non biji)\", \"#bumbu :\", \"4 sdm kecap asin\", \"3 lembar daun salam\", \"2 sdm penuh gula pasir\", \"1 bongkah gula jawa\", \"1 sdm penuh garam\", \"1/2 sdm merica bubuk\", \"1/2 sdt kaldu bubuk\"]', '[\"Campur semua bahan blenderan & bumbu. masak hingga daging empuk dan kuah mengental. bila daging blm empuk tambahkan saja airnya.\", \"Bacem kambing setelah empuk & matang. ditahap ini sdh bs dikonsumsi. kalau mau digoreng, dinginkan dl. makin di inep, makin meresap.\", \"Goreng kambing hingga kecoklatan.\", \"Angkat, sajikan.\", \"NOTE : Saya sebelumnya merebus daging dengan irisan jahe plus garam, hingga buih & kotoran keluar, dan daging tdk terlalu bau. kurleb 20 menit sejak air mendidih. banyakin aja jahenya, gpp kok. nanti angkat dagingnya, buang kuah jahenya, ganti dengan air & bumbu halus tadi.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(657, 4, 'SOP Kambing Muda', 'Resep SOP Kambing Muda ala rumahan yang dijamin menggugah selera.', '[\"500 g daging kambing muda\", \"6 siung bawang putih\", \"6 siung bawang merah\", \"1 sdt merica\", \"1/8 biji pala\", \"1 ibu jari jahe digeprek\", \"1 ibu jari lengkuas digeprek\", \"2 lembar daun salam\", \"2 lembar daun jeruk\", \"1/2 sdt bubuk (1 jari kelingking) kayu manis\", \"1 1/2 buah bintang (pekak)\", \"5 butir cengkeh\", \"3 butir kapulaga\", \"2 butir kentang potong persegi\", \"2 buah wortel ukuran sedang potong bulat\", \"1 batang Daun bawang\", \"1 batang Daun seledri\", \"secukupnya Garam dan gula putih\"]', '[\"Masukkan daging, daun salam, daun jeruk, jahe, lengkuas, buah bintang, cengkeh, kayu manis, kapulaga ke dalam panci presto. Tambahkan 2 liter air dan masak selama 25-30 menit sampai daging empuk.\", \"Haluskan merica, pala dan garam. Masukkan dalam rebusan daging. Tambahkan gula secukupnya dan didihkan sebentar.\", \"Masukkan kentang dan wortel dan didikan sekitar 5-10 menit sampai empuk.\", \"Potong-potong tipis bawang merah dan goreng sampai coklat.\", \"Potong-potong daun bawang dan seledri sesuai selera.\", \"Masukkan daun bawang, seledri dan bawang goreng. Aduk sebentar sambil dicoba. Jika rasa sudah pas, angkat dan sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(658, 2, 'Tongseng Kambing Jogja (otentik warisan mertua)', 'Tongseng Kambing Jogja (otentik warisan mertua) dengan daging kambing empuk tanpa bau prengus.', '[\"250 gr Daging kambing, potong dadu\", \"500 ml Air\", \"1/2 butir Kelapa, parut\", \"Secukupnya Minyak goreng\", \"🍄 Bumbu halus 1 :\", \"3 siung Bawang putih\", \"3 butir Kemiri\", \"1 sdt merica\", \"1 sdt ketumbar\", \"Secuil Pala\", \"🍄 Bumbu Halus 2:\", \"2 ruas Jari Kunyit\", \"2 ruas jari Jahe\", \"1 ruas jari Kencur\", \"1 ruas jari Sunti (cuma ada di jogja, aq skip)\", \"🍄 Bumbu Iris :\", \"5 siung Bawang merah, iris tipis\", \"15 buah Cabai rawit merah, iris tipis (sesuai selera pedasnya)\", \"🍄 Bumbu Kering :\", \"1 batang Kayu manis\", \"1 batang Kulit Kayu Krangean\", \"1 buah Cabe jawa\", \"5 butir Cengkeh\", \"3 butir Kapulaga\", \"1 sdt jinten\", \"🍄 Bumbu lain :\", \"2 lembar Daun salam\", \"2 lembar Daun jeruk\", \"1 ruas Lengkuas, geprek\", \"1 batang Serai, geprek\", \"5 sdm Kecap manis\", \"2 sdm Gula merah sisir\", \"Secukupnya Garam & penyedap\", \"🍄 Pelengkap sajian:\", \"Secukupnya Kubis, cincang kasar\", \"Secukupnya Mentimun, iris\", \"Secukupnya Bawang merah, iris\", \"Secukupnya Cabai rawit, iris\"]', '[\"Panaskan 1 sdm minyak, goreng bumbu kering sebentar hingga keluar aromanya, tiriskan lalu haluskan. Campurkan dengan kelapa parut.\", \"Tuangkan air ke dalam kelapa, campur rata sambil diperas-peras, saring dengan kain. Sisihkan.\", \"Panaskan 3 sdm minyak, tumis bumbu iris hingga layu & harum, lalu masukkan bumbu halus 1. Tumis hingga harum.\", \"Masukkan daging kambing, aduk rata dengan bumbu, tutupi & biarkan hingga daging berubah warna & mengeluarkan air.\", \"Tuangkan santan. Masukkan bumbu halus 2 & bumbu lain-lain. Aduk rata, ungkep hingga daging empuk & kuah menyusut sambil sesekali diaduk rata.\", \"Koreksi rasa.\", \"Sajikan bersama nasi hangat & pelengkap.\", \"Catatan :\", \"Ini gambar bumbu kering nya ya..\", \"Kalo di jogja biasanya udah ada yang kemasan gini bumbu keringnya, jd ga repot beli bumbu satu satu..\", \"Nih buat bunda2 yg mau lebih gampang lagi, bumbu kering & bumbu halus 2, bisa diganti dengan bumbu gule instan kemasan (bumbu yg basah), nanti ditumis bareng bumbu halus 1.\", \"Masukkan garam nya terakhir aja sebelum koreksi rasa, karna biasanya dah ada rasa asin dari kecap / bumbu instan nya juga.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(659, 4, 'Sop tulang kambing', 'Resep praktis Sop tulang kambing yang bisa dicoba di rumah.', '[\"1 kg tulang kambing\", \"3 lembar daun bawang\", \"3 lembar daun seledri\", \"2 siung bawang putih\", \"1 siung bawang merah\", \"1 sdm gula pasir\", \"1 sdm garam\", \"10 butir merica\"]', '[\"Rebus tulang sampai lunak\", \"Masukan bawang putih, bawang merah dan merica yang sudah di ulek\", \"Masukan garam dan gula pasir\", \"Masukan potongan daun bawang dan seldri\", \"Siap hidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(660, 3, 'Tumis kambing kecap', 'Nikmati kelezatan Tumis kambing kecap dengan resep sederhana ini.', '[\"1/4 Daging kambing (Sy masak buat 1 x makan aja)\", \"iris Bawang putih\", \"iris Bawang merah\", \"iris Daun bawang\", \"iris Cabe rawit\", \"Daun jeruk\", \"Asam\", \"Micin, royko, garam, gula, ketumbar bubuk\", \"Kecap\"]', '[\"Tumis bumbu yg di iris smua nya, masukan daging oseng2 sebentar lalu masukan kecap, ketumbar bubuk, micin, royko, garam tambah air sedikit, ungkep sampai air menyusut..\", \"Selamat mencoba buntik\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(661, 3, 'Kari Kambing', 'Resep Kari Kambing yang lezat dan mudah dibuat di rumah.', '[\"500 gr daging kambing berlemak/iga kambing, potong sesuai selera\", \"4 siung bawang merah, iris tipis\", \"1 siung bawang putih, iris tipis\", \"1 ruas jari lengkuas, geprek\", \"1 rumpun daun kari\", \"1 sdt asam jawa utuh\", \"2 sdt bubuk kari\", \"1 sdm cabe giling\", \"2 buah pekak/bunga lawang\", \"3 buah cengkeh\", \"1 buah kayu manis\", \"1 sdt kunyit bubuk\", \"2 sdt gula merah sisir\", \"Garam, penyedap (jika suka)\", \"300 ml santan\", \"500 ml air\"]', '[\"Tumis bawang merah, bawang putih, lengkuas, pekak/bunga lawang, cengkeh, kayu manis, daun kari, bubuk kunyit hingga harum dan kuning.\", \"Lalu masukkan bubuk kari, cabe giling, asam jawa. Aduk sebentar kemudian masukkan daging kambing, masak hingga berubah warna.\", \"Beri air 500 ml, tambahkan gula jawa, garam dan penyedap. Aduk sampai meresap lalu masukkan santan.\", \"Kecilkan api sambil menunggu kuah kari mendidih, aduk sesekali, biarkan sampai kuah kari keluar minyak. Tes rasa. Jika kurang air bisa ditambah sesuai selera.\", \"Sajikan dengan roti maryam libya super gampang 😁 resepnya bisa diliat di daftar resep saya.\", \"Kali ini santan saya ganti dengan susu evaporated.. tetap maknyuuuss rasanya 👌😊\", \"Susu evaporated\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(662, 3, 'Soto Kambing Kuah Bening Mang Yudi (#pr_homemadestreetfood)', 'Cara membuat Soto Kambing Kuah Bening Mang Yudi (#pr_homemadestreetfood) yang enak dan praktis untuk keluarga.', '[\"500 gr Daging Kambing\", \"Bumbu Halus :\", \"1/2 Buah Bawang Bombay\", \"6 Siung Bawang Putih\", \"3 cm Jahe\", \"1/2 Sdt Lada Bubuk\", \"1 Sdt Kunyit Bubuk\", \"Bumbu Lain :\", \"3 cm Lengkuas bagian (memarkan)\", \"5 Lembar Daun Jeruk\", \"1 Batang Serai (bagian putihnya saja) memarkan\", \"Secukupnya Garam\", \"Bahan Pelengkap :\", \"Secukupnya Irisan Tomat\", \"Secukupnya Irisan Daun Bawang\", \"Secukupnya Irisan Daun Seledri\", \"Secukupnya Bawang Merah (belah menjadi 4)\", \"Secukupnya Sambal uleg\", \"Secukupnya kecap\", \"Secukupnya Nasi/ Lontong\", \"Secukupnya emping (me skip)\"]', '[\"Cuci daging kambing di air mengalir, lumuri air jeruk lemon, diamkan ±1 jam, cuci lagi, tiriskan (Potong sesuai selera)\", \"Lalu rebus daging kambing sampai setengah empuk.\", \"Tumis bumbu halus dan bumbu lainnya, sampai harum. Masukkan tumisan bumbu ke dalam rebusan daging,aduk rata. Didihkan lagi sampai daging empuk. Tambahkan garam (uji rasa) angkat\", \"Soto Kambing Kuah Bening siap dihidangkan 😁👌\", \"Saran Penyajian : Tata di mangkuk, daging, tomat, irisan bawang merah. Siram kuah, taburi seledri, daun bawang, beri perasan jeruk. (Bisa ditambahkan emping, kecap, lontong or nasi untuk menyantap nya)\", \"Semoga bermanfaat guys 😁👌\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(663, 2, 'Nasi biryani paha kambing', 'Buat Nasi biryani paha kambing yang nikmat dengan langkah-langkah mudah ini.', '[\"Paha kambing 1 sisi\", \"1 liter Beras basmati\", \"2 bonggol Bawang bombay\", \"8 butir Kapulaga\", \"2 batang Sereh\", \"Bumbu kuning\", \"2 siung Jinten\"]', '[\"Haluskan bumbu, lumurin paha kambing, terus wrap pake aluminium foil, panggang di oven 2 jam\", \"Keluarin paha kambing\", \"Bikin nasi biryani kayak bikin nasi goreng\", \"Ratakan nasi di loyang + paha kambing diatasnya (sari dari paha kambing bakal turun ke nasi dibawahnya), terus masukin ke oven selama 10 menit\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(664, 4, 'Tongseng Kambing (NO MSG)', 'Tongseng Kambing (NO MSG) dengan daging kambing empuk tanpa bau prengus.', '[\"0,5 Kg daging dan tulang kambing\", \"2 sendok makan kecap manis (saya pake merk tawon)\", \"1 ruas jahe (sangrai, geprek)\", \"1 batang serai (geprek)\", \"secukupnya daun salam dan daun jeruk\", \"2 sendok kecap manis\", \"0,5 liter santan cair\", \"bumbu halus :\", \"3 cabai rawit (sesuai selera)\", \"2 butir kemiri (sangrai)\", \"5 siung bawang putih\", \"5 siung bawang merah\", \"1 ruas kunyit (bakar)\", \"1 sendok merica\", \"1 sendok ketumbar\", \"1 sendok gula pasir\"]', '[\"Rebus daging dan tulang kambing dengan 1 liter air sampai mendidih, sisihkan daging dan tulang lalu potong daging kecil-kecil.\", \"Haluskan bumbu lalu tumis bumbu halus, serai, dan jahe sampai wangi.\", \"Masukkan daging yang sudah di potong aduk sampai rata.\", \"Tambahkan kecap (jangan langsung diaduk biarkan 5 detik). lalu aduk terus sampai 1 menit.\", \"Tambahkan kaldu, tunggu sampai mendidih, lalu masukkan santan, garam secukupnya, biarkan sampai mendidih.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(665, 4, 'Kambing Goreng Empuk', 'Resep Kambing Goreng Empuk ala rumahan yang dijamin menggugah selera.', '[\"Segenggam Daging Kambing\", \"Secukupnya Kecap Manis, Garam, Lada, Soda Kue\", \"2 siung Bawang Merah\", \"1/4 buah Bawang Bombay\", \"1 buah Cabai Merah Besar\", \"2 buah Cabai Rawit\", \"🍳Bahan Halus\", \"1 cm Kunyit/Kunir\", \"1 sdt Ketumbar\", \"3 siung Bawang Putih\"]', '[\"Iris tipis daging kambing.\", \"Rebus daging kambing dengan segelas air dan sejumput Soda Kue ± 10 menit. Lalu tiriskan.\", \"Haluskan bawang putih, kunir dan ketumbar. Iris tipis Cabai Merah Besar, Cabai Rawit, Bawang Merah, Bawang Bombay.\", \"Tumis semua bumbu dengan minyak panas. Aduk hingga rata dan tercium bau harum.\", \"Masukkan daging kambing, aduk rata. Tambahkan setengah gelas air.\", \"Masukkan garam, lada, dan kecap manis secukupnya.\", \"Aduk rata dan biarkan hingga airnya habis.\", \"Siap disajikan dengan\", \"nasi hangat ❤\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(666, 4, '“Tongseng Kambing”', 'Buat “Tongseng Kambing” yang nikmat dengan langkah-langkah mudah ini.', '[\"250 gr daging kambing potong sesuai selera\", \"500 ml santan dari 1 bks kecil kara\", \"4 lembar daun kol iris kasar\", \"1 batang daun bawang iris kasar\", \"1 buah tomat uk besar potong kasar\", \"10 buah cabe rawit hijau iris kasar\", \"3 lembar daun salam\", \"1 batang serai geprak simpulkan\", \"1/2 ruas lengkuas geprak\", \"3 lembar daun jeruk\", \"Bumbu halus:\", \"4 buah bawang putih\", \"5 buah bawang merah\", \"4 buah kemiri sangrai\", \"1 sdt ketumbar sangrai\", \"1 sdt merica sangrai\", \"2 cm kunyit bakar\", \"2 cm jahe bakar\", \">>\", \"1 sdm garam\", \"1 sdm gula pasir\", \"3 sdm kecap manis\", \"Minyak goreng secukup mya utk menumis\"]', '[\"Bungkus daging kambing dengan daun pepaya Yg telah di remas2 kurang lebih 1 jam Supit daging empuk dan tidak bau saat di masak\", \"Setelah satu jam tumis daging dengan sedikit minyak hingga warna nya berubah angkat dan sisihkan\", \"Tumis bumbu halus, hingga harum masuk an daun salam, jeruk, lengkuas, serai aduk rata\", \"Tambahkan gula pasir garam dan kecap aduk2 kmudian masukan daging kambing diamkan sebentar hingga bumbu meresap\", \"Tambahkan santan dan kalo agak kental bisa di tambahkan air, aduk2 sebentar\", \"Kemudian masukan daun kol daun bawang cabe rawit dan tomat masak sebentar hingga sayuran layu\", \"Angkat dan sajikan dengan ditambah taburan bawang goreng\", \"Selamat mencoba ☺️\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(667, 2, 'Presto kambing bumbu kecap', 'Resep Presto kambing bumbu kecap ala rumahan yang dijamin menggugah selera.', '[\"1 kg daging kambing\", \"3 butir kentang\", \"Bumbu yang dihaluskan:\", \"6 siung bawang merah\", \"4 siung bawang putih\", \"1 sdm lada\", \"1 sdt ketumbar\", \"3 butir kemiri\", \"1/2 butir pala\", \"1 sdt kunyit bubuk\", \"1 sdt cabe bubuk\", \"2 ruas jahe\", \"Bumbu pelengkap:\", \"secukupnya Garam\", \"1 sdt kecap asin\", \"2 sdm kecap manis\", \"1 bks saus tiram\", \"1 bks kaldu rasa sapi\", \"2 ruas jahe digeprek\", \"3 lbr daun salam\", \"3 lembar daun jeruk\", \"2 ruas lengkuas\", \"3 butir kapulaga\", \"1 buah kembang lawang\"]', '[\"Rebus daging kambing yang sudah dibersihkan sebelumnya, kemudian potong sesuai selera (saya: dipotong dadu ukuran sedang); sisihkan air kaldunya\", \"Tumis bumbu yang dihaluskan langsung di panci prestonya, tambahkan bumbu pelengkap. Kemudian masukkan potongan daging kambing dan aduk secara merata kemudian cek rasa. Jangan lupa masukkan potongan kentangnya. Tutup dan masak kurang lebih 20 menit.\", \"Setelah matang sajikan dengan nasi tim panas - panas. Dijamin ada yang minta tambah lagi.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(668, 2, 'Gorengan kambing', 'Resep Gorengan kambing ala rumahan yang dijamin menggugah selera.', '[\"Secukupnya perutan kambing\", \"Secukupnya lada\", \"Secukupnya asam jawa\", \"Sedikit kecap manis\", \"Sesikit mentega\", \"Airbuntuk merebus\"]', '[\"Rebus perutan kurang lebih 30menit,buang airnya.sisihkan\", \"Taruh di wajan perutan yg sudah direbus,tambahkan air masukkan.lada halus,asam,garam.masak sampai air habis.setelah air menyusut kasih mentega aduk setelah itu kasih kecap.siap dinikmati\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(669, 4, 'Soup tulang kambing 🍲', 'Resep Soup tulang kambing 🍲 ala rumahan yang dijamin menggugah selera.', '[\"1 kg tulang kambing rebus kurleb 15 menit, beri perasan jeruk nipis\", \"4 siung bawang putih\", \"3 siung bawang merah\", \"2 cm jahe geprek\", \"2 buah daun bawang\", \"Seledri dan bawang goreng secukup nya\", \"Wortel,lobak, kentang uk besar (masing” 1 buah)\", \"2 biji bunga lawang\", \"1 buah kapulaga\"]', '[\"Haluskan duo bawang, masukkan ke wajan yg sudah di beri air dan garam secukupnya. Masukkan tulang kambing yg sdh di rebus, kapulaga, jahe dan bunga lawang. Tunggu sampai mendidih.\", \"Masukkan wortel, lobak, kentang yg sudah di iris. Tunggu smpai setengah matang.\", \"Masukkan daun bawang dan seledri yg sudah di iris. Tes rasa jika sudah masukkan bawang goreng. Siap di sajikan. 👌\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(670, 4, 'Tongseng Kambing Praktis', 'Tongseng Kambing Praktis - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1/4 daging kambing\", \"Bumbu gulai instan merk indofood\", \"5-7 bawang merah iris\", \"4-5 bawang putih iris\", \"Secukupnya kecap manis\", \"bungkus kecil Santan kara\", \"Kol\", \"Tomat\", \"Daun bawang\", \"Cabe rawit merah utuh\"]', '[\"Masak daging hingga lunak ±1jam tiriskan, sisihkan kaldunya\", \"Tumis bawang merah & bawang putihnya sampe kering baru tumis bumbu gulai instan\", \"Masukkan daging aduk sebentar tambahkan air kaldunya beserta cabe rawit utuh agar ikut matang\", \"Masukan kecap,icip rasa\", \"Masukan santan\", \"Kemudian masukkan kol,tomat & daun bawangnya\", \"Tongseng kambing siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(671, 4, 'Bledek kambing', 'Resep Bledek kambing ala rumahan yang dijamin menggugah selera.', '[\"1 paha depan kambing (kecil)\", \"10 atau lebih bawang merah iris\", \"3 bawang putih iris\", \"2 cabe merah\", \"2 cabe hijau\", \"2 cabe rawit\", \"(Cabe sesuai selera)\", \"1 sereh\", \"2 cm laos\", \"1 daun salam\", \"secukupnya Garam\", \"1 santan kara 65ml\"]', '[\"Potong2 daging lalu goreng sampai lumayan kering (masak kambing jangan dicuci ya)\", \"Tumis bumbu lalu masukkan daging tambah air.\", \"Setengah matang masukkan santan dan garam masak sampai empuk dan airnya nyemek2 (masi ada airnya sedikit) tes rasa,sajikan..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(672, 3, 'Krecek Kambing', 'Resep praktis Krecek Kambing yang bisa dicoba di rumah.', '[\"300 g daging kambing plus tulang, potong tipis2, cuci\", \"Secukupnya garam,gula merah/gula pasir, penyedap(optional)\", \"1 sdm asam jawa\", \"1 buah serai, simpulkan\", \"2 lembar daun salam\", \"Minyak untuk menumis\", \"750-1000 ml air\", \"Bahan diiris:\", \"3 siung bawang putih\", \"3 buah bawang merah\", \"1 cm jahe\", \"1 cm lengkuas\", \"1 buah cabe merah besar\"]', '[\"Tumis bawang merah dan bawang putih hingga harum. Tambahkan sisa bahan yang diiris, serai dan daun salam aduk rata hingga cabe merah sedikit layu. Masukkan daging kambing, aduk-aduk sampai berubah warna.\", \"Ketika daging sudah berubah warna masukkan air, garam, gula, penyedap dan asam jawa, aduk rata. Tunggu hingga air menyusut dan daging sudah empuk. Koreksi rasa dan siap disajikan dengan nasi hangat😍😄\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(673, 4, 'Lemak tulang kambing kuah santan', 'Sajian kambing spesial: Lemak tulang kambing kuah santan yang menggugah selera.', '[\"500 gr tulang kambing yang masih ada dagingnya dikit\", \"250 gr lemak kambing\", \"4 siung bawang merah\", \"4 siung bawang putih\", \"1 1/2 ruas kunyit\", \"4 cabe merah\", \"1/2 sdm ketumbar\", \"4 butir kemiri\", \"1 ruas kecil lengkuas geprek\", \"2 batang sereh ambil putihnya iris\", \"4 tangkai daun bawang\", \"1 bks santan kara\", \"4 sdm kecap manis\", \"1/2 bks royco rasa sapi\", \"Merica bubuk\", \"Garam\", \"Gula pasir\", \"Minyak\", \"Air\"]', '[\"Rebus tulang kurang lebih 1/2 jam\", \"Tumbuk halus bawang merah,bawang putih,kemiri,kunyit,ketumbar,cabe merah\", \"Iris daun bawang, sereh dan lengkuas\", \"Tumis bumbu halus, lengkuas dan sereh sampai harum\", \"Masukkan tulang dan lemak kambing beri air secukupnya\", \"Tambahkan santan, gula pasir,garam, merica bubuk,kecap manis,penyedap\", \"Aduk-aduk agar santan tidak pecah, sebelum di angkat tambahkan daun bawang\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(674, 2, 'Tongseng Kambing 🐐', 'Resep Tongseng Kambing 🐐 yang lezat dan mudah dibuat di rumah.', '[\"1/2 kg daging kambing\", \"Secukupnya kol (iris kasar)\", \"Bumbu rebusan :\", \"1 ruas jari lengkuas (geprek)\", \"2 btg serei (ambil putihnya aja, geprek)\", \"1/2 btr biji pala (geprek)\", \"3 lbr daun salam\", \"3 lbr daun jeruk\", \"Bumbu halus :\", \"8 siung bawang merah\", \"4 siung bawang putih\", \"3 bh cabe keriting\", \"1 ruas jari kunyit\", \"4 btr kemiri\", \"1 sdt jinten\", \"1 sdm ketumbar bubuk\", \"1/2 ruas jari jahe\", \"Bumbu iris :\", \"5 bh caber rawit (iris halus)\", \"2 bh tomat (potong bagi 4)\", \"1 btg daun bawang (iris kasar)\", \"Bumbu pelengkap :\", \"1 sachet kara (65 ml)\", \"3 sdm kecap manis (sy cm 1 sdm kecap tropicana slim)\", \"Secukupnya garam, merica\"]', '[\"Rebus daging kurleb 10 menit lalu buang airnya, lalu potong2 daging sesuai selera, sisihkan\", \"Didihkan lg air baru masukkan daging n bumbu rebusan, rebus kurleb 15 menit\", \"Sementara sambil merebus daging..tumis bumbu halus sampai harum, lalu masukkan k daging yg sedang d rebus\", \"Tambahkan bumbu pelengkap, kecilkan api, tutup wajan, tgg kurleb 20 menit (sblm d tutup aduk dl ya)\", \"Setelah 20 menit masukkan kol n bumbu iris, aduk sebentar lalu matikan api\", \"Done 😉\", \"Dagingnya jgn d cuci ya, d lap aja pk tissu dapur atw bersiin kotorannya, d ambilin gt...sy kbetulan dptnya bersih jd cm d lap2 dikit aja (ktnya klo d cuci bau kambingnya kcium banget)\", \"Saat buang air rebusan yg pertama, ambil dl dagingnya dr panci, baru buang air, jd klo ada sisa kotoran yg ga kliatan bs lgsg kbuang tanpa nempel atw ikut lg d daging kambingnya\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(675, 2, 'Asem-asem Balungan (Tulang kambing) 🐐 🐐', 'Nikmati kelezatan Asem-asem Balungan (Tulang kambing) 🐐 🐐 dengan resep sederhana ini.', '[\"1 kg tulang kambing/sapi\", \"2 ltr air\", \"3 lembar daun salam\", \"3 cm lengkuas (geprek)\", \"1 sdt garam\", \"1 batang serai (geprek)\", \"Bumbu (iris tipis) 🔪 🔪 :\", \"5 siung bawang putih\", \"20 buah belimbing wulu\", \"7 buah Lombok merah/hijau\", \"10 buah Cabai hijau (sesuai selera)\"]', '[\"Iris tipis semua bumbu.\", \"Cuci bersih tulang, rebus dengan 2lt air, lengkuas,serai, daun salam dan garam.\", \"Setelah mendidih masukan bumbu iris, koreksi rasa dan tunggu hingga empuk..\", \"Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(676, 4, 'Tongseng kambing tanpa santan', 'Sajian kambing spesial: Tongseng kambing tanpa santan yang menggugah selera.', '[\"1 kg daging kambing, iris\", \"2 L air\", \"1/2 bongkah kobis, rajang kasar\", \"3 batang daun bawang, rajang kasar\", \"3 buah tomat, iris menjadi 4 bagian per buah\", \"3 batang sereh, geprek\", \"3 cm laos, geprek\", \"3 lembar daun jeruk, remas\", \"2 lembar daun salam, remas\", \"Secukupnya garam\", \"Secukupnya gula pasir\", \"2 sdm kecap manis\", \"Bumbu halus:\", \"6 siung bawang merah\", \"4 siung bawang putih\", \"3/4 sdm ketumbar\", \"1 sdm merica\", \"4 butir kemiri\", \"1 cm jahe\", \"1 cm kunyit\", \"3 buah cabe merah keriting\", \"5 cabe rawit\"]', '[\"Rebus daging dengan air sampai empuk\", \"Tumis bumbu halus sereh, salam, laos, daun jeruk sampai layu dan harum, masukkan daging kambing dan air kaldu.\", \"Tambahkan garam dan gula pasir secukupnya (jangan banyak-banyak dulu karena air akan disusutkan), tambahkan kecap manis.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(677, 3, 'Curry kambing India', 'Buat Curry kambing India yang nikmat dengan langkah-langkah mudah ini.', '[\"1 kl dgng kambing (potong2)\", \"1/2 kl tulng rusuk kambing di potong2 (pilih kambing yg sama ya)\", \"1 ons cabe merah kriting\", \"1 ons bawang merah\", \"1 ons /1 buah bawang bombay (potong2 kecil)\", \"1 jempol jahe\", \"2 jempol kunyit\", \"1 buah bintang bunga lawang\", \"4 sdm ketumbar halus\", \"1/2 sdt jinten\", \"1 buat tomat merah yg besar(potong kecil2)\", \"3 helai serumpun daun Curry (kalaw ada saja)\", \"1 batang daun bawang (potong kecil2)\", \"1 saset masaco rasa apa saja + garam secukupnya\"]', '[\"Tumis bawang bombay,daun curry, bunga lawang. Setelah bawang menguning masukkan bumbu yg di haluskan(cabe besar&kecil bawang merah,jahe kunyit\", \"Setelah matang masukkan bumbu bubuk carry, jinten, ketumbar,setelah wangi masukkan tomat & daun bawang lalu masukkan daging, masaknya di tutup ya dengan api kecil\", \"Setelah setengah matang masukkan masaco dan garam secukupnya.sering di lihat di aduk jangan sampai gosong ya... Setelah matang siap di sajikan.👌😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(678, 4, 'Tengkleng kambing manis', 'Resep Tengkleng kambing manis ala rumahan yang dijamin menggugah selera.', '[\"500 gr Iga kambing\", \"1 ruas sereh geprek\", \"1 jari lengkuas geprek\", \"3 lbr daun jeruk\", \"Bumbu halus\", \"5 siung bawang putih\", \"7 siung bawang merah\", \"3 buah cabe merah(resep asli gak pake)\", \"1 buah bungapekak\", \"1/4 sdt jintan\", \"1/2 sdt lada bubuk\", \"2 buah kapulaga\", \"Secukupnya Gula garam kecap\"]', '[\"Potong2 daging. Iganya dibelah mengikuti tulangnya. Daging kambing JANGAN DICUCI. Tapi rebus sebentar lalu buang airnya. Ini akan membersihkan semua kotoran yg ada di daging.\", \"Rebus daging dengan lengkuas, sereh dan daun jeruk. Ini akan mengusir aroma prengus kambing. Rebus sampai empuk.Saya pakai presto 20 menit.\", \"Tumis bumbu halus, resep asli gak pake cabe merah. Saya pakai cabe supaya warnanya agak merah dan agak pedas.\", \"Masukkan daging beserta airnya kedalam tumisan. Masukkan garam gula.sampai setengah menyusut. Terakhir kecap. Masak sampai berkaramel. Tes rasa.\", \"Beneran enak banget. Lebih enak dr aslinya. Krn saya tambahin cabe merah jd rasanya manis sedikit pedas. Trus ada cabe rawit utuhnya. Kalau mau pedas tinggal gigit cabenya😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(679, 3, 'Sop iga kambing', 'Buat Sop iga kambing yang nikmat dengan langkah-langkah mudah ini.', '[\"1 kg iga kambing\", \"3 L air untuk merebus\", \"Bumbu :\", \"4 siung bawang putih, iris\", \"6 siung bawang merah, iris\", \"1/2 butir pala, geprek\", \"4 butir cengkeh\", \"1/2 sdt lada, haluskan\", \"secukupnya Garam\", \"1 buah tomat, potong2\", \"4 buah wortel, kupas dan potong2\", \"3 lembar kol, iris agak besar\", \"secukupnya Penyedap\", \"2 batang daun bawang\", \"2 batang daun seledri\", \"Bahan pelengkap :\", \"secukupnya Bawang goreng\", \"Acar mentimun/wortel\", \"Sambal\"]', '[\"Didihkan air, masukkan iga kambing dan garam, rebus sampai empuk.\", \"Tumis bawang putih dan bawang merah, angkat dan siramkan ke dalam rebusan iga.\", \"Masukkan tomat, pala, cengkeh, lada, penyedap dan wortel, masak sampai kira2 wortel matang, terakhir masukkan kol, daun bawang dan seledri, cek rasa dan matikan api.\", \"Hidangkan di mangkok panas2, taburi bawang goreng, dan sajikan dengan acar mentimun dan sambal. (kalo saya berhubung kehabisan mentimun dan wortel akhirnya bikin irisan rawit dan bawang merah yg diaduk dengan garam dan jeruk nipis).. hmmm segarnyaaa..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(680, 2, 'Pete Kambing Kecap', 'Pete Kambing Kecap dengan daging kambing empuk tanpa bau prengus.', '[\"1 Kg Daging Kambing (Potong-Potong)\", \"6 Siung Bawang Putih (Iris Tipis)\", \"6 Siung Bawang Merah (Iris Tipis)\", \"2 Lembar Daun Salam\", \"Secukupnya garam\", \"Secukupnya Penyedap\", \"Secukupnya Air\", \"250 Gram Pete (Cuci Bersih)\", \"Secukupnya Kecap Manis\", \"Secukupnya Minyak\"]', '[\"Siapkan minyak dalam wajan hingga panas. Masukkan bawang putih, bawang merah & daun salam. Tumis sampai harum.\", \"Setelah harum masukkan daging kambing, masak sampai matang.\", \"Tambahkan air, lalu tutup wajan sampai daging kambing empuk. Kalo belum empuk kasih air lagi sampai benar-benar daging kambing empuk.\", \"Setelah daging kambing empuk, masukkan pete lalu tambahkan kecap manis, garam, penyedap.\", \"Masak sebentar sampai semua meresap.\", \"Koreksi rasa.\", \"Angkat & sajikan.\", \"Selamat mencoba.\", \"Note : Kalau daging kambing belum empuk jangan di beri kecap. Air saja dulu sampai empuk. Karena kalo sudah masuk kecap, daging kambing gak empuk-empuk.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(681, 4, 'Sop tulang iga kambing', 'Buat Sop tulang iga kambing yang nikmat dengan langkah-langkah mudah ini.', '[\"500 gram tulang iga kambing\", \"2 buah wortel\", \"2 buah kentang\", \"secukupnya Daun bawang\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"1 biji bawang bombay\", \"Jahe kira2 seujung jari kelingking,pala dan merica\", \"1 bungkus royco sapi\", \"1 buah bunga sisir/bunga lawang/pekak\", \"3 biji kapulaga, 3 biji cengkeh\", \"secukupnya Garam dan gula,minyak goreng\"]', '[\"Tulang iga dicuci dan direbus sampai empuk\", \"Bawang merah,bawang putih,jahe,pala,merica,diulek sampai halus\", \"Bawang bombay diiris dan ditumis agak layu dan masukkan bumbu halus,aduk sampai wangi bumbu tercium,angkat dan masukan bumbu kedalam rebusan tulang iga\", \"Masukan kapulaga,bunga sisir,cengkeh,royco, kentang,wortel yang sudah dibersihkan dan dipotong sesuai selera\", \"Tambahkan garam dan gula secukupnya,tunggu kentang dan wortel empuk,masukan irisan daun bawang,tes rasa,dan sop tulang iga kambing siap disajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(682, 3, 'Sate kambing bumbu kacang', 'Resep Sate kambing bumbu kacang yang lezat dan mudah dibuat di rumah.', '[\"Daging kambing\", \"Kacang goreng\", \"Kecap bangau\", \"Tomat\", \"Bawang putih\", \"Bawang merah\", \"Lombok hijau\", \"Gula merah\", \"Garam\", \"Mentega\"]', '[\"Potong daging kambing kecil kecil\", \"Tusukkan ke biting(disini saya menambah ati untuk variasi?\", \"Bakar sate menggunakan arang setengah matang,, lalu oleskan kecap dan bumbu mentega dan bawang putih yg sudah diharuskan,\", \"Bakar lagi sampai matang\", \"Bumbu sambalnya: bawang merah dan lombok diiris tipis, tomat diiris agak besar\", \"Bumbu uleg: kacang, bawang putih, garam, gula jawa, dihaluskan kemudian diberi air secukupnya\", \"Sate disajikan dipiring, kemudian ditaburi bawang merah, lombok dan tomat yg sudah di potong potong\", \"Bumbu uleg yg sudah diberi air di gebyurkan ke sate, kemudian ditambahkan kecap\", \"Sate siap dihidangkan, selamat makan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(683, 2, 'Sate Kambing (#Bumbu Manis)', 'Buat Sate Kambing (#Bumbu Manis) yang nikmat dengan langkah-langkah mudah ini.', '[\"300 gram daging kambing\", \"Bumbu manis\", \"2 Siung bawang merah\", \"1 siung bawang putih\", \"1/2 sdt ketumbar\", \"Sejumput jinten\", \"1 sdt gula jawa\", \"1 mata asem jawa\", \"sesuai selera Garam\", \"2 sdm kecap manis\", \"2 sdm olive oil\"]', '[\"Pertama haluskan bumbu untuk sate, beri kecap dan olive oil, aduk merata\", \"Daging yg sdh kita potong dadu, dibungkus dengan daun pepaya, lalu diamkan 15-45 menit tergantung dagingnya\", \"Tusuk dengan tusukan sate lalu beri bumbu manisnya\", \"Bungkus kembali dengan daun pepaya tunggu sampai bara api siap atau bakar pakai teplon\", \"Bakar sambil sesekali diolesi dengan sisa bumbu\", \"Sajikan dengan nasi hangat, sambel kecap (isi, bawang, rawit, dan tomat iris beri air jeruk limau)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(684, 2, 'Nasi kebuli kambing', 'Sajian Nasi kebuli kambing yang praktis dan lezat untuk dinikmati bersama.', '[\"1 liter beras cap mangkok\", \"200 gr santan kental\", \"100 gr susu cair\", \"1 bh bawang bombay uk besar\", \"250 gr daging kambing\", \"1 sdt bubuk kayu manis\", \"1/2 sdt bubuk kapulaga\", \"1/2 sdt bubuk jinten\", \"1/2 sdt pala bubuk\", \"50 gr mentega\"]', '[\"Cuci bersih beras sisihkan\", \"Rajang kasar bawang bombay sisihkan\", \"Cuci daging kambing sisihkan\", \"Tumis bombay dgn mentega sampai harum masukkan bumbu masak sampai harum masukan daging kambing tunggu kurleb sampai kambing berubah warna masukan beras campur dng bumbu dan kambing. masukan santan dan susu masak sampai nasi menjadi aron tambahkan garam secukupnya kurleb 1sdt\", \"Panaskan kukusan masukan nasi aron masak kurleb 40 menit\", \"Sajikan dgn lauk rendang, acar dan balado kentang resep yg lain menyusul silahkan mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(685, 4, 'Frikase kambing dgn daun pulowaras/ pulosari makan khas yunani', 'Frikase kambing dgn daun pulowaras/ pulosari makan khas yunani - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 paha kaki kambing\", \"1 buah lemon\", \"10 buah selada\", \"secukupnya Garam\", \"Merica\", \"secukupnya Air\", \"10 batang Daun bawang\", \"Daun pulosari/ pulowaras\", \"Minyak sayur\"]', '[\"Cuci bersih semua bahan\", \"Masukan minyak sayur dan masukan daging kambing ke dlm panci yg sudah di cuci masak dgn api sedang kira2 15 mnt\", \"Masukan daun bawang dan daun pulosari ygsudah di iris kecil2, garam, merica kemudian tambahkan sedikit air mendidih, tutup dan masak hingga kurang lbh 1 jam sampai daging benar2 empuk\", \"Setelah daging empuk, potong selada jadi 3 bagian, dan masukan masak lagi kira2 20 mnt pastikan selada matang\", \"Dan yg terakhir kocok 2 kuning telor dgn 1 perasan lemon tambahkan kira2 1/2 gelas air dan kocok, kemudian tuangkan pelan2 ke dlm panci dlm keadaan panas, dan angkat...biasanya cukup dimakan hanya dgn roti ya,,,selamat mencoba👌🏻👌🏻👌🏻\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(686, 3, 'Tengkleng kambing', 'Sajian kambing spesial: Tengkleng kambing yang menggugah selera.', '[\"1 kg daging kambing n campuran tulang\", \"2,5 liter santan encer\", \"2 lembar daun salam\", \"6 lembar daun jeruk purut\", \"5 cm jahe dimemarkan\", \"2 batang serai memarkan\", \"2 sdm kecap manis\", \"Bumbu yang dihaluskan:\", \"10 bawang merah\", \"6 bawang putih\", \"6 cm kunyit bakar\", \"4 cm lengkuas\", \"5 kemiri\", \"1 sdm ketumbar disangrai\", \"2 sdm gula jawa\", \"1 sdm garam\", \"1 sdm mottto\", \"secukupnya Kaldu bubuk\"]', '[\"Tumis bumbu yang dihaluskan berserta daun jeruk, daun salam n serai,jahe hingga berbau harum,masukkan daging kambing n tulang kambing lalu tambahkan santan encer,masak dengan api sedang untuk menunggu daging empuk\", \"Tambahkan santai kental n kecap manis masak hingga mendidih dan bumbu meresap, angkat n siap disajikan\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(687, 2, 'Asem-asem Iga Kambing', 'Resep Asem-asem Iga Kambing ala rumahan yang dijamin menggugah selera.', '[\"700 gr Iga Kambing\", \"200 gr Jerohan Kambing\", \"50 ml Minyak Goreng\", \"1 Liter Air Putih\", \"1 Buah Tomat Merah (Iris)\", \"2 Buah Tomat Hijau (Iris)\", \"Bumbu Iris ::\", \"5 Siung Bawang Putih\", \"7 Siung Bawang Merah\", \"30 gr Cabe Merah Keriting\", \"50 gr Cabe Hijau Keriting\", \"6 Cabe Rawit (Opsional)\", \"1 sdm Asem Jawa Tanpa Biji (Opsional)\", \"5 cm Lengkuas (Dimemarkan)\", \"3 Lembar Daun Salam\", \"3 Lembar Daun Jeruk Purut\", \"Bumbu Pelengkap ::\", \"2 sdm Kecap Manis (Opsional)\", \"1 sdt Kaldu Bubuk\", \"1/3 sdt Lada Bubuk\", \"Secukupnya Garam\", \"Secukupnya Penyedap Rasa\", \"Secukupnya Gula Pasir\"]', '[\"Siapkan iga dan jerohan kambing yang sudah direbus dan sudah empuk, air rebusan dibuang ya. Tiriskan iga dan jerohan kambingnya.\", \"Panaskan minyak goreng, tumis bumbu iris hingga harum.\", \"Kemudian tuang air dan masukkan iga serta jerohan kambing, beri bumbu pelengkap..masak hingga mendidih.\", \"Sesaat sebelum matang masukan irisan tomat, aduk rata..dan matikan api.\", \"Asem-asem iga kambing ala bunda siap disajikan..selamat sarapan pagi.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(688, 3, 'Marak (Sop Kambing Khas Timur Tengah)', 'Resep praktis Marak (Sop Kambing Khas Timur Tengah) yang bisa dicoba di rumah.', '[\"500 gr daging kambing + tulang\", \"2 bh kentang (potong jadi 8=16)\", \"2 bh wortel (potong miring)\", \"2 btg daun bawang (iris sedang)\", \"3 btg daun seledri (iris tipis)\", \"1 bh tomat (potong jd 4)\", \"Bumbu rebusan ke-2\", \"5 bj cengkeh\", \"5 bj kapulaga\", \"2 cm kayu manis\", \"Bumbu Iris\", \"-1 bh bawang bombay\", \"10 bh bawang merah\", \"2 bh bawang putih\", \"1 ruas jempol jahe / boleh digeprek\", \"Bumbu Halus\", \"-5 bh bawang putih\", \"4 bh bawang merah\", \"1 sdt jintan\", \"1/2 sdt lada bubuk\", \"1/2 sdt kunyit bubuk / 1 ruas kunyit\", \"1/2 sdt ketumbar\", \"1/2 sdt kapulaga bubuk (optional)\", \"2 sdt bumbu gulai instant indofood\", \"Bumbu Rempah\", \"-10 bj cengkeh\", \"10 bj kapulaga\", \"2 cm kayu manis\", \"Lainnya\", \"4 sdm olive oil / minyak sayur untuk menumis\", \"secukupnya Garam\", \"Secukupnya gula pasir\", \"Air untuk merebus daging\"]', '[\"Cuci bersih daging + tulangnya. Rebus air sebanyak daging dan tulang kerendam semua,sampai mendidih, dan masukkan daging tulangnya kira2 5 menit. Buang air rebusan, dan cuci kembali daging + tulang, tiriskan.\", \"Rebus air lagi sampai mendidih. Masukkan daging + tulang sampai kerendam semua. Kemudian masukkan wortel dan kental yg sudah dipotong. Masukkan cengkeh, kapulaga dan kayu manis. Jika kentang dan wortel sudah empuk duluan, tiriskan. Dan biarkan daging direbus sampai benar2 empuk. Tiriskan daging dan potong2 sesuai selera.\", \"Sambil menunggu daging direbus, kita siapkan bumbu iris, bumbu halus, dan bumbu rempah lainnya.\", \"Panaskan wajan, masukkan olive oil. Tumis bawang bombay bawang putih bawang merah sampai layu dan harum.\", \"Masukkan bumbu halus,bumbu rempah,daging yg sudah dipotong,bumbu gulai instan, dan sedikit air kaldu rebusan daging. Tumis sampe bumbu meresap ke daging dan air asat.\", \"Masukkan semua kuah kaldu rebusan daging, beserta tulangnya, wortel kentang dan irisan seledri. Diamkan sampai mendidih.\", \"Kemudian masukkan garam dan gula pasir, koreksi easa. Jika sudah pas, masukkan irisan daun bawang dan potongan tomat. Aduk sebentar, matikan kompor.\", \"Sajikan diatas mangkuk, taburi bawang goreng yang banyak.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(689, 3, 'Nasi kambing (nasi Arab)', 'Nasi kambing (nasi Arab) - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 kg beras basmati, beras India atau Arab\", \"500 gram daging kambing usahakan yg masih pake tulang\", \"Jangan dicuci ya daging nya\", \"4 sdm ghee India / minyak samin\", \"1 buah bawang bombai iris\", \"Kayu manis batang 5 sampai 10 cm\", \"8 kapulaga\", \"1/2 biji pala memarkan\", \"5 cengkeh\", \"5 daun salam\", \"Air 500 ml untuk matengin beras\", \"750 ml santan atau bisa juga susu\", \"Bumbu halus\", \"10 bawang merah\", \"6 bawang putih\", \"5 cm jahe\", \"1.5 sdm Ketumbar sangrai\", \"1 sdm Merica bubuk\", \"Gula\", \"Garam\"]', '[\"Tumis bawang bombay sampai wangi, masukan bumbu halus, cengkeh, kayu manis dan daun salam. Masak hingga wangi.\", \"Masukan daging kambingnya, masak hingga berubah warna. Kasih air masak kira kira 500 ml dan tutup hingga agak empuk dagingnya dan berkurang airnya, lalu masukan beras.masak hingga air menyerap pada beras lalu matikan.hingga jadi nasi aron.\", \"Kemudian siapkan magic jar, pindahkan beras dan daging tadi beri santan sesuai batas biasa masak nasi. Masak hingga matang. Hidangkan dengan acar, dan emping. Bisa dipadukan dengan kacang almond dan kismis juga.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(690, 4, 'Gulai kambing kuah susu', 'Sajian Gulai kambing kuah susu yang praktis dan lezat untuk dinikmati bersama.', '[\"1 kg daging kambing\", \"3 liter air\", \"1000 ml susu putih cair full cream(plain)\", \"Bumbu yang dihaluskan :\", \"10 siung bawang merah\", \"5 siung bawang putih\", \"3 sdm ketumbar\", \"2 sdm merica\", \"1 jumput Jinten\", \"5 butir kapolaga\", \"Sepotong jahe\", \"Sepotong lengkuas\", \"Sepotong kunyit\", \"Biji pala sesuai selera\", \"5 lembar daun jeruk\", \"3 lembar daun salam\", \"2 batang sereh digeprek\", \"2 lembar daun kunyit\", \"sesuai selera Cabe merah\", \"secukupnya Garam\"]', '[\"Cuci daging kambing sampai bersih\", \"Siapkan bumbu yg sudah dihaluskan lalu tumis sampai harum\", \"Campurkan daging kambing dg bumbu yg sdh di tumis, aduk sampai bumbu merata di daging\", \"Masukkan satu liter air ke dalam daging kambing yg sdh dibumbui,lalu masak daging kambing di panci yg bertekanan tinggi sekitar 15 menit\", \"Angkat daging kambing dari panci bertekanan tinggi dan tuang ke dalam panci biasa, masukkan susu cair full cream, tambahkan sisa air, masukkan daun jeruk, salam,sereh, daun kunyit aduk sampai mendidih,jk perlu tambahkan garam, jangan terlalu lama dimasak krn daging sdh empuk ketika dimasak di panci bertekanan tinggi\", \"Sajikan gulai kambing dengan nasi hangat, selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(691, 4, 'Sambal Goreng Daging Kambing Tahu', 'Sambal Goreng Daging Kambing Tahu dengan daging kambing empuk tanpa bau prengus.', '[\"1 kg daging kambing\", \"2 potong tahu ukuran besar, potong kotak\\\" kecil\", \"4 lembar daun jeruk\", \"2 lembar daun salam\", \"4 cm laos, geprek / parut\", \"2 cm jahe, geprek / parut\", \"1 sdm asam jawa, larutkan\", \"2 sdm gula merah\", \"Secukupnya garam\", \"Minyak goreng\", \"Bumbu yang dihaluskan :\", \"8 siung bawang merah\", \"6 siung bawang putih\", \"2 ons lombok merah\"]', '[\"Goreng tahu. Tiriskan.\", \"Rebus daging kambing. Potong kotak\\\" kecil. Goreng. Tiriskan.\", \"Tumis bumbu halus hingga matang.\", \"Masukkan semua bahan lainnya. Aduk. Masak hingga bumbu meresap dengan api kecil.\", \"Tes rasa. Siap disajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(692, 3, 'Iga Kambing Cardamom', 'Nikmati kelezatan Iga Kambing Cardamom dengan resep sederhana ini.', '[\"1/2 kg iga kambing\", \"3 lembar daun salam\", \"1 batang serai\", \"1 batang daun bawang\", \"7 biji cardamom(kapulaga)\", \"2 biji cengkeh\", \"Sepotek kayu manis\", \"bumbu halus\", \"5 butir kemiri\", \"5 buah bawang merah\", \"3 siung bawang putih\", \"5 buah cabe merah besar\", \"1 ruas kunyit\", \"1 ruas jahe\", \"1 ruas laos\"]', '[\"Cuci iga nya lalu rebus sbntar, tumis bumbu halusnya hingga mnyusut beri sdikit minyak goreng aduk rata jgn smpe gosong pinggirannya lalu masukkan iganya, daun salam, serai, kapulaga, cengkeh, kayu manis, garam, penyedap, gula tuangkan air tutup biarkan mendidih kecilkan apinya masak sampe agak empuk dagingnya.\", \"Tes rasa bila ada yg kurang tambahkan aja taburkann daun bawang yg udah dipotong2..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(693, 4, 'Rendang bumbu kuning pedas (daging kambing)', 'Resep Rendang bumbu kuning pedas (daging kambing) ala rumahan yang dijamin menggugah selera.', '[\"1/4 daging kambing\", \"5 siung Bawang merah\", \"4 siung Bawang putih\", \"Cabe merah (me;3)\", \"Cabe rawit (me;2)\", \"1/2 ruas jari kunyit\", \"1 bungkus santan kara\", \"Jahe\", \"Lengkuas\", \"Daun salam\", \"Dau jeruk\", \"Sereh\", \"Kemiri\", \"Ketumbar\", \"Lada bubuk\", \"Garam\", \"Gula\", \"Kaldu bubuk\"]', '[\"Cuci bersih daging kambing/sapi, rebus daging dg jahe+bawang putih+salam sampai empuk. Angkat tiriskan (buang air sisa rebusan)\", \"Siapkan bumbu halus, bawang merah, bawang putih, jahe, cabe, kunyit, ketumbar, kemiri, lada.\", \"Tumis bumbu halus sampe wangi, masukkan daun salam, daun jeruk, sereh, lengkuas aduk2 masukkan daging, tambahkan air diamkan hingga air tinggal sedikit dan tambahkan santan, masukkan garam, gula, kaldu bubuk, aduk2 diamkan sampai meresap air dan bumbunya. Cicip rasa. Matikan kompor aduk2 sebentar angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(694, 2, 'Semur kambing', 'Cara membuat Semur kambing yang enak dan praktis untuk keluarga.', '[\"1 kg daging kambing yg bertulang\", \"1 ruas jahe\", \"1 ruas lengkuas\", \"Sedikit kunyit\", \"Sepotek cabe merah\", \"6 siung bawang merah\", \"1 siung bawang putih\", \"3 bh kemiri\", \"1/2 sdt lada\", \"1 bh bawang bombai\", \"1/4 biji pala\", \"6 bh cengkeh\", \"Secukupnya garam\", \"Secukupnya kecap manis\", \"Secukupnya minyak untuk menumis\"]', '[\"Haluskan semua bahan kecuali bombai cengkeh dan biji pala\", \"Iris bawang bombai,tumis hingga harum. Masukkan bumbu halus,tambahkan air sedikit demi sedikit sambil terus diaduk aduk,masukkan pala,cengkeh\", \"Jika bumbu sudah tidak bau langu masukkan kambing,aduk aduk,tambahkan air dan garam. Pindahkan ke panci presto,kecilkan api\", \"Presto sampai 20menit setelah panci berbunyi.matikan kompor.buka tutup presto tambahkan kecap. Aduk sampai rata, diamkan sampai air mengental dan bumbu meresap. Jika menyukai model semur yang berkuah banyak cukup tunggu sampai bumbu meresap\", \"Tes kekenyalan daging,jika dirasa masih keras boleh dipresto lagi\", \"Note: jika kambing ditaruh di frezer.diamkan dulu disuhu ruang sampai tidk beku lagi, jangan direndam sekalipun keadaan kambing dalam plastik. Sesaat sebelum dimasukkan ke bumbu,cuci dengan air mengalir sebentar,agar daging tidak bau.\", \"Dan catatan ke2.. sebenernya kambing diglondongin juga udah enak jd kayanya ga perlu pakai penyedap lg.tp kl ini mah bebas sih\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(695, 3, 'Sop Iga Kambing', 'Resep Sop Iga Kambing ala rumahan yang dijamin menggugah selera.', '[\"Bahan :\", \"750 gr Iga Kambing (aku campur sama dagingnya), potong2\", \"secukupnya Garam\", \"4 lembar Daun Jambu Biji\", \"3 sdm Air Cuka\", \"2 batang Daun Bawang, iris tipis 2 cm\", \"2 buah Tomat, potong dadu\", \"4 cm Kayu Manis\", \"4 butir Cengkeh\", \"1 ruas Jahe, geprek\", \"Secukupnya Penyedap Rasa\", \"Secukupnya Gula\", \"Sedikit Minyak Goreng untuk menumis bumbu halus\", \"Bumbu Halus :\", \"10 siung Bawang Merah\", \"4 siung Bawang Putih\", \"3 buah Cabai Merah (tergantung selera suka pedes atau ga)\", \"1 sdt Merica (optional)\", \"Pelengkap :\", \"2 batang Seledri, Iris Halus\", \"2 sdm Bawang Goreng\", \"Jeruk Nipis, Kecap, Sambal Cabe\"]', '[\"Rebus sampai mendidih, iga kambing bersama daun jambu biji dan air cuka serta garam, agar daging empuk dan tidak berbau.. Setelah mendidih, kecilkan api, tutup panci tidak rapat, setelah daging empuk, angkat daging.. Bersihkan daging menggunakan air bersih..\", \"Rebus kembali daging di air kurang lebih 1liter (tergantung mau kuahnya banyak atau tidak)..\", \"Tumis bumbu halus, masukkan kayu manis, cengkeh, dan jahe.. Masak hingga aromanya keluar.. Masukkan bumbu tumis ke dalam panci berisi daging..\", \"Teruskan rebus hingga mendidih, masukkan garam, gula, penyedap rasa.. Sambil d rasa ya bunda, apakah rasanya sudah pas atau belum..\", \"Masukkan daun bawang dan tomat, masak sebentar.. Angkat..\", \"Sajikan dengan irisan seledri dan taburan bawang goreng..\", \"Bisa di makan menggunakan nasi ataupun ketupat/lontong nasi ya.. Sesuai selera..\", \"NOTE : Iga dan daging kambing yg di siapkan (di sembelih atau di beli), jangan langsung di bersihkan dg air.. Langsung saja di rebus dg daun jambu dan air cuka.. Tujuannya mengurangi bau daging kambing.. Setelah di rebus baru di bersihkan dan di olah..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(696, 3, 'Tongseng kambing dadakaan :D', 'Nikmati kelezatan Tongseng kambing dadakaan :D dengan resep sederhana ini.', '[\"1/4 kg daging kambing\", \"2 buah tomat ukuran sedang\", \"5 lonjor daun bawang\", \"1/4 potong kubis\", \"1 sct santan kara\", \"2 sendok makan kecap manis\", \"500 ml air\", \"Minyak goreng\", \"Bumbu halus :\", \"1/4 bungkus lada bubuk\", \"1/4 bungkus ketumbar\", \"1/2 ruas jari jahe\", \"1/2 ruas jari lengkuas\", \"1/4 ruas jari kunyit\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"3 butir kemiri\", \"1 batang serai geprek dan\", \"3 lembar daun salam\", \"2 buah cabai besar\", \"Garam\", \"Gula\", \"Penyedap rasa\"]', '[\"Daging kambing dipotong dadu dan cuci bersih\", \"Tomat, daun bawang, kubis potong sesuai selera\", \"Panaskan minyak, tumis bumbu halus sampai harum dan masukan daun salam serta serai. Tumis sampai layu\", \"Setelah bumbu harum dan berubah warna, masukan air aduk rata. Masukan bu santan aduk kembali.\", \"Masukan potongan daging. Rebus sampai empuk. Setelah empuk, masukan santan aduk rata.\", \"Tambahkan garam, kecap, gula dan penyedap. Koreksi rasa.\", \"Setelah daging empuk dan semua rasa ok, masukan kubis, daun bawang, cabai iris dan tomat. Masak kurleb 3 menit.\", \"Aduk kembali dan tongseng siaap dihidangkan. Untuk tambahan bisa ditaburi bawang goreng agar lebih sedap. Selamat mencoba.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(697, 2, 'Tengkleng Kambing Bumbu Instan', 'Nikmati kelezatan Tengkleng Kambing Bumbu Instan dengan resep sederhana ini.', '[\"300 gr Iga,Tulang Kambing\", \"200 gr Jeroan Kambing\", \"200 gr Daging Kambing\", \"1 Bungkus Bumbu Instan Gulai\", \"2 Bungkus Santan Instan\", \"50 ml Minyak Goreng\", \"1 Liter Air Putih\", \"Secukupnya Cabe Rawit Utuh\", \"Secukupnya Bawang Goreng\", \"Bumbu Iris ::\", \"5 Siung Bawang Putih\", \"7 Siung Bawang Merah\", \"2 Batang Sereh (Dimemarkan)\", \"5 cm Lengkuas (Dimemarkan)\", \"5 cm Jahe (Dimemarkan)\", \"4 Lembar Daun Jeruk Purut\", \"2 Lembar Daun Salam\", \"10 cm Kayu Manis\", \"3 Butir Kapulaga\", \"3 Biji Cengkeh\", \"Bumbu pelengkap ::\", \"1 sdt Kaldu Bubuk\", \"1/3 sdt Lada Bubuk\", \"1/4 sdt Jintan\", \"Secukupnya Penyedap Rasa\", \"Secukupnya Garam\", \"Secukupnya Gula Pasir\", \"2 sdm Kecap Manis\"]', '[\"Rebus/presto iga,tulang, daging dan jeroan kambing hingga empuk, buang kuahnya dan kemudian potong daging sesuai selera.\", \"Panaskan minyak goreng, tumis semua bumbu iris dan bumbu instan gulai sampai harum.\", \"Masukkan irisan daging dan iga/tulang kambing, aduk rata, masukkan air putih, beri bumbu pelengkap, aduk rata, masak hingga mendidih kemudian tuang santan dan cabe rawit, aduk terus agar santan tidak pecah. Masak hingga mendidih dan matang.\", \"Taburi bawang goreng dan tengkleng kambing bumbu instan ala saya siap disajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(698, 4, 'Tonseng Kambing', 'Sajian Tonseng Kambing yang praktis dan lezat untuk dinikmati bersama.', '[\"1 kg daging kambing\", \"1 potong nanas,parut\", \"Garam\", \"Bumbu halus:\", \"8 siung bawang merah\", \"6 siung bawang putih\", \"5 bh cabe merah keriting\", \"2 bh kemiri sangrai\", \"1/2 sdt ketumbar bubuk\", \"1/2 sdt pala bubuk\", \"1 ruas kunyit\", \"1 ruas jahe\", \"Sedikit jintan\", \"Minyak goreng\", \"Sedikit air\", \"Garam\", \"Merica\", \"Bumbu tumis:\", \"1 ruas lengkuas\", \"2 btg serai\", \"3 lbr daun salam\", \"2 lbr daun jeruk\", \"2 btg kayu manis\", \"4 bh cengkeh\", \"5 bh kapulaga\", \"2 bh bunga pekak/lawang\", \"1 bks santan kara\", \"1 ltr air\", \"Pelengkap:\", \"Kol\", \"Tomat hijau dan merah,iris\", \"Daun bawang,\", \"Cabe rawit merah\", \"Kecap\"]', '[\"Potong daging kambing seperti dadu, tambahkan nanas parut dan garam. Simpan di kulkas kurang lebih 2 jam\", \"Haluskan bumbu halus hingga halus\", \"Panaskan minya lalu tumis terlebih dahulu bumbu tumis hingga harus tambahkan bumbu halus lalu tumis hingga benar benar matang. Tambahkan air dan santan serta garam, merica. Masak hingga mendidih.\", \"Saring kuah gulai agar bersih. Sisihkan\", \"Panasakan wajan dengan sedikit minyak tumis daging kambing hingga berubah warna, tambahkan kuah gulai beri bahan pelengkap. Masak hingga tomat dan kol layu. Koreksi rasanya\", \"Sajikan dengan nasi panas,kerupuk dan acar timun jika ada.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(699, 2, 'Pindang tulang (kambing)', 'Sajian kambing spesial: Pindang tulang (kambing) yang menggugah selera.', '[\"tulang kambing cuci bersih\", \"3 siung bawang putih\", \"5 siung bawang merah\", \"3 cabe merah\", \"kunyit\", \"jahe\", \"5 cabe rawit (tergantung selera)\", \"seebagian bumbu diuleķ dan sebagian di iris2\", \"lengkuas digeprek\", \"sere digeprek\", \"daun kemangi\", \"daun salam\", \"nanas diiris sedang\", \"garam\", \"air\", \"nanas\"]', '[\"Panaskan minyak, tumis bumbu iris dan bumbu halus. masukka lengkuas, sere, dan daun salam. masukkan gula merah. setelah bumbu mateng. tambahkan air dan masukkan tulang. aduk sampai bumbu merata.\", \"Stlh mendidih tambahkan lagi air. masukkan nanas. tutup hingga mendidih\", \"Cek rasa, masukkan kemangi dan matikan kompor. jadi deh 😆\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(700, 2, 'Nasgor Kambing (Memanfaatkan sate dan gulai)', 'Buat Nasgor Kambing (Memanfaatkan sate dan gulai) yang nikmat dengan langkah-langkah mudah ini.', '[\"Gulai dan sate kambing disuir2. Gulainya sisihkan dari kuahnya\", \"1,5 piring nasi dingin\", \"3 siung bawang merah iris\", \"2 siung bawang putih iris\", \"1 ruas jari kunyit\", \"1 butir telur\", \"Garam, gula, kecap manis\", \"Kaldu bubuk, lada\", \"5 buah cabe rawit iris\", \"Minyak zaitun atau margarin untuk menumis\"]', '[\"Ulek kunyit sampai halus, biar kunyitnya merata di nasinya. Duo bawangnya saya ikut ulek kasar aja. Ga diulek gpp.\", \"Panaskan minyak tumis bumbu td sampai harum. Masukkan rawitnya tumis sebentar.\", \"Sisihkan bumbu ke pinggir wajan, masukkan telor buat orak arik. Masukkan suwiran daging kambing. Osreng sebentar.\", \"Masukkan nasi aduk merata bumbu. Beri garam, lada, kaldu bubuk dan kecap. Aduk rata sampai bumbu tercampur baik.\", \"Untuk takaran kecapnya sesuaikan selera ya kalo d skip warnanya akan kuning cerah. Karena saya suka kecap jadi saya tambahkan dan paduan warnanya menggoda selera. Cantik. 😁\", \"Koreksi rasa lalu angkat. Bisa diberi tambahan kerupuk, acar atau dadar telor. Sesuaikan selera ya 👌\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(701, 2, 'Sate goreng kambing 💓', 'Resep Sate goreng kambing 💓 yang lezat dan mudah dibuat di rumah.', '[\"1/2 kg Daging kambing\", \"2 sdm Blueband\", \"250 ml Air\", \"Bumbu halus:\", \"8 siung bawang putih\", \"5 siung bawang merah\", \"6 lembar daun jeruk\", \"Asam jawa tanpa biji 3biji\", \"2 sdm Ketumbar bubuk\", \"3 butir Kemiri\", \"1 ons Gula merah -+\", \"Bumbu tumis:\", \"5 siung bawang merah iris tipis\", \"3 siung bawang putih iris tipis\", \"1 sdm gula pasir\", \"2 sdt lada bubuk\", \"3 sdm kecap manis\"]', '[\"Potong dadu daging.\", \"Haluskan bumbu halus. ungkep daging dengan bumbu dengan air 250ml sampai meresap. Angkat.\", \"Tumis bawang merah,bawang putih dengan blueband sampai harum. Masukan daging gula pasir,lada bubuk,kecap manis,bolak balik sampai agak kegosongan. Angkat sajikan dengan bumbu kacang,timun,irisan kol,& tomat(sesuai selera)👍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(702, 4, 'Tengkleng kambing Solo', 'Resep praktis Tengkleng kambing Solo yang bisa dicoba di rumah.', '[\"1/2 kg tulang kambing/iga kambing\", \"1/4 kg daging kambing\", \"Air yang banyak/ 1,5 lt utk kuahnya\", \"8 butir bawang merah besar, diparut halus\", \"1 sdm kunyit bubuk\", \"2 sdm merica bubuk\", \"1 sdt pala bubuk\", \"1 sereh geprek\", \"4 daun salam\", \"10 daun jeruk\", \"10 buah cabai rawit\", \"sesukanya Garam dan penyedap\"]', '[\"Cuci tulang dan dagingnya, lalu rebus sampai mendidih, buang airnya ganti dengan yang baru supaya tidak terlalu prengus.\", \"Masukkan daun jeruk, daun salam, cabai rawit dan sereh ke dalam rebusan daging.\", \"Tumis parutan bawang, kunyit, pala dan merica. Setelah harum masukkan ke dalam rebusan kambing.\", \"Tambahkan garam dan penyedap sesuai selera. Rebus kembali sampai empuk. Saya rebus selama 1,5 jam. Saat kuah menyusut saya tambah air. Koreksi rasa sebelum selesai memasaknya ya.\", \"Selesaaai. Rasanya gurih dan nagih. Hehehe\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(703, 3, 'Sop kikil (kaki kambing)', 'Resep Sop kikil (kaki kambing) yang lezat dan mudah dibuat di rumah.', '[\"3-4 kaki kambing (sapi juga gak papa)\", \"2 buah tomat\", \"2 bawang prei\", \"5 btr bawang merah\", \"5 btr bawang putih\", \"Asam jawa (dganti blimbing wuluh lebih seger)\", \"15 Cabe rawit\", \"Lengkuas\", \"1 batang tempe\", \"Garam\", \"Gula\", \"Royco\", \"Minyak goreng untuk menumis\"]', '[\"Pertama-tama bersihkan kaki kambing dr bulu dgn cara dibakar hingga kulit bagian luarnya berwarna hitam/gosong. Setelah itu, kerik bulunya yg sudah terbakar sampai bersih, dan buang sepatu kakinya (apa ya namanya, pokoknya kulit kakinya yang keras itu hehe). Bisa dilihat dgambar.\", \"Kedua, rebus atau presto kikil tersebut. Krna aku gak punya presto, jd aku sih drebus 1-2 jam, abis itu nanti aku rebus lagi malemnya, besok bru mulai masak, soalnya suka sama tekstur kikil yang hancur\\\" lumer gmnaa gt hehe.\", \"Nah kalau kikilnya sudah empuk, Potong tipis\\\" bumbu bawang merah dan bawang putih, geprek lengkuas, potong bawang prei, dan tomat, tak lupa juga potong tempe seperti dadu tp kurannya yg lebih besar agar nanti nggak mudah mrotol (?).👌\", \"Tumis semua bumbunya dgn minyak hingga harum\", \"Tambahkan air, lalu masukan asem, kikil, dan tempe, dan cabe rawit,tunggu hingga mendidih\", \"Kalau sudah mendidih tambah kan gula, garam,dan royco secukupnya. Koreksi rasa, angkat, taruh dimangkok, santap deh 👌\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(704, 4, 'Sate Kambing bumbu kecap', 'Resep Sate Kambing bumbu kecap yang lezat dan mudah dibuat di rumah.', '[\"potong Daging, hati & lemak kambing\", \"2 siung bawang merah iris\", \"3 buah cabai rawit iris\", \"1/2 buah tomat iris\", \"secukupnya Kecap\", \"Sedikit minyak goreng\", \"1 lembar daun pepaya\"]', '[\"Tusuk daging, hati dan lemak kambing\", \"Kemudian bungkus dengan daun pepaya dan biarkan beberapa saat\", \"Panaskan pemanggang, sambil menunggu campur sate dengan kecap\", \"Bakar sate sesekali di beri minyak\", \"Jika sudah matang campur sate, cabai, bawang merah, tomat, dan sate siap dinikmati.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(705, 4, 'Kikil kambing Pedas Manis', 'Sajian kambing spesial: Kikil kambing Pedas Manis yang menggugah selera.', '[\"4 buah kikil kambing (ukuran tanggung)\", \"10 siung bawah merah\", \"4 siung bawah putih\", \"35 biji cabe rawit (sesuai selera)\", \"5 biji cabai merah besar\", \"5 buah kemiri\", \"2 buah serai (geprek)\", \"1 buah jahe (geprek)\", \"1 buah lengkuas (geprek)\", \"3 buah tomat (saya pilih yg agak mentah)\", \"3 lembar daun salam\", \"4 lembar daun jeruk\", \"1 bungkus royco(saya pake rasa ayam)\", \"Gula dan garam secukupnyaa\", \"sesuai selera Kecap manis\"]', '[\"Haluskan semua bumbu kecuali yg cukup di geprek saja\", \"Sebumnya bersihkan kikil kambing dan rebus hingga terasa empuk\", \"Setalah bumbu siap tumis bumbu halus sambil tambahkan daun salam, daun jeruk, serai, jahe, dan lengkuas. Tambahkan sedikit gula.\", \"Setelah bumbu tercium bau harum dan sudah cukup matang tambahkan air secukuonya, tambahkan kecap manis.\", \"Baru setelah air mendidih masukkan kikil kambing, tutup menggunakan daun pisang. Tunggu hingga bumbu merasuk sempurna(saya tadi sekitar 20menit).\", \"Masukkan iris tomat sambil sedikit di aduk, tambahkan garam, gula, dan royco.\", \"Masakan siap di sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(706, 2, 'Marak daging kambing', 'Marak daging kambing - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1/2 kg daging kambing\", \"Air untuk merebus daging\", \"Kurang lebih 15 butir bawang merah(semakin bnyak makin enak ya)\", \"3 butir bawang putih\", \"2 cm Jahe\", \"Kunir2cm\", \"2 sendok teh Jintan\", \"secukupnya Merica\", \"secukupnya Gula dan garam\", \"2 buah Tomat\", \"sesuai selera Kapulaga\", \"secukupnya Cengkih\", \"secukupnya Kayu manis\", \"Bawang merah goreng untuk taburan\"]', '[\"Presto daging kambing hingga empuk\", \"Haluskan bawang putih bersama jintan jahe dan kunir\", \"Iris tipis bawang merah. Lalu iris tomat menjadi 2\", \"Tumis smua bumbu hingga harum jangan lupa masukan jg kayu manisnya\", \"Masukan bumbu kedalam rebusan air kambing tadi beri gula dan garam secukupnya\", \"Masukan kapulaga dan cengkih\", \"Tes rasa..tunggu hingga matang\", \"Jika sdh matang sajikan dengan bawang merah goreng\", \"Kalo aku ditambah sambal trasi mentah..enakk😍👍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(707, 4, 'Sup Kaki Kambing', 'Sajian kambing spesial: Sup Kaki Kambing yang menggugah selera.', '[\"5 buah kaki kambing yang telah empuk\", \"6 bh cengkeh\", \"3 bh cardamon (diganti kapulaga putih jg bs)\", \"1 jempol jahe, iris\", \"1 batang kayu manis (sy remukan)\", \"1.5 L air\", \"2 sdm garam\", \"1 sdm gula\", \"1/2 sdt merica bubuk\", \"1/2 sdt kaldu bubuk\", \"1/2 bh tomat besar\", \"1/2 bh pala, geprek\", \"1 bh jeruk lemon, peras airnya\", \"secukupnya daun bawang & seledri\", \"secukupnya cabe rawit utuh, (teknik malas buat sambel 😄)\", \"#Tumis hingga matang :\", \"1/2 bonggol garlic, ulek kasar\", \"1/4 bawang bombay, iris\"]', '[\"Siapkan bahan. ini jeruknya g ke foto, krn monggo disesuaikan dengan jeruk pilihan.\", \"Didiihkan air, masukkan. bahan tumisan dan semua bumbu serta kaki kambing, rebus 20 menitan. setelah itu tambahkan kentang & wortel hingga matang (optional). matikan api, masukkan seledri & daun bawang. ready to eat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(708, 3, 'Sop kambing kuah bening', 'Buat Sop kambing kuah bening yang nikmat dengan langkah-langkah mudah ini.', '[\"250 grm daging kambing\", \"1 buah kentang\", \"2 buah wortel\", \"Buncis\", \"kol\", \"Tomat\", \"2 buah bawang merah\", \"3 buah bawang putih\", \"Daun bawang sledri\", \"Merica bubuk\", \"1 bks penyedap rasa\"]', '[\"Haluskan bawang putih bawang merah dan merica bubuk lalu rebus di air mendidih\", \"Potong daging sesuai selera cuci setelah itu masukan di rebusan air bumbu tadi\", \"Potong sayuran lalu masukan wortel dan kentang terlebih dahulu agar empuk\", \"Setelah itu sayur yg lainnya menyusul\", \"Jangan lupa tambahkan penyedap rasa\", \"Setelah matang beri irisan tomat dan daun bawang juga sledri dan taburan bawang goreng\", \"Siap untuk dihidangkan dengan nasi putih\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(709, 3, 'Kambing Oven', 'Buat Kambing Oven yang nikmat dengan langkah-langkah mudah ini.', '[\"1 bawang bombai\", \"1 kg kambing\", \"Bumbu halus:\", \"10 siung bawang merah\", \"5 siung bawang putih\", \"1 ruas jahe\", \"1 sdm ketumbar\", \"1 sdm jinten\", \"1 sdm garam masala\", \"1 sdt merica\", \"1 sdm garam\", \"1 sdm gula\", \"Saus cocol:\", \"2 sdm kecap\", \"2 siung bawang merah\", \"2 biji cabe rawit\"]', '[\"Cuci bersih daging. Jika ingin dipotong boleh dengan potongan besar.\", \"Siapkan presto, masukan bawang bombai, tumis sampai layu, masukan bumbu halus yang sudah di blender. Tumis lagi hingga harum.\", \"Masukan daging kambing tumis sebentar hingga kecoklatan, kemudian tambahkan air. Presto hingga empuk.\", \"Keluarkan oven dari presto, di dinginkan sebentar, olesi kambing dengan minyak atau mentega. Oven 150 derajat selama 30 menit.\", \"Saus cocol: iris tipis bawang merah dan rawit, campurkan kecap, aduk hingga menyatu.\", \"Kambing oven lezat siap dihidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(710, 3, 'Lontong Kikil Kaki Kambing', 'Sajian kambing spesial: Lontong Kikil Kaki Kambing yang menggugah selera.', '[\"500 g Kaki kambing\", \"Daun bawang\", \"Jeruk nipis\", \"Bawang goreng\", \"7 lembar daun jeruk (sobek2)\", \"4 lembar daun salam (sobek2)\", \"3 batang serai (geprek)\", \"3 ruas lengkuas (geprek)\", \"1/2 ons kacang tanah goreng\", \"Bumbu halus :\", \"15 siung bawang merah\", \"10 siung bawang putih\", \"10 butir kemiri sangrai\", \"4 ruas kunyit (bakar)\", \"3 ruas jahe\", \"3 ruas temu kunci\", \"3 ruas kencur\", \"1 sendok ketumbar sangrai\", \"10 cabai merah besar\", \"1 sendok jintan\", \"secukupnya Gula, garam, penyedap rasa, merica\"]', '[\"Bersihkan kaki kambing, bakar sebentar untuk menghilangkan bulu-bulunya, cuci bersih kemudian potong-potong\", \"Rebus kaki kambing dalam 2 liter air, kemudian buang air rebusan pertama biar kuah kikil tidak bau, ganti dengan air yang baru, masak hingga empuk, tambahkan air jika kikil belum empuk\", \"Haluskan semua bumbu halus\", \"Tumis bumbu halus, daun jeruk, daun salam, serai dan laos hingga harum dan matang\", \"Masukkan bumbu halus ke dalam kuah kikil yang sedang direbus, tambahkan gula, garam dan penyedap rasa, merica secukupnya\", \"Haluskan kacang tanah goreng, kemudian masukkan ke dalam kuah kikil yg masih direbus juga\", \"Potong-potong daun bawang, masukkan sesaat sebelum api dimatikan\", \"Sajikan dengan Lontong, bawang goreng, irisan jeruk nipis, kecap dan sambal\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(711, 3, 'Daging kambing oseng mercon', 'Resep praktis Daging kambing oseng mercon yang bisa dicoba di rumah.', '[\"1 kg daging kambing, rebus lalu potong sesuai selera\", \"7 siung bawang merah, iris halus\", \"5 siung bawang putih, iris halus\", \"1 buah bombay, potong dadu\", \"2 buah tomat, potong kasar\", \"sesuai selera Cabe hijau, boleh di iris atau di utuhkan saja\", \"sesuai selera Cabe rawit, boleh diiris atau di utuhkan saja\", \"secukupnya Saos tiram,\", \"secukupnya Kecap asin,\", \"secukupnya Kecap manis,\", \"secukupnya Minyak wijen,\", \"secukupnya Gulgar\", \"Minyak goreng untuk menumis\", \"secukupnya Air kaldu rebusan daging\"]', '[\"Tumis bawang putih dan bawang merah sampai matang, masukan cabe, aduk rata.\", \"Masukan daging kambing, beri air kaldu secukupnya lalu didihkan\", \"Masukan bumbu botolan, gulgar, masak sampai daging empuk dan kaldu surut.\", \"Masukan bawang bombay dan tomat, masak sebentar sampai layu lalu angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(712, 2, 'Krengsengan kambing', 'Cara membuat Krengsengan kambing yang enak dan praktis untuk keluarga.', '[\"250 gr daging kambing(potong dadu tebal+/- 1cm)\", \"bumbu bacem\", \"1 sendok makan ketumbar, haluskan\", \"4 siung bawang merah cincang\", \"3 siung bawang putih cincang\", \"3 cm lengkuas, geprek\", \"air jeruk nipis\", \"garam, merica\", \"bumbu menumis\", \"5 siung bawang merah cincang\", \"4 siung bawang putih geprek\", \"20 cabe rawit (sesuai selera), haluskan\", \"1 buah tomat (bisa ditamvang sesuai selera)\", \"2 lb daun jeruk\", \"1 lb daun salam\", \"1 cm lengkuas, geprek\", \"2 cm jahe, geprek\", \"garam, gula, merica, kecap manis\", \"air\"]', '[\"Bersihkan daging, masukkan semua bumbu bacem, aduk rata. diamkan dalam kulkas selama kurang lebih 2jam agar meresap\", \"Setelah 2 jam. Panaskan minyak secukupnya, masukkan jahe, lengkuas tumis hingga harum. masukkan bawang merah, bawang putih, cabe. aduk rata\", \"Masukkan daun salam, kemudian daging, aduk-aduk, tambahkan air. Masukkan garam, merica, kecap manis, gula. Aduk hingga rata\", \"Diamkan beberapa saat hingga air meresap dan daging matang. tes rasa. jika sudah pas,masukkan daun jeruk yang sudah diremas, aduk2\", \"Masukkn tomat yang di potong dadu. aduk sebentar, jika suka, bs ditambahkan cabe utuh agar lebih menarik. sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(713, 3, 'Kambing goreng kecap', 'Buat Kambing goreng kecap yang nikmat dengan langkah-langkah mudah ini.', '[\"1/4 daging kambing\", \"3 siung bawang merah\", \"2 siung bawang putih\", \"Sedikit kecap, garam dan penyedap secukupnya\", \"Minyak goreng untuk menumis\"]', '[\"Alup daging sebentar tiriskan\", \"Tumis bawang merah bawang putih hingga harum masukan daging aduk sebentar ungkep hingga matang bumbui garam dan penyedap beri kecap secukupnya aduk\", \"Siap dihidangkan selagi hangat..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(714, 3, 'Gulai Daging Kambing', 'Resep praktis Gulai Daging Kambing yang bisa dicoba di rumah.', '[\"1 kg daging kambing beserta tulang\", \"6 lembar daun jeruk\", \"3 lembar daun salam\", \"2 batang serei\", \"2 ruas lengkuas geprek\", \"1 buah kapulaga\", \"2 biji pekak\", \"5 cm kayu manis\", \"2 biji cengkeh\", \"400 ml santan kental\", \"3 liter air\", \"8 biji cabe rawit\", \"Bumbu yang di haluskan\", \"8 butir bawang merah\", \"5 siung bawang putih\", \"1/2 cabe merah besar\", \"1 ruas kunyit\", \"1 ruas jahe\", \"3 butir kemiri\", \"1/4 sdt pala bubuk\", \"1/4 sdt lada bubuk\", \"1/4 sdt jintan bubuk\", \"1/4 sdt ketumbar bubuk\", \"Secukupnya gula garam dan penyedap\"]', '[\"Cuci bersih daging kambing kemudian rebus dengan air panas selama 5 menit,buang air rebusan dan cuci kembali sisihkan.\", \"Tumis semua bumbu halus hingga wangi.kemudian masuk kan daun jeruk,lengkuas,serei,salam,dan sisa bahan pelengkap lainya.\", \"Setelah bumbu masak dan berbau wanggi masukkan daging kambing.aduk hingga rata.\", \"Kemudian masuk kan 3 liter air.\", \"Pindahkan kan ke dalam panci lain.kemudian rebus hingga mendidih,kecilkan api rebus kembali selama kurang lebih 3 jam hingga daging lunak.\", \"Setelah daging lunak masukkan santan rebus selama 10 menit cicipi rasa dan siap untuk di hidangkan dengan taburan bawang goreng.\", \"Gulai bisa di hindangkan dengan bahan pelengkap lain.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(715, 4, 'Tengkleng Kambing Khas Solo Tanpa Santan', 'Cara membuat Tengkleng Kambing Khas Solo Tanpa Santan yang enak dan praktis untuk keluarga.', '[\"1 kg tulang ayam yang masih ada dagingnya menempel,blansir sebentar\", \"saya pakai 500 gram daging + tulang kambing,rebus sampai empuk\", \"15 buah cabe rawit cengek (saya skip)\", \"2 lembar daun salam\", \"2 lembar daun jeruk\", \"3 cm lengkuas,geprek\", \"3 cm jahe,geprek\", \"2 batang sereh,geprek\", \"1,5 liter air\", \"Bumbu yang di haluskan :\", \"8 siung bawang merah\", \"6 siung bawang putih\", \"1 sdt ketumbar\", \"1 sdt jinten\", \"1 ruas kunyit\", \"4 buah kemiri\", \"5 buah cabe merah keriting (saya skip)\", \"5 buah cabe rawit cengek (saya skip)\"]', '[\"Tumis bumbu halus sampai wangi.\", \"Masukkan bumbu dapur lainnya.\", \"Masukkan tulang ayam / tulang iga kambing,beri air.\", \"Masak sampai empuk dan matang.\", \"Tambahkan cabe rawit,gula dan garam.Tes rasa.Matikan api.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(716, 2, 'Sambel goreng hati kambing dan kentang', 'Resep Sambel goreng hati kambing dan kentang yang lezat dan mudah dibuat di rumah.', '[\"1 hati kambing, rebus hingga empuk\", \"3 buah kentang,\", \"4 buah cabe merah besar, buang bijinya\", \"6 buah cabe merah keriting\", \"2 siung bawang putih\", \"6 siung bawang merah\", \"2 lembar daun salam\", \"5 lembar daun jeruk\", \"1 batang serai\", \"1 ruas lengkuas\", \"secukupnya Garam\", \"secukupnya Gula pasir\", \"secukupnya Minyak goreng\"]', '[\"Potong2 hati kambing yg sudah direbus sesuai selera, goreng sebentar\", \"Potong2 kentang, goreng hingga matang\", \"Haluskan cabe dan bawang\", \"Panaskan minyak, tumis bumbu halus hingga harum, masukkan daun salam, daun jeruk, serai, dan lengkuas. Beri gula dan garam sesuai selera\", \"Setelah sambal matang, masukkan hati dan kentang yg sudah digoreng, aduk2 hingga sambal meresap\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(717, 4, 'Lontong sate kambing', 'Lontong sate kambing - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"250 gram daging kambing\", \"250 gram hati kambing\", \"2 sdm garam\", \"1 sdm lada putih bubuk\", \"Olesan:\", \"10 sdm kecap manis\", \"Air.secukupnya\", \"Pelengkap:\", \"Lontong\", \"Kacang tanah goreng,haluskan\", \"Kecap manis\", \"Cabai rawit\", \"Bawang merah\"]', '[\"Potong dadu kecil daging & hati kambing.Marinara dgn lada & garam,diamkan selama 45mnt di dlm kulkas.Keluarkan dari kulkas.\", \"Tusuk daging kambing lalu hati kambing (selang seling)hingga daging habis.Campurkan kecap & air,aduk rata.Bakar sate di atas arang hingga setengah matang.Olesi sate dgn kecap,bakar lg hingga matang.Lakukan hingga sate habis.Sajikam sate dgn pelengkap.\", \"NOTED :: ~Jumlah lada & garam sesuaikan selera ~Dapat dimakan dgn nasi putih ~Pelengkap dpt ditambah/dkurangi sesuai selera ~Sate dpt dibakar di atas kompor/dgril di happy call ~Apabila.tdk suka hati kambing dpt.dskip\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(718, 3, 'Gulai kambing aceh', 'Resep Gulai kambing aceh yang lezat dan mudah dibuat di rumah.', '[\"1 kg daging kambing\", \"Daun jeruk, sereh\", \"Cengkeh, kapulaga\", \"Kayu manis\", \"Daun karapelle (boleh skip)\", \"Santan\", \"Bumbu halus :\", \"1 ons cabe merah\", \"Bawang putih\", \"Bawang merah\", \"Kemiri goreng\", \"Cabe rawit bagi yg suka pedas\", \"Rempah sangrai haluskan dan ayak :\", \"Ketumbar\", \"bulat Lada\", \"Jintan\", \"Pala\", \"Bakar di atas bara :\", \"Kunyit\", \"Jahe\", \"Lengkuas\"]', '[\"Potong2 daging kambing sisih kan, boleh di ganti dg daging sapi atw daging ayam menurut selera masing2\", \"Sangrai rempah2 bumbu lalu haluskan dg cara di blender atw di tumbuk lalu di ayak sisihkan.\", \"Lalu bakar kunyit, jahe, lengkuas klo ga panas potong2 kecil blender dg bumbu2 lainnya sprt cabe merah dkk\", \"Lalu tumis bumbu cabe merah smp wangi, lalu masukkan rempah yg sdh di ayak aduk2\", \"Masukkan daging aduk2 n tutup sebentar smp kluar air dr daging n aduk2 kembali smp air asat baru tambahkan air sesuaikan dg kematangan daging n muali empuk masukkan santan lalu tambahkan kaldu bubuk tes rasa bila sdh mantap matikan api\", \"Bila suka masakan nya bisa di tambahkan dg daun karapelle atw daun koja\", \"Hidangkan gulai kambing aceh dg Roti jala n taburin bawang goreng di atasnya. Sajikan n cukup mengenyangkan dg 4 - 5 lembar roti jala\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(719, 4, 'Machboos al Laham (nasi kebuli kambing khas Kuwait)', 'Resep praktis Machboos al Laham (nasi kebuli kambing khas Kuwait) yang bisa dicoba di rumah.', '[\"Bahan nasi :\", \"3 cup beras long grain (bulir panjang) merk apa saja\", \"Bahan Daging kambing (bumbu utama) :\", \"350 gram daging kambing potong dadu\", \"Kalo mau pakai bagian yg ada tulangnya jg bisa malah lbh enak 😋\", \"8 siung bawang putih utuh\", \"1 sdt kapulaga arab utuh (cardamom butiran hijau)\", \"1 sdt cengkeh utuh\", \"1/2 sdt jinten bubuk\", \"1/2 sdt black lemon powder (bisa di skip jk tdk ada)\", \"2 butir pekak (bunga lawang/star anise)\", \"2 batang kayu manis (atau 1 batang yg besar)\", \"1/2 sdt kunyit bubuk\", \"2 lembar safron (bisa di skip)\", \"secukupnya garam\", \"1/2 blok kaldu daging maggy\", \"1 sdm gula pasir\", \"1/2 sdt merica\", \"2 sdm minyak samin\", \"800 ml air\", \"Bumbu tumisan :\", \"5 bwg merah uk. besar atau 10 siung bwg merah kecil, iris\", \"2 sdm raisins\", \"2 sdm olive oil / minyak goreng\", \"Bisa juga pakai beras basmati\"]', '[\"Cuci bersih beras rendam dengan air sampai menutup permukaan sisihkan. Beras nya jenis long grain yg bulir panjang merk apa saja. Kalo ngga ada beras biasa jg bisa ya.\", \"Tumis daging dengan minyak samin, dan semua bumbu utama di atas ⬆️. Tutup dan diamkan dgn api sedang sampai 30 menit.\", \"Tambahkan air 800 ml ke dalam tumisan daging td. Dan diamkan selama 45 menit atau sampai daging empuk.\", \"Buang air rendaman beras dan tuang beras ke dalam rebusan daging, aduk dan diamkan 10 menitan sampai beras setengah matang.\", \"Sementara di penggorengan lain tumis bawang merah iris dan raisins dengan sedikit minyak sampai keemasan dan layu lalu angkat.\", \"Pindahkan nasi machboos td ke dalam ke rice cooker dan tambahkan tumisan bawang merah dan raisins (kismis), aduk rata. Lalu masak nasi di rice cooker seperti biasa sampai matang. (setelah matang diamkan 20 menitan dengan tombol warm di rice cooker)\", \"Sajikan di piring saji. Selamat Menikmati. Ditunggu recook nya ya\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(720, 2, 'Tongseng daging kambing', 'Resep praktis Tongseng daging kambing yang bisa dicoba di rumah.', '[\"150 gr daging kambing\", \"500 cc air santan\", \"2 batang serai geprek tali simpul\", \"2 lembar daun salam\", \"3 potong lengkuas\", \"2 sdm Minyak goreng\", \"1 sdm kecap manis\", \"1 sdt Gula pasir\", \"1/4 sdt lada bubuk\", \"5 biji cabe rawit merah\", \"2 buah tomat 🍅 potong dadu agak besar\", \"100 gr kol potong kecil2\", \"1 batang daun bawang\", \"1 sdm bawang goreng\", \"bumbu halus :\", \"3 siung bawang merah\", \"3 siung bawang putih\", \"1 buah kemiri sangkrai\", \"1/2 sdt tumbar sangkrai\", \"1 ruas kunyit bakar\", \"1 ruas jahe geprek\", \"1 sdt garam\"]', '[\"Bahannya: cuci bersih sayurnya lalu potong2, kol,tomat,daun bawang, haluskan bumbu halus, kemiri dan tumbar di sangkrai dlu,kunyit di bakar, kemudian di haluskan semua bahan bumbu halus.\", \"Rebus daging kmbing hingga matang.rebusan airya bisa di pakai. Saya menggunakan daging kambing yg sdh di potong2 Tipis2 jadi ngak saya rebus, tinggal masukkn udah matang cepat.\", \"Siapkan wajan masukkn minyak goreng tumis bumbu halus, serai, daun salam,lengkuas, tumis hingga harum dan layu, masukkn santan,daging kambing, aduk2 masukkn lada,gula,cabe yg masih utuh, masak hingga mendidih masukkn kol,tomat. Kecap manis. Aduk rata tunggu mendidih lagi masukkan potongan daun bawang, incip2 rasa masukkn bawang goreng, dan taruh di mangkok saji.\", \"Tongseng daging kambing siap di hidangkan selamat mencoba. 😘\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(721, 2, 'Sate kambing goreng', 'Resep Sate kambing goreng ala rumahan yang dijamin menggugah selera.', '[\"250 gram daging kambing\", \"3 siung bawang merah\", \"3 siung bawang putih\", \"-+ 10cm  jahe\", \"1 ruas lengkuas\", \"2 butir kemiri\", \"secukupnya Kecap\", \"secukupnya Garam, merica, gula  (kira-kira 1/2sdt atau sesuai selera)\", \"Secukupnya air (saya pakai 1 gelas belimbing)\", \"Minyak untuk menumis\", \"Cabe merah, cabe rawit, dan tomat (optional)\"]', '[\"Potong dadu daging kambing\", \"Haluskan bawang merah, bawang putih, kemiri lalu memarkan jage dan lengkuasnya\", \"Tumis bumbu hingga harum lalu masukkan potongan daging. Aduk sebentar sambil diberi garan, merica, dan gula. Lalu masukkan air dan kecap, tutup wajan tunggu hingga air menyusut sambil sesekali diaduk\", \"Setelah air menyusut (bukan kering) masukkan cabe merah, cabe rawit dan tomatnya. Siap disajikan dengan taburan bawang, tambahkan kecap lagi bila suka 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(722, 2, 'Bestik kambing solo 🐐 🐐', 'Resep Bestik kambing solo 🐐 🐐 ala rumahan yang dijamin menggugah selera.', '[\"150 gr daging kambing\", \"3 siung bawang merah potong serong tipis\", \"2 siung bawang putih potong serong tipis\", \"2 buah tomat ukuran sedang\", \"1 sdm margarin\", \"1/4 sdt pala bubuk\", \"1/4 sdt lada bubuk\", \"1/2 sdt gula pasir\", \"1/4 sdt garam\", \"100 cc air bersih\", \"Bahan pelengkap:\", \"50 gr kol potong halus\", \"3 potong tomat\"]', '[\"Bahannya: potong daging kambing jgn terlalu tebal dan jng terlalu tipis, tomat potong dadu agak besar, bawång merah,putih potong2. Bisa di tambah kentang bila ada.\", \"Siapkan wajan beri 1 sdm margarin, tunggu leleh masukkn bawang merah dan putih tumis hingga layu dan harum baunya masukkn daging kambing aduk rata, sampai berubah warna masukkn tomat aduk rata, masukkn, pala bubuk,lada bubuk,gula,kecap manis, tambahkan air, masak sampai airnya berkurang alias nyemek2 baru tambah garam. Incip2 rasa, klo sdh pas angkat taruh piring saji, dan beri TOPING /lalapan kol dan tomat.\", \"Bestik kambing solo siap di hidang kan. Selamat mencoba 😘\", \"Selamat makan siang. Mantaf Teman2.. Tambah krupuk pasti tambah josss...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(723, 2, 'BakaRica Kambing', 'Nikmati kelezatan BakaRica Kambing dengan resep sederhana ini.', '[\"500 gram daging kambing\", \"3 sdm kecap manis\", \"secukupnya Air\", \"Minyak u/ menumis\", \"Haluskan:\", \"15 buah bawang merah\", \"7 siung bawang putih\", \"2 sdt asam jawa\", \"30 buah cabai merah\", \"2 sdm garam\", \"1 sdt kaldu bubuk\"]', '[\"Potong2 daging kambing,cuci bersih. Panaskan minyak goreng,tumis bumbu halus.\", \"Setelah 1/2 matang,masukan kecap manis,garam & kaldu bubuk tumis kembali hingga bumbu matang.\", \"Masukan daging kambing,aduk rata. Masak hingga daging berubah warna,tambahkan air.Ungkep hingga daging empuk,matang & bumbu meresap.Koreksi rasa & matikan api.\", \"4.Pisahkan daging & bumbu.Bakar daging diatas arang,masukan kembali daging yg sdh dbakar tadi kedalam bumbu,aduk rata & sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(724, 4, 'Kambing bakar #keto', 'Nikmati kelezatan Kambing bakar #keto dengan resep sederhana ini.', '[\"250 gr daging kambing (yang saya punya bagian paha). Iris tipis2\", \"Secukupnya bawang putih bubuk\", \"Secukupnya garam, merica, ketumbar\", \"1 bawang bombay, iris sesuka hati\", \"Beberapa daun pepaya untuk membungkus\", \"Secukupnya minyak dan butter\"]', '[\"Iris tipis2 daging kambing, campurkan garam, merica, ketumbar, bawang putih bubuk. Remas2 lalu bungkus dengan daun pepaya simpan dalam kulkas semalam (chiller).\", \"Keesokan harinya, panaskan minyak dan butter pakai api kecil lalu masukkan daging kambing (daun pepayanya jgn ikutan) masak sampai matang dan agak sedikit berwarna coklat. Sebelum diangkat masukkan bombay yg sudah dipotong\", \"Udah gitu aja, gampil ya... porsinya pas buat keto worrior, kenyang no worry\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(725, 2, 'Goreng kambing simple', 'Cara membuat Goreng kambing simple yang enak dan praktis untuk keluarga.', '[\"250 gr daging kambing\", \"secukupnya garam\", \"sesuai selera kecap manis\", \"minyak untuk menggoreng\"]', '[\"Cuci daging kambing, potong kecil2, goreng sampai matang.\", \"Tata dalam mangkok/ piring, taburi garam dan kecap manis..\", \"Sajikan...\", \"Ngga sempet foto, dangingnya udah keburu abis...😄😁\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(726, 4, 'Sate kambing dan sate usus ayam bumbu kecap cabe tomat', 'Nikmati kelezatan Sate kambing dan sate usus ayam bumbu kecap cabe tomat dengan resep sederhana ini.', '[\"1 ekor kambing(tp g smua dsate cih😀😀)ambil dagingnya\", \"1 kg Usus ayam\", \"Kecap\", \"1 kg Cabe\", \"1/2 kg Bawang merah\", \"1/2 kg Tomat\", \"Tusuk sate\", \"Areng buat bakar satenya😃\", \"Tusuk sate secukupnya\"]', '[\"Daging kambing dan usus di dtusuk\", \"Bumbu cabe bawang merah n tomat diiris2 jdiin satu ksih kecap\", \"Oya klo bakar sate ksih kecap sma bumbunya biar sedep\", \"Klo sdah dbkar smua satenya tnggal mkan dech😀😀😀\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(727, 2, 'Sate kambing dan sate usus ayam bumbu kecap', 'Resep Sate kambing dan sate usus ayam bumbu kecap ala rumahan yang dijamin menggugah selera.', '[\"1 ekor kambing yg muda(ambil dagingnya tp g smua disate yach😃😃)\", \"1 kg usus ayam\", \"Tusuk sate seckupnya\", \"Arang buat bakar\", \"1/2 kg Tomat\", \"1/2 kg Cabe\", \"1/2 kg Bawang merah\", \"Kecap seckupnya\"]', '[\"Daging kambing n usus ayam ditusuk2 trs dbkar tp bakarx pkai bumbu kecap yach biar sedep\", \"Bumbu cabe bwang merah tomat diiris2 kcil2 dan ksih kecap\", \"Klo sudah mateng siap untuk disajikan yach😃😃\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(728, 4, 'Nasi Kebuli Kambing (#PR_AsianFood)', 'Resep praktis Nasi Kebuli Kambing (#PR_AsianFood) yang bisa dicoba di rumah.', '[\"4 cup beras\", \"500 gr daging kambing\", \"1 buah bawang bombay, cincang kasar\", \"12 butir bawang merah, cincang kasar\", \"7 siung bawang putih, cincang kasar\", \"5 butir kapulaga\", \"1 batang kayu manis\", \"3 butir pekak\", \"3 butir cengkeh\", \"5 sdm susu cair/ santan\", \"2 sdm saus tomat\", \"1 sdm bubuk kari\", \"Secukupnya garam, gula, dan air\", \"Bumbu halus :\", \"6 buah cabe merah keriting\", \"1/2 sdt adas\", \"1/2 butir pala\", \"1 sdt merica\", \"1 sdt ketumbar\"]', '[\"Cuci bersih beras lalu rendam selama 5 menit, tiriskan.\", \"Cuci bersih daging kambing.\", \"Panaskan wajan, tumis bawang bombay, bawang putih dan bawang merah serta bumbu yang sudah dihaluskan. Tambahkan kayu manis, cengkeh, pekak, dan kapulaga.\", \"Masukkan daging kambing, masak sampai berubah warna, tambahkan 1 sdm bubuk kari.\", \"Beri air, susu cair/santan, saus tomat, garam dan gula secukupnya. Masak hingga daging empuk. Note: Jumlah air harus banyak karna nanti akan di gunakan untuk nasi.\", \"Angkat daging dari dalam kaldu. Tiriskan, dan goreng daging.\", \"Gunakan kaldu untuk memasak nasi. Koreksi rasa kaldu terlebih dahulu baru masukkan beras. Sesuaikan jumlah takaran air dengan takaran beras.\", \"Aron beras sampai kaldu terserap habis.\", \"Kukus beras sampai matang (saya sekitar 35menit).\", \"Hidangkan nasi kebuli bersama pelengkap seperti acar dan telur dadar, juga taburi bawang goreng.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(729, 4, 'Nasi Kabsah Kambing', 'Buat Nasi Kabsah Kambing yang nikmat dengan langkah-langkah mudah ini.', '[\"1/2 kg daging kambing (bag paha-potong kotak ukuran sedang)\", \"5 sdm Minyak goreng\", \"kayu manis, cardamon, cengkeh, bunga lawang, biji lada hitam\", \"2 sdt bumbu biryani instant\", \"2 sdt meat masala instant\", \"2 buah tomat uk.besar\", \"1 bawang bombay uk.besar\", \"5 siung bawang merah\", \"1 sdt bawang putih dihaluskan\", \"1 sdt jahe dihaluskan\", \"3 cup basmati rice\", \"secukupnya Air\", \"1,5 sdt garam\", \"2 sdm kacang mede, sangrai\"]', '[\"Panaskan minyak goreng pada teflon ukuran besar, masukkan daging kambing, kemudian masukkan bergantian: -rempah-rempah, -garam, -bumbu biryani dan bumbu meat masala instant,-bawang putih dan jahe. Aduk rata, hingga berubah warna\", \"Masukkan bawang bombay dan bawang merah hingga layu. Lalu masukkan tomat, tutup teflon hingga tomat hancur dan merata. Sambil aduk sesekali.\", \"Masukkan air. Masak, tutup teflon hingga daging kambing empuk (30-35 menit).\", \"Angkat dagingnya saja, pisahkan dari kuah. Panggang dagingnya dalam oven 180\' selama 5 menit.\", \"Masukkan basmati rice dalam kuah yang tersisa. Aroni hingga 90%matang dan air terserap seluruhnya. Lalu tutup teflon, kecilkan api. Diamkan selama 5 menit.\", \"Buka tutupnya, rasakan nasinya (sudah matang 100%, tetapi ridak terllau lembek). Nasi siap dihidangkan dengan daging kambing dan taburan kacang mede. Nikmat dimakan bersama yoghurt plain.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(730, 3, 'Nasi Kabsah kambing #pr_asianfood', 'Buat Nasi Kabsah kambing #pr_asianfood yang nikmat dengan langkah-langkah mudah ini.', '[\"1 kg daging kambing\", \"7-8 butir Kapulaga arab\", \"3 buah bawang bombai potong dadu kecil\", \"Bumbu halus 👇👇👇\", \"8 siung Bawang merah\", \"6 siung Bawang putih\", \"4 buah Tomat merah\", \"4 sdm Pasta tomat\", \"Cabe halus basah 1 sdm (non biji)\", \"(Bisa di ganti 3-4 Cabe merah besar buang bijinya haluskan)\", \"Sedikit minyak untuk menumis\", \"2 sdm Bumbu rempah spikuk\", \"secukupnya Penyedap rasa sapi\", \"Garam\", \"2500 ml air untuk merebus\", \"Beras basmati 1 liter (saya pake beras biasa habis soalnya 😂😂)\", \"Bahan pelengkap\", \"Bawang goreng\", \"Acar nanas\", \"Emping\", \"Sambal dll\"]', '[\"Didihkan air setelah mendidih masukan potongan daging kambing masukan juga kapulaga yg sudah di geprek dan potongan bawang bombai\", \"Tumis sampai wangi bumbu halusnya lalu masukan ke rebusan daging kambing\", \"Masukan bumbu rempah spekuk dan penyedap dan garam secukupnya tunggu sampai daging empuk kurang lebih 1 jam\", \"Setelah empuk keluarkan daging dari panci sisihkan\", \"Cuci beras lalu pakai air kaldu daging untuk mengaron, airnya kaldunya di kira2 yaa... tergantung jenis berasnya\", \"Lalu kukus selama 30 menit sampai nasi matang, kalo mau dimasak pake megicom juga bisa, cuci beras lalu masukan air kaldu kambing secukupnya lalu pencet cook tunggu sama matang\", \"Sembari menunggu nasi, goreng daging kambing nya asal garing aja\", \"Setelah nasi matang, siapkan piring saji tuang nasi kabsahnyanlalu taburin bawang goreng lalu letakan dagingnya, acar dan emping sebagai pelengkap\", \"Sajikan.... 😘😚😙\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(731, 4, 'Sop kambing favorit', 'Resep Sop kambing favorit ala rumahan yang dijamin menggugah selera.', '[\"1 kg kambing bagian paha (daging + tulang)\", \"1 + 2 lt air untuk merebus\", \"sedikit minyak untuk menumis\", \"secukupnya kaldu bubuk rasa ayam\", \"secukupnya garam\", \"bumbu :\", \"1 buah bawang putih iris\", \"1 buah bawang bombay ukuran sedang iris\", \"15 buah bawang merah iris\", \"1/5 buah pala iris\"]', '[\"Rebus 1 lt air hingga mendidih\", \"Masukkan daging kambing rebus sebentar lalu tiriskan (daging kambing tidak dicuci)\", \"Setelah direbus baru dicuci, langkah ini biar gak bau kambing yaa\", \"Didihkan kembali 2 lt air, dan masukkan kambing\", \"Sambil merebus daging kambing tumis bumbu2 dengan api kecil sampai berwarna kecoklatan\", \"Setelah bumbu matang, masukkan tumisan bumbu kedalam rebusan daging kambing\", \"Tambahkan kaldu bubuk dan garam sesuai selera\", \"Rebus dengan api kecil, kurang lebih 1,5 jam sampai empuk dan kaldu keluar\", \"Siap disajikan panas\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(732, 4, 'Spaghetti kambing keju', 'Spaghetti kambing keju - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"Bahan A. 1/2 Lafonte spaghetti\", \"1 buah bawang bombay di iris\", \"3 siung bawang putih di haluskan\", \"Daun bawang di hiris\", \"secukupnya Sambal botol\", \"secukupnya Saus tomat\", \"secukupnya Merica\", \"5 sdm Minyak goreng  😗😉\", \"secukupnya Keju parut\", \"1 biji Telur\", \"B. bahan campuran Kambing :\", \"secukupnya Kambing banyak nya sesuai selera bisa di taksir l\", \"bumbu di haluskan :\", \"bawang putih\", \"cabe merah\", \"jahe\", \"ketumbar\", \"tomat\", \"garam\", \"kecap\", \"gula\", \"Bawang merah\"]', '[\"Bahan A, rebus spaghetti sampai lembut tiris.. sisihkan. Panas kan minyak dan tumis semua bumbu hingga harum.. tambahkan Sambal dan saus tomat di campur.. lalu masuk kan spaghetti lalu masukan telur dan campur hingga matang,, tambahkan keju parut, angkat sisihkan lagi\", \"Bahan B. Tumis semua bumbu yg di haluskan hingga harum masukan kambing kecap gula, garam, dan tunggu sampai lembut, angkat campurkan di spaghetti tadi dan tambah parutan keju, bisa di hias dgn tomat dan seledri dari atas, selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(733, 2, 'Daging Kambing Lada Hitam', 'Resep Daging Kambing Lada Hitam yang lezat dan mudah dibuat di rumah.', '[\"200 gr Daging kambing iris tipis\", \"1/2 buah bawang bombay iris bulat\\\"\", \"2 siung bawang putih iris\", \"2 siung bawang putih geprak\", \"1 buah tomat merah iris\", \"1 buah tomah hijau iris\", \"1 buah lombok merah iris (hilangkan isi)\", \"1 buah lombok hijau iris (hilangkan isi)\", \"1/2 sdt garam\", \"1/2 sdt gula pasir\", \"Sedikit air\", \"1 sdm kecap manis\", \"3 buah cabe rawit iris tipis\\\"\", \"1 sachet bumbu instan Saos Lada Hitam merk Pronas\", \"Sedikit minyak goreng unt menumis\", \"1 lembar daun jeruk hilangkan batang tengah\"]', '[\"Tuang minyak dlm teflon Panaskan sebentar. Masukkan irisan, bawang bombay, bawang putih, bawang putih geprek, daun jeruk. Tumis hingga layu dan harum. Masukkan garam, gula, daging yg diiris tipis. Tambahkan air secukupnya. Masak sebentar.\", \"Lalu masukkan kecap, bumbu instan saos lada hitam, aduk merata. Tambahkan irisan lombok merah,hijau, tomat merah, hijau dan irisan cabe rawit. Masak hingga meletup dan matikan kompor.\", \"Daging kambing Lada Hitam Siap Dihidangkan 😉\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(734, 3, 'Gulai daging kambing', 'Resep Gulai daging kambing ala rumahan yang dijamin menggugah selera.', '[\"1/2 kg daging kambing muda\", \"1/2 kg tulang dan lemak kambing\", \"1 buah kelapa parut, bikin santan 3 gelas\", \"3 gelas air\", \"Gula merah\", \"Garam\", \"Penyedap rasa\", \"Segenggam daun kari / daun korokeling\", \"kayu manis\", \"Rempah2 haluskan :\", \"1 bh peka,\", \"1 bh  cabe manis,\", \"5 butir  cengkeh :\", \"Bumbu halus :\", \"5 siung bawang putih\", \"10 siung bawang merah\", \"Cabe sesuai selera, direbus\", \"1/2 sdt ketumbar\", \"1/2 sdt jinten\", \"Sedikit pala\", \"1 sdt merica\", \"Seruas jahe\", \"Seruas kunir\", \"Seruas kencur\", \"segenggam kemiri\", \"Sejempol Laos geprek\", \"1 sereh geprek\", \"5 lembar daun salam\", \"Secukupnya Minyak untuk menumis\"]', '[\"Rebus daging kambing,lemak dan tulangnya, +- 30 menit. Buang airnya,, iris2 daging, sisihkan\", \"Tumis bumbu halus dan rempah geprek, daun salam, daun kari, kayu manis dan rempah halus. Tumis sampai wangi.\", \"Masukkan rebusan daging. Tumis2 lg,lalu kasih air, garam, gula dan penyedap rasa. Biarkan mendidih bbrp lama,sekitar 30 menit\", \"Setelah 30 menit masukkan santan. Biarkan mendidih, aduk2 sambil dikoreksi rasanya\", \"Masak sekitar 30 menit lagi sampai buih dari santannya hilang. Ini berarti santan sudah menyatu dgn bumbu.\", \"Sajikan dgn sbal kecap. Ga ribet kok. Selamat mencoba 😊😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(735, 3, 'Rendang daging kambing mudah nan enakk', 'Sajian Rendang daging kambing mudah nan enakk yang praktis dan lezat untuk dinikmati bersama.', '[\"300 grm Daging kambing (di iris kecil)\", \"2 biji Daun jeruk(aku gak pake)\", \"Serai (aku gk pke)\", \"Bumbu\", \"1 biji Bawang merah besar (di iris tipis)\", \"1 bulat bawang putih (diblender)\", \"1 sdm jahe bubuk\", \"1/2 sdm mrica bubuk\", \"1 sdm ketumbar bubuk\", \"1/2 sdm kunir bubuk\", \"3 biji kemiri\", \"5 biji cengkeh (diuleg)\", \"3 biji kapulaga (diuleg)\", \"3 biji bunga lawang/pk Bintang(di uleg)\", \"Untuk kuah\", \"7 sdm minyak goreng\", \"1 sdm Garam\", \"3 sdm gula pasir/gula jawa\", \"2 biji maggi/ bisa pke ajinomoto\", \"Kecap manis memberi kesan coklat\", \"2 gelas besar Air putih\"]', '[\"Jika daging nya beku rendam dahulu pakai air se ember biar cepet lunak, dan segera potong2 kira2, 1 jam\", \"Stelah daging di potong kecil2 layaknya gule. Lalu Iris tipis bawang merah bombay.\", \"Masukan ke dalam blender bawang putih, mrica bubuk, jahe bubuk, kunir bubuk, ketumbar, kemiri, uleg kan cengkeh, pk Bintang, dan kapulaga, beri air sedikit lalu blender. 1 menit\", \"Setelah itu siapkan wajan beri minyak goreng, nyalakan api, masukkan bawang merah yang di iris tumis sampai coklat, setelah itu masukkan bumbu yang di blender tadi,tumis 3 menit api sedang\", \"Setelah itu Beri 1 gelas air,, kira2 700 ml, masukkan daging kambing sekalian dan tutup biar cepat mendidih.\", \"Setelah itu beri garam, gula pasir, kecap, maggi/ ajinomoto.\", \"Tunggu daging sampai empuk menggunakan api sedang,\", \"Lakukan 3-4 x menambahkan air pada wajan jika sudah agak asat, sampai daging empuk.. Icip2 rasa sesuai selera\", \"#Kunci kesuksesan rasa dan aroma ada pada,pemberian gula, penyedap, dan untuk aroma khas dgn pK bintang, kapulaga, cengkeh\", \"Selamat menikmati.. Makanan siap di santap dengan lahap 😉\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(736, 2, 'Tongseng kambing (santan version) - ala widi', 'Tongseng kambing (santan version) - ala widi dengan daging kambing empuk tanpa bau prengus.', '[\"500 gram daging kambing. Potong kecil2/ sesuai selera\", \"5 lbr daun kol, iris2\", \"1 bh wortel, potong korek api\", \"2 bt daun bawang, potong sktr 2 cm an\", \"1 bh tomat, iris2\", \"Santan kara uk kecil\", \"Bumbu (aq iris2, lg mls blend/ulek) :\", \"5 siung bawang merah\", \"4 siung bawang putih\", \"8 bh cabe oren\", \"3 bh cabe merah\", \"Tambahan :\", \"2 cm jahe memarkan\", \"2 bt serai memarkan\", \"1 ruas lengkuas memarkan/iris\", \"2 lbr daun salam\", \"1 sdt kunyit bubuk\", \"1 sdm ketumbar bubuk\", \"2 sdm kecap manis (sesuai selera masing2)\", \"Secukupnya gula, garam, kaldu bubuk\", \"secukupnya Air\"]', '[\"Tumis bawang merah dan bawang putih, lengkuas, serai, jahe, kunyit, ketumbar dan daun salam. Tunggu hingga wangi.\", \"Masukan daging kambing. Tambahkan air secukupnya. Aduk2. Tambahkan garam dan kaldu bubuk. (gulanya terakhiran aja, katanya biar daging cpt empuk jgn pk gula dl). Masak hingga daging empuk. Tambahkan air bila perlu.\", \"Masukkan santan, aduk2. Lanjut wortel. Tambahkan gula dan kecap manis. Tunggu wortel agak lunak.\", \"Masukkan kobis, tomat dan daun bawang. Aduk sebentar sj jangan kelamaan, biar sayurnya seger kress kress. Koreksi rasa. Jika sdh pas, segera matikan kompor.\", \"Angkat. Sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(737, 3, 'Kambing mercon ala ovi', 'Sajian kambing spesial: Kambing mercon ala ovi yang menggugah selera.', '[\"1 kg daging kambing\", \"3 ruas kunyit\", \"6 bawang merah\", \"5 bawang putih\", \"sereh geprek\", \"20 biji cabe rawit (optional)\", \"15 biji cabe merah\", \"daun salam, gula, garam, penyedap rasa, kecap\"]', '[\"Cuci sampai bersih daging kambing, beri perasan jeruk nipis. lalu rebus dengan sereh daun salam dan bawang putih, beri garam sedikit\", \"Setelah empuk, siapkan bahan halus (duo bawang, cabe, kunyit) lalu tumis sampai harum. beri air sedikit demi sedikit,\", \"Tunggu sampai mendidih setelah itu masukan daging, tambahkan gula, garam, dan penyedap rasa. tambahkan sedikit kecap manis\", \"Tunggu sampai bumbu meresap dan air sedikit menyusut,\", \"Jika sudah, angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(738, 2, 'Terik daging kambing simpel', 'Resep Terik daging kambing simpel ala rumahan yang dijamin menggugah selera.', '[\"1/2 kg daging kambing\", \"4 Bawang merah\", \"3 bawang putih\", \"secukupnya Merica bubuk\", \"3 lembar daun jeruk\", \"2 lembar daun salam\", \"2 batang serai\", \"Jahe\", \"Lengkuas\", \"Kunyit\", \"secukupnya Ketumbar\", \"2 butir kemiri\", \"secukupnya Gula merah\", \"secukupnya Garam\"]', '[\"Cuci bersih daging kambing, kemudian diiris sesuai selera.\", \"Haluskan bumbu : 2bawang,tumbar kemiri,kunyit, garam. Kemudian bumbu diuleni dengan daging kambing yang sudah diiris.\", \"Masukkan daging yang sudah diuleni bumbu kedalam wajan berisi air (cukup diatas daging)\", \"Masukkan jahe,lengkuas, serai(geprek ya) salam,daun jeruk,gula jawa. Tungggu airnya sampe habis baru di kasi kecap manis, setalah itu cek rasa.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(739, 3, 'Sate Kambing Rumahan', 'Nikmati kelezatan Sate Kambing Rumahan dengan resep sederhana ini.', '[\"1 kg daging kambing\", \"1/4 kg gajih\", \"2 ons kacang sambal\", \"2 sdm petis\", \"3 siung bawang putih\", \"5 buah cabe merah\", \"3 lembar daun jeruk purut\", \"Kecap manis\", \"Gula kelapa\"]', '[\"Krukup daging kambing dan gajih menggunakan daun pepaya selama 1 jam (agar daging lebih empuk) lalu potong dadu dan tusuk dg tusuk sate (1 tusuk isi 3, daging gajih daging). Sisihkan\", \"Goreng kacang terlebih dahulu. Lalu goreng dengan sedikit minyak untuk cabe merah, bawang putih selanjutnya blender bersama kacang dan 1 lembar daun jeruk\", \"Setelah halus msukkan ke wajan tmbahkan air 1/2 gelas lalu msukkan petis, sisa daun jeruk, gula kelapa, kecap manis sesuai selera, tmbhkan garam sesuai selera masak smpai mendidih dan sedikit kental\", \"Bakar daging kambing diatas bara arang... Stelah setengah matang lumuri dengan sedikit kecap lalu bakar sampai matang\", \"Setelah matang lumuri sate dengan bumbu kacang taburi irisan bawang merah...\", \"Selamat mencoba... Semoga berhasil... 😘\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(740, 4, 'Tongseng Kambing Tanpa Santan', 'Resep praktis Tongseng Kambing Tanpa Santan yang bisa dicoba di rumah.', '[\"300 gr daging kambing\", \"secukupnya air\", \"2 lembar daun salam\", \"1 lembar daun jeruk\", \"1 batang serai memarkan\", \"1/2 sdt gula jawa\", \"2 sdm gula pasir\", \"1/2 sdt penyedap (optional)\", \"1 sdt garam\", \"3 sdm kecap manis\", \"2 lembar kubis potong-potong\", \"1 buah tomat potong-potong\", \"1 batang daun bawang (optional)\", \"1/2 sdm bawang merah goreng (optional)\", \"bumbu halus:\", \"6 bawang merah\", \"3 bawang putih\", \"3 kemiri\", \"1 cm jahe\", \"1 cm kunyit\", \"1/4 sdt merica butiran\", \"1 pak bumbu tongseng berisi jintan,kayu manis,kapulaga(optional)\"]', '[\"Tumis bumbu halus hingga harum dan matang\", \"Masukkan daging, aduk hingga berubah warna\", \"Masukkan air dan semua bumbu lain\", \"Masukkan kubis&tomat,masak hingga mendidih dengan api kecil saja, koreksi rasa\", \"Taburi bawang goreng,sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(741, 3, 'Gulai kambing ala simbok', 'Nikmati kelezatan Gulai kambing ala simbok dengan resep sederhana ini.', '[\"1 kg daging kambing\", \"5 gelas santan (1 butir kelapa)\", \"Bawang goreng wat taburan\", \"Bumbu halus:\", \"8 siung bawang merah\", \"8 siung bawang putih\", \"6 butir kemiri\", \"1 ruas jari jahe\", \"1 ruas jari kunyit\", \"1 sdm ketumbar\", \"1 sdt merica/lada\", \"1 jumput jinten\", \"3 ruas jari kencur\", \"Bumbu tambahan:\", \"Kayu manis,daun salam, bunga Lawang,kapulaga, daun jeruk,sereh\", \"secukupnya Lengkuas,gula,garam,penyedap\"]', '[\"Potong2 daging kambing dan cuci bersih\", \"Goreng semua bumbu yg mau dihaluskan sampe berbau harum,angkat dan tiriskan\", \"Blender/ ulek bumbu sampe benar2 halus\", \"Taruh daging kambing yg sudah dicuci kedalam wajan lalu tuang bumbu yg sudah halus,campur sampe rata\", \"Tambahkan bumbu kering seperti daun salam dll,ungkep sampe daging lembut\", \"Tuang santan lalu aduk2 sampai mateng,biar santan tidak pecah,jangan lupa koreksi rasa\", \"Selamat menikmati\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(742, 4, 'Krengsengan Tulangan Kambing', 'Sajian kambing spesial: Krengsengan Tulangan Kambing yang menggugah selera.', '[\"1 Kg Daging Tulangan kambing\", \"2 lembar daun jeruk purut, sobek\", \"2 lembar daun salam\", \"3 ruas jari lengkuas, geprek\", \"1 buah tomat merah, potong\", \"1/2 butir bawang bombay, potong\", \"Secukupnya kecap\", \"1 sdm munjung gula merah serut\", \"1 sdt petis\", \"2 sdm air asam jawa\", \"Bumbu halus:\", \"5 butir bawang putih\", \"6 butir bawang merah\", \"1 ruas jari kunyit\", \"1 ruas jari jahe\", \"3 butir kemiri\", \"10 butir cabai rawit merah\", \"2 butir cabai merah besar\", \"sesuai selera Lada, garam\"]', '[\"Cuci bersih daging tulangan kambing kemudian rebus kurang lebih 1 jam, buang air rebusan, tiriskan\", \"Dalam wajan, panaskan secukupnya minyak, masukkan daun jeruk, salam, lengkuas geprek, lalu masukkan bumbu halus, tumis bumbu hingga wangi kemudian tambahkan gula merah, petis dan secukupnya lada garam\", \"Masukkan tulangan, aduk-aduk sebentar kemudian tambahkan kecap manis dan ratakan kembali\", \"Tuangi secukupnya air, tambahkan potongan tomat dan bawang bombay dan air asam jawa, masak hingga air asat dan bumbu mengaramel, koreksi rasa\", \"Sajikan krengsengan dengan taburan bawang goreng diatasnya\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(743, 4, 'Tongseng Kambing (tanpa santan)', 'Buat Tongseng Kambing (tanpa santan) yang nikmat dengan langkah-langkah mudah ini.', '[\"1 kg daging kambing, iris\", \"2 L air\", \"1/2 bongkah kobis, rajang kasar\", \"3 batang daun bawang, rajang kasar\", \"3 buah tomat, iris menjadi 4 bagian per buah\", \"Bumbu halus:\", \"6 siung bawang merah\", \"4 siung bawang putih\", \"3/4 sdm ketumbar\", \"1 sdm merica\", \"1/3 sdt jintan\", \"4 butir kemiri\", \"1 cm jahe\", \"3 buah cabe merah keriting\", \"1 sdt pala bubuk\", \"Pelengkap:\", \"3 batang sereh, geprek\", \"3 cm laos, geprek\", \"3 lembar daun jeruk, remas\", \"2 lembar daun salam, remas\", \"Secukupnya garam\", \"Secukupnya gula pasir\", \"5 sdm kecap manis\"]', '[\"Rebus daging dengan air sampai empuk\", \"Tumis bumbu halus sereh, salam, laos, daun jeruk sampai layu dan harum, masukkan daging kambing dan air kaldu.\", \"Tambahkan garam dan gula pasir secukupnya (jangan banyak-banyak dulu karena air akan disusutkan), tambahkan kecap manis.\", \"Masak sampai kuah menyusut dan terlihat pekat (saya tadi saya susutkan sampai tinggal separonya, atau sesuai selera saja). Tes rasa. Matikan api.\", \"Masukkan rajangan daun bawang, tomat dan kobis. Aduk.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(744, 4, 'Rawon Kambing', 'Resep Rawon Kambing yang lezat dan mudah dibuat di rumah.', '[\"1/4 kg daging kambing\", \"1/4 kg balungan yg masih nempel daging/lemaknya\", \"4 biji kluwek\", \"Bumbu halus:\", \"5 ciung bawang putih\", \"6 ciung bawang merah\", \"2 cm kunyit bakar/segar\", \"2 butir kemiri\", \"Garam\", \"Masako\", \"Gula putih\", \"Bahan tambahan:\", \"4 lembar daun jeruk\", \"1 lembar daun salam\", \"1 batang daun bawang\", \"Secukupnya seledri\", \"Secukupnya tauge kecil\", \"Bawang goreng\", \"Merica bubuk\"]', '[\"Potong daging kambing lalu bersihkan\", \"Rebus daging kambing beserta tulangnya.airnya agak banyak aja ya sekalian buat kaldu\", \"Rendam kluwek dalam air sampai.tunggu beberapa menit lalu geprek pakai ulekan dan ambil dagingnya.trs ulek sampai halus\", \"Rebus kluwek yg halus tadi pakai 2gelas air sampai mendidih.\", \"Tumis bumbu halus sampai wangi lalu masukkan kedalam rebusan daging kambingnya\", \"Setelah daging mendidih masukkan air kluwek sambil disaring ya\", \"Masukkan daun jeruk.salam.seledri,merica bubuk.daun bawang.gula.garam.tunggu sampai matang lalu test rasa\", \"Hidangkan dengan tauge dan sambal mentah/sambal korek\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(745, 2, 'Nasi Goreng Kambing (Maanfatin punjungan Aqiqah)', 'Resep Nasi Goreng Kambing (Maanfatin punjungan Aqiqah) ala rumahan yang dijamin menggugah selera.', '[\"2 piring nasi putih\", \"Daging kambing secukupnya (lebih tepatnya seadanya 😄)\", \"2 buah cabe rawit merah\", \"1 buah cabe merah besar\", \"4 siung bawang merah\", \"3 siun bawang putih\", \"1 buah kemiri\", \"Garam\", \"Kecap manis\", \"1/4 terasi sasa kemasan kecil\", \"Daun bawang\", \"2 sdm mentega / minyak goreng\"]', '[\"Haluskan semua bumbu\", \"Potong-potong daging kambing dengan ukuran kecil\", \"Panaskan minyak, tumis bumbu sampai harum\", \"Masukan nasi dan daging, aduk2 hingga bumbu merata\", \"Masukkan garam dan kecap dan koreksi rasa\", \"Masukan daun bawang\", \"Sajikan dengan tambahan mentimun dan kerupuk. Selamat mencobaaa 😊😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(746, 2, 'Sate Buntel Kambing', 'Cara membuat Sate Buntel Kambing yang enak dan praktis untuk keluarga.', '[\"500 gram daging giling kambing bisa di ganti sapi\", \"1 butir telur ayam\", \"1,5 sdm kecap manis\", \"40 gram  Gula merah sisir\", \"Bumbu halus 👇👇👇\", \"7 siung Bawang merah\", \"4 siung Bawang putih\", \"1 sdt Lada bubuk\", \"1/2 sdt jinten masak\", \"1 sdt  Garam / secukupnya\", \"secukupnya Penyedap\", \"2 sdm Air asam jawa\", \"secukupnya Tusukan sate\", \"Bahan bumbu kecap (untuk olesan bakaran)\", \"2-3 sdm Kecap\", \"2 sdm Minyak\", \"secukupnya Madu kalo ada sedikit aja\"]', '[\"Siapkan wadah masukan daging yg sudah di giling, beserta bumbu halus, masukan juga lada jintan bubuk, kecap garam gula merah air asam jawa campur rata lalu masukan juga telur aduk rata sambil di koreksi rasanya\", \"Lalu ambil adonan kira2 2 sdm tempelkan ke tusuk sate dengan tangan, agak di tekan2 agar menempel sempurna ; lakukan terus sampai adonan daging habis susun di panci posisi berdiri\", \"Setelah itu kukus beserta pancinya sampai matang kira2 30 menitan lalu tiriskan, bisa juga di pangganggang jejerin di loyang kue satenya\", \"Siapkan bara... lalu bakar sate buntelnya sesekali di olesin dengan kuas ke sate nya dengan kecap bumbu\", \"Setelah warna coklat kekuningan tanda nya sate buntel sudah matang, dan aromanya.... sedep menggugah serela makan\", \"Sajikan dengan pelengkap tomat timun atau acar atau sambal kecap\", \"Selamat memcoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(747, 2, 'Bubur oatmeal kambing/syurbah lahm', 'Nikmati kelezatan Bubur oatmeal kambing/syurbah lahm dengan resep sederhana ini.', '[\"5 siung bawang merah\", \"3 bawang putih\", \"1 bombay kecil\", \"1 buah tomat\", \"5 sdm havermut\", \"secukupnya Garam\", \"secukupnya Bumbu gule bubuk\", \"Daging kambing/daging sapi secukupnya. Yg sdh di rebus\", \"1 gelas Air\"]', '[\"Iris2 bawang putih,bawang merah,bombay. Lalu tumis hingga agak layu. Iris kecil2 tomat lalu masukkan kdlam tumisan. Tumis hingga masak. Tambahkan air secukupny kira2 1gelas air,Masukkan garam dan bumbu gule.\", \"Aduk2 sbntr,lalu masukkan havermut aduk hingga semu tercampur rata dan masak,masukkan daging. Koreksi rasa.\", \"Siap dihidangkan dg taburan bawang goreng.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(748, 2, 'Kambing masak kecap pedas', 'Sajian Kambing masak kecap pedas yang praktis dan lezat untuk dinikmati bersama.', '[\"400 gram Daging kambing\", \"2 buah Tomat, potong dadu\", \"15 buah Cabe rawit merah dan hijau, iris (sesuai selera)\", \"5 siung Bawang merah, iris\", \"Bumbu halus :\", \"3 siung Bawang putih\", \"2 siung Bawang merah\", \"1 sdt Ketumbar\", \"1 sdt Merica\", \"secukupnya Garam\", \"5 sdm Kecap manis\", \"1/2 potong Nanas (5 cm), diparut\"]', '[\"Potong2 daging kambing (sesuai selera), lalu lumuri dengan nanas yg sdh diparut. Diamkan sekitar 15 menit. Lalu cuci sekedarnya.\", \"Tumis bumbu halus sampai matang. Lalu masukkan daging kambing, aduk2. Ga perlu tambahan air ya coz dari dagingnya nanti keluar air jg.\", \"Tambahkan kecap manis, masak sampai daging empuk. Masaknya ga terlalu lama ya krn pake nanas jd dagingnya cepet empuk.\", \"Terakhir masukkan tomat, cabe dan irisan bawang merah. Aduk2, masak sebentar.\", \"Alhamdulillah enak, dagingnya empuk. Mantap. Rasanya mirip sate lho tp ga pake tusukan aja.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(749, 2, 'Krengsengan kambing sederhana', 'Resep Krengsengan kambing sederhana yang lezat dan mudah dibuat di rumah.', '[\"3 Lombok besar\", \"7 siung bawang putih\", \"4 siung bawang merah\", \"1 kemiri\", \"1 ruas Laos dan jahe\", \"1 Serai geprek\", \"3 Daun jeruk dan salam\", \"3 kapulaga\", \"5 cengkeh\", \"2 keningar ukuran kecil atau 1 UK sedang\", \"Kecap manis\", \"Kambing sebesar 2 kepalan tangan\", \"secukupnya Minyak gula garam\"]', '[\"Potong kambing seukuran dadu 2 ruas jari\", \"Haluskan bawang merah, putih, lombok, kemiri, jahe, laos\", \"Gongso bumbu halus, masukkan serai daun jeruk dan salam. Aduk terus\", \"Tumis hingga harum dan warna kehormatan. Masukkan air 1 gelas hingga mendidih. Masukkan daging kambing\", \"Aduk. Tambah gula garam, keningar, cengkeh dan kapulaga. Saat air mulai asat masukkan air mendidih lalu asatkan lagi hingga daging empuk\", \"Masukkan kecap, aduk rata.\", \"Siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(750, 2, 'Sate kambing empuk', 'Resep Sate kambing empuk ala rumahan yang dijamin menggugah selera.', '[\"1 kg daging kambing (potong dadu)\", \"1 ikat tusuk sate\", \"2 ikat selada\", \"5 siung bawang merah diiris tipis\", \"3 buah tomat merah besar potong\", \"1 buah jeruk nipis\", \"1 sc lada bubuk\", \"1 bungkus kecap lele\", \"5 buah cabe rawit(yang suka pedas boleh perbanyak lagi)\", \"1 bungkus arang\", \"2 lembar daun pepaya\", \"bumbu halus\", \"4 siung bawang putih\", \"1 sc merica\", \"2 butir miri\", \"1 sdt garam\", \"secukupnya air\", \"secukupnya minyak\"]', '[\"Siapkan cobek haluskan bawang putih, merica, miri, garam setelah halus beri kecap, air diaduk lalu masukan minyak diaduk sampai bumbu bercampur\", \"Potong dadu daging lalu di ungkep dengan daun pepaya diamkan 45 menit setelah diungkep tusuk satupersatu daging\", \"Siapkan tempat pembakar, bakar sate setengah matang lalu masukkan ke bumbu halus tadi beri kecap pada sate yang setengah matang\", \"Bakar kembali sate setelah berubah warna kecoklatan angkat\", \"Saatnya menyiapkan sate bersama pelengkapnya\", \"Setelah sate siap beri irisan bawang merah, tomat potong cabe rawit potong, selada dan sedikit perasan jeruk nipis jangan lupa lada bubuk dan kecapnya.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(751, 3, 'Sate Kambing 🐑🐑', 'Sajian Sate Kambing 🐑🐑 yang praktis dan lezat untuk dinikmati bersama.', '[\"500 gram Daging kambing  potong dadu bagian paha\", \"Nanas muda parut\", \"Bahan halus untu marinasi\", \"6 siung Bawang merah\", \"8 siung Bawang putih\", \"1 sdm Ketumbar bubuk\", \"1 sdt Lada bubuk\", \"secukupnya Garam\", \"3 sdm Minyak goreng\", \"3 sdm Kecap manis\", \"Bumbu sambal kecap 👇👇👇\", \"secukupnya Kecap manis\", \"7 siung Bawang merah  iris tipis\", \"4-6 biji Cabe rawit merah  selera\", \"2 biji Tomat merah\", \"secukupnya Kol iris2\", \"1 sdm perasan jeruk nipis / limau\"]', '[\"Potong daging kambing, rendam pake nanas parut diamkan 1 jam\", \"Haluskan bumbu marinasi, lalu masukan potongan daging kambingnya aduk sampai rata, lalu diamkan di kulkas kurang lebih 3 jam agar bumbu meresap\", \"Setelah meresap tusuk daging gambing pake tusukan sate, Lalu siapkan bara dan bakaran satenya, lalu bakar hingga matang sering di bolak balik posisinya agar matang merata\", \"Setelah matang angkat tata di piring saji, sajikan dengan kecap manis yg di iris bawang merah dan cabe rawit seta pelengkapnya tomat kol dan peresan jeruk nipis nya.\", \"Dagingnya empuk meresap banget.... top.. 👍👍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(752, 3, 'Daging kambing masak kecap', 'Sajian Daging kambing masak kecap yang praktis dan lezat untuk dinikmati bersama.', '[\"Sepiring daging kambing\", \"Air yang banyak untuk merebus (saya 3/4 panci)\", \"Bumbu:\", \"5 siung bawang merah\", \"4 siung bawang putih\", \"3 cm kunyit\", \"1 buah kemiri\", \"1/2 sdt merica bubuk\", \"secukupnya Garam\", \"secukupnya Kecap\", \"Secukupnya gula pasir\", \"Daun salam\", \"2-3 gelas air untuk memasak\"]', '[\"Potong-potong saya kecil-kecil aja daging kambing, cuci bersih, lalu rebus di air yang sudah mendidih sampai empuk.\", \"Haluskan bawang merah, bawang putih, kunyit dan kemiri. Tumis bumbu yang sudah di haluskan, sampai kuning kecoklatan dan harum. Lalu beri air, masukan daging kambingnya..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(753, 3, 'Gulai Kambing Makassar', 'Gulai Kambing Makassar - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1,5 kg daging kambing\", \"Santan dari 1 butir kelapa\", \"250 ml minyak goreng\", \"secukupnya Garam\", \"5 biji kembang lawang\", \"7 lembar daun salam\", \"Bumbu halus :\", \"1 ons bawang merah\", \"1 ons bawang putih\", \"3 ruas kunyit (@4 cm)\", \"1 ons lengkuas\", \"1 ons jahe\", \"4 batang sereh\", \"secukupnya Cabe kriting\", \"Bumbu sangrai :\", \"4 sdm jinten & 4 sdm ketumbar sangrai kemudian haluskan => sisihkan\", \"1 butir kelapa parut sangrai kemudian haluskan/ giling sampai mengeluarkan minyak=> sisihkan\"]', '[\"Potong-potong daging, rendam dengan air garam kurleb 30 mnt, cuci dan tiriskan\", \"Tumis bumbu halus sampai kering atau sampai kunyit benar-benar telah matang, agak lama memang waktu menumisnya\", \"Masukkan daging kedalam tumisan bumbu, tambahkan sedikit saja air karena daging akan mengeluarkan air dan masukan daun salam, masak hingga daging matang /kurleb 1 jam\", \"Masukkan santan, kelapa giling, jinten & ketumbar yg sdh dihaluskan, tambahkan kembang lawang dan garam.\", \"Masak hingga mendidih dan koreksi rasanya.\", \"Angkat dan sajikan dengan kutupat, cocok untuk santapan dihari raya bersama keluarga besar\", \"Tips Dari saya : Sebelum minyak digunakan untuk menumis bumbu, sebaiknya gunakan untuk menggoreng bawang merah. Agar aroma Dan Rasa making mantaappp....\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(754, 4, 'Kambing Masak kecap', 'Cara membuat Kambing Masak kecap yang enak dan praktis untuk keluarga.', '[\"1/2 kg daging kambing (aku banyakan gajih nya dr pada daging)\", \"3 siung bawang merah\", \"2 siung bawang putih\", \"3 cm kunyit\", \"2 cm jahe\", \"1/2 sdt ketumbar\", \"1 sdt lada\", \"2 lembar daun salam\", \"1 batang serai memarkan\", \"Secukupnya kecap\", \"Secukupnua gula garam\"]', '[\"Rebus daging sampe empuk, potong sesuai selera\", \"Haluskan bumbu keccuali serai dan daun salam\", \"Tumis bumbu hingga harum, masukan daging, daun salam, serai, kecap, gula garam dan sedikit air.\", \"Masak hingga matang.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(755, 4, 'Tongseng kambing ala bunda Jk 😄', 'Tongseng kambing ala bunda Jk 😄 dengan daging kambing empuk tanpa bau prengus.', '[\"250 gr daging kambing muda\", \"Kol secukupnya di rajang\", \"1 tomat di potong dadu\", \"3 Cabe rawit merah\", \"4 cabe rawit hijau\", \"1 sdt Jinten\", \"7 butir Cengkih\", \"50 cc Santan kental\", \"secukupnya Garam\", \"Gula secukupnya sbg penggugah rasa\", \"Bumbu halus :\", \"5 Bawang merah\", \"3 Bawang putih\", \"3 cm Kunyit\", \"1 cm Jahe\", \"1 sdm Ketumbar\", \"1 sdt Merica\", \"3 cm lengkuas\", \"2 batang sereh\", \"3 daun jeruk\", \"Pelengkap :\", \"secukupnya Emping\", \"secukupnya Acar\"]', '[\"Haluskan semua bumbu lalu tumis sampai wangi. Masukkan cengkih dan jinten\", \"Masukkan irisan daging kambing lalu tumis sampai berubah warna. Tambahkan air sedikit dan santan. Didihkan dan koreksi rasa\", \"Terakhir masukkan irisan cabai rawit, kol dan tomat. Masak sampai layu. Angkat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(756, 4, 'Asem asem kambing', 'Sajian kambing spesial: Asem asem kambing yang menggugah selera.', '[\"500 gram daging kambing/balungan/jeroan/ bagian kambing lainnya\", \"Bumbu halus\", \"3 siung bawang putih\", \"3 butir kemiri yg sudah di sangrai\", \"5 siung bawang merah\", \"iris Bumbu\", \"2 tangkai daun bawang\", \"5 buah tomat hijau\", \"1 cm kunyit\", \"2 cm laos\", \"1 tangkai serai\", \"3 lembar daun jeruk\", \"2 lembar daun salam\", \"sesuai selera Cabe rawit\", \"Gula\", \"Garam\"]', '[\"Tumis bumbu halus dengan kunyit laos serai daun jeruk dan daun salam sampai matang\", \"Didihkan air masukkan bumbu yg sudah ditumis masukkan daging kambing hingga empuk\", \"Masukkan irisan daun bawang irisan tomat hijau dan cabai rawit bumbui dengan gula dan garam test rasa siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(757, 3, 'Tumis Kambing Cabai Hijau', 'Cara membuat Tumis Kambing Cabai Hijau yang enak dan praktis untuk keluarga.', '[\"180 gram daging kambing\", \"80 gram cabai hijau besar (tropong)\", \"6 buah cabai rawit\", \"6 lembar daun jeruk\", \"2 lembar daun salam\", \"100 gram bawang bombay slice\", \"50 gram lengkuas\", \"2 buah staranish / peka\", \"50 gram lengkuas keprek\", \"1 sdm kecap manis\", \"1 sdt oyster\", \"secukupnya Garam\", \"secukupnya Gula\", \"secukupnya Lada bubuk\", \"Bumbu halus\", \"6 siung bawang merah\", \"2 siung bawang putih\", \"1 buah kemiri sangrai\", \"1 sdm ketumbar\"]', '[\"Potong dadu daging kambing, (kalo saya pake lamb chop agar ada tekstur tulang2 nya) lalu di rebus sebentar dan tiriskan\", \"Siapkan wajan dan panaskan minyak, lalu tumis bumbu yang sudah dihaluskan samapai ke coklatan dan aroma langunya hilang...\", \"Setelah itu masukan cabe hijau, cabai rawit dan bawang bombay...setelah layu masukan daun jeruk, salam dan lengkuas tumis sampai rata lalu tambahkan oyster...\", \"Setelah bahan tumisan masuk semua dan setengah layu lalu masukan daging kambingnya masak hingga tercampur rata dan tambahkan kecap, garam, gula dan lada aduk merata dan tambahkan kaldu masak hingga matang\", \"Setelah asat dan tercampur rata bumbu dan rasanya, matikan kompor, angkat dan sajikan.....\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(758, 2, 'Nasi goreng kambing', 'Resep praktis Nasi goreng kambing yang bisa dicoba di rumah.', '[\"100 gr daging kambing iris tipis\", \"2 piring nasi putih\", \"2 butir telur\", \"2 sosis sapi potong-potong\", \"2 lembar daun salam\", \"1 lembar daun jeruk\", \"1 Sachet saus tomat\", \"2 sachet saus sambal\", \"Kecap manis\", \"3 bawang putih\", \"3 bawang merah\", \"10 cabe rawit\", \"Sedikit ketumbar bubuk\", \"Merica bubuk\", \"Masako sapi\", \"Garam\", \"1 sdm blueband\"]', '[\"Uleg bawang putih bawang merah, cabe, dan sedikit garam.\", \"Panaskan blueband, masukkan telur, orak arik sampai setengah matang, lalu masukkan sosis. Sisihkan.\", \"Tumis daging kambing, beri sedikit merica dan masako, (masukkan irisan bawang bombay jika ada), aduk-aduk sebentar, masukkan bumbu halus, tumis sampai bumbu halus matang.\", \"Masukkan nasi dan orak arik telur, masak sampai tercampur.\", \"Tambahkan saus tomat, saus sambal, daun salam, dan daun jeruk, aduk aduk.\", \"Tambahkan bubuk ketumbar, merica bubuk, dan masako secukupnya. Aduk sampai tercampur.\", \"Masukkan kecap manis sesuai selera. Masak sebentar. Sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(759, 3, 'Sop Tulang Kambing', 'Sop Tulang Kambing - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"500 gr daging kambing beserta tulangnya\", \"2 buah kentang, iris bentuk kotak\", \"secukupnya Air\", \"1 buah wortel uk. Besar, iris\", \"2 batang daun seledri di cincang tipis\", \"1 batang daun bawang, iris\", \"1 batang kayu manis\", \"1 bh kapulaga\", \"3 bh cengkeh\", \"1 bh bunga lawang\", \"Daun salam\", \"Sereh di geprek\", \"Bahan halus :\", \"8 siung bawang merah\", \"3 siung bawang putih\", \"Kunyit secukupnya utk mempercantik warna kuah sop nya\", \"secukupnya Merica dan garam\", \"Bawang goreng utk taburan\"]', '[\"Pertama rebus terlebih dulu tulang beserta daging kambing nya sampe empuk. Di air rebusan nya tambah kan sedikit garam dan jahe agar tidak berbau amis. Setelah empuk, angkat dan sisihkan.\", \"Lalu tumis bumbu halus hingga harum, jika ingin pedas bisa di tambah cabe rawit jg d bumbu halus nya. Tp krna gak semua org d rumah sy suka pedas, akhirnya sy buat cabe nya secara terpisah.\", \"Setelah harum bumbu tumisan td masukkan cengkeh, kapulaga, bunga lawang, kayu manis, daun salam dan sereh.\", \"Lalu tambahkan air secukupnya. Masukkan daging kambing beserta tulang nya. Disusul kentang dan wortel td. Tambahkan garam dan koreksi rasa.\", \"Masak hingga mendidih. Ketika mendidih matikan api. Dan taburi daun seledri dan daun bawang selagi kuah sop nya masih panas. Sajikan di mangkok hidang dan taburi bawang goreng.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(760, 3, 'Serundeng Kambing', 'Sajian Serundeng Kambing yang praktis dan lezat untuk dinikmati bersama.', '[\"2 buah kelapa parut\", \"1/5 kg daging kambing potong-potong\", \"Bumbu halus:\", \"6 siung bawang putih\", \"2 buah cabe merah\", \"3 buah cabe rawit\", \"2 cm kunyit\", \"4 cm lengkuas\", \"secukupnya Jinten\", \"secukupnya Ketumbar\", \"3 helai daun jeruk nipis\", \"secukupnya Air\", \"secukupnya Gula\", \"secukupnya Garam\", \"Gula batok secukupnya\"]', '[\"Tumis bumbu halus bersama daun jeruk nipis hingga harus\", \"Masukkan daging kambing potong lalu tumis hingga bumbu terbaur\", \"Tambahkan air secukupnya biarkan hingga daging lunak\", \"Masukkan garam dan gula aduk rata\", \"Masukkan gula batok\", \"Aduk terus hingga air surut\", \"Masukkan kelapa parut\", \"Kondisikan api dalam posisi paling kecil, aduk terus hingga kelapa mengering\", \"Koreksi rasa\", \"Serundeng siap dinikmati\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(761, 2, 'Telor masak bumbu kambing', 'Telor masak bumbu kambing - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"6 butir telor,rebus,kupas dan goreng\", \"1 sereh geprek\", \"1 lembar daun salam\", \"1/2 sdm bumbu kambing siap pakai\", \"300 ml santan\", \"Bumbu haluskan :\", \"1 cm jahe\", \"1 cm lengkuas\", \"2 cm kunyit bakar\", \"2 butir kemiri\", \"1/2 sdt ketumbar bubuk\", \"1/4 sdt merica bubuk\", \"7 cabe merah keriting yang sudah dikukus\", \"6 siung bawang merah\", \"3 siung bawang putih\"]', '[\"Haluskan bumbu halus,lalu tumis hingga harum\", \"Masukan sereh,daun salam tumis kembali,masukan bumbu kambing\", \"Tumis bumbu hingga matang dan bau mentah hilang,gunakan api kecil agar tidak gosong\", \"Masukan telor yang sudah direbus dan digoreng\", \"Beri santan,beri garam,kaldu bubuk gula pasir,koreksi rasa,biarkan hingga mendidh sambil diaduk agar santan tidak pecah,gunakan api kecil.\", \"Jika sudah matang,angkat sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(762, 3, 'Tongseng kambing🐐🐐🐐', 'Sajian Tongseng kambing🐐🐐🐐 yang praktis dan lezat untuk dinikmati bersama.', '[\"1/4 kg daging kambing campur jeroan\", \"10 cabai rawit merah\", \"5 buah cabai merah besar\", \"4 siung bawang merah\", \"5 siung bawang putih\", \"Merica\", \"Kemiri\", \"secukupnya Kapulaga, kayu manis, jinten, cengkih\", \"1 ruas jahe&laos\", \"1 batang serai\", \"secukupnya Daun salam & daun jeruk\", \"Santan kara\", \"Gula pasir\", \"Royko sapi\"]', '[\"Rebus daging kambing smp lunak terlebih dulu, sambil nunggu daging empuk, blender bumbu2 diatas smp halus.\", \"Panaskan minyak, tumis bumbu smp matang, kmd masukkan serai yg sdh di geprek, daun salam dan daun jeruk, setelah layu masukkan daging kambingnya, beri sedikit air, masukkan royko dan gula pasir, koreksi rasa\", \"Tutup sebentar biar bumbu meresap di dagingnya, setelah dirasa meresap masukkan santan aduk2 biar g pecah santannya, koreksi rasa kembali, tunggu smp mendidih, angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(763, 2, 'Tongseng kambing maknyuss', 'Tongseng kambing maknyuss - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 kg daging kambing\", \"1 butir santan\", \"secukupnya Kol\", \"secukupnya Daun bawang\", \"secukupnya Cabe rawit\", \"Bumbu ulek:\", \"8 siung bawang merah\", \"7 siung bawang putih\", \"4 butir kemiri\", \"secukupnya Merica\", \"secukupnya Ketumbar\", \"secukupnya Kunyit\", \"secukupnya Jahe\", \"Daun salam n daun jeruk\", \"Serai\", \"secukupnya Kecap\"]', '[\"Tumis bumbu halus sampai wangi..masukan daun salam,daun jeruk n serai geprek\", \"Masukan daging.tumis sampai berubah warna.\", \"Masukan santan,kecap, merica,ketumbar bubuk,garam,gula,koreksi rasa\", \"Masukan kol iris,daun bawang n cabe.\", \"Aduk2.. hidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(764, 2, 'Gulai Kambing Pedas Manis', 'Resep Gulai Kambing Pedas Manis yang lezat dan mudah dibuat di rumah.', '[\"Daging kambing yg sudah dipotong² dan diberi air jeruk nipis\", \"Santan\", \"Bunga lawang(pekak)\", \"Cengkeh\", \"Daun salam\", \"Daun jeruk\", \"Sereh digeprek\", \"Kapulaga\", \"Asam kandis\", \"Gula\", \"Garam\", \"Air\", \"Kecap manis\", \"Bumbu halus:\", \"Bawang merah\", \"Bawang putih\", \"Cabe merah(pedasnya suka²)\", \"Kemiri\", \"Jahe\", \"Lengkuas\", \"Kunyit\"]', '[\"Tumis bumbu halus bersama kapulaga, cengkeh, bunga lawang, daun jeruk, daun salam, sereh, asam kandis smp harum\", \"Masukkan daging kambing. Tumis smp berubah warna, lalu masukkan air. Beri gula dan garam. Masak hingga dagingnya lembut.\", \"Kalo daging dirasa lembut, tambahkan kecap manis dan santan. Aduk terus smp meresap bumbunya.\", \"Siap disantap bersama nasi hangat..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(765, 4, 'Mirip tongseng kambing', 'Resep Mirip tongseng kambing yang lezat dan mudah dibuat di rumah.', '[\"1/2 kg daging kambing, iris melintang\", \"5 siung bawang merah, di iris\", \"5 siung bawang putih, diiris\", \"1/2 sdt merica bubuk atau sesuai selera\", \"1/4 sdt ketumbar bubuk\", \"Secukupnya garam\", \"Secukupnya gula pasir\", \"1 sdm kecap atau sesuai selera\", \"1 batang serai, geprek\", \"1 ruas lengkuas, iris jadi 2\", \"3 lembar daun salam\", \"2 lembar daun jeruk\", \"Secukupnya kol(kubis)\", \"1 buah tomat merah\", \"Air putih secukup nya\", \"Bawang merah goreng\"]', '[\"Rebus daging kambing setengah matang kemudian buang air nya, tiriskan\", \"Tumis bawang merah, bawang putih hingga harum. Tambahkan lengkuas, daun salam, Daun jeruk,serai, dan daging kambing\", \"Tambahkan air hingga merendam seluruh bagian daging\", \"Tambahkan garam secukupnya, garam secukupnya, lada,kecap manis, ketumbar bubuk\", \"Masak hingga daging lunak, tambah kan kol dan wortel setelah layu angkat\", \"Hidangkan dengan taburan bawang goreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(766, 4, 'Nasi Kebuli Kambing', 'Nasi Kebuli Kambing dengan daging kambing empuk tanpa bau prengus.', '[\"750 gram beras basmati (sy merk abu kass)\", \"1200 ltr air untuk rebus daging kambing (sampai empuk)\", \"1/2 kg daging kambing\", \"15 siung bawang merah\", \"4 siung bawang putih\", \"7 biji cengkeh\", \"3 potong kayu manis\", \"6 biji kapulaga\", \"2 sdm ketumbar\", \"2 sdt jinten\", \"2 sdt adas\", \"6 biji bunga lawang\", \"2 sdm garam/sesuai selera\", \"3 sdm minyak samin (boleh minyak goreng biasa)\", \"4 cm jahe\", \"2 ruas jari/secukupnya kunyit (bisa juga ga pake kunyit)\", \"75 ml santan (bisa pake kara)\", \"3 lembar daun salam\", \"3 lembar daun jeruk\", \"4 batang sereh\"]', '[\"Blender bumbu (bawang merah, bawang putih ketumbar, jinten, adas, kunyit, jahe) tumis bumbu yg sudah di blender tambah cengkeh, kayu manis, kapulaga, bunga lawang, sereh, salam, daun jeruk, sereh dan garam sampai harum.\", \"Masukan daging kambing kedalam tumisan bumbu.. Tambah air.. Masak hingga empuk.. Jika sudah empuk tambahkan santan kara\", \"Sambil menunggu daging matang.. Cuci beras basmati sampai bersih.. Siapkan rice cooker untuk memasak\", \"Angkat daging dr air.. Karena air rebusan yg sudah berbumbu digunakan untuk memasak nasi..tambahkan air satu ruas jari dr permukaan atas nasi.. Jika sudah taro daging kambing diatas genangan airnya\", \"Kenapa tadi ga langsung aja? Biar tau takaran airnya.. Agar tidak kelembekan atau kekerasan..\", \"Masak di rice cooker sampai matang..\", \"Untuk finishing : daging kambing diangkat.. Oven di microwave.. Jika tdk ada microwave, panggang sebentar diatas teflon.. Buat sambal sesuai selera..\", \"Sajikaaaannnn..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(767, 4, 'Kambing lado merah', 'Resep Kambing lado merah yang lezat dan mudah dibuat di rumah.', '[\"Kambing 1/2 kg (potong kecil/1 ruas jari)\", \"Bawang merah 8 siung (iris)\", \"10 siung Bawang merah\", \"3 siung Bawang putih\", \"20 Cabe keriting merah\", \"Tomat ukuran sedang 1buah\", \"1 ruas jari Jahe\", \"4 lbr daun jeruk iris\", \"Garam\", \"secukupnya Air\", \"Minyak samin / blueband secukupnya untuk menumis\"]', '[\"Tuang minyak samim/blue band, tumis bawang yg sudah diiris, jika harum masukan kambing.. Tambah air dan garam.. Masak hingga empuk dan air kering.\", \"Masak secara terpisah.. Tumis cabe, bawang merah,bawang putih tomat, jahe.. Jika matang.. Angkat dan ulek kasar..\", \"Jika bumbu sudah di ulek.. Tumis lagi.. Tambahkan daun jeruk dan masukan daging kambingnya jika sudah empuk..\", \"Angkat dan sajikannnn\", \"Note : jangan lupa dicicipi hehe\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(768, 3, 'TONGSENG Kambing', 'TONGSENG Kambing - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"500 gr daging kambing\", \"Bumbu halus\", \"6 bawang putih\", \"6 bawang merah\", \"1/2 sdt lada utuh\", \"4 buah kemiri\", \"3 cm kunyit\", \"2 cm jahe\", \"1 sdm ketumbar\", \"Garam\", \"🍒BUmbu pelengkap :\", \"1200 ml santan\", \"3 lembar daun jeruk\", \"3 cm lengkuas\", \"2 batang serai\", \"5 cabe merah dan iris\", \"5 cabe rawit utuH\", \"3 sdm kecap manis bango\", \"4 sdm gula merah sisir\", \"6 sdm minyak u menumis\", \"🍒pelengkap\", \"200 gr kol\", \"3 batang daun bawang\", \"1 buah tomat\", \"Bawang goreng\"]', '[\"Rebus daging dg daun salam.. Aku.. Nih kupresto biar cepet empuk..\", \"Tumis bumbu halus sampai harum.. Masukkan santan.. Aduk rata... Tambahkan bumbu pelengkap... Aduk sampai mendidih.. Masukkan daging... Air sisa rebusan daging kumasukkan juga pemirsah...\", \"Setelah bumbu meresap.. Tambahkan pelengkap.. Daun kol dsb...Cek rasa... Angkat sajikan\", \"😋😋😋\", \"😋😋😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(769, 4, 'Dendeng kambing sambal balado', 'Cara membuat Dendeng kambing sambal balado yang enak dan praktis untuk keluarga.', '[\"1/2 kg daging kambing\", \"Bumbu halus (diblender)\", \"1 sdt ketumbar\", \"3 siung bawang putih\", \"4 siung bawang merah\", \"Bahan balado\", \"1/4 cabe merah (boleh lebih sesuai selera)\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"1 lembar daun salam\", \"Secukupnya garam\"]', '[\"Slices /Potong daging kambing dengan ketebalan 1/2 cm\", \"Rebus daging dengan bumbu yang sudah dihaluskan (rebusnya sampe airnya mengering tp jangan terlalu kering nnti gosong hehe) kenapa pake bumbu halus karna biar ga amis\", \"Tiriskan daging yg sudah direbus, setelah dingin gepkrek mengunakan cobek\", \"Lalu goreng sebentar daging yg sudah di geprek tdi hingga matang lalu tiriskan, jangan terlalu garing nnti jadinya keras\", \"Tumis sebentar, cabe, bawang merah, bawang putih,daun salam hingga layu, biar mudah gilingnya ajah\", \"Lalu giling dengan cobek, cabe, bawang merah, bawang putih, garam secukupnya\", \"Campur sambal dengan daging, dendeng daging kambing siap dinikmati\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(770, 2, 'Sup Daging Kambing Sederhana', 'Sup Daging Kambing Sederhana dengan daging kambing empuk tanpa bau prengus.', '[\"Daging kambing\", \"1 buah wortel\", \"6 lembar kubis\", \"1 buah kentang\", \"3 siung bawang putih\", \"2 cm jahe\", \"Garam\", \"Merica\", \"Air\"]', '[\"Potong potong wortel, kentang, dan kubis sesuai selera\", \"Potong daging sesuai selera. Seperti biasa, kalo saya dagingnya saya pukul2 setelah dipotong, biar cepet matengnya 😅. Lalu rebus dagingnya.\", \"Bawang putih sama jahenya saya geprek aja, biar cepet 😅\", \"Masak air, masukkan bawang putih dan jahe. Setelah mendidih, masukkan kentang dan wortel. Masak hingga setengah matang.\", \"Kemudian masukkan daging dan kubis. Beri garam dan merica.\", \"Tes rasa\", \"Sup siap dihidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(771, 4, 'Kari kambing keluarga', 'Resep praktis Kari kambing keluarga yang bisa dicoba di rumah.', '[\"500 gram daging kambing\", \"50 gram cabe merah\", \"10 siung bawang merah\", \"3 siung bawang putih\", \"seruas jari kunyit\", \"seruas jari jahe\", \"seinduk jari lengkuas muda\", \"1 batang serai\", \"2 lembar daun jeruk\", \"10 lembar daun kari\", \"1 sdm ketumbar\", \"kelapa 1500 l dari 1 kelapa\", \"2 bh bunga lawang\", \"2 bh kapulagA\", \"2 ruas jari kayu manis\", \"secukupnya garam,gula\"]', '[\"Daging cuci bersih tiriskan\", \"Haluskan cabe,bawang,lengkuas,jahe kunyit srreh,ketumbar sdh pakai ketumbar halus\", \"Tumis. Bumbu hlus sampai harum,masukkan daging sampai air sat,masukkan santan,masak hingga daging mulai empuk,\", \"Tambahkan daun jeruk,daun kari,bunga lawang,kapulaga,kayu manis,garAm dan gula\", \"Masak hingga kuah kental dan daging empuk\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(772, 3, 'Bistik Kambing Sambal Matah', 'Bistik Kambing Sambal Matah - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"200 gram daging kambing\", \"1 cup buah nanas potong kecil kecil\", \"5 butir bawang putih\", \"Lada bubuk\", \"5 sdm kecap inggris\", \"1/2 butir jeruk lemon\", \"Lada hitam\", \"Minyak goreng\", \"3 sdm kecap manis\", \"3 buah jalapeno\", \"5 butir bawang merah\", \"1 buah tomat besar\", \"3 buah daun salam\", \"1 batang sereh\", \"secukupnya Garam dan gula\"]', '[\"Sebelum diolah, campurkan nanas dengan daging kambing, diamkan 15 menit.\", \"Setelah 15 menit, bersihkan nanas dari daging.\", \"Buat bumbu untuk mengungkep daging kambing. Masukan bawang putih yang sudah di press, kecap inggris, kecap manis, lada putih bubuk secukupnya, garam dan gula secukupnya dengan perbandingan 2:1, lada hitam, dan minyak goreng. Lalu aduk rata.\", \"Tusuk-tusuk daging kambing yang sudah di potong-potong dengan garpu agar bumbu meresap kedalam.\", \"Masukan daging kambing ke dalam bumbu yang sudah di buat tadi, sambil diolesi semua permukaanya. Setelah semua daging dan bumbu masuk ke dalam satu wadah, aduk-aduk lagi hingga merata.\", \"Ungkep daging dalam keadaan tertutup selama 45 menit hingga 1 jam.\", \"Selama menunggu, buat sambal matahnya. Iris dadu tomat serta Jalapeno, buang bagian bijinya.\", \"Iris bawang merah. Campurkan dengan irisan tomat dan Jalapeno.\", \"Oseng minyak goreng dengan salam dan sereh hingga mendidih.\", \"Tuangkan minya mendidih ke dalam campuran sambal (bawang, jalapeno dan tomat)\", \"Peraskan jeruk lemon. Sambal siap disajikan\", \"Setelah selesai diungkep, siapkan teflon dan sedikit minyak goreng, panaskan.\", \"Panggang daging dengan sedikit minyak diatas api sedang.\", \"Bolak balik hingga daging harum dan matang merata. Setelah matang, angkat, bistik siap disajikan.\", \"Sajikan bistik bersama sambal matah yang sudah tersedia. Happy trying~\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(773, 2, 'Gorengan Kambing Betawi', 'Gorengan Kambing Betawi dengan daging kambing empuk tanpa bau prengus.', '[\"1 kg daging kambing, potong sesuai selera\", \"5 siung bawang merah, haluskan\", \"5 siung bawang putih, haluskan\", \"2 sendok makan asam jawa, dagingnya saja\", \"1 sendok teh ketumbar, haluskan\", \"1 sendok teh garam atau sesuai selera\", \"1 sendok teh gula pasir\", \"5 cm lengkuas\", \"Air buat mengungkep\", \"Minyak buat menggoreng\"]', '[\"Campur semua bumbu kecuali lengkuas\", \"Aduk bumbu dengan daging kambing\", \"Biarkan 30 menit\", \"Rebus air masukkan lengkuas\", \"Setelah mendidih masukkan kambing, pastikan air sampai merendam kambing\", \"Masak sampai asat, bila daging belum empuk tambahkan air lagi.\", \"Setelah empuk angkat daging\", \"Panaskan minyak\", \"Goreng daging sampai kecoklatan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(774, 2, 'Nasi kambing oven', 'Resep praktis Nasi kambing oven yang bisa dicoba di rumah.', '[\"1/4 kg daging kambing\", \"secukupnya Garam\", \"Merica secukupnya(banyak merica makin enak rasanya ya)\", \"5 sendok makan Margarin kira2\"]', '[\"Potong daging kambing sesuai selera lalu cuci bersih\", \"Siapkan presto dan air secukupnya aj g ush terlalu banyak\", \"Masukan semua bahan2 tadi dan presto sampai airnya tinggal sedikit(alias nyemek)\", \"Siapkan alumunium foil untuk membungkus\", \"Ambil daging kambing letakan diatas alumunium foil dan beri sedikit kaldu sisa presto tadi lalu bungkus\", \"Masukan ke oven kurang lebih 1jam * semakin lama semakin empuk ya\", \"Jika sdh empuk keluarkan dr oven dan sajikan dengan nasi haangat dan kecap..bisa ditambah dengan irisan cabai dan bawang merah 😍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(775, 3, 'Rabeg kambing khas Banten ala mama nadyne😋', 'Resep praktis Rabeg kambing khas Banten ala mama nadyne😋 yang bisa dicoba di rumah.', '[\"1 kg daging kambing\", \"Bumbu halus:\", \"1 batang sereh,geprek\", \"1 sdt Kelabet\", \"1 ruas kayu manis\", \"1 SDM Ketumbar\", \"1 sdt jinten\", \"2 lembar daun salam\", \"2 ruas kunyit\", \"3 butir kapulaga\", \"5 butir cengkeh\", \"20 Kemiri\", \"25 siung bawang merah\", \"20 siung bawang putih\", \"1/4 kg cabe merah\", \"secukupnya Kecap,garam,gula\", \"secukupnya Lada bubuk dan kaldu bubuk\", \"secukupnya Air\"]', '[\"Rebus daging kambing buang air rebusan pertama\", \"Haluskan semua bumbu halus lalu tumis hingga harum\", \"Masukan air secuknya\", \"Masukan daging kambing beri garam kecap gula kaldu bubuk lada bubuk ungkep hingga daging empuk dan bumbu menyatu..jika sudah menyatu matikan api..\", \"Sajikan selagi hangat..selamat mencoba😉\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(776, 4, 'Tongseng Kambing/Lamb', 'Tongseng Kambing/Lamb - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"Bahan :\", \"1 kg Daging Lamb/kambing, dipotong sekitar 2 cm\", \"1/2 bh Kol, dirajang kasar\", \"3 bh Tomat merah dipotong dadu\", \"2 bh Daun bawang dipotong kira2 2 cm (aku skip krn lupa beli)\", \"10 bh Cabe rawit (bila suka pedas bisa ditambahkan sesuai selera\", \"2 bh Serai\", \"6 lbr Daun jeruk, disobek kasar\", \"5 lbr Daun salam\", \"4 cm Lengkuas, memarkan\", \"2 cm Jahe, kupas kulit dan memarkan\", \"4 bh Kapulaga\", \"2 bh Bunga Lawang\", \"2 bh Kayu Manis\", \"6 bh Cengkeh\", \"secukupnya Gula pasir/Gula jawa\", \"Secukupnya Garam\", \"secukupnya Merica\", \"200 ml Santan kental (aku pake Kara instan)\", \"2/3 sdm Kecap Manis\", \"2 lt Air untuk memasak\", \"Bahan yang dihaluskan :\", \"10 bh Bawang Merah\", \"8 bh Bawang Putih\", \"5 bh Cabai merah besar\", \"5 bh Kemiri, disangrai\", \"1/4 sdt Jinten bubuk\", \"1 sdm ketumbar (bisa pakai butiran atau bubuk)\", \"1 sdm Kunyit bubuk / 3 cm Kunyit\", \"1/2 bh Biji pala diparut / 1/2 sdt Pala bubuk\", \"Minyak untuk menumis\", \"Bahan pelengkap :\", \"Bawang goreng\", \"Jeruk Nipis\"]', '[\"Cuci bersih daging dengan air mengalir, jangan direndam dalam air, lalu tiriskan. Kemudian potong daging kira-kira sekitar 2 cm (jangan dicuci lagi).\", \"Blender semua bumbu yang dihaluskan dengan menggunakan minyak.\", \"Tumis bumbu dengan menggunakan minyak sampai harum, setelah itu masukkan serai, daun jeruk, daun salam, lengkuas, jahe, kapulaga, kayu manis, biji pala, cengkeh, bunga lawang. Aduk hingga semua rempah tampan layu dan berbau wangi.\", \"Masukkan potongan daging kambing, aduk dan masak hingga daging berubah warna menjadi tidak pucat lagi dan kuah dari daging menyusut. Tambahkan 1/2 porsi air dan masak hingga daging empuk. Jika air habis tapi daging belum empuk maka masukkan setengah porsi air sisanya. Masak hingga daging benar-benar empuk. Jangan memasukkan air sekaligus banyak karena akan membuat daging susah empuk, jadi tambahkan air sedikit2 dan bertahap agar daging tetap gurih.\", \"Setelah daging empuk, masukkin garam, gula, kecap dan santan. Masak hingga santan mengeluarkan minyak dan berbau harum, baru masukkan daun bawang.\", \"Masukkan cane rawit, kol dan tomat kira2 5-10 mnt hingga keliatan agak layu.\", \"Tongseng siap dihidangkan dengan tambahan perasan jeruk nipis dan bawang goreng😊.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(777, 2, 'Oseng oseng kambing', 'Oseng oseng kambing dengan daging kambing empuk tanpa bau prengus.', '[\"daging kambing 500 gram (mau campur atau dagingnya aja juga blh)\", \"secukupnya margarin untuk menumis\", \"6 sendok makan minyak sayur\", \"1 sachet royco sapi\", \"garem,gula seperkiraan saja\", \"3 sendok makan air asam jawa\", \"bahan yg di iris:\", \"30 buah cabe rawit\", \"5 buah cabe merah keriting\", \"1 buah tomat yg gede\", \"8 buah bawang merah\", \"4 buah bawang putih\", \"1 ruas jahe\", \"1 ruas lengkuas (digeprek)\", \"3 lembar salam\", \"2 buah sereh\", \"secukupnya air\"]', '[\"Siapkan daging kambing.. ingat ya daging kambing tidak boleh dicuci...\", \"Panaskan margarin dan minyak.. tumis bumbu yg di iris berserta salam sereh lengkuas.. sampai harum.. masukan daging kambing.. tumis dengan bumbu stlah sedikit berubah warna masukan air.. setelah itu masukan air asam jawa.. tambah kan royco,gula,garam secukupnya.. cek rasa..\", \"Tunggu sampai sedikit menyusut airnya.. dan kuah menjadi kental.. sajikan dengan nasi hangat..👍🏻\", \"Tips : kalo ga yakin dagingnya bisa empuk,bisa direbus dulu ya.. direbus dengan sedikit salam..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(778, 4, 'Oseng mercon kambing', 'Sajian kambing spesial: Oseng mercon kambing yang menggugah selera.', '[\"100 gr daging kambing\", \"10 buah cabe rawit\", \"2 buah bawang putih\", \"2 buah bawang merah\", \"Lada bubuk\", \"Kecap manis\", \"Minyak goreng\", \"Garam\"]', '[\"Rebus daging, iris tipis\", \"Panaskan minyak, tumis bawang merah putih, cabe sampai layu, masukan daging, air, kecap manis\", \"Masak sampai mendidih, koreksi rasa dan angkat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(779, 3, 'Daging kambing bumbu lapis', 'Buat Daging kambing bumbu lapis yang nikmat dengan langkah-langkah mudah ini.', '[\"1 kg daging kambing / sapi iris tipis\", \"10 siung bawang merah iris tipis\", \"secukupnya gula merah (iris)\", \"secukupnya penyedap / kaldu bubuk\", \"secukupnya kecap manis (-+ 50ml)\", \"#bumbu halus\", \"7 siung bawang putih\", \"7 butir kemiri\", \"1/5 sdt merica bubuk\", \"secukupnya garam\"]', '[\"Masukan daging pada wajan / panci,\", \"Tambahkan semua bumbu lalu remas\\\" sampai bumbu rata,\", \"Ukep dengan api kecil sampai empuk (pertama kali d ukep ga perlu di beri air udak keluar sendiri airnya,kalo sampai air habis tp belum empuk baru bisa d tambah air sedikit saja)\", \"Setelah empuk beri sedikit santan kental, biarkan sampai mendidih lalu angkat..Daging lapis siap santap 😍😍😍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(780, 4, 'Nasi Goreng Kambing', 'Sajian Nasi Goreng Kambing yang praktis dan lezat untuk dinikmati bersama.', '[\"3,5 cup beras (buat nasi kemudian dinginkan)\", \"400 gram daging kambing (potong)\", \"1 sdm bubuk kari\", \"1 batang kecil kayu manis\", \"Bumbu yg dihaluskan:\", \"8 butir bawang merah\", \"4 butir bawang putih\", \"1/2 sdt jintan\", \"1/2 sdt adas\", \"1 sdm ketumbar\", \"2 bh kapulaga\", \"5 bh cengkeh\", \"1 sdt merica\", \"secukupnya Kecap manis\", \"Garam dan gula\", \"secukupnya Air\", \"secukupnya Minyak samin\"]', '[\"Tumis bumbu halus dengan minyak samin. Tambahkan bubuk kari dan kayu manis. Setelah matang masukan daging kambing, tambahkan air secukupnya.\", \"Kemudian masukan garam dan gula. Masak daging sampe matang dan kuah mengental.\", \"Masukan nasi dan kecap. Aduk sampai rata dan nasi mengering. Koreksi rasa.\", \"Nasi goreng kambing siap disajikan ditambahkan emping goreng, taburan bawang goreng, telur mata sapi dan acar timun.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(781, 3, 'Tengkleng kambing tanpa santan', 'Buat Tengkleng kambing tanpa santan yang nikmat dengan langkah-langkah mudah ini.', '[\"Iga kambing\", \"2 lembar daun salam\", \"2 lembar daun jeruk\", \"1 buah serai keprek\", \"Lengkuas keprek\", \"5 butir cengkeh\", \"1 kayu manis\", \"2 buah kapulaga\", \"1 buah pekak\", \"sesuai selera Cabe rawit utuhan\", \"Bumbu halus :\", \"6 butir bawang merah\", \"3 butir bawang putih\", \"2 buah kemiri\", \"1 sdt ketumbar\", \"1/2 sdt merica\", \"1 cm jahe\", \"secukupnya Garam dan gula\", \"Penyedap secukupnya ato bisa diskip\"]', '[\"Rebus iga kambing kurleb 2 jam, bwt ilangin prengusnya pas rebus diksh 1/2 butir pala ma irisan jahe dan air rebusan pertama dibuang dan diganti dg air baru dan direbus lg sampe empuk dagingnya\", \"Haluskan bumbu halus, lalu tumis diminyak panas tambahkan daun salam, daun jeruk, serai dan lengkuas keprek, cengkeh, kayu manis, kapulaga, pekak, oseng2 sampai harum baunya baru dicampur ke rebusan iga kambing td, tambahkan garam, gula dan penyedap dan cabe rawit utuhan, tes rasa, jika sudah, rebus sampe meresap bumbunya ke iga kambing, jika dirasa cukup, matikan, sajikan dg nasi hangat dan taburan bawang goreng\", \"Selamat mencoba 😊😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(782, 2, 'Gulai kambing pedas', 'Resep praktis Gulai kambing pedas yang bisa dicoba di rumah.', '[\"500 gr daging kambing, dipotong-potong\", \"Bumbu halus:\", \"7 siung bawang merah\", \"4 siung bawang putih\", \"2 cm jahe, kunyit\", \"3 btr kemiri sangrai\", \"5 cabe merah\", \"5 rawit domba\", \"1 sdt ketumbar, 1/4 sdt jintan, 1sdt merica, garam, royco\", \"1 sdm gulput\", \"Bumbu kasar:\", \"2 btr kapulaga, cengkeh, 1cm kayu manis, laja\", \"2 lmbr daun salam, daun jeruk, serai\", \"Minyak utk menumis\", \"250 ml santan kental\"]', '[\"Tumis bumbu halus sampai harum, masukkan bumbu kasar, lalu masukkan daging, air secukupnya masak hingga empuk.\", \"Tuang santan aduk hingga mengental\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(783, 2, 'Kambing masak kecap bumbu rempah', 'Cara membuat Kambing masak kecap bumbu rempah yang enak dan praktis untuk keluarga.', '[\"1 kg daging kambing\", \"1 ruas jari jahe\", \"1 ruas jari lengkuas\", \"4 kemiri\", \"2 sdm ketumbar, sangrai\", \"1 ruas jari kunyit\", \"Merica\", \"5 siung bawang merah\", \"2 siung bawang putih\", \"1/2 sdt\", \"150 ml santan kara\", \"Bumbu halus:\", \"2 kapulaga\", \"3 cengkeh\", \"Gula merah\", \"3 buah tomat, potong\", \"4 siung bawang merah, iris tipis\"]', '[\"Cuci bersih daging kambing, masukkan ke dalam panci berisi air, rebus daging kambing hingga air mendidih (gunakan api kecil agar kotoran dalam daging terangkat).\", \"Angkat rebusan daging, buang air dan cuci bersih daging kambing di air mengalir. Cuci bersih panci bekas rebusan tadi, isi air dan rebus.\", \"Masukkan kembali daging kambing ke dalam air rebusan tadi, tutup panci dan rebus.\", \"Tumis bumbu halus dan bumbu lain sampai matang, tambahkan kecap.\", \"Masukkan tumisan bumbu ke dalam panci berisi rebusan daging, tambahkan garam (jangan terlalu banyak menambahkan garam). Rebus daging kambing berbumbu tadi hingga air benar benar menyusut dan warna kuah menjadi berwarna coklat. Tambahkan santan. Gunakan api kecil saat merebus agar bumbu lebih meresap dan daging empuk. Sambil sesekali di aduk.\", \"Menjelang air menyusut, tambahkan tomat, rebus tomat bersama daging. Koreksi rasa. (tambahkan garam dan kecap bila perlu)\", \"Banyak nya kuah tergantung yang di inginkan ya, lebih enak nya kuah di sisakan hanya sedikit saja agar tidak terlalu kering. Angkat dan sajikan bersama nasi hangat.😍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(784, 3, 'Sate Kambing Solo', 'Sajian Sate Kambing Solo yang praktis dan lezat untuk dinikmati bersama.', '[\"sekitar 100-200 gram daging kambing\", \"1 sdm nanas parut\", \"tusuk sate, secukupnya\", \"Bumbu rendaman (haluskan) :\", \"2 siung bawang putih\", \"4 siung bawang merah\", \"1/2 sdm ketumbar butiran\", \"1 1/2 butir kemiri\", \"1/2 sdm gula merah\", \"sejimpit garam\", \"Sambal kecap :\", \"1 bawang merah, iris tipis\", \"4 cabe rawit, iris tipis\", \"secukupnya kecap manis\", \"secukupnya Lada bubuk\", \"Pelengkap :\", \"iris Tomat,\", \"Kol, rajang halus\"]', '[\"Balur daging kambing dengan parutan nanas, biarkan 10 menit. cuci dan potong-potong (aku pakai gunting biar cepat motong lemaknya)\", \"Haluskan bumbu, rendam daging kambing di dalam bumbu tadi. Lalu masukkan ke dalam kulkas selama 30 menit agar bumbu meresap\", \"Keluarkan dari kulkas, tusuk daging dengan tusuk sate (daging-lemak-daging). Rendam kecap manis sebentar. Bakar 1/2 matang. Rendam kecap manis lagi. Lalu bakar sampai matang\", \"Sajikan dengan sambal kecap, irisan tomat dan kol\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(785, 4, 'Kari kambing salim aqiqah', 'Cara membuat Kari kambing salim aqiqah yang enak dan praktis untuk keluarga.', '[\"1 Ekor Kambing/Domba Ukuran kira-kira 10 kg\", \"12 liter air\", \"4 Buah Kelapa (Santan)\", \"1 Kg Bawang Merah\", \"1/2 Kg Bawang Putih\", \"1 ons Jahe\", \"3 buah kelapa di gonseng\", \"1/2 Kg Cabe Kering (direndam dengan air panas)\", \"1/4 Kg Cabe Merah\", \"3 ons Ketumbar di sangrai\", \"1 ons Jinten di sangrai\", \"1/2 ons adas disangrai\", \"1 ons kemiri disangrai\", \"1 Ons Kunyit disangrai\", \"3 Buah pala disangrai\", \"10 Buah Kapulaga disangrai\", \"15 Butir Cengkeh disangrai\", \"6 Buah Pekak disangrai\", \"4 Buah Ketapang disangrai\", \"1 Sdm Kas kas disangrai\", \"Garam\", \"Asam Sunti (Buah Belimbing Yang Dikeringkan)/Asam Jawa\", \"Bahan Untuk Menumis:\", \"1/4 Kg Bawang Merah (iris)\", \"1 ons Bawang Putih (iris)\", \"3 Buah Bawang Bombay (iris)\", \"15 Butir Cengkeh\", \"12 Buah Kapulaga\", \"6 Buah Pekak\", \"15 Batang Daun kari\", \"5 Batang Daun Pandan\", \"6 batang Sere\", \"10 Cm Kayu Manis\"]', '[\"Haluskan Bawang merah, Bawang Putih, Jahe, Kemiri, Kunyit, Cabe Merah, cabe kering dan asam sunti.\", \"Haluskan Bumbu yang disangrai.\", \"Bumbu (1) dan (2) tambah kelapa gonseng dicampurkan kedalam kambing/domba yang telah dibersihkan. diamkan selama 20-30 menit.\", \"Tumis bawang merah dan Bawang putih sampai harum kemudian masukkan bawang bombay dan bumbu pelengkap lainnya, tumis sampai harum.\", \"Masukkan daging kambing yang telah dibumbui, diamkan sejenak sampai berubah warna dan air dari daging kambingnya keluar.\", \"Sesekali diaduk setelah daging mulai sedikit empuk tambahkan santan encer dan air selanjutnya tambahkan santan kental. Tambahkan garam dan gula.\", \"Masak sampai empuk. Kari kambing siap untuk disantap untuk 100 orang.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(786, 3, 'Daging Kambing Nanas Asam Manis', 'Resep praktis Daging Kambing Nanas Asam Manis yang bisa dicoba di rumah.', '[\"300 grm Daging kambing/Sapi\", \"2 bh Nanas Madu uk.Kecil (potong2 Kecil)\", \"6 Siung Bawang Putih (dicacah)\", \"1/2 bh Bawang Bombay (iris2)\", \"6 bh Cabe Keriting (iris2)\", \"2 Sendok Makan Saus Tomat\", \"Secukupnya Garam\", \"Secukupnya Merica bubuk\", \"Secukupnya Minyak Goreng\"]', '[\"Masukan daging kedalam panci & rebus hingga mendidih. Kebetulan daging yang saya punya masih beku. Setelah mendidih angkat lalu iris2 kecil2. (Hati2 panas ya moms)\", \"Siapkan wajan masukan minyak goreng. Tumis bawang putih sampai harum, masukan daging kambing aduk2, kemudian masukan nanas, cabe, bawang bombay, dan saos tomat sambil terus diaduk sampai matang merata.\", \"Masukan garam & merica, lalu koreksi rasa. Angkat dan siap di hidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(787, 3, 'Kambing ungkep', 'Resep Kambing ungkep ala rumahan yang dijamin menggugah selera.', '[\"500 gr daging kambing\", \"1 bh bawang bombay\", \"3 bh bawang putih\", \"Garam\", \"Lada halus\", \"Kecap\", \"Mentega untuk menumis\"]', '[\"Tumis bawang bombay dan bawang putih dengan mentega. Tambahkan garam dan lada\", \"Tambahkan air sampai mendidih, lalu masukkan daging\", \"Tunggu mendidih lg, tutup panci dan masak dengan api kecil sampai daging empuk, sekitar 1-1,5 jam.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(788, 3, 'Kambing Goreng Bumbu Sate #NoMSG', 'Kambing Goreng Bumbu Sate #NoMSG dengan daging kambing empuk tanpa bau prengus.', '[\"Bahan yang dipotong-potong/diiris :\", \"500 gr daging kambing\", \"10 siung bawang putih\", \"12 siung bawang merah\", \"7 buah cabe rawit\", \"2 buah tomat besar\", \"Kecap manis (sy pakai bango)\", \"4 lembar daun jeruk (iris tipis)\", \"4 lembar daun salam\", \"sesuai selera Garam\", \"sesuai selera Merica\", \"Bumbu yang dihaluskan :\", \"10 siung bawang putih\", \"1 sdt ketumbar\", \"6 buah kemiri\", \"Bumbu daging :\", \"1/2 bulatan kecil gula merah\", \"5 sdm air asam jawa\", \"Kecap manis (sy pakai bango)\", \"3 sdm margarine\"]', '[\"Blender/ haluskan bawang putih + ketumbar + kemiri + minyak.\", \"Siapkan tempat. Masukkan kecap + gula merah + air asam jawa + margarine + bumbu halus + garam + lada. Aduk rata\", \"Masukkan daging kambing lalu aduk-aduk hingga semua bagian daging kambing tercampur rata. Lalu diamkan 10 menit.\", \"Tumis bawang merah + bawang putih + cabe rawit + daun jeruk + daun salam. Sampai harum..\", \"Lalu masukkan daging kambing kemudian aduk rata. Biarkan hingga air yang keluar dari daging kambing sat atau berkurang. Lebih kurang 15-20 menit sampai daging benar-benar matang.\", \"Setelah matang. Tambahkan kecap + tomat lalu aduk-aduk sebentar. Diamkan sebentar. Taraaa... Siap dihidangkan..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(789, 2, 'Asem-asem kambing anti gagal', 'Buat Asem-asem kambing anti gagal yang nikmat dengan langkah-langkah mudah ini.', '[\"1/2 kg daging kambing (sapi juga boleh)\", \"8 bawang merah\", \"9 bawang putih\", \"10 buah buncis\", \"1 buah wortel ukuran sedang\", \"3 buah tomat ukuran sedang\", \"1 buah asam jawa\", \"20 buah cabai hijau\", \"3-4 buah cabai biasa\", \"3 lembar daun salam\", \"1 ruas laos\", \"Kecap (bangoooo kalo saya)\", \"Gula merah (dikit ajaa separuh lingkaran kecil)\", \"Garam (separuh depan SDM)\"]', '[\"Rebus daging kambing + 2 lembar daun salam + laos. (airnya sesuai selera yaa, nanti buat kuah air rebusannya). Kalo udah empuk potong2 sesuai selera masukkan lagi ke air kaldu td.\", \"Potong2 tipis (bawang merah + bawang putih + cabai biasa). Potong2 buncis, potong dengan tangan cabai hijau (potongannya kaya potongan buncis). Potong memanjang tomat dan wortel.\", \"Tumis bawputbawmer smp harus ~ cabai hijau+cabaibiasa smp layu ~ tomat wortel buncis smpe layu. Kalo udah tambah kecap bangoooo + garam + daunsalam + asem jawa + gula merah. Tumis2 bentar biar agak meresap.\", \"Tumisan slese campur ke kuah kaldu yg sudah ada potongan daging td. Tunggu sampe mendidih dan rasa meresap kedaging. Tambah kecap kalo yg suka manis. ceki ceki rasa. Jadi dehhhh.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(790, 3, 'Sop Kambing', 'Sop Kambing dengan daging kambing empuk tanpa bau prengus.', '[\"Bahan Utama :\", \"1/4 Daging Kambing + Tulang belulang campur tulang sapi 😁\", \"2 Bh Kentang\", \"2 Bh Wortel\", \"2 Cm Jahe\", \"Minyak untuk menumis\", \"Air Untuk merebus daging\", \"garam & penyedap\", \"Bumbu untuk Kuah :\", \"6 siung bawang Merah\", \"3 siung bawang putih\", \"sesuai selera Merica\", \"3 butir kapulaga\", \"3 butir kembang lawang\", \"4 buah kayu manis kecil\", \"1/2 buah pala\", \"1 Batang Daun bawang (boleh tambah seledri klo saya tdk pakai)\", \"1 buah Tomat\", \"Bawang goreng (saya tdk pakai krn malas goreng)\", \"Bahan Pelengkap :\", \"Emping\", \"Bawang goreng\", \"Sambal + jeruk nipis\"]', '[\"Langkah pertama mengolah daging kambingnya terlebih dahulu, potong-potong daging kambing sesuai dengan ukuran yang diinginkan, jika tulang terlalu panjang maka potoh atau belah tulangnya.Setelah itu, cuci daging dan tulang hingga bersih.\", \"Kemudian rebus daging dan tulang dengan air bersih dan masukkan jahe yang sudah dimemarkan, lalu masukkan garam, kemudian rebus daging hingga daging menjadi lebih empuk setengah matang.\", \"Panaskan minyak pada wajan dan tumis bumbu-bumbu yang sudah dihaluskan (bawah merah, bawang putih, merica) bersama dengan cengkih, biji pala, kayumanis hingga harum dan matang. Aduk-aduk terus hingga tercium aroma harum (gunakan api sedang), angkat dan sisihkan.\", \"Kemudian masukkan bumbu tumisan tadi kedalam rebusan kaldu daging yang sebelumnya kita masak. Aduk hingga merata dan teruskan memasak.Lanjutkan merebus hingga daging menjadi lebih empuk dan matang serta kaldu menjadi lebih menyusut sedikit.\", \"Selanjutnya masukkan potongan wortel, aduk hingga wortel terlihat sudah setengah matang, kemudian lanjut masukkan irisan daun bawang dan tomat kedalam rebusan. Aduk-aduk dan masak sebentar hingga tomat dan daun bawang menjadi lebih layu. Selesai tinggal tambahkan Pelengkapnya tadi ya. Selamat Mencoba 👩🏻‍🍳🍲\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(791, 4, 'Sate kambing ala jatim', 'Cara membuat Sate kambing ala jatim yang enak dan praktis untuk keluarga.', '[\"1/2 kg daging kambing yang ada lemaknya\", \"15 tusuk sate\", \"2 lembar daun pepaya\", \"bumbu kecap:\", \"1 botol kecil kecap manis\", \"10 siung bawang merah\", \"sesuai selera cabai rawit\"]', '[\"Bersihkan daging kambing\", \"Potong dadu /sesuai selera\", \"Bungkus dengan daun pepaya supaya empuk\", \"Tusuk daging kambing selang seling dengan lemaknya\", \"Bakar hingga setengah matang lalu lumuri dengan kecap\", \"Angkat sajikan dengan bumbu kecap, irisan bawang merah dan cabai rawit\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(792, 3, 'Kambing Masak Tomat | daging empuk, tidak bau, dan anti ribet', 'Nikmati kelezatan Kambing Masak Tomat | daging empuk, tidak bau, dan anti ribet dengan resep sederhana ini.', '[\"1 kg daging kambing, potong-potong\", \"1 kg tomat, potong dadu kecil\", \"2 buah bawang bombay iris tipis\", \"secukupnya Garam, merica, bubuk kayu manis\", \"4 sdm minyak goreng\"]', '[\"Masukkan minyak, tumis bawang bombay hingga harum\", \"Masukkan daging kambing, aduk rata hingga berubah warna\", \"Tambahkan tomat, aduk, lalu beri merica dan bubuk kayu manis. Kemudian aduk kembali hingga rata\", \"Tutup panci, tunggu air tomatnya hingga menyusut sambil diaduk sesekali\", \"Setelah air tomatnya menyusut dan mengental, tambahkan garam sesuai selera\", \"Siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(793, 4, 'Rica-rica Daging Kambing', 'Rica-rica Daging Kambing - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1/2 kg daging kambing potong dadu ukuran sedang\", \"15 buah cabai rawit merah\", \"1/2 sdt merica\", \"3 butir kemiri\", \"7 butir bawang merah\", \"4 siung bawang putih\", \"2 batang serai\", \"1 batang jahe ukuran sedang\", \"3 ruas lengkuas (geprek)\", \"3 lembar daun salam\", \"4 lembar daun jeruk purut\", \"Secukupnya gula jawa, garam, dan kecap manis\", \"1 buah tomat hijau\", \"2 batang daun bawang (boleh skip), sesuai selera\"]', '[\"Haluskan bumbu : bawang merah, bawang putih, merica, kemiri, dan cabe rawit\", \"Tumis bumbu halus sampai harum kemudian tambahkan gula jawa, daun salam, lengkuas, jahe, serai, dan daun jeruk\", \"Masukkan potongan daging kambing, aduk aduk sampai bumbu tercampur merata\", \"Tambahkan kecap manis dan garam kemudian aduk-aduk lagi\", \"Masukkan air secukupnya untuk melunakkan daging kambing kemudian tunggu sampai daging benar2 matang/lunak\", \"Setelah air agak asat dan daging dirasa sudah matang masukkan potongan tomat dan daun bawang\", \"Aduk-aduk sebentar sampai tomat dan daun bawang agak layu, kemudian angkat dan sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(794, 2, '🍵Tengkleng Iga Kambing🍵', 'Resep 🍵Tengkleng Iga Kambing🍵 yang lezat dan mudah dibuat di rumah.', '[\"2 kg kurleb iga kambing\", \"130 ml Santan instan\", \"Secukupnya air\", \"Secukupnya minyak goreng\", \"🍲bumbu daun dan geprek\", \"2 batang sereh\", \"Seruas jari lengkuas\", \"Seruas jari jahe\", \"2 lembar daun salam\", \"3 lembar daun jeruk\", \"4 butir cengkeh\", \"3 ruas jari kayu manis\", \"🌹 bumbu halus\", \"9 butir bawang merah\", \"5 siung bawang putih\", \"5 butir kemiri\", \"Secukupnya cabai\", \"2 ruas jari kunyit\", \"Seruas jari jahe\", \"1 sdm ketumbar\", \"Secukupnya garam, kaldu bubuk dan gula merah\", \"1/2 sdt lada bubuk\", \"1/4 sdt pala bubuk\", \"🍲pelengkap\", \"Secukupnya bawang goreng\"]', '[\"Tumis semua bumbu hingga harum kecuali kaldu, garam dan gula merah.\", \"Campur bumbu tumis dg iga. Masukkan panci presto dan beri garam dan air secukupnya.\", \"Presto 20 menit dari desisan pertama.\", \"Setelah 20 menit beri gula merah dan kaldu bubuk serta santan kental. Masak hingga mendidih.\", \"Sajikan hangat dg pelengkap\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(795, 3, 'Nasi Kebuli Kambing #suasana idul adha', 'Resep Nasi Kebuli Kambing #suasana idul adha ala rumahan yang dijamin menggugah selera.', '[\"1/5 kg daging kambing\", \"500 ml air\", \"40 ml santan (setengah santan kara yg segitiga)\", \"4 cup beras biasa\", \"Bumbu halus 1:\", \"8 bawang merah\", \"4 bawang putih\", \"2 ruas kunyit\", \"Bumbu halus 2:\", \"2 kapulaga (isinya saja)\", \"2 bunga lawang\", \"1/2 sdt jintan\", \"1/2 sdt lada bubuk\", \"1 sdt ketumbar\", \"1 sdm garam\", \"1 sdt kayu manis\", \"Bumbu pelengkap:\", \"1 1/2 sdt bumbu kare instan\", \"1 sdt gula pasir\", \"1 sdt masako\", \"4 sdm minyak goreng\", \"3 sdm mentega\"]', '[\"Rebus daging kambing (tanpa dicuci) sampai setengah matang, buang airnya, bersihkan kotoran2 yg menempel di daging, sisihkan\", \"Panaskan minyak dan margarin, tumis bumbu halus 1 smpe harum, masukan bumbu halus 2, tumis sebentar, tambahkan air, gula, garam, kare, aduk2\", \"Tambahkan air 500ml dan rebusan daging kambing, tambahkan santan, aduk sampai mendidih\", \"Aku: sisihkan sebagian daging untuk di goreng, dan sebagian lagi untuk diikutkan dimasak bersama beras\", \"Cuci bersih beras, masak dg ricecooker menggunakan air kaldu daging tadi\", \"Di tengah memasak dg ricecooker aduk2 sebentar, lanjut memasak lagi,, sesuaikan air dg beras yg di pakai,, klo aku, hasil rebusan tdi aku masukan semua, dan aku tambahkan air lagi 2 gelas belimbing\", \"Ini hasilnya,, smg bermanfaat,, :)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(796, 2, 'Tongseng kambing pedas', 'Buat Tongseng kambing pedas yang nikmat dengan langkah-langkah mudah ini.', '[\"500 gr  daging kambing\", \"1 buah Bawang bombai, jahe, salam, garam\", \"2 buah tomat, potong kotak\", \"250 gr kol, rajang kasar\", \"8 sdm  kecap manis\", \"3 sdm saus tiram\", \"Mentega untuk menumis\", \"Bumbu halus:\", \"4 siung bawang putih,\", \"5 btr  kemiri sangrai\", \"Kunyit seujung jari, garam, merica,royco sapi, gulput\", \"Bumbu kasar:\", \"6 siung bawang merah iris tipis\", \"5 cabe merah kriting iris\", \"10 rawit domba, iris\", \"lengkuas, daun jeruk, serai\"]', '[\"Poin 1 rebus, buang air rebusannya.potong dagingnya sesuai selera\", \"Tumis bawang merah,masukkan bumbu halus, bumbu kasar, setelah harum masukkan daging.masukkan air secukupnya\", \"Masak hingga lunak(klo aku di presto aja biar cpt mpuk) setelah airnya menyusut masukkan kol dan tomat.aduk sebentar angkat dan hidangkan.\", \"TIPS: setelah makan daging kambing,minum 1 gelas jus timun(tanpa gula) bwt menetralisir.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(797, 3, 'Tumis sayur sate kambing', 'Buat Tumis sayur sate kambing yang nikmat dengan langkah-langkah mudah ini.', '[\"4 tusuk sate kambing\", \"1/2 buah kol iris\", \"2 buah kentang potong kotak lalu goreng\", \"Seledri iris halus\", \"Bumbu :\", \"1 btg bawang pre iris serong\", \"3 siung bawang putih iris tipis\", \"5 siung bawang merah iris tipis\", \"2 ruas jari jahe iris tipis\", \"1 btg serre geprek\", \"2 buah cabe merah\", \"5 buah cabe rawit\", \"1 gelas air\", \"Secukupnya garam gula kaldu bubuk\"]', '[\"Tumis bawang2an, cabe, jahe dan serre geprek hingga harum. Masukkan sate kambing. Beri air biarkan mendidih.\", \"Masukkan irisan kol dan kentang goreng. Beri garam gula dan kaldu bubuk sesuai selera. Tes rasa. Masak hingga kol matang. Taburi seledri. Angkat dan hidangkan hangat dgn nasi\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(798, 4, 'Sate kambing solo sambal kecap', 'Resep Sate kambing solo sambal kecap ala rumahan yang dijamin menggugah selera.', '[\"200 gr daging kambing\", \"100 gr lemak kambing (saya ga pakai)\", \"1 sdt merica bubuk\", \"1 sdt garam\", \"3 sdm kecap manis\", \"1 sdm minyak goreng\", \"Tusuk sate secukupnya\", \"Sambal:\", \"1 buah tomat uk sedang, potong 8 bagian\", \"5 butir bawang merah, iris\", \"10 buah cabe rawit merah, potong2\", \"1 sdt merica bubuk\", \"5 sdm kecap manis\"]', '[\"Potong2 daging dan lemak kambing (potong kotak 2 cm)\", \"Campur dalam mangkok : daging kambing, lemak, merica, garam, minyak, kecap\", \"Remas2 sebentar, lalu diamkan 30 menit\", \"Tusuk daging dan lemak selang-seling (daging.lemak.daging)\", \"Bakar sampai matang\", \"Sambal: masukkan semua bahan sambal dalam mangkok, aduk rata. Diamkan.\", \"Jangan menambahkan air ke sambal yaaa karna nanti tomatnya akan mengeluarkan air\", \"Sajikan sate kambing dengan nasi hangat dan sambalnya\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(799, 4, 'Tongseng Kambing Empuk', 'Buat Tongseng Kambing Empuk yang nikmat dengan langkah-langkah mudah ini.', '[\"1,25 kg daging kambing\", \"bumbu tongseng beli dipasar\", \"garam scukupnya\", \"1 sdm gula\", \"1 bks royco sapi\", \"2 buah nanas parut\", \"1 bks santan kara\", \"1 liter air\", \"10 buah caberawit merah\", \"bawang goreng\", \"1/4 butir kobis iris\", \"minyak untuk menumis\"]', '[\"Gunakan parutan nanas untuk merendam daging kambing aku dari jam 8pagi sampe jam 11 siang..lalu dipresto kurleb 45 menit..kalau sudah potong dadu\", \"Tuang 2sdm minyak ke wajan, masukan bumbu jadi & caberawit..tumis sampai harum\", \"Masukan daging aduk2 sampai merata..tambahkan air kurleb 2 gelas tunggu smpai mendidih\", \"Tambahkan santan kara aduk2...setelah mendidih tambahkan kobis\", \"Sebagai pelengkap tambahkan gula garam royco...icip rasa..sajikan dengan taburan bawang goreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(800, 3, 'Gule (becek) kambing khas Tulungagung', 'Buat Gule (becek) kambing khas Tulungagung yang nikmat dengan langkah-langkah mudah ini.', '[\"1 kg daging kambing beserta tulang sumsum nya\", \"10 siung bawang merah\", \"7 siung bawang putih\", \"2 ruas jari jahe\", \"2 ruas jari lengkuas\", \"2 ruas jari kencur\", \"2 ruas jari kunyit\", \"1 jari telunjuk kunci\", \"3 Batang serai - geprek\", \"1 sdt bubuk ketumbar\", \"7 butir kemiri\", \"5 lembar daun jeruk\", \"2 buah tomat\", \"Air untuk merebus kambing (sesuaikan)\", \"Garam\", \"secukupnya Minyak goreng\", \"Cabai rawit yg direbus untuk pelengkap sajian\", \"Jeruk nipis untuk pelengkap\", \"Kecap untuk pelengkap\"]', '[\"Setelah dibersihkan, rebus daging kambing sampai lunak\", \"Haluskan bumbu bawang merah, bawang putih, kencur, kunyit, jahe, kunci, kemiri, tumbar\", \"Sangrai dengan minyak goreng bumbu yg dihaluskan, masukkan lengkuas, serai, daun jeruk, sampai wangi\", \"Setelah daging kambing matang dan empuk, masukkan bumbu yg sdh disangrai, masak hingga meresap\", \"Setelah benar2 empuk dan meresap, masukkan santan dan koreksi rasa dengan garam, masukkan irisan tomat\", \"Setelah matang sajikan dengan cabao rawit yg direbus, irisan jeruk nipis dan kecap\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(801, 3, 'Tongseng Iga Kambing', 'Resep Tongseng Iga Kambing yang lezat dan mudah dibuat di rumah.', '[\"600 gram iga kambing\", \"5 lembar daun kool/kobis\", \"1 buah tomat segar ukuran besar (potong2)\", \"Bumbu yang di haluskan :\", \"3 siung bawang putih\", \"5 siung bawang merah\", \"3 butir kemiri\", \"1/2 sdt jintan\", \"1 ruas jari jahe\", \"1 ruas kunyit\", \"Seujung sdt pala\", \"1 sdt Ketumbar\", \"Bahan yang dicampurkan :\", \"1 buah sereh memarkan\", \"2 lembar daun salam\", \"3 lembar daun jeruk (sobek2)\", \"30 ml santan kara\", \"3 sdm kecap manis\", \"1 sdt gula merah\", \"secukupnya Garam\", \"secukupnya Lada bubuk\", \"1.5 liter air utk merebus daging\", \"2 sdm Minyak goreng(menumis)\"]', '[\"Panaskan minyak goreng lalu masukkan bumbu yang dihaluskan dan bumbu lainnya kecuali kecap dan santan... Tumis sampai harum kemudian masukkan daging sampai berubah warna\", \"Lalu masukkan air dan rebus daging bersama bumbu sampai benar2 empuk lalu masukkan kecap manis (rebus kurleb 70 menit)\", \"Setelah dagingnya iga empuk dan air menyusut banyak... Tambahkan santan karanya... Aduk2 dan tes rasa ya bunda...😘\", \"Kemudian masukkan daun kool/kobis sampai setengah layu n tomat potong.. Siap dihidangkan bersama nasi hangat...\", \"Semoga bermanfaat n keluarga anda menyukainya🙏🙏\", \"NB : agar daging iga kambing cepat empuknya bungkus lebih dulu dengan daun pepaya lalu cuci dan siap di masak\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(802, 4, 'Tengkleng (sup kambing)', 'Resep Tengkleng (sup kambing) ala rumahan yang dijamin menggugah selera.', '[\"100 gram Jeroan kambing  potong sesuai selera\", \"100 gram Daging kambing muda  dipotong kotak – kotak\", \"200 gram Iga kambing  dipotong kotak kotak\", \"3 lembar Daun salam ,\", \"3 lembar Daun jeruk\", \"3 cm Lengkuas  dimemarkan,\", \"3 cm Jahe\", \"1 batang Sereh  dimemarkan,\", \"6 butir Bawang merah\", \"3 cm Kunyit ,\", \"1 sendok teh Ketumbar\", \"Bumbu halus ##\", \"4 siung Bawang putih ,\", \"3 buah Cabai merah besar ,\", \"secukupnya Bawang merah goreng\"]', '[\"Pertama – tama, rebus daging, iga serta jeroan kedalam air mendidih selama kurang lebih 1 jam, setelah 1 jam dan matang, sisihkan.\", \"Sementara itu, tumis bumbu halus, kemudian masukan daun jeruk, daun salam, dan juga jahe. Aduk hingga mengeluarkan aroma yang wangi, masukan bumbu yang ditumis ke panci yang tadi berisi rebusan daging serta jeroan dan iga kambing yang tadi direbus.\", \"Panaskan lagi panci, dan aduk hingga merata. Tambahkan garam, dan gula secukupnya, bila rasanya dan bumbu sudah pas, maka tutup panci tengkleng dan masak hingga matang dan bumbu meresap.\", \"Setelah bumbu matang, maka sajikan tengkleng kambing ini menggunakan mangkuk saji, dan tambahkan bawang merah goreng sebagai bahan pelengkapnya.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(803, 2, 'Sate Kambing Empuk', 'Resep Sate Kambing Empuk ala rumahan yang dijamin menggugah selera.', '[\"700 gram daging kambing, buang lemaknya\", \"⚘Bumbu Halus untuk dilumurkan daging⚘:\", \"4 Bawang putih\", \"1 sdt Ketumbar\", \"1 bongkah Gula Merah\", \"3 buah Asam Jawa\", \"Secukupnya Garam\", \"⚘Olesan Saat Dibakar⚘ :\", \"5 sdm Kecap Bango\", \"8 sdm Air\", \"3 sdm Minyak Goreng\", \"⚘Pelengkap ⚘ :\", \"2 buah Tomat\", \"5 Bawang merah\", \"2 Cabe Rawit, iris2\"]', '[\"Daging kambing dipotong2 dadu lalu bungkus dg daun pepaya yg telah diremas2. Diamkan 30 menit agar enzim papain yg terkandung pd daun pepaya bekerja mengempukkan daging.\", \"Setelah 30 menit, buka bungkusan daun pepaya lalu cuci daging. Ada yg bilang kalo nyuci daging jangan dicuci ya tapi kalo aku lebih afdoll dicuci bersih dulu\", \"Setelah dicuci, lumuri daging dengan bumbu halus. Aduk2 hingga bumbu merata lalu tusukkan daging pd tusuk sate.\", \"Bakar di atas bara api sambil diolesi bumbu olesan..sambil dikipas2 dan dibalik2 hingga sate matang dan harum.\", \"Empuk beneran lo bukibuk..bener2 ampuhh nii si daun pepaya. Maknyus deh anak2ku aja kuat ngunyahnya\", \"Sajikan sate bersama nasi putih dan irisan tomat + irisan bawang merah dan cabe rawit. Tuangi kecap manis uuuwhhh mancaaap djiwaa xixixixi..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(804, 2, 'Daging Kambing Tumis', 'Daging Kambing Tumis - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"sesuai selera Daging kambing, (direbus smp empuk), potong2\", \"Cabe Merah (sesuai selera)\", \"Cabe Rawit (sesuai selera)\", \"Bawang Merah (sesuai selera)\", \"Bawang Putih (sesuai selera)\", \"Bawang Bombay (sesuai selera)\", \"Belimbing Wuluh/ Besi (secukupnya, klo tll bnyk jd asam)\", \"Daun Salam (2-3 lembar)\", \"Minyak goreng (secukupnya)\", \"Garam (secukupnya)\", \"Penyedap rasa/ vetsin (secukupnya)\"]', '[\"Tutup daging kambing yg sudah dicuci bersih dengan daun pepaya sebelum direbus, kurang lebih 20-30 menit (supaya dagingnya empuk)\", \"Iris cabe merah, cabe rawit, bawang bombay, bawang merah, dan bawang putih\", \"Tumis bumbu yg diiris, masukkan daun salam. Tumis sampai harum dan mulai layu\", \"Potong belimbing menjadi beberapa potong, masukkan dalam tumisan\", \"Setelah tumisan hampir matang, masukkan potongan daging kambing, masak hingga matang. Tambahkan garam dan vetsin, aduk lalu angkat\", \"Voila... Enak disantap dgn nasi hangat 😀\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(805, 4, 'Lamb cop/steak kambing', 'Sajian Lamb cop/steak kambing yang praktis dan lezat untuk dinikmati bersama.', '[\"steak Kambing\", \"Sos tiram\", \"Sos lada hitam\", \"Garam\", \"Bawang putih halus\", \"Mentega\", \"Lada hitam\", \"T.jagung (sikp jg bole)\", \"Toping:\", \"Jpn wortel\", \"Brokoli\", \"Sos steak:\"]', '[\"Uleni lamb dgn bawang putih,sos tiram, diamkan few menit.\", \"Pagang steak pke fying pan tmbah sdkit mentega apa kecil tugu sampe matang bolak balik.angkat sisihkan\", \"Toping: potong wortel sesuai selera. Cuci brokoli dgn bersih dgn garam rendam sebentar angkat rendam lagi sm air panas- 5-10min tiriskan\", \"Sos steak: goreng mentega dkit masukan sos tiram dgn sos lada hitam,sdkit garam tmbah sedkit air.angkat dan tuang sos di atas steak kambing. Sajikan dan beri toping sayur. Done ✅\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(806, 2, 'Kroket daging kambing + tips agar kambing ga bau prengus', 'Sajian kambing spesial: Kroket daging kambing + tips agar kambing ga bau prengus yang menggugah selera.', '[\"Kulit kroket:\", \"100 gr tepung kentang\", \"secukupnya Air panas\", \"1 sdt kaldu bubuk atau garam\", \"1 butir kuning telur\", \"1/2 sdt merica bubuk (boleh kurang)\", \"Sedikiiit aja pala bubuk\", \"Ragout:\", \"100 gr daging kambing rebus cincang\", \"1 batang kecil seledri\", \"1 batang kecil daun bawang (ambil daun ijonya aja)\", \"1 buah wortel potong kotak kecil\", \"75 gr tepung terigu\", \"2 sdm margarin untuk menumis\", \"50 gr keju parut (boleh skip)\", \"500 ml air (boleh ganti susu cair)\", \"1/2 bawang bombay, iris halus\", \"4 siung bawang putih, cincang\", \"1 sdt merica bubuk\", \"Secuil pala, haluskan (1/2 sdt pala bubuk)\", \"secukupnya Garam\", \"5 buah cabe rawit, cincang (boleh skip)\", \"Pelapis:\", \"1 putih telur\", \"secukupnya Tepung roti\"]', '[\"Kulit kroket:\", \"Seduh tepung kentang dengan air panas secukupnya (jgn kalap maakkk nanti blenyek *apa ya bhasa indonesianya?). Boleh ganti kentang biasa yaa tp saya ndak tau takarannya 😅 jd silakan dikira2 sendiri\", \"Masukkan garam, merica dan pala bubuk, cicipi. Kalo udh pas, masukkan kuning telor, aduk rata, sisihkan\", \"Ragout:\", \"Tumis bawang bombay, bawang putih sampai wangi, masukkan pala bubuk dan merica, aduk2 sampai wangiiii\", \"Masukkan daging cincang, aduk rata\", \"Masukkan tepung terigu, aduk sampai bergerindil (kecilkan api biar terigu ga gosong)\", \"Tuang air atau susu, aduk2 sampai terigu ga bergerindil lg\", \"Masukkan parutan keju, wortel, dan cabe. Masak hingga mengental sambil terus diaduk. Cicipi, klo kurang asin bisa tambah garam.\", \"Matikan api, masukkan daun seledri dan daun bawang cincang. Biarkan dingin\", \"Penyelesaian:\", \"Ambil sedikit adonan kulit, beri isian secukupnya. Masukkan ke kocokan putih telur, lalu balurkan ke tepung roti. Goreng hingga matang\", \"Tips: 🍀 setelah dipanir, masukkan kroket ke kulkas 30mnt-1jam, supaya tepung panir benar2 menempel dan ga banyak yg rontok saat digoreng.\", \"🍀supaya daging kambing ga bau prengus. Masukkan daging (potongan besar) ke air mendidih, lalu rebus dengan api besaaarrr sampai busa2nya keluar (10-15mnt). Buang busa, lalu angkat daging, bersihkan lemak dan kotoran2 yg masih tersisa (biasanya sih udah bersih, tp klo masih kurang bersih bisa dicuci di air mengalir).\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(807, 2, 'Sayur asem tulang kambing', 'Cara membuat Sayur asem tulang kambing yang enak dan praktis untuk keluarga.', '[\"1 kg tulang kambing\", \"bahan-bahan sayur asem:\", \"Kacang panjang\", \"Kacang tanah\", \"Daun melinjo\", \"Melinjo\", \"Labu siam\", \"Jagung\", \"Bumbu halus:\", \"3 cabai merah keriting\", \"3 cabai rawit merah\", \"5 bawang merah\", \"1 asam jawa\", \"3 ruas asam mentah\", \"secukupnya Gula merah\"]', '[\"Rebus tulang kambing, saya pakai panci presto agar cepat empuk\", \"Didihkan 1 liter air, jika sudah mendidih masukan bumbu halus, bahan-bahan sayur asem dan tulang kambing. Tambahkan garam secukupnya, koreksi rasa\", \"Sayur asem tulang kambing, siap dihidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(808, 3, 'Kambing Goreng Kecap', 'Resep praktis Kambing Goreng Kecap yang bisa dicoba di rumah.', '[\"500 gr daging kambing (potong-potong)\", \"Sekerat kunyit\", \"2 buah bawang putih (haluskan)\", \"2 buah bawang putih (iris tipis)\", \"1/2 sdt ketumbar bubuk\", \"1/4 sdt lada bubuk\", \"Secukupnya garam\", \"Secukupnya penyedap rasa (Royco)\", \"4 lembar daun jeruk\", \"1/4 cangkir Minyak goreng\", \"Saus kecap:\", \"5 sdm kecap manis (sesuai selera)\", \"3 buah bawang merah (iris tipis)\", \"2 buah cabai merah (iris)\", \"4 buah cabai rawit merah (iris)\", \"Secukupnya garam dan penyedap\"]', '[\"Haluskan bawang putih, kunyit, ketumbar, lada.\", \"Campurkan bumbu halus dengan daging kambing. Tambahkan garam dan penyedap. Aduk rata. Goreng dalam minyak. Masukkan irisan bawang putih dan daun jeruk. Masak hingga matang dan empuk.\", \"Semua bahan saus kecap diaduk menjadi satu. Tes rasa. Dan tuang keatas daging kambing Goreng yang telah matang, siap dihidangkan. 😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(809, 2, 'Sate kambing manis gurih', 'Resep praktis Sate kambing manis gurih yang bisa dicoba di rumah.', '[\"Daging kambing\", \"Minyak goreng\", \"Kecap\", \"Mentega\", \"Tusuk sate\"]', '[\"Daging kambing diiris dadu atau sesuai selera\", \"Setelah dpotong semua tuang sedikit minyak goreng di piring dan msukkan daging ke piring biar empuk sambil di ulet2\", \"Tata daging di tusukan sate sesuai selera\", \"Lumuri daging dengan kecap\", \"Bakar sate sampai matang sambil dioles mentega biar gurih\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(810, 4, 'Rica rica daging kambing', 'Sajian kambing spesial: Rica rica daging kambing yang menggugah selera.', '[\"1/4 daging kambing\", \"4 bj bawang merah\", \"2 bawang putih\", \"3 kemiri\", \"1/2 sendok ketumbar\", \"1/2 sendok merica\", \"3 sdt garam\", \"1 sdt gula pasir\", \"1 sereh\", \"1/4 jahe\", \"1/4 lengkuas\"]', '[\"Rebus daging setengah matang\", \"Semua bumbu di haluskan dan di tumis, masukkan daging dan di aduk rata\", \"Masukkan air secukupnya, masukkan garam, gula pasir,kecap manis\", \"Test rasa dan hidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(811, 2, 'Marak kambing', 'Resep Marak kambing yang lezat dan mudah dibuat di rumah.', '[\"1 kg daging kambing\", \"2 biji bawang bombay (rajang)\", \"10 siung bawang putih (rajang)\", \"8 siung bawang merah (rajang)\", \"1 jari jahe (rajang)\", \"1 jari kunir (rajang)\", \"1 sdt merica bubuk\", \"Kayu manis,cengkeh,kapulaga,garam\", \"1 biji tomat segar\"]', '[\"Rebus air sampai mendidih..Masukan daging sampai kambing berubah warna\", \"Masukan bawang Bombay,bawang merah,bawang putih,jahe,kunir, merica, kayu manis, kapulaga, garam sampai empuk..\", \"Kalau sudah empuk potong tomat menjadi 2 bagian masukin sbntr matiin kompor\", \"Jadi dech...Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(812, 4, 'Sambalado ati kambing', 'Sajian Sambalado ati kambing yang praktis dan lezat untuk dinikmati bersama.', '[\"1 kg hati kambing, rebus bersama: 5 lembar daun salam, 3 lembar daun jeruk, 2 ruas jahe dan 2 batang serai dimemarkan\", \"secukupnya Minyak goreng\", \"Bumbu sambal goreng (direbus& ulek):\", \"100 gr cabe merah\", \"5 biji cabe rawit caplak\", \"8 siung bawang merah\", \"2 siung bawang putih\", \"6 butir kemiri, goreng sebentar\", \"1/2 sdm terasi medan, goreng sebentar\", \"2 buah tomat, ukuran besar\", \"Secukupna garam, gula pasir, kaldu jamur, asam jawa\"]', '[\"Hati yg telah direbus, dipotong2 iris lalu digoreng, sisihkan.\", \"Tumis bumbu sambal goreng kemiri, hingga harum lalu masukkan gula pasir, garam, kaldu jamur & asem. Aduk rata.\", \"Tambahkan hati yg telah digoreng ke dalam sambal yg digoreng,aduk rata. Cicipi rasa. Siap hidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(813, 2, 'Tongseng Daging Kambing Sederhana', 'Cara membuat Tongseng Daging Kambing Sederhana yang enak dan praktis untuk keluarga.', '[\"Daging kambing\", \"kubis\", \"4 lembar daun jeruk\", \"4 lembar daun salam\", \"laos, geprek\", \"sereh, geprek\", \"garam\", \"gula merah / gula biasa\", \"1 sdm kecap manis\", \"minyak\", \"air\", \"Bumbu halus:\", \"4 bawang putih\", \"8 bawang merah\", \"3 cm kunyit\", \"4 cm jahe\", \"1 kemiri\", \"ketumbar\", \"cabe rawit\"]', '[\"Potong2 daging sesuai selera.. kalo saya potong kotak2, lalu saya pukul2 sampe agak tipis.. kemudian rebus daging hingga empuk.\", \"Potong2 kubis sesuai selera\", \"Tumis bumbu halus hingga harum. Masukkan daun salam, daun jeruk, sereh dan lengkuas yg sudah digeprek. Kemudian masukkan daging dan tambahkan air.\", \"Masak hingga mendidih, masukkan kubis yang sudah dipotong2. Kemudian beri garam, gula dan kecap. Tes rasa.\", \"Tongseng siap dihidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(814, 4, 'Tongseng kambing simple', 'Cara membuat Tongseng kambing simple yang enak dan praktis untuk keluarga.', '[\"1/4 daging kambing\", \"1/4 kol dr 1 bulat kol\", \"2 buah tomat\", \"3 siung bawang putih\", \"5 siung bawang merah\", \"1 btg sereh (keprek)\", \"2 lembar daun salam\", \"2 cm jahe\", \"2 cm kunyit\", \"10 buah cabe rawit merah\", \"1/2 sdt lada bubuk\", \"1 sdt ketumbar\", \"2 butir kemiri\", \"2 sdm kecap bango\", \"1 bungkus santan kara 65ml\", \"1 sdt garam\", \"Secukupnya penyedap\", \"1/2 sdt jinten\", \"Secukupnya minyak untuk menumis\", \"Secukupnya air untuk merebus\"]', '[\"Cuci bersih daging kambing potong kecil sesuai selera\", \"Rebus daging dicampur bersama daun salam agar bau anyir tidak terlalu melekat, beri sedikit garam rebus hingga empuk\", \"Iris kol kecil2,, Haluskan bumbu semua bumbu kecuali cabe sereh dan daun salam, kemudian tumis setelah harum masukkan sereh daun salam\", \"Tuang air secukupnya masukkan daging kambing, diamkan sbntr baru masukkan kol hingga layu kemudian masukkan cabe rawit merah, santan kara dan kecap aduk rata tes rasa jika sudah empuk, baru masukkan tomat yg sudah di potong sesuai selera diamkan sebentar baru matikan kompor,,\", \"Tongseng kambing simple siap disajikan dgn nasi hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(815, 4, 'Sup Kambing', 'Resep Sup Kambing ala rumahan yang dijamin menggugah selera.', '[\"1/4 Daging Kambing Potong Dadu\", \"Bawang Goreng\", \"Wortel\", \"Kol Putih\", \"Buncis\", \"Tomat Merah\", \"Daun Bawang\", \"Seledri\", \"Bumbu :\", \"3 Siung Bawang Putih\", \"2 Sdt Lada Bubuk\", \"1 Biji Pala\", \"Secukupnya Garam\", \"Secukupnya Gula Pasir\", \"Secukupnya Air\", \"secukupnya Margarin\"]', '[\"Rebus daging kambing hingga empuk, Haluskan Bawang putih, Lada Bubuk. Tumis margarin dan Bumbu yang sudah dihaluskan\", \"Masukan air dan sayuran kecuali tomat dan seledri, lalu masukan daging kambing yang sudah empuk dan biji pala digeprek, Beri garam dan gula sesuai selera\", \"Terakhir Masukan tomat dan seledri, Hidangkan dengan diberi taburan bawang goreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(816, 2, '🐏 Sate Kambing Goreng Lada Hitam🐏', '🐏 Sate Kambing Goreng Lada Hitam🐏 - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"🐏Bahan Utama :\", \"300 gram daging kambing\", \"🐏 bahan marinasi:\", \"8 Bawang Merah,haluskan\", \"4 Bawang Putih,haluskan\", \"1 sdt merica bubuk\", \"2 sdm ketumbar,sangrai lalu haluskan\", \"2 sdm kecap manis bango\", \"50 ml air\", \"🐏 Bahan Pelengkap :\", \"3 bawang putih geprek,cincang halus\", \"1 bawang bombay, iris tipis\", \"1 sdt lada hitam\", \"2 sdm kecap manis\", \"1 sdm gula merah sisir halus\", \"1/2 sdt garam\", \"1 sdm kaldu jamur\", \"200-250 ml air\", \"1 buah Tomat, iris potong dadu\", \"Cabe rawit secukup nya\"]', '[\"Potong dadu kecil daging kambing. Lalu campurkan pada bumbu untuk marinasi nya. Biarkan minimal 3 jam,klo saya semalaman spy bumbu merasuk sempurna. Penyimpanan dlm lemari es\", \"Tuang daging yg sudah dimarinasi pada wajan. Lalu beri tambahan air aduk rata.\", \"Beri gula merah, kecap & garam. Cicipi rasanya, tunggu hingga daging empuk serta kuah nya susut / habis. Sisihkan dlu. Koreksi rasa jangan lupa yaa😊\", \"Tumis bawang bombay hingga setengah layu lalu masukan bawang putih, aduk hingga bau wangi. Gunakan minyak agak banyak yaa,,karna sekaligus untuk proses goreng daging nya.\", \"Tuang daging yg sudah diungkep tadi, aduk rata hingga tercampur tumisan bawang.\", \"Tambahkan kaldu jamur, aduk rata.\", \"Tunggu hingga daging berubah kering kecoklatan cantik,baru masukan lada hitam nya. Aduk rata\", \"Setelah warna hitam merata & bau khas yg wangi, angkat.\", \"Tata pada wadah, beri irisan tomat & cabai rawit sesuai selera😊.\", \"Selamat makan😍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(817, 4, 'Gule kambing gurih', 'Resep praktis Gule kambing gurih yang bisa dicoba di rumah.', '[\"1 kg iga kambing\", \"2 lt air untuk merebus\", \"2 sct bumbu gule siap pakai\", \"1 sct susu kental manis putih\", \"1 sdm margarin\", \"300 ml santan kara\", \"3 bj cabe merah buang biji(rebus lalu blender)\", \"secukupnya garam dan penyedap\"]', '[\"Rebus air smp mendidih masukkan iga kambing yg sudah dipotong\\\".setelah mendidih biasanya akan keluar kotoran kaldu yg berwarna hitam bisa diambil dan buang/bisa jg dg mengganti air agar kuah tidak kotor.rebus smp daging iga agak empuk\", \"Masukkan bumbu gule siap pakai.biarkan mendidih lalu masukkan cabe merah yg sudah diblender\", \"Setelah mendidih masukkan santan,susu kental manis dan margarin\", \"Masukkan bumbu pendukung lainnya.mendidih dan sajikan.\", \"Saran penyajian.lebih nikmat jika dihidangkan dg menambahkan kecap,perasan jeruk nipis,sambal dan bawang merah goreng.selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(818, 4, 'Nasi Goreng Kambing ala Kebon Sirih', 'Sajian Nasi Goreng Kambing ala Kebon Sirih yang praktis dan lezat untuk dinikmati bersama.', '[\"3 piring nasi dingin (saya 6 piring)\", \"350 gr daging kambing (saya 500 gr), potong-potong dadu\", \"3 butir telur diorak arik (resep asli tidak ada)\", \"1 batang kecil kayu manis (saya panjang 3 cm lebar 1/2cm)\", \"1 sdm bubuk kari (saya pakai bumbu indofood kari pasta)\", \"Bumbu yang dihaluskan:\", \"8 siung bawang merah (saya 12 siung)\", \"4 siung bawang putih (saya 7 siung)\", \"1/2 sdt jintan (saya 1 sdm)\", \"1/2 sdt adas (saya gak pakai karena lagi gak punya)\", \"1 sdm ketumbar (1,5 sdm ketumbar)\", \"2 buah kapulaga\", \"5 buah cengkeh\", \"1 sdt merica\", \"Secukupnya kecap manis, garam, gula, air, dan minyak goreng\"]', '[\"Tumis bumbu halus, kapulaga, adas, bubuk kari sampai harum...kemudian masukan daging kambing. Aduk rata\", \"Tambahkan air secukupnya, garam, gula, sampai daging empuk dan kuah mengental\", \"Masukan nasi, telur orak arik, dan kecap, aduk merata sampai nasi mengering\", \"Sajikan nasi goreng kambing dengan acar kol dan ketimun, emping, bawang merah goreng (saya hanya tambah acar ketimun, bawang merah, cabe rawit, kerupuk aci)\", \"Lebih enak pakai daging kambing yang ada lemaknya, supaya lebih gurih. Yang kolesterolnya tinggi maaf ya ngabibita😆\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(819, 4, 'Tongseng Daging Kambing', 'Nikmati kelezatan Tongseng Daging Kambing dengan resep sederhana ini.', '[\"500 gram Daging kambing, potong2\", \"1 buah tomat\", \"2 lembar daun salam\", \"1 batang sereh, geprek\", \"1 ruas jahe, geprek\", \"1 euas lengkuas, geprek\", \"1 liter santan dari 1 butir kelapa\", \"1/4 kol, potong2\", \"5 buah cabai rawit merah\", \"Kecap manis\", \"Lada bubuk\", \"Penyedap royco\", \"secukupnya Garam dan gula merah\"]', '[\"Rebus daging kambing, tambahkan sereh, daun salam dan daun jeruk. Rebus sampai matang dan buang air nya.\", \"Tumis bumbu halus hingga matang tambahkan sereh, daun salam, jahe dan lengkuas\", \"Masukkan daging dan aduk rata\", \"Tambahkan air secukupnya. Biarkan sesaat hingga mendidih lalu masukkan santan. Aduk rata dan tunggu sampai mendidih\", \"Tambahkan kecap manis secukupnya. Aduk rata. Biarkan beberapa saat lalu tambahkan gula merah, lada bubuk dan royco secukupnya\", \"Terakhir masukkan kol, tomat dan cabai rawit merah utuh. Aduk rata dan koreksi rasa\", \"Sajikan dengan taburan bawang goreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(820, 3, 'Tongseng kambing non santan', 'Resep Tongseng kambing non santan yang lezat dan mudah dibuat di rumah.', '[\"bahan - bahan yang di halus kan, sbb :\", \"5 siung bawang merah\", \"4 siung bawang putih\", \"1 siung jahe\", \"3 butir kemiri\", \"5 cabe merah keriting\", \"5 cabe merah rawit (sesuai selera kalau suka pedas)\", \"bahan - bahan lainnya, sbb :\", \"1 kg daging kambing\", \"1 sachet masako rasa sapi\", \"3 sdm garam (secukupnya)\", \"1 buah jeruk lemon\", \"500 ml air\", \"3 batang sereh\", \"2 lembar daun jeruk\", \"1 lembar daun salam\", \"5 sdm minyak sayur\", \"1 buah tomat\"]', '[\"Rebus daging kambing dengan jeruk lemon (jeruk lemon untuk mengikat lemak kambing) hingga empuk, lakukan 2x perebusan agar bau kambingnya hilang\", \"Setelah empuk potong-potong daging kambingnya sesuai selera\", \"Siapkan pengorengan lalu isikan 5sdm minyak sayur setelah panas masukan bumbu-bumbu yang telah dihaluskan masak hingga harum\", \"Masukkan daging kambing yg telah dipotong-potong, masukan 500ml, masukkan batang sereh yg sudah si geprek beserta daun salam, tomat yang sudah di potong dadu dan daun jeruk tambahan garam dan masako seseuai selera\", \"Masak hingga matang, dan siap di sajikan.\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(821, 2, 'Pindang kambing ala khambec', 'Sajian kambing spesial: Pindang kambing ala khambec yang menggugah selera.', '[\"secukupnya Siapkan daging kambing\", \"Belilah bumbu dapur di pasar yang sudah langsung dihaluskan. ada di pasar biasanya yg sudah diblender\", \"Bumbu dapur sendiri\", \"sereh\", \"Jahe\", \"Cabe\", \"Tomat\", \"Daun salam\", \"1 Batang sereh\", \"Bawang merah\", \"Bawang putih\", \"Kunyit\", \"Garam\", \"Gula\", \"Penyedap rasa\", \"secukupnya Air\", \"secukupnya Minyak makan\"]', '[\"Rebus terlebih dahulu dagingnya agar daging dapat empuk\", \"Setelah direbus haluskan bumbu yakni: cabe, bawang putih, bawang merah, jahe, kunyit, lengkuas, tomat, ini adalah bumbu dapur yang kita ulek sendiri karna kita memiliki 2 bumbu yang pertma kita beli di pasar tdi\", \"Panaskan wajan.. Beri minyak masukan bumbu halus yang beli dipasar yg telah diblender\", \"Kemudian masukan bumbu dapur yg kita ulek baru saja\", \"Oseng oseng hingga mencium wewangian sedap\", \"Masukkan daging kambing yang telah direbus dan beri secukupnya air\", \"Tambahkan daun salam dan Batang sereh jngan lupa beri penyedap rasa.. Termasuk juga garam dan gula tergantung selera\", \"Sudah tunggu saja sekitar 30menit dan tnggu mendidih siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(822, 2, 'Tongseng Kambing (Instant Pot)', 'Buat Tongseng Kambing (Instant Pot) yang nikmat dengan langkah-langkah mudah ini.', '[\"Bahan/Bumbu :\", \"500 gr / 1 lb daging kambing/lamb, rebus 1/2 matang (Saya\", \"dengan air, 2 cm jahe & 2 daun salam\", \"Bumbu:\", \"1 L santan\", \"500 ml air\", \"1/2 ibu jari lengkuas atau bubuk\", \"1 batang serai memarkan\", \"2 lembar daun salam\", \"2 batang daun bawang, potong kasar\", \"1 buah tomat\", \"1/4 kol/kubis Iris tipis\", \"4 buah cabai rawit merah, potong 2 cm\", \"3 sendok makan kecap manis\", \"4 buah bawang merah atau 1/3 bawang bombay, iris tipis\", \"Minyak untuk menumis\", \"Pelengkap: bawang merah goreng\", \"Bumbu Halus:\", \"4 siung bawang putih atau bubuk\", \"6 butir bawang merah atau onion bubuk\", \"1 sendok teh merica\", \"4 buah kemiri, sangrai\", \"3 cm kunyit, bakar atau kunyit bubuk\", \"3 1/2 sendok teh garam\", \"1 sendok makan gula pasir\", \"1 sendok teh ketumbar\"]', '[\"Cara Pengolahan : Rebus daging kambing, daun salam, jahe dan air di instant pot, manual setting 20 menit atau rebus di dalam panci sampai lunak.\", \"Angkat dan buang airnya. Potong-potong.\", \"Haluskan bahan bumbu halus dengan food processor atau blender atau di uleg di cobek.\", \"Tumis bawang merah, bumbu halus, daun salam, lengkuas, serai, bawang merah, cabai rawit merah, serai sampai harum dan matang betul.\", \"Masukkan daging kambing, kecap manis dan air, santan, didihkan sambil diaduk sesekali agar santan tidak pecah sampai semua bumbu meresap dalam daging. Bisa masaknya pake instant pot, dengan setting Sautee.\", \"Tambahkan kol, daun bawang, tomat, dan potongan cabai. Sajikan panas dengan nasi.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(823, 4, 'Tongseng Kambing No Ribet', 'Resep praktis Tongseng Kambing No Ribet yang bisa dicoba di rumah.', '[\"350 gr daging kambing (sesuai selera, kl saya campurr semua dah)\", \"Bumbu halus :\", \"6 siung bawang merah\", \"3 siung bawang putih\", \"3 butir ketumbar\", \"10 buah cabe rawit 😁\", \"secukupnya Jahe\", \"Pelengkap :\", \"2 ruas serai, geprek\", \"2 helai daun salam\", \"Gula, garam, kecap manis\", \"1 buah tomat\", \"1 tangkai daun bawang\"]', '[\"Daging kambing yg blm diapa2in dimasak dl smp agak matang yaa ~ boleh pke panci presto biar lbh empuk\", \"Tumis bumbu halus smp berubah warna kemudian masukkan serai yg sdh digerpek dan daun salam\", \"Masukkan potongan daging kambing, dan aduk sebentar smp bumbu tercampur\", \"Tambahkan air dan biarkan smp bumbu meresap. Tambahkan gula, garam, kecap manis.. Cek rasa\", \"Jika sdh oke, masukkan potongan tomat (sy suka yg potongannya agak gede) 😁 oh ya jgn lupa irisan daun bawangnya.. Siap disajikan dehh\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(824, 3, 'Daging kambing tumis', 'Daging kambing tumis dengan daging kambing empuk tanpa bau prengus.', '[\"1 kg daging kambing\", \"Bawang putih\", \"Bawang merah\", \"Lengkuas\", \"Merica\", \"Daun srek\"]', '[\"Potong kecil kecil daging\", \"Setelah dipotong kecil2 dagingnya, rebus selama setengah jam agar dagingnya lebih maknyos\", \"Sambil menunggu direbus, ulek semua bumbu yang ada di bahan bahan tadi\", \"Setelah itu, masukan bumbu2 yang yg sudah di ulek kedalam kuali berisikan minyak sedikit\", \"Setelah itu, masukan daging yang sudah direbus tadi\", \"Aduk hingga rata.. jangan lupa tambahkan kecap\", \"Daging kambing tumis siap dihidangkan👌\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(825, 4, 'Gulai Kambing Special', 'Cara membuat Gulai Kambing Special yang enak dan praktis untuk keluarga.', '[\"500 g daging kambing\", \"4 daun salam\", \"6 daun jeruk\", \"1 kayu manis\", \"3 cengkeh\", \"2 batang sereh\", \"5 cabe rawit utuh\", \"200 ml santan kara\", \"2 bungkus bumbu gulai(indofood)\", \"±4 sdm kecap manis(tergantung selera)\", \"1 liter air\", \"bumbu halus:\", \"5 bawang merah besar\", \"4 bawang putih\", \"1/2 sdt jintan\", \"2 sdm kunyit halus\", \"6 butir kemiri utuh\", \"2 cm lengkuas\", \"1 cm jahe\", \"1/2 sdt pala\", \"1/2 sdt ketumbar\"]', '[\"Daging direbus dengan 1 liter air,daun salam,daun jeruk,cengkeh,kayu manis,sereh,rawit,hingga daging empuk.\", \"Tumis bumbu halus hingga matang,lalu masukkan kedalam rebusan daging.\", \"Terakhir tuang santan dan bumbu gulai ke dlm rebusan daging..tambah kan kecap manis aduk hingga kuah mengental..lalu sajikan...selamat mencoba😋😋\", \"Notes: agar daging kambing tidak bau,cuci hingga bersih,buang lemak berlebih n darah nya..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(826, 2, 'Gulai kambing ala momz rafbyan', 'Sajian Gulai kambing ala momz rafbyan yang praktis dan lezat untuk dinikmati bersama.', '[\"1 kg daging kambing yang ada tulangnya\", \"1 liter santan\", \"1 bungkus kara\", \"500 ml air\", \"5 lembar daun jeruk\", \"3 lembar daun salam\", \"2 cm Kayu manis\", \"secukupnya Gula pasir, garam, penyedap rasa\", \"Bawang goreng\", \"Minyak secukupnya untuk menumis\", \"Bumbu halus :\", \"8 siung bawang putih\", \"10 siung bawang merah\", \"1 buah cabe merah\", \"1 ibu jari kunyit\", \"Pala sedikit saja\", \"1 sdt ketumbar\", \"2 buah kemiri\", \"Bumbu geprek :\", \"1 ibu jari lengkuas\", \"1 ibu jari jahe\", \"2 buah sere yang putihnya saja\"]', '[\"Presto daging kambing sekitar 15 menit, dinginkan lalu iris sesuai selera.\", \"Haluskan bumbu.\", \"Tumis bumbu sampai setengah matang lalu masukkan lengkuas, jahe, sere, daun salam dan daun jeruk, tumis sampai matang\", \"Masukkan air dan santan tunggu sampai mendidih lalu masukkan daging.\", \"Sambil di aduk masukkan gula pasir, garam dan penyedap rasa.\", \"Tunggu sampai mengeluarkan minyak, tes rasa.\", \"Angkat dan siap di hidangkan dengan taburan bawang goreng.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(827, 4, 'Sate Daging Sapi/Kambing Happy Call', 'Sajian Sate Daging Sapi/Kambing Happy Call yang praktis dan lezat untuk dinikmati bersama.', '[\"1/2 kg daging sapi/kambing\", \"1 sachet kecap bango\", \"1 gandu gula merah\", \"3 siung bawang merah\", \"1 siung bawang putih\", \"1 sdm garam\", \"1 sdt ketumbar bubuk\", \"1/2 sdt merica\", \"1/2 ruas kunyit\", \"1 sdt penyedap rasa sapi\", \"2 buah cabai rawit\", \"sachet Mentega\", \"Bumbu pecel yang sudah jadi\", \"Tusuk sate\", \"Siapkan Happy Call untuk memanggang\"]', '[\"Potong2 daging kotak2 sesuai selera\", \"Ulek 2 siung bawang merah,bawang putih,garam,merica,ketumbar dan kunyit\", \"Masukan daging pada bumbu yg telah diuleg\", \"Diamkan sampai bumbu meresap kemudian tusuk menggunakan tusuk sate\", \"Siapkan happy call diatas kompor dan beri mentega\", \"Masukan daging dan tutup,setelah 10 menit balikan daging\", \"Setelah 20 menit dipanggang daging siap di sajikan\", \"Sajikan bersama bumbu pecel yang sudah jadi dan bumbu kecap yang diberi potongan bawang merah juga cabai rawit\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(828, 2, 'Bakso kambing', 'Buat Bakso kambing yang nikmat dengan langkah-langkah mudah ini.', '[\"1/4 kg daging kambing iris kecil\", \"1 sdm bawang goreng\", \"3 siung bawang putih dihaluskan bersama 1/2 sdt mrica\", \"2 sdt garam\", \"1/2 bks masako\", \"1 btr telur\", \"1 bawang preh\", \"1/4 sdt baking powder\", \"7 sdm kanji\"]', '[\"Semua bahan diblender kecuali kanji\", \"Setelah halus campur kanji\", \"Rebus air sampai mendidih kemudian matikan kompor\", \"Pentol dibulatin taruh di air panas\", \"Rebus sampai terapung lalu angkat pentol taruh diar es biar tetap bulat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(829, 3, 'Krengsengan Kambing Merah', 'Cara membuat Krengsengan Kambing Merah yang enak dan praktis untuk keluarga.', '[\"2 ons daging kambing\", \"Bumbu halus\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"1 cm jahe\", \"4 buah cabe merah\", \"1 sdt merica\", \"Bahan pelengkap\", \"2 sdm kecap manis\", \"4 cm kayu manis\", \"1 sdt saus tiram\", \"secukupnya Gula garam\", \"1 buah tomat ukuran kecil\"]', '[\"Potong daging sesuai selera (kalau saya. Saya potong tipis)\", \"Masukkan bumbu halus yg sudah di blend tmbahkan sedikit air. Tumis smpai harum... masukkan sedikit minyak kemudian masukkan daging kambing tunggu selama 20 menit jika air mulai habis tambahkn air 1 gelas kecil.. kemudian masukkan kecap kayu manis.dan saus tiram. Aduk merata biarkan 5 menit masukkan gula garam dan tomat..\", \"Matikan api setelah 5-10 menit. Tes rasa.. dan siap dihidangkan..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(830, 3, 'Nasi Goreng Kambing Rempah', 'Cara membuat Nasi Goreng Kambing Rempah yang enak dan praktis untuk keluarga.', '[\"200 gr daging kambing, potong kecil-kecil\", \"50 gr lemak kambing, potong kecil-kecil\", \"4 piring nasi putih\", \"4 sendok minyak zaitun\", \"1/2 sendok teh jintan\", \"1/2 sendok teh adas manis\", \"2 bunga lawang\", \"2 cm kayumanis\", \"4 kapulaga hijau\", \"4 buah cengkeh\", \"1/2 sendok teh lada putih\", \"1 sendok teh gula\", \"1 sendok teh Royco\", \"sesuai selera Garam\"]', '[\"Haluskan jintan, adas manis, bunga lawang, kayumanis, kapulaga dan cengkeh. Sisihkan\", \"Panaskan minyak zaitun, masukkan lemak kambing, goreng sampai kering\", \"Masukkan daging kambing, masak sampai matang.\", \"Masukkan bumbu halus, royco, gula dan lada putih. Aduk rata.\", \"Masukkan nasi aduk sampai rata.\", \"Tambahkan garam sesuai selera. Aduk rata.\", \"Hidangkan panas-panas\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(831, 2, 'Daging Kambing bumbu Rica Rica', 'Daging Kambing bumbu Rica Rica dengan daging kambing empuk tanpa bau prengus.', '[\"1/2 kg daging kambing\", \"50 gr cabe rawit\", \"5 butir bawang merah\", \"3 butir bawang putih\", \"2 butir kemiri\", \"secukupnya jahe,lengkuas,kunyit (dikira2 aja)\", \"3 lmbar  daun jeruk\", \"1 btg daun serai\", \"1 lmbar  daun kunyit\", \"1 lmbar kecil  daun pandan\", \"1 btang daun bawang\", \"2 butir tomat\", \"1/2 ikat daun kemangi\", \"secukupnya garam gula dan kaldu bubuk(gk boleh sebutin merek :D)\"]', '[\"Rebus terlebih dahulu daging kambing kurleb 1 jam.potong kotak.sisihkan\", \"Haluslan cabe,bawang,kemiri,jahe,kunyit,lengkuas di ulek yaa jgn di blender..gk asli heheh sisihkan\", \"Potong halus (sesuai selera)daun jeruk,d serai,daun bawang,d pandan,d kunyit,daun bawang.potong kotak2 tomatnya\", \"Tumis bumbu halus hingga harum masukan daun-daunannya kecuali daun bawang n tomat.tumis hingga harum\", \"Masukan daging yg sdh di potong kedlm bumbu aduk rata.tambahkan bumbu penyedap\", \"Masukan 1/2 gelas air aduk2 tutup wajan dgn tutup panci sbentar2 di aduk yaa..sambil koreksi rasa\", \"Masukan daun bawang dan tomat aduk rata tutup sebentar biar agak layu(koreksi rasa)\", \"Terakhir masukan d kemangi aduk aduk sampai tercium aroma kemanginya...\", \"Mengenai kuahnya sesuai selera yaa klo sya gk terlalu berkuah nyamak2 aja heheh.Selamat Mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(832, 4, 'Roti Jala Kare Kambing', 'Roti Jala Kare Kambing - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"Bahan roti\", \"500 gr terigu serbaguna\", \"2 sdm mentega (cairkan)\", \"1 sdt garam\", \"1 sdm susu bubuk\", \"2 butir telur\", \"1000 ml air matang(bisa ditambah jika masih kekentalan)\", \"Bahan kare\", \"500 gr daging kambing\", \"6 siung bawang putih\", \"6 siung bawang merah\", \"5 cabai merah besar\", \"10 cabai merah keriting (selera ukur kepedasan yg diinginkan)\", \"3 butir kemiri\", \"1 sdt merica\", \"Secukupnya ketumbar\", \"1 sdm bumbu kare kambing(saya beli di pasar tradisional)\", \"1 ruas lengkuas\", \"1 ruas jahe\", \"1/2 ruas kunyit\", \"2 batang sereh\", \"4 lembar daun salam\", \"5 lembar daun jeruk\", \"Secukupnya cengkih\", \"Secukupnya bunga lawang\", \"Secukupnya jinten\", \"1/2 butir kelapa parut ambil kanilnya saja\", \"secukupnya Air\", \"Secukupnya pala bubuk\", \"1 sdm gula pasir\"]', '[\"Buat rotinya..campur semua bahan aduk sampai kalis dengan whisk saring dan dadar dengan menggunakan corong roti jala kalo tidak ada bisa pake plastik segitiga gunting ujungnya buat seperti jala (caranya bisa lihat resep saya roti jala kare ayam) gulung seperti gulung risol\", \"Buat karenya..blender semua bahan kecuali bunga lawang cengkih daun jeruk sereh\", \"Tumis bahan dengan sedikit minyak sampai harum tambahkan daging kambing aduk sampai airnya habis tambahkan santan dan air masak hingga daging empuk (boleh juga di presto)tambahkan gula pasir cek rasa\", \"Untuk tambahan boleh buat acar ketimun siapkan 2 buah ketimun 3siung bawang merah cabai secukupnya gula garam dan bbrp tetes cuka aduk sampai layu\", \"Siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(833, 2, 'Tongseng Kambing Cabe Merah (Tanpa Santan)', 'Tongseng Kambing Cabe Merah (Tanpa Santan) - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"350 gr daging kambing\", \"1 genggam potongan kol\", \"1 buah tomat merah uk.sedang\", \"Bumbu Halus:\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"3 buah kemiri\", \"5 buah cabe keriting merah\", \"3 buah cabe rawit merah (sesuai selera pedas)\", \"1 cm jahe\", \"Bumbu Pelengkap:\", \"4 buah daun jeruk\", \"1 buah serai (geprek)\", \"1 sdm bubuk kari\", \"1/3 sdm merica bubuk (boleh tambah/ kurangi)\", \"1 sdm gula pasir\", \"3 sdm kecap manis (saya bango)\", \"1/2 sdm kaldu penyedap (saya royco)\", \"1/2 sdm garam (boleh kurangi/tambah sesuai selera)\", \"Minyak goreng\", \"Secukupnya air (saya kisar 500ml)\"]', '[\"Cuci bersih daging kambing. Potong tipis.\", \"Siapkan bumbu halus. Haluskan dengan uleg atau blender.\", \"Panaskan minyak. Tumis bumbu halus dengan serai dan daun jeruk hingga berubah warna.\", \"Tambahkan daging. Tumis2 daging hingga setengah matang dan warna merah daging berkurang.\", \"Masukkan 500 ml air dan bumbu perasa lain nya. Masak hingga air sedikit menyusut agar daging empuk.\", \"Masukkan kol dan tomat menjelang matang dan daging sudah empuk. Biarkan sebentar sampai layu.\", \"Check rasa akhir. Sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(834, 2, '🍚 Nasgor Kambing sederhana ala Dapur Fitri 🍚', 'Resep praktis 🍚 Nasgor Kambing sederhana ala Dapur Fitri 🍚 yang bisa dicoba di rumah.', '[\"500 gram Nasi putih\", \"100 gram Daging kambing muda\", \"2 batang Daun bawang, iris\", \"3 siung Bawang putih cincang\", \"3 buah Cabe keriting, iris halus\", \"1/2 sdt Lada hitam bubuk\", \"1 sdt Garam\", \"1 sdm Margarine\", \"1 sdm Minyak goreng\", \"Pelengkap :\", \"Acar dan kerupuk emping\"]', '[\"Panaskan minyak dan margarine lalu tumis bawang dan cabe hingga wangi dan layu setelah itu masukkan potongan daging, aduk-aduk, tumis sekitar 3 menit daging kambing sudah di rebus sebelumnya bersama lada dan bawang putih.\", \"Masukkan nasi aduk-aduk kemudian tambahkan lada dan garam, aduk kembali. Terakhir masukkan irisan daun bawang. Masak sekitar 2 menit, cicipi jika kurang boleh di tambah garam.\", \"Angkat dan sajikan bersama acar dan kerupuk atau tambah telur.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(835, 4, 'Gulai kambing tanpa santan', 'Sajian kambing spesial: Gulai kambing tanpa santan yang menggugah selera.', '[\"200 gr tetelan kambing\", \"Bumbu halus :\", \"4 siung bawang merah\", \"3 siung bawang putih\", \"1/2 ruas kunyit\", \"4 butir kemiri\", \"Bumbu yang langsung dimasukkan\", \"1/2 ruas jahe digeprek\", \"1 ruas lengkuas digeprek\", \"1 batang sereh digeprek\", \"2 lembar daun salam\", \"2 lembar daun jeruk\", \"1/4 sendok ketumbar\", \"1/2 sendok merica\", \"sesuai selera Garam, Gula, penyedap rasa\", \"1/4 sendok pala\"]', '[\"Tumis bumbu halus hingga harum atau kuning keemasan, lalu tambahkan air\", \"Masukkan tetelan kambing. Kemudian masukkan semua bumbu seperti jahe, laos, daun salam, daun jeruk, merica, ketumbar, pala, gula, garam, dan penyedang\", \"Pastikan tetelan kambing terendam air. Masak dengan api besar. Setelah air susut tinggal separuh, masak dengan api sedang....\", \"Kemudian cek rasa, gulaipun siap dihidangkan... dijamin g enek.... mantaaap deh\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(836, 4, 'Garang asam kambing', 'Buat Garang asam kambing yang nikmat dengan langkah-langkah mudah ini.', '[\"1/2 kg daging kambing\", \"7 buah cabe rawit merah\", \"1 buah tomat potong kotak\", \"1 sdt asem jawa + 3 sdm air\", \"1 lt air untuk merebus daging\", \"2 lembar daun salam\", \"1 batang sereh geprek\", \"1 sdt garam\", \"1 sdt gula pasir\", \"1/2 sdt kaldu bubuk (sy rasa sapi)\", \"Secukupnya minyak goreng untuk menumis\", \"Secukupnya air sisa rebusan daging\", \"Bumbu yg dibakar:\", \"8 siung bawang merah\", \"3 siung bawang putih\", \"1 ruas kunyit\", \"1 ruas jahe\", \"Sejempol lengkuas\"]', '[\"Potong2 daging sesuai selera lalu rebus smp empuk sisihkan\", \"Iris2 bumbu yg sdh dibakar td lalu tumis smp harum masukan daun salam dan sereh\", \"Masukan daging aduk Tambahkan air sisa rebusan daging air dan air asem jawa\", \"Masukan cabe rawit merah tomat,Tambahkan garam gula pasir dan kaldu bubuk aduk tes rasa\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(837, 4, 'Kare Kambing Simpel Mudah', 'Buat Kare Kambing Simpel Mudah yang nikmat dengan langkah-langkah mudah ini.', '[\"2 kg Daging Kambing Campur dengan jerohan jg\", \"Bumbu\", \"Secukupnya air mendidih sampai daging terendam\", \"8 siung bawang putih geprek\", \"3 buah cabe merah gunting serong\", \"4 cm kencur geprek\", \"4 cm kunyit geprek\", \"1 sdt jinten\", \"6 bh cengkeh\", \"1 sdt ketumbar bubuk\", \"3 lbr daun jeruk robek\", \"3 lbr daun salam\", \"2 bh serai geprek\", \"2 bks santan kara kecil\", \"1 bks kecil bumbu kare BMN (jika ada pakai bubuk kare sj)\", \"Secukupnya garam\", \"Secukupnya gula\", \"Alat\", \"Magic Com\", \"Pelengkap\", \"Bawang Goreng\", \"Sambal Terasi\"]', '[\"Siapkan magic com bersih. Potong daging sesuai selera (daging tdk perlu dicuci)\", \"Masukkan air mendidih (krn membuat makanan lebih awet tidak cepat basi) sampai daging seluruhnya terendam. Nyalakan magic com. Tunggu sampai kira kira 30menit.\", \"Masukkan semua bumbu.\", \"Hirup bau bumbu yg menggugah selera. Sesekali intip bumbu sudah matang atau belum. Daging akan sangat empuk nantinya. Sesekali aduk.\", \"Setelah matang. Sajikan dgn taburan bawang goreng, sambal terasi dan nasi hangat yg dipisah tempatnya.\", \"Selamat Menikmati. ☺\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(838, 3, 'Sop Kambing Sayuran #KitaBerbagi', 'Cara membuat Sop Kambing Sayuran #KitaBerbagi yang enak dan praktis untuk keluarga.', '[\"500 gram daging + tulang kambing\", \"secukupnya kol\", \"secukupnya wortel\", \"secukupnya brokoli\", \"secukupnya jagung manis\", \"secuil kapulaga\", \"1 buah bunga lawang\", \"1 ruas jari kelingking kayu manis\", \"secukupnya garam\", \"secukupnya gula pasir\", \"2 batang seledri\", \"1 batang daun bawang\", \"secukupnya bawang merah goreng\", \"Bumbu halus :\", \"5 siung bawang putih\", \"3 buah kemiri\"]', '[\"Potong - potong daging kambing dan babat sesuai selera, rebus hingga mendidih. Buang air didihan pertama untuk menghilangkan bau apek kambing.\", \"Masak kembali daging dan tulang kambing. Masukkan irisan wortel dan jagung manis. Masak ± 30 menit.\", \"Tumis bumbu halus hingga matang.\", \"Kalau memasak di kompor 2 tungku, tungku 1 bisa untuk merebus daging, tungku satunya untuk menumis bumbu halus.\", \"Setelah bumbu masak, masukkan ke dalan rebusan daging. Masukkan kayu manis, kapulaga dan bunga lawang. Masak ± 10 menit.\", \"Masukkan kol, daun bawang. Masak ± 10 menit.\", \"Masukkan brokoli, galua pasir dan garam. Masak ±5 menit.\", \"Angkat dan sajikan dengan taburan seledri dan bawang merah goreng. Sajikan dengan sambal kecap.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(839, 2, 'Kepala kambing Bumbu Merica#kitaberbagi', 'Sajian kambing spesial: Kepala kambing Bumbu Merica#kitaberbagi yang menggugah selera.', '[\"1 kepala kambing\", \"5 siung bawang putih\", \"2 sdm merica utuh\", \"10 buah cabe hijau\", \"Secukupnya Garam\", \"1 keping gula merah kira kira 1/2 ons\", \"Secukupnya daun jeruk, salam, jahe, lengkuas. Serei\", \"Secukupnya Garam\", \"1 buah tomat besar\", \"1 sachet Kaldu sapi bubuk\", \"secukupnya Kecap\"]', '[\"Rebus kepala kambing sampai empuk.. PoTong sesuai selera\", \"Haluskan bawang putih merica dan garam... Tumis dengan sedikit minyak sampai harum\", \"Masukkan potongan daging kepala kambing dan cabe iris.. Aduk rata... Masukkan gula merah jahe daun salam daun jeruk lengkuas serei... Aduk rata\", \"Tambahkan air... Setelah bumbu meresap.. Tambahkan kaldu bubuk dan Kecap...masukkan Potongan toMat....Cek rasa\", \"Sajikan dengan taburan daun bawang dan bawang goreng\", \"😋😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(840, 4, 'Tengkleng tulang kambing', 'Cara membuat Tengkleng tulang kambing yang enak dan praktis untuk keluarga.', '[\"1 kg tulang kambing\", \"500 ml santan\", \"1000 ml air\", \"Secukupnya garam\", \"Secukupnya gula jawa\", \"Secukupnya penyedap\", \"\\\"Bumbu\\\"\", \"2 lembar daun salam\", \"2 cm laos\", \"1 lembar daun jeruk\", \"1 batang serai\", \"2 ruas jahe\", \"2 ruas kunyit\", \"4 ruas jari, kayu manis\", \"4 butir cengkeh\", \"10 buah cabe utuh\", \"☘bumbu halus☘\", \"5 bawang merah\", \"4 bawang putih\", \"3 butir kemiri\", \"1 sdt ketumbar\", \"Merica bubuk\"]', '[\"Presto tulangan kambing,\", \"Sambil menunggu tulang yang di presto, giling bumbu halus. Lalu tumis bumbu halus sampai harum, masukkan bumbu yg tidak digiling.\", \"Setelah tulang empuk, buang air sisa presto, masukkan bumbu yg sudah ditumis, air dan santan, cek rasa, tunggu sampe meresap dan air agak menyusut.\", \"Angkat, dan sajikan hangat. 😄\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(841, 4, 'Sop kambing Idul Adha 😁', 'Nikmati kelezatan Sop kambing Idul Adha 😁 dengan resep sederhana ini.', '[\"15-20 siung bawang putih (ukuran sedang)\", \"500 gr daging dan tulang kambing\", \"1 sdm merica butir\", \"3-5 cm jahe (sesuai selera)\", \"10 butir cengkeh\", \"5 cm kayu manis\", \"1 butir pala\", \"Secukupnya Bunga lawang\", \"2-3 L air\", \"4 buah wortel\", \"4 buah kentang\", \"2 buah tomat\", \"1 batang Seledri dan bawang daun\", \"Secukupnya Garam, gula, penyedap rasa\", \"Secukupnya Bawang goreng\"]', '[\"Pertama, daging dipotong2 sesuai selera kemudian cuci daging dan tulangan kambing dengan cara masukan ke dalam air mendidih yg sudah diberi cengkeh dan kayumanis agar daging tidak bau. Rebus sekitar 1-2 menit lalu angkat.\", \"Haluskan : bawang putih, merica, jahe. Tumis sebentar bumbu halus sampai harum\", \"(Saya menggunakan presto agak daging cepat empuk). Masukkan air dan bumbu halus yg sudah di tumis serta daging kemudian di presto kurang lebih 30 menit.\", \"Setelah daging di presto, masukkan kentang, wortel, kayu manis, cengkeh dan bunga lawang. Masak hingga sayur empuk\", \"Masukkan garam, gula dan penyedap rasa\", \"Tambahkan seledri, daun bawang dan tomat\", \"Angkat dan sajikan bersama bawang goreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(842, 3, 'Tongseng Kambing #KitaBerbagi', 'Nikmati kelezatan Tongseng Kambing #KitaBerbagi dengan resep sederhana ini.', '[\"250 gr Daging Kambing (boleh campur tulang/iga)\", \"2 lembar daun salam\", \"1/2 ruas jahe (keprek)\", \"air masak utk merebus dan menambah kuah (takarannya dikira2 aja)\", \"2 sdm minyak untuk menumis\", \"4 sdm Santan kental\", \"1 sdm gula pasir\", \"1 sdm garam halus\", \"merica bubuk\", \"Bumbu Halus:\", \"6 siung bawang merah\", \"3 siung bawang putih\", \"1 bh kemiri\", \"1/2 ruas jahe\", \"1 cm kunyit\", \"1 sdt garam\", \"1 sdt gula\", \"secukupnya merica bubuk\", \"secukupnya ketumbar bubuk\", \"3 sdm kecap manis\", \"Bumbu Kasar:\", \"1 btg sereh\", \"2 lmbr daun salam\", \"2 lmbr daun jeruk\", \"1 cm lengkuas (keprek)\", \"sesuai selera cabe rawit dan cabe hijau rajang miring2,\"]', '[\"Rebus/ungkep daging kambing dgn air, daun salam dan jahe. tutup, masak hingga empuk. tiriskan. potong2 sesuai selera.\", \"Tumis bumbu yg sudah dihaluskan, masukan bumbu kasar, tumis hingga wangi, masukan daging kambing yg sudah diungkep, tmbh air, santan, garam,gula,merica dan ketumbar bubuk.aduk terus (spy tdk pecah santan) hingga mendidih,kecilkan api. masukan kecap. tambahkan kol dan tomat, aduk dan koreksi rasa.\", \"Sajikan dengan taburan bawang goreng. selamat mencoba.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(843, 3, 'Semur daging kambing', 'Semur daging kambing dengan daging kambing empuk tanpa bau prengus.', '[\"500 gram daging kambing, potong agak tebal kira-kira 1,5 cm\", \"5 siung bawang putih\", \"8 siung bawang merah\", \"1 sdt lada hitam, sangrai (selera)\", \"2 butir cengkeh, sangrai (selera)\", \"1/2 ruas jari jahe\", \"1 sdt ketumbar, sangrai\", \"10 sdm kecap manis (saya pakai kecap Bango)\", \"1 tangkai serai, memarkan\", \"2 lembar daun salam\", \"secukupnya kaldu sapi (royco)\", \"secukupnya garam\", \"secukupnya minyak untuk menumis\", \"secukupnya bawang merah goreng untuk taburan\"]', '[\"Membuat bumbu halus : haluskan 5 siung bawang merah, 8 siung bawang putih, 1 sdt lada hitam sangrai, 2 butir cengkeh sangrai, 1/2 ruas jari jahe, 1 sdt ketumbar sangrai, dan garam.\", \"Tumis bumbu halus bersama serai dan daun salam hingga harum kemudian masukkan daging, tumis hingga berubah warna dan tidak berair (kesat).\", \"Tambahkan air, kecap dan kaldu sapi secukupnya. aduk rata dan masak hingga daging lunak dengan api sedang.\", \"Ter rasa dan kematangan daging. menu siap disajikan.\", \"Sajikan semur daging kambing dengan ditaburi bawang merah goreng. semoga suka\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(844, 4, 'Soto Balungan Sapi n Kambing Empuk by: Erni Hartanti.Amd😘😍😄', 'Resep Soto Balungan Sapi n Kambing Empuk by: Erni Hartanti.Amd😘😍😄 yang lezat dan mudah dibuat di rumah.', '[\"Secukupnya Balungan Sapi\", \"Secukupnya Balungan Kambing\", \"Secukupnya Babat Kambing empuk\", \"Secukupnya Air\", \"Sedikit garam\", \"2 sdt Gula pasir\", \"1 bks (20 gram) Bumbu Soto Ayam Sajiku\"]', '[\"Bumbu soto saya pakai ini\", \"Masak semua bahan sampai matang test rasa..pas angkat sajikan\", \"Selamat makan siang:-)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(845, 4, 'Oseng kambing ala anak kos', 'Resep Oseng kambing ala anak kos ala rumahan yang dijamin menggugah selera.', '[\"Daging kambing\", \"Garam\", \"Ketumbar\", \"Lada bubuk\", \"Cabe\", \"Bawang merah\", \"Bawang putih\", \"Bawang bombay\", \"Daun bawang\", \"Kecap\"]', '[\"Iris daging yang sudah direbus sesuai selera\", \"Haluskan bawang merah, putih, cabe dan ketumbar(sesuai selera)\", \"Cincang sesuai selera bawang bombay dan daun bawang\", \"Panaskan minyak, goreng bumbu yang sudah dihaluskan\", \"Masukkan daging dan cincangan daun bawang, bombay\", \"Tunggu sampe wangi\", \"Tambah sedikit air, kecap, lada, garam\", \"Testing dulu rasanya sebelum disajika\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(846, 3, 'Gule kambing #kitaberbagi', 'Sajian kambing spesial: Gule kambing #kitaberbagi yang menggugah selera.', '[\"500 gr daging kambing, tulang-tulang\", \"2 lembar daun salam\", \"4 lembar daun jeruk\", \"5 cm kayu manis\", \"2 batang batang sereh, digeprek\", \"secukupnya Air\", \"Minyak goreng untuk menumis\", \"Cabe rawit merah, kalo mau pedes (optional)\", \"secukupnya Gula garam\", \"Penyedap rasa (optional)\", \"200 ml santan kental (saya pake sun kara yg kecil @65ml 2bks)\", \"Bumbu halus :\", \"10 siung bawang merah\", \"5 siung bawang putih\", \"2 ruas kunyit\", \"2 ruas jahe\", \"5 butir kemiri\", \"1 butir biji pala\", \"1 sdt lada bubuk\", \"1 sdm ketumbar bubuk\", \"6 buah cabe merah keriting\", \"Pelengkap :\", \"Acar timun\", \"Bawang merah goreng\"]', '[\"Cuci daging kambing dkk. Rebus sebentar. Mendidih, angkat cuci bersih buang airnya.\", \"Rebus air sampai mendidih, masukkan daging rebus tadi, bersama daun salam, daun jeruk, kayu manis. Rebus sampai mendidih lagi.\", \"Tumis batang sereh hingga harum, masukkan bumbu yang sudah dihaluskan tadi, masak sampai matang dan harum, tambahkan sedikit air rebusan daging. Masak lagi sampai mendidih.\", \"Tuang bumbu yang sudah ditumis tadi kedalam panci rebusan daging, aduk rata, masukkan gulgar, penyedap rasa, tes rasa, aduk lagi. Biarkan sampai mendidih dan daging menjadi empuk. Masukkan cabe rawit jika ingin rasa lebih pedas.\", \"Setelah daging empuk dan mendidih, masukkan santan kental, aduk sebentar biarkan mendidih lagi.\", \"Matikan kompor siap dihidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(847, 3, 'Oseng kacang panjang daging kambing', 'Resep praktis Oseng kacang panjang daging kambing yang bisa dicoba di rumah.', '[\"200 gr daging kambing\", \"1 ikat kacang panjang\", \"secukupnya Tempe\", \"3 siuang bawang merah\", \"3 siung bawang putih\", \"1 ruas jari lengkuas\", \"1 lembar daun salam\", \"1 buah tomat hijau\", \"Lada\", \"secukupnya Kecap\", \"secukupnya Gula jawa\", \"1 sdm Garam\", \"Nanas untuk mengempukkan daging\"]', '[\"Siapkan daging kambing, potong kecil-kecil, siapkan nanas potong 1/4nya aja, kemudian parut & campurkan ke daging, tunggu 10-15 menit\", \"Potong-potong kacang panjang & cuci,\", \"Potong-potong tempe dengan ukuran kecil\", \"Siapkan bumbu, bawang merah, bawang putih diiris tipis2, kemudian tumis dengan minyak goreng hingga harum\", \"Masukkan lengkuas yg sudah di geprek, potongan tomat hijau dan daun salam\", \"Masukkan daging yg direndam dalam nanas, tambahkan sedikit air & tunggu smpai daging mulai matang & empuk\", \"Masukkan tempe, tunggu hingga agak matang kemudian masukkan kacang panjang, tambahkan kecap, gula jawa & garam, (tambahkan air jika diperlukan)\", \"Matikan kompor, oseng kambing, tempe kacang panjang siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(848, 3, 'Krengseng cabe²an kepala kambing', 'Sajian Krengseng cabe²an kepala kambing yang praktis dan lezat untuk dinikmati bersama.', '[\"1/2 kg tetelan kepala kambing, cuci bersih\", \"Bumbu halus\", \"7 siung Bawang putih\", \"5 siung Bawang merah\", \"Bumbu pelengkap\", \"1 ruas Lengkuas, memarkan\", \"1 ruas Jahe, memarkan\", \"1 batang Serai, memarkan\", \"20 biji Cabe rawit, potong serong\", \"8 biji Cabe merah & Cabe hijau besar, potong serong\", \"3 helai daun salam\", \"3 helai daun jeruk\", \"Secukupnya Ale (bisa di ganti petai)\", \"Secukupnya kecap manis\", \"Secukupnya garam\"]', '[\"Cuci bersih kulit kambing yg sdh di rebus, lalu potong sesuai selera ya\", \"Tumis semua bumbu.\", \"Masukkan kulit kepala kambing, aduk sebentar. Tambahkan air, garam dan kecap manis secukupnya.\", \"Test rasa. Taburi bawang goreng....\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(849, 2, 'Sop Daging Kambing Kuah Bening #kitaberbagi', 'Resep Sop Daging Kambing Kuah Bening #kitaberbagi yang lezat dan mudah dibuat di rumah.', '[\"200 gr daging kambing dan tulang kambing\", \"bumbu halus :\", \"5 siung bawang putih\", \"10 siung bawang merah\", \"1/2 sdt lada\", \"1/2 butir biji pala\", \"rempah-rempah :\", \"2 butir kapulaga\", \"1 buah kayu manis\", \"2 butir cengkeh\", \"2 butir kembang lawang\", \"1 buah lemon\", \"2 kotak kaldu sapi maggi\", \"1 ruas jahe geprek\", \"potong besar daun bawang di\", \"potong dadu tomat di\", \"garam\", \"gula\", \"bawang goreng\", \"emping\"]', '[\"Lumuri daging dan tulang dengan air lemon, diamkan selama 2 jam.\", \"Cuci bersih daging dan tulang, rebus hingga mendidih dan kotoran terangkat. Buang air rebusan, cuci kembali daging lalu rebus kembali dengan 500ml air dengan api sedang sampai mendidih kemudian tambahkan rempah-rempah.\", \"Tumis bumbu halus dan jahe hingga harum kemudian masukan dalam rebusan daging. Masak hingga daging empuk.\", \"Tambahkan daun bawang, rebus sebentar kemudian angkat.\", \"Sajikan sop daging kambing dengan taburan bawang goreng, emping melinjo, dan irisan tomat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(850, 2, 'Sate Kambing Simpel', 'Resep Sate Kambing Simpel yang lezat dan mudah dibuat di rumah.', '[\"1 kg Daging Kambing (potong dadu)\", \"4 siung bawang putih\", \"1 sdm ketumbar\", \"2 sachet kecap Ba*go uk kecil\", \"secukupnya garam\", \"secukupnya lada bubuk (taburan)\"]', '[\"Daging kambing yg sudah dipotong, tata di tusukan sate.\", \"Ulek bawang putih, ketumbar dan garam sampai halus. Tambahkan kecap, aduk rata.\", \"Rendam daging kambing yg sudah ditusuk sate dengan bumbu kecap tadi. Diamkan.\", \"Siapkan arang untuk membakar sate. Buat bara apinya.\", \"Bakar sate, bolak balik agar tidak gosong. Gulingkan sate ke bumbu kecap. Ulangi smpai 3x. Angkat dr bakaran, sajikan dgn pelengkap 😉\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(851, 3, 'Nasi goreng kambing #KitaBerbagi', 'Resep praktis Nasi goreng kambing #KitaBerbagi yang bisa dicoba di rumah.', '[\"5 tusuk sate kambing / bs pk daging kambing segar\", \"Sepiring penuh nasi putih\", \"Haluskan :\", \"3 bh cabai merah\", \"5 bh cabai rawit\", \"3 siung bawang merah\", \"3 siung bawang putih\", \"1 bh kemiri\", \"5 cm kunyit\", \"1/4 sdt lada halus\", \"1 btg serai di potong2\", \"secukupnya Garam\", \"1 sdt kaldu bubuk\", \"secukupnya Kecap manis\", \"2 sdm margarin utk menumis\"]', '[\"Ini bahan2nya\", \"Panaskan margarin lalu tumis bumbu halus sampai harum dan berminyak lalu beri serai.. aduk sampai bumbu matang\", \"Masukan sate kambing dan nasi putih, beri bumbu.. aduk2 sampai rata.. koreksi rasa dulu baru matikan api..\", \"Hidangkan nasgor kambing dgn irisan tomat dan mentimun plus krupuk..\", \"Ini krupuknya hasil rikuk dr cookpad dapurvy.. enaak\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(852, 3, 'Sate kambing sambel kecap', 'Nikmati kelezatan Sate kambing sambel kecap dengan resep sederhana ini.', '[\"2 kg daging kambing\", \"1 buah jeruk nipis\", \"Tusukan sate\", \"Bumbu oles :\", \"Kecap manis bango\", \"secukupnya Minyak\", \"Bumbu sambel :\", \"8 siung bawang merah\", \"10 buah cabe rawit\", \"2 buah tomat\", \"Secukupnya kecap\"]', '[\"Potong2 daging kambing lalu tusuk2 jadi sate (jangan di cuci dagingnya) lumuri jeruk nipis saja\", \"Lumuri daging kambing yang sudah di tusuk2. Bakar daging di bara yang menyala\", \"Untuk sambal kecap, iris semua bahan lalu campuri kecap\", \"Siap di hidangkan bersama keluarga\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(853, 2, 'Nasgor kambing #kitaBerbagi', 'Nasgor kambing #kitaBerbagi dengan daging kambing empuk tanpa bau prengus.', '[\"5 porsi nasi putih\", \"100 gr potongan kambing\", \"1 sdt jinten\", \"1 sdt bumbu gule\", \"Bumbu halus:\", \"1 siung bawang putih\", \"5 biji bawang merah\", \"3 bji cabe merah\", \"2 buah tomat\", \"1 sdt trasi\", \"Secukupx garam\"]', '[\"Goreng kambing yg suda d potong dan di lumuri garam.. Tunggu smpai matang\", \"Tumis bumbu yg sudah d haluskan td... Smpai harum tmbh kecap, bumbu gule,jinten,lalu campur nasi dan kambing td...\", \"Siap d sajikan dgn acar dan kripik emping... Krna saya dadakan jd g pke hahaha.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(854, 4, 'Gule kambing#kitaberbagi', 'Cara membuat Gule kambing#kitaberbagi yang enak dan praktis untuk keluarga.', '[\"1/2 kg daging kambing\", \"2 bgks bumbu instan gule\", \"Secukupnya bawang merah goreng\", \"Secukupnya bawang putih goreng\", \"3 batang daun kucai/2 pre\", \"Secukupnya gula&garam\"]', '[\"Potong daging kecil2. Didihkan air.Rebus daging smp empuk.\", \"Goreng bumbu brsama dgn daging smp harum. Tambahkan kuah kaldu sdikit aja,biarkan mendidih & bumbu meresap\", \"Tuang daging kdlm panci rebusan daging\", \"Tunggu smp mendidih. Masukkan daun kucai. Sy lg ga ada,gnti daun pre\", \"Tes rasaaa\", \"Mariii,taburi bawang goreng makin muantep. Suwun mbak yu Azizah paringan bumbu gulenipun,mantabs👌👍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(855, 2, 'Kambing Bumbu Lapis (#KitaBerbagi)', 'Kambing Bumbu Lapis (#KitaBerbagi) - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 kg Daging kambing\", \"Bumbu :\", \"8 bawang merah\", \"3 bawang putih\", \"2 cabe merah besar\", \"2 cabe rawit (optional bisa dtmbah jika ingin pedas)\", \"4 butir kemiri\", \"1 sdm ketumbar\", \"2 lembar daun salam\", \"2 lembar daun jeruk\", \"2 cm /Seiris engkuas geprek (dikira-kira aja ya😉)\", \"2 cm/Seiris jahe geprek\", \"2 bungkus Santan instan (saya paake rosebrand/kara jg bisa)\", \"10 sdm Kecap\", \"1 sdt merica bubuk\", \"5 sdm gula merah (gula merah di iris\\\", sebnyak 5 sdm)\", \"3 gelas/secukupnya Air\", \"secukupnya Garam\"]', '[\"Karena daging yg saya punya abis keluar dari frezee dan agak beku, jadi saya rebus sebentar skitar 5 menit. Lalu tiriskan. Dan iris\\\".(Tahap ini bisa diskip, ga usah direbus jg gpp\\\",di iris\\\".langsung ke step 2)\", \"Blender bawang merah, bawang putih, cabe,kemiri,ketumbar dengan sedikir air biar mudah saat diblender.\", \"Tumis bumbu yg sudah diblender dengan sedikit minyak goreng.\", \"Masukkan daun salam, daun jeruk, lengkuas, jahe. Tumis hingga harum.\", \"Lalu masukkan irisan gula merah dan garam, merica bubuk,aduk aduk sampai gula larut.\", \"Masukkan daging kambing, santan,air 3 gelas(secukupnya), kecap manis, Aduk aduk.tes rasa,biarkan mendidih sampai daging empuk dan bumhu meresap.\", \"Masak dengan api sedang sampai air surut.\", \"Saat ngetik resep ini, masakan saya masih dalam proses biar meresap. Karna buru-buru pengen ikutan event #KitaBerbagi biar targetnya full bisa 1000 tusuk😂karna ini hari terakhir dan udah malem,jg masaknya. Jadi maklum ya..fotonya seadanya.\", \"Tapi dijamin ini endessss banget..suka banget sama jenis masakan ini😋😋👍👍👍👌 lazizzzz.. selamat mencobaa.\", \"Taraa...ini foto yg sudah meresap..\", \"Masih ada kuahnya. Tapi sudah meresap jadi agak kental.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(856, 2, 'Daging kambing kecap pedas #kitaberbagi', 'Nikmati kelezatan Daging kambing kecap pedas #kitaberbagi dengan resep sederhana ini.', '[\"1/4 gr daging kambing\", \"bumbu:\", \"5 buah bawang merah\", \"4 buah bawang putih\", \"5 butir kemiri\", \"1/2 sdt ketumbar\", \"7 buah cabe kecil\", \"1 buah cabe merah besar\", \"jahe\", \"kunyit\", \"merica bubuk\", \"garam\", \"gula\", \"penyedap\"]', '[\"Rebus air sampai mendidih, masukkan daging kambing yg telah dipotong2 tambahkan jahe dan bawang putih geprek\", \"Rebus daging sampai empuk\", \"Haluskan bumbu kemudian tumis dg minyak\", \"Masukkan daging kambing yg sudah empuk\", \"Tambahkan air dan tunggu bumbu sampai meresap\", \"Tes rasa\", \"Daging kambing kecap pedas siap dinikmati\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(857, 2, 'Sate kambing bumbu kacang #kitaberbagi', 'Resep praktis Sate kambing bumbu kacang #kitaberbagi yang bisa dicoba di rumah.', '[\"1 kg  daging kambing\", \"1 buah jeruk nipis\", \"1 sdt garam\", \"Olesan atau celupan\", \"5 siung bawang putih\", \"5 buah kemiri\", \"1 sdt ketumbar\", \"50 ml kecap manis\", \"Saus kacang\", \"Sesuai selera cabe rawit\", \"2 siung bawang putih\", \"4 siung bawang merah\", \"2 genggam kacang tanah kupas goreng\", \"Secukupnya garam dan gula\", \"Pelengkap\", \"Secukupnya bawang merah iris tipis\", \"Secukupnya tauge kacang hijau\"]', '[\"Cuci daging lalu potong dadu, rendam dengan perasan jeruk nipis dan garam,, diamkan 30mnt\", \"Tusuk daging, lalu haluskan dan campur bahan celupan dan olesan.\", \"Siapkan bakaran dan celupkan daging ke bahan celupan, bakar daging dan setelah daging setengah matang olesi dgn bumbu olesan lagi. Lalu bakar lagi\", \"Haluskan dan campur bahan saus,,\", \"Tata sate di piring lalu tuangi dengan saus, taburi bawang merah dan tauge.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(858, 2, 'SOP KAKI KAMBING #KuahSusu', 'SOP KAKI KAMBING #KuahSusu dengan daging kambing empuk tanpa bau prengus.', '[\"500 gr Jerohan Kambing\", \"secukupnya Tulang kambing\", \"2 Liter air\", \"600 ml Susu full cream (aq susu ultra full cream)\", \"Bahan Dihaluskan:\", \"10 Siung bawang merah\", \"10 Siung bawang putih\", \"1 Sendok teh merica\", \"Bahan Lain:\", \"2 cm Jahe digeprek\", \"3 Lembar daun salam\", \"5 Tangkai cengkeh\", \"5 Biji kapulaga\", \"Kayu manis bubuk\", \"Pala bubuk\", \"Loncang (iris jgn terlalu halus)\", \"Seledri 3 batang (buat ikat simpul)\", \"Garam\", \"Gula pasir\", \"Minyak samin\", \"Bahan Pelengkap:\", \"Bawang goreng\", \"Emping\", \"Tomat (potong kecil)\", \"Acar\", \"Sambal bawang\", \"Kecap\"]', '[\"Didihkan 2 liter air bersama jahe dan daun salam\", \"Setelah mendidih masukan simpul seledri, jerohan dan tulang kambing. Masak sampai empuk. Kalau mau cepat empuk ditutup panci nya. Setelah empuk, amgkat jerohan dan tulang, sisihkan di tempat tersendiri.\", \"Tumis bahan yg dihaluskan bersama cengkeh dan kapulaga.\", \"Masukan bahan tumisan ke panci.\", \"Tambahkan kayu manis, pala, gula pasir dan garam.\", \"Masukkan loncang, masak hingga loncang layu.\", \"Masukkan susu, didihkan sebentar lagi. Taburi bawang goreng. Mateng dhe...\", \"Penyajiannya, tata jerohan dan tulang secukupnya di mangkok. Siram dengan kuah. Beri kira2 satu sendok teh minyak Samin. Tambahkan emping, potongan tomat, acar, sambal dan kecap sesuai selera.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(859, 4, 'Tongseng Kambing Dadakan #kitaberbagi', 'Buat Tongseng Kambing Dadakan #kitaberbagi yang nikmat dengan langkah-langkah mudah ini.', '[\"500 gram daging kambing + Tulang\", \"3 lembar daun salam\", \"5 lembar daun jeruk\", \"bumbu halus :\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"1 ruas jahe\", \"1 ruas kunyit\", \"2 butir kemiri sangrai\", \"1 sdt ketumbar sangrai\", \"1 sdt merica\", \"2 sdt kaldu bubuk\", \"secukupnya garam\", \"750 ml- 1 liter air (tergantung selera)\", \"65 ml santan kental kemasan (1 bks santan kemasan)\", \"2 sdm kecap manis\", \"1 batang sereh\", \"2 lembar daun salam\", \"2 lembar daun jeruk, sobek\\\"\", \"10 buah cabe rawit merah utuh\", \"5 buah cabe rawit ijo\", \"pelengkap :\", \"1/2 buah kol, potong\\\"\", \"2 batang daun bawang, iris tipis\", \"1/2 buah tomat, potong\\\"\"]', '[\"Didihkan air secukupnya, lalu rebus daging kambing + tulang bersama dengan daun jeruk, daun salam, dan sedikit garam.. rebus hingga daging empuk dan matang kurang lebih 30-45 menit.. angkat lalu potong\\\" sesuai selera\", \"Selanjutnya, panaskan minyak goreng secukupnya, kemudian tumis bumbu halus, daun jeruk, daun salam, dan sereh hingga harum dan matang, setelah itu masukan potongan daging kambing, aduk hingga rata..\", \"Selanjutnya tambahkan air dan cabe rawit, masak hingga mendidih.. setelah mendidih, masukan santan kental, tambahkan garam, kaldu bubuk, dan kecap manis aduk rata.. masak kembali hingga bumbu meresap\", \"Setelah bumbu meresap, cek rasa.. jika sudah pas, masukan kol, daun bawang, dan tomat, aduk rata.. masak sebentar, matikan api, angkat dan sajikan hangat dengan nasi putih 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(860, 4, 'Tongseng kambing(no bau)', 'Tongseng kambing(no bau) dengan daging kambing empuk tanpa bau prengus.', '[\"500 gr daging kambing\", \"5 lbr daun salam\", \"secukupnya air untuk merebus daging\", \"Bumbu Halus :\", \"2 cm kunyit\", \"2 cm jahe\", \"1 sdt ketumbar\", \"1 sdt lada\", \"3 siung bawang merah\", \"4 siung bawang putih\", \"3 bh kemiri\", \"3 cm lengkuas (di geprek saja)\", \"2 btg sereh (di geprek)\", \"2 lbr daun salam\", \"Pelengkap :\", \"Kol secukupnya (sesuai selera)\", \"2 bh tomat\", \"5 bh cabai rawit (iris sesuai selera)\", \"secukupnya daun bawang\", \"1 bks kara uk kecil\", \"3-4 sdm kecap manis\", \"secukupnya garam\", \"gula secukupnya (sy tdk pakai MSG,hny mnambahkan gula sdkt)\"]', '[\"Rebus daging bersama daun salam sekitar 1 jam,hingga dirasa sdh ckup empuk,angkat lalu potong2 sesuai selera\", \"Tumis bumbu halus,masukan lengkuas,daun salam,sereh..tumis hingga harum\", \"Masukan santan kara kedalam tumisan tadi,lalu masukan daging yg sudah dipotong,dan masukkan kecap,tambahkan air secukupnya\", \"Tambahkan garam,gula,lalu masukan kol,tomat,irisan cabai rawit dan daun bawang\", \"Koreksi rasa dan masak hingga matang\", \"Tongseng kambing siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(861, 4, 'Daging kambing nyusss 😊', 'Buat Daging kambing nyusss 😊 yang nikmat dengan langkah-langkah mudah ini.', '[\"Daging kambing\", \"Bawang putih\", \"Bawang merah\", \"Merica\", \"Ketumbar\", \"Garam\", \"Jeruk nipis\", \"Kecap\"]', '[\"Bumbu yg dihaluskan bawang merah bawang putih garam ketumbar merica bila sudah tambahkan air dan kecap sesuai selera\", \"Sebelumnya daging kambing di iris sesuai selera lalu kasih perasan air jeruk nipis untuk menghilangkan bau daging kambing\", \"Tusuk tusuk daging kambing yg suda di iris\", \"Lalu masukan kedalam bumbu yg suda dihaluskan tadi\", \"Siap dibakar 😊\", \"Saat dibakar bisa dicelupkan lg kedalam air bumbu tadi yaa biar lebih ngresep bumbunya\", \"Selamat mencoba 💐😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(862, 4, 'Olahan daging kambing dapur rahma', 'Sajian kambing spesial: Olahan daging kambing dapur rahma yang menggugah selera.', '[\"potong dadu Daging kambing di\", \"3 lembar Daun pepaya di remas\", \"Kecap\", \"Bumbu halus:\", \"4 btr Miri\", \"10 biji Bawang merah\", \"5 biji Bawang putih\", \"1 sdm Tumbar\", \"1 sdt Garam\", \"1/2 bks Masako\", \"1 sdt Gula merah\", \"1 bks Ladaku\", \"secukupnya Lengkuas\", \"Air asam jawa\", \"Bahan sambal:\", \"Cabe rawit dirajang(resep asli pakai cabai hijau besar)\", \"1 sdm Cuka\", \"2 buah tomat potong dadu kecil\", \"Irisan bawang merah(resep asli gk pakai)\", \"Kecap\"]', '[\"Remas daun pepaya, untuk membungkus potongan daging. Diamkan 30 menit(biar daging empuk)\", \"Setelah 30mnt masukkan bumbu halus beserta kecap diamkan 30menit(resep asli 15mnt)\", \"Tusuk dg tusuk sate\", \"Panggang di atas pemanggang(saya pakai pemanggang teflon yg sudah di olesi minyak)\", \"Membuat sambal, campurkan semua bahan sambal aduk2\", \"Copot sate dari tusukanya(gak juga gpp). Siram dg sambal\", \"Selamat mencoba......\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(863, 4, 'Sate kambing empuk #KitaBerbagi', 'Resep Sate kambing empuk #KitaBerbagi yang lezat dan mudah dibuat di rumah.', '[\"350 gr daging kambing (potong\\\")\", \"5 siung bawang merah\", \"2 siung bawang putih\", \"1 butir kemiri\", \"1/2 sdt lada bubuk\", \"1/2 sdt ketumbar\", \"1 cm jahe\", \"garam\", \"daun pepaya\", \"secukupnya margarin  dicairkan+ kecap utk olesan daging\", \"sambal kecap:\", \"15 buah cabe merah\", \"8 siung bawang merah\", \"5 buah tomat\", \"secukupnya kecap\"]', '[\"Siapkan daging pd tusukan sate,sisihkan.\", \"Haluskan bumbu,lumuri sate dgn bumbu,bungkus daun pepaya,diamkan selama 1 jam. Supaya bumbu meresap dan empuk.\", \"Siapkan margarin cair + kecap dgn wadah piring ceper.\", \"Siapkan arang utk membakar. Bakar sate setengah matang,olesi margarin cair + kecap,bakar lg sampai matang.\", \"Buat sambal kecap. Iris cabe merah,bawang merah,tomat beri kecap.\", \"Siram bumbu kecap diatas sate. Yummy.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(864, 2, 'Tongseng Kambing 🐐 #KitaBerbagi', 'Resep Tongseng Kambing 🐐 #KitaBerbagi yang lezat dan mudah dibuat di rumah.', '[\"600 gr daging kambing, jangan dicuci\", \"1 batang sereh, geprek\", \"6 lembar daun jeruk & 6 lembar daun salam\", \"1 sdm garam\", \"Air secukupnya untuk merebus daging\", \"2 btg daun bawang, rajang halus\", \"1 buah tomat ukuran besar, potong dadu\", \"1 batang kol, rajang *Saya gak pake\", \"Sesuai selera cabe rawit\", \"Bumbu halus:\", \"8 siung bawang merah\", \"6 siung bawang putih\", \"4 buah cabe merah\", \"3 btr kemiri, sangrai\", \"2 sdt biji ketumbar, sangrai\", \"1/2 buah pala\", \"1/4 sdt jintan\", \"1 ruas kunyit\", \"Bumbu lainnya:\", \"6 lbr daun jeruk, sobek2\", \"4 lbr daun salam\", \"1 batang sereh, geprek\", \"6 btr cengkeh\", \"4 btr kapulaga\", \"2 ruas kayu manis\", \"2 buah bunga lawang\", \"2 sdm gula jawa sisir\", \"2 sdt gula pasir & garam\", \"1/2 sdt lada bubuk\", \"65 ml santan kental instan\", \"2 sdm kecap manis\", \"1 liter air\", \"Secukupnya minyak goreng\"]', '[\"Didihkan satu panci air dgn sereh, daun jeruk & daun salam. Masukkan daging kambing, rebus 10 menit. Angkat dagingnya, buang air rebusannya. *Ini tips dari saya supaya dagingnya gak bau. Lalu potong2 daging kambing searah serat seukuran 2 cm.\", \"Panaskan minyak goreng, tumis bumbu halus & bumbu lainnya KECUALI santan & kecap manis. Tumis hingga harum & dedaunan layu. Masukkan daging, tumis sebentar. Tuangkan 500 ml air, masak daging dgn api kecil hingga kuah menyusut. Wajan/pancinya ditutup ya.\", \"Begitu daging mulai empuk, tuangkan sisa 500 ml air lalu masukkan daun bawang, santan & kecap. Masak dgn api sedang sambil diaduk hingga mendidih. Tambahkan garam, gula & merica bubuk, koreksi rasa. Terakhir masukkan tomat & cabe rawit, masak hingga tomat agak layu, angkat.\", \"Sajikan dgn sambel rawit, perasan jeruk nipis & bawang goreng. *Saya cuma pake cabe rawit gelundungan aja tadi, lagi males nyambel.. 😅\", \"Kuahnya asli manteppp...!!! Gurih-segar tanpa bau kambing. Dagingnya juga empyukk.. Awas nambah. 😎\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(865, 2, 'Sate kambing / sapi', 'Buat Sate kambing / sapi yang nikmat dengan langkah-langkah mudah ini.', '[\"1 kg daging kambing/ sapi\", \"bawang merah mentah secukupnya untuk campuran bumbu, iris kasar\", \"secukupnya bawang merah goreng\", \"secukupnya jeruk nipis\", \"secukupnya kecap\", \"secukupnya daun pepaya / nanas\", \"secukupnya tusukan sate\", \"secukupnya arang\", \"😊bahan pencelup:\", \"secukupnya kecap\", \"secukupnya minyak goreng\", \"😍bumbu kacang:\", \"1/4 kg kacang tanah, goreng dulu\", \"8 buah cabe merah, goreng dulu\", \"5 siung bawang putih, goreng dulu\", \"150 gram gula merah, sisir\", \"secukupnya air\", \"secukupnya garam\"]', '[\"Potong dadu daging kambing / sapi, tapi agak tipis gepeng ya, agar matang. bungkus daun pepaya, diamkan 15-30 menit. kalau pake nanas, campur irisan/ parutan nanas dengan daging, langsung tusuk jangan tunggu lama sebab lebih cepat reaksinya.\", \"Tusuk daging sampai habis.\", \"Bakar sate diatas arang sampe ½ matang (bisa juga di atas kompor pake fancy grill), olesi bahan pencelup, bakar lagi hingga matang, jangan lupa dibolak balik ya\", \"Bumbu kacang : haluskan semua bahan kecuali gula merah. masukkan air dan gula merah, masak dengan api kecil (dikotok bahasa jawanya), sampai berminyak bumbunya, jika minyak belum keluar tamvahkan air lanjutkan memasak sampai minyak keluar.\", \"Penyajian: campur bumbu kacang dengan kecap secukupnya, bawang merah mentah, aduk rata. beri perasan air jeruk nipis secukupnya, lalu tuang diatas sate, taburi bawang goreng dan sajikan.\", \"Siap disajikan bersama nasi hangat atau lontong, sooo yummyyy\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(866, 4, 'Tengkleng Kambing #KitaBerbagi', 'Tengkleng Kambing #KitaBerbagi - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 kg Daging + jeroan + tulang kambing\", \"4 bh cabe rawit\", \"3 lembar daun salam (remas)\", \"2 batang sereh (geprek, simpulkan)\", \"6 lembar daun jeruk (remas)\", \"1 butir kapulaga\", \"2 butir cengkeh\", \"1 potong kayu manis\", \"1 cm lengkuas (geprek)\", \"1/2 bungkus santan bubuk\", \"2-3 sdm kecap manis\", \"Secukupnya merica bubuk\", \"Secukupnya gula pasir\", \"Secukupnya garam\", \"Masako sapi\", \"Penyedap (optional)\", \"Bumbu halus :\", \"6 butir Bawang putih\", \"6 butir Bawang merah\", \"1/4 sdt jinten\", \"1 ruas jahe\", \"1 ruas kunyit\", \"1 sdt ketumbar\", \"4 butir kemiri\"]', '[\"Rebus daging, jeroan & tulang kambing sampai mendidih. Supaya lebih enak saya tambahkan garam & merica saat direbus (bisa diskip). Tiriskan, kemudian potong2 sesuai selera.\", \"Haluskan bumbu (kalo suka pedas cabe bisa ikut dihaluskan, kalo saya cabe saya biarkan utuh, suami suka pedas jd saat mau dihidangkan tinggal uleg cabenya di mangkok). Tumis bumbu halus, daun salam, daun jeruk, sereh & lengkuas sampai harum, tambahkan air yg agak banyak. Masukkan santan, cabe, kapulaga, kayu manis & cengkeh. Biarkan hingga mendidih.\", \"Masukkan daging + jeroan + tulang sapi & semua bahan yg tersisa. Masak lg hingga mendidih & bumbu meresap. Koreksi rasa.\", \"Taburi bawang goreng biar lebih enak. Siap dihidangkan 😊\", \"Tips : Kalo mau daging lebih empuk, sebelum dimasak bisa dibungkus dgn daun pepaya yg sdh diremas2 selama kurleb 30 menit. Atau baluri dgn parutan nanas selama 5 menit saja (kalo kelamaan nanti daging bisa hancur saat dimasak karena terlalu empuk) lalu cuci bersih.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(867, 4, 'Sup Tulang (Kambing) Rempah', 'Nikmati kelezatan Sup Tulang (Kambing) Rempah dengan resep sederhana ini.', '[\"tulang kambing matang yg sdh direbus jahe & garam\", \"1.5 L air\", \"2 jempol jahe, iris tipis\", \"2 jumput cumin/jinten\", \"2 bh bunga lawang/anis star\", \"6 butir cengkeh\", \"1 bongkah bawang putih, cacah\", \"1 batang kayu manis, geprek\", \"1 bh pala, geprek\", \"1.5-2 sdm garam\", \"1/2 sdm gula pasir\", \"1/2 sdt kaldu bubuk\", \"1/2 sdt merica bubuk, pakai merica hitam lebih OK\", \"#versi lengkap#\", \"1 tomat, bagi 8 bagian\", \"1/2 bh air lemon import\", \"secukupnya seledri & bawang goreng\"]', '[\"Goreng bawang putih, hingga kecoklatan, masukkan jahe & cumin, aduk hingga bau jahe keluar.\", \"Masukkan daging ke air yg sdh mendidih. tambahkan tumisan bawang putih, jahe & cumin plus minyaknya.\", \"Masukkan pala, merica, anis star, cengkeh, kayu manis, garam, gula, kaldu. aduk, koreksi rasa. biarkan sampai menyerap.\", \"Ketika daging sdh matang sempurna, matikan api. hidangkan. #VERSI LENGKAP : masukkan tomat, air lemon & seledri (terakhir pas api sdh dimatikan). biasanya setelah ditambah lemon & tomat, rasa berubah asam, tambahkan garam & sedikit gula utk menetralisir.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(868, 4, 'Sop kambing kuah susu#kitaberbagi', 'Resep Sop kambing kuah susu#kitaberbagi yang lezat dan mudah dibuat di rumah.', '[\"250 gr daging kambing dipresto\", \"150 gr tulang kambing dipresto untuk kaldu\", \"Bahan tambahan\", \"5 siung bawang putih iris\", \"5 siung bawang merah iris\", \"1 tomat iris\", \"0.5 bh bawang bombay iris\", \"Sejumput jinten\", \"Sejumput pala\", \"5 bh kapulaga\", \"1 sdt ladaku\", \"Sejumput kayu manis\", \"Sejumput ketumbar\", \"1 bkus susu bubuk dancow\", \"Gula garam kaldu jamur totole\"]', '[\"Daging dan tulang dipresto tambahkan jahe salam sereh daun jeruk\", \"Tumis bahan iris dgn mentega/minyak\", \"Tuang kaldu kambing dr presto 200 cc..masukan daging n tulang\", \"Tambahkan pala kapulaga ketumbar lada jinten kayu manis\", \"Tuang susu bubuk atau encerin dulu pake air\", \"Aduk..sampe matang..tambah tomat..gula garam kaldu bubuk\", \"Tes rasa..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(869, 4, 'Tumis daging kambing #kitaberbagi', 'Resep Tumis daging kambing #kitaberbagi ala rumahan yang dijamin menggugah selera.', '[\"150 gr daging kambing iris tipis\", \"secukupnya nanas\", \"1 buah bawang putih iris tipis\", \"1/2 buah bawang bombay iris tipis\", \"2 buah cabe ijo besar buang bijinya iris sesuai selera\", \"2 buah cabe merah besar buang bijiny iris sesuai selera\", \"secukupnya lada, garam, gula\", \"1 sdm kecap manis\", \"kecap asin saya tidak pakai\", \"tomat saya tidak pakai\"]', '[\"Siapkan bahan\", \"1.siapkan daging beri garam dan lada sisihkan Diamkan selama 30 menit 2. iris bawang putih, bawang bombay, cabe hijau sisihkan\", \"Siapkan pan, beri minyak/mentega, biarkan panas, masukkan bawang putih, tumis hingga harum, masukkan daging, masak hingga berubah warna hingga 1/2 matang masukkan nanas, cabe hijau dan bawang bombay, tambah gula dan kecap koreksi rasa, dan daging matang angkat\", \"Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(870, 2, 'GULE KAMBING #KitaBerbagi', 'GULE KAMBING #KitaBerbagi dengan daging kambing empuk tanpa bau prengus.', '[\"500 gr daging kambing campur tulang\", \"10 siung bawang merah\", \"5 siung bawang putih\", \"1/2 sdt merica\", \"1/4 sdt jintan, disangrai\", \"1 buah cabe jawa\", \"1 buah kapulaga\", \"2 cm kayu manis\", \"3 cm jahe\", \"2 cm kunyit, dibakar\", \"2 sdt garam\", \"20 gr gula jawa\", \"5 cm lengkuas, digeprek\", \"3 lbr daun jeruk\", \"1 batang sereh\", \"2 lbr daun salam\", \"300 ml air\", \"750 ml santan encer\", \"2 sdm minyak goreng\"]', '[\"Haluskan bawang merah, bawang putih, merica, jintan, cabe jawa, kapulaga, kayu manis, jahe, kunyit dan garam\", \"Panaskan minyak goreng, tumis bumbu halus, daun jeruk, lengkuas, sereh dan daun salam, hingga harum\", \"Masukkan daging kambing dan gula jawa, tambahkan air ungkep hingga bumbu meresap dan daging setengah empuk, tes rasa yaaaa....\", \"Tambahkan santan encer, ungkep kembali hingga matang dan daging empuk\", \"Sajikan dengan taburan bawang goreng\", \"Selamat mencoba....\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(871, 3, 'Sate kambing bumbu kecap 2 #kita berbagi', 'Resep praktis Sate kambing bumbu kecap 2 #kita berbagi yang bisa dicoba di rumah.', '[\"200 gr daging kambing potong potong\", \"tusuk sate\", \"bumbu perendam\", \"1 buah bawang putih haluskan\", \"1/4 sdt lada halus\", \"1/4 sdt garam\", \"sepotong nanas haluskan\", \"1/2 sdt minyak goreng\", \"1 sdt kecap\", \"ini semua bisa ditambah yaa sesuai porsi yang akan dimasak\", \"bumbu kecap\", \"5 buah cabe rawit iris bulat\", \"1 buah tomat potong dadu\", \"1 buah jeruk limau\", \"secukupnya kecap manis\", \"2 buah bawang merah iris halus\"]', '[\"Siapkan bahan membuat sate\", \"1.campur daging dengan bumbu perendam diamkan selama 15 menit (menurut mba fitri paling lama 30 menit lebih dari itu daging akan lebih lunak dan hancur jika dimasak) 2.ambil tusuk sate, tusukkan daging di tusuk sate lakukan hingga daging habis 3.siapkan pemanggang, kali ini saya gunakan teflon (happy call) karena arangnya sudah habis, bisa menggunakan arang yaa, bakar hingga matang\", \"Siapkan bahan bumbu kecap, campur semua bahan sajikan bersama sate\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(872, 4, 'Tumis kecap daging kambing', 'Resep Tumis kecap daging kambing ala rumahan yang dijamin menggugah selera.', '[\"400 gr daging kambing\", \"bumbu halus utk marinade:\", \"2 siung bawang putih\", \"1/2 sdt merica butiran\", \"5 sdm kecap manis\", \"1 sdm kecap asin\", \"bumbu iris :\", \"3 siung bawang merah\", \"1 buah cabe merah besar\", \"2 buah cabe rawit pedas\", \"6 buah cabe rawit\", \"secukupnya gula dan garam\", \"2 sdm kecap manis\", \"1 sdt kecap asin\", \"secukupnya air\", \"jika suka penyedap\", \"secukupnya minyak goreng utk menumis\"]', '[\"Iris daging dadu kmd lumuri dg bumbu halus juga kecap2an,diamkan selama kurleb 1 jam bs masukkan k dlm kulkas\", \"Stlh 1 jam, siapkan bumbu irisan bawang merah dan cabe2an\", \"Tumis bumbu iris hingga matang kmd masukkan daging yg sudah dimarinade\", \"Masak sbntr hingga daging berubah warna kmd masukkan air tunggu hingga mendidih lalu masukkan gula garam kecap manis dan kecap asin\", \"Bisa tambahkan penyedap jika suka. tes rasa sembari menunggu air agak menyusut dan daging empuk\", \"Jika sdh pas bs diangkat hidangkan dg taburan bawang goreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(873, 3, 'Rabek kambing', 'Buat Rabek kambing yang nikmat dengan langkah-langkah mudah ini.', '[\"1 kilo tulang kambing (bisa jg dagingnya saja)\", \"7 siung bawang merah\", \"5 siung bawang putih\", \"1/4 siung bawang bombai\", \"10 buah cabe rawit (kecil)\", \"1/2 sdm lada halus\", \"secukupnya garam\", \"5 sdm kecap manis\", \"3 sdm mentega\", \"1/2 sdm cuka apel (cuka biang)\", \"bawang goreng utk taburan\"]', '[\"Cuci bersih tulang kambing\", \"Rajang halus semua bawang\", \"Giling kasar cabe rawit\", \"Panaskan mentega. Tumis semua bawang hingga sedikit layu (nyemek2 gitu 😆😆)\", \"Masukan tulang kambing beri air hingga terendam.\", \"Masukkan cabe giling, lada halus, dan garam\", \"Masak hingga empuk dagingnya. Bila kurang air bisa ditambah lagi.\", \"Masukkan kecap. Masak hingga air tersisa sedikit.\", \"Terakhir masukkan cuka. Cek rasa. Bila sudah ok siap untuk dihidangkan dengan ditaburi bawang goreng.\", \"Rabek kambing siap disantap.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(874, 3, 'Nasi Goreng Kambing #KitaBerbagi', 'Nasi Goreng Kambing #KitaBerbagi - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"250 gram daging kambing (potong kotak)\", \"3 piring nasi\", \"1 sdm bubuk kari\", \"Secukupnya garam, gula & kaldu bubuk\", \"Secukupnya kecap manis dan air\", \"🔹Bahan Rempah🔹\", \"5 buah cengkeh\", \"2 buah kapulaga\", \"1 batang kecil kayu manis\", \"🔹Bumbu Halus🔹\", \"7 buah bawang merah\", \"4 buah bawang putih\", \"1/2 sdt jintan\", \"1/2 sdt adas\", \"1 sdm ketumbar\", \"1 sdt merica\"]', '[\"Tumis bumbu halus, bubuk kari dan bahan rempah sampai harum. Lalu masukan daging dan beri air secukupnya. Masak hingga daging empuk dan air mengental. Gunakan api kecil ya.\", \"Masukan garam, gula dan kaldu. Lalu masukan nasi dan kecap, aduk rata, koreksi rasa. Masak hingga nasi mengering.\", \"Nikmati nasi goreng kambing dengan pelengkap lain na😉ini enak banget...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(875, 2, 'Tongseng Kambing #kitaberbagi', 'Tongseng Kambing #kitaberbagi dengan daging kambing empuk tanpa bau prengus.', '[\"500 gr daging kambing (rebus sebentar dan cuci bersih)\", \"5 helai kol,iris\", \"1 buah tomat potong2\", \"1 buah bawang bombay potong2 (optional)\", \"1 sdt garam halus\", \"1/3 sdt penyedap rasa\", \"secukupnya gula merah\", \"secukupnya kecap manis\", \"minyak untuk menumis\", \"100 ml santan\", \"air\", \"lengkuas geprek\", \"1 btg sereh geprek\", \"2 lbr daun jeruk\", \"2 lbr daun salam\", \"cabai (optional)\", \"bumbu halus:\", \"5 siung bawang merah\", \"5 siung bawang putih\", \"lada\", \"2 cm jahe\", \"2 cm kunyit\", \"rempah2 sedikit >pala,cabe jawa,kayu manis,bunga lawang,ketumbar\"]', '[\"Rebus daging sebentar kemudian cuci bersih\", \"Haluskan bumbu\", \"Tumis hingga harum dan kuning kecoklatan\", \"Masukkan daging,kemudian masukkan lengkuas,sereh,daun jeruk,daun salam,beri air\", \"Setelah daging empuk,masukkan santan,kol,tomat,bawang bombay,cabai utuh,garam,gula,kecap,penyedap rasa,tunggu hingga mendidih,koreksi rasa\", \"Siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(876, 3, 'Sate kambing goreng #Kitaberbagi', 'Sajian Sate kambing goreng #Kitaberbagi yang praktis dan lezat untuk dinikmati bersama.', '[\"400 gr daging kambing\", \"8 siung bawang merah\", \"6 siung bawang putih\", \"1 sdt munjung ketumbar bubuk\", \"1/2 sdt merica bubuk\", \"4 sdm kecap manis (sesuai selera)\", \"sedikit nenas parut untuk pengempuk\", \"Pelengkap: irisan cabe rawit, bawang merah, tomat\"]', '[\"Potong2 daging seukuran dadu, lumuri dengan sedikit parutan nenas, biarkan 10-15 menit jgn lebih nnti daging bs trll empuk saat dimasak\", \"Tumis bawang merah bawang putih yg sdh dihaluskan, tambahkan ketumbar dan merica bubuk, tumis hingga harum\", \"Masukkan daging, aduk rata dengan bumbu. Tambahkan kecap, garam, kaldu bubuk. Koreksi rasa. Masak sampai daging empuk.\", \"Hidangkan dengan irisan cabe rawit, bawang merah, dan tomat...ini maknyuss bgt moms😋👌🏻 alternatif bgi yg males tusuk2 sate macam sya😁\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(877, 4, 'Sop tulang kambing praktis#kitaberbagi', 'Sop tulang kambing praktis#kitaberbagi - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1/2 kg tulang kambing\", \"2 lembar daun salam\", \"1 ruas lengkuas\", \"2 sndok makan jeruk nipis\", \"1/2 siung bawang bombay\", \"bawang goreng\", \"bumbu halus\", \"merica butir secukup\'y\", \"4 siung bawang merah\", \"3 siung bawang putih\", \"minyak untuk menumis\", \"penyedap rasa secukup\'y (me; Royco)\"]', '[\"Rebus tulang kambing sampai empuk masukan daun salam & lengkuas\", \"Tumis bumbu halus sampai Wangi masukan air,,lalu masukan tulang yg sudah direbus tadi biarkan mendidih & matang\", \"Masukan bawang bombay yg sudah diiris, masukan penyedap rasa & perasan jeruk nipis\", \"Setelah air agak menyusut & matang angkat tulang dan beri taburan bawang goreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(878, 4, 'SATE KAMBING #KitaBerbagi', 'SATE KAMBING #KitaBerbagi dengan daging kambing empuk tanpa bau prengus.', '[\"500 gr daging kambing, potong dadu\", \"5 siung bawang putih\", \"2 siung bawang merah\", \"2 sdt ketumbar\", \"1/2 sdt merica\", \"1 sdt garam\", \"25 gr gula jawa\", \"100 ml kecap manis\", \"50 gr kol, rajang halus\", \"3 siung bawang merah, rajang kasar\", \"4 buah cabe rawit merah, diiris\", \"1 buah tomat\", \"Tusuk sate\"]', '[\"Haluskan bawang merah, bawang putih, ketumbar, merica dan garam\", \"Setelah halus, tambahkan gula jawa, haluskan kembali\", \"Tempatkan daging kambing dalam wadah, lalu lumuri dengan bumbu halus, diamkan kurang lebih 15 - 25 menit\", \"Tusuk potongan daging kambing, lalu di panggang diatas bara hingga setengah matang\", \"Campur sisa bumbu rendaman dengan 50 ml kecap manis, oleskan pada sate yg setengah matang, lalu panggang kembali hingga tingkat kematangan sesuai selera\", \"Setelah matang, sajikan dengan irisan tomat, kol, bawang merah dan cabe rawit. Tambahkan kecap manis.\", \"Selamat mencoba....\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(879, 3, 'Kambing Lada Hitam', 'Cara membuat Kambing Lada Hitam yang enak dan praktis untuk keluarga.', '[\"1/4 kg daging kambing\", \"1 bh kentang\", \"2 bh tomat\", \"1/2 siung bawang bombay\", \"4 siung bawang merah (cincang)\", \"3 siung bawah putih (cincang)\", \"1 sdt lada hitam bubuk\", \"1/2 sdt merica bubuk\", \"1/2 sdt jahe\", \"secukupnya garam\", \"minyak goreng\"]', '[\"Bersihkan daging kambing (jangan dicuci) lalu potong dadu\", \"Tambahkan cincangan bawang merah dan putih ke dalam potongan daging, aduk sambil diremas-remas.\", \"Tambahkan bubuk lada hitam, merica dan jahe, aduk kembali hingga merata. Diamkan selama 30 menit.\", \"Kentang dipotong dadu kemudian digoreng. Sisihkan.\", \"Panaskan minyak secukupnya. Tumis bawang bombay yang telah dipotong-potong. Setelah layu masukkan daging.\", \"Masukkan tomat yang telah dipotong dadu. Tambahkan garam sesuai selera. Aduk agar merata.\", \"Masukkan kentang goreng. Aduk dan tutup wajan. Diamkan hingga daging empuk.\", \"Aduklah sesekali agar daging tidak lengket.\", \"Jika daging telah empuk, angkat dan hidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(880, 3, 'Sate Kambing Empuk Sambel Kecap #KitaBerbagi', 'Buat Sate Kambing Empuk Sambel Kecap #KitaBerbagi yang nikmat dengan langkah-langkah mudah ini.', '[\"350 gr daging kambing\", \"2 lbr daun pepaya\", \"Bumbu halus :\", \"6 siung bawang merah\", \"3 siung bawang putih\", \"2 btr kemiri\", \"1 ruas jahe\", \"1 sdt merica bubuk\", \"1 sdt ketumbar bubuk\", \"1 sdt garam\", \"Bahan olesan :\", \"Secukupnya margarin yg sdh di panaskan / cair\", \"Secukupnya kecap manis\", \"Bahan Sambel Kecap :\", \"Irisan bawang merah,bawang putih, cabe rawit, tomat &kecap manis\", \"Jangan lupa siapkan arang & tusuk sate nya ya\"]', '[\"Cuci daging kambing *potong2 dadu *masukan daging ke tusukan sate. 1 tusuk = 4-5 daging\", \"Oleskan bumbu halus ke potongan daging kambing\", \"Siapkan wadah yg sudah dialasi 1 lembar daun pepaya, taruh daging yg sdh dibumbui diatasnya & tutup daging dgn 1 lembar daun pepaya lagi. Diamkan / simpan dikulkas slm 1 jam\", \"Sambil menunggu bumbu daging meresap, Siapkan bahan olesan & bumbu kecapnya. Termasuk persiapan arang jg (dinyalakan)\", \"Bakar sate sampai 1/2 matang, olesi dgn bumbu olesan lalu bakar lagi hingga matang sempurna\", \"Siram sate dgn bumbu kecap & siap di santap sepiring br2 dgn suami😄\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(881, 2, 'Tongseng kambing #kitaberbagi', 'Resep praktis Tongseng kambing #kitaberbagi yang bisa dicoba di rumah.', '[\"1/2 kg daging kambing\", \"santan (sy pake 1/4 kelapa)\", \"bumbu halus:\", \"bawang putih\", \"bawang merah\", \"kemiri\", \"cabe merah besar\", \"cabe rawit\", \"kunyit\", \"bumbu cemplung:\", \"daun salam\", \"daun jeruk\", \"laos\", \"sereh\", \"secukupnya kecap\", \"secukupnya garam\", \"kol\", \"tomat\"]', '[\"Daging kambing rebus sebentar.\", \"Haluskan bumbu halus. kemudian tumis sampai harum. masukkan bumbu cemplung.\", \"Masukkan daging kambing yg sudah direbus. masukkan santan,aduk rata.\", \"Tambahkan kecap manis,garam,gula sesuai selera. cicipi rasa. bisa ditambah air bila suka encer.\", \"Tunggu sampai empuk kemudian masukkan kol dan tomat yang sudah diiris. diamkan sampai sayuran layu.\", \"Sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(882, 4, 'Sate Kambing Simple Empuk #KitaBerbagi', 'Sajian Sate Kambing Simple Empuk #KitaBerbagi yang praktis dan lezat untuk dinikmati bersama.', '[\"1 kg daging Kambing (bisa dicampur lemak atau gajih sapi)\", \"sesuai selera Kecap manis\", \"1/2 buah nanas. Parut untuk mengempukkan daging\", \"bumbu halus\", \"5 siung bawang merah\", \"6 siung bawang putih\", \"1 sdt ketumbar bubuk\", \"1 sdt jahe bubuk\", \"1 sdt merica bubuk\", \"1/2 blok gula jawa\", \"1 sdt garam\", \"Daun jeruk iris tipis\", \"Laos / lengkuas digrebek bareng bumbu halus\"]', '[\"Potong daging sesuai selera. Lalu lumuri parutan nanas diamkan 15 menit.\", \"Sementara nunggu daging empuk, kita buat bumbu untuk marinasi. Semua BUMBU HALUS dihaluskan. Tambahkan kecap sesuai selera. Bagi 2. Untuk marinasi dan untuk olesan Bakaran.\", \"Setelah daging empuk masukan ke bumbu marinasi yang sudah dipisah. Marinasi daging dalam wadah tertutup masukan ke kulkas. 30 menit cukup.\", \"Setelah selesai marinasi, tusuk daging sesuai selera. Usahakan jangan banyak jeda karena daging jika dibakar akan mengkerut.\", \"Bakar diatas arang atau menggunakan pan grilled. Setengah matang olesi dengan bumbu marinasi yang sudah dipisah tadi.\", \"Bakar sampai matang. Dan siap disantap rame rame bareng keluarga 🤗\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(883, 2, 'Oseng daging kambing dan sapi ala dechan', 'Resep Oseng daging kambing dan sapi ala dechan yang lezat dan mudah dibuat di rumah.', '[\"Secukupnya daging kambing dan sapi (sudah d rebus sampai empuk)\", \"15 buah cabe rawit\", \"1 buah tomat\", \"1/2 siung bawang bombay\", \"1/2 ruas jahe(bisa di skip)\", \"2 sdm kecap manis\", \"5 sdm saos cabai\", \"3 sdm air matang\", \"Sejumput garam\", \"Sejumput penyedap rasa\", \"Secukupnya minyak\"]', '[\"Potong daging sapi dan kambing sesuai selera.(me:kecil kecil dan tipis)\", \"Potong dadu tomat merah.kemudian iris bawang bombay,jahe dan cabe rawit\", \"Panaskan minyak.masukan tomat,jahe dan bawang bombay.tumis sampai layu dan wangi\", \"Masukan daging kambing dan sapi.\", \"Setelah itu masukan kecap tambahkan air.aduk aduk sampai air mendidih dan menyusut,kemudian masukan saos cabe,garam dan penyedap rasa.test rasa.\", \"Sebelum di matikan masukan cabe rawit aduk aduk sebetar.lalu sajikan..\", \"Note:Masakan ini saya buat untuk 10 porsi.jadi air nya dikit aja ya kalo yg mau buat dalam porsi dikit. Dan cabe nya juga bisa d kurangn.saya pake cabe banyak karna pada doyan pedes d rumah.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(884, 2, 'Krengseng Kambing Bumbu Kecap *tanpa santan #KitaBerbagi', 'Sajian kambing spesial: Krengseng Kambing Bumbu Kecap *tanpa santan #KitaBerbagi yang menggugah selera.', '[\"1 kg daging kambing/tetelan, potong2 agak kecil\", \"Bumbu:\", \"6 siung bawang putih,haluskan\", \"12 btr bawang merah,haluskan\", \"4 butir kemiri,haluskan\", \"1/4 sdt mrica bubuk\", \"6 buah cabe hijau besar, potong2\", \"6 buah cabe merah besar,potong2\", \"10 bh(sesuai selara) cabe rawit utuh\", \"2 buah tomat,potong2\", \"2 tangkai sere, geprek\", \"2 ruas jahe, geprek\", \"2 ruas lengkuas, geprek\", \"5 lbr daun jeruk\", \"Kecap secukupnya (kalo aku suka agak banyak\", \"secukupnya Garam\", \"secukupnya Kaldu bubuk\", \"Bawang goreng secukupnya untuk taburan\", \"secukupnya Air\", \"Minyak utk menumis\"]', '[\"Cuci bersih daging yang udah dipotong2, sisihkan\", \"Panaskan sedikit minyak utk menumis. Masukkan bawang putih, bawang merah, dan kemiri yang telah dihaluskan, merica bubuk, jahe, lengkuas, sereh, dan daun jeruk, tumis sampe harum\", \"Masukkan irisan cabe ijo dan merah, tumis sebentar, terus masukkan daging dan tomat. Aduk2 sampe daging berubah warna.\", \"Tambahkan air, tapi jangan terlalu banyak ya.. asal daging tercelup air saja. Dan juga garam, kecap dan penyedap. Tutup wajan, agar bumbu meresap dan daging cepet mateng, sambil sesekali diaduk. Jangan lupa untuk tes rasa. Dan jika dirasa air kurang, tapi daging belum empuk, tambahkan air secukupnya.\", \"Jika daging sudah empuk. Matikan kompor. Sajikan dg taburan bawang goreng 👌\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(885, 2, 'Sate Kambing #KitaBerbagi', 'Resep Sate Kambing #KitaBerbagi ala rumahan yang dijamin menggugah selera.', '[\"300 gr daging kambing\", \"Secukupnya tusuk sate\", \"3 lbr daun pepaya\", \"Bumbu halus:\", \"4 siung bawang putih\", \"1 sdm ketumbar butiran\", \"Secukupnya garam\", \"Sambal kecap:\", \"Secukupnya kecap manis\", \"Cabe rawit\", \"Tomat\", \"Bawang merah\"]', '[\"Cuci bersih daging,potong dadu..lumuri dg bumbu halus yg sdh diuleg..bungkus dg daun pepaya,biarkan kurleb 30-60 menit\", \"Siapkan bakaran,bakar sampai kematangan yg diinginkan (ada yg suka matang,ada yg suka setengah matang)\", \"Sambal kecap: iris2 cabe rawit,dan bawang merah..tuangi kecap secukupnya\", \"Penyajian:tata sate di piring,siram dg sambal kecap..beri irisan tomat..\", \"Siap dinikmati dg nasi putih hangat 😊😊😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(886, 2, 'Semur kambing endes #KitaBerbagi', 'Sajian kambing spesial: Semur kambing endes #KitaBerbagi yang menggugah selera.', '[\"300 gr daging kambing\", \"6 buah bawang merah(iris)\", \"5 buah bawang putih (iris)\", \"Tambahan\", \"4 bawang putih dan merah(blender)\", \"1 ruas jahe (blender)\", \"1 buah bawang bombay ukuran sedang\", \"15 buah cabe merah keriting\", \"25 buah cabai rawit\", \"15 buah cabai hijau\", \"1 ruas lengkuas(geprek)\", \"2 helai serai (geprek)\", \"3 lembar daun salam\", \"2 lembar daun jeruk purut\", \"1 buah utuh kemiri\", \"1 sashet masako sapi\", \"1 bks tumbar halus\", \"1 bks kecap bango ukuran kecil\", \"2-3 gelas air\"]', '[\"Daging sapi jgn dicuci cukup rendam air panas sebentar sembari nyiapin bumbu,\", \"Iris smua bumbu dan geprek laos dan serai\", \"Blender / haluskan bawang putih, bawang merah, jahe,kemiri\", \"Iris daging sesuai selera, kalo saya kecil2, tiriskan\", \"Tumis bumbu halus dan bumbu iris dengan sedikit minyak hingga wangi, aduk aduk hingga rata, dan layu masukan air lalu beri kecap, penyedap, aduk hingga rata dan mendidih\", \"Lalu masukan daging kambing, aduk hingga rata, tutup wajan pake penutup sandang biar bumbu meresap dan kambing lembut kurleb 5-8menit\", \"Lalu aduk dan icip2, mau kering atau dikasih kuahnya tergantung selera masing2 ya, kalo saya agak kering tapi tetap sedikit basah, tiriskan siap dinikmati,\", \"Vavorite bapak dan suami 😋😋😋😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(887, 3, 'Nasi goreng kambing ala kebon sirih #KitaBerbagi', 'Nasi goreng kambing ala kebon sirih #KitaBerbagi dengan daging kambing empuk tanpa bau prengus.', '[\"200 gr daging kambing (potong dadu)\", \"3 piring nasi putih dingin\", \"🌺Bumbu halus:\", \"7 bawang merah\", \"5 bawang putih\", \"Rawit (sesuai selera)\", \"1/2 sdt adas\", \"1/2 sdt jintan\", \"1 sdt ketumbar\", \"1 btg kecil kayu manis\", \"5 cengkeh\", \"3 kapulaga\", \"1 sdm bubuk kari\", \"100 gr minyak samin\", \"Secukupnya Gula,garam,merica,air\"]', '[\"Tumis bumbu halus dgn minyak Samin... tambahkan cengkeh,kapulaga, kayu manis,tumis sampai harum.. tambahkan daging kambing,masak smp berubah warna..\", \"Tambahkan air,masak sampai daging empuk.. masukkan gula garam,tes rasa..\", \"Jika sudah pas,masukkan nasi n kecap,goreng sampai matang n rata...\", \"Sajikan dgn acar n emping.. ini buat sarapan,sdh laper blm bikin acar (JANGAN DITIRU🙈)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(888, 2, 'Sate Kambing bumbu kecap #KitaBerbagi', 'Nikmati kelezatan Sate Kambing bumbu kecap #KitaBerbagi dengan resep sederhana ini.', '[\"1/4 kg daging kambing\", \"bumbu celup:\", \"2 siung bawang putih\", \"5 sdm kecap\", \"1 sdt ketumbar bubuk\", \"5 sdm air asam jawa\", \"4 sdm air putih\", \"bumbu sate:\", \"5 sdm kecap\", \"2 sdm air asam jawa\", \"2 sdm air putih\", \"1 sdm bawang putih goreng (diremuk dahulu)\", \"pelengkap:\", \"3 siung bawang merah (iris tipis)\", \"1 buah tomat (potong jadi 4)\", \"secukupnya kubis\"]', '[\"Potong kotak-kotak daging dan tusuk dengan tusuk sate.\", \"Siapkan bumbu celup dan haluskan.\", \"Lumuri daging yang sudah ditusuk dengan bumbu celup. Diamkan 10 menit.\", \"Panggang setengah matang. Celup kembali ke bumbu celup. Panggang kembali hingga matang.\", \"Siapkan bumbu sate dan pelengkapnya. Campur bumbu sate hingga rata.\", \"Tata bumbu sate dan pelengkap di piring serta sate kambingnya. Siap disajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(889, 3, 'Pepes otak kambing medium hot.', 'Resep Pepes otak kambing medium hot. yang lezat dan mudah dibuat di rumah.', '[\"1 buah Otak kambing\", \"secukupnya Daun Kemangi\", \"2 lembar Daun salam\", \"1 sachet Masako ayam atau sapi.selera\", \"secukupnya Daun pisang\", \"Bumbu halus...\", \"5 siung Bawang merah , butiran kecil sedang.atau sesuai selera\", \"2 siung Bawang putih  ukuran besar.kalo kecil 3-4 siung\", \"3 buah Cabai merah besar\", \"sesuai selera Cabai rawit  pedasnya.kalo ndk mau pedas kasih 3\", \"1/2 sdt Merica .atau secukupnya\", \"1 ruas jari jempol Laos\", \"1/2 ibu jari Kunir\", \"1 ruas Jahe sedikit saja.setengah klingking\", \"3-4 butir Kemiri\", \"secukupnya Garam\", \"Sedikit Micin bisa skip\"]', '[\"Otak kambing di rebus hingga agak lunak..kalo saya sampe lunak aja.selera...kan di kukus lagi nantinya kalau kurang lunak 😊..kmudian angkat..sisihkan\", \"Ulek semua bumbu halus..campur bumbu halus dan daun kemangi dengan otaknya aduk rata beserta masakonya.tes rasa\", \"Bungkus dengan daun pisang dan selipkan daun salam di dalam bungkusannya..\", \"Kemudian kukus sampai matang...the end...siap santap\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(890, 4, 'Rica Kambing', 'Sajian Rica Kambing yang praktis dan lezat untuk dinikmati bersama.', '[\"500 gr daging kambing direbus sampai empuk\", \"Bumbu halus :\", \"1 sdt lada\", \"3 siung bawang merah\", \"3 siung bawang putih\", \"1 sdt Jinten\", \"1/4 biji Pala\", \"sesuai selera Cabe rawit merah\", \"1 ruas jahe memarkan\", \"1 ruas kunyit memarkan\", \"3 lembar daun jeruk\", \"sesuai selera Gula\", \"secukupnya Garam\", \"secukupnya Kecap manis\", \"secukupnya Bawang goreng untuk taburan\"]', '[\"Tumis bumbu halus sampai layu dan berbau harum masuk kan jahe kunyit dan daun jeruk\", \"Tambahkan kaldu sisa rebusan daging lalu masuk kan daging\", \"Tambah kan gula garam dan kecap masak sampai air nya menyusut dan daging empuk\", \"Hidang kan beri taburan bawang merah\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(891, 2, 'Rendang kambing', 'Rendang kambing - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"500 gram daging kambing, potong dadu\", \"500 gram kentang, kupas dan potong dadu, goreng\", \"1 ruas laos, geprek\", \"6 lembar daun jeruk\", \"4 buah cabe besar\", \"10 butir bawang merah\", \"6 siung bawang putih\", \"1 ruas jahe\", \"1 bungkus santan kara\", \"sesuai selera Cabe rawit\", \"secukupnya merica bubuk\", \"secukupnya kunyit bubuk\", \"secukupnya garam\", \"secukupnya gula\", \"secukupnya air\", \"minyak untuk menumis\"]', '[\"Haluskan bawang merah, bawang putih, cabe besar, cabe rawit, jahe, merica dan kunyit.\", \"Tumis bumbu halus, daun jeruk dan laos sampai harum.\", \"Masukkan daging kedalam bumbu. Tumis sampai daging berubah warna.\", \"Tambahkan air sampai daging terendam. Biarkan sampai daging empuk. (Jika daging belum empuk, tambah air lagi sampai daging empuk)\", \"Jika daging sudah empuk dan air menyusut, masukkan kentang dan santan.\", \"Beri garam dan gula. Cek rasa.\", \"Setelah matang sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(892, 2, 'Sate Kambing Bulbul #KitaBerbagi', 'Cara membuat Sate Kambing Bulbul #KitaBerbagi yang enak dan praktis untuk keluarga.', '[\"500 gram daging kambing\", \"4 siung bawang putih\", \"3 siung bawang merah\", \"1 sdm ketumbar\", \"2 sdm kacang tanah goreng, haluskan\", \"Secukupnya Kecap manis\", \"secukupnya  Garam\", \"Secukupnya Minyak goreng\", \"3 lembar Daun jeruk\", \"sesuai selera Cabai rawit\"]', '[\"Bersihkan daging kambing, jangan dicuci. Potong dadu memanjang.\", \"Haluskan bawang merah, bawang putih, garam, merica dan ketumbar. Campur rata dengan daging kambing, tambahkan minyak goreng dan kecap manis. Diamkan 30 menit di kulkas.\", \"Tusuk2 daging yg sudah di marinate. Sisa bumbu bisa ditambahkan kecap dan minyak goreng. Bakar sate diatas arang sambil dioles bumbu rendaman.\", \"Campurkan kacang yg sudah dihaluskan dengan air dan kecap. Beri irisan cabe rawit bagi yg suka pedas. Sate siap dinikmati 👍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(893, 4, 'Kambing goreng sambal kecap super instan', 'Sajian Kambing goreng sambal kecap super instan yang praktis dan lezat untuk dinikmati bersama.', '[\"sesuai selera Daging kambing, onta jg boleh kalo ada\", \"1 sachet kecap\", \"1 sachet sambal\", \"Secukupnya Garam\", \"1 sachet blueband\", \"Secukupnya Minyak goreng, air, wajan, kompor gas, elpiji\"]', '[\"Cuci bersih daging lalu rebus sampai empuk, tiriskan\", \"Buat bumbu kuning, panaskan wajan. Masukkan blueband/minyak kayu putih. Eh minyak goreng maksudnya 😛😛\", \"Campurkan dging dlm bumbu sampai meresap, ksih sdikit garam lalu goreng. Bila sudah matang, tiriskan.\", \"Panaskan wajan, tumis blueband + sambal sachet. Tambah sedikit air lalu masukkan daging\", \"Tumis sebentar kasih kecap, hitung 1 - 10 atau se feeling hatinya. Dan... Siap dihidangkan. Soal rasa? Saya berani jamin 😎\", \"Terimah kasih karena sudah membaca resep ini mbak cantik 😚😛\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(894, 3, 'Tongseng kambing #kitaBerbagi', 'Nikmati kelezatan Tongseng kambing #kitaBerbagi dengan resep sederhana ini.', '[\"200 gram daging kambing\", \"2 lembar daun sawi putih (karena gak ada kol 😂)\", \"1 buah tomat mengkel\", \"4 buah cabe rawit\", \"2 smd santan kental\", \"1 sdt garam\", \"1 smd gula merah\", \"1 sdt merica bubuk\", \"2 siung bawang merah di iris\", \"2 siung bawang putih di iris\", \"Bumbu halus :\", \"2 butir kemiri\", \"1 cm kunyit\", \"1 sdt ketumbar\", \"2 gelas air\"]', '[\"Potong daging kecil kecil\", \"Ulek bumbu halus, goreng bersama irisan bawang merah dan putih Tumis sampai harum tambahkan air\", \"Masukan daging, kara, garam, gula, merica\", \"Setelah hmpir matang masukan sawi, tomat dan cabai masak sampai matang\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(895, 3, 'Soto Daging Kambing #Kitaberbagi', 'Resep Soto Daging Kambing #Kitaberbagi ala rumahan yang dijamin menggugah selera.', '[\"1/2 kg daging kambing dan tulang tulangnya kurleb\", \"1 bks santan kara\", \"3 lbr serai geprek\", \"2 cm lengkuas geprek\", \"3 lbr daun salam\", \"3 lbr daun jeruk\", \"sejumput jintan\", \"2 butir kapulaga\", \"1 batang kayu manis\", \"1 bgks masako sapi\", \"secukupnya garam dan sasa\", \"1/2 butir gula merah\", \"1 batang daun bawang potong potong\", \"bumbu halus\", \"8 butir bawang merah\", \"5 butir bawang putih\", \"1/2 sdt lada putih\", \"1 sdt ketumbar\", \"3 cm kunyit (sangrai terlebih dahulu)\", \"3 butir kemiri (sangrai terlebih dahulu)\", \"2 cm jahe\", \"bahan pelengkap\", \"sesuai selera cabe rawit kecil (rebus dan uleg)\", \"sesuai selera emping\", \"secukupnya bawang goreng\", \"1 buah kentang goreng potong potong\", \"1 buah tomat potong potong\", \"1 buah jeruk nipis\"]', '[\"Daging dicuci lalu direbus sampai agak empuk (takaran air sesuai kebutuhan)\", \"Haluskan smua bumbu halus setelah itu tumis sampai harum,masukkan juga jintan,kapulaga,kayu manis,daun jeruk daun salam,serai, lengkuas,gulmer,garam,sasa dan masako dan beri sedikit air\", \"Masukkan bumbu yg sudah ditumis ke dalam panci yg berisi daging dan tulang,aduk aduk lalu tunggu sebentar dan masukkan santan kara aduk aduk lalu masukkan daun bawang\", \"Koreksi rasa kalau sudah pas siap untuk dihidangkan beserta bahan pelengkap👌selamat mencoba ya bunda\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(896, 4, 'Tongseng iga kambing #memasakitumudah', 'Tongseng iga kambing #memasakitumudah - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"250 gram iga kambing\", \"bumbu halus :\", \"7 siung bawang merah\", \"3 siung bawang putih\", \"4 butir kemiri\", \"1 cm jahe\", \"1 cm kunyit\", \"1 sdt merica bubuk\", \"1 sdt ketumbar\", \"bahan pelengkap :\", \"1 cm lengkuas\", \"1 batang serai\", \"3 lembar daun salam\", \"2 lembar daun jeruk\", \"Secukupnya kecap\", \"sesuai selera cabai rawit di iris\", \"1 buah tomat hijau di iris\", \"1/4 buah kol putih\", \"secukupnya garam\", \"Secukupnya gula merah\", \"sedikit penyedap\", \"1 bgks santan kental (bumas)\", \"secukupnya air\"]', '[\"Rebus iga kambing dengan jahe sampai airnya tiris.\", \"Haluskan bumbu halus, tumis bumbu hingga harum, masukan lengkuas, daun salam, sereh, dan daun jeruk.. kemudian masukan iga kambing yang sudah direbus tumis sebentar\", \"Tambahkan air dan rebus sebentar. kemudian tambahkan santan, didihkan. masukan kecap secukupnya dan didihkan kembali. tambahkan garam, gula, dan penyedap. koreksi rasa. tambahkan cabai, tomat dan kol sebelum dihidangkan.\", \"Tongseng iga siap di sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(897, 3, 'Gulai babat dan kepala kambing #kitaberbagi', 'Nikmati kelezatan Gulai babat dan kepala kambing #kitaberbagi dengan resep sederhana ini.', '[\"1 buah kepala kambing muda\", \"1/2 kg jeroan kambing (babat,usus)\", \"1 lembar daun salam\", \"1 buah serai geprek\", \"1 ruas jempol lengkuas geprek\", \"3 lembar daun jeruk\", \"1 buah tomat iris kasar\", \"7 buah cabe rawit merah dan hijau iris kasar\", \"3 gelas santan kental dari 1 butir kelapa\", \"Bumbu halus :\", \"4 siung bawang putih\", \"7 butir bawang merah\", \"1/4 sdt jinten\", \"1/2 sdt merica butiran/bubuk\", \"1 jari telunjuk kunyit\", \"1 sdt ketumbar bubuk\", \"2 sdt garam\", \"2 sdt gula pasir\", \"1 ruas jempol jahe\", \"Pelengkap :\", \"Sambel pecel\", \"secukupnya Kecap\", \"3 lembar daun jeruk dan bawang merah Irisan\", \"1 buah Tomat iris\"]', '[\"Cuci bersih kepala dan jeroan kemudian rebus sampai empuk, biar cepat empuk sebelum direbus remas jeroan dengan daun pepaya lalu rebus bersama daun pepaya\", \"Tumis bumbu halus bersama lengkuas,daun salam,daun jeruk dan serai sampai wangi kemudian tuangi santan dan masukkan kepala,jeroan,cabe rawit\", \"Didihkan dan tes rasa jika sudah pas matikan api\", \"Gulai kepala kambing dan babat siap dihidangkan\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(898, 4, 'Rujak Kambing Muda', 'Nikmati kelezatan Rujak Kambing Muda dengan resep sederhana ini.', '[\"1/2 kg daging kambing muda yang sudah direbus\", \"300 ml air asam jawa\", \"5 siung bawang putih, 3 siung untuk digoreng, 2 siung untuk diulek\", \"5 siung bawang merah, iris\", \"1 sdm ketumbar, diulek bersama bawang putih\", \"10 bh cabe rawit, iris serong kecil\", \"2 ruas sereh iris kecil2\", \"1 jempol jahe iris kecil2\", \"5 lembar daun jeruk, iris tipis\", \"3 sdm kecap ABC\", \"1 bks masako\", \"1 sdm gula merah yang diiris tipis\", \"1 lembar daun salam\", \"5 sdm minyak goreng\"]', '[\"Cara mengolah daging kambing agar empuk dan tidak bau prengus; 1. Daging kambing yang masih mentah (belum dicuci) dilumuri jus nanas (1/2 buah nanas+air yang diblender), diamkan selama 20menit. 2. Siram daging lalu rebus sampai mendidih, tiriskan 3. Lumuri daging kambing yang sudah dingin dengan bubuk kopi, diamkan selama 30 menit 4. Cuci kembali daging kambing hingga bersih dari bubuk kopi 5. Rebus kembali daging dengan ditambahkan 1sdm garam dan diamkan hingga daging empuk, angkat dan tiriskan\", \"Panaskan minyak goreng\", \"Masukkan bawang merah dan bawang putih\", \"Masukkan ketumbar dan bawang putih yang dihaluskan\", \"Masukkan cabe rawit, jahe, dan sereh, aduk hingga harum dan cabe rawit sedikit layu\", \"Masukkan daun salam dan daun jeruk\", \"Tuangkan air asam jawa, masako, gula merah dan kecap manis ABC. Aduk-aduk dan diamkan hingga air sedikit surut, lalu aduk lagi dan angkat. Daging kambing siap dihidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(899, 4, 'Krengsengan Kambing', 'Resep praktis Krengsengan Kambing yang bisa dicoba di rumah.', '[\"500 gr daging kambing (bisa ditambah jeroan)\", \"2 lembar daun jeruk\", \"1 cm jahe\", \"1 buah serai\", \"1 buah tomat\", \"Secukupnya air\", \"Secukupnya kecap\", \"Secukupnya garam, lada, gula\", \"Bumbu halus:\", \"6 siuang bawang merah\", \"3 siung bawang putih\", \"1 buah cabe merah besar\", \"3 buah cabe rawit\"]', '[\"Rebus daging kambing dengan daun jeruk dan jahe. Ulangi sampe 3x agar daging tidak berbau. Iris kotak2, sisihkan.\", \"Haluskan bumbu halus\", \"Tumis bumbu halus beserta serai. Hingga harum (Bisa ditambah bawang bombay juga)\", \"Masukkan daging kambing yg sudah direbus dan diiris kotak2. Tambahkan air, kecap, gula, garam, dan lada\", \"Masak hingga air menyusut dan matang\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(900, 2, 'Tongseng kambing ala Bunda Nunuy', 'Resep Tongseng kambing ala Bunda Nunuy yang lezat dan mudah dibuat di rumah.', '[\"1/2 kg daging kambing plus lemak\", \"10 siung bawang merah\", \"4 siung bawang putih\", \"5 biji cabe rawit\", \"1 sdm merica\", \"5 sdm kecap manis\", \"gula plus garam\", \"secukupnya air\"]', '[\"Cuci bersih daging kambing lalu iris2 sesuai selera\", \"Haluskan bawang merah,bawang putih,cabe rawit dan merica\", \"Tumis bumbu yg dihaluskan,stlh harum dan layu lalu masukkan daging kambing,aduk sampai daging berubah warna lalu diberi air,biarkan sampai mendidih\", \"Stlh kuah mendidih lalu masukkan kecap manis,gula dan garam,biarkan sampai air meresap dan daging empuk\", \"Tes rasa,lalu angkat,pindahkan ke mangkok saji taburi dgn bawang goreng,sajikan dgn nasi putih,lezatos.....\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(901, 3, 'Sate kambing goreng pasti enak', 'Sate kambing goreng pasti enak dengan daging kambing empuk tanpa bau prengus.', '[\"250 gram daging kambing\", \"bumbu halus :\", \"5 siung bawang merah\", \"1 sdt ketumbar\", \"5 butir kemiri\", \"bumbu sate:\", \"secukupnya merica bubuk\", \"2 sdm kecap manis\", \"2 sdm margarin\", \"secukupnya gula merah\", \"4 sdm air asam\", \"secukupnya garam\", \"bumbu iris :\", \"8 siung bawang merah\", \"2 siung bawang putih\", \"7 buah cabai rawit (disesuaikan pedasnya)\", \"3 lembar daun jeruk\", \"minyak goreng\"]', '[\"Siapkan daging kambing, potong sesuai selera, kemudian haluskan bumbu halus, gunakan minyak jika menghaluskan bumbu dengan blender\", \"Siapkan bumbu campuran sate, masukan kecap, margarin, gula jawa yang sudah di iris halus, air asam jawa dan garam aduk hingga tercampur, lalu masukkan daging kambing yg sudah diiris dan di aduk sampai rata, diam kan selama 30 menit\", \"Siapkan penggorengan, panas kan minyak, tumis bumbu iris sampai harum, kemudian masukan daging kambing beserta bumbunya, tumis hingga matang ditandai dengan keluar nya minyak dan daging menjadi kering. jangan lupa koreksi rasa\", \"Dan sate kambing goreng siap di sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(902, 2, 'Krengsengan Kambing #kitaberbagi', 'Krengsengan Kambing #kitaberbagi - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"200 gr daging kambing\", \"Secukupnya gula, garam, merica bubuk\", \"Secukupnya air\", \"Secukupnya kecap manis\", \"Bumbu halus :\", \"3 siung bawang putih\", \"4 siung bawang merah\", \"2 buah cabe keriting\", \"4 buah cabe rawit (sesuai selera)\", \"1 cm kunyit\", \"1 cm jahe\", \"Bumbu cemplung :\", \"1 buah serai, geprek\", \"3 cm lengkuas, geprek\", \"2 lembar daun salam\", \"2 lembar daun jeruk\"]', '[\"Cuci bersih daging lalu potong² (saya potong dadu)\", \"Tumis bumbu halushalus bersama bumbu cemplung, tumis hingga harum\", \"Masukkan daging, aduk rata kemudian tambahkan secukupnya air, lalu beri guka, garam, merica bubuk dan kecap manis, aduk rata,tes rasa,, masak hingga mendidih dan bumbu meresap,,sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(903, 4, 'Sop Kambing Kuah Putih #KitaBerbagi', 'Sop Kambing Kuah Putih #KitaBerbagi dengan daging kambing empuk tanpa bau prengus.', '[\"500 gram daging & tulang kambing\", \"1,5 liter air\", \"300 ml susu Ultra Plain\", \"1 sachet kecil susu bubuk Dancow (putih)\", \"5 siung bawang merah, dirajang tipis\", \"3 siung bawang putih, dirajang tipis\", \"3 cm jahe, digeprek\", \"5 cm kayumanis\", \"5 butir kapulaga\", \"5 biji cengkeh\", \"1/2 butir biji pala, diparut\", \"1/2 sdt merica bubuk\", \"1 sdt gula merah\", \"secukupnya garam\", \"minyak & margarin\", \"Pelengkap:\", \"1 buah tomat merah segar, potong sesuai selera\", \"daun bawang & seledri sbg taburan\", \"kripik emping\", \"acar timun, wortel, bawang merah, rawit hijau\", \"(aku gaa sempat buat acar nya 😉)\", \"bawang merah goreng utk taburan di nasi biar wangi 😍\", \"bisa juga siapin potongan jeruk nipis jika mau ada rasa kecut2\"]', '[\"Rebus daging & tulang kambing dgn air 1,5 liter sampai empuk. jika sudah empuk sisihkan sisa air rebusan (disaring yaa...)\", \"Panaskan wajan, tuang minyak & margarin, tumis bawang putih, bawang merah dan jahe.\", \"Setelah tercium aroma wangi, tambahkan air sisa rebusan tadi kemudian masukkan kayumanis, kapulaga, cengkeh, merica dan biji pala. setelah mendidih masukkan susu cair dan susu bubuk. aduk terus.\", \"Jika susu sdh tercampur masukkan daging dan tulang kambing. masak lagi sampai mendidih.\", \"Tambahkan garam dan gula merah. koreksi rasa, jika sudah pas matikan kompor sambil terus diaduk (kira2 10 detik)\", \"Siapkan wadah Sop, masukkan potongan tomat kemudian tuang Sopnya, taburi daun bawang dan seledri juga kripik emping.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(904, 2, 'Sate kambing sedehana', 'Sajian Sate kambing sedehana yang praktis dan lezat untuk dinikmati bersama.', '[\"1 kg daging kambing dipotong kecil2 dan ditaruh diwadah\", \"3 lembar daun pepaya untuk membungkus daging\", \"Bumbu yang dihaluskan :\", \"8 siung bawang putih\", \"2 sdt ketumbar\", \"secukupnya Garam\", \"secukupnya Gula jawa\", \"Bahan pencelup sate\", \"3 sdm margarine\", \"secukupnya Kecap manis\", \"Bahan pelengkap sate\", \"4 buah tomat potong kotak kecil\", \"secukupnya Cabe rawit hijau\", \"secukupnya Lada\", \"5 siung bawang merah diiris tipis\", \"secukupnya Kecap\", \"secukupnya Ketimun, dan selada\", \"secukupnya Lidi untuk sate\"]', '[\"Taruh potongan daging dlm wadah dan di alasi daun pepaya lalu tutup dengan daun pepaya diamkan selama kurleb 30 smp 60 menit\", \"Haluskan bawang putih, ketumbar, garam dan gula jawa, balurkan keseluruh daging yg sudah didiamkan td diamkan lg kurleb 15 menit smp bumbu meresap, lalu tusuk daging...\", \"Bakar setengah matang, angkat balurkan ke dalam bahan pencelup bakar lagi hingga matang\", \"Sate siap dihidangkan bersama pelengkapnya..\", \"Selamat mencoba 😘😘😘\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(905, 2, 'Kambing oven', 'Resep Kambing oven ala rumahan yang dijamin menggugah selera.', '[\"1 bagian paha kambing\", \"8 bh bawang putih\", \"1 ruas jahe\", \"8 sdm kecap manis (bs dtambah kalo kurang manis dan coklat)\", \"secukupnya merica\", \"secukupnya garam\", \"secukupnya gula pasir\", \"100 ml minyak goreng\", \"5 sdm blueband (sy pke forvita)\", \"1 lt air\"]', '[\"Cuci bersih daging potong beberapa bagian sedang (sy jadi 5 bagian) sambil ditusuk tusuk (lebih enak kalo dagingnya masih fresh y..belum masuk kulkas)\", \"Haluskan bumbu bawang putih,jahe,merica,gula,garam. campur bumbu halus dengan minyak dan kecap\", \"Lumurkan ke daging smpai merata kemudian diamkan ke dalam kulkas minimal 1 jam agar bumbu meresap\", \"Siapkan panci presto atau panci biasa jg boleh..masukkan daging beserta bumbu dan tambahkan margarin..tutup rapat. kalau panci presto kurang lebih 15 menit saja.kalo pake panci biasa tggu hingga empuk\", \"Angkat daging dan saring sisa bumbu di panci kemudian masing2 bagian dan bumbu dibungkus dengan alumunium foil\", \"Panggang dengan oven atau dengan happycall sampai dirasa kering bumbu didalamnya\", \"Siap dinikmati...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(906, 2, 'Sate kambing teflon', 'Sate kambing teflon dengan daging kambing empuk tanpa bau prengus.', '[\"250 gram daging kambing\", \"bumbu halus:\", \"3 siung bawang putih\", \"1 sdt ketumbar\", \"1/2 sdt merica\", \"sambal:\", \"kecap\", \"2 siung bawang merah\", \"3 cabai setan\", \"1 sdt minyak goreng\", \"secukupnya garam\", \"kubis\"]', '[\"Iris daging kecil2 sesuai selera, kemudian cuci. Haluskan bawang putih,ketumbar,merica kmudian lumuri pada daging sertakan sdikit kecap,minyak dan garam pada daging. Campur hingga rata boleh beri sedikit air agar mudah mencampurkannya.\", \"Diamkan daging 30 mnt di dalam kulkas agar meresap.\", \"Sambil menunggu, buat sambal kecapnya. Caranya campur secukupnya kecap dg irisan bawang merah dan cabai. Aduk2, sisihkan. Untuk topping lgs sj iris tipis kubis yg sudah d cuci bersih\", \"Setelah 30 mnt, ambil daging dlm kulkas. Panaskan teflon. Stlh pnas masukan daging tsb. Kl teflonnya rata blh pake tusuk sate ya. Masukan daging ktika teflon sdh pns. Jgn lp d balik. Angkat ktka sudah berbau wangi dan daging sudah berubah warna\", \"Angkat dan tiriskan. Campur pada topping dan sambal kecap td. Cocok jg d tmbhkn nasi panas yg ditabur lada bubuk 😍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(907, 3, 'Kambing guling', 'Resep Kambing guling yang lezat dan mudah dibuat di rumah.', '[\"sesuai selera Daging kambing\", \"Secukupnya Kecap manis\", \"Bumbu\", \"7 siung bawang putih\", \"3 siung bawang merah\", \"3 cm jahe\", \"2 sdt ketumbar\", \"1/2 sdm garam\", \"Bahan sambal\", \"6 buah Cabe rawit\", \"2 buah cabe keriting\", \"1 butir Jeruk nipis\", \"1 buah tomat kecil\", \"Secukupnya Kecap manis\"]', '[\"Blender bumbu halus, bagi 2 wadah\", \"1 wadah untuk rebus 1 wadah untuk bumbu oles\", \"Masukaan daging dgn bumbu halus tunggu sampai benar2 empuk\", \"Jika sudah empuk angkat daging iris dadu sesuai selera masukkan kedalam bumbu halus yg wadah satunya tambah kecap manis\", \"Tunggu sampai 1jam\", \"Jika suka panggang di teflon kasih margarin sedikit\", \"Bikin sambalnya iris semua tambah kecap dan perasan jeruk nipis\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(908, 2, 'Sate kambing empukk', 'Sajian Sate kambing empukk yang praktis dan lezat untuk dinikmati bersama.', '[\"Daging kambing ( jgn dicuci d potong dadu di taro daun pepaya\", \"2 buah nanas parut\", \"Tusuk sate kambing(beda sama tusuk sate ayam yaa)\", \"Bumbu olesan bakar:\", \"Kecap\", \"Margarin(blueband)\", \"iris Bawang merah\", \"Bumbu kacang:\", \"8 Bawang merah\", \"250 gr Kacang tanah goreng n d blender\", \"6 bawang putih\", \"4 Kemiri\", \"Garam secukupny\", \"Kecap secukupny\", \"Acar:\", \"Timun\", \"Wortel\", \"2 buah nanas potong dadu.(biar ada manis asemny)\", \"5 Bawang merah potong dadu\", \"10 cabe rawit (inilah kejutanny tmbh mantab)\", \"4 tomat potong dadu\", \"Cuka\", \"dikit Garam\", \"dikit Gula pasir\", \"secukupnya Jeruk limo\"]', '[\"Taruh daging diatas daun pepaya, tidak di cuci spya sedappp (kta jiddah ini supaya dagingnya empuk)dagingny ga tau berapa kg jdiny krg lbih 100 tusuk.\", \"Potong daging kya dadu masukan ke tusuk sate kira2 4/5 tusuk ya)\", \"Sebelum dibakar lumuri daging dengan nanas parut agar wangi n jd empukk\", \"Bakar daging kambing dengan bumbu olesan kecap n blue band...hmmm wanginya menyebar kmna2\", \"Bumbu kacang: tumis bumbu halus bawang putih dan kemiri masukan kacang yg sdh d blender tmbh garam n gula..tmbh kecap n perasan jeruk limo deh\", \"Acar: potong dadu kecil kecil timun, wortel, bawang merah, cabe rawit tomat masukan cuka garam n gula aduk rata..klo sy cabe di pisah coz ad anak kecil n si abang ga ska pedas..itu buat emaknya..hee..\", \"Sajikan sate.bumbu kacang n acar..dgn nasi hangatt..\", \"Komentar si abang itu satenya enakk..empukk...iyalah siapa dlu yg ngipas..he..he abii ga mau kalah😅😅\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(909, 4, 'Tongseng daging sapi/kambing#kitaberbagi', 'Tongseng daging sapi/kambing#kitaberbagi dengan daging kambing empuk tanpa bau prengus.', '[\"500 gr daging sapi/kambing di potong-potong kecil\", \"1500 ml air\", \"4 lembar daun salam\", \"2 batang sereh\", \"4 lembar daun jeruk\", \"secukupnya Garam dan kaldu sapi bubuk\", \"1/2 sdm gula merah\", \"1 sdm bawang merah goreng utk taburan\", \"3 lembar kol di iris kasar\", \"2 batang daun bawang di iris kasar\", \"1 buah tomat jika suka di potong2\", \"bumbu halus :\", \"10 siung bawang merah\", \"4 siung bawang putih\", \"4 butir kemiri\", \"1 ruas jari jahe\", \"1 ruas jari kunyit\", \"1/2 sdt merica butiran\"]', '[\"Tumis bumbu halus hingga harum dan matang Masukkan daging, aduk hingga berubah warna\", \"Masukkan air dan semua bumbu lain Masak hingga mendidih, koreksi rasa Tutup panci, masak api kecil sekitar 1/2 hingga 1 jam, kalau aku 1 jam, soalnya suka dagingnya empuk.\", \"Jika daging sudah empuk, buka panci, masukkan bawang goreng, kol dan daun bawang serta cabe merah utuh, masak sebentar hingga meresap dan kuah menyusut, nyemek gitu. Jika pakai tomat, masukkan juga tomat iris.\", \"Tongseng siap utk di hidangkan 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(910, 2, 'Sate Kambing Mantap', 'Sajian kambing spesial: Sate Kambing Mantap yang menggugah selera.', '[\"1/2 Kg Daging Kambing (bisa + sedikit jambal)\", \"Bumbu halus :\", \"1/2 sdt jintan\", \"1/2 sdt ketumbar\", \"1/2 sdt merica\", \"Masing-masing 2 cm jahe, lengkuas, kunyit\", \"3 siung Bawang putih\", \"3 siung Bawang merah\", \"Secukupnya daun jeruk, gula merah, garam, air\", \"Secukupnya kecap manis\"]', '[\"Cuci bersih daging lalu potong kecil2. Bisa langsung rendam dlm bumbu halus/ rendam dulu dng parutan nanas muda/soda/daun pepaya agar lbh empuk.\", \"Setelah di rendam dlm bumbu halus tusuk2 satenya lalu panggang hingga setengah matang. Celupkan lagi kedalam bumbu halus lalu panggang lagi. Terakhir setelah hampir matang balurkan kecap manis lalu bakar sebentar.\", \"Sajikan bersama kecap, irisan tomat, cabai dan bawang merah. Selamat Menikmati\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(911, 3, 'Sop kepala kambing #kitaberbagi', 'Nikmati kelezatan Sop kepala kambing #kitaberbagi dengan resep sederhana ini.', '[\"Jahe,kapulaga&cengkeh untuk merebus tulangan\", \"1 buah tulangan kepala kambing yg dbelah jdi 3-4 bagian\", \"Bumbu halus:\", \"7 siung bawang merah\", \"4 siung bawang putih\", \"1 sdm merica\", \"2 butir kemiri\", \"Seledri&daun bawang sckpnya\", \"Garam&penyedap,sckpnya\", \"Goreng bawang(optional)\"]', '[\"Rebus tulangan kepala dg jahe yg dgeprek,kapulaga&daun salam sckpnya sampe daging2nya empuk(saya ga pke presto jdi hrs sabar).Ini bukan perebusan pertama karna sblmnya kepala kambing sudah drebus mateng sblm kulit kepalanya diambil jadi perebusan yg skrg biar empuk sampe copot2 sisa dagingnya dari tulangan.\", \"Ulek bumbu halus,tumis sampai harum kemudian masukan kdlm rebusan tulangan tadi.Koreksi rasa,masukan potongan daun bawang&seledri kemudian matikan api.Siap disajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(912, 3, '#KitaBerbagi tips mengurangi bau khas kambing', 'Cara membuat #KitaBerbagi tips mengurangi bau khas kambing yang enak dan praktis untuk keluarga.', '[\"1/2 kg daging kambing\", \"1 buah biji pala\", \"2 cm jahe\", \"3 lembar salam\", \"5 lembar daun jeruk\", \"Serai, kayu manis (optional) stok dirumah kosong 😅\", \"Air\"]', '[\"Rebus air dengan semua bahan polowijo (bumbu yg aromax kuat) di memarkan sampai mendidih\", \"Masukkan daging kambing, lama memasak sampai daging dirasa empuk\", \"Tiriskan, masukkan kulkas. Kalau butuh daging siap di olah ya moms... 😊\", \"Semoga bermanfaat dan bisa mengurangi bauk kambing\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(913, 4, 'Gule iga kambing #KitaBerbagi', 'Sajian Gule iga kambing #KitaBerbagi yang praktis dan lezat untuk dinikmati bersama.', '[\"800 gr iga kambing (adanya segitu)\", \"2 batang sereh\", \"3 lembar daun salam\", \"3 buah cengkeh\", \"4 cm kayu manis\", \"3 lembar daun jeruk\", \"1 tangkai daun kari\", \"1 bungkus santan kara 65ml\", \"secukupnya gula,garam,penyedap\", \"bawang goreng\", \"sesuai selera cabai rawit merah utuh\", \"bumbu halus :\", \"6 buah bawang merah\", \"4 buah bawang putih\", \"3 cm lengkuas\", \"3 cm kunyit\", \"3 cm jahe\", \"1 sdt jinten\", \"4 buah kemiri\", \"2 sdt ketumbar\"]', '[\"Rebus iga kambing sampai empuk,atau presto untuk mempersingkat waktu\", \"Tumis bumbu halus bersama bumbu lainnya sampai harum, tambahkan iga bersama air rebusan iga,tambahkan air lg jika perlu\", \"Tambahkan gula,garam,dan penyedap(jika suka).lalu tambahkan santan,\", \"Setelah matang taburi gule dgn bawang goreng,siap dinikmati dgn nasi hangat. bisa juga tambahkan kecap dan jeruk nipis jika suka\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(914, 3, 'Lodeh pepaya (campur tahu + daging kambing)', 'Sajian kambing spesial: Lodeh pepaya (campur tahu + daging kambing) yang menggugah selera.', '[\"1/4 kg daging kambing\", \"1 buah pepaya muda\", \"5 siung bawang merah + putih\", \"1 ruas lengkuas geprek\", \"3 lembar daun salam\", \"5 butir kemiri\", \"5 buah cabe rawit\", \"secukupnya ebi\", \"1/2 butir kelapa (peras, ambil santanya)\", \"Secukupnya gul+gar\"]', '[\"Rebus dulu daging smp empuk, buang airnya. Potong tahu kecil2, kalemudian goreng setengah matang\", \"Haluskan smw bumbu, kemudian rebus air, masukan lgi daging yang sudah dipotong kecil2 + pepaya, selanjutnya masukan bumbu yg sudah halus\", \"Tambahkan santan, tahu, lengkuas, gul+ gar dan daun salam, yg terakhir koreksi rasa\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(915, 4, 'Sate Kambing #kitaberbagi', 'Sate Kambing #kitaberbagi dengan daging kambing empuk tanpa bau prengus.', '[\"300 gram daging kambing\", \"1 sdt nanas parut\", \"secukupnya Gula\", \"secukupnya Garam\", \"secukupnya Kecap manis\", \"Bumbu halus:\", \"2 siung bawang putih\", \"3 buah bawang merah\", \"1/2 sdm ketumbar\", \"2 kemiri\", \"Sambal kecap:\", \"6 buah cabe merah kecil, potong2\", \"3 buah cabe hijau kecil potong2\", \"2 buah bawang merah, potong2\", \"Secukupnya kecap manis\"]', '[\"Potong dadu kecil daging kambing, lumuri dengan 1 sdt nanas parut, diamkan 20 menit (misal skip langkah melumuri nanas ini juga tdk apa2 cuma daging tidak akan seempuk jika dilumuri nanas parut)\", \"Haluskan bumbu, siram kedalam daging campur sampai rata diamkan 20-30 menit agar bumbu meresap. Ambil tusuk sate, tusukkan daging 4-5 potong daging.\", \"Panggang/bakar sampai matang\", \"Angkat, hidangkan dengan sambal kecap\", \"Sambal kecap: aduk semua bahan jadi satu, hidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(916, 3, 'Sate Kambing empuk', 'Sajian kambing spesial: Sate Kambing empuk yang menggugah selera.', '[\"1 kg Daging kambing\", \"1 sdm Ketumbar\", \"5 siung Bawang putih\", \"3 sdt Merica\", \"1 sdt Garam\", \"3 lembar Daun pepaya\", \"1 buah Tomat\", \"1 buah Bawang merah\", \"secukupnya Cabe merah dan rawit\", \"secukupnya Kecap manis dan margarin\"]', '[\"Daging kambing jangan dicuci, potong-potong, daging ditutup (dibungkus) dengan daun pepaya selama 1 jam\", \"Ulek merica, ketumbar, bawang putih. Balurkan ke daging kambing, tunggu marinasi selama 1 jam (dengan masih ditutup daun pepaya)\", \"Siapkan sambal kecap, bawang merah, tomat, cabe rawit dan merah. Dipotong kecil-kecil. Masukkan kecap\", \"Setelah 2 jam, sate kambing siap dibakar, ketika dibakar dilumuri mentega dan kecap, agar makin enak.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(917, 4, 'Gule Kambing #KitaBerbagi', 'Resep Gule Kambing #KitaBerbagi ala rumahan yang dijamin menggugah selera.', '[\"500 gr daging kambing campur dgn daging yg ada tulangnya\", \"1 liter santan sedang\", \"2 batang serai, ambil putihnya memarkan\", \"5 lembar daun jeruk remas”\", \"1 telunjuk jari kayu manis\", \"4 butir cengkeh (boleh tidak pakai)\", \"Secukupnya air untuk merebus daging\", \"Secukupnya garam, gula, kaldu bubuk\", \"Secukupnya minyak goreng untuk menumis\", \"Secukupnya bawang merah goreng dan bawang merah goreng\", \"✒ Bumbu Halus:👇\", \"8 siung bawang putih\", \"12 butir bawang merah\", \"1 sdm ketumbar\", \"1 sdt merica butiran\", \"1/4 sdt jinten\", \"1 ruas jahe\", \"1 telunjuk jari kunyit\"]', '[\"Cuci bersih daging lalu tiriskan. Rebus air sampai mendidih lalu masukkan daging, masak daging sampai​empuk.\", \"Sambil menunggu daging empuk, tumis bumbu halus tambahkan sere,daun jeruk,kayu manis, tumis sampai bumbu harum dan benar\\\" matang.\", \"Bila daging sdh empuk, angkat dan tiriskan lalu potong\\\" sesuai selera.\", \"Rebus kaldu daging kambing sampai mendidih lalu masukkan santan dan bumbu masak sampai mendidih masukkan daging, garam, dan kaldu bubuk bila suka masak sampai mendidih dan kuah menyusut tes rasa bila sudah pas tambahkan bawang putih goreng, masak sampai matang, matikan api lalu taburi dengan bawang goreng merah.\", \"Gule kambing siap dihidangkan bersama nasi hangat atau lontong dan sambal kecap serta acar timun.lezatoz\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(918, 4, 'Iga Kambing Bakar Mercon (Teflon)', 'Nikmati kelezatan Iga Kambing Bakar Mercon (Teflon) dengan resep sederhana ini.', '[\"500 gram iga kambing (potong sesuai selera)\", \"1 buah bawang bombay (cincang halus)\", \"Secukupnya air\", \"Secukupnya kecap manis\", \"1/5 garam\", \"1/5 merica bubuk hitam\", \"1/5 gula pasir\", \"1 jeruk nipis\", \"3 sdm minyak goreng (utk menumis)\", \"bumbu ulek kasar:\", \"10-12 cabe orange\", \"4 siung bawang putih\", \"3 cm jahe kurang lebih\"]', '[\"Rebus air sampai mendidih, masukan iga kambing biarkan 10 menit agar daging empuk, tp jgn terlalu lama jg nanti ancur, jika sudah tiriskan\", \"Panaskan minyak goreng lalu tumis bumbu kasar di tambah bawang bombay yg sudah di potong halus, tumis sampai bumbu wangi\", \"Masukan iga kambing yg sudah di tiriskan tadi, masak aduk rata hingga berubah warna\", \"Tambahkan kecap manis, garam, merica bubuk hitam, gula dan air. Masak hingga matang dan bumbu meresap ke daging\", \"Tambahkan perasan air jeruk nipis kedalamnya, aduk rata\", \"Siapkan panggangan / pakai teflon bisa bakar iga bakar satu persatu ke panggangan / teflon hingga berubah warna kecoklatan sambil sekali di olesi bumbu yg di masak tadi dan olesi kecap manis, jika sekiranya sudah matang bisa angkat dan sajikan di wadah\", \"Setelah sudah di sajikan di wadah piring, siram saos mercon di atas iga kambingnya yg tadi di tumis sebelumnya, lalu nikmati bersama keluarga tercintamu ya\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(919, 3, 'Kambing (Krengsengan)', 'Kambing (Krengsengan) - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"Daging Kambing\", \"Bawang merah\", \"Bawang putih\", \"Cabe rawit\", \"Jahe\", \"Daun salam\", \"Daun jeruk\", \"Wortel\", \"Kubis\", \"tomat\", \"Kecap\", \"Garam\"]', '[\"Rebus daging kambing 2x (pertama 5menit, buang airnya kemudian isi air lagi dan masukan daging kambing lagi selama 1jam) sampai empuk\", \"Setelah daging empuk, tiriskan jika sudah dingin potong sesuai selera\", \"Siapkan bumbu\", \"Panaskan minyak 1 sendok makan, masukan bawang merah, bawang putih tunggu sampai harum\", \"Kemudian, masukan cabe, daun salam, daun jeruk dan jahe digeprek\", \"Tambahkan air kaldu (air rebusan daging tadi)\", \"Masukan garam, setelah itu masukan wortel tunggu sampai mendidih\", \"Setelah mendidih, masukan daging dan tambahkan air kaldu lagi aduk-aduk sampai rata masukan kubis, tomat dan kecap\", \"Icipi dan siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(920, 2, 'Gulai daging sapi/kambing', 'Cara membuat Gulai daging sapi/kambing yang enak dan praktis untuk keluarga.', '[\"1 kg daging sapi/kambing\", \"2 batang serai\", \"5 lb daun salam\", \"5 lb daun jeruk\", \"1 ibu jari lengkuas geprek\", \"2 bh cengkeh\", \"1 ruas jahe geprek\", \"1 helai batang daun kari\", \"1/2 btr Santan kental dari  kelapa\", \"secukupnya Gula, garam, dan penyedap rasa\", \"Bumbu halus :\", \"6 siung bawang merah\", \"4 siung bawang putih\", \"3 butir kemiri\", \"1 ruas kunir\", \"1/4 sdt pala bubuk\", \"1/2 sdt merica\"]', '[\"Rebus daging sapi bersama jahe hingga lunak, lebih baik pakai panci presto. Setelah empuk potong2 daging sapi/kambing. Air sisa rebusan boleh dibuang kalo dirasa masih prengus trus diganti air biasa, kalau saya air sisa rebusannya saya pakai lagi.\", \"Tumis bumbu halus hingga harum.\", \"Masukan bumbu halus ke dalam air sisa rebusan daging.\", \"Masukan kembali daging yg telah dipotong2.\", \"Masukan daun salam, daun jeruk, daun kari, lengkuas, kayu manis, dan cengkeh.\", \"Tambahkan santan kental sesuai selera/secukupnya.\", \"Tambahkan gula garam dan penyedap rasa secukupnya.\", \"Masak hingga bumbu2 meresap.\", \"Icipi rasa, bila sudah pas, matikan api, pindahkan ke mangkok saji, sajikan dengan taburan bawang goreng dan sambal kecap.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(921, 4, 'Sate kambing #kita berbagi', 'Cara membuat Sate kambing #kita berbagi yang enak dan praktis untuk keluarga.', '[\"500 gram daging kambing\", \"7 butir bawang merah\", \"1 sdm ketumbar\", \"1 sdt garam\", \"4 buah gula merah\", \"1 buah asem\"]', '[\"Iris2 daging. Sisihkan\", \"Haluskan bawang merah, ketumbar, garam, asem, dan gula merah. Campur daging dg bumbu. Diamkan 15 menit. Kemudian tusuk2 daging.\", \"Siapkan api (pakai arang atau teflon sesuai keadaan saja. Shuka-shuka)\", \"Bakar hingga matang. Dibolak balik ya....Sajikan bersama tomat, bawang merah, cabai, kecap, merica dan kol.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(922, 2, 'Daging Kambing Saus Teriyaki #KitaBerbagi', 'Daging Kambing Saus Teriyaki #KitaBerbagi dengan daging kambing empuk tanpa bau prengus.', '[\"250 gram daging kambing yang sudah direbus hingga matang\", \"3 sdm saos teriyaki\", \"1 sdt garam\", \"1/4 sdt lada\", \"1/2 bawang bombay\", \"3 siung bawang putih\", \"1 siung bawang merah\", \"1 batang bawang pre\", \"1 sdm kecap\", \"550 ml air\", \"3 sdm minyak goreng\"]', '[\"Iris kecil kecil bawang bawang tadi\", \"Tumis bawang merah dan putih sampai harum\", \"Masukkan bawang bombay tumis sampai harum\", \"Masukkan daging lalu tumis 2 menit\", \"Masukkan daun bawang dan tumis hingga harum\", \"Masukkan air dan bumbu bumbu lalu aduk hingga merata. Sekaligus mencicipi air yg telah bercampur bumbu, silahkan atur bumbunya sesuai selera.\", \"Ungkep atau tutup wajan hingga airnya tinggal sedikit dan agak mengental. Maka sudah siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(923, 4, 'Sate kambing muda ala mama nino', 'Sate kambing muda ala mama nino - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1.2 kg daging kambing bagian paha\", \"6 siung bawang merah,\", \"3 siung bawang putih,\", \"3 biji kemiri,\", \"1 sendok makan  ketumbar,\", \"secukupnya garam .\", \"secukupnya kecap\", \"10 buah cabe rawit  iris kecil.\", \"6 siung Bawang merah iris kecil.\", \"1 buah  tomat\"]', '[\"1.2 kg daging potong segiempat ukuran dikira2 saja kurang lebih 3x3 cm\", \"Rendam daging selama 30 menit dengan bubuk paya (pengempuk daging). Bubuk paya yang digunakan 2 sendok makan. Aduk dan remas2 daging dengan bubuk paya. Lalu diamkan 30 menit\", \"Sementara daging didiamkan, ulek bumbu 6 bawang merah, 3 bawang putih, 3 kemiri, 1 sendok makan ketumbar, garam secukupnya.\", \"Setelah daging selesai didiamkan, cuci bersih daging dengan air.\", \"Lalu campurkan bumbu ulek dengan daging yang sudah dicuci. Remas2 dan aduk rata. Lalu diamkan 20 menit.\", \"Tambahkan kecap secukupnya.\", \"Daging siap dibakar. Kalau saya kebetulan blm beli arang jd saya panggang menggunakan happy call tevlon.\", \"Buat bumbu kecap dengan campuran cabe rawit 10 buah iris kecil. 6 Bawang merah iris kecil. 1 buah tomat potong2 kecil.\", \"Sate kambing muda ala mama nino siap disantap.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(924, 2, 'Sop kambing betawi #kitaberbagi', 'Nikmati kelezatan Sop kambing betawi #kitaberbagi dengan resep sederhana ini.', '[\"1/2 kg daging kambing (jeroan dan tulang2an)\", \"1 gelas susu full fat/1 kara\", \"5 batang Daun serai\", \"5 lembar daun jeruk\", \"1 ruas ibu jari jahe\", \"7 siung bawang putih\", \"7 siung bawang merah\", \"5 buah kemiri\", \"1 SDM lada\", \"1 ruas kelingking kayu manis\", \"4 buah kapulaga\", \"1 1/2 liter air\", \"1/2 buah pala\", \"secukupnya Garam\", \"1 SDT gula (optional)\", \"Pelengkap\", \"3 buah daun bawang\", \"2 buah kentang\", \"1/4 kg emping\", \"sesuai selera Sambal\", \"secukupnya Kecap\", \"1 buah jeruk nipis\"]', '[\"Bersihkan daging, dan rebus hingga empuk, masukan kapulaga, kayu manis daun salam kedalam rebusan daging\", \"Haluskan bumbu yang di beri tanda bintang, dan tumis hingga harum\", \"Jika daging sudah empuk, masukan bumbu yg sudah dihaluskan, masukan juga susu atau santan\", \"Koreksi rasa beri garam, dan gula (optional)\", \"Jika sudah matang sediakan dengan pelengkapnya 😊😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(925, 3, 'Gulai kambing #kitaBerbagi', 'Cara membuat Gulai kambing #kitaBerbagi yang enak dan praktis untuk keluarga.', '[\"0,5 kg daging kambing\", \"Bahan alung untuk merebus:\", \"1 buah kayu manis\", \"3 buah kapulaga\", \"3 buah bunga lawang\", \"2 ruas lengkuas\", \"1 batang sereh\", \"2 lembar daun salam\", \"3 buah cengkeh\", \"Bahan halus :\", \"3 siung bawang merah\", \"3 buah cabai tanjung\", \"3 buah cabai rawit\", \"0,5 sdt ketumbar\", \"0,5 sdt merica\", \"2 ruas kunir\", \"1 ruas jahe\", \"3 butir kemiri\", \"2 bungkus santan kara\"]', '[\"Rebus daging hingga setengah matang dengan bahan Alung, angkat lalu potong dadu lalu rebus kembali hingga matang\", \"Haluskan bumbu, lalu masukan bumbu ke rebusan daging, masak hingga matang (saya masak 2 jam supaya bau kambing hilang dan bumbu menyerap sempurna)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(926, 2, 'Penyetan empal daging kambing ala kadarnya', 'Resep Penyetan empal daging kambing ala kadarnya ala rumahan yang dijamin menggugah selera.', '[\"500 gr daging kambing\", \"bumbu halus :\", \"3 bawang putih\", \"1 ruas kunyit\", \"2 sdt ketumbar\", \"secukupnya garam\", \"4 lbr daun jeruk\", \"2 lbr daun salam\", \"Secukupnya gula merah\", \"bahan sambal :\", \"6 siung bawang putih\", \"20 buah cabe kecil\", \"pelengkap :\", \"1 bungkus tahu sutra\", \"1 bungkus tempe\", \"sesuai selera daun selada sbgai hiasan (karna gak ada timun, hehehe)\"]', '[\"Daging kambing bersihkan kemudian rebus sebentar kurang lebih 30 menit. Setelah itu angkat tiriskan (supaya daging tdk tllu menyusut). Kemudian potong iris tipis tipis.\", \"Daging yg sdh sy iris tipis2...sy pukul2 lagi pke cobek/uleg2 untuk mempersingkat waktu. (Mauu keluarin presto lgi malas nyuci berat2).\", \"Masukkan bumbu halus kedalam panci, lalu tambahkan air sedikit saja..kira2 daging tsb terendam bumbu, tambahkan daun jeruk dan daun salam (mengurangi bau). Rebus sekali lagi dgn api sangat kecil..sampai airnya menyusut. Setelah menyusut angkat dan tiriskan. Bisa disimpan dkulkas, klo lagi pgen tinggal goreng.\", \"Tambahkan tahu tempe beserta selada cantik sbgai lalapan...jadii deh selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(927, 3, 'Gulai Daging Kambing 1st Cook #KitaBerbagi', 'Gulai Daging Kambing 1st Cook #KitaBerbagi - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"500 gram daging kambing dan tulang an (potong sesuai selera)\", \"1 1/2 liter air\", \"2 kemasan santan instan\", \"Bumbu Halus :\", \"8 butir bawang merah\", \"5 siung bawang putih\", \"10 buah cabai merah\", \"2 sdt ketumbar\", \"1 sdt merica butiran\", \"1/2 butir pala\", \"1/4 sdt jinten\", \"2 ruas kunyit (bakar sebentar)\", \"2 ruas jahe\", \"Bumbu Lain :\", \"2 ruas lengkuas (geprek)\", \"2 btg sereh (ambil putihnya, geprek)\", \"4 lembar daun salam\", \"3 lembar daun jeruk (sobek kasar)\", \"3 butir cengkeh\", \"1 buah kayu manis (boleh skip)\", \"2 butir kapulaga\", \"2 butir kembang lawang\", \"Secukupnya garam\", \"Secukupnya gula pasir\", \"Secukupnya kecap\", \"Secukupnya kaldu bubuk\"]', '[\"Rebus daging smp cukup empuk (aq rebus pakai panci presto, 1/2 jam udh cukup empuk)\", \"Jika tdk ingin direbus dlu, daging bs lgsg ditumis bersama bumbu halus)\", \"Panaskan minyak, tumis bumbu halus sampai harum. Aduk2 agar tidak gosong.\", \"Masukkan bumbu lain kecuali kecap. Aduk rata.\", \"Masukkan potongan daging, tumis sebentar hingga daging berubah warna (jika daging tdk direbus). Sisihkan.\", \"Didihkan air. Masukkan tumisan bumbu dan daging kedalam rebusan air. Masak hingga daging matang dan kuah mendidih.\", \"Masukkan santan dan kecap. Aduk rata.\", \"Masak hingga santan matang. Aduk sesekali agar santan tidak pecah.\", \"Jika sudah terlihat berminyak dan mengental, koreksi rasa.\", \"Jika sudah pas rasa nya, angkat dan sajikan.\", \"Tambahkan taburan bawang goreng sebagai pelengkap.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(928, 2, 'Gulai Daging Kambing #kitaberbagi', 'Nikmati kelezatan Gulai Daging Kambing #kitaberbagi dengan resep sederhana ini.', '[\"200 gr daging kambing di potong dadu\", \"Rempah-rempah :\", \"2 buah sereh di geprek\", \"2 ruas lengkuas di geprek\", \"2 ruas jahe di geprek\", \"2 butir kapulaga ambil isinya\", \"2 buah kembang lawang\", \"3 butir cengkeh\", \"1 batang kayu manis\", \"3 lembar daun salam\", \"300 ml santan encer\", \"bumbu halus :\", \"10 siung bawang merah\", \"5 siung bawang putih\", \"2 butir kemiri\", \"1 sdt lada\", \"1 sdt jinten\", \"1/4 biji pala\", \"1 ruas kunyit\", \"5 buah cabe merah\", \"1/2 sdt ketumbar\", \"secukupnya gula garam\", \"1 buah tomat dan bawang goreng irisan\"]', '[\"Tumis bumbu halus bersama dengan rempah-rempah hingga wangi, tambahkan daging kambing dan aduk sampai bumbu merata dan berubah warna.\", \"Didihkan air 500ml, masukan daging yang sudah di bumbui, aduk hingga mendidih. kemudian tambahkan santan, aduk terus sampai mendidih dan minyak dari santan keluar.\", \"Tes rasa dan sajikan bersama irisan tomat dan bawang goreng.\", \"Tips : agar daging empuk dan tidak prengus saya biasanya menggunakan perasan jeruk nipis atau lemon, rendam lebih lama, saya suka inapkan di dalam kulkas. Dan menurut yang pernah saya baca bahwa daging kambing tidak perlu di cuci dulu, agar tidak alot dan bau. tapi saya menggantinya dengan langsung merebusnya beberapa kali setelah di rendam air jeruk nipis.\", \"Tips : memasak tongseng dari gulai kambing adalah tumis bawang merah dan irisan cabai hingga wangi kemudian masukan gulai kambing, tambahkan gula merah dan kecap. bila kurang asin boleh tambah garam. setelah mendidih masukan irisan kol, masak hingga agak layu. sajikan bersama irisan tomat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(929, 3, 'Oseng Iga Kambing Pedas', 'Resep Oseng Iga Kambing Pedas yang lezat dan mudah dibuat di rumah.', '[\"250 gr daging kambing\", \"2 siung bawang putih\", \"2 siung bawang merah\", \"1 bawang bombay kecil\", \"10 cabai rawit\", \"2 sdm saos tomat\", \"3 sdm kecap manis\", \"1 buah tomat\", \"Secukupnya air\", \"Secukupnya penyedap\", \"Secukupnya garam\", \"Secukupnya merica\"]', '[\"Potong daging kambing sesuai selera dan bersihkan\", \"Cincang bawang putih dan bawang merah, iris bawang bombay\", \"Panaskan api, tumis bawang yang sudah dicincang hingga harum\", \"Masukan daging beri sedikit air\", \"Tambahkan saos, kecap, cabe rawit dan bumbui sesuai selera\", \"Beri perasan lemon dan irisan tomat\", \"Angkat dan sajikan, langsung dimakan pake nasi anget nyamm😆\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(930, 3, 'Tengkleng Daging Kambing #kitaberbagi', 'Tengkleng Daging Kambing #kitaberbagi - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"500 gr iga dan daging kambing (saya campur tulang)\", \"500 gr Jeroan (optional saja, saya tdk pake jeroan)\", \"1 potong Nanas  utk mengempukkan daging\", \"Dihaluskan :\", \"12 siung bawang merah\", \"6 siung bawang putih\", \"6 cm kunyit\", \"6 butir kemiri sangrai\", \"1 butir pala\", \"Dimemarkan :\", \"4 cm jahe\", \"4 cm lengkuas\", \"2 batang serai\", \"Bumbu lainnya :\", \"4 lembar daun jeruk (saya tambah biar prengusnya benar2 ilang)\", \"2 lembar daun salam\", \"3 cm kayu manis\", \"6 butir cengkeh\", \"1 liter air matang\", \"1 sachet santan instan\", \"secukupnya Garam\", \"secukupnya Minyak goreng\", \"secukupnya Kecap manis\"]', '[\"Hancurkan nanas dan balur ke daging, remas2 lalu diamkan 15-20 menit\", \"Cuci daging, lalu rebus dgn api besar 3 menit utk membersihkan kotoran. Buang busa dan airnya. Lalu cuci daging, dan cuci jg panci masaknya. Isi lg dengan air baru utk merebus daging dan tulangnya (saya ga perlu waktu lama, krn daging sdh empuk)\", \"Panaskan minyak didalam wajan, tumis bumbu-bumbu yg dimemarkan, kemudian bumbu halus dan bahan lainnya kecuali air matang, santan dan iga kambing, hingga harum.\", \"Masukkan iga kambing, kemudian aduk-aduk hingga terbalut bumbu merata.Tambahkan air matang kedalamnya, dan biarkan mendidih, kemudian kecilkan api dan masak iga kambing hingga menjadi empuk.\", \"Tambahkan garam dan kecap manis.\", \"Siap disajikan bersama irisan jeruk nipis dan bawang goreng.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(931, 3, 'Kambing Bumbu Sate', 'Kambing Bumbu Sate dengan daging kambing empuk tanpa bau prengus.', '[\"1/2 kg daging Kambing\", \"2 genggam kacang tanah\", \"6 siung bawang putih\", \"8 siung bawang merah\", \"3 biji kemiri\", \"sesuai selera madu (bisa di skip jika tidak ada)\", \"secukupnya  kecap\"]', '[\"Potong daging kambing kotak kotak. Lumuri madu, cuci (supaya cepat empuk).\", \"Iris bawang putih. goreng.sisihkan\", \"Iris bawang merah. kemiri.goreng.sisihkan\", \"Goreng kacang\", \"Campur kacang goreng, bawang putih goreng, bawang merah goreng, kemiri.tambahkan sedikit air. blender\", \"Tumis bumbu, tambahkan kecap dan daging.tutup wajan.masak api kecil.\", \"Kalau air susut tambahkan air sedikit. ulangi sampai daging empuk.tambahkan garam,dan koreksi rasa ☺\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(932, 3, 'Kambing teriyaki ala bunda liya', 'Kambing teriyaki ala bunda liya dengan daging kambing empuk tanpa bau prengus.', '[\"500 gram daging kambing jeroan dan tulang\", \"Secukupnya kecap manis\", \"bumbu iris :\", \"1/2 siung bawang bombay\", \"5 lombok merah\", \"2 lombok rawit setan\", \"bumbu halus :\", \"4 siung bawang putih\", \"8 siung bawang merah\", \"sejumput ketumbar\", \"sejumput merica\", \"sejumput jinten\", \"bumbu celup :\", \"3 lembar daun salam\", \"1 ruas laos\", \"1 batang serai\", \"1 ruas jahe\", \"1 ruas kunyit\"]', '[\"Rebus daging sisihkan\", \"Tumis bumbu halus..\", \"Masukkan bumbu celup\", \"Masukkan daging tambah air\", \"Tambahkan kecap garam gula\", \"Tes rasa\", \"Siap dihidangkan\", \"Note : saya lebih suka masak kambing direbus dulu pake serai salam laos jahe kunyit biar g bau prengus...dan selalu ditaburi brambang goreng...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(933, 4, 'Gulai Kambing Arab +tips mengolah daging kambing #KitaBerbagi', 'Buat Gulai Kambing Arab +tips mengolah daging kambing #KitaBerbagi yang nikmat dengan langkah-langkah mudah ini.', '[\"1 kg daging sapi/kambing\", \"1 resep garamasala\", \"1/4 kg bawang putih (½ kg utk yg hipertensi)\", \"3/4 kg bawang merah (resep asli 1kg)\", \"1/4 kg bawang bombay\", \"1-2 sdm ketumbar bubuk\", \"7 lembar daun jeruk\", \"7 lembar daun salam\", \"3 batang sereh, geprek\", \"secukupnya gula aren , sisir halus\", \"1 sdm air jeruk nipis\", \"3 liter air\", \"Bahan Garamasala:\", \"8 siung bawang putih\", \"12 siung bawang merah\", \"8 biji kemiri\", \"8 biji kapulaga\", \"1 sdt jintan bubuk\", \"1 sdt adas\", \"1/4 sdt cinnamon bubuk\", \"1 jempol lengkuas\", \"1/2 jempol jahe\", \"2 jari kunyit\", \"5 lembar daun salam\", \"3 batang sereh\"]', '[\"Cara membuat garam masala: Haluskan semua bahan kecuali salam dan sereh. Tumis sampe wangi. Masukkan salam+sereh, aduk rata. Angkat, siap digunakan atau dinginkan sampe suhu ruang lalu masukkan ke dalam wadah tertutup.\", \"Rebus air sampe mendidih, masukkan daging yang sudah dipotong2. Masak sampai agak empuk.\", \"Haluskan bawang, tumis bersama ketumbar. Tumis agak lama sampai warnanya kecoklatan dan aroma bawangnya hilang.\", \"Masukkan garamasala, aduk rata, kemudian masukkan semua bumbu ke panci berisi rebusan daging yg sudah agak empuk.\", \"Masukkan daun jeruk, salam, sereh.\", \"Masak sampai daging empuk.\", \"Tambahkan gula aren dan air jeruk nipis secukupnya. Aduk rata.\", \"Angkat, sajikan.\", \"Tips mengolah daging kambing : Setelah dipotong, daging kambing jangan dicuci dulu. Rebus air bersama sebatang lengkuas geprek. Masukkan daging kambing, rebus sekitar 5 menit. Angkat, buang airnya. Cuci bersih daging, siap diolah.\", \"Semoga bermanfaat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(934, 2, 'Nugget tempe', 'Nugget tempe - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 papan tempe dihaluskan(saya kukus dlu)\", \"1 buah wortel (parut kasar)\", \"2 batang daun bawang (di iris kasar)\", \"1 butir telur\", \"3 butir bawang merah (di iris lalu di goreng)\", \"3 butir bawang putih (di haluskan)\", \"5 sdm tepung terigu\", \"Secukupnya garam,lada & penyedap rasa\", \"secukupnya Tepung panir\", \"secukupnya Minyak goreng\"]', '[\"Campur tempe,wortel,daun bawang & bumbu yg sudah dihaluskan,beri garam,lada & penyedap rasa,tes rasa lalu masukkan telur\", \"Bentuk adonan sesuai selera lalu gulingkan di tepung panir\", \"Goreng hingga matang\", \"Sajikan dengan saos sambal\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(935, 4, 'Tempe tepung sajiku', 'Resep Tempe tepung sajiku ala rumahan yang dijamin menggugah selera.', '[\"1 potong tempe 3000\", \"1 bngkus sajiku tepung serbaguna\", \"secukupnya Air\", \"Minyak untuk manggoreng\"]', '[\"Potong tempe tipis2\", \"Tuang tepung lalu beri air secukupnya\", \"Panaskan minyak tunggu sampai panas\", \"Masukan satu persatu\", \"Tempe kedalam tepung sampai adonan habis\", \"Angkat tiriskan dan sajikan dengan cabe rawit\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(936, 3, 'Patty Tempe', 'Resep praktis Patty Tempe yang bisa dicoba di rumah.', '[\"250 gram tempe, kukus, haluskan\", \"150 gram daging sapi/ ayam (sy: 200 gr daging sapi)\", \"5 sdm tepung panir (sy: tepung kobe putih)\", \"2 butir telur\", \"1 buah bawang bombay ukuran sedang, potong kotak kecil\", \"4 siung bawang putih, memarkan lalu cincang\", \"1/4 sdt merica bubuk\", \"1/2 sdt garam\"]', '[\"Ini tepung kobe putih yg sy pakai.\", \"Campur semua bahan dalam wadah.\", \"Ulen hingga semua tercampur rata. Adonan menjadi padat. Tes rasa.\", \"Bentuk bulat lalu pipihkan. Timbang per adonan bila perlu.\", \"Siapkan teflon, beri 2 sdm minyak goreng, panaskan. Masukkan adonan. Masak hingga bagian bawah adonan kecoklatan, lalu balik, masak kembali hingga kecoklatan. Angkat, dinginkan, siap untuk isian burger. Atau mau dimakan gitu aja di cocol saus sambal jg enakkk.\", \"Bila akan di simpan di freezer, sebaiknya panggang di teflon setengah matang, biarkan dingin, lalu masukkan dalam wadah tertutup atau plastik. (sengaja sy simpan 1 buah selama 2 minggu, setelah di goreng ttp oke rasanya).\", \"Selamat Mencoba 😃\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(937, 3, 'Orek tempe basah bumbu ulek (recook)', 'Sajian tempe lezat: Orek tempe basah bumbu ulek (recook) penuh protein nabati.', '[\"1 papan tempe, potong sesuai selera (sy 1/2 papan tempe+4 tahu)\", \"3 cabe ijo, iris (sy lombok merah utuh)\", \"Secukupnya kecap manis\", \"Secukupnya gula, garam, penyedap (sy garam aja)\", \"Secukupnya air\", \"Bumbu halus:\", \"5 butir bawang merah\", \"2 siung bawang putih\", \"1/2 buah tomat\", \"3 cabe merah keriting/cabe rawit (sy skip)\", \"2 butir kemiri\", \"1/4 sdt ketumbar\"]', '[\"Goreng tempe setengah matang, angkat, tiriskan dan sisihkan.\", \"Panaskan secukupnya minyak, tumis bumbu sampai layu dan harum. Tambahkan air, biarkan mendidih. Tambahkan kecap, lombok dan garam, aduk rata. Tambahkan tempe, aduk rata. Koreksi rasa. Angkat.\", \"Siap disajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(938, 2, 'Perkedel Tempe', 'Resep praktis Perkedel Tempe yang bisa dicoba di rumah.', '[\"1/2 potong papan tempe (haluskan dgn sedikit air)\", \"bumbu halus: ulek kasar\", \"6 siung bawang merah\", \"2 siung bawang putih\", \"2 cabai rawit\", \"1 sdt ketumbar bubuk\", \"secukupnya garam, ebi\", \"1/2 bungkus tepung racik bakwan\"]', '[\"Campurkan adonan tempe basah dengan bumbu halus, aduk rata\", \"Panaskan wajan dgn minyak, tuang adonan per 1 sendok makan sampai adonan habis\", \"Goreng adonan sampai berwarna kekuningan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(939, 2, 'Nugget Tempe Simple', 'Resep Nugget Tempe Simple yang lezat dan mudah dibuat di rumah.', '[\"1 papan tempe\", \"1 buah wortel\", \"1 butir telur (kocok lepas)\", \"5 siung bawang merah\", \"2 siung bawang putih\", \"2 batang daun bawang\", \"1 sdt garam\", \"Secukupnya: tepung terigu, merica, tepung roti & kaldu bubuk\"]', '[\"Haluskan bawang merah, bawang putih, merica, garam & kaldu bubuk. Tambahkan tempe, uleg sampai lembut\", \"Potong2 daun bawang & parut wortel menggunakan parutan keju, siapkan baskom\", \"Masukkan semua bahan dalam baskom kecuali telur & tepung roti. Tambahkan air & terigu, aduk rata. Masukkan dalam loyang & kukus selama 30 menit\", \"Angkat, setelah dingin potong2 sesuai selera, celupkan dalam telur & gulingkan dalam tepung roti, simpan dalam freezer 30 menit. Lalu goreng. 🍱\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(940, 3, 'Sarden ikan pindang tempe pedas adam manis', 'Sarden ikan pindang tempe pedas adam manis - olahan tempe khas Indonesia yang nikmat.', '[\"2 ikan pindang ukuran sedang/besar\", \"1 papan tempe kecil iris serong\", \"2 buah cabe keriting\", \"6 cabe rawit\", \"2 siung bawang putih iris\", \"4 siung bawang merah iris\", \"1 sachet saos pedas (saya merk ABC)\", \"1 sdm saos tomat\", \"2 sdt garam (sesuai selera)\", \"1 sdm gula\", \"2 tangkai daun bawang\", \"1 ruas jahe\", \"1 ruas lengkuas\", \"1 lembar daun salam\", \"1 buah tomat\"]', '[\"Goreng ikan pindang yg sudah diberaihkan durinya dan tempe. Lalu sisihkan\", \"Tumis irisan baput, bamer,cabe, tomat hingga agak layu\", \"Tambahkan air hingga hampir mendidih tambahkan saos tomat,saos pedas,gula,garam\", \"Masukkan tempe dan ikan oindang yg sudah digoreng sebelumnya.\", \"Tes rasa dan tunggu hingga dirasa sudah cukup. Lalu sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(941, 2, 'Tempe Isi Kekinian', 'Tempe Isi Kekinian - olahan tempe khas Indonesia yang nikmat.', '[\"1 papan tempe bulat\", \"1/4 tepung terigu\", \"Garam\", \"Gula\", \"Merica\", \"Ketumbar bubuk\", \"Daun bawang\", \"⤵ Isian tempe\", \"5 buah cabe merah\", \"10 buah cabe hijau\", \"3 buah bawang merah\", \"2 buah bawang putih\"]', '[\"Potong tempe lalu buat lubang di tengah untuk isiannya\", \"Ulek cabe,bawang sampai kasar atau halus sesuai selera\", \"Siapkan tepung,merica,daun bawang diiris, garam dan aduk sampai rata. Lalu beri air secukupnya\", \"Masukan hasil ulekan bawang dan cabe kedalam tempe yang sudah dilubangi.\", \"Masukan tempe kedalam adonan terigu.\", \"Panaskan minyak lalu goreng tempe sampai kecoklatan. Lalu tiriskan, tempe pun siap disajikan bersama nasi hangat atau jadi cemilan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(942, 2, 'Sayur Lodeh Tempe Semangit (Bumbu Ulek)', 'Sajian Sayur Lodeh Tempe Semangit (Bumbu Ulek) yang praktis dan lezat untuk dinikmati bersama.', '[\"1 buah labu siam, potong tipis\", \"1 buah terong ungu, potong kecil\", \"1 ikat kacang panjang, potong-potong\", \"1 papan tempe semangit, potong kasar\", \"1 bungkus santan kara cair\", \"3 lembar daun salam\", \"1 ruas lengkuas, geprek\", \"1.5 sdm ebi, seduh, tiriskan\", \"2 buah gula jawa, sisir halus\", \"Sesuai selera garam dan gula\", \"Bumbu Halus:\", \"5 siung bawang merah\", \"2 siung bawang putih\", \"3 buah cabe merah\"]', '[\"Tumis ebi hingga setengah kering. Masukkan bumbu halus. Tumis hingga harum. Tambahkan daun salam dan lengkuas.\", \"Masukkan air sesuai selera. Tambahkan santan cair. Masukkan gula jawa, garam, dan gula pasir. Aduk rata.\", \"Setelah setengah mendidih masukkan kacang panjang dan labu siam. Setelah setengah empuk, masukkan terong dan tempe semangit. Biarkan hingga mendidih.\", \"Matikan api setelah didapat kematangan yg diinginkan. Jangan lupa koreksi rasa. Sajikan dengan nasi hangat, sambal terasi, dan empal daging.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(943, 4, 'Tempe mendoan', 'Sajian tempe lezat: Tempe mendoan penuh protein nabati.', '[\"8 ptg tempe mendoan\", \"10 sdm Tepung terigu -+\", \"3 Bawang putih\", \"sndk teh Merica stg\", \"sndk teh Ketumbar stng\", \"Garam sckupnya\", \"2 batang Daun bawang\", \"Air kira2\"]', '[\"Campurkan tepung terigu dengan air\", \"Masukkan daun bawang iris\", \"Masukkan bawang putih yang dihaluskan, merica bubuk, garam, ketumbar bubuk\", \"Goreng setengah matang.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(944, 4, 'Bacem tempe mentega', 'Resep Bacem tempe mentega ala rumahan yang dijamin menggugah selera.', '[\"2 buah tempe ukuran sedang\", \"Bumbu bumbu:\", \"4 butir bawang merah\", \"4 siung bawang putih\", \"Sedikit ketumbar\", \"2 Biji gula jawa\", \"2 sm mentega\", \"3 sm kecap manis sedang\", \"sesuai selera Penyedap rasa\", \"secukupnya Garam\", \"2 lbr daun salam\", \"1 cm laos\", \"600 ml air\"]', '[\"Tempe di potong sesuai selera\", \"Haluskan Bawang merah, bawang putih dan ketumbar.\", \"Siapkan wajan, taruh tempe yang sudah dipotong, bumbu halus, gula Jawa, kecap, garam, penyedap rasa, daun salam dan lengkuas, tambahkan air, kemudian tutup dan rebus dengan api sedang\", \"Setelah air rebusan tinggal separo, dibolak balik agar bumbu merata dan koreksi rasa.\", \"Setelah air hampir habis masukkan mentega, sambil di bolak balik agar bumbu merata dan tidak gosong\", \"Setelah air habis, matikan kompor\", \"Bacem tempe siap di sajikan\", \"Selamat mencoba dan terima kasih.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(945, 3, 'Sayur tempe mix tahu alaala kari', 'Resep Sayur tempe mix tahu alaala kari ala rumahan yang dijamin menggugah selera.', '[\"1/4 tempe dari 1 papan\", \"5 buah tahu\", \"2 keris pete\", \"3 buah wortel ukuran sedang\", \"800 ml Santan\", \"Bumbu:\", \"4 bawang merah\", \"3 bawang putih\", \"3 cm kunyit\", \"2 cm jahe\", \"2 butir kemiri\", \"1/2 sdt ketumbar\", \"1 sdm garam\", \"secukupnya Gula\", \"Penyedap rasa saya pakai royco ayam\", \"Bumbu pelengkap:\", \"3 cm laja\", \"2 lbr daun salam\", \"3 lbr daun jeruk\", \"Minyak untuk menumis bumbu\"]', '[\"Tempe potong kotak, goreng\", \"Tahu potong serong, goreng\", \"Kupas pete jangan dibelah\", \"Kupas wortel, cuci lalu potong dadu kecil\", \"Siapkan bumbu, cuci lalu haluskan kecuali laja, daun salam dan daun jeruk. Laja geprek aja.\", \"Tumis bumbu sampai layu, masukan geprekan laja, daun salam dan daun jeruk. Beri sedikit air supaya meresap\", \"Masukan santan, biarkan sampai mendidih.\", \"Masukan pete, wortel, tempe dan tahu.\", \"Masukan gula, penyedap. Aduk2, tes rasa\", \"Masak sekitar 10 menit.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(946, 3, 'Tempe goreng segitiga', 'Resep Tempe goreng segitiga yang lezat dan mudah dibuat di rumah.', '[\"Tempe secukupnya lalu potong bentuk segitiga\", \"1 sdm tepung ayam (merk apa saja)\", \"1 sdt baking powder\", \"Bumbu halus\", \"3 siung bawang merah\", \"4 siung bawang putih\", \"Sedikit kemiri\", \"iris Daun bawang\", \"Sedikit kunyit bubuk\", \"Secukupnya garam dan penyedap rasa\"]', '[\"Campur bumbu halus dengan air, tepung terigu, tepung ayam, baking powder dan kunyit bubuk, aduk sampai rata\", \"Beri secukupnya garam,penyedap rasa dan irisan daun bawang. Untuk adonan tidak terlalu encer yaa\", \"Panas kan minyak, lalu goreng hingga berwarna kecoklatan\", \"Sajikan dengan saus sambal😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(947, 2, 'Tempe Goreng Tepung', 'Resep Tempe Goreng Tepung ala rumahan yang dijamin menggugah selera.', '[\"1/4 Tempe\", \"Terigu\", \"Ketumbar Bubuk\", \"Garam\", \"Masako Ayam\", \"1 lembar Daun Bawang\"]', '[\"Potong - potong tempe dahulu dan daun bawang.\", \"Siapkan adonan, masukan terigu, garam secukupnya, ketumbar bubuk secukupnya, dan masako. Beri air sedikit aduk rata. (kalo aku ga begitu kental adonannya jd aga cair dikit)\", \"Siapkan minyak yang sudah panas dengan api kecil, masukan tempe keadonan, dan goreng tempe hingga matang (tdk terlalu gosong dan tdk terlalu setengah matang)\", \"Tempe goreng tepung siap untuk cemilan atau dibuat lauk👌\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(948, 3, 'Tumis Tempe Jamur', 'Sajian Tumis Tempe Jamur yang praktis dan lezat untuk dinikmati bersama.', '[\"Secukupnya tempe, potong dadu\", \"Secukupnya jamur kuping, iris iris\", \"Secukupnya jamur enoki\", \"4 bh cabai rawit\", \"2 bh cabai merah\", \"1/2 bh tomat hijau\"]', '[\"Cincang bawang putih dan bawang merah, iris tipis2 cabai, sisihkan\", \"Cuci bersih jamur, lalu potong2 sesuai selera, sisihkan\", \"Potong dadu tempe, atau sesuai selera ya\", \"Tumis bawang sampai harum, setelah itu masukkan cabai aduk2 hingga layu kemudian masukan tomat dan air secukupnya\", \"Masukkan jamur dan tempe aduk hingga matang dan beri kecap secukupnya.\", \"Tunggu hingga beberapa menit kemudian sajikan😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(949, 4, 'Tumis Kacang Panjang Tempe', 'Nikmati kelezatan Tumis Kacang Panjang Tempe dengan resep sederhana ini.', '[\"1/2 ikat kacang panjang (potong lalu cuci bersih)\", \"2 papan tempe ukuran sedang (potong,lalu goreng sebentar)\", \"Tomat (iris)\", \"Gula (secukupnya)\", \"Garam (secukupnya)\", \"Minyak goreng (secukupnya)\", \"2 sdm ikan teri (cuci bersih)\", \"Bumbu iris :\", \"1 buah bawang bombay\", \"2 siung bawang merah\", \"4 siung bawang putih\", \"15 buah cabe rawit (bisa dikurangi sesuai selera)\", \"5 buah cabe merah kriting\"]', '[\"Panaskan minyak lalu tumis bumbu iris sampai layu\", \"Lalu masukkan kacang panjang aduk rata\", \"Masukkan tempe,tomat,gula,dan garam. Cicipi sampai rasanya pas dan sesuai selera. Masak sampai matang dan bumbu meresap. Angkat lalu sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(950, 2, 'Tempe Selimut Simple', 'Nikmati kelezatan Tempe Selimut Simple dengan resep sederhana ini.', '[\"Tempe Rp 2000,\", \"-Daun bawang Rp 500,\", \"-Tepung racik tempe goreng\", \"Tempung maizena\", \"sedikit Air\", \"Garam\"]', '[\"Bikin adonannya terlebih dahulu, siapkan air di mangkok. Lalu masukkan tepung maizena, tepung racik tempe goreng jd satu. Jgn begitu kental, jgn begitu lembek. Jgn lupa kasih garam.. Cicipi rasanya sdh pas atau blm\", \"Kalau sudah tercampur, cuci daun bawang lalu potong kecil2 dan masukkan ke dalam campuran tepung td.\", \"Potong tempe sesuai selera. Masukkan tempe ke dalam adonan bumbu td..\", \"Goreng hingga warna sedikit ke coklatan\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(951, 2, 'Kering Tempe', 'Buat Kering Tempe yang nikmat dengan langkah-langkah mudah ini.', '[\"1 papan tempe\", \"Bumbu :\", \"12 siung bawang merah\", \"7 siung bawang putih\", \"1 jempol jahe\", \"10 buah cabai rawit\", \"2 buah cabai keriting\", \"2 buah cabai merah besar\", \"1 blok gula merah\"]', '[\"Tempe potong korek api. Goreng sampai kering. Tiriskan\", \"Haluskan bawang merah, bawang putih, cabai rawit, cabai keriting dan jahe. Iris serong cabai merah besar (buang bijinya). Tumis sampai harum\", \"Sisir gula merah. Kemudian masukkan ke tumisan bumbu, aduk2 sampai gula merah hancur. Tambahkan garam, merica. Tumis lagi dan cek rasa\", \"Masukkan tempe kering. Tambahkan 1 gelas air. Aduk2 dan biarkan air menyusut. Angkat dan siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(952, 2, 'Tempe kecap pedas manis', 'Buat Tempe kecap pedas manis yang nikmat dengan langkah-langkah mudah ini.', '[\"1 kotak tempe ukuran kecil (iris dadu)\", \"1 siung bawang putih\", \"1 siung bawang merah\", \"10 cabe rawit (harusnya cabe hijau) iris bulet\", \"1 butir kemiri\", \"1 ruas jahe\", \"Garam\", \"Sepucuk sdm maizena\", \"1/2 gelas Air\", \"Kecap\", \"Minyak\"]', '[\"Haluskan kemiri, garam dan geprek jahe. Larutkam maizena ke dalam air. Iris tipis bawang merah dan bawang putih.\", \"Goreng basah (sebentar saja) tempe. Lalu angkat.\", \"Tumis bawang merah dan bawang putih sampe harum. Masukan cabe. Masukan tempe.\", \"Masukan bumbu halus ke larutan maizena. Aduk. Masukan ke tumisan tempe. Aduk sampe rata.\", \"Tambah kecap secukupnya, hingga warna rata menjadi kecoklatan.\", \"Test rasa. Done\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(953, 4, 'Sandwich Tempe Jeletot', 'Resep Sandwich Tempe Jeletot yang lezat dan mudah dibuat di rumah.', '[\"1 papan Tempe\", \"Bahan Sambel :\", \"Cabe Merah\", \"Cabe Rawit\", \"Cabe Rawit merah\", \"1 buah Kemiri\", \"3 siung Bawang Merah\", \"1 siung Bawang Putih\", \"1 sdm Gula Pasir\", \"secukupnya Garam\", \"Penyedap Rasa (optional)\", \"secukupnya Minyak goreng\", \"Bahan celupan :\", \"4 sdm Tepung terigu\", \"Tepung tapioka 1 sdm (kalo saya skip ini)\", \"1 sdt Lada\", \"1 sdt Garam\", \"Bawang putih bubuk secukupnya (optional)\"]', '[\"Potong tempe memanjang, belah dibagian tengahnya. (Dipotongnya jangan sampai terputus bagian bawahnya ya bunda) (sisihkan)\", \"Panaskan minyak sayur kedalam wajan, lalu goreng semua bahan sambal sampai harum, kemudian angkat\", \"Haluskan semua bahan sambal, tambahkan minyak sayur panas sisa goreng tadi, tambahkan garam, gula dan penyedap rasa (optional) lalu sisihkan\", \"Campur semua bahan celupan. Tuang air perlahan-lahan. Kekentalan adonannya dikira2 ya bunda, jangan terlalu ko ko ko mi koencer juga.\", \"Ambil tempe yang sudah diiris, kemudian isi dengan bahan sambal yg sudah dihaluskan. Ulangi sampai selesai.\", \"Panaskan minyak sayur.\", \"Goreng adonan kedalam wajan\", \"Cocok dijadikan lauk atau sebagai cemilan\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(954, 2, 'Sambal Tempe Bosok', 'Buat Sambal Tempe Bosok yang nikmat dengan langkah-langkah mudah ini.', '[\"1/2 papan tempe semangit (tempe yang terlalu matang)\", \"4 butir bawang merah\", \"2 butir bawang putih\", \"1 batang sereh\", \"Kencur (sesuai selera)\", \"Jahe (sesuai selera)\", \"5 buah cabe (sesuai selera ya. Saya sukanya pedas)\", \"secukupnya Garam\"]', '[\"Potong2 tempe lalu kukus selama kurang lebih 30 menit.\", \"Sambil tempe dikukus cuci bersih sereh, bawang, cabai, kencur, jahe.\", \"Saat tempe matang, ulek tempe dan semua bumbu. Tambahkan garam.\", \"Sambal tempe bosok siap dihidangkan. Paling cocok dinikmati dengan nasi kencur 😊😊 Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(955, 2, 'Orek tempe+kacang+teri simple', 'Nikmati kelezatan Orek tempe+kacang+teri simple dengan resep sederhana ini.', '[\"2 genggam kacang tanah\", \"1 buah tempe yg harga 4000\", \"1 genggam ikan teri medan\", \"2 buah bawang merah\", \"1 siung bawang putih\", \"3 buah cabe merah keriting\", \"secukupnya Garam\", \"Minyak untuk menggoreng\"]', '[\"Potong tempe sebesar korek api dan beri garam secukupnya. Iris bawang merah,cabe dan bawang putih.\", \"Goreng tempe,kacang tanah dan ikan teri hingga garing\", \"Goreng bawang merah dan putih terlebih dahulu,setelah setengah masak masukkan cabe merah dan goreng hingga garing\", \"Setelah semua matang tinggal dicampur ya bunda\", \"Difoto cuma kelihatan kacangnya krna tempe sama ikan teri ketutupan.\", \"Selamat mencoba bunda moga suka.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(956, 3, 'Oseng teri tempe cabe hijau', 'Sajian Oseng teri tempe cabe hijau yang praktis dan lezat untuk dinikmati bersama.', '[\"1 papan tempe (potong dadu kecil)\", \"2 papan pete\", \"3 buah cabe hijau besar (iris2 serong)\", \"6 siung bawang putih (iris2 seperti biasa)\", \"5 buah cabe merah (iris2 serong)\", \"5 buah cabe rawit hijau (iris2 serong)\", \"1 bulat bawang bombay\", \"1 genggam kacang kapri (saya potong jadi 2)\", \"1/4 teri asin yang sudah dicuci dan digoreng garing\", \"4 sdm minyak goreng\", \"Garam 1/2 sdt (secukupnya)\", \"Gula 1sdt (secukupnya)\", \"Sedikit air untuk menumis\", \"secukupnya Bumbu penyedap ayam\", \"Kecap manis 3 sdm atau secukupnya\", \"secukupnya Lada\"]', '[\"Tempe dipotong dadu kecil2 lalu digoreng hingga berubah warna kecoklatan. Angkat Lalu sisihkan di piring lain.\", \"Goreng teri hingga garing. Hati2 jangan sampai gosong ya. Kalau sudah garing lalu angkat dan sisihkan ke piring yang lain juga.\", \"Gunakan minyak goreng yang baru untuk menumis bawang bombay dan bawang putih\", \"Jika bawang sudah agak kecoklatan warnanya,masukan cabe hijau,rawit hijau dan cabe merah..tumis hingga semua berbau wangi. Setelah itu masukan pete, kacang kapri. Tumis hingga agak layu sedikit tapi jangan terlalu layu..agar sayurnya masih terasa ada garing2nya jika dimakan.\", \"Jika sudah agak layu lalu masukan tempe nya. Masukan garam,gula pasir,lada dan kecap manis. Tumis hingga bumbu rata. Lalu tambahkan sedikit air biar tidak terlalu kering tumisanya. Lalu masak dan diamkan sekitar 2 menit supaya airnya agak surut sedikit.\", \"Terakhir masukan ikan terinya. Teri dimasukan terakhir agak ikan teri yg sudah digoreng garing tidak akan jadi melempem.\", \"Sajikan bersama keluarga. Selamat menikmati :)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(957, 2, 'Tempe & Tahu Bacem', 'Resep Tempe & Tahu Bacem yang lezat dan mudah dibuat di rumah.', '[\"Tempe 1 papan potong 6\", \"6 tahu putih\", \"1/2 liter air\", \"2 daun salam\", \"5 sdm kecap manis\", \"5 sdm gula merah sisir\", \"Garam\", \"Merica\", \"Bumbu halus:\", \"5 bawang merah\", \"3 bawang putih\", \"1/2 sdt ketumbar\", \"secukupnya Minyak goreng\"]', '[\"Panaskan panci/wajan di atas kompor, masukan bahan2 dan bumbu halus. Masak sampai bumbu meresap dan surut. Aduk perlahan.\", \"Setelah bumbu meresap, angkat\", \"Panaskan minyak goreng, goreng tempe & tahu bacem sampai kecoklatan\", \"Angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(958, 4, 'Tumis oseng2 tempe', 'Sajian Tumis oseng2 tempe yang praktis dan lezat untuk dinikmati bersama.', '[\"1/2 papan tempe pot. Dadu\", \"Segenggam kacan tanah\", \"I ons teri\", \"10 bh bwg merah\", \"4 bh bwg putih\", \"2 sdm cabe giling tuk pewarnanya\", \"3 bh cabe merah keriting\", \"10 bh cabe rawit\", \"3 lbr daun jeruk\", \"kecap\", \"Gula,garam\", \"1/2 bh jeruk nipis (airnya)\"]', '[\"Goreng tempe,teri dan kacang tanah\", \"Iris bwg merah,bwg putih,dan cabe-cabean. Cabenya sesuai selera ya bun\", \"Tumis dgn secukup minyak bumbunya yg diiris tadi,tambahkan daun jeruk dan cabe giling sampe layu\", \"Kemudian tambahkn kecap,airjeruk nipis,gula dan garam sesuai selera.. Tes rasa\", \"Jika sudah pas,masukan tempe,teri dan kacang yg sudah digoreng tadi..aduk2,jadi deh..😍 ada pedas manisnya gitu😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(959, 4, 'Orek tempe pedas manis', 'Orek tempe pedas manis - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1/2 papan tempe, potong kotak2\", \"2 buah tahu kuning, potong kotak2\", \"Minyak u. Menumis\", \"1 buah gula merah, iris2\", \"Garam\", \"Bumbu penyedap (blh skip)\", \"Bumbu halus :\", \"3 bawang merah\", \"2 bawang putih\", \"2 Cabe merah uk. Besar\"]', '[\"Goreng tempe dan tahu hingga berwarna kecoklatan lalu angkat dan sisihkan\", \"Tumis bumbu halus hingga harum lalu masukan gula merah yg diiris tadi aduk hingga merata lalu masukan garam\", \"Terakhir masukan tempe dan tahu tadi aduk hingga merata dan sedikit menyusut, jangan lupa koreksi rasa lalu angkat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(960, 4, 'Tempe goreng sederhana', 'Resep Tempe goreng sederhana ala rumahan yang dijamin menggugah selera.', '[\"1/2 papan tempe\", \"Secukupnya tepung terigu\", \"1 batang daun bawang\", \"Secukupnya garam\", \"Secukupnya air\", \"Secukupnya minyak goreng\"]', '[\"Potong tempe sesuai selera, iris daun bawang. Sisihkan.\", \"Siapkan tepung terigu di wadah lalu masukan garam dan daun bawang, beri air sedikit demi sedikit (jgn terlalu encer) Test rasa.\", \"Masukan tempe satu persatu lalu aduk pelan.\", \"Tuangkan minyak ke wajan lalu goreng tempe sampai warna kecoklatan. Tiriskan.\", \"Tempe goreng siap disantap😍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(961, 2, 'Jangan Ndeso Alakadarnya a.k.a Sayur Tempe Gunungkidul', 'Buat Jangan Ndeso Alakadarnya a.k.a Sayur Tempe Gunungkidul yang nikmat dengan langkah-langkah mudah ini.', '[\"1/2 papan tempe, goreng setengah kering\", \"5 buah tahu putih, goreng\", \"10 buah kacang panjang\", \"Bumbu:\", \"4 siung sedang bawang putih, geprek iris2\", \"6 siung bawang merah, iris2\", \"1 ruas lengkuas\", \"3 lembar daun salam\", \"Segenggam cabe keriting hijau, iris serong tipis2\", \"5 buah cabe rawit merah\", \"65 ml santan kara\", \"Secukupnya garam\", \"Sedikit merica\", \"Secukupnya air\", \"Secukupnya minyak goreng, utk menumis\"]', '[\"Tumis duo bawang, duo cabe, daun salam sampai wangi. Tambahkan lengkuas. Tumis sebentar.\", \"Masukkan santan. Aduk sebentar. Tambahkan air seauai selera.\", \"Masukkan tempe, tahu yang sudah digoreng. Kemudian kacang panjang.\", \"Tambahkan garam dan merica. Aduk sampai santan dan bumbu meresap. Koreksi rasa.\", \"Jangan Ndeso siap disantap😋\", \"Hati hati, bisa nambah berpiring2😂\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(962, 2, 'Jangan Tempe Tahu', 'Resep praktis Jangan Tempe Tahu yang bisa dicoba di rumah.', '[\"Tahu potong menyerong\", \"Tempe potong kotak\", \"Pete\", \"Udang papay\", \"Santan\", \"Garam\", \"Gula\", \"Penyedap\", \"Minyak goreng untuk tempe tahu\", \"Bumbu halus\", \"3 butir Bawang merah\", \"3 butir Bawang putih\", \"secukupnya Cabe\", \"3 cm Kunyit\", \"3 cm Jahe\", \"Ketumbar\", \"Kemiri\", \"Terasi\", \"Pelengkap\", \"Daun salam\", \"Daun jeruk\", \"Lengkuas\"]', '[\"Goreng tempe dan tahu setengah matang\", \"Ulek bumbu halus\", \"Tumis bumbu halus masukan udang papay dan pete jangan lupa masukan daun salam daun jeruk dan lengkuas yang sudah di geprek\", \"Tambahkan air tinggu hingga meresap\", \"Jika bumbu sudah meresap masukan tambahan air\", \"Masukan gula garam dan penyedap\", \"Masukan santan\", \"Masukan tempe dan tahu\", \"Koreksi rasa jika sudah pas tinggal tunggu mendidih ya\", \"Angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(963, 4, 'Tumis Toge Tempe Kecap', 'Tumis Toge Tempe Kecap - olahan tempe khas Indonesia yang nikmat.', '[\"1 papan Tempe\", \"150 gr Tauge\", \"2 siung Bawang Merah\", \"2 siung Bawang Putih\", \"3 cabe rawit/sesuai selera\", \"sesuai selera kecap\", \"Merica (Bisa Skip)\"]', '[\"Cuci bersih tauge, buang buntutnya, sisihkan\", \"Potong tempe sesuai selera lalu goreng, tiriskan\", \"Geprek bawang putih iris, iris jg bawang merah dan cabe\", \"Tumis bumbu sampe harum, masukkan tempe lalu kecap jika kecap dirasa sudah meresap masukkan tauge\", \"Masukkan garam, gula sesuai selera, tes rasa. sajikan 🤗\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(964, 4, 'Ayam Dan Tempe Goreng Serundeng', 'Ayam Dan Tempe Goreng Serundeng - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 dada ayam\", \"1/2 kelapa parut\", \"2 tempe (potong agak tebal)\", \"3 siung bawang putih (dihaluskan)\", \"1 ruas jari kunyit (dihaluskan)\", \"secukupnya Garam\", \"secukupnya Penyedap royco\", \"3 lembar daun salam\", \"2 batang sereh\", \"secukupnya Air masak\"]', '[\"Setelah ayam dicuci bersih, didihkan air. Masukkan ayam, lalu tiriskan\", \"Didihkan air kembali, setelah air sudah mendidih masukkan bumbu yang sudah di haluskan, daun salam, sereh.\", \"Jika sudah tercium wangi, masukkan ayam aduk rata. Tunggu sampai 10-15 menit. Lalu masukkan tempe.\", \"Setelah agak berkurang airnya, masukkan kelapa lalu aduk hingga rata sampai air mengering. Angkat dan sajikan.\", \"Goreng dengan api sedang, nikmati dengan sambal tomat yang pedas. Resep bisa di lihat di upload resep sebelumnya.\", \"Selamat mencoba Moms!\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(965, 4, 'Tempe isi Sambel', 'Sajian tempe lezat: Tempe isi Sambel penuh protein nabati.', '[\"1 kotak tempe\", \"200 gr Tepung terigu\", \"Bumbu harus untuk pelapis tempe\", \"Garam dan 2 butir bawang (dihaluskan)\", \"5 biji cabe rawit\", \"2 butir bawang putih\", \"3 butir bawang merah\", \"2 lembar daun jeruk\", \"secukupnya Garam\"]', '[\"Iris tempe menjadi 10 bagian kotak belah sedikit tengahnya untuk memasukkan isi sambelnya. Taruh di wadah lalu bumbui dengan garam dan bawang yang sudah di haluskan.\", \"Iris semua bumbu sambal(karna gag suka ngulek bun).. tempatkan jadi 1 diwadah setelah selesai teriiris aduk rata kasih sedikit garam.\", \"Masukkan isi sambal kedalam belahan tempe tadi.\", \"Masukkan kedalam adonan tepung terigu yang sudah di bumbui garam dan bawang yang telah dihaluskan.\", \"Panaskan wajah yang sudah terisi minyak,,goreng hingga kekuningan. Angkat tiriskan.\", \"Tempe isi siap di hidang kan,,bisa untuk lauk pauk ataupun sekedar di Cemil.. bagi yang suka pedes banget bisa di cocol sama saos pedes.. yummy 😋😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(966, 2, 'Tumis Udang tempe kacang panjang', 'Sajian tempe lezat: Tumis Udang tempe kacang panjang penuh protein nabati.', '[\"1 potong tempe, potong Kecil2\", \"6 ekor udang, buang kulit dan kepala lalu cuci bersih\", \"3 buah kacang panjang, potong2\", \"1 siung bawang putih, iris\", \"1/2 siung bawang bombay, iris\", \"1 bawang pring, potong 2\", \"3 buah cabe rawit, iris\", \"1/2 sdm saus tiram\", \"1/2 sdm kecap manis\", \"1/2 sdm saos tomat\", \"Sedikit garam dan gula\", \"Minyak untuk menggoreng\"]', '[\"Panaskan minyak di atas wajan\", \"Goreng tempe, angkat\", \"Masukkan bawang putih dan bawang bombay. Tumis hingga harum\", \"Masukkan cabe rawit dan daun bawang\", \"Masukkan udang, aduk hingga berubah warna. Lalu masukkan tempe yg sudah digoreng\", \"Tambahkan saus tiram, saus tomat, kecap manis, sefikit garam dan gula. Aduk sebentar hingga bumbu merata. Tes rasa...\", \"Angkat dan sajikan dg nasi hangat. Mantaaappp\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(967, 3, 'Cireng isi tempe renyah', 'Resep praktis Cireng isi tempe renyah yang bisa dicoba di rumah.', '[\"300 gr tepung tapioka (sy rose Brand)\", \"1 sdt mucung garam\", \"1 siung bawang putih\", \"Sec Air mendidih\", \"Sec daun bawang\", \"Isian\", \"7 potong Uk sedang tempe\", \"1 siung bawang putih\", \"1 siung bawang merah\", \"10 buah cabe rawit\", \"2 sdt gula pasir\", \"1 sdt garam\"]', '[\"Isian : Potong dadu tempe, goreng setengah matang. Angkat tiriskan\", \"Goreng bawang dan cabe setengah matang. Angkat dan tiriskan\", \"Siapkan cobek, haluskan tempe, bawang dan cabe, masukan gula garam. Cicipi. Jika kurang pedas tambahkan cabe rawit. Karna jika sudah di goreng rasanya akan berkurang\", \"Adonan cireng : Siapkan wadah besar. Masukan tepung tapioka, garam, bawang putih halus, aduk. Lalu masukan air mendidih sedikit demi sedikit. Aduk. Jangan sampe kalis. Tp masih menggumpal\", \"Tambahan irisan daun bawang, aduk\", \"Ambil 1 sendok adonan, pipihkan lalu masukan 1/2 sdm Isian tempe. Jika lengket di tangan taburkan tepung tapioka / terigu. Lipat menjadi setengah lingkaran. Saya suka Isian yg banyak. Lakukan sampai adonan habis\", \"Pada saat akan menyimpan agar tidak menempel satu sama lain. Taburkan tepung tapioka / terigu\", \"Goreng sampai matang/kecoklatan. Sisanya bisa disimpan di kulkas\", \"Ga pake cocol an saus jg enak\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(968, 3, 'Sate Tempe... yummy.. max', 'Nikmati kelezatan Sate Tempe... yummy.. max dengan resep sederhana ini.', '[\"1 lonjor tempe.. potong dadu\", \"Bumbu bakar\", \"6 siung bawang putih\", \"8 siung bawang merah\", \"1 sdm merica\", \"2 sdm ketumbar\", \"2 sdm gula pasir\", \"1 ons gula merah sisir\", \"1 sachet kaldu ayam\", \"Garam\", \"Kecap manis\", \"2 sdm maizena\"]', '[\"Potong tempe dadu.... goreng sampai kecoklatan... tiriskan\", \"Haluskan bumbu.. kecuali meizena dan kecap. Rebus di wajan dengan menambahkan 100 ml air atau secukupnya pemirsah sesuai selera.. mau kental banget atau cair.. jika suka cair air bisa ditambahkan jadi 1 gelas.. aduk rata..\", \"..... setelah mendidih... tambahkan kecap.. dan meizena yg tlah dicairkan... aduk rata...tes rasa... jika sudah siiip... langsung bisa oles2\", \"Tusuk tempe... bisa selang seling dengan potongan mentimun tomat cabe.. dan bawang bombay atau bawang merah... oles dgn bumbu bakar.. atau celupkn tusukan tempe pada bumbu bakar\", \"Panggang diatas bara.. sampai matang\", \"Siap dihidangkan.. dgn taburan cabe dan irisan bawang merah\", \"Kucuri dengan kecap manis... saya pakai kecap bango pemiRsah.. bukan iklan lho\", \"😋😋😋\", \"Noted. sblm dibakar diatas bara.. aning oven dulu sate yg siap bakar di oven listrik memakai api atas suhu 200 darcel terlebih dulu... selama 15 menit supaya bumbu meresap.. baru dibakar diatas bara\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(969, 2, 'Tumis tempe kacang panjang', 'Sajian Tumis tempe kacang panjang yang praktis dan lezat untuk dinikmati bersama.', '[\"5 buah kacang panjang, potong-potong\", \"1 papan tempe ukuran kecil potong korek\", \"2 lembar daun salam\", \"1 ruas jari lengkuas, geprek\", \"3 buah cabe merah keriting, iris serong\", \"4 buah bawang merah, iris tipis\", \"2 buah bawang putih, iris tipis\", \"1 buah tomat, potong jadi 8 bagian\", \"1 sdm saos tiram\", \"Secukupnya kecap\", \"Secukupnya gula, garam\", \"Secukupnya air dan minyak\"]', '[\"Goreng tempe hingga kuning keemasan, angkat, sisihkan.\", \"Panaskan sedikit minyak, tumis cabe merah, bawang merah, bawang putih dan daun salam, tumis hingga wangi. Masukan kacang panjang, tumis hingga layu lalu tambahkan sedikit air.\", \"Tambahkan bumbu-bumbu, saos tiram, kecap, gula, garam lalu aduk rata. Masukan tomat, tempe yang telah digoreng, aduk rata, tes rasa. Jika sudah pas, tunggu hingga matang dan air menyusut. Angkat, sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(970, 4, 'Terik tahu tempe labu siam jipang', 'Sajian Terik tahu tempe labu siam jipang yang praktis dan lezat untuk dinikmati bersama.', '[\"100 gr daging sapi sambelan\", \"1 buah labu siam jipang potong2\", \"1 papan tempe potong2\", \"5 buah tahu\", \"2 lembar daun salam\", \"secukupnya Bawang goreng\", \"2 mangkok santan\", \"1 liter air\", \"Bumbu halus:\", \"4 siung bawang putih\", \"4 siung bawang merah\", \"Garam.gula\", \"1/2 sdm merica\", \"secukupnya Laos.jahe.kunyit\", \"1/4 butir pala\"]', '[\"Rebus daging dgn air sampe empuk.sambil menunggu empuk.masukkan tmpe tahu jipang dan bumbu halus biar meresap\", \"Tambahkan daun salam dan santan.rebus mendidih.icip2 rasanya.tambahkn bawang goreng\", \"Happy cooking moms\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(971, 2, 'Tumis kacang tempe icha', 'Resep Tumis kacang tempe icha yang lezat dan mudah dibuat di rumah.', '[\"10 kacang panjang ukuran sedang\", \"1 papan tempe\", \"9 siung bawang merah\", \"3 siung bawang putih\", \"5 cabe rawit hijau\", \"1 butir kemiri\", \"5 sendok makan kecap\", \"100 ml air (setengah gelas belimbing)\", \"1 bh tomat ukuran kecil\", \"5 cabe merah keriting\", \"1 sendok teh garam\", \"Secukupnya penyedap rasa (masako ayam)\", \"1/4 kg Minyak goreng\"]', '[\"Potong dan cuci bersih kacang panjang sesuai selera\", \"Potong sesuai selera tempe\", \"Cuci bersih dan kupas bumbu, kemudian ulek sisakan 5 cabai untuk diiris dan tomat untuk diiris\", \"Panaskan minyak, tumis tempe tidak terlalu kering ya warna kecoklatan ajah\", \"Angkat tempe, minyak di parohkan, untuk menumis bumbu tumis bumbu tambahkan garam dan penyedap rasa, setelah bumbu harum masukan air dan tambahkan kecap\", \"Tunggu sampai menggolak masukan kacang panjang tunggu sampai layu setelah layu tambahkan tempe aduk2\", \"Masukan irisan tomat dan cabai tunggu 2 menit. Koreksi rasa jika sudah pas selesaii\", \"Tumis kacang tempe siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(972, 4, 'Tempe Goreng Telur', 'Tempe Goreng Telur - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 papan tempe uk kecil\", \"1 butir telur\", \"2 sdm tepung terigu\", \"Secukupnya bawang putih bubuk\", \"Secukupnya garam, kaldu bubuk, merica\"]', '[\"Potong2 tempe memanjang spt stick, lalu kukus -+ 10 mnt, sisihkan\", \"Campurkan bawang, garam, kaldu bubuk, merica aduk rata, tambahkan telur aduk rata, terakhir tambahkan terigu aduk biarkan bergerindil\", \"Panaskan minyak, gulingkan satu persatu tempe di adonan telur, lalu masak sampai kecoklatan, tiriskan, sajikan hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(973, 3, 'Oseng tempe buncis', 'Resep praktis Oseng tempe buncis yang bisa dicoba di rumah.', '[\"2 potong kecil tempe (dpotong dadu lalu goreng)\", \"1 genggam buncis (potong2)\", \"1 saset saos tiram\", \"Kecap manis, masako ayam, air, secukupny\", \"Minyak goreng untuk mnumis\", \"2 lmbar daun salam\", \"2 cm lengkuas\", \"Bumbu iris :\", \"1 bh bwang bombai\", \"2 siung bwang ptih\", \"5 siung bwang mrah\", \"1 bh tomat\", \"1 btng daun bwang\"]', '[\"Tumis bumbu iris, daun salam, lengkuas smp harum lalu masukan buncis smp agak layu masukan tempe, saos tiram,kecap manis, masako ayam, bwang bombai & air scukupny lalu cek rasa jika sdh pas matikan api dan sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(974, 3, 'Tumis pedas manis tempe buncis', 'Resep praktis Tumis pedas manis tempe buncis yang bisa dicoba di rumah.', '[\"1/2 papan tempe\", \"secukupnya Buncis\", \"2 siung bawang merah\", \"1 siung bawang putih\", \"sesuai selera Bakso\", \"2 butir kemiri\", \"5 bh rawit merah\", \"2 bh cabai keriting merah\", \"Kecap\", \"Garam\", \"secukupnya Air\"]', '[\"Haluskan kemiri, baput, bamer dan cabai\", \"Potong dadu tempe goreng setengah matang, lalu tiriskan.\", \"Bersihkan buncis lalu potong2 sepanjang batang korek.\", \"Tumis, bumbu hingga harum masukan buncis dan tempe\", \"Tambah air sedikit, aduk2 tambahkan kecap dan garam. Masak hingga buncis matang\", \"Siap di sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(975, 2, 'Stik Tempe Racik', 'Resep Stik Tempe Racik yang lezat dan mudah dibuat di rumah.', '[\"2 papan tempe\", \"1 butir telur\", \"Tepung panir\", \"2 sdt bumbu racik tempe\"]', '[\"Potong tempe seperti stik\", \"Larutkan bumbu racik tempe dengan sedikit air\", \"Celupkan tempe yg sudah dipotong\", \"Ambil tempe gulingkan ke tepung panir, lalu celupkan ke dalam telur & celupkan kembali ke tepung panir\", \"Lakukan sampai habis & goreng sampai kecoklatan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(976, 2, 'Oseng teri tempe rawit', 'Resep Oseng teri tempe rawit yang lezat dan mudah dibuat di rumah.', '[\"1 ons teri nasi (cuci pakai air hangat sebentar saja di saring)\", \"Tempe secukupnya di potong kecil tipis sesuai selera\", \"Bahan iris :\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"10 cabe rawit merah\", \"15 cabe rawit hijau(saya utuh ga di iris ya)\", \"2 lbr daun salam\", \"secukupnya Garam dan kaldu bubuk\", \"2 sdm minyak untuk menumis\"]', '[\"Goreng tempe jangan terlalu kering ya, sisihkan\", \"Panaskan minyak, tumis bawang merah sampai harum\", \"Tambahkan bawang putih + daun salam aduk + cabe rawit merah + cabe rawit hijau aduk sampai agak setengah kering ya moms\", \"Masukkan teri aduk terus + tempe+ garam dan kaldu bubuk, tes rasa\", \"Angkat sajikan...bisa abis 2 piring dgn lauk ini maklum paling doyang hihihi😋😋😍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(977, 4, 'Kering tempe manis', 'Resep praktis Kering tempe manis yang bisa dicoba di rumah.', '[\"1 papan tempe iris2 kecil\", \"5 siung bawang merah iris tipis\", \"6 siung bawang putih iris tipis\", \"5 buah cabe merah potong serong tipis\", \"3 cm lengkuas geprek\", \"2 cm jahe iris tipis\", \"50 gram gula merah sisir halus\", \"1 /2 SDM gula pasir\", \"1 SDT garam\", \"Penyedap rasa (optional)\", \"Daun salam\", \"1 mata asem jawa\", \"Minyak goreng\"]', '[\"Goreng tempe yg sudah di iris kecil2 sampai kering. Sisihkan\", \"Goreng bawang merah, bawang putih dan cabe merah sampai bawang kering. Sisihkan\", \"Masukan sedikit minyak goreng ke dlm kuali dan tumis lengkuas dan jahe sampai harum.\", \"Masukan 50 ml air, gula merah sisir, dan asem. Biarkan sampai mendidih dan berambut/kental.\", \"Masukkan bawang merah, bawang putih dan cabe merah yg sudah di goreng.\", \"Masukkan garam dan penyedap rasa,\", \"Terakhir masukkan tempe goreng, aduk cepat dan kecilkan api.\", \"Setelah tercampur rata, angkat dan siap dihidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(978, 2, 'Tempe tepung kress', 'Nikmati kelezatan Tempe tepung kress dengan resep sederhana ini.', '[\"1/2 papan tempe\", \"1 bh daun bawang diiris\", \"5 sendok tepung terigu\", \"1 sendok tepung kanji\", \"bumbu halus :\", \"3 siung daun putih\", \"1 bh kemiri\", \"secukupnya kunyit bubuk\", \"secukupnya garam\", \"secukupnya air\", \"secukupnya minyak goreng\"]', '[\"Potong tempe sesuai selera jangan terlalu tipis dan jangan terlalu tebal.\", \"Siapkan bumbu halus untuk campuran adonannya.\", \"Campur tepung terigu, tepung sagu, daun bawang yang sudah diiris kemudian masukkan bumbu halus. adul rata dan sesekali beri air secukupnya. jangan terlalu encer atau terlalu kental. cek rasa.\", \"Panaskan minyak diwajan. laburi tempe dengan adonan tepung kemudian masukkan pada wajan yang telah panas. usahakan jangan terlalu sering membolak balikkan tempe.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(979, 4, 'Orek Tempe Basah', 'Orek Tempe Basah - olahan tempe khas Indonesia yang nikmat.', '[\"1 papan Tempe\", \"Minyak goreng\", \"1/2 bawang bombai\", \"secukupnya Kecap manis\", \"secukupnya Gula\", \"secukupnya Garam / penyedap\", \"Bumbu halus:\", \"5 butir bawang putih\", \"2 butir bawang merah\", \"1/4 ketumbar\", \"2 butir kemiri\", \"Cabai keriting dan cabe rawit\", \"1/2 buah tomat\"]', '[\"Haluskan bumbu, kemudian tumis hingga matang diatas wajan sampai harum, tambahkan sedikit air. Masukkan garam, kecap, gula secukupnya. Test rasa\", \"Masukkan tempe yang sudah digoreng (setengah matang) dan bawang bombai yang sebelumnya sudah ditumis.\", \"Aduk hingga tercampur rata, dan masak sampai semua bumbu meresap. Tambahkan taburan cabai keriting diatas tempe orek.\", \"Tabur bawang goreng diatasnya. Sajikan dan selamat mencoba😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(980, 4, 'Tempe Tepung Simple', 'Sajian tempe lezat: Tempe Tepung Simple penuh protein nabati.', '[\"1 papan tempe\", \"6 sdm tepung terigu\", \"Minyak goreng\", \"Secukupnya air\", \"bumbu halus :\", \"5 siung bawang putih\", \"1/2 ruas kunyit\", \"Secukupnya garam\"]', '[\"Potong tempe tipis tipis\", \"Haluskan bumbu dan masukkan ke tepungnya\", \"Tambahkan air aduk tepung dan bumbu sampai rata. Jangan terlalu encer. Mending agak kentel\", \"Cicipi asinnya. Kalo kurang asin tambahin garam. Soalnya kadang meskipun dcicipi uda asin tapi pas tepung mateng jadi ga seberapa asin\", \"Masukkan tempenya lumuri tepung sampai rata. Lalu goreng sampai matang. Nyammm😋😋 dicocol sambel kecap lebih enak 😋😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(981, 3, 'Tempe kecap', 'Resep Tempe kecap ala rumahan yang dijamin menggugah selera.', '[\"1/2 papan Tempe, potong kotak\", \"4 siung Bawang merah, iris tipis\", \"2 siung Bawang putih, iris tipis\", \"4 buah Cabai rawit, iris tipis\", \"secukupnya Kecap manis\", \"secukupnya Garam\", \"secukupnya Gula\"]', '[\"Goreng tempe hingga setengah matang, angkat tiriskan\", \"Tumis bawang merah, bawang putih dan cabai rawit, hingga harum, tambahkan sedikit air\", \"Masukkan tempe setengah matang dan bumbui dgn gula, garam dan kecap manis, masak hingga bumbu meresap ke tempe, sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(982, 4, 'Tumis tempe, udang,ati ampela', 'Resep praktis Tumis tempe, udang,ati ampela yang bisa dicoba di rumah.', '[\"1/4 udang\", \"4 papan tempe uk kecil\", \"2 pasang ati ampela (optional)\", \"Cabe rawit 10 biji (tergantung selera)\", \"4 siung Bawang merah\", \"3 siung Bawang putih\", \"secukupnya Garam\", \"secukupnya Gula\", \"Kaldu ayam bubuk(kalau suka) q pake royco\", \"Tepung bumbu seba guna\", \"secukupnya Minyak goreng\"]', '[\"Cincang cabe rawit, bawang putih, bawang merah\", \"Potong dadu tempe,ati ampela(yg sudah digoreng sebelumnya), bersihkan udang dari kulitnya cuci sampai bersih\", \"Goreng tempe yg sudah di potong dadu dengan tepung serba guna biar nempel tempe di Kasih air sedikit atau bisa dicelupkan ke kocokan putih telur,goreng sampai kecoklatan lalu angkat dan tiriskan\", \"Tumis bawang merah dan bawang putih sampe layu lalu masukan cabe tumis sampe wangi\", \"Masukan udang dulu, baru ati ampela dan tempe yg sudah digoreng masukan paling akhir\", \"Beri garam, gula, dan kaldu bubuk secukupnya koreksi rasa dan siap dihidangkan\", \"Siap dimakan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(983, 2, 'Oseng Tempe & Kacang Panjang', 'Buat Oseng Tempe & Kacang Panjang yang nikmat dengan langkah-langkah mudah ini.', '[\"200 gr tempe\", \"50 gr kacang panjang\", \"7 bh bawang merah\", \"2 bh bawang putih\", \"2 lbr daun jeruk\", \"Laos (secukupnya di geprek)\", \"Merica (secukupnya)\", \"Garam, gula,kecap\"]', '[\"Iris tempe sesuai selera, setelah di iris goreng setengah matang. Iris semua bahan di atas & tumis hingga harum ke coklatan, tambah kan air secukupnya masukan tempe & kacang panjang. Tunggu hingga matang dan siap untuk di sajikan 😘\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(984, 4, 'Tempe tepung sambel kecap', 'Nikmati kelezatan Tempe tepung sambel kecap dengan resep sederhana ini.', '[\"10 iris tempe\", \"1 sdm duan bawang yang diiris tipis\", \"350 ml air matang\", \"250 gr tepung terigu\", \"1 sdm tepung beras\", \"minyak goreng\", \"Bumbu Halus:\", \"1 sdt ketumbar sangrai\", \"2 siung bawang putih\", \"1 sdt kaldu ayam\", \"1 sdt garam\"]', '[\"Kerat-kerat kedua sisi irisan tempe agar bumbu menyerap.\", \"Campur tepung dengan bumbu halus dan air hingga cukup kental.\", \"Tambahkan daun bawang dan tempe.\", \"Panaskan minyak banyak di atas api sedang.\", \"Goreng tempe dengan balutan adonantepung hingga kuning kecokelatan.\", \"Angkat dan tiriskan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(985, 3, 'Tempe goreng', 'Sajian tempe lezat: Tempe goreng penuh protein nabati.', '[\"1/2 papan Tempe\", \"2 siung bawang putih\", \"Secukupnya Ketumbar\", \"Secukupnya garam\", \"Minyak goreng\"]', '[\"Potong tempe sesuai selera\", \"Uleg ketumbar dan bawang putih hingga halus, kemudian tambahkan bawang putih, uleg lagi hingga halus\", \"Tambahkan sedikit air putih dan rendam tempe selama 15 menit\", \"Panaskan minyak dan goreng tempe hingga kecoklatan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(986, 4, 'Tempe jeletot', 'Nikmati kelezatan Tempe jeletot dengan resep sederhana ini.', '[\"1 papan tempe\", \"6 siung bawang putih\", \"6 siung bawang merah\", \"5 buah cabe keriting\", \"secukupnya Kencur\", \"sesuai selera Cabe rawit\", \"Daun bawang\", \"1/4 kg tepung terigu\", \"6 sendok makan tepung beras\", \"Penyedap rasa dan garam\", \"Ketumbar\", \"Minyak untuk menggoreng\"]', '[\"Potong tempe belah tengah jangan sampai putus\", \"Isian: ulek bumbu hingga halus setelah halus siram bumbu dengan minyak goreng\", \"Adonan tepung: haluskan 2 siung bawang merah,putih, ketumbar beri garam dan kaldu lalu larutkan tepung terigu dan tepung beras dengan air, beri daun bawang, koreksi rasa\", \"Isi tempe dengan cabe,lakukan hingga tempe habis terisi cabe\", \"Panaskan minyak,celupkan tempe di adonan tepung goreng sampai matang\", \"Sajikan selagi hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(987, 3, 'Oseng buncis tempe', 'Resep praktis Oseng buncis tempe yang bisa dicoba di rumah.', '[\"2 bungkus buncis\", \"1 papan tempe\", \"8 siung bawang merah\", \"5 siung bawang putih\", \"10 cabe rawit\", \"masako\", \"sedikit air\", \"garam\", \"gula\"]', '[\"Potong tempe menjadi tipis\\\" juga lalu goreng setengah matang\", \"Iris tipis\\\" bawang merah bawang putih dan cabe rawit, oseng sebentar bawang merah dan bawang putih\", \"Potong serong buncis menjadi tipis dan cuci bersih. oseng buncis sampai layu dan masukkan bawang merah dan bawang putih lalu masukkan tempe setengah matang.\", \"Setelah tercampur masukkan cabe rawit dan beri air secukupnya\", \"Tambahkan gula garam dan masako secukupnya tes rasa bila rasa kurang tambahkan masako lagi\", \"Masak sebentar lalu sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(988, 4, 'Kering Tempe Cabjo', 'Kering Tempe Cabjo - olahan tempe khas Indonesia yang nikmat.', '[\"4 papan tempe plastik ukuran sedang\", \"1 butir jahe (di peprek)\", \"1 butir lengkus (di peprek)\", \"1 butir kamijara (di peprek)\", \"2 lembar daun salam (di remas)\", \"Gula merah secukupnya (disisir)\", \"Cabai secukupnya (menurut selera)\", \"secukupnya Minyak\", \"secukupnya Bawang solong\", \"Bumbu yang di haluskan (bumbu kuning) :\", \"1 butir kunyit\", \"2 siung bawang putih\", \"5 siung bawang merah\", \"1 butir kemiri\", \"1 butir ketumbar\", \"secukupnya Pala\", \"secukupnya Lada\", \"secukupnya Garam\"]', '[\"Irislah tempe menjadi bagian bagian kecil memanjang.\", \"Iris cabai, bawang solong dan daun salam. Sisir gula merah.\", \"Jahe, lengkuas dan kamijara di peprek.\", \"Siapkan ulekan, masukan kunyit, kemiri, bawang putih, bawang merah, ketumbar, lada, pala, garam. Haluskan.\", \"Goreng tempe yang sudah diiris.\", \"Angkat jika sudah berwarna kecoklatan.\", \"Setelah itu siapkan wajan lagi, panaskan minyak dan tumis bawang solong, jahe, lengkuas, kamijara, daun salam, cabai dan masukan gula merah yang telah di sisir.\", \"Setelah tercium harum dan menggoda di perut beri air sedikit dan masukan tempe yang sudah di goreng.\", \"Aduk sampai benar benar merata dan meresap, tes rasa.\", \"Apabila rasanya kurang asin bisa tambahkan masako atau royco secukupnya. Aduk lagi hingga masak.\", \"Angkat dan sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(989, 4, 'Kering tempe renyah', 'Kering tempe renyah - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 papan tempe ukuran sedang (25x20 cm), potong kecil-kecil\", \"Bumbu halus ::\", \"6 butir bawang merah\", \"3 siung bawang putih\", \"2 cm lengkuas muda\", \"3 cabe rawit merah\", \"Bahan lain ::\", \"3 cabe keriting, iris serong\", \"2 helai daun salam\", \"1 buah jeruk nipis seukuran bola pingpong, peras\", \"Secukupnya garam dan gula\", \"2-3 sdm minyak untuk menumis\"]', '[\"Goreng tempe hingga kuning kecoklatan dan renyah. Sisihkan.\", \"Tumis bumbu halus hingga harum, masukkan daun salam dan cabe keriting iris, gula dan garam, aduk rata.\", \"Tambahkan air perasan jeruk nipis, aduk, koreksi rasa, tunggu sampai air menyusut dan bumbu kental. Matikan api.\", \"Tunggu sesaat sampai bumbu tidak beruap/dingin, masukkan tempe, aduk rata. Kalau sudah dingin, simpan dalam toples kedap udara.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(990, 2, 'Oseng Tempe Buncis', 'Resep praktis Oseng Tempe Buncis yang bisa dicoba di rumah.', '[\"1/3 papan tempe (seadanya stok) potong kotak2\", \"7 batang buncis (adanya itu)\", \"1 batang daun bawang\", \"2 siung bawang putih (cincang halus)\", \"1/4 bw bombay (kehabisan stok bawang merah hiks)\", \"1 sdm kecap\", \"1/2 sdm saori saus tiram\", \"1/2 cm laos geprek\", \"1/2 cm jahe geprek\", \"1 bh jeruk limau kecil\"]', '[\"Goreng tempe sisihkan.\", \"Tumis bw bombay, bw putih, jahe n lengkoas hingga harum.\", \"Masukan saori n kecap aduk2 beri sedikiiit air, masukan buncis. Hingga agak layu masukan tempe.aduk2 sebentar. Matikan api.\", \"Peras jeruk limau dan Hias dgn daun bawang.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(991, 2, 'Nasi Liwet Tempe bacem', 'Resep praktis Nasi Liwet Tempe bacem yang bisa dicoba di rumah.', '[\"20 potong tempe\", \"500 ml air kelapa\", \"1 buah gula merah\", \"1 sdt garam\", \"Sdikit kaldu bubuk\", \"2 lbr daun salam\", \"1 vatang serai\", \"1 ruas lengkoas\", \"Minyak u menggoreng\", \"Bumbu halus:\", \"5 siung bamer\", \"2 siung baput\", \"1 sdt ketumbar\", \"3 butir kemiri\"]', '[\"Campur tempe air kelapa dan bumbu halus dan salam sereh lengkoas gula garam fan kaldu bubuk. Sampai air menyusut. Lalu goreng dengan api kecil. Selamat masak.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(992, 2, 'Oseng Tempe Kacang Panjang Udang', 'Cara membuat Oseng Tempe Kacang Panjang Udang yang enak dan praktis untuk keluarga.', '[\"1 ikat kacang panjang, potong seukuran korek\", \"1 papan tempe, potong korek & goreng\", \"100 gr udang, buang kepala\", \"5-7 siung bawang merah, iris2\", \"1 siung bawang putih, geprek\", \"5 buah cabe merah, iris serong\", \"1 ruas lengkuas, geprek\", \"2 lembar daun salam\", \"1 sdm gula merah\", \"Secukupnya gula pasir, garam & kaldu bubuk\", \"Secukupnya air\", \"Sedikit minyak utk menumis\"]', '[\"Tumis duo bawang sampai layu & harum. Masukan cabe, lengkuas & daun salam, aduk-aduk.\", \"Masukan udang, masak sampai udang berubah warna. Masukan kacang panjang, aduk-aduk. Tambahkan gula merah dan beri air sedikit.\", \"Masukan tempe, gula pasir, garam & kaldu bubuk. Beri air lagi utk mematangkan kacang panjang, aduk rata. Koreksi rasa.\", \"Masak sampai air agak mengering & kacang panjang matang. Matikan api, angkat & sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(993, 3, 'Orek tempe cabai hijau', 'Resep Orek tempe cabai hijau ala rumahan yang dijamin menggugah selera.', '[\"1 papan tempe\", \"10 buah cabai hijau keriting\", \"3 siung bawang merah\", \"3 siung bawang putih\", \"1 ruas lengkuas\", \"1 lembar daun salam\", \"Secukupnya kecap manis\", \"Secukupnya gula merah\", \"Garam\", \"Penyedap rasa\"]', '[\"Potong-potong tempe seuk korek api(sesuai selera cie ukurannya)😉😉😉.\", \"Panaskan minyak,goreng tempe sampai garing,sisihkn.\", \"Potong semua semua bumbu,geprek lengkuas.\", \"Panaskan minyak masukan bumbu yg sdh di potong td,tunggu sampai harum,masukan tempe beri sedikit air,setelah agak mengering masukan kecap,cek rasa.\", \"Orek tempe cabai hijau siap di sajikan😉😉\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(994, 3, 'Kikil tempe pedas manis', 'Sajian Kikil tempe pedas manis yang praktis dan lezat untuk dinikmati bersama.', '[\"1/4 kikil\", \"1 papam tempe\", \"bumbu halus\", \"6 siung bawang merah\", \"3 siung bawang putih\", \"5 bh cabe keriting merah (selera)\", \"8 bh cabe rawit merah (selera)\", \"3 bh cabe ijo besar\", \"2 Lmbar daun salam\", \"1 ruas kunyit\", \"1 ruas laos\", \"kecap manis\", \"kecap asin\", \"penyedap rasa\", \"garam, gula\", \"minyak goreng\"]', '[\"Rebus sbentar kikil, daun salam dn laos.. lalu tiriskan\", \"Potong dadu tempe lalu goreng dan tiriskan\", \"Panaskan minyak, masukan bumbu halus beserta daun dan salam laos smpe harum\", \"Lalu campurkan kikil dan tempe, tambahkan kecap manis, kecap asin, penyedap rasa, gula dn garam\", \"Aduk hingga trcampur rata,\", \"Koreksi rasa... lalu hidangkan...\", \"Happy cooking bunda😘😘\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(995, 2, 'Nugget tempe keju', 'Nikmati kelezatan Nugget tempe keju dengan resep sederhana ini.', '[\"400 gr tempe\", \"200 gr daging ayam giling\", \"4 sdm terigu\", \"2 siung bawang putih haluskan\", \"2 btr telur\", \"1 sdt garam (blh lbh)\", \"1/2 sdt merica bubuk (blh skip)\", \"1 sdt penyedap rasa sapi\", \"60 gr keju parut\", \"Sckup nya daun bawang Iris halus (blh skip)\", \"💞 pelapis 💞\", \"4 Btr telor kocok\", \"Seckup nya Breadcrumb\"]', '[\"Campur semua bahan, tuang dloyang yg d oles minyak dl.. Kukus 25 mnit smpe matang. Dinginkan, potong2, celup d pelapis (kocokan telur - bread crumb)\", \"Selamat mencoba 😂😂\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(996, 4, 'Tempe Tumis Ikan Asin', 'Resep Tempe Tumis Ikan Asin ala rumahan yang dijamin menggugah selera.', '[\"2 ekor ikan asin jenis apa sj\", \"2 buah tomat\", \"2 cabe merah besar\", \"3 siung bawang putih\", \"3 cabe merah keriting\", \"4 Batang cemangi,ambil daun sj\", \"5 Siung bawang merah\", \"15 cabe rawit\", \"1/4 tempe\", \"Secukupnya garam\", \"Secukupnya masako\", \"Secukupnya merica bubuk\", \"Secukupnya gula pasir\", \"Minyak goreng\"]', '[\"Rendam tempe dgn air garam,biarkan meresap,sisihkan.Cuci ikan asin,potong 2 bagian,sisihkan.\", \"Uleg halus semua bumbu,sisihkan.\", \"Goreng tempe hingga kering juga ikan asin,lakukan hingga habis.sisihkan.\", \"Tumis bumbu halus hingga wangi,masukan Masako,gula,garam,merica icip rasa jika telah pas masukan tempe dan ikan asin beserta kemangi,aduk rata tanpa menambah air y bunda.\", \"Biarkan kering dan angkat...sippp😊😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(997, 4, 'Kering tempe', 'Resep Kering tempe ala rumahan yang dijamin menggugah selera.', '[\"1/2 papan tempe besar\", \"2 buah cabai besar\", \"1/2 potong gula merah kecil\", \"1 sdm gula pasir\", \"1 lembar daun salam\", \"1 ruas jahe (saya td gapake karna gaada jahe di rumah)\", \"Sereh\", \"Bumbu halus :\", \"4 siung bawang merah\", \"3 siung bawang putih\", \"1 ruas lengkuas/laos\", \"secukupnya Garam\", \"Lada secukupnya (cuma buat pedes\\\"an)\"]', '[\"Tempe diiris memanjang (persegi panjang) kecil kecil. Panaskan minyak, goreng tempe setengah matang dan tiriskan\", \"Haluskan bumbu terlebih dahulu, untuk lengkuas dan jahe cukup di geprek aja.\", \"Iris cabai secara menyamping\", \"Panaskan minyak, masukkan bumbu yang telah dihaluskan, tumis hingga harum kemudian masukkan irisan cabai, daun salam lengkuas dan jahe.\", \"Masukkan gula merah dan gula pasir, tambah sedikit air. Biarkan hingga mengental\", \"Setelah mengental, masukkan tempe yg sudah digoreng setengah matang, campur hingga merata\", \"Kering tempe siap disajikan :)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(998, 4, 'Tempe mercon kekinian', 'Sajian Tempe mercon kekinian yang praktis dan lezat untuk dinikmati bersama.', '[\"1 papan tempe ukuran sedang (dipotong bagi 5 bagian)\", \"2 siung bawang putih\", \"2 siung bawang merah\", \"10 biji cabe rawit domba\", \"1/4 sdt Merica bubuk\", \"secukupnya Daun bawang\", \"5 sdm tepung terigu\", \"1/2 ruas kencur\", \"Secukupnya penyedap rasa\", \"Secukupnya air\", \"Secukupnya minyak kelapa\"]', '[\"Potong tempe, kira kira tidak terlalu tipis dan tidak terlalu besar, lalu tengahnya dipotong sedikit / diberi lubang untuk memasukan bumbu pedasnya, tumbuk cabe rawit, kencur, bawang putoh, dan bawang merah beri sedikit garam dan gula.\", \"Adonan tepung : masukan terigu kedalam wadah beri garam, penyedap rasa, dan merica bubuk, lalu masukan juga daun bawang yg telah diiris tipis.\", \"Setelah adonan tepung dan tempe siap.. Lalu digoreng. Gunakan api sedang agar tempe yg didalam tepung matang..\", \"Simple... Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(999, 2, 'Tumis tempe peda', 'Tumis tempe peda - olahan tempe khas Indonesia yang nikmat.', '[\"2 ekor peda, buang tulang tengah, potong potong\", \"1 papan tempe, potong dadu, goreng ½ matang\", \"1 sdm kecap manis\", \"secukupnya Garam\", \"Bumbu iris:\", \"2 buah cabe merah, iris serong\", \"4 buah cabe hijau, iris serong\", \"Cabe rawit secukupnya, iris serong\", \"4 butir bawang merah, iris tipis tipis\", \"4 siung bawang putih, iris tipis tipis\", \"3 buah tomat, potong potong\"]', '[\"Tumis bumbu iris kecuali tomat hingga harum\", \"Masukkan tempe, ikan peda, tomat, kecap, beri dikit air, masak hingga agak menyusut airnya, tes rasa kalo kurang asin baru kasi garam (hati hati pemberian garam sebab peda sudah asin)\", \"Masak hingga air menyusut dan bumbu meresap, matikan api\", \"Siap disajikan bersama nasi hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1000, 3, 'Orek tempe', 'Buat Orek tempe yang nikmat dengan langkah-langkah mudah ini.', '[\"1 papan tempe\", \"Bumbu :\", \"4 biji cabe\", \"3 siung bawang merah\", \"1 siung bawang putih\", \"secukupnya Kecap manis\", \"secukupnya garam, micin, royco\"]', '[\"Langkah membuat.potong2 tempe menurut selera. Setelah itu goreng tempe sampk coklat. Setelah itu haluskan bumbu setelah siap semua goreng bumbu halus sampai harum setelah itu beri garem,micin,roico aduk2 dan masukan tempe beri kecap aduk2 kembali.lalu angkat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1001, 3, 'Tempe Bacem Mantap', 'Resep praktis Tempe Bacem Mantap yang bisa dicoba di rumah.', '[\"8 Potong Tempe\", \"1 Butir Asam\", \"2 Lembar Salam\", \"1 Ruas Langkuas Geprek\", \"Bumbu Ulek:\", \"5 Siung Bawang Merah\", \"2 Siung Bawang Putih\", \"Secukupnya Ketumbar, Garam, Kaldu, air dan kecap/gula merah\"]', '[\"Masukan semua bahan dan bumbu ulek ke dalam panci, beri secukupnya air, garam, kaldu, dan kecap.\", \"Masak sampai airnya menyusut. Angkat.\", \"Di goreng lagi enak. Dimakan langsung juga enak. Dihidangkan dengan nasi akeul lebih enak. :)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1002, 3, 'Tumis toge dan tempe simple gak pake lama', 'Resep Tumis toge dan tempe simple gak pake lama ala rumahan yang dijamin menggugah selera.', '[\"Sebungkus toge\", \"secukupnya Tempe\", \"2 siung bawang putih\", \"2 siung bawang merah\", \"1/2 bawang bombay ukuran sedang\", \"3 buah cabe rawit\", \"Kecap manis\", \"Saus tiram\", \"Air\"]', '[\"Rajang semua bumbu.\", \"Iris tempe kotak* dan bersihkan toge bagian ekornya.\", \"Goreng tempe terlebih dahulu sampai setengah kering. Tiriskan\", \"Kemudian tumis bumbu yg sudah dirajang kemudian masukkan garam, tempe dan toge.\", \"Masukkan kecap dan saus tiram secukupnya.\", \"Kemudia masukkan sedikit air agar bumbu meresap dan rata. Tunggu mendidih kemudian tes rasa. Me sampai air menyusut habis.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1003, 2, 'Oseng Teri Tempe', 'Sajian Oseng Teri Tempe yang praktis dan lezat untuk dinikmati bersama.', '[\"1 ons ikan teri\", \"1 tempe (potong dadu)\", \"10 cabe rawit\", \"4 biji bawang putih\", \"6 biji bawang merah\", \"4 lembar daun jeruk\", \"1 buah tomat (potong dadu)\", \"Air\", \"Garam\"]', '[\"Cuci ikan teri dengan air bersih\", \"Goreng setengah matang tempe dan ikan teri\", \"Potong tipis bawang merah, bawang putih, daun jeruk, dan cabe rawit (sisakan 4 cabe rawit untuk diuleg)\", \"Tumis bumbu yang telah dipotong tipis sampai layu, masukkan cabe yang telah diuleg, tambahkan sedikit air dan garam\", \"Masukkan tempe dan ikan teri yang telah digoreng setengah matang\", \"Koreksi rasa, kemudian masak hingga bumbu meresap\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1004, 4, 'Kering tempe teri', 'Resep Kering tempe teri ala rumahan yang dijamin menggugah selera.', '[\"5 tempe (bungkus daun) atau 1 papan tempe\", \"Segenggam teri\", \"1 buah h tomat\", \"2 cm lengkuas\", \"4 daun jeruk\", \"3 daun salam\", \"Air asam jawa 2 sdm (larutkan asam jawa dalam air panas, ambil)\", \"3 cabe keriting hijau\", \"2 sdm kecap\", \"1 sdt gula merah\", \"💋bumbu halus:\", \"8 bawang merah\", \"5 bawang putih\", \"10 cabe rawit\", \"Garam\", \"Merica\", \"Penyedap\"]', '[\"Potong2 tempe lalu goreng hingga kering\", \"Uleg kasar bumbu halus\", \"Potong tomat dan cabe\", \"Goreng teri sebentar lalu tiriskann\", \"Tumis bumbu halus hingga harum, masukkan lengkuas daun jeruk daun salam. Lalu bumbui dengan garam, merica, gula merah dan kecap serta air asam jawa.. Aduk2 hingga rata\", \"Masukkan tomat, cabe hijau trakir tempe dan teri. Masak hingga tercampur dan bumbu meresap.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1005, 3, 'Tempe Teriyaki', 'Sajian Tempe Teriyaki yang praktis dan lezat untuk dinikmati bersama.', '[\"1 papan Tempe\", \"5 Bawang putih cincang\", \"2 Bawang Bombai(kecil)\", \"Saus teriyaki\", \"Kecap manis\", \"Lada\"]', '[\"Potong tempe menjadi kotang kotak\", \"Lalu goreng tempe stngh matang saja, dan tiriskan\", \"Kemudian tumis bawang putih dan bawang bombai sampai harum, beri kecap manis,lada dan saos teriyaki sedikit (tidak pakai garam ya soalnya saos teriyakinya sudah asin)\", \"Baru masukan tempe yang tadi di goreng aduk rata, kalau kecap manis dan saus teriyaki kurang bisa di tambah\", \"Dan Tempe Teriyaki siap di sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1006, 4, 'Tumis buncis tempe', 'Tumis buncis tempe - olahan tempe khas Indonesia yang nikmat.', '[\"10 buncis potong miring\", \"Tempe iris sesuai selera trus goreng (jgn terlalu kering)\", \"1 buah tomat\", \"3 siung bawang putih iris\", \"3 siung bawang merah iris\", \"3 cabai (menurut selera)\", \"secukupnya Kecap\", \"Secukupnya Garam\", \"secukupnya Gula\", \"penyedap rasa\"]', '[\"Tumis bawang putih, bawang merah dan cabe sampai harum\", \"Masukkan buncis, aduk rata sampai agak layu\", \"Masukan tempe yg sdh digoreng aduk rata\", \"Tambahkan gula, garam, prnyedap rasa, dan kecap... cek rasa\", \"Sajikan\", \"So yummy\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1007, 2, 'Tempe Orek', 'Buat Tempe Orek yang nikmat dengan langkah-langkah mudah ini.', '[\"1 papan tempe uk.besar\", \"2 keping gula merah kecil\", \"2 lembar daun jeruk\", \"1 lembar daun salam\", \"1 sdm peres gula pasir\", \"Bumbu iris :\", \"5 bawang merah uk.besar\", \"3 bawang putih\", \"7 cabe merah kriting\", \"3 cabe rawit merah\", \"Secukupnya air matang\"]', '[\"Potong tipis2 tempe, cuci bersih tiriskan beri secukupnya garam, lalu goreng kering, tiriskan,sisihkan.\", \"Tumis bumbu iris,daun salam, daun jeruk, lalu tambahkan gula merah, gula pasir dan secukupnya air, masak sampai mengental, beri garam,test rasa.Masukkan tempe,aduk rata. Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1008, 2, 'Tempe Orek Basah', 'Resep praktis Tempe Orek Basah yang bisa dicoba di rumah.', '[\"1 papan tempe uk sedang, potong dadu\", \"2 lembar daun salam (tambahan dr saya)\", \"Seruas jempol lengkuas, memarkan (tambahan dr saya)\", \"Secukupnya kecap manis\", \"Secukupnya garam, gula dan kaldu bubuk (sy pk kaldu jamur)\", \"Secukupnya air matang\", \"1 buah jeruk limau uk besar, ambil airnya (tambahan dr saya)\", \"Bumbu yg dihaluskan :\", \"5 siung bawang merah\", \"2 siung bawang putih (sy pk bawang putih kating)\", \"1/2 buah tomat\", \"2 buah kemiri(sangrai/goreng)\", \"2 buah cabai merah besar\", \"1/2 sdt ketumbar\"]', '[\"Goreng tempe yg sudah dipotong dadu sebentar sampai kecoklatan (jangan sampai kering ya)\", \"Tumis bumbu halus, salam dan lengkuas menggunakan minyak sayur sampai harum dan matang. Lalu masukan air secukupnya. Aduk rata. Biarkan mendidih. Tuang kecap manis dan bumbu lainnya. Aduk rata kembali dan tes rasa.\", \"Masukan tempe yg sudah digoreng tadi, aduk merata. Masak sampai bumbu meresap. Matikan kompor. Beri air perasan jeruk limau. Aduk rata. Siap disajikan.\", \"Sajikan bersama nasi hangat.. sooo yummyy👍👌.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1009, 2, 'Tumis sawi hijau plus tempe', 'Cara membuat Tumis sawi hijau plus tempe yang enak dan praktis untuk keluarga.', '[\"2 ikat sawi hijau\", \"1 bungkus tempe\", \"Bumbu:\", \"4 siung bawang merah(iris tipis²)\", \"2 siung bawang putih (iris tipis²)\", \"5 buah cabe rawit merah(potong jadi 3 bagian)\", \"1 sedok teh garam\", \"secukupnya gula pasir\", \"penyadap rasa\", \"secukupnya air\"]', '[\"Potong sawi hijau lalu cuci bersih\", \"Goreng tempe setengah matang\", \"Tumis bawang merah, bawang putih,dan cabe hingga harum\", \"Masukan sawi hijau dan tempe.. tambah kan air secukupnya\", \"Masukan gula, garam,dan penyedap rasa.. icip rasa..tunggu air sampai menyusut lalu hidang kan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1010, 2, 'Tempe mendoan melet', 'Tempe mendoan melet - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 papan tempe\", \"4 buah tahu putih\", \"Bahan sambal:\", \"12 siung bawang merah\", \"5 siung bawang putih\", \"Cabe rawit (saya pakai 100biji karena suka pedas)\", \"1 buah tomat\", \"secukupnya Gula & garam\", \"Bahan tepung:\", \"1 sdm tepung tapioka\", \"6 sdm tepung terigu\", \"3 siung bawang putih\", \"secukupnya Ketumbar bubuk\", \"Bubuk kaldu (saya pakai ayam)\", \"Air\", \"Minyak untuk menggoreng\"]', '[\"Pertama buat sambal dulu, masukkan bawang merah, bawang putih, tomat, cabe rawit ke food processor (bisa juga di ulek) jangan sampai terlalu halus\", \"Tumis bahan sambal yang sudah siap, bubuhkan garam dan gula tes rasa, sisihkan\", \"Buat adonan tepung, haluskan bawang putih, campurkan dengan tepung terigu dan tapioka, masukkan garam dan bubuk kaldu, masukkan air tapi jangan terlalu kental, sisihkan\", \"Belah tempe dan tahu, ushakan agar agak tebal karena masih akan diisi sambal\", \"Masukkan sambal ke dalam tahu dan tempe yang sudah dibelah\", \"Masukkan tempe dan tahu ke dalam tepung, dan siapkan minyak untuk menggoreng\", \"Goreng dalam keadaan minyak sudah cukup panas dan tidak perlu sampai berubah coklat\", \"Siap disajikan hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1011, 3, 'Orek tempe basah cabe ijo', 'Resep Orek tempe basah cabe ijo ala rumahan yang dijamin menggugah selera.', '[\"1 papan tempe(aku bli 2000)\", \"3-4 sdm kecap manis\", \"secukupnya Gula, garam, kaldu bubuk\", \"Bumbu yg di haluskan:\", \"5 siung bawang merah(agak kecil2 bawangnya)\", \"2 siung bawang putih\", \"4 buah cabe merah keriting\", \"3 buah cabe rawit orange\", \"1 butir kemiri\", \"1/4 sdt ketumbar bubuk\", \"Pelengkap:\", \"3 buah cabe ijo besar, iris\", \"2 lembar daun salam\", \"1 ruas lengkuas\", \"100 ml Air kurang lebih\"]', '[\"Potong2 tempe,lalu goreng. Jangan terlalu kering.\", \"Tumis bumbu yg di haluskan, masukan daun salam dan lengkuas timis hingga bumbu matang dan harum.\", \"Masukan kecap, cabe ijo, beri air.\", \"Masukan gula, garam, dan kaldu bubuk. Tes rasa.\", \"Masukan tempe yg sudah d goreng. Aduk rata\", \"Jika air sudah aga menyusut dan tasa sudah pas. Angkat dan sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1012, 2, 'Tumis kacang panjang-tempe', 'Sajian Tumis kacang panjang-tempe yang praktis dan lezat untuk dinikmati bersama.', '[\"10 helai kacang panjang, potong\", \"1 papan tempe, iris, goreng\", \"Daun salam\", \"Bumbu:\", \"3 buah bawang merah\", \"2 buah bawang putih\", \"2 buah kemiri\", \"1/2 sdt lada\", \"Garam, gula\", \"Kecap manis\"]', '[\"Uleg bumbu hingga halus.\", \"Tumis bumbu hingga harum.\", \"Masukkan kacang panjang potong. Tambahkan air. Masak sampai matang.\", \"Masukkan tempe. Bumbui dengan kecap manis.\", \"Koreksi rasa. Sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1013, 2, 'Udang, Tempe, Terong balado', 'Nikmati kelezatan Udang, Tempe, Terong balado dengan resep sederhana ini.', '[\"250 gram udang\", \"200 gram tempe\", \"2 buah terong\", \"4 siung bawang putih\", \"4 siung bawang merah\", \"5 biji cabe merah keriting\", \"5 biji cabe rawit merah\", \"Garam\", \"Gula\", \"Kecap manis\", \"3 biji Tomat\"]', '[\"Cuci udang dan buang kepala nya, rendam pake jahe 10 menit.\", \"Potong tempe dan terong sesuai selera. Lalu goreng tempe, Terong dan udang setengah matang.\", \"Haluskan bumbu diatas. Kecuali tomat.\", \"Tumis bumbu smpai bau harum bru masukkan tomat. Tumis tomat smpai layu.\", \"Masukkan tempe, terong dan udang. Tambah kan air 250 ml. Agar bumbu meresap. Tunggu mendidih.\", \"Koreksi rasa. Tambahkan kecap manis.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1014, 4, 'Tahu tempe pedes manis', 'Cara membuat Tahu tempe pedes manis yang enak dan praktis untuk keluarga.', '[\"5 buah tahu kecil\", \"1 tempe daun\", \"2 batang daun bawang\", \"1/2 siung bawang bombay, iris\", \"3 siung bawang merah, iris\", \"2 siung bawang putih, cacah\", \"2 cabe rawit merah (sesuai selera)\", \"2 cabe rawit hijau\", \"Sejumput merica\", \"1 sendok makan saos tiram\", \"1 sendok makan kecap manis\"]', '[\"Potong kotak kotak semua tahu dan tempe. Kemudian goreng hingga setengah matang\", \"Tumis bawang bombay, bawang merah dan bawang putih\", \"Masukkan tahu dan tempe yg sudah di goreng\", \"Masukkan cabe, saos tiram, kecap manis dan merica\", \"Tambahkan sedikit air\", \"Masak hingga bumbu meresap\", \"Siap disajikan 😄\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1015, 4, 'Orek tempe ikan cuwe\'', 'Resep Orek tempe ikan cuwe\' ala rumahan yang dijamin menggugah selera.', '[\"1 kranjang ikan cuwe isi 4\", \"1 papan Tempe\", \"Bumbu2\", \"4 siung bawang merah\", \"1 siung bawang putih\", \"5 buah Cabai rawit\", \"Gula\", \"Garam\"]', '[\"Iris dadu tempe atau memanjang\", \"Goreng tempe dan ikan cuwe\'\", \"Uleg semua bumbu\", \"Panaskan minyak\", \"Masukkan bumbu yg sudah d uleg\", \"Tambahkan sdikir air\", \"Masukkan ikan cuwe\' dan tempenya\", \"Boleh d tmbahin kecap\", \"Cicipi jika rasanya kurg enak tmbahin penyedap..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1016, 4, 'Sayur terong tempe santan gampang', 'Sayur terong tempe santan gampang - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"2 buah terong diiris bulat\", \"1 papan tempe kecil, dipotong kotak kotak 1 cm\", \"2 lembar daun salam\", \"2 cm lengkuas, memarkan\", \"1 batang serai, memarkan\", \"3 buah cabai hijau iris serong\", \"600 ml santan (saya kara + air)\", \"1,5 sdt garam\", \"1 sdt gula pasir\", \"1/4 sdt merica bubuk\", \"Minyak goreng\", \"Bumbu halus :\", \"5 butir bawang merah\", \"3 siung bawang putih\", \"3 butir kemiri sangrai\", \"1/4 sdt ketumbar\", \"2 cm kunyit\"]', '[\"Panaskan minyak, goreng terong sampai agak layu. Sisihkan.\", \"Tumis bumbu halus, lengkuas, daun salam, serai hingga harum. Masukkan cabai lalu aduk hingga matang.\", \"Tuang santan. Masukkan gula, garam, merica. Aduk rata.\", \"Masukkan tempe, masak hingga matang. Aduk2 ya agar tidak pecah.\", \"Masukkan terong, masak hingga terong matang. Selesaiiiiii.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1017, 3, 'Tempe melet huhah', 'Tempe melet huhah - olahan tempe khas Indonesia yang nikmat.', '[\"1 papan tempe\", \"5 cabe rawit\", \"10 cabe merah keriting (sesuai selera)\", \"2 buah tomat\", \"2 siung bawang merah\", \"2 siung bawang putih\", \"Gula\", \"Garam\", \"Tepung bumbu/tepung terigu\"]', '[\"Bikin sambal dengan Haluskan cabe, bawang merah, bawang putih, tomat, tambah sedikit gula dan garam\", \"Tumis sambal dengan minyak\", \"Potong tempe, belah bagian tengah. Isi tempe dengan sambel yg sudah matang\", \"Balut tempe isi dengan tepung bumbu yg sudah diencerkan.\", \"Goreng tempe. Sajikan selagi hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1018, 3, 'Kering Tempe Harum', 'Sajian Kering Tempe Harum yang praktis dan lezat untuk dinikmati bersama.', '[\"3 papan tempe\", \"3 siung bawang putih\", \"6 siung bawang merah\", \"5 cabai merah (setan) optional tergantung selera\", \"3 lembar daun salam\", \"2 lembar daun jeruk nipis\", \"1 siung jahe\", \"1 siung laos\", \"1 siung sereh\", \"secukupnya garam\", \"secukupnya penyedap rasa\", \"secukupnya kecap manis\", \"secukupnya gula jawa / sesuai selera saya pakai 2 sisir gula jawa ukuran kecil\"]', '[\"Iris tempe sesuai selera ☺\", \"Goreng sampai kering\", \"Uleg bumbu-bumbu. Tambahkan garam setengah sendok teh atau sesuai selera.. karena saya suka asin jadi saya tambahkan agak banyak ☺\", \"Kecuali laos, jahe, sereh. Cukup di memarkan / geprek kasar\", \"Panaskan minyak tumis semua bumbu termasuk laos, jahe, daun jeruk, dan daun salam, sereh. Tambahkan gula jawa 2 sisir kecil / sesuai selera dan Kecap secukupnya\", \"Tambahkan air setengah gelas belimbing\", \"Jika semua sudah tercampur dan bau sudah harum\", \"Masukan kering tempe\", \"Tambahkan penyedap rasa (optional) sesuai selera\", \"Masak kurleb 5 menit.\", \"Tes rasa. Jika kurang manis atau asin bisa di tambahkan\", \"Angkat dan sajikan\", \"Harum sis baunya.. ☺☺\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1019, 2, 'Abon ikan tokol + tempe', 'Sajian Abon ikan tokol + tempe yang praktis dan lezat untuk dinikmati bersama.', '[\"1 kg ikan tongkol\", \"1 papan tempe\", \"1 prapat  bawang kering\", \"Bumbu halus\", \"30 buah cabe rawit klo suka pedas tmbahin\", \"5 siung bawang putih\", \"1 ruas kunyit\", \"1 cm jahe\", \"1 cm laos\", \"1 sendok teh lada\", \"1 sdm gula yg mau pke kecap bisa tp q pke gula\", \"1 sdt merica\", \"1 sdt garam\", \"1 masako rasa sapi\", \"dan minyak untuk mngoreng\"]', '[\"Bersihkan ikan buang kpla dan isi dalam lalu rebus jgn trllu matang atau lembek, sisihkan\", \"Potong tempe sesuai selera, q potong panjang kecil2, lalu goreng sisihkan\", \"Lalu giling ikan tongkol pke cobek giling ksar jangn smpe lembut sisihkan sbntar. Potong bawang tipis2 lalu goreng. minyak sisa dri bawang klo trllu bnyak kurangin untuk mnggoreng ikan nya sampe kering dengn api kecil sambil di aduk2.\", \"Campur semua bumbu lalu haluskan dan goreng sampe harum msukkn kecap/ gula dan masako rasa spi tadi secara brtahap klo bumbu sudah kluar harum nya msukkan ikan goreng sama tempe nya jgn lma2 lalu mtiin api nya. Klu sudah dingin msukkan bawang goreng tadi lalu aduk smpe mrata. Udah siap..\", \"Jgn lupa ya pas di rebus ksih garam merica tomat bawang putih 1 siung aja iris tipis\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1020, 3, 'Tahu tempe bacem', 'Resep Tahu tempe bacem ala rumahan yang dijamin menggugah selera.', '[\"1 kotak tahu putih\", \"1 papan tempe\", \"5 lembar daun salam & lengkuas\", \"1 batang sereh\", \"Gula merah\", \"Kecap\", \"Garam\", \"Bumbu halus :\", \"Ketumbar\", \"5 siung bawang merah\", \"2 siung bawang putih\"]', '[\"Tata daun salam dibawah kemudian tempe, tahu dan bumbu lainnya. Masukkan air sampai tahu terendam\", \"Masak sampai air hampir habis (menyusut) kemudian goreng.\", \"Nb : ini sih saya panggang berhubung minyak gorengnya lagi abis wkwkwkwkwk\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1021, 2, 'Tempe goreng mentega', 'Resep praktis Tempe goreng mentega yang bisa dicoba di rumah.', '[\"1 papan tempe, potong² menjadi persegi\", \"3 sdm tepung terigu\", \"1 sdm tepung tapioka\", \"1 sdt ketumbar bubuk\", \"1 sdt lada bubuk\", \"secukupnya garam\", \"1/2 sdt kunir bubuk\", \"secukupnya air\", \"minyak goreng\", \"3 sdm mentega\"]', '[\"Buat adonan dengan mencampurkan semua bahan kecuali tempe dan minyak goreng\", \"Masukkan tempe dan baluri dengan adonan\", \"Panaskan minyak dan mentega, goreng tempe hingga kecoklatan\", \"Angkat, sajikan, lebih nikmat selagi hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1022, 4, 'Orek tempe pedas', 'Cara membuat Orek tempe pedas yang enak dan praktis untuk keluarga.', '[\"1 papan Tempe\", \"20 Cabai kriting merah\", \"Tomat (jika mau tdk trll pedas)\", \"Jeruk limo 1 buah peras airnya\", \"5 Bawang merah\", \"3 Bawang putih\", \"Garam\", \"Gula\", \"Minyak goreng\"]', '[\"Potong2 tempe sesuai selera, goreng smp garing jgn gosong\", \"Ulek bumbu halus: duo bawang, tomat, garam, gula, tumis hingga wangi\", \"Masukkan tempe yg telah digoreng aduk rata, koreksi rasa\", \"Sajikan dengan sayur asem atau dengan nasi hangat sudah enak bgt ni orek tempe pedas👍🏻👍🏻slmt menikmati\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1023, 3, 'Tahu Tempe Bacem', 'Resep praktis Tahu Tempe Bacem yang bisa dicoba di rumah.', '[\"Tempe\", \"Tahu\", \"Gula merah\", \"Garam\", \"Kecap (boleh skip)\", \"Bumbu halus :\", \"Bawang merah\", \"Bawang putih\", \"Ketumbar\", \"Bumbu tambahan :\", \"Lengkuas (digeprek)\", \"Sereh (digeprek)\", \"Daun salam\"]', '[\"Potong tempe dan siapkan tahu\", \"Haluskan bumbunya kecuali yg di geprek dan daun salam\", \"Sediakan air untuk merebus (ungkep), lalu masukan bumbu halusnya\", \"Setelah bumbunya larut, masukan gula merah, garam, kecap. Lalu tahu dan tempe\", \"Tahu dan tempe sudah terendam dengan rebusan airnya, masukan sereh, daun salam dan lengkuas\", \"Koreksi rasa dan tunggu sampai airnya menyusut\", \"Setelah itu bisa langsung digoreng dan sisanya masukin kulkas deh\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1024, 3, 'Orek tempe kacang', 'Resep praktis Orek tempe kacang yang bisa dicoba di rumah.', '[\"1 papan tempe fresh 5000-an, potong tipis\\\" sedang\", \"3 sdm Kacang tanah\", \"secukupnya Minyak goreng fresh\", \"Bumbu halus:\", \"10 buah Cabe merah keriting, 7 dihaluskan, 3 diiris tipis\\\"\", \"5 butir Bawang merah\", \"3 siung Bawang putih\", \"1 ruas jari Lengkuas, memarkan\", \"1/2 ruas jahe, haluskan/memarkan\", \"2 lembar Daun salam\", \"4 lembar Daun jeruk\", \"1 batang Serai, potong, ambil bgian tebalnya, memarkan\", \"1-2 sdm Gula merah yg sdh disisir tergantung selera\", \"secukupnya Garam, gula\", \"Sdkt sj air (kurleb 2 sdm)\"]', '[\"Potong tempe tipis\\\" sprti gbr di atas. Goreng sampai berubah warna dan sdkt garing. Tiriskan.\", \"Selnjutnya goreng kacang hingga matang dan berubah warna. Jgn smpi gosong ya Bun.. nnti pahit.\", \"Kemudian tumis bumbu halus, masukan lengkuas, jahe, salam, daun jeruk,serai. Tumis sampai harum dan matang.\", \"Setelah itu beri air sedikit sj, masukan garam, sdkt gulpas (bs diskip trgntung selera) dan gula merah sisir. Aduk merata. Koreksi rasa.\", \"Setelah agak kental masukan tempe, menyusul kacang tanah, aduk hingga rata dan bumbu meresap. Matikan api.\", \"Taruh dipiring saji. Siap deh dinikmati utk teman makan ditambah lauk yg lainnya.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1025, 3, 'Tahu tempe telor bumbu bali ala mommies', 'Sajian Tahu tempe telor bumbu bali ala mommies yang praktis dan lezat untuk dinikmati bersama.', '[\"1 bks tempe (240gr)\", \"1 bks tahu (kira\\\" 1/4kg)\", \"4 butir telur ayam\", \"Bumbu halus :\", \"1 siung shallot ukuran besar (Kalo ukuran kecil 2 siung yay)\", \"4 siung bawang putih\", \"5 biji cabai rawit (skip kalau tdk suka pedas)\", \"Bumbu tambahan :\", \"Secukupnya garam\", \"Secukupnya gula\", \"Secukupnya Masako ayam\", \"Secukupnya lada putih\", \"Sere\", \"Daun salam\", \"Laos\", \"Jahe\", \"Bumbu Bali instan\", \"Minyak untuk menumis\", \"1 buah tomat\", \"2 Sdm kecap manis\"]', '[\"Siapkan bahan-bahan\", \"Potong- potong tempe dan tahu, sesuai selera\", \"Rebus telur sampai matang\", \"Haluskan shallots, bawang putih, dan cabai (boleh diblender), saya lebih suka diulek sih 😊\", \"Goreng tempe, tahu dan telur rebus (jangan terlalu matang) lalu tiriskan\", \"Tumis bumbu halus dan bumbu Bali instan, hingga baunya harum\", \"Lalu masukkan sere, jahe, Laos dan daun salam, tumis hingga wangi\", \"Masukkan tempe, tahu dan telur yang sudah digoreng kedalam tumisan bumbu\", \"Tumis sebentar hingga meresap, lalu tuang 2 gelas air\", \"Aduk hingga rata, lalu masukkan tomat\", \"Beri garam, gula, lada putih, dan Masako ayam secukupnya, lalu tes rasa\", \"Tambahkan sedikit kecap manis, kira-kira 2 atau 3 sendok makan sesuai selera, tunggu sampai airnya habis lalu angkat\", \"Siap dihidangkan, dimakan pake Nasi anget tambah kerupuk, maknyusss👻 Happy break fast, guys\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1026, 2, 'Sate Tahu & Tempe (Teflon)', 'Cara membuat Sate Tahu & Tempe (Teflon) yang enak dan praktis untuk keluarga.', '[\"2 tahu putih\", \"1/3 papan tempe (ukuran besar)\", \"1 ruas lengkuas\", \"1 daun salam\", \"2 sdm kecap manis\", \"Secukupnya garam\", \"Secukupnya penyedap (optional)\", \"Secukupnya gula pasir\", \"Bumbu Halus ;\", \"2 bawang putih\", \"4 bawang merah\", \"2 kemiri\", \"Secukupnya gula jawa\", \"1 sdt merica\", \"1/2 sdt ketumbar\"]', '[\"Potong tahu & tempe sesuai selera\", \"Masukkan tahu & tempe dalam panci bersama daun salam, lengkuas, kecap manis. Beri air sampai bahan terendam.\", \"Masak dengan api sedang, bumbui garam, gula pasir, penyedap. Koreksi rasa dan masak sampai kuah menyisut dan bumbu meresap.\", \"Susun tahu & tempe dengan tusuk sate/lidi.\", \"Panggang tahu & tempe diatas teflon dengan sedikit minyak.\", \"Lumuri sate dengan sisa bumbu tadi, kucuri kecap dan panggang sampai agak kering.\", \"Jangan lupa dibalik dan beri kecap di sisi lainnya. Sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1027, 3, 'Tempe orek iris', 'Buat Tempe orek iris yang nikmat dengan langkah-langkah mudah ini.', '[\"1/2 papan tempe (iris dadu)\", \"Kecap manis (secukupnya, sampai tempe berubah warna hitam)\", \"8 buah bawang merah (iris)\", \"3 buah bawang putih iris\", \"7 cabai merah keriting (iris)\", \"3 cabai rawit (iris)\", \"3 / 2 lembar daun salam\"]', '[\"Goreng irisan tempe sampai matang (sisihkan)\", \"Tumis bumbu2 iris nya setengah matang\", \"Masukkan tempe yg sudah di goreng\", \"Tambahkan kecap secukupnya\", \"Aduk rata, koreksi rasa, sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1028, 2, 'Oseng Mie Tempe ala QeeLa\'s Kitchen', 'Oseng Mie Tempe ala QeeLa\'s Kitchen - olahan tempe khas Indonesia yang nikmat.', '[\"1 bungkus Mie Urai (merah)\", \"1 papan tempe (potong kecil2)\", \"5 siung bawang putih\", \"8 siung bawang merah\", \"10 buah cabe rawit (sesuai selera)\", \"2 lembar daun salam\", \"1 ruas jahe (geprek)\", \"1 ruas lengkuas (geprek)\", \"secukupnya Garam\", \"secukupnya Gula\", \"5 sdm kecap manis\", \"secukupnya Air\", \"Minyak untuk menumis\"]', '[\"Rebus mie urai sampai hampir matang, angkat tiriskan\", \"Tumis duo bawang, cabe sampai harum, masukan lengkuas salam dan jahe\", \"Masukan tempe, air, kecap, gula dan garam biarkan mendidih dan agak menyusut\", \"Masukan mie yg sudah direbus tadi, aduk sampai semua tercampur rata... koreksi rasa\", \"Sajikan 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1029, 2, 'Bakso Tempe', 'Sajian Bakso Tempe yang praktis dan lezat untuk dinikmati bersama.', '[\"Terigu 6 sendok makan.. Tepung kanji 8 sendok Makan.. Tempe Sepapan Telur 1 Masako 1 Bawang Putih 3\"]', '[\"Potong Tempe kecl2 Lalu Kukus sampai 15 menit.. Kemudian Tumbuk Tempe Hingga Halus.. Lalu Haluskan bawang Putih(ulek) Lalu Campur kan Adonan Yg Sudah Di Siapkan.. Lalu uleni.. Lalu Di Bentuk Bulat2\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1030, 4, 'Lodeh tatem(tahu tempe)', 'Buat Lodeh tatem(tahu tempe) yang nikmat dengan langkah-langkah mudah ini.', '[\"1 bh tahu\", \"1 papan tempe(1000an)\", \"3 lbar daun salam\", \"3 lbar daun jeruk\", \"secukupnya Santan\", \"sedikit Gula\", \"secukupnya Air\", \"Lengkuas geprek sckpnya\", \"Bumbu halus:\", \"3 bh cabe keriting\", \"1 sdt ketumbar\", \"1 siung bawang putih\", \"2 siung bawang merah\", \"1/2 jari kunyit\", \"1 sdt garam\", \"2 btr kemiri\"]', '[\"Potong segitiga tahu tempe.uleg bumbu halus\", \"Tumis bumbu halus hingga wangi.masukkan daun salam daun jeruk lengkuas.masukan air sedikit tunggu mendidih.setelah mendidih masukan tahu tempe.ungkep sebentar.\", \"Setelah tahu tempe dirasa matang masukan santan gula,penyedap(jk suka).tunggu hingga mendidih.koreksi rasa.angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1031, 2, 'Orak arik tempe tahu teri', 'Buat Orak arik tempe tahu teri yang nikmat dengan langkah-langkah mudah ini.', '[\"1 buah tahu putih, potong kotak\", \"1/2 tempe lonjor, potong kotak\", \"1/2 ons teri medan\", \"bumbu halus :\", \"6 buah cabai merah keriting\", \"2 siung bawang putih\", \"3 siung bawang merah\", \"1/2 buah tomat\", \"sesuai selera garam, gula putih dan gula merah\"]', '[\"Goreng dahulu tempe, tahu dan teri. Sisihkan.\", \"Blender semua bumbu yang dihaluskan. Setelah itu, tumis bumbu halus hingga matang dan beri sedikit air. Aduk - aduk.\", \"Setelah bumbu agak matang, beri garam, gula putih, dan gula merah, aduk rata hingga matang.\", \"Masukan semua bahan, tempe, tahu dan teri. Aduk hingga tercampur rata dengan bumbu. Angkat dan Masakan siap dihidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1032, 3, 'Tumis kacang&tempe', 'Sajian Tumis kacang&tempe yang praktis dan lezat untuk dinikmati bersama.', '[\"1 ikat kacang panjang\", \"Tempe\", \"Bawang putih,\", \"bawang merah,\", \"cabe,\", \"tomat\", \"saus tiram,\", \"terasi\", \"Penyedap rasa,\"]', '[\"Potong kacang cuci bersih dan tempe\", \"Potong bahan bumbu sesuai selera..\", \"Tumis bumbu, masukan kacang dan tempe\", \"Tunggu hingga layu, dan kasi air secukupnya, sirami dengan saus tiram\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1033, 4, 'Sambel tempe semangit kemangi', 'Sambel tempe semangit kemangi - olahan tempe khas Indonesia yang nikmat.', '[\"1 papan tempe lanas\", \"1 genggam kemangi segar\", \"10 buah cabe merah keriting\", \"3 buah cabe rawit merah\", \"3 siung bawang putih\", \"4 siung bawang merah\", \"1 sdm gula pasir\", \"3 sendok makan minyak goreng\", \"secukupnya Garam\", \"secukupnya Bumbu kaldu\"]', '[\"Goreng tempe setengah matang ( jangan terlalu kering agar aromanya tetap ada?\", \"Goreng cabe, bawang merah dan bawang putih sebentar\", \"Uleg bawang putih,bawang merah, cabe dan garam haluskan,setelah sambal halus campurkan tempe ke sambel tadi dan uleg pelan agar tidak terlalu lembek dan hancur\", \"Siapkan minyak lalu tumis tempe yang sudah dicampur dengan sambel, tambahkan gula dan penyedap, koreksi rasa dan tumis sampe kering dan wangi\", \"Siapkan kemangi di atas cobek, lalu tuangkan tempe yang masih panas dan campur kemangi dengan tempe dengan menggunkan ulegan agar kemangi sedikit layu\", \"Sambal tempe semangit pedas dan gurih siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1034, 2, 'Terik Tempe', 'Cara membuat Terik Tempe yang enak dan praktis untuk keluarga.', '[\"10 potong tempe (goreng setengah matang)\", \"3 siung bawang putih\", \"6 siung bawang merah\", \"2 buah kemiri\", \"1 lembar daun salam\", \"50 ml santan encer\", \"1 batang daun bawang\", \"1 buah tomat potong2\", \"5 buah cabe rawit merah\", \"Secukupnya garam\", \"1 sdt gula merah\", \"1 sdm kecap manis\"]', '[\"Tumis bawang putih, bawang merah dan kemiri yang sudah dihaluskan terlebih dahulu, masak bersama daun salam hingga harum dan matang.\", \"Masukkan santan cair masak sampai mendidih jangan lupa diaduk aduk.\", \"Masukkan kecap, gula merah dan garam aduk rata.\", \"Kemudian masukkan tempe, daun bawang, tomat dan cabe rawit, masak hingga air mengental. Jangan lupa tes rasa ya bunda2 cantik\", \"Terik tempe siap untuk dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(1035, 3, 'Tempe salted egg', 'Tempe salted egg - olahan tempe khas Indonesia yang nikmat.', '[\"1/2 papan tempe\", \"100 gr terigu\", \"50 gr sagu\", \"Kaldu ayam bubuk\", \"Garam\", \"Merica\", \"Telor\", \"Saus salted egg:\", \"2 butir kuning telor asin.hancurkan\", \"Susu cair\", \"Bawang putih. Haluskan\", \"Mentega untuk menumis\"]', '[\"Campur terigu, sagu, kaldu bubuk, garam dan merica. Koreksi rasa.\", \"Kocok lepas telor, celupkan tempe di telor, gulingkan di tepung. Goreng\", \"Tumis bawang putih sampai harum, masukkan telur asin, tambahkan susu cair, masak dengan api kecil sambil terus diaduk sampai mengental. Angkat.\", \"Sajikan dengan tempe crunchy. Yummmmm 😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1036, 3, 'Tempe Bacem', 'Cara membuat Tempe Bacem yang enak dan praktis untuk keluarga.', '[\"2 papan tempe ukuran besar, potong dan kerat tiap sisinya\", \"600 ml air kelapa muda\", \"500 ml air biasa\", \"3 lembar daun salam\", \"1 Ibu jari lengkuas\", \"8 keping gula merah (ukuran kecil)\", \"1 SDM kecap manis\", \"Secukupnya asam jawa\", \"Secukupnya garam\", \"Bumbu Halus:\", \"8-10 butir bawang merah\", \"6 siung bawang putih\", \"1 SDM ketumbar\"]', '[\"Tuang air kelapa dan air biasa dalam wajan, masak dengan api sedang cenderung kecil, lalu masukkan bumbu halus, irisan gula merah, kecap manis, garam, asam jawa, daun salam dan lengkuas, aduk rata\", \"Tidak perlu menunggu hingga mendidih, masukkan potongan tempe, masak hingga semua air nya menyerap dan mengering, sesekali di aduk dan di balik ya tempenya, supaya air bumbu meresap di kedua sisi, koreksi rasa\", \"Setelah airnya kering, matikan api\", \"Kalo mau digoreng, gunakan api kecil aja ya supaya warnanya cakep gak gosong\", \"Kalo buat stok, biarkan uap panasnya hilang lalu simpan tempe bacem dalam wadah tertutup, simpan di lemari es\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1037, 4, 'Oseng - oseng tempe', 'Buat Oseng - oseng tempe yang nikmat dengan langkah-langkah mudah ini.', '[\"1 papan tempe\", \"bumbu :\", \"2 bh bawang putih\", \"3 bh bawang merah\", \"1 bh cabe merah, 1 bh cabe\", \"1 bh tomat\", \"garam, gula, penyedap\", \"minyak goreng\", \"air\"]', '[\"Tumis bumbu yg sudah di potong2 tadi hingga tercium harum\", \"Masukan tempe aduk dan tercampur beri kecap, garam, gula,penyedap tbhkan air sedikit. cicipi rasa\", \"Masak hingga matang\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1038, 2, 'Sambal tempe semangit', 'Cara membuat Sambal tempe semangit yang enak dan praktis untuk keluarga.', '[\"1 papan tempe\", \"7 cabai rawit\", \"6 cabai domba (cabai merah)\", \"2 siung bawang putih\", \"4 siung bawang merah\"]', '[\"Potong tempe. Lalu digoreng sampai setengah matang\", \"Goreng bawang putih, bawang merah, cabai.\", \"Setelah semua digoreng lalu diulek cabai, bawang merah, bawang putih. Setelah itu ulek tempe juga. Cukup ulek kasar.\", \"Bumbui dengan sedikit garam/kaldu bubuk, gula pasir. Incip rasa\", \"Goreng kembali dengan sedikit minyak\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1039, 3, 'Lodeh krecek tahu tempe', 'Sajian Lodeh krecek tahu tempe yang praktis dan lezat untuk dinikmati bersama.', '[\"1 plastik krecek (sekitar 250gr)\", \"1 papan tempe\", \"5 buah tahu matang\", \"3 lonjor pete\", \"200 ml santan instant\", \"Secukupnya air\", \"Seruas laos(sekitar 2cm geprek)\", \"2 lembar daun salam\", \"2 sdt gula pasir\", \"Secukupnya penyedap\", \"Bumbu halus:\", \"3 siung bawang putih\", \"6 siung bawang merah\", \"10 buah cabe rawit merah/ cabe gendut\", \"2 cm kunyit\", \"4 buah kemiri sangrai\", \"1 sdt garam\"]', '[\"Potong dadu tempe dan tahu, juga krecek lalu sisihkan iris jadi 2 pete lalu cuci bersih\", \"Haluskan semua bumbu halus lalu tumis tambahkan laos dan daun salam tumis sampai harum\", \"Masukkan pete lalu krecek biarkan sampai sedikit asat lalu masukkan tempe tahu beri air lalu santan kara\", \"Tambahkan gula dan penyedap aduk rata tunggu mendidih smbil diaduk bentar2 jangan sampe santan pecah\", \"Test rasa matikan kompor jika sudah benar2 matang/ mendidih\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1040, 4, 'Nugget tempe bumbu kuning', 'Resep praktis Nugget tempe bumbu kuning yang bisa dicoba di rumah.', '[\"1/4 kedelai bakal tempe\", \"21/2 sdm bumbu dasar kuning\", \"1 telur\", \"Garam\", \"Pelapis\", \"2 sdm terigu\", \"Tepung panir\"]', '[\"Haluskan kedele bakal tempe dg dry mill\", \"Kocok telur tambahkan bumbu dasar kuning dan garam\", \"Masukan tempe yg telah dihaluskan, aduk rata, masukan ke cetakan (aku pake cetakan brownis persegi panjang)\", \"Panaskan kukusan, kukus selama 15 menit, tunggu dingin, potong dan balur dg panir, simpan di kulkas atau taruh di frezzer\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1041, 3, 'Tempe Saus Mentega KW (ala anak kos)', 'Tempe Saus Mentega KW (ala anak kos) - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"2 papan tempe (beli @2000), potong dadu\", \"Boleh dimarinasi alias direndam airgaram+kaldu bubuk&lada bubuk\", \"1 buah bawang bombay ukuran besar (potong2)\", \"3 siung bawang putih -boleh skip- (geprek cincang)\", \"2 sdm kecap manis\", \"3 sdm saus tiram (pengganti kecap inggris, hehe)\", \"2 sachet margarin (harga @1000) sekitar 4-5 sdm\", \"Secukupnya garam, gula, lada bubuk, air, (kaldu bubuk jika suka)\"]', '[\"Potong dadu tempe, (boleh direndam dulu dg air+garam+kaldu bubuk beberapa saat agar lebih mantap rasanya) goreng hingga matang tapi jgn terlalu kering (saya tadi goreng dg sedikit minyak, lbh mirip disangrai, hehe), sisihkan\", \"Tumis bawang bombay dan bawang putih, masukkan kecap manis dan saus tiram, margarin, tambah air, gula, garam, lada dan kaldu bubuk(sedikit)\", \"Masukkan tempe, saya tadi airnya sampai merendam tempe (tapi nggak terlalu banyak juga, tujuannya agar bumbu bisa lebih meresep ke dalam tempe, soalnya tadi tempenya tidak direndam bumbu terlebih dahulu, tidak seperti marinasi ayam)\", \"Koreksi rasa ketika sudah mendidih airnya, jika masih ada yg kurang boleh ditambah lagi, dan masak sambil terus menerus diaduk hingga air menyusut, sajikan^^\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1042, 4, 'Tempe cabe garam', 'Tempe cabe garam - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 papan tempe\", \"1 bungkus tepung bumbu\", \"6 siung bawang putih\", \"3 siung bawang merah (optional)\", \"10 buah cabe rawit\", \"secukupnya Garam\", \"Minyak untuk menumis dan menggoreng\", \"secukupnya Daun bawang\"]', '[\"Potong dadu tempe, rendam dengan bawang putih, garam dan merica yang dihaluskan. Biarkan sampai meresap\", \"Cincang bawang putih, bawang merah, dan cabe. Iris tipis daun bawang.\", \"Goreng tempe dengan tepung bumbu sampai golden brown.\", \"Tumis bawang merah sampai harum, tambahkan bawang putih dan cabe. Aduk sampai harum.\", \"Tambahkan sejumput garam, masukkan daun bawang.\", \"Setelah merata, tambahkan tempe yang sudah digoreng.\", \"Aduk sebentar, siap disajikan\", \"Happy cooking 💖💖💖\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1043, 3, 'Tempe penyet kemangi icha', 'Buat Tempe penyet kemangi icha yang nikmat dengan langkah-langkah mudah ini.', '[\"1 papan tempe\", \"10 cabai merah keriting\", \"1 buah tomat sedang\", \"5 cabe rawit merah\", \"5 bawang merah\", \"2 bawang putih (ini bisa 3 ya soalnya stok tinggal 2)\", \"1 bungkus royko ayam\", \"1/2 sendok teh garam\", \"1 bungkus terasi abc\", \"Secukupnya minyak\", \"Secukupnya daun kemangi aku beli 1000\"]', '[\"Potong2 tempe (jangan terlalu tebal dan jangan terlalu tipis) sedang sedang bae\", \"Kupas bawang putih bawang merah cuci bersih bersama cabe\", \"Siapkan air 350 ml atau sekitar 1 1/2 gelas belimbing dan royko ayam untuk merendam tempe biasa aku pakai bawang putih garam dan ketumbar karena stok lagi habis jadi pakai royko ayam\", \"Siapkan minyak panas aku tadi pakai 1/4 kg untuk menggoreng tempe. Setelah panas goreng hingga kecoklatan agak garing ya lebih garing lebih enak tapi jangan ditinggal videocall apalagi fb an takutnya gosong\", \"Angkat tempe, kemudia minyak panas gunakan untuk menggoreng bumbu tempe penyet (cabai bawang tomat) tunggu hingga layu\", \"Setelah bumbu diangkat kemudia goreng terasi, untuk menggoreng terasi minyak jangan terlalu banyak karena terasi bisa ancur gunakan 3 sdm untuk menggoreng terasi goreng sebentar dan angkat\", \"Uleg bumbu hingga halus jangan lupa terasinya setelah halus tambahkan garam dan masukan tempe sambil di ulek kasar (sesuai selera) kemudian masukan kemangi aduk rata dan taro dipiring\", \"Tempe penyet siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1044, 4, 'Tempe bacem', 'Nikmati kelezatan Tempe bacem dengan resep sederhana ini.', '[\"2 balok tempe\", \"4 siung bawang merah\", \"3 siung bawang putih\", \"2 ruas jahe\", \"1 ruas lengkuas\", \"2 butir kemiri\", \"1/2 ruas kunyit\", \"1 sendok garam\", \"2 sendok kecap manis\", \"2 sendok gula merah\", \"1 sereh geprek\", \"2 daun jeruk\", \"1/2 gelas air\", \"secukupnya Minyak goreng\"]', '[\"Potong2 tempe sesuai selera kamu, goreng sebentar jgn mpe coklat\", \"Haluskan bumbu kecuali : daun jeruk, sereh geprek\", \"Tumis bumbu yg dihaluskan kemudian masukan tempe setelah itu masukan gula merah dan kecap manis aduk hingga merata masukan garam sedikit\", \"Koreksi rasa, masukan air sedikit demis sedikit\", \"Tumis hingga mengering dan bumbu mulai mengering\", \"Sajikan enjoyyy\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1045, 2, 'Tempe garit dan sambel', 'Buat Tempe garit dan sambel yang nikmat dengan langkah-langkah mudah ini.', '[\"Tempe garit:\", \"1 papan tempe\", \"1 siung bawang putih\", \"Secukupnya garam\", \"Bahan sambel:\", \"1 siung bawang putih\", \"5 siung bawang merah\", \"11 buah cabe rawit\", \"2 lembar daun jeruk\", \"Secukupnya garam\"]', '[\"Potong tempe dan garit2.. marinasi dengan bawang putih, garam dan air\", \"Goreng tempe sampai coklat keemasan, kl aku suka yang ga begitu kering\", \"Setelah tempe digoreng semua, goreng bahan untuk sambel sampai matang dan tiriskan\", \"Ulek semua bahan sambel, termasuk daun jeruk, lalu beri garam.\", \"Tempe garit dan sambel siap disantap..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1046, 3, 'Opor Ayam Tempe', 'Resep Opor Ayam Tempe ala rumahan yang dijamin menggugah selera.', '[\"1/2 ekor ayam\", \"1/2 papan Tempe\", \"3 lembar daun jeruk\", \"2 lembar daun salam\", \"Bumbu ulek :\", \"5 siung bawang merah yg besar\", \"3 siung bawang putih\", \"2 butir kemiri\", \"1 ibu jari jahe\", \"1/2 ibu jari kunyit\", \"1/2 sdt ketumbar\", \"1/2 sdt lada\", \"Kencur (pake sedikit banget)\", \"Bahan geprek :\", \"1 tangkai sereh\", \"1 ibu jari lengkuas\", \"secukupnya Garam\", \"secukupnya Royco ayam\", \"Bawang goreng utk taburan\"]', '[\"Cuci bersih ayam\", \"Geprek dan ulek bumbu diatas kecuali daun2an\", \"Panaskan minyak secukupnya\", \"Tumis semua bumbu termasuk daun2an sampai matang\", \"Setelah matang masukan ayam aduk2 sebentar sampai bumbu tercampur dgn ayam\", \"Tambahkan air kurleb 1 setengah liter\", \"Masukan garam & royco secukupnya. Koreksi rasa\", \"Masukan tempe yg sudah d potong 8 bagian\", \"Tunggu sampai ayam empuk, bumbu meresap, dan air agak menyusut (kekentalan kuahnya tegantung selera masing2 ya, klo saya gak terlalu kental & suka banyak kuahnya)😃\", \"Setelah matang masukan santan.. Aduk2 sebentar.. Matikan api..\", \"Siap dihidangkan dengan taburan bawang goreng lebih sedap😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1047, 2, 'Bakwan tempe ala mama baby..', 'Resep Bakwan tempe ala mama baby.. yang lezat dan mudah dibuat di rumah.', '[\"1/2 papan tempe\", \"secukupnya Tepung terigu\", \"2 siung bawang merah\", \"1 siung bawang putih\", \"lada bubuk\", \"Daun bawang\", \"Irisan cabe rawit merah\", \"Royco\", \"Penyedap\", \"Air\", \"Minyak\"]', '[\"Tumbuk tempe sampai agak halus masukan ke mangkok\", \"Haluskan bawang merah bawang putih\", \"Setelah halus campurkan bumbu halus kedalam tempe yang sudah d tumbuk\", \"Masukkan terigu, penyedap, royco,secukupnya lada bubuk, irisan daun bawang, irisan cabai rawit beri air secukupnya jangan terlalu encer kemudian koreksi rasa\", \"Panaskan minyak, kemudian goreng hingga kecoklatan\", \"Bakwan tempe siap di hidangkan..\", \"Selamat mencoba momy...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1048, 2, 'Tumis pucuk pepaya vs tempe', 'Resep Tumis pucuk pepaya vs tempe yang lezat dan mudah dibuat di rumah.', '[\"Pucuk pepaya\", \"1/2 tempe\", \"2 bawang merah\", \"1 bawang putih\", \"Cabe rawit\", \"1/2 tomat\", \"Garam\", \"Gula\", \"Sasa\", \"1 gelas air putih\"]', '[\"Cuci dan potong-potong pucuk pepaya\", \"Tempe Iris kotak-kotak kecil\", \"Goreng tempe sampai matang lalu tiriskan\", \"Iris cabai, bawang merah, bawang putih, tomat\", \"Goreng bumbu iris tadi sampai wangi lalu masukan pucuk pepaya dan tempe\", \"Kasih air 1 gelas,lalu kasih garam,gula,sasa,biarkan sampai menyerap dan pucuk pepaya matang\", \"Siaap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1049, 3, 'Sambel Tempe ala RHpawonalit', 'Sambel Tempe ala RHpawonalit - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"2 bh tempe bungkus daun, kupas\", \"5 bh cabe rawit merah\", \"1 bh bawang putih kupas\", \"Secukupnya garam\"]', '[\"Siapkan cobek biasa yang ceper dari tanah liat ataupun batu. Taruh cabe dan bawang uleg sampai halus, tambahkan garam, uleg lagi terakhir tambahkan tempe dan ulek kembali hingga tempe hancur kasar\", \"Sambel tempe siap menemani nasi hangat...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1050, 3, 'Ikan asin 2T(terong, tempe)', 'Ikan asin 2T(terong, tempe) - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"150 gram ikan asin\", \"6 bh terong hijau kecil (iris)\", \"200 gram tempe (iris sesuai selera)\", \"150 gram cabe\", \"4 siung bawang merah\", \"secukupnya Garam\"]', '[\"Goreng tempe dan terong sampai matang,, lalu goreng ikan asing sampai matang\", \"Lalu goreng cabe yang sudah di giling pakai bawang + garam secukupnya\", \"Setelah matang cabe campurkan terong+tempe +ikan asin\", \"Koreksi rasa\", \"Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1051, 3, 'Stek tempe', 'Resep Stek tempe yang lezat dan mudah dibuat di rumah.', '[\"1 papan tempe\", \"1/2 bawang bombai\", \"1 sdm minyak wijen\", \"1 sdt saos tiram\", \"2 siung bawang putih\", \"1 buah telur\", \"1 batang daun bawang\", \"Garam dan penyedap secukupnnya\", \"Tepung panir secukupnnya\", \"1 sdm bluben\", \"Untuk saos:\", \"1/2 bawang bombai\", \"1 siung bawang putih\", \"2 sdm Tepung terigu\", \"400 ml air\", \"1 sdm saos tomat\", \"1 sdm kecap\", \"1 sdm saos tiram\", \"1 sdm gula pasir\", \"Garam dan penyedap secukupnnya\"]', '[\"Kukus tempe 15 menit haluskan sisihkan, tumis bawang bombai,bawang putih dengan bluben sampai harum masukkan sosis dan daun bawang sampai layu.masukkan tumisan bawang dan sosis ke tempe beri garam,saos tiram,minyak wijen dan penyedap aduk rata bulat dan pipihkan masukkan ke kocokan telur dan balur dengan panir.goreng.\", \"Carannya membuat saos\", \"Tumis bawang putih dan bombai masukkan tepung,air dan bumbu lain aduk sampai mendidih dan kental.\", \"Pelengkap\", \"Kentang goreng dan wortel rebus\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1052, 4, 'Oseng tempe pete', 'Resep praktis Oseng tempe pete yang bisa dicoba di rumah.', '[\"1 papan tempe\", \"1 papan pete\", \"secukupnya Cabe ijo & merah\", \"secukupnya Air\", \"Kecap manis\", \"secukupnya Minyak goreng\", \"Garam dan penyedap rasa\", \"Bumbu halus :\", \"3 siung bawang merah\", \"3 siung bawang putih\", \"1 ruas jahe\", \"secukupnya Ketimbar dan lada bubuk\"]', '[\"Potong dadu tempe kemudian goreng tempe setengah mateng\", \"Tumis bumbu halus, masukkan tempe\", \"Tambahkan sedikit air dan kecap, garam dan penyedap rasa\", \"Cek rasa kemudian masukkan pete, irisan cabe ijo dan cabe merah\", \"Masak sebentar, tiriskan, selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1053, 4, 'Tumis tempe kacang panjang sederhana', 'Resep Tumis tempe kacang panjang sederhana yang lezat dan mudah dibuat di rumah.', '[\"1 papan Tempe\", \"1 ikat sayur kacang panjang\", \"Merica\", \"Terasi\", \"Tomat\", \"Cabe rawit\", \"Minyak,masako ayam\"]', '[\"Potong tempe dan kacang panjang sesuai selera\", \"Goreng tempe.\", \"Haluskan bumbu.lalu tumis\", \"Setelah harum masukkan kacang panjang.yumis sebentar lalu masukkan tempe.\", \"Beri masako dan koreksi rasanya.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1054, 4, 'Tempe Mendoan', 'Cara membuat Tempe Mendoan yang enak dan praktis untuk keluarga.', '[\"1 papan tempe\", \"1 batang panjang daun bawang iris2\", \"Secukupnya daun seledri iris2\", \"5 sdm tepung terigu\", \"Secukupnya kaldu bubuk rasa ayam\", \"200 ml air\", \"Bumbu Halus :\", \"2 siung bawang putih\", \"3 siung bawang merah\", \"1 sdt ketumbar\", \"Secukupnya garam\"]', '[\"Iris tempe, beri sayatan di kedua sisi agar bumbu meresap. Lumuri tempe ke bumbu yang telah dihaluskan lalu sisihkan.\", \"Campurkan tepung terigu, daun seledri, daun bawang, bumbu halus tuang air sambil diaduk rata, beri garam dan kaldu secukupnya, koreksi rasa.\", \"Panaskan minyak, celuokan tempe ke adonan tepung hingga merata kemudian goreng hingga matang. Tiriskan\", \"Hidangkan bersama saus sambal atau cabai rawit sesuai selera 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1055, 3, 'Tahu + Tempe + Teri Pedas Manis', 'Sajian tempe lezat: Tahu + Tempe + Teri Pedas Manis penuh protein nabati.', '[\"5 buah tahu\", \"1 bungkus tempe ukuran sedang\", \"1/4 Teri Medan\", \"15 buah cabe hijau\", \"10 buah cabe rawit\", \"3 buah daun bawang\", \"1/2 siung bawang bombay\", \"2 sdm kecap manis\"]', '[\"Potong dadu tempe dan tahu. Kemudian goreng, jangan terlalu kering.\", \"Cuci teri kemudian goreng juga\", \"Tumis bawang, cabai dan daun bawang sampai harum. Tambahkan gula, garam dan penyedap secukupnya, test rasa.\", \"Tambahkan sedikit air dan kecap manis, masukkan tahu, tempe dan teri.\", \"Hidangkan..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1056, 4, 'PLecing Kacang panjang + tempe pedas manis', 'Buat PLecing Kacang panjang + tempe pedas manis yang nikmat dengan langkah-langkah mudah ini.', '[\"Bahan utama\", \"1 ikat kacang panjang isi 5\", \"1/2 tempe\", \"irisan Bahan\", \"1 buah Cabai merah\", \"1 buah bawang putih\", \"9 buah Rawit (sesuai selera)\", \"Bahan uLekan\", \"4 buah bawang putih\", \"5 buah bawang merah\", \"Bumbu-bumbu\", \"Secukupnya masako\", \"Secukupnya kecap manis\", \"4 sdt minyak ikan\", \"Minyak untuk menumis\"]', '[\"Potong2 bahan utama kacang panjang berikut tempe (sesuai kata hati)\", \"Goreng terlebih dahulu tempe hingga ke kuning2an,, tiriskan\", \"Goreng bahan uLekan sampai wangi, lanjut masukan bahan irisan..\", \"Masukan tempe yg sudah di goreng, kacang panjang lalu aduk rata..\", \"Masukan minyak ikan, di aduk2 campur Masako.. #koreksi rasa\", \"Lanjut masukan kecap, oseng2 sampai kecap merata #koreksi rasa\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1057, 4, 'Embes-Embes Tempe Banyumasan', 'Embes-Embes Tempe Banyumasan - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 papan tempe (potong-potong -+ 1 cm)\", \"1 batang serai, geprek\", \"2 cm lengkuas geprek\", \"2 lembar daun salam\", \"2 sdm kecap manis\", \"1/4 sdt kaldu bubuk\", \"500 ml air\", \"Secukupnya garam halus\", \"Secukupnya minyak goreng\", \"Taburan:\", \"Secukupnya bawang merah goreng\", \"Bumbu halus:\", \"5 buah bawang merah\", \"4 siung bawang putih\", \"3 butir kemiri (sangrai terlebih dahulu)\", \"1/4 sdt ketumbar (sangrai terlebih dahulu)\", \"2 cm kunyit (bakar terlebih dahulu)\", \"1 cm jahe (bakar terlebih dahulu) (tambahan ku)\", \"1/4 sdt merica bulat\"]', '[\"Tumis bumbu halus, daun salam, serai dan lengkuas geprek dengan secukupnya minyak goreng sampai harum..\", \"Tambahkan air dan masuk kan tempe, garam, kaldu, gula pasir dan kecap manis, aduk rata. Tutup dan masak sampai mendidih, jangan lupa tes rasa, masak sampai kuah menyusut.. Angkat dan sajikan dengan taburan bawang merah goreng..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1058, 2, 'Orek tempe cabe hijau', 'Nikmati kelezatan Orek tempe cabe hijau dengan resep sederhana ini.', '[\"1 papan tempe daun\", \"9 siung bawang merah (iris)\", \"5 siung bawang putih (iris)\", \"10 cabai hijau keriting\", \"4 sdm kecap bango\", \"secukupnya Minyak\", \"1/2 bks Royco ayam\"]', '[\"Potong\\\" tempe agak memanjang.\", \"Panaskan minyak, goreng tempe hingga mengering. Jika sudah angkat tiriska.\", \"Panaskan sedikit minyam di penggorengan, tumis bawang putih dan merah hingga harum. Tambahkan cabai hijau. Aduk rata\", \"Masukkan tampe yg sudah digoreng, tambahahkan royco aduk rata dan terakhir tambahkan kecap Bango.aduk hingga semua tercampur rata. Jika sudah matikan api.\", \"Orek tempe siap untuk dihidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1059, 4, 'Tumis kacang panjang tempe santan', 'Tumis kacang panjang tempe santan - olahan tempe khas Indonesia yang nikmat.', '[\"1 ikat kacang panjan, potong potong\", \"1 papan tempe ukuran kecil, iris memanjang\", \"bumbu\", \"5 butir bawang merah\", \"3 butir bawang putih\", \"5 buah cabe rawit merah\", \"5 buah cabe merah\", \"3 lembar Daun salam\", \"Lengkuas digeprek\", \"secukupnya Garam\", \"secukupnya Gula  (gula jawa lebih sedap)\", \"Secukupnya kecap asin\", \"Secukupnya kecap ikan\", \"(klo ga ada kecap asin dan kecap ikan ga pake jg tetap enak)\", \"Santan sun kara kecil\"]', '[\"Iris bawang merah, bawang putih, cabe, tumis dengan sedikit minyak, masukkan daun salam dan lengkuas\", \"Klo sudah harum tambah secangkir air, tunggu mendidih masukkan tempe dan kacang panjang\", \"Masukkan garam, gula, kecap asin, kecap ikan, tunggu sampe air tinggal sedikit\", \"Masukkan santan, koreksi rasa, angkat...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1060, 2, 'Pakis, Daging, Tempe, santan', 'Resep praktis Pakis, Daging, Tempe, santan yang bisa dicoba di rumah.', '[\"1/3 kg daging sapi potong dadu\", \"Tempe (potong dadu, goreng setengah matang)\", \"1 ikat pakis\", \"2 bawang putih\", \"4 bawang merah\", \"1/4 bawang bombay\", \"3 cabai rawit\", \"2 cabai merah\", \"2 ruas lengkuas\", \"Serai, daun salam\", \"Kunyit bubuk\", \"1 sct santan instant klatuk\"]', '[\"Rebus daging hingga matang.\", \"Tumis bumbu yang sudah diiris tipis2 hingga harum, masukkan kaldu daging dan daging yg sudah direbus.\", \"Tambahkan gula, garam, kunyit bubuk. Masukkan santan.\", \"Tunggu agak mendidih, masukkan pakis dan tempe yg telah digoreng setengah matang.\", \"Masak hingga matang. Sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1061, 2, 'Tempe Jeletot', 'Nikmati kelezatan Tempe Jeletot dengan resep sederhana ini.', '[\"1 papan tempe (potong sedang)\", \"Secukupnya Minyak goreng\", \"🌶 bahan sambal :\", \"3 bawang merah\", \"2 bawang putih\", \"5 cabe rawit\", \"3 cabe merah uk besar\", \"1/2 sachet terasi abc\", \"Secukupnya gula pasir & garam\", \"🌶 bahan pencelup :\", \"2 sdm tepung bumbu\", \"1 sdm tepung beras\", \"Secukupnya air\"]', '[\"Goreng sbentar semua bahan sambal hingga layu. Haluskan bersama gula pasir & garam.\", \"Potong tempe mjd 2 bagian (jangan sampai terputus), isi dg sambal.\", \"Celup ke dlm adonan tepung, balut tempe dg adonan.\", \"Goreng hingga kecoklatan, kemudian angkat.\", \"Sajikan selagi hangat 😊 Hmmm,... Yummy\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1062, 4, 'Oseng tempe lombok ijo', 'Resep Oseng tempe lombok ijo yang lezat dan mudah dibuat di rumah.', '[\"2 papan tempe, potong kotak.goreng setengah matang\", \"250 gram buncis, potong-potong\", \"Sedikit minyak untuk menumis\", \"Sedikit air\", \"Secukupnya gula merah, sisir\", \"Bumbu:\", \"6 butir bawang merah, iris tipis\", \"6 siung bawang putih, iris tipis\", \"6 buah cabai hijau besar, potong-potong\", \"3 cm lengkuas, geprek\", \"1 lembar daun salam\", \"secukupnya garam\", \"Secukupnya penyedap rasa\"]', '[\"Panaskan minyak, tumis bumbu hingga harum dan layu\", \"Masukkan buncis, biarkan layu\", \"Masukkan tempe, tambahkan gula merah dan sedikit air\", \"Koreksi rasa, angkat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1063, 4, 'Orek tempe telor', 'Buat Orek tempe telor yang nikmat dengan langkah-langkah mudah ini.', '[\"1/2 papan tempe\", \"1 telor,\", \"5 siung bawang merah, iris\", \"3 siung bawang putih, iris\", \"3 buah cabai rawit, iris\", \"1 cabe merah,iris\", \"2 sdm kecap\", \"2 lembar daun salam\", \"1 ruas lengkuas geprek\", \"Garam\", \"Gula\", \"Merica\"]', '[\"Kocok telur, tambahkan daun bawang beri sedikit garam, masak dadar, sisihkan, potong potong\", \"Potong tempe dadu, goreng setengah matang sisihkan\", \"Panaskan minyak, tumis bwm, bwp, cabai, tambahkan daun salam dan lengkuas, tunggu hingga layun dan wangi\", \"Masukkan kecap, garam, gula, merica\", \"Masukkan tempe goreng dan telur dadar, aduk sebentar, koreksi rasa\", \"Koreksi rasa\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1064, 2, 'Sayur tempe, terong & hati ayam', 'Cara membuat Sayur tempe, terong & hati ayam yang enak dan praktis untuk keluarga.', '[\"5 hati ayam (rebus)\", \"1 papan tempe (potong2)\", \"1 bh terong (potong2)\", \"3 siung bawang putih\", \"4 siung bawang merah\", \"Sedikit ketumbar butir\", \"2 bj kemiri sangrai\", \"Sedikit terasi bakar\", \"Secukupnya cabe rawit\", \"2 bh cabe merah\", \"Seruas lengkuas (geprek)\", \"2 lbr daun salam\", \"2 lbr daun jeruk\", \"Secukupnya gula merah (atau 2sdm gula merah yg sudah dicairkan)\", \"1/2 sdm gula pasir\", \"Secukupnya garam & kaldu bubuk\", \"1 sdm kecap inggris\", \"500 ml santan sedang\", \"Secukupnya air\"]', '[\"Haluskan duo bawang, kemiri, ketumbar, cabe rawit, cabe merah, terasi.\", \"Tumis bumbu halus. Masukkan daun salam & jeruk. Tambahkan juga lengkuas.\", \"Masukkan air secukupnya. Beri gula merah, gula, garam, kaldu bubuk & kecap Inggris. Setelah mendidih, masukkan santan.\", \"Koreksi rasa.\", \"Masukkan hati ayam, tempe, terong ke dalam kuah yg sudah mendidih.\", \"Masak dg api kecil. Sambil diaduk sesekali. Masak agak lama biar bumbu meresap sempurna\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1065, 3, 'Tempe Bacem endeussss', 'Resep Tempe Bacem endeussss yang lezat dan mudah dibuat di rumah.', '[\"1 papan tempe ukuran besar,potong2\", \"4 lembar daun salam\", \"1 batang serai,geprek\", \"800 ml air\", \"4 bongkah kecil gula merah\", \"1 sdt asam jawa,larutkan dlm 100ml air panas\", \"secukupnya garam,gula pasir,lada bubuk\", \"kaldu jamur secukupnya (sy skip)\", \"Bumbu Halus :\", \"8 siung bawang merah\", \"4 siung bawang putih\", \"2 ruas lengkuas\"]', '[\"Siapkan semua bahan\", \"Tumis bumbu halus sampe harum lalu tambahkan daun salam dan serai aduk sampe bumbu matang.\", \"Kemudian masukan air,air asam jawa,gula merah yg di iris,aduk2 lalu beri garam,gula pasir,lada bubuk dan kaldu jamur,masak hingga air mendidih.\", \"Masukan tempe,masak hingga air menyusut,lalu tutup dan diamkan kurleb 30 menit biar bumbu meresap sempurna.\", \"Goreng tempe dg minyak yg sudah di panaskan sampe kuning kecoklatan,gorengnya bentar aja ya moms,angkat lalu tiriskan..\", \"Super endeeuuussss....\", \"Happy Cooking...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1066, 4, 'Balado Teri Kacang Tempe', 'Sajian Balado Teri Kacang Tempe yang praktis dan lezat untuk dinikmati bersama.', '[\"1 buah Tempe potong2 dan goreng kering\", \"1/4 kg kacang tanah, rendam dengan air 1 jam lalu goreng\", \"Teri secukupnya atau sesuai selera (saya 2 bungkus)\", \"2 cm lengkuas digeprek\", \"1 cm jahe digeprek\", \"1 lbr daun salam\", \"2 lbr daub jeruk\", \"secukupnya Kecap\", \"4 sdm gula pasir\", \"1 sdm gula merah\", \"secukupnya Masako\", \"Bumbu Halus :\", \"3 siung bawang putih\", \"5 siung bawang merah\", \"8 buah cabe merah\", \"7 buah cabai kecil\", \"1 bungkus terasi ABC\"]', '[\"Tumis bumbu halus hingga harum, lalu tambahkan daun jeruk, daun salam, lengkuas dan jahe masak hingga harum.\", \"Setelah harum tambah air sedikit lalu masukan masako, kecap, gula merah dan gula pasir masak hingga menjadi kental atau karamel.\", \"Matikan kompor lalu masukan teri, tempe dan kacang yang telah di goreng terlebih dahulu. Aduk hingga bumbu rata.\", \"Selamat mencoba 😘\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1067, 2, 'Mendhol Tempe', 'Buat Mendhol Tempe yang nikmat dengan langkah-langkah mudah ini.', '[\"1 papan tempe (setengah busuk, potong dan kukus)\", \"Seruas kencur\", \"3 siung bawang merah\", \"2 siung bawang putih\", \"5 bh cabe rawit\", \"2 bh cabe merah (rajang kasar)\", \"Secukupnya gula garam kaldu bubuk\", \"4 lbr daun jeruk (rajang halus)\", \"2 sdm tepung terigu\"]', '[\"Haluskan tempe busuk.\", \"Haluskan duo bawang, cabe merah, cabe rawit, setengah rajangan daun jeruk, kencur, gula, garam, kaldu bubuk.\", \"Campur tempe, bumbu halus, setengah rajangan daun jeruk dan tepung terigu.\", \"Jika dirasa terlalu kering, bs ditambah sedikit air agar bs dibentuk\", \"Ambil adonan. Bentuk sesuai selera. Kemudian goreng.\", \"Siap sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1068, 3, 'Tahu tempe bacem ala anak kost', 'Sajian tempe lezat: Tahu tempe bacem ala anak kost penuh protein nabati.', '[\"1 papan tempe\", \"1 bungkus tahu (isi 5)\", \"5 siung bawang merah\", \"4 siung bawang putih\", \"3 butir kemiri\", \"1 lengkuas (geprek)\", \"secukupnya Asam jawa\", \"secukupnya Garam, penyedap rasa\", \"kecap\", \"gula merah\"]', '[\"Halus kan semua bahan bahan dan tumis sampe matang\", \"Sesudah bumbu sudah matang campurkan tahu dan tempe kasih air aduk rata\", \"Diam kan sampe airnya mengering,tiriskan\", \"Dan jadi deh tahu tempe bacem ala anak kost yang nikmaaaaaaat.... Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1069, 3, 'Tumis Baby Buncis Kornet Tempe', 'Nikmati kelezatan Tumis Baby Buncis Kornet Tempe dengan resep sederhana ini.', '[\"1 bungkus baby buncis (+-250gr)\", \"2 sdm kornet\", \"1 bungkus tempe bungkus daun (bisa tempe biasa), potong dadu\", \"1/4 siung bawang bombay besar\", \"3 siung bawang putih\", \"3 buah cabe rawit\", \"1 sdm kecap manis\", \"1/2 sdm kecap asin\", \"1/2 sdm saus sambal\", \"1 sdt lada bubuk / secukupnya\", \"1/2 sdm gula pasir / secukupnya\", \"secukupnya Garam\", \"secukupnya Air\", \"secukupnya Minyak goreng+margarine\"]', '[\"Panaskan minyak goreng+margarine. Tumis bawang bombay, bawang putih, lalu baru cabe rawit. Aduk hingga harum.\", \"Masukkan kornet & tempe. Aduk sampai setengah matang dan setengah kering.\", \"Tambahkan kecap asin, manis, saus tomat. Lalu beri air secukupnya.\", \"Setelah air mendidih, masukkan buncis, beri lada bubuk, garam, gula, lalu tutup wajan supaya buncis matang merata.\", \"Tusuk dengan garpu, tes kematangan buncis. Kalo saya suka buncis yg masih renyah (tidak terlalu matang & lembek). Cicipi rasanya juga, tambahkan garam & gula jika kurang.\", \"Sajikan selagi hangat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1070, 2, 'Tempe Goreng Tepung Ekonomis', 'Resep praktis Tempe Goreng Tepung Ekonomis yang bisa dicoba di rumah.', '[\"Tempe papan atau tempe daun pisang\", \"Bawang Putih\", \"Penyedap rasa\", \"Garam secukupnya\", \"secukupnya Air\", \"Minyak untuk menggoreng\"]', '[\"Potong tempe jadi beberapa bagian. Jangan terlalu tebal tapi juga jangan terlalu tipis\", \"Rendam tempe ke larutan garam. Kurleb 30 menit. Sementara itu kita buat adonan tepung.\", \"Campurkan tepung terigu dan tepung beras. Campur dengan air hingga adonan agak encer. Geprek bawang putih, potong kasar, masukkan. Bumbui dengan penyedap rasa lalu tes rasa adonan.\", \"Panaskan wajan terlebih dahulu. Baru tuangkan minyak. Ini untuk menghindari adonan lengket di wajan.\", \"Setelah minyak panas, masukkan tempe yang sudah diceupkan ke adonan tepung. Goreng dengan api sedang. Lanjutkan hingga tempe habis.\", \"Taraaa... begini penampakan yang sudah jadi. Bisa untuk lauk makan pakai nasi hangat. Ataupun kudapan di sore hari.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1071, 2, 'Sambal Tempe Kencur', 'Resep Sambal Tempe Kencur ala rumahan yang dijamin menggugah selera.', '[\"1 papan Tempe uk 15x15 cm atau sesukanya, potong kotak\", \"4 buah Cabe gendot, diiris\", \"1 cm Lengkuas, digeprek\", \"1 buah Cabe merah besar, diiris\", \"1 batang Serai digeprek\", \"Perasa Jamur\", \"Gula pasir\", \"1 genggam Daun kemangi\", \"Bumbu halus:\", \"5 buah Cabe rawit merah\", \"4-5 cm Kencur\", \"4 siung Bawang putih\", \"1 sendok teh Garam\"]', '[\"Goreng tempe setengah matang.\", \"Haluskan bumbu-bumbu\", \"Tumbuk tempe sampai cukup hancur tp masih kasar\", \"Tumis bumbu halus sampe setengah matang lalu masukan cabe gendot, serai, lengkuas dan cabe merah. Tumis sampai matang dan harum\", \"Masukan Tempe lalu aduk sampe tempe matang, lalu tambahkan kemangi. Beri 1 sendok makan gula pasir dan secukupnya perisa jamur. Cicipi\", \"Sambal tempe siap disantap..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1072, 3, 'Tempe Mendol', 'Sajian tempe lezat: Tempe Mendol penuh protein nabati.', '[\"1 papan tempe semangit *yg sdh didiamkan 2 atau 3 hari\", \"Bumbu halus:\", \"4 buah bawang merah\", \"3 buah bawang putih\", \"5 buah cabe rawit merah *boleh tidak pakai\", \"10 lembar daun jeruk\", \"2 ruas kencur\", \"1 sdt ketumbar\", \"Secukupnya garam\", \"Minyak sayur utk menggoreng\"]', '[\"Siapkan tempe, potong2. lalu kukus selama 15 menit\", \"Setelah dikukus, haluskan tempe (saya pakai ulekan). setelah tempe sdh halus masukan bumbu halus aduk rata. Buat bulatan2 setelah itu goreng tempe mendol\", \"Selamat Mencoba..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1073, 2, 'Oreg tempe', 'Sajian Oreg tempe yang praktis dan lezat untuk dinikmati bersama.', '[\"500 gr tempe\", \"5 buah cabe ije (iris bulet or sesuai selera)\", \"7 buah cengek (iris tipis)\", \"4 siung bawang putih (iris halus)\", \"4 siung bawang merah (iris tipis)\", \"40 ml kecap manis (aku pake bango)\", \"1 sdt maizena (campur dengan 5 sdm air)\", \"1 sdt garam\", \"1 sdt penyedap rasa\", \"1/4 gr minyak goreng\", \"1 lembar daun salam\", \"3 cm laos di geprek\", \"2 tangkai daun bawang\"]', '[\"Iris dadu tempe,lalu goreng set mateng,iris,potong semua bumbu\", \"Tumis bawang merah,putih dan bawang daun sesudah wangi masukkan salam dan laos dan cabe,cengek,\", \"Lalu masukan tempe yang sudah di goreng aduk sampe rata dengan api kecil az,lalu masukkan maizena dan kecap,garam dan penyedap rasa aduk sampe bumbu meresap cek rasa lalu matikan api dan hidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1074, 4, 'Temro tempe dijero /didalam 😁', 'Resep praktis Temro tempe dijero /didalam 😁 yang bisa dicoba di rumah.', '[\"4 batang singkong\", \"Royco\", \"Gula pasir\", \"4 siung Bawang putih\", \"siung bawang merah\", \"20 Cabe jablay\", \"2 ikat kemangi\", \"1 papan tempe\", \"secukupnya Minyak goreng\"]', '[\"Kupas singkong cuci parut taburkan royco\", \"Blender bumbu kl ditumbuk paling males sy suka kena mata wkwkkw\", \"Goreng tempe potong dadu tumbuk\", \"Tumis bumbu halus masukan kemangi royco gulA test rasa aduk dengan tempe yg sudah dihaluskan\", \"Cetak adonan isinya atau dalam nya pake tempe\", \"Goreng deh jadi deh....pedessssnga sadessssss....\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1075, 4, 'Orak arik tempe', 'Sajian tempe lezat: Orak arik tempe penuh protein nabati.', '[\"2 papan tempe\", \"1/2 ons teri tanjung\", \"1 buah bawang bombay\", \"1 ruas jahe geprek\", \"2 lembar daun jeruk\", \"3 lembar daun salam\", \"3 buah cabe merah\", \"25-30 buah cabe rawit\", \"3 sendok makan kecap\", \"sesuai selera Garam\"]', '[\"Potong tempe sesuai selera, goreng garing dilanjutkan dengan teri\", \"Tumis bawang bombay setelah matang, masukkan jahe daun jeruk dan daun salam, lanjutkan dengan cabe yang sudah diris serong\", \"Masukkan tempe dan teri kemudian tuangkan kecap. Tambahkan garam sesuai selera\", \"Tempe orak arik selesai dan siap disantap\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1076, 4, 'Embes Embes Tempe', 'Resep Embes Embes Tempe yang lezat dan mudah dibuat di rumah.', '[\"1 bngks tempe(aku pakai 2),potong sedikit tebal\", \"10 bh cabe rawit utuh(optional)\", \"2 lbr daun salam\", \"1 btg serai,memarkan\", \"1 ruas lengkuas,geprek\", \"1 sdm kecap manis\", \"Secukupnya air\", \"Secukupnya garam dan gula\", \"Bumbu halus :\", \"6 btr bawang merah\", \"4 siung bawang putih\", \"4 btr kemiri,goreng\", \"1 ruas jahe\", \"1/2 sdt kunyit bubuk/1 ruas kunyit\", \"1/2 sdt lada bubuk\", \"1/2 sdt ketumbar bubuk\"]', '[\"Tumis bumbu halus,daun salam,serai dan lengkuas hingga matang dan harum.\", \"Masukkan secukupnya air,tunggu hingga mendidih.\", \"Masukkan tempe dan cabe rawit utuh,beri kecap manis,garam dan gula,tes rasa.\", \"Masak hingga kering atau air sedikit menyusut(optional).\", \"Salin dan sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1077, 2, 'Tempe mendoan goreng', 'Resep Tempe mendoan goreng ala rumahan yang dijamin menggugah selera.', '[\"1 papan trmpe iris tipis\", \"16 sdm trigu+6 sdm tepung beras(bila ada)\", \"4 siung bawang putih+2 bawang merah\", \"3 sdm ketumbar bubuk\", \"1 ruas kencur\", \"Secukupnya gula\", \"Secukupnya garam\", \"Secukupnya r*yc* sapi\"]', '[\"Campur tepung trigu dan tepung beras\", \"Haluskan ketumbar bubuk,bawang putih,bawang merah,garam,gula,royco sapi.\", \"Campur smua bahan tadi dlm satu wadah.\", \"Lumur i tempe lalu goreng\", \"Siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1078, 4, 'Kering Tempe dan Kulit Pangsit', 'Kering Tempe dan Kulit Pangsit - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 papan tempe (potong tidak terlalu tebal dan tipis)\", \"Kulit pangsit (potong 1/4)\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"2 bh cabe merah besar\", \"1 bh cabe rawit\", \"Secukupnya lengkuas\", \"Secukupnya gula merah\", \"Secukupnya gula\", \"Secukupnya garam\", \"Sedikit air\", \"Secukupnya minyak\"]', '[\"Goreng tempe dan kulit pangsit. Angkat dan tiriskan\", \"Blender/Ulek bawang merah, bawang putih, cabe merah besar, cabe rawit, dan lengkuas. Tumis\", \"Masukkan sedikit air (agar tahan lama dan tidak melempem), gula merah, gula, garam,\", \"Cicipi dan jika sudan pas rasanya sesuai selera masukkan tempe dan kulit pangsit. Aduk rata dan angkat\", \"Hidangkan. Jika ingin dimasukkan ke dalam toples, tunggu sampai dingin agar tidak melempem.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1079, 3, 'Gulai Kacang panjang tempe', 'Resep Gulai Kacang panjang tempe ala rumahan yang dijamin menggugah selera.', '[\"1 ikat kacang panjang,potong2\", \"2-3 gelas Santan dri kelapa parut\", \"5 potong tempe,goreng dan potong dadu\", \"secukupnya Garam dan gula\", \"Kaldu jamur Non msg\", \"Bumbu halus ;\", \"5 bawang merah\", \"2 bawang putih\", \"5 cabe rawit merah\", \"1 kemiri\", \"1 cm kunyit\", \"Daun jeruk\", \"Daun salam\", \"Laos geprek\"]', '[\"Kacang panjang potong2,bilas bersih lalu tiriskan\", \"Tumis bumbu halus sampe wangi tambahkan daun salam,daun jeruk dan laos\", \"Masukkan kacang panjang,setelah setengah matang baru masukan tempe\", \"Setelah itu masukan santan, aduk² jangan sampai pecah tambahkan gula, garam, kaldu jamur..koreksi rasa\", \"Sajikan selagi hangat 😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1080, 2, 'Tumis Tempe Kikil Lada Hitam', 'Buat Tumis Tempe Kikil Lada Hitam yang nikmat dengan langkah-langkah mudah ini.', '[\"1/4 kg kikil (kulit sapi)\", \"1 papan tempe\", \"1/2 ons tauge panjang\", \"30 cabe rawit (belah-belah 2)\", \"2 cabe merah besar (iris serong)\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"1 siung bawang bombay uk sedang\", \"1 sachet saos lada hitam (me: saori)\", \"1 ruas jahe\", \"1 ruas laos\", \"3 lembar daun salam\", \"1 sdm gula pasir\", \"1 sdt garam\", \"Penyedap masakan (optional)\", \"Air mineral\", \"Minyak sayur\"]', '[\"Siapkan bumbu-bumbu.\", \"Potong kotak-kotak tempe. Goreng kering. Sisihkan.\", \"Patong kotak-kotak kikil. Rendam sebentar dalam air hangat. Sisihkan.\", \"Cuci bersih tauge. Sisihkan.\", \"Panaskan minyak sayur. Tumis bawang bombay sampai sedikit layu. Tambahkan bawang merah dan bawang putih. Tumis lagi hingga harum. Lalu masukkan irisan cabe dan bumbu lainnya. Aduk-aduk sampai semua layu.\", \"Setelah bumbu layu. Masukkan tauge, oseng-oseng hingga agak layu. Lalu masukkan kikil. Oseng-oseng lagi sebentar lalu masukkan tempe.\", \"Aduk-aduk temua bahan yang sudah dicampur tadi. Tambahkan air mineral hingga agak tergenang.\", \"Masukkan gula, garam, penyedap masakan, dan saos lada hitam. Aduk-aduk. Kontrol rasa.\", \"Tunggu hingga mendidih dan air sat sambil terus diaduk-aduk. Kontrol lagi rasanya.\", \"Kalau air sudah sat dan rasa sudah pas, angkat. Sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1081, 3, 'Tempe goreng super crispy & lembut', 'Sajian tempe lezat: Tempe goreng super crispy & lembut penuh protein nabati.', '[\"2 papan tempe\", \"8 sendok tepung terigu\", \"2 sendok tepung beras(rosebrand)\", \"Sejumput Baking soda\", \"1,1/5 gelas  Air kulkas\", \"Bumbu halus\", \"secukupnya Garam merica ketumbar bawang putih\"]', '[\"Iris tipis tempe\", \"Uleg bumbu sampai halus\", \"Masukan bumbu kewadah, tambahkan air kulkas\", \"Lalu soda, selanjutnya terigu & tepung beras\", \"Aduk adonan sampai rata, agak cair memang supaya crespy\", \"Goreng ke minyak panas, setelah kecoklatan angkat & tiriskan👌\", \"Fyi : satu sendoknya agak munjung yaa\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(1082, 2, 'Sayur Tempe Lombok Ijo', 'Sayur Tempe Lombok Ijo - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"2 papan tempe kukus lalu potong kotak\", \"10 butir telor puyuh rebus\", \"Daging sapi sedikit (utk kaldu)\", \"Seikat kecil kacang panjang potong2\", \"15 buah Lombok ijo iris serong\", \"10 siung bawang merah iris\", \"Santan (kara yg kecil)\", \"7 siung bawang putih geprak cincang\", \"2 sdt ketumbar sangrai lalu dihaluskan\", \"5 butir kemiri goreng lalu uleg\", \"2 batang serai\", \"5 lembar daun salam\", \"sedikit Gula Jawa\", \"Sedikit garam\", \"Minyak goreng utk menumis\"]', '[\"Siapkan wajan beri minyak dan tunggu hingga panas, masukkan lengkuas dan serai biarkan sesaat lalu masukkan bawang putih sampai harum lalu bawang merah setelah harum masukkan daging, kemiri dan ketumbar. Ungkep sekitar 5 menit.\", \"Masukkan air mendidih secukupnya lalu beri daun salam. Biar kan sekitar 10 menit.\", \"Beri gula merah dan sedikit garam serta santan sambil sesekali aduk pakai api sedang ya, masukkan tempe nya. Biarkan lagi 5-10 menit biar bumbu meresap.\", \"Lalu masukkan kacang panjang masak hingga matang. Sekitar 5-7 menit. Setelah itu telur, Lombok/cabe ijo nya, catatan bila suka pedas monggo ditambah cabe rawit. Biarkan sesaat dan koreksi rasa.\", \"Dan sayur tempe Lombok ijo siap dihidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1083, 3, 'Keripik Tempe Kobe', 'Resep praktis Keripik Tempe Kobe yang bisa dicoba di rumah.', '[\"1 papan tempe panjang\", \"1 sdm ketumbar bubuk\", \"1/2 sdt garam\", \"1/2 sdt penyedap rasa\", \"3 siung bawang putih\", \"secukupnya Air\", \"1 bks tepung bumbu kobe\", \"secukupnya Minyak goreng\"]', '[\"Potong tempe menjadi 3 bagian (sesuai selera), lalu iris tipis. Sisihkan.\", \"Haluskan bawang putih & garam. Masukan bumbu halus ke dalam air, ditambah ketumbar bubuk & penyedap rasa (koreksi rasa). Aduk rata.\", \"Rendam tempe ke air yang telah diberi bumbu sampai tempe terendam sempurna,lalu masukan ke dalam kulkas. Diamkan minimal 2 jam hingga bumbu meresap.\", \"Siapkan minyak goreng panas. Balur tempe dengan tepung bumbu kobe, lalu goreng dengan api kecil hingga matang kecoklatan. Dinginkan & simpan dalam toples yang rapat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1084, 2, 'Kering Tempe pedas manis', 'Kering Tempe pedas manis - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"2 papan Tempe 2rb an per papan\", \"3 buah gula Merah\", \"6 cabe rawit\", \"3 bawang Merah\", \"2 bawang putih\", \"1 sachet masako\", \"Secukupnya garam\"]', '[\"Potong memanjang Tempe agak tipis lalu goreng setengah matang,lalu sisihkan.\", \"Potong duo bawang,Dan cabai potong serong,lalu tumis terlebih dahulu Bawang putih, bawang Merah terakhir cabai NYA sampai harum,\", \"Setelah harum masukan air secukupnya,lalu masukan 3 Blok gula Merah Besar,gula NYA banyak Karena suami suka yg manis, setelah meletup masukan masako Dan sedikit garam,\", \"Aduk terus sampai air menyusut,setelah menyusut masukan Tempe,aduk terus jangan sampai gosong,koreksi Rasa,setelah airnya habis kering Tempe siap disajikan m\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1085, 2, 'Steak Tempe Sederhana', 'Resep Steak Tempe Sederhana ala rumahan yang dijamin menggugah selera.', '[\"Bahan Steak Tempe :\", \"1 papan tempe (di saya harga 2rb)\", \"1 siung bawang putih\", \"2 siung bawang merah\", \"1/2 sdt merica bubuk\", \"1/2 sdt ketumbar bubuk\", \"1/4 sdt garam (sesuai selera)\", \"1/4 sdt gula (sesuai selera)\", \"2 sdm tepung bumbu (saya pakai tepung bumbu serbaguna Sajiku)\", \"1 butir telur\", \"2 sdm mentega (untuk menggoreng, bisa diganti minyak goreng)\", \"Bahan Saus :\", \"3 sdm saus sambal (saya pakai indofood extra pedas)\", \"1 sdm saus lada hitam (saya pakai saori)\", \"1/2 siung bawang bombay ukuran sedang, iris tipis\", \"1 siung bawang putih, iris tipis\", \"1 siung bawang merah, iris tipis\", \"1/2 sdt tepung maizena (bisa diskip)\", \"1 sdm mentega\", \"100 ml air\", \"Bahan Pelengkap :\", \"Sayur :\", \"1 buah wortel\", \"1/4 buah kembang kol\", \"Mashed potato :\", \"1 buah kentang ukuran besar\", \"1 sdm mentega\", \"3 sdm susu cair plain uht (bisa diskip)\", \"merica (secukupnya)\", \"1 batang daun bawang merah, iris kecil-kecil (bisa diskip)\"]', '[\"Cara membuat Steak Tempe :\", \"a. Kukus tempe kira-kira 15 menit\", \"b. Sembari mengukus, haluskan bumbu steak\", \"c. Haluskan tempe yang sudah dikukus\", \"d. Campur tepung, telur, tempe dan bumbu yang sudah dihaluskan\", \"e. Bagi menjadi dua dan pipihkan\", \"f. Goreng steak tempe dengan mentega yg sudah dipanaskan\", \"g. Angkat steak tempe jika sudah berwarna kecoklatan\", \"Cara membuat saus :\", \"a. Panaskan mentega\", \"b. Tumis bawang bombay, bawang merah, bawang putih sampai harum\", \"c. Tambahkan saus sambal dan saus lada hitam\", \"d. Tambahkan larutan tepung meizena dengan air\", \"e. Tunggu 1-2 menit, matikan kompor\", \"Cara membuat bahan pelengkap :\", \"a. Potong kentang, wortel dan kembang kol sesuai selera\", \"b. Kukus setengah matang wortel dan kembang kol (kecuali kentang harus sampai matang)\", \"c. Jika sudah, angkat\", \"d. Untuk membuat mashed potato, kentang yang sudah dikukus sampai matang dihaluskan, selagi masih panas dicampur mentega, merica dan susu cair\", \"Plating :\", \"a. Tata steak tempe, sayur, dan mashed potato di piring\", \"b. Siram steak tempe dengan saus\", \"c. Taburkan daung bawang merah di atas mashed potato\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1086, 4, 'Tempe goreng ketumbar', 'Cara membuat Tempe goreng ketumbar yang enak dan praktis untuk keluarga.', '[\"1 papan tempe\", \"Bumbu :\", \"3 siung bawang putih\", \"2 sdm ketumbar\", \"1 cm kunyit\", \"Garam\", \"Penyedap rasa\"]', '[\"Potong tempe dengan ketebalan 1/2 cm, dan dikerat.\", \"Haluskan bumbu, beri air secukupnya.\", \"Celupkan tempe dibumbu bolak balik, kemudian diamkan selama 1 jam.\", \"Panaskan minyak dan goreng dengan api sedang, sampai kuning keemasan. Angkat dan tiriskan.\", \"Santapan sederhana nan mewah karena bumbunya😍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1087, 3, 'Combro / Comro Isi Sambal Tempe', 'Resep Combro / Comro Isi Sambal Tempe ala rumahan yang dijamin menggugah selera.', '[\"1.5 kg singkong\", \"500 gr kelapa parut\", \"1 sdm peres garam\", \"2 batang daun bawang, iris2\", \"🌀 Bahan Isi Sambal Tempe 🌀\", \"2 papan tempe\", \"1 ikat besar kemangi. Ambil daunnya\", \"2 siung bawang putih\", \"2 buah cabe merah tanjung\", \"10 buah cabe keriting\", \"20 buah cabe rawit merah\", \"3 ruas kencur\", \"1/2 keping gula merah\", \"Secukupnya garam & kaldu bubuk\"]', '[\"Potong2 lalu goreng tempe sampai matang, ulek, sisihkan. Goreng bawang, cabe2 an, angkat, tiriskan. Ulek bawang, cabe, kencur, gula, garam, kaldu bubuk, lalu satukan dgn tempe & kemangi, adul rata, jgn lupa koreksi rasanya. Panaskan sedikit minyak, lalu oseng sambal tempe sampai daun kemangi layu, siap digunakan sbg isi comro.\", \"Cuci, kupas & parut singkong & kelapa, satukan, aduk rata, tambahkan daun bawang, garam, aduk rata,\", \"Ambil adonan combro segenggaman tangan lalu pipihkan, beri sambal di tengahnya, ratakan sampai sambal terbalut adonan, bentuk bulat pipih, lakukan sampai habis\", \"Panaskan minyak, lalu goreng combro sampai kecoklatan, angkat tiriskan, lakukan sampai habis, sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1088, 3, 'Tempe pedes', 'Nikmati kelezatan Tempe pedes dengan resep sederhana ini.', '[\"Tempe 1 papan (tempe matang yang didiamkan sehari)\", \"Petai\", \"Daun kemangi\", \"Udang kecil\", \"Santan dari 1/2 butir kelapa\", \"Bumbu halus:\", \"3 siung Bawang merah\", \"4 siung Bawang putih\", \"3 butir Kemiri\", \"Bumbu dirajang :\", \"Cabe rawit setan\", \"Laos\", \"Daun salam (satu daun dipotong jadi 2)\", \"Garam dan gula\"]', '[\"Potong kotak kotak tempe.\", \"Tumis bumbu halus dengan sedikit minyak\", \"Setelah harum masukkan bumbu yang dirajang\", \"Masukkan udang, petai, tempe.\", \"Beri air secukupnya, masukkan garam dan gula\", \"Setelah air mendidih masukkan santan\", \"Terakhir masukkan daun kemangi\", \"Setelah mendidih matikan api\", \"Siap dihidangkan dengan nasi hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1089, 3, 'Opor tahu,tempe,telur puyuh', 'Cara membuat Opor tahu,tempe,telur puyuh yang enak dan praktis untuk keluarga.', '[\"14 butir telur puyuh\", \"1 papan tempe (potong sesuai selera)\", \"8 buah tahu kuning\", \"300 ml santan\", \"Bumbu halus\", \"6 buah bawang merah\", \"5 buah bawang putih\", \"3 buah kemiri\", \"3 jari kunyit\", \"2 jari jahe\", \"2 jari lengkuas\", \"1 sdm ketumbar\", \"Bahan tambahan\", \"4 lbr daun jeruk\", \"3 lbr daun salam\", \"2 batng sereh (geprek)\", \"secukupnya Garam,gula masako\", \"jika suka #cabe rawit\"]', '[\"Panaskan minyak, lalu tumis bumbu halus dan bumbu tambahan (daun jeruk, d.salm,sereh), sampai matang\", \"Lalu masukan tahu,tempe,telur puyuh dan air sampai 3T terendam beri garam, gula, masako secukupnya, dan masukan rawit unggu sampai mendidih\", \"Setelah mendidih masukan santan, aduk terus dengan api kecil supaya santan tidak pecah.\", \"Jika sudah mendidih angkat dan sajikan, tambah kan bawang goreng supaya lebih harum 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1090, 4, 'Udang tempe kuah santan', 'Udang tempe kuah santan - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1/4 kg udang besar kupas\", \"secukupnya Tempe\", \"1/2 Santan kara\", \"Bumbu halus :\", \"3 biji cabe rawit\", \"1 biji cabe besar\", \"Seruas kunyit\", \"1/2 sdt ketumbar (me ketumbar bubuk)\", \"Daun jeruk\", \"3 siung bawang putih\", \"5 buah bawang merah\", \"secukupnya Lengkuas muda\", \"secukupnya Garam\", \"sendok teh Gula setngh\"]', '[\"Haluskan bumbu-bumbu menggunakan ulekan.\", \"Iris dadu tempe, cuci udang sampai bersih.\", \"Goreng udang setengah mateng, kemudian tumis bumbu yg sudah dihaluskan sampai harum.\", \"Masukkan tempe yg sudah dipotong dan udang yg sudah digoreng kemudian kasih air sesuai secukupnya (me 500ml). Kalau sudah mendidih masukkan santan dan garam gula secukupnyam kemudian tes rasa. Dan siap dinikmati😍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1091, 2, 'Tempe santan', 'Cara membuat Tempe santan yang enak dan praktis untuk keluarga.', '[\"1 lonjor tempe potong dadu\", \"4 butir bawang merah\", \"2 siung bawang putih\", \"2 cm jahe cincang halus\", \"2 cm lengkuas geprek atau iris\", \"1 lembar daun salam\", \"sesuai selera Merica bubuk\", \"sesuai selera Kaldu ayam\", \"Paprika potong dadu sesuai selera\", \"secukupnya Air\", \"1 bungkus kara kemasan kecil\", \"secukupnya Garam dan gula pasir\"]', '[\"Potong tempe dadu\", \"Bumbu: iris bawang merah dan bawang putih. Kemudian tumis bawang, jahe,lengkuas, jahe, daun salam sampai wangi\", \"Masukan potongan paprika, lalu tempe sambil di aduk. Beri santan kara dan air secukupnya, sambil diaduk merata\", \"Masukan merica bubuk, beri garam, kaldu, dan gula sesuai selera\", \"Tunggu beberapa menit sampai bumbu meresap dan benar2 matang. Lalu siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1092, 3, 'Sambal Goreng ATK (Ampela Tempe Kentang) ala Dapur Fitri', 'Sajian tempe lezat: Sambal Goreng ATK (Ampela Tempe Kentang) ala Dapur Fitri penuh protein nabati.', '[\"300 gram Ampela ayam\", \"200 gram Kentang, potong kotak\", \"250 gram Tempe, potok kotak\", \"100 gram Wortel, potong kotak kecil\", \"1 sdt Garam masala\", \"1 sdt Bumbu padang\", \"2 sdm Air jeruk nipis\", \"1/2 sdt Lada putih bubuk\", \"2 sdm Kecap manis\", \"1 sdt Chicken powder\", \"1 butir Bawang bombay, iris\", \"3 butir Bawang merah, iris\", \"3 siung Bawang putih, iris\", \"4 buah Tomat, iris\", \"1 sdt Garam\"]', '[\"Pertama-tama, marinasi ampela ayam bersama bumbu padang, garam masala dan air jeruk nipis. Diamkan sejenak sekitar 7 menit.\", \"Sambil menunggu ampela ayam yang di marinasi. Gorenglah potongan tempe dan kentang, untuk menghemat waktu.\", \"Panaskan minyak dan tumis ampela ayam sekitar 5 menit lalu masukkan irisan bawang, tomat, wortel dan cabe. Aduk rata setelah itu masukkan tempe dan kentang setelah itu beri garam, lada, Chicken powder dan kecap. Aduk rata dan masak sampai bumbu meresap pada tempe dan kentang.\", \"Angkat dan sajikan pada piring.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1093, 3, 'Tempe katsu', 'Nikmati kelezatan Tempe katsu dengan resep sederhana ini.', '[\"Stengah papan tempe(lumatkan)\", \"2 sdm terigu\", \"1 lbar daun bawang (iris iris)\", \"+ 3 sdm air\", \"1 sdt saos tiram\", \"1 sdt kecap manis\", \"1 sdt saos abc\", \"secukupnya Royco\", \"secukupnya Lada bubuk\", \"secukupnya Tepung panir\", \"secukupnya Minyak sayur\"]', '[\"Campur tempe dengan tepung, air, daun bawang, saos tiram, kecap, dan saos abc, royco, dan lada bubuk, uleni dngan tangan, sampai tercampur rata, lalau bulatkan dan pipihkan, samapi agak tipia\", \"Buat bahan pencelup :4 sdm trigu dan air secukupnya, aduk samapai rata\", \"Lumuri tempe dngan terigu kring, lalau celupkan k bahan pencelup, kemudian lumuri dngan tepung panir, kemudian goreng dngan api sedang sampi matang\", \"Selamat mencoba, semoga bermanfaat 😊😊😊😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1094, 3, '29. Kering Balado Tempe Kacang Pedas Manis', 'Nikmati kelezatan 29. Kering Balado Tempe Kacang Pedas Manis dengan resep sederhana ini.', '[\"1 papan tempe (potong tipis2 lalu goreng hingga kering)\", \"100 gram kacang tanah goreng\", \"4 sdm gula putih\", \"50 gr gula jawa iris\", \"2 lmbar daun jeruk (potong tipis)\", \"bumbu halus\", \"3 siung bawang putih\", \"2 siung bawang merah\", \"3 biji cabai merah besar\", \"5 biji cabai rawit kecil\", \"Penywdap rasa secukupnya (me=royko ayam)\", \"secukupnya Garam\"]', '[\"Panskan minyak di penggorengan, masukkan bumbu halua tunggu sampai harum\", \"Kemudian masukkan gula putih,gula merah, penyedap rasa aduk sebwntar hingga berbentuk karamel lalu matikan api\", \"Masukkan tempe yg sda di goreng, kacang tanah dan irisan daun jeruk ke dalam wajan bumbu karamel tadi aduk hingga merata\", \"Setelah merata, ambil piribg saji dan siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1095, 4, 'Tempe Kecap Non MSG', 'Tempe Kecap Non MSG - olahan tempe khas Indonesia yang nikmat.', '[\"1 bungkus tempe daun yg panjang\", \"Kecap manis\", \"Garam\", \"Gula merah\", \"Air\", \"Bumbu halus:\", \"6 bawang merah\", \"2 bawang putih\", \"1 bks kecil Merica bulat\", \"1/2 biji pala\", \"2 biji kemiri utuh\", \"Bumbu cemplung :\", \"3 daun salam\", \"1/2 cm lengkuas\"]', '[\"Potong tempe berbentuk dadu....goreng setengah matang.\", \"Tumis bumbu halus sampai wangi tambahkan daun salam dan lengkuas.\", \"Kemudian masukkan air, kecap manis dan gula merah.\", \"Tunggu sampai air mendidih\", \"Masukkan tempe dan tunggu sampai bumbu meresap\", \"Cek rasa\", \"Bila bumbu sudah meresap dan rasa sudah pas....matikan.kompor, tunggu agak dingin dan hidangkan 😊😊😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1096, 2, 'Tumis tempe kacang panjang special', 'Resep Tumis tempe kacang panjang special yang lezat dan mudah dibuat di rumah.', '[\"1/2 ikat kacang panjang (potong spt korek)\", \"1 ons udang peci\", \"1 papan kecil tempe (potong spt korek)\", \"1 buah tomat\", \"2 iris lengkuas (memarkan)\", \"1 buah serai (memarkan)\", \"1/2 buah jeruk nipis\", \"3 siung bawang merah\", \"2 siung bawang putih\", \"Minyak goreng\", \"2 sdm kecap\", \"1 sdm saus tiram\", \"secukupnya Totole\", \"Gula\", \"Garam\", \"Merica\", \"Air\"]', '[\"Kupas kulit udang lalu cuci bersih. Beri perasan air jeruk nipis dan garam. Diamkan kurleb 15 menit.\", \"Panaskan minyak lalu goreng tempe sampai kering. Angkat lalu tiriskan.\", \"Panaskan 3 sdm mkn minyak goreng. Lalu masukkan bawang merah dan putih yg sdh diiris. Tumis sampai wangi. Kemudian masukkan lengkuas dan serai aduk kembali\", \"Masukkan udang lalu aduk kembali sampai berubah warna. Kemudian masukkan tempe dan kacang panjang\", \"Tambahkan kecap, saus tiram, totole, gula, garam dan merica. Tambahkan sedikit air lalu aduk hingga rata. Test rasa\", \"Bila air sdh meresap masukkan potongan tomat, aduk kembali lalu sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1097, 4, 'Tempe melet seuhah', 'Resep praktis Tempe melet seuhah yang bisa dicoba di rumah.', '[\"1 papan tempe potong agak tebal, belah tengah nya tp jgn sampai putus\", \"Bahan sambel :\", \"3 bh bawang putih\", \"6 bh bawang merah\", \"10 cabe merah keriting\", \"1 genggam cabe rawit ijo (sesuai selera)\", \"1 buah tomat\", \"1/2 terasi ABC\", \"secukupnya Gula & garam\", \"Bahan pelapis :\", \"5 sdm terigu + sejumput garam & kaldu bubuk larutkan dlm air secukupnya. Jgn terlalu encer\", \"Minyak u/ menggoreng\"]', '[\"Buat sambal : panaskan 2sdm minyak kmd masukan bahan sambal. Masak sampai bahan layu. Angkat. Kmd uleg kasar dgn cobek. Bumbui gula & garam. Tes rasa.\", \"Ambil tempe masukan sambel pd bagian yg dibelah. Kmd celup dlm bahan pelapis. Dan goreng dlm minyak panas. Angkat & sajikan\", \"Pedes bikin melet 😝\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1098, 4, 'Tumis buncis wortel tempe', 'Nikmati kelezatan Tumis buncis wortel tempe dengan resep sederhana ini.', '[\"15 buah buncis iris kecil\", \"3 buah wortel ukuran sedang iris panjang\", \"1/2 iris tempe pasar (3ribuan) iris kotak kecil\", \"Minyak goreng untuk menumis bumbu\", \"Air secukupnya (±2 gelas)\", \"🌸 Bumbu\", \"1/2 sdm gula pasir\", \"1/2 sdt garam\", \"1/2 bgks kaldu ayam\", \"Kecap\", \"Saos tiram\", \"3 buah bawang merah iris tipis\", \"1 buah bawang putih iris tipis\", \"3 buah cabe rawit iris serong (sesuai selera)\"]', '[\"Goreng tempe setengah matang\", \"Panaskan minyak goreng, lalu masukkan bawang merah terlebih dahulu. Bila sudah setengah matang masukkan bawang putih dan cabe. Tunggu sampe bumbu matang\", \"Beri air, garam dan gula. Tunggu sampai mendidih. Lalu masukkan buncis dan wortel. Tutup wajan.\", \"Bila sudah empuk wortel dan buncisnya, masukkan tempe, kecap, dan saus tiram\", \"Cek rasa\", \"Lauk siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1099, 2, 'Tempe Melet Mercon', 'Tempe Melet Mercon - olahan tempe khas Indonesia yang nikmat.', '[\"1 papan Tempe\", \"1 bks Tepung bumbu serbaguna\", \"Untuk isian:\", \"1 kaleng Kornet Sapi\", \"Secukupnya daun bawang\", \"18 buah cabai rawit (sesuai selera)\", \"5 buah cabai keriting\", \"3 siung bawang putih\", \"4 siung bawang merah\", \"Secukupnya merica\", \"Secukupnya garam\", \"Secukupnya penyedap rasa\"]', '[\"Iris tempe jadi 8 bagian (sesuai selera, tapi kalo bisa lebih tebal) lalu rendam di air garam\", \"Belah tengah tempe yg sudah diiris tadi (kalo saya di belah bentuk \'V\' kecil, biar isinya bisa masuk banyak)\", \"Uleg cabai, bawang merah & bawang putih, lalu iris tipis daun bawang\", \"Tumis bawang merah & bawang putih sampai harum, lalu masukan cabai dan kornet, setelah itu masukkan daun bawang, garam, penyedap rasa & merica (koreksi rasa)\", \"Masukkan bahan isian ke dalam tempe, lalu lumuri oleh tepung, setelah itu goreng hingga matang & siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1100, 2, 'Bacem tahu tempe', 'Resep Bacem tahu tempe yang lezat dan mudah dibuat di rumah.', '[\"1 papan tahu\", \"1 papan tempe\", \"7 bawang merah\", \"4 bawang putih\", \"1 keping gula merah\", \"1 sdt ketumbar\", \"2 mata asem jawa\", \"1 sdt garam\", \"2 sdm kecap\", \"1 sdt masako\", \"1 ruas lengkuas geprek\"]', '[\"Potong tempe,tahu lalu goreng\", \"Haluskan semua bumbu, lalu tumis hingga harum, lalu tambah kan air dan kecap\", \"Masukan tempe tahu biarkan hingga menyusut\", \"Sudah matang hidang kan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1101, 3, 'Tempe orek pedes', 'Resep praktis Tempe orek pedes yang bisa dicoba di rumah.', '[\"1 papan tempe, potong dadu/sesuai selera\", \"5 siung bawang merah, iris halus\", \"3 siung bawang putih, iris halus\", \"Cabe rawit merah sesuai selera banyaknya, potong serong\", \"Seruas lengkuas memarkan\", \"5 lembar daun jeruk, buang tulang daunnya\", \"1 batang serai, geprek\", \"2 sdm kecap manis\", \"1/2 sdm kecap asin\", \"secukupnya Garam dan gula\"]', '[\"Sipakan bahannya\", \"Goreng tempe sampai matang, sisihkan.\", \"Tumis bawang merah, bawang putih, cabai, lengkuas, daun jeruk, serai sampai harum.\", \"Masukkan tempe aduk sebentar.\", \"Tambahkan garam, gula, kecap asin, kecap manis, aduk rata, jika terlalu kering bisa tambahkan sedikit air.\", \"Masak sampai bumbu meresap, tes rasa,siap di sajikan. Happy cooking moms.. 😊😊😊😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1102, 2, 'Tempe balado by icha', 'Sajian tempe lezat: Tempe balado by icha penuh protein nabati.', '[\"2 papan tempe\", \"9 siung bawang merah\", \"5 siung bawang putih\", \"15 cabai merah keriting\", \"5 cabai rawit merah\", \"2 kemiri (boleh skip) aku tadi lupa ga tak taroin\", \"1/2 tomat merah\", \"1 1/2 sendok teh garam\", \"1/2 gelas belimbing Air\", \"1 sendok teh gula putih\", \"1/4 kg minyak goreng\"]', '[\"Potong dadu tempe\", \"Cuci bersih bumbu bawang putih bawang merah cabe\", \"Kemudian uleg halus bumbu dan jangan lupa masukan garam agar cepat halus\", \"Siapkan minyak panas\", \"Goreng tempe hingga kecoklatan\", \"Setelah mateng angkat tempe dan minyak bekas menumis tempe di parohkan atau ambil secukupnya untuk menumis bumbu\", \"Tumis bumbu hingga harum dan matang masukan air dan gula aduk sebentar masukan tempe\", \"Aduk rata jangan lupa tambahkan penyedap rasa goreng sampai keaduk rata dan air menyusut\", \"Tempe balado by Icha siap dihidangkan\", \"Happy cooking bunda\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1103, 4, 'Kering Tempe dan Kentang', 'Nikmati kelezatan Kering Tempe dan Kentang dengan resep sederhana ini.', '[\"1 papan tempe ukuran besar\", \"1/2 kg kentang\", \"150 gr gula jawa\", \"8 siung bawang merah\", \"5 siung bawang putih\", \"10 buah cabe merah\", \"Secukupnya garam\", \"Minyak untuk menggoreng dan menumis\"]', '[\"Iris tipis kentang dan tempe sesuai selera.\", \"Goreng kentang dan tempe sampai kering.\", \"Iris bawang merah dan putih juga cabe, kemudian tumis sampai kering.\", \"Beri sedikit air, masukkan gula jawa dan garam.\", \"Tunggu sampai air menjadi kental seperti karamel.\", \"Koreksi rasa bila sudah pas masukkan kentang dan tempe yang sudah digoreng. Aduk2 sampai tercampur rata.\", \"Bila sudah dingin simpan didalam toples agar renyahnya awet.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1104, 2, 'Sambal Goreng Tempe Gembus', 'Sambal Goreng Tempe Gembus - olahan tempe khas Indonesia yang nikmat.', '[\"3 papan tempe gembus\", \"250 gr krecek\", \"2 papan pete\", \"15 biji cabe rawit\", \"5 biji cabe merah\", \"5 biji cabe hijau\", \"7 siung bawang merah\", \"4 siung bawang putih\", \"2 lembar daun salam\", \"1 ruas lengkuas, geprek\", \"Kecap manis\", \"Gula\", \"Garam\", \"Penyedap rasa\", \"Minyak goreng\"]', '[\"Potong dadu tempe gembus lalu cuci dengan air hangat agar tempe menjadi sedikit padat.\", \"Cuci bersih krecek lalu potong sesuai selera\", \"Kupas pete dan potong menjadi 2. Jika suka utuh maka tdk perlu dipotong. Cuci bersih.\", \"Potong bawang merah, bawang putih, cabe rawit, cabe merah dan cabe hijau.\", \"Tumis bumbu, daun salam dan lengkuas. Tumis hingga harum, selanjutnya masukkan krecek dan pete tumis hingga setengah matang. Lalu masukkan tempe gembus. Masukkan kecap manis, garam, gula, penyedap rasa. Aduk hingga merata. Koreksi rasa.\", \"Sajikan selagi hangat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1105, 4, 'Bacem tempe', 'Bacem tempe - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"2 papan tempe\", \"5 lmbr daun salam\", \"Air kelapa dari 1buah kelapa\", \"2 btng sereh\", \"3 ruas lengkuas\", \"♛Bumbu yg dihaluskan:\", \"5 buah bawang putih\", \"4 ruas kunyit\", \"1 genggam ketumbar\", \"Secukupnya asam jawa\", \"Secukupnya gula merah\", \"Secukupnya garam\"]', '[\"Potong tempe sesuai selera,\", \"Panaskan wajan, beri air kelapa tambahkan bumbu halus, masukkan daun salam, sereh, dan lengkuas yg digeprek, secukupnya garam, tambahkan sedikit air.\", \"Tambahkan potongan tempe, masak dengan api kecil hingga air larut dan bumbu meresap.\", \"Bisa langsung digoreng, atau jg disimpan dalam kulkas untuk cadangan lauk.\", \"Selamat mencoba, 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1106, 2, 'Sate tempe', 'Cara membuat Sate tempe yang enak dan praktis untuk keluarga.', '[\"400 grm tempe potong dadu\", \"3 lembar daun salam\", \"Seruas lengkuas geprek\", \"100 ml santan\", \"secukupnya Garam dan gula\", \"bahan yg dihaluskan :\", \"8 siung bawang merah\", \"5 siung bawang putih\", \"Seruas kunyit\", \"1 sdt ketumbar\", \"bahan olesan :\", \"2 sdm kecap manis dicampur dengan 1 sdt minyak goreng\"]', '[\"Siapkan bahannya\", \"Tumis bumbu halus, lengkuas, dan daun salam sampai harum.\", \"Tambahkan tempe, santan, garam, gula masak sampai bumbu meresap dan kering.\", \"Tusuk2 tempe dengan tusukkan sate.\", \"Olesi kecap manis.\", \"Bakar sampai harum dan kecoklatan.\", \"Baru diangkat ini moms. Siap disajikan.\", \"Happy cooking.. 😉😉😉😉😉😉😉\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1107, 4, 'Oseng Cingur Tempe', 'Sajian Oseng Cingur Tempe yang praktis dan lezat untuk dinikmati bersama.', '[\"2 papan tempe ukuran sedang\", \"3 genggam cingur\", \"5 siung bawang merah\", \"4 siung bawang putih\", \"5 cabe hijau\", \"3 cabe merah\", \"6 cabe rawit\", \"Lengkuas\", \"Daun Salam\", \"Kecap\", \"Garam\", \"Gula\", \"Kaldu jamur\"]', '[\"Potong cingur kotak\\\"dan cuci bersih. Rebus sebentar. Sisihkan. Potong juga tempe kotak\\\". Goreng tempe sebentar. Sisihkan.\", \"Iris kasar semua cabe. Haluskan bawang merah dan bawang putih.\", \"Tumis bumbu halus(bawang merah dan putih). Tambahkan lengkuas dan daun salam. Tumis sampai harum dan berubah warna. Kemudian masukkan irisan semua cabe, aduk\\\" dan tumis sebentar.\", \"Tambahkan sedikit air. Masukkan cingur, aduk\\\". Kemudian masukan tempe goreng. Aduk. Masukkan pula garam, gula, kaldu jamur dan kecap. Aduk merata dan masak sampai matang. Jangan lupa koreksi rasa.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1108, 4, 'Ayam & Tempe Geprek Keju Melt', 'Nikmati kelezatan Ayam & Tempe Geprek Keju Melt dengan resep sederhana ini.', '[\"4 Paha atas Ayam\", \"6 iris tempe\", \"Bahan bumbu ayam:\", \"1 bungkus tepung bumbu ayam Sasa\", \"Air\", \"2 siung Bawang putih\", \"Secukupnya garam\", \"Secukupnya lada bubuk\", \"Bahan sambal bawang:\", \"2 siung bawang putih\", \"20 Cabe rawit merah\", \"6 siung bawang merah\", \"secukupnya Garam\", \"secukupnya Gula\", \"Minyak goreng\", \"sedikit Air\", \"Bahan pelengkap:\", \"Keju craft melt / keju mozzarella\"]', '[\"Potong2 tempe. Sisihkan.\", \"Geprek 2 siung bawang putih.\", \"Panaskan air secukupnya. Masukkan bawang putih, garam, lada bubuk.\", \"Setelah air mendidih masukkan paha atas ayam.\", \"Rebus hingga ayam empuk. Angkat lalu sisihkan.\", \"Siapkan bumbu ayam tepung pada 2 wadah. 1 wadah bumbu cair dan 1 wadah bumbu kering. Untuk membuat tepung bumbu cair hanya menambahkan air pada tepung kering.\", \"Celupkan ayam yg sudah di rebus ke tepung bumbu kering, lalu masukkan ketepung bumbu cair dan terakhir masukkan ke tepung bumbu kering kembali.\", \"Lalu lakukan yg sama dengan tempe. Masukkan tempe ketepung bumbu cair dan kering.\", \"Goreng ayam & tempe.\", \"Membuat sambal: ulek kasar cabai, bawang merah, bawang putih, setelah diulek tumis dengan minyak yang telah dipanaskan, tambahkan air sedikit. Tumis hingga harum lalu masukkan garam & gula. Tumis kembali hingga sambal matang. (Saya menggunakan Chopper) :)\", \"Tata ayam dan tempe pada loyang, panaskan oven.\", \"Tata sambal bawang diatas ayam dan tempe lalu geprek.\", \"Lalu parut keju melt diatas ayam dan tempe yg sudah digeprek dengan sambal bawang.\", \"Panggang ayam dan tempe hingga keju leleh.\", \"Catatan: Bisa pakai keju mozzarella bila ada. Bila pakai keju mozzarella lebih nikmat dan lebih meleleh kejunya\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1109, 3, 'Tempe Mendoan Krispi', 'Nikmati kelezatan Tempe Mendoan Krispi dengan resep sederhana ini.', '[\"1 Bungkus Tempe\", \"2 Siung Bawang Merah\", \"3 Siung Bawang Putih\", \"1 Daun Bawang\", \"1/2 Sdm Ketumbar bubuk\", \"1 cm Kunyit\", \"4 Sdm Tepung Terigu\", \"2 Sdm Tepung Beras\", \"Secukupnya Air\", \"sesuai selera Gula Garam\", \"1 Butir kemiri\"]', '[\"Siapkan bumbunya dulu, bawang merah bawang putih, kunyit, ketumbar, kemiri, gula garam secukupnya, Ulek sampai halus.\", \"Tambahkan air, aduk. Masukan tepung, aduk.\", \"Masukan tempe yg sudah di iris\", \"Celupkan tempe, irisi daun bawang tipis2.\", \"Goreng tempe sampai matang kecoklatan\", \"Sajikan, paling enak di makan waktu masih hangat2 nya😘\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1110, 3, 'Tempe penyet', 'Tempe penyet - olahan tempe khas Indonesia yang nikmat.', '[\"1 kotak kecil tempe, potong2\", \"1 bungkus Bumbu racik tempe\", \"3 siung bawang putih\", \"5 siung bawang merah\", \"1 tomat ukuran kecil\", \"10 cabe rawit merah\", \"10 cabe merah keriting\", \"1 sdt terasi goreng/bakar\", \"sesuai selera Gula, garam\"]', '[\"Rendam tempe yg sudah dipotong2 dalam bumbu racik yg sudah dicampur air, biarkan selama 10 menit\", \"Goreng tempe sampai kering kecoklatan, sisihkan\", \"Goreng bawang putih, bawang merah, cabe, tomat sampai matang, angkat bersama sedikit minyaknya\", \"Ulek terasi, garam, gula, dan bumbu yg sudah digoreng, masukkan tempe sambil di penyet2, sajikqn bersama nasi panas\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1111, 2, 'Oseng tempe pedas', 'Sajian tempe lezat: Oseng tempe pedas penuh protein nabati.', '[\"1 papan tempe (mau tempe yang pakai daun atau plastik boleh)\", \"kecap manis\", \"1 ons cabai besar hijau\", \"4 siung bawang merah\", \"3 siung bawang putih\", \"1 iris sedikit lengkuas\", \"garam\", \"penyedap rasa\", \"minyak goreng\", \"gula jawa\"]', '[\"Iris kecil kecil tempe lalu goreng hingga kecoklatan, sisihkan.\", \"Iris cabai hijau, bawang merah,bawang putih.\", \"Panaskan minyak tumis irisan bumbu hingga harus, masukkan gula jawa dan garam, lengkuas dan air sedikit.\", \"Masukkan tempe goreng, kecap manis, penyedap, aduk hingga rata dan icip icip enak sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1112, 2, 'Orem tempe tahu', 'Resep praktis Orem tempe tahu yang bisa dicoba di rumah.', '[\"1 batangan tempe\", \"8 kotak tahu\", \"Bumbu halus :\", \"5 siung bawang merah\", \"4 siung bawang putih\", \"1 ruas kunyit\", \"Kencur (sesuai selera)\", \"3 buah kemiri\", \"Ketumbar (secukupnya)\", \"Lengkuas (geprek)\", \"2 lembar Daun salam\", \"2 lembar Daun jeruk\", \"Cabe rawit (secukupnya)\", \"Santan kara\"]', '[\"Potong kotak tempe tiriskan\", \"Goreng tahu setengah matang\", \"Goreng dg minyak sedikit bahan bumbu halus (kecuali lengkuas),,angkat, haluskan,tiriskan\", \"Panaskan penggorengan dengan sedikit minyak, setelah panas masukkan bumbu halus tunggu sampe harum.\", \"Setelah harum, masukkan tempe dan tahu\", \"Beri air secukupmya\", \"Masukkan daun salam dan daun jeruk, serta lengkuas yg sudah digeprek.\", \"Setelah mendidih masukkan santan. Dan tambahkan penyedap rasa. (Beri gula sedikit)\", \"Sesekali aduk agar tekstur santan tidak pecah\", \"Setelah matang orem orem siap dmkn dan disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1113, 3, 'Bakwan tempe sayur kriuk', 'Buat Bakwan tempe sayur kriuk yang nikmat dengan langkah-langkah mudah ini.', '[\"1 buah tempe\", \"150 gram tepung terigu\", \"2 sdm tepung maizena\", \"2 sdm margarin\", \"1 buah wortel\", \"2 lembar sawi putih\", \"2 tangkai bawang daun\", \"2 lembar cesim\", \"2 lembar kol\", \"2 tangkai seledri\", \"3 siung bawang merah\", \"2 siung bawang putih\", \"1/2 sdm ketumbar\", \"3 buah kemiri\", \"1 ruas kunyit\", \"secukupnya garam\", \"secukupnya bubuk kaldu ayam (optional)\", \"secukupnya air\", \"secukupnya minyak goreng\"]', '[\"Lelehkan margarin,sisihkan\", \"Hancurkan tempe(saya pake tangan saja), usahakan kacang kedelainya tdk sampe ancur, lalu iris tipis semua jenis sayuran,sisihkan\", \"Haluskan bawang merah,bawang putih, kemiri,kunyit\", \"Campurkan semua bahan, buat adonan, jgn terlalu encer\", \"Panaskan minyak (api sedang)\", \"Ambil bakwan dgn sendok lalu goreng (saya goreng agak tipis spy garing)\", \"Jika sudah dianggap matang, angkat\", \"Sajikan\", \"Bisa disantap begitu saja atau ditemani cabe rawit,saus sambal,mayones,atau sambal cuko\", \"Klu saya dicoel sambel cuko dgn irisan cabe rawit\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1114, 3, 'Ayam dan Tempe Goreng Kunyit', 'Sajian Ayam dan Tempe Goreng Kunyit yang praktis dan lezat untuk dinikmati bersama.', '[\"1/2 ekor ayam, potong 6\", \"1/2 papan tempe, potong-potong\", \"2 siung bawang putih\", \"3 siung bawang merah\", \"1 ruas jari kunyit\", \"1 ruas jari jahe\", \"1/2 st ketumbar\", \"secukupnya Garam, gula, kaldu jamur (optional)\", \"1,5 gelas air\"]', '[\"Haluskan bumbu (saya dengan blender+stengah gelas air).\", \"Susun ayam dan tempe di wajan,masukkan bumbu halus dan air. Ungkep hingga ayam empuk dan bumbu meresap. Angkat dan biarkan dingin\", \"Goreng dalam minyak hingga kuning keemasan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1115, 2, 'Tempe goreng tepung renyah', 'Sajian tempe lezat: Tempe goreng tepung renyah penuh protein nabati.', '[\"2 papan tempe kecil\", \"Bahan tepung kering:\", \"1 bungkus tepung serba guna(prima)\", \"5 sdm tepung terigu\", \"Secukupnya garam\", \"1/4 sdt bubuk kunyit\", \"Seujung sdt baking soda\", \"Bahan tepung basah:\", \"1 bungkus tepung serba guna (prima)\", \"6 sdm tepung terigu\", \"2 siung bawang putih (haluskan)\", \"Secukupnya garam\", \"1/4 ketumbar bubuk\", \"Secukupnya air\", \"Secukupnya minyak untuk menggoreng\"]', '[\"Iris tipis tempe.\", \"Campur jadi satu bahan kering aduk rata. Campur bahan basah aduk rata.\", \"Masukan tempe ke tepung basah kemudian masukan ke tepung kering lalu goreng sampai matang.\", \"Sudah matang tempe kriukkk... bangett..\", \"Cocok bgt sama nasi pecel.\", \"Note: baking soda nya jangan kebanyakan nanti pait.\", \"Selamat mencoba.. simple bgt kan..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1116, 3, 'Tumis oyong wortel tempe', 'Nikmati kelezatan Tumis oyong wortel tempe dengan resep sederhana ini.', '[\"1 buah wortel, potong serong\", \"1 buah oyong, kupas, potong-potong\", \"1/2 potong tempe, potong kecil\", \"Bumbu iris ::\", \"3 buah cabe merah keriting, potong serong\", \"2 butir bawang merah\", \"2 siung bawang putih\", \"1/2 sdm saus tiram\", \"Secukupnya garam dan gula\"]', '[\"Panaskan wajan. Beri sedikit minyak. Tumis bumbu iris hingga harum. Masukkan wortel dan tempe, beri sedikit air. Tutup. Biarkan wortel empuk.\", \"Setelah wortel empuk, masukkan oyong, garam, gula, dan saus tiram. Aduk rata. Tes rasa. Masak hingga oyong layu.\", \"Angkat dan hidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1117, 4, 'Tumis tempe dan kepala cumi', 'Sajian Tumis tempe dan kepala cumi yang praktis dan lezat untuk dinikmati bersama.', '[\"1 papan tempe potong kecil2\", \"1/4 kg kepala cumi\", \"Royco ayam\", \"secukupnya Garam\", \"secukupnya Gula merah\", \"5 sdm air\", \"Bumbu tumis\", \"7 buah cabe rawit iris tipis\", \"4 buah cabe merah kriting iris tipis\", \"4 siung bawang merah iris tipis\", \"4 siung bawang putih cincang halus\", \"1 buah bawang bombay potong halus\", \"1 buah tomat potong 4\", \"2 batang daun bawang iris tipis\", \"2 lbr daun salam\", \"1 ruas laos\"]', '[\"Goreng tempe sampai setengah kering\", \"Cuci cumi diair mengalir lalu rendam air garam lalu goreng hingga matang\", \"Tumis bawang merah + bawang putih hingga harum lalu masukkan cabai +bawang bombai masak sampai layu masukan Laos + salam beri garam penyedap rasa (Royco) gula merah,aduk sampai rata tambahkan air 5 sendok makan biar bumbu rata aduk hingga air susut sedikit\", \"Masukan daun bawang aduk2 lalu masukan tempe + cumi aduk hingga rata lalu sajikan dengan nasi panas\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1118, 2, 'Tempe Isi', 'Sajian Tempe Isi yang praktis dan lezat untuk dinikmati bersama.', '[\"1 papan tempe\", \"1 bungkus kecil tepung sajiku\", \"5 sdm tepung maizena\", \"Secukupnya daun bawang\", \"1 sdm ketumbar\", \"2 siung bawang putih\", \"Secukupnya lada bubuk\", \"Seujung sendok garam\", \"Bahan sambel:\", \"2 siung bawang merah\", \"4 siung bawang putih\", \"10 buah cabe rawit\", \"Royco\"]', '[\"Potong tempe menjadi beberapa bagian,iris tengahnya seperti contoh gambar\", \"Goreng bahan sambel lalu ulek\", \"Isi tempe dengan sambel sesuai selera\", \"Larutkan semua tepung tp jngan terlalu encer,beri tambahan daun bawang,lada bubuk,garam,ketumbar\", \"Masukkan tempe ke adonan tepung lalu goreng. Beres. Sajikan dg sambal kecap/saos/cabe ijo\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1119, 3, 'Tumis tempe kemangi', 'Resep Tumis tempe kemangi ala rumahan yang dijamin menggugah selera.', '[\"1 papan tempe\", \"1 ikat daun kemangi\", \"3 aiung bawang putih\", \"2 siung bawang merah\", \"Secukupnya gula garam\", \"Secukupnya kecap\", \"Secukupnya kaldu bubuk\", \"Secukupnya minyak\"]', '[\"Cuci bersih bahan, iris 2 bawang, suka pedas? Tambahkan irisan cabai yaaa. Tempe goreng terlebih dahulu\", \"Tumis bawang hingga matang. Kemudian masukkan tempe. Tambahkan kecap, beri bumbu, koreksi rasa. Jika sudah matang tambahkan kemangi, aduk sebentar hingga layu. Matikan. Siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1120, 2, 'Sambal Tempe', 'Sajian Sambal Tempe yang praktis dan lezat untuk dinikmati bersama.', '[\"1 papan Tempe semangit, potong-potong\", \"20 buah Cabe rawit hijau (optional, bisa dikurang/ditambah)\", \"4 siung Bawang putih\", \"1 ruas Kencur, kupas\", \"Secukupnya Gula dan Garam\", \"Secukupnya Minyak goreng, utk menggoreng\"]', '[\"Goreng tempe sampai agak kering, tiriskan.\", \"Uleg cabe, bawang putih, kencur hingga halus. Beri gula, garam, cek rasa. Beri minyak panas bekas goreng tempe td, kurleb 2 sdm.\", \"Masukkan tempe, uleg kasar atau di gecek (halah). Aduk hingga rata.\", \"Siap disajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1121, 3, 'Tempe Balado/Orek Tempe', 'Buat Tempe Balado/Orek Tempe yang nikmat dengan langkah-langkah mudah ini.', '[\"1 papan Tempe, potong dadu\", \"1 buah Bawang Bombay ukuran kecil, iris tipis\", \"1 lembar daun Jeruk, robek2 daunnya\", \"2 lembar daun Salam\", \"1 ruas Lengkuas, geprek\", \"1 buah/sisir Gula merah\", \"Secukupnya Garam dan Gula pasir\", \"Secukupnya Minyak goreng, utk menumis\", \"Bumbu halus:\", \"5 siung Bawang Merah\", \"4 siung Bawang Putih\", \"3 buah Cabe Merah besar\", \"10 buah Cabe Rawit hijau\", \"2 sdm Minyak goreng, utk blender bumbu\"]', '[\"Goreng tempe terlebih dahulu, hingga agak kering/matang. Sisihkan.\", \"Tumis bumbu halus, masukkan gula merah, lengkuas, daun salam dan daun jeruk, masak hingga agak menyusut dan berkaramel.\", \"Masukkan bawang bombay, beri gula dan garam, tes rasa (pedas, manis, asin)\", \"Masukkan tempe yg sudah digoreng, aduk hingga tempe rata dg bumbu.\", \"Siap disajikan! Selamat mencoba! ;)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1122, 3, 'Tempe Melet - Tempe Pedes', 'Cara membuat Tempe Melet - Tempe Pedes yang enak dan praktis untuk keluarga.', '[\"1 Papan Tempe\", \"12 Siung Bawang Merah\", \"6 Siung Bawang Putih\", \"1 Buah Tomat\", \"150 gram Cabe rawit merah\", \"Bahan Tepung :\", \"250 gram Tepung rendah protein\", \"Secukupnya Air\", \"Secukupnya Garam\", \"1 Sdm Ketumbar halus\", \"1 Sdt Gula\", \"Minyak untuk menggoreng\", \"1 Sdm Margarin (yang ini saya ngga pake soalnya abis)\"]', '[\"Siapkan Tempe, Lalu Potong tempe tapi jangan terlalu tipis karena tengahnya nanti akan diisi, kurang lebih 1.5 cm - 2cm\", \"Ulek semua cabe, bawang putih, bawah merah, tomat, (klo cape ngulek bisa pake Food Processor, tapi inget jangan sampai halus)\", \"Setelah semua diulek, siapkan wajan, panaskan minyak, setelah minyak panas masukan sambal yang diulek tadi lalu tambahkan Garam dan Gula (koreksi rasa yaa..)\", \"Setelah itu, saatnya memasukan sambal tadi kedalam tempenya.\", \"Sekarang bikin adonan tepungnya, siapkan wadah, masukkan tepung terigu, ketumbar bubuk, masukkan air sedikit-sedikit (tepung yang kita buat ini sedikit kental ya, bisa dibilang kaya bikin pisang goreng)lalu masukkan garam dan margarin.\", \"Siapkan wajan kembali untuk menggoreng tempe, minyaknya agak banyak ya, agar tempenya terendam semua.. jika sudah kecoklatan angkat tempenya dari wajan, setelah itu tempe melet siap untuk disantap.\", \"Sedikit catatan kecil aja, seharusnya di adonan tepungnya itu, ada bumbu halusnya seperti bawang merah, bawang putih dan kunyit, berhubung tenaganya abis buat ngulek sambel, jadi semua itu diskip aja, cuma yang dipake ketumbar bubuk aja.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1123, 2, 'Oseng tempe gembus cabe ijo', 'Resep Oseng tempe gembus cabe ijo ala rumahan yang dijamin menggugah selera.', '[\"2 papan tempe gembus\", \"9 biji cabe ijo\", \"7 biji cabe rawit\", \"3 siung bawang merah\", \"3 siung bawang putih\", \"Secukupnya garam dan penyedap\", \"Secukupnya minyak\", \"Secukupnya garam\"]', '[\"Iris tempe beserta bumbu\", \"Tumis bumbu sampai harum. Masukkan garam dan penyedap. Masukkan tempe. Tambahkan air panas.\", \"Masak sampai matang. Jangan lupa cicipi rasanya\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1124, 2, 'Tempe Goreng Asin', 'Tempe Goreng Asin - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 tempe bungkus daun yg panjang\", \"secukupnya Minyak goreng\", \"Bumbu halus\", \"3 siung bawang putih besar\", \"1 ruas kunyit lebih dikit\", \"1 ruas jahe\", \"1 sdt garam\", \"1 sdt penyedap (roy**)\", \"10 biji merica\", \"Sepucuk sdt micin (dikit bgt)\", \"1/2 gelas air masak\"]', '[\"Potong tempe tipis tapi jangan terlalu tipis ya bun, nanti jadinya malah kripik tempe (sesuai selera)\", \"Haluskan semua bumbu, berhubung judulnya tempe asin jadi aku td kasih garam yg banyak, sama tambahan sedikit micin, setelah bumbu benar² halus tambahkan air. Jangan d icipi ya bun air bumbunya karena so pasti asin bgt 😂\", \"Panaskan minyak sesuai kebutuhan, goreng tempe di minyak panas, kalau sudah menguning dan kering angkat tiriskan.\", \"Note : pastikan tempe benar² kering karna jika tdk kering maka tempe akan mengandung banyak minyak. Karena bumbu ini menggunakan kunyit maka pastikan minyak di wajan jangan berlebihan karena kunyit membuat minyak hitam dan wajan lengket. Selamat mencoba ya bun, aku sih suka bgt sama masakan aku yg satu ini mungkin gara² pake micin jd rasanya gurih bgt 😂\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(1125, 4, 'Orem2 tempe', 'Orem2 tempe - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 bkgs tempe\", \"1 kara kecil\", \"3 siung bawang merah\", \"3 siung bawang putih\", \"Lengkuas\", \"3 biji kemiri\", \"Kunyit\", \"secukupnya Cabe\", \"Jahe\", \"2-3 daun jeruk\", \"secukupnya Garam\", \"Penyedap rasa\", \"1/2 sdt gula\"]', '[\"Potong2 tempe sesuai selera lalu kukus selama 5menit stlh matang tiriskan\", \"Blender semua bumbu sampe halus kecuali lengkus sama daun jeruk\", \"Panaskan wajan utk masak bumbu yg sudah dihaluskan+daun jeruk+lengkuas yg digeprek tumis sampe harum\", \"Stlh itu masukan tempe+air secukupnya masukan garam+penyedap rasa+gula diamkan sampe medidih stlh itu masukan kara aduk2 sampe bumbu+kara meresap.\", \"Masak selama 10 menit stlh siap disajikan orem2 tempenya\", \"Selamat mencoba.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1126, 3, 'Tempe,kentang,santan pedas', 'Buat Tempe,kentang,santan pedas yang nikmat dengan langkah-langkah mudah ini.', '[\"2 buah Tempe,  kentang, potong sesuai selera\", \"Santan kelapa\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"1 batang sereh\", \"Seruas lengkuas\", \"2 lembar daun salam\", \"Cabe rawit + cabe kriting\", \"1 sachet royco ayam\", \"secukupnya Gula pasir,garam\", \"Minyak goreng\"]', '[\"Potong tempe dan kentang,goreng setengah mateng,angkat dan tiriskan\", \"Siapkan bumbu,iris bawang merah,bawang putih,dan cabe\", \"Peras kelapa parut 2 kali perasan ditempatkan terpisah\", \"Tumis bawang merah, bawang putih, lengkuas,sereh sampai layu dan wangi,masukan tempe dan kentang,dun salam,tambahkan perasan santan yang ke 2, royco,gula pasir,biarkan sampai kentang empuk\", \"Tambahkan lagi santan perasan pertama dan cabe,tes rasa,klo kurang asin bisa ditambahkan garam,sampai rasanya pas dilidah\", \"Pindahkan kepiring saji dan siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1127, 2, 'Oseng Tempe', 'Cara membuat Oseng Tempe yang enak dan praktis untuk keluarga.', '[\"1 papan tempe uk sedang pot dadu\", \"2 siung bawang putih\", \"3 buah bawang merah\", \"3 buah cabai hijau\", \"5 buah pete\", \"1 sdt gula pasir\", \"2 sdm kecap manis\", \"1/2 sdt garam/kaldu bubuk royco\", \"1 sdm saus tiram\", \"secukupnya minyak goreng\", \"30 ml air matang\", \"1 lembar daun salam\", \"2 cm lengkuas\"]', '[\"Goreng tempe sampai layu/setengah matang, angkat sisihkan\", \"Iris bawang dan cabai, tumis sampai harum\", \"Masukan daun salam, lengkuas, pete. masak hingga layu dan kecoklatan\", \"Masukan tempe, aduk sebentar. masukan air, saus tiram, kecap, gula, garam\", \"Masak hingga bumbu meresap dan air menyusut\", \"Angkat, sajikan dengan bawang goreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1128, 4, 'Nugget Tempe', 'Sajian tempe lezat: Nugget Tempe penuh protein nabati.', '[\"1 papan tempe (haluskan dengan garpu)\", \"1 buah wortel (parut kasar)\", \"2 batang daun bawang iris\", \"1 butir telur\", \"5 sdm tepung terigu\", \"5 buah bawang merah (iris tipis dan goreng)\", \"3 siung bawang putih (haluskan)\", \"secukupnya Garam, lada, kaldu ayam bubuk\", \"150 gr tepung roti untuk lapisan\", \"Minyak untuk menggoreng\"]', '[\"Campur semua bahan jadi 1 kecuali telur. Test rasa lalu tambahkan telur.\", \"Ambil 1 sendok makan adonan. Bulatkan. (Adonan agak lengket).\", \"Masukkan ke tepung roti dan tekan menggunakan garpu sampai berbentuk bulat pipih. Balurkan sampai semua bulatan tertutup tepung roti.\", \"Goreng dalam minyak panas sampai matang.\", \"Enak juga pakai cocolan saus sambal dan mayonaise. 😀\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1129, 4, 'Tempe tahu bacem', 'Nikmati kelezatan Tempe tahu bacem dengan resep sederhana ini.', '[\"1 papan tempe\", \"3 potong tahu\", \"Bumbu halus:\", \"8 siung bawang merah\", \"5 siung bawang putih\", \"1 sdt ketumbar\", \"2 keping asam\", \"Gula merah\", \"Garam\", \"Kecap manis\", \"Lengkuas geprek\", \"Kaldu bubuk\"]', '[\"Potong tempe dan tahu, haluskan bumbu\", \"Tumis bumbu hingga harum, masukan lengkuas, masukan air, tambahkan kecap manis\", \"Masukan tempe dan tahu, ungkep sampe air menyusut\", \"Setelah menyusut, sisihkan\", \"Panaskan minyak dan goreng\", \"Angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1130, 3, 'Tempe orek kentang pedas manis', 'Tempe orek kentang pedas manis - olahan tempe khas Indonesia yang nikmat.', '[\"1/2 papan tempe\", \"1 kentang\", \"1 sdt ketumbar\", \"1 sdt lada\", \"5 cabe\", \"3 bawang merah\", \"2 bawang putih\", \"1 batang serai\", \"1 daun salam\", \"4 sdm kecap manis\", \"1 gelas air\", \"1 sdt lengkuas\"]', '[\"Iris kotak tempe dan kentang, goreng dan tiriskan\", \"Haluskan bumbu,kecuali daun salam serai dan lengkuas, tumis hingga harum\", \"Masukan tempe kentang serai dan daun salam,ratakan\", \"Tambahkan air, setelah mendidih masukan garam, penyedap rasa(sesuai selera)\", \"Tunggu hingga air tinggal sedikit sambil sesekali di aduk\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1131, 3, 'Tempe menjes merakyat', 'Resep praktis Tempe menjes merakyat yang bisa dicoba di rumah.', '[\"Tempe gembus\", \"Tepung rempeyek (ak pake merk VIRGO)\", \"Minyak goreng\", \"secukupnya Air\", \"sejumput Garam\"]', '[\"Potong tempe gembus tipis2(aku jadi in 10 potong)\", \"Siapkan adonan basah dgn mencampur tepung, garam & air. (atur kekentalan sesuai selera)\", \"Celupkan tempe ke dlm adonan basah\", \"Goreng hingga kuning kecoklatan\", \"Angkat & sajikan :)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1132, 2, 'Gulai tempe telor', 'Buat Gulai tempe telor yang nikmat dengan langkah-langkah mudah ini.', '[\"1 papan tempe (potong2)\", \"Telor (rebus, kupas)\", \"1 bks kara\", \"3 siung bawang putih\", \"6 siung bawang merah\", \"secukupnya Cabe keriting\", \"secukupnya Ketumbar\", \"secukupnya Kayu manis\", \"secukupnya Kapulaga\", \"Bunga lawang secukupnya\", \"secukupnya Jinten\", \"2 buah kemiri\", \"Salam\", \"Sere\", \"secukupnya Minyak goreng\", \"secukupnya Air\", \"secukupnya Kunyit\", \"secukupnya Penyedap/ gula\", \"secukupnya Garam\"]', '[\"Bawang putih, bawang merah, cabe, ketumbar, kayu manis, kapulaga, bunga lawang, jinten, kunyit, kemiri di ulek\", \"Kemudian tumis sampai matang dan harum masukan air tunggu sampai menggolak kemudian masukan tempe, penyedap/ gula, garam, salam, sere masak sampai matang\", \"Kemudian masukan telor dan santan aduk perlahan sampai menggolak angkat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1133, 2, 'Tumis Tauge Buncis Tempe', 'Resep Tumis Tauge Buncis Tempe ala rumahan yang dijamin menggugah selera.', '[\"1 bungkus tauge (beli 3ribu di mba sayur)\", \"1/2 papan tempe\", \"secukupnya Buncis\", \"1/2 buah tomat (iris)\", \"5 siung bawang merah (iris tipis)\", \"3 siung bawang putih (iris tipis)\", \"5 buah cabe merah keriting (iris serong)\", \"3 buah cabe ijo besar (iris serong)\", \"1 ruas jari lengkoas (geprek)\", \"1 lbr daun salam\", \"2 sdm saus tiram\", \"secukupnya Garam, gula, kaldu bubuk\", \"secukupnya Air\"]', '[\"Potong-potong tempe sesuai selera lalu goreng setengah matang\", \"Tumis irisan bawang merah dan bawang putih sampai harum, lalu masukkan irisan cabe, lengkoas dan daun salamTumis sampai layu\", \"Masukkan tempe dan buncis, aduk sebentar lalu tambahkan saus tiram, garam, gula, kaldu bubuk, dan air secukupnya. Aduk kembali\", \"Masukkan tauge dan irisan tomat. Tambahkan air kembali bila perlu. Masak sampai matang, lalu koreksi rasa.\", \"Siap dihidangkan..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1134, 3, 'Sambal Tempe (Tempe Balado) super gampang', 'Sambal Tempe (Tempe Balado) super gampang - olahan tempe khas Indonesia yang nikmat.', '[\"Bahan-bahan\", \"Tempe (dipotong2 kecil, ukurannya sesuai selera)\", \"Bumbu halus (semuanya diblender jadi satu, beri air sedikit)\", \"6 siung bawang merah\", \"5 siung bawang putih\", \"16 buah cabe merah\", \"1 buah tomat\", \"Bahan Tambahan\", \"2 sdm minyak sayur\", \"1 sdm garam\", \"4 sdm gula\", \"Secukupnya penyedap rasa\", \"Secukupnya bawang goreng\"]', '[\"Tempe dipotong kecil, lalu di goreng. Tiriskan.\", \"Panaskan minyak, Tumis bumbu halus. Tambahkan garam, gula, penyedap. Koreksi Rasa.\", \"Masukan tempe yang sudah digoreng. Aduk sebentar sampai sambal meresap di tempe.\", \"Angkat. Sajikan dengan bawang goreng.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1135, 4, 'Tumis Tempe Cabe Ijo', 'Resep praktis Tumis Tempe Cabe Ijo yang bisa dicoba di rumah.', '[\"3 papan kecil tempe\", \"5 buah cabe ijo besar\", \"1 buah tomat\", \"1 bungkus penyedap\", \"Secukupnya kecap manis\", \"Bumbu ulek :\", \"2 siung bawang merah\", \"2 siung bawang putih\", \"2 buah kemiri\", \"3 buah cabe merah kriting\", \"Sedikit garam\"]', '[\"Potong dadu tempe, lalu goreng sebentar.\", \"Cuci cabe ijo lalu iris tipis.\", \"Ulek semua bumbu hingga halus.\", \"Panaskan sedikit minyak, tumiskan bumbu halus. Masukan cabe ijo dan tomat. Tambah satu setengah gelas air matang. Masukan penyedap dan kecap. Test rasa.\", \"Masukan tempe, tumis hingga bumbu meresap.\", \"Angkat dan sajikan😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1136, 3, 'Tumis labu buncis sosis campur tempe super pedas', 'Cara membuat Tumis labu buncis sosis campur tempe super pedas yang enak dan praktis untuk keluarga.', '[\"1 buah labu siam\", \"8 biji buncis\", \"1 bungkus Sosis\", \"1/2 tempe\", \"Bumbunya\", \"7 biji cabe merah besar\", \"15 biji cabe setan\", \"1 siung bawang putih\", \"2 siung bawang merah\", \"1 buah bawang bombay\", \"2 lembar Daun salam\", \"secukupnya Garam\", \"Penyedap (ro*k*) skip aja ya\"]', '[\"Siapin bahan2 nya.. labu nya sudah saya iris,sebenarnya nya cabe nya masih bnyak\", \"Iris/potong2 bahan sayuran n tempe serta sosisnya.. jgn lupa ya.. cuci dlu..\", \"Ini cabe bawang merah bawang putih nya di blender aja,cape sis klo hrus ngulek,oh iya.. bawang bombay nya di iris ya.. tumis hingga bau nya sedap alias sudah wangi\", \"Pertma si tuang tempe sama sosis nya dlu,tumis bersama cabe tadi,lalu masukkan bahan2 sayuran lainnya,masak hingga matang,tutup tumisan hingga empuk,jgn terlalu empuk ya.. biar keliatan seger,jgn lp masukan garam,penyedap rasa\", \"Angkat lalu sajikan,di jamin enak buibu\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1137, 3, 'Tempe Ijo', 'Tempe Ijo - olahan tempe khas Indonesia yang nikmat.', '[\"2 papan tempe (dipotong agak tipis)\", \"10 siung bawang putih (diiris tipis)\", \"10 bh cabe hijau besar (diiris serong)\", \"secukupnya Garam\", \"secukupnya air\", \"secukupnya gula putih\", \"royco (jika suka)\"]', '[\"Siapkan semua bahan\", \"Goreng tempe yang sudah dipotong setengah matang sisihkan.\", \"Siapkan wajan berisi minyak kelapa panaskan dan masukan bawang putih masak sampai harum dan agak layu\", \"Masukan cabe hijau, garam dan gula tumis hingga layu\", \"Masukan sedikit air (jangan kebanyakan...) tumis hingga matang, icip rasa tambahkan royco jika perlu. angkat dan sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1138, 3, 'Kering tempe sederhana', 'Kering tempe sederhana - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"Tempe\", \"5 siung Bawang putih\", \"8 Bawang merah\", \"3 Cabe merah besar\", \"3 cm Laos\", \"3 lembar Daun salam\", \"secukupnya Gula merah\", \"secukupnya Asam jawa\", \"secukupnya Kecap\", \"Garam\"]', '[\"Iris tempe kemudian goreng.\", \"Iris bawang putih, bawang merah, cabe merah, kemudian tumis bawang putih dan bawang merah setelah harum masukkan cabe, laos, daun salam gula merah, asam jawa, kecap, garam dan tambahkan sedikit air.\", \"Koreksi rasa kemudian masukkan tempe yang sudah digoreng lalu aduk2 sampai bumbu meresap lalu matikan api.\", \"Kering tempe sudah siap untuk disajikan...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1139, 2, 'Oseng Oseng Tempe Gembus', 'Resep praktis Oseng Oseng Tempe Gembus yang bisa dicoba di rumah.', '[\"1 kotak tempe gembus\", \"1/3 kotak tempe kedelai\", \"1 ikat sawi hijau\", \"1 plastik jamur tiram\", \"bumbu-bumbu:\", \"2 buah cabe keriting merah\", \"4 buah cabe rawit\", \"4 siung bawang merah\", \"2 siung bawang putih\", \"bahan pelengkap:\", \"secukupnya gula\", \"secukupnya garam\", \"saos tiram\", \"kecap\", \"air\"]', '[\"Cuci bersih semua bahan. potong dadu tempe dan sawi hijau\", \"Goreng tempe kedelai dan tempe gembus sampai matang\", \"Potong bumbu bumbu (cabe dan bawang) dan tumis sampai harum. masukkan jamur tiram dan sawi hijau, tambahkan sedikit air. masak sampai lunak\", \"Masukkan tempe yang sudah digoreng, garam, gula, saus tiram dan kecap. koreksi rasa.\", \"Selamat menikmati ❤️\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1140, 4, 'Tumis kacang panjang + tempe simple 😋', 'Resep Tumis kacang panjang + tempe simple 😋 yang lezat dan mudah dibuat di rumah.', '[\"250 gram kacang panjang (boleh lebih)\", \"1 papan tempe potong2 dan goreng setengah matang\", \"2 siung bawang merah iris halus\", \"2 siung bawang putih geprek cincang kasar\", \"2 buah cabai merah iris serong\", \"1 buah cabai rawit (optional)\", \"1 lembar daun salam\", \"1 sdm kecap manis (boleh jg pakai saus tiram)\", \"secukupnya Garam\", \"secukupnya Lada bubuk\", \"secukupnya Penyedap\"]', '[\"Cuci kacang panjang lalu iris serong, sisihkan.\", \"Tumis duo bawang + cabai + daun salam dgn minyak hingga harum lalu masukan kacang panjang aduk rata hingga kacang setengah matang.\", \"Kemudian masukan tempe yg telah digoreng setengah matang.\", \"Masukan garam, lada, penyedap & kecap manis. Aduk rata, test rasa.\", \"Sajikan... simple kan.. selamat mencoba..😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1141, 3, 'Pecel Sayur & Tempe Mendoan', 'Sajian tempe lezat: Pecel Sayur & Tempe Mendoan penuh protein nabati.', '[\"1 ikat kangkung\", \"Toge\", \"Kol\", \"Kacang panjang\", \"Timun\", \"Bumbu pecel instan\", \"6 buah cabe rawit merah\", \"secukupnya Air panas\", \"Pelengkap :\", \"Bawang goreng\", \"Tempe mendoan\"]', '[\"Rebus semua sayuran, tp jgn terlalu matang\", \"Ulek bumbu pecel dgn cabe rawit, larutkan dgn air panas\", \"Tata sayuran yg sudah direbus kedalam piring.. Siram dgn bumbu pecel\", \"Taburi bawang goreng & tambahkan tempe mendoan\", \"Simple.. Tapi raos😄 selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1142, 2, 'Sup sayur pentol sosis,sambal kecap dan ayam tahu tempe ungkep', 'Resep Sup sayur pentol sosis,sambal kecap dan ayam tahu tempe ungkep yang lezat dan mudah dibuat di rumah.', '[\"2 bungkus sayuran sup (kulbis,wortel,kentang,buncis,preseledri)\", \"1/2 bongkol bunga kol\", \"3 sosis ayam\", \"20 pentol ayam kecil\", \"Bumbu halus sup:\", \"5 siung bawang merah\", \"4 siung bawang putih\", \"secukupnya Merica\", \"Garam\", \"Penyedap rasa\", \"Kecap,cabai,jeruk nipis untuk sambal\", \"Bumbu ungkep:\", \"5 siung bawang putih\", \"secukupnya Ketumbar\", \"secukupnya Laos,kunyit\", \"Daun sereh\", \"Daun jeruk\"]', '[\"Cuci bersih semua sayuran kemudian potong2 lalu masukkan kedalam panci yg sudah diisi air\", \"Sambil menunggu mendidih uleg bumbu halus kemudian masukkan potongan sosis dan pentol ke dalam panci\", \"Tumis bumbu dan preseledri pada wajan lalu masukkan ke dalam panci\", \"Aduk2 beri garam dan penyedap rasa tunggu dan koreksi rasa\", \"Setelah sup matang ungkep ayam tempe dan tahu uleg semua bumbu ungkep kemudian balurkan pada ayam tempe dan tahu\", \"Masukkan ke dalam wajan beri air secukupnya lalu tunggu hingga air meresap\", \"Jika air sudah meresap ayam tempe telur siap untuk digoreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1143, 4, 'Ayam dan tempe sambel mentah', 'Resep praktis Ayam dan tempe sambel mentah yang bisa dicoba di rumah.', '[\"bumbu ungkep ayam dan tempe:\", \"3 siung bawang putih\", \"1 ruas kunyit\", \"garam\", \"kaldu bubuk\", \"merica bubuk\", \"sambal:\", \"2 buah tomat merah\", \"3 buah cabai rawit\", \"1/2 sdt terasi\", \"secukupnya garam\", \"secukupnya kaldu bubuk\", \"2 sdm minyak panas\", \"jeruk limau\"]', '[\"Haluskan bawang putih dan kunyit. masukkan ke 300ml air. beri garam dan kaldu bubuk. masukkan ayam. ungkep sampai air menyusut, sisakan air untuk mengungkep tempe.\", \"Goreng ayam dan tempe samia kecoklatan\", \"Sambal:\", \"Ulek garam, gula terasi, kaldu jamur dan cabai sampai halus. terakhir masukkan tomat uleg lagi sampai halus.\", \"Terakhir beri 2 sdm minyak panas dan perasan jeruk limau.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1144, 3, 'Tempe Tahu Kecap Cabe Ijo', 'Buat Tempe Tahu Kecap Cabe Ijo yang nikmat dengan langkah-langkah mudah ini.', '[\"250 gr Tempe Potong sesuai selera\", \"4 buah Tahu Putih Besar Potong sesuai selera\", \"4 buah Cabe Ijo iris panjang\", \"8 buah Bawang putih iris tipis (seneng dibanyakkin baputnya)\", \"secukupnya Garam\", \"secukupnya Gula pasir\", \"secukupnya Ladaku merica bubuk\", \"secukupnya Ketumbar bubuk\", \"2 buah Kemiri dihaluskan\", \"Kecap manis (saya pakai ban*o) secukupnya sesuai selera\", \"2 sdm minyak goreng (jangan banyak2, ga sehat)\"]', '[\"Tumis bawang putih sampai harum kemudian masukkan bumbu2 dan cabe ijo, tumis hingga cabe agak layu\", \"Masukkan potongan tempe, aduk hingga bumbu merata dan matang kecokelatan\", \"Masukkan potongan tahu, aduk hingga bumbu tercampur rata\", \"Masukkan kecap manis secukupnya, aduk hingga merata\", \"Icip icip kalo dirasa udah pas sesuai selera langsung sajikan 😆\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1145, 4, 'Tahu tempe isi mercon', 'Resep Tahu tempe isi mercon yang lezat dan mudah dibuat di rumah.', '[\"1 papan tempe\", \"4 buah tahu putih belah jadi 2\", \"Tepung bumbu serbaguna merk apa aja\", \"Air matang\", \"Isian :\", \"15 cabe rawit setan (bisa ditambah atau dikurangi)\", \"2 siung bawang putih\", \"2 siung bawang merah\", \"secukupnya Garam\", \"Minyak goreng\"]', '[\"Goreng tahu setengah matang. Angkat dan tiriskan.\", \"Potong tempe kurleb 4cm belah tengahnya jangan sampai putus. Lakukan hal yg sama dengan tahu nya.\", \"Panaskan minyak goreng. Lalu goreng bawang merah bawang putih cabe setelah itu di uleg tambahkan garam.\", \"Masukkan ulegan cabe tadi kedalam tahu dan tempe sesuai selera.\", \"Buat adonan tepung bumbu dicampurkan air jangan terlalu encer.\", \"Panaskan minyak goreng. Celupkan tahu dan tempe yg sudah diberi isian tadi dlm adonan tepung. Lalu goreng dengan minyak panas. Setelah kecoklatan angkat dan tiriskan.\", \"Tahu tempe isi mercon siap disajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1146, 4, 'Sate Tempe Madu (Sampedu)', 'Resep Sate Tempe Madu (Sampedu) yang lezat dan mudah dibuat di rumah.', '[\"2 buah tempe potong dadu (kalau saya ukuran kecil tempe nya)\", \"Cabe merah (sesuai selera)\", \"4 siung bawang merah (diulek)\", \"4 siung bawang putih (diulek)\", \"1 ruas Laos (geprek)\", \"Sejumput lada (saya pakai lada bubuk)\", \"Sejumput ketumbar (saya pakai ketumbar bubuk)\", \"3 lembar daun salam\", \"3 lembar daun jeruk\", \"Secukupnya madu\", \"Garam\", \"Gula merah\", \"Kecap\", \"Margarin (untuk olesan)\", \"secukupnya Air\", \"Minyak sedikit untuk menumis\", \"4 buah kemiri\"]', '[\"Semua bumbu ditumis sampai harum\", \"Masukkan sedikit air\", \"Masukkan potongan tempe kedalam bumbu tumisan\", \"Cek rasa\", \"Biarkan hingga airnya menyusut dan bumbu meresap\", \"Setelah dingin susun pada tusuk sate\", \"Bakar menggunakan margarin biar lezat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1147, 3, 'Tumis Kangkung Tempe Bosok', 'Sajian Tumis Kangkung Tempe Bosok yang praktis dan lezat untuk dinikmati bersama.', '[\"2 ikat kangkung\", \"1/4 tempe bosok/semangit potong dadu\", \"5 cabe rawit\", \"5 cabe merah keriting\", \"3 siung bawang putih\", \"5 siung bawang merah\", \"1 bungkus saori saus tiram\", \"1/2 sdt garam\", \"Minyak untuk menumis\"]', '[\"Tumis bawang putih & merah sampai harum kemudian masukkan cabai\", \"Masukkan tempe bosok/semangit beri sedikit air sampai tempe nya terendam (untuk mematangkan tempe)\", \"Masukkan kangkung yg telah di cuci bersih & di potong\", \"Masukkan saus tiram 1 bungkus sambil aduk\", \"Beri 1/2 sdt garam, cek rasa, hidangkan panas2\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1148, 3, 'Bola bola tempe isi telur', 'Resep Bola bola tempe isi telur yang lezat dan mudah dibuat di rumah.', '[\"1 buah tempe\", \"1 buah telur\", \"secukupnya Penyedap rasa\", \"Telur puyuh (rebus)\", \"Keju\", \"Tepung roti\", \"Susu cair\"]', '[\"Terlebih dahulu kukus tempe setelah itu tumbuk tempe sampai halus\", \"Tambahkan telur plus penyedap rasa\", \"Ambil adonan sedikit pipih kan lalu masukan telur puyuh rebus, balut kmbali dengan adonan tempe...terlebih dahulu masukan ke dlm kulkas\", \"Terus ambil kembali adonan tempe yg sudh berbentuk bulat bulat\", \"Siapkan telur kocok plus susu cair aduk\\\"kemudian celupkan adonan tersebut lalu guling\\\" kan ke tepung roti.... Siap d goreng\", \"Selamat mencoba..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1149, 2, 'Tumis tempe pakcoy', 'Resep Tumis tempe pakcoy ala rumahan yang dijamin menggugah selera.', '[\"1 bonggol pakcoy\", \"1/2 bawang bombay\", \"3 siung bawang putih\", \"2 buah cabai merah\", \"1 buah cabai hijau\", \"1/2 potong tempe\", \"2 sdm saus tiram\", \"1/2 sdm tepung maizena\", \"2 batang daun kucai\", \"secukupnya gula dan garam\"]', '[\"Potong tempe tipis. lalu goreng hingga kering\", \"Iris cabai merah, cabai hijau, bawang bombai, pakcoy, dan daun kucai.\", \"Geprek bawang putih lalu cincang.\", \"Tumis bawang putij, bombai, cabai merah hijau hingga harum. kemudian tambahkan air 1 gelas.\", \"Masukkan pakcoy. setelah pakcoy empuk. masukkan tempe.\", \"Tambahkan saus tiram, garam dan gula\", \"Koreksi rasa.\", \"Siap dinikmati\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1150, 4, 'Tempe Mendoan Stick', 'Resep Tempe Mendoan Stick ala rumahan yang dijamin menggugah selera.', '[\"1 tepak tempe\", \"1 butir telur\", \"secukupnya Minyak\", \"Bumbu ungkep :\", \"2 siung bawang putih\", \"1 siung bawang merah\", \"1/2 sdt ketumbar\", \"secukupnya Garam\", \"Penyedap\", \"potong Daun bawang potong kecil\"]', '[\"Haluskan tempe yg sudah di ungkep dengan bumbu sampai halus masukkan daun bawang aduk rata.kocok lepas telur\", \"Panaskan minyak celupkan tempe kedalam kocokan telur lalu goreng sampai kecoklatan angkat sajikan...jika suka pedas tambahkan cabe kriting saat menghaluskan tempe\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1151, 4, 'Balado tempe teri jengki', 'Resep praktis Balado tempe teri jengki yang bisa dicoba di rumah.', '[\"1 papan tempe, potong korek api, goreng kering\", \"1 genggam teri jengki, rendam air panas, cuci bersih, tiriskan,\", \"goreng kering\", \"Bumbu halus :\", \"6 buah cabe merah keriting\", \"3 buah cabe rawit setan\", \"1 butir kemiri\", \"4 siung bawang merah\", \"2 siung bawang putih\", \"1 lembar daun salam\", \"1 lembar daun jeruk, buang tulang daunnya\", \"1 ruas jari kelingking lengkuas, geprek\", \"secukupnya Air\", \"sesuai selera Garam, gula dan penyedap rasa ayam\"]', '[\"Tumis bumbu halus hingga harum, masukkan daun salam, daun jeruk dan lengkuas aduk terus sampai daun terlihat layu dab bumbu matang.\", \"Beri air secukupnya biarkan sampai mendidih lalu bumbui garam, gula dan penyedap rasa, tes rasa.\", \"Jika sudah pas baru tempe dimasukkan aduk rata biarkan air menyusut dan bumbu menyerap sempurna ketempe baru masukkan ikan teri aduk rata, jika terlihat teri sudah menempel sempurna dgn bumbu matikan kompor, angkat.\", \"Pindah kemangkuk saji, siap disajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1152, 3, 'Tempe goreng tepung sejuta umat', 'Sajian tempe lezat: Tempe goreng tepung sejuta umat penuh protein nabati.', '[\"1/2 papan tempe\", \"1 gelas air\", \"1 sendok ketumbar\", \"6 bawang putih\", \"Segelas tepung terigu\"]', '[\"Tumbuk bumbu atau blender dengan air\", \"Campur bumbu dengan air dan terigu serta garam dan lada\", \"Masukan tempe yg telah diiris tipis ke adonan\", \"Goreng tempe dengan minyak agak banyak dan panas\", \"Goreng tempe sampai kuning kecoklatan dan tiriskan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1153, 2, 'Orek tempe saus tiram', 'Resep praktis Orek tempe saus tiram yang bisa dicoba di rumah.', '[\"1 papan tempe (potong dadu)\", \"3 buah cabe merah keriting (potong serong)\", \"5 buah rawit hijau (potong serong)\", \"5 siung bawang merah (giling kasar)\", \"2 siung bawang putih (giling kasar)\", \"1 sendok kecap manis\", \"2 1/2 sendok saus tiram\", \"secukupnya Air\", \"1 lembar daun salam\", \"Garam\"]', '[\"Tumis bawang merah dan bawang putih hingga agak layu\", \"Masukkan cabe dan daun salam, tumis sampai harum\", \"Masukkan tempe (sebelumnya tempe digoreng setengah matang terlebih dahulu) dan air, kemudian aduk\", \"Masukkan kecap, saus tiram, garam. Tunggu smpai air meresap\", \"Koreksi rasa dan siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1154, 3, 'Orek Tempe Tahu', 'Buat Orek Tempe Tahu yang nikmat dengan langkah-langkah mudah ini.', '[\"1 bungkus tempe (potong memanjang, goreng)\", \"6 buah tahu (potong memanjang, goreng)\", \"5 siung bawang putih (iris)\", \"1 ruas jahe (geprek)\", \"1 biji cabe merah besar (iris serong)\", \"1 batang daun bawang (iris serong)\", \"3 batang daun seledri (iris)\", \"1 sdm saus tiram\", \"1 sdm kecap inggris\", \"1 sdm kecap manis\", \"1 sdt merica\", \"(saya tidak menambahkan garam krn saus tiramnya sudah asin)\"]', '[\"Panaskan minyak goreng, tumis bawang putih, jahe, cabe merah\", \"Tambahkan saus tiram, kecap inggris, kecap manis, merica\", \"Masukkan tempe dan tahu yang sudah digoreng\", \"Masukkan daun bawang dan daun seledri\", \"Koreksi rasa kemudian sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1155, 4, 'Sayur Tahu & Tempe', 'Cara membuat Sayur Tahu & Tempe yang enak dan praktis untuk keluarga.', '[\"2 tahu putih (potong dadu)\", \"1/3 papan tempe (potong)\", \"1/2-1 tomat\", \"1 daun salam\", \"1 ruas lengkuas\", \"1/2 santan kara\", \"Secukupnya garam\", \"Secukupnya gula jawa\", \"Secukupnya gula pasir\", \"Secukupnya penyedap (optional)\", \"Secukupnya kaldu bubuk (optional)\", \"Secukupnya air\", \"Bumbu iris:\", \"2 bawang putih\", \"3 bawang merah\", \"1 cabe merah\", \"1 cabe rawit\"]', '[\"Goreng tahu dan tempe. Sisihkan.\", \"Tumis bumbu iris dengan daun salam dan lengkuas. Tumis sampai harum\", \"Masukkan air sampai mendidih, masukkan tahu & tempe, gula jawa, gula pasir, garam, penyedap, kaldu bubuk. Cek rasa.\", \"Masukkan santan, tomat. Cicipi sekali lagi.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1156, 3, 'Sambal teri tempe petai 😂', 'Resep Sambal teri tempe petai 😂 yang lezat dan mudah dibuat di rumah.', '[\"10 buah Cabe keriting\", \"10 buah Cabe rawit\", \"1 buah Tomat\", \"3 siung Bawang merah\", \"3 siung Bawang putih\", \"200 gr Teri\", \"Tempe (cuman buat tambahan, kalo gasuka tempe cukup teri)\", \"Petai 2 keris (sesuai selera)\", \"Gula merah\", \"Garam\"]', '[\"Cuci teri\", \"Potong dadu tempe\", \"Goreng tempe dan teri hingga kecoklatan\", \"Haluskan semua bumbu\", \"Panaskan minyak untuk menumis bumbu\", \"Lalu masukan bumbu halus dan petai aduk2 hingga aromannya berubah lalu beri sedikiy air\", \"Masukan tempe dan teri yg sudah matang tadi\", \"Aduk2 sampai matang sembari tes rasa🙏\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1157, 3, 'Stkpe(sambel tempe kentang pete ebi....)', 'Resep praktis Stkpe(sambel tempe kentang pete ebi....) yang bisa dicoba di rumah.', '[\"Tempe\", \"Kentang\", \"Pete\", \"Ebi\", \"Semua bahan sesuai porsi masing masing ya.\", \"Bumbu halus\", \"Cabe merah(aku tambah pake rawit merah...)\", \"5 siung Bawang merah\", \"3 siung Bawang putih\", \"1 buah Tomat\", \"Minyak sayur\", \"Garam\", \"Penyedap\"]', '[\"Potong tempe kentang sesuai selera... lalu goreng dan sisih kan\", \"Tumis bumbu halus hingga harum tambah kan ebi yg sudah di bersihkan... tambah garam dan penyedap sesuai rasa. aduk hingga sambel bener bener matang.\", \"Masukkan tempe kentang dan pete.. aduk rata..\", \"Siap di sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1158, 4, 'Tempe Melet', 'Resep praktis Tempe Melet yang bisa dicoba di rumah.', '[\"1 papan tempe\", \"Bahan sambel\", \"40 biji cabe rawit\", \"3 siung bawang putih\", \"2 siung bawang merah\", \"1 sdt garam\", \"Adonan tepung\", \"1 siung bawang putih\", \"Sedikit kunyit\", \"Secukupnya tepung\", \"Secukupnya air\", \"Garam\", \"Lada\"]', '[\"Potong potong tempe kemudian celupkan ke air garam\", \"Haluskan bahan bahan sambelnya kemudian masukan ke tempe\", \"Membuat adonan tepung haluskan bawang dan sedikit kunyit kasih garam dan lada bubuk sedikit masukan ke tepung kemudian tambahkan air\", \"Celupkan tempe ke adonan\", \"Kemudian goreng pakai api kecil supaya tempenya matang sampai dalam\", \"Angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1159, 3, 'Tumis kacang panjang kekyan tahu tempe', 'Sajian tempe lezat: Tumis kacang panjang kekyan tahu tempe penuh protein nabati.', '[\"1 ikat kacang panjang\", \"2 buah tahu uk.5x5cm\", \"1 buah tempe uk.10x3cm\", \"1 buah kekyan panjang\", \"6 buah bakso sapi\", \"bumbu*\", \"4 siung bawang putih\", \"4 siung bawang merah\", \"1 buah bawang bombay kecil\", \"1 ruas lengkuas\", \"4 buah tomat uk.sedang\", \"2 lembar daun salam\", \"2 sdm saori saus tiram\", \"5 sdm kecap manis\", \"10 buah cabe rawit merah\", \"Minyak utk menumis\", \"2 gelas belimbing air matang\", \"secukupnya Garam, lada\"]', '[\"Potong semua bahan. Kacang potong sekitar 3cm. Bahan lain potong dadu. Cincang bawang bawangan.\", \"Panaskan minyak utk menumis\", \"Masukkan bawang putih, bawang merah tumis sampai harum, lalu masukkan bawang bombay, cabe rawit (utuh), tomat, lengkuas, daun salam. Aduk rata.\", \"Masukkan kekyan. Aduk rata hingga kekyan berubah kenyal\", \"Masukkan tahu, tempe, bakso Aduk pelan agar tahu tidak hancur.\", \"Masukkan kacang panjang, saori, kecap manis. Aduk rata.\", \"Setelah rata tambahkan air matang. Kemudian tunggu hingga mendidih\", \"Setelah mendidih tambahkan garam&lada sesuai selera, aduk rata. Matikan api. Siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1160, 4, 'Tempe penyet sambal bawang', 'Tempe penyet sambal bawang - olahan tempe khas Indonesia yang nikmat.', '[\"Tempe kedelai (sesuai selera)\", \"2 siung bawang putih\", \"Cabe rawit (sesuai selera)\", \"sejumput Terasi\", \"Gula putih (sesuai selera)\", \"1 buah Cabai merah/ cabai besar\"]', '[\"Goreng tempe yang sudah di bumbui seperti biasa.\", \"Sembari menunggu tempe matang, kita buat sambalnya. Siapkan peralatan cobek dkk masukkan bumbu2 yg lain kemudia uleg\", \"Jika tempe sudah matang, angkat dan tidak perlu ditiriskan. Langsung taruh di cobek penyet dengan sambal yg sudah dihaluskan tadi (minyak ikut ya sedikit).\", \"Tadaaaa, selamat mencoba yaaa buk ibuk 😋😋😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1161, 3, 'Tempe mendoan ala aq 😁', 'Tempe mendoan ala aq 😁 - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"2 bks tempe khusus mendoan(isi 6lmbr)\", \"1 bks tepung mendoan\", \"4 sdm tepung terigu\", \"secukupnya Garam, roico, penyedap\", \"Daun bawang\", \"secukupnya Air\", \"piring Daun pisang utk pelapis\"]', '[\"Campurkan tepung mendoan dn terigu, tmbhkn grm, roico dn penyedap seckpnya. Aduk, tambhkn air sedikt dm sdkt\", \"Setelah tercmpur rata, masukn irisan daun bawang. Lalu goreng tempe, setelah matang lapisi piring saji dgn daun pisang\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1162, 4, 'Tempe mercon/tempe jontor/tempe melet kekinian', 'Sajian tempe lezat: Tempe mercon/tempe jontor/tempe melet kekinian penuh protein nabati.', '[\"1 Papan tempe (Potong tebal dan iris dibagian tengah)\", \"Isian sambal terasi (lihat resep sambel terasi)\", \"Adonan tepung :\", \"5 Sdm Tepung terigu\", \"1 Sdm Tepung maizena\", \"1 Sdt Ketumbar\", \"2 cm Kunyit (Sy gk pake)\", \"2 cm Kencur\", \"Sejumput Gula & garam\", \"Secukupnya kaldu bubuk (Sy gk pake)\", \"Secukupnya Daun bawang (Sy gk pake)\", \"Secukupnya air\"]', '[\"Isi tempe dengan sambal satu per satu. (Untuk isian sesuai selera, karna pak su gk begitu suka pedas jadi saya bikin isiannya gk terlalu banyak).\", \"Campur adonan tepung hingga rata (adonan jgn terlalu encer/kental ya).\", \"Celupkan tempe kedalam adonan tepung satu per satu.\", \"Siapkan wajan dengan api kecil dan minyak sayur. Goreng hingga berubah warna.\", \"Siap disajikan dan dinikmati.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1163, 2, 'Tempe orek kacang panjang', 'Sajian Tempe orek kacang panjang yang praktis dan lezat untuk dinikmati bersama.', '[\"1 papan tempe, potomg-potong kecil\", \"2 bawang putih\", \"4 bawang merah\", \"2 buah cabe keriting merah\", \"3 keping kemiri\", \"1 sdm lada bubuk\", \"secukupnya Kecap manis\", \"10 kacang panjang\"]', '[\"Goreng tempe sampai kering\", \"Potong-potong kacang panjanh, cuci bersih\", \"Ulek duo bawang, kemiri, cabe sampai halus.\", \"Tumis bumbu halus sampai wangi, masukan kacang panjang. Beri air jangan terlalu banyak. Biarkan sampai kacamh panjang layu dan matang.\", \"Masukan tempe, kecap, lada Bubuk. Aduk terua sampai kecap terbagi rata. Koreksi rasa. Sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1164, 4, 'Kering Ubi Tempe Pedass', 'Buat Kering Ubi Tempe Pedass yang nikmat dengan langkah-langkah mudah ini.', '[\"4 bh Ubi jalar (kupas, cuci, potong korek tipis2)\", \"1 papan kecil Tempe (potong korek)\", \"° Bumbu iris :\", \"8 siung Bawang merah\", \"5 siung Bawang putih\", \"15 bj Cabai rawit\", \"2 bj Cabai hijau gendot\", \"° Bumbu uleg :\", \"8 bj Cabai merah keriting\", \"1 sdm Gula aren (sesuai slera)\", \"° Bumbu lain :\", \"Lengkuas geprek, daun salam\", \"Kecap manis\", \"Gula\", \"Garam\", \"Kaldu bubuk\", \"bila perlu Gula aren\"]', '[\"Ubi dan tempe yg udah dipotong2, goreng hingga agak kering. Sisihkan\", \"Tumis bumbu uleg hingga harum, trus masukkin bumbu iris. Tumis hingga harum dan matang. Kasih sdikit air. Beri lengkuas geprek dan daun salam.\", \"Bumbui gula, garam, kaldu bubuk. Masukkan ubi dan tempe goreng. Aduk rata, beri sesuai selera kecap. Aduk rata lagi, koreksi rasa.\", \"Masak hingga bumbu meresap. Sajikaaan\", \"Enak bgt buat lauk sama nasi anget, makannya pake tangan. Hihihi. Nagihhh\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1165, 3, 'Oseng tempe leunca', 'Sajian tempe lezat: Oseng tempe leunca penuh protein nabati.', '[\"200 gram leunca\", \"1/2 papan tempe ukuran sedang\", \"2 buah cabe merah keriting\", \"6 buah cabe rawit merah\", \"1 ruas kencur\", \"4 siung bawang putih\", \"6 siung bawang merah\", \"secukupnya kecap\", \"secukupnya garam\", \"secukupnya minyak\", \"penyedap rasa ayam (optional)\"]', '[\"Ulek kasar cabe keriting, bawang merah, bawang putih, cabe rawit merah, kencur\", \"Panaskan minyak, masukkan bumbu yg sudah diulek kasar, sambil menunggu bumbu yg sedang ditumis, ulek tempe (jangan terlalu hancur). setelah bumbu wangi masukkan tempe, aduk sebentar lalu masukkan leunca\", \"Tambahkan air secukupnya, garam, penyedap rasa, kecap, dan tumis sampai air menyusut dan bumbu telah meresap.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1166, 4, '14. Tempe Jeletot', 'Sajian 14. Tempe Jeletot yang praktis dan lezat untuk dinikmati bersama.', '[\"1 papan tempe\", \"2 siung bawang merah, iris tipis\", \"2 siung bawang putih, haluskan\", \"7 buah cabe merah keriting, ulek kasar\", \"7 buah cabe rawit merah, ulek kasar\", \"1/2 sdt kaldu bubuk\", \"secukupnya Garam\", \"1 batang daun bawang, iris tipis\", \"Tepung bumbu serbaguna secukupnya (saya pakai kobe) + air\", \"secukupnya Minyak goreng\"]', '[\"Haluskan bawang putih, cabe merah dan cabe rawit. Tambahkan garam, aduk rata\", \"Tumis irisan bawang merah dengan sedikit minyak hingga layu.\", \"Siram tumisan bawang merah + minyak ke atas bumbu yang sudah dihaluskan, tambahkan kaldu bubuk, aduk rata.\", \"Potong-potong tempe dengan ketebalan sesuai selera (saya potong kira-kira 2 cm). Belah dua potongan tempe, jangan sampai putus.\", \"Isi tempe dengan cabe bawang yang sudah dicampur. Celupkan ke dalam tepung serbaguna yang sudah dicampur daun bawang dan air.\", \"Goreng tempe dengan api sedang hingga kuning kecokelatan.\", \"Angkat dan tiriskan minyaknya. Tempe jeletot siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1167, 2, 'Tempe isi', 'Sajian Tempe isi yang praktis dan lezat untuk dinikmati bersama.', '[\"1 buah tempe\", \"5 siung bawang merah\", \"5 siung bawang putih\", \"8 buah cabe rawit\", \"3 batang daun bawang\", \"secukupnya Tepung bakwan\", \"secukupnya Garam dan gula pasir\", \"Minyak untuk menggoreng\"]', '[\"Potong tempe, tipis. Sisihkan\", \"Ulek kasar : bawang putih, bawang merah, cabe rawit. beri gula dan garam secukup nya. Siapkan wadah masukan tepung terigu bakwan beri air dan irisan daun bawang\", \"Ambil tempe beri bahan yg sudah di ulek, tutup dengan tempe (seperti bikin roti)\", \"Kemudian masuk kan ke dalam adonan tepung bakwan.\", \"Goreng adonan, masak hingga matang\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1168, 2, 'Nugget Tempe Mozarella', 'Nugget Tempe Mozarella - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 papan tempe\", \"70 gram tepung bumbu siap saji\", \"secukupnya Tepung panir\", \"secukupnya Air\", \"Secukupnya keju mozarella\"]', '[\"Siapkan bahan-bahan\", \"Haluskan tempe kemudian tambahkan sedikit air dan tepung bumbu sampai adonan lengket dan bisa dibentuk. Buat yang suka asin boleh ditambahkan garam.\", \"Bentuk tempe sesuai selera, selipkan keju mozarella di tengah adonannya. Kalau saya tempenya saya bentuk pipih agar saat digoreng matang sempurna.\", \"Masukan adonan tempe ke tepung bumbu yang sudah diberi air, kemudian gulingkan ke tepung panir sampai adonan tertutup sempurna.\", \"Nugget tempe mozarella siap digoreng. Goreng dengan api kecil agar tidak cepat gosong.\", \"Nugget tempe siap dihidangkan.\", \"Kalau adonan mau ditambahkan sayuran seperti wortel atau buncis juga bisa. Kalau adonan mau dikukus dulu sebelum digoreng juga bisa banget, disesuaikan saja dengen selera masing masing 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1169, 4, 'Tempe goreng tepung bumbu', 'Tempe goreng tepung bumbu - olahan tempe khas Indonesia yang nikmat.', '[\"1 papan tempe (saya 2 rb)\", \"1 bungkus tepung bumbu\", \"Secukupnya air\", \"Secukupnya minyak goreng\"]', '[\"Iris tempe dengan ketebalan sesuai selera (saya tipis spt mendoan) sisihkan\", \"Campur tepung bumbu dengan air, hingga tekstur nya tidak terlalu kental dan tidak terlalu encer\", \"Panaskan minyak goreng\", \"Celupkan tempe pada adonan tepung, goreng dengan minyak banyak dan api sedang\", \"Setelah kecoklatan, angkat dan siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1170, 4, 'Tempe maknyuus', 'Sajian tempe lezat: Tempe maknyuus penuh protein nabati.', '[\"1 bh tempe\", \"Adonan :\", \"5 sdm Tepung terigu\", \"secukupnya Gula\", \"secukupnya Garam\", \"1 cm kunir di haluskan\", \"secukupnya Lada\", \"Bawang pre iris tipis\", \"1 btr Telur ayam\", \"secukupnya Air\"]', '[\"Iris tempe.. jangan terlalu tebal\", \"Masukkan smua bahan2 adonan hingga menjadi satu. Adonaan jangan terlalu encer\", \"Setelah itu celupkan tempe satu persatu. Lalu goreng.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1171, 4, 'Tumis Pare Tempe Pedas', 'Nikmati kelezatan Tumis Pare Tempe Pedas dengan resep sederhana ini.', '[\"1 buah pare\", \"1/2 papan tempe\", \"10 buah cabe rawit\", \"1 buah tomat\", \"5 siung bawang merah\", \"4 siung bawang putih\", \"2 buah cabe merah\", \"1 butir telur\", \"secukupnya Gula\", \"secukupnya Garam\", \"secukupnya Merica\", \"secukupnya Minyak\", \"secukupnya Air\"]', '[\"Belah pare jadi 2 bagian. Lalu buang bagian dalamnya hingga bersih. Potong tipis-tipis. Lumuri garam (agak banyak, tanpa air). Remas-remas hingga berbusa. Bilas dengan air sampe bersih (busanya hilang). Ulangi lagi tersebut sekali lagi agar pare tidak pahit.\", \"Potong tempe kecil-kecil. Lalu goreng matang. Sisihkan.\", \"Tumis rajangan kasar bawang merah dan bawang putih. Lalu masukkan rajangan kasar tomat, cabe merah, dan cabe rawit. Tumis hingga wangi.\", \"Masukkan telor lalu kocok-kocok agar tercampur rata.\", \"Masukkan pare. Masak hingga layu dan berubah warna. Lalu masukkan tempe yang sudah digoreng tadi.\", \"Tes rasa. Tambahkan gula, garam, dan merica secukupnya.\", \"Siap dihidangkan.\", \"Semoga bermanfaat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1172, 2, 'Pokcoy siram tempe saus tiram', 'Sajian tempe lezat: Pokcoy siram tempe saus tiram penuh protein nabati.', '[\"5-6 batang pokcoy ukuran kecil\", \"3 siung bawang putih cincang\", \"5 buah tempe iris dadu\", \"4 sdm saus tiram\", \"2 sdm kecap manis\", \"1 sdt merica bubuk\", \"secukupnya garam dan gula\"]', '[\"Re us pokcoy dalam air yang telah mendidih selama 4 menit (tergantung besar pokcoy nya) kl kuntum kecil 2 menit cukup kemudian tiriskan\", \"Tumis bawang putih sampai harum, masukkan tempe oseng2 sebentar lalu masukkan saus tiram, merica, kecap manis, garam dan gula aduk merata, kemudian tambahkan air secukupnya\", \"Letakan pokcoy yang telah direbus tadi di atas piring kemudian siram dengan tempe saus tiram. pokcoy siram saos tiram siap di sajikan...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1173, 4, 'Tempe apa yaa namanya😅', 'Cara membuat Tempe apa yaa namanya😅 yang enak dan praktis untuk keluarga.', '[\"1 papan tempe\", \"3 buah cabe hijau iris\", \"2 siung sedang bawang merah iris\", \"Secukupnya kecap\", \"Bumbu halus :\", \"1 butir kemiri\", \"Secukupnya ketumbar bubuk\", \"2 siung bawang merah\", \"3 siung bawang putih\", \"3 buah cabe merah keriting\", \"3 buah cabe merah keriting\", \"1/2 buah tomat\", \"Secukupnya gula merah\", \"Secukupnya garam\", \"Secukupnya Ro*co\", \"sedikit Air\"]', '[\"Goreng matang tempe tapi jangan sampe kering\", \"Goreng bawang merah iris sampe harum\", \"Masukkan bumbu halus sampai matang dan masukkan sedikit air setelah air mendidih masukkan cabe hijau iris dan kecap.\", \"Bumbui garam,gula,ro*co tes rasa sampai pas kemudian masukkan tempe masak sampai matang.\", \"Selamat mencoba☺😊\", \"😘\", \"😘\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(1174, 3, 'Oseng basah tempe daun', 'Resep praktis Oseng basah tempe daun yang bisa dicoba di rumah.', '[\"10 biji Tempe daun\", \"Kacang panjang sckupx\", \"3 siung bawang merah\", \"2 siung bawang putih\", \"5 biji cabe rawit\", \"Gula,garam,penyedap,sckupx\"]', '[\"Iris2 tempe daun..ulek duo bawang merah dan cabe smpai lembut\", \"Iris tipis kacang panjang,cuci,sisihkan\", \"Tumis bumbu uleg dg 5 sdk mkn minyak goreng..mykx agk byk krn skalian matengkan tempex ya\", \"Stlah bumbu wangi,masukan tempe barengan dg kacang panjang..aduk rata..\", \"Jika minyak susut trserap oleh tempe,tuang sdkit air agr tmpex agk basah..sdkit saja y klo kbykan jd kuah ntar😂\", \"Aduk trs smpai tempe wangi dan kacang layu,bri gula,gram,penyedap..icip rasa angkat..dg nasi anget pun udh mantap\", \"Anak2 lbh syukak tempe daun d oseng basah gini..klo tempe bgkus pkastik biasax d goreng dl jdx agk keras..aromax yg daun jg lbh wangi n syedafff😂\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1175, 3, 'Krenseng tahu tempe.', 'Resep praktis Krenseng tahu tempe. yang bisa dicoba di rumah.', '[\"Tahu\", \"Tempe\", \"1 batang Lengkuas\", \"secukupnya Santan\", \"Bawang Merah\", \"Bawang Putih\", \"Cabe merah besar\", \"Cabe kecil\"]', '[\"Potong kotak-kotak tahu tempe,dan potong kecil-kecil cabe merah besar,cabe kecil,bawang merah,bawang putih,lalu tumbuk agak halus dan tumis,lalu masukkan lengkuas,tunggu sampai harum.\", \"Kemudian masukkan potongan tahu tempe ke dalam wajan dan campur bersama bahan bahan yg sudah di tumis harum tadi,tunggu sampai bumbu meresap,lalu masukkan santan secukupnya sesuai porsi dan kasih kecap,saori/bumbu lain secukupnya.\", \"Tutup masakan dengan tutup panci,dan tunggu hingga bumbu meresap.\", \"Masakan siap dihidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1176, 3, 'Tongseng TTS (Tahu Tempe Sosis) + Cambah', 'Resep Tongseng TTS (Tahu Tempe Sosis) + Cambah ala rumahan yang dijamin menggugah selera.', '[\"1 buah tahu (seribuan), potong dadu\", \"1 potong tempe (seribuan), potong dadu\", \"Cambah (seribu\", \"2 potong sosis (iris serong)\", \"3 siung bawang merah\", \"2 siung bawah putih\", \"1 iris laos (seruas jempol, geprek)\", \"5 buah cabe (optional)\", \"1 buah lombok besar (iris serong)\", \"Secukupnya kecap, garam, lada bubuk, kaldu bubuk\", \"Secukupnya air\"]', '[\"Goreng tempe, tahu, sosis (jgn sampai terlalu kering)\", \"Tumis bawang merah, bawang putih, laos, cabe kecil, dan lombok besar sampai berbau harum. Masukkan cambah, tunggu sebentar langsung beri kecap (agar lebih meresap), aduk rata, setelah itu tuang air\", \"Masukkan tahu, tempe, dan sosis yg sudah digoreng tadi, beri garam, lada bubuk, kaldu bubuk.\", \"Koreksi rasa, udah.. 😁👌 selamat menikmati\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1177, 4, 'Kering Tempe simple Tanpa kecap', 'Buat Kering Tempe simple Tanpa kecap yang nikmat dengan langkah-langkah mudah ini.', '[\"3 papan Tempe\", \"1 ons kacang tanah (optional)\", \"1 ons bilis / Teri medan\", \"10 buah cabe rawit\", \"2 buah cabe merah\", \"2 siung bawang merah ukuran agak besar\", \"3 siung bawang putih\", \"secukupnya Garam & penyedap Rasa\", \"Minyak untuk menggoreng\"]', '[\"Potong Tempe ke ukuran kecil Dan memanjang lalu goreng\", \"Sambil menunggu semua Tempe siap digoreng, iris cabe, bawang putih Dan bawang merah\", \"Goreng kacang tanah Dan bilis\", \"Setelah semua bahan matang, tumis cabe, Dan duo bawang sampai mendekati kering, lalu masukkan tempe, kacang tanah Dan bilis, aduk rata lalu masukkan Garam, koreksi Rasa Dan matikan api selesaai\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1178, 4, 'Pecel ❤️ tempe mendoan', 'Resep Pecel ❤️ tempe mendoan ala rumahan yang dijamin menggugah selera.', '[\"1 ikat bayam\", \"1 ikat kacang panjang (banyaknya sesuain sendiri)\", \"sesuai keinginan Touge\", \"1 buah mentimun\", \"1/4 kacang tanah (bahan sambel pecel)\", \"Cabe merah besar + cabe rawit ( sesuai selera suka pedas apa Tdk\", \"2 lembar Daun jeruk\", \"3 siung Bawang putih\", \"1 buah Asem Jawa\", \"sedikit Jahe\", \"Bahan buat mendoan\", \"1 bungkus tempe\", \"2 helai daun bawang / loncang\", \"Bawang putih\", \"Tepung terigu\", \"Royko\"]', '[\"Kita bikin sambel pecelnya dulu, goreng kacangnya hingga berubah warna kemerahan jgn sampai gosong 😂 lalu di diamkan\", \"Setelah itu kacangnya kita tumbuk hingga halus kalau gamau repot ya diblender jg lebih oke, kalau udah halus kita taruh di mangkok\", \"Lalu gantian kita tumbuk bumbunya masukan bawang, cabe, daun jeruk, asem, garam, jahe, dan gula Jawa hingga halus setelah itu kita masukan kacang yg udah ditumbuk kedalam bumbunya tdi lalu kita tumbuk lgi hingga bumbu dan kacangnya menyatu. Kalau sudah menyatu siap deh kita tiriskan\", \"Rebus sayur2an kecuali mentikunnya kita potong2 kecil dadu.\", \"Next bikin mendoan potong tipis2 tempenya hingga menjadi beberapa bagian\", \"Potong2 lembut daun bawangnya\", \"Haluskan bawang sama garam lalu dikasih air dikit kita masukan tempenya yg udah dipotong sambil nunggu bumbunya meresap kita bikin adonan\", \"Tepung terigu sesuai banyaknya mendoan lalu masukan daun bawang yg udah dipotong dikasih royko dikit kasih air secukupnya selanjutnya masukan mendoan ke adonan siap digoreng 😅\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1179, 2, 'Nugget tempe sayur', 'Buat Nugget tempe sayur yang nikmat dengan langkah-langkah mudah ini.', '[\"1 papan tempe ukuran sedang\", \"2 buah wortel (parut)\", \"1 btng daun bawang\", \"1 butir telur (untk pelapis)\", \"6 sdm tepung terigu\", \"1 bks royco sapi\", \"5 siung bawang putih\", \"1/2 merica bubuk (ladaku)\", \"sedikit garam\", \"minyak utk menggoreng\", \"secukupnya tepung panir\"]', '[\"Potong tempe lalu kuku selama 10 mnt\", \"Sambil menunggu tempe nya d kukus persiapkan bumbunya ulek bawang putih sampai halus parut wortel dan iri daun bawang hingga halus\", \"Stlh tempe d kukus ulek tempe hingga halus lalu masukan bawang putih, parutan wortel, daun bawang, tempe dan royco cek rasa tmbh sdkit garam\", \"Ksh sdikit air jgn trlalu bnyk stlh adonan kalis bentuk bulat pipih lakukan hingga selesai\", \"Lalu kocok telur masukan tempe yg sudah d pipihkan td lalu masukan ke dlm tepung panir hingga menutupi tempenya siapkan minyak dan goreng dngn api kecil agar bgian dlm matang\", \"Sajikan selagi hangat blh d tmbhkn dengab saos ya mom..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1180, 3, 'Tempe balado jahe', 'Tempe balado jahe - olahan tempe khas Indonesia yang nikmat.', '[\"1 papan kecil tempe\", \"Minyak goreng\", \"5 buah cabai merah tanjung\", \"5 buah cabe kriting\", \"3 siung bawang merah\", \"3 siung bawang putih\", \"2 cm jahe\", \"3 lembar daun salam\", \"3 butir kemiri\", \"1/2 sdt garam\", \"Penyedap (sesuai selera)\", \"2 sdm gula\", \"250 ml air\"]', '[\"Potong tempe menjadi kotak-kotak\", \"Goreng setengah matang\", \"Ulek bawang merah, bawang, putih, cabai kriting, kemiri dan cabai merah tanjung\", \"Geprek jahe\", \"Tumis bumbu halus dan masukan jahe yang sudah digeprek sampai harum\", \"Masukan air. Tunggu hingga mendidih lalu masukan daun salam\", \"Masukan gula, garam, dan penyedap\", \"Masukan tempe dan aduk hingga tempe terlumuri bumbu\", \"Siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1181, 4, 'Orak Arik Tempe Pedas🔥', 'Resep Orak Arik Tempe Pedas🔥 yang lezat dan mudah dibuat di rumah.', '[\"1 buah tempe daun ukuran sedang\", \"5 buah cabai merah\", \"Segenggam cabai rawit\", \"3 siung bawang merah\", \"3 siung bawang putih\", \"1/4 bawang bombai\", \"Secukupnya garam & gula\", \"Secukupnya air\"]', '[\"Seperti biasa, persiapkan bahan-bahannya terlebih dahulu. Jangan lupa cuci bersih bahan irisan.\", \"Tumis bawang bombai terlebih dahulu hingga harum, lalu baru masukkan bahan irisan lainnya.\", \"Masukkan secukupnya air, sedikit saja yaa.\", \"Kemudian masukkan secukupnya garam & gula, baru setelah itu masukkan tempe. Aduk-aduk dan orak-arik semuanya hingga air mengering, jangan lupa koreksi rasa sebelum disajikan.\", \"Orak-arik tempe pedas siap santaaap😍🔥\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1182, 2, 'Tempe Goreng Isi Sambal', 'Nikmati kelezatan Tempe Goreng Isi Sambal dengan resep sederhana ini.', '[\"250 gr tempe\", \"🍅Bahan sambal:\", \"7 biji cabe rawit\", \"4 butir bawang merah\", \"1 siung bawang putih\", \"1 batang daun bawang (iris tipis2)\", \"🍄Bahan adonan tepung:\", \"3 sdm tepung terigu\", \"1 sdm tepung beras\", \"Secukupnya garam\", \"Secukupnya air\"]', '[\"Potong tempe agak tebal,punya saya jadi 9pcs belah bagian tengahnya jangan sampai terputus sisihkan...\", \"Tumis bahan sambal sampai matang,setelah matang angkat pindahkan ke cobek tambahkan garam kemudian haluskan & isikan kedalam tempe...\", \"Adonan tepung: campur kedua jenis tepung+garam tambahkan air secukupnya,adonan agak encer aja...\", \"Panaskan minyak goreng celupkan tempe kedalam adonan tepung lalu goreng sampai matang...\", \"Setelah matang angkat & sajikan...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1183, 3, 'Kol Udang tahu tempe', 'Buat Kol Udang tahu tempe yang nikmat dengan langkah-langkah mudah ini.', '[\"udang\", \"kubis putih / kol\", \"tahu\", \"tempe\", \"bumbu :\", \"4 siung bawang merah\", \"1 bawang putih\", \"2 cabe rawit\", \"1 cabe merah\", \"1 kemiri\", \"secukupnya gula, garam\", \"bumbu penyedap rasa Masako\"]', '[\"Kupas udang, iris tahu dan tempe kotak2, cuci lalu goreng terlebih dahulu, tiriskan\", \"Iris tipis2 kubis\", \"Haluskan bumbu2 diatas lalu tumis tambah kan sedikit air\", \"Masukkan semua bahan, tunggu smpai mendidih tambh kan sedikit penyedap rasa\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1184, 4, 'Penyetan TETATE (TEmpe TAhu TErong)', 'Resep Penyetan TETATE (TEmpe TAhu TErong) yang lezat dan mudah dibuat di rumah.', '[\"1 papan Tempe\", \"2 papan Tahu\", \"2 bh Terong\", \"Bumbu gorengan\", \"3 bh Bawang putih\", \"1 sdt Ketumbar\", \"1 sdt Garam\", \"secukupnya Air\", \"Bahan sambal\", \"6 bh Cabe keriting\", \"8 bh Cabe rawit\", \"7 bh Bawang merah\", \"2 bh Bawang putih\", \"1 sachet kecil  Terasi (mamasuka)\", \"1 bh  Tomat yg besar\", \"Seiris jeruk nipis\", \"secukupnya Garam\", \"secukupnya Gula pasir\", \"Minyak utk menggoreng\"]', '[\"Bumbu gorengan, haluskan bawang putih, garam, dan ketumbar lalu tambahkan air\", \"Iris tahu, tempe dan terong sesuai selera aja ya bunda, lalu celupkan ke bumbu gorengan dan goreng sampai matang. Utk terong gak aku masukin ke bumbu lgsg aq goreng aja. Tp sebelumbya dicuci dulu ya bunda.\", \"Sekarang kita bikin sambalnya. Iris2 bawang merah,bawang putih, cabe kriting, cabe rawit n tomat lalu goreng dengan 3sdm minyak goreng. Trasi jgn lupa digoreng sklian ya bunda.\", \"Jika dirasa sdh matang, haluskan tambahkan garam dan gula secukupnya. Dan terakhir masuk seiris jeruk nipis uleg sekalian disambalnya biar rasanya tambah mantap bunda.\", \"Siap deh dihidangkan dg nasi hangat dan kerupuk.\", \"Selamat mencoba ya bunda.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1185, 3, '🍔 Mini Burger Tempe Ayam ala Dapur Fitri 🍔', '🍔 Mini Burger Tempe Ayam ala Dapur Fitri 🍔 - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"10 roti Burger\", \"10 lembar Daun selada\", \"5 buah Tomat segar, potong\", \"1 buah Timun segar, potong\", \"10 sdm Saos sambal atau tomat\", \"10 sdm Mayonaise\", \"Bahan Burger tempe ayam :\", \"300 gram Daging ayam\", \"300 gram Tempe, cincang\", \"100 gram Tepung bumbu\", \"4 batang Seledri, iris\", \"2 batang Daun bawang, iris\", \"1 sdt Lada putih bubuk\", \"1 sdt Bawang putih bubuk\", \"1 sdt Chicken powder\", \"1/2 sdt Garam jika kurang rasa\"]', '[\"Cincang tempe dan giling daging ayam setelah itu mix bersama daun bawang, seledri serta bumbu-bumbu, aduk rata setelah itu tambahkan tepung bumbu, aduk kembali sampai tercampur rata.\", \"Ambil 40 gram adonan burger lalu padatkan dan bentuk bulat pipih, lakukan sampai adonan burger habis. Lalu panaskan sedikit minyak pada teflon kemudian goreng burgernya hingga matang sekitar 3 menit. Angkat sisihkan.\", \"Siapkan roti burger yang sudah di belah. Lalu mulai lah memberi isian pada burger sesuai urutannya yang di inginkan.\", \"Mino burger tempe ayam pun siap 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1186, 2, 'Sambel Tempe', 'Sajian tempe lezat: Sambel Tempe penuh protein nabati.', '[\"1 papan tempe\", \"3 siung Bawang putih\", \"Garam\", \"5 Cabe\", \"1 ruas kencur\"]', '[\"Potong² tempe lalu bumbui dgn bawang putih & garam yg dihaluskan\", \"Lalu goreng. Lebih enak jika menggunakan tempe yg setengah jadi (belum banyak raginya)\", \"Haluskan cabe, bawang putih, kencur, garam.\", \"Lalu penyet (uleg) tempe diatas sambel\", \"Sajikan dgn nasi hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1187, 4, 'Nasi sambel tempe kencur', 'Nasi sambel tempe kencur - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 piring nasi\", \"1/4 papan tempe potong kotak kecil2\", \"Bawang putih\", \"Cabe\", \"Kencur\", \"Garam\", \"Royco\", \"Sawi putih\", \"Kunyit iris tipis\"]', '[\"Goreng tempe smpe kering, uleg bawang putih, kencur dan cabe, beri garam royco, masukan tempe goreng uleg lagi, jangan terlalu lembut yaa.. Lalu. Campurkan dengan nasi, aduk rata.\", \"Goreng sawi putih dan kunyit dengan bumbu garam... Goreng smpe matang\", \"Sajikan bersama nasi sambel tempe kencur\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1188, 4, 'Oseng tempe cabe Hijau', 'Cara membuat Oseng tempe cabe Hijau yang enak dan praktis untuk keluarga.', '[\"1 papan tempe\", \"secukupnya Cabe kriting hijau\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"10 cabe rawit\", \"1 btr kemiri\", \"Garam (secukupnya)\", \"Gula (secukupnya)\", \"Penyedap (secukupnya)\", \"Minyak\", \"Kecap manis\"]', '[\"Iris tipis tempe (sesuai selera)\", \"Iris cabe besar ijo (sesuai selera)\", \"Siapkan wajan dan panaskan minyak\", \"Goreng tempe yg sudah diiris tipis dan tiriskan\", \"Haluskan semua bumbu\", \"Tumis bumbu yg sudah dihaluskan\", \"Masukan irisan cabe besar ijo, tunggu sampai layu\", \"Masukkan tempe yg sudah digoreng stengah matang\", \"Aduk terus sampai tercampur\", \"Masukkan sedikit kecap dan aduk sampai matang\", \"Oseng tempe cabe ijo pun siap disajikan 😀😀😊😊 selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1189, 4, 'Tempe tahu bacem gagal 😅', 'Resep praktis Tempe tahu bacem gagal 😅 yang bisa dicoba di rumah.', '[\"1 bungkus tahu kulit\", \"1 lembar tempe potong\", \"(bumbu halus)\", \"4 siung bawang merah\", \"5 siung bawang putih\", \"5 buah cabai merah besar\", \"1 ruas kunyit\", \"1 ruas jahe\", \"3 biji kemiri\", \"ketumbar\", \"(bahan pelengkap)\", \"santan kara\", \"ladaku\", \"1 sdt garam\", \"secukupnya gula merah\", \"2 sdm kecap\", \"1/2 bungkus royco sapi\", \"air\"]', '[\"Tumis bumbu halus di atas yang sudah di uleg dengan cobek\", \"Tambahan 1/2 gelas air, setelah agak mendidih masukan 1/2 sachet santan kara\", \"Masukan tempe dan tahunya\", \"Setelah mendidih tambahkan bahan pelengkap di atas..\", \"Tunggu sampai bumbu mengental dan koreksi rasa\", \"Siapkan wadah untuk penyajiannya\", \"Happy cooking bunda 😄\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1190, 2, 'Oseng tempe kacang panjang', 'Nikmati kelezatan Oseng tempe kacang panjang dengan resep sederhana ini.', '[\"1 papan Tempe potong memanjang\", \"Segenggam kacang iris serong\", \"3 bawang merah\", \"2 bawang putih\", \"1 bh cabe merah\", \"Saus tiram\", \"Garam\", \"Gula\", \"Penyedap\", \"Lada\"]', '[\"Goreng tempe terlebih dahulu, lalu tumis bawang merah dan bawang putih hingga harum masukkan kacang lalu tempe nya aduk2 sambil diberi saus tiram, garam gula lada penyedap secukupnya, terakhir masukkan cabe nya, oseng tempe kacang panjang pun siap dhidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1191, 4, 'Stik Tempe', 'Sajian Stik Tempe yang praktis dan lezat untuk dinikmati bersama.', '[\"1 papan tempe\", \"1 butir telur ayam\", \"1 siung bawang putih\", \"1 sdt ketumbar\", \"secukupnya Garam\", \"Tepung panir\"]', '[\"Potong tempe memanjang. Rendam dalam larutan bumbu (bawang putih, ketumbar, garam).\", \"Kocok telur dalam mangkok n beri 1 sdm air putih matang\", \"Masukkan irisan tempe ke kocokan telur lalu baluri tepung panir. Kemudian digoreng deh. Gampang kan?\", \"Siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1192, 4, 'Sate Tempe', 'Sate Tempe - olahan tempe khas Indonesia yang nikmat.', '[\"250 gr tempe potong dadu\", \"10 bh tusuk sate\", \"250 ml santan kental dari (1/2 btr kelapa)\", \"Minyak goreng untuk menumis\", \"Bumbu yg dihaluskan:\", \"6 bh cabe merah (jika suka pedas boleh ditambah)\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"1 cm kunyit\", \"1 sdt ketumbar sangrai\", \"1 sdm serai iris halus\", \"1 sdm lengkuas cincang\", \"jika suka penyedap\", \"1/2 sdt garam\"]', '[\"Tumis bumbu halus dengan minyak goreng sampai harum.\", \"Masukkan santan, didihkan.\", \"Masukkan tempe, masak sampai kuah mengental. Tes rasa, jika sudah pas matikan kompor. Dinginkan\", \"Tusuk 3-4 potong tempe, panggang sambil dioles sisa kuah, sampai agak kering.\", \"Angkat. Tata dipiring. Sajikan.\", \"Catatan: jika masih ada sisa kuah, dapat disiramkan setelah ditata di piring saji\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1193, 2, 'SATE Tempe', 'Resep SATE Tempe yang lezat dan mudah dibuat di rumah.', '[\"1 papan tempe ukuran kecil, potong2 dadu\", \"10 buah tusukan sate\", \"Bahan Marinasi =\", \"garam dan Bawang putih di haluskan, beri air\", \"Bahan Sambel =\", \"1 genggam kacang tanah digoreng\", \"5 buah cabe merah\", \"4 siung Bawang merah\", \"2 siung Bawang putih\", \"secukupnya Gula merah\", \"secukupnya Garam\", \"1 buah jeruk limau\"]', '[\"Rendam potongan tempe ke dalam bahan marinasi. Diamkan selama 15 menit\", \"Haluskan semua bahan untuk sambel sate, tumis dan masak sambel sate hingga mengental. Angkat\", \"Tusuk2 tempe dengan tusukan yg telah dipersiapkan.\", \"Olesi tempe yg telah ditusuk2 tadi dengan sambel kacang, kemudian bakar hingga matang.\", \"Beri perasan jeruk limau pada sisa sambel kacang, sate tempe siap dihidangkan beserta nasi hangat2\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1194, 4, 'Bola bola tempe isi telur puyuh', 'Resep praktis Bola bola tempe isi telur puyuh yang bisa dicoba di rumah.', '[\"2 blok tempe ukuran kecil\", \"Telur puyuh secukupnya buat isian (rebus)\", \"2 butir telur\", \"1 sdm kaldu bubuk\", \"1/2 sdt bawang putih bubuk\", \"50 ml susu full cream cair plain\", \"Secukupnya tepung roti\"]', '[\"Potong2 tempe, kukus kurleb 10 mnt, angkat dan uleg\", \"Tambahkan kaldu bubuk, bawang putih bubuk, telur 1 butir, parutan keju...aduk hingga tercampur rata\", \"Pipihkan adonan tadi di tangan kemudian masukan rebusan telur puyuh, bulatkan hingga telur puyuh tertutup sempurna, lakukan sampai adonan habis\", \"Setelah selesai..simpan bola2 tempe di kulkas kurleb 15-20mnt\", \"Sementara didinginkan, bikin adonan buat balutan bola2 tempenya...1 buah telur dikocok dgn susu fullcream cair plain\", \"Masukan bola2 telur ke dalam telur yg telah dicampur susu dan gulingkan ke dalam tepung roti\", \"Goreng bola2 tempe dgn api sedang hingga berubah warna kecoklatan...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1195, 3, 'Tempe Crispy Super Cepat dan Gampang!', 'Buat Tempe Crispy Super Cepat dan Gampang! yang nikmat dengan langkah-langkah mudah ini.', '[\"6 potong tempe\", \"2 potong tahu\", \"3 sendok makan tepung serbaguna (aku pake Sasa) untuk adonan basah\", \"5 sendok makan tepung serbaguna untuk adonan kering (lebih banyak juga boleh biar makin crispy)\"]', '[\"Buat dua adonan: Adonan Basah dan Kering. Untuk adonan basah, campurkan 3 sendok tepung serbaguna dan 6 sendok makan air dingin, aduk merata. Kemudian untuk adonan kering, letakkan 5 sdm/lebih tepung serbaguna ke dalam piring datar\", \"Ambil potongan tempe ke adonan basah, kemudian ke adonan kering, remas, tekan, ratakan kurleb 5-10 kali\", \"Goreng dengan minyak panas hingga kuning keemasan.\", \"Angkat dan hidangkan panas-panas. Kriuknya bikin nagih! 🙆🏻‍♀️\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1196, 3, 'Tempe manis', 'Nikmati kelezatan Tempe manis dengan resep sederhana ini.', '[\"1 papan tempe\", \"Kecap\", \"4 bawang merah\", \"2 bawang putih\", \"Garam\", \"Merica bubuk\"]', '[\"Potong tempe berbentuk dadu\", \"Goreng tempe hingga kering\", \"Tumis bawang merah dan bawamg putih\", \"Setelah harum masukkan tempe, air merica kecap dan garam\", \"Koreksi rasa\", \"Jika air sudah menyusut (jangan sampai habis) tempe manis siap di sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1197, 2, 'Bakwan Tempe', 'Bakwan Tempe - olahan tempe khas Indonesia yang nikmat.', '[\"potong dadu Tempe rebus,\", \"Secukupnya Taoge\", \"1 buah Wortel, potong dadu/korek\", \"5 buah Buncis, iris tebal\", \"1 bks Tepung Bakwan instan\", \"secukupnya Air\"]', '[\"Siapkan wadah, tuang tepung bakwan dan air hingga menjadi adonan kental. Masukkan taoge, wortel, buncis, potongan tempe. Goreng hingga matang, sajikan dengan sambel\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1198, 4, 'Tempe Orek Pedas Manis Saya Suka', 'Nikmati kelezatan Tempe Orek Pedas Manis Saya Suka dengan resep sederhana ini.', '[\"3 papan tempe (saya 1 papan)\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"1 ruas laos, keprek\", \"2 lembar daun salam\", \"4 lembar daun jeruk buang tulang tengah\", \"4 biji cabe besar\", \"4 biji cabe rawit\", \"1 1/2 sdm kecap manis\", \"2 sdm gula merah iris\", \"1/2 sdm kaldu bubuk (saya pakai kaldu jamur)\", \"1/2 sdt garam (selera)\", \"50 ml air\"]', '[\"Siapkan bahan2\", \"Potong tempe dadu 1 cm x 1 cm atau sesuai selera. Lalu goreng 1/2 matang. Sisihkan\", \"Tumis duo bawang yg sudah di iris dengan 3 sdm minyak goreng. Masukkan cabe rawit dan cabe besar, daun salam, daun jeruk dan laos. Aduk sampai wangi.\", \"Tambahkan kecap manis, garam, kaldu, aduk lalu masukkan air dan gula merah. Tunggu sampai meletup atau mendidih lalu masukkan tempe. Kecilkan api. Aduk2. Tes rasa. Biarkan sampai air sat.\", \"Rasanya sedaaaaap. Pedas manisnya pas. Mpuk dan legit.\", \"Selamat mencoba bu ibu.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1199, 3, 'Tempe Tahu Bacem', 'Sajian tempe lezat: Tempe Tahu Bacem penuh protein nabati.', '[\"15 potong tempe/tahu putih\", \"Air kelapa dari 1 buah kelapa\", \"2 butir kemiri\", \"1 sdt ketumbar bubuk\", \"1/2 sdt penyedap rasa\", \"1 sdt garam\", \"75 gr gula merah sisir\", \"5 buah bawang merah\", \"3 siung bawang putih\", \"2 lembar daun salam\"]', '[\"Haluskan semua bumbu (kecuali daun salam, remas sedikit)\", \"Tata didalam panci tahu/tempe\", \"Masukan air kelapa dan semua bumbu + daun salam\", \"Rebus selama 30 menit atau lebih sampai bumbu meresap\", \"Angkat dinginkan, lalu goreng kecoklatan (saya suka agak gosong2)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1200, 2, 'Oblok-oblok Tempe', 'Sajian tempe lezat: Oblok-oblok Tempe penuh protein nabati.', '[\"2 papan tempe, potong kotak\", \"1 papan petai, kupas belah @ menjadi 2\", \"10 buah cabe rawit, buang tangkainya dan biarkan utuh\", \"3 buah cabe merah keriting, iris serong\", \"4 butir bawang merah, iris tipis\", \"2 cm lengkuas, memarkan\", \"1 lembar daun salam\", \"1 bungkus kaldu instant\", \"250 ml santan\", \"secukupnya minyak goreng\", \"Bumbu yang dihaluskan:\", \"3 siung bawang putih\", \"2 butir kemiri\", \"secukupnya garam\"]', '[\"Tumis cabe merah keriting dan bawang merah hingga harum. Setelah itu masukkan bumbu yang sudah dihaluskan, tumis lagi hingga harum. Kemudian tuangkan santan, lengkuas, daun salam dan kaldu instant. Aduk rata.\", \"Masukkan tempe dan cabe rawit, aduk rata dan biarkan hingga bumbu meresap kedalam tempe. Terakhir masukkan petai, aduk rata dan biarkan hingga petai layu. Angkat.\", \"Tata diatas piring saji dan sajikan bersama dengan nasi hangat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1201, 2, 'Sambel goreng teri tempe', 'Sajian Sambel goreng teri tempe yang praktis dan lezat untuk dinikmati bersama.', '[\"1 buah tempe\", \"1 ons ikan teri\", \"3 siung bawang putih\", \"7 siung bawang merah\", \"1/4 laos\", \"10 cabe rawit\", \"3 cabe merah\", \"3 daun jeruk\", \"2 daun salam\", \"Gula merah\", \"Gula pasir\"]', '[\"Goreng tempe dan teri terlebih dahulu lalu tiriskan. Gorengnya beda2 ya bu ibu. Jangan campur antara tempe dan teri 😂😂\", \"Haluskan bahan2 : 5 bawang merah, 2 bawang putih, 10 cabe rawit, cabe merah.\", \"Geprek laos. Dan iris tipis 2 bawmwer, 1 bawang putih, dan 1 cabe merah\", \"Lalu tumis bahan yg sudah dihaluskan. Tunggu hampir matang lalu tambahkan laos dan bahan2 yg diiris tipis dan daun jeruk dan daun salam\", \"Tunggu hingga harum. Dan masukkan tempe dan ikan teri\", \"Lalu tambahkan garam, gula merah dan gula putih secukupnya\", \"Lalu koreksi rasa.\", \"Ohya bayi yg suka kecap bisa ditambahkan pakai kecap ya :)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1202, 3, 'Kripik tempe simple', 'Sajian tempe lezat: Kripik tempe simple penuh protein nabati.', '[\"1 tempe ukuran sedang (potong tipis-tipis)\", \"500 ml air\", \"1 bungkus kobe tepung tempe kriuk 210 gr\", \"5 gram kapur sirih\", \"secukupnya Minyak goreng\"]', '[\"Masukan tempe yang sudah di potong tipis-tipis kedalam air yang sudah di campur dengan kapur sirih,rendam 30 menit.Angkat, cuci dan tiriskan.\", \"Kemudian, balurkan tempe yang sudah di rendam dengan tepung kering kobe\", \"Panaskan minyak, masukan tempe yang sudah di baluri tepung\", \"Kalau sudah matang, tunggu sampai dingin. Kripik tempe disimpan di toples\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1203, 3, 'Sambel tempe simpel', 'Resep praktis Sambel tempe simpel yang bisa dicoba di rumah.', '[\"1 bungkus tempe potong bumbui masako lalu goreng sisihkan\", \"10 cabe\", \"4 bawang\", \"sedikit garam\", \"sedikit gula\", \"sedikit minyak\", \"penyedap\"]', '[\"Goreng tempe sampai kekuningan sisihkan\", \"Siapkan bahan sambal di ulek semua bahan\", \"Contoh seperti ini\", \"Ulek tambahin tempe ulek sampai lembut dan di cocol sama daun ketumbar atau ulek bersa.ma.an hemmm nyammi\", \"Tarrrra simpel enak nyammmi makan bisa nambah lagi sama lalapan atau kerupuk\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1204, 4, 'Kering Tempe Manis', 'Kering Tempe Manis - olahan tempe khas Indonesia yang nikmat.', '[\"1 lonjor tempe daun\", \"12 siung bawang merah, iris tipis\", \"6 siung bawang putih, geprek cincang halus\", \"3 buah gula jawa (yang setengah lingkaran)\", \"3 lembar daun salam\", \"3 lembar daun jeruk, buang tulangnya\", \"Secukupnya garam\"]', '[\"Potong tempe kecil2 seperti korek api.\", \"Goreng tempe sampai kering.\", \"Tumis bawang putih dan bawang merah dengan sisa minyak goreng tempe.\", \"Tambahkan daun jeruk dan daun salam. Tumis sampai wangi.\", \"Setelah wangi, masukkan gula jawa. Aduk aduk. Beri sedikit air.\", \"Setelah air habis, masukkan tempe yg sudah digoreng tadi.\", \"Tambahkan sejumput garam.\", \"Aduk rata sampai gula jawa terkaramel. Matikan kompor. Angkat.\", \"Kering tempe siap dihidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1205, 3, 'Nugget tempe sayur ayam', 'Sajian tempe lezat: Nugget tempe sayur ayam penuh protein nabati.', '[\"1 potong Tempe\", \"1/4 daging ayam cincang\", \"1/2 potong wortel\", \"2 biji daun bawang\", \"2 buah kacang panjang\", \"2 butir telur\", \"Tepung roti / tepung panir\", \"Garam\", \"Gula\", \"Lada\", \"Bawang merah\", \"Bawang putih\", \"1 lembar daun pisang untuk mengukus\"]', '[\"Potong dadu tempe lalu kukus\", \"Iris daun bawang, wortel dan kacang panjang sesuai selera\", \"Ulek bawang putih, bawang merah, garam, gula dan lada\", \"Penyetkan tempe dan campurkan dengan semua bahan lalu tambahkan telur dan aduk rata\", \"Kukus adonan dengan daun pisang hingga matang\", \"Potong2 sesuai selera lalu masukan ke dalam telur lalu masukan ke dalam tepung roti\", \"Setelah itu boleh di simpan di freezer bisa bertahan sampai 1-2minggu dan jika ingin di makan tinggal di goreng👌🏻\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1206, 2, '2T 1S, Tumis Tauge Tempe Sosis', 'Resep 2T 1S, Tumis Tauge Tempe Sosis ala rumahan yang dijamin menggugah selera.', '[\"3 bh sosis\", \"3 genggam tauge\", \"Tempe secukupnya potong dadu\", \"3 siung bawang putih\", \"5 siung bawang merah\", \"5 bh cabe rawit\", \"4 bh cabe merah keriting\", \"1 bungkus bumbu instan racik tumis\", \"1/2 sdt kecap\"]', '[\"Goreng tempe sampai berubah warna, angkat & tiriskan\", \"Tumis bumbu, bawang putih & merah sampai harum kemudian masukkan cabe\", \"Masukkan sosis, tempe & tauge yg telah di cuci bersih tumis hingga agak layu\", \"Masukkan 1 bungkus bumbu instan racik tumis, kemudian tambahkan kecap\", \"Cek rasa, boleh pakai air atau tidak (kalau saya tidak) jadi deh\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1207, 3, 'Bakso tempe', 'Bakso tempe - olahan tempe khas Indonesia yang nikmat.', '[\"2 papan tempe\", \"7 sdm terigu\", \"7 sdm tapioka\", \"Daun kucai\", \"secukupnya Garam\", \"2 siung bawang putih\", \"sedikit Merica\"]', '[\"Rebus tempe sampai empuk,tiriskan\", \"Ulek bawang putih,merica dan garam smpe halus lalu ulek kasar tempe campur dgn bumbu tadi,tiriskan\", \"Masukan terigu,tapioka aduk rata lalu masukan tempe yg di ulek bersama bumbu,daun kucai uleni smpe kalis/bs di bentuk jika bergerindil ksh air panas dikit\\\"..cek rasa\", \"Ambil sedikit adonan lalu bentuk bulat,lakukan smpe adonan habis\", \"Rebus air sampe mendidih lalu masukan adonan yg sudah di bulatkan,masak hingga adonan mengambang/matang...\", \"Bakso siap di makan dgn saos ato bisa goreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1208, 4, 'Tempe saus mentega with bakso', 'Buat Tempe saus mentega with bakso yang nikmat dengan langkah-langkah mudah ini.', '[\"1/2 papan tempe potong dadu\", \"10 butir bakso belah jadi dua\", \"1/2 bawang bombay\", \"3 bawang putih\", \"1 daun bawang\", \"1 sdt kecap manis\", \"1/2 tomat\", \"1 sdt saori saus mentega\", \"secukupnya Garam\", \"Sedikit merica\"]', '[\"Goreng tempe terlebih dahulu lalu angkat dan tiriskan\", \"Tumis bawang putih dan bawang bombay lalu masukan tomat dan daun bawang\", \"Masukan tempe dan bakso lalu tambahkan kecap, saus sambal, merica, garam, penyedap rasa, dan saori saus mentega\", \"Aduk rata sebentar dan tambahkan 1/2 gelas air atau sekitar 100 ml\", \"Tunggu sampai air menyerap lalu angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1209, 2, 'Tumis labu siam tempe', 'Resep praktis Tumis labu siam tempe yang bisa dicoba di rumah.', '[\"250 gram labu siam / 2 buah labu yg besar\", \"150 gram tempe / 1 papan tempe dibagi 2\", \"3 buah tomat (iris2)\", \"450 ml santan dari 1/4 butir kelapa\", \"2 cm lengkuas\", \"2 lembar daun salam\", \"1 sendok teh gula & garam\", \"Minyak goreng secukupnya untuk menumis\", \"Bumbu yang Dihaluskan\", \"3 siung bawang putih\", \"6 butir bawang merah\", \"1 1/2 sendok teh ebi\", \"3 buah cabai merah\"]', '[\"Pertama-tama buang getah labu siam yang telah anda siapkan. Dimana caranya yaitu potong labu siam. Lalu gosok-gosokan hingga getah labu siam keluar. Setelah itu, kupas labu siam dan potong Sesuai selera (kalau saya berantakan). Lalu cuci denganmenggunakan air bersih.\", \"Selanjutnya, potong kotak tempe yang telah anda siapkan. Lalu panaskan minyak secukupnya pada wajan. Apabila minyak telah panas, anda bisa langsung menggoreng tempe yang telah dipotong-potong tersebut hingga berkulit.\", \"Kemudian, potong-potong tomat dan memarakan lengkuas.4.Setelah itu, seduh ebi yang telah disiapkan. Lalu sangarai.\", \"Haluskan semua bumbu halus beserta ebi yang telah disangrai. Anda bisa menghaluskannya dengan cara ditumbuk atau diblender.\", \"Panaskan minyak goreng secukupnya. Apabila minyak telah panas, anda bisa langsung memasukan semua bumbu yang telah dihaluskan, lengkuas dan daun salam.Tumis bumbu-bumbu tersebut sampai tercium harum. Jika sudah seperti itu, anda bisa langsung menambahkan tomat. Aduk hingga tomat menjadi layu.\", \"Setelah itu, tambahkan labu siam yang telah anda potong, tempe yang telah digoreng beserta petai cina. Aduk semua bahan tersebut sampai merata.\", \"Selanjutnya, masukan santan beserta bumbu-bumbu seperti garam dan gula merah. Aduk merata hingga bumbu menjadi larut. Lalu masak kembali hingga semua bahan matangdan bumbu meresap dengan sempurna. Apabila telah dirasa matang anda bisa langsung menyajikannya pada piring saji yang telah disiapkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1210, 2, '4.Tempe kobe', 'Buat 4.Tempe kobe yang nikmat dengan langkah-langkah mudah ini.', '[\"1 papan tempe(iris tipis/sesuai selera)\", \"3 sdm tepung bumbu kobe\", \"Bumbu halus:\", \"1 siung bawang putih\", \"1/2 sdt garam\", \"secukupnya Minyak goreng\"]', '[\"Rendam tempe iris dalam bumbu halus ±5menit\", \"Masukkan ke tepung bumbu kering dan goreng dengan api kecil sampai menguning. Angkat tiriskan\", \"Hidangkan hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1211, 3, 'Tumis kacang panjang with tempe dan baso', 'Sajian tempe lezat: Tumis kacang panjang with tempe dan baso penuh protein nabati.', '[\"Kacang panjang\", \"Tempe\", \"Baso\", \"Bawang merah\", \"Bawang putih\", \"Cabe merah kriting\", \"Cabe rawit\", \"Saos tiram\", \"Garam, gula dan bumbu penyedap\"]', '[\"Tumis duo bawang dan cabe\", \"Masukan kacang panjang tambahkan air sedikit dan beri saos tiram\", \"Kemudian masukan tempe dan baso aduk rata\", \"Tambahkan gula dan garam juga bumbu penyedap, tes rasa\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1212, 4, 'Tumis Pare Tempe', 'Resep Tumis Pare Tempe yang lezat dan mudah dibuat di rumah.', '[\"4 bh pare\", \"1/2 papan tempe, iris bentuk korek api halus\", \"1 sdm garam halus\", \"Bumbu :\", \"Cabe sesuai selera, pedas lebih mantap bun\", \"5 siung bawang merah\", \"2 siung bawang putih\", \"2 lbr daun salam\", \"1 ruas lengkuas geprek\", \"Sedikit air\", \"secukupnya Minyak\", \"secukupnya Masako/royco\"]', '[\"Belah 2 pare buang bijinya. Lalu iris tipis dan remas2 pare dengan garam sampai lemas. Cuci bersih.\", \"Haluskan cabe, bawang merah & bawang putih.\", \"Panaskan minyak, tumis bumbu halus dan masukkan lengkuas dan daun salam. Masak sampai harum.\", \"Masukkan pare dgn secukupnya air, aduk rata.\", \"Setelah setengah matang masukkan tempe iris. Aduk rata hingga bumbu tercampur.\", \"Lalu masukkan penyedap rasa. Masak hingga matang sampai air menyusut. Dan jangan lupa utk tes rasa.\", \"Tumis Pare Tempe siap disajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1213, 4, 'Tumis Tempe Oyong \"Saos Tiram\"', 'Resep praktis Tumis Tempe Oyong \"Saos Tiram\" yang bisa dicoba di rumah.', '[\"2 buah oyong uk. Kecil\", \"1 papan tempe uk. Sedang\", \"Secukupnya saos tiram\", \"Secukupnya air\", \"Secukupnya garam. Gula. Merica bubuk dan kaldu bubuk\", \"Bumbu👇\", \"4 siung bawang merah. Iris\", \"3 biji cabe merah keriting. Iris\", \"1 buah tomat. Iris\", \"3 siung Bawang putih. Geprek. Cincang\"]', '[\"Kupas oyong. Cuci bersih. Kemudian Potong2\", \"Potong2 tempe. Goreng setengah matang. Angkat. Sisihkan\", \"Tumis bumbu2 sampai harum. Masukkan tempe. Aduk2. Masukkan oyong. Aduk2. Kemudian masukkan secukupnya air. Tambahkan saos tiram. Garam. Gula. Merica bubuk dan kaldu bubuk. Masak sampai matang. Jangan lupa tes rasa ya... 😊\", \"Sajikan...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1214, 2, 'Botok tempe cumi', 'Buat Botok tempe cumi yang nikmat dengan langkah-langkah mudah ini.', '[\"3 ekor Cumi  besar (adanya dikulkas itu)\", \"1/2 papan Tempe\", \"1 kotak Tahu\", \"secukupnya Kelapa parut  disesuikan dengan jumlah anggota kelurga\", \"3 ekor Ikan asin\", \"Petai cina alias lamtoro\", \"Tomat\", \"Air\", \"Bahan bumbu halus\", \"sesuai selera Cabe\", \"Bawang merah\", \"Bawang putih\", \"Kunyit\", \"Kencur\", \"Daun jeruk\", \"Ketumbar\", \"Garam\", \"Penyedap rasa\"]', '[\"Persiapkan bahan\", \"Iris cabe hijau tomat dan isian botok\", \"Haluskan bumbu\", \"Tumis bumbu hingga harum\", \"Kemudian masukkan isian tumis sampai harum dan setengah masak\", \"Masukkan kelapa aduk rata sampai benar benar masak sempurna\", \"Jangan lupa tmbahkan air ya biar bumbu meresap sempurna\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1215, 4, 'Gulai Telur Tempe Ala2 (Tnp Santan)', 'Sajian Gulai Telur Tempe Ala2 (Tnp Santan) yang praktis dan lezat untuk dinikmati bersama.', '[\"1 buah Tempe\", \"2 butir Telur\", \"Cabe Rawit Secukupnya (diiris bulat2)\", \"Daun Bawang Secukupnya (dirajang)\", \"Bumbu Gulai (sisa beli dipasar)\", \"Secukupnya Garam Halus\", \"secukupnya Penyedap Rasa (klw saya pakai Royco)\", \"Gula (sedikit, seujung sendok)\", \"Secukupnya Air\", \"Minyak Makan utk menumis\"]', '[\"Terlebih dahulu rebus 2 butir telur bulat sampai matang, kemudian sisihkan\", \"Panaskan minyak makan kemudian masukkan dan tumis bumbu Gulai\", \"Masukkan cabe rawit yg sudah diiris, tumis bersamaan bumbu gulai\", \"Tambahkan air secukupnya (sesuai selera) lalu tunggu sampai mendidih\", \"Masukkan tempe yang sudah dirajang + telur (sudah dikupas)\", \"Tambahkan Garam Halus, Penyedap Rasa (sy pakai royco) dan gula, disusul daun bawang\", \"Tunggu sampai mendidih sempurna, Angkat, Siap Disajikan (karena saya suka pedas jadi rawitnya agak banyak, dan gulanya sedikit, semua tergantung selera)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1216, 3, 'Orek Tempe', 'Resep Orek Tempe yang lezat dan mudah dibuat di rumah.', '[\"1/2 papan tempe, potong2\", \"2 siung bawang putih, iris2\", \"2 siung bawang merah, iris2\", \"2 cabe merah besar, iris serong\", \"3 sdm kecap manis\", \"2 sdm gula pasir\", \"secukupnya Garam\", \"2 lembar daun salam\", \"2 ruas jari lengkuas geprek\", \"3 sdm air\"]', '[\"Goreng tempe sampai setengah matang, sisihkan.\", \"Tumis duo bawang dan cabai smp harum.\", \"Masukkan tempe, daun salam dan lengkuas, oseng2 sebentar.\", \"Masukkan air, kecap, gula pasir dan garam.\", \"Tes rasa dan orek tempe siap disantap.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1217, 2, 'Oreg tempe kering', 'Sajian tempe lezat: Oreg tempe kering penuh protein nabati.', '[\"1 papan tempe\", \"3 biji cabai merah keriting\", \"7 biji cabai rawit(Kalo suka pedes)\", \"8 butir bawang merah\", \"5 butir bawang putih\", \"2 lembar daun salam\", \"3 lembar daun jeruk\", \"1 ruas lengkuas geprek\", \"1 gula merah\", \"3 sdm kecap manis\", \"1/2 bungkus asam jawa\", \"secukupnya Gula pasir\", \"secukupnya Garam\", \"secukupnya Lada\", \"50 ml Air\"]', '[\"Potong tempe dengan ukuran korek api,goreng hingga kecoklatan.sisihkan\", \"Iris bawang merah,putih,cabai tumis hingga matang tambahkan daun salam,jeruk,lengkuas aduk sampai harum.\", \"Tambahkan air,gula merah,kecap,garam, gula pasir,dan lada aduk sampai mengental,tes rasa\", \"Terakhir masukkan tempe aduk hingga rata.tempe oreg siap d sajikan 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1218, 2, 'Mendol tempe', 'Resep praktis Mendol tempe yang bisa dicoba di rumah.', '[\"1/2 papan tempe\", \"Secuil kelapa\", \"2-3 sdm terigu\", \"Bumbu halus\", \"2 bh cabe\", \"1 bh cabe keriting\", \"2 siung bawang merah\", \"2 siung bawang putih\", \"Secuil tempe bosok\", \"Secukupnya Garam\", \"Secukupnya Gula\"]', '[\"Siapkan bahan2nya\", \"Parut kelapa.haluskan tempe.uleg bumbu halus\", \"Campurkan kelapa parut tempe halus dan bumbu halus aduk rata.masukan terigu aduk rata\", \"Cetak sesuai selera\", \"Panaskan minyak dan goreng hingga kuning keemasan.angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1219, 4, 'Tumis cumis tempe cabai hijau', 'Cara membuat Tumis cumis tempe cabai hijau yang enak dan praktis untuk keluarga.', '[\"1/2 cumi asin\", \"1 buah tempe\", \"Bumbu yg d\'haluskan:\", \"Cabai hijau besar/kriting\", \"Bawang merah\", \"Bawang putih\"]', '[\"Cuci terdahalu cumi hingga bersih...lalu rebus sbntr kira\\\" 5mnt.\", \"Potong tempe sesuai selera lalu goreng stngah mtang.\", \"Rebus bumbu terlebih dahulu sblm dhaluskn...cabai,bawang merah,dan bawang putih sbntr.\", \"Lalu ulak bumbu...setelah itu tumis bumbu hingga harum...msukan cumi dan tempe ksih penyedap rasa secekup\'a...angkt dan hidangkn.\", \"Slmt mncoba ibu\\\"\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1220, 2, 'Perkedel Tempe #kisahkasihcookpad', 'Perkedel Tempe #kisahkasihcookpad - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"300 gram tempe\", \"1 butir telur kocok lepas\", \"1 batang daun bawang, iris2\", \"1 sdt seledri iris halus\", \"Secukupnya gula, garam dan lada bubuk\", \"Bumbu halus (goreng/tumis dulu baru di haluskan):\", \"3 siung bawang putih\", \"4 siung bawang merah\"]', '[\"Kukus tempe 20-25 menit.\", \"Lalu haluskan selagi panas.\", \"Goreng bawang putih dan merah lalu haluskan.\", \"Masukan semua bahan lalu aduk rata.\", \"Bentuk sesuai selera. Saya pakai centong sayur.\", \"Saya jadi 11 buah. Lumayan banyak buat berdua😉\", \"Goreng dalam minyak yg sudah panas hingga matang. Jangan balik sebelum kering nanti hancur. Balik sekali saja ya biar perkedel tempenya kering dan tidak berminyak. Angkat lalu tiriskan.\", \"Sajikan. Enak sekaliiiii😍😍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1221, 3, 'Tempe sambel 🍛', 'Cara membuat Tempe sambel 🍛 yang enak dan praktis untuk keluarga.', '[\"2 bungkus tempe\", \"5 siung bawang putih\", \"3 siung bawang merah\", \"15 cabe rawit atau sesuai selera\", \"secukupnya Garam\", \"Penyedap rasa (bila perlu)\", \"2 sdm Kecap manis\"]', '[\"Potong dadu tempe tersebut,kemudian goreng hingga kering\", \"Haluskan semua bahan (jangan sampai terlalu halus),lumatkan tempe tersebut pada sambal yg dibuat hingga berbentuk potongan kecil\", \"Kemudian goreng sampai kering\", \"Tambahkan kecap manis selesai sikap dihidangkan 😋😋\", \"Selamat mencoba 🙇\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(1222, 4, 'Tempe dan kentang balado tanpa tomat', 'Buat Tempe dan kentang balado tanpa tomat yang nikmat dengan langkah-langkah mudah ini.', '[\"1/2 papan tempe\", \"1 bh kentang\", \"5 bh cabai merah keriting\", \"4 bh cabai rawit jawa\", \"3 siung bawang putih\", \"4 siung bawang merah\", \"1 bh cabai hijau\", \"Sedikit terasi\", \"secukupnya Garam\", \"secukupnya Gula\", \"Penyedap rasa\"]', '[\"Iris tempe tipis2 dan kentang tipis2. Dan goreng hingga sedikit garing\", \"Haluskan cabai, bawang merah, putih, terasi. Dan beri garam dan gula secukupnya\", \"Panaskan penggorengan dan beri sedikit minyak untuk menumis bumbu. Masukkan bahan yang telah dihaluskan. Tumis hingga harum masukkan cabai hijau yang telah diiris\", \"Beri penyedap rasa sesuai selera. Dan masukkan tempe dan kentang yang telah digoreng. Aduk hingga rata\", \"Jika sudah tercampur rata tambahkan sedikit air dan minyak agar tidak kering\", \"Tes rasa. Dan sajikan :)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1223, 4, 'Kering Tempe Kentang', 'Resep praktis Kering Tempe Kentang yang bisa dicoba di rumah.', '[\"4 balok tempe iris tipis-tipis\", \"2 buah kentang ukuran besar iris tipis-tipis\", \"1 ruas jempol lengkuas geprek\", \"5 lbr daun jeruk\", \"2 buah asam matang\", \"1 buah/batok gula merah serut kasar\", \"100 ml air\", \"secukupnya Garam\", \"Bumbu halus :\", \"20 siung bawang merah\", \"9 siung bawang putih\", \"1 ons lombok merah\", \"15 buah cabe rawit (selera)\"]', '[\"Goreng terlebih dahulu tempe dan kentang secara bertahap dan terpisah. Goreng sampai coklat kekuningan lalu tiriskan. Distep ini perlu banyak minyak sampai tempe kentang tenggelam dan saat menggoreng gunakan api besar.\", \"Haluskan bahan bumbu, kalau saya pakai blender. Saat mau blender bahan bumbu, beri minyak kurleb 50 ml agar cepat halus. Mau diulek monggo tidak apa2 😉\", \"Siapkan wajan tidak perlu minyak, karna td saat blender bumbu sudah pakai minyak. (Kalau bahan bumbu tadi diulek, saat menumis HARUS pakai minyak yess) Tumis bumbu tsb, daun jeruk dan laos sampai harum.\", \"Masukan tempe dan kentang yang sdh digoreng tadi aduk rata agar tercampur bumbunya. Distep ini saat menumis, usahakan pakai api sedang agar tidak gosong tempe dan kentangnya.\", \"Lalu masukan air, gula merah, asam dan garam. Aduk rata terus sampai gula dan asamnya mencair dan bumbu meresap lengket di tempa kentangnya.\", \"Cicipi rasa kalau sudah pas, masak beberapakali adukan sampai tanek lalu sajikan\", \"Pakai nasi kuning atau nasi uduk lebih enak pastinya 😁\", \"Kalau buat banyak bisa disimpan ditempat kedap udara 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1224, 3, 'Bakso Goreng Tempe', 'Resep praktis Bakso Goreng Tempe yang bisa dicoba di rumah.', '[\"1/2 papan tempe\", \"150 gr ayam yg sdh dihaluskan\", \"3 sdm munjung tepung tapioka/kanji\", \"3 siung bawang putih,haluskan\", \"1/4 sdt lada bubuk\", \"1 butir telur\", \"secukupnya kaldu,garam,gula\", \"1 liter air putih (buat rebusan)\", \"minyak untuk menggoreng\", \"Taburan :\", \"secukupnya daun bawang  iris2 tipis\"]', '[\"Tumbuk/haluskan tempe,lalu campurkan dengan ayam yg sdh dihaluskan, tepung tapioka, 1 butir telur,bawang putih,lada bubuk,garam,kaldu,gula aduk rata. koreksi rasa,kemudian bentuk bulat2, adonan lakukan hingga habis.\", \"Rebus air hingga mendidih,beri 1 sdm minyak sayur agar adonan bakso tidak lengket.kemudian masukkan adonan bakso tempe,biarkan hingga mengapung,angkat dan tiriskan.\", \"Panaskan minyak,goreng bakso tempe hingga matang kecoklatan.\", \"Bakso goreng tempe siap dinikmati dg cocolan saos.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1225, 3, 'Tempe meled', 'Resep praktis Tempe meled yang bisa dicoba di rumah.', '[\"1 papan tempe\", \"Bahan sambel\", \"Cabe rawit (option) aku cuma pake 7 cabe rawit cabe merah 1\", \"5 siung bawang merah\", \"2 siung bawang putih\", \"1 buah tomat\", \"Garam dan penyedap secukup nya\", \"bahan tepung\", \"2 siung bawang merah\", \"1 siung bawang putih\", \"secukupnya Ketumbar\", \"Kunyit\", \"3 sdm terigu\", \"2 sdm tepung beras\", \"secukupnya Air\", \"Garam dan penyedap\", \"1/2 sachet merica bubuk\"]', '[\"Potong tempe sesuai selera belah tengah nya untuk isian sambel\", \"Uleg semua bahan sambel mulai dari cabe bawang dan tomat tumis hingga harum\", \"Isi sambal ke tempe yang sudah di belah tengahnya (jangan sampai putus)\", \"Campurkan terigu tepung beras merica bubuk garam dan penyedap tambahkan air secukupnya dan campurkan dengan bawang merah,bawang putih kunyit, ketumbar yang sudah di haluskan aduk rata\", \"Panaskan minyak. Goreng sampai kecoklatan.. Tiriskan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1226, 3, 'Oseng ati tempe', 'Resep praktis Oseng ati tempe yang bisa dicoba di rumah.', '[\"200 gr hati sapi,rebus potong kotak\", \"1 papan tempe\", \"3 bawang merah\", \"2 bawang putih\", \"3 cabai hijau potong2\", \"1 sdm saos tiram\", \"4 sdm kecap manis\", \"1 sdt kecap asin\", \"1 sdt kecap inggris\"]', '[\"Tumis bawang merah bawang putih yang diiris tipis sampai kering,lalu masukkan cabai hijau\", \"Tambahkan ati sapi dan tempe. Masukkan saos saos dan beri setengah gelas air.\", \"Tambahkan kecap dan masak sampai rasanya pas. Buat yang suka asin bisa ditambahkan takaran kecap asinnya atau garam. Saya mengurangi konsumsi garam untuk mencegah hipertensi selama kehamilan. Tetap sehat ya semuanya\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1227, 4, 'Bacem Tahu&Tempe Tanpa Kecap (a.k.a Bacem ndeso)', 'Sajian tempe lezat: Bacem Tahu&Tempe Tanpa Kecap (a.k.a Bacem ndeso) penuh protein nabati.', '[\"5 tahu kulit\", \"1/2 papan tempe\", \"1 ruas lengkuas\", \"1 daun salam\", \"Secukupnya garam\", \"Secukupnya penyedap (optional)\", \"Secukupnya gula pasir\", \"Secukupnya air\", \"Bumbu halus;\", \"2 bawang putih\", \"4 bawang merah\", \"2 kemiri\", \"1 sdt ketumbar\", \"1 bulatan gula jawa\"]', '[\"Tata tahu, tempe dalam panci/wajan.\", \"Masukkan bumbu halus, daun salam, lengkuas, air, garam, penyedap, gula pasir.\", \"Masak sampai air menyusut. Jagan lupa cek rasa.\", \"Bisa langsung dinikmati, bisa juga digoreng.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1228, 4, 'Tempe Tahu Crispy Black paper', 'Buat Tempe Tahu Crispy Black paper yang nikmat dengan langkah-langkah mudah ini.', '[\"2 buah Tahu Putih (potong dadu jadi 16)\", \"1 Potong tempe (potong dadu jadi 6)\", \"1 buah Wortel (potong memanjang seperti korek api)\", \"Bahan Saus :\", \"1/2 buah paprika merah (potong kotak)\", \"1/2 buah paprika kuning (potong kotak)\", \"2 siung bawang putih (iris tipis)\", \"2 buah cabe rawit merah (iris tipis)\", \"1 buah bawang bombai kecil\", \"Kecap manis\", \"Kecap asin\", \"Gula pasir\", \"Garam\", \"Lada hitam (tumbuk halus)\", \"Air\", \"Tepung maizena\", \"Bahan tambahan :\", \"Tepung bumbu serbaguna untuk menggoreng tahu dan tempe\", \"Minyak goreng\"]', '[\"Potong dadu tahu dan tempe, celupkan pada tepung bumbu yang sudah diberi air.\", \"Panaskan minyak untuk menggoreng\", \"Setelah minyak panas, masukan tahu dan tempe yang sudah di celupkan pada bumbu ke dalam minyak, lalu goreng sampai warna kuning kecoklatan.\", \"Setelah matang, angkat dan tiriskan.\", \"Untuk saus, tumis bawang putih, bawang bombai, cabai, sampai tercium bau khas.. Lalu masukkan Wortel dan paprika, beri sedikit air. Diamkan sebentar.\", \"Lalu setelah itu masukkan kecap manis, kecap asin, Gula pasir, garam secukupnya sesuai selera dan rasanya pas.\", \"Kemudian beri tepung maizena yang sudah dicairkan dengan air, pada bahan Saus. Aduk merata sampai saus mengental. Tes rasa....\", \"Jika rasa sudah pas, masukan tahu dan tempe Crispy kedalam tumisan saus. Lalu beri lada hitam yang sudah di tumbuk. Aduk hingga merata\", \"Diamkan sebentar sampai saus meresap pada tahu dan tempe Crispy.\", \"Setelah matang, angkat dan sajikan.\", \"Silahkan di coba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1229, 2, 'Sayur labu tempe', 'Nikmati kelezatan Sayur labu tempe dengan resep sederhana ini.', '[\"1 buah labu siam\", \"1/2 papan tempe\", \"1 bgks santan kara kecil\", \"1 ruas lengkuas\", \"2 lembar daun salam\", \"1 batang serai\", \"1 batang daun bawang\", \"Sejumput garam, lada, gula dan penyedap\", \"secukupnya Air\", \"Bumbu halus\", \"7 buah cabai merah\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"2 biji kemiri\"]', '[\"Haluskan bumbu, lalu sangrai hingga harum, tambahkan salam, lengkuas dab batang sereh\", \"Tunggu mendidih. Masukkan tempe yg sudah diiris kecil kecil.\", \"Tunggi sampai mendidih lagi, Lalu tambahkan labu yg sdh diiris kecil kecil.\", \"Setelah sdh sedikit layu masukkan santan, lalu taburi garam, lada, gula dan penyedap rasa. Terakhir masukkan daun bawang.\", \"Setelah mendidih, tes rasa...\", \"Jika sudah pas, hidangkan beri taburan bawang goreng.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1230, 3, 'Empal Daging Tahu Tempe khas Serang Banten', 'Cara membuat Empal Daging Tahu Tempe khas Serang Banten yang enak dan praktis untuk keluarga.', '[\"1/2 kg daging sapi\", \"6 potong tempe\", \"6 potong tahu goreng\", \"1 bks santan kara segitiga\", \"6 siung bawang merah (iris halus)\", \"2 siung bawang putih (haluskan)\", \"4 buah cabe merah besar (rebus, haluskan)\", \"3 ruas lengkuas (geprek)\", \"3 lembar daun salam\", \"1 butir asam jawa\", \"secukupnya garam gula\", \"secukupnya minyak untuk menumis\"]', '[\"Rebus daging hingga empuk, tambahkan garam n asam jawa agar meresap dalam daging.\", \"Rebus cabe merah sekalian bersama daging. setelah cabe layu, haluskan bersama bawang putih\", \"Iris halus bawang merah lalu tumis sampai harum. Tambahkan cabe, lengkuas dan bawang putih yg sudah dihaluskan, tumis sampai harum. Sisihkan.\", \"Sekira daging sudah empuk, masukan tumisan bumbu kedalam rebusan daging. Tambahkan tahu, tempe, salam, laos, garam n gula. Rebus hingga bumbu meresap.\", \"Tambahkan santan kara, aduk, koreksi rasa asin manis sesuai selera.\", \"Siap disajikan dengan taburan bawang goreng..yumm\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1231, 3, 'Tempe kukus sambal tomat', 'Cara membuat Tempe kukus sambal tomat yang enak dan praktis untuk keluarga.', '[\"1/2 papan tempe\", \"10 buah cabe rawit hijau\", \"3 buah cabe merah\", \"1 buah tomat agak besar\", \"8 siung bawang merah\", \"3 siung bawang putih\", \"1 sdt Trasi bakar\", \"1 1/2 sdt garam\", \"1 sdt gula merah\"]', '[\"Kukus tempe, tomat, bawang merah putih dan cabe, ak taruh di atas magic com pas bareng masak nasi\", \"Uleg bahan yang dikukus kecuali tempe bersama Trasi, garam dan gula merah\", \"Setelah sambal jadi, penyet tempe, hmmm.... Enak\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1232, 2, 'Tempe lummer mozzarela', 'Resep Tempe lummer mozzarela yang lezat dan mudah dibuat di rumah.', '[\"500 gr tempe\", \"50 gr mozzarela\", \"Adonan mendoan\", \"1 ons tepung terigu\", \"50 gr daun bawang\", \"200 ml air\", \"1 butir telor\", \"200 gr tepung roti\", \"secukupnya penyedap\", \"Minyak untuk menggoreng\"]', '[\"Campur adonan seperti; tepung terigu,daun bawang,telor,air dan penyedap secukupnya\", \"Belah tempe menjadi 4 bagian.\", \"Masukkan mozzarella kedalam tempe dan masukkan tempe kedalam adonan\", \"Kemudian masukkan tempe yg sudah dilumuri adonan kedalam tepung roti.\", \"Panaskan minyak dengan api sedang agar t.roti tidak mudah hangus.\", \"Tiriskan sejenak lalu siap dihidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1233, 3, 'Tumis kacang panjang tempe', 'Sajian tempe lezat: Tumis kacang panjang tempe penuh protein nabati.', '[\"Kacang panjang yang masih seger\", \"Tempe\", \"3 siung bawang merah\", \"2 siung bawang putih\", \"Cabe merah dan cabe hijau\", \"Rebon udang sedikit (optional)\", \"Sejumput garam\", \"Sejumput gula pasir atau gula merah (kalo aku gula merah ya)\", \"2 butir, kemiri\", \"Penyedap rasa\", \"Bumbu dapur (daun salam, jahe,sereh, lengkuas)\", \"Minyak untuk menumis\"]', '[\"Potong potong kacang panjang (cuci betsih)\", \"Potong potong dadu tempe\", \"Uleg, bawang merah, bawang putih, kemiri, sedikit terasi dan Gula Garam, rebon\", \"Potong serong cabe merah dan cabe hijau\", \"Geprek bumbu dapur\", \"Tumis bahan ulugan, dan cabe, masukan bumbu dapur.\", \"Setelah bumbu berabu harum masukan kacang panjang dan tempe, tes rasa. Masukan sedikit air untuk mematangkan, tutup samapi matang\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1234, 2, 'Minyak Ayam', 'Resep Minyak Ayam ala rumahan yang dijamin menggugah selera.', '[\"400 gr kulit ayam & lemaknya\", \"8 siung bawang putih kating, cincang kasar\", \"1 ruas jahe, geprek\", \"350 ml minyak goreng\", \"1 sdm ketumbar bubuk\"]', '[\"Cuci bersih kulit ayam. Sisihkan\", \"Ambil 50 ml minyak goreng satu bahan yg sudah disiapkan tadi. Tumis jahe hingga harum.\", \"Masukkan kulit ayam, ketumbar dan bawang. Biarkan hingga keluar minyak alaminya sambil diaduk-aduk.\", \"Tambahkan sisa minyak goreng. Masak hingga kulit ayam mengering. Angkat dan saring.\", \"Setelah cukup dingin minyak ayam tadi dapat disimpan dalam wadah kering seperti mason jar/botol. Kalo saya, saya masukkan juga sedikit bawang putih goreng.\", \"Kulit ayam yg sudah digoreng kering tadi bisa dinikmati begitu saja sebagai camilan dengan ditaburi sejumput garam lalu aduk rata.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1235, 4, 'Nasi Bakar Ayam', 'Hidangan ayam lezat: Nasi Bakar Ayam untuk keluarga tercinta.', '[\"1 piring nasi\", \"¹/⁴ fillet ayam, potong kotak, cuci bersih\", \"Daun pisang yang sudah dibersihkan\", \"Lidi/tusuk gigi untuk mengapit daun\", \"1 lbr daun salam\", \"3 cm serai, memarkan\", \"1 ikat daun kemangi, opsional\", \"1 cabe merah besar, iris tipis\", \"1 sdt kecap manis\", \"Minyak untuk menumis\", \"100 ml air\", \"Bumbu Halus:\", \"1 cabe merah besar\", \"3 cabe kecil\", \"2 siung bawang merah\", \"1 siung bawang putih\", \"1 kemiri\", \"1 cm kunyit\", \"¹/² ruas jahe\", \"¹/⁴ tomat\", \"1 sdt gula pasir\", \"1 blok kaldu ayam (aku biasa pake maggy) pake royco, masako\", \"Merica (dikira2 z takar nya, aku sdkit z sih)\"]', '[\"Tumis bumbu halus, masukkan daun salam, serai\", \"Masukkan potongan ayam, kecap dan air, masak hingga air menyusut dan koreksi rasa\", \"Masukkan irisan cabe merah dan daun kemangi, aduk sebentar dan matikan api\", \"Tata daun pisang, tata nasi di atas daun, beri isian ayam atau bisa juga nasi di campur dan diaduk dulu dengan ayam baru di tata di daun Pisang, bunbu ayam akan lebih meresap k nasi\", \"Setelah nasi di bungkus, barulah nasi di bakar, aku bakar pake teflon z br cepet 😀😀\", \"Sajikan selagi hangat 👍👍endeusss\", \"Note: Jangan membakar terlalu lama biar nasi ga kotor dari daun yg di bakar kering\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1236, 4, 'Ayam Saus Hintalu Jaruk', 'Sajian Ayam Saus Hintalu Jaruk yang praktis dan lezat untuk dinikmati bersama.', '[\"1/2 Ekor ayam\", \"2 Butir Hintalu Jaruk\", \"1 Buah Cabe merah\", \"1 Buah Cabe hijau\", \"300 gr Tepung terigu\", \"1 bks Merica bubuk\", \"2 Siung Bawang putih\", \"1 Buah jeruk nipis\", \"secukupnya Minyak goreng untuk menumis dan menggoreng\", \"secukupnya Gula, garam dan penyedap rasa\"]', '[\"Potong ayam menjadi kotak-kotak ukuran sedang cuci bersih kemudian lumuri perasan jeruk nipis, garam dan merica\", \"Buat adonan tepung untuk melapisi ayam. Adonan A (Tepung terigu, garam, merica, penyedap dan air es) dan adonan B (Tepung terigu, garam, merica dan penyedap)\", \"Masukan daging ayam kedalam adonan A kemudian lapisi dengan adonan B, setelah itu goreng daging kedalam minyak panas sampai berwarna kuning keemasan. Angkat tiriskan\", \"Cincang bawang putih,iris seron cabe merah dan cabe hijau. Lumatkan kuning hintalu jaruk aka telur asin dengan air dingin sampai berbentuk pasta\", \"Tumis bawang putih dan cabe sampai harum, kemudian tuangkan ayam dan pasta kuning telur.\", \"Tambahkan gula, garam, penyedap dan merica secukupnya. Tes rasa dan masal hingga mengental\", \"Angkat dan sajikan bersama nasi putih panas. Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1237, 2, 'Ayam saos teriyaki Lada Hitam', 'Ayam saos teriyaki Lada Hitam dengan bumbu meresap sempurna.', '[\"Ayam bagian dada dan tulang\", \"1 buah bawang bombay\", \"2 siung bawang daun\", \"4 siung bawang putih\", \"1 buah cabe merah besar\", \"1 buah cabe ijo besar\", \"Bahan bumbu :\", \"secukupnya Air\", \"Mentega untuk menumis\", \"1 bungkus saos teriyaki (2 sdm)\", \"1 sdm gula pasir\", \"1 bungkus royco ayam\", \"Larutan meizena\"]', '[\"Cara Buat :\", \"1. Sediakan teplon or wajan beri sedikit minyak dan masukan bawang putih dan bawang bombay yang sudah di potong potong tumis sampai harum. Bisa juga sebelum dimasak ayamnya dibalurkan ke saos teriyaki dan diamkan selama 15 menit agar meresap\", \"2. Masukan ayam oseng sampai agak mateng, baru masukan cabe ijo dan merah.\", \"Beri sedikit air\", \"3. Masukan bumbu royco ayan saos teriyaki, gula, dan bubuk lada hitam. Cicipin\", \"4. Setelah mulai mateng masukan daun bawang jika ingin kental bisa masukan larutan meizena yak. Saya tadi gak pake karena tiba tiba amnesia kirain punya tepungnya ternyata udah habis 😭..\", \"Setelah masak siap disajikan dengan nasi angat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1238, 4, 'Steak ayam', 'Steak ayam - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"300 gr dada ayam fillet\", \"1 sdm air jeruk nipis\", \"secukupnya garam\", \"adonan basah\", \"50 gr terigu\", \"10 gr maizena\", \"1/4 sdt merica\", \"garam\", \"secukupnya air\", \"adonan kering\", \"150 gr terigu\", \"30 gr maizena\", \"1/2 sdt merica bubuk\", \"1/4 sdt kaldu jamur\", \"secukupnya garam\", \"secukupnya minyak goreng\", \"bahan saus jamur\", \"50 gr jamur tiram blender\", \"3 bawang putih cincang halus\", \"20 gr keju parut\", \"1 sdm maizena cairkan dgn air\", \"2 sdm saus tiram\", \"1 sdm kecap manis\", \"1/2 sdt merica halus\", \"secukupnya garam & kaldu jamur\", \"air\", \"bahan pelengkap\", \"buncis dan wortel di kukus\"]', '[\"Cuci bersih ayam, iris tipis melebar, rendam dgn garam dan air jeruk nipis 10 menit, cuci\", \"Campur adonan kering, sisihkan\", \"Campur adonan basah, sisihkan\", \"Panaskan minyak goreng dgn api sedang, gulingkan ayam pada adonan kering, lalu celup ke adonan basah, gulingkan lg pada adonan kering, jgn di remas2, kibas2 daging ayam pada adonan kering, lalu goreng di minyak yg banyak dan panas, biarkan krispinya terbentuk dl, jgn di balik2 dl, setelah cukup kering br di balik, goreng smpe matang, tiriskan\", \"Blender jamur tiram kasih air sedikit. tumis bawang putih yg di cincang halus, masukkan jamur yg di blender, masukkan bumbu2 yg lain sampai meresap, lalu tuang maizena yg sdh di cairkan dgn setengah gelas air, aduk2, masukkan keju parut, aduk sampai meletup2, tes rasa, klo sdh sesuai, angkat\", \"Tata dlm piring, ayam goreng tepung dan sayur kukus, siram dgn saus jamur, taburi daun bawang atau parsley jk ada.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1239, 2, 'Ayam Saos Asam Manis Simple', 'Cara membuat Ayam Saos Asam Manis Simple yang enak dan praktis untuk keluarga.', '[\"1/4 kg Ayam bagian dada fillet (Potong dadu)\", \"Secukupnya air jeruk nipis utk baluran\", \"1 Bungkus tepung bumbu ayam instan uk besar + campur sedikit tepung terigu\", \"3 Siung b.putih (iris tipis)\", \"3 Siung b.merah (Iris tipis)\", \"1 Buah b.bombay (Iris tipis)\", \"1 Buah tomat uk besar (Haluskan)\", \"3 sdm saos sambal\", \"1 Sdm Saos tiram\", \"Secukupnya Gula & garam\", \"Secukupnya merica bubuk\"]', '[\"Lumuri ayam yg sdh dipotong dadu dgn garam & perasan jeruk nipis (diamkan sebentar)\", \"Baluri ayam dengan tepung basah, lanjutkan ke tepung kering, diamkan sebentar\", \"Goreng ayam yg sdh dbaluri tepung sampai kering & matang, angkat tiriskan.\", \"Membuat Saos Asam Manis : -Tumis b.merah & putih (sy suka klo bawang y agak kering)\", \"Masukkan bawang bombay, tumis sebentar.\", \"Masukkan tomat buah yg sdh dihaluskan tdi, tumis lagi pakai api sedang, tambahkan air secukupnya\", \"Masukkan saos sambal, saos tiram, sedikit perasan jeruk nipis, gula, garam & merica (koreksi sampai rasanya terasa asam manis gurih segar)\", \"Masukkan ayam yg sdh digoreng tdi kedalam saos asam manis, diamkan sebentar\", \"Setelah ayam sdh cukup merasap dengan saos asam manisnya matikan api dan siap disajikan dengan nasi putih hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1240, 2, 'Mie Ayam Homemade by suami😂😂😂', 'Mie Ayam Homemade by suami😂😂😂 - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"Bahan mie ayam :\", \"1 kg tepung terigu proteiin tinggi\", \"4 butir telur\", \"3 sendok minyak goreng\", \"Air\", \"Secukupnyaa garam\", \"Air untuk merebus mie :\", \"secukupnya Air\", \"Minyak goreng\", \"Bumbu halus kuah ayam untuk mie ayam :\", \"3 Dada ayam(potong kotak2 jngn terlalu besar)\", \"5 siung bawang merah\", \"5 siung bawang putih\", \"4 buah kemiri\", \"secukupnya Lada\", \"Secukupnya ketumbar\", \"Jahe\", \"Lengkuas\", \"2 lembar sereh\", \"5 lembar daun jeruk\", \"2 lembar daun salam\", \"Kecap\", \"Gula merah\", \"Minyak untuk menumis\", \"Bahan pelengkap :\", \"Daun bawang\", \"Sawi hijau\", \"Bawang goreng(me gak pakai lupa)\", \"Bahan sambal :\", \"20 buah cabai rawit merah\", \"Garam(agar tidak cepat bau asam)\", \"Air untuk merebus\"]', '[\"Kocok telur masukan garam n minyak goreng,aduk rata.masukan tepung terigu uleni pakai tangan sampai kalis(tidak menempel di tangan)diamkan 5 menit.\", \"Bagi adonan menjadi beberapa untuk memudahkan menggilasnya nanti,pipihkn pakai tangan lalu giling pakai ketebalan 4 setalah itu giling lg pakai ketebalan 1(ketebelan selera ya kalau saya suka yg tipis),sebelum di giling ke cetakan mie beri taburan terigu di atas adonannya agar tidak menempel,lakukan sampai adonan habis.\", \"Bagi mie menjadi beberapa porsi jngn lupa di beri taburan terigu ya agar tidak menempel.\", \"Haluskan semua bumbu halus kecuali daun jeruk&salam.\", \"Siapkan penggorengan beri minyak untuk menumis bumbu halus,masukan daun jeruk(sobek2)&daun salam,sereh geprek aja,tunggu sampai harum,lalu masukan ayam beri air(banyak boleh karna untuk kuahnya nanti)masukan kecap n gula merah,garam&penyedap test rasa.\", \"Untuk sambal rebus cabai merah rawit kira2 5menit.\", \"Siapkan panci beri air untuk merebus mie, masukan minyak goreng ke dalam air tujuaan untuk tidak menyatu.setelah mendidih masukan mie tunggu sampai mie naik ke atas barubdi angkat.\", \"Siapkan mangkok beri garam n kuah ayam aduk2 mie baru di berikan bahan pelengkap.\", \"Mie ayam homemade by suami siap di sajikan 😉😉😉😉\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1241, 4, 'Ayam Bakar Pedas Manis Resep :Nila Sari', 'Resep Ayam Bakar Pedas Manis Resep :Nila Sari ala rumahan yang dijamin menggugah selera.', '[\"1 Ekor Ayam Broiler Ukuran Jumbo\", \"Bumbu :\", \"5 Siung Bawang Merah\", \"10 Buah Cabe (Optional)\", \"1 Ruas Jahe\", \"1 Ruas Kunyit\", \"Secukupnya Lada Bubuk\", \"Secukupnya Ketumbar\", \"2 Lembar Daun Jeruk\", \"3 Lembar Daun Salam\", \"1 Batang Serai\", \"4 Siung Bawah Putih\", \"Secukupnya Kecap\", \"Secukupnya Gula Merah\", \"Secukupnya Minyak Goreng\", \"Secukupnya Royco\", \"Secukupnya Garam\", \"1 Bungkus Santan Kara\"]', '[\"Iris tipis bawang merah dan daun jeruk.\", \"Haluskan cabe, bawang putih, lada, ketumbar, jahe dan kunyit.\", \"Tumis bawang merah hingga wangi.\", \"Masukan bumbu yang telah dihaluskan ke dalam tumisan bawang tumis semua hingga harum.\", \"Masukan serai, daun jeruk dan daun salam masak sedikit tuang santan kara dan tambahkan air.\", \"Kemudian masukan ayam taburi royco, lada dan garam aduk aduk tutup dan tunggu ayam empuk dan air mulai susut tes rasa.\", \"Bakar ayam bisa menggunakan arang, teflon, atau batu bakar (saya memakai grill lebih praktis).\", \"Selamat Mencoba.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1242, 2, 'Semur Ayam Kentang Ala Mama Kirana', 'Resep praktis Semur Ayam Kentang Ala Mama Kirana yang bisa dicoba di rumah.', '[\"1/2 Ekor ayam\", \"Kentang\", \"Bumbu Halus :\", \"Bawang putih - bisa di sesuaikan sesuaikan\", \"Bawang merah\", \"Merica\", \"Kemiri\", \"Sedikit biji Pala\", \"Cabai Merah kriting, bila suka pedas\", \"Sedikit jahe\", \"Rempah:\", \"Daun salam\", \"Lengkuas\", \"Sereh\", \"Kapulaga\", \"Kulit manis\", \"Irisan bawang bombay\", \"Irisan tomat\", \"Garam\", \"Kecap manis\", \"Sedikit penyedap rasa\", \"Jeruk nipis untuk ayam\"]', '[\"Cuci bersih ayam lalu baluri dengan perasan jeruk nipis\", \"Cuci lagi ayam dan baluri dengan garam lalu rebus sebentar lalu di goreng\", \"Kentang saya goreng bisa di sesuaikan sesuai selera masing²\", \"Tips goreng ayam agar hasil nya tdk keras : di goreng hanya sebentar\", \"Tumis bawang bombay lalu masukan bumbu halus dan masukkan semua rempah + irisan tomat + kecap manis\", \"Setelah bumbu harum masukkan air tunggu gingga mendidih\", \"Tambahkan garam + penyedap rasa apabila kurang manis bisa ditambahkan kecap lagi\", \"Setelah semua sudah sesuai dgn rasa masukkan kentang goreng + ayam goreng\", \"Tunggu kuah hingga menyusut dan kiraa² 5 mnt angkat. Dan terakhir saya taburin bawang goreng bisa disesuaikan jg dgn selera masing². Selesai\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1243, 3, 'Ayam suwir', 'Resep Ayam suwir yang lezat dan mudah dibuat di rumah.', '[\"300 gram Ayam suwir (sudah direbus/Goreng)\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"1/2 buah tomat\", \"1/2 sdt merica\", \"1/2 sdt terasi\", \"2 buah cabe rawit\", \"2 buah cabe kriting\", \"Secukupnya gula\", \"Secukupnya garam\", \"Secukupnya air\", \"Secukupnya penyedap rasa (Royco)\", \"2 lembar daun salam\", \"1 jari Lengkuas geprek\"]', '[\"Haluskan semua bumbu kecuali tomat, lengkuas, Dan daun salam\", \"Siapkan wajan untuk menumis Bumbu, kemudian tuang sedikit minyak Goreng Dan tumis Bumbu yang sudah dihaluskan ditambah daun Salam Dan lengkuas\", \"Setelah tercium bau Bumbu yang ditumis kemudian masukkan tomat yang sudah dipotong potong\", \"Kemudian setelab tomat layu masukkan air secukupnya Dan rasakan kuahnya kalau belum pas bisa ditambahkan penyedap rasa (Royco)\", \"Masukkan ayam yang sudah disuwir Dan aduk\", \"Tunggu sampai meresap Dan air berkurang\", \"Dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1244, 2, 'Ayam goreng tepung', 'Cara membuat Ayam goreng tepung yang enak dan praktis untuk keluarga.', '[\"150 gr fillet ayam\", \"5 sdm tepung bumbu serbaguna\", \"1 butir telur ayam (kocok lepas)\", \"Garam sck\", \"Minya goreng secukupnya untuk menggoreng\"]', '[\"Cuci ayam, tiriskan beri perasan jeruk lemon (skip boleh) Potong ayam bentuk dadu.\", \"Koco telur beri secukupnya garam. Masukkan ayam yg telah dipotong dadu.\", \"Balurkan ke dalam tepung serbaguna.\", \"Goreng pada minyak yg panas.\", \"Siap disantap😘😘😘😘\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1245, 3, 'Tulang Ayam Pedas Manis', 'Resep Tulang Ayam Pedas Manis yang lezat dan mudah dibuat di rumah.', '[\"1/2 kg tulang ayam bersihkan lalu potong\", \"5 bh cabe merah keriting\", \"5 bh cabe rawit (tambah jika suka pedas)\", \"4 butir bawang merah\", \"2 butir bawang putih\", \"1 ruas kunyit\", \"2 lbr daun salam\", \"1 lbr daun jeruk\", \"1 btg sereh geprek\", \"1 ruas jahe geprek\", \"1 btr jeruk nipis\", \"secukupnya kaldu bubuk\", \"secukupnya gula pasir\", \"secukupnya kecap manis\", \"500 ml air untuk merebus tulang\", \"minyak untuk menumis\"]', '[\"Setelah tulang ayam di bersihkan dan di potong potong lumuri tulang dengan perasan jeruk nipis lalu biarkan\", \"Siapkan bumbu yg akan di haluskan bwg merah, bwg putih, cabe, dan kunyit blender hingga halus\", \"Siapkan air untuk merebus tulang tambahkan jahe yg sudah di geprek dan daun jeruk ungkep tulang hingga air menyusut\", \"Tumis bumbu yg sudah di halus kan tambahkan air secukupnya dan daun salam juga sereh geprek, masukan tulang ayam, beri kaldu bubuk, gula pasir dan kecap manis secukupnya jgn lupa test rasanya dan biarkan tulang ayam hingga meresap\", \"Setelah tulang ayam kuahnya agak sedikit meresap angkat lalu sajikan\", \"Bisa untuk teman makan mie ayam lohh moms 😃\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1246, 4, 'Ayam penyet rumahan', 'Sajian Ayam penyet rumahan yang praktis dan lezat untuk dinikmati bersama.', '[\"1 ekr ayam negri cuci bersih ptng beri air jeruk nipis cuci lagi\", \"1 buah jeruk nipis\", \"Bumbu ayam goreng jd,yg bsah. bisa beli di pasar,aku beli 3rb\", \"2 lmbr daun salam\", \"2 lmbr daun jeruk\", \"1 btng sere geprek\", \"Garam secukupnya dan penyedap\", \"secukupnya Minyak goreng\", \"Sambel penyet:\", \"20 buah cabe rawit merah\", \"5 buah cabe merah\", \"2 siung bawang p kating\", \"5 buah bawang merah goreng sebentr\", \"Penyedap dan sedikit gula\"]', '[\"Ungkep ayam bersama bumbu jadi, daun salam, daun jeruk, sere,dan garam,tambah sedikit penyedap apinya kecil ajah ya. Lalu tutup\", \"Apabila sudah empuk dan matang goreng dalam minyak panas dan banyak sampe warna kuning kecoklatan, angkat\", \"Sementara lagi goreng ayam, kita siapkan sambel dulu, uleg semua cabe, dan bawang merah garam,sedikit gula dan penyedap, setelah agak halus kumpulin sambalnya di tengah cobek lalu siram dengan minyak panas bekas goreng ayam tadi lalu uleg lagi supaya rata\", \"Masukan ayam goreng ke dalam cobek lalu penyet pake ulegan, siap di hidangkan\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1247, 3, 'Sop ayam', 'Resep praktis Sop ayam yang bisa dicoba di rumah.', '[\"1 kg ayam potong kecil kecil\", \"1/2 kg ceker ayam bersihkan\", \"1/2 kg kentang iris\", \"1/2 kg wortel iris\", \"1 mangkok makaroni (rebus)\", \"2 batang daun bawang (sesuai selera)\", \"4 batang daun seledri (sesuai selera)\", \"Bumbu dihaluskan :\", \"8 siung bawang merah\", \"5 siung bawang putih\", \"Tambahan :\", \"1 sendok teh lada halus\", \"secukupnya Garam\", \"Penyedap rasa (bila Sun\'s saya pake gula aja)\"]', '[\"Tumis bawang merah dan bawang putih hingga harum\", \"Masukkan potongan ayam dan ceker ke tumisan bumbu aduk rata\", \"Pindahkan ke panci besar tanbahkan air secukupkan\", \"Didihkan sampai ayam dan ceker cukup matang\", \"Masukkan kentang dan wortel yang diiris tadi, tunggu sampai lembut\", \"Masukkan macaroni yg sudah direbus\", \"Taburkan lada bubuk dan garam, tes rasa\", \"Terakhir masukkan daun bawang dan daun seledri\", \"Siap dihidangkan, taburkan bawang goreng biar tambah maknyuss\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1248, 3, 'Nugget Ayam Home Made', 'Hidangan ayam lezat: Nugget Ayam Home Made untuk keluarga tercinta.', '[\"1/4 kg ayam d fillet ambil dagingnya aja\", \"1 buah wortel\", \"1 buah daun bawang prei\", \"4 siung bawang putih\", \"8 siung bawang merah\", \"1 sdt merica\", \"1/2 kg tepung tapioka\", \"2 telur ayam\", \"Garam, penyedap rasa\", \"Tepung roti/ tepung panir\"]', '[\"Cuci bersih ayam. Setelah itu potong kecil2. Masukkan dlm blender. Tambahkan 1 telur ayam, bwg pth, bwg merah, merica. Air sdkt. Lalu blender.\", \"Setelah itu parut wortel, ptong kecil2 daun bawang prei\", \"Taruh adonan ayam dalam wadah\", \"Masukkan wortel, daun prei, tepung tapioka 10 sdm. Kalau pengen lebih padet bisa tambahkan lagi. Sesuai selera\", \"Aduk2 ya sampai tercampur rata. Tambah i garam, penyedap.\", \"Siapkan wadah. Tuang adonan ke dalam wadah yg sebelumnya d olesi mentega\", \"Kukus d panci pengukusan. Kukus 30 - 40 mnt.\", \"Setelah matang, keluarkan dr panci. Biarkan dingin. Lalu keluarkan.\", \"Siapkan 1 telur (dikocok), tepung panir. Potong2 adonan jd kecil2, celupkan ke telur, lalu baluri dg tepung panir.\", \"Setelah itu goreng.Nugget siap d hidangkan. Nugget juga bisa d simpan d dalam freezer ya moms 😊. Jadi sewaktu2 bisa langsung goreng.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1249, 3, 'Ayam Koloke', 'Hidangan ayam lezat: Ayam Koloke untuk keluarga tercinta.', '[\"250 gr ayam fillet, potong-potong\", \"2 sdm tepung bumbu serbaguna (larutkan dgn 75 ml air)\", \"Pelapis:\", \"4 sdm tepung terigu\", \"1 sdm maizena\", \"Bahan Saus\", \"1 sdm butter / margarin\", \"2 siung bawang putih, cincang halus\", \"1 siung bawang bombai uk. Kecil (iris halus)\", \"1/2 bh wortel (potong korek api)\", \"1/2 bh timun (buang biji dan iris korek api)\", \"1 btg daun bawang (potong2)\", \"2 bh cabe merah (iris serong)\", \"3 bh cabe rawit (iris serong)\", \"3 sdm saus tomat\", \"1 sdm saus tiram\", \"1 sdt minyak wijen\", \"1 sdt air lemon / jeruk nipis / cuka masak\", \"250 ml air\", \"Garam, lada, gula\", \"1 sdt maizena (larutlan dgn 1 sdm air)\"]', '[\"Marinade ayam dgn tepung bumbu serbaguna yg sudah dilarutkan, aduk & disisihkan.\", \"Siapkan bahan pelapis. Ambil potongan ayam & balur ke dalam bahan pelapis. Goreng dalam minyak panas sampai matang. Lakukan sampai habis.\", \"Bahan saus: lelehkan butter, tumis duo bawang sampai harum. Masukkan wortel dan timun, tambahkan air, lalu masak sampai air mendidih. Masukkan duo cabe, saus tomat, saus tiram, minyak wijen, garam, gula, lada, air lemon, aduk rata. Masukkan larutan maizena, aduk sampai mengental. Terakhir masukkan daun bawang, matikan api supaya sayuran tidak over cook.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1250, 4, 'Mie tulang ayam', 'Hidangan ayam lezat: Mie tulang ayam untuk keluarga tercinta.', '[\"1/4 kg tulang ayam\", \"1 bungkus kecil mie burung dara\", \"5 siung bawang putih\", \"3 siung bawang merah\", \"7 cabe rawit\", \"1 tangkai daun bawang\", \"2 tangkai seledri\", \"1 1/2 sdm merica bubuk\", \"2 sdm saos cabe\", \"3 sdm kecap manis\", \"secukupnya Gula dan garam\", \"Minyak untuk menumis\"]', '[\"Cuci bersih lalu rebus tulang ayam kurleb 10 menit. Lalu tiriskan\", \"Rebus mie sampai setengah matang. Lalu tiriskan\", \"Haluskan bawang merah, bawang putih dan cabe rawit\", \"Tumis sampai harum bumbu halus dengan irisan seledri dan daun bawang. Lalu tambahkan merica bubuk, gula dan garam.\", \"Masukkan tulang ayam, tunggu sampai bumbu meresap.\", \"Masukkan mie, saos dan kecap. Lalu tumis sampai bumbu tercampur. Tambahkan gula dan garam jika diperlukan.\", \"Mie tulang ayam siap dihidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1251, 4, 'Ayam Suir Bali (bemesere bali)', 'Resep Ayam Suir Bali (bemesere bali) yang lezat dan mudah dibuat di rumah.', '[\"1/2 kg dada ayam (rebus dahulu)\", \"50 ml minyak goreng\", \"Bumbu :\", \"1/4 kg cabai merah\", \"1/2 buah tomat\", \"5 buah Cabe rawit\", \"secukupnya Garam\", \"secukupnya Gula jawa\", \"1 sdt terasi bakar\", \"1/2 perasan jeruk limo\", \"3 buah daun jeruk purut\"]', '[\"Rebus ayam terlebih dahulu. Lalu, di suwir-suwir. (saya rebus karna kalau goreng, ayamny akan terasa keras dan kering)\", \"Ulek halus bumbu, lalu icip2 rasa agar pas\", \"Siapkan wajan, masukkan minyak goreng. Tunggu sampai panas, tuangkan bumbu\", \"Stelah stengah matang, lalu masukan ayam yang sudah disuir.\", \"Tunggu sampai agak meresap bumbuny. Masukkan perasan limo dan daun jeruk\", \"Makanan siap dihidangkan. Simple dan enak\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1252, 4, 'Pindang ayam jadul', 'Pindang ayam jadul dengan bumbu meresap sempurna.', '[\"1/2 kg ayam\", \"5 btr bawang merah iris halus\", \"10 buah cabe rawit iris halus\", \"2 cm jahe iris halus\", \"1 cm lengkuas iris halus\", \"1/2 sdt kunyit halus\", \"1 sdt asam jawa\", \"1 sdt terasi bangka panggang\", \"1 bh tomat potong 4\", \"Secukupnya daun kemangi (me:gak ada)\"]', '[\"Tumis semua bumbu kecuali tomat dengan 2 sdm minyak,oseng sampai harum,tambahkan 1 liter air didihkan,kalau sudah mendidih masukkan ayam,tutup, masak sampai ayam matang, setelah ayam matang koreksi rasa,beri taburan tomat dan daun kemangi, sajikan hangat, segerrr abis\", \"Selamat mencoba\", \"Semoga bermanfaat untuk semua\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1253, 3, 'Ayam Kacang Panjang Saos Hoisin', 'Hidangan ayam lezat: Ayam Kacang Panjang Saos Hoisin untuk keluarga tercinta.', '[\"Bahan Daging\", \"1 lembar paha atas/dada ayam\", \"1 sdm kecap asin, arak beras, tapioka\", \"Bahan saos\", \"1 ikat Kacang panjang\", \"2 siung baput cincang halus\", \"3 cm jahe cincang halus\", \"1 sdm saos hoisin\", \"1 sdt kecap asin\", \"0.5 sdt micin\", \"100 ml air\", \"Larutan tapioka\"]', '[\"Marinade daging dengan bahannya 30mnt.\", \"Sebelum di tumis beri 1sdm minyak di daging ayam, aduk rata, lalu tumis agar tidak lengket di wajan. Matang, lalu angkat.\", \"Tumis jahe 10detik, masukkan baput lalu tumis sampai wangi.\", \"Masukkan kacang panjang, tumis sebentar lalu masukkan air, saos hoisin, kecap asin, micin. Tutup wajan, kecil kan api.\", \"Tunggu 1-2menit, buka tinder tutup wajan, aduk sebentar lalu tutup lg 1-2menit.\", \"Masukkan daging, aduk rata.\", \"Masukan larutan tapioka agar saos mengental. Aduk rata lalu sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1254, 4, 'Tongseng ayam', 'Resep Tongseng ayam yang lezat dan mudah dibuat di rumah.', '[\"500 g daging ayam (potong2)\", \"1250 CC santan dr 1 butir kelapa (pisahkan bagian yg kental)\", \"3 lembar daun jeruk\", \"3 lembar daun salam\", \"1 ruas lengkuas (geprek)\", \"1 batang serai (geprek)\", \"20 buah cabe rawit hijau\", \"1 batang daun bawang (potong serong)\", \"1 buah tomat (potong2)\", \"3 sdm kecap manis\", \"1 buah kentang ukuran sedang (potong2)\", \"Secukupnya kol (iris2 tebal)\", \"Secukupnya garam,kaldu bubuk, gula pasir (sesuai selera masing2)\", \"Bawang goreng untuk taburan\", \"Secukupnya minyak untuk menumis\", \"Bumbu halus ;\", \"8 siung bawang merah\", \"4 siung bawang putih\", \"1 ruas jahe\", \"1/2 ruas kunyit\", \"1 sdt ketumbar\", \"1/2 sdt merica\", \"3 butir kemiri sangrai\", \"3 buah cabai merah besar\"]', '[\"Siapkan semua bahannya.. panaskan minyak, masukkan bumbu halus.. masak hingga keluar aroma wangi,masukkan daun salam, daun jeruk, serai dan lengkuas.. kemudian masukkan potongan daging ayamnya.\", \"Tuangkan santan encer, tunggu hingga daging ayam setengah matang.\", \"Masukkan kentang, garam, gula, kaldu bubuk, dan kecap.\", \"Masak hingga matang... Masukkan potongan kol dan juga cabai hijau.. lalu d susul dgn memasukkan santan kental, aduk2.. jgn sampai pecah santannya, tes rasa..\", \"Setelah mendidih matikan api, masukkan potongan daun bawang dan tomat, lalu beri taburan bawang goreng.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1255, 3, 'Ayam penyet sambel kemangi', 'Sajian Ayam penyet sambel kemangi yang praktis dan lezat untuk dinikmati bersama.', '[\"400 gr dada ayam\", \"1 ikat daun kemangi\", \"1 buah timun uk sedang\", \"1 bungkus bumbu racik tempe\", \"bahan sambel\", \"10 buah cabe merah\", \"10 buah cabe rawit\", \"3 siung bamer\", \"2 siung baput\", \"gula\", \"garam\", \"1/2 buah tomat merah\", \"secukupnya terasi\", \"secukupnya minyak utk menggoreng\", \"air utk mengungkep ayam\"]', '[\"Potong ayam sesuai selera,cuxi bersih lalu ungkep dengan sesikit air dan campur dengan bumbu racik tempe,matang angkat\", \"Panas kan minyak lalu goreng ayam hingga matang kecoklatan\", \"Goreng sebentar semua bahan sambel nya,,uleg jadi satu tambahkan garam gula...tes rasa...kalo sudah oke..masukkan beberapa lmbar daun kemangi..giling agak kasar aja\", \"Geprek ayam di atas ulek an,,susun di piring lalu letakkan sambel di atas ayam..susun irisan timun,dan juga kemangi. siap di santap dwngan nasi panas\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1256, 4, 'Nugget Ayam Wortel', 'Sajian Nugget Ayam Wortel yang praktis dan lezat untuk dinikmati bersama.', '[\"250 gram daging ayam giling\", \"1 buah wortel ukuran sedang\", \"1/2 buah bawang bombay\", \"2-3 siung bawang putih\", \"3 batang daun bawang\", \"2 butir telur ayam\", \"100 gram tepung terigu (kurang lebih)\", \"secukupnya Tepung roti\", \"secukupnya Garam\", \"secukupnya Lada\", \"secukupnya Penyedap rasa ayam\", \"Minyak goreng\"]', '[\"Potong-potong bawang bombay dan bawang putih. Tumis dengan sedikit minyak hingga harum. Angkat\", \"Campurkan tumisan bawang dengan daging ayam giling dengan menggunakan blender atau food processor. Campur hingga bawang halus & tercampur rata. Tuang pada wadah yg telah disediakan untuk dicampur dengan bahan lain\", \"Potong wortel jadi bagian yg kecil. Masukkan pada campuran daging giling sebelumnya\", \"Potong daun bawang jadi bagian yg kecil. Masukkan pada adonan. Campur hingga rata\", \"Masukkan 1 butir telur ayam. Campurkan\", \"Masukkan tepung terigu perlahan-lahan dan campur hingga rata. Masukkan garam,lada dan penyedap rasa secukupnya.\", \"Panaskan kukusan\", \"Letakkan adonan pada cetakan yg telah disediakan. Masukkan pada kukusan yg telah dipanaskan sebelumnya. Tutup kukusan diberi kain agar air tidak menetes diadonan. Kukus kurang lebih 25-30 menit\", \"Angkat adonan yg sudah matang dari kukusan. Biarkan agar sedikit dingin.\", \"Setelah dingin potong-potong sesuai ukuran yg diinginkan.\", \"Kocok lepas 1 butir telur ayam. Celupkan adonan nugget yg telah dipotong tadi kedalam telur. Kemudian gulingkan di tepung roti.\", \"Ulangi langkah 11 hingga adonan nugget habis\", \"Dinginkan pada freezer kurang lebih 1 jam agar tepung roti menempel dengan sempurna\", \"Goreng nugget dengan minyak panas. Nugget ayam wortel siap disajikan.\", \"Nugget yg masuk ke dalam freezer dapat bertahan maksimal 3-4 minggu\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1257, 3, 'Ayam goreng pedas gila ala Kfc', 'Buat Ayam goreng pedas gila ala Kfc yang nikmat dengan langkah-langkah mudah ini.', '[\"1/2 kg ayam\", \"3 bungkus tepung bumbu uk 80 g yg pedas (aku pke sajiku)\", \"Secukupnya air es\", \"Minyak goreng\"]', '[\"Potong\\\" ayam, lalu cuci sampai bersih.\", \"Siapkan 2 mgkok. 1 untuk adonan tepung yang basah yg 1 nya lagi untuk tepung kering.\", \"Tuangkan kira\\\" 2 sdm tepung bumbu lalu tambahkan secukupnya air es kocok pakai garpu sampai adonannya encer.\", \"Celupkakan ayam ke dalam adonan basah lalu gulingkan ke dalam tepung kering sambil di remas\\\" hingga terbentuk kulit tepung yang keriting. Ulangi sampai selesai\", \"Panaskan minyak, lalu goreng sampai kecoklatan. Angkat, tiriskan.\", \"Ayam goreng siap untuk dinikmati.\", \"NB: kalau gk suka terlalu pedas tepung bumbunya bisa di mix sama yang original ya jd yg pedas bisa pke 1 bungkus aj yg 2 bungkus yg original.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1258, 4, 'Chicken Teriyaki', 'Nikmati kelezatan Chicken Teriyaki dengan resep sederhana ini.', '[\"500 gr Daging ayam iris memanjang\", \"1 bh Bawang bombay, iris memanjang\", \"1/2 sdt Gula\", \"1/4 sdt Garan\", \"150 ml Air\", \"Minyak untuk menumis\", \"Bumbu perendam :\", \"3 sdm Saus teriyaki\", \"2 sdm Saus tiram\", \"1 sdm Kecap manis\", \"1 sdt Minyak wijen\", \"3 siung bawang putih, haluskan\", \"2 cm Jahe, haluskan\", \"1/4 sdt Merica\", \"1/2 sdt Kaldu bubuk\"]', '[\"Campur daging  ayam dengan bumbu perendam,gula dan garam,diamkan dikulkas 1-2jam agar bumbu meresap.\", \"Panaskan minyak tumis daging sampai matang tuangi air,masukan bawang bombay,masak sampai air agak menyusut,kentalkan dengan larutan maizena.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1259, 4, 'Ayam Kecap Pedas Jeruk Limao', 'Resep praktis Ayam Kecap Pedas Jeruk Limao yang bisa dicoba di rumah.', '[\"1/2 kg ayam potong2\", \"2 lbr daun salam\", \"1 ruas jahe geprek\", \"4 lbr daun jeruk, buang tulangnya\", \"3 buah jeruk limao\", \"Secukupnya air perasn jeruk nipis\", \"Secukupnya garam, merica, gula pasir, kaldu bubuk\", \"Secukupnya kecap manis\", \"250 ml air\", \"1 siung bawang Bombay, iris2\", \"🌀 Bumbu Halus 🌀\", \"3 siung bawang putih\", \"5 siung bawang merah\", \"10 buah cabe keriting merah\", \"5 buah cabe rawit merah\"]', '[\"Cuci ayam, lalu lumuri dgn perasan air jeruk nipis & garam, diamkan sebentar -+ 10 mnt, lalu bilas sampai bersih\", \"Goreng ayam sebentar, tidak usah sampai garing, sisihkan\", \"Panaskan minyak, tumis bumbu halus, daun salam, daun jeruk, jahe, sampai harum\", \"Masukkan bawang Bombay, masak sebentar\", \"Tambahkan air, beri garam, merica, gula pasir, kecap, & masukkan ayam, aduk rata, koreksi rasa\", \"Biarkan air surut & bumbu meresap, setelah matang, matikan api, beri perasan jeruk limao, aduk rata, sajikan\", \"Enakk 👌 pedes seger 😍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(1260, 4, 'Resep Ayam Kecap Rumahan', 'Cara membuat Resep Ayam Kecap Rumahan yang enak dan praktis untuk keluarga.', '[\"1/2 Kg ayam\", \"Bumbu yg di haluskan :\", \"3 Bawang Putih\", \"7 Bawang Merah\", \"sesuai selera Cabe rawit dan cabe merah besar\", \"2 cm Jahe\", \"secukupnya Lada dan Pala\", \"Lengkuas se jempol kaki😂\", \"4 biji Kemiri\"]', '[\"Rebus air sampai mendidih lalu masukan ayam dan ungkep sampai empuk\", \"Haluskan semua bumbu\", \"Panaskan minyak lalu tumis bumbu halus sampai wangi\", \"Masukan daun salam 3 lembar dan sereh 2 di geprek\", \"Setelah bumbu sudah matang masukkan 1 gelas air\", \"Tambahkan garam,micin,royko,asem\", \"Setelah di rasa sudah cukup masukan ayam\", \"Kecilkan api biar bumbunya meresap.\", \"Masak sampai bumbu menyusut (jadi agak kental gitu)\", \"Lalu hidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1261, 4, 'Sop Ayam Garang Asam', 'Hidangan ayam lezat: Sop Ayam Garang Asam untuk keluarga tercinta.', '[\"1/2 ayam\", \"3 serai\", \"3 cm jahe\", \"20 cabe rawit merah\", \"8 bawang putih\", \"4 bawang merah\", \"2 tomat hijau\", \"2 jeruk nipis (boleh lebih)\", \"4 daun jeruk\", \"secukupnya daun bawang\", \"secukupnya garam\", \"secukupnya penyedap\", \"secukupnya air matang\"]', '[\"Potong dan bersihkan ayam sesuai selera (kalo aku ku beri perasan jeruk nipis lalu diamkan dulu)\", \"Bawang2an diiris kasar, serai dan jahe di geprek, cabe aku hanya iris 6pc sisanya aku biarkan utuh, tomat kupotong memanjang begitu juga daun bawang.\", \"Panaskan minyak sedikit saja, masukkan bawang serai daun jeruk dan juga cabe diamkan hingga harum lalu masukkan air dan tunggu hingga mendidih. aetelah mendidih masukkan ayam\", \"Tunggu ayam hingga setengah empuk bumbui dengan penyedap garam dan juga gula, masukkan perasan jeruk nipis dan tomat aduk hingga merata\", \"Setelah koreksi rasa dan dirasa sudah pas dan ayam matang masukkan daun bawang. setelah itu selesai\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1262, 2, 'Ayam goreng krutuk', 'Resep Ayam goreng krutuk yang lezat dan mudah dibuat di rumah.', '[\"tepung terigu\", \"Air matang\", \"ayam (yg sudah direbus sebelumnya)\", \"Garam\", \"Gula/penyedap\", \"Lada bubuk\", \"1 butir telur ayam\", \"Minyak goreng\"]', '[\"Campur tepung terigu(kurang lebih 1/2 mangkuk kecil) dengan garam,gula/penyedap dan garam secukupnya. Tambahkan air matang sedikit demi sedikit hingga agak mengental. Koreksi rasa\", \"Balur ayam yg telah direbus sebelumnya dengan 1 butir telur (yg sudah dikocok lepas), kemudian gulingkan dalam adonan tepung, sisihkan\", \"Panaskan minyak goreng dengan api sedang, jika sudah panas masukan ayam yg sudah diberi adonan tepung, kecilkan api lalu masak hingga berwarna kecoklatan dan garing, angkat dan tiriskan.\", \"Selamat menikmati 😀\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1263, 3, 'Ayam panggang saos kecap', 'Nikmati kelezatan Ayam panggang saos kecap dengan resep sederhana ini.', '[\"Bumbu ayam panggang ;\", \"1 kg ayam potong sesuai selera\", \"3 siung bawang merah,ulek halus\", \"3 siung bawang putih,ulek halus\", \"Sedikit kunyit,dan garam,ulek halus\", \"Untuk olesan ayam ;\", \"Kecap manis,saus tomat,sedikit minyak,dicampur\", \"Saos kecap/cocolan ;\", \"sesuai selera Kecap manis\", \"5 siung bawang merah,iris melintang agak tebal\", \"3 siung bawang putih,ulek halus\", \"5 buah cabe rawit,ulek halus\", \"2 buah tomat potong sesuai selera\", \"Jeruk nipis (skip)\", \"Arang untuk memanggang ayam\"]', '[\"Cuci bersih ayam dan tiriskan,campur dibumbu yang sudah dihaluskan,aduk rata,diamkan selama 15 menit,lalu kukus selama 20 menit/ sampai mateng\", \"Sementara menunggu ayam dikukus,siapkan pemanggangan arangnya dulu untuk memanggang ayam\", \"Keluarkan ayam yang sudah dikukus dan siap dipanggang diatas pemanggangan arang\", \"Panggang ayam sambil diolesi dengan olesan, campuran kecap manis,saos tomat dan minyak,bolak balik ayam agar tidak gosong sambil diolesi sampai matang,angkat dan taroh dipiring saji\", \"Campurkan semua bahan saos kecap/ cocolan nya diwadah(mangkok),tambahkan kecap manis secukupnya,aduk agar tercampur rata,dan beri perasan jeruk nipis\", \"Ayam panggang dan saos kecap sudah siap dihidangkan bersama nasi hangat dan irisan timun sebagai pelengkap\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1264, 4, 'Soto ayam kuah santan', 'Hidangan ayam lezat: Soto ayam kuah santan untuk keluarga tercinta.', '[\"1/5 kg ayam (diungkep dulu,lalu digoreng)\", \"2 bungkus santan kara\", \"2 cm kunyit\", \"1 cm jahe\", \"secukupnya Lada\", \"secukupnya Daun salam,lengkuas,daun jeruk dan sereh\", \"5 siung bawang merah\", \"5 siung bawang putih\", \"Penyedap : gula,garam royko ayam\", \"Bahan pelengkap:\", \"iris Tomat\", \"Daun bawang dan seledri\", \"Bihun (rebus dulu)\", \"Bawang goreng\", \"Kol di potong tipis\", \"Tahu goreng\", \"Kerupuk\", \"Bawang goreng\", \"Jeruk nipis\", \"Sambal (cabe rawit,bawang putih/merah di rebus dulu, diulek)\"]', '[\"Panaskan air rebus ayam hingga matang lalu tiriskan (air rebusan ayam bisa untuk kuah soto),lalu goreng ayam hingga matang\", \"Haluskan bumbu bawang merah,putih,kunyit,jahe,lada,lengkuas sereh cukup digeprek dan tumis hingga matang\", \"Masukan tumisan bumbu kedalam rebusan air,masukan daun salam,sereh dan daun jeruk\", \"Berikan bumbu garam,gula penyedap rasa, daun bawang dan santan kara masak hingga matang\", \"Sajikan soto selagi hangat bersama bihun dan pelengkap lainya\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1265, 3, 'Ayam Goreng Bumbu Kuning', 'Resep praktis Ayam Goreng Bumbu Kuning yang bisa dicoba di rumah.', '[\"5 potong ayam\", \"Secukupnya air\", \"Secukupnya minyak goreng\", \"🐓 Bumbu Halus 🐓\", \"1 siung bawang putih\", \"1 ruas jari kunyit\", \"1/2 ruas jari jahe\", \"1/2 sdt ketumbar\", \"Secukupnya garam\"]', '[\"Cuci bersih ayam,masukkan dalam panci,tambahkan bumbu halus dan air. Masak hingga empuk,matang dan bumbu meresap,tiriskan.\", \"Goreng dalam minyak panas dan api sedang hingga kuning keemasan,angkat,tiriskan\", \"Sajikan👌\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1266, 4, 'Mie Geprek (Mie + ayam geprek)', 'Resep Mie Geprek (Mie + ayam geprek) yang lezat dan mudah dibuat di rumah.', '[\"1 bungkus mie burung dara\", \"1 ons dada ayam\", \"tepung terigu\", \"kubis\", \"bawang putih\", \"kecap\", \"royco sapi\", \"secukupnya garam\", \"ebi\", \"minyak wijen\", \"saus tiram\", \"lada bubuk\", \"minyak goreng\", \"air\", \"cabe rawit\", \"bawang merah\"]', '[\"Rebus mie burung dara, tiriskan\", \"Geprek bawang putih 2 siung, tumis sampai harum\", \"Masukkan minyak wijen 1 sendok teh. Tumis tumis sebentar bersama bawang\", \"Masukkan air 1 gelas belimbing\", \"Tambahkan kecap, ebi, garam, saus tiram, royco sapi, lada bubuk sesuai selera. Didihkan\", \"Masukkan mie yang telah direbus. Masak sampai air menyusut\", \"Tambahkan irisan kubis/kol. Aduk-aduk sebentar sampai air habis. Angkat\", \"Cuci bersih ayam, potong jadi 2 bagian atau iris sesuai selera\", \"Siapkan tepung kering. Caranya tambahkan garam dan royco sapi pada tepung. Takarannya sesuaikan dengan jumlah tepung\", \"Siapkan celupan tepung basah. Caranya campurkan tepung dengan air sampai teksturnya cair tapi cukup kental\", \"Masukkan ayam pada tepung kering. Lalu celupkan pada tepung basah. Masukkan ke tepung kering lagi. Remas-remas sampai tepung yang menempel ditangan terlepas dan menempel pada ayam\", \"Goreng ayam pada minyak panas dengan api besar, agar teksturnya crispy. Masak sampai kecoklatan lalu angkat.\", \"Sekarang membuat sambel bawang. Caranya bawang putih setengah siung + bawang merah 2 siung + cabe rawit sesuai selera diulek bersama garam dan gula. Tambahkan 1 sendok minyak lalu campur rata\", \"Geprek ayam crispy tadi kedalam sambel bawang\", \"Sajikan mie goreng dengan topping ayam geprek dan lalapan mentimun\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1267, 3, 'Seblak Mie Tulang Ayam', 'Seblak Mie Tulang Ayam dengan bumbu meresap sempurna.', '[\"1 bungkus mie burung dara\", \"1/4 tulang ayam sisa filet (jadi masih ada daging2ny😁)\", \"Sawi hijau\", \"Sawi putih\", \"Garam\", \"Gula\", \"Bahan halus :\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"3 buah cabe keritinh\", \"15 buah cabe rawit (sesuai selera)\", \"1 ruas jari kencur\"]', '[\"Haluskan seluruh bumbu halus (saya pake blender)\", \"Tumis bumbu halus sampai wangi, masukan tulang ayam, tambahkan air, tunggu smpai ayam matang\", \"Setelah ayam matang masukan mie, gula, dan garam kemudian koreksi rasa..\", \"Setelah rasa pas masukan sayur2n sampai agak layu, jangan terlalu lama..\", \"Seblak mie siap dinikmati😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1268, 4, 'Sweet Buffalo Chicken 🐔', 'Sweet Buffalo Chicken 🐔 dengan bumbu meresap sempurna.', '[\"🐔 Bahan Utama:\", \"1 kg Paha ayam (10 potong)\", \"🐔 Bumbu Pelapis Ayam :\", \"Secukupnya Garam\", \"1 sdt Lada hitam bubuk\", \"1 sdt Paprika bubuk\", \"2 sdm Tepung terigu\", \"🐔 Bumbu Saus:\", \"6 sdm Margarin unsalted\", \"2 sdt Bawang putih bubuk\", \"4 sdm Gula merah bubuk\", \"4 sdm Saus tomat\", \"4 sdm Saus sambal\", \"secukupnya Garam\", \"Secukupnya Wijen\"]', '[\"Cuci dan keringkan ayam (sampai kering).\", \"Lumuri ayam dengan garam, lada hitam, dan paprika bubuk.\", \"Baluri dengan tepung terigu. Diamkan 30 menit (saya 60 menit)\", \"Goreng ayam dengan minyak cukup banyak sampai matang +- 10 menit. Kemudian angkat dan tiriskan.\", \"Panaskan margarin, tambahkan bawang putih bubuk, gula merah bubuk, saus tomat, saus sambal dengan api sedang.\", \"Aduk rata dan biarkan sampai mengental. Pastikan api tidakterlalu besar karena ada gula merah yang rawan gosong.\", \"Masukan ayam dan baluri dengan bumbu sampai rata. Diamkan 5 menit sampai bumbu menyatu pada ayam.\", \"Angkat. Hidangkan sweet buffalo chicken dan taburi dengan wijen.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1269, 4, 'Ayam Garang Asem', 'Hidangan ayam lezat: Ayam Garang Asem untuk keluarga tercinta.', '[\"1/2 ekor ayam\", \"Secukupnya daun pisang\", \"1 santan kara kecil\", \"1 jeruk nipis\", \"👉bumbu rajang\", \"5 cabai rawit\", \"5 cabai merah\", \"4 tomat hijau kecil\", \"6 bawang merah\", \"4 bawanh putih\", \"👉tambahan\", \"1 ruas laos\", \"2 ruas jahe\", \"4 daun jeruk\", \"2 daun salam\", \"2 batang serai\", \"👉garam gulpas air minyak goreng\"]', '[\"Potong2 ayam kecil2 lalu cuci dan beri perasan jeruk nipis diamkan sebentar dan cuci lgi.\", \"Tumis bumbu rajang beserta laos, daun jeruk, jahe, daun salam dan serai.\", \"Masukkan ayam dan air secukupnya. Tanbahkan garam dan gulpas. Masak setengah mateng\", \"Lalu masukkan santan kara aduh2 sampai mendidih matikan kompor\", \"Bungkus ayam dengan daun pisang lalu kukus kira2 15 menit\", \"Siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1270, 3, 'Ayam Asam Manis Rumahan citarasa Resto', 'Resep Ayam Asam Manis Rumahan citarasa Resto ala rumahan yang dijamin menggugah selera.', '[\"Bahan\", \"250 gram dada ayam, potong dadu\", \"1 buah paprika merah/hijau\", \"Sedikit nanas, potong dadu\", \"1 bawang bombay\", \"2 siung bawang putih, geprek\", \"1 sdm minyak bawang utk menumis\", \"Air dan tepung sagu, perbandingan 2:1\", \"Saos asam manis:\", \"4 sdm saos tomat\", \"1 sdm saos sambal\", \"1/2 sdt saos lea perrins\", \"3 sdm gula pasir\", \"1 sdt kaldu ayam\", \"secukupnya garam\", \"3 sdm kecap Inggris\", \"1 sdt minyak wijen\", \"1 sdm maggie seasoning\", \"1 sdm saos raja rasa\", \"Bumbu marinasi ayam:\", \"1 sdt gula pasir\", \"1 sdt garam\", \"1 sdt kaldu ayam\", \"1/2 sdt merica\"]', '[\"Marinasi ayam dengan bumbu marinasi, diamkan selama 10 menit\", \"Tumis bawang bombay, bawang putih, paprika\", \"Masukkan daging ayam yg telah dimarinasi\", \"Masukkan saos asam manis\", \"Masukkan campuran air dan tepung sagu\", \"Aduk hingga mengental\", \"Test rasa, tambahkan garam dan gula sesuai selera\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1271, 4, 'Ayam goreng tepung simple', 'Sajian Ayam goreng tepung simple yang praktis dan lezat untuk dinikmati bersama.', '[\"500 gram ayam dada potong2\", \"6 siung bawang putih haluskan\", \"1/2 sdt lada bubuk\", \"secukupnya Kaldu bubuk\", \"secukupnya Garam\", \"1 butir telur\", \"Tepung pelapis :\", \"100 gram tepung terigu\", \"20 gram tepung meizena\"]', '[\"Potong ayam sesuai selera, aku pake ayam dada utuh karna yg ada stok di kulkas itu hehehhehe\", \"Campur ayam dengan bawang putih yg sudah di haluskan, garam, lada, kaldu bubuk, aduk rata.\", \"Simpan di kulkas minimal 2 jam. (Semakin lama dibumbui ayamnya semakin enak, aku bumbui malam karna untuk di goreng pagi)\", \"Keluarkan ayam dari kulkas masukkan telur ke ayam aduk rata.\", \"Siapkan tepung pelapis diaduk rata lalu gulingkan potongan ayam ke dalam tepung remas sedikit.\", \"Goreng ayam ke dalam minyak panad sampai kecoklatan.\", \"Angkat sajikan, happy cooking moms. 😊😊😊😊😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1272, 2, 'Sop Balungan Ayam', 'Sajian Sop Balungan Ayam yang praktis dan lezat untuk dinikmati bersama.', '[\"Tulang dari 1 ekor ayam jowo, rebus dg api kecil\", \"Bumbu ulek :\", \"4 siung bawang putih\", \"1/4 sdt merica bubuk\", \"1/2 sdt pala bubuk\", \"2 cengkeh\", \"1 sdm garam(sesuaikan dg penggunaan air)\", \"1/2 sdt kaldu jamur\", \"1 sdt gula\", \"Bahan sayur :\", \"2 buah wortel, iris tipis\", \"1 kentang ukuran kecil, potong dadu\", \"1 bonggol sawi sendok\", \"Secukupnya seledri dan daun bawang\", \"Pelengkap : bawang merah goreng\"]', '[\"Cuci bersih tulang ayam, rebus dg api kecil hingga keluar kaldu bening, buang kotoran yang mengapung, setelah itu masukkan bumbu ulek. Biarkan mendidih.\", \"Kemudian masukkan wortel, tunggu 3 menit masukkan kentang, tunggu 5 menit lalu cek rasa dan kematangan sayur, setelah pas baru masukkan sawi sendok, seledri, dan daun bawang. Aduk sebentar lalu matikan kompor.\", \"Sajikan dengan taburan bawang merah goreng dan sambal kecap.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1273, 4, 'Ayam goreng lepas tulang lembut', 'Resep Ayam goreng lepas tulang lembut yang lezat dan mudah dibuat di rumah.', '[\"1 kg ayam\", \"4 bawang putih\", \"3 ruas laos\", \"1 ruas jahe\", \"Daun salam, serai 2 ruas, daun jeruk,\"]', '[\"Masukkan ayam dalam magic com.\", \"Bawang putih, jahe, laos, jahe blender sampai lembut.\", \"Masukkan bumbu yang sudah dihaluskan tadi dalam magic com\", \"Tuang air bioglass dalam magic com sampai ayam terendam air bioglass.\", \"Cetrek cook. Tunggu kira kira 45 menit.\", \"Ambil ayam dari magic com\", \"Taburi garam secukupnya\", \"Goreng\", \"Jadii deh ayam empuk lezatnya. Biar ayamnya dingin juga masih empuk😊😊\", \"Cara bikin sambel nya\", \"Cabe, bawang merah trasi, goreng di sisa minyak ayam goreng tadi. Minyak nya dikit aja.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1274, 3, 'Sayap Goreng Bumbu Ngo Hiang', 'Sajian Sayap Goreng Bumbu Ngo Hiang yang praktis dan lezat untuk dinikmati bersama.', '[\"1 kg sayap ayam bagian drum stick\", \"2 sdm air jeruk nipis / lemon\", \"1 sdt garam\", \"1 sdm bumbu ngo hiang\", \"3 tetes suclarose/stevia drop (boleh skip)\"]', '[\"Cuci sayap ayam, lalu dalam satu wadah masukkan sayap ayam beserta seluruh bumbu diatas, remas2\", \"Simpan dalam kulkas semalaman hingga bumbu meresap\", \"Goreng sayap ayam dengan minyak panas dan banyak hingga matang, sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1275, 4, 'Semur ayam kampung', 'Resep praktis Semur ayam kampung yang bisa dicoba di rumah.', '[\"1/2 kg ayam kampung\", \"3 siung bawang putih\", \"5 siung bawang merah\", \"3 butir kemiri\", \"1 ruas jahe\", \"4 lembar daun jeruk\", \"1 lembar daun salam\", \"1 batang serai (digeprek)\", \"Lengkuas\", \"1/4 sdt kunyit bubuk\", \"1/2 sdt ketumbar bubuk\", \"1/4 sdt merica bubuk\", \"3/4 sdt garam\", \"1/2 sdt gula pasir\", \"Sedikit royco\", \"Secukupnya kecap manis\", \"Secukupnya air kaldu ayam kampung\", \"Secukupnya minyak goreng\"]', '[\"Potong ayam cuci lalu rebus sampai empuk. Haluskan bawang, kemiri, jahe.\", \"Tumis bumbu halus sampai harum masukan serai, daun jeruk, daun salam, lengkuas. Masukan air kaldu, ayam, merica, garam, kunyit, ketumbar, kecap, royco. Masak hingga bumbu meresap dan empuk banget, cek rasa ya bun..\", \"Semur ayam kampung udah matang...\", \"Ini aku masaknya sampai empuk banget... gak alot ya.. gigitnya gak pakai gigi, pakai bibir aja udah bisa, hhheee... krn sebelum dibumbuin direbus dulu sampai empuk, setelah itu baru dibumbuin.\", \"Selamat mencoba..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1276, 3, 'Ayam Tepung KFC super gurih', 'Ayam Tepung KFC super gurih - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"4 potong ayam (paha atas atau paha bawah)\", \"1 Sdt air lemon\", \"Secukupnya black papper\", \"Secukupnya garam\", \"Bahan pelapis :\", \"200 gr tepung terigu serba guna\", \"30 gr tepung maizena\", \"1 Sdt oregano\", \"1 Sdt garam\", \"1 Sdt masako ayam\", \"1 Sdt bubuk cabai\", \"Bahan pencelup :\", \"2 sdm tepung terigu\", \"1 Sdt bubuk cabai\", \"1 Sdt garam\", \"Secukupnya lada putih\", \"Air es\"]', '[\"Marinade Ayam dengan air lemon, black papper Dan garam, diamkan kurleb 1 jam atau lebih\", \"Campur semua bahan pelapis\", \"Campur semua bahan pencelup\", \"Lumuri Ayam dengan bahan pelapis, celupkan ke dalam bahan pencelup dan lumuri dengan bahan pelapis lagi. Lakukan 2-3 kali. Cubit cubit Bagian Luarnya agar hasilnya keriting\", \"Panaskan minyak goreng\", \"Goreng Ayam sampai matang, apinya Jangan terlalu besar agar matangnya merata hingga kebagian dalam\", \"Sajikan bersama kentang, selada atau asparagus sesuai selera\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1277, 4, 'Soto Ayam Surabaya', 'Nikmati kelezatan Soto Ayam Surabaya dengan resep sederhana ini.', '[\"1/2 Ekor Ayam\", \"6 Siung Bawang Merah\", \"4 Siung Bawang Putih\", \"Secukupnya Ketumbar\", \"Secukupnya Lada\", \"1 Ruas Kunyit\", \"1 Ruas Lengkuas\", \"1 Ruas Jahe\", \"1 Butir Kemiri\", \"Daun Salam\", \"Daun Jeruk\", \"Gula\", \"Garam\", \"Penyedap Rasa (boleh pakai boleh tidak)\", \"Daun Bawang\", \"Kol\", \"Tauge\", \"Kentang\", \"Telur Rebus\", \"Sambal Rebus\"]', '[\"Haluskan semua bumbu kecuali lengkuas & Sereh\", \"Tumis bumbu yg dihaluskan tadi hingga harum\", \"Rebus ayam hingga terlihat kaldunya kemudian masukkan bumbu yg telah ditumis tadi\", \"Icip & sajikan dengan kentang goreng, bihun, tauge & irisan tomat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1278, 2, 'Ayam Suwir ala Bali / Ayam Sisit', 'Resep praktis Ayam Suwir ala Bali / Ayam Sisit yang bisa dicoba di rumah.', '[\"500 gram fillet ayam tanpa kulit\", \"1 sdm minyak wijen\", \"1 sdm kecap ikan\", \"1 sdm saos tiram\", \"1 sdm unsalted butter untuk menumis\", \"Bumbu yang dihaluskan\", \"10 siung bawang merah\", \"5 siung bawang putih\", \"1 ruas jari kencur\", \"2 ruas jari kunyit\", \"10 buah rawit merah atau sesuai selera\", \"1 sdt udang rebon\", \"1 sdt garam\"]', '[\"Rebus/Kukus Ayam lalu disuwir2, sisihkan\", \"Tumis bumbu halus, tambahkan minyak wijen, kecap ikan, saos tiram\", \"Masukkan suwiran ayam, aduk rata sampai tercampur dan kering (sesuai selera)\", \"Siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1279, 4, 'Risoles rogut ayam', 'Sajian Risoles rogut ayam yang praktis dan lezat untuk dinikmati bersama.', '[\"Bahan isian:\", \"3 buah kentang, kukus dan tumbuk halus\", \"1 buah wortel, diserut kasar\", \"100 gr dada ayam rebus, suwir halus\", \"2 sdm tepung terigu\", \"secukupnya Lada bubuk\", \"Secukupnya garam\", \"100 ml susu cair\", \"2 siung bawang putih, haluskan\", \"50 gram keju cheddar parut\", \"2 sdm minyak goreng\", \"Bahan kulit:\", \"250 gram tepung terigu\", \"3 sdm margarine, dicairkan\", \"2 butir telur\", \"Secukupnya garam\", \"secukupnya Air\", \"100 gram tepung panir untuk membalur\"]', '[\"Aduk rata kentang kukus yang sudah dihaluskan, tepung terigu, susu cair sampai tidak menggumpal. Sisihkan\", \"Tumis bawang putih yang sudah di haluskan sampai wangi, masukkan adonan kentang kukus yg sudah di campur susu dan terigu tadi.\", \"Tambahkan keju parut, lada bubuk, ayam suwir, aduk cepat sampai kental. Angkat dan sisihkan\", \"Untuk membuat kulit: campur tepung terigu, air, garam, 1 butir telur, aduk dengan pengocok telur agak tidak mengggumpal. Setelah rata masukkan margarine yg sudah dicairkan. Aduk rata kembali.adonan dibuat jangan terlalu kental.\", \"Panaskan wajan anti lengket, dadar adonan sampai habis.\", \"Ambil lembaran kulit, letakkan di tengah kulit dadar isian rogut, tutup sisi kanan kirinya\", \"Sebelum di goreng, celupkan gulungan dadar yg sudah diisi tadi kedalam telur dan balurkan dengan tepung roti ulangi sekali lagi.\", \"Panaskan minyak, goreng hingga kecoklatan.\", \"Risoles siap disajikan hangat dengan cabai rawit atau saos cabai.\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1280, 2, 'Ayam masak kicap ala malay', 'Cara membuat Ayam masak kicap ala malay yang enak dan praktis untuk keluarga.', '[\"4 potong ayam\", \"1 buah bawang bombay\", \"4 buah cabai keriting merah\", \"3 buah cabai rawit\", \"8 buah cabai lalap\", \"1 buah tomato\", \"4 sdm kecap\", \"1 sdm saos sambal\", \"1 sdm saos tiram\", \"1 sdt kunyit bubuk\", \"1 sdt garam\", \"1/2 sdt kaldu bubuk totole (skip boleh/ ganti kaldu bubul lain)\"]', '[\"Cuci ayam sampai bersih, ungkep dengan kunyit bubuk dan garam boleh tambahkan air jeruk lemon atau jeruk nipis. Ungkep selama kurang lebih 15menit\", \"Setelah diungkep goreng ayam sampai kekuningan, angkat sisihkan.\", \"Tumis bawang bombay, cabai kriting merah, cabe rawit, cabe lalap dan tomat sampai harum. Masukkan kecap manis, saos sambal, saos tiram beri garam dan kaldu bubuk sckpnya.\", \"Masukkan ayam beri sedikit air. Cicip rasa.. Masak sampai matang\", \"Masakan siap disantappppp😍😍😍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1281, 4, 'Ayam tepung', 'Resep praktis Ayam tepung yang bisa dicoba di rumah.', '[\"1 kg ayam\", \"500 gram tepung terigu\", \"secukupnya Royco\", \"6 siung bawang putih\", \"1 sendok teh lada bubuk\", \"1 ruas jahe\", \"1 ruas kunyit\", \"secukupnya Garam\", \"Minyak goreng\", \"2 butir telur ayam ambil putih nya aja\"]', '[\"Bersih kan ayam potong jadi 14\", \"Haluskan,bawang putih,jahe,kunyit masuk an ke panci,masuk an ayam,tambah garam diam kan 30 menit(kalau aku di ungkep bentar bun tambah air segelas)\", \"Campur terigu,royco untuk tepung kering\", \"4sendok tepung terigu cair kan dengan 100 ml air,+ 2 butir putih telur kocok lepas,untuk celup an\", \"Panas kan minyak goreng,ambil 1 potong ayam,masuk an ke tepung kering + masuk ke tepung celup + masuk ke tepung kering lalu goreng dengan minyak panas,api sedang sampai kecoklatan\", \"Angkat dan bisa langsung di sajikan bunda\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1282, 2, 'Ayam goreng bakar kecap', 'Cara membuat Ayam goreng bakar kecap yang enak dan praktis untuk keluarga.', '[\"1 kg ayam\", \"Secukupnya minyak untuk menggoreng\", \"Bumbu kuning halus:\", \"4 bawang putih\", \"8 cm kunyit (dikira-kira aja ya)\", \"5 cm lengkuas\", \"1 sdm ketumbar\", \"1 sdt merica\", \"100 ml air\", \"Secukupnya garam dan kaldu bubuk\", \"Bumbu bakar:\", \"8 sdm kecap\", \"2 sdm mentega\", \"Bahan sambel:\", \"3 bawang merah\", \"1 bawang putih\", \"4 cabe hijau besar\", \"7 cabe rawit\", \"1 tomat hijau\", \"Secukupnya garam dan gula\"]', '[\"Ungkep ayam dgn bumbu kuning, hingga bumbu meresap, tiriskan\", \"Panaskan minyak, goreng ayam hingga garing, tiriskan lalu marinade dgn bumbu bakar\", \"Siapkan alat bakaran, bakar jangan trllu lama, angkat\", \"Rebus semua bahan sambal, hingga layu kurleb 5menit, tiriskan lalu ulek, beri bumbu. Boleh d tumis lagi sambelnya. Saya gak sempet d tumis lg udah enak ko\", \"Siap disantap bersama nasi panas dan lalab 👌\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1283, 2, 'Somay ayam bumbu kacang', 'Resep Somay ayam bumbu kacang yang lezat dan mudah dibuat di rumah.', '[\"250 gr dada ayam\", \"Kulit lumpia instan\", \"150 gr terigu\", \"100 gr kanji\", \"4 siung bawang putih\", \"1/2 sdm merica bubuk\", \"1 sachet royco\", \"Bumbu kacang\", \"250 gr kacang\", \"200 gr gula merah\", \"1 sdt royco\", \"1 sdm gula pasir\", \"secukupnya Cabe\", \"Larutan maizena\", \"Kecap\", \"Pelengkap ;\", \"Gubis\", \"Telur puyuh\", \"Tahu putih\"]', '[\"Blender dada ayam tanpa tulang, bawang putih, merica bubuk, & royco..blender sampai lembut...blender dikasih es batu ya..\", \"Tambahkan tepung terigu & kanji.aduk sampai merata\", \"Ambil satu lembar kulit lumpia.isi dengan jeladren ayamnya..bentuk sesuai selera..lakukan hingga adonan habis\", \"Kukus 20 menit sampai layu..kukus bersama pelengkapnya yaa..gubis & tahu putih... Gubis digulung2 lipat dengan tusuk sate..tahu putih dipotong2 dadu..\", \"Telur puyuh rebus sampai matang..tiriskan\", \"Buat bumbu ; goreng kacang sampai kecoklatan..\", \"Blender kacang,cabe,& gula merah...tambahkan air secukupnya\", \"Masukan bumbu kedalam kacang..masak hingga matang, tmbahkan gula pasir, penyedap rasa, tmbahkan larutan maizena agar kental\", \"Potong2 somay,gubis,tahu,& telur puyuh..siram bumbu kacang ke atasnyaa...tmbahkan bawang goreng & kecap\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1284, 4, '.Ayam Kecap Cabe Ijo', 'Buat .Ayam Kecap Cabe Ijo yang nikmat dengan langkah-langkah mudah ini.', '[\"1 ekor ayam potong 8, bersihkan\", \"Cabe ijo 15 buah, potong serong\", \"Bawang bombay 1 siung, potong\", \"Bawang putih 2 siung, cincang\", \"garam\", \"Gula pasir\", \"Lada bubuk\", \"1/2 sdt kaldu bubuk (aku pake royco)\", \"4 sdm Kecap manis (aku pake bango)\", \"Bumbu ungkep :\", \"4 siung bawang merah\", \"5 siung bawang putih\", \"2 cm kunyit\", \"2 cm jahe\", \"2 cm lengkuas, geprek\", \"1 batang serai\", \"1,5 sdt ketumbar\", \"2 buah kemiri\", \"4 lbr daun jeruk\", \"Garam\"]', '[\"1. Ungkep ayam dengan bumbu ungkep kurleb 20 menit hingga bumbu meresap, sisihkan\", \"2. Tumis bawang putih hingga harum, masukkan cabe ijo, bwg bombay, dan lada bubuk\", \"3. Tambahkan air, gula pasir, kecap manis, tunggu hingga mendidih, masukkan ayam\", \"4. Biarkan bumbu meresap, sambil ditambah garam kalau dirasa kurang asin\", \"5. Kalau sudah mulai meresap, tes rasa, angkat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1285, 2, 'Ayam Masak Kluwek', 'Cara membuat Ayam Masak Kluwek yang enak dan praktis untuk keluarga.', '[\"6 kluwek\", \"2 ayam paha\", \"5 sayap ayam\", \"2 buah kemiri\", \"2 buah cabe merah (opsional)\", \"2 siung bawang merah\", \"1 siung bawang putih\", \"2-3 cm jahe\", \"1 keping asam kering\", \"1 sdm bubuk kunyit\", \"Garam, Gula, Penyedap Rasa\", \"secukupnya Air\"]', '[\"(Cabe merah + bwg merah + bwg putih + kemiri + jahe) di tumbuk halus - masukan bubuk kunyit - aduk bentar\", \"Tumis bumbu halus hingga wangi - masukan ayam aduk bentar\", \"Kasih air - garam - gula - penyedap rasa - masukan kluwek - masukan asam keping\", \"Masak hingga ayam matang & bumbu meresap\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1286, 2, 'Ayam Goreng Telur', 'Ayam Goreng Telur dengan bumbu meresap sempurna.', '[\"10 potong Paha Ayam(aku: 1 kg ayam. Potong_potong)\", \"6 siung Bawang Putih\", \"4 lembar Daun Jeruk\", \"3 lembar Daun Salam\", \"2 batang Serai\", \"1 sendok teh Garam\", \"1/2 sendok teh Ketumbar Bubuk\", \"2 cm Kunyit\", \"2 butir Telur Ayam\", \"500 ml Air\"]', '[\"Cuci bersih paha ayam.\", \"haluskan kunyit yang sudah dibakar,garam dan ketumbar bubuk. masukkan bumbu yang sudah dihaluskan,bawang putih yang digeprek,daun jeruk,daun salam dan serai ke dalam air. aduk rata. kemudian masukkan ayam sampai terendam.\", \"masak hingga bumbu meresap. angkat dan diamkan hingga sedikit dingin.\", \"Kocok lepas telur ayam.\", \"guling-gulingkan ayam yang sudah dibumbui sampai telur terbalur rata. siapkan minyak panas dan banyak agar ayam bisa tergoreng sempurna. goreng sampai berwarna kuning keemasan. tiriskan.\", \"Sajikan dengan sambal tomat atau sambal terasi dan nasi hangat :)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1287, 2, 'Ayam Goreng Pemalas', 'Sajian Ayam Goreng Pemalas yang praktis dan lezat untuk dinikmati bersama.', '[\"1 kg ayam\", \"1 bks bumbu ayam goreng sajiku\", \"secukupnya lengkuas parut\", \"2 sdm makan minyak goreng\", \"secukupnya air matang\"]', '[\"Bersihkan ayam.\", \"Lumuri ayam dengan bumbu sajiku. Kalau bisa sambil diremas2.\", \"Masukkan lengkuas parut, air plus minyak goreng. Remas2 lagi sampai semua tercampur sempurna.\", \"Ungkap ayam dengan api kecil kurang lebih 30-45 menit. Agak lama jg gak apa2 biar ayamnya empuk😄\", \"Matikan kompor. Dinginkan sebentar.\", \"Lalu goreng deh. Jangan lupa lengkuasnya disaring ya moms, biar ada nyes2 nya 😄\", \"Sandingkan dengan lalapan, sambal terasi. Klop deh. Selamat makan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1288, 3, 'Nuttget ayam+sayur', 'Resep Nuttget ayam+sayur ala rumahan yang dijamin menggugah selera.', '[\"1 butir telur\", \"1/2 kg Ayam\", \"1 wortel\", \"4 sdm tepung trigu\", \"2 sdm tapioka\", \"5 bawang putih\", \"3 bawang merah\", \"daun bawang+seledri\", \"Lada\", \"Tepung panir\", \"Royko (sesuai selera)\"]', '[\"Filet ayam ambil bagian dagingnya lalu di cincang karna saya pake blender biar gampangdi cincang dulu😅 masukan bawang merah+putih dan telur blender jadi satu\", \"Parut wortel dan iris tipis daun bawang dan sendri (ambil daunnya yg warna hijau saja) + trigu dan tapioka (tambah trigu bila kurang kental) aduk sampai rata tambahnya royko garam dan lada siap di kukus\", \"Tunggu sampai dingin potong sesuai selera gulingkan di telur (saya pakai trigu yg di kasih air sama saja hasilnya) lalu taburi tepung panir\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1289, 4, 'Chicken Hainan & Nasi Hainan Simple Magic Com', 'Buat Chicken Hainan & Nasi Hainan Simple Magic Com yang nikmat dengan langkah-langkah mudah ini.', '[\"Bahan untuk Ayam Hainan:\", \"4 pcs Paha Ayam Utuh (Paha atas dan Paha bawah)\", \"6 siung bawang putih\", \"3 ruas jahe\", \"1 batang sereh\", \"2 lembar daun salam\", \"1 jeruk nipis / lemon\", \"1/2 siung bawang bombay\", \"2 sdm kecap ikan\", \"2 sdm minyak wijen\", \"Sejumput garam\", \"Air Matang\", \"Kaldu ayam bubuk / block (opsional, saya tidak pake)\", \"Bahan untuk Nasi Hainan:\", \"3 Cup beras\", \"4 siung bawang putih\", \"2 ruas jahe\", \"1 batang sereh digeprek\", \"2 lembar daun salam\", \"2 sdm minyak wijen\", \"Sejumput garam\", \"Kuah rebusan bumbu Chicken Hainan\", \"Margarin\", \"Bahan untuk Saus Hainan:\", \"1 siung bawang putih parut\", \"2 sdm kecap manis\", \"2 sdm kecap asin\", \"2 sdm minyak wijen\", \"Bahan tambahan pelengkap:\", \"Ketimun\", \"Daun bawang\", \"Bawang goreng\", \"Emping\"]', '[\"Memasak Chicken Hainan: Cuci bersih ayam dan lumuri dengan sejumput garam dan perasan air jeruk nipis / lemon. Diamkan selama 10 menit. Sambil menunggu 10 menit, iris kasar bawang bombay, kemudian parut bawang putih dan jahe. Masak air hingga mendidih dipanci, dan jika sudah mendidih masukka bawang bonbay, bawang putih, jahe, sereh dan salam. Tunggu beberapa saat hingga harum, masukka ayam dan sedikit minyak wijen. Masak dengan api sedang selama kurang lebih 40menit.\", \"Sebaiknya untum merebus Chicken Hainan ini airnya dibnyakin. Karena nanti kuah rebusan ayamnya ini digunakan untuk kuah chicken hainan dan untuk memasak nasi.\", \"Memasak Nasi Hainan:. Cuci beras hingga bersih dan tiriskan. Kemudian parut bawang putih dan jahe. Selanjutnya lelehkan margarib pada wajan dengan api sedang dan kemudian tumis bawang putih, jahe, sereh dan salam. Tunis hingga harum dan layu. Beri sedikit air dan aduk2 hingga mendidih. Jika sudah mendidih, masukkan beras yg telah dicuci jedalam wajan, aduk rata hingga air dan bumbu tiris dan meresap. Angkay beras dan pindahlan ke Magic Com beserta bumbu2 yg sudah meresap tsb.\", \"Masak beras dengan menggunakan air rebusan Chicken Hainan dan ditambahkan lg sejumput garam dan minyak wijen. Ayam yang sudah direbus tadi bisa juga ikut dimasukkan kedakam magi com agar lebih nikmat nasi hainan nya.\", \"Membuat Saus Hainan: campurkan semua bahan didalam satu wadah, dan aduk rata.\", \"Jika nasi sudah matang, Chicken Hainan dan Nasi Hainan ini siap disajikan dengan saus dan kuahnya. ditambahkan dengan topping daun bawang pada kuah, bawang goreng pada nasi dan ketimun sebagai pelengkap.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1290, 3, 'Ayam Rica-rica super pedes', 'Nikmati kelezatan Ayam Rica-rica super pedes dengan resep sederhana ini.', '[\"1 ekor ayam potong\", \"Bumbu:\", \"5 buah cabai merah\", \"20 buah cabai rawit\", \"5 siung bawang putih\", \"7 siung bawang merah\", \"3 buah kemiri\", \"1 sachet merica bubuk\", \"1 sachet ketumbar bubuk\", \"secukupnya gula merah\", \"secukupnya kecap manis\", \"secukupnya garam\", \"secukupnya penyedap rasa\", \"1 ruas kunyit\", \"1 ruas jahe\", \"1 ruas besar lengkuas\", \"2 batang serai\", \"3 lembar daun salam\", \"2 lembar daun jeruk\", \"secukupnya minyak goreng\", \"secukupnya air\"]', '[\"Potong potong ayam cuci bersih tiriskan\", \"Haluskan cabai merah rawit, bawang merah,putih, kemiri, dan kunyit.\", \"Geprek jahe, lengkuas, serai, dan gula.\", \"Tumis bumbu yang sudah di haluskan hingga harum, masukkan daun salam, jeruk dan bumbu yang digeprek kecuali gula merah.\", \"Masukkan ayam, beri air secukupnya, ungkep 10 menit.\", \"Masukkan merica, ketumbar, gula merah, kecap, garam dan penyedap rasa.\", \"Ungkep selama kurang lebih 20 menit.\", \"Tes rasa. siap sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1291, 3, 'Ayam Goreng', 'Ayam Goreng dengan bumbu meresap sempurna.', '[\"1 ekor ayam (cuci dan rebus sebentar untuk ngurangin lemaknya)\", \"Bumbu :\", \"5 siung bawang putih (geprek)\", \"3 siung bawang merah (geprek)\", \"1 ruas kunyit (geprek)\", \"1/2 sdm ketumbar bubuk\", \"2 lembar daun salam\", \"1 lembar daun jeruk\", \"1 batang serai (geprek)\", \"secukupnya garam\"]', '[\"Siapkan sedikit air dalam panci, didihkan\", \"Jika sudah mendidih masukkan semua bumbu bawang putih, bawang merah, kunyit, ketumbar, daun salam, daun jeruk, serai\", \"Masukkan ayam, tambahkan garam, tes rasa, jika dirasa kurang garam bisa di tambahkan sesuai selera, lalu diamkan beberapa menit hingga air menyusut dan bumbu meresap, angkat dan sisihkan ayam dalam wadah kosong (Dinginkan)\", \"Panaskan wajan dan minyak goreng, goreng ayam satu persatu hingga warna menjadi kuning kecoklatan, sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1292, 3, 'Ayam Cabe Ijo', 'Resep praktis Ayam Cabe Ijo yang bisa dicoba di rumah.', '[\"1 ekor ayam broiler potong 8 bagian\", \"1 sdm air jeruk nipis\", \"2 sdt garam\", \"3 sdm minyak goreng utk menumis\", \"2 lbr daun jeruk\", \"1 batang sereh di geprek\", \"Bumbu Halus :\", \"8 butir bawang merah\", \"5 siung bawang putih\", \"10 buah cabe hujau besar\", \"5 buah cabe rawit hijau\", \"1 ruas jahe\", \"1/2 ruas kunyit\", \"3 butir kemiri\", \"secukupnya Garam dan gula pasir\"]', '[\"Lumuri potongan ayam dengan air jeruk nipis dan garam, sisihkan, biarkan selama 15 menit.\", \"Goreng ayam dengan minyak panas hingga kuning keemasan.\", \"Tumis bumbu yg telah di haluskan masukan daun jeruk, dan serehnya, aduk rata masak terus hibgga bumbu matang dan keluar aromanya.\", \"Masukan ayam yg telah di goreng sebelumya aduk rata, kalau perlu boleh tambahkan air sedikit agar bumbu meresap.\", \"Cek rasanya, bila telah matang taruh di piring saji,ayam goreng cabe ijo siap disantap...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1293, 3, 'Ayam fillet asam manis', 'Resep Ayam fillet asam manis yang lezat dan mudah dibuat di rumah.', '[\"2 buah dada ayam tanpa tulang\", \"100 gr tepung terigu\", \"50 gr tepung maizena\", \"1 putih telur\", \"5 sdm saus tomat\", \"1/2 sdm saus tiram\", \"1 buah bawang bombay (iris)\", \"2 siung bawang putih (cincang halus)\", \"1 sdt garam\", \"1 sdt gula pasir\", \"1 sdt merica bubuk\"]', '[\"Cuci bersih dada ayam lalu potong kecil2 sesuai selera\", \"Tambahkan garam, merica dan putih telur\", \"Masukkan potongan ayam kedalam adonan tepung (tepung terigu + maizena + garam + lada). Atau bisa pakai tepung ayam instan.\", \"Goreng dalam minyak panas selama 5-6 menit sampai berubah warna menjadi golden brown\", \"Siapkan wajan untuk membuat saus asam manis\", \"Tumis bawang putih dengan 3 sdm minyak goreng\", \"Setelah harum masukkan bawang bombay\", \"Tambahkan saus tomat, saus tiram dan setengah gelas air\", \"Masukkan garam, gula dan merica bubuk, aduk sampai tercampur\", \"Jangan lupa untuk koreksi rasa\", \"Larutkan 1sdt maizena dengan air\", \"Tambahkan larutan maizena sedikit demi sedikit hingga kekentalannya pas\", \"Matikan api, siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1294, 4, 'Ayam ukep bumbu sederhana', 'Resep Ayam ukep bumbu sederhana yang lezat dan mudah dibuat di rumah.', '[\"1 kg ayam broiler\", \"8 siung bawang putih ukuran besar\", \"1 sdm peres ketumbar\", \"Kunyit\", \"Garam\", \"Gula\", \"Air\"]', '[\"Cuci bersih ayam, boleh diberi perasan air jeruk nipisbiar ngga amis. Tp kebetulan aku ngga simpen jeruk nipis jd ya ngga pake. Ngga amis kok.\", \"Ulek bawang putih, kunyit dan ketumbar hingga halus\", \"Masukkan air ke wajan, nyalakan kompor. Masukkan setengah bumbu halus beri gula garam sesuai selera, masukkan ayam dilanjut dgn setengah bumbu sisanya.\", \"Tutup wajan. Setelah 5 menit campur ayam dgn bumbunya. Tutup dan diamkan lg hingga dirasa matang.\", \"Jika tidak langsung digoreng semua, bisa ditaruh di wadah tertutup. Tp tunggu dingin dulu yaa ayamnya. Trus masukkin kulkas deh.\", \"Ini ayam yg udh digoreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1295, 4, 'Tongseng Ati Ampela Ayam', 'Resep Tongseng Ati Ampela Ayam yang lezat dan mudah dibuat di rumah.', '[\"2 potong hati ampela ayam yang masih dibalut usus\", \"2 sdm minyak goreng\", \"50 ml air\", \"2 siung bawang putih\", \"4 siung bawang merah\", \"5 buah cabe rawit\", \"3 buah cabe merah keriting\", \"2 butir kemiri\", \"1/4 sdt ketumbar bubuk\", \"1/2 ruas jahe\", \"1 ruas lengkuas geprek\", \"1 lembar daun salam\", \"1/4 sdt lada\", \"1/2 sdt garam\", \"1/2 sdt penyedap\", \"2 sdm kecap manis\", \"Sejumput pala bubuk\"]', '[\"Bersihkan ati ampelanya. Kemudian rebus, goreng setengah matang. Sisihkan!\", \"Baput, bame, kemiri, cabe digoreng bentar lalu uleg\", \"Panaskan minyak tumis bumbu, beri air dan masukkan ati ampelanya. Icip rasa. Tunggu hingga kuah agak menyusut. Sajikan :)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1296, 2, 'Ayam penyet ala sy', 'Buat Ayam penyet ala sy yang nikmat dengan langkah-langkah mudah ini.', '[\"1/2 kg ayam potong2cuci bersh\", \"1 sdm ktumbar bbuk\", \"2 siung bwg puth\", \"5 siung bwg merah\", \"1 ruas laus\", \"4 lmbr daun salm\", \"secukupnya Garam\", \"secukupnya Jeruk nipis\", \"Bhn sambl ulek\", \"secukupnya Cabe merah,cabe rawit\", \"1 buah tomat merah besar\", \"Secukupnya terasi bkar\", \"Jeruk nipis atau jeruk limau\"]', '[\"Ungkep ayam dg bumbu yg sdh d hluskan hingga airnya hmpir kering\", \"Setelh itu angkt.\", \"Goreng ayam hingga matang,lalu tumbuk d a atas ulekkan.\", \"Goreng semua bhn sambl lalu d uleg,setelh itu siram k ayam td\", \"Jd deh siap d santap,iya jnga lupa tes rasa dl iy.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1297, 4, 'Broccoli Rice with Grilled Chicken (menu sehat)', 'Broccoli Rice with Grilled Chicken (menu sehat) dengan bumbu meresap sempurna.', '[\"1 bonggol Brokoli ukuran sedang / besar\", \"500 gr Dada Ayam (bumbui dgn garam, lada, rosemary, kecap hitam)\", \"1 buah Jamur King Oyster (sesuai selera)\", \"50 gr Kentang (rebus terlebih dahulu)\", \"Bawang putih cincang (untuk menumis)\", \"Garam, lada hitam, gula / vetsin (untuk memperkuat rasa)\", \"Rosemary dan thyme kering\"]', '[\"Halusnya brokoli dgn menggunakan Food Chopper / Food Processor sampai menyerupai oatmeal konsistensinya.\", \"Tumis brokoli yg td dgn sedikit minyak dan bawang putih yg sdh dicincang halus. Beri garam, lada, dan sdkit gula. Sisihkan.\", \"Panggang ayam di teflon yg panas sampai matang. Sisihkan.\", \"Panggang kentang di teflon. Beri garam, lada, rosemary, dan thyme sedikit untuk memberikan rasa. Sisihkan.\", \"Tumis jamur yg sdh dipotong2 dgn sdkit minyak dan bawang putih. Beri garam dan lada. Sisihkan. Jamur hanya dimasak sebentar saja. Karena kalu terlalu lama, jamur akan menyusut mjd kecil, dan kandungan vitamin serta proteinnya bs hilang.\", \"Setelah semua sudah matang. Tinggal susun saja di kotak makan seperti di foto. Bisa lsg dimakan. Atau dijadikan bekal untuk adik atau anak ke sekolah. Kalau saya, besok paginya saya tinggal panaskan di microwave sebentar, baru dibawa deh sama adik ke sekolah. Atau bs jg dikukus sebentar saja sampai hangat.\", \"Oh iya. Saya sgt suka mengkonsumsi jamur. Dan king oyster ini adalah jamur favorit saya. Memang harganya lebih mahal dibandingkan jamur2 yg lain. Sekitar 40rb 1 bungkusnya. Tp selain jamur ini sgt besar ukurannya, jamur ini jg hampir tidak mempunyai bau. Jd adik saya yg masih sekolah pun bisa makan jamur ini tanpa komplain krn jamur biasanya memiliki bau yg tidak enak. Berikut foto King Oyster Mushroom yg saya ambil di google (www.veggiecravings.com) untuk referensi.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1298, 2, 'Ayam goreng kremes renyah + sambal trasi🌶🍅🍗', 'Buat Ayam goreng kremes renyah + sambal trasi🌶🍅🍗 yang nikmat dengan langkah-langkah mudah ini.', '[\"1/2 kilo ayam (aku pakai ayam broiler bagian dada) potong2\", \"2 lembar daun salam\", \"2 batang sereh\", \"4 lembar daun jeruk\", \"500 ml santan (1 bungkus santan kemasan+air)\", \"500 ml minyak untuk menggoreng (atau secukupnya)\", \"🍗bumbu yang dihaluskan🍗\", \"6 jsiung bawang putih\", \"5 siun bawang meraih\", \"1/4 sdt ketumbar bubuk\", \"1/4 sdt merica bubuk\", \"3 buah kemiri\", \"2 ruas jari kunyit\", \"1 sdm gula\", \"1 sdt garam\", \"🍗Bahan kremes🍗\", \"300 ml air rebusan ayam (disaring)\", \"125 g tepung sagu (aq sagu tani)\", \"2 sdm tepung beras\", \"1 butir telur utuh\", \"1/2 sdt baking powder double acting (aq hercules)\", \"secukupnya Gula garam\", \"🌶🍅Sambal terasi🍅🌶\", \"7 buah cabe merah (bole ditambah)\", \"1 cabe merah\", \"2 siung bawamg putih\", \"4 siung bawang merah\", \"1 buah tomat ukuran sedang\", \"Secukupnya terasi\", \"Secukupnya Gula garam\"]', '[\"Tumis bumbu halus dengan baceman bawang putih (resepnya disini https://cookpad.com/id/resep/931522-bumbu-penyedap-gurihbaceman-bawang-putih) masukkan sereh,salam dan daun jeruk masak hingga bumbu wangi dan kesat\", \"Masukkan ayam tambahkan santan dan masak hingga mendidih dan bumbu meresap\", \"Carbut kremes: Ambil 300 ml air rebusan air yang sudah disaring dan masukkan kedalam mangkok yang agak besar,masukkan bahan-bahan kremesan aduk hingga rata dan licin\", \"Panaskan api dengan api sedang cenderung kecil,masukkan ayam kedalam adonan kremesan\", \"Aduk2 bahan kremesan dengan tangan,dan siram adonan kedalam wajan menggunakan jari (saat memasukkan adonan,tangan digoyang-goyang ya)\", \"Masukkan ayam keatas kremesan(didalam wajan) biarkan sebentar lalu lipat kremesan menutupi ayam. Goreng hingga coklat keemasan\", \"Ulangi sampai adonan kremesan dan ayam habis\", \"🌶🍅Sambal terasi🍅🌶: goreng bahan sambal hingga matang (jangan gosong ya) lalu ulek hingga halus tambahkan gula garam secukupnya\", \"Siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1299, 2, 'Balado ayam', 'Balado ayam - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"Fillet ayam 1/4 kg\", \"1 biji Bawang bombay\", \"Cabe kering\", \"Bumbu halus(cabe bawang merah bawang putih kemiri merica garam)\", \"secukupnya Gula\", \"Bunga kapulaga\"]', '[\"Tumis bawang bombay masukan ayam tumis hingga berbau harum masukkan bumbu halus cabe kering bunga kapulaga dan gula juga penyedap rasa\", \"Angkat dan sajikan dengan nasi putih 😄\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(1300, 4, 'Mie ayam', 'Mie ayam - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1/2 kg ayam fillet\", \"1/2 kg ceker ayam\", \"bila suka Tetelan ayam\", \"Bahan minyak ayam :\", \"Kulit ayam\", \"Minyak goreng\", \"2 siung bawang putih cincang\", \"Bahan tambahan :\", \"Mie kuning\", \"1 ikat sawi\", \"Daun bawang\", \"Daun seledri\", \"1 batang serai geprek\", \"1 daun jeruk\", \"1 daun salam\", \"Laos geprek\", \"Bawang goreng\", \"Kecap manis\", \"Kecap asin\", \"Bahan sambal :\", \"15 cabe rawit\", \"2 siung bawang putih\", \"Bumbu yang dihaluskan :\", \"5 siung bawang merah\", \"2 siung bawang putih\", \"1 ruas jari jahe\", \"1 ruas jari kunyit\", \"1 buah kemiri\", \"Merica bubuk\"]', '[\"Cara buat minyak ayam : siapkan minyak, tumis bawang putih cincang dan kulit ayam.. masak hinggal kulit ayam mengecil. Sisihkan\", \"Potong2 ayam bentuk dadu bersihkan lalu sisihkan.\", \"Masukkan ceker dan tetelan ayam ke dalam air 500 cc.. masak hingga ceker empuk. Sisihkan kaldunya\", \"Tumis bumbu yg telah dihaluskan.. tambahkan serai, daun salam, daun jeruk, dan laos geprek hingga harum dan berubah warna\", \"Tuang bumbu yg telah di tumis ke dalam air kaldu ayam bersamaan dg potongan ayam... Tambahkan gula, garam, kaldu ayam bubuk, kecap manis. Masak hinggal bumbu meresap.. Test rasa\", \"Saran penyajian : tuang 1 sendok makan minyak ayam ke dalam mangkok, tambahkan 2 tetes kecap asin.. aduk2.. tambahkan mie kuning. Sawi. Kecambah. Tuang ayam dan ceker ke dalam mie. Tambahkan bawang goreng, dan sambal. Kasih saos bila suka\", \"Mie ayam siap dinikmati selagi panas\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1301, 2, 'Chicken wings \"saori\" super simple', 'Hidangan ayam lezat: Chicken wings \"saori\" super simple untuk keluarga tercinta.', '[\"1/2 kg sayap ayam\", \"6 siung bawang putih\", \"2 sdm saori saus tiram\", \"4 sdm saori saus teriyaki\", \"1/4 sdm lada\"]', '[\"Cuci bersih sayap ayam yang telah di belah 2.\", \"Cuci bersih bawang putih tanpa di kupas Kulit, lalu geprek\", \"Masukan dalam wadah semua bumbu\", \"Diamkan selama minimal 1 jam (semalaman juga lebih oke - di kulkas)\", \"Goreng dengan API kecil (saya goreng menggunakan happy call supaya tidak lengket)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1302, 4, 'Tim Ayam Bawang', 'Buat Tim Ayam Bawang yang nikmat dengan langkah-langkah mudah ini.', '[\"1 ekor ayam potong sesuai selera (saya potong 12)\", \"4 siung bawang merah iris tipis\", \"3 siung bawang putih iris tipis\", \"4 batang daun bawang potong serong\", \"1 buah bawang bombay ukuran sedang\", \"1 ruas jari jahe\", \"penyedap rasa ayam secukup nya\"]', '[\"Masukan ayam dan semua bahan kedalam 2ltr air.\", \"Masak dengan api sedang kurang lebih 30 menit.\", \"Tim ayam bawang siap di hidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1303, 4, 'Ayam richeese saos fire & keju', 'Sajian Ayam richeese saos fire & keju yang praktis dan lezat untuk dinikmati bersama.', '[\"Adonan ayam crispy:\", \"Tepung serbaguna\", \"7 sayap ayam\", \"1 Telur ayam kocok lepas\", \"Saos fire:\", \"2 sdm saos sambal\", \"2 sdm saos tomat\", \"3 sdm saos barbeque (delmonte)\", \"1 sdt minyak wijen\", \"1 sdm saos tiram\", \"3 siung bawang putih geprek\", \"1 sdm bon cabe\", \"1 sdt kecap manis\", \"Saos keju:\", \"100 ml susu uht full cream\", \"secukupnya Keju parut chedar\", \"1 sdm maizena (larutkan dengan air)\", \"Margarin\"]', '[\"Adonan ayam crispy: cuci bersih ayam (disini aku rebus dulu ayamnya biar mateng sempurna), kocok lepas telur. Ayam di celup ke adonan telur, lalu celup di adonan tepung serbaguna (untuk lebih crispy ulang 2x proses celup) goreng sampai ayam kecoklatan\", \"Saos fire: tumis bawang putih sampai harum dan kecoklatan, lalu campurkan semua bahan saus. Masak sampai mendidih\", \"Saos keju: panaskan margarin, masukan susu, keju, maizena aduk rata sampai kental dan mendidih (API KECIL)\", \"Masukan ayam crispy ke adonan saos fire. Aduk rata\", \"Ayam bbq ala richeese siap disajikan 😀\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1304, 2, 'Sup kembang tahu+bakso ayam', 'Cara membuat Sup kembang tahu+bakso ayam yang enak dan praktis untuk keluarga.', '[\"100 gram kembang tahu kering\", \"2 buah wortel potong dadu\", \"6 buah ceker ayam\", \"10 buah bakso ayam\", \"1 ltr air\", \"secukupnya Garam dan merica\", \"secukupnya Daun bawang\"]', '[\"Rendam kembang tahu dlm air kurleb 1-2 jam.rendam hgg kembang tahu jd lembut.ceker ayam cuci bersih buah kulit dan kukunya.\", \"Masak air dipanci hgg mendidih lalu masukkan ceker ayam dan wortel masak hgg empuk.\", \"Masukkan kembang tahu dan bakso ayam.masak hgg mengambang baksonya.tmbhkn garam dan merica lalu koreksi rasa.taburkan daun bawang diatasnya.\", \"Sup kembang tahu+bakso ayam siap disajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1305, 4, 'Ayam jamur barbecue', 'Hidangan ayam lezat: Ayam jamur barbecue untuk keluarga tercinta.', '[\"500 gr Sayap ayam\", \"100 gr Jamur campion\", \"1/2 siung bawang Bombay\", \"3 siung bawang putih\", \"1 sendok makan saus kikoman\", \"1 sendok makan saus tiram\", \"2 sendok makan saus barbecue\", \"1 sendok makan kecap manis\", \"Sejumput merica dan garam\", \"Minyak untuk menggoreng\", \"100 ml air\"]', '[\"Setelah ayam dicuci, lalu goreng ayam sampai kering lalu angkat\", \"Iris tipis semua bahan seperti jamur, bawang Bombay dan bawang putih lalu tumis semua bahan tambahkan genk saus, dan jangan lupa garam dan merica.\", \"Setelah tumis semua bahan, masukan air, lalu masukan ayam, tunggu sampai meresap lalu matikan api, lalu sajikan di pinggan.\", \"Hidangkan dengan nasi hangat, atau lainnya.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1306, 4, 'Ayam bumbu kuning', 'Resep Ayam bumbu kuning yang lezat dan mudah dibuat di rumah.', '[\"500 gr sayap ayam potong 2\", \"100 gr kelapa parut\", \"6 siung bawang merah\", \"4 siung bawang putih\", \"1 sdt kunyit bubuk / 2 cm kunyit\", \"secukupnya garam\", \"secukupnya merica\", \"1/2 sdt biji pala bubuk\", \"300 ml air\", \"minyak goreng\", \"2 batang sereh (memarkan)\", \"2 lembar salam\", \"2 cm lengkuas (digeprek)\"]', '[\"Haluskan bawang merah, bawang putih, garam, merica & kunyit\", \"Tumis bumbu halus dengan salam, sereh & lengkuas yg digeprek hingga harum\", \"Masukan potongan ayam yg sudah dicuci bersih kedalam tumisan bumbu hingga berubah warna\", \"Masukan kelapa parut hingga tercampur rata, masukan air matang. Masak hingga air surut, test rasa\", \"Ayam bumbu kuning siap disajikan, dapat dijuga digoreng menjadi ayam goreng serundeng. Selamat menikmati 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1307, 3, 'Semur Ati Ayam, Telur Puyuh, Tahu', 'Resep praktis Semur Ati Ayam, Telur Puyuh, Tahu yang bisa dicoba di rumah.', '[\"5 buah ati ayam, cuci bersih\", \"6 Butir telur puyuh, rebus lalu kupas\", \"3 buah tahu, potong melintang lalu goreng (jangan terlalu kering)\", \"1 buah tomat, potong-potong\", \"1 buah sereh, ambil putihnya, geprek\", \"1 buah daun salam\", \"2 cm lengkuas geprek\", \"3 sdm minyak goreng\", \"secukupnya Kecap manis\", \"secukupnya gula merah, garam, lada\", \"secukupnya air\", \"Bumbu Halus:\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"1 cm jahe\", \"1 cm kunyit\", \"2 butir kemiri\", \"1 buah cabai keriting\"]', '[\"Panaskan minyak goreng. Tumis bumbu halus,salam, sereh, lengkuas sampai harum. Setelah harum, masukkan ati ayam. Aduk sampai berubah warna.\", \"Masukkan air secukupnya. Tambahkan kecap,gula merah,garam lada. Masak ati sampai agak matang.\", \"Masukkan tahu, telur puyuh dan tomat. Masak sampai air agak menyusut. Jangan lupa cicipi rasa.\", \"Siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1308, 3, 'Soto Ayam Kampung', 'Cara membuat Soto Ayam Kampung yang enak dan praktis untuk keluarga.', '[\"1 kg ayam kampung\", \"1 batang serai geprek\", \"1 daun jeruk\", \"Daun seledri\", \"Daun bawang\", \"Bawang goreng\", \"Jeruk nipis\", \"Bumbu yg dihaluskan :\", \"7 siung bawang merah\", \"3 siung bawang putih\", \"2 ruas jari kunyit\", \"2 ruas jari jahe\", \"sedikit Laos\", \"secukupnya Merica bubuk\", \"Bahan pelengkap\", \"Bihun atau soun\", \"Gubis\", \"Kecambah\"]', '[\"Bersihkan dan potong ayam kampung sesuai selera\", \"Rebus ayam yg telah di bersihkan\", \"Tumis bumbu yg telah di haluskan, tambahkan serai dan daun jeruk. Tumis sampai harum dan berubah warna\", \"Masukkan bumbu yg sudah di tumis ke dalam air rebusan ayam.. tambahkan irisan daun seledri dan daun bawang. Beri garam, gula, merica bubuk dan kaldu ayam bubuk bila suka.. tes rasa\", \"Terakhir taburi bawang merah goreng.. soto ayam kampung siap dihidangkan bersama soun, gubis dan kecambah...\", \"Selamat mencoba momm\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1309, 3, 'Mie ayam by dapur mama R&M', 'Mie ayam by dapur mama R&M - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"Ayam (saya pakai separuh dada ayam)\", \"1 bungkus mie telor\", \"Secukupnya pokcoy\", \"Secukupnya daun bawang\", \"1 lembar daun salam\", \"Secukupnya air\", \"Secukupnya gula\", \"Secukupnya garam\", \"Secukupnya kecap\", \"Penyedap rasa (optional)\", \"3 siung bawang putih\", \"2 siung bawang putih (geprek)\", \"4 siung bawang merah\", \"1/2 sdt ketumbar\", \"2 butir kemiri\", \"1 ruas kunyit\", \"Lada bubuk\"]', '[\"Cuci ayam lalu rebus sampai stgh matang.sisihkan ayam dari air kaldunya.\", \"Lalu suwir2 ayam atau potong kecil2.sisihkan.\", \"Masukkan bawang putih geprek,lada bubuk,penyedap,irisan daun bawang kedalam kuah kaldu,masak lagi.test rasa.matikan api\", \"Siapkan bumbu halus : bawang putih,bawang merah,kemiri,ketumbar,kunyit.tumis bersama daun salam smp wangi.beri air secukupnya.masukkan suwiran ayam.beri kecap,garam,gula,penyedap.test rasa.masak smp matang.\", \"Rebus air smp mendidih lalu masukkan daun pokcoy sebentar,tiriskan.\", \"Siapkan mie telor dalam wadah,lalu siram dengan air mendidih,tunggu smp empuk.tiriskan.\", \"Penyajian : tata mie dalam mangkok,beri daun pokcoy,tumisan ayam,daun bawang,siram dengan kuah kaldu.tambah saos dan kecap.\", \"Mie ayam siap dinikmati\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1310, 2, 'Steak ayam saos lada Hitam', 'Buat Steak ayam saos lada Hitam yang nikmat dengan langkah-langkah mudah ini.', '[\"4 filetan dada ayam\", \"Bumbu untuk ayamnya :\", \"1/2 sdt lada hitam\", \"1/2 sdt royco ayam\", \"1/2 sdt bubuk bawang putih\", \"Bahan tepung :\", \"100 gram tepung\", \"1/2 sdt lada\", \"1/2 sdt royco\", \"1/2 sdt bawang putih\", \"1-2 butir telur (bisa di skip)\", \"Minyak untuk menggoreng\", \"Wijen sangrai untuk hiasan\", \"Wortel, kentang, buncis untuk lalapan\", \"Bahan saos :\", \"2 sdm saos tiram\", \"1 buah bawang bombay\", \"4 siung bawang putuh\", \"1/2 sdm royco\", \"1/2 sdm gulpas\", \"1/2 sdt lada hitam bubuk\", \"Larutan meizena\", \"1 gelas kecil air\"]', '[\"Langkah pertama : cuci bersih ayam dan fillet bagian dadanya.. lalu sisihkan kalau mau bagian paha bisa ya sesuai selera.\", \"Beri bumbu lada hitam, bubuk Bawang putih dan royco kedalam ayam lalu kacak / aduk merata. Diamkan di dalam kulkas selama 15 menit sampai bumbu benar benar meresap.\", \"Langkah ke 2. Campurkaan tepung terigu, tepung beras, royco, lada, dan bubuk bwg putih menjadi satu aduk rata.\", \"Ambil ayam yang sudah di diamkan tadi balurkan ke tepung dan masukan ke telur balurkan lagi ke tepung dan ke telur dan balurkan lagi ke tepung sampai ketebalan yang di inginkan.\", \"Goreng ayam sampai bewarna kekuningan lalu angkat dan tiriskan di tempat yang sudah di alasi tisu\", \"Next siapkan bahan untuk saos. Potong2 bawang bumbay dan putih tumis sampai harum beri air dan masukan saos tiram, gulpas, royco, dan lada bubuk.. cicipin\", \"Jika dirasa sudah pas masukan larutan meizena atau tepung beras masak sampai kental dan matikan kompor\", \"Next.. potong potong wortel, buncis dan kentang lalu rebus setengah empuk masak tiriskan dan tata di piring dan taruh ayum lalu tuang saos di atasnya\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1311, 2, 'Ayam saos nanas pedas manis', 'Cara membuat Ayam saos nanas pedas manis yang enak dan praktis untuk keluarga.', '[\"Bahan 1 :\", \"400 gr dada ayam filet\", \"1 sdm tepung maizena\", \"Kecap asin\", \"Bahan 2:\", \"2 sdm saos pedas\", \"1-2 sdm minyak wijen\", \"2 sdm kecap manis\", \"2 sdm saos tiram\", \"secukupnya Lada bubuk\", \"Bahan 3:\", \"3 bh Bawang putih\", \"1 bawang bombay potong kotak\", \"1 paprika potong kotak (sy pakai cabe merah)\", \"Bbrp potong nanas\", \"secukupnya Gula dan garam\"]', '[\"Bahan 1 dicampur..diamkan 1 jam lalu digoreng hingga kecoklatan\", \"Bahan 2 dicampur n diaduk dalam 1 wadah terpisah. Sisihkan\", \"Tumis bawang putih hingga harum.. tambahkan ayam yang telah digoreng dan bumbu saos kemudian diaduk\", \"Koreksi rasa..\", \"Tambahkan bawang bombay dan paprika sesaat sebelum diangkat. Terakhir masukan potongan Nanas. Sajikan dengan nasi hangat\", \"Selamat mencoba..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1312, 3, 'Ayam Santan Ngamuk', 'Nikmati kelezatan Ayam Santan Ngamuk dengan resep sederhana ini.', '[\"Ayam 1/2 kg,potong sesuai selera\", \"6 siung Bawang putih\", \"4 siung Bawang merah\", \"2 ons Cabe merah\", \"secukupnya Gula merah\", \"1 sendok Kecap manis\", \"3 lembar Daun jeruk\", \"Kemiri 4 butir,goreng\", \"Jeruk limau\", \"1 bungkus Lada bubuk\", \"secukupnya Santan kental\", \"1/2 sendok Gula pasir\", \"secukupnya Garam\", \"secukupnya Air\"]', '[\"Cuci bersih ayam,rendam dengan perasan air jeruk,diam kan sesaat\", \"Giling cabe merah,bawang merah,bawang putih,kemiri sampai halus\", \"Tumis bumbu yg sudah dihaluskan hingga harum\", \"Masukkan daun jeruk,gula merah,garam, lada bubuk,gula pasir,dan air\", \"Tunggu hingga mendidih\", \"Bila telah mendidih masukkan ayam,masak hingga kuah surut dengan api kecil\", \"Kemudian tambah kan santan kental dan air secukupnya lagi\", \"Masak kembali sampai bumbu meresap\", \"Tambah kan kecap manis,koreksi rasa\", \"Apabila bumbu sudah mulai surut dan daging telah empuk,angkat\", \"Sajikan\", \"Selamat mencoba😁🙏\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1313, 2, 'Ayam asam manis', 'Ayam asam manis dengan bumbu meresap sempurna.', '[\"3 iris ayam (potong kecil2 sesuai selera)\", \"Secukupnya tepung serbaguna\", \"1 biji telur\", \"Bahan saos :\", \"2 buah cabe merah besar (buang biji, iris memanjang)\", \"1 buah bawang bombay\", \"3 siung bawang putih\", \"Secukupnya wortel (iris memanjang)\", \"Secukupnya kacang polong\", \"5 sdm saus tomat\", \"1 sdm saos sambal\", \"Secukupnya tepung maizena (dilarutkan)\"]', '[\"Ayam yang telah dipotong kecil dicelupkan ke dlm telur kemudian balurkan ke dlm tepung serbaguna, kemudian goreng hingga coklat keemasan.\", \"Untuk membuat saos, tumis bawang putih dan bawang bombay hingga layu kemudian masukkan saos tomat dan saos sambal aduk rata.\", \"Tambahkan air secukupnya, kemudian larutan maizena, aduk rata.\", \"Masukkan potongan wortel, cabe merah dan kacang polong, beri gula, garam dan penyedap.\", \"Terakhir masukkan ayam yang telah digoreng tadi, aduk sebentar hingga merata.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1314, 3, 'Ayam bumbu Betutu', 'Resep Ayam bumbu Betutu ala rumahan yang dijamin menggugah selera.', '[\"1/2 ekor ayam kampung\", \"10 bawang merah\", \"6 bawang putih\", \"1 ruas lengkuas\", \"15 cabe rawit merah\", \"6 cabe merah\", \"5 kemiri\", \"Kunyit (secukupnya)\", \"1 sdt ketumbar\", \"1 terasi abc\", \"Sereh\", \"2 daun jaruk\", \"2 daun salam\"]', '[\"Haluskan cabai, bw merah, bw putih, kemiri, ketumbar, lengkuas, kunyit, terasi, garam, gula, penyedap (kecuali sereh,daun salam, dan daun jeruk)\", \"Cuci bersih ayam, potong sesuai selera\", \"Tumis bumbu halus (saya ngehalusinnya pake blender), masukan sereh, daun salam, daun jeruk.. tumis hingga matang dan harum\", \"Kalau sudah matang, masukan potongan ayam, tambahkan air, tunggu hingga airnya surut dan meresap\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1315, 4, 'Siomay Ayam Udang', 'Siomay Ayam Udang dengan bumbu meresap sempurna.', '[\"150 gr ayam, blender\", \"150 gr udang cincang kasar\", \"1 btr telur\", \"1 btr bawang putih, blender bersama ayam\", \"1 bh wortel parut, sisihkan sedikit u/ taburan\", \"1 btg daun bawang\", \"1 sdm saus tiram\", \"1 sdm minyak wijen\", \"Garam\", \"Merica\", \"Kulit siomay\"]', '[\"Campur semua bahan aduk rata.\", \"Oles minyak kulit siomay sblm diisi.\", \"Beri taburan wortel lalu kukus (kukusan yg telah dipanaskan sebelumnya) 15 menit api sedang.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1316, 4, 'Ayam Kecap Manis Cabai', 'Ayam Kecap Manis Cabai - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"500 gr ayam\", \"3 siung bw putih, geprek cincang\", \"1 bh cabe merah besar, iris serong\", \"1/2 sdt merica bubuk\", \"3-4 sdm kecap manis\", \"200 ml air\", \"Secukupnya garam\", \"3 sdm minyak sayur\", \"Secukupnya daun bawang, utk taburan\"]', '[\"Tumis bw putih, cabe dan merica bubuk hingga layu dan baput agak kecokelatan\", \"Masukkan ayamnya, aduk hingga berubah warna\", \"Beri kecap manis lalu tuang air, bubuhi garam secukupnya, aduk rata lalu tutup wajan hingga airnya sat dan bumbu meresap\", \"Sajikan lalu taburi dgn daun bawang\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1317, 2, 'Spicy chicken wings keto/low carb', 'Cara membuat Spicy chicken wings keto/low carb yang enak dan praktis untuk keluarga.', '[\"1/2 kg sayap ayam belah dua\", \"bumbu rendam :\", \"4 siung bwg putih haluskan (garlic powder kl ada,sy blm ada...)\", \"1 sdt lada bubuk (lada hitam)\", \"secukupnya garam\", \"cabe bubuk 1 sdm,tambahkan bila ingin lebih pedas\", \"bumbu siram:\", \"1 s/d 2 sdm butter\", \"1 s/d 2 sdm kecap tropicana slim\", \"1 sdm kecap asin\", \"1 sdm atau lebih cabe bubuk\", \"secukupnya garam\", \"secukupnya air matang\", \"minyak goreng untuk menggoreng\"]', '[\"Potong sayap ayam jadi 2 bagian lalu cuci bersih dan tiriskan\", \"Siapkan serbet bersih/kain tuangkan ayam ke serbet lalu tekan2 hingga ayam tidak basah (kunci ayam jd crispy)\", \"Setelah ayam di serap airnya simpan dalam mangkok lalu beri bumbu rendaman masukan kulkas dan diamkan selama 25 menit agar bumbu meresap\", \"Siapkan wajan tuang minyak goreng, goreng ayam dengan deep fried atau minyak banyak. gunakan api sedang cenderung kecil agar ayam matang di dalam dan crispy di luar, memang agak lama.setelah matang lalu angkat dan tiriskan.\", \"Siapkan wajan masak bumbu siram, tumis butter,lalu masukan bumbu yg lain beri air secukupnya.tunggu agak kental /menyusut\", \"Masukan ayam ke wajan bumbu siram. aduk2 sebentar lalu angkat.\", \"Tunggu sebentar lalu sajikan, kulitnya crispy dan dalamnya matang. selamat mencoba.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1318, 4, 'Ayam Pedas Kemangi', 'Sajian Ayam Pedas Kemangi yang praktis dan lezat untuk dinikmati bersama.', '[\"1 kg ayam\", \"2 ikat daun kemangi\", \"1 batang serai (geprak)\", \"2 lembar daun salam\", \"2 lembar daun jeruk\", \"1 ruas jari laos (geprak)\", \"Jeruk nipis\", \"Gula\", \"Garam\", \"Merica bubuk\", \"Kaldu ayam\", \"Bumbu halus :\", \"2 siung bawang putih\", \"6 siung bawang merah\", \"2 cabe merah besar\", \"20 cabe rawit atau sesuai selera\", \"1 butir kemiri\", \"Sejumput kecil ketumbar\", \"1 ruas jari jahe\", \"2 ruas jari kunyit\"]', '[\"Lumuri ayam yg telah di bersihkan dengan jeruk nipis perah, garam, dan merica bubuk (diamkan selama 10 menit)\", \"Tumis bumbu2 yg telah di haluskan. Tambahkan serai, daun salam, daun jeruk, dan laos yg telah di geprak (tumis sampai harum dan berubah warna)\", \"Goreng ayam yg telah di bumbui sampai setengah matang\", \"Masukkan ayam yg telah di goreng setengah matang ke dalam bumbu yg sedang di tumis.. tambahkan 300 ml air atau sesuai selera.. masak hingga air menyusut.. masukkan daun kemangi. Tambahkan gula, garam, kaldu ayam bubuk sesuai selera. Tes rasa\", \"Sajikan selagi hangat 😊😊😊 jgn lupa magic com nya di dekatkan yaa biar klo nambah nasi ga jauh2 ambilnya... selamat mencobaa\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1319, 3, 'Sup Ayam Segarrrrr', 'Resep praktis Sup Ayam Segarrrrr yang bisa dicoba di rumah.', '[\"2 Dada Ayam Cuci Bersih n Iris Kotak (Dadu)\", \"Secukupnya Air\", \"Secukupnya Garam Halus\", \"Secukupnya Gula Pasir\", \"Secukupnya Merica Butir\", \"Secukupnya Daun Bawang, Cuci Bersih n Iris Sesuai Selera\", \"Seledri Secukupnya, Cuci Bersih n Iris Sesuai Selera\", \"2 Batang Serai,Cuci Bersih n Geprek\", \"3 Lembar Daun Salam, Cuci Bersih\", \"3 Lembar Daun Jeruk,Cuci Bersih\", \"1 Ruas Jahe, Kupas,Cuci Bersih n Geprek\", \"Bumbu Yg DiGoreng Hingga Layu:\", \"9 Siung Bawang Merah Kupas n Cuci Bersih\", \"7 Siung Bawang Putih Kupas n Cuci Bersih\", \"Sayuran:\", \"100 Grm Wortel Kupas, Cuci Bersih n Iris Sesuai Selera\", \"100 Grm Kembang Kol,Petik Dr Kuntumnya n Cuci Bersih\", \"100 Grm Kentang Kupas n Cuci Bersih n Iris Sesuai Selera\", \"50 Grm Buncis, Bersihkan Bagian Pinggirnya n Cuci Bersih\"]', '[\"Didihkan Air, Setelah Air Mendidih Rebus Ayam, Rebus Dengan Api Kecil, Setelah Mendidih Buang Rebusan Pertama n Rebus Untuk Yang KeDua Kalinya,,,\", \"Sembari Menunggu Rebusan Ayam Yang KeDua Mendidih, Ulek Bumbu Yang Sudah Di Goreng Hingga Layu Dengan Merica, Ulek Hingga Lembut,,,\", \"Setelah Rebusan KeDua Mendidih Tambahkan Bumbu Yang Sudah Di Ulek Juga Serai,Daun Salam, Daun Jeruk n Jahe, Setelah Mendidih Tambahkan Kentang n Wortel Biarkan Dulu Hingga Lunak Setelah Itu Tambahkan Kembang Kol n Buncis Biarkan Lagi Hingga Mendidih, Lalu Terakhir Tambahkan Daun Bawang n Seledri Juga Garam n Gula Pasir Secukupnya, Koreksi Rasa Jika Sudah Pas Matikan Kompor\", \"Pas BGT,,, Lagi Gak Enak Badan,,, Buat Sarapan Sayurnya Sup Ayam,,, Berasa BGT Rempahnya,,, Segarrrrr...\", \"Sehat Karena Tanpa MSG Atau Pun Penyedap Instan Lainnya,,,\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1320, 4, 'Steak ayam panir keju', 'Sajian Steak ayam panir keju yang praktis dan lezat untuk dinikmati bersama.', '[\"1 buah dada ayam filet. Iris menjadi 2 bagian\", \"secukupnya Tepung terigu\", \"1 butir telur. Kocok lepas\", \"2 sdm cabe bubuk\", \"secukupnya Tepung panir\", \"100 gr keju parut (blh di skip)\", \"Bahan marinate:\", \"secukupnya Susu cair\", \"secukupnya Garam\", \"secukupnya Merica\", \"4 siung bawang putih, haluskan\"]', '[\"Marinate dada ayam dgn bumbu marinate kira2 30 menit\", \"Udelin ayam dgn tepung terigu, masukkan ke dlm kocokan telur, lalu udelin ke campuran tepung panir\", \"Oh ya, tepung panirnya di campur dgn parutan keju & cabe bubuk ya\", \"Goreng dgn api sedang supaya warnanya tdk terlalu hitam seperti buatan saya he he.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1321, 3, 'Grilled chicken breast', 'Resep Grilled chicken breast yang lezat dan mudah dibuat di rumah.', '[\"1/2 potong dada ayam fillet\", \"Secukupnya bawang bombay iris memanjang\", \"Secukupnya paprika merah iris memanjang\", \"1 siung bwg putih cincang\", \"Secukupnya keju melted\", \"1/2 sdt garam,\", \"Secukupnya lada\", \"Minyak sayur / olive\", \"Hiasan:\", \"1 lbr selada\", \"5 bh tomat kecil\"]', '[\"Belah2 dada ayam (tp jgn samlai putus)\", \"Beri garam, merica, saya tmbh bubuk paprika, dan bawang putih cincang diamkan 15mnt\", \"Selipkan bawang bombay, paprika dan keju di tiap belahan\", \"Panaskan oven 200 derajat, beri minyak pada alas dan potongan ayam, panggang slama 20 menit\", \"Hias piring dg selada dan tomat, bs tmbh kentang jika mau..lalu letakan dada ayam di tengah..\", \"Grilled chicken siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1322, 4, 'Sambal ayam penyet', 'Buat Sambal ayam penyet yang nikmat dengan langkah-langkah mudah ini.', '[\"Ayam goreng (resep ungkepnya ada di resep ku yg lain ya)\", \"Daun singkong (klop banget sm lalapan rebusan daun singkong loh)\", \"15-20 Cabe orens\", \"1-2 bawang putih\", \"Minyak panas\", \"Royco (rasa sapi)\", \"Garam\", \"Gula pasir (yg ga pengen terlalu pedas boleh pake gula dikit)\"]', '[\"Cuci bersih cabe dan bawang putih,ulek kasar di cobek\", \"Panaskan minyak lalu tuang ke cobek ya\", \"Bumbuin garam sedikit,royco sapi dan gula (optional)\", \"Ulek lg sambil di aduk2.tes rasa\", \"Kalo udah pas,bejek2 ayam goreng nya di atas sambal\", \"Sajikan dg nasi panas bertabur bawang goreng.lalapannya rebusan daun singkong,di jamin keringetan dan nasi nya harus banyak ya karena pasti nambah2 trs hehehe\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1323, 2, 'Chicken Pop Bumbu Sambel Bawang Tumis', 'Nikmati kelezatan Chicken Pop Bumbu Sambel Bawang Tumis dengan resep sederhana ini.', '[\"1/4 kg Dada Ayam\", \"Jeruk nipis\", \"1 1/2 bks Tepung serbaguna\", \"Bahan Sambel :\", \"15 Siung bawang merah\", \"1 Siung bawang putih\", \"3 biji cabe rawit (sesuai selera)\", \"1 biji cabe keriting\", \"2 buah tomat\", \"Lain-lain :\", \"Minyak goreng\", \"Garam\", \"Mecin\", \"Gula\", \"Terasi\"]', '[\"Potong-potong dadu ayam, kemudian cuci bersih. Setelah itu, rendam ayam dengan air perasan jeruk nipis, lalu diamkan selama 15 menit.\", \"Sambil menunggu, siapkan bumbu sambelnya. Iris-iris semua bahan dan sisihkan.\", \"Setelah bumbu siap, siapkan tepung basah (jangan terlalu encer) dan tepung kering di dalam wadah yang berbeda.\", \"Cuci bersih kembali ayam yang tadi direndam. Kemudian, masukkan ke dalam tepung basah. Setelah itu, pindahkan ke tepung kering dan lumurin ayam hingga merata.\", \"Panaskan minyak goreng hingga benar-benar panas. Lalu goreng ayam hingga berwarna keemasan. Lalu, sisihkan.\", \"Setelah itu, panaskan minyak lagi dan tumis semua bumbu sambal hingga matang. Tambahkan garam, mecin, gula dan terasi secukupnya. Tes rasa.\", \"Kecilkan api, lalu masukkan semua ayam, lalu aduk hingga rata. Sajikan, sangat pas dimakan dengan nasi hangat. \"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1324, 3, 'Ayam Ukep Bumbu Bebek', 'Sajian Ayam Ukep Bumbu Bebek yang praktis dan lezat untuk dinikmati bersama.', '[\"1 kg ayam segar bersih\", \"3 siung bawang merah (a)\", \"7 siung bawang putih (a)\", \"1/2 sdm ketumbar (a)\", \"1 ruas kunir (1 cm) (a)\", \"1/2 cm jahe hanya supaya ayam tdk amis (a)\", \"2 btg sereh (digeprek)\", \"5 lbr daun jeruk\", \"Lengkuas diparut,jmlh sesuai selera(saya skip krn gaada parutan)\", \"Garam\"]', '[\"Haluskan/blender semua bahan (a). Masukkan ayam ke dalam panci bersama bumbu (a), parutan laos, sereh, daun jeruk, garam (sesuai selera, kalo saya suka yg asin ntar bumbunya bisa digoreng juga). Jgn lupa kasih air kira-kira 2 gelas supaya tdk kebanyakan air.\", \"Rebus dgn api sedang sampai ayam matang jgn lupa diaduk. Rebus sampai air agak menyusut dan kuah kental dgn bumbu.\", \"Goreng ayam & sajikan 😄 (bumbu, sereh & daun jeruknya jg saya goreng jg sampai crispy kress kress dimakan pake nasi anget enak 😋)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1325, 4, 'Soto ayam special', 'Buat Soto ayam special yang nikmat dengan langkah-langkah mudah ini.', '[\"1/2 kg ayam kampung\", \"1/4 kg jeroan ayam\", \"1/2 kg kentang\", \"5 telur ayam\", \"1/4 kg bwg merah buat taburan\", \"1/4 kg bwg putih buat taburan\", \"1/4 kg toge kecil\", \"Seledri\", \"Jeruk nipis\", \"Bumbu :\", \"1/4 kg bwg merah\", \"1/4 kg bwg putih\", \"Lengkuas\", \"Kunyit\", \"Kemiri\", \"Jahe\", \"Serai\", \"Daun jeruk\"]', '[\"Bwg merah putih,kunyit,lengkuas,kemiri,jahe halus kan\", \"Tumis bersamaan dg serai dan daun jeruk sampai harum\", \"Rebus ayam,masukan bumbu yg uda ditumis sampai mendidih\", \"Angkat ayam.goreng bersamaan dg jeroan ayam\", \"Siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1326, 4, 'Ayam Goreng Tepung', 'Sajian Ayam Goreng Tepung yang praktis dan lezat untuk dinikmati bersama.', '[\"5 potong paha ayam\", \"4 siung bawang putih, dihaluskan\", \"secukupnya Garam\", \"secukupnya Lada\", \"Kaldu bubuk (optional, klo bisa yg non msg ya soalnya buat anak)\", \"1 btr telur\", \"Bahan pelapis :\", \"4 sdm Tepung terigu\", \"2 sdm tepung maizena\", \"Garam secukupnya (diresep aslinya gak pake garam)\"]', '[\"Cuci bersih ayam lalu tusuk2 dgn garpu dagingnya (supaya bumbu meresap dan ketika digoreng bagian dalamnya jg matang) dan lumuri dengan bawang putih halus, garam, lada, kaldu bubuk campur rata\", \"Masukan kedalam lemari es selama bbrp jam (semakin lama semakin meresap bumbunya)\", \"Ketika ingin digoreng beri telur dan campur rata\", \"Lalu masukan kedalam wadah tepung terigu dan maizena yg sdh dicampur jd satu, tekan2 dan agak dicubit2 tepungnya supaya permukaannya keriting/kriuk\", \"Goreng dgn api kecil dan minyak yg agak banyak sampai ayam tenggelam supaya ayam matangnya merata\", \"Selamat mencoba... 😉\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1327, 2, 'Soto ayam', 'Resep Soto ayam ala rumahan yang dijamin menggugah selera.', '[\"350 gr ayam\", \"Bumbu :\", \"5 bawang merah\", \"3 bawang putih\", \"Kunyit seruas jari\", \"seruas Lengkuas\", \"seruas Jahe\", \"Gula\", \"Garam\", \"Kaldu ayam\", \"Lada\", \"sedikit Ketumbar\", \"1 Sereh geprek\", \"2 daun salam\", \"Isian :\", \"Kol iris tipis\", \"iris Daun sop\", \"Tauge\", \"Bawang goreng\"]', '[\"Goreng ayam yang dimarinasi dengan lada dan garam\", \"Blender bumbu. Kemudian di tumis dengan ditambah sereh dan daun salam\", \"Masukkan bumbu yang sudah ditumis ke air. Masak hingga mendidih. Beri gula, garam, kaldu. Cek rasa\", \"Taruh isian dimangkuk, siram dengan kuah panas. Ayam yang sudah digoreng disuwir ya mom.\", \"Tambahkan bawang goreng, sambal dan perasan jeruk (opsional).\", \"Soto ayam segar siap dinikmati bersama keluarga tercinta\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1328, 4, 'Nugget ayam simpel', 'Nugget ayam simpel - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"500 gr ayam giling\", \"6 buah bawang merah\", \"4 bawang putih\", \"2 sdm tepung kanji\", \"3 sdm tepung oatmeal\", \"2 telur ayam\", \"Brokoli\", \"Wortel\", \"Garam\", \"Kaldu jamur\", \"Bahan celup\", \"2 telur\", \"Tepung roti\"]', '[\"Ulek bawang sampai halus. Sayuran di parut (secukupnya)\", \"Campur ke dalam ayam giling. Campurkan semua bahan aduk sampai rata\", \"Siapkan wadah untuk mencetak adonan. Masukan kedalam kukusan. Tunggu sampai matang (kurleb 30menit)\", \"Jika sudah matang. Potong sesuai selera. Celupkan kedalam bahan celup.\", \"Masukan kedalam kulkas.tunggu minimal 30menit\", \"Baru goreng nugget sesuka hati\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1329, 2, 'Ayam Goreng ala Kentucky', 'Ayam Goreng ala Kentucky - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 ekor ayam negeri (potong 8)\", \"300 gr tepung terigu (segitiga biru)\", \"100 gr tepung maizena\", \"4 siung bawang putih halus (bisa juga garlic powder)\", \"1 sdt Baking powder\", \"Garam\", \"Lada putih bubuk\", \"Lada hitam dihaluskan\", \"Ketumbar bubuk\", \"Kaldu bubuk\", \"Cabe bubuk\", \"1 butir telur ayam\", \"1 sachet dancow putih\", \"1 sdm cuka dapur/jeruk nipis/lemon\", \"150 ml air hangat\"]', '[\"Marinasi Ayam dengan 1sdm garam, 1sdm lada putih, lada hitam, 1sdt kaldu bubuk, bawang putih, 1sdm ketumbar bubuk dan 1sdm cabe bubuk.\", \"Buttermilk untuk rendaman ayam: campur susu dancow dengan 250ml air hangat lalu masukan cuka dapur dan aduk hingga terbentuk gumpalan2 kecil dari susu\", \"Masukkan telur kedalam cairan buttermilk lalu kocok dan tambahkan baking powder\", \"Masukkan campuran buttermilk dan telur kedalam ayam dan ratakan\", \"Diamkan selama minimal 12 jam di dalam kulkas, makin lama marinasi maka bumbu semakin meresap dan juicy\", \"Setelah 12 jam keluarkan dari kulkas\", \"Campurkan terigu dan maizena dalam wadah\", \"Tambahkan garam, kaldu bubuk, lada putih, ketumbar bubuk, cabe bubuk (masing2 1sdt)\", \"Aduk tepung dan bahan bubuk hingga rata\", \"Masukkan ayam kedalam tepung, lalu balur sampai permukaan ayam tertutup tepung\", \"Tips jangan menekan dgn kuat atau pijat daging ayam ketika penepungan karena hasilnya akan bantet\", \"Masukkan kembali ayam ke rendaman buttermilk, kemudian pindahkan ke tepung lagi\", \"Bolak balikkan ayam di tepung hingga tepung menempel dengan sempurna\", \"Masukkan ayam kedalam minyak yang sudah benar2 panas dan banyak hingga semua bagian ayam terendam\", \"Goreng dengan api kecil selama 12-14menit dipastikan daging matang sampai kedalam\", \"Setelah berwarna coklat keemasan angkat lalu tiriskan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1330, 3, 'Opor ayam kuah Susu... 🐥🐓🍶', 'Cara membuat Opor ayam kuah Susu... 🐥🐓🍶 yang enak dan praktis untuk keluarga.', '[\"1/2 ekor ayam\", \"6 siung bwg merah\", \"5 siung bawang putih\", \"2 buah cabe merah\", \"10 buah cabe rawit merah utuh\", \"2 buah kemiri\", \"1/2 ruas kunyit\", \"1 ruas jahe\", \"2 lembar daun salam\", \"Ketumbar bubuk\", \"1/4 sdt Jintan\", \"secukupnya Lada bubuk\", \"Garam, gula Pasir,kaldu bubuk rasa ayam secukupnya.\", \"500 ml Susu Cair (saya pakai ultra low fat)\", \"Secukupnya air mateng\"]', '[\"Haluskan bwg merah, bwg putih,kemiri,jintan,kunyit,jahe,cabe merah, Ketumbar (utuh),Atau bisa gunakan yg bubuk.. Sisihkan\", \"Cuci bersih ayam.. Lumuri jeruk nipis diamkan sekitar 20 menit kemudian bilas\", \"Rebus ayam sampai aga empuk.. Buang airnya..\", \"Tumis Bumbu halus masukkan daun salam,tumis sampai wangi dan matang tambahkan air.. Aduk rata masukkan ayam.. Tambahkan gula, Garam, Lada bubuk..masak sampai air aga asat..masukkan cabe rawit merah utuh..lalu Tambahkan Susu Cair.. Masukkan kaldu bubuk.. Koreksi rasa.. Masak dgn api kecil sampai keluar minyak ayam nya.. Tambahkan sedikit susu cair lgi.. Masak hingga Kental..\", \"Setelah matang.. Angkat dan sajikan dgn taburan bawang goreng.. Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1331, 3, 'Ayam Krispy Sambal Matah', 'Resep Ayam Krispy Sambal Matah ala rumahan yang dijamin menggugah selera.', '[\"Bahan ayam Krispy:\", \"2 buah paha atas ayam\", \"1 sachet tepung bumbu merek apa saja ukuran sedang\", \"1 butir telur ayam\", \"1 buah jeruk nipis\", \"secukupnya Garam, merica, penyedap\", \"Bahan sambal matah :\", \"10 buah bawang merah\", \"2 buah cabe rawit (atau sesuai selera)\", \"1/2 sdt terasi\", \"2 sdm minyak goreng\", \"1 buah jeruk nipis\", \"secukupnya Garam, gula, penyedap\"]', '[\"Iris sebanyak 2 irisan pada bagian daging paha atas ayam (agar bagian dalam ayam cepat matang), kemudian taburkan garam, merica, penyedap secukupnya, peraskan jeruk sambil aduk2, diamkan sebentar..\", \"Sambil menunggu kupas dan potong2 bawang merah, cabe rawit, kemudian masukkan ke mangkok kecil, lalu tabur sejumput kecil garam, gula, penyedap pada potongan bawang merah\", \"Panaskan minyak,masukkan terasi, sambil aduk2 sampe minyak terasa sudah panas, kemudian tuang keatas potongan bawang, lalu segera diaduk2. Peraskan jeruk nipis. Sambal matah sudah jadi, sisihkan..\", \"Siapkan telur dan tepung bumbu di wadah yang berbeda. Panaskan minyak untuk mengoreng di wajan.\", \"Ambil ayam, celupkan ke telur sampai merata, lalu pindah celupkan di tepung sampai merata, lalu ulang sekali lagi celup ke telur dn tepung, kemudian masukkan ke penggorengan.\", \"Goreng dengan api kecil, jangan tll besar, agar di dalam matang terlebih dlu. Waktu memasak ayam krispy kurang lebih 20-30menit dg api kecil agar matang sampai kedalam.\", \"Setelah matang, angkat, siapkan di piring lalu taburkan sambal matah. Bon apetite!\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1332, 3, 'Ayam Suwir Sambal Matah', 'Resep praktis Ayam Suwir Sambal Matah yang bisa dicoba di rumah.', '[\"1/2 ekor ayam\", \"5 bawang merah\", \"8 buah cabai merah\", \"3 cabai rawit\", \"1/2 bungkus terasi ABC: dibakar lalu haluskan\", \"1 lbr daun jeruk\", \"1 btg serai\", \"1/2 bh jeruk limau\", \"Secukupnya garam, gula, penyedap rasa (opsional)\", \"Secukupnya minyak untuk menumis\"]', '[\"Bersihkan ayam dan lumuri dg air jeruk nipis. Kukus ayam hingga empuk. Dinginkan dan suwir-suwir.\", \"Ulek kasar : bawang merah,cabai merah dan cabai rawit. Tambahkan terasi.\", \"Tumis bahan yg sudah dihaluskan dengan daun jeruk dan serai. Tambahkan ayam suwir. Bumbui dg garam, gula dan penyedap sesuai selera. Kucuri dg perasaan jeruk nipis. Tuang sedikit air.\", \"Masak hingga bumbu meresap.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1333, 4, 'Ayam brokoli saus teriyaki', 'Cara membuat Ayam brokoli saus teriyaki yang enak dan praktis untuk keluarga.', '[\"1/2 kg dada ayam\", \"1 ons Brokoli\", \"1/2 bawang bombay\", \"2 siung bwg putih\", \"2 siung bwg merah\", \"2 cabe besar merah\", \"2 cabe rawit ijo, (harusnya pake cabe rawit pedas tapi gk ada)\", \"Saos Teriyaki bungkus kecil saori\", \"1 sendok saos tiram\", \"1 sdt royco\", \"1/2 sdt gula\", \"1/2 sdt garam\"]', '[\"Dada ayam dicuci bersih kemudian di rendam jeruk nipis 15 menit,\", \"Setelah itu dada ayam di potong dadu sesuai selera.\", \"Brokoli di potong\\\" kemudian cuci bersih, rendam dulu dengan air garam sebentar kemudian bilas.\", \"Dada ayam direbus dulu sebentar biar gak keras, setelah direbus dimarinate dulu pakai 2 sdm saos teriyaki selama 30 menit.\", \"Potong potong bwg bombay, bwg merah, bwg putih dan cabe.\", \"Kemudian ditumis sampai harum,\", \"Masukkan ayam yg sudah dimarinate 30 menit dikulkas, kemudian masukan brokoli juga\", \"Tambahakan gula garam royco saori Teriyaki 1 sdm, saori saos tiram 1 sdm. Dan air secukupnya sesuai selera.\", \"Diaduk kemudian tes rasa, untuk air sesuai selera aja ya.\", \"Setelah matang angkat dan sajikan.\", \"Selamat makan dan selamat mencoba 😉\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1334, 2, 'Ayam KFC ala NR', 'Resep praktis Ayam KFC ala NR yang bisa dicoba di rumah.', '[\"500 gr tepung roti\", \"250 gr tepung bumbu sajiku\", \"2 butir telur\", \"1 ekor ayam\", \"100 ml air es\", \"1 sdt garam\", \"1 sdt lada\", \"1 ltr myk grg\"]', '[\"Potong ayam lalu cuci hingga bersih n tiriskan\", \"Campurkan tepung terigu tepung bumbu sajiku,garam n lada bubuk di dlm baskom\", \"Campurkan 2 butir telor dgn air es n kocok hingga berbusa\", \"Celupkan ayam kedlm kocokan telur trus celupkan ke dlm tepung n lakukan hingga 3 lapis\", \"Goreng ayam dgn api sedang hingga wrn berubah menjadi kecoklatan\", \"Angkat n sajikan dgn saos sambal\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1335, 2, 'Karii Ayam Simple 🐔', 'Hidangan ayam lezat: Karii Ayam Simple 🐔 untuk keluarga tercinta.', '[\"1 bh dada ayam potong dadu\", \"1 bh wortel potong dadu\", \"2 bh kentang potong dadu\", \"1/2 bh kol iris\", \"Bumbu halus :\", \"5 bh Bawang merah besar\", \"2 siung Bawang putih\", \"3 bh Kemiri\", \"1 ruas Jahe\", \"1 sdm ketumbar\", \"sesuai selera Cabe rawit\", \"5 bh Cabe merah\", \"1 ruas Kunyit\", \"400 ml Santan cair\", \"Kaldu bubuk, Garam, gula dan lada sckpnya\"]', '[\"Cuci bersih semua bahan\", \"Tumis bumbu halus hingga harum, masukkan air\", \"Masukkan sayuran potong (urutannya kentang, wortel dan kol) tambahkan santan cair.. aduk terus jangan sampai santan pecah\", \"Masukkan ayam, kaldu bubuk, gula, garam dan lada\", \"Cek rasa dan kematangan.. siapppp deh 😉\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1336, 3, 'Ayam Kampung Tanpa Santan(krebek kuning)', 'Sajian Ayam Kampung Tanpa Santan(krebek kuning) yang praktis dan lezat untuk dinikmati bersama.', '[\"1 ekor ayam kampung\", \"Bumbu halus:\", \"8 siung bawang merah\", \"6 siung bawang putih\", \"4 butir kemiri\", \"2 buah cabe merah besar(bisa tambahin lagi sesuai selera)\", \"2-3 cm jahe dan kunyit\", \"Bumbu Pelengkap:\", \"2 batang sereh(geprek)\", \"2 lembar daun salam\", \"Cabe rawit secukupnya(biarkan utuh)\", \"Lengkuas (geprek)\", \"Garam dan gula\", \"secukupnya Asam jawa\", \"secukupnya Air kaldu\"]', '[\"Potong dan rebus ayam hingga empuk\", \"Haluskan semua bumbu halus (bisa diblender ato diulek)lalu tumis hingga harum, tambahkan bumbu pelengkap dan aduk rata\", \"Masukkan ayam kampung yang sudah direbus, aduk rata\", \"Tambahkan sedikit air kaldu, garam, gula aduk hingga merata\", \"Biarkan mendidih agar bumbu lebih meresap (untuk kuahnya optional bisa pake versi banyak ato dikit tergantung selera aja)\", \"Koreksi rasa dan sajian siap dihidangkan..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1337, 2, 'Risol sayuran + daging ayam', 'Cara membuat Risol sayuran + daging ayam yang enak dan praktis untuk keluarga.', '[\"Kulit\", \"230 gram terigu\", \"20 gr sagu\", \"1 telur kocok dulu\", \"secukupnya Air\", \"Isian\", \"potong kecil Daging ayam\", \"potong kecil Wortel\", \"Kentang potong kecil, goreng dl\", \"iris Daun bawang\", \"5 siung Bamer\", \"2-3 siung Baput\", \"Royco\", \"Lada\", \"Garam\", \"Gula\", \"Tambahan :\", \"Telur\", \"Tepung panir\"]', '[\"Buat adonan kulit dengan mencampur semua bahan untuk kulitnya, jangan terlalu encer\", \"Pakai pan anti lengket (20cm) untuk membuat kulit. Di pan oles dulu dengan mentega supaya tdk lengket dan tuang skitar 1 sendok sayur untuk 1 lembar kulit risol\", \"Membuat isian :\", \"Tumis bamer dan baput sampai wangi dan kecoklatan masukan daging ayam dan aduk sampai ayam berubah warna\", \"Masukan kentang yang sudah di goreng dan juga wortel.. aduk sampai rata, beri 2 sdm tepung terigu untuk mengentalkan isian. Dalam resep ini kentang tdk sy goreng, tapi mertua sy biasa membuatnya dgn di goreng lbh dl jd aromany lbh wangi\", \"Beri air secukupnya untuk memasak supaya wortel lembek.\", \"Beri garam, royco, gula, lada dan cicipi rasanya apakah sudah pas. Sebelum air habis masukan daun bawang dan aduk rata sampai agak kering. Bila rasa sudah pas bisa di pindahkan ke piring\", \"Ambil selembar kulit risol dan isi dengan isinya. Isinya di ratakan dulu spy mudah membungkusnya. Lem pinggir kulit risol dengan air sagu spy tdk terbuka kulitny saat di goreng. Lakukan smp kulit dan isian habis\", \"Kocok telur dan beri sedikit air dan kecap asin angsa spy kulit ada sedikit rasa asin. Dan siapkan tepung panir di piring lain\", \"Lumuri risol yang sudah di bungkus dengan telur dan baluri dengan tepung panir\", \"Goreng risol yang sudah di balur panir ke minyak panas. Goreng sampai kecoklatan\", \"Angkat dan siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1338, 2, 'Soto ayam kediri', 'Soto ayam kediri - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1/4 ekor ayam (ayam kampung lebih enak)\", \"1/4 kg ceker atau tulang\", \"2 batang daun bawang\", \"3 batang serai\", \"4 lembar daun salam\", \"3 lembar daun jeruk\", \"1 ruas lengkuas\", \"360 ml santan jika suka pakai santan atau kurang kental kuahnya\", \"secukupnya Penyedap\", \"secukupnya Garam\", \"Pelengkap :\", \"2 batang daun sledri (cincang halus)\", \"Kol secukupnya iris halus\", \"secukupnya Tauge/kecambah kacang hijau\", \"2 buah kentang iris tipis-tipis (goreng kering)\", \"4 buah tahu (goreng,iris tipis)\", \"2 buah tomat potong sesuai selera\", \"Bawang goreng untuk taburan\", \"sesuai selera Kecap manis\", \"Bumbu halus :\", \"12 butir bawang merah\", \"8 butir bawang putih\", \"1 jari kunyit\", \"1 ruas jari jahe\", \"1 ruas kencur\", \"1/4 sdt merica\", \"1/2 sdt ketumbar\", \"3 buah kemiri\"]', '[\"Panaskan air hingga mendidik,masukkan ayam dan ceker/tulang tunggu hingga matang.\", \"Tumis bumbu halus hingga harum,diamkan sebentar.untuk bumbu halus bisa diblender (langsung bisa masuk kekuah) atau diparut (setelah ditumis diberi air kemudian diperas kekuah pakai saringan diambil sarinya saja bagi yg tidak begitu suka rempah)\", \"Angakat ayam yg direbus td kemudian goreng setengah matang suwir-suwir.\", \"Masukkan bumbu halus kekaldu (kuah),daun salam,serai (geprek),daun jeruk,daun bawang (bisa utuh/dipotong-potong),lengkuas,penyedap,garam.\", \"Tunggu hingga mendidih kemudian koreksi rasa.kalau pakai santan usahakan masukkan santan paling terakhir dan tidak perlu lama-lama supaya santan tidak pecah.matikan api,siap untuk dihidangkan bersama pelengkapnya\", \"Cara membuat sambelnya : cukup rebus cabe merah dan cabe kriting sesuai selera sampai mendidih kemudian haluskan.\", \"NB.untuk penglengkap bisa divariasikan sendiri sesuai selera.bisa ditambah telor,soun,bihun,kentang rebus dll.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(1339, 4, 'Ayam Rica Crispy', 'Ayam Rica Crispy - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"200 gr fillet ayam\", \"150 gr tepung maizena\", \"50 gr tepung terigu\", \"2 butir telur\", \"3 siung bawang putih cincang\", \"1 buah bawang bombai iris\", \"10 buah cabai rawit dan merah (iris tipis)\", \"1 buah tomat\", \"2 batang daun bawang\", \"6 sdm saus cabai\", \"2 sdm saus tomat\", \"1 sdm saus tiram\", \"1 sdm minyak wijen\", \"150 ml air\", \"Air jeruk nipis untuk marinasi ayam\", \"secukupnya Garam, gula, merica\"]', '[\"Cuci bersih ayam, lumuri dengan air jeruk nipis, garam dan merica. Diamkan 15 menit.\", \"Kocok lepas telur. Di wadah terpisah campur tepung maizena dan terigu.\", \"Masukkan daging ayam ke dalam telur, tepung, telur lagi dan tepung lagi. Tekan sambil dicubit-cubit. Goreng hingga matang. Sisihkan.\", \"Tumis bawang putih dan bawang bombai sampai harum. tambahkan cabai dan tomat. Masukkan saus cabai, saus tomat, saus tiram, minyak wijen, garam, lada dan gula. Tambahkan air. Aduk rata dan tunggu mendidih.\", \"Masukkan ayam dan daun bawang. Aduk rata dan siap disajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1340, 4, 'Ayam Mentega', 'Cara membuat Ayam Mentega yang enak dan praktis untuk keluarga.', '[\"1/2 kg Sayap Ayam\", \"6 siung Bawang Merah\", \"4 siung Bawang Putih\", \"Cabai merah besar\", \"Laos\", \"Merica\", \"Gula\", \"Garam\", \"1 Sdm Saos Tiram\", \"1 Sdm Mentega\", \"Daun Bawang\", \"Kecap manis\"]', '[\"Goreng sayap ayam hingga setengah matang. Tiriskan.\", \"Tumis duo bawang dan laos sampe harum baunya.\", \"Masukkan ayam yang telah digoreng sebelumnya.\", \"Tambahkan air secukupnya. Lalu masukkan merica, gula, garam, kecap, dan saos tiram sesuai selera.\", \"Setelah air agak menyusut masukkan 1 Sdm mentega. Masukkan daun bawang. Koreksi rasa. Angkat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1341, 2, 'Ayam Ungkep Bumbu Kuning', 'Nikmati kelezatan Ayam Ungkep Bumbu Kuning dengan resep sederhana ini.', '[\"12 potong Ayam\", \"×Bumbu Halus×\", \"8 butir Bawang Merah\", \"6 butir Bawang Putih\", \"2 cm Jahe\", \"3 ruas Kunyit\", \"2 cm Kencur\", \"5 cm Laos\", \"2 jumput Ketumbar\", \"2 sdm Lada\", \"×Bumbu Pelengkap×\", \"4 lembar Daun Jeruk\", \"3 lembar Daun Salam\", \"2 batang Serai\", \"secukupnya Garam\", \"3-4 gelas Air\"]', '[\"Siapkan bahan dan haluskan bumbu\", \"Masukkan air ke dalam panci, masukkan ayam dan bumbu halus. Aduk-aduk\", \"Masukkan daun jeruk, daun salam, dan serai geprek\", \"Setelah air mendidih, masukkan garam dan biarkan ayam matang sekitar 20 menit\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1342, 4, 'Ayam kecap pedas', 'Hidangan ayam lezat: Ayam kecap pedas untuk keluarga tercinta.', '[\"100 gr ayam\", \"2 siung bawang putih\", \"1 bh cabe gendot\", \"3 bh cabe rawit domba (bisa ditambah sesuai selera)\", \"1 sdm saos cabe botol (saya pake merk indofood)\", \"1 sdm kecap manis\", \"secukupnya Garam, gula, merica\"]', '[\"Rebus dada ayam hingga matang. Tunggu dingin lalu suir sesuai selera. Tiriskan\", \"Tumis bawang putih, cabe gendot, cabe rawit sampai agak layu\", \"Masukan ayam yg sudah disuir tadi\", \"Masukan air kurang lebih 1 cangkir\", \"Beri garam, gula, merica, saos sambal, kecap\", \"Aduk rata, koreksi rasa. Tunggu sampai Air menyusut atau tinggal sedikit.\", \"Angkat lalu sajikan dengan nasi hangat.\", \"Selamat mencoba.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1343, 3, 'Chicken wings cola', 'Buat Chicken wings cola yang nikmat dengan langkah-langkah mudah ini.', '[\"10 potong sayap ayam, cuci bersih, potong jadi 2\", \"300 ml coca cola\", \"1 sendok makan pasta tomat ato saos tomat\", \"4 siung bawang putih, cincang halus\", \"1 ruas jahe, geprek\", \"secukupnya Garam, gula pasir dan merica\", \"Untuk yg suka pedas, boleh ditambah cabai bubuk ato saos sambel\"]', '[\"Tumis bawang putih dgn sedikit minyak sampe harum.\", \"Masukkan sayap ayam, kemudian tambahkan saos tomat (dan saos sambal jika suka pedas). Aduk sampai tercampur.\", \"Tuangkan coca cola sampai seluruh ayam terendam.\", \"Masukkan jahe, gula pasir, garam dan lada bubuk.\", \"Cicipi rasa dan masak sampai ayam matang dan coca cola asat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1344, 4, 'Ayam suir kecap', 'Nikmati kelezatan Ayam suir kecap dengan resep sederhana ini.', '[\"1/2 kg ayam\", \"5 sendok makan kecap manis(sy pake kecap Bangau lbih kental)\", \"5 empela ayam\", \"5 cabe rawit\", \"5 cabe merah besar(iria tipis)\", \"5 siung bawang merah\", \"2 siung bawang putih\", \"1 bawang bombay (iris tipis)\", \"2 kemiri\", \"secukupnya Lada bubuk\", \"Penyedap rasa ayam\", \"2 batang sereh\", \"2 lembar daun salam\", \"1 buah tomat (iris tipis)\", \"secukupnya Garam\", \"Minyak utk menumis\"]', '[\"Rebus ayam dan empela hingga mendidih,tiriskan dan potong kecil\\\" (simpan air kaldu)\", \"Ulek bumbu(bawang merah,bawang putih,cabe rawit,kemiri,garam hingga halus dam sereh (geprek)\", \"Panaskan minyaak, masukan bumbu halus dan irisan bawang bombay,tomat,cabe merah yg sdh di iris,daun salam dan aduk hingga harum\", \"Masukan ayam yg udh di potong\\\" aduk hingga tercampur rata dgn bumbu\", \"Masukan air kaldu secukupnya,penyedap rasa dan lada bubuk,tunggu sampai mendidih\", \"Masukan kecap aduk hingga rata (15menit) biarkan mendidih\", \"Ayam suir kecap siaaap di hidangkaaan...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1345, 3, 'Suwir Ayam Balado 😋', 'Hidangan ayam lezat: Suwir Ayam Balado 😋 untuk keluarga tercinta.', '[\"1/2 ekor ayam\", \"Bawang putih\", \"Bawang Merah 12 siung atau sesuai selera\", \"1 ons Cabai Merah\", \"3 lembar daun jeruk\", \"Secukupnya garam\", \"Secukupnya gula\", \"Secukupnya penyedap rasa (Royko ayam or masako ayam)\"]', '[\"Cuci ayam dan bahan\\\",,siapkan air untuk merebus ayam\", \"Rebus ayam sampai empuk biar gampang untuk menyuirnya kira\\\" 20-30mnt\", \"Sambil menunggu ayam empuk,, siapkan ulekan, masukkan bamer, baput, cabai dan tambahkan garam,, ulek sampai benar\\\" halus\", \"Setelah ayam matang,, suwir daging mnjadi kecil\\\"\", \"Setelah halus bumbu,, siapkan wajan kasi minyak sedikit,, masukan bumbu masak sampai harum\", \"Setelah harum masukan ayam suwir,, aduk hingga merata,,tambahkan garam,gula dan penyedap rasa sesuai selera,,\", \"Setelah pas rasanya, tambahkan daun jeruk,,tunggu hingga matang,,,\", \"Sajikan sesuai selera 😍 selamat mencoba 😇😘\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1346, 2, 'Mie Ayam Abang2', 'Resep Mie Ayam Abang2 ala rumahan yang dijamin menggugah selera.', '[\"Bahan ayam kecap :\", \"2 potong dada ayam, potong dadu\", \"1 ruas lengkuas, geprek\", \"1 ruas jahe, geprek\", \"1 lembar daun salam\", \"2 lembar daun jeruk\", \"1,5 sdm kecap manis\", \"1/2 sdt gula pasir / sesuai selera\", \"Secukupnya garam\", \"Bumbu halus ayam kecap :\", \"3 bawang merah\", \"3 siung bawang putih\", \"1/4 sdt merica\", \"1 ruas kunyit / kunyit bubuk atau giling\", \"1 sdt ketumbar sangrai\", \"1 kemiri\", \"1 batang serai, ambil bagian putihnya\", \"Bahan minyak ayam :\", \"6 sdm minyak goreng\", \"2 siung bawang putih\", \"Secukupnya kulit ayam\", \"Bahan kuah :\", \"Secukupnya air\", \"Secukupnya tulang2 ayam\", \"Secukupnya garam\", \"Secukupnya daun bawang\", \"Bahan sambal :\", \"10 cabe rawit merah\", \"2 cabe merah keriting\", \"1 siung bawang putih\", \"1/4 sdt garam\", \"Pelengkap :\", \"3 porsi mie, rebus\", \"Secukupnya sawi, potong & rebus\", \"Secukupnya daun bawang, iris\", \"Secukupnya saos sambal belibis\"]', '[\"AYAM KECAP : tumis bumbu halus, daun salam, daun jeruk, jahe & lengkuas.\", \"Masukkan ayam, tumis sampai ayam berubah warna. Tambahkan kecap, air, gula & garam.\", \"Masak ayam sampai matang & air menyusut.\", \"MINYAK AYAM : panaskan wajan. masukkan semua bahan, masak sampai kulit ayam & bawang putih kering.\", \"KUAH : siapkan panci, didihkan air secukupnya. Kecilkan api, masukkan tulang2 ayam. Masak sampai kaldu ayam keluar. Bila sudah matang tambahkan garam & daun bawang. Matikan api.\", \"Sambal : rebus cabe & bawang putih sampai matang. Tambahkan garam lalu blender.\", \"PENYAJIAN : Siapkan mangkuk. Masukkan 2 sdm minyak ayam. Tambahkan mie, aduk rata. Tata sawi, topping ayam kecap, sambal, saos. Terakhir taburkan daun bawang & beri kuah.\", \"Siap disajikan 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1347, 3, 'Bubur Ayam Bumbu Kuning', 'Hidangan ayam lezat: Bubur Ayam Bumbu Kuning untuk keluarga tercinta.', '[\"Bahan bubur:\", \"1 gelas beras\", \"6 gelas air\", \"1/2 santan kara yang ukuran paling kecil\", \"1 lembar daun salam\", \"1 batang sereh (geprek)\", \"secukupnya Garam\", \"Bahan bumbu kuning:\", \"4 siung bawang merah\", \"3 siung bawang putih\", \"1 ruas jahe\", \"1 butir kemiri\", \"1 batang sereh (geprek)\", \"1 sdt kunyit bubuk\", \"secukupnya Garam\", \"secukupnya Merica\", \"secukupnya Kaldu bubuk\", \"1 (1/2 gelas) air\", \"Sedikit minyak untuk menumis\", \"Bahan pelengkap:\", \"Ayam suwir\", \"Bawang goreng\", \"Seledri\", \"Kerupuk bawang\"]', '[\"Membuat bubur: campur semua bahan bubur, aduk rata sampai beras menjadi bubur. Terus diaduk agar bubur tidak gosong. Jika masih ada bentuk nasi, air bisa ditambah sedikit demi sedikit sampai bubur matang.\", \"Haluskan: bawang merah, bawang putih, kemiri, dan jahe.\", \"Panaskan minyak, tumis bumbu halus, kunyit bubuk, dan sereh sampai harum. Tambahkan garam, merica, dan kaldu bubuk. Koreksi rasa.\", \"Angkat bumbu kuning lalu saring.\", \"Sajikan bubur, beri kuah bumbu kuning, ayam suwir, bawang goreng, seledri, dan kerupuk.\", \"Selamat menikmati 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1348, 3, 'Pentol Ayam Bumbu Kecap', 'Pentol Ayam Bumbu Kecap - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 kg Ayam\", \"6 Siung bawang merah\", \"4 Siung bawang putih\", \"Garam\", \"Gula\", \"Masako\", \"1 butir telur Ayam\", \"Tepung Kanji\", \"Daun sop\", \"Lombok Merah\", \"Lombok hijau\", \"Pala\", \"Ketumbar\", \"Blue Band (untuk menumis)\", \"Kecap Manis\", \"Tomat\", \"Air\"]', '[\"Cuci bersih ayam pisahkan daging dan tulang nya, lalu haluskan daging ayam..\", \"Haluskan Bumbu (bawang merah, bawang putih, pala, ketumbar, garam, gula)\", \"Masukan separo dari bumbu yang di haluskan ke ayam yg telah di haluskan td.. Aduk hingga rata, masukan juga tepung kanji secukup nya, masukan telur ayam.. Aduk merata\", \"Potong2 daun sop.. Lalu masukan ke dalam ayam yg di haluskan td beserta bumbu.. Aduk merata\", \"Masukan blue band k dalam wajan.. Masukan sisa bumbu yg telah di haluskan td.. Sampai wangi..yah 😀 lalu masukan air secukupnya..\", \"Bulat2kan ayam yg di haluskan td.. Kedalam air yg bumbu tumisan td..\", \"Setelah bulatan ayam mnegras masukan kecap sesuai selera yah.. Aduk merata..\", \"Potong2 lombok merah, lombok hijau & tomat (untuk hiasan)\", \"Setalah matang angkat pentol2 ayam td ke dalam wadah lalu hias.. Siap d hidangkan. Selamat mencoba 😀\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1349, 3, 'Germasem Ayam Kampung', 'Resep praktis Germasem Ayam Kampung yang bisa dicoba di rumah.', '[\"1 ekor ayam kampung cuci bersih\", \"10 siung bawang merah\", \"2 siung bawang putih kating\", \"4 biji kemiri\", \"10 buah cabe\", \"10 buah cabe rawit/cengek\", \"1/2 sdm merica bubuk\", \"4 cm jahe\", \"6 cm lengkuas/laos\", \"3 helai daun salam\", \"4 helai daun jeruk (disobek)\", \"1 batang serai digeprek\", \"2 buah tomat\", \"1/2 sdm gula pasir\", \"1/2 sdm garam\", \"Penyedap secukupnya jika suka\"]', '[\"Haluskan dan tumis bumbu (kecuali daun salam, daun jeruk, serai dan tomat) hingga harum.\", \"Masukkan daun salam, daun jeruk, serai.\", \"Masukkan ayam kampung dan tambah sedikit air (jangan langsung banyak karena menjadi anyir). Tunggu sampai air berkurang lalu tambah air lagi.\", \"Masukkan tomat dan masak hingga matang.\", \"Germasem ayam kampung siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1350, 3, 'Sup ayam brokoli', 'Nikmati kelezatan Sup ayam brokoli dengan resep sederhana ini.', '[\"1 bonggol brokoli\", \"2 sayap ayam\", \"2 batang wortel, potong2\", \"1 buah kentang, potong dadu\", \"1 batang seledri, iris2\", \"1 batang daun bawang, iris2\", \"3 butir bawang merah\", \"2 siung bawang putih\", \"secukupnya Garam dan ada bubuk\"]', '[\"Cuci bersih sayap ayam dan sayuran, rendam brokoli dengan air hangat+garam (supaya ulat dalam brokoli mati) lalu cacah brokoli\", \"Rebus sayap ayam dengan api kecil hingga matang dan kuah menjadi berkaldu, masukan potongan kentang dan wortel, masak hingga 1/2 matang\", \"Haluskan bawang merah dan bawang putih, lalu tumis hingga harum, masukan ke dalam kuah kaldu sup\", \"Masukan cacahan brokoli+daun bawang+seledri\", \"Beri garam dan lada bubuk lalu test rasa, masak hingga semua matang\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1351, 4, 'Ayam Bumbu Kuning', 'Buat Ayam Bumbu Kuning yang nikmat dengan langkah-langkah mudah ini.', '[\"1/2 kg ayam,bersihkan\", \"1 batang serai,memarkan\", \"1 ruas lengkuas besar,memarkan\", \"1 lembar daun salam\", \"1 lembar daun jeruk\", \"secukupnya Air\", \"Bumbu halus:\", \"2 siung bawang putih\", \"4 siung bawang merah\", \"1 ruas jahe,bakar sebentar\", \"1 ruas kunyit,bakar sebentar\", \"2 biji kemiri,bakar sebentar\", \"1 sdt ketumbar\", \"Secukupnya garam\", \"Secukupnya gula\", \"Secukupnya merica\", \"Minyak untuk menumis\"]', '[\"Bersihkan ayam terlebih dahulu,kemudian rebus sebentar dengan air+daun salam,setelah mendidih buang airnya.\", \"Haluskan semua bahan bumbu halus (saya pakai ulekan 💪😁).\", \"Kemudian panaskan wajan berisi minyak,masukkan daun salam,daun jeruk,lengkuas,serai.tumis hingga layu\", \"Setelah layu,masukkan bumbu halus.tumis hingga beraroma harum.\", \"Masukkan ayam,tutup wajan dan diamkan selama 5 menit.kemudian tambahkan air.\", \"Tutup kembali wajan dan diamkan sampai air menyusut (kurang lebih 30 menit).\", \"Angkat dan sajikan begitu saja atau digoreng dahulu. 😁\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1352, 2, 'Sambal Ayam gecok sederhana🍗', 'Sajian Sambal Ayam gecok sederhana🍗 yang praktis dan lezat untuk dinikmati bersama.', '[\"1 Ayam goreng (me:paha)\", \"👉🏻Bahan sambal:\", \"20 cabe rawit (optional)\", \"1 siung bawang putih kecil\", \"1 siung bawang merah kecil\", \"1 buah jeruk limo kecil\", \"Tomat sesuai selera (me :2 tomat cherry)\", \"Royco,gula,penyedap rasa (optional)\"]', '[\"Uleg semua bahan sambal,tes rasa,beri perasan jeruk limo aduk2,taruh ayam goreng pd cobek yg berisi sambal,lalu tekan2 hingga sedikit hancur\", \"Siap disajikan bersama lalapan ☺️ sambal bs jg di tambahin kencur sedikit jika suka,kebetulan sy lg gada kencur🙈\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1353, 3, 'Kuah Soto ayam simple', 'Resep Kuah Soto ayam simple yang lezat dan mudah dibuat di rumah.', '[\"bumbu halus :\", \"3 bawang putih\", \"1/2 sdt ketumbar\", \"10 butir lada/lada bubuk sedikit jg bs\", \"1 kemiri\", \"1 ruas jari kunyit\", \"1/4 ekor ayam bagian dada, potong2\", \"2 lembar salam\", \"1 lembar daun jeruk.. ditambah jg bs.. kalo anak2ku kurang suka bau na\", \"1 batang sereh geprek\", \"1 ruas jari jahe geprek\", \"1 batang daun bawang dan sedikit seledri potong2\", \"bawang goreng\", \"secukupnya garam dan kaldu bubuk\", \"3/4 gayung air utk merebus\", \"minyak utk menumis bumbu\"]', '[\"Cuci bersih ayam.. masuk kan k panci.. tambah air, salam, sereh, jahe, daun jeruk, garam, kaldu bubuk.. masak\", \"Sambil merebus ayam tumis bumbu halus lalu tuang k panci rebusan.. kalo ayam sudah empuk angkat ayam.. tulangan aq biarin d panci.. tes rasa, tambah daun bawang seledri, bawang goreng. masak sebentar matikan kompor..\", \"Ayam digoreng g usah lama2 y biar g keras..\", \"Penyajian suwir2 ayam siram kuah soto kasih jeruk nipis dikit.. kalo mo pake pelengkap yg lain jg bs ky soun rebus, kol iris, toge, bubuk koya, emping, telur rebus..\", \"Atau sambal rebus : cabe rawit yg sudah direbus, tambah garam dikit, haluskan.. mo dikasih air dikit trus dimasak sebentar jg bs..\", \"Soto na mau pake santan jg bs..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1354, 3, 'Ayam serundeng', 'Resep Ayam serundeng yang lezat dan mudah dibuat di rumah.', '[\"1 ekor ayam potong sesuai selera\", \"1/4 buah kelapa parut\", \"3 lembar daun salam\", \"Bumbu halus;\", \"1 ruas jari kunyit\", \"2 ruas jari lengkuas\", \"4 buah bawang merah\", \"2 buah bawang putih\", \"3 butir kemiri\", \"1/2 sdm ketumbar\", \"Secukupnya garam\", \"Secukupnya air dan minyak goreng\"]', '[\"Cuci bersih ayam hingga kesat, tiriskan. Haluskan semua bumbu, panaskan sedikit minyak lalu tumis bumbu hingga harum. Masukan daun salam, tumis hingga layu. Tambahkan air (tidak usah terlalu banyak, asal ayam terendam saja) masukan ayam, aduk-aduk lalu ungkep hingga air menyusut. Jika sudah empuk, angkat ayam dan tiriskan. Sisa air ungkepan jangan dibuang.\", \"Panaskan minyak, goreng ayam hingga kuning keemasan. Jika sudah matang, angkat, sisihkan.\", \"Siapkan kelapa, panaskan kembali sisa air ungkepan, masukan kelapa parut lalu sangrai hingga wangi dan coklat keemasan. Masukan ayam yang telah digoreng. Aduk-aduk beberapa saat, jika sudah meresap dan matang, angkat, sajikan. Selamat mencoba.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1355, 4, 'Kare ayam 🐔', 'Resep praktis Kare ayam 🐔 yang bisa dicoba di rumah.', '[\"1 ekor ayam\", \"500 ml santan kental\", \"200 ml air\", \"3 lembar daun jeruk\", \"1 batang serai, memarkan\", \"1 bks royco ayam\", \"1 sdt gula\", \"bumbu halus :\", \"7 bawang merah\", \"6 bawang putih\", \"3 buah kemiri\", \"1 sdt ketumbar\", \"3 cm kunyit\", \"1 ruas jahe\", \"1/2 sdt merica bubuk\", \"1/2 sdt garam\"]', '[\"Potong-potong ayam menjadi beberapa bagian, cucu bersih\", \"Uleg bumbu halus\", \"Tumis bumbu halus, serai, daun jeruk hingga harum\", \"Lalu masukkan ayam, tambahkan air dan santan sambil diaduk\", \"Tambahkan royco ayam dan gula. Masak hingga air meresap\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1356, 2, 'Ayam Jamur Lada Hitam', 'Resep Ayam Jamur Lada Hitam yang lezat dan mudah dibuat di rumah.', '[\"350 gr ayam fillet\", \"Jamur kancing secukupnya (iris)\", \"Brokoli secukupnya (iris)\", \"1/2 buah bawang bombay (iris)\", \"2 sdm lada hitam butiran (digerus)\", \"2 sdm kecap manis\", \"1 sdm saus tiram\", \"3 sdm saus sambal\", \"1 sdt kecap asin\", \"secukupnya Garam, gula\", \"2 cm jahe (iris)\", \"1 sdm tepung maizena (larutkan dengan 50ml air)\", \"3 siung bawang putih (cincang halus)\", \"secukupnya Air\"]', '[\"Tumis bawang putih cincang sampai harum, tambahkan lada hitam, jahe iris lalu masukkan ayam. Aduk2 sampai ayam berubah warna dan sedikit matang\", \"Masukkan semua bahan saos, lalu tambahkan air, sambil terus diaduk\", \"Masukkan jamur, brokoli, dan bawang bombay. Aduk hingga semua bahan tercampur. Beri garam dan gula, serta larutan maizena. Koreksi rasa\", \"Masak hingga kuah agak mengental dan semua bahan matang. Angkat dan siap dihidangkan.\", \"Untuk sayuran bisa divariasikan, misal ditambah wortel, paprika, buncis, dll sesuai selera yah..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1357, 2, 'Ayam Geprek Bensu', 'Nikmati kelezatan Ayam Geprek Bensu dengan resep sederhana ini.', '[\"1 Ekor ayam\", \"Tepung Sasa Kentucky\", \"Telur\", \"Bumbu halus\", \"Bawang putih\", \"Merica\", \"Garam\", \"Sedikit penyedap rasa saya pakai M*g*c\", \"Minyak goreng\", \"Bumbu sambel\", \"Cabai krting merah no rawit agar anak2 bisa ikutan makan jg\", \"Bawang putih\", \"Sedikit tomat\", \"Garam, gula\"]', '[\"Cuci ayam sampai bersih\", \"Lalu masukkan bumbu halus, telur, tusuk2 ayan pke garpu agar bumbu meresap ke dalam aduk hingga rata. Simpan di kulkas -+ 1 jam simpan nya jgn di prezer\", \"Terakhir lumuri ayam dengan tepung bumbu sasa ayam kentucky sambil di cubit2 dan Goreng deh sembari di goreng tusuk2 lagi ayam nya agar ayam nya mateng dengan sempurna.\", \"Untuk sambel nya, rebus semua bahan sambel lalu ulek kasar setelah itu tumis sambel dan jgn lupa ksh garam gula, setelah sambel matang, biarkan hingga sambel tdk panas lg barudeh di campur ayam krispinya\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1358, 4, 'Ayam goreng serundeng', 'Ayam goreng serundeng dengan bumbu meresap sempurna.', '[\"1 kg ayam. Potong sesuai selera\", \"1/3 buah kelapa parut\", \"1 bsk royko bumbu ayam goreng\", \"2 ruas kunyit\", \"4 ruas laja\", \"3 buah daun salam\", \"1 batang sereh\", \"4 siung bawang putih\", \"2 siung bawang merah\", \"2 buah lemon\", \"1 sdt garam\"]', '[\"Bersihkan ayam, lalu baluri dengan air perasan lemon. Diamkan. Agar ayam menjadi empuk\", \"Haluskan bawang merah, bawang putih, dan kunyit. Parut laa. Lalu haluskan\", \"Siapkan wajan besar masukan ayam, bumbu halus, salam, sereh, dan kelapa parut, garam. Beri 1/2 gelas belimbing air. Aduk (air jangan terlalu banyak karna ayam nanti akan mengeluarkan air).\", \"Jika tidak di beri kelapa parut. Jumlah garam nya di kurangi ya. Karna royko bumbu ayam goreng sudah asin\", \"Ungkap ayam dengan api sedang Sampai air habis. Jangan lupa koreksi rasa\", \"Goreng sampai kecoklatan. Sisanya ayam bisa di masukan dlm lemari es. Untuk stok\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1359, 2, 'Ayam KFC KW By Queen', 'Resep praktis Ayam KFC KW By Queen yang bisa dicoba di rumah.', '[\"ayam potong 12\", \"8 bh bawang putih\", \"1/2 sdm garam\", \"1 sachet royco\", \"1/2 sdm merica\", \"3 sdm tepung tapioka\", \"9 sdm tepung terigu\", \"telur 2 butir kocok\"]', '[\"Cuci bersih ayam lalu tiriskan\", \"Ulek bwang putih dngn garam hingga halus\", \"Lumuri ayam dngn bumbu yang dah di haluskan\", \"Diamkan semalaman atau 1-2 jam di kulkas\", \"Ambil wadah campur tepung terigu,tepung tapioka,merica,royco aduk rata\", \"Setelah 1 jam atau smlaman keluarkan ayam dari kulkas gulingkan k tepung bumbu>kocokan telur>bumbu lalu goreng deh\", \"Selamat menikmati\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1360, 4, 'Soto Ayam', 'Cara membuat Soto Ayam yang enak dan praktis untuk keluarga.', '[\"1/2 kg daging ayam (dadanya yaa kalau bisa)\", \"1 buah kol yg ukuran kecil aja jangan banyak\", \"2 buah tomat\", \"1 bungkus bihun (mau pake atau ngga juga boleh)\", \"3 lbr bawang daun\", \"1 buah laos/lengkuas (ukuran jempol di potong trus di geprek)\", \"1 tangkai sereh di geprek\", \"5 lbr daun salam\", \"3 lbr daun jeruk (mau pake atau ngga juga bebas)\", \"1 buah jeruk nipis\", \"1 1/2 masako ayam\", \"2 sdt garam\", \"1 sdt micin\", \"Bumbu halus :\", \"4 bawang merah\", \"3 bawang putih\", \"1 kunyit (ukuran jempol aja)\", \"1 sdt merica butir\", \"2 bks kemiri (diwarung sih 1bks nya 500an)\"]', '[\"Ayam dicuci bersih lalu di rebus sampe mateng trus di suir suir ayam nya. Setelah itu rebus kembali pake air baru yaah bukan air yg abis ngerebus ayam tadi. Panaskan di kompor api sedang.\", \"Tumis bumbu halus, masukan laos(lengkuas), salam, sereh, daun jeruk, tumis sampai harum tambahin air dikit aja biar kaga gosong. Abis itu masukin tumisan bumbu tadi ke rebusan ayam. Aduk sampe rata\", \"Tambah bumbu penyedap rasa. Kalau saya 1 1/2 itu karena kan airnya banyak gtu menyesuaikan dengan air nya deh ya buibu.. tambah garam, sama micin juga biar rada mantep hehee kalo gasuka micin ga usah pake aja bu.\", \"Aduk sampe tercampur. Catetan disini saya ada kol sama bihun nya itu ga dicampur dimasak yaa tapi kalau mau makan ya terpisah aja ga disatuin. Kecuali yg ga pake bihun mau kol nya di campurin ke soto nya gak apa apa. Tapi kol nya di iris yaa kaya mau bikin bala bala hahaha\", \"Terakhir icip rasa nya yaa trus masukin bawang daun nya sama tomat nya yg di potong potong.\", \"Mangga disajikan penuh cinta dan kasih sayang buat yg paling disayang inshaa allah nikmat apalagi kalau makannya bareng bareng lahap lagi hahaha.. awas jangan terlalu asin yaa bu ibu 😘\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1361, 2, 'Ayam Lodoh ala Uti', 'Ayam Lodoh ala Uti dengan bumbu meresap sempurna.', '[\"1 ekor ayam kampung\", \"5 siung bamer (banyak lebih enak)\", \"5 siung baput\", \"1/2 ons lombok\", \"Jahe, laos, kencur, kunyit\", \"sereh, daun salam, daun jeruk\", \"cabe rawit putih\", \"ketumbar, jintan, lada putih\", \"gula, garam\", \"santan dari 2 butir kelapa\"]', '[\"Belah 2 ayam (potong” sesuai selera), cuci bersih kemudian lumurin garam, bakar\", \"Haluskan bamer, baput, lombok, kunyit, jahe, kencur, ketumbar, jintan, lada\", \"Tumis bumbu halus hingga wangi masukan daun salam, daun jeruk, sere dan laos\", \"Setelah itu masukan ayam dan beri air secukupnya tambahkan lombok putih, garam dan gula tunggu hingga empuk\", \"Setelah agak empuk beri santan dan masak lagi hingga benar” empuk dan matang\", \"Siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1362, 2, 'Chiken krispi simple', 'Resep Chiken krispi simple ala rumahan yang dijamin menggugah selera.', '[\"1/4 daging ayam\", \"tepung terigu\", \"telor ayam\", \"bawang putih\", \"garam\", \"lada\", \"ketumbar\", \"minyak goreng\"]', '[\"Potong2 ayam sesuai selera lalu cuci hingga bersih\", \"Campurkan ayam,bawang putih yg sudah di haluskan dan telor dalam satu wadah aduk2 hingga merata\", \"Di wadah yg lain campur tepung terigu,garam, lada,ketumbar yg sudah di haluskan lalu aduk hingga merata\", \"Panaskan minyak goreng,ambil satu potong ayam yg sudah di campur dengan telor gulingkan kedalam tepung yg berbumbu hingga merata lalu goreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1363, 4, 'Tongseng Ayam praktis', 'Nikmati kelezatan Tongseng Ayam praktis dengan resep sederhana ini.', '[\"1/2 kg ayam\", \"1/4 kol sedang\", \"15 cabai rawit\", \"2 tangkai daun bawang\", \"Bumbu :\", \"10 bawang putih\", \"4 bawang merah\", \"4 daun jeruk\", \"1 ruas kecil laos (geprek)\", \"1 ruas sedang kunyit (bakar)\", \"2 ruas kecil jahe (geprek)\", \"2 tangkai serai (geprek)\", \"1 bks santan sasa instan\", \"Secukupnya (garam, gula pasir, royco, Lada bubuk, kecap & air)\"]', '[\"Bersihkan ayam, lalu cincang kasar dan tiriskan\", \"Cuci bersih Kol, daun bawang dan cabai rawit, lalu potong2\", \"Geprek (jahe, laos, serai) siapkan daun jeruk yg sudah di cuci\", \"Haluskan bumbu (kunyit yg sudah dibakar, bawang merah, bawang putih, garam)\", \"Tumis bumbu halus sampai harum, lalu masukkan jahe,serai,laos yg telah digeprek tadi, masukkan juga daun jeruknya sampai harum dan layu\", \"Masukkan daging ayam, masak sebentar sambil diaduk2, lalu tambahkan air secukupnya biarkan sampai mendidih\", \"Masukkan santan instan, beri gula dan penyedap rasa secukupnya sambil di cicipi, masak hingga ayam matang, tambahkan kecap sesuai selera\", \"Masukkan kol, irisan cabai rawit, dan daun bawang, siap di sajikan untuk keluarga tercinta 😍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1364, 2, 'Chicken garlic super gampang', 'Resep Chicken garlic super gampang ala rumahan yang dijamin menggugah selera.', '[\"1/2 kg ayam. potong kecil2\", \"1 bungkul bawang putih\", \"1 sdt bawang putih bubuk\", \"secukupnya garam\", \"secukupnya lada bubuk\", \"secukupnya ketumbar bubuk\", \"1 sdm minyak wijen\", \"1 sdt saus tiram (optional)\"]', '[\"Cuci bersih ayam\", \"Dalam baskom/wadah kosong. campurkan bawang putih bubuk,ketumbar bubuk,lada bubuk,garam,minyak wijen,saus tiram dan bawang putih 1bungkul yg sudah digeprek. geprek sama kulitnya skalian ya. aduk jd 1 smuanya\", \"Klo ga punya bawang putih bubuk,ya pake aja bawang putih biasa di ulek atau di parut pake oarutan keju (kurleb pakai 4siung)\", \"Masukkan ayam yg sudsh dicuci bersih. camour aduk smua jd 1. marinate selama kurang lebih 2 jam. taruh di kulkas. lebih dr 2 jam juga gpp makin endeuuussss\", \"Goreng dlm minyak panas. goreng pakai api kecil ya biar matang merata sampai ke tulang 😊😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1365, 3, 'Mie ayam rica rica', 'Resep praktis Mie ayam rica rica yang bisa dicoba di rumah.', '[\"1/4 ayam dipotong potong kecil\", \"3 siung bawang putih\", \"2 siung bawang merah\", \"secukupnya Cabai rawit\", \"1 buah kemiri\", \"2 lembar daun jeruk\", \"secukupnya Minyak\", \"1 sdm kecap\", \"Bahan mie\", \"1 bungkus mie ayam\", \"1 sdt kecap asin\"]', '[\"Tumbuk bawang merah, bawang putih, kemiri, cabai rawit\", \"Tumis semua bahan bahan yang sudah ditumbuk\", \"Masukan ayam potong lalu beri daun jeruk. Lalu beri air sedikit dan masukan kecap. Lalu tunggu hingga air sedikit berkurang\", \"Rebus mie setengah matang, lalu beri kecap asin dan minyak\", \"Lalu beri ayam beberapa sendok dann siap di hidangkann\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1366, 2, 'Bakso ayam', 'Resep Bakso ayam ala rumahan yang dijamin menggugah selera.', '[\"500 gr daging ayam\", \"250 gr tepung sagu\", \"secukupnya Air\", \"6 baput\", \"Lada,garam,r***o\", \"Bahan pelengkap:\", \"Mie\", \"Daun bawang\", \"Seledri\", \"Bumbu kuah:\", \"8 baput\", \"5 bamer\", \"secukupnya Lada garam r***o\", \"Air kira\\\" z\", \"Tetelan tulang ayam\"]', '[\"Hancurkan(sy pke gilingan daging) daging ayam sm tulang ayam yg masih muda campur z biar jd baso urat\", \"Tambahkan tepung sagu dan bumbu halus bumbui cek rasa\", \"Didihkan air di panci stelah mendidih matikan api cetak baso pke sendok sampai hbs didihkan lg hingga matang lalu angkat tiriskan\", \"Cara membuat kuah tumis bumbu sisihkan didihkan air masukkan tumisan bumbu dan bumbui kuah cek rasa\", \"Rebus mie dan iris daun bawang dan seledri bakso siap di sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1367, 4, 'Mie Ayam Solo', 'Mie Ayam Solo - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"400 gr Mie Telur (saya pakai mie telur cap 3 ayam 2 bks)\", \"3/4 kg Dada Ayam\", \"Minyak\", \"Garam\", \"Merica\", \"Bumbu Ayam yg dihaluskan:\", \"6 siung Bawang Merah\", \"7 siung Bawang putih\", \"1 sdt Ketumbar halus\", \"3 btr Kemiri (di goreng tanpa minyak)\", \"1 sdt Kunyit (pakai yg bubuk)\", \"1 sdm Minyak wijen\", \"Bumbu ayam pelengkap:\", \"1 ruas jari Jahe\", \"2 ruas jari Lengkuas\", \"Serai\", \"Gula merah\", \"Kecap Manis\", \"2 lbr Daun Salam\", \"2 lbr Daun Jeruk\", \"Bahan Pendamping:\", \"Bakso\", \"Kerupuk pangsit\", \"Sawi\", \"Daun bawang\", \"Bawang goreng\", \"Sambal\"]', '[\"1. Rendam mie hingga sedikit lunak, lalu kukus (mie diberi sedikit minyak agar tdk lengket) selama 20mnt. Selagi mengukus Potong dadu ayam.\", \"2. Bumbu ayam:\", \"Haluskan semua bahan pendamping menggunakan blender/food processor, lalu tumis menggunakan minyak (kurleb 150ml).\", \"3. Jika sudah harum, masukan bumbu pelengkap ayam kedalam tumisan, dan beri garam dan merica.\", \"4. Masukan ayam potong dadu tadi kedalam tumisan, lalu beri air (kurleb 300ml).\", \"5. Tumisan ayam sudah matang, lalu siap dihidangkan bersama bahan pendamping 😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1368, 4, 'Tahu ayam udang', 'Sajian Tahu ayam udang yang praktis dan lezat untuk dinikmati bersama.', '[\"3 bh Tahu cina putih\", \"100 gr udang dikupas\", \"200 gr dada ayam tanpa tulang\", \"sedikit Daun bawang\", \"3 sdm tepung sagu/tapioka\", \"Garam\", \"Lada\", \"Penyedap\", \"3 siung bawang merah\", \"2 siung bawang putih\"]', '[\"Potong tahu\", \"Siapkan udang dan ayam\", \"Haluskan / blender ayam dan udang, bawang merah, bawang putih, setelah halus tambahkan garam, lada penyedap dan irisan daun bawang\", \"Tambahkan tepung sagu/tapioka serta sedikit air es\", \"Bentuk dengan tahu sesuai selera\", \"Kemudian dikukus sampai matang\", \"Setelah matang, bisa langsung dinikmati atau digoreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1369, 3, 'Ayam cabai hijau', 'Resep Ayam cabai hijau yang lezat dan mudah dibuat di rumah.', '[\"1/4 kg ayam\", \"Bumbu ungkep :\", \"4 siung Bawang putih\", \"Jahe\", \"Laos\", \"1 ruas jari Kunyit\", \"Ketumbar\", \"Garam\", \"Gula\", \"Penyedap rasa (semua bumbu ungkep duhaluskan)\", \"Sereh digeprek\", \"2 lembar Daun jeruk\", \"2 lembar Daun salam\", \"Sambal hijau:\", \"15 buah Cabai hijau\", \"10 buah Cabaim rawit hijau\", \"4 siung Bawang merah\", \"4 siung Bawang putih\", \"2 lembar Daun jeruk\", \"Garam\", \"Gula\", \"Penyedap rasa (haluskan semuanya)\"]', '[\"Cuci ayam lalu potong2\", \"Rebus ayam bersama dengan bumbu ungkep sampai ayam empuk dan bumbu meresap.jangan lupa cek rasa\", \"Setelah ayam direbus, angkat lalu goreng dengan minyak panas sebentar saja (jngan terlalu kering)\", \"Tumis sambal yang sudak diulek sampai harum... Tambahkan sedikit air.. Cek rasa\", \"Tunggu sampai air agak menyusut.. Kemudian masukkan ayam yang sudah digoreng tadi...\", \"Aduk2 sampai kuah nya tinggal sedikit\", \"Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1370, 2, 'Ayam ukep', 'Buat Ayam ukep yang nikmat dengan langkah-langkah mudah ini.', '[\"Bahan\", \"500 gram ayam (potong besar)\", \"Bumbu ukep\", \"4 lembar daun jeruk\", \"2 lembar daun salam\", \"1 batang serai (geprek/pakai ukuran besar)\", \"1 sdt ketumbar bubuk (agak aku lebihin)\", \"1 sdt kunyit bubuk\", \"Lengkuas (ukuran ibu jari/parut)\", \"Jahe (ukuran ibu jari/parut)\", \"secukupnya Gula dan garam\", \"Air biasa/air kelapa (untuk merebus ayam bersama bumbu)\"]', '[\"Cuci ayam hingga bersih lalu taruh di panci yang berisi air. Dan usahakan takaran air sampai di atas ayam.\", \"Masukan semua bumbu ukep ke panci\", \"Tunggu sampai mendidih dan surut airnya (airnya sampai tinggal sedikit)\", \"Setelah surut diam kan sampai dingin\", \"Kalau untuk stock di kulkas aku gak pakai air sisa rebusan,cukup bumbu2 sisa saja biar gak jadi jelly saat di suhu dingin..dan aku pakai tempat penyimpanan makanan yang kedap udara\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1371, 3, 'SAYAP AYAM ISI DAGING.... By. Dapoer Linggar', 'Cara membuat SAYAP AYAM ISI DAGING.... By. Dapoer Linggar yang enak dan praktis untuk keluarga.', '[\"500 gr sayap ayam\", \"Panci pengukus\", \"Bahan rendamam :\", \"Kaldu bubuk ayam\", \"1/2 sdt ladah bubuk\", \"Bahan isi :\", \"250 gr daging ayam giling\", \"100 gr udang\", \"1 sendok minyak wijen\", \"1 sdt kecap ikan\", \"1/2 sdt kecap asin\", \"Gula pasir\", \"blok Kaldu\", \"1 Sdm saos tiram\", \"2 butir bawang putih\", \"2 sdm tapioka\"]', '[\"Sayap ayam bersihkan lalu keluarkan tulang bagian sayap atas (yg spt paha) dengan cara patahkan bagian antara sayap atas dan bawah bila sudah patah puter sayap sampai tulang telepas dari daging lalu cabut tulangnya keluarkan\", \"Kemudian rendam sayap ayam yang sudah tanpa tulang selama 2 jam atau semaleman di lemari pendingin\", \"Bahan isi semuanya di blender hingga halus dan rata smuanya tercampur jadi satu\", \"Test rasa bahan isi dengan cara panaskan wajan lalu oles margarin lalu letakkan sedikit bahan usi ke wajan dan masak hingga matang.\", \"Masukan bahan isi ke dalam plastik segitiga atau apa aza yang tersedia supaya bisa memudahkan memasukannya ke dalam sayap.\", \"Kukus sayap ayam selama 20 menit hingga matang menyeluruh kemudian dinginkan...\", \"Bisa untuk simpen menjadi froozen atau langsung goreng dengan api kecil hingga warna keemasan...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1372, 2, 'Pangsit rebus isi ayam simple', 'Hidangan ayam lezat: Pangsit rebus isi ayam simple untuk keluarga tercinta.', '[\"250 gr ayam giling atau ayam filet juga bisa\", \"Kulit pangsit yang sudah jadi\", \"2 siung bawang putih\", \"1 btg daun bawang\", \"1 sdm Merica bubuk\", \"Penyedap rasa ayam\", \"secukupnya Garam\", \"Bahan kuah ::\", \"secukupnya Air\", \"secukupnya Garam\", \"Penyedap rasa sapi\", \"2 batang daun bawang\", \"3 siung bawang putih\", \"Merica bubuk\"]', '[\"Cuci bersih daging ayam giling atau filet. Haluskan bawang putih. Dan campurkan penyedap rasa, garam, merica bubuk, daun bawang ke adonan ayam giling. Aduk hingga rata dan tes rasa\", \"Jika sudah rata, masukkan ke kulit pangsit bentuk2 sesuai selera. Didihkan air, beri sedikit minyak agar tidak lengket\", \"Jika sudah mengambang, pangsit siap diangkat\", \"Membuat kuah, didihkan air. Uleg kasar bawang putih. Dan masukkan garam secukupnya, penyedap rasa sapi, dan bawang putih yang telah di uleg kasar kedalam air mendidih\", \"Tes rasa. Jika sudah pas, matikan kompor masukkan daun bawang dan siram ke pangsit yang sudah matang.\", \"Note : jika ingin makan pangsit tersebut. jangan didihkan bersama kuah. tetapi kuah didihkan setelah itu siram saja ke pangsit. agar pangsit tidak lembek\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1373, 4, 'Ayam Bakar Madu Sederhana dengan Happy Call ala Febs', 'Cara membuat Ayam Bakar Madu Sederhana dengan Happy Call ala Febs yang enak dan praktis untuk keluarga.', '[\"4 pcs Paha Ayam Utuh (Paha Atas dan Bawah)\", \"1 buah Jeruk Nipis / Lemon\", \"Ketimun / Bahan Lalapan\", \"bumbu halus:\", \"5 siung Bawang Putih\", \"5 Siung Bawang Merah\", \"3 butir Kemiri\", \"2 sdt Ketumbar\", \"2 ruas Jahe\", \"2 ruas Laos\", \"6 cm Kunyit\", \"bumbu tumis:\", \"Secukupnya Minyak Goreng\", \"1 Serah (digeprek)\", \"2 lbr Daun Salam\", \"3 sdm Kecap Manis\", \"3 sdm Madu\", \"2 sdt Garam\", \"bumbu oles:\", \"1 sdm Margarin\", \"2 sdm Madu\", \"2 sdm Kecap Manis\"]', '[\"Cuci bersih ayam dan lumuri dengan air jeruk nipis / lemon. Simpan didalam kulkas kurang kebih 15 menit.\", \"Haluskan semua bahan bumbu halus.\", \"Panaskan minyak diwajan dengan api sedang dan kemudian tumis bumbu yang sudah dihaluskan beserta Serah dan Daun salam. Tumis hingga warna kuning dan jangan sampai berubah warna coklat. Masukkan air dan ayam. Aduk hingga bumbu merata. masukkan Madu dan kecap manis dan aduk hingga bumbu merata. Tambahkan sedikit garam. Dan Masak ayam selama kurang lebih 20 menit.\", \"Sambil menunggu ayam masak, siapkan bumbu oles untuk bakar ayamnya. Campurkan Margarin, Madu, kecap manis dalam 1 wadah. Jika ayam sudah masak, tambahkan 3sdm sisa bumbu ayam yang dimasak tadi ke dalam bumbu oles.\", \"Olesi Teflon / Happy Call dengan Margarin agar tidak lengket (saya menggunakan Happy Call dengan api sedang). Kemudian olesi ayam bolak balik dengan bumbu oles sebelum dibakar. Jika sudah merata dibakar, angkat dan sajikan dengan lalapan dan sambal.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1374, 4, 'Ayam Saos Mentega Ala Mama Kina', 'Resep Ayam Saos Mentega Ala Mama Kina yang lezat dan mudah dibuat di rumah.', '[\"10 potong ayam yg sdh diungkep\", \"1 bh tomat uk sedang (iris sesuai selera)\", \"3 lembar daun bawang (iris dg jarak 0,5cm)\", \"3 siung bamer (iris tipis)\", \"3 siung baput (iris tipis)\", \"1/2 potong bawang bombay uk sedang (iris tipis)\", \"2 bh cabe merah (iris serong)\", \"2 bh cabe ijo (iris serong)\", \"Mentega secukupnya (me: 2 1/2 sdm)\", \"Garam\", \"2 sdt gula\", \"1/2 sdt ladaku\", \"1 sdm penyedap rasa (me: royco ayam)\", \"4 sdm kecap manis\", \"1 sdm saos tiram\"]', '[\"Goreng ayam terlebih dahulu, tiriskan\", \"Siapkan wajan, masukkan mentega dg api kecil\", \"Tumis bambay bamer baput, sambil diaduk pelan ya.\", \"Lalu masukkan ayam yg sdh digoreng, aduk rata dan pelan. Tunggu sebentar sampai bumbu meresap\", \"Masukkan cabe merah, cabe ijo, garam, gula, ladaku, kecap manis, saos tiram, royco. Aduk sampai rata dan meletup.\", \"Koreksi rasa. Terakhir masukan daun bawang dan tomat\", \"Angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1375, 3, 'Ayam bakar bacem manis', 'Cara membuat Ayam bakar bacem manis yang enak dan praktis untuk keluarga.', '[\"Ayam (seplastik karena beli ditukang belanja)\", \"Tempe\", \"Bahan ungkep ayam:\", \"secukupnya Garam\", \"Air untuk merendam karena habis masuk freezer\", \"Bumbu tumis:\", \"6 Bawang merah\", \"4 Bawang putih\", \"1 Kemiri\", \"1/2 sdt Tumbar\", \"3 daun salam\", \"secukupnya Gula pasir\", \"sesuai selera Gula jawa\", \"sesuai selera Kecap\"]', '[\"Keluarkan ayam dari freezer kemudian rendam dengan air hangat campur air biasa. Campur sedikit garam. Agak lama kemudian cuci lagi sampai tidak ada darah kemudian potong kecil2\", \"Haluskan bumbu bawang merah, bawang putih, tumbar, kemiri, garam, gula\", \"Kemudian tumis bumbu halus\", \"Kemudian masukan ayam potongan, tempe, daun salam, gula jawa ke wajan. Diberi air. Kemudian campurkan bumbu yg sudah ditumis tadi\", \"Bisa tambahkan kecap. Tutup ungkepan, kemudian rasakan. Jika kurang manis atau asin bisa ditambah sesuai selera.\", \"Setelah itu siapkan tempat untuk membakar. Masukan mentega. Kemudian bakar. Bisa saja digoreng. Sesuai selera\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1376, 3, 'Ayam ukep bakar', 'Ayam ukep bakar dengan bumbu meresap sempurna.', '[\"Bahan\", \"2 potong ayam yang sudah di ukep (ukuran besar)\", \"Bumbu oles\", \"3 sdm kecap manis (aku pakai merk bango)\", \"2 butir bawang putih (haluskan)\", \"1 sdm minyak goreng\"]', '[\"Siapkan teflon,olesi dengan minyak sampai rata\", \"Kalau sudah panas masukan ayam ke teflon sambil di olesi bumbu oles\", \"Sering2 dibalik dan sering2 di olesi bumbu oles. (aku olesi terus2an biar bumbu nya meresap)\", \"Setelah sudah matang,angkat dan sajikan😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1377, 3, 'Ayam Asam Manis', 'Resep Ayam Asam Manis ala rumahan yang dijamin menggugah selera.', '[\"5 potong ayam bagian dada, potong lagi lebih kecil\", \"1 sdt bawang putih halus\", \"Secukupnya garam dan merica bubuk\", \"💜Saus Asam Manis💜\", \"1/2 buah bawang bombay, potong memanjang\", \"3 siung bawang putih, cincang halus\", \"1/2 buah wortel, potong korek api\", \"4 sdm saus tomat\", \"1 sdm saus tiram\", \"1/2 sdm kecap manis\", \"1 sdm maizena, larutkan dengan 2 sdm air\", \"Secukupnya gula pasir, garam dan merica bubuk\", \"Secukupnya air\", \"Secukupnya minyak goreng untuk menumis\"]', '[\"Marinasi ayam dengan bawang putih halus, garam dan merica bubuk. Diamkan di chiller minimal 2 jam\", \"Goreng sebentar ayam hingga berkulit. Sisihkan\", \"Tumis bawang bombay dan bawang putih hingga wangi. Masukkan wortel dan ayam, tumis-tumis sebentar\", \"Masukkan saus-sausan, garam, gula pasir dan merica bubuk. Tambahkan air. Biarkan hingga mendidih. Cek rasa\", \"Tambahkan larutan maizena, biarkan hingga meletup-letup\", \"Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1378, 3, 'Bola - Bola Ayam', 'Bola - Bola Ayam - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"500 gr dada ayam fillet (haluskan dgn blender)\", \"3 siung bawang putih (iris halus)\", \"4 siung bawang merah (iris halus)\", \"1 btr telur\", \"secukupnya Merica bubuk\", \"secukupnya Garam\", \"secukupnya Royco\", \"secukupnya Tepung sagu\", \"Daun bawang (iris halus)\"]', '[\"Campur semua bahan diatas,ambil sejumput lalu gr. Untuk tes rasa...\", \"Bulatkan dgn bantuan sendok,lalu goreng. Angkat setelah matang,sajikan dech 😉\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(1379, 3, 'Fillet Ayam Bumbu Caramel ala Lila\'s Kitchen', 'Buat Fillet Ayam Bumbu Caramel ala Lila\'s Kitchen yang nikmat dengan langkah-langkah mudah ini.', '[\"1/4 kg ayam (yg bertulang potong kecil*, daging iris agak tipis)\", \"Tepung maizena secukupnya (sbg baluran utk bwt ayam crispy)\", \"3 siung bwg putih + 1 sdt merica + garam (dihaluskan/blender)\", \"4 siung bwg merah (a)\", \"3 siung bwg putih (a)\", \"Lombok segar yg blm lembek (a)\", \"1 btg sereh (b)\", \"5 lbr daun jeruk (b)\", \"sesuai selera Kecap manis\", \"/- 3 sdm gula merah yg sudah diiris-iris\", \"Garam\", \"Royco\"]', '[\"Campurkan ayam mentah bersih dgn bumbu halus (bwg putih+merica+garam) tanpa air. Diamkan +/- 30 menit.\", \"Panaskan minyak goreng sambil baluri ayam tadi dgn tepung maizena (tanpa air). Lalu goreng ayam dgn api kecil supaya ayam bisa benar-benar matang & crispy bisa awet.\", \"Blender kasar semua bahan (a) dan iris tipis-tipis memanjang bahan (b)\", \"Tumis bahan (a) dan (b) sampai harum. Masukkan gula merah, garam, royco dan terakhir masukkan kecap manis aduk dgn bumbu hingga rata (jgn terlalu lama krn caramel bisa keras). Cicipi rasa.\", \"Masukkan ayam crispy yg sdh digoreng tadi. Aduk-aduk sebentar saja sampai rata lalu angkat & sajikan 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1380, 3, 'Semur Ayam, Tahu, Kentang', 'Semur Ayam, Tahu, Kentang dengan bumbu meresap sempurna.', '[\"1/4 kg Sayap ayam\", \"2 buah kentang sedang\", \"1 kotak besar tahu (potong sesuai selera lalu goreng)\", \"5 siung bawang putih\", \"5 siung bawang merah\", \"secukupnya Merica\", \"secukupnya Garam\", \"secukupnya Gula\", \"secukupnya Kecap\", \"secukupnya Air\", \"5 butir lombok (sesuai selera)\"]', '[\"Haluskan bawang merah dan bawang putih. Tumis hingga harum. Beri kecap dan air. Masak sebentar, lalu masukkan ayam.\", \"Setelah agak empuk, masukkan kentang, tahu, dan lombok.\", \"Masukkan gula, garam, merica. Tes rasa. Masak hingga ayam dan kentang empuk.\", \"Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1381, 4, 'Tongseng ayam tahu', 'Buat Tongseng ayam tahu yang nikmat dengan langkah-langkah mudah ini.', '[\"500 gr ayam dipotong kecil2\", \"2 bh tahu dipotong kotak2 dan digoreng 1/2 matang terlebih dahulu\", \"500 ml santan (me: kara plus air)\", \"1 bt daun sereh\", \"Bumbu halus:\", \"5 siung bawang merah\", \"5 siung bawang putih\", \"2 bh cabe merah\", \"4 bh cabe rawit (bs dikurangi utk yg tdk suka pedas)\", \"2 bh kemiri\", \"secukupnya Garam\", \"secukupnya Gula\", \"Penyedap rasa\"]', '[\"Haluskan bumbu. Kemudian tumis bumbu sampai wangi kemudian masukkan sereh..\", \"Masukkan ayam. Tumis ayam hingga matang dan sedikit berair. Kemudian tuang santan.\", \"Masukkan tahu. Masak hingga bumbu meresap dan ayam empuk. Kemudian masukkan tomat.\", \"Koreksi rasa. Jika rasa sdh pas dan ayam sdh empuk, matikan kompor\", \"Angkat dan sajikan. Lebih yummy diberi taburan bawang goreng diatasnya.\", \"Selamat mencoba dan menikmati. 😊😊😊👍👍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1382, 4, 'Ayam kecap taoge', 'Ayam kecap taoge - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1/4 daging ayam\", \"secukupnya Toge\", \"3 bawang putih\", \"5 bawang merah\", \"sesuai selera Cabai\", \"Daun salam+daun jeruj\", \"sedikit Lengkuas\", \"sedikit Daun sletdri\", \"Kecap manis\", \"Minyak untuk menumis\", \"Bumbu rèbus:\", \"1 bawang putih\", \"Ketumbar\", \"Garam\", \"Sedikit penyedap\", \"Serai\", \"Haluskan bumbu kecuali serai\"]', '[\"Rebus ayam dengan bumbu halus sampai empuk lalu tiriskan\", \"Panaskan wajan berisedikit minyak tumis semua bumbu sampai harum masukkan ayam beri kecap kasih sedikit air cicipi rasa setelah matang sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1383, 2, 'Cap Cay Ayam', 'Resep Cap Cay Ayam ala rumahan yang dijamin menggugah selera.', '[\"2 siung bawang putih\", \"1 ruah jahe\", \"Daum bawang\", \"Bawang bombay\", \"potong dadu Ayam\", \"Kol\", \"Wortel\", \"Brokoli\", \"Sawi\", \"Lada bubuk\", \"Saos tiram\", \"Kecap asin\", \"Minyak wijen\", \"Minyak goreng\"]', '[\"Tumis bawang putih dan jahe yg dihaluskan tunggu hingga kecoklatan\", \"Masukan potongan ayam aduk, tambahkan air, soas tiram, kecap asin, minyak wijen, gula dan garam hingga ayam matang\", \"Tambahkan wortel tunggu hingga empuk kemudian masukan brokoli, kol, sawi, bawang bombay dan daun bawang aduk hingga rata dan layu\", \"Setelah semua layu angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1384, 2, 'Chicken Katsu', 'Sajian Chicken Katsu yang praktis dan lezat untuk dinikmati bersama.', '[\"250 gr dada ayam (iris tipis saja)\", \"Secukupnya tepung bumbu\", \"Secukupnya tepung panir\", \"Saus:\", \"1 butir bawang putih cincang\", \"1 SDM minyak wijen\", \"1 sdt margarin\", \"3 SDM saos tomat\", \"2 SDM saos cabe\", \"1 sdt saos tiran\", \"1 SDM kecap manis\", \"50 ml air\", \"Secukupnya gula dan merica bubuk\"]', '[\"Ambil sedikit tepung bumbu dan beri air jgn terlalu encer dan jgn terlalu kental.. sisihkan\", \"Baluri ayam dgn tepung bumbu sampai merata kemudian masukan ke adonan tepung yg telah di cairkan.. dan Balur dgn tepung panir.. lakukan sampai ayam habis dan simpan dlm freezer 30 menit saja biar memadat (sy simpan semalaman).\", \"Goreng ayam yg sudah di simpan dlm freezer hingga berubah kecoklatan.. angkat dan tiriskan..\", \"Untuk saos tumis bawang putih menggunakan margarin, sampai wangi kemudian masukan saos tomat, saos cabe, saos tiram, kecap, gula, merica bubuk, minyak wijen dan air masak hingga matang.. sisihkan\", \"Penyajian: tata nasi pada mangkok letakkan ayam di atasnya dan siram dgn saosnya.. siap di sajikan 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1385, 4, 'Crispy Chicken', 'Cara membuat Crispy Chicken yang enak dan praktis untuk keluarga.', '[\"Ayam Potong 8 (rebus stengah matang pakai garam + bawang putih)\", \"Merica Bubuk (Merk Ladaku)\", \"Garam\", \"Baking Powder (Merk Koepoe2)\", \"Royco Ayam\", \"Tepung Maizena (1:4 sama terigu)\", \"Tepung Terigu (4:1 sama maizena)\", \"Minyak Goreng\", \"Telur 2 butir (1 dimasukan ke mangkok dan 1 untuk campuran ayam)\"]', '[\"Campurkan ayam dengan 1 sdm baking powder, merica bubuk, garam, dan 1 butir telur, aduk rata. (Takaran bumbu sesuai selera) *jika ada sisa telur, bisa di campur ke telur yang di pisah di mangkok*\", \"Campur tepung terigu, tepung maizena, 1 sdm baking powder dan royco.\", \"Masukan 1 per satu potongan ayam ke dalam campuran tepung, sambil di cubit-cubit (penting agar ayam kribo). (Maksud di cubit disini meregangkan tepung sehingga tepung agak sedikit terlepas dan menjadi retak-retak spt gambar)\", \"Ayam yang telah di lumuri tepung dicelup kedalam telur yang ada di mangkok terpisah. Ulangi langkah ke tiga.\", \"Setelah semua ayam sudh di lumuri tepung kembali dan di cubit-cubit goreng hingga berwarna kuning keemasan.\", \"Ayam Crispy siap di hidangkan. (Saus cocolan aku biasa pakai sambal ayam goreng ABC)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1386, 4, 'Gulai ayam', 'Resep praktis Gulai ayam yang bisa dicoba di rumah.', '[\"1/2 kg ayam\", \"2 bh kentang\", \"5 bh kacang panjang\", \"1 ruas jahe\", \"1 ruas lengkuas\", \"3 bh daun jeruk\", \"2 bh daun salam\", \"200 cc santan kental\", \"1 bh serai\", \"Bumbu halus\", \"6 bh bawang merah\", \"4 bh bawang putih\", \"1 ruas kunyit\", \"4 bh cabe rawit\", \"3 bh kemiri\"]', '[\"Tumis bumbu halus, serai, daun salam, daun jeruk, jahe, lengkuas sampe harum\", \"Masukkan ayam. Tambahkan air dan santan. Tnggu sampe setengah matang\", \"Masukkan kentang, selang bbrp menit masukkan kacang panjang. Beri garam gula sesuai selera\", \"Tunggu hingga kuah mengental, lalu sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1387, 4, 'Sayap Ayam (Saus) Margarin', 'Sajian Sayap Ayam (Saus) Margarin yang praktis dan lezat untuk dinikmati bersama.', '[\"8 buah sayap ayam, cuci bersih\", \"1/2 buah bawang bombay, potong panjang\", \"3 siung bawang putih, geprek dan cincang halus\", \"1/2 dt saus tiram\", \"1/4 sdt kecap Inggris\", \"1/2 sdt kecap manis\", \"1/4 sdt kecap asin\", \"secukupnya Gula dan merica bubuk\", \"75 gr margarin\", \"100 ml air\", \"Bahan rendaman ayam:\", \"2 sdt air jeruk nipis\", \"secukupnya Garam\"]', '[\"Lumuri ayam dengan garam dan air jeruk. Diamkan selama kurang lebih 10 menit.\", \"Panaskan minyak, goreng ayam hingga kuning kecoklatan. Angkat dan tiriskan\", \"Lelehkan margarin, tumis bawang bombay dan bawang putih hingga harum. Masukkan saus tiram, kecap Inggris, dan kecap manis. Masukkan ayam goreng. Aduk rata.\", \"Tambahkan air. Beri merica dan gula secukupnya. Koreksi rasa. Masak hingga meresap.\", \"Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1388, 4, 'Gule nagka kacang pnjang, kepala ayam sadappppp', 'Resep Gule nagka kacang pnjang, kepala ayam sadappppp ala rumahan yang dijamin menggugah selera.', '[\"Nanka, kacang pnjang, kepala ayam, santan,gula,garam,peyedap,\", \"Daun jeruk Sama daun salam\", \"Bumbu, yg di halus kan, bawang merah putih, kemiri jahe, kuyit\", \"Lengkuwas, ketumbar kemiri, merica, cabe keriting, sereh,,,\"]', '[\"Nanka kacang pnjang kepala ayam, di rebus,\", \"Bumbu yg sudah di blender, di tumis sampai harum, daun jeruk sama daun salam, masukan nanka kacang pnjang kepala ayam, di gongso, trus masuk kan santan hingga mendidih\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1389, 4, 'Chicken Nugget', 'Chicken Nugget - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"2 dada ayam tanpa tulang\", \"2 bawang putih\", \"1 telor\", \"4 sdm tepung tapioka\", \"1 sdt garam\", \"1/2 sdt merica\", \"5 gelas tepung panko\", \"5 sdm tepung bumbu\", \"1/2 gelas air\", \"1 liter minyak goreng\"]', '[\"Masukan ayam kedalam food processor/blender beserta bawang putih, garam & merica. Giling sampai halus. Pindahkan ke dalam wadah lalu masukan tepung tapioka & telor. Aduk rata.\", \"Panaskan panci kukusan berisi air, masukan adonan ayam ke dalam wadah/loyang tahan panas kurang lebih 1 cm. Padatkan lalu kukus 30 menit\", \"Angkat. Biarkan sampai benar2 dingin\", \"Lalu potong2 sesuai selera\", \"Letakan tepung panko dalam wadah, dan tepung bumbu di larutkan dgn air 1/2 gelas aduk rata.\", \"Celupkan potongan nugget kedalam tepung bumbu lalu ke dalam tepung panko. Balurkan merata\", \"Masukan ke dalam wadah, tutup rapat. Masukan dalam kulkas 1-2 jam\", \"Panaskan minyak lalu goreng sampai kecoklatan. Angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1390, 4, 'Opor ayam simple', 'Resep Opor ayam simple yang lezat dan mudah dibuat di rumah.', '[\"1/2 kg ayam\", \"2 bungkus bumbu instan opor indofood\", \"2 sdt bumbu kunyit (saya pakai desaku bumbu kunyit)\", \"1 bungkus sunkara kecil\", \"secukupnya Air, gula pasir, minyak goreng, masako ayam\"]', '[\"Cuci ayam sampai bersih lalu taburin garam. Diamkan 1/2 jam lalu cuci bersih\", \"Tumis bumbu instan indofood sampai harum\", \"Masukkan air dan ayam\", \"Tambahkan bumbu kunyit bubuk, masako ayam dan gula pasir. Aduk sampai rata\", \"Masukkan sunkara dan aduk rata. Jangan sampai masih ada santan yang menggumpal\", \"Cek rasa. Jika dirasa sudah cukup tunggu hingga mendidih.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1391, 2, 'Semur Ayam Bumbu Merah', 'Hidangan ayam lezat: Semur Ayam Bumbu Merah untuk keluarga tercinta.', '[\"1/2 kg ayam\", \"1 sdm kecap manis\", \"Bumbu halus:\", \"3 buah cabai merah\", \"5 siung bawang merah\", \"5 siung bawang putih\", \"2 butir kemiri\"]', '[\"Tumis bumbu halus sampai harum. Masukkan daging ayam. Aduk rata.\", \"Masukkan 500ml air. Bumbui dengan garam, merica, dan penyedap rasa.\", \"Diamkan hingga airnya surut, masukkan kecap, aduk rata.\", \"Semur ayam siap disajikan. Selamat memasak 💙🍽\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1392, 4, 'Semur Ayam', 'Hidangan ayam lezat: Semur Ayam untuk keluarga tercinta.', '[\"1/2 ekor ayam (12 potong), rebus sampai matang\", \"6 buah tahu kotak, potong jadi 4 segitiga per buah\", \"4 buah kentang, potong jadi 6 per buah\", \"2 lembar daun salam\", \"1 batang sereh, geprek\", \"6 buah cengkeh\", \"1 buah kayu manis\", \"1 sdm kaldu ayam bubuk\", \"1/2 sdm garam\", \"1/2 sdm merica\", \"1 sdm pala bubuk\", \"6 sdm kecap manis\", \"3 sdm kecap inggris\", \"300 ml air kaldu ayam (sisa rebusan ayam)\", \"300 ml air biasa\", \"Bumbu halus:\", \"6 siung bawang merah\", \"4 siung bawang putih\", \"1 ruas jahe, sangrai terlebih dahulu\", \"4 biji kemiri, sangrai terlebih dahulu\", \"1 sdm ketumbar, sangrai terlebih dahulu\"]', '[\"Goreng ayam, kentang, dan tahu secara terpisah, kemudian sisihkan\", \"Panaskan minyak, tumis bumbu halus, daun salam, cengkeh, kayu manis, sereh (sampai wangi)\", \"Masukkan kecap manis, kecap inggris, kaldu ayam bubuk, garam, merica, pala bubuk\", \"Masukkan ayam, kentang, dan tahu yg sudah digoreng, kemudian aduk rata\", \"Masukkan air kaldu ayam dan air biasa\", \"Diamkan sampai ayam, kentang, dan tahu berubah warna dan bumbu meresap\", \"Koreksi rasa sesuai selera\", \"Sajikan dengan bawang goreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1393, 4, 'Ayam Crispy', 'Sajian Ayam Crispy yang praktis dan lezat untuk dinikmati bersama.', '[\"1/2 kg ayam potong\", \"Bahan baluran ayam :\", \"Putih telur\", \"Tepung terigu\", \"Tepung beras\", \"Garam\", \"Garlic powder\", \"Bahan rendaman ayam :\", \"Garam\", \"Merica\", \"Penyedap\", \"Micin\", \"Bawang putih parut\", \"Sedikit pala bubuk\", \"Sedikit kunyit\", \"Minyak untuk menggoreng\"]', '[\"Cuci bersih ayam potong, lalu rendam dengan bahan rendaman ayam. Diamkan kurleb 30menit.\", \"Campurkan tepung terigu & tepung beras dengan perbandingan 2:1, tambahkan garam & garlic powder.\", \"Setelah ayam meresap, balur dengan putih telur lalu tepung. Ulangi jika ingin hasil kulit yg tebal (saya hanya 1x baluran)\", \"Goreng dengan minyak panas, angkat jika sudah kuning ke emas\'n.\", \"Sajikan selagi hangat 👍🏻 Biar krenyes2.,\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1394, 4, 'Ayam goreng sambal matah', 'Resep praktis Ayam goreng sambal matah yang bisa dicoba di rumah.', '[\"Ayam kampung paha dan dada\", \"1 sachet bumbu ayam goreng royco\", \"1 Tahu\", \"1 Tempe\", \"5 siung Bawang putih\", \"20 siung Bawang merah\", \"10 Cabe rawit\", \"secukupnya Lada garam gula\", \"Sereh\", \"Jeruk nipis\"]', '[\"Cuci bersih ayam, lalu ungkep dengan bumbu royco\", \"Panaskan minyak, goreng ayam yang sudah diungkep dengan tahu tempe, tiriskan\", \"Sambal matah: potong2 bawang merah,putih,cabe lalu beri garam lada gula. Terakhir siram minyak dari goreng ayam dan jeruk nipis\", \"Sajikan dengan nasi putih, tahu dan tempe\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1395, 4, 'Kalio Ayam ala Diana\'s Kitchen', 'Resep Kalio Ayam ala Diana\'s Kitchen ala rumahan yang dijamin menggugah selera.', '[\"1 Ekor Ayam potong sesuai selera\", \"1 kelapa tua parut\", \"2 batang serai\", \"1 lembar daun kunyit\", \"Bbrp lembar daun jeruk aku suka pake bnyk hihihii\", \"Bahan2 yg di haluskan :\", \"8-10 Bawang merah\", \"4-6 Bawang Putih\", \"12 buah cabe merah besar/keriting kl suka pedas\", \"2 sdt ketumbar halus\", \"Lengkuas 2 ruas jari kupas kulitnya\", \"Jahe 2 ruas jari kupas kulitnya\", \"Kunyit 4 ruas jari kupas kulitnya\", \"Boleh tambah asam kandis kl suka yaa Mom\'s\", \"Gula, Garam, lada..\", \"Optional ; Cabe rawit utuh, Ceker, AtiAmpela, Telur Rebus\"]', '[\"Pertama buat bumbu halus terlebih dahulu, boleh di ulek atw blender, suka2 aja, senyaman nya,,, tips : kl pake blender/food procesor better gunakan minyak sayur utk menghaluskan yaa mom, atw kl menggunakan air masak dgn api kecil smp kadar air redius yaa mam, coz kita perlu bumbu yg betul2 matang, biar tdk bau bumbu mentah nanti nya....\", \"Cuci ayam dan potong sesuai selera...\", \"Buat Santan, Kental & cair, buat menjadi 3 gelas santan saja yaa mom, 1 gelas santan kental, 2 gelas santan cair, kl kurang nnt tinggal tambah air saja...\", \"Tumis Bumbu dgn 3 sdm minyak sayur, tumis hingga harum, masukkan daun2 beraroma (sereh,daun kunyit, daun jeruk) masak hingga matang & harum....\", \"Masukkan santan masak hingga santan mendidih, lalu masukkan ayam, aduk hingga santan mengental dan ayam berubah warna,,,\", \"Setelah tercampur rata, masukkan santan kental, bumbui sesuai selera (kl aku biasa dominan manis sih, dan anak2 sering komplain, tp ttp di makan n abis kok 😉)\", \"Aduk hingga rata n mendidih, matikan api siap di hidangkan, pake nasi atw ketupat...\", \"Enjoyed The Food Mam #HappyCooking\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1396, 2, 'Opor ayam kuah kuning', 'Cara membuat Opor ayam kuah kuning yang enak dan praktis untuk keluarga.', '[\"1 kg ayam\", \"3 lembar daun salam\", \"65 ml santan kara\", \"secukupnya garam,penyedap rasa,gulpas\", \"bumbu halus:\", \"7 siung bawang merah\", \"4 siung bwg putih\", \"1/2 sdt jinten bubuk\", \"1/2 sdt lada bubuk\", \"1/2 sdt ketumbar bubuk\", \"3 buah kemiri\", \"1 ruas kunyit\", \"secukupnya jahe\"]', '[\"Cuci bersih ayam,lalu rebus ayam hingga 1/2 matang setelah mendidih angkat ayam(jangan buang air rebusan)\", \"Tumis bumbu halus hingga harum lalu masukan daun salam, masukan ayam,aduk rata masukan air rebusan tadi secukupnya,lalu masukan santan,aduk terus agar tidak pecah santannya hingga mendidih(jngn masukan santan dlm keadaan air mendidih karna akn pecah).klo sudah mendidih masukan gulpas,penyedap,dan garam,cek rasa.angkt sajikan,😉😉\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1397, 3, 'Ayam Geprek Diet Fatsecret kalori 206', 'Nikmati kelezatan Ayam Geprek Diet Fatsecret kalori 206 dengan resep sederhana ini.', '[\"(60) gr dada ayam tanpa kulit\", \"(1) potong Tahu\", \"(1) butir telur\", \"(5) buah cabai rawit galak\", \"(1) buah bawang putih\", \"Garam himalaya\", \"(1) sendok minyak wijen (utk menggoreng)\"]', '[\"Rebus dada ayam tanpa kulit sampai matang\", \"Goreng tahu dengan minyak sedikit (gunakan teflon anti lengket agar makanan tidak menempel pada saat dibalik)\", \"Kocok telur lepas berikan sedikit garam dan di dadar, dengan teflon (jangan pakai minyak)\", \"Untuk sambel : campurkan semua bahan untuk membuat sambal (dapat tambahkan terasi bakar) uleg\", \"Masukan ayam rebus, tahu, dan telur dadar ikut diuleg bersamaan dengan sambel yang sudah dibuat tadi.\", \"Jadi dehhh.....\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1398, 3, 'Ayam Woku bikin rindu', 'Resep Ayam Woku bikin rindu yang lezat dan mudah dibuat di rumah.', '[\"8 potong ayam\", \"1 iket daun kemangi, siangi\", \"2 batang daun bawang, iris sesuai selera\", \"Bumbu :\", \"3 cm kunyit\", \"1/2 butir kemiri\", \"1/2 sdt lada bubuk\", \"2 batang sereh, iris halus\", \"3 lembar daun salam\", \"3 lembar daun jeruk\", \"2 cm lengkuas\", \"2 cm jahe\", \"1/4 sdt gula pasir\", \"1/2 sdt garam\", \"1/2 sdt kaldu bubuk (Royco ayam)\", \"8 siung bawang merah (separuh diiris)\", \"4 siung bawang putih (separuh diiris)\", \"Cabai rawit dan cabai merah suka-suka (separuh diiris)\"]', '[\"Cuci ayam, marinate dengan jeruk nipis dan garam kurleb 10 menit. Goreng ayam hingga matang keemasan. Tiriskan.\", \"Blender halus bumbu, kecuali sereh, daun jeruk dan daun salam. Tumis bumbu halus pada minyak panas, tambahkan sereh, daun jeruk dan daun salam, aduk hingga harum dan cukup matang bumbunya.\", \"Masukkan ayam kedalam tumisan bumbu, aduk rata, masukkan ayam yang sudah digoreng. Tambahkan air sedikit (hanya untuk membuat ayam lebih empu dan juicy). Tambahkan garam, gula, dan kaldu bubuk. Tambahkan kemangi yang sudah di siangi, juga daun bawang. Aduk, tes rasa. Tunggu hingga air menyurut (biarkan ada kuahnya jangan sampai habis airnya, karna kalo pakai nasi kuahnya itu nikmaaat banget). Sajikan dengan nasi panas, dan jangan lupa cuci tangan sebelum makan, serta berdoa.\", \"Selamat menikmati ;)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1399, 2, 'Ayam Geprek Manyuss', 'Buat Ayam Geprek Manyuss yang nikmat dengan langkah-langkah mudah ini.', '[\"Ayam crispy\", \"Sambel\", \"5 cabe setan\", \"5 cabe rawit\", \"1 bawang putih\", \"1 bawang merah\", \"Garam\", \"Gula\"]', '[\"Haluskan sambel, kemudian siram minyak panas\", \"Penyet ayam di atas sambel\", \"Sajikan dengan nasi panas\", \"Selamat mencobaa 🌼\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1400, 2, 'Ayam Pedas Manis', 'Sajian Ayam Pedas Manis yang praktis dan lezat untuk dinikmati bersama.', '[\"1/2 kg ayam, ungkep, goreng\", \"2 sdm kecap manis\", \"1 sdm saos tiram\", \"Secukupnya gul-gar\", \"Dihaluskan:\", \"2 bh cabe merah\", \"3 siung bawang merah\", \"5 siung bawang putih\", \"2 butir kemiri\", \"Secukupnya ketumbar\", \"1/2 sdm gula merah\"]', '[\"Tumis bumbu yg sudah dihaluskan\", \"Masukkan ayam, kecap, saos tiram dan air\", \"Tambahkan gulgar, cek rasa, masak hingga kuah mengental.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1401, 3, 'Ayam geprek simple', 'Cara membuat Ayam geprek simple yang enak dan praktis untuk keluarga.', '[\"1/2 kg ayam bagian paha\", \"1/4 kg ceker (kalau suka)\", \"1 bks bumbu ayam goreng instan\", \"1 bks kecil tepung bumbu\", \"Bumbu ulek :\", \"10 bh bawang merah\", \"5 siung bawang putih\", \"3 bh cabai merah besar buang bijinya\", \"5 bh cabai kecil (bisa ditambahkan kalau suka pedas)\", \"secukupnya Garam\", \"secukupnya Gula\", \"Penyedap rasa (bila suka)\", \"secukupnya Minyak untuk menggoreng ayam dan bumbu ulek\"]', '[\"Potong-potong ayam sesuai selera, tambahkan bumbu ayam goreng instan yang sudah dicairkan terlebih dahulu dengan sedikit air. Campur rata berikut ceker, ungkep hingga matang\", \"Celupkan ayam dan ceker ke dalam tepung bumbu yg sudah dicairkan dengan sedikit air hingga membentuk adonan kental\", \"Goreng ayam dan ceker hingga kuning keemasan, angkat dan tiriskan\", \"Sementara itu haluskan bumbu ulek, lalu tumis hingga harum, koreksi rasa\", \"Geprek ayam dan ceker goreng, siram dengan bumbu ulek\", \"Tarraa...sajikan dengan nasi hangat dan irisan timun, hmmm, yummy...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1402, 3, 'Tumis ayam pokcoy bumbu terasi', 'Buat Tumis ayam pokcoy bumbu terasi yang nikmat dengan langkah-langkah mudah ini.', '[\"250 gr ayam fillet potong kecil\", \"500 gr pokcoy potong kecil (pisahkan daun dan tangkainya)\", \"10 bh cabe rawit\", \"2 sdm bawang putih goreng\", \"1 sdt terasi matang\", \"secukupnya Garam\", \"Minyak untuk menumis\", \"Air secukupnya (kurleb 100 ml)\"]', '[\"Haluskan cabe,bawang putih goreng,terasi\", \"Panaskan minyak masukan ayam fillet yg sdh dipotong kecil..masak sampai matang\", \"Masukan bumbu yg sdh dihaluskan tumis sampai harum\", \"Masukan tangkai pokcoy lalu kasih air\", \"Biarkan sampai layu lalu masukan garam\", \"Masukan daun pokcoy aduk diamkan sebentar sampai agak layu\", \"Angkat dan sajikan\", \"Taburi bawang goreng diatas masakan,kalau tdk suka bisa di skip\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1403, 2, 'Ayam Panggang', 'Nikmati kelezatan Ayam Panggang dengan resep sederhana ini.', '[\"1 kg ayam\", \"Bumbu halus :\", \"200 gr jahe\", \"2 batang serai\", \"100 gr cabai rawit burung\", \"10 bh cabai merah keriting\", \"10 siung bawang merah\", \"5 siung bawang putih\", \"Bahan lain :\", \"200 gr gula merah\", \"100 gr asam jawa\", \"secukupnya Garam\", \"secukupnya Royco rasa ayam\", \"3 sendok sayur minyak goreng\", \"300 cc air\"]', '[\"Tumis bumbu halus sampai harum dengan minyak goreng\", \"Masukkan potongan ayam yg sudah dibersihkan. Aduk rata.\", \"Tambahkan air, asam jawa, garam, royco dan gula merah\", \"Masak ayam hingga empuk (seperti ungkap ayam)\", \"Setelah ayam empuk, koreksi rasa. Tunggu air menyusut hingga bumbu mengental dan meresap.\", \"Matikan api. Siapkan teflon atau panggangan, panggang ayam.\", \"Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1404, 3, 'Ayam pop ala ala', 'Sajian Ayam pop ala ala yang praktis dan lezat untuk dinikmati bersama.', '[\"1/2 kg ayam potong\", \"2 butir air kelapa\", \"bumbu halus:\", \"4 siung bawang putih\", \"4 siung bawang merah\", \"kemiri dan jahe\", \"bumbu pelengkap:\", \"salam 3 lbr,daun jeruk 5 lembar,lengkuas,2 batang sere\", \"secukupnya garam dan gula\"]', '[\"Bahan pelengkap ditata di tempat untuk memasak,kemudian taruh ayamnya juga kemudian ditambah bumbu yg sudah dihaluskan\", \"Masukkan air kelapa rendam ayam dan bumbu kemudian masak dengan api sedang\", \"Tunggu hingga air menyusut dan masukkan garam dan gula koreksi rasa\", \"Bila sudah menyusut angkat ayam...\", \"Ayam boleh di goreng sebentar kira kira 10 detik di minyak yg panas kmudian angkat.\", \"Air kelapa sisa merendam ayam tadi jangan dibuang, bisa untuk merebus daun singkong sebagai pelengkap makan.dan bisa disajikan dengan sambal sesuai selera\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1405, 4, 'Ayam Presto /Ayam Goreng Tepung', 'Resep Ayam Presto /Ayam Goreng Tepung ala rumahan yang dijamin menggugah selera.', '[\"1 ekor ayam potong sesuai selera\", \"Bumbu presto 💕\", \"5 siung bawang putih\", \"3 buah kemiri\", \"1 ruas kunyit\", \"2 sdm ketumbar\", \"1 sdm munjung garam\", \"Adonan encer 💕\", \"3 sdm munjung tepung terigu\", \"1 sdm munjung tepung beras\", \"2 sdt saj*ku bumbu ayam goreng\", \"secukupnya Air\", \"Adonan kering 💕\", \"8 sdm munjung tepung terigu\", \"3 sdm munjung tepung beras\", \"2 sdm saj*ku bumbu ayam goreng\"]', '[\"Haluskan bumbu presto. Balurkan pd ayam yg sudah dipotong dan dicuci\", \"Presto ayam ±25-30 menit. Sy tambahkan daun jeruk biar harum. *boleh ditambah serai jika ada\", \"Campurkan adonan encer *jangan terlalu encer\", \"Campurkan adonan kering\", \"Ini hasil ayam yg sudah di presto\", \"Goreng ayam. Masukkan ayam yg sudah di presto pd adonan encer kemudian adonan kering satu persatu\", \"Ayam siap santap\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1406, 3, 'Ayam Terong Goreng Balado', 'Ayam Terong Goreng Balado dengan bumbu meresap sempurna.', '[\"4 potong ayam\", \"1 buah terong, dipotong sesuai selera\", \"2 sdm cabe giling kasar (cabenya sudah pake bawang)\", \"2 biji kecil asam jawa kasih air 1 sdm, diremas. Ambil airnya\", \"1 buah tomat iris kasar jangan terlalu besar\", \"1 sdm gula/secukupnya\", \"1 sdt garam/secukupnya\", \"5 sdm minyak goreng/secukupnya\", \"1 sdt jahe giling halus\", \"1 sdt bawang putih giling halus\", \"Note:\", \"Asam jawa bisa diganti cuka, sesuaikan saja\"]', '[\"Rebus ayam menggunakan jahe dan bawang putih, goreng, dan tiriskan\", \"Goreng terong dan tiriskan\", \"Panaskan minyak menggunakan api sedang, masukkan tomat, goreng hingga tomat sedikit menjadi lembek dan wangi, lalu masukkan cabe, air perasan asam jawa, aduk aduk hingga cabe matang dan wangi. Tambahkan gula dan garam. Koreksi rasa.\", \"Setelah cabe matang dan wangi (tidak ada bau mentah lagi) masukkan ayam dan terong, lalu diaduk sebentar hingga rata. Jangan terlalu lama takut ayamnya malah menjadi keras.\", \"Angkat dan sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1407, 4, 'Soto Ayam kuah bening', 'Soto Ayam kuah bening dengan bumbu meresap sempurna.', '[\"Ayam potong 1/4 kg\", \"1 bungkus sedang Bihun jagung\", \"Taoge\", \"Bumbu halus:\", \"Bawang merah\", \"Bawang putih\", \"Biji pala\", \"Ketumbar\", \"Jahe\", \"Lengkuas (geprek)\", \"Sereh (geprek)\", \"Daun jeruk\", \"Daun salam\", \"Daun bawang (iris)\", \"Seledri (iris)\", \"Tomat (iris)\", \"Garam\", \"Sambal:\", \"Cabe direbus haluskan\"]', '[\"Rebus ayam kasih daun salam dan garam lalu goreng suwir suwir. Bihun jagung dan toge disiram menggunakan air panas sampai matang.\", \"Masak air kurang lebih 2 liter lalu masukkan bumbu halus tadi. Aku pakai tetelan tulang dan kulit ayam yang tadi direbus agar ada sedikit lemaknya\", \"Masukkan tomat daun bawang dan seledri\", \"Tunggu sampai mendidih\", \"Setelah itu tata dan siap sajikan dengan sambal\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1408, 4, 'Buttermilk chiken wings ala Gerry girianza', 'Cara membuat Buttermilk chiken wings ala Gerry girianza yang enak dan praktis untuk keluarga.', '[\"6 potong sayap ayam (dipotong dua)\", \"125 ml susu full cream\", \"1 buah lemon\", \"1 bungkus tepung bumbu ayam crispy (aku pakai sasa)\", \"Secukupnya garam\", \"Secukupnya gula\", \"Secukupnya black papper\", \"Secukupnya minyak goreng\"]', '[\"Lumuri ayam dgn garam, gula, blackpapper, lalu campurkan susu dan juga jeruk lemon, diamkan sekitar 30 menit(lebih enak apabila direndam semalaman dikulkas)\", \"Lalu lumuri ayam kedalam tepung bumbu crispy\", \"Goreng dengan minyak panas(api sedang)\", \"Setelah ayam kuning keemasan, angkat dan siap dinikmati\", \"Tambahan untuk sauce : 1 sendok makan sauce cabe merk ibu jari, 1 sendok makan sauce bangkok merk indofood, 1/2 sendok makan butter yang sudah dilelehkan, kalau bang gerry saucenya dilumuri ke ayam, kalau aku dipisah aja biar ayamnya tetep crispy, mantapppp 😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1409, 3, 'Spicy Chicken Drumstick', 'Sajian Spicy Chicken Drumstick yang praktis dan lezat untuk dinikmati bersama.', '[\"4 potong sayap ayam\", \"Tepung bumbu S*s* hot n spicy\", \"1 butir telur ayam\", \"secukupnya Garam\", \"Minyak goreng\"]', '[\"Potong sayap ayam menjadi dua bagian. Kemudian kerat daging ayam(jangan sampai putus) lalu satukan di salah satu ujung tulang. Untuk sayap yg mempunyai dua tulang, lakukan hal yg sama. Patahkan dan buang tulang yg lebih kecil. Bentuk seperti drumstick.\", \"Rebus ayam dengan sedikit garam.\", \"Setelah matang, angkat ayam lalu beri 2 sdm tepung bumbu dan sedikit air. Diamkan selama 15 menit.\", \"Setelah itu balut ayam dengan tepung bumbu kering, celupkan ke telur lalu balut tepung kembali.\", \"Goreng dengan cara deep frypan. Setelah matang, angkat. Sajikan dengan saos tomat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1410, 3, 'Ayam Goreng Lengkuas', 'Hidangan ayam lezat: Ayam Goreng Lengkuas untuk keluarga tercinta.', '[\"1 kg Ayam\", \"1 ons Lengkuas (parut)\", \"3 lembar Daun Salam\", \"500 ml Air\", \"sesuai selera Kaldu Bubuk\", \"1 sdm Gula Pasir\", \"Bumbu Halus\", \"-5 siung Bawang Merah\", \"3 Siung Bawang Putih\", \"1 ruas kunyit\", \"Minyak Goreng secukup\'nya\"]', '[\"Siapkan air dlm panci, masukan Ayam yg telah dicuci,daun salam,lengkuas,bumbu halus, kaldu bubuk,gula pasir.\", \"Ungkep Ayam smp air menyusut,tes rasa. Setelah air menyusut, angkat ayam.Dingin\'kan, goreng dlm minyak panas\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1411, 4, 'Ayam Kecap/Semur', 'Buat Ayam Kecap/Semur yang nikmat dengan langkah-langkah mudah ini.', '[\"Ayam 4 potong dan 6 ceker\", \"8 potong Tahu goreng\", \"1/2 Bawang bombay iris panjang\", \"1 buah Tomat iris halus\", \"Bumbu halus:\", \"1 sendok makan bawang putih\", \"1 sendok makan bawang merah\", \"1 ruas Jahe\", \"secukupnya Kecap manis\", \"Sedikit saus tiram\", \"Merica\", \"Pala\"]', '[\"Goreng terlebih dahulu ayam dan tahu, setelah itu sisihkan\", \"Lalu tumis bawang merah dan bawang putih sampai wangi, disusul dengan ayam dan tahu, tambahkan kecap manis dan sedikit saus tiram lalu tambahkan air\", \"Masukkan juga bawang bombay dan tomat yang sudah di iris-iris.\", \"Aduk rata, jangan lupa garam merica dan pala. Aduh rata biarkan sampai bumbu meresap ke ayam dan tahu.\", \"Setelah itu siap di hidangkan. Untung pemanis bisa tambahkan irisan daun bawang tapi kali ini aku skip yaaa.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1412, 3, 'Ayam rica - rica', 'Nikmati kelezatan Ayam rica - rica dengan resep sederhana ini.', '[\"4 sayap ayam\", \"3 bawang merah\", \"5 cabe merah\", \"1 kunyit\", \"6 cabe rawit\", \"2 bawang putih\", \"1 royco ayam\", \"1 sdt garam\", \"1 sdm gula pasir\", \"Sedikit merica bubuk\", \"Serai\", \"3 lembar daun salam\", \"Kecap manis\", \"Air secukupnya aja ya\", \"Hiasan :\", \"Tomat\", \"Selada kriting\", \"Mentimun\", \"Daun kemangi\"]', '[\"Rebus ayam yang sudah di cuci bersih dengan garam,royco,kunyit,rebus hingga matang & dan tiriskan (kaldu ayamnya bisa dipakai) / ayam yang sudah di bacem\", \"Goreng ayam jangan terlalu kering\", \"Ulek bumbu halus\", \"Tumis bumbu halus sampai matang,lalu beri serai dan daun salam\", \"Setelah itu masukkan ayam, tambahkan air kaldu secukupnya, gula pasir, garam, merica bubuk,kecap manis (aduk rata & cicipi rasanya)\", \"Dan ayam rica2 siap dihidangkan (jangan lupa pakai hiasan)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1413, 3, 'Rica rica ayam no msg', 'Resep Rica rica ayam no msg ala rumahan yang dijamin menggugah selera.', '[\"1/2 kg ayam potong\", \"Bumbu :\", \"5 siung bawang putih\", \"5 siung bawang merah\", \"2 ruas lengkuah\", \"1 ruas kunyit\", \"Sedikit Kencur\", \"1/2 sdt ketumbar\", \"Ketumbar\", \"Garam\", \"1/2 sdt gula\", \"Daun jeruk\", \"2 sereh\", \"1 ruas jahe\"]', '[\"Bersihkan ayam dan dipotong sesuai selera.\", \"Haluskan smua bumbu menggunakan ulekan blender juga bisa kecuali lengkuas, jahe, daun jeruk dan sereh.\", \"Setelah dihaluskan tumis sampai harum masukkan daun jeruk, sereh dan lengkuas dan jahe yg sudah di geprek serta garam dan gula. Tumis sampai harum masukkan ayam yg sudah dibersihkan\", \"Kemudian masukkan air 1 Liter.\", \"Tunggu sampai air menyusut. Apabila kurang empuk bisa ditambahkan air dan tunggu lagi sampai menyusut kemudian tes rasa.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1414, 2, 'Ayam Kemangi', 'Hidangan ayam lezat: Ayam Kemangi untuk keluarga tercinta.', '[\"1/2 kilo dada ayam\", \"1 iket kemangi\", \"Bumbu halus\", \"3 siung bawang putih\", \"5 siung bawang merah\", \"Cabe merah cabe rawit (sesuai selera)\", \"1 kemiri\", \"1 ruas kunyit\", \"1 ruas jahe (geprek)\", \"3 lembar daun jeruk\", \"2 batang serai (geprek)\", \"Gula\", \"Garam\", \"Penyedap rasa\"]', '[\"Rebus setengah matang ayam yang sudah dipotong potong. Jangan buang kuahnya.\", \"Tumis bumbu yang sudah dihaluskan sampai harum.\", \"Masukkan daging ayam dengan kuahnya. Tutup dan biarkan sampai bumbu meresap.\", \"Masukkan kemangi. Aduk bentar. Sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1415, 2, 'Ayam Suwir Bali', 'Nikmati kelezatan Ayam Suwir Bali dengan resep sederhana ini.', '[\"350 gr filet dada ayam》rebus matang》suwir2 tipis\", \"2 cm lengkuas》geprek\", \"2 lembar daun salam\", \"2 lembar daun jeruk\", \"2 batang sereh》geprek\", \"150 ml air\", \"1 sdm gula merah\", \"pete\", \"garam\", \"gula\", \"lada\", \"bumbu halus:\", \"5 cabe merah keriting\", \"4 cabe rawit merah\", \"5 bawang merah\", \"3 bawang putih\", \"1 sdt terasi\", \"2 cm kunyit\"]', '[\"Panaskan 2 sdm minyak di wajan》tumis daun salam dan jeruk, sereh, lengkuas, dan bumbu halus hingga wangi dan matang》beri ayam》aduk rata》beri air, garam, gula, dan lada, pete》aduk rata hingga bumbu meresap dan air menyusut》cicipi》angkat 😋\", \"Yummyy !😚\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1416, 2, 'Ayam suwir pedas', 'Ayam suwir pedas - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"250 gram dada ayam\", \"15 buah cabe keriting merah\", \"3 buah cabe rawit merah\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"1 ruas kencur\", \"1 ruas kunyit\", \"1 sdt terasi\", \"2 lembar daun salam\", \"4 lembar daun jeruk\", \"2 serai, geprek\", \"2 iris lengkuas\", \"2 sendok makan air asam jawa\", \"2 sendok gula merah sisir\", \"Garam\", \"Kaldu bubuk\", \"300 ml air\", \"Minyak untuk menumis\"]', '[\"Cuci bersih ayam, blansir, cuci lagi. Kemudian direbus sampai matang dan disuwir2. Sisihkan\", \"Haluskan cabe, bawang merah putih, terasi, kencur, kunyit, sedikit garam\", \"Tumis bumbu halus sampai setengah matang kemudian masukkan serai geprek, daun salam, daun jeruk, lengkuas. Tumis sampai matang dan masukkan air\", \"Setelah mendidih, masukkan ayam suwir. Aduk2 dan tambahkan gula merah sisir, garam, kaldu bubuk dan air asam jawa\", \"Aduk2 lagi dan sesuaikan rasa. Masak hingga sat. Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1417, 3, '005 ayam penyet', 'Hidangan ayam lezat: 005 ayam penyet untuk keluarga tercinta.', '[\"1/4 kg ayam\", \"4 siung bawang merah\", \"2 siung bawang putih\", \"1 ruas kunyit\", \"1 ruas jahe\", \"1/2 sdm ketumbar\", \"3 lembar daun jeruk purut\", \"Garam\", \"Penyedap rasa\", \"Minyak goreng\", \"Air\", \"Bahan sambal\", \"10 buah cabe rawit\", \"5 buah cabe merah keriting\", \"1 buah tomat\", \"4 siung bawang merah\", \"2 siung bawang putih\", \"Air jeruk purut\", \"Gula pasir\", \"Garam\"]', '[\"Siapkan bahan\", \"Cuci ayam sampai bersih, lalu marinasi dgn garam, sisihkan. Buat bumbu halus.\", \"Campurkan bumbu halus ke ayam, ratakan, tambahkan air sampai ayam ter rendam, lalu masukan daun jeruk purut yang sudah d robek. Ungkep ayam sampai air ny susut.\", \"Goreng bahan² sambal, sampai layu-kecuali jeruk-. Lalu d tumbuk kasar. (Sebelum digoreng, kasih irisan di tomat dan cabe rawit, spy tdk meletup saat d goreng). sisihkan.\", \"Goreng ayam di minyak panas sampai kuning keemasan, tambahkan sedikit minyak panas ke sambal yg sudah d tumbuk. Masukkan ayam yang sudah digoreng kedalam cobek, penyet dengan sambal, beri perasan air jeruk purut. Sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1418, 4, 'Ayam Gepreeekk', 'Hidangan ayam lezat: Ayam Gepreeekk untuk keluarga tercinta.', '[\"250 gram ayam (dada)\", \"200 gram tepung bumbu kentucky\", \"Secukupnya masako\", \"Sambal:\", \"15 cabe rawit\", \"2 siung bawang putih\", \"4 siung bawang merah\", \"Secukupnya garam\"]', '[\"Ayam di potong sesuai selera, rebus agar matang sempurna, lalu rendam ke dalam masako -/+ 15 menit.\", \"Setelah itu angkat dari rendaman masako, lalu masukkan kedalam tepung bumbu kentucky. Jangan lupa di tepuk-tepuk agar tepung menyatu dengan ayam\", \"Goreng dalam minyak yang panas, usahakan hingga terendam minyak. Setelah kecokelatan angkat lalu tiriskan\", \"Membuat sambal:\", \"Goreng sebentar bawang merah dan putih agar tidak langu.\", \"Setelah itu uleg bersama cabe dan beri sedikit garam. Masukkan ayam goreng tepung ke tempat sambal. Lalu gepreek bersama sambalnya\", \"Ayam geprek siap dihidangkan 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1419, 4, 'Chicken katsu', 'Resep praktis Chicken katsu yang bisa dicoba di rumah.', '[\"1 ekor ayam, iris pipih ambil bagian dagingnya saja\", \"1/4 tepung roti\", \"1/8 terigu\", \"Bumbu halus:\", \"1 sdm ketumbar\", \"2 bawang putih\", \"Garam\", \"1 sdt lada\", \"Bumbu sambal:\", \"1 sdm mentega\", \"Saos tomat\", \"Saos sambal\", \"Saos tiram\"]', '[\"Campurkan terigu dg air, buat adonan mengental. Masukan bumbu halus dan tambahkan garam. Aduk rata.\", \"Celupkan ayam yg telah diiris pipih ke dalam adonan, kemudian angkat dan baluri dengan tepung roti.\", \"Masukan freezer, tunggu membeku. Kemudian Goreng.\", \"Bumbu sambal: panaskan 1 sdm mentega. Kemudian masukan saos sambal, saos tomat dan saos tiram. Tambahkan sedikit air, buat saos mengental. Tunggu sampai mendidih, angkat.\", \"Tuang sambal diatas chicken katsu yg telah digoreng, sajikan hangat-hangat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1420, 2, 'Mie Ayam Lezat', 'Mie Ayam Lezat - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"Bahan Kuah :\", \"2 Liter air bersih\", \"1/4 kg tulang ayam (aku SKIP ganti pake 1 ons udang)\", \"1/2 sdt penyedap (aku SKIP ganti gula)\", \"secukupnya garam\", \"Bumbu halus kuah :\", \"2 siung bawang putih\", \"1/2 ruas jari jahe\", \"1/2 ruas jari kunyit\", \"1 butir kemiri\", \"Bahan topping mie ayam :\", \"1/4 kg daging dan kulit ayam (potong kecil, cuci bersih)\", \"7-10 sdm kecap manis\", \"3 gelas air bersih\", \"1 helai daun pree, iris untuk taburan\", \"Bumbu halus topping mie ayam :\", \"4 butir bawang merah\", \"3 siung bawang putih\", \"3 lembar daun jeruk\", \"1 ruas jari lengkuas\", \"1 ruas jari kunyit\", \"1 ruas jari jahe\", \"1/2 ruas jari kencur\", \"1/2 sdt ketumbar (aku SKIP)\", \"4 butir kemiri\", \"secukupnya gula, garam\", \"Bahan pelengkap :\", \"4 keping mie telur homemade (resep sebelah) rebus sampai matang\", \"sawi hijau, rebus\", \"secukupnya saus sambal\"]', '[\"Kuah ; tumis bumbu halus sampai harum, tambahkan air dan sisa bahan rebus sampai matang, sisihkan\", \"Topping Mie Ayam ; tumis bumbu halus topping mie ayam masukkan daging dan kulit ayam, aduk rata masak sampai matang lalu tuang air dan sisa bahan topping masak sampai matang\", \"Penyajian : dalam mangkok saji masukkan mie telur secukupnya, tuang kuah, topping mie ayam, sawi dan saus sambal\", \"Sajikan...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1421, 3, 'Sop ceker vs pala ayam', 'Sop ceker vs pala ayam dengan bumbu meresap sempurna.', '[\"1 kg ceker&kepala ayam\", \"1 bungkus sayuran buat sop2an.(yng simpel aja.beli udah komplit)\", \"1 bungkus ladaku\", \"1 bungkus masako\", \"Bawang merah&putih\", \"secukupnya Seledri,bawang daun\", \"1 buah tomat merah\"]', '[\"Pertama2 bersihkan cker sma pala ayam.lalu cuci bersih.dan rebus sampai stengah mtang\", \"Potong sayuran sesuai selera\", \"Iris bawang merah.bawang putih\", \"Panaskan wajan dan tambahkan sedikit minyak goreng\", \"Tumis bawang putih&merah.sampai harum.lalu masukkan sayuran yng sudah di potong.orak arik sbentar sampai sdikit layu.masukan masako&ladaku.klo perlu tambah garam sedikit\", \"Tambahkan air secukupnya.biarkan sbentar.sambil nunggu air mendidih.potong sledri,bawang daun&tomat.\", \"Masukkan cker&pala ayam jika air sudah mendidih.tambahkan ptongan sledri dll nya.biarkan sampai matang\", \"Icip2 saja.klo sudah sesuai selera lidah yng masak.boleh langsung di sajikan.....\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1422, 4, 'Ceker vs pala ayam bumbu kecap', 'Nikmati kelezatan Ceker vs pala ayam bumbu kecap dengan resep sederhana ini.', '[\"1/4 kg cker& pala ayam\", \"1/2 ruas kunyit\", \"2 buah cabe merah\", \"1 bungkus kecap manis\", \"1/2 ruas lengkuas&jahe\", \"secukupnya Garam&gula\", \"2 siung bawang merah&putih\", \"1 bungkus ladaku&ketumbar bubuk\"]', '[\"Cker dan pala ayam yng sudah di bersihkan,lalu di rebus sampai matang.sisihkan\", \"Sambil nunggu matang.ulek kunyit,bawang merah&putih,cabe.tambahkan merica bubuk&ladaku.\", \"Tumis bumbu halus sampai harum, masukan lengkuas dan jahe. tambahkan air secukupnya.lalu tambahkan kecap sesuai selera.jngan lupa garam&gula juga ikut di masukan yh.biarkan sbentar sambil di icip2.\", \"Setelah di rasa bumbu pas.langsung saja msukan cker dan pala ayamnya.tunggu sampai airnya tinggal sedikit dan bumbu mresap.....\", \"Ceker vs pala ayam bumbu pun siaaaappppp di nikmati\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(1423, 4, 'Gulai Ayam', 'Resep Gulai Ayam ala rumahan yang dijamin menggugah selera.', '[\"1/2 kg ayam cuci bersih\", \"1 kentang potong dadu\", \"1 tomat sedang potong dadu\", \"1 wortel sedang potong spt bunga\", \"bumbu halus :\", \"5 bawang merah\", \"3  bawang putih\", \"3  kemiri\", \"1  ruas  jahe\", \"1  ruas  kunyit\", \"secukupnya  garam\", \"1 sdt ketumbar,\", \"2 sereh geprek\", \"1 ruas laos, geprek\", \"daun salam dan daun jeruk\", \"secukupnya air\", \"Gula Garam dan penyedap rasa\", \"1 santan kara ukuran sedang\"]', '[\"Tumis bumbu halus sampai wangi tambahkan daun salam, daun jeruk, sereh, laos dan air biarkan mendidih\", \"Masukkan ayam, kentang, dan wortel biarkan mendidih sebentar lalu masukan Gula Garam dan penyedap rasa biarkan ayam wortel dan kentang sampe empuk\", \"Jika ayam sudah empuk masukan santan aduk aduk jangan sampai pecah, masukan tomat, tes rasa dan siap di sajikan dengan nasi hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1424, 4, 'Ayam goreng bumbu kuning', 'Resep Ayam goreng bumbu kuning yang lezat dan mudah dibuat di rumah.', '[\"1 kg ayam\", \"bumbu haluskan :\", \"4 siung besar bawang merah\", \"2 siung bawang putih\", \"1 sdt merica bubuk\", \"3 pcs ketuncar\", \"1/2 rus kuning\", \"garam\", \"gula pasir\", \"salam\", \"sereh (geprek dan simpulkan)\", \"minyak goreng\"]', '[\"Haluskan bumbu,\", \"Panaskan minyak, tumis bumbu sampai harum dan masukan salam dan sereh\", \"Beri air sedikit\", \"Masukan ayam yg sudah d cuci dan di potong potong\", \"Tunggu sampai bumbu meresap sekitar 10 - 15 menit sambil cicipi bumbu yang kurang\", \"Jika sudah meresap daging sudah matang tiriskan\", \"Panaskan minyak untuk menggoreng daging tunggu sampai kecoklatan\", \"Siap dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1425, 2, '356. Rendang Ayam Kacang Merah', 'Resep praktis 356. Rendang Ayam Kacang Merah yang bisa dicoba di rumah.', '[\"1/2 kg ayam, potong sesuai selera\", \"250 grm kacang merah basah\", \"500 ml santan kental\", \"500-750 ml air (untuk merebus kacang)\", \"Bumbu-bumbu:\", \"8 siung bawang merah\", \"5 siung bawang putih\", \"3 bh cabe merah, potong-potong\", \"10 bh cabe rawit (sesuaikan selera aja ya)\", \"1 ruas lengkuas, iris tipis\", \"1 ruas jahe, iris tipis\", \"1 ruas kunyit, iris tipis\", \"5 bh kemiri utuh\", \"1 sdt ketumbar\", \"1/2 sdt merica\", \"1/4 sdt jinten\", \"4 lbr daun jeruk\", \"3 lbr daun salam\", \"3 tangkai serei, memarkan\", \"1.5 sdt garam halus\", \"1.5 sdt gula pasir\", \"3 sdm minyak goreng untuk menumis bumbu\"]', '[\"Siapkan dan timbang bahan sesuai resep.\", \"Haluskan semua bumbu kecuali daun jeruk, daun salam, serei, dan gula pasir.\", \"Tumis semua bumbu kecuali gula hingga harum, masukkan kacang merah dan tambahkan air. Rebus hingga kacang empuk.\", \"Masukkan ayam dan gula pasir. Masak hingga ayam empuk.\", \"Masukkan santan, masak lagi hingga santan sedikit menyusut (saya suka agak kering).\", \"Tes rasa, kalau sudah cukup, matikan apinya dan angkat.\", \"Ini hasilnya, Rendang Ayam Kacang Merah siap disajikan😊😋\", \"Selamat mencoba!\", \"Happy cooking😋😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1426, 4, 'Japanese Chicken Katsu Curry', 'Resep Japanese Chicken Katsu Curry yang lezat dan mudah dibuat di rumah.', '[\"1/2 bagian dada ayam tanpa tulang (fillet menjadi 3 bagian)\", \"Bumbu Marinasi :\", \"150 ml Susu Cair (dancow dicairkan)\", \"1 siung Bawang Putih (cincang halus)\", \"1/2 sdt Garam\", \"1/2 sdt Lada Bubuk\", \"1/2 sdt Penyedap Rasa (optional)\", \"1/2 sdt Oregano (boleh skip)\", \"Bahan Pelapis :\", \"6 sdm Tepung Terigu\", \"1 butir Telur (kocok lepas)\", \"6 sdm Tepung Roti / Panir\", \"Minyak untuk menggoreng\", \"Bahan Saus Curry :\", \"1 buah Wortel (potong dadu)\", \"1 buah Kentang (potong dadu)\", \"2 siung Bawang Putih (cincang halus)\", \"1 buah Bawang Bombay (iris tipis)\", \"1/2 bungkus Bumbu Instan Curry (Indofood)\", \"400 ml air\", \"Secukupnya lada bubuk\", \"Secukupnya garam\", \"Secukupnya penyedap rasa (optional)\", \"1 sdm Tepung Maizena (larutkan dalam air)\"]', '[\"Siapkan bahan.\", \"Bumbu Marinasi : campur semua bahan lalu rendam ayam menggunakan cairan tersebut. Diamkan kurang lebih 30 menit dalam kulkas\", \"Saus Curry :\", \"Tumis bawang putih dan bawang bombay hingga matang dan harum. Masukkan bumbu curry, lalu tambahkan kentang dan wortel yg sudah dipotong. Aduk rata. Masukkan air, masak hingga sayuran matang\", \"Bumbui dengan lada garam. Cek rasanya. Setelah itu kentalkan dengan tepung maizena yg telah dicairkan tadi. Sisihkan\", \"Penyesalan ayam : balut dengan tepung terigu lalu masukkan kedalam telur yg telah dikocok dan baluri dengan tepung roti/panir\", \"Tepung terigu ➡️ telur ➡️ tepung roti / panir\", \"Goreng ayam dalam minyak panas hingga matang. (gunakan api kecil saja supaya ayam matang merata)\", \"Sajikan bersama nasi dan saus curry tadi.\", \"Silakan mencoba ❤️\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1427, 2, 'Lodeh kacang & ceker ayam', 'Resep Lodeh kacang & ceker ayam ala rumahan yang dijamin menggugah selera.', '[\"10 biji ceker ayam\", \"1 ikat kacang panjang\", \"1 kotak tempe (sy skip)\", \"1 santan kara yg kecil\", \"👉Bumb halus :\", \"5 cabai rawit\", \"1 cabai merah besar\", \"3 bawang merah\", \"2 bawang putih\", \"2 kemiri\", \"1 ruas Kencur\", \"1 ruas Kunyit\", \"1 sdt Tumbar bubuk\", \"1 sdt Lada bubuk\", \"Garam dan gula pasir\", \"👉tambahan\", \"2 daun jeruk\", \"1 daun salam\", \"1 ruas laos\"]', '[\"Potong2 kacang dan cuci bersih sisihkan. bersihkan ceker dan rebus sampai empuk\", \"Sambil menunggu rebusam ceker. Tumis bumbu halus beserta daun salam daun jeruk dan laos sampai harum dan matang.\", \"Masukkan bumbu ke rebusan ceker. Tambah garam dan gula pasir. Lalu masukkan kacang terakhir masukkan santan.\", \"Tunggu sampai kacang matang dan matikan kompor\", \"Siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1428, 3, 'Tumis Jagung Wortel Ayam Kecap Panggang', 'Hidangan ayam lezat: Tumis Jagung Wortel Ayam Kecap Panggang untuk keluarga tercinta.', '[\"Bahan Ayam Kecap Panggang:\", \"1 potong ayam bagian dada (bersihkan,beri sedikit perasan lemon)\", \"3 siung bawang putih (ulek halus)\", \"12-15 butir lada hitam (ulek halus)\", \"1 sdt kecap inggris\", \"1 sdm kecap manis\", \"1 sdm olive oil\", \"1/2 sdm extra virgin olive oil/EVOO\", \"Bahan Tumis Jagung Wortel:\", \"1/2 wortel (bersihkan lalu potong kecil)\", \"5 baris jagung (sisir dan bersihkan)\", \"2 siung bawang putih (iris tipis)\", \"2 siung bawang merah (iris tipis)\", \"5 buah cabe rawit (iris serong)\", \"Secukupnya garam\", \"secukupnya Lada bubuk putih\"]', '[\"Campurkan semua bahan ayam panggang. Lalu marinasi di kulkas selama 20-30 menit\", \"Panaskan oven, oleskan loyang dengan olive oil. Panggan ayam selama 25-30 menit pada temperatur 180 derajat Celcius, gunakan api atas bawah\", \"Untuk tumisan jagung wortel. Panaskan 2-3 olive oil. Lalu tumis bawang putih, bawang merah dan cabe rawit sampai harum dan agak kecoklatan\", \"Masukkan jagung dan wortel, aduk rata. Lalu beri air matang 1 gelas kecil, lalu diamkan sampai air menyusut\", \"Lalu beri garam dan lada putih. Aduk rata dan koreksi rasa. Lalu sajikaan bersama ayam panggang🤤\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1429, 3, 'Ayam Goreng Mentega', 'Resep praktis Ayam Goreng Mentega yang bisa dicoba di rumah.', '[\"1 kg ayam\", \"100 gr mentega\", \"1/4 bawang bombay\", \"4 siung bawang putih\", \"5 sdm Saus tomat\", \"1 sdm kecap\", \"1 sdm gula\", \"1/2 sdt garam dan lada\", \"2 sdm kecap inggris\", \"6 biji cabe hijau\"]', '[\"Cuci bersih ayam. Lalu rebus dengan 1 sdt garam setelah matang tiriskan\", \"Marinasi semua Bahan kecuali bawang Bombay dan bawang putih\", \"Goreng ayam di minyak panas hingga habis dan tiriskan\", \"Tumis mentega dengan bawang Bombay dan bawang putih\", \"Masukan semua Bahan. Koreksi rasa.. Setelah itu Masukan ayam goreng masak sebentar dan jangan lupa cabe hijau nyaa\", \"Koreksi rasa dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1430, 3, 'Sayap Ayam Goreng Pedas #ketopad', 'Nikmati kelezatan Sayap Ayam Goreng Pedas #ketopad dengan resep sederhana ini.', '[\"500 gr Sayap ayam,potong 2 bagian\", \"Garam\", \"1 bh jeruk lemon\", \"Bumbu iris halus :\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"15 bh cabe rawit merah\", \"10 buah cabe rawit hijau\", \"3 bh cabe merah\", \"3 bh cabe gendot\", \"1 batang serai,ambil bag putihnya\"]', '[\"Lumuri sayap ayam dengan garam dan jeruk lemon(sebagian saja)\", \"Lalu goreng sampai matang,sisihkan\", \"Tumis bawang2an dan cabe2an serta serai dengan minyak sisa goreng ayam.. sampai agak layu..\", \"Tambahkan garam dan penyedap di tumisannya.. aduk rata lalu angkat\", \"Tata sayap ayam di piring lalu siram dengan bumbu tumisannya.. lalu tambahkan perasan jeruk lemon\", \"Sayap ayam goreng pedas siap di santap\", \"Selamat mencoba🙏🙏\", \"📝untuk cabe2an bisa di sesuaikan ya banyaknya\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1431, 4, 'Seblak Tulang Ayam ala Jeletet Murni', 'Resep praktis Seblak Tulang Ayam ala Jeletet Murni yang bisa dicoba di rumah.', '[\"1 genggam kerupuk (rebus, tiriskan, dan rendam dalam air biasa)\", \"1 buah paha ayam (rebus dgn bawang putih bubuk, jahe bubuk, merica bubuk, gula dan garam, tiriskan)\", \"1 butir telur\", \"1/2 batang daun bawang (iris)\", \"3 siung bawang putih\", \"1 siung bawang merah\", \"1 butir kemiri\", \"3 sdm cabe bubuk\", \"1 sdt kencur bubuk\", \"Segcukupnya Garam\", \"Secukupnya Gula\", \"Secukupnya Merica bubuk\", \"Sedikit air\"]', '[\"Haluskan bawang merah, bawang putih, kemiri, garam, gula, merica bubuk, cabe bubuk, dan kencur bubuk.\", \"Tumis bumbu halus dan daun bawang hingga harum. Masukkan ayam, lalu aduk.\", \"Beri air secukupnya dan tunggu hingga mendidih.\", \"Masukkan telur dan kerupuk. Tunggu hingga matang dan sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1432, 3, 'Ayam Bakar Taliwang', 'Resep Ayam Bakar Taliwang yang lezat dan mudah dibuat di rumah.', '[\"1 kg ayam\", \"2 batang sereh, geprek\", \"2 lembar daun jeruk\", \"1/2 keping gula merah\", \"Santan (65ml kara+200ml)\", \"Bumbu halus :\", \"10 siung bawang merah\", \"4 siung bawang putih\", \"4 butir kemiri\", \"1 sachet terasi ABC\", \"2 buah cabe merah\", \"7 buah cabe rawit (sesuai selera)\", \"2 cm kencur\"]', '[\"Tumis bumbu halus bersama serai dan daun jeruk hingga matang, tambahkan gula merah (disisir agar cepat larut), dan garam. Aduk.\", \"Masukan santan, aduk rata. Masukan ayam. Lalu ukep ayam hingga bumbu meresap dan mengental serta ayam sudah empuk.\", \"Jika dirasa sudah empuk, angkat ayam. Lalu tuang sisa bumbu di mangkok untuk olesan pas dipanggang.\", \"Panggang ayam dengan panggangan/teflon dan semacamnya. Olesi ayam dengan sisa bumbu ukep. Masak dengam dibolak balik hingga matang.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1433, 4, 'Chiken Mushroom Teriyaki', 'Hidangan ayam lezat: Chiken Mushroom Teriyaki untuk keluarga tercinta.', '[\"500 gram ayam tanpa tulang potong dadu\", \"(Pake Chiken wings di potong 2 atw ayam potong juga boleh yaa\", \"1 sdm Saos Teriyaki\", \"1/2 Sdm saos inggris\", \"1 sdm kecap manis\", \"1 butir bawang bombay\", \"secukupnya Bawang putih\", \"150 gr Jamur Merang\", \"150 gr Jamur Kuping\", \"Secukupnya Garam, Lada, Gula\", \"Optional : Daun Bawang, Seledry, Cabe2 an, sayur2 an yaa Mom\'s\"]', '[\"Tumis bawang Bombay, Bawang putih hingga harum\", \"Setelah harum masukkan ayam aduk hingga berubah warna...\", \"Masukkan smua jenis saos, aduk rata,,, Tambahkan air sedikit, utk membantu pematangan ayam,\", \"Setelah sdikit sa\'at airnya dan mendidih, masukkan smua jenis jamur, aduk rata, bumbui garam, gula, lada dan kecap manis\", \"Siap di hidangkan dgn Nasi Panas, dan Bubur buat akyuuuu....\", \"Enjoyed The Food yaa Mom\'s... #HappyCooking 😘😘\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1434, 4, 'Ayam goreng tepung / kentucky', 'Ayam goreng tepung / kentucky dengan bumbu meresap sempurna.', '[\"1 kg ayam bagian paha\", \"1/2 tepung terigu\", \"1 butir telur ayam\", \"1 sdm merica bubuk\", \"Secukupnya bawang putih\", \"Secukupnya masako ayam\", \"Secukupnya air\", \"Minyak untuk menggoreng\"]', '[\"Siapkan ayam, dan lumuri semua ayam dgn merica bubuk, masako dan bawang puting yg sudah dihaluskan, diamkan selama 30 menit, lebih dri 30 menit jga ga apa2 yaa..\", \"Siapkan tepung kering, tepung cair, dan telur yg sudah dikocok dlm 3 wadah yg berbedah. Semua bahan sudah dicampur dgn merica bubuk secukupnya dan masko secukupnya\", \"Siapkan minyak untuk menggoreng, ambil ayam yg sudah di diamkan bersama bumbu tdi. Celupkan ayam kedlm wadah telur, kemudian celupkan kewadah tepung kering, celupkan lgi kewadah tepung cair dan terakhir tepung kering lagi dan agak diremas dgn pelan kemudian masukan keminyak yg sudah panas\", \"Goreng dgn api sedang, setelah warnanya kuning keemasan angkat dan tiriskan\", \"Ayam goreng siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1435, 3, 'Ayam bakar bumbu kari', 'Ayam bakar bumbu kari dengan bumbu meresap sempurna.', '[\"700 gr ayam, potong2 sesuai selera, cuci bersih\", \"1 batang sereh, geprek bagian putihnya aja\", \"2 ruas jari lengkuas, geprek\", \"2 lembar daun salam\", \"3 lembar daun jeruk, sobek2\", \"Secukupnya daun kari\", \"65 ml santan kental instant (sy pake kara segitiga)\", \"200 ml air\", \"Secukupnya minyak goreng\", \"Secukupnya kaldu jamur, garam, lada dan gula\", \"▪ Bumbu halus:\", \"6 butir bawang merah\", \"3 siung bawang putih\", \"3 butir kemiri\", \"1/2 sdt ketumbar halus\", \"1/2 sdt kunyit bubuk\", \"3 sdt bubuk kari (sy pake merk Koepoe Koepoe)\"]', '[\"Rajang kasar bawang merah, bawang putih dan kemiri.\", \"Blender hingga halus semua bumbu halus.\", \"Panaskan minyak secukupnya, tumis bumbu halus hingga mengeluarkan minyak, masukkan daun salam, sereh, lengkuas, daun jeruk dan daun kari. Tumis hingga daun2 agak layu, lalu masukkan ayam, aduk rata.\", \"Tuang air, aduk rata. Lalu tuang santan, aduk rata lagi.\", \"Masukkan kaldu jamur, garam, lada dan gula. Tes rasa. Sesekali sambil diaduk.\", \"Masak hingga air menyusut seperti ini. Ayam siap utk dibakar.\", \"Bakar ayam di atas teflon. Gak perlu ditutup ya teflonnya moms..\", \"Balik ayam jika satu sisinya sudah kecoklatan.\", \"Ayam bakar bumbu kari siap disantap...\", \"Wangi karinya.... hmmmm..... bikin nambah nasi trs 😆😆\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1436, 2, 'Macaroni Schotel dgn Ayam', 'Macaroni Schotel dgn Ayam - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"Bahan Utama :\", \"200 gr makaroni elbow, fabus hingga al dente\", \"250 ml susu cair sy merk ultra\", \"3 butir telur kecil\", \"150-200 gr dada ayam, rebus, cincang\", \"1 buah bwg bombay uk kecil, cincang kasar\", \"3 buah bwg putih, cincang halus\", \"50 gram keju cheddar, parut\", \"1 sachet royco rasa ayam\", \"Secukupx garam, lada bubuk, pala bubuk dan oregano\", \"Secukupx myk goreng utk menumis\", \"Bahan White Sauce :\", \"250 ml susu cair\", \"2 sdm terigu\", \"50 gr keju cheddar, parut\", \"2 sdm margarin\"]', '[\"Tumis bwg bombay dan bwg putih hingga harum. Masukkan ayam cincang tumis hingga ayam cukup matang. D wadah lain kocok 3 butir telur lalu tambahkan susu cair. Sy tambahkan bumbu2 dan keju parut dlm larutan susu dan telur. Lalu masukkan k dlm tumisan ayam td disusul dgn makaroni rebus. Koreksi rasa.\", \"Selanjutnya buat white sauce dgn cara panaskan 2 sdm margarin. Krn ud bbrp kali nyoba teknik aduk cpt d tambah 2 sdm tepung hasilx gumpal jd saya akalin dengan melarutkan terigu, susu dan keju parut dlm wadah lain kemudian d masukkan dlm mentega yg sudah d panaskan tadi. Masak dgn api kecil hingga saus mengental.\", \"Penyelesaian tata makaroni dlm alfoil lalu tutupi dgn white sauce. Jika ingin rasa lebih creamy white sauce bisa d banyakin dgn membuat 2x resep.\", \"Taburi dgn oregano jika suka boleh d tambahi keju parut lagi. Lalu panggang slm krg lebih 40-50 menit tgt oven masing2 smp schotel agak set dan atasx kekuningan.\", \"Diamkan schotel 10-20 menit agar set. Max schotel dgn ayam siap d makan. Saya tambahkan mayones dan saus pedas d atasnya.\", \"Cincangan bawang bombay dan bwg putih\", \"Campuran telur, susu dan keju serta tambahan bumbu\", \"Cincangan ayam rebus cincang\", \"Parutan keju\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1437, 4, 'Ayam Sisit khas Bali', 'Buat Ayam Sisit khas Bali yang nikmat dengan langkah-langkah mudah ini.', '[\"300 gr dada ayam fillet\", \"3 siung bawang putih\", \"5 buah cabai keriting (sesuai selera)\", \"5 buah daun jeruk\", \"seujung jari Terasi bakar\", \"sesuai selera gula,garam, penyedap\"]', '[\"Rebus dada ayam sampai matang, sisihkan air sisa rebusannnya.\", \"Ulek / blender semua bumbu : bawang putih,cabe,terasi.\", \"Suwir dada ayam dengan cara di geprek lalu di suwir agar lebih mudah.\", \"Campur suwiran ayam dengan bumbu yg sudah diulek, aduk2 sampai rata.\", \"Panaskan minyak lalu tumis semua bumbu dan ayam yg sudah tercampur rata, masukan air kaldu rebusan sedikit, lalu masukan daun jeruk, garam,gula, penyedap. Koreksi rasa lalu tunggu sampai airnya sap/habis dan siap dihidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1438, 3, 'Ayam bacem uenakkk', 'Buat Ayam bacem uenakkk yang nikmat dengan langkah-langkah mudah ini.', '[\"1 ekor ayam\", \"Bumbu halusnya :\", \"1 1/2 sdm ketumbar sangrai\", \"3/4 sdt jinten\", \"5 butir bawang merah\", \"3 butir bawang putih\", \"Bumbu lainnya :\", \"6 lembar daun salam\", \"2 buah lengkuas uk. besar, geprek\", \"70 gr gula merah\", \"4 sdm kecap manis\", \"1 sdm gula\", \"1 sdm garam/sesuai selera\", \"1 liter air/air kelapa\", \"1 sdm asam jawa, eceran dgn 100 ml air dan saring\"]', '[\"Cuci ayam hingga bersih, potong sesuai selera, tiriskan, haluskan semua bahan bumbu halus.\", \"Campur air, bumbu halus, dan semua bahan lainnya kecuali ayam, masak hingga mendidih, masukan ayam, masak hingga matang bumbu meresap/kuah tinggal sedikit/mengering sampai tahap ini ayam udah enak banget loh...\", \"Goreng ayam dalam minyak banyak dan panas, sebentar aja, soale cepet gosong karena kandungan gula lumayan banyak, siap disajikan dgn nasi putih dan sambal terasi, yummy.\", \"Ini foto step by stepnya ya.\", \"Siap disimpan dikulkas sebelum masuk pengorengan,😋😋😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1439, 3, 'Soto ayam lamongan super simpel', 'Soto ayam lamongan super simpel dengan bumbu meresap sempurna.', '[\"1 ekor ayam kampung (bisa menggunakan ayam potong)\", \"2 tangkai seledri, iris tipis\", \"2 batang daun bawang iris tipis\", \"1/4 buah kol / gubis, iris tipis\", \"1 ons kecambah (optional)\", \"1 bungkus ukuran kecil mie soun, rendam dengan air selama 10 menit, sisihkan\", \"4 butir telur, rebus dan bagi 2\", \"3 lembar daun jeruk\", \"2 batang sereh, geprek\", \"2 batang daun bawang, iris tipis\", \"Bumbu halus :\", \"2 ruas kunyit bakar\", \"1/2 sdt ketumbar\", \"3 buah kemiri\", \"8 siung bawang merah\", \"4 siung bawang putih\", \"Bahan perkedel:\", \"3 buah kentang, goreng\", \"Secukupnya bawang merah goreng\", \"1 butir telur, kocok\", \"Bahan koya:\", \"6 buah kerupuk udang, goreng (saya pakai merk kelapa gading menurut saya pribadi, merk ini kerupuk yang paling enak hihi)\", \"3 siung bawang putih goreng\", \"Sambal :\", \"10 buah cabe rawit\", \"Secukupnya air\"]', '[\"Rebus ayam dengan air yang memenuhi ayam hingga matang, angkat dan sisihkan kaldunya (jangan di buang ya)\", \"Suwir ayam, sisihkan\", \"Tumis bumbu halus, sereh dan daun jeruk hingga benar benar asat\", \"Panaskan kembali kaldu ayam, tambahkan 2-3 gelas, masukkan tumisan bumbu, 1/2 bagian daun bawang yang sudah diiris tipis, 1/2 bagian daun seledri yang sudah diiris tipis, tambahkan garam dan kaldu bubuk (apabila diinginkan), aduk hingga rata dan mendidih, tes rasa\", \"Perkedel: ulek kentang dengan bawang, bentuk beberapa bulatan, kemudian celupkan ke telur yang sudah di kocok, goreng\", \"Koya : hancurkan semua kerupuk dan bawang sampai halus dan rata\", \"Sambal : 10 cabe rawit direbus kemudian blender dengan sedikit air\", \"Sajikan, selamat makaaan 😍😍\", \"Ittadakimassu 😍🙏🏼\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1440, 3, 'Ayam bakar simple', 'Buat Ayam bakar simple yang nikmat dengan langkah-langkah mudah ini.', '[\"500 gr ayam potong\", \"Bumbu halus:\", \"8 siung bawmer\", \"4 siung bawput\", \"1 ruas jahe\", \"3 buah tomat\", \"Bumbu cemplung:\", \"Daun salam\", \"Sere\", \"Pelengkap kecap manis,penyedaprasa,gula,garam\"]', '[\"Cuci bersih ayam\", \"Masukkan bumbu halus dan aym..serta pelengkap bumbu..tambah air secukupnya..Ungkep ayam sampe air meresap dan ayam matang\", \"Tiriskan,lalu panggang di teflon\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1441, 2, 'Ayam Kecap Sederhana', 'Hidangan ayam lezat: Ayam Kecap Sederhana untuk keluarga tercinta.', '[\"8 ptg ayam chopstick (paha)\", \"1 buah kentang ukuran sedang (potong kotak)\", \"Bawang merah, bawang putih, dan bawang bombay (dicincang)\", \"Cabe merah (buang biji)\", \"Daun salam dan daun jeruk (daun jeruknya di cincang)\", \"Sereh dan jahe (digeprek)\", \"Tomat (kalo gak pake, gpp)\", \"Garam, ladaku, dan kaldu jamur\", \"Kecap manis\", \"Saus tiram\", \"Olive oil / mentega\"]', '[\"Cuci bersih ayam, lalu taburi dengan garam dan ladaku. Ditekan2 agar meresap dan merata. Biarkan selama kurleb 15menit.\", \"Goreng ayam sebentar saja, lalu tiriskan.\", \"Panaskan olive oil (bisa pakai mentega), tumis bawang merah putih bombay, cabe, daun salam, daun jeruk, sereh, jahe, dan tomat, hingga harum.\", \"Masukkan ayam yg tadi sudah digoreng. Diamkan sebentar lalu balik ayamnya. Agar kedua sisi terkena bumbunya. Dan masukkan kentang.\", \"Lalu beri garam, ladaku, kaldu jamur, saus tiram, dan kecap manis (jika krg gurih bisa tambah kecap manisnya atau gula). Dan tambahkan air secukupnya. Aduk rata.\", \"Setelah itu tunggu hingga bumbu meresap dan air menyusut. Di sela sela tahap ini bisa koreksi rasa.\", \"Ayam kecap siap dihidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1442, 3, 'Chicken Karaage', 'Sajian Chicken Karaage yang praktis dan lezat untuk dinikmati bersama.', '[\"1/2 kg paha ayam fillet\", \"Bahan Bumbu Marinasi:\", \"2 siung bawang putih,cincang halus\", \"2 sdm gula aren/ gula palem\", \"1 butir telur\", \"1/2 sdt lada hitam\", \"1/2 sdt merica\", \"2 sdm kecap asin jepang (kalo ga ada,kecap asin biasa juga bisa)\", \"garam sedikit saja\", \"sesuai selera penyedap\", \"sedikit jahe cincang (kalau suka)\", \"Bahan Adonan Kering :\", \"10 sdm maizena\", \"5 sdm sagu / tepung tapioka\", \"1/2 sdt bubuk bwg putih\"]', '[\"Potong ayam bentuk persegi kurang lebih 3-4 cm, campur dengan semua bumbu marinasi dan remas-remas kemudian diamkan di kulkas selama 1-3 jam.\", \"Di wadah lain buat adonan kering, campur maizena, sagu, dan bubuk bawang putih.Aduk-aduk sampai rata.\", \"Keluarkan Ayam sepotong demi sepotong dan balurkan ke adonan kering sampai tertutup rata sambil ditekan-tekan. Goreng dengan api kecil sampai kecoklatan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1443, 3, 'Garang asem ati ampela ceker ayam', 'Cara membuat Garang asem ati ampela ceker ayam yang enak dan praktis untuk keluarga.', '[\"10 pasang ati ampela ayam\", \"250 gr ceker ayam\", \"6 buah blimbing wuluh,potong\\\"\", \"2 lembar daun salam,sobek\", \"1 batang sereh (agak besar),geprek\", \"1 ruas jahe,geprek\", \"1 ruas langkuas,geprek\", \"Bumbu iris :\", \"8 buah bawang merah\", \"5 buah bawang putih\", \"10 buah cabe rawit merah(kalo ga suka pedas bisa dikurangi)\", \"Gula,garam,penyedap\", \"secukupnya Santan sedang\"]', '[\"Cuci bersih ati ampela ceker,rebus sebentar beri sdkit garam...tiriskan,buang air rebusannya,kalo mau lebih empuk cekernya boleh di presto ya mom.😊\", \"Cuci bersih bumbu\\\",iris\\\" sisihkan\", \"Siapkan wadah anti panas..tata bumbu iris,potongan blimbing wuluh,bumbu geprek,beri gula garam penyedap..masukkan rebusan ati ampela ceker,tuang santan...banyaknya santan sesuai selera ya mom..kalo mau banyak kuahnya ya tinggal di banyakin santannya\", \"Kukus dlm dandang selama kurleb 45menit(tdi lupa di timer)😁\", \"Setelah matang,angkat dan sajikan..wangi rempah dan gurihnya santan bikin ga tahan pengen cepet\\\" nyendok nasi..🤣🤣\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1444, 4, 'Semur hati ayam dan kentang ala bunda raffa (no msg)', 'Sajian Semur hati ayam dan kentang ala bunda raffa (no msg) yang praktis dan lezat untuk dinikmati bersama.', '[\"5 pasang ati ampela\", \"1/4 kg sayap ayam (3 potong sayap)\", \"2 buah kentang ukuran besar\", \"Bumbu iris :\", \"4 siung bawang putih\", \"2 buah bawang bombay ukurang kecil\", \"2 buah cabe merah besar\", \"1 buah tomat\", \"10 buah cabe rawit\", \"Tambahan :\", \"4 sdm kecap manis\", \"2 sdm saos tiram\", \"Secukupnya gula dan garam\", \"Secukupnya air (kurleb 500 - 600 ml\"]', '[\"Rebus ati ampela dan ayam sampai matang dan empuk. Kemudian potong2 kotak ati ampela sesuai selera. Sisihkan\", \"Kupas kentang, kemudian potong sesuai selera dan goreng sampai matang. Sisihkan\", \"Tumis semua bumbu iris sampai harum dan bawang bombay mulai layu.\", \"Masukkan ati ampela, ayam dan kentang kemudian aduk sampai bumbu rata. Diamkan sebentar agar bumbu meresap.\", \"Tambahkan air (airnya bisa dikira2 saja ya sesuka hati)\", \"Tambahkan kecap, saos tiram, gula dan garam\", \"Tes rasa. Kemudian biarkan sampai air menyusut (air tinggal sedikit saja)\", \"Matikan api dan sajikan dg nasi hangat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1445, 4, 'Rolade Ayam Tahu', 'Rolade Ayam Tahu dengan bumbu meresap sempurna.', '[\"1/2 kg daging ayam fillet\", \"2 buah tahu putih ukuran sedang\", \"3 siung bawang putih\", \"4 siung bawang merah\", \"1 siung bawang bombai\", \"5 butir telur ayam\", \"100 gram tepung terigu\", \"Secukupnya garam\", \"Secukupnya gula pasir\", \"Secukupnya lada bubuk\", \"5 lembar plastik bening ukuran sedang\"]', '[\"Rajang kasar bawang putih, bawang merah dan bawang bombai. Tumis dengan sedikit minyak goreng sampai harum.\", \"Setelah dibersihkan, haluskan daging ayam fillet, tahu putih dan tumisan bawang dengan blender.\", \"Setelah halus, masukkan 1 butir telur dan blend kembali hingga tercampur rata.\", \"Pindahkan adonan ke wadah, masukkan tepung terigu, aduk hingga rata. Masukkan secukupnya garam, gula pasir, dan lada bubuk. Sesuaikan rasa.\", \"Buat beberapa telur dadar tipis dengan menambahkan sedikit garam agar tidak hambar.\", \"Bentangkan plastik bening, kemudian letakkan 1 telur dadar di atasnya, lalu beri adonan rolade. Kemudian gulung dan bungkus rapat plastik bening.\", \"Kukus rolade hingga matang. Setelah matang, tiriskan dan potong menjadi beberapa bagian sesuai selera. Rolade siap disajikan, dapat juga digoreng lagi setelah di potong-potong.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1446, 4, 'Opor ayam pedas', 'Resep praktis Opor ayam pedas yang bisa dicoba di rumah.', '[\"6 potong daging ayam\", \"7 bawang merah\", \"3 bawang putih\", \"1 kunyit\", \"3 kemiri\", \"1 sereh (geprek)\", \"1 daun jeruk\", \"Secukupnya jahe (geprek) ketumbar,lada,cabe giling,garam,gula\", \"Santan kental dan cair\"]', '[\"Giling atau blender bawang merah,kunyit,bawang putih,kemiri,lada,ketumbar. Kemudian di tumis sampe harum\", \"Masukan geprekan (jahe,sereh)daun jeruk,daun salam dan gilingan cabe merah\", \"Setelah bumbu masak masukan potongan daging ayam tumis sebentar kemudian masukan santan cair setelah daging masak masukan santan kental aduk hingga mendidih\", \"Taburkan bawang merah diatas masakan dan siap untuk disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1447, 3, 'Fire Chicken Wings', 'Resep praktis Fire Chicken Wings yang bisa dicoba di rumah.', '[\"Bahan Ayam Goreng Tepung:\", \"1 Kg Sayap Ayam\", \"80 Gram Tepung Ayam Goreng Kentucky (Saya Merk: Sasa)\", \"1 Butir Telur\", \"Bahan Saus Fire:\", \"200 Gram Cabai Merah\", \"50 Gram Cabai Rawit\", \"3 Siung Bawang Putih (Secukupnya)\", \"8 Siung Bawang Merah (Secukupnya)\", \"2 Buah Tomat (Ukuran Sedang)\", \"50 Gram Saos Cabai\", \"2 Lembar Daun Jeruk\", \"Secukupnya Gula Merah\", \"2 Sdm Gula Putih\", \"1 Sdm Garam\"]', '[\"Rebus sayap ayam yang sudah dibersih kan. Rebus sampai matang (Kira kira 10-15 menit)\", \"Blander sampai halus cabai merah, cabai rawit, bawang merah, bawang putih dan tomat.\", \"Setelah sayap ayam matang, tiriskan. Celupkan kedalam telur yang sudah dikocok lalu celupkan kedalam tepung ayam goreng. Lalu goreng sampai berwarna golden brown.\", \"Untuk sausnya tumis bahan yang sudah diblander halus. Setelah setengah matang, masukkan daun jeruk, saus cabai, gula merah, gula putih dan garam.\", \"Tunggu sampai matang. Setelah matang masukkan ayam goreng yang sudah matang tadi. Aduk sampai rata. Dan siap disajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1448, 4, 'Rendang Ayam', 'Buat Rendang Ayam yang nikmat dengan langkah-langkah mudah ini.', '[\"1 ekor ayam (potong2)\", \"3 bh kentang (kupas dan potong 2)\", \"bumbu ulek :\", \"8 bh bawang merah\", \"4 bh bawang putih\", \"2 bh cabe merah keriting (sesuai selera)\", \"1 bh kunyit\", \"2 cm jahe\", \"2 bh kemiri\", \"1 sdt ketumbar\", \"1/2 sdt lada\", \"1/4 sdt jinten\", \"2 bh daun salam\", \"2 bh daun jeruk\", \"1 bh serai (geprek)\", \"100 ml santan kental\", \"secukupnya gula dan garam\"]', '[\"Tumis bumbu dengan minyak secukupnya sampai harum, masukkan ayam, aduk2 sampai berubah warna. masukkan santen dan air secukupnya, masak dengan api kecil dan tutup\", \"Sekitar 15 menit kemudian masukkan kentang, masukkan garam dan gula (kira2 saja), masak sampai ayam dan kentang lunak, koreksi rasa. angkat, hidangkan dengan taburan bawang goreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1449, 4, 'Yamie Ayam', 'Sajian Yamie Ayam yang praktis dan lezat untuk dinikmati bersama.', '[\"1 ekor ayam kampung\", \"5 siung bawang putih, cacah halus\", \"3 sdt kecap ikan\", \"1 sdt kaldu ayam atau jamur bubuk\", \"secukupnya Merica\", \"1 sdt gula pasir\", \"Untuk kuah:\", \"3 siung bawang putih, cacah halus\", \"10 butir bakso\", \"1 batang daun bawang, iris tipis\", \"Sambal:\", \"12 buah cabai rawit merah\", \"3 siung bawang putih\", \"secukupnya Garam\", \"1/2 sdt gula pasir\", \"1/2 sdt kaldu ayam atau jamur bubuk\", \"1/2 sdt cuka\", \"5-6 sdm air panas\", \"Bumbu Mie:\", \"4-5 sdm minyak ayam (minyak dari menggoreng kulit ayam)\", \"1 sdm kecap ikan\", \"2 sdt minyak wijen\", \"secukupnya Merica\", \"1 sdt kaldu ayam atau jamur bubuk\", \"Bahan pelengkap:\", \"Mie kering atau basah\", \"Rebusan sawi hijau\", \"Irisan daun bawang\", \"Bawang goreng\"]', '[\"Rebus ayam hingga lunak. Sisihkan dagingnya. Suwir dan cacah.\", \"- Didihkan kuah. Tambahkan bakso dan bawang putih. Bumbuhi dengan kaldu bubuk, garam dan merica secukupnya. Masak hingga bawang matang dan harum. Koreksi rasa. Masukkan daun bawang dan matikan api.\", \"- Untuk topping ayam: tumis bawang putih hingga harum. Tambahkan kecap ikan. Masukkan ayam dan aduk rata. Bumbuhi dengan garam, gula, kaldu bubuk dan merica secukupnya.\", \"Bila dirasa kurang empuk dan meresap, tambahkan air secukupnya dan masak hingga kuah habis. Koreksi rasa. Sisihkan.\", \"- Untuk sambal: rebus cabai dan bawang putih. Haluskan dan campur rata dengan bahan lainnya. Tuang dalam mangkuk.\", \"- Untuk bumbu mie: campur rata semua bahan.\", \"- Untuk penyajian: rebus seporsi mie. Tiriskan dan beri 1 sdm bumbu mie: aduk rata. Beri topping ayam, sawi, daun bawang dan bawang goreng. Sajikan dengan kuah bakso dan sambal.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1450, 2, 'Sup Ayam Telur Puyuh NCC Untuk si Kecil so simple👍', 'Cara membuat Sup Ayam Telur Puyuh NCC Untuk si Kecil so simple👍 yang enak dan praktis untuk keluarga.', '[\"500 gr ayam, potong kecil\", \"2 buah wortel, potong2\", \"1 buah kentang, potong dadu\", \"2 buah daun bawang, iris halus\", \"2 buah daun seledri, iris halus\", \"secukupnya Kol\", \"10 butir telur puyuh, rebus kupas\", \"1500 ml air\", \"Bumbu halus :\", \"1/2 sdt lada bubuk\", \"4 siung bawang putih\", \"1/4 sdt pala\", \"secukupnya Garam gula\", \"Topping :\", \"secukupnya Bawang goreng\"]', '[\"Masak air dalam panci hingga mendidih masukkan ayam, dan biarkan hingga matang. Kemudian masukkan wortel dan kentang masak sebentar\", \"Masukkan bumbu halus biarkan kuah mendidih sebentar. Masukkan kol, daun bawang, daun seledri dan telur puyuh aduk rata...beri garam dan gula koreksi rasa.\", \"Matikan api, siap disajikan..enakkkkkk....si kecil pasti suka moms 😘\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1451, 4, 'Ayam kecap sederhana', 'Cara membuat Ayam kecap sederhana yang enak dan praktis untuk keluarga.', '[\"1 ekor ayam (potong 12)\", \"10 bh cabe rawit (potong 2 memanjang)\", \"1 bh jeruk nipis (di peras)\", \"1 saset lada bubuk\", \"Secukupnya garam\", \"secukupnya Gula\", \"secukupnya Penyedap\", \"Secukupnya air putih\", \"Secukupnya kecap manis\", \"Bumbu Halus:\", \"6 siung bawang merah\", \"4 siung bawang putih\", \"Secukupnya lada\"]', '[\"Cuci ayam hingga bersih,campurkan ayam dengan jeruk nipis dan lada bubuk diamkan sebentar lalu ungkep.\", \"Siapkan bumbu halus\", \"Masukan air dan bumbu halus masak hingga mendidih, masukan ayam dan kecap aduk dan diamkan sebentar.\", \"Masukan gula,garam dan penyedap serta cabe rawit aduk hingga rata diamkan sebentar..\", \"Masak hingga matang\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1452, 4, 'Pindang ceker ayam 🐣', 'Pindang ceker ayam 🐣 dengan bumbu meresap sempurna.', '[\"500 gr ceker ayam\", \"Secukup nya daun bawang\", \"Secukup nya kemangi\", \"1 buah tomat\", \"1 ruas jari jahe\", \"1 ruas jari sereh\", \"1 ruas jari laos\", \"3 lembar daun salam\", \"Bumbuh yang di haluskan:\", \"8 siung bawang merah\", \"3 siung bawang putih\", \"1/5 ons cabai merah kriting ( boleh di tambah kalau suka pedas\", \"1 bungkus kaldu ayam (optional)\", \"Secukup nya garam\", \"Secukupnya gula\", \"1 sdm kecap manis\", \"1 sdt kecap asin\", \"1 sdt terasi\", \"3 sdm minyak (untuk menumis)\", \"1000 ml air\"]', '[\"Cuci sampai bersih ceker ayam lalu rebus sampai mendidih lalu matikan kompor dan buang air rebusan\", \"Didihkan 1000 ml air kedalam panci lalu masukan ceker yg sdah di rebus tadi, lalu tambahkan sereh laos jahe dan daun salam\", \"Blender bumbu yg di haluskan cabai bawang putih dan bawang merah sampai halus lalu tumis dengan 3 sdm minyak tumis bumbu sampai harum dan mateng\", \"Lalu masukan bumbu yg di tumis tadi ke dalam panci yg berisi ceker ayam tambahkan garam gula terasi dan kaldu ayam(optional) lalu baru masukan kecap manis dan asin tunggu sampai ceker ayam mateng dan kua menyusut\", \"Potong2 daun bawang dan tomat lalu masukan ke dalam kua ceker ayam koreksi rasa terakhir masukan kemangi dan angkat pindang ceker ayam siap di sajikan 👌\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1453, 2, 'Ayam Panggang Bumbu Gulai', 'Buat Ayam Panggang Bumbu Gulai yang nikmat dengan langkah-langkah mudah ini.', '[\"1 Ekor Ayam Ukuran Sedang\", \"Bumbu Halus :\", \"6 Buah Bawang Merah\", \"4 Siung Bawang Putih\", \"6 Buah Cabe Merah Keriting\", \"2 Sdm Bumbu Gulai Siap Pakai\", \"2 Cm Jahe\", \"3 Cm Lengkuas\", \"2 Batang Serai (Memarkan)\", \"6 Lembar Daun Jeruk\", \"2 Lembar Daun Salam\", \"350 ML Santan\", \"1 Potong Asam Kandis\"]', '[\"Bersihkan ayam, potong menjadi empat bagian. Campur bersama bumbu halus. Aduk sampai rata.\", \"Masak ayam dalam panci tertutup dengan api kecil bersama serai, daun jeruk, dan daun salam sampai berair. Tuang santan, sambil sesekali diaduk sampai santan habis. Angkat.\", \"Bakar ayam di oven sambil sampai ayam mulai mongering di kedua sisinya.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1454, 3, 'Tumis Ayam Wangi', 'Tumis Ayam Wangi - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 belah dada ayam\", \"7 siung bawang meeah\", \"4 siung bawang putih\", \"10 buah cabai merah\", \"5 buah cabe rawit (sesuai selera)\", \"1 batang daun bawang\", \"2 lembar daun pandan\", \"1 bungkus tepung bumbu (secukupnya)\", \"2 sdm terigu (larutkan dengan sedikit air dan garam)\", \"Secukupnya garam\", \"Secukupnya merica bubuk\", \"Secukupnya kaldu bubuk\"]', '[\"Fillet dada ayam, potong dadu. Beri sedikit air jeruk nipis dan garam agar tidak amis.\", \"Rajang bawang merah, bawang putih, cabe merah. Potong2 daun pandan dan bawang daun, jangan terlalu kecil.\", \"Celupkan fillet ayam ke adonan terigu yang telah dicampur air dan garam, balur ke tepung bumbu. Ulangi bila perlu. Goreng hingga matang, coklat keemasan.\", \"Tumis bawang, cabe hingga harum. Masukkan daun pandan dan daun bawang. Tumis hingga layu. Beri garam, merica dan kaldu bubuk. Cicipi rasa. Matikan api, masukkan ayam goreng. Aduk rata.\", \"Sajikan dengan nasi panas. Yummy..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1455, 2, 'Oseng jantung ayam sayur', 'Hidangan ayam lezat: Oseng jantung ayam sayur untuk keluarga tercinta.', '[\"1/4 jantung ayam\", \"1/4 kacang panjang\", \"1 biji wortel\", \"Bumbu :\", \"7 siung bawang merah\", \"4 siung bawang putih\", \"3 biji cabe rawit\", \"2 biji cabe merah keriting\", \"1 sachet saori\", \"Gula pasir\", \"Kecap\", \"Royko ayam\", \"Garam\", \"1/2 sdt maizena\"]', '[\"Cuci bersih jantung ayam lalu rebus sampai matang\", \"Siapkan bumbu : bawang merah bawang putih cabe iris tipis tipis\", \"Siapkan wajan tumis semua bumbu sampai layu\", \"Masukkan jantung ayam tumis tumis sebentar\", \"Masukkan saori garam gula royko kecap sesuai selera.. Kalo saya suka agak manis\", \"Masukkan air 1/2gelas belimbing aduk2 sebentar\", \"Terakhir masukkan tepung maizena aduk sampai matang n masakkan jd mengental\", \"Angkat n sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1456, 2, 'Ayam Kemiri Ketofy', 'Cara membuat Ayam Kemiri Ketofy yang enak dan praktis untuk keluarga.', '[\"500 gram ayam, potong sesuai selera\", \"1 batang serai, geprek\", \"1 ruas lengkuas, geprek\", \"1 sdt kecap tropicanaslim\", \"2-3 tetes sucralose\", \"1 sdt garam\", \"Bumbu Halus:\", \"5 butir kemiri sangrai\", \"8 siung bawang merah\", \"6 siung bawang putih\", \"1 sdt ketumbar\", \"1 ruas terasi keto\", \"Secukupnya air\"]', '[\"Cuci bersih ayam, taburi garam dan jeruk nipis, diamkan 30 menit, cuci lagi\", \"Tumis bumbu halus dengan serai dan lengkuas, tumis agak kering agar tidak bau langu\", \"Masukkan kecap, sucralose, garam.. Beri sedikit air, aduk, lalu masukkan ayam\", \"Masak dengan api kecil sampai ayam matang, bumbu meresap dan air menyusut.. Siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1457, 3, 'Ayam kecap', 'Hidangan ayam lezat: Ayam kecap untuk keluarga tercinta.', '[\"250 gr ayam potong\", \"6 siung bawang merah\", \"3 siung bawang putih\", \"2 buah cabe merah\", \"15 buah cabe rawit\", \"Lengkuas\", \"Jahe\", \"Daun salam\", \"Sereh\", \"Kecap\", \"Penyedap rasa\", \"Tepung maizena\", \"Air\"]', '[\"Rebus potongan ayam smpai matang\", \"Tumis bawang merah, bawang putih, cabe merah, dan cabe rawit smpai harum\", \"Tambahkan sdikit air, masukkan jahe, lengkuas, yg sudah digeprek. Masukkan daun salam dan sereh. Tambahkan air secukupnya\", \"Masukkan ayam yg telah matang, lalu masak hingga meresap, tambahkan maizena agar kuah mengental\", \"Koreksi rasa, siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1458, 2, 'Semur Ayam Kecap', 'Semur Ayam Kecap - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"500 gr daging ayam\", \"10 bawang merah\", \"2 daun salam\", \"4 cengkeh\", \"1 cm kayu manis\", \"1 tomat\", \"Bumbu halus\", \"3 bawang putih\", \"2 ruas jahe\", \"2 kemiri sangrai\", \"1 sdt ketumbar\", \"1/4 sdt jinten\", \"1/2 sdt merica\", \"1/2 sdt pala bubuk\", \"Secukupnya garam, gula, kecap, kaldu bubuk\"]', '[\"Rebus daging untuk menghilangkan darah yg menempel, tiriskan. Goreng dengan api kecil setengah matang\", \"Iris bawang merah, tomat, haluskan bumbu. Tumis bawang merah hingga harum, tambahkan bumbu halus. Masukkan daun salam, kayu manis, cengkeh dan tomat. Beri sedikit air\", \"Tambahkan ayam yg sudah digoreng tadi, tambahkan air sampai ayam terendam. Beri garam, gula, kecap dan kaldu bubuk. Koreksi rasa.\", \"Biarkan bumbu meresap dan air menyusut/ sesuai selera\", \"Siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1459, 4, 'Ayam Panggang Teflon', 'Ayam Panggang Teflon dengan bumbu meresap sempurna.', '[\"300 gr Ayam potong (jadi 2 potong)\", \"Bumbu kuning :\", \"1 siung bawang putih\", \"1 sdm ketumbar\", \"1/2 ruas kunyit\", \"1 sdm garam\", \"300 ml air\", \"Bumbu panggang :\", \"2 siung bawang merah\", \"2 siung bawang putih\", \"3 buah cabe\", \"1 sdm garam\", \"1 sdt lada\", \"1 sdm masako\", \"3 sdm kecap manis\"]', '[\"Sayat ayam agar mempermudah bumbunya meresap\", \"Haluskan semua bumbu kuning lalu masukkan ke dalam panci dan beri air, tunggu hingga mendidih\", \"Setelah mendidih, masukkan ayam lalu rebus ayam sampai air di panci tinggal sedikit (hati hati gosong)\", \"Haluskan semua bumbu panggang lalu masukkan ke dalam mangkok lalu beri kecap\", \"Setelah ayam selesai di rebus, balurkan bumbu panggang ke seluruh bagian ayam\", \"Masukkan kulkas (bukan freezer) dan tunggu hingga 1 sampai 2 jam sampai bumbu meresap\", \"Setelah 2 jam panaskan pan dengan api kecil lalu masukan margarin secukupnya\", \"Panggang ayam hingga masak (api kecil), jangan sampai terlalu gosong\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1460, 3, 'Ayam kecap bumbu giling', 'Nikmati kelezatan Ayam kecap bumbu giling dengan resep sederhana ini.', '[\"Setengah badan ayam (1 paha dan 1 dada)\", \"10 bawang merah\", \"5 bawang putih\", \"Jahe geprek dan giling\", \"Laos geprek dan giling\", \"5 cabe kriting merah\", \"5 cabe rawit merah\", \"Lada bubuk\", \"Daun jeruk\", \"Daun salam\", \"Wortel / kentang/ brokoli (opsional)\", \"Halawa bumbu probiotik perisa ayam\"]', '[\"Giling semua bumbu (gamau ribet jd lgsg pke blender)\", \"Tumis bumbu beserta jahe laos geprek, salam, daun jeruk, lada bubuk, halawa..\", \"Setelah dikira matang bumbunya, masukkan ayam... Aduk smpe rata... Biarkan kurleb 1-2 mnt\", \"Masukkan air, kecap, biarkan smpe mendidih danbair berkurang\", \"Tambahkan air lagi dan kecap agak lbh berasa, garam dan sayuran\", \"Biarkan sampe air surut atau kalau suka kering.. Biarkan sampe air habis...\", \"Hidangkan...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1461, 3, 'Opor ayam', 'Buat Opor ayam yang nikmat dengan langkah-langkah mudah ini.', '[\"6 potong sayap bagi 2 yg sudah direbus bentar\", \"15 butir telur puyuh rebus\", \"6 buah tahu bagi 4 lalu goreng tiriskan\", \"6 butir bawang merah iris\", \"3 siung bawang putih iris\", \"3 cm jahe iris\", \"3 cm lengkuas iris\", \"secukupnya Merica\", \"3 lembar daun salam\", \"2 lembar daun jeruk\", \"2 bungkus kara kecil\", \"sesuai selera Garam, gula, kaldu dan air\", \"Sayuran di rebus terpisah sesuai selera (bisa skip)\", \"Bawang goreng untuk taburan\"]', '[\"Tumis bumbu: bawang, jahe, lengkuas daun salam sampai wangi\", \"Masukan ayam yg sudah di rebus, aduk bentar. Lalu masukan santan kara, aduk sampai rata. Masukan air sesuai selera\", \"Masukan telur puyuh rebus, daun jeruk. beri garam,gula, kaldu, merica sampai rasanya pas.\", \"Terakhir masukan tahu. Aduk sampai rata, hidangkan dengan sayuran yg sudah di rebus terpisah dan beri taburan bawang goreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(1462, 4, 'Chicken nibbles crispy super easy', 'Resep Chicken nibbles crispy super easy ala rumahan yang dijamin menggugah selera.', '[\"Ayam potong an sayap\", \"1,5 liter air\", \"Penyedap rasa\", \"1 sdt garam\", \"Bumbu tepung\", \"500 gram tepung terigu\", \"300 gram tepung beras\", \"1 sdt garam\", \"1 sdt Chili powder\", \"Royco rasa ayam\", \"1 butir telur kocok lepas\", \"2 sdm susu Cair\", \"Minyak untuk menggoreng\", \"1 sdm mentega\"]', '[\"Pertama rebus ayam kurang lebih 45 menit lalu angkat dan sisihkan. Kocok telur dan susu cair (kocok lepas) masukan ayam ke dalam telur sampai merata\", \"Campurkan tepung beras, tepung terigu, Chili powder, royco dan garam ke dalam wadah dan aduk hingga bercampur (pisahkan wadah tepung dengan telur) lalu balurkan ayam dengan tepung\", \"Panaskan minyak untuk menggoreng (deep fried) dan tambahkan 1 sdm margarin ke minyak panas\", \"Goreng hingga berwarna golden atau keemasan.. selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1463, 4, 'Ayam Goreng Balado', 'Resep praktis Ayam Goreng Balado yang bisa dicoba di rumah.', '[\"4 potong ayam (disini sy pake sayap karena tinggal nyisa ini)\", \"Bumbu ayam goreng :\", \"3 siung bawang merah\", \"2 siung bawang putih\", \"Bumbu penyedap\", \"Air\", \"Bumbu balado :\", \"6 siung bawang merah\", \"4 siung bawang putih\", \"3 bh cabe merah\", \"3 bh cabe rawit (boleh lebih kalo mau pedes bgt)\", \"Tomat\", \"Gula pasir\", \"Garam\", \"Mecin\"]', '[\"Cuci bersih ayam\", \"Haluskan bawang merah, bawang putih untuk bumbu ayam goreng lalu tumis tambahkan dengan royco/masako dan air masukan ayam biarkan sampai bumbu meresap lalu goreng ayam nya\", \"Haluskan bawang merah, bawang putih, cabe rawit, cabe merah, tomat sampai halus lalu tumis bumbu untuk balado tambahkan bawang daun/kemangi lalu beri bumbu penyedap, garam, gula pasir secukupnya\", \"Masukan ayam yg telah digoreng td kedalam bumbu balado aduk sampai rata pada semua ayam, setelah tercampur matikan kompor dan makanan siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1464, 3, 'Sate lilit ayam praktis', 'Resep praktis Sate lilit ayam praktis yang bisa dicoba di rumah.', '[\"250 gr ayam giling\", \"1 genggam kelapa parut\", \"1 btg serai\", \"Minyak goreng\", \"Stik es krim\", \"Bumbu halus\", \"5 btr bawang merah\", \"3 siung bawang putih\", \"1 buah cabe merah, buang biji\", \"1 cm lenkuas\", \"1/2 cm kencur\", \"1 cm kunyit\", \"1/2 cm jahe\", \"1 sdm gula merah sisir\", \"Garam, kaldu bubuk\"]', '[\"Tumis bumbu halus + serai sampai matang & harum. Test rasa, buang serainya\", \"Campur semua bahan. Lilitkan adonan pd stik es krim, jgn terlalu tipis jgn terlalu tebal jg. Lakukan sampai adonan habis\", \"Panaskan wajan teflon atau panggangan. Letakkan sate diatasnya, panggang sampai matang. Done!\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1465, 4, 'Ayam tepung bumbu original', 'Resep Ayam tepung bumbu original ala rumahan yang dijamin menggugah selera.', '[\"1 kg ayam potong potong jadi 8\", \"1 btr telor\", \"Bumbu halus\", \"1 sdt ketumbar\", \"1 bks kaldu\", \"1 ruas jari kunyit\", \"1/2 sdt garam\", \"Bahan tepung\", \"500 gr tepung cakra\", \"150 gr tepung maizena\", \"1 bks lada bubuk\", \"1 bks kaldu\", \"Bumbu celupan\", \"250 ml air\", \"5 sdm campuran bahan tepung\", \"1 sdt baking soda\"]', '[\"Ayam diberi bumbu halus lalu simpan dalam kulkas semalaman\", \"Buat bumbu celup....aduk semua bahan juga simpan dikulkas\", \"Aduk jadi satu bahan tepung sampai rata\", \"Ambil ayam lalu kasih satu butir telor aduk rata lalu gulingkan ketepung sambil diremas remas,baru celupkan ke bahan celupan batu gulingkan ketepung lagi sambil dicubit cubit...\", \"Lalu goreng dengan api sedang dengan minyak banyak ya...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1466, 4, 'Risoles Rogut Ayam (Super Creamy)', 'Resep Risoles Rogut Ayam (Super Creamy) ala rumahan yang dijamin menggugah selera.', '[\"Bahan Kulit :\", \"150 gr terigu (segitiga biru)\", \"300 ml air\", \"1 butir telur\", \"1 sdm butter (saya pakai wijsman)\", \"1/2 sdt garam\", \"Bahan isian :\", \"250 gr daging cincang ayam\", \"1 buah wortel (potong dadu)\", \"3 sdm tepung terigu\", \"1/2 siung bawang bombay\", \"2 siung bawang putih (potong halus)\", \"1/2 sdt pala bubuk\", \"1 sdt gula\", \"Secukupnya garam dan gula\", \"2 sdm butter untuk menumis\", \"Bahan celupan :\", \"2 butir telur (kocok lepas)\", \"Secukupnya tepung panir halus\"]', '[\"Cara buat kulit : campur semua bahan jadi satu, aduk rata sampai licin tidak ada yg bergerindil.\", \"Buat dadaran di teflon ambil 1 ciduk sayur, dgn api kecil lakukan sampai habis.\", \"Cara buat isian : tumis bombay, bawang putih sampai harum, masukkan ayam & wortel, masak sampai berubah warna.\", \"Masukkan terigu aduk sampai berbutir, lalu masukkan susu cair dikit2 sambil diaduk. beri lada, pala, gula, garam, kaldu, masak sampai kuah mengental lalu angkat.\", \"Penyelesaian : ambil 1 kulit dadaran beri isian, lipat, & celupkan ke telur lalu tepung panir.\", \"Goreng dengan minyak panas api sedang, sampai kuning keemasan\", \"Yummy, selamat mencoba! 😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1467, 3, 'Ayam tepung kecap', 'Resep praktis Ayam tepung kecap yang bisa dicoba di rumah.', '[\"1/4 ayam\", \"Tepung sajiku\", \"2 Bawang putih\", \"3 Bawang merah\", \"1 cm jahe\", \"Cabe rawit\", \"secukupnya Kecap\", \"secukupnya Air\"]', '[\"Ayam dipotong kecil-kecil dan campurkan dengan tepung sajiku, goreng sampai kering lalu tiriskan\", \"Iris tipis bawang putih, bawang merah, cabe rawit dan geprek jahe\", \"Tumis irisan bawang, cabe dan jahe sampai wangi lalu tambah air secukupnya\", \"Setelah air mendidih masukkan ayam dan tambahkan garam, penyedap rasa dan kecap secukupnya\", \"Tunggu hingga kuah menjadi sedikit kental dan ayam tepung kecap siap disiapkan 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1468, 2, 'Sup Ayam', 'Cara membuat Sup Ayam yang enak dan praktis untuk keluarga.', '[\"250 gr ayam potong2\", \"700 ml air\", \"1 buah wortel potong kotak\", \"Secukupnya garam dan kaldu ayam bubuk\", \"1/4 butir pala biarkan utuh\", \"1 ruas jahe geprek\", \"Secukupnya daun bawang iris, seledri iris, dan bawang goreng\", \"Bumbu halus:\", \"5 siung bawang putih\", \"2 buah bawang merah\", \"1/2 sdt merica\"]', '[\"Rebus ayam sampai mendidih. Buang air rebusan pertama.\", \"Rebus kembali ayam bersama jahe geprek dan biji pala. Sampai mendidih.\", \"Tumis bumbu halus sampai harum.\", \"Masukkan tumisan bumbu halus ke dalam air rebusan ayam. Masukkan wortel. Beri garam dan kaldu bubuk. Masak sampai mendidih. Koreksi rasa.\", \"Tumis bumbu halus sampai harum.\", \"Masukkan tumisan bumbu halus ke dalam air rebusan ayam. Masukkan wortel. Beri garam dan kaldu bubuk. Masak sampai mendidih. Koreksi rasa.\", \"Sajikan dengan taburan daun bawang, seledri dan bawang goreng.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1469, 2, 'Opor Ayam', 'Cara membuat Opor Ayam yang enak dan praktis untuk keluarga.', '[\"1 kg ayam\", \"1 bks santan kara\", \"Salam\", \"Laos\", \"Daun jeruk\", \"Sereh\", \"Kaldu bubuk\", \"Gula dan garam\", \"Merica bubuk\", \"Air\", \"Bumbu halus :\", \"Bawang merah\", \"Bawang putih\", \"Jahe\", \"Kunir\", \"Ketumbar\", \"Kemiri\"]', '[\"Tumis bumbu halus bersama salam, laos, sereh dan daun jeruk\", \"Apabila sdh harum masukkan ayam yg sudah dipotong kecil dan dibersihkan\", \"Jika ayam dirasa sdh tercampur rata dengan bumbu tambahkan air secukupnya\", \"Biarkan hingga ayam empuk, kemudian tambahkan merica bubuk, gula, garam dan kaldu bubuk\", \"Beri santan dan koreksi ras\", \"Hidangkan dan taburi bawang goreng lebih nikmat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1470, 4, 'Ayam Saos Lada Hitam', 'Resep praktis Ayam Saos Lada Hitam yang bisa dicoba di rumah.', '[\"1/4 dada ayam filet, potong dadu\", \"2 buah bawang bombay, potong bulat\", \"1 sdm tepung maizena\", \"Bumbu:\", \"3 siung bawang putih\", \"1 sdt lada hitam\", \"2 sdm saos tomat\", \"3 sdm saos pedas\", \"1 sdt saos tiram\", \"1 sdm kecap manis\", \"1 sdt kecap asin\", \"secukupnya Garam\", \"secukupnya Gula pasir\"]', '[\"Haluskan bawang putih dan gerus kasar lada hitam.\", \"Tumis bawang putih dan lada hitam. Lalu masukkan daging ayam.\", \"Aduk2 sampai ayam berubah warna (api kecil saja).\", \"Masukkan air, berbagai macam saos, kecap asin, kecap manis, garam, gula pasir.\", \"Kentalkan kuah dengan tepung maizena yang sudah dilarutkan dengan air.\", \"Masukkan bawang bombay. Aduk2, tunggu hingga kuah meletup2. Koreksi rasa. Angkat beri irisan daun bawang.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1471, 2, 'Tongseng Ayam dengan kuah santan kental yang pedass #18', 'Tongseng Ayam dengan kuah santan kental yang pedass #18 dengan bumbu meresap sempurna.', '[\"1/2 ekor ayam\", \"Air\", \"1 Kara\", \"Minyak\", \"Bawang goreng\", \"Secukupnya irisan kobis\", \"1 tomat belah sesuai selera\", \"Bumbu iris :\", \"5 bawang merah\", \"10 rawit / sesuaikan\", \"Bumbu halus :\", \"5 bawang putih\", \"2 kemiri\", \"Seruas kunyit\", \"Bumbu pelengkap :\", \"1 sdm tumbar bubuk\", \"1/2 sdm merica\", \"secukupnya Garam\", \"secukupnya Gula\", \"Penyedap rasa\", \"Daun salam\", \"Daun jeruk\", \"Lengkuas1 sereh geprek\", \"Seruas jahe geprek\"]', '[\"Cuci bersih ayam, lalu potong sesuai selera..\", \"Goreng irisan bawang merah setengah matang, masukkan bumbu halus.. Tunggu hingga harum lalu masukkan daun salam daun jeruk sereh lengkuas jahe.. Kemudian masukkan cabai dan tomat.. Setelah itu masukkan ayamnya.. Adukk hingga bumbu merata..\", \"Tuang air sedikit agar ayam cepat empuk dan matang.. Tunggu sampai air menyusut kemudian masukkan kara.. Dan tambahkan air serta merica bubuk, garam, gula, penyedap rasa\", \"Setelah matang masukkan kobis.. Tunggu sebentar saja setelah itu tuang ke mangkok dan taburin bawang gorengnya, masakan siap untuk disajikan.\", \"Selamat mencoba 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1472, 4, 'Sayap ayam crispy ala2', 'Resep Sayap ayam crispy ala2 ala rumahan yang dijamin menggugah selera.', '[\"6 potong sayap ayam (bagi 2)\", \"4 siung bawang putih (dihaluskan)\", \"secukupnya Garam\", \"secukupnya Merica\", \"Secukupnya penyedap rasa\", \"1 butir telur\", \"Bumbu pelapis :\", \"5 sdm tepung terigu\", \"2 sdm tepung maizena\"]', '[\"Lumuri sayap ayam dengan bawang putih halus, garam, merica, dan bumbu penyedap. Campur dengan rata. Diamkan selama beberapa jam supaya bumbu meresap. Lebih enak lagi kalo semalaman\", \"Jika sudah akan dmasak, lumuri dengan telur. Lalu balur ke bahan pelapis. Cubit2 ayamnya supaya tepung bisa menempel\", \"Goreng hingga matang dan kecoklatan. Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1473, 3, '8. Egg salted chicken', 'Nikmati kelezatan 8. Egg salted chicken dengan resep sederhana ini.', '[\"1 iris fillet dada ayam, potong kecil\", \"Bumbu halus :\", \"1 siung bawang merah\", \"1 siung bawang putih\", \"3 sdm tepung goreng ayam\", \"Sedikit air dingin\", \"Bumbu saus :\", \"2 butir kuning telur\", \"200 ml susu cair\", \"1 siung bawang putih\", \"Secukupnya garam\"]', '[\"Masak ayam dengan digoreng tepung seperti biasa\", \"Kemudian buat saus telur asinnya, yg pertama campur kuning telur asin yg sudah matang dgn susu cair dan garam, kemudian tumis bawang putih lalu masukkan campuran yg tadi aduk2 hingga mendidih kemudian matikan api... Dan siram sausnya di atas ayam\", \"Siap disantap...\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1474, 2, 'Ampela ati ayam sayur genjer saus tiram', 'Resep praktis Ampela ati ayam sayur genjer saus tiram yang bisa dicoba di rumah.', '[\"1 ikat sayur genjer\", \"1/4 kg hati ampela ayam\", \"Bumbu halus\", \"3 siung bawang putih\", \"4 siung bawang merah\", \"7 Cabe rawit merah\", \"secukupnya Gula dan garam\", \"1 sachet saus tiram\", \"Minyak untuk menumis\", \"secukupnya Air\"]', '[\"Cuci dan potong sayur genjer lalu rebus sekitar 1 min dan tiriskan peras air nya,rebus juga hati dan ampela ayam potong dadu\", \"Haluskan bumbu kemudian panas kan wajan dan minyak tumis bumbu halus masukan hati ampela ayam aduk2 terakhir masukan sayur genjer,saus tiram gula dan garam secukupnya kemudian tambahkan air masak hingga matang\", \"Koreksi rasa 🤗🤗🤗\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1475, 4, 'Ayam Yakiniku(tumis)', 'Resep Ayam Yakiniku(tumis) ala rumahan yang dijamin menggugah selera.', '[\"4 ptg dada ayam(dagingnya saja)\", \"1 buah lemon(untuk rendam ayam)\", \"Bumbu tumis\", \"3 buah cabai merah (iris)\", \"2 buah cabai hijau(iris)\", \"1 btg bawang daun (iris)\", \"1 buah bawang bombay (iris)\", \"1 sdm margarine\", \"2 sdm kecap asin\", \"1 sdm kecap manis\", \"Bumbu halus(dibagi2):\", \"4 siung bawang putih\", \"1 ruas jari jahe\"]', '[\"Bersihkan ayam rendam sebentar pakai lemon kemudian bilas\", \"Lumuri ayam dengan bumbu halus\", \"Tumis bumbu tumis, masukkan sampai harum(sisihkan)\", \"Tumis bumbu halus sampai harum lalu masukkan ayam tambahka air secukupya\", \"Setelah ayam hampir matang, masukkan bumbu tumis masak sebentar sekali agar cabai dan.bawang tdk layu\", \"Siap di sajikan. Notes kalo pengen teriyaki tinggal balik porsi kecap manis lebih banyak\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1476, 2, 'Bestik ati ampela ayam', 'Sajian Bestik ati ampela ayam yang praktis dan lezat untuk dinikmati bersama.', '[\"4 hati ampela ayam, cuci, rebus, potong2 dan goreng sebentar\", \"1 buah kentang, potong dan goreng hingga berkulit\", \"1 buah wortel, potong memanjang\", \"6 buah buncis, potong panjang\", \"Bumbu :\", \"2 buah bawang putih\", \"5 buah bawang merah\", \"1 buah bawang bombay\", \"secukupnya Minyak goreng  untuk menumis\", \"secukupnya Air\", \"Garam, merica dan kaldu bubuk\", \"secukupnya Kecap manis\", \"sedikit Pala\"]', '[\"Iris tipis bawang2an, tumis dengan sedikit minyak sampai kecoklatan\", \"Masukkan buncis dan wortel, tumis sebentar\", \"Masukkan air\", \"Bumbui dengan garam, merica, pala, kaldu bubuk dan kecap sesuai selera\", \"Masukkan hati ampela dan kentang goreng\", \"Masak dengan api kecil hingga bumbu meresap dan kuah menyusut\", \"Sajikan hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1477, 4, 'Mie goreng Ayam seadanya...😄😄', 'Cara membuat Mie goreng Ayam seadanya...😄😄 yang enak dan praktis untuk keluarga.', '[\"1/2 bungkus mie telor\", \"1 paha ayam filet, iris tipis\", \"1 butir telur\", \"5 batang sawi hijau\", \"1 sachet kecap bango\", \"bumbu halus :\", \"2 siung bawang putih\", \"3 siung bawang merah\", \"sedikit lada bubuk\", \"secukupnya royco ayam\"]', '[\"Rebus dahulu mie telor dan ayam, setelah matang, sisihkan. beri sedikit minyak pada rebus mie. dan beri kecap aduk hingga rata.\", \"Haluskan, bawang putih, bawang merah, dan lada halus, beri sedikit garam. Ulek hingga halus.\", \"Tumis bumbu yang dihaluskan tadi hingga harum. Masukan telur, aduk rata. kemudian masukan telur, aduk - aduk hingga tercampur rata.\", \"Masukan sawi hijau, aduk hinga benar - benar tercampur semua bahan, dan jangan lupa tambahkan royco. Masak hingga matang.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1478, 4, 'Opor ayam kuning', 'Opor ayam kuning dengan bumbu meresap sempurna.', '[\"10 bh sayap ayam\", \"6 btr bawang merah\", \"5 btr bawang putih\", \"1 ruas jahe\", \"1 ruas lengkuas geprek\", \"1/2 ruas kunyit\", \"1 sdt ketumbar\", \"1/2 sdt merica\", \"4 btr kemiri\", \"100 ml santan\", \"secukupnya Garam\", \"1 lbr daun salam\", \"1 batang sereh geprek\", \"secukupnya Bawang goreng\", \"Royco ayam (skip)\"]', '[\"Haluskan bumbu kecuali daun2an.\", \"Rebus ayam setengah matang\", \"Tumis bumbu sampai harum. Masukkan ayam. Masukkan daun2an. Beri air. Biarkan sampai bumbu meresap ke ayam.\", \"Tuang santan. Aduk rata. Tunggu sampai agak mendidih. Angkat. Sajikan dg taburan bawang goreng\", \"Taraa....enaak nyaa...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1479, 4, 'Swiss chicken wings', 'Nikmati kelezatan Swiss chicken wings dengan resep sederhana ini.', '[\"14 sayap ayam\", \"1 sdm garam kasar\", \"(saya ganti dengan 1sdt garam halus)\", \"1 liter air dingin\", \"1/2 panci air mentah\", \"900 ml air\", \"Bumbu :\", \"4 siung bawang merah (geprek)\", \"4 lembar iris jahe\", \"4 sdm gula batu\", \"2 sdm kecap asin\", \"1.5 sdm kecap hitam\", \"1 sdt garam\", \"2 fakok\", \"2 helai daun hongyip\", \"(saya pakai 1 karena di kulkas habis)\"]', '[\"Remas sayap ayam dengan garam. Cuci bersih lalu rebus 1/2 panci air higga mendidih. Masukka sayap ayam rebus 30 detik.Lalu taruh sayap ayam rendam ke dalam air es selama 10 menit. Angkat\", \"Cuci fakok dan hongyip, tiriskan.\", \"Rebus 900 ml air, masukkan bahan bumbu.Setelah mendidih masukkan sayap ayam. Rebus sayap ayam selama 4 menit.Angkat\", \"Rebus lagi air bumbu selama 8 menit, agar lebih mengental.\", \"Lalu masukkan sayap ayam lagi ke panci, kecilkan api.Rebus 4 menit lagi sambil di lihat takut gosong. Matikan api.Diamkan sebentar, lalu hidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1480, 3, 'Tumis Ampela Ayam ala QeeLa\'s Kitchen', 'Tumis Ampela Ayam ala QeeLa\'s Kitchen dengan bumbu meresap sempurna.', '[\"1/2 kg ampela ayam\", \"6 siung bawang putih (iris)\", \"8 siung bawang merah (iris)\", \"1/2 ons cabe rawit/cabe hijau kriting (iris)\", \"2 lembar daun salam\", \"1 ruas lengkuas (geprek)\", \"1 ruas jahe (geprek)\", \"4 sdm kecap manis\", \"1 sdm saori saus tiram\", \"Secukupnya gula\", \"Secukupnya garam\", \"Royco ayam (bila suka)\", \"Secukupnya minyak\", \"Secukupnya air\"]', '[\"Bersihkan ampela ayam, rebus 8 menit, tiriskan lalu potong2\", \"Tumis duo bawang sampai harum, masukan cabai, salam, laos, lengkuas sampai layu\", \"Masukan ampela ayam yg sudah dipotong2, saori, gula, garam, royco ayam, kecap dan air\", \"Biarkan mendidih, koreksi rasa\", \"Setelah menyusut, aduk sebentar\", \"Siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1481, 3, 'Mie Ayam Pokcoy', 'Resep praktis Mie Ayam Pokcoy yang bisa dicoba di rumah.', '[\"250 gr mie keriting (rebus, tiriskan)\", \"6 pokcoy/ sawi hijau (rebus sebentar tiriskan)\", \"Kuah:\", \"Secukupnya tulang ayam\", \"600 ml air\", \"3 siung bawang putih\", \"1/2 sdt merica\", \"Secukupnya garam dan kaldu bubuk\", \"Bahan toping ayam:\", \"500 gr ayam bagian dada (potong²)\", \"200 ml air\", \"1 batang daun bawang iris\", \"2 cm lengkuas geprek\", \"2 cm jahe geprek\", \"2 batang sereh geprek\", \"2 lbr daun salam\", \"4 lbr daun jeruk\", \"1 sdm saus tiram\", \"1 sdt kecap asin\", \"4 sdm kecap manis\", \"2 sdm gula merah\", \"Secukupnya garam, gula dan kaldu bubuk rasa ayam\", \"Bumbu halus:\", \"5 siung bawang putih\", \"4 buah bawang merah\", \"1 ruas kunyit\", \"1/2 sdt merica\", \"1/4 sdt ketumbar\"]', '[\"Kuah: Rebus tulang ayam sampai mendidih. Tumis bawang putih sampai harum. Masukkan ke dalam air rebusan. Beri garam, merica dan kaldu bubuk. Masak sampai mendidih kembali. Matikan api\", \"Tumis bumbu halus dengan lengkuas, jahe, sereh, daun salam, dan daun jeruk sampai harum. Masukkan daun bawang iris, tumis sampai layu. Kemudian masukkan ayam masak sampai berubah warna.\", \"Masukkan kecap manis, kecap asin, saus tiram dan gula merah. Aduk2, masak sampai bumbu meresap.\", \"Kemudian masukkan sedikit air. Beri garam, gula, dan kaldu bubuk. Masak sampai air menyusut. Koreksi rasa matikan api.\", \"Penyajian:\", \"Tata mie, pokcoy, beri toping ayam, siram dengan kuah. Taburi daun bawang. Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1482, 3, 'Steak Ayam', 'Sajian Steak Ayam yang praktis dan lezat untuk dinikmati bersama.', '[\"2 buah daging ayam filet\", \"adonan basah :\", \"3 sdm tepung bumbu (me: sajiku)\", \"air secukupnya buat agak encer\", \"adonan kering :\", \"6 sdm tepung terigu\", \"2 sdm tepung maizena\", \"saos steak :\", \"1 sdm tepung bumbu\", \"1 siung bawang putih besar geprek cincang\", \"1 sdm saos tiram\", \"1 sdt saos inggris (boleh skip)\", \"secukupnya margarin\", \"secukupnya gula garam merica\", \"pelengkap:\", \"wortel rebus\", \"buncis rebus\", \"jagung rebus (saya tdk pakai)\", \"kentang goreng\", \"saos cabe\"]', '[\"Cara membuat saus steak : panaskan 1sdm munjung margarin hingga meleleh lalu masukan tepung bumbu masak dgn api kecil hingga kecoklatan lalu tumis bawang putih sebentar,masukan air,saos tiram,gula,merica,dan garam jika kurang asin,aduk hingga mengental,jika dirasa kurang kental bisa ditambah sedikit tepung bumbu larutkan sedikit air lalu tuang ada aduk k dalam saos steak\", \"Siapkan daging ayam fillet iris tipis melebar,masukan ayam ke adonan basah lalu gulingkan ke adonan kering tekan2 (jika mau tepung tebal bisa diulang masukan ke adonan basah dan adonan kering lagi). goreng hingga matang\", \"Sajikan ayam crispy beserta pelengkap dan saos steak\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1483, 3, 'Chicken teriyaki rice bowl', 'Resep praktis Chicken teriyaki rice bowl yang bisa dicoba di rumah.', '[\"1 kg fillet paha ayam\", \"Merica\", \"Garam\", \"Bumbu penyedap rasa ayam\", \"Tepung maizena\", \"Tepung terigu\", \"Light soya\", \"Dark soya\", \"Mirin/Sake (tentative)\", \"Gula\", \"Madu (tentative)\", \"Bawang bombay\", \"Jahe\", \"Bawang putih\", \"Cabai merah besar\", \"Jagung baby\", \"Brokoli\", \"Wortel baby\", \"Minyak wijen\", \"Togarashi/bubuk cabai\", \"Wijen sangrai\", \"Nasi putih\", \"Kecap ikan\", \"Telur\"]', '[\"Pertama tama marinasi ayam dengan lada, garam, gula, dan penyedap rasa ayam. Lalu tambahkan 2 buah telur, aduk rata menggunakan tangan. Lalu taburkan dengan tepung maizena dan aduk kembali. Setelah itu siapkan tepung terigu di wadah terpisah.\", \"Menggoreng ayam, siapkan ayam yg sudah di marinasi, siapkan tepung terigu dengan wadah terpisah, panaskan minyak dan pastikan minyak sudah panas, lalu balurkan tipis ayam dengan tepung terigu lalu goreng hingga benar2 matang dengan api kecil.\", \"Siapkan bumbu teriyaki, iris tipis bawang bombay dan jahe lalu siapkan wajan dan panaskan light soya sebagai bahan dasar teriyaki di dalam wajan, campurkan sedikit dark soya untuk memberi warna, masukan irisan bawang bombay dan jahe, masukan sake/mirin secukupnya, lalu beri gula/madu hingga sedikit manis. Masak hingga mendidih, bumbui dengan garam, lada secukupnya, diamkan dalam api kecil.\", \"Membuat mix vegetables, potong semua bahan sayuran, chop halus bawang putih, panaskan pan, beri sedikit minyak dan masukan bawang putih, tumis hingga wangi lalu masukan semua bahan sayuran termasuk cabai, aduk sebentar lalu beri air sedikit agar sayuran matang, masak sayuran hingga matang, lalu bumbui dengan kecap ikan. Berikan tepung maizena yang sudah di campur dengan air sebagai pengental, harus dalam keadaan panas agar tidak menggumpal dan harus sambil diaduk. Lalu berikan minyak wijen\", \"Mencampur ayam dengan bumbu teriyaki, setelah ayam matang, masukan ke dalam bumbu teriyaki dan biarkan kira2 2 menit agar bumbu meresap, lalu angkat ayam dan panaskan kembali wajan baru, beri bumbu teriyaki sedikit dan tumis ayam dengan bumbu, lalu angkat\", \"Siapkan bowl yang sudah berisi nasi, tambakan sayuran yang sudah di buat lalu tambahkan chicken teriyaki, untuk garnish saya menambahkan biji wijen dan togarashi, jika tidak ada bisa dengan bubuk cabai apapun.\", \"Voila... selesai sudah pembuatan chicken teriyaki rice bowl.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1484, 2, 'Chicken Steak', 'Resep praktis Chicken Steak yang bisa dicoba di rumah.', '[\"Bahan Steak\", \"bahan A\", \"1/2 kg daging ayam (bagian dada di filet tipis tipis)\", \"1 sdt merica bubuk\", \"1 sdm saos tiram (apa aja boleh bagusnya yang kental)\", \"1/2 sdt garam\", \"1/2 sdt penyedap rasa (me, totole)\", \"bahan B\", \"8 sdm tepung cakra\", \"3 sdm tepung maizena\", \"2 butir telur\", \"Bahan Kuah Steak\", \"beberapa potong tulang ayam\", \"1 1/2 ltr air\", \"1/2 buah bawang bombay besar/ 1 buah ukuran kecil\", \"2 sdm kecap inggris\", \"2 sdm saos tomat\", \"3 sdm kecap manis\", \"secukupnya garam\", \"secukupnya penyedap rasa\", \"3 sdm peres tepung maizena\", \"Bahan Pelengkap\", \"1/2 kg kentang goreng\", \"1/2 kg wortel rebus\", \"1/4 kg buncis rebus\"]', '[\"Campur bahan A dalam wadah (piring saja) kemudian masukkan dalam freezer 30-60 menit\", \"Siapkan 3 buah wadah, wadah pertama isi dengan 5 sdm tepung cakra, wadah kedua isi dengan 2 telur kemudian kocok, wadah ketiga isi dengan 3 sdm tepung cakra campur dengan 3 sdm tepung maizena\", \"Keluarkan ayam dri freezer, sambil memanaskan minyak (api sedang)\", \"Celupkan ayam dalam wadah pertama, kemudian celup di adonan kedua, kemudian ke adonan ke tiga lalu goreng... (lakukan pada smua ayam)\", \"Untuk kuah steak, cincang bawang bombany kemudian tumis dengan sedikit minyak angkat dan sisihkan\", \"Panaskan 1 1/2 ltr air kemudian masukkan potongan tulang sebagai kaldu sampai air sedikit berkurang dan sudah mendidih, kemudian masukkan bawang bombay yang sudah ditumis...\", \"Tambahkan kecap inggris, saos tomat, kecap manis, garam dan penyedap.. (test rasa) bila sudah sesuai masukkan tepung maizena yang sudah di larutkan terlebih dahulu dengan air biasa, angkat dan sisihkan\", \"Pelengkap lainnya gampang kan ya... Kemudian sajikan... 😊😊😊 gampang kok bu ibu.... 😘😘😘 have a nice cook day...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1485, 2, 'Terong ayam balado', 'Resep praktis Terong ayam balado yang bisa dicoba di rumah.', '[\"250 gr ayam\", \"3 bh terong ungu\", \"Bahan yg dihaluskan :\", \"7 siung bawang merah\", \"4 siung bawang putih\", \"9 bh cabe merah\", \"3 bh tomat kecil\", \"1 bks masako ayam\", \"secukupnya Gula pasir\"]', '[\"Bersihkan ayam dan lumuri dgn garam\", \"Kupas terong lalu potong2 sesuai selera\", \"Goreng ayam dan terong hingga kering\", \"Haluskan bawang merah, bawang putih, cabe dan tomat\", \"Lalu tumis hingga harum dan tambahkan air sedikit. Tambahkan masako dan gula\", \"Masukan ayam dan terong aduk hingga rata dan airnya habis\", \"Koreksi rasa dan masakan siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1486, 4, 'Ayam balado...', 'Buat Ayam balado... yang nikmat dengan langkah-langkah mudah ini.', '[\"6 potong ayam\", \"1/2 ons cabe merah\", \"5 butir bawang merah\", \"1 buah tomat merah\", \"secukupnya Garam\"]', '[\"Rebus ayam dan garam sebentar, lalu goreng kering\", \"Uleg dgn ulekan ya cien...😊cabe,bawang merah, tomat,garam kasar saja, atau pecah pecah\", \"Tumis dalam minyak panas yg cukup byk, atau sambel menggenang khas restoran padang😁\", \"Setelah harum masukkan ayam, aduk sebentar....siap di sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1487, 2, 'Asam pedas ayam batang kemumu', 'Resep praktis Asam pedas ayam batang kemumu yang bisa dicoba di rumah.', '[\"I kg ayam\", \"5 batang kemumu\", \"I00 gram cabe merah\", \"50 gram cabe rawit\", \"5 siung bawang merah\", \"4 siung bawang putih\", \"1 ruas jahe\", \"2 ruas lengkuas\", \"1 ruas kunyit\", \"4 lembar daun salam\", \"3 butir kemiri\", \"3 lembar daun jeruk\", \"1 lembar daun kunyit\", \"1 btg serai geprek\"]', '[\"Ungkep ayam lebih kurang 5 menit. Angkat dan tiriskan\", \"Potong batang kemumu cuci bersih lalu rebus sekitar 3 menit beri sedikit garam dan 1 keping asam kandis.. angkat tiriskan\", \"Blender cabe merah, cabe rawit, baput, bamer, jahe, kunyit, kemiri sampai halus.\", \"Tumis bumbu halus masukkan sedikit air aduk hingga 3 menit\", \"Masukkan ayam masak sekitar 20 menit lalu masukkan kemumu. Masak lagi kurleb 15 menit\", \"Koreksi rasa dan angkt.. sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1488, 4, 'Ayam goreng mentega', 'Hidangan ayam lezat: Ayam goreng mentega untuk keluarga tercinta.', '[\"1 kg ayam potong 12\", \"3 biji bombay\", \"8 siung bawang putih\", \"1,5 ons margarin\", \"Merica\", \"10 sdm Kecap manis\", \"secukupnya Minyak sayur\"]', '[\"Rebus ayam dgn garam sebentar. Lalu goreng\", \"Panaskan minyak sayur dan margarin\", \"Masukkan bawang putih yg dicincang halus dan sedikit bombay yg sudah dipotong tipis. Tumis sampai harum\", \"Masukkan kecap aduk hingga agak mengkaramel\", \"Terakhir masukkan sisa bombay, merica, dan ayam goreng\", \"Aduk sampai rata dan bombay layu\", \"Siap dihidangkan\", \"Panas lbh nikmat....\", \"Selamat mencoba...semoga bermanfaat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1489, 3, 'Hainan Chicken - Ayam Rebus Hainan - Phak Cam Kee', 'Hainan Chicken - Ayam Rebus Hainan - Phak Cam Kee dengan bumbu meresap sempurna.', '[\"1 ekor ayam (baiknya ayam kampung, tp broiler pun oke)\", \"Secukupnya Air utk merebus ayam (ayam hrs terendam)\", \"Secukupnya air es + es batu utk merendam ayam\", \"Bumbu2:\", \"2 sdm garam\", \"5 bh daun bawang, (pakai semua batang dan daunnya)\", \"5-6 cm jahe, kupas, geprek\", \"Bumbu siram (aduk jadi satu):\", \"3 sdm minyak wijen\", \"3 sdm kecap asin (sy cap angsa)\", \"Bahan taburan:\", \"8 siung bawang putih cincang\", \"5 cm jahe, kupas, potong korek api\", \"3 sdm minyak wijen\", \"Tambahan: secukupnya daun ketumbar, cuci bersih\"]', '[\"Ayam dibuang kepala & kakinya. Biarkan bulat utuh, pastikan bulu2 halus sdh tdk ada.\", \"Beri perasan jeruk nipis/cuka seluruh bagian ayam supaya hilang bau anyir dan lendir nya. Diamkan beberapa menit, bilas.\", \"Balur ayam dgn 2 sdm garam ke semua bagian, kemudian bilas kembali ayam.\", \"Masukkan jahe geprek dan daun bawang ke dalam rongga ayam. Didihkan air, masukkan ayam ke air rebusan sampai ayam terendam seluruhnya.\", \"Rebus ayam ±30 menit, angkat ayam. Di wadah berisi air es, segera masukkan ayam ke dalamnya selama ± 5 menit\", \"Keluarkan ayam dr air es, lamgsung masukkan lagi ayam ke kuah panas, 5 menit kemudian, pindahkan lagi ke air es, biarkan ayam dingin (tujuannya spy kulit ayam bagus dan kenyal)\", \"Buat siraman: campur jadi satu minyak wijen dan kecap asin\", \"Buat taburan: goreng jahe dan bawang putih dgn minyak wijen sampai kekuningan, angkat.\", \"Potong2 ayam (kalau perlu lepaskan dr tulangnya), tata di piring, beri bumbu siraman, dan taburan bawang putih + jahe.\", \"Beri daun ketumbar. Hidangkan\", \"Note: Lebih enak jika dihidangkan dengan nasi hainam, yang bisa dibuat dr sisa kuah, gunakan kuah utk aron nasi, tambahkan garam dan minyak wijen\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1490, 4, 'Mie ayam home made', 'Sajian Mie ayam home made yang praktis dan lezat untuk dinikmati bersama.', '[\"1 dada daging ayam\", \"1 bungkus mie keriting (rebus)\", \"Secukupnya sawi hijau (rebus)\", \"Kecap manis\", \"Saos\", \"Daun bawang\", \"Garam\", \"Gula\", \"🍰 Bumbu Ayam\", \"4 siung bamer\", \"3 siung baput\", \"1 buah kemiri\", \"Kunyit\", \"Jahe\", \"Merica\", \"Garam\", \"secukupnya Lengkuas\", \"1 batang sereh\", \"1 buah daun salam\", \"🍰 Bumbu Kuah\", \"Secukupnya air\", \"2 siung baput geprek\", \"Kaldu ayam\", \"Lada bubuk\", \"🍰 Bumbu Minyak\", \"Kulit ayam\", \"2 siung baput\", \"Secukupnya minyak\"]', '[\"Rebus daging ayam setengah matang, suwir suwir\", \"🍰 Bumbu Ayam\", \"Haluskan semua bumbu ayam, kecuali lengkuas, salam dan sereh\", \"Tumis sampai harum. Masukkan lengkuas, daun salam, sereh. Tambahkan garam, gula, dan air (agak banyak ya)\", \"Masukkan ayam yg sudah di suwir suwir. Tambahkan kecap manis. Tes rasa. Sisihkan\", \"🍰 Bumbu minyak\", \"Masak kulit ayam sampai kering dengan minyak. Masukkan baput geprek sampai matang. Sisihkan\", \"🍰 Bumbu Kuah\", \"Rebus dengan air sampai matang. Tes rasa\", \"🍰 Penyelesaian\", \"Tuang bumbu minyak kedalam mangkok, tambahkan mie, sawi dan ayam. Jangan lupa di kasih kuah. Topping daun bawang, kecap manis, dan saos\", \"Selamat menikmati\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1491, 4, 'Chicken street food ala shihlin', 'Sajian Chicken street food ala shihlin yang praktis dan lezat untuk dinikmati bersama.', '[\"1/2 kg dada ayam fillet\", \"1 butir telur ayam\", \"Minyak goreng\", \"Bahan marinasi :\", \"2 siung bawang putih\", \"1 sdt merica\", \"1/2 sdt garam\", \"Bahan pelapis :\", \"1 cup tepung terigu\", \"1 cup tepung tapioka\", \"Secukupnya kaldu ayam bubuk\", \"Secukupnya garam\", \"Bubuk taburan :\", \"Secukupnya cabe bubuk (saya pakai merk aida)\", \"Secukupnya kaldu ayam (saya pakai royco)\", \"Boleh tambah bubuk rumput laut, barbeque,keju atau bubuk lainnya\"]', '[\"Fillet tipis dada ayam. Pukul2 dengan ulekan agar makin tipis tp jangan sampai hancur.\", \"Haluskan bumbu marinasi. Lumuri ke dada ayam fillet yang sudah tipis. Diamkan selama 5 menit\", \"Campur semua bahan pelapis hingga merata\", \"Lapis dada ayam fillet yang sudah di marinasi ke telur yang sudah dikocok, lalu ke campuran bahan pelapis\", \"Goreng deep fry diminyak panas dengan api kecil. Goreng hingga kuning keemasan\", \"Tiriskan dan taburi kaldu ayam bubuk secukupnya saja supaya ada rasa gurih dan cabe bubuk nya sesuai selera tingkat kepedasannya. Lalu putong kecil2 dengan pisau atau gunting bersih. Siap di sajikan 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1492, 4, 'Ayam Geprek Terasi Makban', 'Resep praktis Ayam Geprek Terasi Makban yang bisa dicoba di rumah.', '[\"250 gr dada ayam fillet\", \"Secukupnya tepung serbaguna\", \"Bumbu Sambal:\", \"1 siung bawang putih\", \"1 buah cabe merah besar\", \"Secukupnya cabe rawit (banyaknya diseauaikan dengan selera)\", \"Sejumput kaldu bubuk\", \"1/2 sdt Terasi Udang Makban\"]', '[\"Celupkan ayam kedalam adonan basah tepung bumbu, lalu lumuri dengan tepung bumbu, ulangi hingga 2-3x.\", \"Panaskan minyak, goreng ayam hingga coklat keemasan, tiriskan.\", \"Uleg semua bahan sambal menjadi satu.\", \"Geprek ayam goreng tepung dengan sambal.\", \"Ayam geprek siap disajikan, selamat menikmati.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1493, 4, 'Ayam filet kriukk.', 'Ayam filet kriukk. dengan bumbu meresap sempurna.', '[\"1 belah ayam bagian dada ukuran sedang\", \"1 butir telur\", \"1 bungkus tepung bumbu (me : sasa crispy)\", \"2 sdm tepung terigu\", \"2 sdm maizena (bagi 2 untk adonan basah & kering)\", \"seujung sendok teh baking powder\", \"minyak untuk menggoreng\", \"air\"]', '[\"Cuci bersih ayam.. iris tipis tipis..\", \"Adonan basah : campur 4 sdm tepung bumbu instan, telur, baking powder, 1sdm maizena. beri sedikit air agar tepung tdk menggumpal.\", \"Masukan ayam ke dalam adodan basah. diamkan dlm kulkas minimal 15 menitan.\", \"Adonan kering : campur sisa tepung bumbu instan.. 2 sdm terigu, 1 sdm maizena, baking powder. di tahap ini saya kasih bubuk cabe kobe level 30 biar pedes ayamnya..\", \"Panaskan minyak. sambil menunggu minyak panas, celupkan satu persatu ayam ke dalam adonan kering. tekan tekan agar tepung menempel.\", \"Goreng ayam dalam minyak yg panass dan api kecil. sekali kali di balik biar ga gosong.\", \"Tunggu sampe berwarna kecoklatan... angkattt...\", \"Kalo adonan keringnya kurang.. bisa ditambah tepung terigu di kasih sedikit garam / penyedap.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1494, 4, 'Soto Ayam Ekonomis', 'Resep Soto Ayam Ekonomis yang lezat dan mudah dibuat di rumah.', '[\"50 gr tulang ayam (kalo bisa punggung)\", \"200 gr daging ayam\", \"5 lembar daun jeruk\", \"2 lembar daun salam\", \"2 btg sereh (geprek)\", \"1 ruas jari lengkuas (geprek)\", \"3 cm jahe (geprek)\", \"2000 ml air\", \"Haluskan\", \"15 bawang merah\", \"6 bawang putih\", \"2 sdt ketumbar\", \"3 cm jahe\", \"2 butir kemiri (sangrai)\", \"Secukupnya garam\", \"Secukupnya lada putih\", \"Pelengkap\", \"4 butir telur rebus\", \"Secukupnya tauge (boleh di rebus dulu atau tidak)\", \"Secukupnya kol (iris tipis)\", \"Secukupnya daun bawang\", \"Secukupnya bawang goreng\", \"Secukupnya bihun (seduh)\", \"Secukupnya jeruk nipis\"]', '[\"Rebus daging dan tulang didalam air. Buang kotoran yang ada pada rebusan kaldu. Jika ayam sudah matang,angkat lalu suwir2.\", \"Masukan jahe geprek, lengkuas,daun jeruk,daun salam,sereh pada air kaldu. Rebus sampai mendidih,sisihkan.\", \"Tumis dengan sedikit minyak bumbu halus sampai wangi. Angkat dan masukan ke dalam kaldu rebusan tulang ayam\", \"Didihkan kembali air kaldu yg sudah dicampur bumbu halus. Tambahkan garam dan lada. Jika suka boleh ditambah air jeruk nipis\", \"Tata pelengkap di mangkuk dan siramkan kuah sotonya,sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1495, 3, 'Kungpao chicken', 'Resep praktis Kungpao chicken yang bisa dicoba di rumah.', '[\"75 gr Dada ayam fillet\", \"2 siung Bawang putih\", \"secukupnya Bawang bombay\", \"secukupnya Paprika\", \"1 biji Cabe merah\", \"secukupnya Daun bawang\", \"1 sdm Saus tiram\", \"1 sdt Mushroom soy\", \"1 sdt Kecap manis\", \"1 sdm Saus tomat\", \"2 sdm Minyak wijen\", \"Lada\", \"Garam\", \"Gula\", \"Penyedap rasa\", \"Tepung kanji (pengental)\"]', '[\"Fillet dada ayam, lalu marinade dengan garam lada dan penyedap kurang lebih 10menit\", \"Lalu goreng ayam jangan terlalu garing, lalu tiriskan\", \"Potong kotak bombay, paprika dan cabe merah, daun bawang slice, bawang putih chop\", \"Tumis bawang putih dulu, lalu masukan bombay,paprika dan cabe merah\", \"Lalu tambah air, kemudian masukan saus tiram,kecap manis,mushroom soy,saus tomat lalu berok rasa\", \"Jika rasa sudah pas kentalkan dengan tepung kanji cair, lalu masukan ayam dan beri minyak wijen, selesai.\", \"Usahakan bahan2 tadi tidak terlalu lama di atas api, agar bahan2 fresh. Usahakan masak dengan cepat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1496, 2, 'Bubur Ayam wortel', 'Resep Bubur Ayam wortel ala rumahan yang dijamin menggugah selera.', '[\"4 sdm nasi yang sudah matang (aku pakai organik)\", \"2 sdm ayam cincang yang sudah direbus (aku pakai ayam kampung)\", \"1 buah wortel (ukuran sedang*serut)\", \"2 sdm kacang merah (sudah aku rebus sebelumnya)\", \"5 helai seledri\", \"2 sdm tahu sutra (aku pakai merk kong kee)\", \"1 buah cup kecil unsalted butter (pakai merk elle)\", \"250 ml kaldu ayam\", \"1/2 sdt evoo\"]', '[\"Masukan serutan wortel,tahu sutra dan ayam cincang ke air kaldu yang mendidih\", \"Haluskan nasi,seledri dan kacang merah (aku pakai blender dan teksturnya aku buat tidak terlalu lembut/agak kasar)\", \"Setelah rebusan tadi agak matang lalu masukan nasi yang dihaluskan bersama seledri dan kacang merah\", \"Setelah matang semua,matikan api lalu masukan unsalted butter nya\", \"Tuangkan sedikit di mangkuk makan bayi,kalo sudah hangat baru di masukan evoo nya (masukan evoo nya jangan dalam keadaan panas,nanti vitamin nya hilang. Jadi tunggu hangat dulu)😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1497, 4, 'Ayam Saos Mayo', 'Hidangan ayam lezat: Ayam Saos Mayo untuk keluarga tercinta.', '[\"1/4 kg ayam\", \"3 sdm saos sambal\", \"3 sdm saos mayo\", \"Bahan marinasi ayam :\", \"1 sdt garam\", \"2 bawang putih (haluskan)\", \"1 sdt merica\", \"1 sdt penyedap\", \"Bahan krispi :\", \"6 sdm tepung kanji\"]', '[\"Marinasi ayam dengan bumbu marinasi 15 menit\", \"Kemudian masukkan tepung kanji, campur-campur dengan ayam hingga rata, goreng hingga kecoklatan\", \"Tata ayam yang sudah matang dalam wadah, kemudian beri saos sambal dan mayonaise secukupnya\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1498, 3, 'Bakwan goreng ayam', 'Hidangan ayam lezat: Bakwan goreng ayam untuk keluarga tercinta.', '[\"100 gr dada ayam giling\", \"4 sdm tepung tapioka\", \"1 sdm tepung terigu\", \"2 sdt royco\", \"1 butir telur\"]', '[\"Campurkan semua bahan, lalu goreng dalam minyak panas sampai keemasan\", \"Bakwan goreng siap disantap, so simple 🤣\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1499, 3, 'Sayap ayam kemangi', 'Sayap ayam kemangi dengan bumbu meresap sempurna.', '[\"4 sayap ayam (potong jadi 2)\", \"1 ikat kemangi, petik daunnya\", \"Bumbu halus👇\", \"5 siung bawang merah\", \"2 siung bawang putih\", \"15 cabe rawit\", \"1 cabe merah besar\", \"1 tomat\", \"secukupnya Garam dan micin\"]', '[\"Rebus ayam smpe mateng bisa dibumbuin bisa tidak(me kasik bumbu ketumbar, bawang n gram)\", \"Goreng ayam smpe kering, setelah bumbu dihaluskan goreng smpe bau wangi,\", \"Masukan kemanginya lalu aymnya kasik sdikit air, tutup tunggu smpe meresap, cek rasa siap disajikan👌\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1500, 3, 'Chicken eggroll ala hokben', 'Nikmati kelezatan Chicken eggroll ala hokben dengan resep sederhana ini.', '[\"Bahan kulit:\", \"8 sdm tepung terigu (kurang lebih)\", \"1 buah telur (putih+kuningnya)\", \"2 sdm margarin\", \"1/2 sdt garam\", \"1/2 sdt gula\", \"secukupnya Air\", \"Bahan isi:\", \"1/4 kg daging ayam (tanpa tulang)\", \"1 buah putih telur\", \"2 siung bawang putih\", \"1 sdm tepung maizena\", \"1 sdt merica\", \"secukupnya Garam dan gula\"]', '[\"Panaskan margarin ke dalam teflon sampai cair. Tunggu dingin sebentar lalu masukkan ke wadah mangkok bersama bahan kulit yang lain. Kocok sampai halus, jangan terlalu encer/kental. Kalau keenceran bisa ditambah tepung\", \"Lap teflon bekas margarin dengan tisu lalu panaskan dengan api kecil\", \"Masukkan beberapa sendok adonan kulit ke teflon, putar -putar teflon sampai adonan merata (kayak bikin terang Bulan. Bikin setipis mungkin). Angkat apabila sudah matang. Disini saya bikin sampai 3 kulit dulu saja\", \"Blender semua bahan isi\", \"Letakkan kulit di atas plastik (saya pakai plastik biasa lalu disobek biar lebar).\", \"Letakkan beberapa sendok isi ke atas kulit lalu gulung. Ulangi sampai adonan isi habis.\", \"Kukus selama 10 menit dengan api kecil\", \"Angkat lalu potong-potong menyerong\", \"Balur dengan tepung terigu lalu goreng dengan api kecil.\", \"Siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1501, 3, 'Bakso Ayam ala Agnes', 'Sajian Bakso Ayam ala Agnes yang praktis dan lezat untuk dinikmati bersama.', '[\"1/2 kg dada ayam\", \"3 sdm tepung maizena (tidak munjung)\", \"4 siung bawang putih (goreng lalu haluskan)\", \"1 sdt penuh baking powder\", \"1/2 sdt baking soda\", \"1/2 sdt merica bubuk\", \"1/2 sdm gula pasir\", \"1 sdt kaldu bubuk\", \"1/2 sdm garam halus\", \"120 ml air es\", \"Bahan kuah :\", \"Secukupnya daun bawang dan sledri (dibiarkan utuh)\", \"1 sdt merica bubuk\", \"1 sdt kaldu bubuk\", \"4 siung bawang putih\", \"Sedikit pala\", \"1/2 sdm garam halus\", \"1 sdt gula pasir\", \"Tulang dada sisa yg dibuat bakso\", \"Pelengkap :\", \"Seledri (iris tipis)\", \"Bawang merah goreng (aku beli jadi)\", \"Mie jagung (sisa bikin nugget kemarin)\"]', '[\"Pisahkan daging dan tulang ayam. Cincang daging ayam sampai halus, beri sedikit demi sedikit air es jangan banyak2.\", \"Dalam wadah lain, jadikan satu bumbu yg sudah disiapkan dan beri tepung maizena. Kemudian larutkan dengan sisa air es tadi.\", \"Campur jadi satu daging yg sudah dihaluskan dan juga bumbu yg sudah diberi air es. Uleni hingga kalis.\", \"Banting2 adonan agar nantinya bakso elastis.\", \"Jika sudah, pindah ke wadah kecil dan beri tutup plastik kemudian masukkan ke freezer kurleb 40 menit.\", \"Ambil adonan dalam freezer kemudian siapkan panci untuk merebus adonan pentol. Cukup setengah panci saja jangan banyak2 airnya. Beri 1 sdm garam halus agar rasa pentol tetap terjaga. Tunggu hingga air mendidih.\", \"Jangan lupa juga beri 1 sdm minyak goreng di adonan, dan juga lumasi tangan dengan minyak goreng agar tidak lengket.\", \"Kalau sudah mendidih, kecilkan api (lebih bagus lagi api dimatikan dulu) lalu bentuk bulat2 adonan sesuai selera. Tunggu hingga mengapung semua, jika sudah mengapung tandanya sudah matang.\", \"Sekarang bikin kuahnya, untuk air rebusan pentol tadi jangan dibuang bisa untuk kuah bakso. Haluskan bawang putih dan pala kemudian tumis sebentar. Kemudian masukkan ke air mendidih sisa rebusan tadi.\", \"Masukkan garam dan gula pasir. Kemudian masukkan utuh daun bawang dan sledri, kaldu bubuk 1 sdt, dan terakhir masukkan tulangnya. Tunggu hingga mendidih.\", \"Tata pentol di mangkok, beri mie, sledri, bawang merah goreng, dan bisa kasih apa aja sesuai selera. Berhubung aku adanya itu jadi ya ala kadarnya😂 Oh iyaa kalo sambalnya aku rebus cabe rawit sama bawang putih kemudian dikasih garam sedikit jadi deh. Happy cooking😘🙏\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(1502, 4, 'Chicken Fajitas', 'Cara membuat Chicken Fajitas yang enak dan praktis untuk keluarga.', '[\"3 buah sayap ayam (lebih baik pakai chicken fillet)\", \"1/2 buah bawang bombay\", \"1 buah paprika merah (suka-suka aja, pakai warna lain gak masala\", \"Bahan rendaman :\", \"1/2 buah jeruk nipis (ambil airnya)\", \"2 sdm minyak goreng/olive oil\", \"2 siung bawang putih, memarkan dan cincang halus\", \"1/2 sdt jintan bubuk\", \"1/2 sdt bubuk kari\", \"1/2 sdt garam\", \"1 sdt bubuk cabe (boleh tambah cabe rawit kalau suka pedas)\", \"1/2 sdt paprika bubuk (optional)\"]', '[\"Campur semua bumbu rendaman.\", \"Masukkan ayam ke dalam bumbu rendaman sambil diremas-remas agar bumbu meresap. Biarkan selama 15-30 menit. Bisa juga direndam semalaman simpan di kulkas.\", \"Iris tipis paprika dan bawang bombay.\", \"Panaskan teflon dan beri sedikit minyak.\", \"Panggang ayam menggunakan teflon sambil oleskan bumbu yang tersisa. Jangan terlalu lama memanggang ayam agar daging ayam masih juicy. Setelah matang, angkat ayam dan tutup agar daging tidak kering.\", \"Tumis sisa bumbu rendaman ayam bersama bawang bombay hingga kecoklatan.\", \"Masukkan paprika dan tumis hingga paprika agak layu. Jangan menumis terlalu lama agar tekstur paprika masih segar.\", \"Iris-iris daging ayam dan sajikan bersama tumisan paprika, salad, tortila/nasi hangat.\", \"Selamat mencoba :)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1503, 3, 'Egg Salted Chicken', 'Resep praktis Egg Salted Chicken yang bisa dicoba di rumah.', '[\"250 gram daging ayam\", \"4 kuning telur bebek asin\", \"250-350 ml susu\", \"1 butir telur ayam\", \"secukupnya garam\", \"2-3 siung bawang putih\", \"secukupnya merica\", \"350 gram tepung maizena\", \"secukupnya minyak goreng\", \"secukupnya salam koja\", \"2-3 buah cabe keriting merah\"]', '[\"Hancurkan kuning telur hingga halus, sisihkan\", \"Potong daging ayam yang telah disiangi dadu besar untuk bikin chicken corn, sisihkan\", \"Kocok lepas telur ayam, beri garam dan merica secukupnya-sisihkan, lalukan yang sama pada tepung maizena dan ayam, sisihkan\", \"Baluri rata ayam berbumbu pada maizena berbumbu hingga rata lalu masukan dalam kocokan telur berbumbu, kemudian celup kembali ke maizena berbumbu hingga rata, goreng hingga keeemasan, angkat dan tiriskan\", \"Cincang atau haluskan bawang putih, tumis hingga harum, masukan kuning telur asin halus, tumis hingga berbusa, masukan daun salam koja dan irisan cabe keriting lalu tuangi sedikit demi sedikit susu hingga sebati, matikan api jika telah meletup\", \"Sisihkan sebagian besar saus kuning telur asin, saus yang tersisa di tumis bersama chicken corn, hingga rata, hidangkan bersama nasi dan tuangi saus kuning telur asin lagi secukupnya😋selamat menikmatiiiii\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1504, 3, 'Sate Ayam Ponorogo', 'Sate Ayam Ponorogo - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"400 gram daging ayam\", \"1 1/2 buah gula merah\", \"4 siung bawang putih\", \"4 siung bawang merah\", \"1 sendok makan jintan\", \"1/2 sendok teh merica\", \"1 ruas lengkuas\", \"1 sendok makan ketumbar\", \"4 butir kemiri\", \"1/4 sendok teh terasi bakar\", \"4 sendok makan selai kacang tanah\", \"secukupnya garam\", \"7 sendok makan air hangat\"]', '[\"Fillet daging ayam sesuai selera, sisihkan\", \"Haluskan dan campur bawang merah, bawang putih, kemiri sangrai, ketumbar sangrai, jintan sangrai, garam 1/2sendok teh dan gula merah, rendam daging ayam sambil dipijat hehhee😁ungkep di Teflon sampai bumbu mengering pada ayam sampai agak terpanggang\", \"Campur selai kacang, air hangat dan terasi bakar, tambahkan garam 1sendok teh, aduk hingga sebati😋selamat menikmatiiiii\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1505, 3, 'Sup ayam kesukaan Ade', 'Sajian Sup ayam kesukaan Ade yang praktis dan lezat untuk dinikmati bersama.', '[\"300 grm ayam cincang\", \"1 bks sayur saop kmplit\", \"secukupnya Lada kasar\", \"4 siung bawang merah\", \"4 siung bawang putih\", \"3 butir kemiri\", \"Royco ayam sckpnya\", \"secukupnya Minyak goreng\"]', '[\"Haluskan bumbu yg sudah d siapkan\", \"Pnas kn minyak goreng masukan bumbu yg sudah d haluskan tumis sampai harum\", \"Masukan air secukupnya jika air sudah mendidih masukkan ayam cincang nya jika sudah setengah matang masukkan sayuran dan masukan roico\", \"Kalau sudah matang siap di sajikan\", \"Selamat masak2 ibu2\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1506, 2, 'Ayam Pedas Bumbu Kuning', 'Cara membuat Ayam Pedas Bumbu Kuning yang enak dan praktis untuk keluarga.', '[\"1 kg ayam\", \"15 cabe rawit merah\", \"5 cabe merah kriting\", \"5 siung bawang merah\", \"1 siung bawang putih\", \"secukupnya Lada bubuk\", \"2 butir kemiri\", \"secukupnya Gula merah\", \"secukupnya Garam\", \"Bumbu Penyedap rasa ayam\", \"2 batang sereh\", \"1 ruas jari kunyit\", \"2 lembar daun salam\", \"Air\"]', '[\"Cuci ayam hingga bersih,,potong menjadi 10/12 bagian atau sesuai kebutuhan\", \"Haluskan semua bumbu menjadi satu,kecuali daun salam dan sereh cukup di geprek biar pipih\", \"Panaskan minyak dan tumis bumbu sampai harum dan setengah matang\", \"Masukan ayam aduk biar tercampur dengan bumbu, tambahkan air secukupnya,\", \"Tunggu sampai air mendidih sambil di aduk hingga bumbu meresap semua (15-20 menit) dan siap untuk di hidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1507, 2, 'Opor ayam dan telur', 'Buat Opor ayam dan telur yang nikmat dengan langkah-langkah mudah ini.', '[\"1 ekor Ayam\", \"8 butir Telur ayam\", \"10 siung Bawang merah\", \"2 siung Bawang putih\", \"2 ruas Kunyit\", \"3 buah kemiri\", \"1 st lada bubuk\", \"3 lembar daun jeruk\", \"3 lembar daun salam\", \"1 ruas lengkuas (geprek)\", \"2 batang sereh (geprek)\", \"1 mangkuk santan kental\"]', '[\"Semua bumbu diblender atau diulek halus, setelah semua bumbu halus ditumis, sampai harum masukkan, sereh, salam, lengkuas, dan daun jeruk,\", \"Bumbu matang masukan ayam dan digodok hingga matang\", \"Telur direbus dan digoreng,,\", \"Setelah ayam empuk, masukkan santan aduk jangan sampai pecah santannya dan masukan telur yg sudah digoreng, setelah mendidih matikan dan taburi bawang goreng,,, (selamat mencoba😍😍)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1508, 4, 'Ayam Ungkep Kuning', 'Ayam Ungkep Kuning dengan bumbu meresap sempurna.', '[\"1/2 ekor ayam\", \"5 siung bawang merah\", \"5 siung bawang putih\", \"5 cm kunyit\", \"1 sdt ketumbar\", \"1 sdt lada\", \"4 butir kemiri\", \"1 cm jahe\", \"5 cm lengkuas\", \"2 lembar daun jeruk\", \"2 lembar daun salam\", \"1 batang sereh\", \"2 sdt garam\", \"1 sdt gula\", \"Sekitar 500 ml air\"]', '[\"Haluskan bawang merah, bawang putih, ketumbar, lada, kemiri, kunyit, jahe, dan lengkuas\", \"Setelah ayam dibersihkan dan dipotong-potong, tata dalam panci, masukkan bumbu halus, tambahkan air, madak dengan api sedang\", \"Tambahkan daun jeruk, daun salam, dan sereh\", \"Sekitar 15 menit kemudian, tambahkan gula dan garam\", \"Masak lagi sekitar 10 menitan, jika air telah banyak berkurang, matikan. Hilangkan uap panasnya, tata dalam wadah, dan simpan dalam kulkas\", \"Siap untuk digoreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1509, 4, 'Ayam bekakak', 'Resep praktis Ayam bekakak yang bisa dicoba di rumah.', '[\"1 ekor ayam\", \"4 lmbar  daun salam,2 batang sereh,lengkuas geprek,3 daun jeruk\", \"5 siung Bawang merah besar\", \"4 siung Bawang putih besar\", \"3 butir Kemiri\", \"1 sendok teh ketumbar\", \"1/2 sdt jinten\", \"1 ruas kunyit\", \"1 ruas jahe\", \"secukupnya Gula merah\", \"secukupnya Air  untuk ungkep\", \"Secukupnya Garam\", \"secukupnya Kecap manis\"]', '[\"Cuci bersih ayam rendam dengan air garam dan ulekan bawang putih dan kunyit slma 45 mnit\", \"Ulek smua bumbu sampe halus lalu tumis sbntar...\", \"Masukkan ayam beri air smp ayam sdikit terendam ungkwp ayam..masukn garam gula merah dan kecap..\", \"Tunggu sampe air asat dan bumbu meresap dengn mnggunakan api sedang\", \"Ayam siao dipanggang mnggunakan panggangn bs dikompor pke alat panggangn yg muter..ato di atas bara lebih sedap\", \"Sewaktu dipanggang oleskan kecap manis yg sudah dicampur dengn sdikit bumbu ungkep td...\", \"Setelah matang kcoklatan angkat, lengkapi dengn sambelTerasi dan lalapan (timun,kol,kemangi)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1510, 4, 'Ayam asep ala rawid kitchen', 'Buat Ayam asep ala rawid kitchen yang nikmat dengan langkah-langkah mudah ini.', '[\"1 ekor ayam potong sesuai selera\", \"Bumbu halus:\", \"10 cabe merah besar\", \"10 cabe rawit (selera)\", \"6 siung bawang putih\", \"1 sdt merica\", \"1/2 sdm petis madura (hitam)\", \"2 sdm kecap manis\", \"Gula pasir, garam, penyedap rasa\"]', '[\"Cuci bersih ayam, lumuri dg garam, diamkan sebentar, goreng smp matang\", \"Tumis bumbu halus, beri air sdkt, masukkan ayam aduk rata\", \"Koreksi rasa, masak hingga bumbu meresap\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1511, 2, 'Chicken Teriyaki Simple', 'Chicken Teriyaki Simple dengan bumbu meresap sempurna.', '[\"500 gr ayam dada fillet\", \"Bawang bombai\", \"2 siung bawang putih\", \"Daun bawang\", \"3 sdm Saus tiram\", \"1 sdm Kecap manis\", \"1 sdm kecap asin\", \"secukupnya Garam\", \"secukupnya Lada bubuk\", \"1 sdm minyak sayur\"]', '[\"Cuci ayam fillet, lalu potong dadu atau sesuai selera.\", \"Campurkan saus tiram, kecap asin, kecap manis, dan lada bubuk. Lalu rendam ayam.\", \"Simpan ayam di kulkas selama 20 menit.\", \"Potong halus bawang bombai, bawang putih, dan daun bawang.\", \"Panaskan minyak, tumis bawang mombai dan bawang putih hingga harum. Lalu masukkan rendaman ayam.\", \"Tambahkan garam dan daun bawang. Tunggu hingga matang. Siap disajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1512, 2, 'Ayam goreng pedas ala korea', 'Resep Ayam goreng pedas ala korea ala rumahan yang dijamin menggugah selera.', '[\"Bahan ayam goreng :\", \"5 potong ayam\", \"1 bungkus tepung sajiku\", \"1 buah telur\", \"Bahan saus:\", \"3 sdm saus barbeque (bisa dibeli di indomar*t)\", \"3 sdm saos tomat\", \"4 sdm sambal abc\", \"1 sdm saus tiram\", \"2 sdm madu\", \"1 sdt gula\", \"1 sdt garam\", \"1/2 sdt lada\", \"Boncabe secukupnya sesuai selera\", \"1 sdm margarin\"]', '[\"Masukkan ayam ke dalam kocokan telur, lalu balurkan ke tepung, ulangi lagi masukkan ke telur, lalu balur ke tepung\", \"Goreng dengan api kecil sampai matang kecoklatan\", \"Masukkan semua bahan saus kecuali margarin ke sebuah mangkok, aduk sampai tercampur\", \"Panaskan margarin sampai cair. Masukkan saus,aduk-aduk beberapa menit,tambahkan sedikit air\", \"Masukkan ayam yang sudah digoreng. Masak sampai saus menyusut dan meresap\", \"Ayam goreng pedas ala korea siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1513, 2, 'Sayap ayam extra pedas', 'Sayap ayam extra pedas - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"4 sayap ayam (dipisah bagian pangkal dan sayapnya, gw gatau namanya apa 😂)\", \"±1,5 bungkus  tepung ayam kobe\", \"1-2 telur ayam (apabila telurnya besar cukup 1saja)\", \"± 3-4 sdm  tepung kanji (dicampur dengan tepung kobe agar ayam renyah)\", \"secukupnya royco rasa ayam\", \"secukupnya lada bubuk\", \"secukupnya garam\", \"± 2sdm  gula\", \"± 5-7 sdm  saos sasa extra pedas\", \"± 4-5 sdm  saos bangkok indofood\", \"1 bawang merah\", \"1 bawang putih\", \"± 5-7  cabai rawit (sesuai selera)\", \"± 1 sdm  saos tiram (opsional kalo saya pake)\", \"secukupnya  air (saya memakai air secangkir)\", \"secukupnya minyak goreng\"]', '[\"Campurkan tepung kobe dengan tepung kanji, kemudian berikan lada bubuk sedikit\", \"Kemudian bagi tepung diwadah terpisah menjadi 2, pecahkan telur diwadah yang berbeda dan kocok sampai rata\", \"Balurkan sayap ayam ke tepung, kemudian tekan-tekan dan lanjutkan hingga sayap habis terbalur oleh tepung semua, kemudian balurkan ayam yang sudah diberi tepung ke adonan telur (balurkan telur hingga rata) lakukan satu persatu kemudian dibalurkan kembali ke tepung yang masih belum digunakan (lakukan hingga seluruh ayam sudah diberikan telur dan tepung, jangan lupa ayam ditekan2 pada adonan tepung)\", \"Goreng ayam hingga keemasan\", \"Cincang/uleg bawang merah, bawang putih, cabai (kalo saya diuleg), kemudian siapkan penggorengan dg sedikit minyak kira2 ±1/2 sdm dengan api kecil, tumis bawang dan cabau sampai harum, kemudian masukkan air, saos extra pedas, saos bangkok, aduk hingga merata (boleh juga ditambahkan saos tiram), masukkan garam, gula, lada dan royco (sebaiknya diicip dahulu apakah sudah pas), tunggu hingga air meletup2 dan sedikit berkurang kemudian masukkan ayam dan aduk hingga rata\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1514, 4, 'Gule Ayam', 'Resep Gule Ayam yang lezat dan mudah dibuat di rumah.', '[\"500 gram Ayam potong bersihkan\", \"2 lembar daun salam\", \"1 batang serai geprek\", \"3 cm kayu manis\", \"1/2 sdt jinten\", \"Secukupnya garam\", \"Secukupnya gula\", \"Secukupnya lada bubuk\", \"Secukupnya ketumbar\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"5 buah cabai rawit\", \"5 buah cabai keriting\", \"1 ruah jahe\", \"1 ruas kunyit\", \"3 butir kemiri\", \"1/2 air perasan jeruk nipi\", \"2 lembar daun jeruk\", \"5 biji cengkeh\"]', '[\"Bersihkan ayam potong lalu goreng setengah matang. Sisihkan\", \"Haluskan bumbu bawang merah, bawang putih, ketumbar, lada cengkeh, cabai rawit cabe keriting, kunyit, jahe dan kemiri.\", \"Tumis bumbu yang sudah dihaluskan hingga harum. Masukkan air lalu diamkan sampai mendidih\", \"Masukkan gula, garam, cengkeh, daun jeruk purut, serai dan air perasan jeruk nipis. Aduk aduk dan incipi rasa sesuai selera asin dan manisnya.\", \"Setelah dirasa bumbu sudah enak. Masukkan ayam yg sudah digoreng tadi. Diamkan dengan api kecil. Sesekali diaduk supaya bumbunya meresap dan merata. Tunggu 10 menit. Atau sampai bumbu mengental. Lalu Matikan kompor.\", \"Selesai, siap disajikan sebagai lauk. Selamat mencoba 😍 jangan lupa foto recooked nya yaa\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1515, 2, 'Ayam Jingkrak', 'Resep praktis Ayam Jingkrak yang bisa dicoba di rumah.', '[\"1/2 kg ayam\", \"1 buah Jeruk nipis\", \"1/2 sdt garam\", \"Bumbu halus:\", \"10 biji cabe merah keriting\", \"5 butir bawang merah\", \"2 siung bawang putih\", \"1 ruas laos\", \"1/2 ruas jahe\", \"1 ruas kunyit\", \"1 sdm ketumbar\", \"2 biji kemiri\", \"Pelengkap:\", \"2 batang serai geprek\", \"2 lembar daun jeruk\", \"1 lembar daun salam\", \"1 lembar daun kunyit\", \"2 sdm saori saus tiram\", \"2 sdm kecap manis\", \"1/2 sdt ladaku\"]', '[\"Potong ayang dan bersihkan lalu beri perasan jeruk nipis dan garam lalu diamkan 10 menit.\", \"Giling semua bumbu halus dan beri sedikit garam, lebih baik giling tangan pake cobek guys daripada blender. Tekstur nya jgn terlalu halus.\", \"Goreng ayam diminyak yg panas hingga mateng kecoklatan. Angkat dan sisihkan.\", \"Tumis bumbu halus dan tuangkan semua bumbu pelengkap, tumis hingga harum lalu masukkan gorengan ayam. Aduk hingga merata dan jika sudah merata matikan api. Dan siap disajikan.\", \"Selamat mencoba moms. Annyeong ❤ jangan lupa share recook nya ya 💋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1516, 4, 'Ayam kemangi bumbu kuning pedas', 'Resep Ayam kemangi bumbu kuning pedas ala rumahan yang dijamin menggugah selera.', '[\"500 gram ayam\", \"2 buah jeruk nipis (utk rendaman)\", \"Bumbu halus:\", \"12 buah cabai rawit\", \"1 buah cabai merah keriting\", \"1 siung bawang putih\", \"4 siung bawang merah\", \"2 butir kemiri\", \"3 cm kunyit\", \"Bumbu pelengkap:\", \"1 batang serai\", \"1 lembar daun salam\", \"1 lembar daun pandan (bisa skip)\", \"1 lembar daun kunyit (bisa skip)\", \"2 lembar daun jeruk\", \"1 buah tomat ukuran kecil\", \"Secukupnya kemangi\", \"Secukupnya garam-gula-penyedap\"]', '[\"Potong n cuci bersih ayam, rendam dgn perasan jeruk nipis slama 15 mnt, cuci bersih, sisihkan\", \"Cincang tomat, sisihkan. Geprek jahe n serai, sisihkan. Sangrai atau bakar kemiri di atas api kompor, sisihkan\", \"Haluskan cabai rawit-cabai keriting-duo bawang-kemiri-kunyit\", \"Panaskan sedikit minyak dlm wajan, tumis bumbu halus, tambahkan serai-tomat-daun salam kunyit pandan, aduk2 hingga wangi. Masukkan ayam, aduk sebentar, masukkan air\", \"Beri garam-gula-penyedap, setelah mendidih tambahkan daun kemangi, aduk sesekali, cek rasa, setelah air mngental angkat n siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1517, 3, 'Honey Butter Chicken', 'Nikmati kelezatan Honey Butter Chicken dengan resep sederhana ini.', '[\"Dada ayam fillet secukupnya. Potong dadu/memanjang\", \"Buttermilk secukupnya (susu cair+perasan jeruk nipis)\", \"secukupnya Lada+Garam\", \"Tepung bumbu serbaguna\", \"1 sdm Madu\", \"1 sdm Saus Tiram (bs diganti Kecap Asin)\", \"1 sdm Gula Pasir\", \"1/2 sdt Kecap Manis\", \"1 sdm Air\", \"1 siung Bawang Putih\", \"1 sdm Butter/Margarin\"]', '[\"Lumuri Ayam yg sudah dipotong dg sedikit Lada+Garam, rendam dlm Buttermilk ±15menit (boleh jg dimarinasi malam, masuk kulkas, pagi tinggal goreng)\", \"Goreng Ayam pakai Tepung Bumbu serbaguna sesuau petunjuk kemasan saja. Sisihkan\", \"Campur Madu+Saus Tiram+Gula Pasir+Kecap Manis+Air. Sisihkan\", \"Cincang bawang putih, tumis dg butter sampai wangi. Kemudian masukkan campuran saus madu, aduk sebentar\", \"Masukkan gorengan Ayam, aduk2 sampai saus menempel\", \"Sajikan, tabur potongan daun bawang+wijen (optional).\", \"Makan dg nasi hangat 💦💦\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1518, 2, 'Chicken Fire Wings Recheese', 'Nikmati kelezatan Chicken Fire Wings Recheese dengan resep sederhana ini.', '[\"7 Sayap Ayam (Potong Jadi 2)\", \"2 Bungkus Bumbu Serbaguna (Kalau aku pakai kobe)\", \"1 Sdm Margarin\", \"Bumbu Saos Fire :\", \"2 Siung Bawang Putih Cincang Halus\", \"5 Sdm Saos Tomat\", \"4 Sdm Saos Sambal\", \"3 Sdm Saos Barbeque (Aku Pakai Del Monte)\", \"1.5 Sdm Saos Tiram\", \"2 Sdm Madu\", \"2 Sdm Bon Cabe Lvl 10 (Kalau Suka Pedes bisa lvl 30)\", \"1 Sdm Kecap Manis\"]', '[\"Bersihkan Ayam lalu lumuri dengan lada bubuk dan jeruk nipis selama 1 jam.\", \"Lalu, beri tepung ke ayam dengan cara.. Larutkan sedikit bumbu ayam kobe ke air hangat ke dalam mangkok, dan sisa bumbu nya letaknya di mangkok yg lain. pertama ayam masukkan ke bumbu yg cair, setelah itu ke bumbu bubuk sambil di remas agar padat.\", \"Goreng Ayam ke dalam minyak panas sampai matang, berubah kecoklatan\", \"Lalu di tempat yg berbeda, tumis bawang putih dengan 1 Sdm Margarin sampai harum\", \"Lalu masukkan Saos Tomat, Saos Sambal, Saos Barbeque, Saos Tiram, Kecap Manis, Bon Cabe dan Madu.\", \"Aduk sampai matang dan meletup letup\", \"Ketika sudah matang, matikan kompor. masukkan ayam yg sudah di goreng tadi. aduk sampai rata.\", \"Siap Di Santap!\", \"Note : Aku memang gak bikin saos kejunya :\')\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1519, 2, 'Ceker Ayam Bumbu Balado~', 'Ceker Ayam Bumbu Balado~ - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"500 gr ceker ayam, cuci bersih\", \"1 batang serai, memarkan\", \"2 lembar daun salam\", \"1 cm lengkuas, memarkan\", \"1 buah tomat, belah 4 bagian\", \"1 sdt merica bubuk\", \"secukupnya Garam dan gula\", \"Minyak goreng utk menumis\", \"Air untuk merebus\", \"Bumbu halus:\", \"3 siung bawang putih\", \"4 butir bawang merah\", \"2 butir kemiri\", \"5 buah cabai merah (aku pakai cabai TW)\", \"2 buah cabai rawit (aku pkai sdkit krn tdk trlalu suka pedas)\"]', '[\"Pertama rebus ceker ayam yg sudah dibersihkan tadi, hingga empuk kurang lebih 10 menit. Angkat dan tiriskan.\", \"Tumis bumbu halus, masukkan serai, daun salam dan lengkuas hingga harum.\", \"Masukkan air, lalu masukkan ceker ayam.\", \"Tambahkan garam, merica dan gula secukupnya. Lalu masukkan tomat. Masak hingga bumbu meresap dan angkat.\", \"Ceker ayam bumbu balado siap disajikan~~\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1520, 4, 'Ayam RicaRica Kemangi', 'Resep Ayam RicaRica Kemangi yang lezat dan mudah dibuat di rumah.', '[\"1/2 kg paha ayam potong kecil\", \"Bumbu halus\", \"8 butir bawang merah\", \"6 siung bawang putih\", \"1 sdt terasi\", \"4 cabe merah\", \"2 cabe kecil(klo suka pedas ditambah lg)\", \"Garam secukupny\", \"secukupnya Gula\", \"2 butir kemiri\", \"Tambahan\", \"Kemangi\", \"Daun salam\", \"Daun jeruk\", \"1 batang sere digeprek\", \"1 ruas lengkuas digeprek\"]', '[\"Tumis bumbu halus masukan sere+daun jeruk+daun salam hingga wangi\", \"Masukan air 2 gelas\", \"Masukan daging ayam masak\", \"Setengah masak masukan kemangi.\", \"Lalu tunggu matang\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1521, 3, 'Ayam RicaRica Pedas', 'Ayam RicaRica Pedas dengan bumbu meresap sempurna.', '[\"1 ekor ayam\", \"1 jeruk nipis\", \"2 batang serai ambil putihnya iris\", \"5 daun jeruk diris kecilkecil\", \"bumbu halus (sy diblender)\", \"7 siung bawang merah\", \"5 siung bawang putih\", \"2 buah cabe keriting merah iris\", \"25 cabe rawit merah\", \"seruas jahe\", \"seruas kunyit\", \"secukupnya garam, gula, lada, air\"]', '[\"Cuci bersih ayam lalu lumuri dengan perasan jeruk nipis kurleb 15 menit, cuci lagi hingga bersih\", \"Tumis bumbu halus hingga harum, masukan daun jeruk, serai, beri air, garam, gula, lada aduk rata\", \"Tes rasa bumbunya dulu, bila sudah cukup masukan ayamnya dan biarkan hingga air menyusut (sy ditutup biar makin menyerap bumbunya ke ayam)\", \"Angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1522, 3, 'Semur Ayam dan Kentang', 'Resep Semur Ayam dan Kentang yang lezat dan mudah dibuat di rumah.', '[\"1 kg Ayam potong_potong. Goreng terlebih dahulu\", \"1/2 kg kentang, kupas, potong bulat dan goreng\", \"6 siung bawang putih dihaluskan\", \"3 siung bawang merah dihaluskan\", \"6 sdm kecap manis atau sesuai selera\", \"1/2 sdt merica bubuk\", \"1 sdm saus tiram\", \"Secukupnya garam\", \"Secukupnya gula\", \"1 ruas jahe geprek\", \"Secukupnya air\", \"Minyak untuk menggoreng ayam\"]', '[\"Tumis bumbu halus dan jahe sampai harum. Masukkan ayam dan Kentang serta bumbu lainnya. Masukkan air. Masak sampai ayam matang dan air meresap. Test rasa. Angkat dan sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1523, 4, 'Nugget ayam wortel', 'Nikmati kelezatan Nugget ayam wortel dengan resep sederhana ini.', '[\"1/4 kg dada ayam tanpa tulang\", \"3 siung bawang putih diparut\", \"2 sdm tepung maizena\", \"3 sdm tepung tapioka\", \"1 tangkai daun prei\", \"1 buah wortel ukuran sedang (diparut)\", \"-saya pake parutan keju\", \"2 butir telur\", \"2 butir telur untuk lapisan nugget\", \"Secukupnya gula pasir\", \"Secukupnya garam\", \"Secukupnya kaldu bubuk (optional)\", \"1/2 butir pala (dihaluskan dulu)\", \"Kurleb 175cc air es\", \"Secukupnya tepung roti\", \"Secukupnya margarin untuk olesan\"]', '[\"Siapkan blender masukkan berurutan : duo tepung, bawang putih, garam, kaldu, gula, pala, daun prei, wortel, ayam, 2 butir telur, terakhir air es. Lalu blender sampai rata.\", \"Koreksi rasa dengan menggoreng sedikit adonan. Tekstur tidak terlalu encer dan tidak terlalu padat ya.\", \"Olesi wadah dengan margarin agar adonan ngga nempel. Tips saya langsung buka bag bawah blender dari pada saya tuang dari atas biar gak susah ngeluarin adonannya.\", \"Panaskan dandang, setelah panas, kukus adonan sampai setengah matang lalu kecilkan api. Lakukan tes tusuk untuk mengetahui adonan sudah matang atau belum.\", \"Dinginkan sebentar lalu iris sesuai selera. Oleskan margarin pada pisau agar ngga lengket.\", \"Lapisi dengan telur, gulingkan di tepung roti, caranya dengan menggoyang-goyang mangkok biar rata sempurna.\", \"Masukkan kulkas dulu agar tepung roti lebih nempel. Setelah itu bisa dimasukkan freezer, masukkan di wadah kedap udara. Bisa tahan semingguan, atau paling lama sehari udah ludes 😂\", \"Goreng dengan minyak secukupnya smp kuning keemasan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1524, 2, 'Ayam Sioh simple', 'Resep Ayam Sioh simple yang lezat dan mudah dibuat di rumah.', '[\"1 kg ayam potong2 sesuai selera\", \"50 gr asam dilarutkan dengan 125 cc air\", \"10 buah cabai rawit\", \"50 gr gula merah\", \"1 sdt garam\", \"Jeruk nipis\", \"Bumbu halus :\", \"2 sdt ketumbar sangrai\", \"4 siung bawang putih\", \"5 buah bawang merah\", \"1/2 sdt terasi\", \"2 sdm irisan serai\"]', '[\"Lumuri ayam dengan 1 sdm air jeruk nipis dan 1 sdt garam, diamkan 15 menit.\", \"Tumbis bumbu halus sampai matang dan harum.\", \"Masukkan ayam, aduk hingga kaku, tuangi air asam, dan gula tambahkan 350 cc air dan cabai rawit.\", \"Jika perlu tambahkan setiap kalinya 100cc air panas.\", \"Masak ayam sampai lunak dan kuah kental.\", \"Selamat mencoba 💪\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1525, 2, 'Ayam Goreng Ungkep ala Ummu Rasya', 'Nikmati kelezatan Ayam Goreng Ungkep ala Ummu Rasya dengan resep sederhana ini.', '[\"1/2 kg daging ayam\", \"Bumbu Halus:\", \"7 siung bawang putih\", \"1 ruas jari kunyit\", \"1 ruas jari jahe\", \"Bumbu Uleg Kasar :\", \"1 ruas jari lengkuas / laos\", \"Bumbu Iris :\", \"2 batang sereh\", \"Bumbu Pelengkap :\", \"5 lembar daun salam\", \"2 sendok garam\", \"Secukupnya air\"]', '[\"Siapkan wajan/panci berisi air, masukkan ayamnya\", \"Masukkan seluruh bumbu2nya\", \"Aduk rata, tunggu hingga air nya sudah tinggal sedikit atau sat\", \"Goreng sesuai selera\", \"Sajikan dg nasi hangat dan sambal tomat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1526, 3, 'Garang asem ayam *tanpa daunpisang dan tanpa dikukus', 'Garang asem ayam *tanpa daunpisang dan tanpa dikukus dengan bumbu meresap sempurna.', '[\"1/2 kg Ayam\", \"5 siung Bawang merah ..iris2\", \"4 siung Bawang putih ..iris2\", \"3 lembar Daun salam\", \"4 lembar Daun jeruk\", \"2 batang Sere\", \"3 cm Lengkuas\", \"2 buah Rawit\", \"1 buah Tomat\", \"5 buah Belimbing wuluh\", \"Garam.merica.kaldu jamur\", \"2 sdm Santan bubuk\"]', '[\"Masak air..stlh panas..masukkan duo bawang.salam.sere.lengkuas..masak sampai mendidih dan wangi\", \"Masukkan ayam.tomat.belimbing.lalu bumbuin dgn garam.merica.dan kaldu jamur\", \"Terakhir masukkan santan.dan rawit aduk2 sampai rata..lalu test rasa\", \"Kalau tidak ada belimbing..tambahkan perasan air jeruknipis ato larutan asam jawa\", \"Banyaknya rawit dan santan sesuai selera ya\", \"Saya sengaja rawitnya terakhir..krn masakan saya bagi 2..yg 1 tanpa rawit utk anak2..yg 1 bwt saya yg doyan pedes 😅\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1527, 3, 'Sayur sop kulit ayam ala anak kos', 'Hidangan ayam lezat: Sayur sop kulit ayam ala anak kos untuk keluarga tercinta.', '[\"Kulit ayam (sesuai selera)\", \"Sawi hijau\", \"Kol\", \"Daun bawang\", \"Seledri\", \"1 siung bawang putih (digeprek)\", \"2 siung bawang merah (diiris)\", \"secukupnya lada bubuk\", \"secukupnya pala bubuk\", \"secukupnya masako ayam\", \"1 bungkus bumbu sop instan\", \"1 butir telur (dikocok lepas)\"]', '[\"Potong kulit ayam sesuai selera dan rebus dulu. Bisa ditambah sosis atau bakso (kebetulan gak punya haha)\", \"Potong sawi, kol, daun bawang, dan seledri. Goreng bawang merah.\", \"Buang air rebusan kulit ayam, tambahkan 2 gelas air mendidih. Masukkan bawang putih, sawi, kol, daun bawang, dan seledri.\", \"Tambahkan bumbu instan, lada, pala, dan masako.\", \"Tunggu hingga mendidih, masukkan telur sambil diaduk pelan saja.\", \"Taburkan bawang merah goreng. Selesai ☺\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1528, 3, 'Rica rica ayam pedas dengan cabai rawit set*n', 'Hidangan ayam lezat: Rica rica ayam pedas dengan cabai rawit set*n untuk keluarga tercinta.', '[\"500 grm ayam (potong sesuai selera)\", \"1 genggam cabe rawit merah /rawit setan\", \"4 lbr daun jeruk\", \"2 buah serah (geprek)\", \"5 siung bawang merah besar\", \"3 siung bawang putih\", \"secukupnya Garam,gula pasir, penyedap, minyak goreng\", \"sesuai selera Kunyit\", \"secukupnya Air\"]', '[\"Haluskan : kunyit, cabai, bawang merah, bawang putih,\", \"Panaskan minyak,goreng ayam yg telah di potong2, kemudian sisihkan\", \"Panaskan minyak, tumis bumbu halus, masukan sereh dan daun jeruk, setelah harum masukan sedikit air tunggu hingga mendidih, kemudian masukan garam, penyedap, gula pasir aduk rata\", \"Masukan ayam yg telah di goreng, aduk hingga mengering dan bumbu menyerap\", \"Angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1529, 2, 'Pentul sayap ayam goreng panir', 'Resep Pentul sayap ayam goreng panir yang lezat dan mudah dibuat di rumah.', '[\"12 bh pentul sayap ayam\", \"2 siung bawang putih\", \"3 cm jahe\", \"1/2 sdt merica bubuk\", \"1 sdt kecap asin\", \"secukupnya Garam dan kaldu bubuk\", \"Bahan pelapis\", \"1 butir telur\", \"secukupnya Tepung maizena\", \"secukupnya Tepung panir oranye\"]', '[\"Cuci bersih pentul sayap ayam, kerat bagian ujungnya, lalu tarik ke bawah hingga daging berkumpul di bagian bawah. Sisihkan.\", \"Haluskan bawang putih dan jahe, campurkan ke pentul sayap, tambahkan merica bubuk, kecap asin, garam dan kaldu bubuk. Aduk hingga rata. Diamkan selama 2 jam di kulkas.\", \"Setelah itu, tiriskan bumbu rendaman. Gulingkan pentul sayap ke tepung maizena hingga rata, remas-remas agar tepung menempel. Lalu celupkan ke kocokan telur, terakhir lapisi dengan tepung panir. Lakukan hingga habis.\", \"Goreng dengan minyak banyak hingga keemasan. Angkat dan tiriskan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1530, 2, 'Sempol Ayam', 'Sajian Sempol Ayam yang praktis dan lezat untuk dinikmati bersama.', '[\"1/4 daging ayam giling\", \"1 butir telur\", \"5 siung bawang putih\", \"5 siung bawang merah goreng\", \"1 sdt lada\", \"Secukupnya garam\", \"1 SDM terigu\", \"4 SDM tapioka\", \"3 lbr daun bawang iris tipis\", \"Secukupnya minyak untuk menggoreng\", \"2 sdm terigu untuk larutan pelekat\", \"Secukupnya tepung roti untuk Baluran\", \"2 sdm saos tiram\"]', '[\"Kalo aq sih daging ayamnya beli di babang sayur trus di blender sndiri sama telor\", \"Setelah halus campur rata semua bahan\", \"Aduk rata hingga semua tercampur, ambil sedikit bagian, goreng / rebus, koreksi rasa\", \"Bentuk bulat2 lalu pasangkan tusuk eskrim, jangan lupa tangan diolesi minyak, soalnya adonan nya sangat lengket\", \"Rebus di air yg panas tapi ngga sampe mendidih\", \"Tiriskan\", \"Balur dengan tepung roti lalu goreng dengan api kecil hingga warna kuning kecoklatan\", \"Bisa disimpan di freezer kalo mau buat besok2\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1531, 2, 'Ayam Kecap Pedas', 'Ayam Kecap Pedas dengan bumbu meresap sempurna.', '[\"1/4 kg dada ayam, dipotong jadi 6 bagian\", \"3 siung bawang merah, iris tipis\", \"1/4 buah bawang bombay, diiris\", \"5 buah cabe merah, diiris\", \"2 buah cabe rawit (atau sesuai selera), diiris\", \"1 tangkai daun bawang, potong kecil-kecil\", \"1 buah tomat sayur, potong kecil-kecil\", \"1 cm lengkuas\", \"2 lembar daun salam\", \"400 ml air\", \"Secukupnya garam\", \"Secukupnya gula merah\", \"Secukupnya kecap\", \"Bumbu halus:\", \"3 siung bawang putih\", \"1 butir kemiri\", \"1/2 sendok teh merica\", \"1 ruas jahe\"]', '[\"Tumis bawang merah, bawang bombay, cabe merah dan cabe rawit. Tunggu sampai harum, lalu masukkan daun salam dan lengkuas.\", \"Masukkan bumbu halus, tumis sampai bumbu matang\", \"Masukkan ayam, aduk sampai merata dengan bumbu dan bawang\", \"Masukkan air, tunggu sampai mendidih\", \"Tambahkan garam, gula merah dan kecap sesuai selera. Karena lagi pengen manis, saya pakai 1/2 botol kecil kecap bango.\", \"Koreksi rasa, tunggu sampai air menyusut, tapi jangan sampai kering. Pakai api kecil saja\", \"Masukkan daun bawang dan tomat. Aduk, lalu tunggu sebentar. Matikan api, Ayam kecap pedas siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1532, 2, 'Ayam Ungkep', 'Nikmati kelezatan Ayam Ungkep dengan resep sederhana ini.', '[\"1 kg Ayam\", \"5 siung Bawang putih\", \"4 siung Bawang merah\", \"3 jari Kunyit\", \"1/4 jari Jahe\", \"1 bh Sereh\", \"3 lbr Daun salam\", \"Ketumbar\", \"Garam\", \"Air\"]', '[\"Haluskan bawang merah,bawang putih,jahe,ketumbar,kunyit.\", \"Tumis bumbu yg sudah dihaluskan hingga harum,lalu masukkan ayam.\", \"Masukkan air,daun salam,sereh dan garam lalu tunggu hingga mendidih dan semua bumbu meresap.\", \"Panaskan minyak lalu goreng ayam hingga berwarna kecoklatan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1533, 4, 'Ayam Saos Belibis', 'Ayam Saos Belibis dengan bumbu meresap sempurna.', '[\"Bahan utama:\", \"2 Bh Ayam fillet dada yg besar\", \"20 bh sosis merk champ atau bernadhi\", \"8 telur ayam (boleh pakai boleh tidak)\", \"Bumbu :\", \"1 bh bawang bombay ukuran besar\", \"8 bh bawang putih\", \"1 bh paprika ukuran besar(kl kecil pakai 2)\", \"3 bh cabe hijau besar\", \"1 bh tomat\", \"8 bh saos belibis(selera)\", \"1 sdm kecap(selera)\", \"1 sdm minyak wijen\", \"Garam\", \"Gula\", \"Royco\"]', '[\"Cuci bersih ayam... Lumurin jeniper (jeruk nipis peras) agar tidak amis\", \"Rebus ayam..... jangan di buang air rebusan ayam karna untuk kaldunya\", \"Setelah di rebus...suwir atau potong potong ayam..goreng setengah matang\", \"Tumis bawang..cabe..paprika...hingga harum dan layu...lalu masukan ayam dan air rebusan ayam tadi sebagai kaldu dan tambahkan air 1 gelas\", \"Masukan saos belibis dan tomat di parut menggunakan parutan keju...tunggu sampai mendidih\", \"Jika air sudah berkurang... Masukan telur..sosis tambahkan minyak wijen..garam..gula..kecap\", \"Masak dengan hati ikhlas dn senang akan menambah kenikmatam\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1534, 2, 'Tahu telur surabaya', 'Resep praktis Tahu telur surabaya yang bisa dicoba di rumah.', '[\"1 butir telur\", \"1 potong tahu putih goreng setengah matang\", \"1/2 siung bawang putih goreng\", \"1 sdm petis udang\", \"3 sdm kacang tanah goreng\", \"secukupnya Gula merah\", \"secukupnya Air\", \"Kucai secukupnya / seledri\", \"secukupnya Bawang goreng\", \"secukupnya Garam\", \"Kecap manis\", \"4 buah cabai rawit goreng\", \"Tauge\", \"Acar\"]', '[\"Uleg kacang, cabai, bawang putih, gula merah, petis. Tambahkan air matang. Aduk rata. Sisihkan\", \"Potong tahu kecil-kecil. Sisihkan\", \"Kocok telur dan garam. Masukkan tahu ke telur. Goreng\", \"Campur telur goreng dan tauge dengan saus kacang. Aduk rata.\", \"Pindah ke piring, beri kecap manis secukupnya, taburi bawang goreng dan kucai/seledri. Tambahkan acar\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1535, 3, 'Telur ceplok masak kecap', 'Telur ceplok masak kecap - hidangan telur praktis dan lezat.', '[\"4 butir telur\", \"4 siung bwng merah\", \"2 siung bwng putih\", \"1 buah tomat\", \"4 buah cabe merah besar\", \"secukupnya Kecap bango\"]', '[\"Ceplok telur lalu sisihkan\", \"Iris tipis dua bwng,cabe dan tomat\", \"Panaskan minyak tumis bmbu sampai harum\", \"Tambahkan kecapmasukan telur tambahkan air sampai bmbu meresap\", \"Angkat dan sajikan dengn nasi panas\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1536, 4, 'Sambal telur ayam', 'Buat Sambal telur ayam yang nikmat dengan langkah-langkah mudah ini.', '[\"1/2 kg telur\", \"6 cabe merah besar\", \"10 cabe rawit\", \"Sejumput lada\", \"Garam\", \"Gula putih\", \"Kecap manis\", \"3 bawang putih\", \"6 bawang merah\"]', '[\"Rebus telur lalu kupas dan goreng\", \"Rebus cabe merah, rawit, bawang putih, bawang merah, tomat\", \"Lalu haluskan lada garam, dan bumbu yg di rebus tadi\", \"Tumis bumbu sampai harum masukkan penyedab rasa dan gula, aduk rata. Masukkan air matang sedikit lalu masukkan kecap manis sesuai selera dan telur. Tunggu sampai air menyusut. Icip rasa\", \"Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1537, 2, 'Telur Dadar Padang', 'Resep Telur Dadar Padang ala rumahan yang dijamin menggugah selera.', '[\"3 btr telur ayam(lebih enak pakai telur bebek)\", \"4 sdm kelapa parut,sangrai(asli : 3 sdm)\", \"2 sdm tepung beras,larutkan dengan sedikit air\", \"1/2 lbr daun kunyit,buang tulangnya,iris halus(skip)\", \"2 btg daun bawang,iris halus\", \"Secukupnya garam dan kaldu bubuk(optional)\", \"Bumbu halus :\", \"3 bh cabe merah,giling/iris halus(aku tambah 5 bh cabe rawit)\", \"5 btr bawang merah\", \"3 siung bawang putih\", \"1/2 ruas kunyit\", \"1 sdt kari bubuk(aku pakai Baba\'s)\", \"1 sdt ketumbar bubuk\", \"1/2 sdt lada bubuk\"]', '[\"Kocok telur sebentar saja,jika kelamaan telurnya kempes saat didadar.\", \"Masukkan bumbu halus,aduk rata.\", \"Tambahkan bahan lainnya,beri garam dan kaldu bubuk,tes rasa.\", \"Panaskan wajan datar anti lengket dengan api besar,beri minyak goreng secukupnya.\", \"Setelah minyak panas,tuang kocokan telur,kecilkan api,tutup wajan.\", \"Jika sudah kokoh,balik telur dan masak sisi lainnya hingga matang.\", \"Angkat dan tiriskan.\", \"Sajikan saat masih hangat dengan nasi panas..lamakk banaa..ngga perlu sambel lagi..karna ini udah pedess..😰😰\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1538, 2, 'Ceplok Telor saus Asam Manis', 'Resep Ceplok Telor saus Asam Manis yang lezat dan mudah dibuat di rumah.', '[\"2 btr telur\", \"1 ruas wortel iris korek api\", \"1 siung bwg putih geprek cacah halus\", \"1/2 siung bwg bombay iris tipis\", \"1 sdm saus tomat\", \"1 sdm saus sambel\", \"Sejumput garam, merica n kaldu bubuk\", \"Seujung sdt gula\", \"30 ml air\"]', '[\"Ceplok telur sisihkan\", \"Tumis bwg putih n bwg bombay sampai harum lalu masukkan wortel, tumis sampai agak layu\", \"Kecilkan api, tambahkan air n masukkan duo saus serta bumbu perasa lain\", \"Aduk rata n masak sampai meletup letup, lalu guyurkan k telur ceplok\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1539, 4, 'Potatoes cheese with egg', 'Nikmati kelezatan Potatoes cheese with egg dengan resep sederhana ini.', '[\"250 gr kentang kupas dan potong bulat\\\" goreng setengah matang\", \"2 bh sosis potong bulat\", \"50 ml susu segar\", \"50 gr keju cheedar parut\", \"50 gr keju mozarela parut\", \"3 butir telur kocok\", \"lada dan garamsecukupnya\"]', '[\"Siapkan cetak tahan panas olesi dgn mentega, uk 12 cm\", \"Tata kentang goreng dipinggan sampai tertutup semua\", \"Kocokan telur bumbui dgn lada dan garam secukupnya, kocok rata tambahkan susu segar, sisihkan\", \"Kentang yg sdh diatur dipinggan atasnya taburi dgn keju cheedar, potongan sosis, dan keju mozarela, terakhir tuangkan kocokan telur susu\", \"Oven selama 20 mnt dgn suhu 180 derajat, jgn lupa panaskan oven lebih dahulu\", \"Siap disajikan dgn saoce sambal tomat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1540, 2, 'TTKK (tahu telur timun tauge kuah kacang)', 'Nikmati kelezatan TTKK (tahu telur timun tauge kuah kacang) dengan resep sederhana ini.', '[\"1 butir telur\", \"1 tahu\", \"secukupnya Timun\", \"secukupnya Tauge\", \"Kuah kacang :\", \"Kacang tanah disangrai\", \"Bawang merah\", \"Bawang putih\", \"Cabe kering\", \"Cabe rawit\", \"Gula merah\"]', '[\"Goreng tahu dan telur, rebus tauge.\", \"Potong2 timun sesuai selera\", \"Tata telur pada piring, potong tahu taruh diatas telur tadi lalu tauge dan timun lalu airam kuah kacang\", \"TTKK siap disantap\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1541, 4, 'Semur kering telur kentang', 'Resep Semur kering telur kentang ala rumahan yang dijamin menggugah selera.', '[\"2-4 butir telur\", \"2 buah kentang\", \"3 siung bawang merah\", \"3 siung bawang putih\", \"secukupnya Kemiri\", \"3 buah cabai merah (sesuai selera)\", \"secukupnya Air\", \"secukupnya Gula pasir\", \"secukupnya Lada bubuk\", \"Penyedap makanan\", \"secukupnya Kecap\", \"1 daun salam\"]', '[\"Potong kentang sesuai selera dan rebus bersama dengan telur.\", \"Selagi menunggu kentang dan telur di rebus. Haluskan bawang merah, bawang putih, cabai, kemiri, dan lada.\", \"Setelah kentang dan telur selesai direbus. Kupas telurnya\", \"Goreng kentang dan telur yang sudah di rebus sebentar saja.\", \"Tumis bumbu yang sudah di haluskan sampai harum. Kemudian tambahkan daun salam dan air.\", \"Setelah mendidih masukan telur dan kentangnya. Tambahkan kecap secukupnya.\", \"Tambahkan gula & penyedap rasa, aduk-aduk.\", \"Tutup panci sambil sesekali di lihat sampai kuahnya hilang dan meresap.\", \"Semur kering telur kentang sudah bisa di hidangkan!\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1542, 4, 'Kari tahu telur kentang', 'Sajian Kari tahu telur kentang yang praktis dan lezat untuk dinikmati bersama.', '[\"4 butir telur rebus\", \"4 buah tahu, potong 8 bagian lalu goreng berkulit\", \"2 buah kentang, potong 4 bagian\", \"1 bks santan kara ukuran kecil\", \"1000 ml air / kaldu\", \"5 buah cengek utuh (tambahan dari saya)\", \"Haluskan :\", \"1 buah cabe merah buang biji\", \"5 siung bawang merah\", \"2 siung bawang putih\", \"1 sdm bumbu kari instant\", \"2 butir kemiri\", \"1/4 sdt ketumbar\", \"1/2 sdt merica bubuk\", \"1/8 sdt pala bubuk\", \"2 ruas jari kunyit\", \"Rempah cemplung\", \"1 batang sereh, geprek\", \"2 cm lengkuas\", \"1 cm jahe\", \"2 lembar daun jeruk\", \"1 lembar daun salam\", \"Secukupnya asam jawa\", \"Garam / kaldu bubuk\", \"Gula pasir\"]', '[\"Tumis bumbu halus dan rempah cemplung hingga harum dan matang\", \"Masukan kentang. Aduk rata\", \"Beri air. Setelah agak mendidih masukan telur, tahu dan rawit utuh\", \"Bumbui garam dan gula pasir\", \"Setelah didih, masukan santan, aduk sesekali\", \"Angkat, sajikan dengan pelengkap\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1543, 2, 'Buncis Cah Telur', 'Olahan telur sederhana: Buncis Cah Telur yang mudah dibuat.', '[\"20 bh buncis iris tipis2\", \"4 siung bawang putih cincang\", \"1/4 bawang Bombay iris halus\", \"2 bh cabe merah iris halus\", \"5 bh bakso iris tipis / bs ganti dgn sosis\", \"secukupnya Kaldu Ayam\", \"secukupnya Air panas\", \"1-2 btr telur\"]', '[\"Tunis bawang putih, bawang Bombay, cabe merah sampai wangi Masukkan bakso atau sosis oseng2.\", \"Masukkan bunci yang sudah di iris, oseng sampai berubah warns, Masukkan sedikit air panas biar kan sampai agak matang, Masukkan bumbu penyedap Dan tes rasa.\", \"Terakhir, tepikan buncisnya Dan Masukkan Telurnya, oseng2 Telur kemudian balurkan dengan buncisnya.\", \"Selamat mencoba :)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1544, 2, 'Telur cah tomat', 'Telur cah tomat - hidangan telur praktis dan lezat.', '[\"2 butir telur\", \"1 buah tomat (potong2)\", \"2 siung bawang merah (iris)\", \"1/2 siung bawang bombay (iris)\", \"2 buah cabe rawit merah/sesuai selera (iris)\", \"Secukupnya daun bawang\", \"Garam\", \"Merica\", \"Gula\"]', '[\"Tumis bawang merah dan bawang bombay, masukkan telur lalu orak arik dan sisihkan\", \"Tambahkan sedikit minyak disisi lain wajan, masukkan tomat, cabe dan daun bawang lalu aduk2 sampai tomat layu,\", \"Setelah layu, aduk rata dengan telur yg sudah di orak arik, tambahkan garam, merica dan gula, koreksi rasa, sajikan dengan nasi hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1545, 3, 'Cah sawi putih campur telur', 'Olahan telur sederhana: Cah sawi putih campur telur yang mudah dibuat.', '[\"1 buah sawi putih potong sesuai selera\", \"2 butir telur kocok lepas\", \"3 siung bawang putih geprek\", \"10 buah cabe merah iris\", \"secukupnya Air\", \"secukupnya Garam, gula\"]', '[\"Siapkan bahannya\", \"Tumis bawang dan cabe sampai harum.\", \"Sisihkan cabe dan bawang kepinggir wajan, masukkan telur aduk rata bikin orak arik.\", \"Masukkan sawi aduk sebentar tambahkan sedikit air, garam, gula, aduk rata tes rasa.\", \"Siap disajikan, simple dan lezat. Happy cooking moms 😊😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(1546, 4, 'Telur Tahu Kukus Goreng', 'Resep Telur Tahu Kukus Goreng ala rumahan yang dijamin menggugah selera.', '[\"2 butir telur\", \"3 buah tahu putih\", \"2 tangkai daun bawang\", \"1/2 buah wortel (aku lagi gak ada)\", \"1 siung bawang putih\", \"sedikit lada\", \"secukupnya garam\", \"secukupnya penyedap rasa\"]', '[\"Haluskan bawang putih dan lada.\", \"Hancurkan tahu dengan garpu.\", \"Potong2 daun bawang. wortel diparut dengan parutan keju.\", \"Kocok telur dengan garpu, tambahkan bumbu halus, garam dan penyedap rasa.\", \"Masukkan tahu, daun bawang dan wortel.\", \"Siapkan wadah tahan kukus kedian olesi dengan minyak goreng agar tidak lengket nanti.\", \"Masukkan telur ke wadah, kukus selama kurang lebih 15menit.\", \"Dinginkan telur, keluarkan dan potong2 sesuai selera.\", \"Kocok 1 butir telur.\", \"Celupkan potongan telur ke kocokan telur lalu goreng hingga kecoklatan.\", \"Angkat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1547, 2, 'Telor Sambal Ebi', 'Nikmati kelezatan Telor Sambal Ebi dengan resep sederhana ini.', '[\"4 Butir Telor Ayam\", \"5 Bawang Merah\", \"2 Bawang Putih\", \"5 Cabai Rawit\", \"Serai Geprek\", \"Merica Bubuk\", \"Garam\", \"Gula\"]', '[\"Rebus telur sampai matang, kupas lalu Goreng. Sisihkan\", \"Haluskan bawang merah bawang putih dan cabai, lalu tumis sampai harum. Masukkan serai lalu ebi. Bubuhkan Garam dan merica lalu gula.\", \"Masukkan telor, aduk sampai rata kemudian tambahkan sedikit air biarkan meresap.\", \"Angkat dan sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1548, 3, 'Telur Dadar Daging', 'Telur Dadar Daging - hidangan telur praktis dan lezat.', '[\"200 gr daging giling\", \"1 bh wortel, parut\", \"2 siung bawang putih, cincang\", \"1/2 bh bawang bombay, cincang\", \"4 btr telur\", \"1 btng seledri, iris halus\", \"Garam, gula, merica, penyedap sckpnya\"]', '[\"Tumis bw pth dan bombay hingga harum, masukkan daging, aduk hingga berubah warna. Masukkan wortel dan seledri, beri garam, gula, merica dan penyedap. Tes rasa, masak sampai semua matang, angkat.\", \"Kocok telur, masukkan tumisan daging td, aduk rata. Buat dadar pada pan teflon kcl hingga beberapa buah. Sajikan panas\\\" enyaakkk,,,,,😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1549, 2, 'Telur gulung (jajanan SD)', 'Resep praktis Telur gulung (jajanan SD) yang bisa dicoba di rumah.', '[\"telur ayam\", \"sedikit air\", \"garam\", \"lada\", \"masako (skip)\", \"tusukan kayu\"]', '[\"Panaskan minyak terlebih dahulu, minyak nya banyakin yah.\", \"Campur semua bahan jadi satu, lalu kocok sampai berbusa\", \"Masukan dalam botol kecap plastik / tuang 2 sendok menyebar yah\", \"Tuang ke minyak panas, lsg gulung2 pakai tusukan kayu terus dipinggirkan ke penggorengan supaya tdk terlalu banyak menyerap minyak.\", \"Tiriskan dan siap disantap pakai saos yg sudah dicampurkan air.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1550, 3, 'Pangsit Goreng Isi Bihun Telur', 'Pangsit Goreng Isi Bihun Telur - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 bidang bihun\", \"secukupnya Kubis\", \"3 tangkai seledri\", \"1 buah wortel\", \"1 butir telur\", \"5 butir bawang merah\", \"3 butir bawang putih\", \"secukupnya Saos tiram\", \"secukupnya Kecap\", \"secukupnya Garam\", \"Kulit pangsit\"]', '[\"Potong wortel kecil-kecil, dan rebus sampai matang. Angkat, tiriskan.\", \"Telur digoreng orak arik, tambahkan garam agar lebih berasa.\", \"Haluskan bawang merah dan putih, tumis. Tambahkan bihun yang sudah direbus, wortel, kubis, seledri, telur orak arik. Tambahkan juga saos tiram dan kecap.\", \"Rasakan, jika rasa kurang kuat, tambahkan garam atau penyedap rasa. Jika sudah selesai, angkat dan sisihkan.\", \"Ambil kulit pangsit, isikan isian yang sudah masak kedalamnya. Goreng, dan tiriskan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1551, 4, 'Telur Dadar Kilat', 'Telur Dadar Kilat - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"2 butir telur\", \"2 siung bawang merah, iris tipis\", \"1 cabe rawit, iris tipis\", \"1 batang daun bawang, iris-iris\", \"secukupnya garam\", \"mentega/ minyak\"]', '[\"Campurkan bawang merah, cabe dan daun bawang dengan telur. Kocok lepas. Beri garam secukupnya\", \"Siapkan teflon, beri sedikit mentega atau minyak. Masukkan adonan telur, lebarkan. Tunggu hingga sisi bawah matang kemudian balik. Lipat perlahan dan masak beberapa menit, kemudian angkat. Potong sesuai selera dan sajikan...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1552, 4, 'Semur kentang telur', 'Olahan telur sederhana: Semur kentang telur yang mudah dibuat.', '[\"4 buah telur ayam rebus\", \"2 buah kentang potong sesuai selera\", \"secukupnya Kecap manis\", \"2 lembar daun salam\", \"Bumbu halus :\", \"4 siung bawang putih\", \"3 siung bawang merah\", \"secukupnya Lada\", \"2 buah kemiri\"]', '[\"Goreng sebentar kentang dan telur rebus.\", \"Tumis bumbu halus hingga wangi, tambahkan daun salam dan air secukupnya.\", \"Setelah mendidih, tambahkan kecap manis, telur dan kentang.\", \"Tambahkan gula pasir, dan penyedap rasa\", \"Tunggu hingga air berkurang, jangan sampe terlalu kering ya bun.\", \"Cek rasa, hidangkan dengan taburan bawang goreng 👌\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1553, 4, 'Timun kuah telur (diet debm)', 'Cara membuat Timun kuah telur (diet debm) yang enak dan praktis untuk keluarga.', '[\"1 timun (Potong tipis/selera)\", \"1 bawang putih (geprek)\", \"Merica bubuk\", \"Garam, penyedap\", \"Saos tiram\", \"2 telur\"]', '[\"Tumis bawang dan merica hingga harum... Beri air... Lalu masukan timun, beri garam, penyedap, dan saos tiram.. Setelah mendidih masukkan telur. Koreksi rasa. Matangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1554, 3, 'Telor Balado Pete', 'Resep Telor Balado Pete yang lezat dan mudah dibuat di rumah.', '[\"10 bh telur ayam (rebus, kupas kulit)\", \"4 papan pete\", \"2 bh sereh (geprak)\", \"4 bh daun jeruk\", \"Secukupnya garam+gula+kaldu jamur\", \"Secukupnya air\", \"Bumbu halus:\", \"125 gr cabe merah keriting/besar\", \"8 bh bawang merah\", \"2 bh bawang putih\"]', '[\"Panaskan minyak secukupnya, masukan bumbu halus+sereh+daun jeruk.Tumis sampai wangi. Beri air secukupnya, masukan garam+gula+kaldu jamur. Masukan pete. Masak sampai tidak bau langgu. Tes rasa.\", \"Terakhir masukan telor rebus, aduk rata & masak sebentar. Voilaa.. Telor Balado Pete is ready! Uenakk!👍😘\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1555, 3, 'Pecel telur', 'Pecel telur - hidangan telur praktis dan lezat.', '[\"6 butir telur ayam(rebus dan kupas cangkangnya)\", \"10 buah cabai rawit merah\", \"1 buah tomat uk. sedang\", \"1 siung bawang putih\", \"1 sdm kacang goreng\", \"Secukupnya terasi, garam, gula dan penyedap\", \"2 tangkai kemangi\"]', '[\"Goreng telur yg tadi sudah di rebus. Angkat dan tiriskan\", \"Goreng bawang putih, cabai, tomat hingga matang.\", \"Haluskan bahan sambal. Tambahkan kacang tanah goreng, Beri garam, gula, terasi dan penyedap\", \"Masak sebntar dan masukkan daun kemangi. Masukkan telur dan test rasa.\", \"Siap untuk disajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1556, 4, 'Telur bumbu merah', 'Resep Telur bumbu merah ala rumahan yang dijamin menggugah selera.', '[\"5 butir telur\", \"5 siung bawang merah\", \"5 siung bawang putih\", \"10 buah cabai merah (boleh ditambah bila suka pedas)\", \"2 buah tomat merah\", \"secukupnya Garam dan gula pasir\", \"2 lembar Daun salam\", \"2 cm lengkuas digeprek\", \"Penyedap bila suka (saya diskip)\", \"Minyak goreng untuk menumis\", \"350 ml air putih (satu set gelas belimbing)\"]', '[\"Goreng telur mata sapi, sisihkan\", \"Rebus bawang merah, bawang putih, cabai dan tomat (biar lebih merah warnanya)\", \"Haluskan bahan yang sudah direbus\", \"Tumis bahan yang sudah dihaluskan, tambahkan daun salam dan lengkuas geprek\", \"Masukkan air dan telur, tambah gula pasir dan garam, biarkan sampai mendidih dan meresap sampai air berkurang\", \"Koreksi rasa, hidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1557, 3, 'Telor dadar endol', 'Resep Telor dadar endol yang lezat dan mudah dibuat di rumah.', '[\"1 buah telur ayam\", \"Daging ayam cincang\", \"Stgh sdt terigu\", \"Daun bawang\"]', '[\"Cincang daging ayam,iris daun bawang\", \"Satukan bahan,tambah garam dan sasa\", \"Kocok dan goreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1558, 2, 'Telur bulet sambel terong', 'Resep Telur bulet sambel terong ala rumahan yang dijamin menggugah selera.', '[\"4 butir telur ayam, Rebus kupas kulitnya\", \"1 buah terong ungu ukuran besar\", \"Bumbu halus\", \"1/2 ons cabe hijau\", \"1 buah tomat merah\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"1/2 sdt terasi yg sudah dibakar\", \"secukupnya Garam\", \"Minyak untuk menggoreng\"]', '[\"Goreng telur yg sudah dikupas sebentar aja,angkat tiriskan\", \"Goreng terong yg sudah dipotong2,angkat tiriskan\", \"Goreng bumbu halus hingga wangi dengan api kecil\", \"Masukkan terong dan telur yg sudah digoreng\", \"Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1559, 2, 'Tumis labu siam dan telur', 'Tumis labu siam dan telur - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 butir telur\", \"Secukupnya labu siam (iris memanjang)\", \"3 siung bawang putih\", \"Garam\", \"Gula\", \"Penyedap\"]', '[\"Tumis bawang putih hingga harum, masukkan telur kemudian orak arik.\", \"Masukkan labu siam, tambahkan sedikit air aduk rata.\", \"Tambahkam garam, gula dan penyedap.\", \"Koreksi rasa dan siap sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1560, 2, 'Otak Sapi Goreng Telur', 'Resep Otak Sapi Goreng Telur ala rumahan yang dijamin menggugah selera.', '[\"250 gram otak sapi mentah\", \"3 lembar daun salam\", \"1 ruas jahe, geprek\", \"2 buah telur ayam\", \"Sesuai selera garam, lada bubuk, kaldu bubuk\"]', '[\"Rebus otak sapi mentah dengan daun salam dan jahe geprek sampai mendidih dan matang. Buang airnya. Tiriskan. Lalu potong tipis-tipis.\", \"Kocok lepas telur ayam dengan garam, lada bubuk, dan merica bubuk. Celupkan otak sapi satu persatu dan goreng dalam minyak panas.\", \"Lalu ambil kembali otak yg sedang digoreng tadi dan celupkan ke kocokan telur dan goreng kembali. Saya lakukan ini sampai 3 kali celupan. Kata suami supaya telurnya tebal. Sajikan dengan nasi hangat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1561, 2, 'Telor Balado', 'Resep Telor Balado yang lezat dan mudah dibuat di rumah.', '[\"10 telur ayam\", \"1/2 kg cabe merah\", \"8 bh bawang merah\", \"1 sdt minyak wijen\", \"2 bh terong balado\", \"1/2 sdt kecap\", \"Garam\", \"Royco\", \"Gula\"]', '[\"Rebus telur... Supaya gampang di lepas kulitny...rendam telor di air biasa\", \"Blender cabe dan bawang hingga halus\", \"Panaskan minyak goreng telurny sebentar saja ya kalo kelamaan telur bisa menciut lalu angkat\", \"Goreng sebentar terongnya\", \"Tiriskan telur dan terong\", \"Tumis bumbu yang di blender hingga berwarna kecoklatan dengan api kecil...jika sudah kecoklatan tambahkan kecap garam dan gula aduk rata ke telur dan terong\", \"Bisa di tambahkan suwiran ayam atau teri ya\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1562, 4, 'Telur dadar sawi tauge', 'Nikmati kelezatan Telur dadar sawi tauge dengan resep sederhana ini.', '[\"3 butir telur\", \"3 siung bawang merah iris\", \"semangkuk taoge\", \"2 bonggol sawi\", \"1 lembar daun bawang iris\", \"3 biji cabe rawit iris\", \"2 sdm kecap manis\", \"secukupmya garam lada bubuk\", \"Kaldu bubuk/opsional\"]', '[\"Siapkan Bahan. dadar telor lalu iris memanjang\", \"Panaskan sedikit minyak tumis bawang dan cabe hingga harum\", \"Masukan telur beri sedikit air matang tambahkan kecap lada garam kaldu bubuk\", \"Segera setelah mendidih masukan irisan daun bawang sawi dan toge. besarkan api masak sebentar hingga layu àngkat\", \"Simpel enak dan bergizi 😍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1563, 3, 'Bali kecap telur ayam', 'Sajian Bali kecap telur ayam yang praktis dan lezat untuk dinikmati bersama.', '[\"ayam\", \"telur\", \"tempe\", \"#bumbu:\", \"cabe merah\", \"bawang merah putih\", \"jahe\", \"laos\", \"daun jeruk\", \"gula merah\", \"kemiri\", \"kecap manis\", \"garam\"]', '[\"Cuci bersih ayam lalu rebus dan goreng. rebus telur buang kulit dan goreng\", \"Haluskan smua bumbu\", \"Panaakan sedikit minyak\", \"Tumis bumbu hingga harum\", \"Masukkan laos jahe dan daun jeruk\", \"Tambah sedikit air dan kecap manis\", \"Ending\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1564, 3, 'Telur Dadar Goreng Tepung', 'Cara membuat Telur Dadar Goreng Tepung yang enak dan praktis untuk keluarga.', '[\"2 butir telur (untuk di Dadar)\", \"1 butir telur, kocok lepas (untuk pencelup)\", \"secukupnya Garam\", \"secukupnya Penyedap rasa\", \"1 btg Daun Bawang, iris (saya skip karena kehabisan)\", \"Bahan kering (campurkan):\", \"2 sdm tepung terigu\", \"3 sdm tepung beras\", \"secukupnya Merica bubuk\", \"secukupnya Penyedap rasa (Masako/royko)\"]', '[\"Kocok 2 butir telur, campurkan dengan daun Bawang, garam, dan penyedap rasa secukupnya\", \"Hidupkan kompor, gunakan teplon, tuang 3 sdm minyak goreng, tunggu hingga setengah panas lalu tuangkan setengah adonan telur dan langsung jepit telur dengan dua spatula (bagian belakang bertemu bagian belakang) Nb: boleh langsung memasukkan semua adonan telur, tapi harus lebih hati hati agar telur tidak patah. Nb: jangan menunggu minyak panas karena telur akan langsung mengeras ketika dituang sehingga akan susah dijepit\", \"Teruskan menjepit jepit telur hingga telur kokoh dan berbentuk segitiga, balik telur dikedua sisinya hingga matang, tiriskan\", \"Ulangi point 3-4 untuk sisa setengah telur yang belum di Dadar, tiriskan\", \"Potong potong telur, gulingkan ditelur kocok, lalu gulingkan di bahan kering. Tekan tekan lembut hingga tepung menempel sempurna di telur dadar\", \"Goreng dengan minyak banyak hingga kecoklatan, matikan kompor\", \"Telur dadar goreng tepung siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1565, 2, 'Semur telur ayam', 'Olahan telur sederhana: Semur telur ayam yang mudah dibuat.', '[\"1/2 kg telur ayam, rebus kupas\", \"3 lbr daun salam\", \"2 batang sereh\", \"2 biji kapulaga\", \"2 biji bunga lawang\", \"2 butir cengkeh\", \"3 cm kayu manis\", \"1/4 pala\", \"3 cm jahe geprek\", \"3 cm lengkuas geprek\", \"1 sdt gula pasir\", \"1 1/2 sdt garam\", \"Kecap manis bango 8 sampai 10 sdm atau sesuai selera\", \"Bumbu halus :\", \"8 btr bw merah (iris2 goreng 1/2 matang sebelum dihaluskan)\", \"4 butir bw putih\", \"1/2 sdt mrica butiran\", \"5 butir kemiri sangrai\", \"Haluskan terpisah :\", \"1 buah tomat merah\"]', '[\"Panaskan 3 sdm minyak goreng. Tumis bumbu halus sampai harum tambahkan tomat yg telah dihaluskan masak sampai matang\", \"Masukan salam,pala, lengkuas,jahe,kayu manis,bunga lawang,cengkeh dan sereh. Aduk2 sampai tercium aroma wangi rempahnya\", \"Masukan 2 - 3 gelas air tunggu sampai mendidih baru tambahkan telur, garam,gula,kecap,penyedap rasa (saya pakai masako sapi)\", \"Masak terus sambil sesekali diaduk. Sampai kuah agak menyusut. Jika ingin berkuah banyak tinggal tambahkan air sesuai selera dan koreksi rasanya\", \"Angkat dan siap dihidangkan dg taburan bawang goreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1566, 3, 'Telur gulung korea/roll egg korean', 'Resep Telur gulung korea/roll egg korean ala rumahan yang dijamin menggugah selera.', '[\"Bahan :\", \"5 butir telur\", \"Wortel potong halus secukupnya\", \"secukupnya Daun bawang\", \"secukupnya Garam\", \"secukupnya Merica\"]', '[\"Cara membuat : campur dan aduk semua bahan ke dalam mangkuk, lalu panaskan frypan dan minyak secukupnya, tuang adonan sedikit demi sedikit dan gulung,hingga adonan habis\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1567, 2, 'Telur merah dadar pas pedasnya dan simpel', 'Sajian Telur merah dadar pas pedasnya dan simpel yang praktis dan lezat untuk dinikmati bersama.', '[\"Telur bebek,cabe rawit merah\", \"Garam,royko ayam\", \"Minyak\"]', '[\"Haluskan cabe rawit merah sampai halus,cabe rawitnya secukupnya saja ya!.\", \"Setelah halus,buka telur masukkan ke dalam botol lalu kocok\", \"Setelah di kocok masukkan ke dalam manci atau wadah. dan masukkan royko rasa ayam,cabe rawit yang sudah di haluskan,garam.\", \"Setelah sudah tercampur merata lalu panaskan minyak dan goreng deh.trs telur merah dadar pas pedasbya dan simpel siap di hidangkan.saya memakai telur bebek karena supaya warnnanya merah sekali walaupun cabenya sedikit. SELAMAT MENCOBA\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1568, 3, 'Telur rebus cuma 5 menit(bener2 hemat gas dan waktu)', 'Telur rebus cuma 5 menit(bener2 hemat gas dan waktu) - hidangan telur praktis dan lezat.', '[\"4 btr telur\", \"secukupnya Air\", \"Panci teplon beserta tutupnya\"]', '[\"Tuang air dlm panci hingga mencapai 1 cm dari dasar panci lalu masukkan telur lalu tutup dgn tutup panci rebus dgn api besar selama 2 menit,stlh 2 menit kecilkan apinya lalu masak dgn api kecil selama 3 menit.\", \"Setelah 3 menit matikan apinya dan biarkan dan tutup jangan dibuka2 dan panci tetap masih di atas kompor,biarkan di atas kompor selama 9 menit.\", \"Setelah 9 menit tutup panci boleh dibuka,pindahkan telur ke wadah yg berisi air dingin hingga telur dingin untuk memudahkan waktu telur dikupas.\", \"Telurnya mulus dan matang sempurna.\", \"Siap untuk disantap.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1569, 4, 'Balado telur', 'Resep Balado telur ala rumahan yang dijamin menggugah selera.', '[\"1/4 kg telur\", \"5 buah bamer\", \"3 buat baput\", \"10 buah cabe keriting\", \"1 buah tomat\", \"secukupnya Gula merah\", \"Garam dan penyedap\"]', '[\"Rebus telur kemudian goreng dgn minyak panas\", \"Haluskan semua bumbu kemudian tumis hingga harum\", \"Masukan sedikit air...krmudian masukan telur\", \"Tunggu hingga air hbs...sehingga bumbu meresap ditelur\", \"Telur balado siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1570, 2, 'Tahu Goreng Telur Simple', 'Tahu Goreng Telur Simple - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"Tahu putih (potong sesuai selera, jgn terlalu tipis)\", \"1 butir telur\", \"Garam dan ladaku\", \"Olive oil / Canola oil\"]', '[\"Cuci tahu dengan air mengalir, lalu lumuri tahu dengan garam.\", \"Kocok lepas telur. Berikan garam dan ladaku secukupnya. kocok rata.\", \"Rendam tahu dalam telur yg sudah dibumbui.\", \"Panaskan minyak (jangan terlalu banyak, seperti goreng telur dadar saja) lalu goreng tahu yg telah di rendam telur dengan api kecil sedang.\", \"Jika satu sisi sudah coklat, bisa balik ke sisi lainnya. setelah matang, tiriskan dan siap di hidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1571, 3, 'Semur Telor Simpel', 'Buat Semur Telor Simpel yang nikmat dengan langkah-langkah mudah ini.', '[\"7 butir telur ayam\", \"Cabai merah (iris serong)\", \"1/2 sdm gula merah\", \"secukupnya Air\", \"secukupnya Garam\", \"secukupnya Kecap manis\", \"Bumbu halus :\", \"6 siung bawang merah\", \"3 siung bawang putih\", \"2 butir kemiri\", \"1/4 sdt merica\"]', '[\"Ceplok telur satu persatu (telor nya mau direbus juga boleh)\", \"Panaskan sedikit minyak, tumis bumbu halus dan cabai merah hingga harum\", \"Beri sedikit air, masukan telor ceplok tambahkan kecap manis, garam dan gula merah\", \"Tunggu air sedikit menyusut koreksi rasa dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1572, 4, 'Cah Buncis Telur', 'Resep Cah Buncis Telur ala rumahan yang dijamin menggugah selera.', '[\"Buncis secukupnya (iris serong)\", \"2 butir telur (kocok lepas)\", \"Bumbu (iris) :\", \"Cabe merah\", \"Cabe hijau besar\", \"1 siung bawang putih\", \"3 butir bawang merah\", \"Bawang bombay\", \"secukupnya Garam\", \"secukupnya Gula pasir\", \"secukupnya Bubuk kaldu\"]', '[\"Panaskan sedikit minyak tumis bumbu sampe layu dan harum\", \"Masukkan kocokan telur lalu orak arik. Setelah itu masukkan buncis tambahkan sedikit air\", \"Tambahkan bumbu2 penyedapnya. Cek rasa lalu angkat😁\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1573, 2, 'Orek buncis + telor', 'Orek buncis + telor - hidangan telur praktis dan lezat.', '[\"10 batang buncis\", \"1 butir telor (kocok lepas)\", \"2 buah baso\", \"Bahan-bahan :\", \"2 siung bawang merah\", \"2 siung bawang putih\", \"2 cabe rawit\"]', '[\"Belah buncis menjadi 2 dan potong setelahnya. Kemudian cuci bersih. Potong baso tipis2. Kocok lepas telor.\", \"Tumis bumbu halus sampai harum kemudian masukkan buncis,baso. Pinggirkan buncis dan baso, masukkan telor orek2.setelah itu campur semua bahan tadi, tambahin air sedikit. Masak sampai matang dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1574, 2, 'Telor dadar terigu', 'Cara membuat Telor dadar terigu yang enak dan praktis untuk keluarga.', '[\"1 butir telur (aku pakek telur ayam)\", \"1 sdm munjung terigu\", \"1 sdm aja sagu\", \"1 1/2 sdm margarin\", \"1 siung bawang merah\", \"1 siung bawang putih\", \"2 buah cabe rawit/cabe merah (opsional)\", \"Secukupnya bawang bombay\", \"1/2 sdt merica (boleh bubuk boleh butir)\", \"1 sdt penuh penyedap rasa/garam(aku dua2nya, garam nya dikit aj)\", \"Sedikit minyak wijen\", \"Secukupnya air hangat\"]', '[\"Cairkan terigu dan sagu dengan air hangat hingga encer\", \"Potong bawang, cabe dkk\", \"Campurkan semua bahan jadi 1, biarkan bawang dkk mentah(gak usah ditumis biar wangi)\", \"Setelah itu, panaskan wajan dengan margarin hingga hilang kreces-kreces nya, lalu goreng adonan dengan api yang sedang cenderung besar biar hasil nya wangi, tapi jgn sampai gosong.\", \"Bolak balik sesekali biar matang luar dalam, jika sudah agak keluar asap, angkat.\", \"Telor dadar siap dinikmati, wangi bawang dan cabai mentah nya enak bgt 😍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1575, 4, 'Egg roll lembut harum', 'Cara membuat Egg roll lembut harum yang enak dan praktis untuk keluarga.', '[\"500 gr paha ayam giling\", \"1 butir telur\", \"3 siung bawang putih\", \"1 sdm peres bumbu ngohiong / five spice\", \"1 sdm terigu, 3 sdm sagu, 1 sdm maizena\", \"1 sdm dark soy sauce/ soyu\", \"1 sdm saos tiram\", \"1/2 sdt merica\", \"Utk kulit: 5 butir telur, 100 ml air, 2 sdm terigu, 1 sdt sagu\", \"Kocok rata ayak spy tdk bergerindil\"]', '[\"Aduk rata ayam giling + telur + bumbu\", \"Masukkan telur aduk rata sampai kalis\", \"Masukkan tepung2 ngan sisihkan\", \"Dadar tipis telur tata 2 sdm adonan diatas telur\", \"Gulung seperti buat lumpiah\", \"Bungkus plastik wrap / aluminium foil\", \"Kukus api sedang 40 menit\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1576, 3, 'Tahu telor malang sederhana', 'Buat Tahu telor malang sederhana yang nikmat dengan langkah-langkah mudah ini.', '[\"2 buah telor ayam\", \"2 potong tahu putih\", \"1 genggam daun bawang muda\", \"1 genggam tauge\", \"👉 bumbu kacang\", \"1 genggam kacang tanah yg sdh digoreng\", \"2 siung bawang putih goreng\", \"3 buah cabe rawit\", \"1/2 sdt terasi\", \"secukupnya kecap\"]', '[\"Kocok telur dalam wadah. beri garam dan lada sedikit. masukan tahu putih yg sdh dihancurkan. boleh juga dipotong2 kotak biasa. tambahkan daun bawang. dadar melebar sampai matang\", \"Ulek cabe, bawang putih, dan terasi. tambahkan kacang tanah. ulek sampe halus.sesekali ditambah air supaya agak encer. terakhir masukkan kecap. tes rasa, klo dirasa kurang kecap, tambahin lagi.\", \"Cara penyajian : nasi diatas piring, tarus tahubtelur diatasnya. siram dengan bumbu kacang. kemudian taburi dengan tauge yg sdh direbus setengah matang. taburi sledri dan bawang goreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1577, 4, 'Kari tahu dan telur', 'Olahan telur sederhana: Kari tahu dan telur yang mudah dibuat.', '[\"Tahu 6/7buah (potong 2 mnjd segitiga)/sesuai selera\", \"4 buah Telur\", \"2 buah Kara\", \"secukupnya Bumbu kari indofood\", \"2 lembar daun salam\", \"1 Sereh\", \"1/2 jempol Laja(laos)\", \"2 lembar daun jeruk\", \"1 sdt gula\", \"2 sdt garam\", \"Bumbu halus:\", \"1 kemiri\", \"3 bawang putih\", \"2 cm kunyit\", \"7 bawang merah\", \"2 cabe merah besar (sesuai selera)\", \"8 Cabe rawit (sesuai selera)\"]', '[\"Rebus telur hingga matang lalu kupas sisihkan\", \"Goreng tahu hingga matang, sisihkan\", \"Tumis (bumbu halus, salam, sereh, laos, daun jeruk) hingga aroma wanginya tercium. Sisihkan\", \"Didihkan air di panci, lalu masukan tumisan yg tadi\", \"Masukan tahu dan telur ke dalam panci\", \"Masukkan kara dan bumbu indofood aduk hingga merata\", \"Masukkan gula dan garam\", \"Koreksi\", \"Kari tahu dan telur siap disajikan 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1578, 3, 'Telor ceplok asam jawa', 'Olahan telur sederhana: Telor ceplok asam jawa yang mudah dibuat.', '[\"3 buah telur;boleh lebih\", \"1 buah tomat\", \"3 buah bawang putih\", \"3 buah bawang merah\", \"3 btg cabe\", \"Daun bawang\", \"3 sdm air asam jawa\", \"secukupnya Garam gula dan penyedap\"]', '[\"Ceplok telor sampai garing,sisihkan\", \"Tumis duo bawang dan cabe sampai harum kemudian masukan air asam jawa, tambahkan garam gula dan penyedap rasa koreksi rasa\", \"Masukan tomat dan telor, sajikan dengan taburan daun bawang\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1579, 3, 'Telor Ceplok Bumbu Pedas', 'Resep Telor Ceplok Bumbu Pedas ala rumahan yang dijamin menggugah selera.', '[\"5 butir telor, Ceplok kasih garem dikit\", \"2 sdm Bumbu Dasar merah, scroll aja bu, Ada diresep cookpad akuu\", \"2 siung bawang putih\", \"3 siung bawang merah\", \"3 bh rawit merah\", \"Daun Salam, daun jeruk\", \"1 sdt Minyak wijen\", \"2 sdm Minyak goreng\", \"bila suka Garam, gulpas, penyedap\", \"Sedikit merica bubuk\", \"sedikit Air\"]', '[\"Iris tips, duo bawang rawit\", \"Panaskan wajan, tuang minyak. Tumis urusan duo bawang sampai harum. Masukkan daun jeruk, daun Salam, rawit.\", \"Masukkan Bumbu Dasar merah. Aduk Sampai harum. Tuang Sedikit air, garam gulpas penyedap, Minyak wijen,merica bubuk. Tes rasa\", \"Masuukan telor Ceplok, jgn sering diaduk Aduk. Ntar ancur...\", \"Tunggu Sampai meresap bumbunya.. Sajikan hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1580, 2, 'Telur Ceplok Masak Tauco', 'Buat Telur Ceplok Masak Tauco yang nikmat dengan langkah-langkah mudah ini.', '[\"8 butir telur ceplok\", \"3 sdm tauco\", \"1 sdm saus tomat\", \"1 sdm saus sambel\", \"6 siung bawang merah, iris tipis\", \"4 siung bawang putih, iris tipis\", \"2 buah cabe besar hijau, iris serong\", \"15 buah cabe rawit (kepedasan sesuai selera), iris serong\", \"1 buah tomat, potong jadi, 8\", \"secukupnya air\", \"secukupnya garam\"]', '[\"Tumis bawang merah dan bawang putih hingga harum\", \"Masukkan cabe dan tumis kembali hingga layu, tambahkan air\", \"Masukkan tauco, saus sambel dan saus tomat serta garam. aduk rata\", \"Setelah sedikit mendidih koreksi rasa, jika sudah pas masukkan telur ceplok\", \"Masak hingga air susut\", \"Selamat Mencoba ^_*\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1581, 3, 'Telur Ceplok Balado', 'Cara membuat Telur Ceplok Balado yang enak dan praktis untuk keluarga.', '[\"1/2 kg telur ayam\", \"Bahan bumbu balado :\", \"13 cabe keriting merah\", \"8 cabe rawit merah\", \"6 siung bawang merah\", \"3 siung bawang putih\", \"1 buah tomat\", \"1 sdk teh Garam, penyedap rasa,Gula msg2\", \"Minyak Goreng untuk menumis dan menggoreng telur\"]', '[\"Pertama, siapkan penggorengan bisa juga teflon. Tuang minyak goreng secukupnya untuk membuat telur ceplok.\", \"Ceplok 4 telur diatas penggorengan atau teflon. Setelah matang angkat. Ulangi hal tsb seperti yg pertama. Setelah semua matang tiriskan.\", \"Sekarang, siapkan blender masukan semua bahan bumbu balado, lbh bagus pakai minyak goreng (saya pakai minyak) pada saat ingin blender, air juga boleh.\", \"Setelah di blender tumis bumbu balado, siapkan penggorengan, tuang bumbu hasil blender. masukan garam, gula, penyedap rasa ke dalamnya. Lalu tumis sampai keluar minyak. Dan di icip rasanya jika ada yg kurang bisa ditambahkan lagi.\", \"Taruh 8 telur ceplok di piring setelah ditiriskan. Kemudian setelah bumbu balado matang, guyur bumbu ke atas telur. Telur ceplok balado siap di hidangkan.\", \"Semoga dapat membantu bagi pemula yg mau belajar memasak. Karna saya juga pemula.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1582, 2, 'Telur Balado', 'Buat Telur Balado yang nikmat dengan langkah-langkah mudah ini.', '[\"6-8 butir telur ayam, rebus atau di buat mata sapi (saya suka keduanya)\", \"2 lembar daun jeruk\", \"1 batang serai, memarkan\", \"2 mata asam Jawa, beri sedikit air\", \"1-2 sdm gula pasir\", \"secukupnya Garam dan merica\", \"secukupnya Minyak goreng\", \"Bumbu yang dihaluskan:\", \"8 buah cabai merah besar\", \"4 buah cabai rawit merah\", \"2 buah tomat merah\", \"6 butir bawang merah\"]', '[\"Setelah direbus, goreng telur. Sisihkan.\", \"- Di wajan yang sama, panaskan sedikit minyak dan tumis bumbu halus bersama daun jeruk dan serai. Masak sebentar selama 5 menit kemudian bumbuhi dengan garam, gula dan merica secukupnya. Tambahkan air asam.\", \"- Masak sebentar hingga air mulai habis.\", \"- Masukkan telur. Aduk rata. Masak sebentar hingga bumbu meresap.\", \"- Matikan api dan sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1583, 3, 'Telur Gulung Keju', 'Buat Telur Gulung Keju yang nikmat dengan langkah-langkah mudah ini.', '[\"4 butir telur\", \"wortel iris kecil-kecil\", \"1 batang daun bawang iris tipis\", \"1 buah keju slice (potong memanjang)\", \"secukupnya garam\", \"secukupnya kaldu jamur\"]', '[\"Kocok telur bersama semua bahan (kecuali keju).\", \"Panaskan teflon (saya pakai teflon uk 20) dan oleskan sedikit minyak. Lebih baik jika mengoleskan minyaknya dengan tissue agak merata dan tidak terlalu banyak minyak.\", \"Tuang 1 sendok sayur telur dan ratakan diwajan, lalu gulung.\", \"Tambahkan keju slice di atasnya dan lalukan secara berulang (saya hanya buat 3 lapisan saja).\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1584, 4, 'Ca sawi telur', 'Resep Ca sawi telur ala rumahan yang dijamin menggugah selera.', '[\"1 ikat Sawi hijau, potong\", \"1 butir Telur\", \"3 siung Bawang putih, geprek\", \"3 buah Cabai rawit, iris tipis\", \"secukupnya Merica\", \"secukupnya Garam\", \"secukupnya Gula\"]', '[\"Tumis bawang putih hingga harum, tambahkan cabai rawit, tumis hingga layu, tambahkan sedikit air\", \"Tambahkan telur, kocok dan masak hingga telur matang\", \"Bumbui dengan garam, merica dan sedikit gula\", \"Masukkan sawi hijau, dan masak hingga matang\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1585, 3, 'Semur Kecap Tahu Telur', 'Semur Kecap Tahu Telur - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"20 tahu putih (potong 2 segitiga)\", \"6 butir telur (rebus)\", \"2 ruas kayu manis\", \"2 kapulaga\", \"1 bunga lawang\", \"4 lembar daun salam\", \"5 butir kemiri\", \"6 siung bawang merah\", \"5 siung bawang putih\", \"1 ruas jahe\", \"2 ruas laos\", \"1/2 sdt merica\", \"1/2 sdt pala bubuk\", \"Sejumput adas manis\", \"1/2 ketumbar\", \"2 cengkeh\", \"1 sdm gula pasir\", \"1/2 sdt garam\", \"Penyedap masakan (optional)\", \"Kecap manis\", \"Air mineral\", \"Minyak sayur\"]', '[\"Rebus telur sampai matang. Kupas kulitnya. Sisihkan.\", \"Kupas kentang. Cuci bersih. Potong-potong sesuai selera. Goreng hingga setengah matang. Sisihkan.\", \"Potong tahu jadi 2 (me: segitiga). Goreng sebentar. Sisihkan.\", \"Haluskan bawang merah, bawang putih, kemiri, jahe, laos, adas manis, kapulaga, pala, merica, dan ketumbar.\", \"Panaskan minyak sayur. Tumis bumbu yang sudah dihaluskan tadi hingga harum. Masukkan daun salam, kayu manis, dan bunga lawang. Tumis hingga bumbu matang.\", \"Setelah bumbu matang. Tambahkan air mineral. Dikira-kira saja. Jangan terlalu sedikit, dan jangan terlalu banyak.\", \"Masukkan kecap, gula, garam, dan penyedap masakan. Koreksi rasa.\", \"Jika airnya sudah hampir mendidih, masukkan kentang, telur, dan tahu putihnya. Aduk-aduk pelan hingga tercampur.\", \"Tunggu hingga mendidih. Koreksi rasa.\", \"Jika sudah matang. Angkat, sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1586, 4, 'Telor Penyet Sambel Geprek', 'Cara membuat Telor Penyet Sambel Geprek yang enak dan praktis untuk keluarga.', '[\"1 butir telor ayam\", \"3 lembar selada air (opsional)\", \"5 buah kerupuk (opsional)\", \"2 buah cabe rawit\", \"2 buah cabe merah\", \"1 buah bawang putih\", \"Garam\", \"Minyak\"]', '[\"Goreng telur seperti biasa, beri garam secukupnya dan bagian kuning di orek2 (sengaja biar kuningnya merata)\", \"Goreng bahan sambal\", \"Cuci bersih selada air, potong sedang\", \"Haluskan sambel, diuleg lebih mantep, beri garam secukupnya\", \"Tambahkan telor dipenyet, selada air dipenyet dan tambahkan kerupuk\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1587, 4, 'Telur Tumis Kecap', 'Buat Telur Tumis Kecap yang nikmat dengan langkah-langkah mudah ini.', '[\"3 telur ayam\", \"2 baw.merah\", \"2 baw.putih\", \"1 cabai merah\", \"3 cabai rawit\", \"1/2 tomat merah\", \"2 sdm kecap manis\", \"1 sdm kecap asin\", \"sedikit merica\"]', '[\"Goreng telur ayam (diceplok) kemudian sisihkan\", \"Tumis bumbu iris dengan sedikit minyak kemudian tunggu harum\", \"Masukkan telur dan kecap manis+kecap asin+merica\", \"Masak hingga kecap meresap pada telur\", \"Angkat dan sajikan dengan nasi hangat 😉\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1588, 3, 'Tahu Telur Kubis Bumbu Kecap', 'Nikmati kelezatan Tahu Telur Kubis Bumbu Kecap dengan resep sederhana ini.', '[\"1 buah tahu putih\", \"3 butir telur ayam\", \"1 genggam kubis\", \"3 siung bawang putih\", \"4 siung bawang merah\", \"1 buah cabe merah\", \"4 buah cabe rawit(biarkan utuh)\", \"secukupnya Garam, gula, merica bubuk, penyedap\", \"Kecap manis\"]', '[\"Cincang halus bawang merah dan bawang putih, iris tipis cabe merah, dan biarkan utuh cabe rawitnya\", \"Potong tahu sesuai selera lalu goreng hingga matang\", \"Goreng telur satu persatu buat telur mata sapi\", \"Tumis semua bumbu yang sudah dicincang hingga harum\", \"Masukkan kubis yang sudah diiris, tumis hingga layu\", \"Setelah itu masukkan tahu dan telur,aduk hingga rata\", \"Tambahkan sedikit air, kecap, garam, gula, merica, penyedap, aduk hingga rata\", \"Koreksi rasa, masakan siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1589, 4, 'Telor Gulung Sosis', 'Telor Gulung Sosis - hidangan telur praktis dan lezat.', '[\"2 butir telur\", \"1 buah sosis (ukuran diameter 2cm)\", \"garam\", \"lada\", \"minyak goreng\"]', '[\"Panaskan minyak, lalu goreng sosis dalam ukuran panjang (± 2-3 menit)\", \"Angkat sosis yang sudah di masak\", \"Goreng telur yang sudah di kocok dan telah di campuri garam dan lada\", \"Setelah telur sudah mulai matang, taruh sosis di atas telur lalu di gulung\", \"Biarkan telur yang di gulung tetap pada wajan, lalu goreng telur kembali sebagai layer bawah\", \"Setelah setengah matang, gulung kembali telur dengan telur yang sebelum nya agar menempel harus setengah matang\", \"Angkat telur lalu potong perlahan karena mudah hancur\", \"Telor gulung sosis ready to serve!😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1590, 4, 'Tumis Telur Pasta AB', 'Olahan telur sederhana: Tumis Telur Pasta AB yang mudah dibuat.', '[\"100 gram pasta\", \"3 butir telur\", \"1 lembar daun bawang\", \"1 lembar seledri\", \"2 buah cabai hijau besar\", \"10 buah cabai hijau kecil\", \"2 sdm kecap manis\", \"1 sdt garam\", \"3 sdm sambal terasi ABC\", \"4 buah bawang merah\", \"2 buah bawang putih\", \"4 sdm minyak goreng\"]', '[\"Rebus air sampai mendidih. Masukkan pasta hingga empuk, tiriskan.\", \"Tumis irisan bawang merah-putih, daun bawang, seledri, dan cabe hingga harum. Masukkan telur dan terus dioseng. Masukkan pasta. Aduk hingga warna mulai kecokelatan. Tambahkan sambal terasi ABC dan kecap. Aduk hingga warna merah kecokelatan. Angkat. Sajikan selagi hangat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1591, 2, 'Telur Bumbu Bali', 'Olahan telur sederhana: Telur Bumbu Bali yang mudah dibuat.', '[\"secukupnya telur yang telah direbus, lalu goreng (saya pakai 4 butir)\", \"2 lembar daun jeruk (buang tulang daunnya)\", \"1 batang serai (memarkan)\", \"50 ml air\", \"secukupnya garam, kaldu bubuk rasa ayam & gula merah\", \"secukupnya minyak untuk menumis\", \"bumbu halus :\", \"6 siung bawang merah\", \"3 siung bawang putih\", \"10 pcs cabe merah keriting\", \"secukupnya terasi goreng\", \"1 ruas jahe\"]', '[\"Tumis bumbu halus bersama daun jeruk & serai hingga harum & matang. Tambahkan garam,kaldu bubuk & gula merah.\", \"Masukkan telur. Aduk aduk. Koreksi rasa\", \"Tuang air. Masak hingga matang & air menyusut.\", \"Telur Bumbu Bali siap disajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1592, 4, 'Telur dadar ala rm padang', 'Olahan telur sederhana: Telur dadar ala rm padang yang mudah dibuat.', '[\"3 butir telur bebek\", \"1 butir telur ayam\", \"1/2 sdt tepung terigu\", \"Secukupnya daun bawang\", \"5 siung bawang merah\", \"7 buah cabai rawit merah dan cabai merah keriting\", \"Secukupnya garam, minyak goreng\"]', '[\"Haluskan cabai dengan garam. Masukkan ke dalam wadah yang sudah terisi telur, daun bawang dan bawang merah. Tambahkan terigu, kocok. Koreksi rasa.\", \"Goreng telur kedalam teflon yang sudah terisi minyak panas dan agak banyak. Tunggu hingga 1 sisi matang. Setelah salah satu sisi matang, pindahkan ke dalam wajan / penggorengan lain. Buat agar sisi yang lain / di dasar penggorengan. Goreng lagi hingga matang.\", \"Setelah matang, angkat dan potong sesuai selera.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1593, 3, 'Mie goreng sosis telur', 'Nikmati kelezatan Mie goreng sosis telur dengan resep sederhana ini.', '[\"1 bungkus mie AA\", \"1 bh sosis ayam/ sapi (sesuai selera)\", \"2 butir telur (orak orik)\", \"4 siung bawang putih (geprek cincang halus)\", \"Sejumput garam\", \"Sejumput gula pasir\", \"1/2 sdt kaldu jamur /royco ayam\", \"1 sdt kecap ikan\", \"secukupnya Lada\", \"Kecap manis\", \"1 sdm sambal botol (boleh skip)\", \"150 ml air\"]', '[\"Rebus mie (beri sedikit minyak dan garam saat merebus) tiriskan\", \"Tumis bawang putih sampai harum, masukkan sosis aduk rata, masukan telur orak arik.\", \"Masukan kaldu jamur, kecap ikan, lada, gula pasir, garam, sambal botol, kecap manis, kasih air aduk rata sampai mendidih\", \"Masukan mie, aduk2 hingga rata tercampur dan kering, koreksi rasa...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1594, 3, 'Telur Korea', 'Cara membuat Telur Korea yang enak dan praktis untuk keluarga.', '[\"3 butir telur\", \"2 daun bawang\", \"Secukupnya kubis/kol\", \"Secukupnya wortel\", \"Sejumput garam\", \"Secukupnya minyak\", \"Teflon anti lengket\"]', '[\"Iris halus kol,daun bawang,dan wortel(diparut aja bunda) sisihkan.\", \"Pecahkan telur lalu kocok lepas hingga menyatu,masukan garam,dab sayuran,aduk rata.\", \"Panaskan teflon dgn api kecil,tuang minyak dan sapu menggunakan tisu.\", \"Masukan 1 sendok sayur,ratakan pada teflon,jika kurang bnyak boleh ditambah lebih dari ukuran sendok.ratakan dan biarkan matang bagian bawah.\", \"Gulung telur namun jangan sampai habis,sisakan sedikit pada bagian ujung.\", \"Tambahkan telur,ratakan,biarkan matang kembali bagian bawah,lakukan hingga adonan habis,d ab biarkan matang merata dgn cara di bolak balik.\", \"Angkat dan dinginkan sejenak,potong..siap di hidangkan.😊😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1595, 4, 'Telur Teri Balado Hijau', 'Resep Telur Teri Balado Hijau yang lezat dan mudah dibuat di rumah.', '[\"5 telur rebus\", \"Sejumput teri\", \"Daun jeruk\", \"Bumbu halus:\", \"Cabe hijau\", \"Cabe rawit\", \"Bawang merah\", \"sedikit Bawang putih\"]', '[\"Goreng telur yang telah direbus. Juga terinya lalu sisihkan\", \"Tumis cabe yang telah dihaluskan sampai matang. Jangan lupa daun jeruk, garam, dan penyedap sesuai selera\", \"Lalu masukkan telur dan teri yang telah di goreng.\", \"Aduk rata dan siap di hidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1596, 3, 'Balado telur bulat', 'Balado telur bulat - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1/2 kg telur ayam\", \"10 buah cabai merah keriting\", \"5 buah cabai rawit merah(kalau suka pedas boleh di tambahkan)\", \"2 buah tomat\", \"4 siung bawang merah\", \"4 siung bawang putih\", \"Secukupnya gula merah\", \"Secukupnya garam\", \"Penyedap rasa\"]', '[\"Rebus telur ayam 15menit-20menit,buang air rebusan lalu ganti dengan air dingin agar mudah untuk mengupas kulitnya.\", \"Ulek semua bumbu.\", \"Goreng telur ayam,jangan terlalu lama ini hanya untuk mendapatkan tekstur berkulit saja😉😉.\", \"Panaskan minyak masukan bumbu yang sudah di ulek tunggu sampai harum,lalu masukan telur,cek rasa.\", \"Balado telur bulat siap di sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1597, 4, 'Bihun Goreng Tabur Telur', 'Nikmati kelezatan Bihun Goreng Tabur Telur dengan resep sederhana ini.', '[\"1 Bungkus Bihun Jagung yang sudah di rebus\", \"10 Buah Bawang Merah\", \"5 Buah Bawang Putih\", \"1 Sachet Lada Bubuk\", \"1 Bungkus Penyedap Rasa\", \"secukupnya Garam\", \"secukupnya Kecap\", \"secukupnya Sawi Hijau\", \"secukupnya Daun Bawang\", \"Minyak secukupnya (untuk menumis)\", \"Telur Dadar secukupnya (untuk hiasan)\"]', '[\"Haluskan bawang merah dan bawang putih\", \"Lalu tumis bahan yang sudah dihaluskan\", \"Setelah itu beri sedikit air dan masukan kecap dan semua bumbu\", \"Masukan bihun yang sudah direbus dan sayuran\", \"Aduk hingga merata\", \"Setelah itu buat telur dadar lalu dipotong memanjang\", \"Sajikan bihun diatas piring dan beri taburan telur\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(1598, 2, 'Nasi Goreng Komplit (Sosis, Bakso Ikan dan Telor Ceplok)', 'Nasi Goreng Komplit (Sosis, Bakso Ikan dan Telor Ceplok) - hidangan telur praktis dan lezat.', '[\"1 porsi nasi putih\", \"2 siung bawang merah cincang\", \"1 siung bawang putih cincang\", \"3 bh cabai merah keriting\", \"3 bh cabai rawit\", \"1 bh sosis sapi\", \"3 bh bakso ikan\", \"Irisan kol\", \"1 butir telur\", \"Daun bawang\", \"1 sdm saori saos tiram\", \"2 sdm kecap manis\", \"1/2 sdt saos raja rasa\", \"1 sdt garam\", \"1 sdt royco\"]', '[\"Ceplok telur terlebih dahulu sisihkan, kemudian goreng sosis dan bakso yang sudah dicuci dan dipotong sesuai selera angkat dan sisihkan\", \"Tumis bawang merah, bawang putih dan cabai sampai harum. Kemudian masukkan nasi putih, sosis dan bakso ikan lalu aduk rata\", \"Tambahkan kecap, saori, saos raja rasa, garam, dan royco. Jangan lupa masukkan daun bawang. Aduk rata\", \"Setelah dirasa enak sajikan ke piring, jangan lupa telor ceplok, irisan kol dan taburi bawang goreng\", \"Selamat Mencoba 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1599, 3, 'Ati Ampela plus telur sambel tomat', 'Ati Ampela plus telur sambel tomat - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1/4 kg ati ampela ayam\", \"2 butir telur\", \"2 buah tomat (iris kecil memanjang)\", \"Bumbu halus:\", \"4 siung bawang merah\", \"2 siung bawang putih\", \"5 buah cabe merah\", \"Garam\", \"Gula\"]', '[\"Pecahkan telur, kocok kemudian dadar.\", \"Rebus ati ampela, kemudian tiriskan dan goreng\", \"Potong-potong sesuai selera ati Ampela dan telur dadar.\", \"Haluskan bumbu: garam, bawang merah, bawang putih, dan cabe merah\", \"Panaskan minyak goreng dan tumis bumbu halus serta tomat yg telah diiris\", \"Masukkan ati ampela dan telur\", \"Cek rasa, jika pas maka siap disajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1600, 4, 'Tumis (BTW) buncis telur wortel', 'Buat Tumis (BTW) buncis telur wortel yang nikmat dengan langkah-langkah mudah ini.', '[\"1 bngkus buncis\", \"2 buah wortel (d potong korek api trus d rebus)\", \"1 telur\", \"3 cabe merah\", \"1 bawang bombay\", \"3 bawang putih\", \"3 bawang merah\", \"Saos tiram secukupny\", \"Kecap secukypnya..(aq lbih sk pke kecap dikit)\"]', '[\"Tumis bumbu yg sudah di iris seperti cabe, bawang bombay, bawang putih, bawang merah.\", \"Sisihkan lalu orak arik telur\", \"Campur semua sayuran(wortel d rebus dulu ya), telur orak arik n bumbu yg sdah d tumis.\", \"Beri saos tiram n air sedikit, masak sampai matang\", \"Cek rasa, klo sudah matang angkat\", \"Sajikan selagi panas, krena ad telur klo sdah dingin jd agak amis,\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1601, 3, 'Sandwich isi telor dadar', 'Sandwich isi telor dadar - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"2 lembar roti gandum\", \"1 butir telor\", \"1 set saos\", \"1 sdm margarin\"]', '[\"Oleskan margarin ke roti gandum dua sisi\", \"Bakar/garang di teplon sampai warna kecoklatan\", \"Tambahkan telor dadar kasih saos di tengah\", \"Sandwich isi telor dadar siap di sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1602, 3, 'Telur pindang', 'Olahan telur sederhana: Telur pindang yang mudah dibuat.', '[\"10 btr telur, rebus lalu kupas dari kulit\", \"2 teh celup\", \"3 Sdm gula merah sisir\", \"2 Sdm kecap manis\", \"2 Sdm gula\", \"Segenggam kulit bawang merah\", \"Daun salam\", \"Serai geprek\", \"secukupnya Garam\", \"secukupnya Penyedap rasa\", \"500 ltr air\"]', '[\"Rebus telur bersama bahan bahan yang ada, sampai air menyusut.\", \"Angkat dan sajikan untuk orang orang tersayang 😍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1603, 2, 'Telur Kukus Praktis dan Sehat', 'Resep Telur Kukus Praktis dan Sehat ala rumahan yang dijamin menggugah selera.', '[\"1/2 bulatan kol\", \"2 batang daun bawang\", \"2 batang seledri\", \"secukupnya royco ayam\", \"2 butir telur\", \"secukupnya lada hitam bubuk\"]', '[\"Panaskan air untuk mengkukus\", \"Cuci semua bahan hingga bersih\", \"Potong kol, daun bawang, dan seledri halus dan tipis (agar saat dikukus tidak retak).\", \"Kocok telur dan masukan royco ayam dan lada bubuk. aduk rata\", \"Masukan potongan sayur tadi ke adonan telur dan aduk sampai menjadi satu.\", \"Beri minyak pada cetakan kukusan dan ratakan keseuluh bagian dalam cetakan. (dikit saja hanya untuk melapisi agar saat kukusan ingin diangkat tidak lengket)\", \"Masukan adonan ke cetakan dan kukus kurang lebih 30 menit.. (tips: tusukan lidi/pisau kecil untuk mengetahui apakah kukusan sudah matang)\", \"Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1604, 4, 'Orak arik telur endolita', 'Olahan telur sederhana: Orak arik telur endolita yang mudah dibuat.', '[\"8 siung bawang merah (sengaja agak banyak biar tambah sedeep)\", \"5 buah cabe rawit\", \"1 buah tomat merah kecil\", \"2 sdm udang kering/rebon\", \"2 butir telur ayam\", \"Garam/masako\", \"1 sdt gula pasir\"]', '[\"Kocok telur dan bikin orak arik, sisihkan\", \"Iris bawang, cabe dan tomat\", \"Tumis bahan yg diiris hingga layu dan harum\", \"Masukkan udang kering/rebon aduk sebentar lalu masukkan telur yg sdh diorak arik tadi, kmudian kasih garam/masako secukupnya dan trakhir gula pasir, aduk2 rata, jangan lupa tes rasa.\", \"Siap utk disajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1605, 3, 'Telor kecap', 'Sajian Telor kecap yang praktis dan lezat untuk dinikmati bersama.', '[\"5 butir telor atau lebih rebus kupas\", \"100 gr gula pasir\", \"3 sdm kecap\", \"500 ml air panas\"]', '[\"Panaskan gula pasir dgn teflon sampai berbuih/coklat karamel(jgn diaduk ya dan apinya kecil aja)..setelah itu tuang airnya.masukkan telor dan kecap.sampai warna yg diinginkan.angkat masak sesuai keinginan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1606, 3, 'Telor Dadar Sayuran', 'Nikmati kelezatan Telor Dadar Sayuran dengan resep sederhana ini.', '[\"2 butir telor ayam\", \"1 batang kecil wortel\", \"8 batang buncis\", \"2 batang kecil daun bawang pre (kalo besar 1 aja)\", \"1 batang seledri\", \"1/2 siung kecil bawang bombay\", \"4 buah cabe rawit\", \"Secukupnya merica\", \"Secukupnya garam atau kaldu bubuk\", \"Secukupnya minyak goreng\"]', '[\"Persiapkan bahan2nya, kemudian cuci bersih.\", \"Potong2 bahan sesuai selera. Saya sarankan iris tipis saja, supaya sayurnya cepat matang dan tidak langu. Wortelnya saya parut kasar.\", \"Masukkan 2 butir telor, garam/kaldu bubuk, dan merica kemudian aduk rata. Jangan takut isinya kebanyakan/telurnya kurang. Awalnya memang terlihat seperti kurang telornya, tapi terus diaduk saja sampe sayur2nya agak lemas dan adonan sesuai😄 saya mengaduk sekitar 4-5 menit.\", \"Panaskan wajan/teflon.. tuangkan sedikit minyak goreng. Masukkan adonan telor dadar. Masak dengan api kecil saja biar matangnya merata. Jangan dibalik kalo bawahnya belum bener2 matang ya. Karena kalo blm bener2 matang ntar hancur pas dibalik. Kemudian masak sisi baliknya hingga matang. Jadi deh, yuuuk cobain☺️😊\", \"Ini hasilnya kalo udah matang. Agak gosong dikit karena tadi saya tinggal bentar. Hehehe, yang penting rasanya☺️😆\", \"Saya potong jadi 4 bagian. Lumayan bisa buat makan seharian (anak kos hemat☺️)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1607, 2, 'Ca Telur Sayur', 'Ca Telur Sayur - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"~ Bahan utama\", \"3 bh telur, kocok, tambah 1 sdm kecap asin\", \"1 bh wortel, serut kasar\", \"1/4 bh kol, iris agak halus\", \"1 ikat kecil kucai, iris kasar\", \"~ Bumbu :\", \"500 ml air\", \"1/2 bh bombay, iris\", \"2 sdm kecap asin (sy lee kum kee)\", \"1 sdm minyak wijen\", \"1 sdm garam\", \"1/2 sdt merica bubuk\", \"1/2 sdt kaldu jamur\"]', '[\"Tumis bombay dengan minyak plus minyak wijen hingga matang.\", \"Tambahkan air. didihkan.\", \"Masukkan sayuran. plus bumbu.\", \"Tuang telur kocok. didihkan. koreksi rasa. matikan api.\", \"Masukkan kucai. aduk rata.\", \"Hidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1608, 2, 'Telor dadar sambel pete', 'Cara membuat Telor dadar sambel pete yang enak dan praktis untuk keluarga.', '[\"2 butir telur ayam\", \"1 papan pete\", \"2 batang daun bawang\", \"Secukupnya garam\", \"Secukupnya royco\", \"Sedikit minyak goreng\", \"Bumbu halus\", \"4 siung bawang merah\", \"2 siung bawang putih\", \"3 buah cabe rawit\", \"3 buah cabe merah\", \"1 buah tomat\", \"1/4 gandu gula merah\"]', '[\"Panaskan minyak. Iris tipis daun bawang, campurkan pada telur. Tambahkan penyedap rasa lalu kocok.\", \"Masukan telur kocok tadi ke penggorengan. Setelah matang angkat, potong sesuai selera, sisihkan.\", \"Uleg bumbu halus. Panaskan sedikit minyak. Masukan penggorengan tambahkan pete, penyedap dan garam oseng oseng sebentar.\", \"Siramkan sambel pete diatas telur dadar. Sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1609, 4, 'Pindang tongkol selimut telur', 'Pindang tongkol selimut telur - hidangan telur praktis dan lezat.', '[\"5 ptg pindang tingkol\", \"1 btr telur\", \"Sejumput garam\", \"Secukupnya minyak goreng\"]', '[\"Kocok lepas telur tambahkan sejumput garam masukan ikan tongkol lalu goreng hingga kuning keemasan angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1610, 4, 'Tahu Telor Sambal Kecap', 'Resep Tahu Telor Sambal Kecap ala rumahan yang dijamin menggugah selera.', '[\"1 kotak tahu putih\", \"1 butir telor ayam\", \"Tauge\", \"Seledri\", \"Bawang goreng\", \"3 siung bawang merah\", \"5 siung bawang putih\", \"secukupnya Garam\", \"8 cabai rawit hijau\", \"Kecap manis\"]', '[\"Potong tahu kecil2. Lalu goreng. Boleh matang boleh setengah matang. Sesuai selera. Sisihkan.\", \"Kocok telur. Lalu buat orak-arik. Sisihkan.\", \"Siapkan cobek. Ulek bawang putih, bawang merah, cabai dan garam sampai halus. Tuang kecap manis lalu aduk rata.\", \"Masukkan tahu goreng dan telor ke cobek kemudian aduk hingga rata. Masukkan tauge yg sudah dicuci. Aduk kembali.\", \"Taburkan seledri dan bawang goreng diatasnya. Sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1611, 3, 'Cah Wortel Kubis Telur', 'Buat Cah Wortel Kubis Telur yang nikmat dengan langkah-langkah mudah ini.', '[\"3 butir telur\", \"2 buah wortel ukuran sedang\", \"1/4 sayur kubis ukuran sedang\", \"1 helai daun bawang\", \"1 buah tomat ukuran sedang\", \"Bumbu:\", \"4 siung bawang putih iris tipis\", \"3 siung bawang merah iris tipis\", \"3 buah cabe rawit iris tipis\", \"1/4 ketumbar bubuk\", \"secukupnya Garam dan gula\", \"bila perlu Penyedap rasa\"]', '[\"Orak arik telur dan masukkan bumbu dan oseng hingga harum\", \"Masukkan air 1 gelas blimbing dan masukkan wortel yang telah diiris tipis memanjang\", \"Kemudian tunggu hingga mendidih dan masukkan kubis yang telah dipotong kecil kecil dan kemudian masukkan tomat yang diiris tipis dan daun bawang iris tipis campur semua\", \"Tunggu hingga sayur sedikit layu sambil koreksi rasa bila sudah pas siap disajikan. Siap dinikmati dengan nasi hangat biar lebih kenyang heheh 😄\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1612, 2, 'Balado terong, telur, teri & kentang', 'Resep praktis Balado terong, telur, teri & kentang yang bisa dicoba di rumah.', '[\"1 buah terong ungu\", \"1 buah kentang\", \"5 butir telur ayam\", \"1/2 ons teri\", \"1 ons cabe merag keriting\", \"10 pcs cabe rawit merah\", \"5 pcs bawang merah\", \"1 pcs tomat\", \"Jeruk nipis (sedikit saja)\", \"Garam\"]', '[\"Belah terong menjadi 2 bagian lalu potong kecil2, dan kupas kulit kentang dan potong sesuai keinginan\", \"Rebus telur bulat sampai matang\", \"Goreng berturut2 kentang, terong, telur & teri di minyak panas 1-1 ya jgn sekaligus\", \"Ulek kasar cabe merah keriting, cabe rawit merah, bawang, tomat dan garam\", \"Kemudian tumis cabe yg sudah di ulek tadi kemudian masukan jeruk nipis tumis smpai harum, kemudian masukan terong, kentang, teri & telur yang sudah d goreng tadi\", \"Masakan siap d sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1613, 2, 'Tumis telur pete', 'Cara membuat Tumis telur pete yang enak dan praktis untuk keluarga.', '[\"1 papan pete\", \"3 ptg tahu goreng\", \"1 btr telur\", \"1 siung bawang putih\", \"3 siung bawang merah\", \"1 btg daun bawang\", \"1/2 bh tomat\", \"2 sdm kecap manis\", \"1 sdm saus tiram\", \"1 sdt kaldu bubuk\", \"Secukupnya minyak goreng\", \"Secukupnya air\"]', '[\"Panaskan minyak lalu tumis bawang merah dan bawang putih yg sdh di iris2 lalu masukan pete tumis hingga harum lalu masukan telur kemudian aduk telur jd orak arik masukan air,kecap manis,saus tiram,kaldu bubuk dan tahu goreng aduk rata terakhir masukan potongan daun bawang dan tomat jgn lupa tes rasa lalu angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1614, 3, 'Tumis kolor ijo (kol telor cabe ijo) 😅', 'Resep Tumis kolor ijo (kol telor cabe ijo) 😅 yang lezat dan mudah dibuat di rumah.', '[\"Kol (iris tipis)\", \"1 butir Telor ()\", \"3 siung Bawang merah ()\", \"2 siung Bawang putih ()\", \"15 buah Cabe ijo (/kalau mau lebih pedas bisa ditambah)\", \"1 buah Tomat ()\", \"secukupnya Garam ()\", \"secukupnya Royco ()\"]', '[\"Rajang bawang merah dan bawang putih, iris serong cabe ijo dan tomat\", \"Panaskan minyak sayur lalu tumis irisan bawang merah, bawang putih dan cabe ijo sampai harum\", \"Lalu masukan telur di orak arik tpi jgn terlalu halus dan masukan kol, garam, royco, dan tomat, masak hingga matang siap disajikan\", \"Selamat mencoba y bunsay☺️\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1615, 4, 'Telur Dadar', 'Resep Telur Dadar ala rumahan yang dijamin menggugah selera.', '[\"2 telur ayam\", \"2 batang daun bawang, iris halus\", \"1 sdm tepung terigu munjung (optional)\", \"Sejumput garam\", \"Sejumput kaldu jamur/ kaldu ayam bubuk (optional)\", \"1 sdm margarin/ minyak goreng\"]', '[\"Kocok lepas telur, masukkan garam, kaldu jamur, dan daun bawang, kocok hingga rata\", \"Panaskan margarin diatas teflon, lalu masukkan kocokan telur, masak hingga matang/ kecoklatan\", \"Angkat, hidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1616, 2, 'Tea Egg/ Telur Pindang', 'Resep praktis Tea Egg/ Telur Pindang yang bisa dicoba di rumah.', '[\"1 T  bumbu ngo hiang/ all spice\", \"2 T  Kecap Hitam\", \"2 pods Cabe kering/Dried Chilly\", \"2 T  Daun Teh/ Tea Leaves\", \"1/2 cup bawang bombay potong/ sliced onion\", \"3 pods  Anise\", \"12 telur/eggs\", \"4 cups of water\", \"1 t  garam himalaya/ himalayan salt\"]', '[\"Campur semua bumbu dengan air, masukkan telur, didihkan 10 menit. Pastikan air menutupi telur. Stir all ingredients in a pot with water, add eggs, boil for 10 minutes. Make sure the water covers the eggs.\", \"Ketuk kulit telur sampai retak2. Tap around the egg shells with hard spoon until it crack.\", \"Kecilkan api, rebus lagi selama 10 menit, tinggalkan telur di dalam air tebusan semalaman di dalam kulkas. Simmer the egg for another 10 minutes, refrigerate leave overnight.\", \"Selamat menikmati! Enjoy the egg!\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1617, 2, 'Tumis buncis telur', 'Tumis buncis telur - hidangan telur praktis dan lezat.', '[\"Buncis diiris tipis\", \"1-2 butir telur\", \"3-4 siung bawang putih digeprek/diiris\", \"Garam\", \"Lada\", \"Gula pasir/penyedap\"]', '[\"Siapkan bahan\", \"Tumis bawang putih sampai harum matang\", \"Masukkan telor ayam kemudian diorak-arik\", \"Masukkan buncis iris, tambahkan garam, lada, penyedap\", \"Masak dgn api kecil, JANGAN ditambah air (krn buncis sudah mengandung air) masak hingga setengah matang atau matang sesuai selera\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1618, 2, 'Orak Arik Telur Sosis', 'Orak Arik Telur Sosis - hidangan telur praktis dan lezat.', '[\"2 butir telur\", \"1 bh sosis sapi/ayam\", \"1 siung bawang putih\", \"2 bh cabai merah keriting\", \"1 bh cabai rawit setan (kalo suka pedes bisa ditambah lg)\", \"Selembar daun bawang\", \"Bahan tambahan :\", \"1 sdt saori saos tiram\", \"1 sdm kecap manis\", \"1 sdt garam\", \"1 sdt merica bubuk\", \"1 sdt penyedap rasa\"]', '[\"Kocok telur, tambahkan garam, penyedap rasa dan merica bubuk\", \"Cincang bawang putih, iris cabai dan sosis menyerong, lalu iris daun bawang\", \"Panaskan minyak diatas wajan, tumis bawang putih, cabai dan sosis sampai aroma harum sisihkan dipinggir\", \"Masukkan kocokan telur orak arik sebentar kemudian tambahkan saori, kecap, sejumput garam dan merica\", \"Terakhir masukkan daun bawang. Sajikan dan nikmati dengan sepenuh hati 🌹\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1619, 4, 'Sambal balado telur bumbu rebus', 'Sambal balado telur bumbu rebus - hidangan telur praktis dan lezat.', '[\"7 telur ayam\", \"5 butir bawang merah\", \"3 butir bawang putih\", \"15 cabai merah\", \"15 cabai rawit hijau\", \"3 buah tomat\", \"1/2 keping gula merah\", \"Secukupnya minyak, garam dan royco\", \"Sedikit air\"]', '[\"Rebus telur hingga matang lalu angkat dan beri air dingin lalu di kupas kulitnya\", \"Goreng telur hingga sedikit coklat jangan lupa di bolak balik agar merata\", \"Rebus cabai merah, cabai rawit, bawang merah, bawang putih dan tomat setelah empuk angkat sisihkan\", \"Haluskan bumbu yang sudah di rebus kalau saya pakai blender\", \"Tumis bumbu masukkan gula merah sisir beri sedikit air di blender agar bersih tidak ada bumbu yang terbuang tumis hingga harum lalu masukkan telur, garam dan royco aduk hingga rata setelah itu angkat dan hidangkan selamat mencoba 😄\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1620, 2, 'Orak-arik telur pete', 'Sajian Orak-arik telur pete yang praktis dan lezat untuk dinikmati bersama.', '[\"3 butir telur ayam\", \"1 papan pete\", \"Bumbu iris:\", \"8 siung bawang merah\", \"5 siung bawang putih\", \"3 buah cabe merah\", \"10 buah cabe rawit\", \"2 lb daun salam\", \"1 ruas lengkuas geprek\", \"1 sdm saus tiram\", \"2 sdm kecap manis\", \"Gula garam\"]', '[\"Tumis bumbu iris hingga wangi lalu tambahkan salam dan lengkuas\", \"Masukkan saus tiram, kecap, dan pete\", \"Tambahkan air hingga mendidih\", \"Beri gula dan garam sesuai selera (boleh ditambah kaldu bubuk)\", \"Masukkan telur, lalu orak-arik hingga telihat agak menggumpal, tes rasa, sajikan hangat dengan nasi putih\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1621, 3, 'Balado telur ceplok dan pindang salem', 'Resep praktis Balado telur ceplok dan pindang salem yang bisa dicoba di rumah.', '[\"2 pindang salem\", \"4 telur\", \"6 siung bawang merah\", \"3 siung bawang putih\", \"3 butir kemiri\", \"11 cabe keriting (pnjng kira kira 10-15cm)\", \"1 butir tomat\", \"1/3 sdt garam (sesuaikan rasa)\", \"1,4 sdt gula (sesuaikan rasa)\", \"Sedikit royco\", \"Secukupnya air (100-130ml)\", \"Secukupnya minyak goreng untuk menumis\"]', '[\"Cuci bersih pindang, goreng. Goreng telur diceplok. Haluskan, bawang, cabe, kemiri.\", \"Tumis bumbu sampai harum masukan irisan tomat tumis, masukan air tunggu sampai mendidih lalu masukkan telur dan pindang. Masak sampai bumbu meresap. Sajikan\", \"Balado telur ceplok pindang salem sudah siap.. mantapp dech..\", \"Selamat mencoba..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1622, 4, 'Telur Ceplok Tauco', 'Resep Telur Ceplok Tauco ala rumahan yang dijamin menggugah selera.', '[\"6 butir telur\", \"6 butir bawang merah, iris\", \"3 siung bawang putih di iris\", \"4 Cabe keriting hijau, iris\", \"5 Cabe rawit, iris\", \"1 Buah tomat, Iris\", \"2 Sdm Tauco\", \"secukupnya Kecap manis, K. asin,gula,air\"]', '[\"Buat telur ceplok mata sapi, sisihkan\", \"Tumis bawang merah, bawang putih, cabe dan tomat sampai layu dan harum\", \"Tambahkan tauco, kecap manis, kecap asin, sedikit gula dan air secukupnya\", \"Masukan telur. Cicipi. Jika kurang asin tambahkan garam, kecap asin masak sampai mendidih dan kuah meresap ke telur\", \"Angkat dan sajikan...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1623, 3, 'Menu diet kentang dan telur tamagoyaki', 'Buat Menu diet kentang dan telur tamagoyaki yang nikmat dengan langkah-langkah mudah ini.', '[\"1 kentang ukuran sedang\", \"2 telur ayam\", \"2 cabai rawit\", \"2 batang sayur hijau\", \"1 sosis\", \"3 sendok makan garam\", \"1 sendok makan origanic\", \"2 sendok makan merica\", \"2 sendok makan minyak goreng/ zaitun (untuk diet)\"]', '[\"Kentang 👉 kupas 1 kentang lalu potong memanjang, iris seperti bentuk kentang di atas, rendam di air bersih selama 5-10 menit, lalu rebus kentang dan berikan 2 sendok makan garam dan 2 sendok makan merica serta origanic kedalam rebusan tersebut dengan waktu rebusan 10-15menit dengan api sedang (hingga matang)\", \"Telur 👌 potong sosis dengan ukuran tipis, dan cabai rawitnya, jika menyukai sayur bisa di pakai sayur hijau atau wortel di potong tipis dan kecil2, lalu kocok 2 telur dan masukan semua bahan2 nya dan aduk hingga merata\", \"Memasak telur tamagoyaki panaskan kompor dengan api sedang lalu masukan campuran telur tadi sedikit dulu tunggu hingga matang, gulung perlahan sisihkan di pinggir wajan, lalu sambung masukan telur tadi di depan telur pertama tunggu hingga matang lalu gulung kembali, di ulang hingga telur habis dan kematangan telur nya pas\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1624, 3, 'Seblak toge telur', 'Nikmati kelezatan Seblak toge telur dengan resep sederhana ini.', '[\"1 bks toge\", \"1 butir telur ayam\", \"3 siung bawang merah\", \"2 siung bawang putih\", \"1 ruas kencur\", \"5 buah cabe domba (klo ingin pedas bisa di tambah)\", \"Secukupnya merica bubuk\", \"Secukupnya gula pasir\", \"Secukupnya penyedap rasa\", \"2 sdm minyak goreng\", \"1/2 gelas air putih\"]', '[\"Cuci bersih toge dengan air mengalir diamkan\", \"Haluskan bawang merah, bawang putih kencur dan cabe\", \"Panaskan wajan masukan minyak goreng tumis bumbu halus sampai harum masukan toge tumis hingga sedikit layu masukan telur aduk2 sampai merata\", \"Tambahkan air aduk lagi,masukan penyedap rasa, gula pasir dan merica bubuk aduk2 lagi sampai merata\", \"Cicipi takuta ada yg kurang setelah pas tunggu sampai air surut dan seblak togepun siap di hidangkan\", \"Mudahkan cookpedlovers selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1625, 3, 'Tahu telur ala surabaya (siram sambel pecel)', 'Tahu telur ala surabaya (siram sambel pecel) - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 butir telur\", \"1 buah tahu putih\", \"Sejumput garam\", \"Minyak goreng\", \"Pelengkap:\", \"Sejumput toge pendek\", \"Kemangi\", \"Sambel pecel\"]', '[\"Kocok telur dengan garam.\", \"Iris tipis tahu\", \"Panaskan teplon beri minya secukupnya.\", \"Tata tahu di teflon lalu tuang kocokan telur pelan2 (ini tips mudah, kalau tahunya yang dimasukin ke telur nanti susah natanya waktu di masukin ke teplon).goreng dengan api kecil hingga agak kering lalu di balik goreng hingga matang.\", \"Cuci, toge dan kemangi dengan air matang.\", \"Encerkan sambel pecel dengan air hanggat secukupnya.\", \"Sajikan telur dadar tahu, beri toge dan kemagi diatasnya lalu siram sambel pecel.\", \"Bisa di makan sendiri atau sama nasi.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1626, 2, 'Telor sambal', 'Cara membuat Telor sambal yang enak dan praktis untuk keluarga.', '[\"5 butir telur ayam\", \"10 cabe merah (bisa kurang bisa tambah)\", \"3 rawit setan (sesuaikan selera)\", \"5 bawang merah\", \"3 bawang putih\", \"1 Tomat ukuran besar\", \"3 daun jeruk (sobek)\", \"sedikit gula pasir, garam / penyedap (me : indofood magic)\", \"minyak untuk menumis\", \"air es\"]', '[\"Rebus telur sampai matang. buang air rebusan... masukan telur kedalam air es sampai terendam.. ini bertujuan agar telur gampang di kupas dan telurnya mulus tdk gompal gompal..\", \"Goreng sebentar telur yg sudah di kupas biar berkulit..\", \"Goreng bumbu.. cabe merah, rawit, bawang merah bawang putih dan tomat sampe layu.\", \"Ulek kasar bumbu.. || tumis bumbu beserta daun jeruk (minyak utk menumis agak banyak) agar sambal tdk kering.. karena dsni saya tdk menambahkan air.\", \"Tumis sebentar saja. karena pda dasarnya bumbu sudah matang.\", \"Masukan gula dan penyedap. tes rasa.. jika dirasa sudah pas. masukan telur yg sudah di goreng. aduk aduk sebentar. angkat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1627, 3, 'Telur ceplok asam manis', 'Olahan telur sederhana: Telur ceplok asam manis yang mudah dibuat.', '[\"2 telur ceplok (goreng mata sapi)\", \"Bumbu :\", \"1/4 bawang bombai kecil\", \"1 bawang putih kecil\", \"1 sdm mentega\", \"1/2 gelas air\", \"3 sdm saos tomat\", \"1/2 sdt saos tiram\", \"Secukupnya garam\", \"Secukupnya lada\"]', '[\"Cincang bawang bombay dan bawang putih, panakan mentega tumis hingga harum masukan air, saos tomat, saos tiram, aduk2 masak hingga mendidih masukan telur ceplok bumbui garam, lada, dan gula masak hingga kuah kental dan bumbu meresap jangan lupa cicipin.\", \"Siap di sajikan\", \"NB: kalau telur ceplok mau dimasak asem manis di goreng ceploknya tanpa garam / bumbu apapun.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1628, 3, 'Trik Merebus Telur (Rebus 5 Menit Matang)', 'Trik Merebus Telur (Rebus 5 Menit Matang) - hidangan telur praktis dan lezat.', '[\"4 butir telur ayam\", \"150 ml air\"]', '[\"Rebus telur dengan air di wajan teflon (tutup wajan dengan penutupnya)\", \"Rebus dengan api besar selama 2 menit, lalu kecilkan api dan rebus selama 3 menit. Matikan api dengan kondisi wajan masih tertutup rapat. Biarkan selama 9 menit.\", \"Setelah 9 menit, angkat telur, lalu masukkan ke air dingin. (Supaya telur cepat dingin dan mudah dikupas)\", \"Kupas kulit telur. Telur siap disajikan atau diolah lagi sesuai selera.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1629, 3, 'Telur Kecap Ikan', 'Sajian Telur Kecap Ikan yang praktis dan lezat untuk dinikmati bersama.', '[\"1 butir Telur ( pun bisa)\", \"secukupnya Kecap ikan merah ()\", \"1 sdt minyak goreng (per butir telur)\"]', '[\"Panaskan minyak goreng\", \"Ceplok telur dan tunggu hingga setengah matang, kemudian urak arik hingga telur hancur, urak arik hingga matang\", \"Tuang telur yang sudah matang ke mangkuk atau piring, tambahkan kecap ikan, aduk-aduk, beri nasi hangat, siap dinikmati\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1630, 4, 'Telur kornet keto', 'Telur kornet keto - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 sendok cornet sapi\", \"1 butir telur ayam\", \"Cabe / bon cabe\", \"Lada bubuk\", \"Penyedap rasa\", \"Keju chedar\"]', '[\"Bumbui kornet terlebih dahulu dengan penyedap rasa dan lada\", \"Goreng dengan api sedang\", \"Kocok telur lalu bumbui Dengan penyedap rasa\", \"Tambahkan irisan cabe\", \"Goreng telur dengan kornet lalu orak arik / sesuai selera\", \"Setelah kecoklatan kornet dan telur matang tiriskan\", \"Siap di hidangkan dengan parutan keju chedarr\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1631, 2, 'Oseng bayam telur', 'Nikmati kelezatan Oseng bayam telur dengan resep sederhana ini.', '[\"1 butir telur\", \"1 ikat bayam\", \"1 buah tomat (potong)\", \"1 buah bawang merah (iris)\", \"1 bawang putih (cincang)\", \"Sejumput garam\", \"Sejumput kaldu jamur\", \"Minyak kelapa\"]', '[\"Goreng bawang merah dengan sedikit minyak kelapa, masukkan tomat, tunggu hingga sedikit layu, masukkan telur, aduk2 hingga matang, tambahkan sedikit garam, pindahkan kedalam piring saji\", \"Tumis bawang putih dengan sedikit minyak kelapa, masukkan bayam, aduk2 hingga layu, gunakan api kecil, dan tambahkan sedikit kaldu jamur\", \"Hidangkan bersama masakan telur sebelumnya\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1632, 3, 'CILOR aci telor ala Bandung', 'Nikmati kelezatan CILOR aci telor ala Bandung dengan resep sederhana ini.', '[\"100 gr tepung tapioka /sagu\", \"100 gr tepung terigu protein sedang\", \"140 ml air mendidih\", \"2 siung bawang putih haluskan\", \"1/4 sdt garam\", \"2 sdt gula pasir\", \"1/4 sdt royco ayam\", \"1/4 sdt lada bubuk\", \"1 butir telur\", \"secukupnya Minyak goreng\", \"Bahan Sambal:\", \"2 sdm sambal kacang instan\", \"1 siung bawang putih\", \"2 cabe rawit\", \"Sejimpit garam\", \"1 sdm gula pasir\", \"1 sdm saus sambal\"]', '[\"Haluskan bawang putih, dngan garam. Siapkan wadah masukkn tepung tapioka dan tepung terigu, masukkn jg bawang putih yg sdh di halus. Tambah royco ayam, lada bubuk, gula pasir. Aduk rata tuangi air mendidih sedikit demi sedikit. Setelah itu uleni sampai kalis. Dan bagi menjadi beberapa bagian, kemudin Piling2 seperti gambar no 3 lakukan sampai adonan habis.\", \"Siapkan panci beri air secukupnya masak sampai mendidih masukkn adonan aci yg sdh di Piling2 tadi masak sampai mengapung. Dan biarkan matang kira2 10 menit angkat tiriskan. Tunggu dingin potong2 sesuai selera kemudian lumuri dng 1 sdm Minyak sayur biar tidak lengket. Seperti gambar no 3. Dan sisih kan.\", \"Kocok lepas telur bumbui dng lada dan garam secukupnya.\", \"Siapkan wajan beri 1 sdm Minyak goreng masukkn aci yg sdh di potong2 tadi goreng dng api kecil saja, sampai kering dan kekuning2an masukkan telur kocok, tunggu 30 detik baru di aduk2. Sampai rata dan matang angkat.\", \"Siapkan sausnya, haluskan cabe dan bawang putih sedikit garam sampai halus masukkn sambal kacang instan, saus cabe,gula pasir beri sedikit air panas aduk rata.\", \"Tuang saus kacang di atas cilor. Dan siap di nikmati. Kalau ada tusukan bisa di tusuk kayak sate 🍢.\", \"CILOR aci dan telor siap di nikmati 👍 selamat mencoba 😘\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1633, 2, 'Egg Salted Fettuccini', 'Egg Salted Fettuccini - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"segenggam Fettuccini\", \"secukupnya minyak\", \"secukupnya garam\", \"secukupnya merica bubuk\", \"1 butir telur\", \"1-2 siung bawang putih\", \"secukupnya keju\", \"1/2 sendok makan mayonaise\", \"2 sendok makan Egg Salted Sauce\", \"1/2 buah tomat\", \"secukupnya daging sapi asap\", \"1-2 batang daun seledri\"]', '[\"Masukan Fettuccini dalam air mendidih dengan secubit garam dan sedikit minyak, hingga al dente, angkat sisihkan\", \"Campur dalam wadah, telur, keju parut, Egg Salted Sauce, mayonaise, merica halus, aduk hingga rata, sisihkan\", \"Geprek dan cincang bawang putih, tumis hingga harum, masukan daging sapi asap yang dipotong kotak kecil hingga warnanya lebih tua, masukan Fettuccini kemudian masukan campuran saus, potongan dadu kecil tomat dan cincangan seledri, aduk rata, angkat😋selamat menikmatiiiiih\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1634, 2, 'Telur ceplok teri bumbu merah ala fe\'', 'Olahan telur sederhana: Telur ceplok teri bumbu merah ala fe\' yang mudah dibuat.', '[\"6 butir telur diceplok\", \"2 sendok makan teri medan digoreng\", \"3 lembar daun jeruk\", \"1 lembar daun salam\", \"Bumbu diulek halus :\", \"5 buah cabe merah\", \"3 siung bawang putih\", \"5 siung bawang merah\", \"3 butir kemiri sangrai\", \"1 buah tomat\", \"1 sendok teh gula\", \"Garam secukupnya jika perlu\"]', '[\"Telur diceplok satu2 tiriskan. Teri digoreng pake sedikit minyak bekas ceplok. Tiriskan & jangan buang minyaknya. Dipakai untuk tumis bumbu.\", \"Tumis bumbu ulek dengan minyak bekas goreng teri, masukkan daun jeruk & daun salam hingga harum. Beri gula pasir.\", \"Masukkan teri goreng & telur ceplok.\", \"Aduk rata & tes rasa. Masak hingga bumbu meresap.\", \"Siap disajikan dengan taburan bawang daun.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1635, 2, 'Tahu Telur Daun Mint', 'Cara membuat Tahu Telur Daun Mint yang enak dan praktis untuk keluarga.', '[\"1 buah tahu ukuran kecil, haluskan dengan garpu\", \"1 buah telur\", \"Segenggam daun mint, rajang kasar\", \"1 buah cabai, iris tipis\", \"1 bawang putih, cincang\", \"1 bawang merah, rajang halus\", \"1/4 lada bubuk\", \"1 sdt garam\", \"1/4 sdt kaldu jamur\", \"3 sdm Minyak goreng\"]', '[\"Siapkan semua bahan, haluskan tahu dg garpu, tambahkan telur, kocok lepas. Tambahkan daun mint dan bumbu lain kecuali minyak.\", \"Panaskan 3 sdm minyak, tunggu hingga panas baru masukkan perlahan, tunggu hingga mulai berkulit baru dibalik. Tunggu hingga matang angkat dan tiriskan, sajikan. Ingat gunakan api kecil biar matang sempurna.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1636, 4, 'Bihun Telur Gulung', 'Bihun Telur Gulung - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"2 butir telur\", \"50 g bihun\", \"Sedikit garam\", \"Penyedap rasa\", \"Sedikit lada bubuk\", \"4 sendok air\", \"Saos\"]', '[\"Masukkan telur, garam, penyedap, lada bubuk dan air kedalam botol. Kocok2 sampe tercampur rata.\", \"Seduh bihun dengan air panas, diamkan sampe bihun lunak, lalu tiriskan buang airnya.\", \"Panaskan minyak, sampe bener2 panas ya agar telurnya pecah saat digoreng.\", \"Tuang telur, lalu masukkan bihun. putar2 dengan menggunakan tusukan, lalu gulung telur kepinggiran kuali.\", \"Lakukan sampai habis.\", \"Beri saos diatasnya, atau bisa juga di cocol sesuai selera.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1637, 2, 'Buncis orak arik telur', 'Sajian Buncis orak arik telur yang praktis dan lezat untuk dinikmati bersama.', '[\"1/4 buncis\", \"1 butir telor\", \"2 siung bawang putih (cincang halus)\", \"3 siung bawang merah (iris)\", \"100 ml air\", \"secukupnya Garam\", \"secukupnya Gula pasir\", \"Minyak untuk menumis\"]', '[\"Potong buncis serong.cuci hingga bersih tiriskan\", \"Tumis duo bawang hingga harum. Sisihkan, orak arik telor masukan buncis aduk hingga rata masukan air garam dan gula pasir.masak hingga buncis empuk..sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1638, 3, 'Balado Telur Rebon', 'Cara membuat Balado Telur Rebon yang enak dan praktis untuk keluarga.', '[\"6 btr telur\", \"1 ons rebon udang kering\", \"15 bh cabe keriting\", \"10 bh rawit merah\", \"2 bh tomat\", \"6 bawang merah\", \"3 bawang putih\", \"secukupnya Gula Garam\"]', '[\"Rebus telor hingga matang dan kupas, cuci rebon dan goreng.\", \"Ulek bawang merah bawang putih cabe2 dan tomat, tumis bumbu halus masukkan telur dan rebon, gula garam koreksi rasa, jadi daahh..nyaam simple tapi past tense lah gurih nyoyy\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1639, 2, 'Telur ceplok kecap', 'Telur ceplok kecap - hidangan telur praktis dan lezat.', '[\"3 telur ayam\", \"2 siung bawang merah\", \"1 siung bawang putih\", \"5 cabe rawit\", \"1 buah tomat\", \"Kecap manis\", \"Air\", \"Garam\", \"Lada\"]', '[\"Goreng ceplok telur ayam satu per satu, sisihkan, potong jadi 2\", \"Iris bawang merah, bawang putih, cabe rawit, tomat dan daun bawang\", \"Tumis bahan yg sudah diiris tadi hingga harum, tambahkan kecap sesuai selera dan air. Tambahkan garam dan lada,setelah itu masukan telur ceplok tadi. Koreksi rasa dan sajikan, selamat mencoba 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1640, 2, 'Nasi goreng telur', 'Nikmati kelezatan Nasi goreng telur dengan resep sederhana ini.', '[\"1 piring nasi putih\", \"2 butir telur ayam\", \"5 siung bawang merah\", \"1 siung bawang putih\", \"3 buah cabai merah kriting\", \"3 butir kemiri\", \"Sejumput terasi\", \"Garam\", \"Kaldu ayam bubuk\", \"Kecap manis\", \"secukupnya Kol\", \"Minyak goreng\"]', '[\"Haluskan bawang putih, bawang merah, cabai, kemiri, garam, terasi\", \"Goreng 1 butir telur diceplok, angkat.\", \"Tumis bumbu halus sampai harum lalu masukkan satu butir telur ayam yg sudah dikocok, dan orak arik\", \"Masukkan kol dalam tumisan bumbu, orak arik sampai layu\", \"Masukkan nasi dan aduk2 sampai bumbu tercampur rata (dg api kecil)\", \"Koreksi rasa, lalu tambahkan kecap dan kaldu,, ratakan kembali dan tunggu sesaat hingga nasi goreng tanak\", \"Sajikan dengan tambahan telur ceplok dan mentimun.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1641, 2, 'Telur dadar cah tauge', 'Resep praktis Telur dadar cah tauge yang bisa dicoba di rumah.', '[\"2 butir telur\", \"1 genggam tauge\", \"3 pentol bakso\", \"2 siung bawah putih\", \"4 siung bawang merah\", \"1 bawang daun\", \"1 cabe merah\", \"10 cabe rawit (sesuai selera sih, krn aku suka pedes 😊)\", \"Minyak wijen\", \"Saos raja rasa\", \"Saos tiram\", \"Kecap manis\", \"Gula\", \"Garam\"]', '[\"Kocok telur, tambahkan sedikit garam, lalu goreng. Iris memanjang\", \"Tumis bawang putih, bawang merah sampai harum, lalu masukkan cabai. Tambahkan air secukupnya\", \"Beri saus tiram, saus raja rasa, minyak wijen, gula, dan garam. Masukkan tauge dan daun bawang. Cek rasa\", \"Setelah itu masukkan irisan telur dadar. Aduk rata, siap di sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1642, 3, 'Baso Goreng Orak Arik Telor Saus Blackpaper', 'Sajian Baso Goreng Orak Arik Telor Saus Blackpaper yang praktis dan lezat untuk dinikmati bersama.', '[\"20 baso kerat kembang goreng smpai mekar\", \"1 buah bawang bombay\", \"1 telor orak arik\", \"1 sachet saus blackpaper\"]', '[\"Tumis bawang bombay smpai layu dan harusm masukan baso yg sudah digoreng dan telor orak arik... aduk rata\", \"Tambahkan saus blackpaper beri air sckpnya, cek rasa.. biarkan sbntr meresap. Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1643, 2, 'Menu telur dadar ala ala padang', 'Menu telur dadar ala ala padang - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"6 telur ayam\", \"5 sdm kelapa sangrai\", \"4 sdm tepung beras (rosbrand)\", \"Bawang daun\", \"Seledri\", \"10 cabe kriting\", \"Bumbu halus\", \"5 bawang merah\", \"5 bawang putih\", \"2 kemiri\", \"Pedes putih\", \"1 ruas kunyit\"]', '[\"Haluskan bumbu telebih dahulu, kemudian potong serong cabe rawit. Dan potong semua bawang daun dan seledri.\", \"Sangrai kelapa hingga harum. Sedikit di oseng dan api paling kecil.\", \"Pecahkan telur, masukan bumbu halus, bawang daun, seledri, kelapa sangrai, cabe rawit, garam, penyedap rasa (jika mau), pedes kemudian aduk rata (mengaduknya pelan-pelan aja jngan sampe berbusa),\", \"Panaskan wajan berikan minyak, dan masukan telur. Api kecil agar tidak cepet gosong\", \"Telur dadar padang siap disantap bisa d lengkapi dengan sambal ijo ikan teri.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1644, 3, 'Telor masak kecap', 'Buat Telor masak kecap yang nikmat dengan langkah-langkah mudah ini.', '[\"4 biji telor ayam\", \"1 buah sosis\", \"4 siung bawang merah\", \"2 siung bawang putih\", \"6 buah rawit merah & hijau\", \"bawang bombai\", \"1 sdm kecap manis\", \"1 sdt saos tiram\", \"secukupnya garam, lada, gula dan penyedap rasa\", \"air matang\", \"minyak goreng (untuk menumis)\"]', '[\"Ceplok telor sampai matang, dan iris semua bumbu\", \"Tumis bumbu (bawang bombai, bawang putih & merah) sampai harum, lalu masukan rawit\", \"Setelah itu masukan saos tiram dan kecap manis dan beri sedikit air\", \"Masukan sosis dan telor, tambahkan garam, lada, gula dan penyedap, (jgan lupa tes rasa)\", \"Biarkan sampai air sedikit meresap. matikan kompor dan siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1645, 4, 'Telor sambel pete', 'Resep praktis Telor sambel pete yang bisa dicoba di rumah.', '[\"5 butir telor ayam (rebus,kupas)\", \"1 papan pete,kupas\", \"Bumbu halus :\", \"8 buah cabe merah\", \"8 siung bawang merah\", \"2 butir kemiri\", \"1/2 buah tomat\", \"secukupnya Garam,gula\"]', '[\"Goreng telur ayam yg sudah di rebus,sampai kulit luarnya agak kering\", \"Belender/ulek cabe bawang,tomat,kemiri hingga halus\", \"Panaskan minyak,tumis bumbu halus sampe harum\", \"Setelah harum,masukkan Pete dan beri sdkit air,masak 5 menit agar bumbu benar\\\" matang\", \"Beri gula garam,tes rasa..terakhir masukkan telur aduk\\\" 5 menit..angkat,sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1646, 4, 'Lumpia isi tahu + telur', 'Cara membuat Lumpia isi tahu + telur yang enak dan praktis untuk keluarga.', '[\"Bahan kulit :\", \"250 gram tepung terigu\", \"3 sdm tepung kanji / tapioka\", \"3 sdm tepung maizena\", \"1 butir telur\", \"2 sdt garam\", \"4 sdm minyak goreng\", \"Secukupnya Air\", \"Bahan isian :\", \"3 potong tahu kuning (tahu putih juga bisa)\", \"2 butir telur\", \"5 sdm tepung terigu\", \"2 sdm tepung kanji / tapioka\", \"2 sdt garam (secukupnya)\", \"1 sdt gula (secukupnya)\", \"3 siung bawang merah\", \"2 siung bawang putih\", \"4 buah cabe (sesuai selera / secukupnya)\", \"2 sdt kecap asin\", \"2 sdt penyedap rasa (sesuai selera / secukupnya)\", \"Bahan menggoreng :\", \"500 gram minyak goreng\"]', '[\"Pertama² buat adonan kulit, masukkan tepung terigu, tepung kanji, tepung maizena, telur dan garam aduk jadi satu sambil tambahkan air sedikit demi sedikit. Aduk hingga tidak menrintil / adonan mencair semua.\", \"Saring adonan kulit hingga benar² cair dan tidak ada yang merintil. (Catatan : adonan harus benar² mencair seperti air)\", \"Kemudian buat isian, pertama² buat bumbu isian campur cabe, bawang merah, bawang putih, gula dan garang tumbuk jadi satu hingga halus\", \"Haluskan tahu, kemudian tambahkan tepung terigu, tepung kanji, telur, tumbukan bumbu, kecap asin dan penyedap rasa kemudian uleni hingga tercampur semua\", \"Setelah bahan isian jadi, masak kulit luar diteflon satu persatu, sambil dimasukkan isian.\", \"Kemudian setelah semua selesai, goreng lumpia dalam minyak panas. Tunggu hingga berubah warna atau dirasa cukup (sudah matang). Kemudian tiriskan.\", \"Lumpia siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1647, 3, 'Lumpia rebung, ebi, telur', 'Nikmati kelezatan Lumpia rebung, ebi, telur dengan resep sederhana ini.', '[\"10 lb kulit lumpia (beli jadi)\", \"100 gr rebung\", \"25 gr ebi\", \"2 btr telur\", \"3 siung bawang putih\", \"secukupnya garam, gula, mecin, lada\"]', '[\"Rebus rebung, potong tipis dan rendam\", \"Potong korek api\", \"Rendam ebi dan tumis bawang merah yg digeprek, masukan ebi, telur kocok dan rebung aduk2 tambahkan bumbu2\", \"Bungkus dng kulit lupia, goreng\", \"Siap dihidangkan👍👍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(1648, 4, 'Seblak telor', 'Seblak telor - hidangan telur praktis dan lezat.', '[\"5 telor rebus kupas\", \"4 butir bawang merah iris\", \"2 siung bawang putih iris\", \"1 batang serai iris\", \"3 butir kemiri\", \"1/2 cabai merah buang bijinya (/cabai rawit sesuai selera)\", \"3 cm kencur\", \"sesuai selera Garam, gula, kaldu, air\", \"secukupnya Bawang goreng untuk taburan\", \"Terasi bakar dikit aja\", \"Merica bubuk dikit aja\"]', '[\"Telor rebus di kupas, lalu di goreng bentar. Telornya tusuk2 dl ya mom pake garpu biar ga muncrat\", \"Siapkan bumbu: ulek kemiri, kencur dan cabai. Lalu iris bawang dan serai.\", \"Goreng semua bumbu sampai wangi\", \"Masukan air beri garam, gula, kaldu, terasi bakar, merica bubuk sampai pas rasanya.\", \"Kemudian masukan telor yang sudah di goreng td, aduk bentar lalu saring kuahnya. Taburi dengan bawang goreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1649, 3, 'Semur telur kentang tahu', 'Sajian Semur telur kentang tahu yang praktis dan lezat untuk dinikmati bersama.', '[\"2 butir telur\", \"2 buah kentang sedang\", \"3 tahu sedang\", \"1 bawang putih\", \"2 bawang merah\", \"1 biji pala utuh\", \"1 lembar daun salam\", \"Seiris laos\", \"1 sdt merica bubuk\", \"Kecap\", \"Garam\", \"Gula pasir\", \"1 sdt Gula merah\", \"Penyedap\"]', '[\"Rebus kentang Dan telur\", \"Haluskan bawang putih bawang merah, merica bubuk, garam\", \"Tumis bumbu halus, Laos, salam, pala\", \"Tambahkan kecap, gula penyedap, Gula merah, lalu masukkan telur, kentang. Beri sedikit air, lalu masukkan tahu. Selesai..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1650, 4, 'Tahu telur', 'Nikmati kelezatan Tahu telur dengan resep sederhana ini.', '[\"4 btr Telor\", \"Tahu 2 lepak\", \"4 sdm tepung trigu\", \"3 sdm tepung sajiku\", \"Daun bawang secukupnya\", \"Bumbu Yg haluskan:\", \"2 biji Cabe rawit\", \"3 siung Bawang putih\", \"6 siung Bawang merah\", \"Mrica bubuk secukupnya\"]', '[\"Haluskan semua tahu pakai garpu sampai halus\", \"Pecahkn semua telor lalu campur kedalam tahu yg sudah di Haluskan tadi\", \"Campur semua bumbu yg sudah di haluskan tadi Dan bserta tepung terigu masako dan tepung sajiku\", \"Aduk semua sampai merata jgn lupa di msukkan jg daun bwgnya,,,\", \"Untuk menggorengnya pakai Teflon, masukkan minyak goreng secukupnya tunggu minyak smpai hngat dl, lalu masukkan adonan tadi persendok makan sampai habis tunggu sampai kuning matang, lalu hidangkn dgn Cabe rawit\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1651, 4, 'Kentang goreng dan orek telor', 'Buat Kentang goreng dan orek telor yang nikmat dengan langkah-langkah mudah ini.', '[\"1/4 kentang (potong memanjang)\", \"2 butir telor\", \"secukupnya Merica bubuk\", \"secukupnya Garam\", \"secukupnya Minyak goreng\"]', '[\"Panaskan wajan/ teflon masukan telor satu persatu aduk2 sampai telor matang beri garam angkat sisihkan\", \"Kemudian goreng kentang sampai matang angkat sisihkan\", \"Kentang dan telor taruh dalam tempat untuk kentang taburi garam dan lada bubuk hidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1652, 3, 'Steak tamagoyaki (telur korea)', 'Sajian Steak tamagoyaki (telur korea) yang praktis dan lezat untuk dinikmati bersama.', '[\"2 butir telur ayam\", \"2 buah wortel iris sesuai selera\", \"1 buah kentang iris lalu goreng\", \"3 buah buncis iris sesuai selera\", \"1/3 bagian jagung manis\", \"🌸 bahan saus\", \"2 sdm Saus tiram\", \"2 sdm gula pasir\", \"3 sdm kecap (boleh diskip)\", \"1/2 sdt garam\", \"1/2 sdt kaldu\", \"1/2 sdt merica\", \"1/3 botol saus tomat 340 ml (sesuai selera)\", \"1 buah tomat\", \"1/2 bawang bombai iris dan sebagian dihaluskan\", \"2 bawang putih\", \"3 bawang merah\", \"🌸 bahan tamagoyaki\", \"2 buah telur kampung (sesuai stock)\", \"2 lembar daun bawang (onclang) iris tipis\", \"2 buah bawang putih haluskan\", \"Sejumput merica\", \"Secukupnya garam\", \"2 buah buncis iris tipis\", \"1/2 wortel iris kecil\"]', '[\"Haluskan bumbu terlebih dahulu (merica, bawang putih, bawang merah, bombai)\", \"Rebus tomat, jagung manis, wortel, (buncis dimasukkan kalau wortel sudah setengah matang). Lalu tiriskan. Untuk kentang bisa direbus/ digoreng. Bila tomat sudah matang, tunggu dingin lalu kupas dan buang isinya lalu haluskan.\", \"Tumis bumbu halus dan irisan bawang bombai. Bila sudah harum masukkan tomat, serta bumbu lainnya.\", \"Bila sudah matang, tes rasa.\", \"Tamagoyaki, cara buatnya kocok telur, campur semua bumbu. Goreng di teflon anti lengket, beri sedikit minyak lalu usap dengan tisu. Masukkan 1/3 bagian, pinggirkan. Lalu masukkan 1/3 bagian lagi, gulung. Lalu masukkan adonan yg terakhir. Bila sudah matang gulung kembali. Tiriskan. Biarkan dingin lalu potong\", \"Taraaaa, siap disajikan\", \"Dengan nasipun juga cocok\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1653, 4, 'Telur cabe ijo', 'Telur cabe ijo - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"6 butir telur rebus lalu goreng dan sisihkan\", \"3 lembar daun jeruk dan daun salam\", \"2 batang sereh, geprek\", \"1 buah tomat hijau, potong kotak2\", \"5 siung bawang merah, iris tipis\", \"Bumbu yg dihaluskan:\", \"5 buah cabe ijo keriting\", \"5 buah cabe ijo besar\", \"10 buah cabe rawit ijo/sesuai selera jika suka pedas bisa di +\", \"3 siung bawang putih\", \"secukupnya Gula dan garam\", \"1 SDM minyak wijen\"]', '[\"Tumis bawang merah dgn minyak wijen hingga harum, masukkan bumbu halus, daun jeruk, daun salam, sereh dan tomat hijau\", \"Tambahkan sedikit air, jika sdh matang masukkan gula dan garam, koreksi rasa\", \"Kemudian masukkan telur yg sudah direbus dan di goreng\", \"Angkat dan sajikan, siap di santap moms 😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1654, 2, 'Pempek telor no msg', 'Nikmati kelezatan Pempek telor no msg dengan resep sederhana ini.', '[\"1/2 kg ikan kakap/tengiri\", \"400 gr tepung sagu/tapioka\", \"2 sdm garam& gula pasir\", \"1 gelas air\", \"secukupnya Telur\"]', '[\"Siapkan air rebusan ksih sedikit garam& minyak. Campur ikan,garam,gula &air aduk rata.lalu masukkan tepung aduk rata.\", \"Ambil sedikit adonan bentuk sprt lumpang lalu isi dgn telur\", \"Untuk pempek telur kecil ( telornya diaduk terlebih dhulu.\", \"Untuk pempek telur besar(kapal selam) ambil adonan 125 gr bentuk sprt lumpang lalu masukkan telur utuh.\", \"Bisa jg dibentuk bulat panjang/pempek lenjer.\", \"Rebus di air yg sdh mendidih\", \"Tips agar pempek tdk kenyal jgn terlalu lma diaduk.trs ksh sdikit minyak spy tdk lengket.\", \"Segera angkat setelah pempeknya naik keatas/ mengapung\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1655, 2, 'Mie Goreng Sosis Telur', 'Cara membuat Mie Goreng Sosis Telur yang enak dan praktis untuk keluarga.', '[\"2 Mie Goreng Instan\", \"2 Butir Telur (sesuai selera)\", \"3 Sosis Ayam / Sapi (sesuai selera)\", \"5 Biji Cabai Rawit (sesuai selera)\", \"Sayur Sawi Putih / Kubis (sesuai selera)\", \"2 sdt Saos Tiram\", \"Bumbunya pake dari Mie Instan yg sudah ada dalam kemasan\"]', '[\"Jangan lupa Berdoa sesuai keyakinan masing2, kalau saya baca Basmalah dulu.. :)\", \"Pisahkan Mie yang mau di rebus dari bumbunya.\", \"Cabai iris kecil2, Sawi Putih / Kubis juga iris tipis2. Potong Sosis dan Kocok Telur.\", \"Goreng telur, sosis lalu setelah di goreng. Sisihkan ke tempat lain. Ganti buat numis cabai, sawi putih / kubis dan bumbu dr mie instan tsb.\", \"Rebus Mie Instan, setelah selesai di rebus. Buang air nya, lalu masukkan di wajan yg sudah ada isinya (sesuai langkah 4). Tambahkan sedikit saos tiram.\", \"Aduk hingga rata dan koreksi rasa. Setelah di koreksi dan sudah OK.\", \"Alhamdulillah, makanan siap di hidangkan. Selamat Makan dan Selamat Mencoba :)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1656, 2, 'Schotel telor', 'Resep praktis Schotel telor yang bisa dicoba di rumah.', '[\"1 kg telor ayam\", \"7 Cabai merah\", \"3 bawang merah\", \"2 bawang putih\", \"3 kemiri\", \"secukupnya Kunyit\", \"Garam\", \"Gula\", \"Sasa\", \"Minyak sayur\"]', '[\"Rebus telor 1kg sampai matang(setelah matang telor dikupas,pisahkan telor putih dan yg kuningnya, lalu aluskan telor yg kuning dan telor yg putih di iris menjadi kotak-kotak kecil\", \"Rebus cabai merah\", \"Ulek bumbu sampai alus(cabai merah, bawang merah, bawang putih, kunyit, kemiri,garam, gula, sasa)\", \"Panaskan minyak sayur dan goreng bumbu yg sudah di alus kn tadi sampai wangi dan kuning\", \"Setelah bumbu matang campurkan ke adonan telor kuning\", \"Campurkn juga telor putih yg sudah diiris kotak2 td ke telor kuning\", \"Campurkn 2telir mentah ke adonan telor(aduk sampai rasa, rasa sesuai selera, boleh tambah garam, gula dan sasa lg)\", \"Masukan adonan telor ke plastik perempatan(iket rapi)atau masukan ke cetakan jeli\", \"Kukus selama 20menit atau sampai matang\", \"Setelah matang diamkan 5menit\", \"Setelah itu jika menggunakan plastik tinggal diiris tp jgn terlalu tipis\", \"Siaap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1657, 2, 'Roti tawar goreng isi telur dan rumput laut', 'Nikmati kelezatan Roti tawar goreng isi telur dan rumput laut dengan resep sederhana ini.', '[\"6 lembar roti tawar (me: Sari roti yg putih)\", \"Rumput laut kemasan (skip klu gak ada)\", \"3 butir telur rebus (potong”)\", \"Saos sambel\"]', '[\"Ambil satu lembar roti tawar beri rumput laut, potongan telur rebus,mayonnaise dan saus\", \"Lipat dua menjadi bentuk segitiga, rapatkan tepian roti dgn garpu, lakukan pengisian berulang hingga roti habis terisi\", \"Siap kan wajan penggoreng dan minyak goreng (minyak panas dgn api kecil)goreng sebentar dan sekali balik karna akan cepat gosong dan menyerap minyak\", \"Nb: kalau takut lipatan roti akan terbuka saat di goreng siapkan telur kocok, sebelum di goreng, baluri tepian lipatan roti dgn telur (seperti perekat)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1658, 2, 'Telur dadar spesial hari ini', 'Nikmati kelezatan Telur dadar spesial hari ini dengan resep sederhana ini.', '[\"3 btr telur\", \"1 bh wortel,parut dg parutan keku\", \"1 btg daun pre,rajang\", \"1 btg sledri,rajang\", \"Secukupnya garam\", \"2 sdm sajiku\"]', '[\"Campur smua bahan jd satu,aduk smp rata sebentar. Panaskan teflon yg sdh diberi margarin 1 sdm. Tuang telur diteflon. Gulung telur pelan2.. Tunggu smp agak kecoklatan,balik lalu ditekan2 dg spatula agar cpt matang. Sajikaannn hangat,plus nasi angett..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1659, 3, 'Telur ceplok manis pedas', 'Cara membuat Telur ceplok manis pedas yang enak dan praktis untuk keluarga.', '[\"4 butir telur\", \"5 buah cabe rawit hijau, iris serong\", \"6 buah cabe rawit setan, iris serong\", \"5 siung bawang merah, iris tipis\", \"secukupnya garam\", \"secukupnya gula\", \"1 sachet kecap bango\", \"1/2 gelas air\"]', '[\"Ceplok telur terlebih dahulu. Setelah selesai, sisihkan.\", \"Tumis bawang merah hingga agak kecoklatan, kemudian masukan cabai. Aduk rata. kemudian beri air, masak hingga mendidih.\", \"Tambahkan garam dan gula sesuai selera. setelah mendidih. tuang semua kuah ke telor ceplok tadi. Masakan siap dihidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1660, 4, 'Telur Dadar bumbu Kemiri', 'Nikmati kelezatan Telur Dadar bumbu Kemiri dengan resep sederhana ini.', '[\"4 btr Telur Ayam\", \"Haluskan.\", \"5 siung Bawang Merah\", \"2 siung Bawang Putih\", \"5 btr Kemiri\", \"3 Cabe Merah Besar buang bijinya\", \"Sedikit Garam\", \"Minyak goreng utk dadar\"]', '[\"Kocok Telur Ayam dengan bumbu halus hingga tercampur rata, koreksi rasa.\", \"Panaskan wajan dengan sedikit minyak goreng. Goreng adonan telur, hingga matang atas bawah, angkat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1661, 3, 'Rendang Telor', 'Sajian Rendang Telor yang praktis dan lezat untuk dinikmati bersama.', '[\"4 butir telor,rebus lalu kupas\", \"200-250 ml santan\", \"1 lembar daun kunyit\", \"2 lembar daun salam\", \"1 sereh geprek\", \"sedikit Gula pasir\", \"1 bungkus bumbu rendang indofood\", \"2 sdm kelapa parut yang disangrai dan ditumbuk halus(boleh skip)\", \"Bumbu haluskan :\", \"7 siung bawang merah\", \"1 cm kunyit\", \"1 cm lengkuas\", \"1 cm jahe kupas\", \"2 butir kemiri\", \"4 siung bawang putih\", \"1/2 sdt ketumbar bubuk\", \"1/4 sdt lada bubuk\"]', '[\"Rebus telor,rendam dengan air dingin agar gampang mengupas,kupas lalu goreng\", \"Tumis bumbu halus hingga harum,masukan daun kunyit,daun salam,sereh,aduk rata,masukan bumbu rendang indofood,tumis hingga bumbu matang.\", \"Masukan telor aduk rata,masukan santan.Aduk terus agar santan tidak pecah.masukan kelapa parut sangrai yang sudah ditumbuk halus.Beri gula,koreksi rasa\", \"Masak hingga kuah kental,Gunakan api kecil cenderung sedang.Jika sudah kental matikan kompor.Siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1662, 3, 'Telur dadar minimalis dan sederhana', 'Resep praktis Telur dadar minimalis dan sederhana yang bisa dicoba di rumah.', '[\"2 butir telur\", \"1 ikat daun bawang\", \"1 sdm bawang merah goreng\", \"Garam\", \"Merica\", \"Kaldu bubuk\", \"Minyak goreng\"]', '[\"Kocok telur, masukkan daun bawang dan bawang goreng, tambahkan garam, merica, dan kaldu bubuk lalu goreng hingga matang. Angkat dan sajikan. 😋😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1663, 3, 'Kembang telor/kuah telor', 'Olahan telur sederhana: Kembang telor/kuah telor yang mudah dibuat.', '[\"1 btr telor\", \"1 siung kecil bawang putih\", \"1 siung bawang merah\", \"1/2 gelas air\", \"secukupnya Garam\", \"secukupnya Gula\"]', '[\"Cincang bawang putih &bawang merah.kocok lepas telor.\", \"Tumis duo bawang hingga harum dan kecoklatan.masukkan air,garam&gula tunggu sampai mendidih\", \"Setelah mendidih masukkan telor kocok sambil dikacau kacau.koreksi rasa.tunggu sekejap.angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1664, 4, 'Sayur obor daun katuk + teri+telur', 'Cara membuat Sayur obor daun katuk + teri+telur yang enak dan praktis untuk keluarga.', '[\"1 ikat Daun katuk\", \"4 butir Telur\", \"Ikan teri tanjung\", \"5 buah Bawang merah\", \"1 siung Bawang putih\", \"20 buah Cabe rawit\", \"Lengkuas ujung jari geprek\", \"Santan\", \"2 lembar Daun salam\"]', '[\"Rebus dahulu telur setelah itu kupas\", \"Cuci daun katuk hingga bersih\", \"Cuci ikan teri\", \"Blender semua bumbu kecuali lengkuas di geprek saja\", \"Tumis bumbu hingga harus, masukan santan dan masukan daun katuk,dan telur yang dikupas, lengkuas geprek dan daun salam..upss ikan teri jangan lupa masak hingga matang dengan api kecil.. 😉\", \"Taraa sajikan dengan nasi hangat suami pasti syuka selamat mencoba🤗🤗\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1665, 3, 'Egg Roll Mozarella', 'Nikmati kelezatan Egg Roll Mozarella dengan resep sederhana ini.', '[\"3 butir telur ayam (jika ingin lebih tebal telur ny tambahkan sesuai selera)\", \"1 bh daun bawang\", \"secukupnya Mozarella\", \"Garam\", \"Untuk isi:\", \"Bisa tambahkan sosis.. Ayam\"]', '[\"Siapkan teflon..pastikan api kecil agar tidak mudah gosong\", \"Kocok semua bahan sampai tercampur rata kecuali mozarella\", \"Tuang telur sedikit sedikit lalu roll..tuang lagi telur nya taruh mozzarella lalu roll lagi lakukan seterusnya hingga telur nya habis\", \"Di santap lebih nikmat saat masih hangat\", \"Keju yang saya pakai\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1666, 2, 'Rolade telur', 'Resep Rolade telur yang lezat dan mudah dibuat di rumah.', '[\"4 butir telur\", \"2 sdm terigu\", \"1 buah wortel\", \"1 batang daun bawang\", \"3 buah bawang merah\", \"2 buah bawang putih\", \"1 sdt merica bubuk\", \"1 sdt garam dan penyedap rasa\"]', '[\"Haluskan bumbu bawang merah dan bawang putih\", \"Blender wortel dan daun bawang\", \"Ambil wadah untuk mengocok semua telur\", \"Tambahkan terigu dan semua bumbu serta sayuran yg sudah dihaluskan\", \"Masukan kedalam plastik es kemudian rebus sampai mengambang kira2 5 menit\", \"Angkat dan diamkan sampai dingin kemudian potong2 rolade telurnya,, bisa digoreng lagi dan bisa juga dimasak saus tiram asam manis\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1667, 2, 'Sandwich Telur', 'Resep praktis Sandwich Telur yang bisa dicoba di rumah.', '[\"** Bahan Sandwich :\", \"1 butir telur\", \"1 sdm mentega\", \"Secukupnya merica bubuk\", \"Secukupnya garam\", \"2 lembar roti tawar (saya pakai roti tawar Mr. Bread)\", \"** Bahan Pelengkap :\", \"3 potong irisan timun\", \"3 potong irisan tomat\", \"Secukupnya mayonnaise\", \"Secukupnya saus sambal\", \"1 mangkok salad hokben (bisa diskip)\"]', '[\"Panaskan mentega hingga cair. Sambil menunggu, kocok telur bersama merica bubuk dan garam.\", \"Goreng telur hingga matang dengan menggunakan mentega.\", \"Plating. Tata sandwich dengan urutan roti, dadar telur, timun, tomat, saus dan mayonnaise, tutup lagi dengan roti. Jika suka tambahkan salad hokben.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1668, 4, 'Jamur goreng telur', 'Olahan telur sederhana: Jamur goreng telur yang mudah dibuat.', '[\"250 gr jamur merang\", \"5 buah bawang putih / 3 sendok teh Bubuk bawang\", \"1 butir telur\", \"secukupnya garam\", \"secukupnya minyak goreng\", \"250 gr jamur merang\", \"5 buah bawang putih / 3 sendok teh Bubuk bawang\", \"1 butir telur\", \"secukupnya garam\", \"secukupnya minyak goreng\", \"250 gr jamur merang\", \"5 buah bawang putih / 3 sendok teh Bubuk bawang\", \"1 butir telur\", \"secukupnya garam\", \"secukupnya minyak goreng\"]', '[\"Suwir jamur sesuai selera.cuci dengan air mengakir dan tiriskan.\", \"Haluskan bawang putih dengan garam. Boleh diuleg atau diblender. Campur air. Tes rasa, kemudian rendam jamur lebih kurang 15-30 menit.\", \"Saran : apabila bumbu anda terlalu asin maka jgn merendam terlalu lama, tp jika tdk terlalu asin boleh sampai 30 menit.\", \"Saring jamur, tiriskan. Masukkan telur ke dalam mangkok, aduk. Kemudian masukkan jamur.\", \"Siapkan minyak ke dalam panci. Jika anda lebih suka gurih maka masaklah dg api sedang dg waktu lama hingga kecoklatan, tp jika lbh suka agak basah maka masak dg api sedang hingga kekuningan.\", \"Haluskan bawang putih dengan garam. Boleh diuleg atau diblender. Campur air. Tes rasa, kemudian rendam jamur lebih kurang 15-30 menit.\", \"Saran : apabila bumbu anda terlalu asin maka jgn merendam terlalu lama, tp jika tdk terlalu asin boleh sampai 30 menit.\", \"Saring jamur, tiriskan. Masukkan telur ke dalam mangkok, aduk. Kemudian masukkan jamur.\", \"Siapkan minyak ke dalam panci. Jika anda lebih suka gurih maka masaklah dg api sedang dg waktu lama hingga kecoklatan, tp jika lbh suka agak basah maka masak dg api sedang hingga kekuningan.\", \"Haluskan bawang putih dengan garam. Boleh diuleg atau diblender. Campur air. Tes rasa, kemudian rendam jamur lebih kurang 15-30 menit.\", \"Saran : apabila bumbu anda terlalu asin maka jgn merendam terlalu lama, tp jika tdk terlalu asin boleh sampai 30 menit.\", \"Saring jamur, tiriskan. Masukkan telur ke dalam mangkok, aduk. Kemudian masukkan jamur.\", \"Siapkan minyak ke dalam panci. Jika anda lebih suka gurih maka masaklah dg api sedang dg waktu lama hingga kecoklatan, tp jika lbh suka agak basah maka masak dg api sedang hingga kekuningan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1669, 4, 'Sambal balado telur dan ikan cue', 'Nikmati kelezatan Sambal balado telur dan ikan cue dengan resep sederhana ini.', '[\"4 butir telur,rebus dan kupas kulitnya\", \"1 bgks ikan cue,goreng setengah matang saja.(boleh skip)\", \"bumbu\", \"secukupnya Cabe merah\", \"secukupnya Cabe rawit\", \"4 siung bawang merah\", \"2 siung bawang putih\", \"2 lembar daun jeruk (boleh skip)\", \"secukupnya Garam,gula\", \"secukupnya Air\"]', '[\"Uleg/blender smua bumbu\", \"Lalu tumis bumbu di minyak yg sdh panas,sampai baunya harum,lalu masukan air sedikit\", \"Lalu masukan ikan cue dan telur rebus.test rasa.done\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1670, 2, 'Oseng Buncis Cambah Telor Sosis', 'Oseng Buncis Cambah Telor Sosis - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 genggam buncis (iris serong)\", \"1 genggam cambah\", \"1 butir telur\", \"1 buah sosis\", \"3 siung bawang merah\", \"1 siung bawah putih\", \"1 buah tomat (iris memanjang jadi 8 bagian)\", \"6 buah cabe kecil\", \"1 buah lombok merah besar\", \"Secukupnya garam, gula, kaldu sapi bubuk\", \"Secukupnya air\"]', '[\"Tumis bawang putih, bawang merah, cabe kecil dan lombok merah sampai harum. Kemudian masukkan sosis goreng sebentar, masukkan telur buat orak arik\", \"Masukkan buncis, oseng sebentar, lalu cambah, aduk rata\", \"Masukkan tomatnya, aduk. Tambahkan air untuk kuah dan gula, kaldu bubuk, dan garam. Koreksi rasa. Udah selesee 🤗🤗\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1671, 4, 'Omelet telur panggang ala thailand', 'Omelet telur panggang ala thailand - hidangan telur praktis dan lezat.', '[\"4 butir telur ayam\", \"3 batang daun bawang potong2\", \"4 buah cabai merah keriting, potong2\", \"2 buah cabai hijau potong2\", \"Lada bubuk, garam, gula, penyedap\", \"Daun pisang bentuk seperti mangkuk/takir\"]', '[\"Campur semua bahan, lalu tes rasa\", \"Tuang ke daun pisang\", \"Panggang/bakar, aku pake teflon sebaiknya ditutup biar lbh cepat mateng\", \"Silahkan di sajikan... Sebagai camilan dicocol sama saos/sambal atau bisa juga utk lauk\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1672, 4, 'Telur Rebus sambal matah DEBM', 'Telur Rebus sambal matah DEBM - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 bungkus indomie sambal matah (ambil bumbu nya saja)\", \"2 butir telur\", \"200 ml air\"]', '[\"Didihkan air. lalu masukkan telur dan aduk2 tapi jangan sampai hancur semua.\", \"Siapkan mangkok. masukkan bumbu indomie sambal matah ke dalam mangkok. beri sedikit air panas tadi. aduk hingga bumbu tercampur rata\", \"Jika telur sdh matang. matikan kompor, masukkan telur + kuahnya ke dalam mangkok lalu aduk rata\", \"Hidangkan selagi hangat. selamat mencoba.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1673, 3, 'Oatmeal telur', 'Sajian Oatmeal telur yang praktis dan lezat untuk dinikmati bersama.', '[\"1 sachet oatmeal rasa soto ayam\", \"1 butir telur\", \"1 gelas air (200ml)\", \"sedikit garam\"]', '[\"Didihkan 200ml air. lalu masukkan telur. aduk2 sebentar lalu tunggu hingga telur agak matang. tambahkan sejumput garam.\", \"Masukkan oatmeal lalu aduk terus sampai 5menit. matikan api. sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1674, 4, 'Telur kentang balado', 'Resep Telur kentang balado yang lezat dan mudah dibuat di rumah.', '[\"7-10 butir telur\", \"10 siung bawang merah\", \"5 siung bawang putih\", \"3 helai daun jer,uk\", \"1 sachet kecil royco ayam\", \"Gula merah secukupnya,e\", \"secukupnya Gula pasir dan garam\", \"1 buah kentang (besar),bisa juga beli kentang goreng siap saji\", \"7 Cabe kriting + 15 -20 cabe rawit\", \"2 buah tomat\", \"secukupnya Minyak dan air\"]', '[\"Siapkan bumbu,tomat diiris tipis\", \"Rebus telur sampai mateng,dan kupas kulitnya\", \"Kupas kentang dan potong persegi panjang,cuci bersih,dan langsung goreng\", \"Haluskan bumbu,7 siung bawang merah(3 siung iris tipis untuk ditumis),bawang putih,cabe kriting dan rawit\", \"Tumis bawang merah iris sampai layu dan wangi,masukan bumbu halus,irisan tomat,daun jeruk,aduk sampai bumbu trcium wangi\", \"Tambahkan air,royco Gula merah,masukan telur rebus,dan aduk biar tercampur dengan bumbu\", \"Jika air mulai menyusut,tes rasa dan bunda bisa tambahkn garam dan gula pasir sampai pas dilidah\", \"Selanjutnya masukan kentang goreng,aduk bolak balik agar kentang tercampur dengan bumbu,matikan api\", \"Pindahkan masakan kepiring saji,dan siap dihidangkan bersama nasi putih irisan timun\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1675, 2, 'Dadar Tahu Telur', 'Resep Dadar Tahu Telur ala rumahan yang dijamin menggugah selera.', '[\"1 buah tahu putih\", \"2 butir telur, kocok lepas\", \"1 sdt cabe merah giling\", \"1 batang daun bawang, iris\", \"Secukupnya garam, kaldu jamur\"]', '[\"Hancurkan tahu dg garpu. Campur telur dg semua bahan. Panaskan pan, beri secukupnya minyak, tuang adonan, goreng hingga satu sisi mulai mengeras n kecokelatan. Balik, goreng hingga matang. Sajikan.\", \"Note: kalo gk asa cabe merah giling bisa diganti dg irisan cabe merah/ rawit.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1676, 3, 'Gongso telur kriting ati ampela', 'Gongso telur kriting ati ampela - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1/2 kg ati ampela ayam\", \"1-2 telur ayam\", \"8 bawang merah\", \"7 bawang putih kecil\", \"4 bawang merah untuk rebus ati ampela\", \"4 bawang putih untuk rebus ati ampela\", \"4 cabe merah\", \"6 cabe rawit merah(cabe setan) sesuai selera pedasnya\", \"1 cm kunyit\", \"2-3 daun salam\", \"secukupnya Garam\", \"secukupnya Gula\", \"secukupnya Masako\", \"secukupnya Saos tiram\", \"Kecap\", \"1/2 tomat\", \"1/2 bawang bombay\", \"Gula merah/gula jawa/gula aren\"]', '[\"4 bawang merah, 4 bawang putih, garam secukupnya dihaluskan. Lalu rebus ati ampela, bumbu yg dihaluskan tadi ditambah 2-3 daun salam untuk menghilangkan bau amis dan gula jawa. Sekitar 5-6 menit atau sekiranya sudah mendidih\", \"Haluskan 8bawang merah, 7bawang putih, garam, cabe merah, cabe rawit, dan kunyit. Iris bawang bombay, tomat.\", \"Goreng telur orak arik kemudian sisihkan dahulu\", \"Setelah rebusannya sudah dimatikan lalu potong kecil-kecil ati ampela sesuai selera.\", \"Setelah diiris, panaskan minyak untuk menumis bumbu dan bawang bombay. Setelah harum masukkan ati ampela, saos tiram, kecap, garam secukupnya, gula secukupnya, masako, dan tomat. Ditambah air rebusan tadi sedikit saja agar tidak kering.\", \"Lalu terakhir setelah matang masukan orak arik telur, tumis sebentar. Jadilah gongso telur kriting ati ampela\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1677, 2, 'Telur Dadar toping Daging Cincang ala DEBM', 'Resep Telur Dadar toping Daging Cincang ala DEBM yang lezat dan mudah dibuat di rumah.', '[\"2 btr telur\", \"100 gr daging cincang\", \"3 siung bawang merah\", \"1 bh bawang bombay\", \"5 siung bawang putih\", \"secukupnya Kaldu jamur\", \"secukupnya Lada hitam\", \"1 sdt saus tiram\", \"1 sdm minyak makan\"]', '[\"Tumis bawang putih + bawang bombay sampe wangi\", \"Masukkan daging cincang,tambahkan kaldu + saus tiram + lada hitam..jika sudah matang sisihkan\", \"Kocok lepas telor + irisan bawang merah,dadar\", \"Tata di piring telor dadar + tumis daging...\", \"Saya tambah cabe biar sedikit bewarna..\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1678, 2, 'Kimchi Jeon / Telur Dadar Kimchi ala korea', 'Nikmati kelezatan Kimchi Jeon / Telur Dadar Kimchi ala korea dengan resep sederhana ini.', '[\"3 butir telur ayam\", \"100 gram kimchi (atau lebih)\", \"1 batang daun bawang\", \"Cabe merah secukupnya (jika suka pedas), saya ga pake krn buat anak2\", \"Secukupnya Garam\", \"Secukupnya minyak untuk menumis\"]', '[\"Potong halus daun bawang\", \"Potong2 kimchi. Pilih kimchi yang halal ya teman 😊\", \"Aduk rata telur, daun bawang, garam dan cabai (jika pakai cabai)\", \"Jika sudah tercampur rata, masukkan kimchi dan aduk lagi\", \"Panaskan minyak goreng di pan. Goreng keseluruhan adonan sehingga memenuhi pan. Gunakan api kecil. Saat sudah kecoklatan, balik dengan hati2 supaya tidak pecah.\", \"Kimchi Jeon siap dihidangkan. Bisa ditambah saos sambal atau sesame sauce.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1679, 4, 'Sabal kecap + telur dadar gombal gambul', 'Sabal kecap + telur dadar gombal gambul - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"Sambal kecap\", \"5 cabe setan\", \"3 bawang merah\", \"1 bawang putih\", \"garam secukup nya\", \"beri sedikit kunir\", \"Telur dadar\", \"3 butir telur\", \"2 ruas daun bawang yang segar\", \"2 bawang merah di potong kecil\", \"3 cabe setan di potong kecil\", \"Beri garam secukup nya\", \"Tanpa micin sesuai selera yaa\"]', '[\"Tumis bentar bawang dan cabe sambe cukup panas.. kemuadian setelah rata ulekan sambal nya di beri kecap dan sedikit garam,,, tinggal colek\", \"Kocok telur sampai rata kemudian daun bawang, cabe, iris tipis,, beri sedikit garam ya jangan asin2 yaa... panaskan kompor tinggal goreng beberapa menit jadi deh ☺️👌\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1680, 2, 'Sandwich egg mozarella', 'Sajian Sandwich egg mozarella yang praktis dan lezat untuk dinikmati bersama.', '[\"Roti tawar\", \"Telur (yang sudah di dadar)\", \"Selada\", \"Keju mozarella\", \"Saos sambal\", \"Mayones\"]', '[\"Roti di panggang sebntar, isi isiannya seperti telur selada dan keju mozarellanya\", \"Panggang kembali di atas teplon dengan api sedang\", \"Jika sudah kecoklatan, siap di angkat dan di hidangkan\", \"Isiannya sebenarnya sesuai selera ya bun, ini saya hanya manfaatin apa yang ada di kulkas aja... Selamat mencoba 😉\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1681, 4, 'Telur Krispi', 'Resep Telur Krispi ala rumahan yang dijamin menggugah selera.', '[\"2 butir telur\", \"4 sdm tepung serbaguna ayam krispi (Sasa)\", \"minyak goreng\"]', '[\"Buat telur dadar (tawar) tipis saja 2 telur jadi 4x dadar\", \"Potong kecil sesuai selera\", \"Buat adonan 1 sdm tepung agak cair untuk bahan pencelup\", \"Celupkan telur dadar kedalam adonan tsb lalu gulingkan di sisa tepung sampai rata\", \"Goreng kecoklatan, angkat\", \"Sajikan dengan saus tomat atau mayonaise\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1682, 2, 'Sate telur', 'Olahan telur sederhana: Sate telur yang mudah dibuat.', '[\"4 butir telur\", \"secukupnya Garam\", \"secukupnya Lada bubuk\", \"Air\", \"Tepung sagu / tapioka (setengah SDM)\", \"Tusuk sate / stick\"]', '[\"Kocok telur hingga berbusa sisihkan\", \"Larutkan tepung sagu / tapioka dengan air secukupnya\", \"Tuang larutan tepung kedalam kocokan telur. Tambahkan garam dan lada bubuk. Bisa ditambah penyedap rasa\", \"Siapkan minyak yg cukup banyak. Panaskan.\", \"Setelah panas kecilkan api dan masukan telur kedalam minyak panas\", \"Putar2 stick hingga telur menggulung di badan stick\", \"TIPS: minyak harus banyak, setelah memasukan telur ke dalam minyak harus langsung digulung cepat karena jika telur terlalu matang di minyak membuat telur susah di gulung,\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1683, 3, 'Telur petis teman lontong sayur', 'Resep Telur petis teman lontong sayur ala rumahan yang dijamin menggugah selera.', '[\"6 butie telur ayam\", \"5 buah cabe merah kecil\", \"3 buah bawang putih\", \"1 ruas kunci\", \"3 sdm petis\", \"1/2 gelas blimbing air putih\", \"Gula\", \"Garam\", \"secukupnya Minyak goreng\"]', '[\"Rebus telur hingga matang, buang kulitnya\", \"Uleg bawang putih,cabe merah kecil dan kunci\", \"Tumis dgn sedikit minyak. Masukan petis, air,gula dan garam\", \"Masak hingga air menyusut\", \"Cek rasa\", \"Teman makan sayur labu dan lontong..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1684, 4, 'Balado telor kentang pete', 'Nikmati kelezatan Balado telor kentang pete dengan resep sederhana ini.', '[\"5 butir telor ayam,rebus, kupas kulitnya\", \"3 buah kentang, kupas, potong memanjang\", \"10 buah cabe rawit merah\", \"1 papan pete, kupas, belah 2, bersihkan, sisihkan\", \"5 siung bawang merah\", \"5 siung bawang putih\", \"2 butir kemiri\", \"1 buah tomat merah ukuran sedang, cuci, potong2\", \"Daun salam\", \"1 ruas jari lengkuas, bersihkan, geprek\", \"secukupnya Garam\", \"secukupnya Gula pasir\", \"Minyak sayur\"]', '[\"Haluskan bawang putih, bawang merah, kemiri, cabe rawit, dan tomat.\", \"Goreng kentang hingga berwarna coklat keemasan, angkat, tiriskan. Sisihkan.\", \"Tuang minyak sayur, tumis bumbu halus dengan api kecil agar tdk gosong, jika sudah mulai tercium harum, tambahkan lengkuas dan daun salam, aduk kembali. Koreksi rasa dengan menambahkan garam dan gula secukupnya. Aduk kembali hingga rata.\", \"Masukan telur yg sudah direbus, kentang yg sudah digoreng, dan irisan pete, aduk-aduk.\", \"Goreng sebentar agar bagian luar telur agak kering dan bumbu menempel di telur, kentang,dan pete. Angkat, Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1685, 2, 'Telur Dadar ala Padang', 'Telur Dadar ala Padang - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"4 butir telur ayam\", \"2 batang daun bawang (onclang)\", \"2 sdm kelapa parut\", \"2 sdm tepung beras larutkan dengan 2 sdm air\", \"Bumbu halus :\", \"3 siung bawang merah\", \"2 siung bawang putih\", \"3 buah cabe (kalau suka pedas bisa ditambah)\", \"Sedikit kunyit dan merica bubuk\", \"1 buah kemiri\", \"Secukupnya garam\", \"Minyak untuk menggoreng\"]', '[\"Campur semua bahan jadi satu.\", \"Panaskan minyak dalam wajan kemudian masukkan telur, tutup wajan agar matangnya merata. Gunakan api kecil saat menggoreng.\", \"Kalau pinggirnya sudah kering balik dengan hati2 agar telur tidak hancur.\", \"Potong2 dan telur siap dinikmati dengan nasi hangat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1686, 3, 'Oseng wortel telur', 'Sajian Oseng wortel telur yang praktis dan lezat untuk dinikmati bersama.', '[\"4 batang wortel,potong korek api aga tipis\", \"1 butir telur\", \"5 baso uk. kecil,potong sesuai selera\", \"2 siung bawang merah,iris tipis\", \"1 siung bawang putih,geprek dan diiris tipis\", \"1/2 bungkus kaldu jamur\", \"secukupnya garam\", \"secukupnya air\", \"minyak untuk menumis\"]', '[\"Tumis bawang merah dan bawang putih hingga harum\", \"Masukkan baso yg sudah dipotong2,kemudian masukkan wortel\", \"Tuang air sesuai selera (klo ingin berkuah kasih air aga banyak),sambil diaduk sedikit\", \"Setelah airnya mendidih masukkan telur,oseng2 hingga berbaur telurnya\", \"Beri kaldu jamur,sedikit garam,cek rasa\", \"Cek keempukan wortelnya..klo aku aga lamaan masak nya biar anakku mau makan sayuran\", \"Setelah matang,angkat sajikan dengan nasi hangat..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1687, 4, 'Balado Takoler (kentang, jengkol, telor)', 'Olahan telur sederhana: Balado Takoler (kentang, jengkol, telor) yang mudah dibuat.', '[\"2 butir Telur\", \"1/4 kg baby kentang\", \"1/4 kg jengkol\", \"1 buah tomat\", \"4 cabai merah\", \"15 cabe rawit (sesuai selera pedas)\", \"4 siung bawang merah\", \"1 buah sereh\", \"2 lembar daun salam\", \"Minyak untuk menumis\", \"secukupnya Gula merah, garam, lada bubuk\"]', '[\"Telur dan baby kentang rebus kurang lebih 15 mnt. Lalu tiriskan. Goreng sampai bagian kulitnya keriput.\", \"Jengkol bisa digoreng/direbus/kukus agar empuk.\", \"Semua bumbu dihaluskan, kecuali salam dan sereh. Sereh dipeprek.\", \"Tumis semua bumbu dengan minyak. Setelah wangi beri air dan tuangkan baby kentang, telur, dan jengkol. Masak sampai air menyerap.\", \"Jangan lupa koreksi rasa.\", \"Tarraaaaaa...siap-siap bersehah ria dan nambah terus nasinya😉\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1688, 3, 'Cuma telur dadar 😂', 'Nikmati kelezatan Cuma telur dadar 😂 dengan resep sederhana ini.', '[\"2 butir telur ayam\", \"1 batang daun bawang, iris\", \"1 siung bawang putih, cincang\", \"7 buah cabe rawit, iris\", \"Secukupnya garam dan masako\", \"Secukupnya minyak\"]', '[\"Siapkan mangkuk, campur semua bahan, kocok telur dengan menggunakan garpu sampai tercampur rata. Panaskan minyak secukupnya, lalu goreng sampai matang.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1689, 2, 'Nasi goreng telur simple', 'Olahan telur sederhana: Nasi goreng telur simple yang mudah dibuat.', '[\"1-2 piring nasi putih\", \"1 butir telur\", \"1 sdm kecap manis\", \"1 sdt saus tiram\", \"Secukupnya lada bubuk\"]', '[\"Panaskan wajan, beri sedikit minyak, buat orak-arik telur. Masukkan nasi, beri kecap, saus, lada, aduk rata hingga tercampur. Masak hingga matang dan sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1690, 2, 'Telur rebus cepat matang hanya 5 menit', 'Resep Telur rebus cepat matang hanya 5 menit ala rumahan yang dijamin menggugah selera.', '[\"6 butir telur/kurang dari 6 boleh me 3 butir\", \"200 ml air\", \"Panci + tutup me ukuran 1.5 liter\"]', '[\"Cuci telur\", \"Letakkan di panci\", \"Isi panci dengan air\", \"Rebus dengan api besar 2 menit\", \"Kecilkan api lanjut merebus selama 3 menit\", \"Setelah itu matikan kompor, dan diamkan dulu selama 9 menit, tutup jgn di buka dulu ya\", \"Noted: selama proses perebusan dan 9 menit di diamkan tutup panci ga boleh di buka dulu ya\", \"Matang sempurna, hemat waktu, hemat gas... Sukak\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1691, 4, 'Macaroni telur', 'Buat Macaroni telur yang nikmat dengan langkah-langkah mudah ini.', '[\"3 genggam macaroni telur\", \"1 butir telur\", \"Garam\", \"Kaldu jamur\", \"Bumbu kentang goreng Indofood rasa jagung bakar\", \"Boncabe\"]', '[\"Dalam panci, didihkan air. Rebus macaroni dengan sedikit minyak. Setelah matang tiriskan.\", \"Kocok telur, tambahkan garam, kaldu jamur. Aduk. Tambahkan pula macaroninya. Aduk merata.\", \"Panaskan wajan dengan sedikit minyak. Masukkan macaroni, aduk merata. Masak sampai matang. Sisihkan.\", \"Tambahkan macaroni dengan bumbu kentang goreng indofood, aduk merata. Tambahkan pula dengan boncabe, aduk merata. Koreksi rasa. Jika dirasa cukup, angkat. Sajikan Macaroni Telur dengan taburan keju.. lebih nikmat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1692, 2, 'Balado ikan pindang balut telor', 'Resep Balado ikan pindang balut telor ala rumahan yang dijamin menggugah selera.', '[\"3 potong ikan pindang salem\", \"2 butir telor\", \"Bumbu yang dihaluskan:\", \"5 bawang merah\", \"4 bawang putih\", \"8 cabe merah\", \"2 tomat\", \"secukupnya Garam\", \"secukupnya Kaldu bubuk\", \"secukupnya Motto\", \"secukupnya Gula\"]', '[\"Bersihkan pindang ambil durinya\", \"Kocok telor dimangkok lalu masukkan ikan pindang kedalam mangkok y berisi telor n masako\", \"Panaskan minyak lalu goreng pindang lalu sisihkan\", \"Tumis bumbu yang dihaluskan lalu masukkan air secukupnya beri garam, gula, kaldu bubuk,motto aduk rata n masukkan pindang yang digoreng tadi aduk rata\", \"Setelah matang angkat n tiriskan siap disajikan\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1693, 4, 'Ikan Pindang Telur Balado', 'Cara membuat Ikan Pindang Telur Balado yang enak dan praktis untuk keluarga.', '[\"2 keranjang ikan (4potong)\", \"2 butir telur ayam\", \"2 siung bawang putih\", \"5 siung bawang merah\", \"4 cabai rawit (sesuai selera)\", \"6 cabai merah keriting (sesuai selera)\", \"2 tomat merah\", \"Garam\", \"Gula pasir\", \"Minyak goreng\"]', '[\"Rebus telur ayam hingga matang. Kupas, bagi dua bagian kemudian goreng\", \"Bersihkan ikan, kemudian goreng setengah matang\", \"Goreng setengah matang bumbu-bumbu : bawang merah, bawang putih, cabai, tomat\", \"Uleg / haluskan bumbu yang sudah digoreng\", \"Tumis bumbu halus, tunggu sampai harum dan berubah warna agak gelap. Tambahkan gula pasir dan garam\", \"Masukan ikan dan telur yang sudah digoreng.\", \"Aduk sebentar. Koreksi rasa\", \"Siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1694, 3, 'Cheese Egg Bread Toast', 'Sajian Cheese Egg Bread Toast yang praktis dan lezat untuk dinikmati bersama.', '[\"2 lembar roti tawar\", \"1/⁴  Keju quick melt\", \"1 buah telur ayam\", \"1/² potong  bawang bombay\", \"Daun bawang\", \"Seledri\", \"Bisa ditambah bakso/sosis\", \"Tomat\", \"Mentega\", \"1 sdm gula pasir\", \"Lada\", \"Saos sambal\"]', '[\"Kocok telur, lalu masukkan parutan keju, irisan bawang bombay, daun bawang, seledri, tomat, bakso/sosis ke dalam telur\", \"Potong roti menjadi segitiga\", \"Panaskan teflon, beri mentega sedikit\", \"Celupkan roti ke dalam kocokan telur, lalu panggang hingga matang\", \"Sajikan dengan saos sambal😉\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1695, 4, 'Telor ceplok cabe hijau', 'Resep praktis Telor ceplok cabe hijau yang bisa dicoba di rumah.', '[\"3 telor ayam\", \"5 bawang merah\", \"4 bawang putih\", \"8 cabe hijau\", \"2 daun salam\", \"1 cm laos\", \"secukupnya Garam\", \"secukupnya Motto\", \"secukupnya Gula\", \"secukupnya Kaldu bubuk\", \"secukupnya Air\", \"secukupnya Minyak\"]', '[\"Panaskan minyak n ceplok telor lalu tiriskan\", \"Iris bawang merah, bawang putih, cabe hijau, salam n laos disiapkan\", \"Panaskan minyak lalu tumis bawang merah, bawang putih, lalu cabe hijau n salam,laos n lalu tambahkan air n beri garam, gula n motto serta kaldu bubuk aduk rata\", \"Angka kepiring kecil n siap disajikan\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1696, 3, 'Dadar telur tauge', 'Resep Dadar telur tauge ala rumahan yang dijamin menggugah selera.', '[\"3 telur ayam\", \"2 batang daun bawang(ambil batangnya aja)\", \"1 mangkok sedang tauge\", \"secukupnya Garam\", \"Minyak goreng\"]', '[\"Campur semua bahan jadi satu kecuali minyak goreng\", \"Siap kan Teflon ukuran sedang.\", \"Panaskan minyak\", \"Tuangkan bahan keatas Teflon yang sudah di panaskan dengan minyak\", \"Membalikkan harus hati hati supaya dadar tidak hancur\", \"Dadar siap di santap buat keluarga\", \"Yang diet debm boleh di coba kok\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1697, 2, 'Semur telur & tahu ala JTT', 'Resep praktis Semur telur & tahu ala JTT yang bisa dicoba di rumah.', '[\"4 butir telur,rebus,kupas\", \"4 bh tahu,potong diagonal,goreng\", \"2 ruas jari lengkuas,geprek\", \"3 lmbr daun salam\", \"1 btng serai,geprek\", \"1 bh kembang lawang/pekak\", \"1 btng kayumanis (3 cm an)\", \"2 btr kapulaga\", \"5 sdm kecap manis (tambah kalo ingin warna lebih pekat)\", \"secukupnya garam,gula merah & asam jawa\", \"secukupnya air (300 ml)\", \"🍅 bumbu halus 🍅\", \"4 siung bawang merah\", \"3 siung bawang putih\", \"1 sdt merica butiran\", \"1/4 bh pala\", \"4 butir kemiri sangrai\", \"2 bh cabe merah keriting (sy skip)\"]', '[\"Tumis bumbu halus sampai harum & matang,masukkan serai,salam,lengkuas,pekak,kapulaga & kayu manis,tumis sebentar. Tambahkan garam,gula,asam jawa & kecap,aduk sebentar saja.\", \"Masukkan telur & tahu,aduk. Tambahkan air. Biarkan mendidih. Cek rasa. Masak sampai kuah menyusut / mengental,tp tdk sampai kering yaa...\", \"Angkat & siap disajikan👌\", \"Agar bumbu lebih meresap ke dlm telur sebaiknya goreng dulu telur rebusnya (jgn lupa sayat² dulu biar ngak meletup),sy td ngak digoreng dulu soalnya lupa😁\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(1698, 3, 'Roti telur keju', 'Resep Roti telur keju ala rumahan yang dijamin menggugah selera.', '[\"3 butir telur\", \"3 lembar roti tawar\", \"1/2 daun bawang (sesuai selera)\", \"5 lembar daun seledri (sesuai selera)\", \"1/2 tomat\", \"4 cabai merah\", \"secukupnya Garam\", \"Keju secukupnya sesuai selera\", \"20 ml susu cair\", \"Mentega untuk menggoreng\"]', '[\"Cincang kasar cabe, tomat, daun bawang dan daun seledri\", \"Potong roti menjadi lima bagian\", \"Parut keju\", \"Kocok telur dengan bahan cincang, tambahkan susu\", \"Panaskan wajan dan lelehkan mentega\", \"Panggang roti, setelah terpanggang di kedua sisi, tuangkan setengah adonan telur, tunggu beberapa menit\", \"Balik sisi, dan tuangkan telur sisanya\", \"Setelah kedua sisi matang, taburkan keju parut, diamkan beberapa menit di dalam wajan dengan wajan ditutupi, agar kejunya meleleh, kurangi api, agar tidak gosong 😂\", \"Selamat mencoba 😊 cocok untuk cemilan\", \"Enak disantap dengan saos pedas 😍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1699, 4, 'Brokoli telur maizena', 'Resep Brokoli telur maizena ala rumahan yang dijamin menggugah selera.', '[\"1 buah brokoli yg ukurang sedang\", \"2 siung bawang putih (iris)\", \"3 siung bawang merang (iris)\", \"2 cabai merah (iris)\", \"Garam & lada (secukupnya)\", \"Air (secukupnya)\", \"1 sdt tepung maizena (dilarutkan dengan air)\", \"1 sdm saori\", \"1 butir telur\"]', '[\"Masukan brokoli ke dalam panci yang berisi air mendidih, taburi garam, aduk2 lalu diamkan kurang lebih 5-10 menit. Saring lalu di tata di atas piring.\", \"Lalu tumis bahan2 yang sudah di iris (bawang putih.merah dan cabai)\", \"Masukan telur, aduk2, masukan saori,air dan terakhir masukan larutan maizena, aduk sampai mengental.\", \"Tuang ke dalam piring yang sudah terbentuk lingkarang brokoli.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1700, 2, 'Tim Telur', 'Sajian Tim Telur yang praktis dan lezat untuk dinikmati bersama.', '[\"1 butir telur\", \"Sejumput bawang bombay cincang\", \"Sejumput jagung manis pipil\", \"Sejumput irisan daun bawang\", \"Sejumput tomat cincang\", \"secukupnya Garam & merica\", \"1 sdm minyak goreng\"]', '[\"Tuang semua bahan ke dalam mangkuk / cetakan tahan panas, aduk rata.\", \"Letakkan mangkuk di atas panci berisi air, didihkan air dan masak sekitar 15 menit sampai telor matang. Tusuk telor dengan tusuk gigi untuk cek kematangan.\", \"Sajikan dengan saus sambal botol.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1701, 2, 'Mie rebus telur pedes', 'Cara membuat Mie rebus telur pedes yang enak dan praktis untuk keluarga.', '[\"3 mie cap tiga telur\", \"2 telur\", \"1 daun bawang\", \"3 bawang putih\", \"2 bawang merah\", \"1/4 lada merah halus\", \"1 tomat\", \"5 cabe keriting\", \"1 selada air\", \"1 minyak secukupnya\", \"1 garam secukupnya\"]', '[\"Pertama-tama bersihkan bawang dan bumbu2 setelah itu di haluskan dan tumis bawang nya saja yaa 🙂 setelah halus panaskan kuali beri sedikit minyak goreng secukup nya kemudian tumis sampai keluar aroma sedap.. selsai menumis panaskan air dan berikan lada bubuk setelah selsai biarkan terlebih dahulu... buat rebus mie pisahkan karena buat kesehatan air mie harus di saring 🤭\", \"Setelah mie udah masak campurkan mir tsb dengan rebusan bumbu pertama.. jangan lupa campurkan telur nya ya hehe, buat menunggu mie masak iris tomat sesuai selera dan beri sedikit selda air biar terlihat beda,, makasih by irham wa 081214943796 📞\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1702, 3, 'Telur Kuah simpel', 'Resep Telur Kuah simpel yang lezat dan mudah dibuat di rumah.', '[\"1 buah telur\", \"1 buah bawang putih\", \"1 buah bawang merah\", \"3 buah cabe rawit\", \"Secukupnya penyedap rasa\", \"Secukupnya garam\", \"1 gelas air putih\"]', '[\"Iris bawang merah bawang putih dan cabai\", \"Tumis dengan api sedang hingga layu\", \"Masukkan telur dan orak arik hingga tidak menggumpal\", \"Tambahkan garam dan penyedap\", \"Masukkan air\", \"Aduk dan sajikan selagi hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1703, 2, 'Orak arik telur', 'Nikmati kelezatan Orak arik telur dengan resep sederhana ini.', '[\"1 butir telur ayam\", \"1 lembar smoked beef\", \"1 siung bawang bombai\", \"1 siung bawang putih\", \"1 lembar bawang daun\", \"1/2 buah tomat merah\", \"Secukupnya merica bubuk dan garam\", \"Pelengkap:\", \"Sepiring nasi putih\", \"Secukupnya mayonese dan saos sambal\"]', '[\"Potong dan iris semua bahan. Kocok lepas telur\", \"Panaskan teflon dgn minyak sedikit. Masukan telur tambahkan bahan2 yg td suda diiris2 diatasnya. Tambahkan merica dan garam. Tunggu hingga telur aga matang baru diaduk2. Masak hingga telur matang seluruhnya.\", \"Sajikan dgn nasi hangat dan baluran mayo dan saos sambal kl suka 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1704, 4, 'Telur Dadar Bihun', 'Sajian Telur Dadar Bihun yang praktis dan lezat untuk dinikmati bersama.', '[\"5 butir Telur Ayam\", \"Secukupnya Bihun Rebus (gunting supaya tidak terlalu panjang)\", \"1 batang Daun Bawang (iris tipis)\", \"1 buah Wortel (parut kasar)\", \"1 bungkus Kaldu Jamur Bubuk\", \"Secukupnya Lada Bubuk\", \"Secukupnya Gula Garam (saya skip karena kaldu jamur sudah gurih)\", \"Secukupnya Keju Parut\", \"Secukupnya Smoked Beef/Sosis Iris (bisa skip)\", \"Secukupnya Bon Cabe (sesuai selera)\", \"Secukupnya Margarin/Minyak Sayur\"]', '[\"Kocok lepas telur, masukkan semua bahan, kocok rata. Masak di atas wajan anti lengket yang sudah diberi margarin. Saya tuang adonan telur 4 kali, jadi 1 resep terdiri dari 4 gulung telur dadar. Foto disamping adalah contoh bahan pelengkap bakso yang saya pisah/tidak dicelup kuah jadi sisanya bisa untuk bahan tambahan masakan lainnya.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1705, 2, 'Telur Dadar Gulung Korea (Gyeranmari)', 'Resep Telur Dadar Gulung Korea (Gyeranmari) ala rumahan yang dijamin menggugah selera.', '[\"2 Butir Telur Ayam (telur omega lebih baik)\", \"2 siung daun bawang. Iris\", \"1/2 pcs wortel. Iris dadu\", \"1/4 butir bawang bombay. Iris dadu\", \"2 Sdm Susu UHT putih\", \"secukupnya Garam, Lada, Margarin\"]', '[\"Masukkan telur, irisan wortel, irisan daun bawang, susu, lada dan garam. Kocok hingga tercampur semua.\", \"Oles teflon anti lengket dengan margarin (asal dioles saja). Tunggu sampai agak panas (api kecil saja).\", \"Kalau teflon sudah panas, masukkan 1/3 adonan telur. Tunggu hingga setengah matang, gulung sebagian.\", \"Tuang adonan telur lagi. Tunggu hingga setengah matang, gulung lagi. Tuang adonan lagi. Lakukan hal tersebut hingga adonan habis.\", \"Kalau sudah matang, segera angkat dari teflon. Lalu dinginkan.\", \"Jika sudah dingin, potong telur gulung secara menyerong.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1706, 2, 'Telor Balado Endolita', 'Telor Balado Endolita - hidangan telur praktis dan lezat.', '[\"6 butir telur (rebus sampai matang, kupas kulitnya)\", \"1 helai daun bawang (iris serong)\", \"Secukupnya air\", \"Minyak goreng untuk menggoreng telur dan menumis bumbu\", \"secukupnya Kecap manis\", \"Bumbu halus:\", \"4 buah cabai merah (bisa disesuaikan dengan selera pedasnya)\", \"4 siung bawang putih\", \"5 siung bawang merah\", \"2 buah kemiri\", \"secukupnya Gula jawa\", \"secukupnya Garam\"]', '[\"Siapkan semua bahan\", \"Goreng telur hingga permukaan telur menjadi coklat berkerut.\", \"Haluskan bumbu yang sudah disiapkan.\", \"Panaskan sedikit minyak dalam wajan, tumis bumbu halus hingga harum, lalu tambahkan irisan daun bawang.\", \"Masukkan telur yang sudah digoreng ke dalam wajan tumisan bumbu, aduk rata.\", \"Tambahkan sedikit kecap manis Dan secukupnya air.\", \"Masak hingga matang, sampai bumbu meresap dan mengental. Test rasa.\", \"Siapkan mangkok saji. Sajikan.\", \"Taraaaaa!!! Telur Balado siap dinikmati. Selamat mencoba😉\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1707, 3, 'Telor Balado Simple', 'Resep Telor Balado Simple ala rumahan yang dijamin menggugah selera.', '[\"4 butir telor\", \"1/4 buncis\", \"Ati ampela (rebus)\", \"Kemangi\", \"1 buah tomat\", \"Bumbu halus :\", \"20 cabe rawit (sesuai selera)\", \"3 cabe merah keriting\", \"4 bawang merah\", \"2 bawang putih\", \"Air (secukupnya)\", \"Garam, gula, penyedap\"]', '[\"Ceplok telor (sesuai selera) Lalu haluskan duo bawang, duo cabe\", \"Panaskan minyak tumis bumbu halus sampai agak menyusut minyaknya lalu tambahkan air secukupnya karna tadi gak saya takar kira2 aja\", \"Bumbui dengan gula, garam dan penyedap lalu masukan buncis dan tomat tunggu sampai setengah layu masukan telor yang sudah di ceplok dan ati ampela yang sudah di rebus aduk2 sampai rata\", \"Setelah air sudah menyusut masukan kemangi tunggu beberapa menit lalu sajikan👌🏻\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1708, 3, 'Telur dadar bawang bombay', 'Telur dadar bawang bombay - hidangan telur praktis dan lezat.', '[\"1 butir telur ayam\", \"1 sdm terigu\", \"1/2 buah bawang bombay\", \"1 siung bawang putih\", \"2 siung bawang merah\", \"1 batang daun solong\", \"1/2 sdt garam\", \"Secukupnya gula pasir\", \"1 sdm air\", \"Secukupnya minyak\"]', '[\"Potong tipis bawang merah, cincang bawang putih, iris kasar bawang bombay dan daun bawang (solong)\", \"Larutkan terigu + gula + garam aduk rata lalu masukan bahan yg sudah di potong\", \"Aduk rata lagi dan tambahkan telur\", \"Panaskan minyak dan goreng hingga kecoklatan, pastikan minyak sudah panas dan dg api sedang ya... selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1709, 3, 'Tahu telor bumbu kacang', 'Tahu telor bumbu kacang - hidangan telur praktis dan lezat.', '[\"2 butir telor\", \"3 buah tahu putih, potong dadu\", \"1 helai daun bawang, iris halus\", \"1 buah mentimun, potong dadu\", \"Secukupnya tauge, rendam air panas\", \"Secukupnya minyak\", \"Secukupnya garam\", \"Bumbu kacang :\", \"100 gram kacang tanah (saya pake kenari goreng atau sangrai)\", \"5 buah cabe rawit merah, goreng sebentar\", \"2 siung bawang putih, goreng sebentar\", \"1 sdm gula merah\", \"Secukupnya garam\", \"Secukupnya air\", \"Pelengkap :\", \"Bawang goreng\", \"Kecap manis\"]', '[\"Kocok telur dengan garam dan daun bawang, lalu tambahkan tahu yg sdh dipotong dadu, goreng sampe matang. Sisihkan.\", \"Masukan dalam blender cabe, bawang putih, kacang, gula merah, dan air blender sampe halus.\", \"Didihkan bumbu kacang, tambahkan garam test rasa.\", \"Tata tauge dan mentimun diatas telur yg sdh digoreng, siram dengan bumbu kacang lalu taburi dengan bawang goreng. Sajikan😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1710, 4, 'Talor (tahu telor)', 'Cara membuat Talor (tahu telor) yang enak dan praktis untuk keluarga.', '[\"2 biji tahu kuning\", \"1 butir telur ayam\"]', '[\"Benyak tahu kuning sampai halus\", \"Lalu masukan ke dalam mangkuk\", \"Pecahkan telur ayam lalu masukan telur ke dalam mangkuk berisi tahu yang sudah di haluskan\", \"Aduk hingga merata\", \"Lalu masukan ke dalam kompor goreng sampai kering\", \"Lalu tuangkan kedalam piring\", \"Jadi deh....😀😀😀😀\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1711, 2, 'Sosis telur gulung', 'Resep praktis Sosis telur gulung yang bisa dicoba di rumah.', '[\"1 butir telur ukuran besar\", \"9 sendok air\", \"2 sosis ayam (optional)\", \"Secukupnya garam\", \"Secukupnya penyedap rasa\"]', '[\"Kocok telur, garam, penyedap rasa dan air sampai larut pakai sendok aja kocok telurnya.. Kalau telur ukuran kecil air bisa dikurangi 1 sendok\", \"Untuk sosis bisa digoreng terlebih dahulu agar telurnya nanti bisa menempel saat digulung.. Jika tidak suka sosis bisa diganti dengan nugget, pentol, tempe, tahu\", \"Panaskan minyak sampai benar-benar panas.. Tuang 1 sdm telur kedalam minyak panas langsung digulung menggunakan tusuk sate atau pun lidi.\", \"Tips : saat menggoreng telur jngan langsung dituang banyak karna telur tidak akan berbentuk seperti jaring, cukup 1 sendok saja..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1712, 4, 'Telur Masak Tomat', 'Telur Masak Tomat - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"Bahan di kocok :\", \"4 butir telur\", \"Secukupnya lada bubuk\", \"1/4 sdt minyak wijen\", \"Bahan di tumis :\", \"4 bawang putih, cincang kasar\", \"4 cabe rawit, cincang (optional)\", \"2 buah tomat merah besar, potong2 kasar\", \"100 ml air\", \"Secukupnya kaldu bubuk & lada bubuk\"]', '[\"Kocok lepas bahan telur, goreng orak arik. Sisihkan\", \"Panaskan 1 sdm minyak goreng, tumis bawang putih + cabe rawit. Tambahkan potongan tomat, aduk2.\", \"Tambahkan air, biarkan mengental\", \"Bumbui dengan kaldu bubuk + lada bubuk. Tes rasa\", \"Angkat, siramkan di atas telur orak arik. Hidangkan dengan nasi panas..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1713, 2, 'Telur dan terong sambel', 'Cara membuat Telur dan terong sambel yang enak dan praktis untuk keluarga.', '[\"2 buah telur\", \"1 terong\", \"Gula merah\", \"Bumbu yg di haluskan\", \"4 buah Cabai  (karna ga doyan pedes)\", \"1 Tomat\", \"5 siung Bawang merah\", \"1 siung Bawang putih\", \"Garam\"]', '[\"Ceplok telor dan goreng tetong\", \"Haluskan bumbu bisa di ulek bisa di blender sesuai selera\", \"Setelah bumbu halus masukan bumbu di penggorengan yg berisi minyak goreng panas, oseng2 bumbu sampai bumbu terasa matang setelah itu campurkan air sedikit di kira2 aja\", \"Tunggu sampai bumbu mendidih lalu masukkan telor dan terong yg di goreng tadi\", \"Aduk2 sampai telor dan terong tercampur bumbu hingga meresap\", \"Lalu sajikan 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1714, 4, 'Telur Gulung Korea (gyeran mari) Simple', 'Cara membuat Telur Gulung Korea (gyeran mari) Simple yang enak dan praktis untuk keluarga.', '[\"3 btr telur ayam\", \"1 bh wortel ukuran kecil dirajang(sy ga pake krn G ada stok 😁)\", \"3 lembar daun kol bagian tipis, di ranjang tipis2\", \"2 btg daun bawang, potong tipis2\", \"1 siung bawang putih, cincang (klo yg ga suka bau nya, skip aja)\", \"1/2 sdt garam\", \"1/2 sdt kaldu bubuk\"]', '[\"Bahan2 semua dirajang\", \"Kocok telur sampai berbuih tercampur kuning dan putih nya, kemudian masukkan semua sisa bahan... Aduk2 lagi\", \"Panaskan teflon, masukkan sepertiga telur, ratakan, tunggu agak matang bagian atas nya...gulung di dalam teflon, sisakan sedikit...\", \"Masukkan lagi sepertiga bagian telur... Masak sampai agak matang.. Lanjutkan lagi menggulung, sisakan lagi sedikit menggulungnya mesti rapat bun, n masih agak basah telur nya, supaya tidak be rongga. Punya sy sempat sy tinggal sebentar, panggilan baby😁\", \"Masukkan sisa telur, sampai agak matang, gulung lagi.. Sampai habis, kemudian biarkan sebentar sampai matang sempurna... Setelah itu, angkat dan potong2..*jangan potong terlalu tipis bun,,, tar sobek 😁\", \"Selamat mencoba.... 😊😊😊😊\", \"Kalo saya bisa, bunda juga pasti bisa! ^^\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1715, 3, 'Tumis telor ceplok', 'Cara membuat Tumis telor ceplok yang enak dan praktis untuk keluarga.', '[\"3 telor ceplok\", \"3 bawang merah rajang\", \"2 bawang putih rajang\", \"2 cabai hijau besar rajang\", \"1 cabai merah besar rajang\", \"1 tomat merah iris\", \"Kecap manis\", \"Garam gula pasir air\"]', '[\"Tumis bumbu rajang sampai harum lalu masukkan air trus tambah kecap manis, gula pasir, garam.\", \"Kemudian masukkan telur dan aduk2 sebntar.\", \"Siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1716, 3, 'Sandwich telur mayo', 'Sandwich telur mayo - hidangan telur praktis dan lezat.', '[\"Roti tawar\", \"2 butir Telur\", \"secukupnya Mayonaise\", \"secukupnya Susu kental manis\", \"secukupnya Garam\", \"secukupnya Merica bubuk\", \"1/2 Alpukat\", \"1 butir Tomat\"]', '[\"Rebus telur hingga matang, lalu kupas, cincang putih telur sisihkan\", \"Hancurkan kuning telur, tambahkan mayonaise 1 sendok makan,susu, mrica bubuk, garam secukupnya masukkan irisan alpukat, tomat aduk sampai rata, (usahakan jangan terlalu lembek, biar hasilnya legit)\", \"Panggang roti tawar sebentar lalu olesi dengan isian tutup kembali dengan roti, potong segitiga atau sesuai selera\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1717, 4, 'Telur gulung sosis', 'Cara membuat Telur gulung sosis yang enak dan praktis untuk keluarga.', '[\"3 butir Telur\", \"2 biji Sosis\", \"secukupnya Royco\"]', '[\"Kocok telur kemudian goreng menggunakan teplon dengan api kecil saja.\", \"Goreng sosis.\", \"Setelah telur matang letakkan sosis kemudian gulung telur.\", \"Dinginkan kemudian potong2 sesuai selera lalu sajikan...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1718, 4, 'Pempek udang rebon isi telur dadar', 'Resep Pempek udang rebon isi telur dadar yang lezat dan mudah dibuat di rumah.', '[\"1/2 kg Sagu\", \"1/4 kg Terigu\", \"secukupnya Udang rebon\", \"Penyedap, disaranin tante pake magic\", \"Air panas\", \"3 butir Telur\", \"Mie kuning basah\", \"Ketimun\", \"Bumbu halus untuk kuah :\", \"Ebi / udang kering\", \"Cabe rawit merah (saya suka pedas, kira2 30bj)\", \"6-8 ukuran sedang Bawang putih sekitar\", \"3 bungkus Asam jawa\", \"sedikit Cuka\", \"secukupnya Gula merah\", \"Garam\", \"Penyedap\", \"Air untuk kuah\"]', '[\"Haluskan udang rebon secukupnya\", \"Buat dadar telur dengan garam dan penyedap secukup nya, kalo sudah langsung potong2 sesuai selera\", \"Campur sagu, terigu, udang rebon yg sudah halus dan magic. jika sudah merata ditambah air panas sedikit sedikit sampai agak kalis, jgn sampai kelembekan / encer\", \"Jika adonan sudah siap, bentuk pempek dengan isian telur dadar, lalu rebus sampe pempek mengapung, lalu sisihkan\", \"Untuk kuah, haluskan cabe, bawang putih, dan ebi\", \"Rebus air hingga mendidih, lalu masukan bumbu halus, ditambah asam jawa, gula merah, cuka, garam, dan penyedap\", \"Untuk pempek yg sudah direbus bisa masuk wadah dan disimpan dikulkas, jika ingin dimakan tinggal goreng, kuah pun bisa disimpan dikulkas, jika ingin dimakan tinggal dipanaskan\", \"Note : untuk kuah yg ga mau pedes jg bisa pake cabe merah biasa. Jd tinggal buat sambal terpisah nya aja\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1719, 2, 'Rendang telur', 'Resep Rendang telur ala rumahan yang dijamin menggugah selera.', '[\"5 telur ayam\", \"Tahu (boleh pakai/enggak)\", \"Kentang (boleh pakai/enggak)\", \"secukupnya Garam\", \"secukupnya Gula\", \"secukupnya Merica\", \"Ketumbar bubuk (boleh pakai,boleh enggak)\", \"secukupnya Kecap\", \"1 sachet bumbu jadi\", \"Santan kental\"]', '[\"Goreng kentang,tahu,dan telor\", \"Setelah di goreng,tumis bumbu jadi sampai aroma nya keluar, kemudian masukkan garam,merica, ketumbar,gula,dan kecap secukupnya tambahkan air\", \"Setelah bumbu di tumis masukkan telur,tahu,dan kentang,tunggu sampai bumbu masuk kedalam\", \"Rendang telur siap untuk di nikmati bersama nasi hangat dan kerupuk\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1720, 2, 'Kentang telor kecap simple', 'Nikmati kelezatan Kentang telor kecap simple dengan resep sederhana ini.', '[\"5 telor goreng mata sapi\", \"250 kentang, potong agak besar, goreng\", \"secukupnya Kecap manis\", \"secukupnya Garam, gula, lada\", \"Rajang halus\", \"1 siung bawang bombay\", \"2 siung bawang merah\", \"4 siung bawang putih\", \"Pelengkap\", \"Irisan daun bawang\", \"Irisan cabe rawit/merah (boleh banyak, jika ingin agak pedas ya)\", \"Air\"]', '[\"Tumis sampai harum bahan yg di rajang halus 1 per 1 di minyak yg tdk trllu banyak.\", \"Masukkan telur dan kentang yg telah di goreng, aduk, lalu beri air sedikit, beri kecap dan bumbu lainnya.\", \"Setelah tercampur rata, koreksi rasanya. Jika kurang kecap, tambahin kecap, dst\", \"Sajikan, selamat menikmati\", \"Untuk isian menu nya bisa di gonta ganti ya, boleh pake tahu, ayam, tempe, sesuaiin selera aja.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1721, 3, 'Telur mix sayur beku #bandung_recookSariUtamiKimdonghwa', 'Resep Telur mix sayur beku #bandung_recookSariUtamiKimdonghwa ala rumahan yang dijamin menggugah selera.', '[\"2 btr telur\", \"1 cup / secukupnya sayuran beku\", \"1/3 sdt/secukupnya garam\", \"1 sdt gula pasir\", \"Secukupnya lada bubuk\", \"2 siung bawang putih\", \"3 siung bawang merah\"]', '[\"Iris bawang merah dan bawang putih. Siapkan wajan beri sedikit minyak. Tumis bawang merah dan bawang putih hingga harum. Sisihkan dipinggir wajan. Masukkan telur,diamkan sebentar-orak arik. Masukkan sayuran beku. Aduk semua bumbu,telur dan sayuran. Beri gula garam lada dan sedikit air. Tumis sebentar hingga air menyusut dan bumbu meresap. Tes rasa, angkat dan sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1722, 2, '08.Telur dadar kelapa parut', 'Resep praktis 08.Telur dadar kelapa parut yang bisa dicoba di rumah.', '[\"2 butir telur ayam\", \"4 sdm kelapa parut\", \"3 bh bawang merah(di iris)\", \"2 bh cabe merah(di potong bulat)\", \"Sedikit royco\", \"Sedikit lada\", \"Secukupnya garam\", \"4 sdt minyak utk menggoreng\"]', '[\"Siapkn semua bahan\", \"Campur semua bahan jd 1,lalu aduk hingga rata\", \"Panaskn wajan,msukkn minyak,goreng hingga kecoklatan.angkat.\", \"Selamat mencoba....😉😉\", \"Hidangkn dgn kasih syg,psti dech suami & anak2 ketagih.😍😍😍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1723, 3, 'Sandwich telur', 'Sandwich telur - hidangan telur praktis dan lezat.', '[\"4 helai roti tawar\", \"1 butir telur\", \"4 lembar selada\", \"secukupnya tomat\", \"saos sambal\", \"2 sdm mentega\", \"secukupnya keju tabur\"]', '[\"Kocok telur lalu dadar dan bagi menjadi 4 potong\", \"Oleskan mentega pada roti dan panggang sebentar\", \"Kemudian masukan isian roti yaitu selada, tomat, dadar telur, dan keju tabur\", \"Beri saus diatasnya tutup roti menjadi segitiga dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1724, 2, 'Pare goreng telur udang', 'Pare goreng telur udang - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"pare\", \"Telur (tergantung selera)\", \"Udang (buang kepalanya)\", \"Minyak\", \"Bumbunya :\", \"Bawang merah (iris tipis)\", \"Bawang putih\", \"Cabe\", \"Tomat\", \"Terasi sedikit aja (tergantung selera)\", \"Penyedap rasa (saya pake masako ayam)\", \"Garam\"]', '[\"Iris tipis pare, taruhin garam, remas-remas sampai keluar airnya (biar pahitnya hilang), abis itu cuci bersih parenya, ulangi jika masih berasa pahit\", \"Cuci udang sampai bersih, buang kepalanya\", \"Untuk bumbunya, cabe, terasi, bawang putih, tomat, taruhin garam kemudian di ulek hingga alus\", \"Bawang merah yg sudah diiris tipis goreng hingga layu lalu masukan bumbu yang sudah dihaluskan tadi, tambahkan masako sesuai selera, goreng setengah matang\", \"Lalu masukan udang yg sudah dibersihkan tadi, goreng hingga berubah warna jadi merah, setelah itu masukan parenya, oseng-oseng sebentar lalu masukkan telur kemudian di aduk hingga merata\", \"Masak hingga matang, jangan lupa icip-icip rasanya, dan siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1725, 3, 'Cireng+telur mini', 'Resep praktis Cireng+telur mini yang bisa dicoba di rumah.', '[\"1/4 tepung tapioka\", \"15 sdm terigu\", \"3 bawang putih (halus)\", \"Daun bawang secukupnya(rajang kecil\\\")\", \"secukupnya Garam,micin\", \"1 butir telur (untuk campuran buat telor mini)\", \"secukupnya Air es\", \"Plastik kecil memanjang\"]', '[\"Siapkan wadah masukkan semua bahan tambahkan bumbu. Lalu masukkan air aduk merata sampai agak mengental lalu taburkan daun bawang aduk kembali.\", \"Potong plastik sesuai panjang cireng yg diinginkan. Kemudian sisahkan separuh campur kan telur aduk lagi merata. Untuk membuat telurnya. Masukkan plastik juga. Sama dg cireng tadi.\", \"Langkah terakhir siapkan dandang beri air. Tunggu airnya mendidih lalu masukkan satu persatu gulungan cireng + telur mininya.\", \"Kalau sudah mengapung lalu cek tusuk dengan tusuk gigi. Untuk melihan kematangannya merata atau tidak.\", \"Jika matangnya sudah merata angkat dan tiriskan.\", \"Dimakan tanpa digoreng juga enak. Kalau saya digoreng inilah hasil keduanya. Traalaa\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1726, 2, 'Sambal terasi pnyet telur', 'Resep praktis Sambal terasi pnyet telur yang bisa dicoba di rumah.', '[\"15 cabe rawit (sesuai selera)\", \"8 buah bawang merah\", \"4 buah bawang putih\", \"1 buah tomat\", \"secukupnya Terasi\", \"Garam, gula, penyedap\", \"Minyak\", \"2 buah telur rebus\"]', '[\"Goreng tomat,bawang putih, bawang merah, cabe (sy gorengnya smpek agak kering? dan terasi..\", \"Ulek tambahkan garam,gula,penyedap test rasaaaa\", \"Penyet telur rebus..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1727, 2, 'Tumis Brokoli Telur Orak Arik', 'Olahan telur sederhana: Tumis Brokoli Telur Orak Arik yang mudah dibuat.', '[\"1 buah brokoli ukuran besar\", \"1/2 buah bawang bombai ukuran besar, iris\", \"1 butir telur ayam\", \"Secukupnya garam\", \"Secukupnya gula\", \"1 sdm minyak sayur untuk menumis\", \"100 ml Air\", \"Bumbu halus\", \"2 siung bawang putih\", \"2 siung bawang merah\"]', '[\"Potong brokoli sesuai selera. Cuci bersih kemudian rendam dengan air garam selama 10 menit. Kemudian tiriskan\", \"Panaskan wajan dan tuang minyak sayur. Masukkan irisan bawang bombai. Tumis sampai setengah matang\", \"Masukkan bumbu halus. Tumis sampai setengah matang\", \"Masukkan telur, tunggu sampai setengah matang baru diaduk-aduk\", \"Setelah telur tercampur, masukkan brokoli. Masak brokoli sampai setengah matang. Kemudian tambahkan gula, garam, dan air\", \"Masak brokoli sampai cukup matang kemudian segera matikan api agar sayur masih terasa fresh dan tidak berubah warna.\", \"Tumis brokoli telur siap disajikan. Bisa ditambahkan taburan bawang goreng apabila suka\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1728, 2, 'Lumpia bihun telur', 'Lumpia bihun telur - hidangan telur praktis dan lezat.', '[\"15 lembar lumpia\", \"4 butir telur ayam\", \"3 batang daun bawang\", \"1 siung bawang putih\", \"1 bks kecil bihun (bisa ganti soun)\", \"1 1/2 bks penyedap rasa sapi\", \"Minyak goreng\"]', '[\"Rendam bihun dengan air\", \"Iris bawang daun dan bawang putih terlebih dahulu\", \"Masukan telur dan penyedap\", \"Buka lumpia dan masukan bihun lalu 2 sdm telur, lipat lalu goreng di minyak dengan api sedang\", \"Angkat lalu sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1729, 4, 'Omlet telur (DEBM)', 'Nikmati kelezatan Omlet telur (DEBM) dengan resep sederhana ini.', '[\"2 butir telur ayam / bebek\", \"1 buah wortel iris kotak/ korek api\", \"5 buah buncis iris kecil\", \"2 buah cabe rawit/ sesuai selera\", \"secukupnya Daun pre nGaram\", \"Minyak untuk menggoreng\"]', '[\"Masukan wortel, buncis, cabe dalam mangkok\", \"Tambahkan telur, daun pre n garam\", \"Campur n kocok smua jd 1\", \"Panaskan penggorengan yg sdh dberi minyak, goreng sampai kecoklatan angkat n sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1730, 4, 'Telor dadar campur cornet', 'Telor dadar campur cornet - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"4 butir telor\", \"1 batang daun bawang\", \"5 bawang merah\", \"4 bawang putih\", \"secukupnya Garam\", \"secukupnya Motto\", \"secukupnya Kaldu bubuk\", \"3 sdm cornet\"]', '[\"Pecahkan telor kedalam mangkok, masukkan irisan bawang merah, bawang putih n daun bawang, tambahkan garam, motto n kaldu bubuk,aduk rata tambahkan cornet aduk rata kembali\", \"Panaskan minyak lalu goreng telor dadar cornet sampai matang,angkat n hidangkan dengan nasi panas\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1731, 4, 'Telur dadar cah taoge', 'Telur dadar cah taoge - hidangan telur praktis dan lezat.', '[\"1 ons taoge\", \"2 btr telur ayam\", \"1 btg daun bawang\", \"1/2 btr tomat\", \"1 sdt kaldu bubuk\", \"Sejumput merica\", \"Secukupnya minyak goreng\", \"Bumbu halus\", \"2 siung bawang putih\", \"4 siung bawang merah\", \"3 biji cabe rawit\"]', '[\"Kocok lepas telur buat dadar lalu setelah dingin iris2 menyerupai mie\", \"Panaskan minyak lalu tumis bumbu halus hingga harum lalu masukan irisan daun bawang dan tomat lalu masukan taoge kaldu bubuk dan merica aduk rata terakhir masukan irisan telur masak sebentar aja hingga taoge layu dan telur dadar cah taoge siap utk disajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1732, 4, 'Telur dadar dengan minyak wijen', 'Cara membuat Telur dadar dengan minyak wijen yang enak dan praktis untuk keluarga.', '[\"1 butir telur ayam\", \"Sejumput garam\", \"1 sdm minyak wijen\"]', '[\"Kocok lepas telur dan garam. Panaskan wajan, beri minyak wijen. Goreng telur hingga matang. Sajikan selagi hangat 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1733, 2, 'Tahu telur ceplok sambal granat 🍳😤😤😤', 'Resep Tahu telur ceplok sambal granat 🍳😤😤😤 yang lezat dan mudah dibuat di rumah.', '[\"2 butir telur\", \"6 biji tahu bandung\", \"1 lembar daun salam\", \"seruas jari lengkuas\", \"Bumbu halus :\", \"35 biji cabai rawit setan\", \"10 biji cabai merah\", \"6 siung bawang merah\", \"2 siung bawang putih\", \"1 1/2 butir kemiri\", \"1 sdt garam\"]', '[\"Cuci tahu sampai bersih,potong\\\" sesuai selera.\", \"Panaskan minyak goreng tahu dan telur.\", \"Tumis bumbu halus,lengkuas,daun salam hingga harum.\", \"Masukkan tahu yg sudah di goreng tadi,aduk sampai rata.\", \"Tambahkan air,diamkan hingga mendidih.\", \"Masukkan telur ceplok,aduk perlahan dan diamkan kembali hingga bumbu meresap.\", \"Jika air sudah menyusut koreksi rasa,angkat dan sajikan 😋😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1734, 2, 'Tahu telur bumbu kacang khas Malang', 'Cara membuat Tahu telur bumbu kacang khas Malang yang enak dan praktis untuk keluarga.', '[\"2 buah tahu ukuran sedang potong dadu kecil\", \"3 buah telur\", \"Secukupnya cabe rawit (opsional)\", \"4 sendok minyak goreng\", \"2 sendok kecap manis\", \"3 siung bawang putih\", \"secukupnya Garam, gula\", \"Secukupnya air putih\", \"4 sendok kacang tanah goreng\"]', '[\"Potong dadu kecil tahu\", \"Kocok lepas telur\", \"Campurkan potongan tahu kedalam telur lalu bumbui dengan garam, penyedap dan merica. Aduk hingga rata\", \"Panaskan minyak goreng lalu goreng dengan api sedang hingga berwarna kuning kecoklatan\", \"Bawang putih, kacang goreng, gula, garam, dan cabe uleg hingga halus\", \"Setelah mulai halus, tuangkan air sedikit2 dan kecap manis. Aduk hingga rata hingga mengental\", \"Sajikan bumbu kacang diatas tahu telur yg telah digoreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1735, 4, 'Pizza Telur', 'Resep Pizza Telur ala rumahan yang dijamin menggugah selera.', '[\"4 btr telur ayam\", \"2 btg daun bawang\", \"1 btg daun seledri\", \"1 bh sosis dicincang\", \"1 bh bawang bombay\", \"secukupnya garam\"]', '[\"Campur semua bahan aduk sampai rata.\", \"Siapkan teflon masukan margarin setelah panas tuang telur ke dalam teflon. Api kecil saja biar tdk gosong.\", \"Tutup teflon kl bagian atasnya sudah kaku lalu dibalik, sebentar saja, angkat.\", \"Cocol dg saos tomat dan mayonaise.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1736, 2, 'Pempek dos isi telur dan tanpa isi cocok untuk bakul jualan+tips', 'Resep praktis Pempek dos isi telur dan tanpa isi cocok untuk bakul jualan+tips yang bisa dicoba di rumah.', '[\"1/2 kg tp terigu\", \"1/2 kg tp sagu udang\", \"1/2 kg tp beras\", \"2 sdm bawang putih halus\", \"3 sdm gula\", \"2 sdm garam\", \"2 bh telur\"]', '[\"Semua bahan diaduk kecuali telur,tambahkan air mendidih secukupnya,aduk rata, tambahkan telur, aduk sampai bisa dibentuk, bentuk pempek beri isian, rebus diair mendidih,beri 2 sdm minyak, rebus sampai mengapung,selesai\", \"Tp itu singkatan dari tepung, tepung sagu yg digunakan namanya tepung sagu udang, ada juga tepung sagu gbr p tani,semua tp sagu bisa digunakan untuk pempek\", \"Sering kita lihat bikin pempek dari tp tapioka,tp tapioka bisa dibuat pempek tapi sudah pasti pempeknya alot keras dan tidak bisa distok,tp tapioka bisa digunakan sebagai pengental adonan saja\", \"Setelah adonan diberi air mendidih, gunakan spatula atau sendok kayu untuk mengaduk adonan, bentuk pempek setelah adonan hangat hangat kuku\", \"Untuk isian pempek telur, untuk bakul jualan 1 telur ditambah 3 sdm tp terigu,agar adonan lebih kental mudah diisikan dan juga lebih hemat, untuk 3/4 kg adonan pempek cuma menggunakan 2 telur dan 6 sdm tp terigu\", \"Gunakan air yg benar benar mendidih saat memasukkan pempek,jika tidak mendidih pempek akan lengket didasar panci, dan tidak akan mengapung\", \"Semoga bermanfaat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1737, 4, 'Balado telur tahu teri pete pedes', 'Olahan telur sederhana: Balado telur tahu teri pete pedes yang mudah dibuat.', '[\"6 butir telur\", \"1 potong tahu\", \"1/2 ons teri\", \"2 papan pete\", \"Bumbu👇\", \"10 siung bawang merah\", \"5 siung bawang putih*me cukup 4 siung aja\", \"4 buah cabai besar*me buang isinya\", \"30 buah cabai rawit\", \"Penyedap rasa\", \"Gula\", \"Garam\", \"secukupnya Air\"]', '[\"Rebus telur lalu goreng sekalian tahu ma terinya ya bunda*pisah2 gorengya lalu tiriskan\", \"Haluskan semua bumbu...*me duo bawang saya goreng dlu ya bunda kecuali duo cabainya baru di blender😁\", \"Tumis bumbu hingga harum masukin garam,gula,penyedap+air sedikit tes rasa ya bunda..\", \"Masukin telur,tahu masak sebentar..setelah mau angkat baru masukin teri+ pete ya bunda*me suka pete yg agak masih mentah gitu..trus anggkat dan sajikan😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1738, 4, 'Maklor [makaroni+telor]', 'Buat Maklor [makaroni+telor] yang nikmat dengan langkah-langkah mudah ini.', '[\"500 grm Makaronia\", \"3 butir Telur\", \"5 siung Bawang merah\", \"3 siung Bawang putih\", \"sesuai selera Merica Bubuk\", \"2 batang Daun bawang\", \"sesuai selera Garam\", \"secukupnya Kaldu bubuk(sya pake magiz lezat)\", \"2 biji Otak otak atau sosis Iris sesuai selera\", \"secukupnya Minyak sayur\"]', '[\"Terlebih dahulu didihkan air untuk merebus makaroni sekitar 5-6 menit ya sya lupa gk liat jam😁.Sambil nunggu matang kita iris semua bahan bahan diatas tadi seperti bawang merah bawang putih dan daun bawang,digambar sya tambahkan irisan cabai ya krn yg makan orng dewasa dn msih sya tmbah kan saos sambal...hehehehe\", \"Angkat makaroni yg sudah matang dan tiriskan.setelah itu siapkan mangkuk besar dan sendok atau garpu msuk kan smua bahan diatas ke dalam mangkuk beserta telur dan makaroni yg sudah tiris tersebut, kocok jdi satu.\", \"Setelah semua tercampur, siapkan wajan atau teflon besar diberi minyak dan nyalakan api, setelah minyak agak panas msuk kan smuanya terus aduk\\\" atau orak arik hingga matang dan siap dihidangkan.\", \"Dan...taraaaaaa....sudah siap disantap...yummmiiiii😍😍. Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1739, 2, 'Telor ceplok masak kecap', 'Resep Telor ceplok masak kecap yang lezat dan mudah dibuat di rumah.', '[\"4 buah telur\", \"3 bh bawang putih, iris\", \"5 bh bawang merah, iris\", \"7 bh cabe rawit hijau yang besar dan tua, iris\", \"Secukupnya air\", \"Secukupnya minyak goreng\", \"Secukupnya kecap manis\", \"Secukupnya garam dan kaldu bubuk\"]', '[\"Goreng telur menjadi telur mata sapi, sisihkan\", \"Tumis iris an bawang dan cabe rawit sampe matang\", \"Masukkan air secukupnya (kalau saya sekitar 100 ml)\", \"Masukkan telur yang sudah digoreng\", \"Bumbui dengan garam, kaldu bubuk dan kecap manis\", \"Cicipi dan sesuaikan selera\", \"Bila sudah pas, masak dengan api kecil sampai kuah menyusun, siap dihidangkan\", \"Enak dan meresap ke telur nya 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1740, 2, 'Gulai Telur & Kentang', 'Gulai Telur & Kentang - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"Bumbu halus:\", \"10 buah cabai merah keriting\", \"6 siung bawang merah\", \"6 siung bawang putih\", \"3 cm kunyit\", \"3 cm lengkuas\", \"3 cm jahe\", \"1 sdt ketumbar sangrai\", \"50 ml minyak\", \"Untuk tumisan:\", \"Secukupnya minyak\", \"2 lembar daun salam\", \"5 lembar daun jeruk\", \"2 batang serai\", \"10 buah telur matang\", \"3 buah kentang rebus\", \"3 buah asam kandis\", \"500 ml santan cair\", \"150 ml santan kental\", \"1 sdm garam\", \"1 sdm merica\", \"1/2 sdm gula\"]', '[\"Rebus telur & kentang. Sisihkan.\", \"Blender kasar semua bumbu halus (sesuai resep diatas)\", \"Tumis daun salam, daun jeruk, dan serai. Tambahkan secukupnya garam, lada dan gula.\", \"Tuang bumbu halus dari blender. Tumis sampai harum.\", \"Masukkan telur & kentang. Aduk rata. Lalu tuang santan cair. Aduk & masukkan asam kandis. Aduk sampai mengental.\", \"Terakhir, masukkan santan kental. Aduk & angkat asam kandisnya. Tambahkan garam & gula sesuai selera.\", \"Siap dihiangkan!😊\", \"Kalo mau kuah yg lebih cair, boleh disaring dulu kuah gulainya baru dituang ke mangkuk. Enjoy💖\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1741, 3, 'Telur Dadar Gulung isi Suka Suka #Ketopad', 'Sajian Telur Dadar Gulung isi Suka Suka #Ketopad yang praktis dan lezat untuk dinikmati bersama.', '[\"5 butir telur utuh (cari yang ukurannya besar)\", \"1/2 sdt royco rasa sapi\", \"30 gram keju meg cheddar warna merah parut\", \"1 lembar daun bawang iris tipis beserta bagian putihnya\", \"1/2 biji cabe merah besar, hilangkan bijinya, iris tipis\", \"1 biji sosis kibif original potong memanjang asal saja\", \"Sejumput merica bubuk\", \"Secukupnya minyak barco untuk menggoreng\"]', '[\"Dalam wadah, campur telur, royco, merica. Aduk dengan whisk sampe rata. Masukkan daun bawang, cabe dan keju. Aduk rata lagi.\", \"Panaskan teflon pakai api kecil saja, tuang minyak secukupnya, ratakan. Tuang telur seperti menggoreng dadar, tata sosis di pinggiran teflon lalu gulung telur. Tunggu agak kering, tuang lagi telur, tata sosis lagi. Selesaikan sampai habis dan matang. Tunggu agak dingin sekejap, potong potong.\", \"Dadar gulung siap disajikan dan dinikmati.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1742, 4, 'Telur dadar sosis + mozzarella', 'Buat Telur dadar sosis + mozzarella yang nikmat dengan langkah-langkah mudah ini.', '[\"4 butir telur ayam\", \"1 buah sosis besar, iris tipis\", \"2 lembar daun bawang, iris tipis\", \"secukupnya Lada, garam, gula\", \"secukupnya Keju mozzarella parut\"]', '[\"Kocok telur, daun bawang, sosis, garam, gula dan lada sampai tercampur rata\", \"Siapkan teflon, olesi margarin, masak telur dengan api kecil, tutup penggorengan\", \"Setelah setengah matang, beri taburan keju mozzarrella diatasnya, dan kembali ditutup sampai telur matang dan keju meleleh\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1743, 2, 'Toge cah telur', 'Toge cah telur - hidangan telur praktis dan lezat.', '[\"Toge\", \"1 btr telur\", \"Daun bawang,iris\", \"2 siung bawang putih,cincang\", \"5 bh cabe rawit,iris\", \"Garam\", \"Kaldu totole\"]', '[\"Toge buang akarnya,cuci bersih\", \"Tumis bawang putih,setelah wangi masukan telur aduk-aduk.kemudian toge aduk-aduk lagi masukan daun bawang,cabe,garam,aduk-aduk sebentar,angkat sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1744, 3, 'Sup telur jagung manis', 'Resep praktis Sup telur jagung manis yang bisa dicoba di rumah.', '[\"3 buah jagung manis disisir\", \"4 buah worteel potong bulet tipis ya\", \"Buncis (sesuai selera) kalo saya 1 kg buncis saya ambil 1/2\", \"Daging ayam (dada ayam fillet)\", \"Sosis sapi dipotong ya jd brapa bagian\", \"2 biji Telur (kocok lepas)\", \"2 sdm Tepung maizena (larutkan dg sedikit air)\", \"Bumbu\", \"1 bulatan  Bawang bombay cincang\", \"2 biji  Bawang putih cincang\", \"Air secukupnya u/ merebus\", \"Gula\", \"Garam\", \"Penyedap rasa ayam\", \"Merica\"]', '[\"Rebus jagung,buncis,wortel dan daging ayam samapi empuk\", \"Masukan bawang bombay dan bawang putih\", \"Apa bila semuanya sudah trlihat empuk kira2 tambah kan air lagi, biarkan sampai mendidih\", \"Jika air sudah mendidih masukan tepung maizena, kemudian masukan telur yg sudah dikocok lepas,diamkan sejenak, lalu aduk rata\", \"Masukan sosis beserta gula,garam,merica,dan penyedap rasa,aduk rata\", \"Tes rasa dulu ya.kalo saya rasanya cenderung manis gurih😊\", \"Kalo udah pas rasanya.. Biarkan sosis sampai mengembang ya. 😃\", \"Jadi deh\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1745, 2, 'Tumis telor sosis manis', 'Resep Tumis telor sosis manis ala rumahan yang dijamin menggugah selera.', '[\"3 buah sosis\", \"1 butir telur ayam kampung\", \"secukupnya kecap asin\", \"1/2 sdt lada bubuk\", \"secukupnya air\"]', '[\"Goreng telur dan di orek, masukan irisan sosis, orek lagi sebentar..\", \"Tambahkan air, lada, dan kecap asin, tes rasa...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1746, 2, 'Telur balado', 'Sajian Telur balado yang praktis dan lezat untuk dinikmati bersama.', '[\"4 btr telur ayam rebus\", \"bumbu yg dihaluskan\", \"3 bh cabe merah besar\", \"5 bh rawit merah\", \"3 siung bawang merah\", \"2 siung bawang putih\", \"3 btr kemiri\", \"1 btg sereh\", \"secukupnya jahe\", \"1 lbr daun salam\", \"1 btg kayu manis\", \"garam, gula, penyedap\", \"minyak untuk menumis\"]', '[\"Rebus telur, kupas lalu goreng sebentar\", \"Tumis bumbu yg sdh d haluskan hingga harum, masukn garam, gula, penyedap, daun salam, sereh, kayu manis, telur rebus yg sdh di goreng, beri sedikit air, tes rasa, dirasa sdh pas angkat beri taburan bawang goreng (punya saya lupa gpake bawang goreng 😂😂)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1747, 3, 'Pindang Telur (Kecap)', 'Resep praktis Pindang Telur (Kecap) yang bisa dicoba di rumah.', '[\"10 butir telur ayam rebus (kupas kulitnya)\", \"3 siung bawang putih dihaluskan (me diparut)\", \"1 sdm petis (me pake yg biasa buat tahu tek)\", \"1 sdm garam\", \"1 sdm gula pasir\", \"secukupnya Kecap manis\", \"1 kantong teh celup (adanya teh biasa aku kasih 1 sdt)\", \"secukupnya Air\"]', '[\"Campur semua bahan lalu aduk2 kecuali kecap manis dan tambahkan air sedikit.\", \"Tata telur dalam panci biar rata warnanya, tambahkan air lagi sampai tingginya melebihi telur.\", \"Setelah mulai berbuih airnya masukkan kecap manis, kecilkan api biarkan sampai meresap dan airnya menyusut banyak.\", \"Pindang telur siap disantap. Jadi pendamping soto atau mie ayam jg enak 😜👍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(1748, 4, 'Orak arik telur baso sosis', 'Buat Orak arik telur baso sosis yang nikmat dengan langkah-langkah mudah ini.', '[\"2 butir telur\", \"sosis\", \"Baso\", \"Cabe merah\", \"Bawang merah\", \"Bawang putih\", \"Garem\", \"Gula merah sedikit sja\"]', '[\"Kocok telur lalu msak dn orak arik smpe matang lalu sisihkan\", \"Haluskan bawang putih dn cabai(ada yg di haluskan ada yg di potong2 ya) dn garam\", \"Iris bawang merah tumis Lalu masukkan bumbu halus kasih gula merah tumis smpai harum\", \"Masukkan baso, sosis, dn telur orak ariknya.\", \"Tumis2 tes rasa dn sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1749, 4, 'Nasi Goreng Ati Ampla Nughet & Telor', 'Olahan telur sederhana: Nasi Goreng Ati Ampla Nughet & Telor yang mudah dibuat.', '[\"2 tusuk Sate Ati Ampla\", \"1 buah Telor\", \"2 siung Bawang Merah (Iris Tipis)\", \"1 siung Bawang Putih (Iris Tipis)\", \"2 buah Cabe Merah Keriting\", \"2 buah Cabe Hijau Keriting\", \"Secukupnya Garam\", \"Secukupnya Lada\", \"Bawang Merah Goreng Sekucupnya\", \"Secukupnya Nasi\", \"secukupnya Kecap manis\", \"secukupnya Nughet\"]', '[\"Potong ati ampla menjadi bentuk dadu.\", \"Goreng nughet secukupnya.\", \"Iris bawang merah, bawang putih dan cabai merah dan hijau.\", \"Buat telor orak arik.\", \"Tumis bumbu-bumbu yang sudah di iris sampai harum.\", \"Lalu campurkan telor yang sudah di orak arik dan ati ampla yang sudah di potong dadu.\", \"Masukan nasi secukupnya.\", \"Masukan garam dan lada.\", \"Masukan kecap manis.\", \"Aduk sampai rata.\", \"Cicipi dan sajikan, lalu taburi bawang merah goreng di atas nasi gorengnya.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1750, 3, 'Bola telur goreng', 'Bola telur goreng - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 potong dada ayam giling\", \"2 buah telor\", \"4 sdm tepung terigu\", \"2 siung bawang putih\", \"3 buah bawang merah\", \"Secukupnya garam + merica\", \"iris Daun bawang\", \"Minyak untuk menggoreng\"]', '[\"Giling ayam, bawang merah dan bawang putih\", \"Masukan semua bahan menjadi satu aduk sampai rata\", \"Bentuk bulatan lalu goreng sampai matang.\", \"Sajikan selagi hangat 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1751, 4, 'Telur Balado Ala anak kosan', 'Olahan telur sederhana: Telur Balado Ala anak kosan yang mudah dibuat.', '[\"3 buah tomat\", \"3 cabe rawit\", \"3 siung bawang putih\", \"4 siung bawang merah\", \"7 butir telur\", \"Masako\", \"Kecup bangau\"]', '[\"Rebus telur (cuci bersih) kira-kira 20 menit, kupas\", \"Goreng telur,angkat tiriskan\", \"Ulek bumbu yang ada, kecuali bawang merah diiris\", \"Tumis bawang merah hingga layu\", \"Masukan sambel yang diulek\", \"Tunggu 5 menit lalu masukan telur, kecap beri gula edikit, masako, koreksi rasa. Kalau sudah pas. Tunggu hingga matang dan angkat dan siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1752, 2, 'Sambal telor bulat', 'Sambal telor bulat - hidangan telur praktis dan lezat.', '[\"Telur\", \"Bawang merah\", \"Bawang putih\", \"Dau salam\", \"Gula putih\", \"Garam\", \"Cabai\", \"Tomat\"]', '[\"Rebus telur hingga matang angkat dan tiris kan.\", \"Kupas kulit terur yang telah di rebus. Setelah itu telur di goreng dalam keadaan bulat utuh. Agkat dan tiris kan setelah ke coklatan\", \"Halus kan bumbu seperti bawang merah dan putih,cabai\", \"Kemudian masak bumbu yang telah dihaluskan masukan daun salam dan tomat tambahkan garam dan gula putih\", \"Setelah itu masukan telur yang telah digoreng aduk hingga merata.\", \"Setelah selesai angkat dan sambal telur bulat pun siap untuk di santap. Terima kasih ☺\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1753, 4, 'Telur ceplok balado sumatra', 'Resep Telur ceplok balado sumatra yang lezat dan mudah dibuat di rumah.', '[\"4 butir telur\", \"2 sdm minyak sayur\", \"1/2 sdt penyedap rasa\", \"1 sdt garam\", \"1/2 sdt gula pasir (saya sih gak pake gula)\", \"Bumbu halus\", \"11 cabe rawit gendot (bisa pake cabe merah besar sesuai selera\", \"2 siung bawang merah dan bawang putih\", \"1 ruas jari jahe dan laos (laos fungsinya membuat masakan wangi)\", \"1 lembar daun jeruk (gak pake jg gak papa kok bun)\"]', '[\"Goreng semua telur (kalo gak suka ceplok dadar jg gak papa bun)\", \"Haluskan semua bumbu termasuk jahe, laos dan daun jeruk\", \"Tumis bumbu sampai harum ya bun (kalau sudah bersing² tandanya sudah harum😂, tujuan menumis sampai harum agar masakan tidak cepat basi)\", \"Tambahkan garam, penyedap, gula secukupnya (kalau mau tambah air sedikit aja saya sih enggak soalnya sudah pake tomat)\", \"Kecilkan api, lalu masukkan telur, aduk dengan sambel d wajan secara peelahan, jangan sampai telur berantakan ya bun nanti buah hati / suami bisa gak selera kalo liat masakan berantakan😁.\", \"Koreksi rasa, angkat, hidangkan, dimakan dengan nasi hangat semakin cucok. 😂\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1754, 2, 'Telur di Pindang Teh Celup', 'Resep Telur di Pindang Teh Celup yang lezat dan mudah dibuat di rumah.', '[\"5-10 telur ayam di rebus lalu kupas kulitnya\", \"2 kantong teh celup merk apa saja boleh\", \"2 sdm kecap manis\", \"2 sdm gula pasir\", \"3 sdm gula merah sisir\", \"1 batang sereh. Keprek\", \"2 lembar daun salam\", \"3 lembar daun jeruk\", \"1 liter air\", \"Secukupnya garam dan kaldu\"]', '[\"Masukkan dalam panci semua bahan. Aduk lalu rebus sampai air sat.\", \"Bila ingin warna lebih pekat biarkan tetap terendam air rebusan semalaman (kalau masih ada sisa air)\", \"Rasanya enak, gurih manis.\", \"Selamat memasak bu ibu.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1755, 2, 'Semur tahu telor', 'Semur tahu telor - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"Bahan:\", \"3 butir telur rebus\", \"1/2 papan tahu potong tebal lalu goreng setengah matang\", \"Bumbu:\", \"2 siung bawang putih\", \"4 siung  bawang merah (haluskan)\", \"secukupnya Merica\", \"secukupnya Gula garam\", \"secukupnya Penyedap rasa\", \"2 sdm rajarasa\", \"secukupnya Kecap manis\"]', '[\"Siapkan minyak goreng, tumis baper bawang putih hingga harum lalu masukkan kecap manis, rajarasa, merica gula garam dan tmbahkan air tes rasa\", \"Jika rasa sudah pas masukkan telur rebus dan tahu goreng tunggu 5mnit hingga bumbu merasuk lalu angkat taburi bawang goreng, sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1756, 3, 'Nasi sosis gulung telur', 'Buat Nasi sosis gulung telur yang nikmat dengan langkah-langkah mudah ini.', '[\"Secukupnya nasi\", \"2 telur\", \"2 sosis\", \"Garam\", \"Penyedap rasa\", \"Margarin\"]', '[\"Siapkan nasi dan tambahkan garam sedikit hingga merata\", \"Goreng sosis (Sambil menunggu sosis matang) campurkan telur, garam, dan penyedap rasa, kemudian kocok sampai berbuih\", \"Panaskan margarin d atas teflon, kemudian tuang kocokan telur tadi hingga matang\", \"Angkat telur, dan ratakan nasi d atasnya, kemudian letakkan sosis dan gulung. Terakhir potong sesuai selera\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1757, 4, 'Egg Curry Homemade', 'Resep Egg Curry Homemade ala rumahan yang dijamin menggugah selera.', '[\"1/2 sdt bawang putih bubuk (sebaiknya pakai bawang putih)\", \"(kalau ada bawang merah tambah bawang merah juga)\", \"2 sdm indofood bumbu gulai\", \"1/2 sdt garam\", \"1/2 sdt masako\", \"1-2 gelas air putih\", \"5 butir telur yang sudah direbus\", \"Minyak untuk menumis\", \"Kentang yang sudah digoreng\"]', '[\"Panaskan minyak, tumis bawang hingga harum. Kemudian masukkan air. Biarkan hingga mendidih.\", \"Masukkan semua bumbu. Aduk hingga merata\", \"Masukkan telur dan kentang. Biarkan bumbu meresap. Kemudian angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1758, 4, 'Tahu telor simple enak', 'Cara membuat Tahu telor simple enak yang enak dan praktis untuk keluarga.', '[\"2 potong tahu\", \"1 butir telor (kocok lepas)\", \"1 buah daun bawang (iris tipis)\", \"2 buah cabe rawit iris tipis (optional)\", \"1 sdm kaldu jamur\", \"1,5 sdt garam\"]', '[\"Lumatkan tahu, masukkan daun bawang, cabe, kaldu jamur, garam aduk hingga merata\", \"Tambahkan telor kocok. Aduk hingga merata\", \"Goreng dalam api sedang hingga kering/sedikit kecoklatan\", \"Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1759, 2, 'Oseng2 tauge telur👍👍👍(orak arik tokolan)', 'Resep praktis Oseng2 tauge telur👍👍👍(orak arik tokolan) yang bisa dicoba di rumah.', '[\"2 bungkus tauge/cambah/tokolan\", \"3 siung bawang putih q geprek\", \"4 siung bawang merah q iris\", \"4 buah cabai rawit q iris lebih pedes lebih enak😋😋😋\", \"1 butir telur\", \"Secukupnya daun bawang\", \"Secukupnya penyedap (q biasa pke kobe bumbu nasgor)\", \"Secukupnya garam\", \"Secukupnya minyak untuk menumis\"]', '[\"Panaskan minyak masukkan telur di orak arik stelah matang sisihkan telur\", \"Tumis bawang putih,bawang merah dan cabai sampai layu dan harum\", \"Stelah harum masukan taugenya lalu tambahkan garam,penyedap setelah tauge layu masukkan telur dan daun bawang tumis sebentar lalu angkat.....\", \"Sajikan bersama nasi hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1760, 2, 'Balado telur super pedas', 'Sajian Balado telur super pedas yang praktis dan lezat untuk dinikmati bersama.', '[\"5 butir telur\", \"1/2 ons cabe merah besar\", \"30 gr cabe rawit\", \"3 siung bawang merah\", \"2 siung bawang putih\", \"1/2 buah tomat\", \"garam\", \"gula\", \"1 liter air\", \"sesikit minyak goreng\"]', '[\"Rebus telus hinggaa matang\", \"Blender semua bumbu hingga halus\", \"Tumis dengan sedikit minyak...smpai tanak..masukan garam dan gula, masukkan telur yg sudah di kupas dari cangkang nya..tes rasa..lalu hidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1761, 3, 'Telor Sambal Balado', 'Resep Telor Sambal Balado ala rumahan yang dijamin menggugah selera.', '[\"5 Butir Telor\", \"3 Buah Tahu\", \"Dauh Jeruk\", \"Garam\", \"Gula\", \"Penyedap Rasa Ayam\", \"Bumbu halus\", \"10 Cabe Merah (Boleh Lebih)\", \"4 Siung Bawang Putih\", \"4 Siung Bawang Merah\", \"3 Buah Kemiri\"]', '[\"Goreng Telur yg sudah di rebus dan Tahu\", \"Tumis Bumbu Halus sampai wangi\", \"Tambahkan air sedikit, tunggu sampai mendidih\", \"Masukkan telor dan tahu yg sudah di goreng\", \"Masak sampai matang dan airnya menyusut\", \"Tambahkan garam, gula dan penyedap rasa\", \"Cicip!\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1762, 3, 'Telur Dadar Istimewa', 'Resep praktis Telur Dadar Istimewa yang bisa dicoba di rumah.', '[\"2 butir telur ayam\", \"2 butir bawang merah\", \"4 cabe rawit\", \"Lada bubuk\", \"Garam\", \"Bon cabe\", \"Sedikit seledri\", \"2 sendok tepung terigu\"]', '[\"Haluskan bawang merah dan cabe sampai halus\", \"Kocok telur dan campurkan smua bahan\", \"Goreng dengan api kecil di teflon\", \"Siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1763, 3, 'Omlet telur loreng ala om tentara', 'Olahan telur sederhana: Omlet telur loreng ala om tentara yang mudah dibuat.', '[\"3 butir telur ayam\", \"1 siung bawang putih\", \"2 siung bawang merah\", \"3 batang daun bawang\", \"1 buah tomat\", \"6 biji cabe hijau\", \"1 tangkai daun seledri\", \"Garam secukupnya.\"]', '[\"Haluskan bawang putih,bawang merah dan cabe\", \"Campurkan ke dalam mangkok yang sudah di masukan telur, kemuian masukan irisan tomat, daun bawang dan daun seledri, tambahkan garam dan diaduk hingga rata\", \"Panaskan wajan yang telah diberi minyak, kemudian digoreng dengan api kecil... Siap disajikan..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1764, 3, 'Oseng Telur Rebus', 'Buat Oseng Telur Rebus yang nikmat dengan langkah-langkah mudah ini.', '[\"2 siung bawang merah\", \"1 siung bawang putih\", \"2 buah cabai rawit\", \"2 butir telur\", \"Secukupnya garam dan rocyo\", \"Secukupnya minyak (saya pakai sedikit saja)\"]', '[\"Rebus telur hingga matang. Angkat kupas dan potong sesuai selera.\", \"Iris bawang merah, putih dan cabai.\", \"Panaskan wajan dengan sedikit saja minyak, masukkan bumbu tumis sampai harum.\", \"Masukkan telur, garam dan Royco, tes rasa.\", \"Jika sudah matang angkat.\", \"Oseng telur rebus siap dihidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1765, 4, 'Telor ikan kakap tepung serbaguna', 'Resep Telor ikan kakap tepung serbaguna ala rumahan yang dijamin menggugah selera.', '[\"Telor ikan yg sudah dbersihan\", \"Tepung bumbu serbaguna\", \"Minyak untuk menggoreng\", \"1 sendok teh air jeruk nipis\", \"1 sendok teh garam\"]', '[\"Rebus telor ikan dgn air jeruk nipis dan garam selama 15 menit\", \"Angkat potong sesuai selera\", \"Lumuri telor dgn tepung serbaguna\", \"Goreng dgn api sedang,angkat sajikan dgn saus.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1766, 4, 'Brokoli Siram Telur', 'Sajian Brokoli Siram Telur yang praktis dan lezat untuk dinikmati bersama.', '[\"1/2 bonggol brokoli\", \"1 btr telur\", \"5 bh cabai merah\", \"2 bh bawang putih\", \"1/2 bh bawang bombai\", \"1 sdt tepung maizena (larutkan)\", \"Secukupnya air\", \"Gula garam, kaldu bubuk, ladaku\"]', '[\"Cuci bersih brokoli, siram dengan air panas, rebus sebentar, taburi garam, angkat sisihkan\", \"Tumis duo bawang dan cabai yg sudah di iris\\\", masukkan telur orak arik sampai hancur, tambahkan Gula Garam, kaldu bubuk, ladaku, tes rasa, terakhir masukkan air maizena\", \"Susun brokoli, kemudian siramkan dengan telur. Selesai\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1767, 4, 'Pindang daging dan telur #taiwan food', 'Buat Pindang daging dan telur #taiwan food yang nikmat dengan langkah-langkah mudah ini.', '[\"400 grm dada ayam\", \"5 butir telur rebus\", \"4 siung bawang putih\", \"3 buah cabe\", \"20 grm gula batu\", \"1 sdt wu siang fen\", \"80 ml kecap jamur\", \"800 ml air\", \"2 sdm minyak goreng\", \"2 sdm bawang goreng\"]', '[\"Siapkan bahan nya\", \"Cuci bersih daging lalu potong kecil” kulit ayam nya potong kecil” lalu pisah kan, telur kupas kulit nya,bawang cincang kasar\", \"Tumis bawang putih dan kulit ayam,tumis hingga harum kemudian masukan gula batu dan cabe,lalu masukan daging,tumis hingga daging berubah warna,masukan 1 sdt wu siang fen,aduk hingga rata,masukan kecap jamur dan bawang goreng,lalu tuang air,masukan telur,masak hingga mendidih,jika sudah mendidih,kecilkan api,masak hingga matang,kurang lebih 30 menit\", \"Wu siang fen\", \"Angkat dan siap untuk di sajikan\", \"Enak di sajikan dengan nasi,mie rebus,atau sayur rebus\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1768, 4, 'Rica rica telor ikan', 'Resep Rica rica telor ikan yang lezat dan mudah dibuat di rumah.', '[\"1/2 kg telor ikan tengiri\", \"8 siung bawang merah\", \"4 siung bawang putih\", \"5 inc jahe\", \"5 inc kunyit\", \"1/4 sendok teh merica\", \"1/4 sendok teh ketumbar\", \"1 sendok teh garam\", \"1/2 potong gula merah/ 1sendok teh gula pasir\", \"1 serai\", \"1 lembar daun salam\", \"1 potong laos\", \"7 cabai rawit\", \"3 cabai merah besar\", \"5 kemiri\", \"Minyak untuk menumis\"]', '[\"Rebus telor ikan dgn sedikit air +garam dan air jeruk nipis selama 15 menit,angkat potong sesuai selera\", \"Haluskan bumbu bawang merah,bawang putih,jahe,kunyit,garam,cabai rawit dan cabai merah,kemiri, merica dan ketumbar\", \"Tumis semua bumbu yg telah dihaluskan masukan serai,salam,laos,gula,garam sampai berwarna kecokelatan tambahkan sedikit air\", \"Setelah dirasa pas rasanya masukan rebusan telor ikan sambil sesekali d aduk,setelah bumbu meresap angkat sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1769, 3, 'Telur gulung/Bihun gulung', 'Telur gulung/Bihun gulung - hidangan telur praktis dan lezat.', '[\"1/4 kg Bihun\", \"2 Butir Telur\", \"Secukupnya Air\", \"Garam\", \"Minyak goreng\", \"Tusuk sate\"]', '[\"Rebus bihun jangan sampai terlalu matang, beri garam sedikit agar bihun tidak terasa hambar. Kemudian tiriskan hingga benar benar sudah tidak ada air yg tersisa.\", \"Kocok lepas Telur tambahkan air sedikit, lalu beri garam\", \"Panaskan minyak, minyak disini harus menggunakan minyak yang banyak karena agar memudahkan dalam menggulung telur dan bihunnya.\", \"Setelah minyak panas. Masukan sedikit bihun, tunggu beberapa detik, lalu masukan telur sedikit juga\", \"Setelah itu gulung menggunakan tusuk sate. Agar tergulung dengan baik usahan tusuk sate tercelup minyak dan menggulungnya posisi di dalam minyak panas tersebut\", \"Lalukan secara berulang sampai bihun dan telur habis\", \"Bihun gulung/telur gulung siap di santap\", \"Tambahkan juga saus sebagai pelengkap\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1770, 3, 'Cheese Egg Toast', 'Olahan telur sederhana: Cheese Egg Toast yang mudah dibuat.', '[\"Secukupnya roti tawar\", \"3 butir telur ayam kocok lepas\", \"1 batang kacang panjang potong serong dan kecil*\", \"1 buah tomat potong kecil*\", \"1 buah bawang bombay kecil* & memanjang\", \"1 buah cabe merah potong serong\", \"1 buah cabe hijau potong serong\", \"3 sdm keju cheddar\", \"Secukupnya garam dan merica\"]', '[\"Kocok lepas telur masukan garam, merica, stlah itu msukan cabe merah, ijau, kacang panjang, tomat, bawang bombay dan keju kocok jadi 1\", \"Panaskan pan anti lengket, beri sdkit minyak ambil selembar roti celupkan kekocokan telur jangan terlalu lama nanti rotinya ancur. Masak sampai matang ya, lalu lakukan hingga habis.\", \"Apa bila sdh matang smuanya bisa potong dua bentuk segitiga disetiap rotinya😂\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1771, 4, 'Sambal telur', 'Resep Sambal telur yang lezat dan mudah dibuat di rumah.', '[\"4 butir telur ayam rebus kupas kulitnya\", \"2 buah terong ungu potong sesuai selera\", \"2 batang daun bawang potong serong\", \"Sambal 🌶\", \"1 genggam cabai merah keriting/sesuai selera\", \"8 buah bawang merah\", \"3 siung bawang putih\", \"1 buah tomat\", \"Secukupnya garam gula dan penyedap\"]', '[\"Panaskan minyak, goreng terong dan telur yg sdah direbus. Angkat sisihkan\", \"Rebus cabai dan bumbu sambal lainya,tambahkan minyak secukupnya lalu blender bertekstur. Goreng sambel hingga harum tambahkan gula garam dan penyedap, tes rasa masukkan telur dan terong aduk2 hingga tercampur tambahkan daun bawang, tunggu sebentar kira-kira bumbu meresap angkat dan sajikan.. 😉\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1772, 3, 'Pempek nasi isi telor', 'Buat Pempek nasi isi telor yang nikmat dengan langkah-langkah mudah ini.', '[\"1 mangkok besar nasi\", \"1 genggam teri\", \"6 siung bawang putih\", \"1/2 sdt merica bubuk\", \"1/2 sdt ketumbar bubuk\", \"1 butir telur kocok\", \"2 sdt munjung Garam\", \"1/2 sdt Kaldu bubuk\", \"secukupnya Air untuk merendam nasi\", \"300 gram tepung ubi kayu\", \"2 sdm tepung jagung\", \"50 gram tepung gandum\"]', '[\"Rendam nasi 2 jam dengan air mendidih. Lalu blender nasi letak dalam panci.\", \"Blender smua bumbu jadi satu hingga lembut.\", \"Campur bumbu ke dalam panci masak hingga mendidih sekitar 10-15 menit. Lalu matikan api dan sisihkan.\", \"Masukkan tepung sedikit demi sedikit lalu aduk rata dengan centong.\", \"Setelah adonan agak dingin mulai adon hingga kalis dan tidak lengket.\", \"Kocok telur dan tambahkan sedikit garam untuk isian pempek.\", \"Bentuk adonan bulat dan lubang tengahnya kemudian isi dengan kocokan telur.\", \"Rebus air hingga mendidih tambahkan sedikit garam lalu masukkan pempek hingga mengapung lalu angkat.\", \"Kemudian angkat dan tiriskan pempek.\", \"Panaskan minyak lalu goreng hingga matang.\", \"Lalu hidangkan bersama cuko atau juga sos.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1773, 2, 'Udang telur balado', 'Resep Udang telur balado ala rumahan yang dijamin menggugah selera.', '[\"1/4 udang\", \"1 butir telur ayam\", \"Bahan ulek :\", \"10 buah Cabe keriting\", \"4 siung Bawang merah\", \"2 siung Bawang putih\", \"secukupnya Kemiri\", \"4 buah Cabe rawit\", \"1 Tomat kecil\", \"secukupnya Garam\", \"secukupnya Gula\", \"secukupnya Merica\", \"secukupnya Jahe\", \"secukupnya Lengkuas\"]', '[\"Cuci bersih udang dan buang kulitnya,\", \"Ulek halus bumbu yg harus diulek kecuali jahe sama lengkuas cukup memarkan saja\", \"Panaskan minyak tumis hingga Wangi bumbu yg sudah di ulek\", \"Campurkan telur sambil di arik\", \"Masukan dalam jahe dan lengkuas\", \"Masukan udang\", \"Tambah gula garam cicip rasa\", \"Hidangkan..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1774, 2, 'Telor dadar gulung isi sosis', 'Sajian Telor dadar gulung isi sosis yang praktis dan lezat untuk dinikmati bersama.', '[\"2 butir telor\", \"1 bj daun prei\", \"1 buah sosis\", \"1/4 sdt Saos tiram\", \"secukupnya Garam dan lada\"]', '[\"Goreng sosis... Kocok telor tambahkan garam lada dan saos tiram.... Masukan daun prei yg sdh dirajang halus\", \"Siapkan teflom beri sedikit mentega... Goreng telor setengah matang taruk sosis dan gulung\", \"Lalu tuang lagi sisa telor tunggu setengah matang lalu gulung lagi balik2 telor gunakan api kecil agar matang sempurna\", \"Setelah matang potong2 bs diberi tambahan saos tomat dan saus sambal\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1775, 2, 'Makaroni telor a.k.a Maklor', 'Resep Makaroni telor a.k.a Maklor ala rumahan yang dijamin menggugah selera.', '[\"150 gram makaroni elbow\", \"1 butir telur (kocok lepas)\", \"1 sdm minyak wijen(boleh dganti minyak apa aja)\", \"Secukupnya air\", \"Sejumput garam\", \"Bumbu tabur(sesuai selera)\", \"Secukupnya bumbu balado, jagung bakar,bon cabe\"]', '[\"Didihkan air yg sudsh dicampur minyak+garam. Lalu rebus makaroni hingga matang. Tiriskan\", \"Siapkan wajan, beri sedikit minyak lalu masukkan makaroni, oseng2 hingga setengah kering.\", \"Masukkan telur yg sudah dikocok td. Lalu orak arik hingga matang. Tiriskan, kemudian beri bumbu tabur. Siap dimakan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1776, 2, 'Orak arik telur tomat hijau', 'Orak arik telur tomat hijau - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"2 butir telur\", \"2 buah tomat hijau\", \"1 siung bawang putih\", \"3 buah bawang merah\", \"8 buah cabai rawit (sesuai selera)\", \"1 bks merica bubuk (aq pake ladaku) / bisa di skip\", \"secukupnya Gula garam\", \"Minyak goreng\"]', '[\"Iris tomat kotak kotak (dadu)\", \"Iris semua bumbu\", \"Panaskan minyak, tumis semua bumbu hingga layu\", \"Masukan telur yang sudah dikocok, aduk aduk(orak arik), masukan tomat masak sampai matang\", \"Tambahkan gula dan garam secukupnya masak sebentar, koreksi rasanya\", \"Angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1777, 2, '13. Telur Ceplok Kuah Santan Pedas', 'Resep 13. Telur Ceplok Kuah Santan Pedas yang lezat dan mudah dibuat di rumah.', '[\"4 butir telur ayam, ceplok\", \"4 potong tahu putih, goreng setengah putih\", \"65 ml santan kara\", \"8 buah cabe rawit merah utuh\", \"2 buah cabe hijau, iris tipis\", \"1 ruas lengkuas, geprek\", \"1 lembar daun salam\", \"1 lembar daun jeruk\", \"1 sdt gula pasir, atau sesuai selera\", \"1/2 sdt garam, atau sesuai selera\", \"1/2 sdt penyedap, atau sesuai selera\", \"1 sdt gula merah\", \"500 ml air\", \"5 sdm minyak sayur\", \"6 buah cabe rawit merah, haluskan\", \"4 siung bawang merah, haluskan\", \"2 siung bawang putih, haluskan\", \"2 butir kemiri, haluskan\"]', '[\"Tumis bumbu halus: bawang merah, bawang putih, kemiri, lengkuas, daun salam dan daun jeruk hingga harum\", \"Masukkan air, gula merah, santan, gula, garam dan penyedap. Masak hingga mendidih.\", \"Masukkan telur, tahu dan cabe, aduk rata. Masak hingga bumbu meresap.\", \"Sajikan dengan nasi hangat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1778, 4, 'Kentang Bayam Telur ala orang Jerman (cocok untuk menu diet)', 'Cara membuat Kentang Bayam Telur ala orang Jerman (cocok untuk menu diet) yang enak dan praktis untuk keluarga.', '[\"Secukupnya kentang (saya yg yg kecil2 sekitar 15)\", \"400 gr daun bayam segar (bisa disesuaikan kebutuhan)\", \"2 buah telur\", \"1 buah bawang bombay kecil/2 buah bawang merah\", \"1 buah bawang putih\", \"Secukupnya garam, merica, bila perlu bisa sedikit penyedap rasa\", \"1 sdm susu cair tawar (opsional)\"]', '[\"Cuci kentang dan bayam. Kalau kentang nya besar2 bisa diiris jadi 2 bagian agar lebih cepat matang. Rebus/kukus kentang sampai matang. Saya kebetulan kentangnya direbus dan ketika direbus saya beri 1sdt garam supaya rasa kentang tidak terlalu tawar\", \"Siapkan air panas dipanci, dan rebus bayam sampai layu tapi usahakan masih hijau. Angkat bayam dan cuci dengan air dingin biasa supaya proses pematangannya berhenti dan warnanya masih hijau cantik. Kemudian tiriskan (diperas sedikit saja) dan iris kecil2 rebusan bayam\", \"Ceplok telur mata sapi\", \"Iris semua bawang dn tumis di wajan dengan sedikit saja minyak sampai layu kemudian masukan irisan bayam aduk2 dengan bawang. Bumbui dengan garam gula dsb juga kalau ada susu tawar dan terakhir beberapa sdm air supaya bayam tidak terlalu kerin dan aduk lagi sebentar kemudian angkat\", \"Siap disajikan dengan sedikit mayonase dan bubuk cabe dan tabur sedikit garam juga :)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1779, 2, 'Semur telur.', 'Semur telur. - hidangan telur praktis dan lezat.', '[\"4 butir telur ayam\", \"3 siung bawang merah\", \"3 siung bawang putih\", \"3 buah cabe merah\", \"1/2 buah kemiri\", \"1 lembar daun salam\", \"1 lembar daun jeruk\", \"1 ruas lengkuas\", \"Secukupnya royco dan gula\"]', '[\"Rebus telur hingga matang lalu kupas\", \"Haluskan bawang merah, bawang putih, kemiri dan cabe.. Sy diblender aja biar praktis 😁\", \"Tumis bumbu halus, daun salam, daun jeruk, dan lengkuas sampai harum.. Tambahkan secukupnya gula dan royco\", \"Setelah harumasukan telur dan beri sedikit air, tunggu hingga air memyusut\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1780, 3, 'Telur bulat sambal pete', 'Cara membuat Telur bulat sambal pete yang enak dan praktis untuk keluarga.', '[\"4 butir telur\", \"1 papan pete\", \"10 cabai rawit\", \"4 cabai merah\", \"3 siung bawang merah\", \"2 siung bawang putih\", \"1 butir kemiri\", \"secukupnya Gula aren\", \"Garam\", \"Penyedap rasa\"]', '[\"Rebus telur sampai matang,angkat & tiriskan lalu kupas cangkang telur.. Pisahkan pete dengan papannya..\", \"Ulek cabai rawit,cabai merah,kemiri,bawang putih bawang merah,garam dan gula aren\", \"Tumis bumbu halus,setelah tercium aroma bumbu lalu masukan telur lalu aduk kemudian masukan pete dan tambahkan penyedap rasa.. 😊\", \"Dan terakhir.. Jika sdh matang telur sambal pete siap di sajikan...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1781, 3, 'Tumis / Ca Caisim + Telor', 'Nikmati kelezatan Tumis / Ca Caisim + Telor dengan resep sederhana ini.', '[\"1 ikat Caisim\", \"1 butir Telur Ayam\", \"3 buah bawang merah\", \"2 buah bawang putih\", \"3 cabe merah\", \"1 sdt garam\", \"1/2 sdt merica bubuk\", \"1/2 sdt garam\", \"secukupnya penyedap rasa\", \"1 sdm minyak\"]', '[\"Bersihkan Caisim, lalu potong sesuai selera. Cincang duo bawang dan cabai.\", \"Panaskan minyak, goreng telor diorak-arik, lalu sisihkan di pinggir penggorengan.\", \"Masukkan duo bawang, setelah harum masukan cabai, lalu masukkan garam dan merica. aduk rata.\", \"Masukkan Caisim. Aduk, jika terlalu kering boleh ditambahkan air sedikit. Masukkan gula dah penyedap rasa. Koreksi rasa.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1782, 2, 'Orak arik telur dan sayuran', 'Resep praktis Orak arik telur dan sayuran yang bisa dicoba di rumah.', '[\"2 butir telur, kocok lepas\", \"1 batang wortel, iris kecil\", \"10 batang buncis, iris kecil2\", \"5 lembar sawi putih\", \"2 batang daun bawang, potong2\", \"1 sdt minyak wijen\", \"1/2 buah bawang bombay, potong2\", \"1 sdm blueband\", \"secukupnya Garam, gula pasir\", \"100 ml air\", \"Bumbu dihaluskan:\", \"2 butir kemiri\", \"5 siung bawang putih\"]', '[\"Panaskan minyak goreng dan margarin, masukkan telur lalu orak arik.\", \"Masukkan bawang bombay dan bumbu yg dihaluskan, tumis sampai matang.\", \"Masukkan sayuran, daun bawang, garam, gula, minyak wijen. Tumis sampe sayuran layu.\", \"Masukkan air, tunggu sampai mendidih. Cicipi rasanya, matikan api agar sayuran tetap crunchy. Yummy 😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1783, 3, 'Telur dadar bumbu rujak', 'Cara membuat Telur dadar bumbu rujak yang enak dan praktis untuk keluarga.', '[\"6 butir telur\", \"100 ml santan (saya pake kara 60ml + air 40ml)\", \"Bumbu halus :\", \"5 siung bawang merah\", \"2 siung bawang putih\", \"3 buah cabe merah besar\", \"9 buah cabe rawit\", \"Tambahan :\", \"1 ruas lengkuas geprek\", \"2 lembar daun salam\", \"Secukupnya gula dan garam\", \"Secukupnya kecap manis\", \"Secukupnya daun bawang iris2 tipis\"]', '[\"Kocok lepas telur bersama dg campuran daun bawang dan garam. Dadar sampai matang kemudian potong2 sesuai selera. Tiriskan\", \"Tumis bumbu halus sampai matang, kemudian masukkan daun salam dan lengkuas geprek. Tumis kembali sampai harum dan matang.\", \"Masukkan telur dadar, aduk sampai semua bumbu tercampur rata.\", \"Masukkan santan, aduk kembali sampai rata. Tambahkan gula, garam dan kecap manis.\", \"Tes rasa. Kemudian biarkan sampai santai menyusut kental.\", \"Siap disajikan dg nasi hangat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1784, 4, 'Dadar telur cah toge pete', 'Dadar telur cah toge pete - hidangan telur praktis dan lezat.', '[\"3 butir telur ayam kocok lepas kemudian di dadar, iris tipis\", \"Semangkuk toge\", \"1 papan Pete\", \"1 batang daun bawang\", \"2 siung bawang putih\", \"4 siung bawang merah\", \"1 sendok makan minyak wijen\", \"5 buah cabe rawit merah di iris\", \"1-2 sendok mkn kecap manis sesuai selera\", \"secukupnya Garam\"]', '[\"Dadar telur, iris tipis, sisihkan\", \"Tumis bawang merah, bawang putih hingga harum dgn minyak wijen, masukkan cabe rawit, Pete, setelah toge agak layu masukkan toge, garam, kecap dan daun bawang\", \"Terakhir masukkan telur dadar koreksi rasa, setelah cukup angkat dan sajikan 😘😍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1785, 4, 'Telur Ceplok Balado #KisahKasihCookpad', 'Telur Ceplok Balado #KisahKasihCookpad - hidangan telur praktis dan lezat.', '[\"4 butir telur ayam\", \"2 sdm Blueband/mentega\", \"Bumbu halus (saya pakai blender yang diberi minyak):\", \"4 butir bawang merah\", \"3 siung bawang putih\", \"Sesuai selera cabai merah\", \"(saya: mix cabai merah keriting & cabai rawit merah)\", \"1 buah tomat\", \"Secukupnya minyak sayur\", \"Penyedap rasa :\", \"secukupnya  garam\", \"secukupnya  gula pasir\", \"secukupnya  Masako\", \"secukupnya  Sasa\"]', '[\"Masak ceplok semua telur. Goreng pakai Blueband. Menjadikan telur gurih. Sisihkan di piring. ***Kalo pakai minyak goreng beri garam saat buat telur ceplok.\", \"Tumis bumbu halus hingga harum. Taburi bumbu penyedap rasa hingga bumbu matang. Masukkan telur ceplok masak hingga tercampur bersama bumbu. Tes rasa.\", \"Pindahkan ke piring dan siap disajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1786, 2, 'Sup Telur AK LiTel', 'Resep Sup Telur AK LiTel ala rumahan yang dijamin menggugah selera.', '[\"1 butir Telur Ayam Kampung\", \"Brokoli\", \"Wortel\", \"Kaldu sapi\", \"Daun Bawang\", \"Seledri\", \"Bawang putih dan bawang merah\", \"Tomat\"]', '[\"Tumis bawang putih, bawang merah dan tomat hingga harum\", \"Setelah berubah warna tambahkan air dan masukkan wortel yang dipotong tipis-tipis\", \"Setelah agak lama masukkan brokoli hingga air mendidih.\", \"Kemudian masukkan telur ayam kampung sambil di aduk. Tambahkan bubuk kaldu sapi dan sedikit garam gula\", \"Terakhir tambahkan seledri dan daun bawang.\", \"Cicipi....setelah matang siap dinikmati selagi hangat 😋😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1787, 2, 'Orak arik brokoli sosis telur', 'Resep Orak arik brokoli sosis telur ala rumahan yang dijamin menggugah selera.', '[\"1 bonggol brokoli\", \"1 butir telur\", \"1 buah sosis\", \"1/2 gelas air\", \"..\", \"bumbu\", \"sejumput garam\", \"sejumput gula\", \"penyedap makanan (royco)\", \"lada bubuk\", \"2 siung bawang putih\", \"2 siung bawang merah\", \"1 potong bawang bombay\", \"5 buah cabe merah (selera)\"]', '[\"Persiapan, potong brokoli kecil2 lalu cuci dan rendam sebentar dg garam sedikit, agar mati kalau ada uletnya.\", \"Kocok telur dengan sedikit garam/royco.\", \"Iris bawang bombay, bawang putih, bawang merah, cabe, tumis dengan sedikit minyak.\", \"Masukkan telur, di orak arik, jangan lama2 jangan sampai mateng, langsung masukkan brokoli, di orak arik agar brokoli dan telor menyatu.\", \"Tambahkan sedikit air, garam gula royco lada, sreng sreng, terakhir masukkan sosis nya.\", \"Tetap dengan api kecil tunggu hingga brokolinya empuk / air nya mau habis.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1788, 2, 'Telor ceplok saos pedas manis', 'Nikmati kelezatan Telor ceplok saos pedas manis dengan resep sederhana ini.', '[\"4 butir telor ayam (terserah brp jumlah sesuai selera)\", \"5 butir tomat merah\", \"8 buah cabe merah keriting\", \"Secukupnya gula\", \"5 siung Bawang merah\", \"3 siung bawang putih\", \"Secukupnya garam\"]', '[\"Ceplok telor (lgsg taburi sedikit garam diatasnya)\", \"Haluskan tomat, cabe merah, 2 siung bawang merah, 1 siung bawang putih, gula dan garam (untuk bikin saos nya, kalo ga mau ribet, bisa jg pake saos sambel yg udah jadi)\", \"Tumis sisa bawang merah dan bawang putih, dg irisan cabe merah keriting, tunggu hingga wangi\", \"Masukkan saos ke tumisan td, tambahkan sedikit air, aduk hingga mendidih, cicipi dan koreksi rasa,,kalo udah pas, masukkan telor ceplok, aduk sesekali, masak hingga air saosnya sedikit meresap ke telor\", \"Siap disantap deh, gampang kan 😉\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1789, 2, 'Tahu Telor Bumbu Rujak Madura', 'Nikmati kelezatan Tahu Telor Bumbu Rujak Madura dengan resep sederhana ini.', '[\"1/2 kotak tahu\", \"2 butir telor\", \"Lontong / nasi (selera)\", \"🌸Bumbu rujak:\", \"1 gengam kacang goreng\", \"5 cabe rawi\", \"1 sdm petis madura (bisa petis lain)\", \"1 sdt gula merah\", \"Secukupnya garam gula\", \"🌸Sayuran pelengkap:\", \"1 ikat kangkung (selera)\", \"1 genggam kecambah (pendek/panjang)\", \"1 buah timun (iris kotak kecil)\"]', '[\"Goreng tahu setengah matang, lalu potong2 dan campurkan dengan telor + garam + lada bubuk (secukupnya), lalu goreng hingga keemasan\", \"Bubuk rujak: haluskan semua bumbu,tes rasa\", \"Sayuran: rebus kangkung dan kecambah, iris kotak timun\", \"Sajikan dengan lontong/nasi\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1790, 3, 'Telor balado', 'Telor balado - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"4 telur ceplok\", \"4 bawang merah\", \"2 bawang putih\", \"8 cabe merah\", \"Sckup nya cabe rawit\", \"1 gelas Air\"]', '[\"Ulek/ blender smua bahan (bumbu)\", \"Lalu tumis bumbu halus tambahkan gula dan garam secukupnya serta air 1 gelas\", \"Terakhir masukkan telur lalu aduk rata\", \"Selamat menikmati,\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1791, 3, 'Wortel kol cah tahu telur', 'Nikmati kelezatan Wortel kol cah tahu telur dengan resep sederhana ini.', '[\"2 bh tahu putih (potong kecil2)\", \"1 btr telur ayam\", \"4 bh baby wortel (iris memanjang)\", \"1/4 bh kol ukuran sedang (iris tipis)\", \"4 siung bawang putih (digeprek)\", \"3 siung bawang merah (iris2)\", \"secukupnya Air\", \"Garam\", \"Penyedap jamur\", \"Royco rasa ayam\", \"Merica\", \"1/4 sdt saos tiram\", \"Margarin utk menumis\"]', '[\"Panas kan margarin lalu masukan bawang merah dan bawang putih...tumis sampai harum...\", \"Setelah bawang merah dan bawang putih harum masukan telur ayam...aduk2 sampai telur set...\", \"Setelah itu masukan wortel,kol, dan tahu putih secara berurutan...tambahkan air...aduk sebentar...\", \"Tambahan royco,garam,penyedap jamur,merica dan saos tiram...oseng2 kemudian koreksi rasa...\", \"Setelag smua ny ok...matikan api dan masakan siap disajikan dan disantap...😘😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1792, 3, 'Telur orak arik sosis bakso', 'Olahan telur sederhana: Telur orak arik sosis bakso yang mudah dibuat.', '[\"2 butir telur ayam\", \"1 batang sosis\", \"2 bakso sapi\", \"1/4 buah bawang bombay\", \"1 batang daun bawang\", \"2 sendok makan Kecap manis\", \"3 sendok makan Saos sambal\", \"secukupnya Lada putih\", \"secukupnya Garam\", \"Minyak untuk menggoreng\"]', '[\"Potong2 sesuai selera sosis, bakso sapi,bawang bombay dan daun bawang\", \"Kocok lepas telur masukan daun bawang dan garam\", \"Panaskan minyak goreng telur lalu orak arik\", \"Masukan kecap, saos sambal dan lada hingga rata\", \"Setelah itu masukan bawang bombay, baso dan sosis. Aduk hingga merata dan siap disajikan 😘\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1793, 2, 'Orak-Arik Kacang TeSoKo (Telur, Sosis, Kol) Praktis', 'Resep Orak-Arik Kacang TeSoKo (Telur, Sosis, Kol) Praktis ala rumahan yang dijamin menggugah selera.', '[\"Kacang Panjang potong 2-3cm\", \"Kol/Kubis potong kotak2\", \"1 Sosis ayam/ sapi (potong bentuk korek)\", \"1 Telur\", \"Cabe merah (potong serong) Jika suka pedes banyakin cabenya\", \"Bawang Merah (potong tipis)\", \"Bawang Putih (potong tipis)\", \"Daun Salam/ Lengkuas (optional)\", \"2 sdm Minyak goreng\", \"Penyedap rasa\", \"2 sdm Kecap Manis\", \"Secukupnya Air\", \"secukupnya Garam\"]', '[\"Panaskan minyak, tumis cabe, bawang merah, bawang putih dan daun salam (diresep ini saya pake daun salam karna lengkuasnya abis) tambahkan garam. Agak pinggirkan.\", \"Pecahkan telur kemudian orak-arik bersama bumbu yang sudah ditumis tambahkan potongan sosis tadi kemudian aduk.\", \"Tambahkan sayur kol aduk sebentar, tambahkan sedikit masak sampai agak layu kemudian tambahkan kacang. Aduk.\", \"Beri kecap, jika ingin agak berkuah bisa ditambahkan air. Aduk, tambah penyedap rasa. Tes rasa. Siap sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1794, 4, 'Telur Orak Arik sederhana', 'Telur Orak Arik sederhana - hidangan telur praktis dan lezat.', '[\"5 buah telur ayam\", \"Buncis\", \"2 siung bawang putih\", \"3 siung bawang merah\", \"Minyak goreng\", \"secukupnya Garam\", \"secukupnya Gula\", \"Penyedap rasa (ayam)\"]', '[\"Potong serong tipis buncisnya, kemudian cuci sampai bersih. Lumuri buncis dengan garam, diamkan sekitar 10 menit agar buncis tidak keras. Setelah buncis tidak keras, cuci lagi hingga bersih.\", \"Kocok 5 buah telur, hingga rata.\", \"Tumis bawang merah dan bawang putih hingga harum. Masukkan kocokan telur, terus aduk2 hingga meringkel2 (seperti yg difoto). Tambahkan garam, gula dan penyedap rasa secukupnya. Kemudian masukkan buncis. Aduk hingga matang. Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1795, 2, 'Semur Telur Tahu Kentang', 'Semur Telur Tahu Kentang - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"4 butir Telur Ayam direbus\", \"16 Potong Tahu Digoreng\", \"4 Butir Kentang ukuran sedang\", \"6 Siung Bawang Merah\", \"4 Siung Bawang Putih\", \"2 cm pala diparut\", \"2 cm Jahe Dimemarkan\", \"2 buah kemiri yang sudah disangrai\", \"secukupnya Ketumbar bubuk\", \"secukupnya Garam, Gula, Merica\", \"sesuai selera Kecap manis\", \"500 ml air matang\", \"1 lembar daun jeruk\", \"1 batang daun bawang\", \"1 buah cabai merah besar\"]', '[\"Haluskan bumbu (bawang merah, bawang putih, kemiri sangrai beri sedikit garam)\", \"Tumis bumbu halus, masukkan juga jahe yang sudah dimemarkan dan daun jeruk. Tumis hingga harum\", \"Tambahkan air, gula garam, merica dan kecap manis sesuai selera. Masak hingga bumbu tanak.\", \"Masukkan tahu, telur dan kentang kemudian masak lagi hingga bumbu meresap. Tambahkan juga daun bawang dan cabai merah. Koreksi rasa. Jika kuah dirasa kurang tambahkan air.\", \"Note : banyaknya kuah garam, gula, lada dan kecap disesuaikan dengan selera masing2 😊\", \"Tambahkan juga bawang goreng sebagai pelengkap. Semur siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1796, 4, 'Kepiting sambal telur pedas manis dengan saos tiram', 'Olahan telur sederhana: Kepiting sambal telur pedas manis dengan saos tiram yang mudah dibuat.', '[\"3 ekor Kepiting\", \"Garam\", \"Kecap Manis\", \"Saos Tomat/Cabe\", \"Saos Tiram\", \"Gula Jawa\", \"Daun Bawang\", \"Bawang Goreng\", \"Minyak Goreng/Sayur\", \"Telur Ayam/Telur Bebek\", \"1 Gelas air\", \"Bumbu Halus:\", \"4 siung Bawang Merah\", \"2 Siung Bawang Putih\", \"11 Biji Cabe rawit\", \"3 Biji Cabe Merah\", \"Jahe Potong 1 cm\", \"Secukupnya Ketumbar\"]', '[\"Rebus kepiting hingga berubah warna kemudian tiriskan.\", \"Tuangkan minyak sayur kedalam wajan teplon untuk Menumis. Tunggu hingga benar-benar panas dengan api sedang\", \"Tumis bumbu halus hingga tercium harum, masukan caos cabai sesuai selera, kemudian tambah saos tiram untuk menambah citarasa khas otentik.\", \"Tambahkan satugelas air, kemudian beri garam dan gula jawa secukupnya. Tumis hingga bumbu merata.\", \"Masukkan telur aduk terus hingga mengental.\", \"Masukkan kepiting yang sudah dirembus tadi, aduk hingga bumbu beresap. Tambahkan kecap Manis hingga warna berubah kecoklatan. Koreksi rasa!\", \"Terakhir taburi bawang daun dan bawang goreng. Sajikan dalam keadaan hangat untuk rasa maksimal.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1797, 3, 'Telur rebus cepat matang', 'Resep praktis Telur rebus cepat matang yang bisa dicoba di rumah.', '[\"6 butir telur/ kurang dari 6 gpp\", \"200 ml air\", \"Panci + tutup, sy panci ukuran 1lt\"]', '[\"Cuci bersih telur, tempatkan dalam panci\", \"Masukkan air, tutup panci\", \"Rebus dengan api besar selama 2 menit, lalu 3 menit dg api kecil\", \"Matikan kompor, diamkan selama 9 menit. (Selama proses rebus dan mendiamkan tutup panci jgn dibuka yaaa)\", \"Taraaaaa matang sempurna\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(1798, 3, 'Telur n Tahu Bumbu Kuning', 'Nikmati kelezatan Telur n Tahu Bumbu Kuning dengan resep sederhana ini.', '[\"4 Telur Yg Sudah Di Rebus\", \"2 Tahu Yg Sudah Di Goreng\", \"Secukupnya Kunyit Bubuk\", \"Secukupnya Lengkuas, Cuci Bersih n Geprek\", \"Secukupnya Garam Halus\", \"Secukupnya Gula Pasir\", \"Secukupnya Air\", \"Bumbu Yg Dihaluskan:\", \"7 Siung Bawang Merah, Kupas n Cuci Bersih\", \"5 Siung Bawang Putih, Kupas n Cuci Bersih\", \"2 Tomat, Cuci Bersih\", \"3 Cabe Merah Besar, Cuci Bersih\", \"1 Cabe Rawit Merah,Cuci Bersih\"]', '[\"Tumis Bumbu Yang Sudah Di Haluskan n Kunyit Bubuk Juga Lengkuas, Tumis Hingga Harum n Matang Setelah Itu Tambahkan Air Secukupnya, Biarkan Dulu Hingga Mendidih,,, Lalu Tambahkan Telur n Tahu Biarkan Lagi Hingga Mendidih Setelah Itu Tambahkan Garam n Gula Pasir Secukupnya n Koreksi Rasa, Biarkan Lagi Sebentar (5 Menit) Setelah Itu Matikan Kompor\", \"Berasa BGT Kunyitnya, Enakkkkkkk\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1799, 2, 'Bubur Telur (menu balita 8m+)', 'Bubur Telur (menu balita 8m+) - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"6 sdm nasi, lumatkan jika ingin tekstur yang lembek\", \"1 butir telur\", \"2 gelas air kaldu/air biasa\", \"1/4 brokoli, iris halus, ambil pucuknya saja\", \"1 sdt EVOO (Extra Virgin Olive Oil)\", \"secukupnya Garam\", \"secukupnya Gula\", \"Pelengkap:\", \"secukupnya Kecap manis\", \"secukupnya Bawang goreng\"]', '[\"Masak nasi dengan air kaldu/air biasa dengan api kecil hingga air berkurang 3/4nya\", \"Masukkan telur, aduk cepat\", \"Masukkan brokoli, garam, dan gula. Koreksi rasa. Masak sambil diaduk-aduk hingga konsistensi yang diinginkan, matikan kompor\", \"Tunggu hingga agak dingin lalu masukkan EVOO, aduk rata.\", \"Beri pelengkap Bawang goreng dan kecap manis, sajikan hangat\", \"Bubur Telur siap dinikmati\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1800, 4, 'Oseng buncis dan orak arik telur', 'Olahan telur sederhana: Oseng buncis dan orak arik telur yang mudah dibuat.', '[\"1/4 gram buncis\", \"1 butir telur\", \"10 cabai rawit\", \"2 cabai hijau besar\", \"3 siung bawang merah\", \"2 siung bawang putih\", \"Garam\", \"Gula\", \"Penyedap rasa(optional)\", \"1 ruas lengkuas digeprak\", \"1 ruas jahe digeprak\", \"2 Daun salam\", \"Kecap Manis\"]', '[\"Cuci buncis terlebih dulu lalu buang ujung nya\", \"Iris miring tipis sisihkan\", \"Rajang semua bumbu kecuali jahe dan lengkuas lalu tumis hingga harum, masukkan daun salam\", \"Masukkan telur orak arik lalu masukkan buncis, kemudian kecap garam, gula, dan penyedap rasa\", \"Koreksi rasa, jika sudah pas biarkan sampai matang tapi jangan over\", \"Buncis orak arik telur siap di sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1801, 2, 'Telur dadar', 'Cara membuat Telur dadar yang enak dan praktis untuk keluarga.', '[\"2 butir telur ayam\", \"1 batang daun bawang\", \"3 biji cabai rawit\", \"secukupnya Garam\"]', '[\"Siapkan bahan\", \"Potong2 daun bawang\", \"Potong2 cabai\", \"Campurkan potongan daun bawang, cabai dan telur dalam 1 mangkuk\", \"Kocok bahan dan tambahkan garam\", \"Dadar di atas penggorengan setelah minyak mulai panas. Dadar sampai berwarna kecoklatan.\", \"Telur dadar siap dinikmati\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1802, 3, 'Semur Telur Mata Sapi/Ceplok', 'Semur Telur Mata Sapi/Ceplok - hidangan telur praktis dan lezat.', '[\"4 butir Telor Ayam\", \"2 lembar Daun Salam\", \"1 batang Sereh\", \"1 cm Lengkuas\", \"1 cm Jahe\", \"1/2 siung Bawang Bombay\", \"2 sdm Kecap Manis\", \"1 1/2 sdt Gula Putih\", \"secukupnya Penyedap Rasa\", \"secukupnya Garam\", \"secukupnya Minyak\", \"secukupnya Air\", \"1 batang Bawang Daun\", \"10 buah Cabe Rawit Hijau/Merah (buat yg suka pedas)\", \"3 siung Bawang Merah\", \"2 siung Bawang Putih\", \"7 buah Cabe Keriting Merah\"]', '[\"Panaskan minyak secukupnya. Lalu Goreng telor ayam hingga matang. Lalu tiriskan.\", \"Haluskan bawang merah, bawang putih dan cabe. Bisa di blender atau di ulek (sesuai selera). Klau saya di blender *biar praktis.\", \"Iris bawang bombay, bawang daun, lengkuas, dan jahe. Sereh di beprek saja.\", \"Panaskan minyak secukupnya. Lalu masukan bumbu halus, lengkuas, jahe, bawang bombay, sereh, daun salam, dan bawang daun. Tumis hingga harum.\", \"Setelah harum masukan air secukupnya. Aduk-aduk hingga matang.\", \"Apabila sudah mendidih masukan penyedap rasa, garam, gula, cabe rawit, dan kecap. Aduk-aduk hingga mereta. Lalu tes rasa.\", \"Setelah itu masukan telur ceplok nya. Aduk perlahan. Lalu tunggu beberapa menit agar bumbu meresap ke dalam telurnya.\", \"Angkat, hidangkan ke dalam piring. Semur Telur Mata Sapi / ceplok nya siap di hidangkan dan di santap.\", \"Selamat mencoba dan terimakasih.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1803, 3, 'Telur orak arik', 'Olahan telur sederhana: Telur orak arik yang mudah dibuat.', '[\"3 butir telur ayam\", \"Secukupnya Wortel,jagung manis dan kacang polong dan daun bawang\", \"1 Sdm oil olive\", \"1 Sdt Lada hitam\"]', '[\"Kocok telur lepas\", \"Wortel,jagung manis dan kacang polong kukus 5menit\", \"Masukkan semua bahan kedalam telur yang sudah dikocok, garam dan lada hitam\", \"Panaskan teflon masukkan telur, aduk buat orak-arik masak sekitar 5menit test rasa lalu angkat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1804, 3, 'Tumis telur bulat bulat', 'Olahan telur sederhana: Tumis telur bulat bulat yang mudah dibuat.', '[\"8 butir telur ayam\", \"2 lembar daun salam\", \"1 lembar daun jeruk\", \"2 ruas jari lengkuas (geprek)\", \"Bumbu halus:\", \"5 siung bawang putih\", \"6 siung bawang merah\", \"3 biji cabe rawit merah\", \"1 biji cabe merah besar\", \"1 buah tomat\", \"secukupnya Gula garam vitsin\"]', '[\"Siapkan semua bahan.\", \"Rebus telur lalu goreng.\", \"Haluskan bumbu halus bersama dgn garam dan gula.\", \"Tumis bumbu halus dengan daun salam daun jeruk dan lengkuas geprek. Tumis sampai berwarna kuning kecoklatan. Lalu tambahkan sedikit air supaya tidak gosong.\", \"Masukkan telur, tambahkan vitsin. Koreksi rasa.\", \"Aduk2 sampai bumbu meresap. Tumis telur bulat bulat siap di hidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1805, 4, 'Kroket kentang wortel isi telur rebus', 'Cara membuat Kroket kentang wortel isi telur rebus yang enak dan praktis untuk keluarga.', '[\"500 gram kentang\", \"2 buah wortel\", \"1 batang daun bawang\", \"2 butir telur rebus untuk isian\", \"secukupnya Minyak goreng\", \"Bumbu halus:\", \"2 siung bawang putih\", \"2 siung bawang merah\", \"1 sdt lada\", \"1 sdt garam\", \"1/2 sct kaldu bubuk rasa ayam\", \"Pelapis:\", \"1 butir telur kocok lepas\", \"100 gram tepung roti\"]', '[\"Potong kentang tebal 1 cm cuci bersih lalu goreng hingga kuning kecoklatan lalu dihaluskan\", \"Potong wortel dadu kecil2 rebus sampai mendidih lalu tiriskan masukkan ke dalam adonan kentang bersama bumbu halus dan daun bawang yg sudah dicincang\", \"Aduk sampai merata koreksi rasa..kalo sudah mantap dibentuk bulatan diisi dengan telur rebus yg sudah dipotong kecil2 sampai adonan habis baru di celupkan ke dalam telur yg sudah di kocok lalu di baluri tepung roti sambil ditekan2 agar tepung rotinya menempel sempurna\", \"Lalu goreng dengan api sedang...saya membaliknya cuma sekali soalnya biar ttp cantik bentuk kroketnya😄\", \"Setelah kuning kecoklatan angkat tiriskan dan kroketnya siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1806, 4, 'Semur bali tahu dan telur', 'Nikmati kelezatan Semur bali tahu dan telur dengan resep sederhana ini.', '[\"4 telur\", \"2 tahu uk besar aku potong segitiga kecil\", \"Gula merah\", \"Kecap manis\", \"2 daun salam\", \"Gula garam dan royco\", \"Bahan halus:\", \"5 cabe merah besar\", \"4 bawang merah\", \"6 bawang putih\", \"1 ruas jahe\", \"2 kemiri\", \"Sedikit tomat potong\"]', '[\"Rebus dulu telur nya sampe matang lalu tiriskan. Dan potong tahu nya dan tiriskan\", \"Goreng telur bulat (skip) dan goreng setengah matang tahunya\", \"Lalu blender semua bahan halusnya\", \"Masukan semua bahan halus ke minya goreng masukan daun salam ny juga.\", \"Lalu kasi bumbu royco gula garam dan kecap dan gula merah\", \"Masukan telur dan tahu yg sudah di goreng aduk sebentar,masukan air 1 gelas kecil\", \"Diam kan beberapa saat sampai air menyusut.\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1807, 2, 'Sosis, Telur, Nugget Pedas Manis #KisahKasihCookpad', 'Olahan telur sederhana: Sosis, Telur, Nugget Pedas Manis #KisahKasihCookpad yang mudah dibuat.', '[\"2 butir telur ayam\", \"1 bh sosis, cincang halus\", \"2 bh nugget goreng, potong\", \"1 batang daun bawang, cincang\", \"3 sdm saus sambal\", \"1 sdm kecap manis\", \"2 sdm Blueband\", \"Secukupnya garam dan merica\"]', '[\"Siapkan bahan.\", \"Panaskan Blueband, masukkan telur beri garam merica buat orak - arik.\", \"Tambahkan sosis cincang, daun bawang cincang, saus sambal dan kecap manis masak sambil diaduk hingga matang merata.\", \"Angkat dan hidangkan bersama nasi hangat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1808, 2, 'Mie kuah telur', 'Resep Mie kuah telur yang lezat dan mudah dibuat di rumah.', '[\"70 gr mie kering ** me,, mie burung dara pipih 1 keping\", \"30 gr kol iris halus\", \"1 btr telur\", \"1 btg kecil bawang daun potong2 serasi\", \"1 bh cabe rawit merah besar dirajang kasar\", \"2 siung bawang merah dirajang halus\", \"Krg lbh1,5 gelas air utk merebus mie\", \"Krg lbh 1,5 gelas air matang dingin utk merebus telur dan bumbu\"]', '[\"Rebus mie hingga matang dan kenyal sisihkan dulu.\", \"Tumis bawang merah dan cabe rawit hingga harum+air matang stlh mendidih pecahkan telur dan biarkan matang+kol+bawang daun masak2 sebentar lalu kecilkan apinya+garam dan kaldu jamur secukupnya aduk2 sebentar lalu angkat.\", \"Sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1809, 3, 'Bubur Daging Telur Butternut', 'Bubur Daging Telur Butternut - hidangan telur praktis dan lezat.', '[\"1 sdm beras\", \"1-2 ptg Daging buntut sapi\", \"secukupnya Butternut\", \"1/2 tomat kupas dan iris kotak\", \"1/2 telur kuning yampung\", \"2 btg buncis iris tipis\", \"NY dan UB\", \"Sedikit kaldu bubuk sapi\", \"Air\"]', '[\"Buat kaldu sapi dengan slow cooker : buntut sapi,tomat,butternut. Masak semalaman. Besok pagi disaring. Kaldu dibuat untuk merebus bubur. Sayuran dipisahkan dan daging dipipil untuk dimasukan ke bubur nanti\", \"Rebus beras hingga lunak. Jika sudah lunak dan air tiris tambahkan lagi dengan air kaldu sapi. Masak kembali sampai mendidih lalu masukkan telur aduk cepat agar tercampur rata.\", \"Mendekati matang masukan butternut,tomat dan buncis. Tambahkan NY dan kaldu bubuk sapi sedikit\", \"Aduk sampai matang dan dapat tekstur yang diinginkan\", \"Sajikan hangat dengan UB, NY dan taburan keju sedikit\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1810, 2, 'Telor ceplok kecap pedes', 'Sajian Telor ceplok kecap pedes yang praktis dan lezat untuk dinikmati bersama.', '[\"6 butir telor ayam\", \"5 buah cabe merah\", \"5 siung bawang merah\", \"5 siung bawang putih\", \"1 buah tomat kecil\", \"Kecap manis\", \"secukupnya Lada bubuk\", \"Sejumput garam\", \"Penyedap rasa\", \"Minyak sayur\", \"300 cc Air\"]', '[\"Panas kan minyak sayur terlebih dahulu..\", \"Lalu ceplok telor nya satu persatu lalu di tiris kan sampe selesai\", \"Panaskan minyak sayur untuk menumis bawang merah, bawang putih, cabe dn tomat sampai harum\", \"Lalu masukan air 300cc ke dalam nya\", \"Lalu tambahkan kecap manis secukupnya, diam kan sampai masak\", \"Lalu masukan telor ceplok nya, koreksi rasa diam kan sebentar sampai bumbu meresap\", \"Lalu angkat dan sajikan ke dalam wadah/ mangkuk\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1811, 4, 'Baby Kaylan Siram Tahu Telur', 'Olahan telur sederhana: Baby Kaylan Siram Tahu Telur yang mudah dibuat.', '[\"1 ikat sedang Baby Kaylan\", \"4 buah tahu kuning bandung, iris dadu\", \"1 butir telur, kocok lepas (resep asli 2 butir)\", \"3 buah cabai merah keriting\", \"2 buah cabai rawit gendut\", \"1/4 siung bawang bombay (sy tdk pakai 😁)\", \"5 siung bawang putih gepek\", \"1 sdm saus tiram saori\", \"Secukupnya garam, gula, merica bubuk\", \"Secukupnya air\"]', '[\"Goreng tahu setengah matang. Angkat tiriskan.\", \"Goreng telur dengan cara di orak arik. Angkat, sisihkan.\", \"Tumis 3 siung bawang putih dan sdkt cabai sampai harum. Tambahkan sdkt air. Masukkan baby kaylan yg sudah diiris dan dicuci bersih. Tambahkan garam merica gula dan saus tiram secukupnya. Koreksi rasa.\", \"Angkat dan tuangkan baby kaylan ke atas piring. Masak baby kaylan jgn terlalu lama supaya rasanya masih fresh dan kres-kres saat dimakan 😁😀\", \"Selajutnya, tumis sisa bumbu bawang dan cabai sampai harum. Masukkan tahu dan telur orak-arik. Tambahkan garam gula merica secukupnya saja, dan sdkt saus tiram. Koreksi rasa.\", \"Tuangkan telur dan tahu yg sudah matang ke atas baby kaylan yg telah matang.\", \"Sajikan hangat :)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1812, 4, 'Telur petis ikan', 'Resep Telur petis ikan yang lezat dan mudah dibuat di rumah.', '[\"6 bh telur\", \"4 siung bawang merah\", \"5 siung bawang putih\", \"1 bh kunci\", \"2 bh kunyit ukuran sedang\", \"6 buah cabe rawit\", \"4 sdm full petis ikan\", \"2 lembar daun jeruk\", \"2 lembar daun salam\", \"1 bh santan kara\", \"secukupnya Garam dan gula\"]', '[\"Rebus telur\", \"Haluskan bawang putih, bawang, 2 bh cabe, kunyit\", \"Geprek kunci\", \"Tumis seluruh bumbu termasuk kunci, daun jeruk dan daun salam\", \"Masukkan cabe rawit, air dan santan\", \"Beri garam dan gula secukupnya\", \"Masukkan telur rebus yg sudah dikupas dan biarkan hingga kuah mendidih dan asat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1813, 3, 'Kare Daging dan Telur', 'Kare Daging dan Telur - hidangan telur praktis dan lezat.', '[\"secukupnya daging\", \"3 telor ayam\", \"15 ml santan kara\", \"secukupnya gula\", \"secukupnya garam\", \"secukupnya penyedap sapi\", \"secukupnya air\", \"1 ruas lengkuas\", \"1 sereh\", \"2 daun salam\", \"4 daun jeruk\", \"bumbu halus\", \"8 bawang merah\", \"6 bawang putih\", \"10 cabe rawit merah\", \"3 cabe merah keriting\", \"3 kemiri\", \"1/2 sendok teh ketumbar\", \"1/2 sendok teh jinten (gapake jg gpp)\", \"1 ruas kunyit\"]', '[\"Bersihkan daging. dagingnya kupilih yg banyak tetelan. lalu potong sesuai selera. dan setelah itu rebus dengan air secukupnya\", \"Tumis bumbu halus beserta lengkuas dan sereh yg telah di geprek dan juga daun salam dan daun jeruk. aduk rata hingga matang lalu masukkan ke rebusan daging yg telah empuk. lalu masukkan telor yang sebelumnya telah direbus dan dikupas kulitnya\", \"Aduk rata lalu masukkan santan, setelah itu garam penyedap dan gula. koreksi rasa dan diamkan dahulu hingga meresap. (kalo tambahan aku pake daun bawang agar lebih segar)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1814, 3, 'Daging & telur bumbu rujak', 'Resep Daging & telur bumbu rujak ala rumahan yang dijamin menggugah selera.', '[\"500 gr daging lulur tanpa lemak potong-potong dan cuci bersih\", \"5 butir telur rebus kupas\", \"10 btr kemiri sangrai\", \"100 gr cabe merah besar\", \"10 bj cabe rawit (optional)\", \"5 bj cabe keriting\", \"10 btr bawang merah\", \"3 biji bawang putir\", \"2 bh tomat\", \"1/2 jempol asem mateng\", \"1 jempol laos geprek\", \"1 btg serai iket lalu geprek\", \"2 lmbr daun salam\", \"2 lmbr daun jeruk\", \"1 sdt gula merah\", \"Secukupnya garam\", \"Minyak goreng untuk menggoreng & menumis bumbu\", \"/+1,5 liter air bersih\"]', '[\"Cabe besar, kecil, bawang merah, bawang putih, tomat goreng jadi satu\", \"Blender bumbu yang telah digoreng td beserta kemiri\", \"Lalu tumis bumbu td bersama dengan bumbu yang lainnya\", \"Tambahkan air lalu masukkan daging dan telur rebus\", \"Setelah mendidih, kecilkan api\", \"Masak hingga air menyusut kental dan daging empuk...\", \"Siap disantap bersama nasi hangat ditemani krupuk\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1815, 3, 'Telur ceplok bumbu kecap', 'Cara membuat Telur ceplok bumbu kecap yang enak dan praktis untuk keluarga.', '[\"5 btr telur di ceplok\", \"3 bh bawang putih, potong halus\", \"2 bh bawang merah potong halus\", \"1 bh cabe merah potong serong\", \"Garam, lada, kecap\"]', '[\"Tumis bumbu sampai harum lalu kasih air, masukkan telur yg sudah diceplok.\", \"Bumbui dan biarkan sampai meresap\", \"Angkat n sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1816, 3, 'Gulai telur dan ceker pedas', 'Olahan telur sederhana: Gulai telur dan ceker pedas yang mudah dibuat.', '[\"250 gr ceker ayam yang sudah dicuci bersih dan dipotong kukunya\", \"2 bh telur yang sudah direbus dan dikupas\", \"1 buah serai memarkan\", \"2 cm jahe memarkan\", \"2 lembar daun jeruk\", \"300 ml santan dari 1/2 butir kelapa\", \"500 ml air\", \"2 sdm minyak goreng\", \"Secukupnya bawang goreng\", \"Bumbu halus :\", \"6 siung bawang merah\", \"2 siung bawang putih\", \"5 bh cabai merah\", \"2 cm kunyit\", \"1 sdt ketumbar sangrai\", \"1/2 sdt gula pasir\"]', '[\"Haluskan semua bumbu Panaskan minyak, tumis bumbu yang sudah halus, serai yang sdh di peprek, jahe, daun jeruk hingga harum.\", \"Masukkan ceker ayam, aduk. Tuang air, aduk rata dan masak hingga matang dan kalau mau ceker lebih empuk bisa pakai panci presto. Tapi saya engga karna ribet hehehe\", \"Tuang santan, aduk rata. Kecilkan api, masukkan telur yang sudah direbus dan dikupas masak hingga mendidih dan bumbu meresap. Angkat dan dipindahkan ke mangkuk atau piring\", \"Dan taburi bawang goreng diatasnya. Sajikan. InsyaAllah enaaaakk😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1817, 4, 'Telur ceplok Balado', 'Cara membuat Telur ceplok Balado yang enak dan praktis untuk keluarga.', '[\"6/7 telor\", \"Salam\", \"Lengkuas\", \"Daun jeruk\", \"Air\", \"Gula pasir\", \"Garam\", \"Kaldu\", \"Bumbu halus\", \"6 bawang merah\", \"3 bawang putih\", \"12 cabe rawit\", \"Tomat merah\"]', '[\"Ceplok semua telor.\", \"Siapkan bumbu yg di galuskab\", \"Geprek lengkuas\", \"Tumis bumbu halus hingga harum.masukan lengkuas.daun salam dan daun jeruk Masukan secukupnya air tmbh gula garam penyedap.dan tumis sebentar lalu masukan telor yg sudh di ceplok\", \"Tumis sebentar dan Nilai rasa\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1818, 2, 'Tumis buncis telur sosis', 'Resep Tumis buncis telur sosis ala rumahan yang dijamin menggugah selera.', '[\"300 gram buncis\", \"2 butir telur kocok lepas\", \"2 sosis potong serong\", \"3 siung bawang putih geprek\", \"secukupnya Garam, gula, air\"]', '[\"Siapkan bahan, cuci bersih buncis potong sering, sosis dipotong goreng sampai matang sisihkan.\", \"Tumis bawang putih dengan sedikit minyak sampai harum, masukkan telur kocok aduk cepat.\", \"Tambahkan buncis aduk sebentar beri air secukupnya aduk2 tambahkan garam, gula aduk rata tes rasa.\", \"Tambahkan sosis aduk cepat, siap disajikan.\", \"Happy cooking moms.. 😊😊😊😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1819, 4, '23. Tahu Telur Bumbu Kacang Simple', 'Olahan telur sederhana: 23. Tahu Telur Bumbu Kacang Simple yang mudah dibuat.', '[\"1 kotak tahu (potong kecil2 -+0.5cm)\", \"2 biji telur ayam (kocok lepas)\", \"1 sdt garam dapur\", \"1 batang daun bawang\", \"1 batang daun seledri\", \"Kerupuk kecil2\", \"secukupnya Minyak\", \"bumbu sambal\", \"100 gram bumbu kacang (me pakek yg kemasan)\", \"3 sdm kecap manis\"]', '[\"Panaskan minyak di penggorengan\", \"Campurkan potongan tahu, irisan daun bawang, garam kedalam telur aduk hingga merata\", \"Masukkan k minyak yg sudah panas, tunggu hingga warna kecoklatan dan kering lalu angkat\", \"Ambil mangkung kecil cairkan bumbu kacang lalu tambahkan kecap manis\", \"Siapkan piring saji, ambil tahu telur yg susah ditiriskan tadi tambhakan bumbu kacang tadi lalu tambkan potongan seledri, bawang goreng dan terakhir tambgakan krupuk kecil\", \"Sudah siao dusajijan bisa ditambahkan nasi/lontong\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1820, 4, 'Tumis Sawi Putih dan Telur orak arik', 'Resep Tumis Sawi Putih dan Telur orak arik yang lezat dan mudah dibuat di rumah.', '[\"7 lembar sawi putih\", \"2 telur ayam, kocok rata\", \"3 bawang putih iris tipis\", \"3 rawit merah iris tipis\", \"3 bawang merah iris tipis\", \"secukupnya Garam merica bubuk kadu\"]', '[\"Potong sawi iris panjang.\", \"Telur di buat orak arik, sisihkan\", \"Tumis bawang merah,bawang putih dan rawit sampai harum\", \"Tambahkan air\", \"Tambahkan garam merica dan bubuk.kaldu\", \"Masukan sawi dan telur orak arik\", \"Dum rata sampai sawi layu. Jangan terlalu lama ya.\", \"Siap disantap\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1821, 2, 'Buncis telur orak arik', 'Resep Buncis telur orak arik yang lezat dan mudah dibuat di rumah.', '[\"1/4 buncis\", \"1 butir telur\", \"3 siung bawang putih\", \"2 sdm makan\", \"Garam dan gula\", \"1 sdm Saos raja rasa (boleh skip)\"]', '[\"Cuci bersih buncis dan potong serong\", \"Geprek atau cincang bawang putih\", \"Tumis bawang putih sampai harum,sisihkan di pinggir wajan masukin telur lalu orak arik\", \"Masukan sayur,garam gula dan sedikit air tambahkan saos raja rasa bila ada\", \"Tes rasa aduk sebentar saja,lalu sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1822, 4, 'Telor Bumbu Bali Instan', 'Sajian Telor Bumbu Bali Instan yang praktis dan lezat untuk dinikmati bersama.', '[\"✔️bahan utama\", \"9 butir telur ayam\", \"1 tahu\", \"✔️bumbu\", \"3 bungkus bumbu bali instan\", \"1 batang serai\", \"2 daun salam\", \"2 daun jeruk\", \"1 sdm kecap\", \"1 sdm gula\", \"1 sdt garam\", \"✔️lainnya\", \"1 gelas air\", \"minyak goreng\"]', '[\"Rebus telur hingga matang, kemudian kupas lalu goreng. sisihkan\", \"Potong kotak tahu, goreng hingga kering sisihkan.\", \"Panaskan sedikit minyak goreng, tumis bumbu instan hingga matang (tanek). lalu masukan daun salam, daun jeruk, serai. aduk2 hingga layu. biarkan sampai tanek (sampai minyak habis)\", \"Tambahkan air, aduk2 lalu tutupi wajan. biarkan hingga mendidih. masukan gula, garam dan kecap. aduk rata. test rasa\", \"Masukan telur dan tahu biarkan air meresap hingha setengah habis (biar tanek dan tahan lama). selesai\", \"Happy cooking 🍳\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1823, 2, 'Telur kukus labu kuning', 'Sajian Telur kukus labu kuning yang praktis dan lezat untuk dinikmati bersama.', '[\"1 btr telur\", \"2 iris lbu kuning kukus\", \"1 sdt minyak wijen\", \"secukupnya Garam\", \"1 sdm susu kentl manis\", \"Sedikit air\", \"1 buah daun bawang\"]', '[\"Aduk rata semua lalu kukus kira2 5 menit\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1824, 4, 'Telur gulung nasi dg keju kries😊', 'Resep praktis Telur gulung nasi dg keju kries😊 yang bisa dicoba di rumah.', '[\"2 btr telur\", \"1 sdm sajiku\", \"1 sdm tepung terigu\", \"7 btg daun kucai(bisa sesuai selera)\", \"1/2 bungkus keju\", \"sesuai selera nasi buat isian\", \"sedikit margarin\"]', '[\"Cuci kucai potong\\\". kocok telur dg tepung beri air sedikit masukkan kucai aduk rata\", \"Panaskan teflon masukkan sedikit margarin, lalu tuang telur sampai matang, angkat. beri isian nasi lalu gulung dan potong\\\"\", \"Panaskan teflon lagi, serut keju panggang di atas teflon sampai berwarna coklat trus krispy. sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1825, 3, 'Telor bumbu bali', 'Resep praktis Telor bumbu bali yang bisa dicoba di rumah.', '[\"10 biji telor rebus\", \"3 biji cabai merah besar buang bijinya (karna untuk kiddos)\", \"6 siung bawang merah\", \"3 siung bawang putih\", \"3 biji kemiri\", \"3 lembar daun jeruk\", \"1 lembar daun salam\", \"2 sdm gula\", \"1 sdt garam\", \"1 sdt kaldu jamur\", \"Sedikit minyak untuk menumis\"]', '[\"Kupas telur rebus dan sisihkan. Goreng sebentar biar gak hancur pas di masak\", \"Haluskan bawang merah,bawang putih, kemiri\", \"Panaskan minyak, tumis bumbu halus sampai harum. Tambahkan gula,garam, kaldu jamur dan sedikit air.\", \"Masukkan telur, aduk rata bumbunya. Test rasa. Matikan api siap di hidangkan\", \"Simpel dan praktis kan 😘\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1826, 4, 'Omlet sayur telur mata sapi', 'Omlet sayur telur mata sapi - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 buah kentang, parut/ potong korek api tipis\", \"1 buah wortel, parut/ potong korek api tipis\", \"1 buah daun bawang, iris tipis\", \"3 butir telur, pisahkan putih dan kuningnya\", \"Secukupnya gula garam dan lada\"]', '[\"Rebus sebentar parutan kentang dan wortel. Tiriskan dan biarkan sampai uap panas hilang.\", \"Campurkan kentang, wortel, daun bawang dan putih telur. Masukkan gula garam dan lada, aduk hingga rata. Bagi adonan menjadi 3 bagian.\", \"Panaskan wajan, beri sedikit minyak.\", \"Masukkan satu bagian sayur, dan lingkaran ditengah (seperti donat), masukkan kuning telur ditengahnya. Tutup wahan agar tidak gosong. Masak hingga matang.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1827, 2, 'Bali Telor Pedas', 'Resep Bali Telor Pedas yang lezat dan mudah dibuat di rumah.', '[\"1/2 kg telur ayam\", \"1/2 sisir gula merah\", \"Bumbu :\", \"7 siung bawang merah\", \"5 siung bawang putih\", \"5 buah cabai merah keriting\", \"5 buah cabai rawit\", \"1/2 jempol jahe\", \"4 butir kemiri\"]', '[\"Ceplok telur, tambahkan sedikit garam. Sisihkan\", \"Ulek semua bumbu. Tumis sampai harum. Tambahkan gula merah yg sudah disisir halus. Aduk2 tambah 1/2 gelas air, gula, garam merica.\", \"Tunggu sampai mendidih. Cek rasa. Masukkan telur ceplok. Diamkan sampai air agak menyusut.\", \"Sajikan dg taburan daun pre\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1828, 3, 'Dadar telor cah toge', 'Dadar telor cah toge - hidangan telur praktis dan lezat.', '[\"2 btr telur ukuran besar\", \"semangkuk toge\", \"3 siung bawang merah,iris\", \"2 siung bawang putih,iris\", \"5 bh cabe rawit,iris (atau sesuai selera)\", \"1 btng daun bawang,iris\", \"1 sdm kecap manis (atau sesuai selera)\", \"1/2 sdm saus tiram\", \"secukupnya garam & merica bubuk\"]', '[\"Buat dadar telor,lalu iris².\", \"Panaskan minyak,tumis duo bawang sampai layu & harum,tambahkan cabe,aduk,masukkan irisan telor,bumbui garam,merica bubuk,kecap & saus tiram,aduk rata.\", \"Masukkan toge & daun bawang,masak sebentar saja agar toge masih kres. Jangan lupa koreksi rasanya yaa...\", \"Angkat & sajikan selagi hangat👍. Simpel,cepat,dan tentu saja enaak...\", \"Saya udah prnh setor resep ini ke mba Vy pas lagi booming☺\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1829, 3, 'Mie Rebus Sosis Telur', 'Sajian Mie Rebus Sosis Telur yang praktis dan lezat untuk dinikmati bersama.', '[\"1 bungkus mie rebus instan\", \"1 buah Telur rebus\", \"1 buah Sosis\", \"secukupnya Daun bawang (iris tipis)\", \"3 buah  Cabe rawit (rajang)\", \"1 buah  Tomat (potong kecil)\", \"Bawang goreng\"]', '[\"Rebus mie\", \"Masukkan sosis, daun bawang, cabe rawit dan tomat\", \"Masak hingga matang, lalu masukkan minyak dan bumbu mie\", \"Sajikan dengan potongan telur rebus dan taburi bawang goreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1830, 4, 'Oseng mandai telur pedas', 'Sajian Oseng mandai telur pedas yang praktis dan lezat untuk dinikmati bersama.', '[\"1 piring mandai\", \"2 butir telur\", \"6 siung bawang merah\", \"4 siung bawang putih\", \"1 buah tomat\", \"10 buah cabe rawit\", \"Secukupnya minyak goreng\", \"Secukupnya air\", \"1 bks royko/Masako ayam\", \"1 sdt gula\"]', '[\"Potong dadu mandai, lebih baik di potong dulu lalu taruh di piring jadi pas ukurannya jadi sepiring. Setelah itu cuci bersih mandai & tiriskan.\", \"Iris bawang, tomat & cabe. Tumis hingga harum, kemudian masukan mandai. Tambahkan air secukupnya. Tujuannya utk merebus mandi agar lebih empuk, masak hingga air mulai mengering. Jika mandai masih agak keras, tambahkan lagi air. Sebenarnya tergantung tahap awal kita permentasi mandai nya, jika permentasi nya sempurna, maka mandai akan menjadi lebih lembut.\", \"Setelah air mengering, sisihkan mandai ke sisi wajan (buat lubang di tengah wajan)kecilkan api spy telur tdk cpt gosong. ceplok telur, diamkan bbrp saat sampai setengah matang lalu aduk bersama mandai.\", \"Bumbui dgn royko & gula. Cek rasa & selamat menikmati. Catatan knp saya pakai royko krn mandai sdh asin jd cuma menambahkan rasa gurih nya saja.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1831, 4, 'Telur Balado (pakai resep Desaku balado bubuk)', 'Resep praktis Telur Balado (pakai resep Desaku balado bubuk) yang bisa dicoba di rumah.', '[\"6 Butir Telur Ayam (rebus terlebih dahulu)\", \"secukupnya Minyak goreng\", \"8 siung bawang merah\", \"4 siung bawang putih\", \"5 cabai rawit (yang suka pedes bisa ditambah ya bu ibu)\", \"1 buah tomat\", \"1 lembar daun salam (bila perlu)\", \"1 sdm gula pasir\", \"1/2 sdm garam\", \"1 gelas air putih\", \"secukupnya Kecap\"]', '[\"Rebus telur terlebih dahulu,setelah itu goreng telur dalam minyak panas (bila ingin ada sensasi kriuk dari bagian putih telur, tidak usah digoreng juga bisa)\", \"Blender bawang merah,bawang putih,cabai,tomat (bisa diuleg halus saja kalau tidak ada blender)\", \"Panas kan minyak goreng,tumis bumbu yg sudah dihaluskan tadi.. Jika sudah harum masukkan daun salam bila perlu sampai harum.. Masukkan 1 sachet bumbu balado (1 sachet bumbu balado ini bisa untuk 8butir telur)\", \"Tambahkan air, masukkan telur rebus nya.. Tambahkan gula & garam serta kecap secukupnya (kenapa saya pakai kecap? Jadi, bumbu baladonya rasanya rada pahit.. Makanya saya beri kecap agar ada sedikit rasa manis. Untuk menetralisir rasa)\", \"Tunggu sampai airnya surut dan bumbunya mengental.\", \"Telur balado siap dihidangkan❤\", \"Selamat mencoba❤\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1832, 4, 'Telor dadar kecap', 'Nikmati kelezatan Telor dadar kecap dengan resep sederhana ini.', '[\"2 butir telor\", \"2 sdm kecap manis\", \"secukupnya Kaldu bubuk\"]', '[\"Pecahkan telor kedalam mangkok, campurkan dengan kecap n kaldu bubuk aduk rata\", \"Panaskan minyak lalu goreng telor hingga matang angkat n tiriskan\", \"Siap disajikan\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1833, 3, 'Scramble Egg Kornet Pedass', 'Resep Scramble Egg Kornet Pedass yang lezat dan mudah dibuat di rumah.', '[\"2 Butir Telur Ukuran Besar\", \"2 Sdm Kornet Sapi (Aku Pakai Pronas)\", \"2 Jumput Garam Halus (Sesuai Selera)\", \"2 Jumput Lada Bubuk\", \"Sedikit Minyak Goreng\", \"Bumbu Rajang :\", \"2 Butir Bawang Merah\", \"2 Butir Bawang Putih\", \"1/2 Buah Bawang Bombay\", \"10 Buah Cabe (Bisa Di Sesuaikan/Skip Aja)\"]', '[\"Siapkan wadah pecahkan 2 butir telur kocok lepas hingga rata tambahkan garam,lada bubuk kornet,potongan cabe, kocok hingga rata.\", \"Panaskan minyak tumis rajang bawang merah, bawang putih, bombay hingga layu.\", \"Tuangkan wadah berisi capuran telur tumis telur hingga telur menjadi serpihan, jika kurang rasa bisa di taburi sedikit garam.\", \"Tes rasa matikan.\", \"Selamat Mencoba.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1834, 2, 'Lumpia udang kulit tahu ala fe\'', 'Resep praktis Lumpia udang kulit tahu ala fe\' yang bisa dicoba di rumah.', '[\"50 gram ayam potong kotak kecil\", \"200 gram udang besar potong kecil\", \"1 lembar daun bawang iris halus\", \"1/2 sendok teh garam halus/sesuai selera\", \"1/2 sendok teh gula\", \"1/4 sendok teh merica bubuk\", \"1 sendok teh kecap ikan\", \"1 sendok teh saus raja rasa\", \"1 sendok teh saus tiram\", \"1 sendok teh minyak wijen\", \"1 sendok makan tepung sagu\", \"1 sendok teh tepung terigu\", \"1 butir telur ambil bagian putihnya saja, kocok lepas\", \"2 lembar kembang tahu kering / kulit tahu direndam sebentar\"]', '[\"Campur ayam & udang dengan semua bumbu & daun bawang, aduk rata. Sesudah rata masukkan tepung sagu, terigu & putih telur. Aduk rata.\", \"Isikan ke lembaran kulit kembang tahu & lipat seperti melipat lumpia, sambil dipadatkan agar rapi & bentuk agak pipih jangan terlalu bulat. Olesi putih telur diujung lipatan agar merekat rapat.\", \"Kukus sekitar 15 menit hingga matang. Angkat dinginkan. Siap digoreng dengan api kecil sebentar. Anakku suka digoreng agak lama dengan kuning telur kocok sisa adonan tadi. Nanti jadi ada kayak jala2 crispynya yang gurih & kering. Angkat & tiriskan jika sudah digoreng matang.\", \"Sajikan dengan dipotong diagonal (potong 2 serong). Siap disantap dengan saus sambal botol yang biasanya saya rebus dengan bawang goreng, cabe rawit iris, gula & sedikit air. Selamat mencoba.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1835, 3, 'Bakwan Udang Sederhana', 'Resep Bakwan Udang Sederhana ala rumahan yang dijamin menggugah selera.', '[\"1/2 kg Tepung terigu (sudah di ayak)\", \"1/2 Udang segar\", \"1 btr Telur\", \"4 siung bawang putih\", \"1 sdm garam\", \"1/2 sdm picin\", \"1/2 bks penyedap rasa\", \"1/2 sdm Merica bubuk\", \"1/2 Ltr Air putih es\", \"Minyak Makan\", \"Daun Bawang (cincang)\", \"Wortel (potong potong kecil)\"]', '[\"Haluskan bawang putih, garam, picin dan merica bubuk\", \"Masukan bumbu yang dihalus kan ke dalam udang, masukkan tepung terigu dan air secukup nya (jangan terlalu kental)\", \"Pecahkan telur kedalam adonan, masukan potongan wortel dan daun bawang aduk hingga merata\", \"Panas kan minyak goreng, masuk kan adonan sedikit demi sedikit\", \"Setelah matang tiris kan, nikmati dengan saus tomat. Yummy\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1836, 3, 'Udang Goreng Tepung Mayonaise', 'Sajian Udang Goreng Tepung Mayonaise yang praktis dan lezat untuk dinikmati bersama.', '[\"300 gr udang (buang kepalanya)\", \"Jeruk nipis\", \"Tepung bumbu Kobe\", \"Sedikit garam\", \"Bahan saos:\", \"Mayonaise 2 sachet @30 ml (saya pakai mayumi)\", \"1-2 sdm saos sambal/tomat\", \"1 sdm susu kental manis\"]', '[\"Cuci bersih udang, tambahkan jeruk nipis supaya tidak amis dan sedikit garam (agar rasa udang sedikit gurih). Sisihkan.\", \"Tuang tepung bumbu secukupnya dalam wadah beri sedikit air hingga tekstur kental. Dalam wadah lain tuang tepung bumbu yang kering (saya campur dengan 2 sdm tepung beras agar gorengan lebih kriuk).\", \"Masukkan udang kedalam adonan cair tepung kemudian pindahkan ke dalam tepung kering. Tepuk2 ringan supaya tepung menempel. Lalu goreng dalam wajan berisi minyak panas sampai kecoklatan.\", \"Saos Mayonaise\", \"> campur semua bahan saos aduk rata. Koreksi rasa.\", \"Sajikan udang goreng tepung dengan saos mayonaise (bisa dicocol atau disiram diatas udang).\", \"Selamat menikmati ☺\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1837, 2, 'Udang saus asam manis', 'Resep Udang saus asam manis ala rumahan yang dijamin menggugah selera.', '[\"1 Kg Udang mutiara\", \"7 siung bawang merah\", \"4 siung bawang putih\", \"4 buah cabai merah\", \"3 ruas jahe\", \"3 ruas lengkuas\", \"5 sdm saus cabai\", \"10 sdm saus tomat\", \"2 sdm saus tiram\", \"5 sdm minyak sayur\", \"1 sdt lada bubuk\", \"1 1/2 sdt Garam (secukupnya)\", \"100 ml air\"]', '[\"Iris bawang merah, bawang putih, jahe, lengkuas, dan cabai merah\", \"Masukan minyak dan bahan yang telah diiris, tumis hingga harum\", \"Masukkan saus tiram, saus cabai dan saus tomat.\", \"Masukan udang. Tambahkan garam dan lada bubuk.\", \"Masukan air matang, aduk rata. Tunggu hingga matang.\", \"Sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1838, 4, 'Tekwan Kuah Udang', 'Tekwan Kuah Udang - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"Untuk Tekwan :\", \"1/4 ekor ikan tenggiri 🌸\", \"2 butir putih telur 🌸\", \"1 sdm kaldu bubuk 🌸\", \"2 sdt garam 🌸\", \"1 sdt gula (aku pakai brown sugar) 🌸\", \"1 sdt lada 🌸\", \"100 ml air dingin 🌸\", \"20 ml minyak sayur 🌸\", \"200 g tepung kanji 🌸\", \"1 liter Air untuk merebus\", \"2 sdm minyak sayur untuk rebusan\", \"Untuk Kuah Tekwan :\", \"1/2 kg Udang\", \"10 butir bawang putih\", \"10 buah Jamur kuping\", \"Bahan Tambahan :\", \"Bihun \\\\ soun\", \"Daun bawang\", \"Sambal cair\"]', '[\"Untuk membuat tekwan, rebus air dengan 2sdm minyak sayur tunggu hingga mendidih. Campur semua bahan 🌸 aduk rata. Bulat- bulatkan adonan lalu celupkan ke dalam air mendidih, tunggu hingga mengapung. Sisihkan.\", \"Untuk Kuah tekwan, kupas udang pisahkan kulit dan kepala nya. Rebus kulit udang sebentar saja hingga mendidih.\", \"Blender kepala udang dalam keadaan mentah, sisihkan.\", \"Rebusan kulit udang tadi, buang kulitnya. Lalu, masukan blenderan kepala udang, udang potong dan tumisan bawang putih. Masak hingga 10 menit.\", \"Tata dalam mangkuk. Bihun matang, tekwan, jamur. Lalu guyur kuah tekwan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1839, 3, 'Sambal udang goreng', 'Buat Sambal udang goreng yang nikmat dengan langkah-langkah mudah ini.', '[\"1/4 kg udang\", \"2 buah jeruk nipis\", \"Minyak goreng\", \"Garam\", \"Gula pasir\", \"Penyedap rasa\", \"Daun jeruk\", \"Bumbu dihaluskan:\", \"6 siung bawang merah\", \"4 siung bawang putih\", \"1 buah tomat\", \"8 cabe merah (sesuai selera)\", \"5 cabe rawit (sesuai selera)\"]', '[\"Cuci udang bersih, lumuri dengan jeruk nipis\", \"Panaskan minyak, goreng udang sebentar\", \"Haluskan bumbu (saya lebih suka di uleg)\", \"Panaskan minyak sedikit, tumis bumbu halus & daun jeruk. Tumis hingga harum.\", \"Masukkan udang. Beri garam, penyedap rasa & 1 sdt gula pasir. Koreksi rasa nya. Tumis sampai bumbu meresap ke udang.\", \"Angkat & sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1840, 2, 'Udang asam manis oregano', 'Udang asam manis oregano dengan udang segar dan bumbu khas.', '[\"1/2 kg udang vaname\", \"1 bh bawang bombai\", \"2 siung bawang putih\", \"1 sdm oregano kering\", \"4-6 sdm saos tomat\", \"1 sdm saos sambal\", \"1 sdm gula\", \"sedikit garam\", \"sedikit air\", \"minyak untuk menumis\"]', '[\"Bersihkan udang dan cuci dengan air garam, iris bawang bombai dan bawang putih\", \"Siapkan wajan yang sudah diberi sedikit minyak lalu tumis bawang sampai harum dan masukkan oregano kering, beri sedikit air baru masukkan udang tunggu sampai udang berubah warna, baru masukkan saosnya beri garam dan gula,\", \"Tambahkan air sedikit lagi tunggu sampai mateng dan cicipin hemmmm,,,\", \"Nb. kalau menurut saya bund jangan pakai saos tomat mereknya delmonte karena kalau merek yg lain baunya g enak ada yg bau busuk ada juga yg bau kunyit,,,, hemmm, tp ini menurut saya ya,,,\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1841, 2, 'Tumis buncis pakai udang', 'Resep praktis Tumis buncis pakai udang yang bisa dicoba di rumah.', '[\"1/4 kg Buncis (iris serong)\", \"4 bh bawang putih (geprek cincang)\", \"Cabai merah keriting (sesuai selera)\", \"10 bh udang (kupas)\", \"1/2 sdt Kaldu jamur /royco\", \"Sejumput gula pasir\", \"secukupnya Garam\", \"1 sdt kecap ikan\", \"secukupnya Lada\", \"150 ml air\"]', '[\"Tumis bawang putih sampai harum, masukan udang, kecap ikan, tumis sampai kemerahan\", \"Masukan buncisnya aduk, masukan kaldu jamur, lada, gula pasir, garam, aduk2, beri air...\", \"Tumis sampai mendidih dan air menyusut... Cicipi rasa.... Jika buncis sudah empuk dan matang, siap disajikan. 👍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1842, 3, 'Udang saos padang', 'Udang saos padang - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"800 gr udang\", \"secukupnya Jahe memarkan\", \"secukupnya Lengkuas memarkan\", \"3 sdm saos sambal\", \"3 sdm saos tiram\", \"1 buah tomat\", \"secukupnya Air\", \"secukupnya Minyak\", \"Garam\", \"Gula\", \"Bumbu halus\", \"6 siung bawang putih\", \"8 siung bawang merah\", \"6 buah cabai merah besar\", \"10 buah cabai\", \"secukupnya Merica\"]', '[\"Haluskan bumbu, tumis di atas wajan dengan minyak secukupnya\", \"Masukkan udang, tomat, dan air\", \"Beri gula, garam, saos tiram dan sambal, aduk rata, kemudian tes rasanya\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1843, 3, 'Udang Goreng Mentega', 'Cara membuat Udang Goreng Mentega yang enak dan praktis untuk keluarga.', '[\"200 gr udang\", \"1/2 buah bawang bombai\", \"2 buah bawang putih\", \"5 buah bawang merah\", \"4 sdm mentega\", \"1 sdt saus tiram\", \"1 sdt saus pedas\", \"1 sdt saus tomat\", \"1 jumput garam\"]', '[\"Bersihkan udang\", \"Iris bawang merah, bawang putih dan bawang bombai menjadi bagian yang kecil dan tipis.\", \"Siapkan wajan / teflon, nyalakan api kecil, kemudian masukan mentega hingga leleh dan panas.\", \"Tumis bawang merah dan bawang putih sebentar saja sekitar 1 menit. Lalu masukan bawang bombai. Tumis lagi hingga harum.\", \"Masukkan udang, garam, saus tiram, saus pedas dan saus tomat. Aduk hingga rata\", \"Jika sudah matang, angkat dan sajikan :)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1844, 3, 'Udang goreng mentega', 'Buat Udang goreng mentega yang nikmat dengan langkah-langkah mudah ini.', '[\"1/2 udang\", \"10 buah cabe hijau\", \"5 siung bawang merah\", \"secukupnya Mentega\", \"secukupnya Garam\", \"secukupnya Penyedap rasa\", \"secukupnya Gula\", \"Perasan jeruk nipis\"]', '[\"Bersihkan udang dari kulit dan kotoran.\", \"Potong cabe dan bawang sesuai selera.\", \"Campurkan cabe dan bawang dan perasan jeruk nipis kedalam udang lalu beri garam gula dan penyedap rasa, aduk sampai terserap\", \"Panaskan wajan lalu masukan mentega dan sedikit minyak. Setelah panas masukan udang yang sudah dicampur dengan bawang dan cabe tadi\", \"Aduk sebentar lalu kecilkan api dan tutup wajan sampai air yang ada didalam wajan surut.\", \"Setelah air mulai sedikit dan udang sudah merah dan lunak angkat lalu tiriskan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1845, 4, 'Udang pete balado', 'Resep Udang pete balado yang lezat dan mudah dibuat di rumah.', '[\"250 gr udang ukuran sedang, kupas, buang kepala dan kulitnya\", \"1 papan petai, buka, bersihkan dr kulitnya, potong mjd 2\", \"4 siung bawang merah\", \"3 siung bawang putih\", \"2 butir kemiri\", \"10 buah cabe merah keriting\", \"Garam secukupnyag\", \"secukupnya Gula pasir\", \"1 ruas jari lengkuas, bersihkam, geprek\", \"1 lembar daun salam\", \"Minyak goreng\", \"1 buah jeruk nipis, belah 2, peras ambil airnya\"]', '[\"Tuang perasan air jeruk nipis ke dalam udang yg sudah dibersihkan. Beri sedikir garam, Aduk2.diamkan sekitar 10menit. Sisihkan.\", \"Tuang minyak sayur, goreng udang dengan api sedang, aduk2 sebentar sampai udang berubah warna kemerahan dan matang, tiriskan. Angkat.\", \"Haluskan bawang putih, bawang merah, kemiri, cabe rawit merah. Sisihkan\", \"Tumis bumbu halus, daun salam dan lengkuas dengan api kecil agar matng dan tidak cepat gosong.\", \"Jika sudah tercium bau harum lalu masukan potongan2 petai yg sudah bersih, aduk2 sebentar, koreksi rasa, tambahkan garam dan gula secukupnya. Aduk kembali hingga rata\", \"Masukan udang yg telah digoreng, aduk rata, angkat. Sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(1846, 4, 'Bakso udang debm', 'Hidangan seafood nikmat: Bakso udang debm untuk pecinta udang.', '[\"500 gram udang\", \"1 sdm tepung keto\", \"1 butir putih telur\", \"1 sdm minyak wijen (opsional)\", \"3 biji bawang putih\", \"Secukupnya garam\", \"3 cube es batu\", \"Secukupnya air es\"]', '[\"Campurkan smua bahan kecuali air es dalam food procesor.proses sampai bener2 halus\", \"Panaskan air dalam panci.bulat2 kan adonan menggunakan sendok lalu rebus sampai matang.\", \"Angkat dan rendam dalam air es untuk menghentikan proses pematangan.biar kenyel ga lembek\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1847, 2, 'Oseng Udang Pedas 🍤🌶️', 'Resep Oseng Udang Pedas 🍤🌶️ yang lezat dan mudah dibuat di rumah.', '[\"1 Kg Udang Ukuran Sedang\", \"5 Butir Bawang Merah (Rajang)\", \"3 Butir Bawang Putih (Rajang)\", \"2 Buah Tomat Segar Ukuran Sedang (Iris)\", \"20 Buah Cabe Rawit Iris (Sesuai Selera)\", \"Secukupnya Lada bubuk\", \"Secukupnya royco bubuk\", \"Secukupnya Gula garam\"]', '[\"Udang buang kepala cuci bersih tiriskan (kalau mau di kupas bersih monggo) rajang bawang, tomat dan cabe.\", \"Panaskan wajan tuang 3sdm minyak goreng tumis bumbu rajang hingga harum masukan sedikit air hingga mendidih tuang udang.\", \"Masukan rajangan tomat dan cabe taburi gula, garam, lada tes rasa matikan.\", \"Selamat Mencoba.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1848, 3, 'Udang Goreng Tepung', 'Resep Udang Goreng Tepung ala rumahan yang dijamin menggugah selera.', '[\"250 gr udang kupas\", \"9 sdm tepung terigu\", \"3 sdm tepung kanji\", \"1/2 sdt merica bubuk\", \"Bahan Perendam:\", \"1 butir telur\", \"1/2 sdt merica\", \"1 siung bawang putih\", \"1/2 sdm saos tiram\", \"secukupnya Garam\"]', '[\"Haluskan bawang, merica dan garam.\", \"Kocok telur, campur dengan bumbu yang sudah dihaluskan ditambah saos tiram.\", \"Masukkan udang ke kocokan telur.\", \"Campur tepung terigu, kanji dan merica bubuk.\", \"Ambil udang dan masukkan ke campuran tepung. Lalu celup lagi ke kocokan telur, ualngi masukkan ke tepung sambil ditekan telan dan dicubit-cubit.\", \"Goreng udang di minyak yang sudah panas. Api sedang. Goreng hingga udang tercelup minyak semua. Biar irit minyak, saya memakai panci kecil. Jadinudang bisa tercelup minyak semua.\", \"Sajikan..biasanya untuk mengoreksi rasa, saya goreng udangnya ato tepungnya sedikit dulu, bila kurang asin bisa ditambah garam di kocokan telur.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1849, 2, 'Udang goreng tepung', 'Udang goreng tepung - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1/5 kg udang besar\", \"2 bungkus Sasa tepung bumbu yg oriental\", \"Minyak untu menggoreng\", \"Saos sambal(cocolan)\", \"Penyedap rasa\", \"Adonan basah;\", \"4 sendok tepung bumbu\", \"Air es\", \"Adonan kering;\", \"Tepung bumbu\", \"Penyedap rasa\"]', '[\"Cuci bersih udang buang kepala&kulitnya sisakn ekornya,,belah bagian perutnya lalu bersihkn benang yg terdapat di dlmnya😉\", \"Masukan udang ke dlm adonan basah lalu balur ke adonan kering masukan lg ke adonan basah n balur ke adonan kering lg,lakukan sampai habis.\", \"Panaskan minyak agak banyak ya agar terendam,api kecil saja biar matang merata.\", \"Udang goreng tepung siap di sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1850, 3, 'Udang asam manis', 'Udang asam manis dengan udang segar dan bumbu khas.', '[\"1/2 kg udang jerbung\", \"5 siung bawang putih\", \"Secukupnya saos tomat\", \"Secukupnya saos cabai\", \"1 sdm tepung maizena larutkan dg air\", \"2 sdm Margarin\", \"Gula garam dan penyedap\", \"Secukupnya minyak goreng\", \"1/2 Bks Saori\", \"3 lbr daun salam\", \"5 lbr daun jeruk\", \"1 ruas jahe\", \"1 buah jeruk nipis\"]', '[\"Cuci udang sampai bersih buang bagian kepala udangnya,. Belah punggung udang (biar bisa mekar pas di tumis) lalu kasih air jeruk nipis diamkan 10 menit lalu bilas dgn air bersih\", \"Cincang bawang putih,geprek jahe panaskan margarin campur sedikit minyak goreng lalu tumis bawang putih dan jahe sampai harum setelah harum masukan daun salam dan daun jeruk di barengi udang,..aduk sampai udang berubah warna kasih sedikit air\", \"Masukan garam penyedap Saori dan saos tomat dan saos cabe gula diamkan sampai air hampir hbis setelah hbis larutkan 1 sendok tepung maizena lalu siramkan ke tumisan udang\", \"Test rasa KL sekiranya udh cukup rasanya udang asem manis siap di sajikan beserta nasi hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1851, 3, 'Udang Saus Telor Asin', 'Buat Udang Saus Telor Asin yang nikmat dengan langkah-langkah mudah ini.', '[\"500 gr Udang, kupas & sisakan ekornya\", \"2 sdt Air jeruk nipis\", \"1/4 sdt Garam\", \"1/4 sdt Merica\", \"6 sdm Tepung Maizena\", \"3 btr Kuning telur asin, haluskan\", \"50 ml Air panas\", \"1/4 sdt Kaldu bubuk, bisa diskip bila dirasa asinnya pas\", \"3 bh Bawang putih, cincang halus\", \"1/4 sdt Gula\", \"1 btg Daun bawang iris halus\", \"secukupnya Minyak goreng\", \"2 sdm Margarin\"]', '[\"Lumuri udang dengan air jeruk nipis, garam dan merica bubuk. Diamkan sekitar 15 menit. Taburkan maizena dan balut sampai rata. Goreng udang dengan minyak yang banyak hingga matang dan tepung kering. Angkat. Sisihkan.\", \"Larutkan kaldu bubuk dalam air panas. Sisihkan.\", \"Panaskan margarin, tumis bawang putih hingga harum. Masukkan kuning telur asin, aduk rata.\", \"Masukkan air kaldu dan gula pasir. Masak hingga mendidih. Masukkan daun bawang. Aduk rata sebentar. Masukkan udang goreng. Aduk cepat sampai udang terbalut rata. Matikan api. Angkat. Sajikan panas\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1852, 2, 'Udang sawi saori saus tiram😆😆', 'Nikmati kelezatan Udang sawi saori saus tiram😆😆 dengan resep sederhana ini.', '[\"1/4 Udang\", \"Bumbu dasar tentunya udh pda tau\", \"Bawang merah/putih\", \"Cabe merah rawit\", \"Tomat salam sereh\", \"Semua bumbu secukupnya diris\"]', '[\"Semua bumbu di iris,lalu tumis ampe harum\", \"Masukan udang ke wajan tumisan bumbu sampe matang harum jgn lupa bubuhi kecap saus tiram biar mantap\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1853, 4, 'Tumis kacang panjang,udang,tahu', 'Sajian Tumis kacang panjang,udang,tahu yang praktis dan lezat untuk dinikmati bersama.', '[\"1 ikat kacang panjang (saya beli 1000)\", \"1 kotak tahu\", \"1/4 kg udang\", \"Bumbu halus :\", \"2 cabai merah besar\", \"15 cabai merah kecil (klo tdak suka pedas bisa dikurangi)\", \"5 bawang merah\", \"3 bawang putih\", \"2 butir kemiri\", \"1 buat tomat\", \"2 sdm saori saus teriyaki\", \"secukupnya Garam\", \"secukupnya Gula\", \"secukupnya Penyedap rasa\"]', '[\"Cuci bersih udang, buang kepala.\", \"Potong tahu kotak2 kecil, lalu goreng setengah matang.\", \"Rebus kacang setengah matang.\", \"Panaskan minyak, tumis bumbu yang sudah dihaluskan hingga harum, tambahkan sedikit air.\", \"Kemudian beri garam,gula,penyedap.saus teriyaki.Test rasa.\", \"Masukkan kacang, aduk rata. Kemudian masukkan tahu,terakhir masukkan udang. Aduk2 sampai rata.\", \"Biarkan sampai air menyusut dan bumbu meresap.\", \"Tumis kacang,udang,tahu siap dihidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1854, 3, 'Udang Goreng Saus Telur Asin', 'Resep Udang Goreng Saus Telur Asin yang lezat dan mudah dibuat di rumah.', '[\"1/4 kg udang kupas\", \"2 butir telur asin\", \"1 bks tepung bumbu\", \"2 bh jeruk nipis\", \"2 bh bawang putih\", \"1 bh daun bawang\", \"1 bh cabai rawit\", \"1 bh cabai besar\", \"Kaldu bubuk (secukupnya)\", \"Mentega\", \"secukupnya Air\"]', '[\"Cuci udang dengan air bersih lalu campurkan udang dengan 2 bh jeruk nipis lalu bilas dengan air lagi agar bau amisnya hilang\", \"Goreng udang dengan baluran tepung bumbu hingga matang dan renyah lalu angkat dan tiriskan\", \"Kupas 1 butir telur asin hancurkan, lalu tambahkan 1 butir telur asin lagi tetapi hanya kuningnya saja\", \"Geprek lalu cincang 2 bh bawang putih, potong cabai miring ataupun sesuai selera, potong juga daun bawang\", \"Panaskan mentega lalu tambahkan bawang putih, cabai rawit, cabai besar lalu tumis sampai wangi lalu tambahkan daun bawang\", \"Tambahkan air secukupnya aduk lalu tambahkan juga telur asin yang sudah dihaluskan dan kaldu bubuk secukupnya (bisa juga ditambahkan sedikit gula jika mau tapi saya tidak pakai) tunggu sampai air meletup yang artinya matang\", \"Masukkan udang yang sudah digoreng aduk sampai saus merata\", \"Udang siap disajikan😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1855, 3, 'Udang Sambal Petai (Sangat Sederhana)', 'Resep Udang Sambal Petai (Sangat Sederhana) yang lezat dan mudah dibuat di rumah.', '[\"1/4 kg Udang\", \"Petai 1 keris\", \"Minyak secukupnya untuk menumis\", \"sesuai selera Gula garam\", \"Bumbu halus (diblender)\", \"7 buah Cabe keriting\", \"3 siung Bawang putih\", \"4 siung Bawang merah\", \"2 buah tomat\", \"1/2 blok Terasi goreng ABC\", \"secukupnya Air\"]', '[\"Cuci semua bahan dan bumbu.\", \"Blender bumbu dengan setengah gelas air.\", \"Panaskan minyak dalam wajan.\", \"Goreng udang yang sudah dibersihkan.\", \"Masukkan petai. Masak sampe setengah matang.\", \"Masukkan bumbu yang sudah dihaluskan dengan blender.\", \"Beri gula garam dan saos tiram.\", \"Koreksi rasa, hidangkan dengan nasi panas.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1856, 2, 'Udang Saus Asam Manis 🍤', 'Hidangan seafood nikmat: Udang Saus Asam Manis 🍤 untuk pecinta udang.', '[\"1/2 Kg Udang uk besar\", \"4 butir bawang putih geprek cincang\", \"1 buah Bawang Bombay iris halus\", \"2 batang daun bawang iris\", \"3 sdm Saus Tomat merk delmonte\", \"2 sdm Saus Tiram\", \"1 sdt lada bubuk\", \"secukupnya garam dan gula pasir\", \"secukupnya air\"]', '[\"Bersihkan Udang, cuci bersih lalu buang kepala dan cangkang badannya. Setelah itu, belah bagian punggungnya buang kotorannya. Beri garam dan jeruk nipis. Lalu goreng udang di minyak panas sebentar saja, hingga berubah warna kemerahan. Angkat dan tiriskan.\", \"Siapkan wajan, panaskan minyak. Tumis bawang putih cincang dan irisan bawang bombay hingga layu dan harum. Setelah itu masukkan saus tomat, saus tiram, lada bubuk, garam dan gula pasir aduk rata. Tuangkan air secukupnya aduk2.. lalu koreksi rasa.\", \"Bila rasa sudah pas, masukkan udang yg sdh digoreng tadi, aduk rata. Biarkan hingga bumbu meresap. Terakhir masukkan irisan daun bawang aduk rata. Masak sebentar saja,\", \"Angkat dan siap disajikan 👍 enakk beut😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1857, 4, 'Daun Singkong Pepes Udang Tahu #praktis', 'Daun Singkong Pepes Udang Tahu #praktis dengan udang segar dan bumbu khas.', '[\"★ bumbu halus\", \"7 siung bawang merah\", \"5 siung bawang putih\", \"5 cabe merah\", \"4 cabe rawit\", \"1 ruas jahe\", \"1 ruas kencur\", \"1 ruas laos\", \"Secukupnya gula, garam, lada\", \"★ bahan isi\", \"60 gr daun singkong, rebus\", \"2 kotak tahu putih, lumat\", \"30 gr udang kecil2\", \"2 sdt teri nasi\", \"1 butir telor\", \"1 batang serai, iris2\", \"2 lembar daun jeruk, iris2\", \"Secukupnya garam dan kaldu bubuk\", \"Daun pisang\"]', '[\"Panaskan wajan, tumis sebentar udang dan teri hingga baunya keluar. Sisihkan.\", \"Daun singkong yg sudah direbus, peras hingga tidak ada air dan potong2 agar mudah memakannya.\", \"Panaskan daun pisang diatas api kompor hingga layu sehingga gampang untuk membungkus dan tidak robek.\", \"Campur semua bahan jadi satu dan aduk rata. Jangan didiamkan trlalu lama karna bila telor sudah dimasukkan dan didiamkan terlalu lama akan berair\", \"Sebelum membungkus, panaskan kukusan yg telah diberi air. Lalu Ambil daun pisang dan isi dengan adonan yg telah di aduk jadi satu. Besar kecilnya ukuran pepes tergantung selera. Lalu kukus kurleb 10-30 menit (tergantung ukuran tiap bungkus) atau sampai matang\", \"Setelah dikukus, bakar diatas api kompor dan pepes siap disajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1858, 4, 'Udang Saus Tiram', 'Udang Saus Tiram - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1/2 kg udang\", \"1 buah wortel (dipotong sesuai selera)\", \"bumbu saus :\", \"1 buah tomat (potong sesuai selera)\", \"1 cabai merah besar(buang biji dan potong*)\", \"3 cabai rawit diiris\", \"5 siung bawang putih dicincang\", \"5 siung bawah merah diiris\", \"2 sdm saus cabai\", \"1 sdm saori saus tiram\", \"daun bawang\", \"secukupnya garam\", \"1 sdm tepung meizena (larutkan dengan 2 sdm air panas)\", \"margarin untuk menumis\", \"air\"]', '[\"Bersihkan udang dan pisahkan dari cangkangnya\", \"Siapkan penggorengan lalu tumis bawang merah,bawang putih,cabai rawit,cabai merah,tomat dengan margarin sampai harum\", \"Masukan wortel dan udang,beri setengah gelas air dan masak hingga udang berubah warna\", \"Beri saus cabai dan saus tiram lalu tuangkan tepung meizena yg sudah di larutkan.\", \"Setelah matang taburi daun bawang dan koreksi rasa.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1859, 4, 'Sambal jeki udang', 'Sambal jeki udang dengan udang segar dan bumbu khas.', '[\"3 ons jeki alias jengkol\", \"4 ons udang\", \"5 butir bwgmerh\", \"2 siung bwg putih\", \"1 ons cabe merh\", \"1 buah tomat merah yg besar\", \"secukupnya Minyk goreng\", \"secukupnya Garam\", \"secukupnya Gula\"]', '[\"Rendam jengkol semalaman\", \"Lalu cuci bersh,potong2,goreng tutup.\", \"Udang kupas bersh lalu cuci bersh,lalu kash garam sdkit nperasin jeruk npis lalu goreng\", \"Lalu tumis semua bumbu n cabe hingga mtng lalu masukan jeki n udang lalu tes rasa,\", \"Angkat sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1860, 3, 'Udang goreng tepung sederhana', 'Sajian Udang goreng tepung sederhana yang praktis dan lezat untuk dinikmati bersama.', '[\"1/4 udang segar\", \"tepung bumbu sasa\", \"sedikit bubuk lada\", \"sedikit garam\"]', '[\"Cuci udang yang sudah di siangkan\", \"Lumuri udang dengan tepung siap pakai, kemudian beri lada dan garam, diamkan selama 10 menit\", \"Panaskan minyak lalu masukkan udangnya, dan goreng hingga kecoklatan. lalu siap di hidangkan di piring saji.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1861, 2, 'Sambel Goreng Udang Tahu', 'Sajian Sambel Goreng Udang Tahu yang praktis dan lezat untuk dinikmati bersama.', '[\"250 gram udang windu lepaskan dari cangkangnya dan cuci bersih\", \"1 buah Tahu potong dadu goreng setengah matang\", \"1/2 siung bombay\", \"2 siung bawang putih\", \"3 siung bawang merah\", \"1 buat tomat potong potong\", \"3 buah cabai rawit\", \"1 sdm saus tiram\", \"1 sdm saus tomat\", \"1 sdt lada bubuk\", \"Secukupnya gula\", \"Secukupnya garam\", \"3 sdm kecap manis\", \"1 buah santan kara\"]', '[\"Haluskan bawang merah, bawang putih, cabai rawit tumis hingga harum. Masukkan udaang yang sudah bersih. Tumis hingga udang berwarna merah.\", \"Masukkan air sedikit, tunggu hingga mendidih lalu masukkan tomat dan tahu yang sudah di goreng.\", \"Tambahkan gula, lada, garam, says tiram, saus tomat dan kecap. Tumis aduk aduk hingga rata.\", \"Masukkan santan dan\", \"Diamkan sampai 10 menit dan siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1862, 3, 'Udang Lombok Merah', 'Nikmati kelezatan Udang Lombok Merah dengan resep sederhana ini.', '[\"1/4 kg udang, buang bagian kepalanya\", \"7 buah cabe merah besar\", \"4 siung bawang putih\", \"1 sdm garam (sesuai selera)\", \"Minyak untuk menumis\", \"50 ml air\"]', '[\"Bersihkan udang, buang bagian kepalanya saja.\", \"Haluskan:cabe merah besar, bawang putih dan garam\", \"Tumis bumbu yang sudah dihaluskan. Tambahkan sedikit air.\", \"Masukkan udang hingga matang.\", \"Sajikan bersama nasi hangat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1863, 3, 'Tumis Labu Udang', 'Buat Tumis Labu Udang yang nikmat dengan langkah-langkah mudah ini.', '[\"1 buah labu siam\", \"Udang Kupas\", \"Daun salam\", \"Royco/garam gula pasir\", \"Saos tiram\", \"Merica\", \"secukupnya Air\", \"Bumbu isi:\", \"4 baw.merah\", \"2 baw.putih\", \"4 cabe merah\", \"tomat boleh pake boleh engga\"]', '[\"Tumis bumbu iris sampai harum\", \"Masukkan udang kupas, masak sampai udang berubah warna\", \"Masukkan labu siam yg sudah diparut/diiris halus, tambah sedikit air\", \"Beri merica, royco dan saos tiram lalu masak sebentar lalu angkat, siap sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1864, 2, 'Martabak telur udang', 'Nikmati kelezatan Martabak telur udang dengan resep sederhana ini.', '[\"2 telur ayam\", \"6 ekor udang (buang kulit lalu cincang halus)\", \"4 lembar kulit lumpia\", \"1/2 wortel (potong dadu)\", \"1/4 Kol (iris tipis)\", \"2 batang daun bawang (iris halus)\", \"Bumbu halus:\", \"2 bawang merah\", \"4 bawang putih\", \"1/2 sendok makan merica\", \"Secukupnya garam\", \"1/4 sendok makan royco\"]', '[\"Tumis bumbu halus hingga harum kemudian masukkan udang tumis hingga berubah warna\", \"Masukkan daun bawang dan sayuran tumis hingga setengah matang\", \"Jika sudah masukkan telur kemudian aduk kira kira selama 5 menit kemudian masukkan garam dan royco aduk rata dan icip rasa jika sudah angkat dan biarkan dingin\", \"Jika sudah dingin tumisan dibungkus dengan kulit lumpia dan bisa direkatkan dengan putih telur agar tidak lepas saat digoreng\", \"Goreng hingga kecoklatan dan siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1865, 2, 'Tumis udang sayur', 'Cara membuat Tumis udang sayur yang enak dan praktis untuk keluarga.', '[\"8 ekor udang besar\", \"1 buah tempe (potong dadu)\", \"6 buah jagung muda (iris tipis)\", \"2 buah sawi\", \"5 buah bakso\", \"secukupnya Jamur hitam\", \"secukupnya Selada\", \"secukupnya Gula garam lada\", \"1 sdt minyak wijen\", \"2 sdm kecap manis\", \"5 siung bawang merah\", \"4 siung bawang putih\", \"8 buah cabai rawit\"]', '[\"Goreng terlebih dahulu tempe yg sudah di potong-potong dadu tadi sampai kering.\", \"Tumis bawang putih, bawang merah sampai harum. Kemudian masukkan udang yg sudah di bersihkan kulitnya. Tumis sampai udang berubah warna menjadi merah.\", \"Masukkan bakso, jagung muda, jamur, tempe. Tambahkan air secukupnya. Tambah gula garam lada. Koreksi rasa.\", \"Tambahkan kecap dan minyak wijen.\", \"Jika di rasa sudah mulai matang, masukkan sawi dan cabai rawit, aduk rata.\", \"Siap di hidangkaaan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1866, 2, 'Asam manis Udang tahu', 'Sajian Asam manis Udang tahu yang praktis dan lezat untuk dinikmati bersama.', '[\"1/2 kg udang\", \"1 tahu cina\", \"1/2 bawang bombay besar\", \"2 baput\", \"4 cabe kriting\", \"1/2 tomat besar\", \"2 sendok saus tiram\", \"4 sachet saus sambal\", \"Gula sckupnya\", \"Garam scukupnya\", \"Air\"]', '[\"Bersihkan udang,\", \"Potong dadu tahu dan goreng hingga kekuningan\", \"Iris2 bumbu diatas tadi\", \"Tumis baput dan babom hingga harum,masukan cabe, tomat, saus tiram,saus sambal,air,gula,garam\", \"Jika sudah pas rasanya,masukkan udang dan tahu tadi\", \"Tunggu hingga air surut atau sesuai selera 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1867, 3, 'Cah buncis udang cumi _ menudiet DEBM', 'Resep Cah buncis udang cumi _ menudiet DEBM yang lezat dan mudah dibuat di rumah.', '[\"250 gram buncis\", \"5 ekor udang\", \"5 ekor cumi\", \"1 sdm kecap ikan\", \"3 siung bawang putih cincang\", \"1/2 ruas jahe cincang\", \"1 sdm minyak wijen\", \"Lada\", \"Air se cukup nya\"]', '[\"Bersihkan buncis potong2. Bersih kan udang dan cumi potong2.\", \"Tumis bawang putih dan jahe hingga harum (bisa pakai minyak goreng biasa atau di campur minyak wijen). Masukkan udang dan cumi aduk2 hingga berubah warna tambahkan sedikit air, masukan kecap ikan dan lada. Setelah mendidih masukan buncis aduk hingga layu angkat dan sajikan dengan taburan bon cabe.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1868, 2, 'Udang Tumis Cabe Ijo', 'Resep Udang Tumis Cabe Ijo yang lezat dan mudah dibuat di rumah.', '[\"Bahan:\", \"1/2 kg Udang Pacet\", \"5 buah Cabe Ijo Besar\", \"5 siung Bawang Merah\", \"4 siung Bawang Putih\", \"1/2 siung Bawang Bombay\", \"5 buah Cabe Rawit Merah (opsional)\", \"1 sdm Minyak Wijen (opsional)\", \"1 sdt Kecap Ikan (opsional)\", \"2 sdt Gula\", \"1 sdt Garam\", \"1 buah Jeruk Nipis / Lemon\", \"secukupnya Air\", \"secukupnya Minyak goreng\"]', '[\"Kupas kepala udang pacet (kalo saya hanya kepalanya saja yg dibuang. Kulit dibadan udang tidak dibuang). Cuci bersih, kemudian lumuri dengan sejumput sdt gula dan sejumput sdt garam. Aduk rata menggunakan tangan, kemudian beri perasan air jeruk nipis / lemon. Diamkan selama 10 menit\", \"Sambil menunggu udang yang didiamkan 10 menit, kita siapkan bahan untuk ditumis. Iris halus cabe ijo besar, cabe rawit merah (opsional), bawang merah, bawang putih, bawang bombay.\", \"Panaskan minyak goreng diwajan dengan api sedang. Jika sudah panas, masukkan bawang merah dan bawang putih hingga harum dan setengah layu. Masukkan cabe ijo, rawit dan bawang bombay. Tumis hingga layu dan harum. Tambahkan minyak wijen dan kecap ikan. Tambahkan sedikit air, dan masukkan udang. Aduk hingga udang matang dan kemerahan. Tambahkan gula dan garam, aduk rata dan kemudian tes rasa. Jika sudah Pas, angkat dan sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1869, 3, 'Tumis kacang panjang+udang', 'Nikmati kelezatan Tumis kacang panjang+udang dengan resep sederhana ini.', '[\"1/2 kg kacng panjng\", \"10 ekor udang buang kulit badan,sisa ujung ekor saja\", \"2 buah bawang merah ukuran besar diiris\", \"1 buah bawang putih diiris halus\", \"2 SDM saus tiram\", \"3 SDM minyak sayur untuk menumis bawang2 nya\", \"1 SDT garam\", \"Tauco secukup ny,[boleh skip kalau gak suka]\", \"air secukup ny buat tumis\"]', '[\"Tumis bwang putih n merah dngan mnyak hingga harum,trus masuk kan udang di onseng2 hingga mateng\", \"Setelah itu masuk kan kacng panjang yg sudah dicuci,, trus masuk kan air ny untuk menumis,\", \"Baru masuk kan garam,tauco,saus tiram tadi,di onseng2 hingga kacang panjang matang de.n siap disajikan😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1870, 3, 'Udang Kentang Balado', 'Resep Udang Kentang Balado ala rumahan yang dijamin menggugah selera.', '[\"1/5 kg Udang\", \"1 buah kentang\", \"Cabai merah\", \"Bawang merah\", \"Bawang putih\", \"Tomat\", \"Garam\", \"Penyedap rasa (selera)\", \"Gula (selera)\"]', '[\"Cuci udang hingga bersih (buang kepala udang)\", \"Kupas kentang lalu potong dadu\", \"Goreng kentang terlebih dahulu, lalu goreng udang setengah matang.\", \"Ulek cabai, bawang merah, bawang putih, tomat. (Boleh blender)\", \"Panaskan minyak sisa menggoreng udang (sedikit saja), lalu masukkan bumbu yg sudah di ulek hingga aroma nya sedap. Tambahkan garam, penyedap rasa dan gula.\", \"Lalu masukkan kentang dan udang yg sudah di goreng tadi.\", \"Udang kentang balado siap di santap.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1871, 4, 'Udang goreng tepung mentega', 'Sajian Udang goreng tepung mentega yang praktis dan lezat untuk dinikmati bersama.', '[\"1/4 kg udang cuci brsh & buang kplanya\", \"2 sdm blueband cake&cookie\", \"4 sdm tepung terigu\", \"2 sdm air\", \"Minyak goreng sckpnya\", \"👉bumbu untuk udangnya\", \"Sdkt garam, lada bubuk&roico\"]', '[\"Udangnya stlh di cuci brsh trskan kmudian di lumuri bumbu...diamkan 15 mnt\", \"Kmudian aduk jd satu terigu,blueband tmbhin aer sdkt2..\", \"Stlh tercmpr rta & dikira pas kekentalanya clpkan udangnya & siap di goreng\", \"Goreng sampe kecoklatan..angkat&trskan... Renyahnya thn lama lhooo\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1872, 4, 'Udang Sambel Terasi', 'Nikmati kelezatan Udang Sambel Terasi dengan resep sederhana ini.', '[\"20 ekor udang\", \"1 buah jeruk nipis potong\", \"5 daun jeruk\", \"1 batang daun bawang iris\", \"Gula putih\", \"Garam\", \"Merica\", \"1/2 gelas air\", \"Bumbu ulek/blender:\", \"10 cabe merah\", \"5 rawit merah\", \"5 bawang merah\", \"5 bawang putih\", \"1 tomat\", \"1 sdt terasi bakar\", \"50 ml minyak goreng\"]', '[\"Cuci bersih udang, jangan di kupas. Peras jeruk nipis di atas udang, aduk rata.\", \"Tumis bumbu beserta daun jeruk, gula, garam & merica. Tambahkan air Aduk rata masak sampai bumbu sambel matang lalu masukan udang dan daun bawang. Masak sampai udang matang.\", \"Angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1873, 3, 'Udang lada hitam', 'Resep Udang lada hitam yang lezat dan mudah dibuat di rumah.', '[\"250 gr udang\", \"1 sdm maizena (dicampurkam kedalam udang)\", \"3 siung bawang putih\", \"1 buah bawang bombay\", \"1,5 sdm kecap manis\", \"1 sdm kecap ikan\", \"1 sdt minyak ikan\", \"1 sdt minyak wijen\", \"1 sdt saos tiram\", \"1 sdt lada hitam\", \"1 sdt lada putih\", \"secukupnya Penyedap rasa\", \"secukupnya Air\", \"1 sdm maizena dicampurkan kedalam air\"]', '[\"Campurkan udang dengan miezena dan kecap ikan aduk rata.diamkan sebentar\", \"Tumis udang yang sudah didiamkan sebentar dan tiriskan\", \"Tumis bawang putih dan bawah bombay sampai harum.kemudian masukkan udang yg sudah ditumis tadi menjdi satu.\", \"Masukkan bumbu pelengkap seperti kecap manis,saos saori,minyak wijen,penyedap rasa,lada hitam dan lada putih.terakhir masukkan larutan maizena aduk hingga rata dan tambahkan sedikit air.\", \"Setelah sudah mengental,hidangan siap disajikann\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1874, 2, 'Perkedel Udang', 'Resep Perkedel Udang yang lezat dan mudah dibuat di rumah.', '[\"1 kg kentang\", \"3 telur ayam\", \"Udang kupas sisakan buntutnya\", \"1/2 sdm garam (boleh kurangi jika terlalu asin)\", \"1/4 sdm royco ayam\", \"1/2 sdm gula\", \"1/4 sdm lada bubuk\", \"1/4 sdm pala bubuk\", \"Bahan pelapis\", \"1 butir telur\", \"secukupnya Tepung panir\"]', '[\"Kupas kentang, goreng, lumatkan\", \"Tambahkan telur dan semua bumbu kecuali bahan pelapis\", \"Dgn menggunakan plastik ambil adonan 1 sdm dan selipkan udang di dalamnya(buntutnya keluarin ya)\", \"Masukkan ke telur(kocok lepas) lalu gulingkan di tepung panir. Susun di loyang lalu oven +/- 30 menit (sesuaikan dengan oven masing2 ya)\", \"Kenapa saya panggang di oven? Karena adonannya lembut bangettt.. kalau langsung goreng bisa juga tapi wajib kurangi telurnya ya..\", \"Bisa langsung disantap atau pun bisa digoreng lagi supaya tambah gurih n garing renyah..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1875, 4, 'Sambel udang pete', 'Hidangan seafood nikmat: Sambel udang pete untuk pecinta udang.', '[\"250 gr Udang Kupas (Belah Punggung udang)\", \"100 gr Jagung Muda\", \"2 buah kentang\", \"1 papan Pete\", \"1 serai\", \"2 daun jeruk\", \"Garam dan gula, minyak untuk menumis secukupnya saja\", \"Bumbu Halus :\", \"3 Siung bawang putih\", \"10 Cabe Merah keriting\", \"1 buah tomat merah\"]', '[\"Haluskan Bumbu menjadi halus dengan mengunakan blender bumbu, sisihkan, blend juga tomat, sisihkan\", \"Kupas dan Potong kentang kotak kecil, Goreng 5menit, 1/2 matang, angkat tiriskan\", \"Panaskan minyak 2 sdm di wajan, masukan bumbu halus, tumis sampai wangi, tambahkan serai, daun jeruk, masukan tomat yang dihaluskan, tambahkan gula, garam secukupnya\", \"Masukkan Jagung muda, pete, Udang, aduk sebentar sampai meresap bumbunya, tambahkan Kentang yang sudah digoreng (Langkah 1) icip rasanya... boleh juga kasi air, masak 5menit ditutup, sajikan dengan nasi hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1876, 3, 'Cah udang dan kol', 'Resep Cah udang dan kol ala rumahan yang dijamin menggugah selera.', '[\"500 gram kol ukuran kecil, belah dua bagian\", \"200 gram udang kupas, sisakan ekornya belah punggungnya\", \"2 siung bawang putih, cincang halus\", \"1 sdm saus tiram\", \"1 sdm minyak wijen\", \"1 sdm kecap ikan\", \"1 sdm kecap inggris\", \"1 sdt tepung maizena, larutkan\", \"1 sdm margarin untuk menumis\", \"1 sdt garam\", \"1 sdt lada\", \"secukupnya Air\"]', '[\"Siapkan kol, rebus sebentar angkat tiriskan dalam mangkuk saji\", \"Tumis bawang putih hingga harum, masukan udang aduk sampai berubah warna, tambahkan kecap ikan saus tiram kecap inggris minyak wijen garam gula pasir & lada aduk2 tambahkan air biarkan mendidih\", \"Masukan larutan maizena aduk2 sebentar, incip rasa & sesuaikan tambahkan garam, gula (jika rasa belum pas)\", \"Angkat siramkan diatas kol, sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1877, 4, 'Tumis Udang saos tiram pedas', 'Nikmati kelezatan Tumis Udang saos tiram pedas dengan resep sederhana ini.', '[\"100 g udang\", \"1 sdm perasan air jeruk lemon/nipis\", \"1 batang daun bawang, potong2\", \"2 siung bawang putih\", \"1/2 Bawang Bombay\", \"4 bh Cabe rawit merah\", \"1 sdm Minyak wijen\", \"1 sdm kecap inggris\", \"1 sdm saos tiram\", \"1 sdm kecap manis\", \"1 sdm Mentega/margarin\", \"Secukupnya garam\"]', '[\"Buang kepala udang, kulit sisakan ekornya kerat/belah punggungnya lalu cuci bersih, lumuri udang dengan air perasan jeruk nipis/lemon, garam aduk rata sisihkan\", \"Geprek bawang putih berserta kulitnya, cincang kasar bawang bombay,\", \"Panaskan margarin/mentega tumis bawang bombay dan bawang putih, cabe sampai layu dan harum\", \"Masukan udang aduk rata, masak udang sampai berubah warna tambahkan kecap manis, minyak wijen, kecap inggris, daun bawang aduk rata, tes rasa kl udh pas tunggu sampai matang lalu angkat dan hidangkan\", \"Pedas, gurih dan enak😁\", \"Gak kalahlah sama yg diresto 😂\", \"Ini bikinan tadi siang sengaja buat makan anak, gak dikasih cabe krn mereka gak suka pedas 😁\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1878, 2, 'Memanfaatkan sampah udang', 'Resep praktis Memanfaatkan sampah udang yang bisa dicoba di rumah.', '[\"150 gr kepala udang (bakal sampah)\", \"secukupnya garam\"]', '[\"Cuci bersih kepala udang. Rebus kepala udang dengan 1/4 gelas sampai keluar saripatinya. Matikan kompor, airnya simpan dalam wadah. Ini bisa buat kuah kaldu udang (untuk Mpasi, atau tomyum).\", \"Kepala udang tadi di tiriskan, Kemudian sangrai kepala udang sampai benar-benar kering (kaku dan garing). Biarkan dingin.\", \"Blender halus kepala udang tadi dengan sejumput garam.\", \"Taruh pada wadah kering, dan bisa dibuat menjadi seperti olahan ebi, campuran nasi goreng, dan lauk lainnya agar terasa seperti makan seafood. Nah, mudah kan. Jadi dirumah bebas dari sampah udang deh. ;)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1879, 4, 'Tumis Pokcoy Udang', 'Sajian Tumis Pokcoy Udang yang praktis dan lezat untuk dinikmati bersama.', '[\"2 ikat pokcoy, potong2\", \"1 buah wortel, potong korek\", \"50 gr udang, buang kepala\", \"1 siung bawang putih, geprek\", \"1/2 siung bawang bombay, iris2\", \"1 sdm saos tiram\", \"Secukupnya air\", \"Secukupnya gula pasir & garam\", \"Sedikit minyak utk menumis\"]', '[\"Tumis duo bawang sampai layu & harum. Masukan udang, aduk-aduk.\", \"Jika udang sdh berubah warna, masukan potongan wortel, saos tiram & sedikit air.\", \"Masukan potongan pokcoy, gula pasir, garam & sedikit air. Aduk rata. Koreksi rasa.\", \"Setelah kuah mendidih, matikan api, angkat & sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1880, 2, 'Udang tepung oatmeal telor asin', 'Udang tepung oatmeal telor asin - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1/2 kg udang agak besar (buang kulit sisakan ekornya)\", \"3 siung bawang putih cincang halus\", \"3 siung bawang merah iris halus\", \"3 telor asin mateng yg merahnya aja\", \"1 telor ayam biasa kocok\", \"1 helai bawang daun\", \"secukupnya Jamur totole\", \"secukupnya Garam\", \"Merica\", \"Minyak goreng\", \"Bahan tepung :\", \"1 sachet tepung golden cryspy sasa (dibuat basah dan kering)\", \"1 sachet tepung sajiku (nanti dicampur dengan tepung sasa)\", \"1/4 tepung oatmeal utk lapisan kering\"]', '[\"Buat adonan basah dari campuran tepung sasa dan sajiku\", \"Sisakan tepung sasa dan sajiku dicampur jadi satu\", \"Masukkan udang yg sdh dikerat badannya dibuang kotorannya trua celup ke adonan tepung basah trus ke adonan tepung kering campuran sasa sajiku terus masukkan ke tepung oatmeal trus goreng trus setelah warnanya kekuningan dan matang.. angkat trus tiriskan\", \"Panaskan minyak utk menggoreng bawang putih dan bawang merah trus masukan telor kuning yg dilembutkan dan kocokan telor..masukkan udang yg sudah digoreng trus aduk rata trus kasih bumbu totole garam merica, aduk rata trus sebelum diangkat masukan irisan bawang daun.\", \"Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1881, 2, 'Tumis Pare dengan udang', 'Buat Tumis Pare dengan udang yang nikmat dengan langkah-langkah mudah ini.', '[\"Udang uk kecil\", \"2 buah Pare\", \"Daun salam\", \"Bumbu halus :\", \"Bawang merah\", \"Bawang putih\", \"Cabe rawit\"]', '[\"Goreng sebentar udang sampai berubah warna, tiriskan\", \"Setelah itu tumis bumbu halus dan daun salam sampai wangi.\", \"Setelah itu masukkan udang dan pare. Tambahkan sedikit aiir\", \"Jangan lupa garam dan gula juga penyedap sesuai selera. Lalu biarkan sampai mateng.\", \"Siap di sajikan ❤️\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1882, 2, 'Lempah Kuning Udang', 'Lempah Kuning Udang - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"250 gram udang\", \"1/4 buah nanas (ukuran kecil)\", \"1 jempol lengkuas geprek\", \"1/2 bungkus asam jawa, larutkan d air\", \"350 cc air\", \"secukupnya Garam, gula\", \"Bumbu halus\", \"3 buah cabai caplak\", \"2 buah cabai merah\", \"2 buah kemiri\", \"2 siung bawang putih\", \"3 siung bawang merah\", \"2 ruas jari kunyit\", \"1 sdm terasi (bakar lbh enak)\"]', '[\"Rebus air hingga mendidih, masukkan bumbu halus, dan lengkuas.\", \"Bila sudah mendidih tunggu hingga bau langu hilang.\", \"Tambahkan udang, tunggu hingga berubah warna dan hampir matang\", \"Masukkan nanas dan air asam. Tambahkan gula dan garam, cek rasa. Bila kurang asam bisa d tambahkan air asam.\", \"Sajikan hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1883, 2, 'Tumis udang kikil', 'Tumis udang kikil dengan udang segar dan bumbu khas.', '[\"1 bungkus udang (dari abangnya udah diplastikin)\", \"1 bungkus kikil\", \"3 buah Cabe ijo\", \"1/2  Tomat (aku pakai setengah tomat)\", \"Bawang bombay (bebas, mau setengah atau satu bongol tak apa)\", \"Cabe rawit & cabe merah (berapa aja bebas tergantung selera)\", \"3 siung Bawang putih\", \"4 siung  bawang merah\", \"Garam & penyedap rasa\", \"Saus sambal (bebas tergantung selera)\", \"Saus tomat (bebas tergantung selera)\", \"Daun salam, lengkuas & jahe (untuk rebus kikil agar tdk amis)\", \"Minyak goreng\", \"Saus tiram\", \"Kecap\", \"Air\"]', '[\"Potong2 kikil sesuai selera, cuci kikil dan udang hingga bersih dan rebus kikil dengan dan salam, lengkuas & jahe yg sudah digeprek (saya masukan udang nya juga agar dimasak tdk kelamaan\", \"Haluskan duo cabe & duo bawang.. Cabe hijau, bawang bombay dan tomat di potong2 saya\", \"Panas kan minyak, sudah panas, tumis bumbu halus sudah agak harus masukan cabe hijau, tomat dan bawang bombay\", \"Masukan garam, penyedap rasa (saya pakai masako) tambahkan saus sambal, saus tomat, kecap dan saus tiram secukupnya\", \"Sudah itu lalu masukan bahan utama kikil dan udang tambahkan air secukupnya agar tidak kering,\", \"Tunggu hingga airnya menyusut dan kental\", \"Dan langsung matang disajikan dengan nasi panas panas (maknyoss)🤗🤗\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1884, 3, 'Bubur udang asparagus saos madu', 'Resep Bubur udang asparagus saos madu ala rumahan yang dijamin menggugah selera.', '[\"250 gr Beras\", \"1 L Air\", \"20 ekor Udang kupas\", \"8 batang Asparagus potong 2-3 bagian\", \"1 buah Paprika merah (iris-iris memanjang)\", \"4 sdm Jagung manis pipil (siap pakai)\", \"2 sdm Butter\", \"5 siung bawang putih (cincang kasar)\", \"4-6 sdm madu (secukupnya)\", \"1 buah Jeruk nipis\", \"Garam (secukupnya)\", \"Lada hitam (secukupnya)\", \"Gula (secukupnya)\"]', '[\"Cuci beras. Masukkan dalam panci, tambahkan air lalu masak sekitar 40 menit sampai jadi bubur. (Jika air kurang bisa tambahkan air sedikit-sedikit). Setelah matang tambahkan garam dan lada hitam secukupnya, aduk rata. Tuang dalam mangkuk cukup besar.\", \"Panaskan butter 1 sdm dengan suhu kompor sedang, tumis bawang putih cincang kasar aduk-aduk saja jangan terlalu lama, masukkan udang lalu tumis peras irisan jeruk nipis kira-kira 2 potongan. Tambahkan madu, garam dan lada hitam secukupnya. Masak hingga saos agak kecoklatan dan udang matang. Lalu sisihkan di piring.\", \"Panaskan butter 1 sdm, masukkan asparagus dan paprika. Tumis. Lalu tambahkan jagung pipil siap pakai, tumis. Masukkan udang saos madu ke dalam pan lalu aduk rata. Icip-icip, kalau kurang gurih bisa tambahkan gula atau garam sedikit. Sesuai selera.\", \"Matikan kompor. Tuang tumisan diatas bubur. Sajikan selagi hangat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1885, 3, 'Udang Bakar Madu', 'Udang Bakar Madu dengan udang segar dan bumbu khas.', '[\"15 ekor udang,pilih yang besar\", \"1 sdm saos cabe\", \"1 sdm madu\", \"1 sdm kecap manis\", \"1 sdm saos tomat\", \"1 sdm saos tiram\", \"1 sdm margarin\", \"2 siung bawang putih haluskan\", \"Sedikit lada buBuk\", \"Sedikit kaldu buBuk\", \"1-2 iris jeruk nipis/ lemon\"]', '[\"Buang kepala udang,bersihkan kotoran,lalu kerat punggung,bersihkan.rendam diair yang sudah beri perasan jeruk nipis,cuci bersih kembali.Panaskan margarin,tumis bawang putih halus,masukan udang,kecilkan api agar bumbu tidak gosong.\", \"Masukan saos cabe,saos tiram,kecap manis,madu,saos tomat,tambahkan lada buBuk dan kaldu bubuk.\", \"Aduk2 terus besarkan api,masak sebentar saja sampai udang kecoklatan dan bumbu kental,jangan terlalu lama memasak udang agar daging udang tidak keras,lalu tusuk dengan tusuk sate.\", \"Bakar diatas pemanggangan\", \"Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1886, 2, 'Udang Rica Pedas', 'Sajian Udang Rica Pedas yang praktis dan lezat untuk dinikmati bersama.', '[\"500 gr pindang udang buang kepalanya\", \"Bumbu uleg kasar:\", \"10 siung bawang merah\", \"6 siung bawang putih\", \"6 buah cabai merah (skip)\", \"15 cabai rawit atau sesuai selera\", \"2 buah tomat ukuran sedang\", \"1 ruas jahe geprek (aku pakai 1/2 sdt jahe bubuk)\", \"Secukupnya garam\", \"Secukupnya gula\"]', '[\"Tumis bumbu dan jahe sampai harum. Masukkan udang. Tumis sampai berubah warna. Masukkan semua bahan. Kalau udang sudah berair, tidak perlu ditambah air. Masak sampai bumbu meresap.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1887, 3, 'Tumis Jamur Tiram Udang', 'Resep praktis Tumis Jamur Tiram Udang yang bisa dicoba di rumah.', '[\"2 genggam jamur tiram\", \"Beberapa ekor udang, bersihkan\", \"3 bawang putih\", \"2 bawang merah\", \"3 Cabe rawit\", \"1 Cabe merah\", \"Lada bubuk\", \"Kecap asin\", \"Saos tiram\", \"Garam\", \"Minyak wijen\"]', '[\"Cuci bersih smua bahan\", \"Suwir\\\" jamur\", \"Cincang bumbu (bawang+cabe)\", \"Tumis bumbu\", \"Masukan udang\", \"Kalo sdh matang udangnya masukan jamur dan beri sedikit air\", \"Tambahan lada, garam, kecap asin, saos tiram dan minyak wijen\", \"Tes rasa\", \"Siap dinikmati\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1888, 3, 'Sambal Goreng Kentang Udang', 'Resep praktis Sambal Goreng Kentang Udang yang bisa dicoba di rumah.', '[\"5 siung bawang merah\", \"3 siung bawang putih\", \"5 Cabai merah\", \"Cabai rawit 2 (sesuai selera)\", \"1/2 Tomat\", \"1 ruas jari lengkuas\", \"1/2 Terasi udang\", \"5 buah kentang\", \"1/4 Udang\", \"Gula\", \"Garam\", \"3 lembar daun jeruk\"]', '[\"Bawang merah, bawang putih, tomat, lengkuas, cabai, tomat, terasi dihaluskan/ diblender\", \"Bersihkan udang, lalu di goreng\", \"Potong kentang setelah dibersihkan, lalu di goreng hingga matang\", \"Tumis bumbu halus, tambahkan garam dan gula. Jika aroma sudah wangi masukkan udang dan kentang yang sudah digoreng. Aduk sampai merata\", \"Tambahkan daun jeruk saat di tumis\", \"Cicipi rasa, setelah agak kering dan teraduk. Angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1889, 2, 'Udang Bakar Madu 🍤', 'Udang Bakar Madu 🍤 dengan udang segar dan bumbu khas.', '[\"🍤 Bahan Utama:\", \"8 ekor Udang ukuran besar\", \"🍤 Bumbu Marinasi:\", \"1 sdm Air jeruk nipis\", \"4 siung Bawang putih\", \"3 siung Bawang merah (saya pakai bawang bombay, karena di sini ga ada)\", \"1 sdm Ketumbar bubuk\", \"3 butir Kemiri (sangray)\", \"1/4 sdm Kunyit bubuk\", \"secukupnya Gula\", \"secukupnya Garam\", \"8 buah Tusuk sate\", \"🍤 Bumbu oles:\", \"secukupnya Madu\", \"secukupnya Kecap manis\", \"secukupnya Margarin/ Mentega tawar\"]', '[\"Bersihkan dan buang kotoran udang. Cangkangnya (skeleton) tidak ikut dibuang ya!\", \"Berikan air jeruk nipis. Diamkan 5 menit dan cuci kembali udang.\", \"Haluskan duo bawang dan kemiri yang telah disangrai sebelumnya. Tambahkan ketumbar, gula, dan garam secukupnya.\", \"Tusuk udang dari arah ekor ke kepala, dan lumuri dengan bumbu marinasi. Simpan dalam kulkas selama kurang lebih 4-6 jam (minimal 1 jam ya, biar meresep dulu bumbunya. Lebih oke lagi kalau lama 😋)\", \"Keluarkan udang dari kulkas. Olesi udang dengan campuran madu, kecap, dan margarin.\", \"Panggang sate udang dengan api sedang.\", \"Angkat dan hidangkan udang bakar madu 😋😋😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1890, 2, 'Udang sambal pete', 'Udang sambal pete dengan udang segar dan bumbu khas.', '[\"0,5 kg udang\", \"0,5 ons cabe kering\", \"2 buah bawang merah\", \"1 buah bawang putih\", \"2 papan pete\", \"secukupnya garam dan penyedap\", \"minyak goreng secukupnya utk menumis\"]', '[\"Rebus cabe kering dan duo bawang hingga lunak\", \"Cuci bersih udang, saya hanya buang kepalanya saja krn suami suka udang yg masi ada kulitnya\", \"Blender cabe+bawang lalu tumis sebentar\", \"Masukkan pete,aduk hingga pete berubah warna\", \"Masukkan udang,aduk2 lagi hingga udang matang lalu tambah garam dan penyedap rasa...it\'s so simple but delicious\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1891, 3, 'Udang', 'Resep praktis Udang yang bisa dicoba di rumah.', '[\"1/2 kg Udang\", \"Minya goreng\", \"Daun bawang (banyakin juga oke)\", \"10 siung Bawang putih\", \"sesuai selera Cabai2an\", \"Merica\", \"dikit Jahe\"]', '[\"Cuci kupas udang, goreng setengah matang.\", \"Iris semua bahan.\", \"Tumis bahan sampai harum.\", \"Masukkan udang.\", \"Jadi deh.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1892, 3, 'Kwetiaw Udang', 'Hidangan seafood nikmat: Kwetiaw Udang untuk pecinta udang.', '[\"200-300 gr kwetiau basah\", \"6 udang kupas kulit\", \"Wortel potong korek api\", \"1 batang daun bawang iris\", \"1 butir telor\", \"1 sdm kecap manis\", \"secukupnya Garam\", \"secukupnya Merica\", \"2 sdm minyak goreng\", \"2 sdm air\", \"Bumbu :\", \"1 bawang merah cincang\", \"1 bawang putih cincang\"]', '[\"Panaskan minyak dgn api sedang dan Tumis bawang merah dan putih\", \"Masukan telor, aduk2, masukan wortel dan udang, masak sampai udang berubah warna.\", \"Masukan kwetiau, daun bawang, kecap manis, garam, merica, air. Aduk rata\", \"Masak sampai kwetiau matang dan sajikan bersama acar timun\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(1893, 3, 'Tahu Udang Tauco', 'Nikmati kelezatan Tahu Udang Tauco dengan resep sederhana ini.', '[\"500 gr udang, kupas sisakan ekornya, cuci bersih\", \"400 gr tahu putih, potong kotak, goreng 1/2 matang\", \"Bumbu Halus :\", \"3 buah bawang merah\", \"2 buah bawang putih\", \"2 buah kemiri\", \"Bahan lainnya :\", \"4 sdm tauco\", \"2 sdm kecap manis\", \"secukupnya Garam\", \"200 ml air\"]', '[\"Tumis bumbu halus hingga harum dan bewarna agak kecoklatan. Masukkan udang dan tahu serta tauco. Aduk rata. Masukkan air dan kecap manis. Aduk rata. Test rasa dulu. Kalau kurang asin tambahkan garam. Bisa tambahkan kaldu bubuk jika mau. Masak hingga air agak menyusut. Sesuai selera saja mau kental atau agak berkuah. Air bisa diganti sebagian dengan santan jika mau terasa gurih. Bisa tambahkan tempe, ayam atau sayuran seperti wortel.\", \"Ini tauco yang kupakai. Tauco manis. Jadi aku pakao garam sedikit\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1894, 2, 'Udang goreng mentega simple', 'Udang goreng mentega simple dengan udang segar dan bumbu khas.', '[\"1/4 udang buang kepalanya\", \"1 bh jeruk nipis\", \"1 bh bawang bombay iiris\", \"2 bh bawang putih geprek iris\\\"\", \"Secukupnya kecap asin\", \"Secukupnya kecap manis\", \"3 sendok margarin\"]', '[\"Goreng udang dg mentega sebentar jangan terlalu matang angkat tiriskan\", \"Masukkan lagi mentega untuk menumis bawang putih dan bawang bombai tunggu sampai harum\", \"Masukkan kembali udang,kecap asin dan kecap manis\", \"Test rasa jika kurang sedap bisa di tambah penyedap sedikit\", \"Aduk\\\" angkat.sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1895, 2, 'Ca buncis brokoli udang wortel', 'Resep Ca buncis brokoli udang wortel yang lezat dan mudah dibuat di rumah.', '[\"1/4 kg buncis\", \"2 buah wortel\", \"1 buah brokoli kecil\", \"1/4 udang sedang\", \"2 siung bawang putih\", \"1 siung bawang bombai kecil\", \"1 tangkai daun bawang\", \"1/4 sendok teh merica bubuk\", \"Minyak secukupnya untuk menumis\", \"1/2 sendok teh gula putih\"]', '[\"Panaskan minyak tumis bawang putih sampai berubah warna masukan bawang bombai sampai harum\", \"Masukan semua sayur yg telah dipotong sesuai selera\", \"Masukan garam merica dan gula putih\", \"Sambil sembari d aduk sampai matang angkat.sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1896, 3, 'Udang saus inggris', 'Resep Udang saus inggris yang lezat dan mudah dibuat di rumah.', '[\"500 gr udang cuci kepalanya\", \"2 siung bawang putih\", \"1 buah bawang bombay\", \"1 jeruk limau\", \"Gula\", \"Garam\", \"Merica secukupnyaa\", \"Bahan sausya\", \"1 sdm kecap asin\", \"1/2 sdm saus tomat\", \"1 sdm saus tiram\", \"2 sdm saus inggris\", \"2 sdm kecap manis\"]', '[\"Cuci udang terlebih dahulu,lalu kasih perasan jeruk limau,taburi garam sedikit\", \"Lalu tumis udang sebentar saja lalu angkat dan tiriskan,sisihkan\", \"Lalu timis bawang putih dan bawang bombay, tambahkan bahan saus td\", \"Masukan udang kedalam tumisan saus,campurkan sampai rata lalu tambahkan air sedikit. Tambahkan gula dan garam.\", \"Tes rasaa,bisarkan sampai saus mengentall lalu angakat dan hidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1897, 4, 'Udang saus tiram', 'Cara membuat Udang saus tiram yang enak dan praktis untuk keluarga.', '[\"1/2 udang kupas\", \"5 bawang merah\", \"3 bawang putih\", \"3 buah cabe besar\", \"5 buah cabe rawit merah\", \"3 sendok saus tiram\"]', '[\"Iris semua bumbu cabe dan bawang\", \"Panaskan minyak dan tumis hingga harum\", \"Masukan udang dan tunggu hingga matang jangan lupa masukan saus tiram dan garam\", \"Tunggu hingga matang dan siap dihidangkan, oh ya paling enak makan dengan nasi hangat,selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1898, 2, 'Perkedel Tahu Udang', 'Resep Perkedel Tahu Udang yang lezat dan mudah dibuat di rumah.', '[\"1 buah tahu cina besar\", \"Secukupnya udang cincang kasar/potong kecil2\", \"1 sdm maizena/ tepung serbaguna\", \"Secukupnya garam\", \"Secukupnya lada\", \"1 buah daun bawang diiris halus\", \"1 butir telur\", \"Secukupnya tepung panir/tepung bumbu untuk melapisi (skip juga bisa)\", \"2 siung bawang putih haluskan\"]', '[\"Hancurkan tahu dengan tangan, masukan garam,lada,telur,tepung maizena, irisan daun bawang, bawang putih dan udang aduk2 hingga merata.\", \"Bentuk bulat2 gulingkan diatas tepung panir.\", \"Panaskan minyak lalu goreng hingga kecoklatan. Selesai.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1899, 2, 'Sup oyong udang', 'Resep Sup oyong udang ala rumahan yang dijamin menggugah selera.', '[\"1/4 udang\", \"2 buah oyong\", \"1 bungkus soun/ misoa\", \"1 batang seledri\", \"1/2 belah tomat(buang biji)\", \"1/4 sdt lada bubuk\", \"1 siung bawang putih, cincang halus\", \"secukupnya Gula, garam dab kaldu bubuk\", \"1 ruas jahe\"]', '[\"Pisahkan kepala udang dan kulitnya, lalu cuci bersih Didihkan air secukupnya masukan kepala dan kulit udang. Untuk air kaldunya. Setelah siap. Saring kulit dan kepala. Kita ambil air kaldunya.\", \"Siapkan air kaldu yg tadi kita buat, masukan jahe, masukan udang(jangan lupa kerat bagian atasnya ya dan buang kotorannya).\", \"Tumis bawang putih hingga kuning dan harum, langsung masukan dalam rebusan udang.\", \"Jika sudah mendidih, masukan oyong beri bumbu garam, gula, kaldu bubuk lada bubuk. Tes rasa.\", \"Masukan soun atau misoa.\", \"Terakhir masuka tomat dan seledri. Jika sudah ok. Angkat dan sajikan hangat...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1900, 4, 'Balado kentang+udang', 'Balado kentang+udang dengan udang segar dan bumbu khas.', '[\"1 kg Kentang Dieng\", \"1/2 kg Udang sedang\", \"1/4 kg Cabe kriting merah dan rawit merah\", \"8 siung Bawang merah\", \"1 buah Tomat\", \"secukupnya Garam\", \"1 sdm Gula\", \"1 bungkus Royco ayam\"]', '[\"Blender cabe kriting merah, cabe rawit merah, tomat, dan bawang merah dengan sedikit minyak goreng, agar mudah dihaluskan\", \"Setelah halus, panaskan minyak goreng, lalu tumis bumbu yang sudah di blender\", \"Setelah agak matang, masukkan gula putih, garam, dan royco ayam, aduk rata, sisihkan (bumbu masih setengah matang)\", \"Goreng udang dan kentang yang sudah di potong sesuai selera\", \"Matangkan kembali bumbu balado yang masih setengah matang tadi dengan api kecil, setelah bumbu matang sempurna, masukkan udang dan kentang yang sudah di goreng\", \"Aduk rata, dan siap dihidangkan.. Sambal balado ini tahan hingga 3 hari (sambalnya saja ya😊)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1901, 3, 'Udang macaroni', 'Cara membuat Udang macaroni yang enak dan praktis untuk keluarga.', '[\"6 ekor udang\", \"secukupnya Brokoli\", \"1 gengam macaroni\", \"100 ml susu uht\", \"Garam\", \"Kaldu ayam non msg\", \"Bawang bombai rajang halus\", \"Bawang putih rajang halus\"]', '[\"1. Rebus macaroni, beri olive oil secukupnya agar enggak lengket\", \"2. Tumis bawang bombai, bawang putih, masukan udang, brokoli aduk hingga mateng, masukan susu uht, garam, kaldu ayam non msg, aduk hingga mengental, masukan macaroni aduk rata\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1902, 3, 'Udang goreng pedas gurih', 'Resep praktis Udang goreng pedas gurih yang bisa dicoba di rumah.', '[\"1/4 udang segar\", \"1 buah tomat\", \"5 buah cabe merah\", \"10 buah cabe rawit\", \"5 butir bawang merah\", \"1 royco\", \"1 sdt penyedap rasa\", \"secukupnya Minyak goreng,\"]', '[\"Cuci bersih udang,tomat, cabe, rawit,bawang\", \"Iris cabe, bawang, tomat, rawit,sesuai selera\", \"Tumis bawang sampai wangi, masukan cabe,tomat, yang sudah di iris, tumis sebentar masukan udang yg sudah di cuci\", \"Tambahkan royko, penyedap sesuai selera\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1903, 2, 'Tumis kangkung udang terasi pedas', 'Resep Tumis kangkung udang terasi pedas ala rumahan yang dijamin menggugah selera.', '[\"1 ikat kangkung (potong2)\", \"1/4 udang (bersihkan kupas kulitnya)\", \"1 sachet terasi bca\", \"2 siung bawang putih\", \"3 siung bawang merah\", \"1/4 butir bawang bombai\", \"7 buah cabe rawit\", \"3 buah cabe merah besar\", \"1 lembar daun salam\", \"secukupnya Garam\", \"secukupnya Gula pasir\", \"Minyak untuk menumis\", \"secukupnya Air\", \"Saori\"]', '[\"Bumbu halus : haluskan cabai rawit, bawang putih dan terasi. Sisihkan\", \"Iris bawang bombay, bawang putih dan cabai merah besar. Sisihkan\", \"Siapkan minyak untuk menumis.\", \"Setelah panas masukkan bawang bombai, tumis sebentar lalu tambahkan bawang merah dan cabai merah besar. Tumis sebentar.\", \"Kemudian tumis bumbu halus dan daun salam hingga harum. Setelah itu tambahkan air sedikit.\", \"Tunggu hingga mendidih lalu masukkan udang yang sudah dibersihkan. Tunggu hingga udang matang (berubah warna dan menciut)\", \"Selanjutnya masukkan kangkung. Aduk2 sambil tambahkan saori, garam dan gula pasir\", \"Tes rasa. Jika dirasa sudah pas matikan api. Tumis kangkung udang terasi pedas ready to serve\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1904, 3, 'Tumis Udang dan Tahu', 'Tumis Udang dan Tahu dengan udang segar dan bumbu khas.', '[\"250 gr udang uk sedang, buang kepala\", \"4 buah tahu cina potong dadu, goreng smpe berkulit\", \"1/4 buah wortel, potong korek api\", \"1/2 biji bawang bombay, iris memanjang\", \"3 siung bawang putih\", \"4 siung bawang merah\", \"1 ruas jahe, geprek\", \"7 buah cabe rawit setan, potong serong (bs ditmbh sesuai slera)\", \"1 batang bawang daun, potong tebal\", \"2 sdt kecap bango\", \"1 sdt saos tomat\", \"3 sdt saos tiram\", \"secukupnya garam dan air\"]', '[\"Tumis bawang bombay dg 2 sdm minyak goreng, hingga harum, masukkan bawang merah, bawang putih, rawit, wortel dan jahe, aduk rata hingga harum.\", \"Masukkan tahu dan udang aduk rata hingga berubah warna, beri air hingga sdikit merendam udang n tahu\", \"Bumbui dg saos tiram, saos tomat, kecap dan garam. Biarkan air mendidih, menyusut dan mulai mengental, koreksi rasa, masukkan bawang daun, aduk2 sbentar, matikan api, sajikan...yummy😄\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1905, 3, 'Tumis Udang Pete n Daun Putut', 'Cara membuat Tumis Udang Pete n Daun Putut yang enak dan praktis untuk keluarga.', '[\"1/4 kg udang yg udh dibersihkan\", \"5 buah daun putut iris serong\", \"2 papan pete diiris / sesuai selera\", \"3 lembar daun salam\", \"1 tempe semanggit\", \"1 mangkuk kecil irisan cabe rawit hijau n merah\", \"1 ruas lengkuas\", \"3 siung bawang merah\", \"2 siung bawang putih\", \"1 sdt garam himalayan/ grm biasa\", \"1/2 sdt kaldu jamur totole\", \"1 sdt kecap manis\", \"sedikit gula tropicana / gula jawa\", \"1/2 gelas kecil air putih\"]', '[\"Iris iris bawang putih bawang merah n cuci, stlh itu tumis dengan sedikit minyak, stlh layu masukan daun salam, lengkuas yg sudah digeprek, tempe semanggit, aduk rata sebentar kemudian msukan udang aduk2 hingga ke orange an, stlh itu masukan garam, kaldu jamur, gula n kecap\", \"Setelah udang layu masukan cabe n pete, aduk sebentar kemudian masukan yg terakhir daun putut, aduk2 lg sebentar kemudian masukan sedikit air, aduk n tunggu hingga agak menyusut matikan api dan selamat menikmati semoga bermaanfaat :) aamiin\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1906, 4, 'Udang crispy', 'Udang crispy - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 kg udang\", \"1 sendok jeruk nipis\", \"Tepung serba guna\", \"Minyak\"]', '[\"Cuci bersih udangnya. Buang kulit dan kepalanya. Setelah di cuci bersih. Lumuri dengan 1 sendok jeruk nipis. Diamkan selama 5menit di dalam kulkas biar meresap\", \"Siapakna 2 adonan tepung serba guna\", \"Mangkuk pertama 5 sendok tepung serba guba tambhkan air jgn terlalu kental. Mangkuk yang ke 2 siapkan buat yang kering\", \"Ambil udang yg di dlm kulkas. Lumuri ke tepung basah lalu ke tepung kering jgn lupa di remas remas biar menyatu smua\", \"Siapkan minyak panas... dengan api sedang. Goreng sampai berwarna kecoklatan...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1907, 4, 'Udang Tumis cabai hijau', 'Sajian Udang Tumis cabai hijau yang praktis dan lezat untuk dinikmati bersama.', '[\"Udang 1 kg buang ujung kepala\", \"Bumbu bumbu\", \"10 siung bawang merah (iris)\", \"4 siung bawang putih (iris)\", \"10 buah cabai rawit (iris serong)\", \"7 buah cabai merah kriting (iris serong)\", \"7 buah cabai hijau besar (iris serong)\", \"1 buah tomat merah (iris dadu besar)\", \"4 buah tomat hijau (belah menjadi 4)\", \"Garam (secukupnya)\", \"Totole (penyedap jamur)\", \"1 sdt Lada\"]', '[\"Cuci udang bersih, dan belah tengah udang, kemudian buang tali hitam yg ada ditengah badan udang, kemudian bumbui dengan garam, lada, dan totole secukupnya,, goreng hingga matang angkat, dan tiriskan\", \"Kemudia, ganti dengan minyak bersih, tumis bawang merah dan putih hingga harum, dan agak sedikit menguning, kemudian masukkan semua cabai dan tomat, kemudian udang, aduk2 koreksi rasa, jika kurang gurih boleh tambahkan garam dan penyedap rasa\", \"Untuk penyedap rasa boleh diganti dengan apapun, sesuai selera, tapi kalo saya memakai totole (penyedap dr jamur),\", \"Koreksi rasa dan matikan kompor,,, SELAMAT MENCOBAA🙏🏻🙏🏻🙏🏻 simple mudah dan rasanya pun enak\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1908, 4, 'Tumis buncis udang pedas simpel', 'Resep praktis Tumis buncis udang pedas simpel yang bisa dicoba di rumah.', '[\"1 ikat buncis\", \"1/4 kg udang (optional)\", \"Bumbu:\", \"7 bh bawang merah\", \"4 bh bawang putih\", \"10 bh cabe rawit(optional)\", \"1 ruas laos(geprek)\", \"2 bh daun salam\", \"1 sdt saos rasa\", \"Garam,gula,penyedap (secukupnya)\", \"secukupnya Air\"]', '[\"Potong\\\"buncis sesuai selera,,\", \"Cuci udang lepas kulity buang kepala\", \"Iris\\\" bawang merput,cabe sisihkan\", \"Tumis semua bahan bumbu yg sdh di iris hingga harum masukkan laos,daun salam\", \"Masukkan udang aduk rata sampai udang berubah warna ke kuningan\", \"Kemudian masukkan buncis aduk rata,,tambahkan air\", \"Tambahkan saos rasa,penyedap,garam,gula aduk \\\" rata\", \"Tunggu sampai masak\", \"Tes rasa\", \"Siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1909, 2, 'Udang simpel', 'Resep praktis Udang simpel yang bisa dicoba di rumah.', '[\"250 gr udang (buang kepala)\", \"3 bawang putih (digeprek)\", \"secukupnya garam\", \"secukupnya tumbar bubuk\", \"secukupnya minyak\"]', '[\"Udang dicuci bersih.\", \"Siapkan wajan, beri sedikit minyak. Tumis bawang putih hingga harum, lalu masukkan udangn\", \"Dioseng sebentar. Tambahkan garam dan tumbar bubuk.\", \"Oseng sebentar, tunggu hingga air tinggal sedikit.\", \"Udang siap disajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1910, 4, 'Udang Saos padang', 'Resep Udang Saos padang ala rumahan yang dijamin menggugah selera.', '[\"500 gr udang buang kepalanya\", \"1 buah telor ayam kocok lepas\", \"1 buah bawang bombay\", \"3 sdm saos sambal\", \"2 sdm saos tiram\", \"2 sdm saos tomat\", \"Daun bawang\", \"Kaldu bubuk\", \"secukupnya Gula pasir\", \"2 gelas air\", \"✨bumbu halus\", \"1 ons cabe keriting\", \"2 buah cabe merah besar\", \"5 siung bawang merah\", \"2 siung bawang putih\"]', '[\"Cuci bersih udang beri perasan jeruk nipis diamkan 5 menit lalu bilas lagi. Goreng sebentar\", \"Tumis bumbu halus smp harum lalu bawang bombay masukan semua saus lalu udang aduk rata lalu masukan air tunggu sampai mendidih\", \"Masukan kaldu bubuk dan gula tes rasa bila sudah pas tunggu smpai air agak susut masukan kocokan telur aduk rata lagi\", \"Terakhir masukan daun bawang jika sudah surut kuah nya angkat sajikann.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1911, 4, 'Udang Balado', 'Sajian Udang Balado yang praktis dan lezat untuk dinikmati bersama.', '[\"1/4 kg udang\", \"2 buah kentang uk.besar, potong dadu\", \"1 ons cabe giling segar\", \"2 siung bawang merah, iris tipis\", \"1/2 buah tomat, belah memanjang\", \"1 buah jeruk nipis, ambil airnya :\", \"Sebagian untuk rendaman udang, sebagian untuk balado\", \"Secukupnya garam\", \"Secukupnya minyak goreng\"]', '[\"Siapkan bahan. Cuci bersih udang beri garam dan jeruk nipis diamkan sebentar.\", \"Goreng udang sampai berubah warna dan matang. Sisihkan minyaknya\", \"Goreng kentang sampai matang\", \"Dengan minyak bekas menggoreng udang, masukkan bawang merah iris, tomat, cabe giling, dan air jeruk nipis\", \"Masak sampe cabe matang, matikan api.\", \"Masukkan udang dan kentang, aduk sebentar sampai cabe meresap. Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1912, 3, 'Udang pete saus kecap', 'Udang pete saus kecap - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"12 udang ukuran besar (buang kepala dan kulitnya)\", \"3 ruas pete(kupas)(pilih pete yg bagus2 yaa😁)\", \"1 bawang bombay(potong2)\", \"6 bawang putih(cincang halus)\", \"Kecap manis\", \"Kecap asin\", \"Saus tiram\", \"Garam\", \"Gula pasir\", \"Lada putih\", \"Tepung maizena\", \"Air putih\", \"Margarin/minyak goreng untuk menumis\"]', '[\"Cuci bersih udang buang kepala dan kulitnya. Sisihkan.. dan cuci bawang putih bawang bombay dan pete.\", \"Cincang /ulek bawang putih. Potong2 bawang bombay. Siapkan gelas dengan1/2 air putih. Tmbhkn tepung maizena sedikit saja. Sisihkan..\", \"Panaskan margarine/minyak goreng sedikit saja. Tumis bawang putih smpe harum. Lalu tambhkan bawang bombay yg sdh di potong2. Tambhkan air yg sdh trcampung dengan tepung maizena. Aduk2 smpe mengentall..\", \"Tambahkan kecap manis,kecap asin,saus tiram, next.. garam, gula pasir, lada aduk2 smpe rata dan mengentall..\", \"Lallu tambhkan udang yg sdh di kupass td. Aduk trus smpe air agak menyusut. Terakhir.. tambhkan pete.. aduk lagi smpe air bener2 menyusut dan sangat kental. Lallu tess rasa yaa..😊 jika rasa sdh pass. Angkat dan sajikann👍😋slamt mencoba smoga sukaa👍😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1913, 4, 'Balado Udang Pete', 'Resep Balado Udang Pete ala rumahan yang dijamin menggugah selera.', '[\"1/4 Udang\", \"2 papan Pete\", \"15 Cabe merah\", \"12 Cabe rawit\", \"4 Bawang merah\", \"2 Bawang putih\", \"1 Tomat kecil\", \"1 Daun pre\", \"secukupnya Minyak\", \"secukupnya Garam\", \"secukupnya Penyedap\"]', '[\"Kupas udang, cuci bersih. Goreng.\", \"Pupili pete. Cuci. Iris kasar daun pre, cuci.\", \"Haluskan cabe merah, cabe rawit, bawang merah, bawang putih, lalu tumis dengan minyak secukupnya. Iris tomat ke dalamnya.\", \"Setelah matang tambahkan pete aduk2, masukkan udang. Cek rasa dgn menambah garam dn penyedap.\", \"Taburi daun pre. Aduk rata\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1914, 2, 'Udang Saus Mentega', 'Udang Saus Mentega - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"500 gr pindang udang, buang kepalanya\", \"6 siung bawang putih cincang halus\", \"4 sdm margarin\", \"1/2 sdt merica bubuk\", \"Secukupnya garam\", \"Secukupnya gula\", \"2 sdm kecap manis\", \"Secukupnya kaldu bubuk\"]', '[\"Tumis bawang putih dengan margarin sampai harum. Masukkan udang, tumis hingga berubah warna. Masukkan bumbu lainnya. Masak hingga bumbu meresap. Angkat dan sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1915, 4, 'Udang saus tiram (menu balita 28bulan)', 'Resep Udang saus tiram (menu balita 28bulan) ala rumahan yang dijamin menggugah selera.', '[\"1 genggam udang kupas\", \"1 buah sosis potong kecil2\", \"1 buah wortel potong kecil2\", \"1 ikat daun bawang muda\", \"1 buah bawang bombay\", \"4 siung bawang putih\", \"2 siung bawang merah\", \"1 sdm minyak wijen\", \"2 sdm kecap manis\", \"2 sdm saus tiram\", \"secukupnya garam\", \"secukupnya lada bubuk\", \"sedikit larutan maizena\"]', '[\"Tumis bawang bombay, bawang putih dan bawang merah sampai harum\", \"Masukkan udang dan sosis\", \"Masukkan wortel\", \"Masukkan saus tiram, minyak wijen, garam dan lada\", \"Masukkan daun bawang\", \"Masukkan kecap. masukkna sedikit larutan tepung kanji/maizena untuk mengentalkan sedikit\", \"Aduk rata. cicipi. siap dimakan dengan nasi hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1916, 4, 'Udang Saos Tiram', 'Sajian Udang Saos Tiram yang praktis dan lezat untuk dinikmati bersama.', '[\"250 gr udang, belah punggung\", \"1/2 buah wortel, potong korek\", \"1 batang daun bawang, iris serong\", \"3 siung bawang putih, cincang halus\", \"4 buah cabe merah, iris serong\", \"1 bungkus saori saos tiram\", \"1 sdm kecap manis\", \"Secukupnya merica bubuk\", \"Secukupnya air\"]', '[\"Tumis bawang putih, setelah wangi masukkan cabe merah, daun bawang, dan wortel.\", \"Setelah itu masukkan udang, aduk2 hingga udang berubah warna.\", \"Lalu masukkan air, saos tiram, kecap manis, dan merica bubuk.\", \"Aduk-aduk hingga matang.\", \"Tes rasa, sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1917, 3, 'Sosis Udang', 'Resep Sosis Udang yang lezat dan mudah dibuat di rumah.', '[\"250 gr udang kupas\", \"200 gr tepung terigu\", \"200 gr tepung sagu\", \"1 gelas air\", \"2 butir telur\", \"4 butir bawang putih\", \"Secukupnya garam, merica bubuk, gula\"]', '[\"Blender bawang, udang, air, telur, merica, garam dan gula.. setelah halus campurkan dgn tepung terigu dan tepung sagu aduk rata.. cetak dgn cara memasukan pada plastik es dan ikat.. kemudian rebus hingga matang.. angkat tiriskan..\", \"Penyajian bs di goreng dengan telur atau lgsg di goreng jg bs.. di cocol di sambel kecap / saus sambal tambah enak... 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1918, 3, 'Nasi goreng udang pete', 'Nasi goreng udang pete - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 piring nasi putih\", \"3 siung bawang merah\", \"2 siung bawang putih\", \"5 buah cabe rawit\", \"5 buah cabe merah\", \"sesuai selera pete\", \"sesuai selera udang\", \"minyak goreng secukupny\", \"garam\"]', '[\"Haluskan bumbu tumis hingga harum masukan udang pete telur orak arik masukan garam masukan nasi terakhir kecap. setelah matang siap di sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1919, 3, 'Siomay Udang Sambal Kecap', 'Resep Siomay Udang Sambal Kecap ala rumahan yang dijamin menggugah selera.', '[\"Bahan siomay:\", \"1/4 kg udang kupas\", \"1 buah wortel sedang, serut\", \"5 sdm tepung terigu\", \"5 sdm tepung kanji (sesuai selera)\", \"1 siung bawang putih sedang\", \"10 btr Merica\", \"Garam sckp\", \"1 jumput Kaldu\", \"1 sdm minyak goreng\", \"Bahan sambal:\", \"3 sdm Kecap\", \"2 buah cabai rawit\", \"1 cm bawang geprek\"]', '[\"Haluskan bawang, garam, merica.\", \"Lumatkankan udang, campur dg wortel, bumbu halus, kaldu, minyak, tepung, dan air secukupnya. Campur hingga merata\", \"Cetak adonan/ bulatkan, lalu rebus dalam air mendidih.\", \"Tiriskan siomay setengah matang, lalu kukus hingga kecoklatan.\", \"Sajikan bersama sambal selera anda..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1920, 4, 'Udang Goreng Crispy', 'Hidangan seafood nikmat: Udang Goreng Crispy untuk pecinta udang.', '[\"1/2 kg udang cabut kepala\", \"Bumbu rendaman:\", \"Garam\", \"Kecap ikan\", \"Saos tiram\", \"Baluran tepung:\", \"3 sendok makan Tepung maizena\", \"Garam\", \"Merica\", \"Bubuk bawang putih(pilihan,skip kalo ga ada)\"]', '[\"Rendam udang dengan bumbu rendaman.kurang lebih 1 jam.\", \"Buat tepung utk baluran udang.campur rata semuanya.\", \"Masukkan udang yg sudah direndam tadi,tiriskan terlebih dahulu.balur dengan tepung baluran tadi sampai rata.\", \"Panaskan minyak goreng.masukkan pada saat minyak panas,goreng sebentar saja.tidak perlu lama2 asal tepung baluran kelihatan crispy.angkat,tiriskan minyaknya.siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1921, 2, 'Udang telur asin', 'Resep praktis Udang telur asin yang bisa dicoba di rumah.', '[\"🍤 bahan utama🍤\", \"15 ekor udang ukuran sedang\", \"3-4 butir telur asin (ambil kuningnya saja)\", \"1 putih telur\", \"🍤 bumbu iris🍤\", \"3 siung bawang putih (iris kecil2)\", \"3 siung bawang merah (iris kecil2)\", \"1 buah cabe merah keriting (iris kecil2)\", \"1 buah cabe rawit setan (iris kecil2)\", \"2 batang daun bawang (iris halus)\", \"🍤bumbu tepung🍤\", \"5 sdm tepung terigu\", \"1 sdm tepung maizena\", \"🍤 bahan lainnya🍤\", \"Margarine n minyak utk menumis n menggoreng\", \"Secukupnya garam, gula pasir, lada\"]', '[\"Kupas bagian kepala udang. Belah sedikit punggung udang kmd cabut spt benang hitam yg ada di punggungnya.. cuci bersih. Rendam udang dlm putih telur kmd beri adonan tepung\", \"Baluri udang dg tepung hingga rata\", \"Goreng udang hingga golden brown. Sisihkan\", \"Hancurkan kuning telur asin dg garpu sampai halus. Kmd tambahkan sedikit air matang shg menjadi seperti bubur. Jgn terlalu encer jg ya\", \"Panaskan 1 sdm margarine n 1 sdm minyak goreng, tumis bawang putih n bawang merah, plus duo cabe (oh iy klo mau pedes, bole ditambah ya mom). Tambahkan sedikit air bila terlalu kering.\", \"Masukkan adonan telur asin kemudian tambahkan daun bawang\", \"Masukkan udang yg telah digoreng tadi...masukkan garam bila dirasa kurang asin, lada maupun gula pasir...aduk rata\", \"Yummmiiiii...comot satu aaah...😄..\", \"Kalau di resto..sepiring imut mihil bgt..ini bisa puaaassss..\", \"Nyuuum...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1922, 2, 'Misoa udang (batita)', 'Misoa udang (batita) dengan udang segar dan bumbu khas.', '[\"4 ekor udang basah\", \"2 keping miso potong dua\", \"3 gelas kaldu udang\", \"3 siung bawang putih\", \"2 siung bawang merah\", \"1/2 tomat\", \"1 sdt kecap asin\", \"1 sdt kecap manis\", \"secukupnya Garam\", \"2 sdm minyak untuk menumis\", \"1 bh wortel parut\", \"1/2 genggam toge\", \"Kaldu udang dari kepala udang basah direbus dan disaring\"]', '[\"Tumis bawang merah, bawang putih dan tomat kemudian masukkan kaldu udang\", \"Kemudian masukkan wortel dan toge serta kecap asin dan manis dan juga udang basah\", \"Setelah mendidih masukkan misoa dan garam koreksi rasa tunggu sampai sedikit kering angkat dan hidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1923, 4, 'Tom Yam Udang + Sayur', 'Cara membuat Tom Yam Udang + Sayur yang enak dan praktis untuk keluarga.', '[\"250 gr udang\", \"6 buah jagung muda\", \"2 buah wortel\", \"4 lembar daun jeruk\", \"5 buah asam potong\", \"15 buah cabe rawit\", \"2 batang serai, geprek\", \"1 ruas jahe, geprek\", \"1 ruas lengkuas, geprek\", \"Bumbu yang dihaluskan :\", \"8 siung bawang merah\", \"3 siung bawang putih\", \"12 buah cabai merah\", \"10 buah cabai rawit merah\", \"secukupnya Garam\", \"secukupnya Gula\"]', '[\"Panaskan minyak, tumis semua bumbu halus tambahkan cabai rawit, jahe, serai, lengkuas, dan daun jeruk tumis hingga harum. Masukkan air dan asam potong, didihkan.\", \"Kemudian masukkan wortel, jagung muda, dan udang, didihkan. Tambahkan garam, gula, dan penyedap secukupnya.\", \"Test rasa, hidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1924, 2, 'Udang baso ikan praktis pedas', 'Buat Udang baso ikan praktis pedas yang nikmat dengan langkah-langkah mudah ini.', '[\"400 gram udang\", \"10 baso ikan kecil\", \"Bumbu halus\", \"3 bawang putih\", \"2 bawang merah\", \"13 cabe rawit\", \"2 cabe merah\", \"1 tomat uk sedang\", \"Merica\", \"Garam\", \"Pelengkap\", \"300ml  air\", \"Minyak untuk menumis\"]', '[\"Bersihkan udang sanpai bersih, rebus setengah matang\", \"Tumis bumbu sampai harum masukkan baso, aduk kemudian air\", \"Masukkan udang, tutup sampai mengental ato sesuai selera\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1925, 2, 'Sayur udang kuah santan', 'Hidangan seafood nikmat: Sayur udang kuah santan untuk pecinta udang.', '[\"1/4 udang kupas kulitnya kasih air jeruk nipis\", \"15 btr telur puyuh(boleh skip)\", \"2 bh sayur labu siam(potong memanjang\", \"3 bh tahu potong dadu(klu sy tahunya dikukus dulu)\", \"10 bh cabe rawit (boleh iris serong)\", \"4 bh bawang merah (rajang)\", \"3 bh bawang putih (rajang)\", \"Lengkuas geprek\", \"Jahe geprek\", \"2 santan kara\", \"1 sdt ketumbar bubuk\", \"2 lmbr daun jeruk\", \"2 lmbr daun salam\", \"secukupnya Gula\", \"secukupnya Garam\"]', '[\"Tumis Bawang merah, bawang putih lengkuas, jahe daun salam, daun jeruk cabe aduk masukan udang aduk sebentar masukan telur dan tahu masukan ketumbar kasih air secukupnya dan santan,kasih garam gula secukupnya\", \"Koreksi rasa biarkan mendidih smp matang\", \"Siap disajikan dg taburan bawang goreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1926, 3, 'Shrimp Ball', 'Nikmati kelezatan Shrimp Ball dengan resep sederhana ini.', '[\"200 gr Udang\", \"Tepung Maizena\", \"Minyak Wijen\", \"2 siung Bawang putih geprek lalu iris tipis\", \"merica (optial)\", \"garam\", \"Roti Tawar\", \"putih telur\"]', '[\"Cuci udang buang kotorannya lalu cacah\", \"Geprek bawang putih lalu iris tipis\", \"Masukkan udang di wadah bawang putih dan campur smua bahan\", \"Tambahkan tepung maizena sampe adonan sdikit padat jgn trlalu padat ya takutnya tepung gak matang\", \"Potong dadu roti tawar buang ujungnya\", \"Bulatkan adonan tempelkan roti tawar yg sudah di potong dadu sambil gempal2kan agar adonan lengket\", \"Panaskan minyak dengan api kecil saja jika sudah agak panas masukkan shrimp ball nya, angkat, tiriskan\", \"Nb : udang bisa di ganti Ayam atau di campurkan tapi Ayamnya rebus terlebih dahulu ya agar matang dgn baik, dan untuk api saat menggoreng jgn besar ya krna roti tawarnya mudah gosong lalu menyerap minyak banyak jdi saat di masukkan jgn tunggu api trlalu panas 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1927, 3, 'Cah brokoli udang saus mentega (saori)', 'Resep Cah brokoli udang saus mentega (saori) ala rumahan yang dijamin menggugah selera.', '[\"250 gr udang\", \"1 brokoli\", \"1 sachet saori saos mentega\", \"1/4 bawang bombay\", \"1 bawang putih\", \"Margarin\"]', '[\"Cuci bersih udang, kupas kulit & buang kepala lalu goreng sebentar sampai warna udang kemerahan\", \"Cuci bersih brokoli, rebus sampai matang\", \"Cincang bawang bombay, geprek bawang putih. Lalu goreng dengan margarin sampai harum\", \"Masukan udang dan brokoli aduk sampai rata\", \"Masukan saos saori, lalu beri sedikit air\", \"Masak sampai kuah mengental\", \"Siap disajikan😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1928, 4, 'Geneman urang (udang)', 'Resep Geneman urang (udang) ala rumahan yang dijamin menggugah selera.', '[\"200 gram udang yang telah di kupas\", \"250 gram kelapa parut\", \"beberapa lembar daun pisang\", \"secukupnya garam\", \"bumbu halus :\", \"2 bawang merah\", \"1 bawang putih\", \"5 cabe rawit\", \"1/2 sdtlada bubuk\", \"1/3 sdt kencur bubuk\", \"1/2 bungkus penyedap rasa\"]', '[\"Haluskan semua bumbu, kemudian campur merata dengan kelapa parut, koreksi rasa\", \"Tambahkan udang, aduk rata. lalu ambil beberapa sendok adonan untuk di bungkus dengan daun pisang\", \"Kukus selama 20-30 menit, sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1929, 3, 'Udang goreng kencur', 'Resep Udang goreng kencur yang lezat dan mudah dibuat di rumah.', '[\"1/4 kg udang sedang buang kepala\", \"Bahan halus\", \"1 sdt garam\", \"3 bh bawang putih\", \"1/2 ruas kunyit\", \"1/2 sdm ketumbar\", \"1/2 ruas kencur\", \"1/4 ruas jahe\"]', '[\"Cuci bersih udang sisihkan...\", \"Haluskan semua bahan campurkan ke udangnya diamkan kurleb 15mnt agar meresap...\", \"Panas kan wajan yg sudah berisi minyak...goreng semua udang dng bumbu2nya...(ditutup ya agar tak kena letupan minyak panasnya...selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1930, 2, 'Balado Udang', 'Balado Udang - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"250 gr udang\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"1 buah tomat\", \"7 buah Cabe merah besar\", \"8 buah Rawit merah\", \"secukupnya Garam, gula, penyedap\"]', '[\"Cuci bersih udang buang kepalanya\", \"Beri perasaan jeruk nipis\", \"Haluskan semua bumbu\", \"Goreng udang sebentar saja, angkat sisihkan\", \"Tumis bumbu halus hingga harum dan matang, masukan garam, gula, penyedap secukupnya, tes rasa\", \"Jika sudah dirasa pas masukan udang dan tumis sampai matang, lalu angkat\", \"Udang Balado siap disajikan dengan nasi hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1931, 4, 'Udang balado saus pasta', 'Resep praktis Udang balado saus pasta yang bisa dicoba di rumah.', '[\"1/4 udang\", \"6 buah Cabe besar\", \"2 bawang putih\", \"6 bawang merah\", \"4 lembar daun salam\", \"1 sendok saus pasta delmonte spagetti\"]', '[\"Uleg bawang merah n bawang putih sampai halus\", \"Blender cabe hingga lembut, jgn terlalu cair\", \"Tumis bawang merah n bawang putih lalu masukan cabenya n 1 sdm saus pasta\", \"Masukan udang,tunggu sampai mendidih n udang nya berubah menjadi merah\", \"Masukan gula, n royco secukupnya. Tes rasa, jika sudah pas tinggal disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1932, 2, 'Tumis Udang Cabe Ijo', 'Cara membuat Tumis Udang Cabe Ijo yang enak dan praktis untuk keluarga.', '[\"200 gr udang kupas\", \"6 buah cabe ijo iris serong\", \"1 batang daung bawang potong-potong\", \"3 siung bawang putih iris\", \"5 siung bawang merah iris\", \"2 lembar daun jeruk\", \"1 sdt garam\", \"1/2 sdm gula\", \"1 sdm kecap manis\", \"secukupnya minyak untuk menumis\", \"royco secukupnya (optional)\"]', '[\"Tumis bawang merah, bawang putih sampai harum dah berubah warna agak kecoklatan\", \"Masukan irisan cabe ijo, daun bawang dan daun jeruk, tumis sampai cabe agak layu\", \"Masukan udang, boleh tambahkan sedikit air\", \"Setelah udang berubah warna masukan gula, garam, kecap dan royco. Tes rasa.\", \"Masak hingga matang dan siap dihidangkan bersama nasi hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1933, 2, 'Udang pete', 'Nikmati kelezatan Udang pete dengan resep sederhana ini.', '[\"250 gr udang besar\", \"250 gr telur puyuh\", \"Bumbu rajang :\", \"1 buah bawang bombay ukuran kecil\", \"2 siung bawang putih\", \"1/4 bagian paprika hijau\", \"1 buah cabe merah besar\", \"2 buah cabe rawit\", \"1 sisir pete\", \"1 buah tomat ukuran kecil\", \"Bumbu :\", \"1 sdt garam\", \"1 sdm saos tiram\", \"2 tetes saos raja rasa\", \"1 sdt kecap manis\", \"1 sdt saos tomat\"]', '[\"Udang buang kepalanya (bisa dipakai untuk minyak udang) belah tengahnya. Goreng sebentar, jangan sampai kering, tujuannya supaya nanti kalau masakan dingin tidak amis.\", \"Goreng sebentar telur puyuh (optional)\", \"Rajang semua bumbu.\", \"Tumis bawang bombay dan bawang putih terlebih dulu hingga harum baru setelah itu masukkan bahan rajang lainnya. Kalau suka rasa pete yg kuat, petenya bisa dimasukkan terakhir tanpa ditumis ya..\", \"Kalau sudah layu, tambahkan semua bumbu (saos garam dll) baru masukkan udang dan telur. Selalu koreksi rasa ya bund..karena selera masing2 orang tidak sama..\", \"Selamat memasak😉😉😉\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1934, 4, 'Udang goreng tepung asam manis', 'Cara membuat Udang goreng tepung asam manis yang enak dan praktis untuk keluarga.', '[\"1/4 udang\", \"1/4 tepung terigu/tepung bumbu instan\", \"1 sendok tepung maizena\", \"1 bh bawang bombay\", \"1 cm jahe\", \"1 siung bawang putih\", \"4 siung bawang merah\", \"2 bh tomat besar\", \"3 bh cabe rawit\", \"4 bh cabe besar merah\", \"Merica bubuk\", \"Saus tiram\", \"Garam\", \"Penyedap\", \"sesuai selera Gula pasir\", \"sedikit Air\", \"1 daun jeruk\", \"2 bks saus tomat\"]', '[\"Bagi dua tepung terigunya basah dan kering,baluri udang kedalam tepung kering lalu ketepung basah tepung kering dan goreng sampai kering tiriskan,larutkan tepung maizena sisihkan,\", \"Iris bawang putih,bawang merah,cabe,bawang bombay,jahe,1tomat,1tomat di blender.\", \"Tumis bawang putih,bawang merah,bawang bombay sampai harum,masukan saos tiram,tomat yang sudah diblender,masukan saus sambal,setelah mendidih masukan bawang bombay,wortel,setelah matang tambahkan air sedikit,masukan garam,penyedap,merica,gula,tambahkan larutan tepung maizena,aduk aduk matikan kompor siram ke udang yang sudah digoreng.selamat mencoba🙂\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1935, 2, 'Tumis Buncis Udang', 'Resep praktis Tumis Buncis Udang yang bisa dicoba di rumah.', '[\"100 gr buncis\", \"1 batang jagung (serut)\", \"1 bh wortel (potong dadu)\", \"10 ekor udang kupas\", \"Bumbu:\", \"4 cabai rawit merah\", \"2 cabai merah kriting\", \"3 siung bawang merah\", \"2 siung bawang putih\", \"Gula\", \"Garam\", \"Penyedap (kalau perlu)\"]', '[\"Siangi sayuran dan cuci bersih\", \"Iris2 semua bumbu.\", \"Siapkan wajan panaskan minyak. Tumis semua bumbu dan tambahkan gula, garam, dan penyedap. jika aroma sudah keluar masukkan wortel dan buncis. Masak hingga layu\", \"Masukkan jagung dan udang. Tumis campur semua, bahkan sedikit air\", \"Test rasa, masak hingga matang. Siap di sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1936, 3, 'Tumis Udang x Jagung Buncis Pete', 'Sajian Tumis Udang x Jagung Buncis Pete yang praktis dan lezat untuk dinikmati bersama.', '[\"1 Buah jagung uk sedang\", \"1 genggam udang kupas segar\", \"7 siung bawang putih\", \"5 siung bawang merah\", \"1/2 buah bawang bombai\", \"1 papan pete, aku potong kecil2\", \"1 buah tomat uk kecil\", \"7 buah cabai rawit merah utuh, iris kalau ingin pedasnya lebih kerasa\", \"Secukupnya Merica\", \"1/2 sdt Garam\", \"1 sdt Gula pasir\", \"Secukupnya Penyedap rasa ayam\"]', '[\"Bersihkan sayurannya / bahan2nya, potong sesuai selera, aku potongnya kecil2.\", \"Tumis bawang2an, tomat, dan cabai, lalu masukkan udang dan pete. Tumis sebentar.\", \"Masukkan jagung dan buncisnya, beri air secukupnya. Beri bumbu, cek rasa. Masak sampai airnya sedikit meresap. Setelah matang angkat dan sajikan. ❤\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1937, 4, 'Perkedel tahu udang', 'Perkedel tahu udang - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"5 buah tahu sedang\", \"8 ekor udang galah yg besar\", \"1 bungkus tepung tempe kriuk me : merk Kobe\", \"7 lembar daun jeruk, buang tangkainya iris halus\", \"1 butir telur\", \"5 sdm tepung terigu\", \"2 siung bawang putih, geprek cincang\", \"1/2 gelas air\", \"Sejumput garam untuk udang\"]', '[\"Bersihkan udang, beri garam sedikit, potong2 1 cm, sisihkan.\", \"Campurkan semua bahan, kasih air 1/2 gelas, aduk rata, masukkan tahu, hancurkan dengan garpu hingga menyatu dengan adonan. Tambahkan potongan udang, aduk rata.\", \"Goreng 1 sendok sayur hingga kuNing keemasan, angkat tiriskan. Lakukan hingga adonan habis.\", \"Sajikan.\", \"Bisa dimakan dengan cabe rawit, cuko pempek atau bumbu pecel 😉😉\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1938, 3, 'Udang Goreng Mentega Gurih', 'Sajian Udang Goreng Mentega Gurih yang praktis dan lezat untuk dinikmati bersama.', '[\"1/4 kg udang putih ukuran kecil dan sedang\", \"2 siung bawang putih, iris tipis\", \"3 siung bawang merah, iris tipis\", \"1/2 bawang bombai ukuran sedang, iris tipis\", \"1 sdt merica bubuk\", \"3 sdm margarin (kalau mau lebih gurih, boleh ditambah)\", \"Secukupnya garam\", \"Secukupnya gula\", \"50 ml air panas\"]', '[\"Tempatkan udang yg sudah bersih pada wadah. Kucuri udang dengan perasan jeruk nipis kemudian aduk2 agar air jeruk merata tercampur. Fungsinya biar udang nggak terlalu amis. Diamkan kira-kira 10 menit\", \"Panaskan wajan dengan api kecil. Masukkan margarin. Tumis bawang bombai sampai cukup harum, kemudian baru masukkan bawang merah dan bawang putih. Masak sampai bumbu harum\", \"Besarkan api lalu masukkan udang dan segera bolak-balik agar bumbu meresap rata dan untuk mencegah overcooked.\", \"Setelah 1 menit, tambahkan gula, garam, merica bubuk, dan air. Kemudian masak kembali sebentar kira-kira 3-4 menit atau jika udang sudah terlihat merah\", \"Koreksi rasa dan segera matikan api.\", \"Segera pindahkan udang pada tempat sajian untuk menghentikan proses memasak. Udang goreng mentega pun siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1939, 3, 'Tumis bayam udang', 'Cara membuat Tumis bayam udang yang enak dan praktis untuk keluarga.', '[\"1 ikat bayam\", \"1/4 kg udang (kupas)\", \"1 buah wortel\", \"3 buah putren\", \"Bawang putih (cincang halus)\", \"secukupnya Garam, gula\", \"Minyak untuk menumis\"]', '[\"Cuci bersih semua bahan\", \"Tumis bawang putih cincang hingga harum\", \"Masukkan udang, wortel dan putren\", \"Terakhir masukkan bayam beri sedikit air (2 sendok makan),tambahkan garam dan gula cek rasa\", \"Siap dihidangkan mudah bukan 😁\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1940, 2, 'Sop udang simpel', 'Resep praktis Sop udang simpel yang bisa dicoba di rumah.', '[\"250 gr udang, belah punggung\", \"3 siung bawang merah, iris tipis\", \"1 siung bawang putih, iris tipis\", \"4 buah cabe merah, potong serong\", \"1 lembar daun kunyit\", \"Secukupnya Air\", \"Secukupnya Garam dan merica\"]', '[\"Tumis bawang merah dan bawang putih sampai wangi, lalu masukkan cabe. Tumis sebentar.\", \"Masukkan udang dan daun kunyit, lalu tuang air secukupnya.\", \"Masak hingga mendidih, lalu masukkan garam dan merica.\", \"Tes rasa.\", \"Siap dihidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1941, 3, 'Capcay Udang Simple ala Annisa Ellen', 'Resep Capcay Udang Simple ala Annisa Ellen ala rumahan yang dijamin menggugah selera.', '[\"2 ons Udang ukuran kecil\", \"2 buah Wortel\", \"1 buah Brokoli\", \"Kubis (sesuai selera mau berapa)\", \"2 buah Cabe merah\", \"1 tangkai Daun bawang\", \"1 sachet Saori saos tiram\", \"Minyak goreng\", \"Mentega\", \"Air\", \"Bumbu di ulek :\", \"2 buah Bawang putih\", \"2 buah kemiri\", \"secukupnya Merica bubuk\", \"Sepucuk sendok garam\", \"(Semua bahan diulek dan ditambah merica bubuk)\"]', '[\"Cuci semua sayuran dan udang sampai bersih, bersihkan dan buang kepala udang\", \"Potong cabe merah dan wortel berbentuk memanjang, potong daun bawang kotak2, brokoli potong ukuran sedang, potong kubis sesuai selera\", \"Goreng terlebih dahulu udang dengan mentega\", \"Panaskan teflon dan masukkan minyak goreng secukupnya, masukkan bumbu yang sudah di ulek tadi, aduk dan tunggu sampai wanginya harum, lalu masukkan cabe merah dan wortel, tambahkan air secukupnya, aduk dan tunggu sampai wortel agak lunak, setelah itu masukkan semua bahan seperti udang, brokoli, kubis, dan daun bawang. Jika masih kurang air bisa di tambahkan air lagi secukupnya. Dan terakhir masukkan Saori Saos Tiram. Aduk hingga merata dan tunggu sampai matang.\", \"Angkat dan tiriskan, masakan siap untuk disajikan. Selamat mencoba 🤗\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(1942, 3, 'Sempol Udang Sayur', 'Resep praktis Sempol Udang Sayur yang bisa dicoba di rumah.', '[\"50 gr Udang\", \"50 gr Wortel\", \"1 butir Telur\", \"3 siung Bawang putih\", \"secukupnya Penyedap rasa + garam\", \"secukupnya Lada\", \"100 gr Tepung tapioka\", \"25 gr Tepung terigu\", \"1 butir Telur untuk olesan\", \"Air untuk rebusan\", \"Minyak untuk menggoreng\"]', '[\"Kupas udang, blender bersama dengan bawang putih dan telur.\", \"Parut wortel, campur dengan udang yang telah dihaluskan tadi.\", \"Campur tepung tapioka, terigu, garam+penyedap rasa. Aduk hingga kalis. Jika terlalu lembek bisa ditambahi tepung terigu. Disesuaikan.\", \"Setelah kalis, bentuk seperti sempol pada tusuk sate. Panaskan air, masukkan sempol, rebus hingga matang. Tiriskan.\", \"Panaskan minyak goreng, goreng sempol sebentar. Setelah setengah matang, angkat sempol celupkan kedalam kocokan telur, goreng lagi hingga matang. Setelah matang, angkat dan sajikan.\", \"Sempol siap disantap bersama saos dan kecap :))\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1943, 2, 'Nasi Bakar isi Balado udang kentang', 'Resep Nasi Bakar isi Balado udang kentang ala rumahan yang dijamin menggugah selera.', '[\"1/4 kg beras putih\", \"1/2 bks santan (aku pakai ayam brand) larutkan dg air 2 gelas\", \"100 gram teri medan goreng\", \"10 cabe rawit orange\", \"Daun pisang dan tusuk gigi\", \"1 iris lengkuas\", \"2 lbr daun salam\", \"2 lbr daun jeruk\", \"1 btg sere\", \"Balado kentang udang (resepnya terpisah ya)\"]', '[\"Siapkan rice cooker. Cuci beras, masukkan ke dlm rice cooker. Tambahkan air, santan, garam, daun salam, sereh, lengkuas, daun jeruk. Masak hingga tanak\", \"Setelah tanak, taburkan teri medan dan cabe rawit. Tutup rice cooker 10 menit hingga tanak lagi.\", \"Siapkan daun pisang. Lalu tata Nasi dr rice cooker dan balado udang ketang) bungkus spt gambar ini\", \"Bakar diatas wajan teflon, bolak-balik agar merata.\", \"Siap disantap. Nasi bakar sederhana, harumnya daun pisang bikin nagih makannya.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1944, 3, 'Udang saos tiram pedas', 'Nikmati kelezatan Udang saos tiram pedas dengan resep sederhana ini.', '[\"500 gr Udang galah\", \"2 siung Bawang putih\", \"Bawang bombay (sy skip krn stock kulkas kosong 😝)\", \"Jahe (sedikit aja diiris / geprek)\", \"2 Lembar daun jeruk\", \"1 batang daun sereh\", \"Daun bawang\", \"200 ml Air matang\", \"Garam\", \"Merica\", \"Saos tiram\", \"1 sdm maizena yg di larutkan dgn sdkt air\", \"Bumbu Yg di haluskan:\", \"7 buah Cabe merah\", \"10 buah rawit merah\", \"1/2 buah tomat\", \"Gula merah\"]', '[\"Tumis bawang putih, bawang bombay sampai harum.\", \"Masukkan bumbu halus, jahe, daun jeruk, sereh. Tumis sampai harum.\", \"Masukkan udang, tambahkan sedikit air. Beri garam, merica, saos tiram. Masak sampai udang matang. Jangan terlalu lama krn tekstur udang nanti jadi liat.\", \"Kecilkan api, Masukkan maizena yg sudah dilarutkan. Tambahkan daun bawang..\", \"Voiiillaaaa... Jadiiiii\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1945, 2, 'Tumis buncis udang wortel', 'Tumis buncis udang wortel dengan udang segar dan bumbu khas.', '[\"200 gr buncis, potong2 serong\", \"1 buah wortel, serut tebal\", \"1 genggam udang kecil yg sdh dibuang kepala & buntut\", \"3 siung bawang putih, cincang kasar\", \"3 buah lombok hijau besar, buang biji potong2 tipis\", \"1 buah tomat, potong2\", \"Sedikit terasi\", \"Secukupnya garam & gula\"]', '[\"Tumis bawang putih sampai layu masukan terasi lalu tumis sampai harum... masukan udang, aduk2 sampai udang berubah warna.. masukan irisan cabe dan tomat aduk biarkan agak layu.\", \"Masukan buncis dan wortel aduk rata, tutup wajan biarkan sampai sayuran layu... tambahkan sedikit air +garam dan gula, aduk rata.\", \"Masak sampai air menyusut, tes rasa.. jika sdh pas rasanya angkat dan sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1946, 2, 'Udang goreng bawang putih', 'Sajian Udang goreng bawang putih yang praktis dan lezat untuk dinikmati bersama.', '[\"1/4 gram udang\", \"1 sdt garam kasar\", \"5 siung bawang putih\", \"1/2 sdt tepung beras\", \"Minyak utk menggoreng\"]', '[\"Cuci bersih udang buang ujung kepalanya dan belah sedikit bagian tengah badan udang tarik kotoranya\", \"Haluskan bawang putih dan garam\", \"Campurkan udang dengan bumbu, aduk rata lalu beri tepung beras aduk2 rata\", \"Goreng udang sampai garing, angkat/tiriskan.. jangan lupa ambil remahan bawang didalam minyak td dan tabur diatas udang\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1947, 4, 'Bakwan Udang', 'Resep Bakwan Udang ala rumahan yang dijamin menggugah selera.', '[\"1 kg udang\", \"750 gr tepung beras (saya pakai rose brand)\", \"3 butir kemiri\", \"4 butir bawang putih\", \"1 ruas kunyit\", \"10 buah cabai (boleh kurang atau lebih sesuai selera)\", \"Secukupnya ketumbar\", \"Secukupnya air\", \"1 sachet royko\", \"Secukupnya garam\", \"Secukupnya micin\"]', '[\"Cuci bersih udang\", \"Ulek kemiri, bawang putih, kunyit, cabai, ketumbar sampai halus setelah itu campur dengan udang\", \"Campurkan semua tepung beras dengan udang dan bumbu ulek\", \"Tambahkan air sampai menyatu dengan sempurna\", \"Tambahkan garam, royko, micin sampai enak\", \"Goreng dengan minyak panas dan hidangkan bersama sambal pedas 👍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1948, 4, 'Tumis Phok Coy Udang Wortel Plus Bawang Bombay', 'Resep Tumis Phok Coy Udang Wortel Plus Bawang Bombay yang lezat dan mudah dibuat di rumah.', '[\"1 ikat phok coy (sawi hijau)\", \"1/2 kg udang\", \"3 buah wortel (iris panjang jangan terlalu tipis)\", \"1 buah bawang bombay\", \"4 siung bawang putih\", \"Kecap manis\", \"secukupnya Merica\", \"secukupnya Gula\", \"secukupnya Garam\", \"Penyedap rasa (optional)\", \"Sedikit air\"]', '[\"Cuci bersih phok coy(sawi hijau), wortel lalu potong2\", \"Cuci bersih udang yang sudah di siangi\", \"Iris-iris bawang putih dan bawang bombay (tumis sampe agak layu), tambahkan sedikit air\", \"Masukkan udang, merica bubuk, gula, garam, aduk rata\", \"Lanjut masukkan wortel aduk rata sampe wortel setengah matang, lalu masukkan sawi\", \"Tambahkan kecap (saya pakai 1 sdm kecap), test rasa, bisa tambahkan penyedap rasa sedikit saja bila suka, aduk rata sampai matang\", \"Tumis Phok Coy Udang Wortel Plus Bawang Bombay siap d\'Hidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1949, 4, 'Bakwan sayur saos petis udang', 'Resep praktis Bakwan sayur saos petis udang yang bisa dicoba di rumah.', '[\"1/4 wortel\", \"1/4 kol / kubis\", \"1/2 kg tepung terigu\", \"3 siung bawang putih\", \"4 butir kemiri\", \"1 sdt ketumbar bubuk\", \"1 sdm garam (sesuai selera)\", \"1 sdt penyedap (skip)\", \"Bahan petis\", \"1 ons petis udang\", \"1 siung bawang putih\", \"1 sdm gula pasir\", \"1/2 sdt penyedap\"]', '[\"Ulek bawang putih, kemiri sampai halus\", \"Campur tepung terigu bumbu halus dan ketumbar, garam, penyedap,tambahkan air kemudian masukan sayuran (wortel dan kubis) sampai rata\", \"Goreng bakwan sampai kecoklatan\", \"Untuk petis udangnya ulek bawang putih, didihkan air, dan masukan petis beserta bumbunya masak hingga meletup2 dan angkat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1950, 3, 'Bakwan sayuran n udang', 'Sajian Bakwan sayuran n udang yang praktis dan lezat untuk dinikmati bersama.', '[\"1 bks toge (Rp. 2000)\", \"2 buah wortel iris korek api\", \"1 batang daun bawang (sy lupa beli daun bawang 😁)\", \"Sckpnya udang\", \"Bumbu halus :\", \"1/4 sdt lada\", \"3-4 bawang putih\", \"Sckpnya garam\", \"10 sdm terigu\", \"2 sdm tepung beras\", \"Sckpnya air\"]', '[\"Campur toge, wortel dan daun bawang aduk rata\", \"Cuci bersih udang buang kepalanya, kulit dan buntutnya jgn dibuang\", \"Campur terigu dan tepung beras beri air sckpnya aduk rata dgn kekentalan sedang masukan jg bumbu halus,garam dan kaldu bubuk aduk rata (icip rasa)\", \"Masukan sayuran ke tepung sckpnya dl (kira2)\", \"Panaskan minyak agak banyak....bikin versi bundar masukan jg centong sayur ke minyak sampai bnr2 panas\", \"Setelah minyak dan centong panas angkat centong sisakan sedikit minyak d centong, taruh adonan bakwan dicentong dan ksh udang diatasnya (hati2 dgn centong yg panas)\", \"Kemudian masukan centong yg berisi adonan bakwan ke minyak\", \"Tunggu bbrp saat sampai bakwan terlepas dr centongnya, goreng bakwan sampai matang dan kecoklatan dgn api sedang\", \"Bakwan siap disantap dgn cabe rawit bisa jg buat lauk makan siang\", \"Selamat mencoba 👌\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1951, 2, 'Udang balado pedas', 'Resep Udang balado pedas yang lezat dan mudah dibuat di rumah.', '[\"1/2 kg udang bersihkan\", \"bumbu halus:\", \"20 cabe rawit merah\", \"20 cabe rawit merah\", \"3 siung bawang putih\", \"6 siung bawang merah\", \"1 tomat\", \"secukupnya gula\", \"secukupnya garam\", \"secukupnya kaldu bubuk ayam (saya pakai yg non msg)\", \"sedikit air\", \"sedikit merica bubuk\", \"3 cabe keriting merah\", \"3 siung bawang putih\", \"6 siung bawang merah\", \"1 tomat\", \"secukupnya gula\", \"secukupnya garam\", \"secukupnya kaldu bubuk ayam (saya pakai yg non msg)\", \"sedikit air\", \"sedikit merica bubuk\"]', '[\"Bersihkan udang, (kalau saya masih pakai kepala dan kulit). lumuri dengan jeruk nipis, diamkan beberapa saat.\", \"Cuci udang lalu goreng (saya lebih suka yang garing), sisihkan\", \"Tumis bumbu halus sampai harum. tambahkan gula, garam, kaldu bubuk dan sedikit air. cek rasa lalu masukkan udang. biarkan bumbu meresap\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1952, 4, 'Udang Crispy Saos Kerang', 'Resep praktis Udang Crispy Saos Kerang yang bisa dicoba di rumah.', '[\"udang crispy ¼ kg (silahkan lihat resep udang crispy\", \"1/4 kg kerang kupas\", \"3 siung bawang putih\", \"4 siung bawang merah\", \"2 buah tomat\", \"merica bubuk (saya pakai ladaku)\", \"1/2 botol saos tomat\", \"maizena (1 sendok teh)\", \"secukupnya gula & garam\"]', '[\"Rajang bawang merah, bawang putih, tomat\", \"Kemudian tumis bawang merah, bawang putih, tomat\", \"Setelah harum, masukkan kerang kupas kedalam tumisan\", \"Masukkan merica bubuk, gula, garam secukupnya, aduk 2 menit\", \"Masukkan saus tomat ½ botol kecil\", \"Agar mengental tambahkan maizena 1 sendok teh kedalam air ½ gelas tanggung, tunggu 3 menit sampai semua bumbu meresap sempurna\", \"Matikan kompor dan masukkan udang crispy aduk hingga saos merata pada udang crispy tsb\", \"Sajikan dengan nasi hangat\", \"Selamat mencoba 👍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1953, 3, 'Udang saos tiram asam manis', 'Sajian Udang saos tiram asam manis yang praktis dan lezat untuk dinikmati bersama.', '[\"1/2 kg udang galah, buang kepala\", \"Bumbu:\", \"7 siung Bawang putih\", \"10 bh Cabe merah keriting\", \"3 bh Cabe rawit merah\", \"5 butir Kemiri\", \"sejumput jari Lada butiran\", \"2 bh Tomat , potong2 dan haluskan kasar\", \"Seledri iris kecil2\", \"Saos tiram, saos tomat, saos sambal dan kecap manis\"]', '[\"Haluskan semua bumbu dan tumis sampe harum\", \"Setelah bumbu harum, masukkan tomat yang sudah dihaluskan smp bumbu berubah berwarna merah\", \"Tambahkan garam dan gula pasir sesuai selera\", \"Masukkan udang.. aduk rata smp matang tapi jangan sampai over cook karena membuat tekstur udang tdk segar lagi\", \"Tambahkan saos tiram, saos tomat, saos sambal dan sedikit kecap manis\", \"Setelah matang sebelum api dimatikan, taburkan seledri, aduk sampai rata dan matikan apik\", \"Siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1954, 3, 'Udang saus telor asin', 'Hidangan seafood nikmat: Udang saus telor asin untuk pecinta udang.', '[\"15 ekor udang ukuran sedang\", \"1 buah jeruk nipis\", \"2 sdm tepung terigu\", \"1 sdm tepung maizena\", \"1 sdt masako\", \"1 butir putih telur\", \"2 buah telor asin (merahnya saja dihancurkan dan beri air sedikit)\", \"1 sdm margarin\", \"2 siung bawang putih (cincang halus)\", \"1/4 ruas jahe (cincang halus)\", \"1/4 bawang bombay (cincang kasar)\", \"Lada\", \"Garam\", \"Garlic powder\"]', '[\"Bersihkan udang, buang kepalanya buang kotoran udang pada bagian punggung dan bawah udang, sisakan buntut udang..\", \"Marinade udang dengan air jeruk nipis, garam, lada dan garlic powder.. masukkan kulkas, marinade min 15 menit..\", \"Setelah udang di marinade masukan putih telur ke dalam udang, aduk hingga semua udang terlapisi putih telur..\", \"Campurkan tepung terigu, tepung maizena, dan masako, setelah tercampur balurkan udang ke dalam adonan tepung hingga terlapisi semuanya..\", \"Siapkan minyak panas untuk menggoreng udang, setelah cukup matang angkat, panaskan minyak lebih panas lalu masukkan kembali udang, goreng selama kurang lebih 1 menit lalu angkat, tiriskan (digoreng 2x agar lebih crispy)..\", \"Panaskan wajan, masukkan margarin, bawang putih, bawang bombay dan jahe, masak hingga harum lalu masukkan merah telor yg sudah dilumatkan dengan sedikit air.. Aduk hingga berbusa, lalu masukkan udangnya aduk hingga merata..\", \"Setelah tercampur rata, siap untuk disajikan :)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1955, 3, 'Botok jamur tahu udang', 'Resep praktis Botok jamur tahu udang yang bisa dicoba di rumah.', '[\"1/2 biji kelapa parut\", \"100 grm udang bersih tanpa kepala dan kulit\", \"1 bungkus jamur tiram\", \"2 biji tahu\", \"1 butir telor\", \"1 biji tomat potong dadu\", \"daun pisang secukup nya\", \"Bumbu Halus\", \"2 biji cabe merah besar\", \"10 biji cabe rawit\", \"3 siung bawang putih\", \"3 bawang merah\", \"2 biji kemiri\", \"1 sendok teh ketumbar\", \"sedikit jahe\", \"sedikit kunyit\", \"sedikit lengkuas\", \"sedikit kencur\", \"2 lmbar daun jeruk\", \"garam\", \"gula\", \"msg kalau perlu aku ngk pakai\"]', '[\"Rebus tahu di air mendidih sebentar dan angkat potong dadu.rebus jamur tiram sebentar saja ya angkat celur daun pisang di air rebusan tahu tadi bagi daun pisang layu biar ngk sobek waktu kita pakai\", \"Haluskan bumbu halus. satukan semua bahan kelapa parut tomat tahu udang jamur aduk rata jagan lupa beri garam gula aduk rata koreksi rasa pecahkan telor aduk rata dan bungkus dengan daun pisang tusuk dengan lidi kukus selama 30menit\", \"Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1956, 2, 'Sambal goreng udang buncis', 'Sajian Sambal goreng udang buncis yang praktis dan lezat untuk dinikmati bersama.', '[\"1/4 kg Udang , buang kepala dan ekornya\", \"1/2 kg Buncis , potong seruas jari\", \"Bumbu :\", \"15 bh Cabe merah keriting\", \"5 bh Cabe rawit merah\", \"8 siung Bawang merah\", \"5 siung Bawang putih\", \"1 buah Tomat\", \"5 butir Kemiri\", \"Salam, laos, serai, daun jeruk\"]', '[\"Haluskan semua bumbu cabe, bawang merah, bawang putih dan kemiri\", \"Panaskan minyak dan tumis bumbu sampai harum dan keluar minyak\", \"Masukkan salam,.laos, serai dan daun jeruk.\", \"Masukkan garam, gula jawa dan sedikit gula pasir sesuai selera\", \"Masukkan udang, tumis sampai tercampur rata dg bumbu baru masukkan buncis\", \"Setelah buncis layu.. matikan api dan siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1957, 3, 'Nasi Goreng Udang Oriental', 'Resep Nasi Goreng Udang Oriental yang lezat dan mudah dibuat di rumah.', '[\"4 piring nasi\", \"150 gr udang kupas\", \"4 siung bawang merah, haluskan\", \"4 siung bawang putih, haluskan\", \"2 butir telur\", \"Margarin\", \"Garam\", \"Merica\"]', '[\"Kocok lepas telur\", \"Panaskan wajan, masukkan margarin, setelah panas masukkan telur.\", \"Aduk telur untuk membuat scrambled egg. Angkat dan sisihkan.\", \"Panaskan lagi wajan, masukkan 2 sendok makan margarin.\", \"Tumis bawang merah dan bawang putih hingga wangi.\", \"Masukkan udang, tumis sampai berubah warna.\", \"Masukkan nasi aduk sampai rata.\", \"Bumbui dengan garam, gula dan merica. Aduk rata.\", \"Masukkan telur aduk hingga rata.\", \"Seimbangkan rasa.\", \"Siap dihidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1958, 4, 'Balado Kentang Udang', 'Nikmati kelezatan Balado Kentang Udang dengan resep sederhana ini.', '[\"1/2 kg kentang\", \"1/4 udang\", \"1 papan pete\", \"5 lembar daun jeruk (iris tipis)\", \"1 buah kemiri\", \"Cabe rawit keriting dan cabe syaiton (sesuaikan selera)\", \"5 siung bawang merah\", \"2 siung bawang putih\", \"1 sachet terasi udang ABC\", \"1 buah tomat\", \"Minyak utk menumis\"]', '[\"Potong dadu kentang, goreng kering, kemudian sisihkan\", \"Rebus cabe, bawang putih, bawang merah, dan tomat hingga lunak kemudian di haluskan bersama dg terasi dn kemiri (kalau sy d blender saja)\", \"Tumis bumbu halus hingga harum, masukkan pete, daun jeruk, dan udang, lalu koreksi rasa.\", \"Masukan kentang goreng. Aduk hingga semua bahan tercampur rata. Balado siap di sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1959, 2, 'Sambal Gami Udang', 'Buat Sambal Gami Udang yang nikmat dengan langkah-langkah mudah ini.', '[\"1/2 kg udang (buang kulit kepala dan ekor\'ny)\", \"Bumbu sambal 👇\", \"2 siung bawang putih\", \"8 siung bawang merah\", \"2 buah tomat\", \"15 buah cabe kecil\", \"1/2 bungkus terasi ABC\", \"2 lembar daun jeruk\", \"Secukupnya gula dan garam\", \"Minyak goreng\"]', '[\"Cuci bersih udang yang telah dibuang ekor dan kulit kepalanya, tiriskan\", \"Goreng bumbu sambal (kecuali daun jeruk) sampai layu, lalu uleg sampai agak halus\", \"Letakkan cobek diatas kompor lalu tumis sambal dengan minyak. Tambahkan gula, garam, daun jeruk beserta udang yang telah dicuci.\", \"Tunggu sampai mendidih dan udang matang. Tes rasa kemudian siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1960, 4, 'Udang Asam Manis Glowing', 'Buat Udang Asam Manis Glowing yang nikmat dengan langkah-langkah mudah ini.', '[\"1/2 kg udang\", \"3 siung bawang merah\", \"Kunyit bubuk\", \"Garam\", \"Penyedap rasa (saya tidak)\", \"Air asam jawa\"]', '[\"Bersihkan udang dan cuci bersih. (Saya tidak kupas kulit)\", \"Masukkan udang dalam air asam Jawa.\", \"Iris bawang merah\", \"Panaskan minyak, tumis irisan bawang merah.\", \"Masukkan udang dan air asamnya ke dalam tumisan. Aduk.\", \"Beri kunyit dan garam. Tes rasa\", \"Tunggu sampai kuah mengental dan dapat warna glowingnya.\", \"Angkat. Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1961, 3, 'Gulai udang dengan daun ubi', 'Gulai udang dengan daun ubi dengan udang segar dan bumbu khas.', '[\"1 kg udang galah/peci yg sedang/besar\", \"4 ikat daun ubi (daun singkong/pucuk perancis,)\", \"1/2 kg kelapa tua, parut\", \"2 lembar daun salam\", \"1 lembar daun kunyit\", \"1 batang serai\", \"4 buah asam kandis\", \"4 lembar daun jeruk\", \"Bahan bumbu halus :\", \"250 gr cabe keriting\", \"4 butir bawang merah\", \"1 butir bawang putih\", \"Sejempol lengkuas/Laos\", \"Sejempol jahe\", \"Seruas kunyit\", \"4 butir kemiri\", \"Garam\"]', '[\"Bersihkan udang, buang ujung kepala dan kulit dikepala udang, gunting kaki2 dan punggungnya buang kotorannya. Cuci bersih, garami, sisihkan.\", \"Siangi daun ubi/daun singkong, ambil yg muda2. Cuci. Rebus dengan sedikit garam hingga empuk. Sisihkan.\", \"Haluskan semua bumbu. Peras kelapa hingga santan keluar kurang lebih jadi 1 kg santan.\", \"Masukkan bumbu halus dan santan dalam kuali, tambahkan daun salam, daun kunyit, daun jeruk, serai, asam kandis dan garam, aduk rata didihkan.\", \"Setelah mendidih masukkan udang, masak hingga udang 1/2 matang.\", \"Daun ubi yg sudah empuk diperas, potong2 atau gunting. Masukkan dalam gulai.\", \"Masak hingga udang dan daun ubi empuk, kuah mengental dan taminyak.\", \"Sajikan dengan nasi panas... dijamin batambuah tambuah maambiak nasinyo 😂😂😂. Nan sabana bana lamak...😋😋😋😋😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1962, 3, 'Udang galah goreng', 'Resep Udang galah goreng ala rumahan yang dijamin menggugah selera.', '[\"250 gr udang galah\", \"4 siung bawang putih\", \"Minyak goreng\", \"secukupnya Garam\"]', '[\"Bersihkan udang,buang kotoran dikepala udang,dan cuci bersih\", \"Haluskan bawang putih dan garam,campurkan udang dan bumbu,aduk agar bumbu tercampur rata,biarkan bumbu resap dulu selama 15 menit\", \"Panaskan penggorengan dan masukan udang,goreng sampai kemerahan,angkat dan tiriskan\", \"Udang galah goreng sudah siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1963, 3, 'Shrimp with salted-egg sauce', 'Resep praktis Shrimp with salted-egg sauce yang bisa dicoba di rumah.', '[\"2 ons udang (kupas+cuci bersih)\", \"1 bgks Tepung bumbu serbaguna\", \"2 butir telur ayam (ambil putihnya)\", \"3 siung bawang putih\", \"3 buah cabe rawit (optional)\", \"1/2 btg daun bawang\", \"3 butir telur asin matang (ambil kuningnya)\", \"Susu full cream/plain\", \"secukupnya Gula, garam, merica\"]', '[\"Rendam udang dalam air lemon/daun jeruk selama beberapa menit (menghilangkan bau amis)\", \"Masukkan udang kedalam putih telur kemudian lumuri dengan tepung bumbu. Goreng sampai kuning keemasan dengan api sedang\", \"Persiapan saus telur asin:\", \"Haluskan kuning telur asin dengan garpu dan ditambahkan susu cair sedikit demi sedikit sampai agak encer\", \"Panaskan minyak, tumis bawang putih yg sudah dicincang halus, cabe rawit dan daun bawang iris tipis.\", \"Tumis hingga harum\", \"Masukkan campuran saus telur asin, kecilkan api dan aduk rata\", \"Jangan lupa tambahkan gula, garam dan lada sesuai selera (rasa cenderung gurih)\", \"Masukkan udang goreng tepung tadi. Kemudian matikan api\", \"Siap disajikan :)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1964, 3, 'Cilok udang sederhana ala anak rantau', 'Cilok udang sederhana ala anak rantau - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"10 sendok makan tepung terigu\", \"10 sendok makan tepung tapioka\", \"Penyedap rasa\", \"Air panas\", \"100 gram udang yang sudah dihaluskan\"]', '[\"Masukan telung terigu dan tepung tapioka kedalam wadah\", \"Masukan penyedap rasa dan udang yang sudah dihaluskan, campur menjadi 1\", \"Rebus air hingga mendidih\", \"Masukan air mendidih sedikit demi sedikit kedalam wadah yang sudah berisi tepung, penyedap rasa, dan udang yang sudah dicampurkan hingga adonan menjadi kalis\", \"Setelah adonan sudah kalis maka bentuklah menjadi bulat-bulat atau sesuai selera\", \"Rebus air hingga mendidih\", \"Setelah air mendidih masukan adonan yang sudah di bentuk kedalam air yang sudah mendidih\", \"Tunggu adonan hingga matang / cilok mengapung di atas permukaan air panas\", \"Angkat dan tiriskan\", \"Cilok siap disantap\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1965, 2, 'Udang balado', 'Udang balado dengan udang segar dan bumbu khas.', '[\"1/2 kg udang\", \"bumbu halus:\", \"5 bawang putih\", \"10 bawang merah\", \"10 cabe merah\", \"sesuai selera cabe rawit\", \"1 bungkus royco\", \"garam\", \"gula\"]', '[\"Buang kepala udang lalu cuci bersih, sisihkan\", \"Blender bumbu halus\", \"Panaskan sedikit minyak lalu masukkan bumbu yang sudah di blender\", \"Jika bumbu sudah mendidih masukkan udang\", \"Tes rasa, sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1966, 2, 'Mie Goreng Udang By Bunda Les', 'Mie Goreng Udang By Bunda Les - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 bks mie telur,rebus dgn sedikit minyak,tiriskan\", \"1 butir telur\", \"1 batang wortel iris korek api\", \"Kol secukupnya,iris halus\", \"10 ekor udang\", \"Sedikit kecap\", \"1 btg daun bawang\", \"Bumbu halus\", \"3 butir bawang putih\", \"2 butir kemiri\", \"Sedikit garam untuk memudahkan mengulek\", \"1 bks masako sapi\", \"Sedikit lada halus\", \"Minyak goreng untuk menumis\"]', '[\"Campur mie dgn kecap hingga rata\", \"Panaskan minyak goreng,tumis bumbu halus hingga wangi,masukkan telur,orak arik,masukkan udang..masak hingga udang berubah warna..\", \"Tambahkan sedikit air,masukkan wortel dan kol..masak sampai sayuran layu dan air asat\", \"Kecilkan api, masukkan mie,masako,lada halus,aduk rata..koreksi rasa\", \"Masukkan daun bawang..aduk sebentar..sajikan..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1967, 3, 'Bakwan Sayur dan Udang', 'Buat Bakwan Sayur dan Udang yang nikmat dengan langkah-langkah mudah ini.', '[\"2 buah wortel,serut korek api\", \"Kol diiris halus\", \"1 batang daun bawang,iris halus\", \"1 batang seledri,iris halus\", \"1 buah jagung,dipipil trus ditekan pelan dgn cobek\", \"350 gr tepung terigu\", \"1 sdm tepung beras\", \"1 sdm tepung sagu\", \"1 bks masako sapi\", \"Sedikit lada halus\", \"Bumbu halus\", \"3 butir bawang putih\", \"2 butir kemiri\", \"Sedikit garam untuk memudahkan mengulek bumbu\", \"secukupnya Minyak goreng\", \"25 ekor udang yg sudah dibersihkan dan dibuang kepalanya\", \"Air matang\"]', '[\"Campur semua bahan dan tambahkan air sampai tercampur rata jgn terlalu encer atau kental yaa..koreksi rata..\", \"Panaskan minyak,rendam sendok sop sampai panas,angkat sendok sop,isi dgn 2 sendok makan adonan bakwan,taruh seekor udang diatasnya..goreng sampai terlepas dr sendok sopnya..kalo msh nempel,bantu congkel dgn sendok..goreng sampai keemasan..\", \"Taraa..siap dihidangkan..aq msh punya bumbu siomay semalam. Tinggal cocol dehh..pakai saos sambal jg mantap..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1968, 3, 'Udang Goreng Saus Padang', 'Udang Goreng Saus Padang dengan udang segar dan bumbu khas.', '[\"500 gr udang, buang kepalanya, cuci bersih, lumuri jeruk nipis\", \"5 siung bawang merah, iris\", \"3 siung bawang putih, iris\", \"10 biji cabe rawit merah, iris\", \"1 ruas jahe, geprek/memarkan\", \"2 sdm saus tiram\", \"2 sdm saus tomat\", \"1 sdm kecap manis\", \"1/2 sdt garam (saus tiramnya sudah asin)\", \"1/2 sdm merica\", \"1 batang daun bawang, iris\", \"3 batang daun seledri, iris\"]', '[\"Goreng udang sampai matang (sebentar saja), kemudian sisihkan\", \"Tumis dengan minyak (1 sdm, sisa gorengan udang): bawang merah, bawang putih, jahe, cabe rawit\", \"Masukkan saus tiram, saus tomat, kecap manis, garam, merica\", \"Aduk sampai bumbu meresap\", \"Koreksi rasa sesuai selera\", \"Hidangkan bersama taburan daun bawang dan daun seledri\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1969, 2, 'Tumis Wortel jagung udang', 'Tumis Wortel jagung udang - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"3 bh wortel potong korek\", \"1 bh jagung pipil atau serut\", \"1/4 udang\", \"1 btg daun bawang iris\", \"1 bh tomat\", \"secukupnya Bawang merah Bawang putih\", \"secukupnya Cabe rawit dan cabe merah\"]', '[\"Goreng udang terlebih dulu, rebus wortel agar empuk. Tumis semua bumbu, masukkan sayuran dan udang. Tambahkan lada, garam, gula, dan penyedap (optional) aduk.koreksi rasa. Jadi deh 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1970, 3, 'Ampal udang debm', 'Resep Ampal udang debm yang lezat dan mudah dibuat di rumah.', '[\"500 gram udang\", \"1 btr telor\", \"1 sdm tepung keto\", \"1 sdm minyak wijen\", \"2 siung bawang putih\", \"1/2 sdt ketumbar\", \"Secukupnya garam\"]', '[\"Masukan smua bahan dalam food procesor.bisa jg pakai blender.proses sampai smua halus dan tercampur rata.\", \"Goreng sesendok demi sesendok sampai kuning keemasan.\", \"Enak bgt d makan sama cabe,saos sambal atopun mayones\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1971, 3, 'Sate Udang Goreng', 'Resep Sate Udang Goreng yang lezat dan mudah dibuat di rumah.', '[\"6-8 ekor udang (biarkan utuh)\", \"5-6 siung bawang putih\", \"1 ruas kunyit\", \"1/2 buah jeruk nipis\", \"Tusuk sate\", \"Secukupnya penyedap, garam\"]', '[\"Siapkan bahan yang diperlukan.\", \"Cuci bersih udang lalu beri perasan jeruk nipis, biarkan beberapa menit\", \"Haluskan bawang putih dan kunyit lalu beri secukupnya garam dan penyedap.\", \"Baluri udang dengan bumbu halus, biarkan beberapa menit.\", \"Lalu goreng hingga kering angkat dan tiriskeun.\", \"Siap disajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1972, 4, 'Mie goreng udang sosis', 'Mie goreng udang sosis dengan udang segar dan bumbu khas.', '[\"1 bungkus mie telur\", \"3 siung bawang merah, cincang halus\", \"4 siung bawang putih, cincang halus\", \"1 btr telur, kocok\", \"1 btg daun pre/daun bawang, potong2\", \"Secukupnya sosis, potong2\", \"Secukupnya udang\", \"1 sdm kecap manis\", \"1/2 sdm kecap asin\", \"1/2 sdm saus tiram\", \"1/2 sdm saus inggris\", \"Secukupnya garam gula merica\", \"Secukupnya kaldu jamur\"]', '[\"Rebus mie telur sampai setengah matang, saring, sisihkan dan beri minyak\", \"Tumis bawang merah bawang putih sampai harum, masukkan telur kocok, kemudian udang sosis.\", \"Masukkan mie, kecap manis, kecap asin, saus tiram, saus inggris. Tambahkan air sedikit bila terlalu kering. Bumbui garam gula merica dan kaldu jamur. Aduk rata. Tes rasa.\", \"Terakir tambahkan irisan daun bawang. Sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1973, 2, 'Tumis jagung udang papay', 'Cara membuat Tumis jagung udang papay yang enak dan praktis untuk keluarga.', '[\"5 buah jagung muda (iris serong tipis tipis sesuai selera)\", \"8 buah tahu pong di potong potong dadu\", \"1 buah wortel iris serong\", \"sesuai selera Udang papay , kalo mau pakai teri lebih enek\", \"3 buah bawang merah iris iris\", \"1 buah bawang putih iris iris\"]', '[\"Panas minyak goreng secukupnya, tumis bawang merah dan bawang putih\", \"Masukkan wortel dan jagung muda..\", \"Setelah agak empuk, masukkan lagi tahu pong dan udang papay nya.. Tambahkan garam dan gula secukupnya\", \"Jangan lupa koreksi rasanya\", \"Kalau sdh pas.. Siap deh dihidangkan\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1974, 4, 'Pare Nenek Udang', 'Buat Pare Nenek Udang yang nikmat dengan langkah-langkah mudah ini.', '[\"4 buah pare uk sedang cuci, iris tipis\", \"50 gr udang\", \"Bumbu halus :\", \"2 bawang merah\", \"1 bawang putih\", \"1 kemiri\", \"1/2 ruas kunyit\", \"1/4 ruas jahe\", \"1/4 sdt terasi\", \"Bumbu tambahan :\", \"2 rawit setan, iris tipis\", \"3 cabe merah keriting, iris tipis\", \"1 lbr daun salam\", \"Kecap manis\", \"Garam\", \"Gula pasir\", \"Gula merah\"]', '[\"Cuci pare dg garam, remas2 smpe keluar air..buang air nya, bilas dg air bersih sampai 3 kali agar tidak pahit.\", \"Ulek halus bahan bumbu halus di atas.\", \"Goreng pare sampai setengah kering (saya tidak terlalu kering 😁) tiriskan.\", \"Panaskan 2 sdm minyak goreng, tumis bumbu halus + cabe iris, daun salam sampai harum masukkan udang, tumis sampai udang berubah warna.\", \"Masukkan pare yg sdh di goreng, tumis sampai pare berbalur rata bumbu, beri garam, gula pasir, gula merah, kecap manis, beri sedikit air. Tes rasa, masak sampai air menyusut dan pare matang.\", \"Sajikan dg nasi hangat 😊😉\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1975, 2, 'Udang Goreng Tepung Pedas', 'Cara membuat Udang Goreng Tepung Pedas yang enak dan praktis untuk keluarga.', '[\"1/4 udang buang kulit dan kepala\", \"1 sdm air jeruk\", \"3 sdm Tepung serbaguna crispy hot spicy (saya pake merk sasa)\", \"Tepung serbaguna crispy original (saya pake merk kruawang thip thailand)\", \"1 telur (kocok lepas)\", \"Minyak goreng\"]', '[\"Rendam udang dengan air jeruk 10 menit, lalu cuci bersih. Tiriskan\", \"Setelah ditiriskan cambur udang dengan bumbu hot spicy. Masukan ke adonan telur, angkat dan balur ke tepung crispy original\", \"Goreng di minyak panas. Angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1976, 4, 'Balado udang pete', 'Hidangan seafood nikmat: Balado udang pete untuk pecinta udang.', '[\"250 gram udang\", \"4 buah pete\", \"Bahan halus:\", \"4 siung bawang merah\", \"3 siung bawang putih\", \"3 kemiri\", \"3 cabe besar\", \"10 cabe rawit\", \"2 sendok Kecap bango\", \"secukupnya Garam\", \"secukupnya Air\", \"secukupnya Sasa\"]', '[\"Cucu bersih udang\", \"Tumis bumbu halus sebentar saja\", \"Masukkan pete\", \"Lalu udang\", \"Tambahkan garam dan sasa\", \"Tunggu udang hingga berubah warna icip icip rasa\", \"Ok siap di hidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1977, 3, 'Udang kuah bumbu', 'Udang kuah bumbu dengan udang segar dan bumbu khas.', '[\"1/2 kg udang\", \"2 lembar daun jeruk\", \"5 buah cabe rawit\", \"1 buah cabe merah\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"3 buah kemiri\", \"1 barang serai\", \"1 ruas laos\", \"1 ruas kunyit\", \"Sedikit jahe\", \"Secukupnya lada bubuk\", \"Secukupnya garam\", \"Secukupnya gula & penyedap rasa\"]', '[\"Cuci bersih udang,memarkan serai,laos..\", \"Ulek bahan bumbu seperti bawang merah,bawang putih,kemiri,kunyit,jahe,cabe tambahkan secukupnya lada bubuk,garam,gula & penyedap\", \"Panaskan sedikit minyak d wajan masukkan ulekan bumbu beserta laos dan serai,tumis hingga harum\", \"Tambahkan air secukupnya lalu masukkan udang.. Aduk sebentar hingga berubah warna udang menjadi agak merah\", \"Tutup sebentar udang agar daging udang masak merata,kemudian buka tutup wajan biar kan kuah hingga menyusut sedikit,\", \"Cek rasa,jika di rasa sudah pas udang kuah bumbu siap di hidangkan, selamat mencoba 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1978, 2, 'Udang nugget balado', 'Buat Udang nugget balado yang nikmat dengan langkah-langkah mudah ini.', '[\"250 gram udang\", \"10 buah nugget ayam\", \"3 sdm cabe giling kasar\", \"2 gelas minyak utk menggoreng\", \"Secukupnya air\", \"Secukupnya garam\", \"Secukupnya penyedap\"]', '[\"Cuci udang dan buang kepala nya\", \"Potong nugget menjadi 2\", \"Panaskan minyak dan goreng nugget\", \"Setelah itu goreng udang\", \"Tumis cabe kasar beri garam, penyedap, dan sedikit air\", \"Lalu masukkan nugget dan udang kedalam cabe, aduk rata setelah matang sajikan😉\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1979, 4, 'Pepes udang kemangi', 'Sajian Pepes udang kemangi yang praktis dan lezat untuk dinikmati bersama.', '[\"250 gr udang\", \"500 gr tahu,dihaluskan\", \"sesuai selera Cabe\", \"5 cm kunyit\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"1 ruas jari lengkuas\", \"3 lembar daun jeruk\", \"Segenggam kemiri\", \"3 buah telur\", \"sesuai selera Garam\", \"sesuai selera Daun kemangi\", \"Daun pisang untuk membungkus\"]', '[\"Haluskan duo bawang,daun jeruk,lengkuas,kunyit,cabe,kemiri (jika menggunakan blender dan menambahkan air sebaiknya tahu diperas dulu sebelum menghaluskannya)\", \"Haluskan tahu yg sudah diperas lalu campur dgn bumbu\", \"Tambahkan garam,kalo kurang asin tambahkan lg\", \"Masukkan udang yg sudah dikupas dan telur,kemudian aduk rata dan masukkan daun kemangi\", \"Siapkan daun pisang untuk membungkus,masukkan 2sdm pepes atau sesuai selera\", \"Kukus kurleb 30 menit atau sampai keluar aroma pepes\", \"Bisa jg ditambahkan cabe hijau yg dirajang untuk yg doyan pedas\", \"Fungsi telur adalah untuk memadatkan pepes\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1980, 4, 'Sayur tumis pakis udang', 'Sayur tumis pakis udang dengan udang segar dan bumbu khas.', '[\"2 ikat sayur paku/pakis\", \"udang yang ukuran kecil2\", \"2 buah cabai keriting\", \"2 buah bawang putih\", \"2 buah bawang merah\", \"2 buah tomat\", \"minyak untuk menumis\", \"sedikit air\", \"garam\", \"gula\", \"saus tiram\"]', '[\"Potong sayur pakis, cuci dan tiriskan.\", \"Cuci bersih udang dan tiriskan.\", \"Panaskan minyak, Iris tipis bawang merah, bawang putih dan cabai. Lalu tumis hingga berwarna kemerahan.\", \"Kemudian masukkan tomat yg sebelumnya jg telah diiris tipis. Lalu masukkan saus tiram.\", \"Setelah tomat layu, masukkan udang dan sayur pakis. Lalu tambahkan sedikit air.\", \"Masukkan garam, dan gula. Tunggu hingga semua matang.\", \"Koreksi rasa, daaaaan fuallaaaaaa 😊😊 sayur pakis siap dihidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1981, 3, 'Udang Pete Saos Tiram Pedes', 'Cara membuat Udang Pete Saos Tiram Pedes yang enak dan praktis untuk keluarga.', '[\"1/2 kg Udang\", \"Pete (jumlah sesuka hati)\", \"1 batang serai\", \"2 cm laos\", \"4 lembar daun jeruk\", \"Minyak gorang\", \"bumbu halus\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"1 tomat besar\", \"sesuka hati Cabai merah dan cabai rawit\"]', '[\"Bersihkan dan kupas cangkang udang. Siapkan minyak goreng dan masak udang hingga kemerahan /setengah matang.\", \"Haluskan Bumbu halus, kemudian tumis sampai harum.\", \"Masukkan daun jeruk, laos dan serai ke tumisan bumbu halus, kemudian masukkan udang dan pete.. Masak hingga matang. Sajikan dengan penuh cinta.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1982, 3, 'Udang Saos Barbeque', 'Sajian Udang Saos Barbeque yang praktis dan lezat untuk dinikmati bersama.', '[\"250 gr Udang\", \"1 bh bawang Bombay kecil\", \"3 siung bawang putih\", \"3 buah cabe merah besar (bisa ditambah rawit klo mau lebih pedas)\", \"2 sdm saos barbeque (saya pakai merk delmonte)\", \"1 sdm saos tiram\", \"1/2 sdm kecap manis\", \"2 sdm saos tomat\", \"Garam\", \"Gula\", \"Merica\", \"secukupnya Air\"]', '[\"Tumis duo bawang n cabe merah smpai wangi, masukkan saos barbeque, saos tiram, saos tomat, dan kecap.\", \"Masukkan udang yg sdh dibersihkan sebelumnya, kemudian masukkan air sesuai selera.\", \"Masukkan garam, gula, n merica. Masak hingga mendidih.\", \"Sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1983, 3, 'Martabak Mini Tahu Udang', 'Buat Martabak Mini Tahu Udang yang nikmat dengan langkah-langkah mudah ini.', '[\"Secukupnya kulit lumpia (saya pake merek finna)\", \"3 butir telur ayam, bisa telur bebek\", \"2 buah tahu putih, rebus dengan sedikit garam\", \"Secukupnya udang, bersihkan cangkang2nya\", \"Secukupnya daun bawang dan seledri\", \"Secukupnya garam, lada bubuk, dan kaldu jamur\", \"Minyak untuk menggoreng\"]', '[\"Potong2 kecil udang kemudian goreng sebentar. Sisihkan\", \"Potong2 kecil tahu, daun bawang, seledri\", \"Kocok telur dan bumbu2. Masukkan potongan tahu, udang, dan daun bawang seledri. Aduk rata\", \"Siapkan kulit lumpia, isi dan lipat sesuai selera.\", \"Goreng sampai matang. Sajikan hangat2 dgn cabai rawit dan teh hangat\", \"Note : jumlah isian harus lebih banyak dari telur, jika tidak maka nanti isian akan basah sekali saat dilipat dan membuat kulit gampang sobek\", \"Tips : sebaiknya panaskan dulu minyak di wajan. Jadi setelah melipat kulit lumpia bs langsung digoreng. Jika terlalu lama didiamkan maka telur bs merembes. Sebaiknya buat 1 langsung digoreng. Begitu seterusnya\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1984, 3, 'Udang Teriyaki', 'Udang Teriyaki - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"250 gr udang yg besar\", \"1 bawang bombay potong besar2\", \"2 bawang putih geprek lalu cincang kasar\", \"3 sdm saus teriyaki (aku pake saori)\", \"1 sdm margarin untuk menumis\"]', '[\"Cuci bersih udang, buang kepalanya & kupas kulitnya lalu potong2 sesuai selera yah. Bisa juga gak dikupas ya, tapi ini aku kupas udangnya soalnya buat sibocil, dia belum bisa ngupas udang, biar ga ribet makannya.\", \"Tumis bawang bombay & bawang putih dengan margarin sampai wangi lalu masukkan udang. Aduk2 sampai udang berubah warna\", \"Masukkan saus teriyaki, masak sampai udang matang & saus menyusut\", \"Sajikan hangat2, pake nasi putih anget, dijamin si bocil lahap makannya 😄😄\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1985, 3, 'Udang goreng Tepung saus Asam Manis', 'Buat Udang goreng Tepung saus Asam Manis yang nikmat dengan langkah-langkah mudah ini.', '[\"250 gram udang, bersihkan,cuci, tiriskan\", \"Bahan pelapis :\", \"4 sdm tepung terigu\", \"1 sdm tepung maizena\", \"1 sdm tepung bumbu, instan\", \"1/4 sdt masing2 garam dan merica\", \"1 butir telur ayam, kocok asal\", \"50 ml - 60 ml air matang\", \"Saus asam manis :\", \"2 siung bawang putih\", \"1 buah bawang bombai kecil\", \"1 buah tomat, rebus, buang kulitnya\", \"1/2 buah buah nanas\", \"1/2 batang wortel, potong bentuk korek api\", \"2 sdm pasta tomat/sambal tomat\", \"1 sdt kecap asin\", \"1/2 sdt masing2 merica dan gula pasir\", \"100 ml air matang\", \"1 sdt tepung maizena+1 sdm air, untuk pengental kuah (saya skip)\"]', '[\"Campur tepung terigu, maizena, tepung bumbu, garam, merica, telur kocok dan air. Masukkan udang, aduk sampai terbalut tepung.\", \"Goreng satu persatu hingga kedua sisinya berwarna kuning keemasan. Angkat, tiriskan minyaknya.\", \"Potong-potong bawang putih, bombai, wortel, nanas dan tomat rebus.\", \"Panaskan 2 sdm minyak goreng, tumis bawang putih dan bombai hingga harum. Masukkan wortel, tomat, nanas, pasta tomat, kecap asin, merica, gula pasir dan air aduk, biarkan mendidih. Tes rasa.\", \"Angkat saus, pindahkan dalam wadah.\", \"Hidangkan di piring dengan sausnya.\", \"Penyajian, tata nasi putih, udang goreng tepung lalu siram dengan saus asam manis. Uwh sedap.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1986, 2, 'Udang saus bakso pedas manis', 'Nikmati kelezatan Udang saus bakso pedas manis dengan resep sederhana ini.', '[\"1 kg udang\", \"6 buah bakso sapi\", \"5 lembar daun selada\", \"4 siung bawang merah\", \"2 siunh bawang putih\", \"5 sendok saus tomat\", \"15 biji cabe rawit\", \"3 sendok mentega\", \"secukupnya Air\", \"secukupnya Royco sapi\", \"1 sdm kanji (untuk mengentalkan)\"]', '[\"Rebus air dan masukka 2 sendok mentega\", \"Iris bawang putih, bawang merah dan cabai rawit, lalu masukkan ke dalam rebusan air\", \"Masukkan bakso dan udang. Tutup dengan tutup panci selama 3 menit\", \"Masukkan saus tomat lalu aduk. Setelah merata tambahkan royco sapi. Lalu masukkan selada\", \"Tambahkan kanji yang sudah dicampur dengan air agar kuah mengental, aduk selama 3 menit\", \"Angkat dan tuang ke mangkok, lalu sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1987, 3, 'Sup Tahu Udang Pedas', 'Sajian Sup Tahu Udang Pedas yang praktis dan lezat untuk dinikmati bersama.', '[\"5 buah tahu (potong kotak)\", \"250 gr udang kupas\", \"5 buah bawang merah\", \"4 buah bawang putih\", \"4 buah cabe merah keriting\", \"5 buah cabe rawit setan\", \"1 buah kemiri\", \"secukupnya Garam\", \"secukupnya Lada halus\", \"secukupnya Kaldu jamur\", \"secukupnya Minyak goreng\", \"secukupnya Susu putih (SKM yg dicairkan)\"]', '[\"Panaskan minyak, goreng tahu yg sudah dipotong kotak hingga kecoklatan.\", \"Blender bawang merah, bawang putih, cabe merah keriting, cabe rawit setan dan kemiri hingga halus.\", \"Setelah itu tumis bumbu yg sudah dihaluskan, bila sudah harum masukan udang. Tumis hingga berubah warna, lalu masukan tahu. Aduk hingga merata, taburkan garam, lada dan kaldu jamur. Koreksi rasa.\", \"Kemudian tambahkan susu ke dalam masakan, tumis hingga berbau harum dan mendidih. Koreksi rasa, lalu masakan siap dihidangkan.. Selamat mencoba😎\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(1988, 4, 'Pergedel Kentang Udang', 'Resep Pergedel Kentang Udang yang lezat dan mudah dibuat di rumah.', '[\"1/2 kg kentang\", \"7 siung bawang putih\", \"5 butir bawang merah\", \"Secukupnya saledri\", \"1/2 sdt ketumbar\", \"Sedikit pala\", \"secukupnya Udang /diptong kecil kecil\", \"1/2 sdk teh Lada\", \"1 butir Telur  (untuk olesan)\", \"secukupnya Royko\"]', '[\"Kentang dikupas potong kecil2, bersihkan lalu digoreng, dan ditumbuk halus\", \"Bawang putih, ketumbar,lada,pala dihaluskan\", \"Bawang merah diiris lalu goreng\", \"Udang Bumbu halus, saledri, bawang merah goreng dicampurkan ke dlm kentang, lalu di uleni dan dibentuk sesuka kita\", \"Setelah pergedel di bentuk balurkan dgn telur ayam yg sudah dikocok\", \"Goreng dgn api sedang\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1989, 2, 'Kerupuk udang', 'Hidangan seafood nikmat: Kerupuk udang untuk pecinta udang.', '[\"1 kg udang\", \"1.1 /2 tepung kanzi\", \"3 bokol bawang puti\", \"Secukupnya Garam  sm penyedap rasa secukup nya\"]', '[\"Udang di rebus sampe berubah warna\", \"Bawang puti jae di belender lalu. Udang klu sudah dingin di belender sama air rebus tdi kalu sudah di rebus lagi sampe benar2 mendidi. Dn tepung kanzi di taruk di bak setelah mendidi di tuangkan ke kanzi sedi kit demi sediki di aduk sm entong kayu. Setelah jdi adonan lalu di kukus sampe mengenyal lalu di dingin kan kalu sudah dingin dn keras baru bisa di iris dn di jemur sampe kering baru bisa d goreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1990, 3, 'Nasi Goreng Udang Mantapp', 'Resep Nasi Goreng Udang Mantapp yang lezat dan mudah dibuat di rumah.', '[\"secukupnya Udang kupas\", \"secukupnya Nasi\", \"3 Bawang putih\", \"1 Bawang merah\", \"secukupnya Cabe merah, rawit\", \"Minyak goreng untk menumis\", \"secukupnya Garam\", \"secukupnya Gula\"]', '[\"Haluskan bawang merah, bawang putih, cabe\", \"Tumis sampai harum\", \"Masukkan udang, tumos hingga kemerahan\", \"Masukkan nasi\", \"Beri garam, gula secukupnya\", \"Aduk sampai merata\", \"Tes rasa\", \"Angkat, sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1991, 2, 'Tumis udang kangkung', 'Resep praktis Tumis udang kangkung yang bisa dicoba di rumah.', '[\"Udang\", \"1 iket kangkung\", \"Cabe merah (potong serong)\", \"Cabe rawit (potong serong)\", \"Bawang merah (iris tipis)\", \"Bawang putih (iris tipis)\", \"Garam / penyedap rasa\"]', '[\"Cuci bersih udang, jangan lupa buang kepalanya\", \"Pilih kangkungnya, ambil ujungnya saja, cuci bersih\", \"Tumis bawang merah, bawang putih, cabe merah, cabe rawit, hingga layu\", \"Masukan udang, oseng hingga udang berubah warna jadi merah, tambahkan air, masukan garam / penyedap rasa (saya pake masako ayam) lalu masukan kangkung, aduk rata\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1992, 4, 'Sup Jagung Udang (Shrimp Corn Soup)', 'Resep Sup Jagung Udang (Shrimp Corn Soup) ala rumahan yang dijamin menggugah selera.', '[\"1/2 kg udang (sebagian dihaluskan)\", \"1 Jagung pipil (sebagian dihaluskan)\", \"1 siung bawang putih\", \"1 sdm susu bubuk\", \"200 ml air + 1 sachet kaldu ayam (lebih baik kaldu bikin sendiri)\", \"Larutan maizena\"]', '[\"Haluskan sebagian udang dan jagung dan 1 siung bawang putih\", \"Masukan udang yang sudah dihaluskan kedalam panci kecil, tambahkan larutan kaldu. Aduk perlahan.\", \"Masukan jagung pipil, rebus tunggu sampai air mendidih dan pipil jagung matang\", \"Masukan sisa udang, aduk perlahan lahan\", \"Kemudian tambahkan susu (disini saya larutkan susu dengan air kaldu yang sudah didihkan). Lalu aduk lagi perlahan-lahan\", \"Setelah mendidih tambahkan larutan maizena\", \"Selesai\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1993, 4, 'Homemade Soury Shrimp Pasta', 'Hidangan seafood nikmat: Homemade Soury Shrimp Pasta untuk pecinta udang.', '[\"15-20 ekor udang\", \"1/2 bungkus pasta La Fonte\", \"2 medium sliced butter (kira2 aja hehe)\", \"2 tsp oregano\", \"1 medium sliced parmesan cheese(aku pake cheddar karna keabisan)\", \"Secukupnya garam, gula, red pepper powder, lada bubuk\", \"5 siung bawang putih, iris\", \"Secukupnya olive oil\", \"Secukupnya perasan jeruk lemon\", \"Secukupnya daun peterseli (parsley)\"]', '[\"Siapkan bahan\", \"Rebus pasta hingga lunak, tiriskan, kuliti udang, petik bayam, iris bawang putih\", \"Panaskan minyak zaitun, lelehkan butter dan tumis bawang putih.\", \"Tambahkan bubuk cabe, udang, oregano, tumis hingga udang memerah\", \"Masukkan bayam, tumis hingga layu, masukkan pasta yang telah direbus, tumis kembali\", \"Tambahkan garam, gula, keju parmesan, daun peterseli dan perasan air jeruk lemon. Tumis hingga matang\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1994, 2, 'Bakwan Sayur Udang', 'Hidangan seafood nikmat: Bakwan Sayur Udang untuk pecinta udang.', '[\"5 sdm tepung terigu\", \"1 sdm tepung beras\", \"3-4 ekor udang, buang kepala, kupas badan, bersihkan, cincang\", \"40 gram wortel, potong korek api tipis\", \"40 gram kol, iris tipis\", \"1 batang daun bawang, iris\", \"1 batang seledri, iris\", \"secukupnya Air\", \"Minyak untuk menggoreng\", \"Bumbu Halus :\", \"2 butir bawang merah\", \"2 siung bawang putih\", \"secukupnya Garam\", \"secukupnya Merica bubuk\", \"Kaldu bubuk (optional)\"]', '[\"Campur semua bahan dan bumbu halus jadi satu, aduk rata.\", \"Koreksi rasa dan pastikan adonan tidak terlalu encer.\", \"Panaskan wajan, beri minyak secukupnya, ambil 1 sendok sayur adonan, lalu goreng sampai kuning keemasan. Aku kebetulan sengaja mencetak dengan sendok sayur.\", \"Hidangkan dengan cabe, atau saus sambal, atau mayonnaise.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1995, 2, 'Udang Balado Simpel', 'Resep Udang Balado Simpel yang lezat dan mudah dibuat di rumah.', '[\"1 kg udang\", \"1/4 kg cabe merah\", \"8 bawang merah\", \"4 bawang putih\", \"1 sdt terasi\", \"1 buah tomat\", \"Air putih/air kaldu\", \"1 buah jeruk nipis\", \"Garam\", \"Gula\", \"Minyak goreng untuk menggoreng\", \"Minyak goreng untuk menumis\"]', '[\"Bersihkan udang...rendam dengan jeruk nipis dan sedikit garam...kurang lebih 15 menit\", \"Blender cabe merah sampai halus. Kalo mau di ulek manual juga boleh\", \"Rahang halus bawang merah dan bawang putih. Tomat potong kecil kecil\", \"Setelah udang direndam jeruk nipis dan garam...cuci bersih kembali. Lalu goreng dengan minyak banyak sampe kering boleh atau mau setengah matang juga boleh. Lalu sisihkan\", \"Panaskan minyak secukupnya. Tumis bawang merah lalu bawang putih sampe harus. Lalu masukkan tomat. Masukkan terasi. Masak sampai layu\", \"Kemudian masukkan cabe merah yang sudah di blender/ilegal. Lalu tambahkan air/air kaldu...sedikit saja supaya cabe nya matang\", \"Tambahkan gula garam...koreksi rasa. Masak terus sampe warna cabe nya jadi merah tua\", \"Masukan udang yang sudah di goreng. Aduk aduk. tambahkan air/air kaldu sedikit...masak sampai bumbu meresap\", \"Udang balado siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1996, 3, 'Kerupuk nasi+ udang', 'Nikmati kelezatan Kerupuk nasi+ udang dengan resep sederhana ini.', '[\"1 piring nasi\", \"secukupnya Air\", \"150 gram udang\", \"1/2 sdt Baking powder\", \"Garam\", \"Penyedap rasa\", \"Tepung kanji secukupnya (sampai adonan bisa kalis)\", \"Bumbu :\", \"3 sdm ketumbar bulat\", \"10 buah cabe keriting, blender kasar\", \"7 siung bawang putih, blender kasar\"]', '[\"Tahapnya seperti ini, tapi saya uraikan lagi prosesnya.\", \"Rendam nasi 1 jam an, blender nasi+udang+air secukupnya. Masukkan kewadah, masukkan juga bumbu, garam, penyedap rasa. Gauli sampai rata.\", \"Masukkan tepung kanji, uleni sampai kalis.\", \"Bisa dibentuk seperti ini.\", \"Bentuk lenjer besar, jangan terlalu kecil.\", \"Panaskan air, masukkan lenjer ke air mendidih. Rebus sampai lenjer mengapung.\", \"Masukkan kulkas dirak bawah,bukan freezer selama 1 hari. Baru diiris iris.\", \"Jemur kurang lebih 2 hari dibawah terik matahari.\", \"Setelah kering, bisa langsung digoreng. Hasilnya renyah dan enak banget.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1997, 3, 'Udang Tahubun (Untuk Bekal Anak)', 'Udang Tahubun (Untuk Bekal Anak) dengan udang segar dan bumbu khas.', '[\"1 ons Udang Segar (cuci bersih buang kulitnya)\", \"1 Tahu putih yg besar (potong dadu, goreng stengah coklat)\", \"Buncis (potong tipis serong)\", \"5-6 siung Bawang merah (iris)\", \"2 siung bawang putih (yg satu iris, satu geprek)\", \"Cabe merah dan rawit (jika suka pedas)\", \"Garam, gula, saus tiram, penyedap (masako)\"]', '[\"Tumis bawang merah dan putih, aduk sampai setengah matang dan wangi\", \"Masukan udang, aduk hingga udang berubah warna dan matang\", \"Masukan buncis aduk sampai layu dan tuang setengah gelas air, diamkan sampai buncis layu\", \"Masukan tahu, disusul garam, gula, saus tiram sedikit dan penyedap aduk rata koreksi rasa, jika rasa sudah pas. Diamkan sebentar smpai mendidih lalu matikan api. Angkat dan sajikan ✌🏼\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1998, 4, 'Sambal Udang Petai', 'Sambal Udang Petai dengan udang segar dan bumbu khas.', '[\"1/2 kg udang\", \"3 sisir petai\", \"1/2 bombay iris tipis\", \"1 sdm gula merah\", \"3 sdm air asam jawa\", \"2 sdm cabe giling\", \"secukupnya Gula pasir, garam, air, minyak\", \"Bumbu Halus:\", \"10 bawang merah\", \"8 bawang putih\", \"1/2 bawang bombay\", \"1 ruas jahe\"]', '[\"Kupas kepala, kulit dan ekor udang, belah punggungnya, buang kotorannya, cuci bersih, beri perasan jeruk nipis dan garam, goreng sebentar sampe berubah warna, angkat, tiriskan\", \"Sisa minyak menggoreng udang tadi pake uttk menumis (dg api kecil saja) bumbu halus dan cabe giling sampe matang dan keluar minyak, sambil diaduk sesekali\", \"Masukan gula merah, gula pasir, garam, air asam, aduk rata, masak lg sampe agak kental\", \"Setelah agak kental, masukan udang, aduk rata, masak sampai bumbu meresap ke udang, tambahkan air bila terlalu kental\", \"Masukan petai dan bombay iris, masak sampai tingkat kekentalan sambal yg diinginkan ya\", \"Jangan lupa cicipi rasanya. Kalau sudah pas, angkat, sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(1999, 4, 'Bakso Udang cepat kilat', 'Buat Bakso Udang cepat kilat yang nikmat dengan langkah-langkah mudah ini.', '[\"500 gr udang (kupas)\", \"5 sdm tepung kanji\", \"1 butir telur ayam\", \"1/2 sdt garam\", \"Sedikit penyedap rasa\", \"Air Es\"]', '[\"Blender : udang, telur, garam & penyedap.\", \"Didihkan air.\", \"Tuang adonan udang dlm wadah, campur dengan tepung sedikit demi sedikit, sambil di remas2.\", \"Bulatkan adonan dlm kepalan, ambil dgn sendok,. Lgsg masukkn dlm air mendidih. (Bola2 jgn lebih besar dr sendok teh, Krn akan mengembang).\", \"Setelah bakso mengapung, angkat & rendam dalam air es.\", \"Simpan dlm freezer.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2000, 4, 'Tumis/oseng² buncis wortel dg udang+bakso', 'Tumis/oseng² buncis wortel dg udang+bakso dengan udang segar dan bumbu khas.', '[\"200 gr buncis\", \"2 bh wortel\", \"1/4 kg udang tambak,kupas\", \"6 btr bakso\", \"Bumbu :\", \"12 siung bawang merah\", \"4 siung bawang putih\", \"3 bh cabe,blh tmbh\", \"Seruas laos\", \"1 lbr daun salam\", \"Sejumput garam + gula\", \"Secukupnya kaldu bubuk\", \"1 sdt saori\", \"1 bh tomat yg kecil\", \"100 ml air matang\"]', '[\"Siapkan bahan2\", \"Panaskan minyak,lalu goreng sbntar udangnya,ckup smp berubah warna..tiriskan. Lanjut oseng bumbu2.. Tunggu smp harum. Lanjut buncis,wortel,bakso. Tambahkan 100 ml air. Tutup wajan agar cpt matang. Gunakan api sedeng ya\", \"Klo sayuran sdh agak empuk,masukkan udang,aduk2,tutup lagi\", \"Tes rasa..matikan kompor..sajikaan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2001, 3, 'Sambal goreng udang', 'Hidangan seafood nikmat: Sambal goreng udang untuk pecinta udang.', '[\"1/4 udang ukuran sedang (cuci bersih hilangkan kulitnya)\", \"1/2 kg kentang bersihkan kupas potong kecil2\", \"Pete (sy g pakai karna pak sayur ga bawa)\", \"2 lmbr daun salam\", \"2 lmbr daun jeruk\", \"1 ruas lengkuas geprek\", \"1 santan instan (sy pakai kara karna malas peras2)\", \"1 sdt kecap manis\", \"secukupnya Minyak goreng\", \"secukupnya Air putih\", \"Bumbu halus\", \"5 siung bawang putih\", \"5 siung bawang merah\", \"2 bh cabe merah (klu mau warna nya lbh merah tambah 1bh lg)\", \"10 bh cabe rawit\", \"2 btr kemiri\", \"1 ruas jahe\", \"1 ruas kunyit\", \"1 sdt ketumbar jinten\", \"secukupnya Garam\", \"secukupnya Gula\"]', '[\"Siapkan penggorengan goreng kentang smp matang sisihkan\", \"Tumis bumbu halus,daun salam, daum jeruk, lengkuas smpai harum masukan air putih, santan,aduk2 smp mendidih masukan udang aduk2 setelah itu masukan kentang goreng,masukan kecap, garam, gula, koreksi rasa tunggu smp kuah mengental,\", \"Setelah matang siap di sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2002, 3, 'Mie goreng udang polos tanpa sayur', 'Mie goreng udang polos tanpa sayur dengan udang segar dan bumbu khas.', '[\"250 gr mie kuning basah\", \"6 bh udang besar, bersihkan, buang kulitnya dan cincang kasar\", \"2 bh bawang putih iris tipis\", \"7 bh bawang merah iris tipis\", \"Secukupnya garam dan kaldu bubuk\", \"Secukupnya kecap\", \"Sedikit minyak untuk menumis\", \"Sedikit air\"]', '[\"Tumis bawang putih dan bawang merah sampai harum dan kecoklatan\", \"Kecilkan api kompor, masukkan udang cincang, masak hingga udang matang (berubah warna)\", \"Tambahkan sedikit air, lalu masukkan mie\", \"Bumbui dengan garam, kaldu bubuk dan kecap sesuai selera\", \"Masak hingga matang dan tekstur mie sedikit kering\", \"Sajikan hangat 👍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2003, 3, 'Minyak udang', 'Sajian Minyak udang yang praktis dan lezat untuk dinikmati bersama.', '[\"250 gr kepala dan kulit udang\", \"2 siung bawang putih\", \"secukupnya Minyak goreng\"]', '[\"Bawang putih memarkan, cincang halus.\", \"Panaskan minyak.\", \"Masukkan kepala dan kulit udang serta bawang putih.\", \"Goreng hingga kecoklatan. Tunggu minyak agak dingin baru masukkan ke dalam toples kaca.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2004, 4, 'Balado Udang & Kentang', 'Balado Udang & Kentang - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1/4 Udang buang kepalanya\", \"1/4 Kentang potong dadu, goreng\", \"Bumbu Halus\", \"10 buah cabai merah\", \"5 buah Rawit (sesuai selera aja)\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"1/2 terasi goreng\", \"Daun salam\", \"Garam\", \"Royco\", \"Saos sambal (Merk bebas)\", \"Minyak Wijen (dikira kira aja)\"]', '[\"Haluskan semua bumbu halus bawang, cabai,bawang putih dan bawang merah (bisa diulek atau blender), dan terasi goreng\", \"Tumis hingga harum dengan daun salam dan matang lalu masukan udang nya terlebih dahulu masak sampai udang berubah warna\", \"Masukan saus cabai (merk apa aja), kemudian masukan minyak wijen secukupnya tumis sampai meresap ke udang lalu masukan kentang nya\", \"Tumis hingga menyerap semua lalu tambahkan garam dan penyedap Royco, lalu koreksi rasanya, dan sajikan.....😘😘😘\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2005, 2, 'Tumis Udang pete', 'Resep praktis Tumis Udang pete yang bisa dicoba di rumah.', '[\"1/2 kg udang\", \"1 buah jeruk nipis\", \"1 buah tomat\", \"2 papan pete\", \"Bumbu :\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"5 buah cabe rawit\", \"3 buah cabe merah besar\", \"1 sdm saos tiram\", \"1 sdm kecap manis\", \"secukupnya Garam dan gula\"]', '[\"Bersihkan udang, buang kulitnya dan lumuri jeruk nipis, diamkan sebentar\", \"Cincang halus bawang merah dan bawang putih, potong sero ng cabe\", \"Potong tomat menjadi 8 bagian\", \"Bersihkan pete\", \"Panaskan wajan, beri sedikit minyak\", \"Tumis bumbu hingga harum\", \"Masukkan tomat, pete, dan udang bersamaan\", \"Beri saos tiram, kecap manis, garam dan gula\", \"Masak hingga matang\", \"Koreksi rasa angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2006, 3, 'Nugget Udang Tahu (Nugget UHu)', 'Resep Nugget Udang Tahu (Nugget UHu) ala rumahan yang dijamin menggugah selera.', '[\"10 ekor  Udang (kurleb 200gr), dibersihkan dari kulit dan kotoran\", \"2-3 potong Tahu\", \"5 sdm Tepung terigu\", \"4 sdm tepung tapioka\", \"bawang putih\", \"gula, garam, lada bubuk\", \"secukupnya bawang merah\", \"secukupnya tepung panir / tepung roti\", \"2 butir  telor (1 untuk adonan yg 1 lagi untuk menggoreng)\", \"2 buah wortel, dipotong dadu atau sesuai selera\", \"secukupnya seledri dan daun bawang, cincang\", \"Minyak goreng\"]', '[\"Poin ke 4 diblender bersamaan dengan udang, tahu dan telor hingga halus dan merata\", \"Tuang adonan tersebut ke sebuah wadah, kemudian masukkan potongan wortel, seledri dan daun bawang.. aduk sampai rata\", \"Tambahkan tepung terigu dan tapioka yang sudah disiapkn sebelumnya. Sambil diaduk sampai rata\", \"Siapkan loyang bersih, lalu olesi dengan minyak atau margarin\", \"Tuang adonan ke loyang, ratakan\", \"Masukkan loyang berisi adonan ke dalam panci kukusan, kukus selama 30 menit\", \"Angkat dari panci dan tunggu sampai dingin,  setelah itu baru bisa dipotong potong sesuai ukuran yang diinginkan\", \"Tuang tepung panir ke wadah\", \"Ambil potongan nugget yang siap digoreng..\", \"Celupkan potongan nugget ke telor kemudian ke tepung panir. Ulangi 2 kali celupan.. saat di taruh di tepung panir, nugget sambil tekan2 supaya tepung panir bisa melekat dan tidak rontok.\", \"Siapkan penggoreng tunggu sampai minyak panas dan masukkan nugget UHU. Tunggu sampai warna kuning kecoklatan. Angkat dan siap dihidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2007, 3, 'Udang saus', 'Buat Udang saus yang nikmat dengan langkah-langkah mudah ini.', '[\"1 kg udang\", \"5 sium bawang merah\", \"3 sium bawang putih\", \"10 bh rica kecil\", \"1 bks Tepung bumbu sajiku\", \"secukupnya Kecap dan saous sambal abc\"]', '[\"Buang kepala udang dan bersihkan\", \"Tepung sajiku larutkan air sedikt campur udang dalam larutan tepung tersebut\", \"Goreng sampai matang\", \"Aluskan semua bumbu tadi\", \"Setelah udang masak semua bumbu yg di haluskan di tumis jangan lupa berikan garam sedikit gula dan kecap dan saos abc secukupnya\", \"Rasa sesuai selera setelah matang angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2008, 3, 'Nasi Bakar isi Udang Sambal Balado', 'Nasi Bakar isi Udang Sambal Balado - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"300-350 gr Nasi putih\", \"200 gr udang yang sudah di kupas kulitnya\", \"2 tangkai pete ambil isinya (saya skip)\", \"1 batang sereh geprek\", \"1 batang daun bawang iris2 tipis\", \"1 buah tomat potong2\", \"secukupnya Gula garam\", \"secukupnya Minyak\", \"secukupnya Daun pisang\", \"Bumbu yang dihaluskan\", \"7 siung bawang merah\", \"5 siung bawang putih\", \"3 butir kemiri\", \"3 cabe merah besar\", \"10 cabe rawit\", \"1 ruas jahe\"]', '[\"Sebelum mempersiapkan bumbu2, daun pisang dipanaskan terlebih dahulu diatas kompor. Gunanya biar pada saat proses pembungkusan tidak mudah sobek lalu di potong2 menjadi beberapa bagian\", \"Tumis bumbubyang dihaluskan beserta sereh hingga wangi, masukan pete, masak hingga pete agak layu. Masukan udang, masak hingga udang berubah warna\", \"Tambah garam, gula, koreksi rasa. Terakhir masukan daun bawang, tomat, lalu masak hingga matang, angkat, sisihkan\", \"Siapkan daun pisang menjadi 2 lapisan letakan nasi, ratakan dengan sendok nasi, lalu ambil 1-2 sendok makan balado udangnya, bungkus dan sematkan kedua sisi menggunakan tusuk gigi/ lidi\", \"Panaskan teflon, bakar dengan api yang kecil, tunggu hingga daun nya berubah warna (balik sekali saja).\", \"Amgkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2009, 2, 'Cah Buncis Udang', 'Nikmati kelezatan Cah Buncis Udang dengan resep sederhana ini.', '[\"20 batang buncis,potong serong\", \"250 gram udang,siangi\", \"15 buah cabe rawit,potong serong\", \"6 siung bawang merah,iris tipis\", \"4 siung bawang putih,iris tipis\", \"3 sdm minyak goreng\", \"1 sdm saos tiram\", \"1 sdt saos rajarasa\", \"100 ml air\", \"Secukupnya garam dan gula pasir\"]', '[\"Panaskan minyak goreng,tumis cabe dan duo bawang hingga harum\", \"Masukkan udang,aduk rata.\", \"Kemudian masukkan air,garam dan gula pasir,masak hingga udang berubah warna\", \"Masukkan buncis,saos rajarasa dan saos tiram,aduk2. Masak hingga buncis setengah layu. Tes rasa,matikan api.\", \"Sajikan😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2010, 4, 'Pare Udang Masak Taoco ala dapur ku', 'Sajian Pare Udang Masak Taoco ala dapur ku yang praktis dan lezat untuk dinikmati bersama.', '[\"2 buah pare\", \"7 siung bawang merah\", \"5 siung bawang putih\", \"Udang\", \"2 cm Lengkuas geprak\", \"2 cm jahe geprak\", \"3 lembar daun salam\", \"secukupnya Santan (santan kara yang kecil)\", \"Gula dan garam\", \"3 buah cabe hijau iris\", \"2 buah cabe keriting iris\", \"2 buah tomat belah / iris\", \"Cabe rawit (tdk pakai)\", \"4 sendok makan taoco (kira2)\", \"Sedikit minyak untuk menumis\"]', '[\"Potong memanjang pare, buang isi nya, iris. Beri sedikit garam remas2 sampai keluar air lalu bilas dan tiris kan. Menurut primbon 😂 untuk mengurangi pahit nya.\", \"Siapkan wajan, beri sedikit minyak setelah panas masukkan lengkuas, jahe, biar kan sesaat lalu bawang putih aduk sebentar, bawang merah. Setelah itu masukkan udang, sambil diaduk tunggu udang berubah warna.\", \"Masukkan cabe merah, cabe hijau, taoco dan daun salam. Biarkan hingga wangi. Bila suka pedas silahkan tambah cabe rawit lebih mantap deh.\", \"Masukkan air sedikit lalu santan. Karena taoco juga asin jadi hati2 penambahan garam nyan Beri garam sedikit dan gula sedikit. Masukkan pare nya dan tomat.\", \"Sambil sesekali diaduk masak sekitar 10 menit dan koreksi rasa. Pare udang masak taoco siap dihidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2011, 4, 'Pepes Tahu Udang Kemangi + pare', 'Pepes Tahu Udang Kemangi + pare dengan udang segar dan bumbu khas.', '[\"5 kotak tahu putih\", \"1/4 kg udang ukuran sedang. Buang kepala dan ekor, potong2\", \"secukupnya Kemangi\", \"1 buah telur\", \"1 buah pare. Buang isi dan potong 8 bagian\", \"Daun pisang\", \"Bumbu halus :\", \"6 butir bawang merah\", \"3 butir bawang putih\", \"1/2 ons cabe rawit hijau\", \"1/2 ons cabe merah keriting\", \"3 butir kemiri\", \"secukupnya Garam dan gula putih\", \"Kaldu jamur secukupnya (kalo suka)\"]', '[\"Haluskan tahu, campurkan dg udang, bumbu halus, telur dan kemangi. Aduk rata.\", \"Siapkan daun pisang yg sdh dilayukan. Isi pare lalu letakkan adonan tahu diatasnya. Kukus selama 30 menit.\", \"Siap dinikmati 😄\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2012, 3, 'Pepes Tahu & Udang', 'Resep Pepes Tahu & Udang ala rumahan yang dijamin menggugah selera.', '[\"5-7 kotak tahu kuning (me:tahu kediri)\", \"2 butir telur ayam\", \"200 gr udang ukuran kecil (buang kepala & ekornya agar tdk nusuk\", \"1/2 butir jeruk nipis (ambil airnya)\", \"Bumbu :\", \"3 buah cabe merah besar\", \"4 cabe rawit (jika suka pedas boleh ditambah)\", \"4 siung bawang putih\", \"5-6 siung bawang merah\", \"1 buah kemiri\", \"1/2 sdt garam\", \"1/2 sdt gula\", \"1/4 sdt kunyit bubuk\", \"1/4 sdt jahe bubuk\"]', '[\"Bersihkan udang, pisahkan kepala & ekornya lalu beri perasan jeruk nipis 5-10 menit (sambil menyiapkan bumbu) setelah itu bilas & tiriskan\", \"Haluskan semua bumbu\", \"Haluskan tahu. Males nguleg jd dipenyet² dgn whisk mixer hehee\", \"Campur tahu, bumbu, udang & telur aduk rata\", \"Koreksi rasa jika sudah sesuai bungkus daun pisang. Bentuk bungkusan bebass..sy bungkus gini karena keterbatasan daun pisang 😁\", \"Kukus selama 15-20 menit\", \"Siapp disajikan. Bisa langsung ataupun dibakar sebentar agar keluar aroma daun pisang yg gosong² sedapp..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2013, 3, 'Tumis Udang Sederhana', 'Resep Tumis Udang Sederhana ala rumahan yang dijamin menggugah selera.', '[\"1/4 kg udang\", \"7 siung bawang putih\", \"5 siung bawang merah\", \"3 buah cabai merah besar\", \"1 sdm gula pasir\", \"Sejumput garam\", \"7 sdm air matang\"]', '[\"Siapkan semua bahan, cuci bersih udang dan iris tipis-tipis bawang merah, bawang putih, cabai merah\", \"Panaskan minyak/margarin\", \"Masukkan bawang merah, bawang putih, cabai merah, oseng hingga harum\", \"Tambahkan air matang, gula pasir, dan garam. Sesuaikan rasa\", \"Masukkan udang, tumis hingga berubah warna\", \"Tunggu hingga mendidih\", \"Tumis udang sederhana siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2014, 3, 'Sambel goreng kentang pete udang krupuk kulit', 'Resep praktis Sambel goreng kentang pete udang krupuk kulit yang bisa dicoba di rumah.', '[\"1/4 Udang\", \"kg Kentang stengah\", \"2 papan Pete\", \"Krupuk kulit\", \"15 biji  Cabe kriting /blender\", \"2 buah  Tomat /blender\", \"6 siung Bawang merah /blender\", \"5 siung Bawang putih /blender\", \"1 cm Jahe /blender\", \"1 cm Lengkuas /blender\", \"2 bj Daun jeruk\", \"1 bj Jeruk lemon\", \"1 biji Sereh /geprek\", \"3 bj Kemiri\"]', '[\"Potong kentang nya kecil2 lalu goreng, tiriskan\", \"Kupas petenya iris kecil2 lalu goreng jg, tiriskan\", \"Lalu blender cabe kriting jahe lengkuas tomat bawang putih bawang merah kemiri\", \"Trus siapkan minyak panas\", \"Lalu tumis bumbu blendernya ampe harum\", \"Masukan sereh sm daun jeruk nya\", \"Lalu kasi garam gula magic ku ladaku secukupnya sesuai selera yah\", \"Lalu tuang krupuk kulitnya, udang kentang yg sdh di goreng bersm aan dgn pete nya aduk rata lalu kasi perasan jeruk lemon\", \"Lalu hidang kan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2015, 4, 'Udang kecap mentega', 'Resep praktis Udang kecap mentega yang bisa dicoba di rumah.', '[\"1/4 kg udang\", \"Bumbu :\", \"5 buah cabe hijau\", \"3 buah cabe merah\", \"2 buah cabe setan\", \"3 siung bawang putih\", \"5 siung bawang merah\", \"2 lembar salam\", \"secukupnya Laos\", \"secukupnya Jahe\", \"1/2 sdm Margarin\", \"secukupnya Minyak goreng\", \"sejumput Garam\", \"sejumput GulaPasir\", \"secukupnya Kecap manis\"]', '[\"Cuci bersih udang\", \"Iris2 bumbu\", \"Beri minyak goreng dalam wajan masukan bawang putih bawang merah oseng smpe layu masukan cabe Laos salam jahe sambil dioseng(diaduk)tggu sampai wangi masukan udang beri sedikit Aer secukupnya dan kecap garam kemudian gula.koreksi rasa jika sudah enak semuanya beri Aer secukupnya diamkan sampai tak ada Aer baru diberi mentega..\", \"Taram siap disajikan dan selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2016, 3, 'Tumis udang bumbu saus tiram', 'Cara membuat Tumis udang bumbu saus tiram yang enak dan praktis untuk keluarga.', '[\"1 kg udang ukuran besar\", \"bawang merah iris2\", \"bawang putih iris2\", \"cabai merah iris2\", \"jahe\", \"1 buah tomat ukuran sedang potong kecil2\", \"saus tiram\", \"garam\", \"masako rasa ayam\", \"wortel\", \"buncis\"]', '[\"Cuci udang sampai bersih,LALU Tumis bawang merah bawang putih cabai merah dan jahe agak kekuningan lalu masukkan buncis dan wortel udang aduk prlahan2 masukkan tomat ttp sbntar lalu masukkan garam masako dan saos tiram,dan biarkan sbntr dengan api sedang agar bumbu agak kekentalan lalu tes rasa.stlh itu siapkan wadah tumis udang saus tiram siap di santap\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2017, 4, 'Sambal udang tahu petai', 'Cara membuat Sambal udang tahu petai yang enak dan praktis untuk keluarga.', '[\"100 gram udang (buang ekor dan kepala)\", \"3 buah tahu potong kotak\", \"2 papan petai\", \"Lengkuas geprek\", \"Bumbu yang dihaluskan\", \"8 buah cabe keriting\", \"4 siung bawang putih\", \"6 siung bawang merah\", \"1/2 sendok teh terasi\", \"Secukupnya minyak goreng\", \"Secukupnya air\", \"Secukupnya garam, gula dan penyedap jika suka\"]', '[\"Panaskan minyak, tumis bumbu yg sudah dihaluskan dan lengkuas hingga bumbu wangi\", \"Masukan petei aduk-aduk, tambahkan udang, masukan air, masak hingga udang berubah warna.\", \"Terakhir masukan tahu, tambah garam, gula, dan penyedap. Tes rasa dan angkat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2018, 3, 'Udang Pete Balado ala Ugrdkitchen', 'Nikmati kelezatan Udang Pete Balado ala Ugrdkitchen dengan resep sederhana ini.', '[\"Udang seger\", \"5 bawang merah\", \"1 bawang bombai\", \"1 pete\", \"5 cabe merah\"]', '[\"Iris halus bawang bombai\", \"Haluskan bawang merah dan cabe merah dan masukkan garam secukupnnya\", \"Masukkan minyak di wajan lalu masak bumbu halus dan masikkan bawang bombai\", \"Kalo bumbu sudah beraroma harum/matang lalu masukkan udang segar lalu aduk rata\", \"Masukan pete lalu aduk rata sampai matang\", \"Yap! Udang pete balado siap dinikmati. Untuk resep lainnya bisa liat di ig : ugrdkitchen\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2019, 2, 'Oseng Udang', 'Nikmati kelezatan Oseng Udang dengan resep sederhana ini.', '[\"500 gram udang ukuran sedang\", \"1/2 ruas jari Kunyit ()\", \"1 sdm Ketumbar ()\", \"1 sdt Garam ()\", \"secukupnya Gula ()\", \"Minyak goreng\", \"secukupnya Bawang putih\", \"secukupnya Bawang merah\", \"secukupnya Ale\", \"secukupnya Cabe hijau\", \"secukupnya Daun bawang\"]', '[\"Kupas udang buang kulitnya, cuci bersih. Tiriskan.\", \"Buat bumbu halus untuk menggoreng udang, yaitu kunyit, ketumbar, bawang putih, dan garam yang sudah dihaluskan.\", \"Masukkan udang ke dalam bumbu halus dan ratakan.\", \"Sementara bumbu meresap, iris tipis semua bahan, bawang merah, bawang putih, dan cabe. Siapkan juga ale. Serta potong kecil daun bawang. Sisihkan\", \"Goreng udang dalam minyak panas. Minyak jangan terlalu banyak. Cukup untuk memanaskan udang sampai setengah matang. Tiriskan.\", \"Siapkan wajan untuk menumis, beri minyak secukupnya, masukan semua bahan yang sudah diiris tipis ke dalam wajan.\", \"Aduk sampai agak layu, masukkan udang. Tambah garam secukupnya. Tambah gula. Aduk rata. Tes rasa.\", \"Tumis sampai matang. Oseng udang siap dihidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2020, 2, 'Udang Lada hitam', 'Resep Udang Lada hitam yang lezat dan mudah dibuat di rumah.', '[\"1/2 kg Udang berukuran sedang/ besar\", \"4 buah Cabe merah\", \"10 siung Bawang putih\", \"1 buah Tomat\", \"Daun sop/bawang (opsional)\", \"1 buah Jeruk nipis\", \"1 ruas Jahe\", \"3 sachet Saori saos lada hitam\", \"2 sdm Saos tiram\", \"1 sdm Kecap manis\", \"Garam,secukupnya\", \"Gula pasir,secukupnya\", \"Air\", \"Minyak goreng,secukupnya\", \"secukupnya Lada bubuk\"]', '[\"Cuci bersih udang, kemudian diamkan beberapa menit dengan perasan air jeruk nipis\", \"Iris serong cabe merah\", \"Geprek bawang putih dan jahe\", \"Panaskan panci yg berisi air, masukkan udang,bawang putih, jahe, biarkan sampai mendidih dan udang berubah warna\", \"Setelah udang matang,matikan api,\", \"Panaskan wajan,masukkan minyak goreng\", \"Tumis cabe merah dan bawang putih dengan api kecil\", \"Tambahkan saori lada hitam,saus tiram,kecap manis,garam, gula, lada bubuk,koreksi rasa\", \"Masukkan irisan tomat dan daun bawang\", \"Masukkan udang beserta air kaldu nya(untuk kaldu sesuai selera)\", \"Tunggu hingga bumbu meresap dan mengental\", \"Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2021, 2, 'Udang Goreng Polos', 'Resep Udang Goreng Polos ala rumahan yang dijamin menggugah selera.', '[\"1/2 kg Udang, bersihkan tanpa membuang kepala dan kulitnya\", \"5 siung bawang putih, cincang halus\", \"1 sdt garam\", \"1 lt minyak sayur\", \"1/2 sdt lada bubuk\"]', '[\"Panaskan minyak di wajan. Sambil menunggu minyak panas, siapkan udang. Balurkan dengan garam, lada, dan bawang putih (seperti akan menggoreng tempe) Kemudian goreng diminyak panas. Biarkan sampai matang lalu dibalik, kemudian tiriskan.\", \"Tips: pastikan minyak cukup untuk merendam udang dan masukan udang saat minyak sudah panas. Jangan bolak-balik udang selama menggoreng karena akan membuat udang berminyak.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2022, 3, 'Sop bola2 udang dengan kaldu udang', 'Sop bola2 udang dengan kaldu udang - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"700 gr udang ukuran sedang\", \"kaldu:\", \"1500 ml air\", \"kulit dan kepala udang\", \"bola2 udang:\", \"450 gr udang kupas\", \"4 sdm tepung tapioka\", \"1/2 sdt bawang putih halus\", \"1 sdt bawang goreng\", \"secukupnya garam dan merica\", \"bahan sop:\", \"1 buah bawang bombay ukuran kecil\", \"1 sdt bawang putih halus\", \"3 cm jahe digeprek\", \"1 buah wortel ukuran sedang potong2 sesuai selera\", \"1,5 ons buncis potong sesuai selera\", \"secukupnya garam dan merica\", \"2 buah kaldu blok\", \"secukupnya daun bawang dan daun sop\", \"1 sdm minyak wijen\"]', '[\"Bersihkan udang, pisahkan dari kepala dan kulit, kasih perasab jeruk nipis, sisihkan. dari 700gr udang jadi 450gr udang kupas\", \"Kaldu: cuci bersih kepala dan kulit udang, tiriskan.\", \"Sangrai kulit dan kepala udang dengan sedikit minyak sampai berubah warna dan harum. Pindahkan kedalam panci tambahkan 1500ml air masak dengan api kecil untuk mendapatkan kaldu udang.. jangan lupa untuk angkat buih yg muncul pada saat proses bikin kaldu. masak kurleb 1 jam, matikan api, saring air kaldu pisahkan dari kulit dan kepala. sisihkan.\", \"Bola2 udang: blender udang kupas sampai halus. tambahkan 1/2sdt bawang putih, 1sdt bawang goreng, garmer secukupnya dan tepung tapioka. aduk rata.\", \"Bikin bola2 dengan menggunakan 2 buah sendok, goreng dengan api sedang, sisihkan.\", \"Tumis bawang bombay, bawang putih halus dan jahe geprek sampai harum dan layu. masukan tumisan bawang kedalam panci yg berisikan kaldu udang.\", \"Nyalakan kompor, masukan wortel masak sampai agak lunak. masukan buncis, masak sampai semua sayuran lunak. tambahkan bola2 udang, masukan kaldu blok juga garam dan merica koreksi rasa.\", \"Matikan kompor, masukan irisan daun sop dan daun bawang, kemudian masukan minyak wijen, aduk rata. sop bola2 udang siap dinikmati.\", \"Bisa ditambahkan tahu cina dipotong kotak2. pakai udang segar untuk mendapatkan rasa kaldu yg manis dan gurih. kalo suka bisa ditambahkan perasan jeruk sambel pas mau makan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2023, 3, 'Udang saus lada hitam', 'Udang saus lada hitam - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"300 gr udang windu\", \"1 buah cabe merah(iris serong)\", \"1 buah bawang bombay\", \"3 siung bawang putih(cincang halus)\", \"1 bks Saori saus tiram\", \"3 sachet saus cabai indo food\", \"2 sdm saus tomat\", \"2 sdm kecap manis\", \"1 sdt kecap Inggris\", \"1 sdm lada hitam\", \"1 sdt merica\", \"1 sdm butter/margarin\", \"100 ml air\", \"Secukupnya garam, pasir,kaldu bubuk\"]', '[\"Buang kepala dan kulit udang kerat bagian punggung untuk membersihkan kotorannya cuci di air mengalir,beri perasan jeruk nipis marinasi dengan garam dan merica diamkan sejenak\", \"Lelehkan butter/margarin didalam wajan masukan irisan bawang Bombay dan bawang bawang putih cincang tumis hingga harum lalu masukan irisan cabe merah hingga sedikit layu setelah itu baru masukan udang masak hingga berubah warna\", \"Setelah udang berubah warna masukan saus tiram, saus tomat,saus sambal,kecap manis,kecap Inggris\", \"Tambahkan air aduk aduk tambahkan bubuk lada hitam,garam, merica,gula pasir juga kaldu bubuk jangan lupa test rasa masak hingga sedikit mengental bila dirasa cukup matikan api pindahkan kedalam piring saji\", \"Done,udang saus lada hitam siap dinikmati\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2024, 4, 'Sambal goreng kentang udang pete', 'Nikmati kelezatan Sambal goreng kentang udang pete dengan resep sederhana ini.', '[\"1 kg kentang\", \"1/4 udang basah\", \"2 papan pete\", \"Bumbu\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"5 butir kemiri\", \"1 ons cabe merah\", \"1 sdt terasi, garam, gula, penyedap secukupnya,\", \"2 lembar daun salam, 3 lembar daun jeruk, 2 batang serai,\", \"Jahe geprek, laos geprek\"]', '[\"Potong kentang kecil2 goreng sampai matang\", \"Bawang merah di rajang tipis2 sisihkan.\", \"Haluskan bawang putih, kemiri, cabe merah yg sdh dikukus, terasi, dan garam sampai halus,\", \"Kupas pete potong2 dan goreng sebentar aja...cabe merah iris di goreng utk hiasan.\", \"Tumis bawang merah sampai layu, tambahkan bumbu halus, jahe, laos, salam, serai, dan daun jeruk.\", \"Klu sdh harum masukkan udang yg sdh digoreng kemudian masukkan santan kara diicipin rasanya klu sdh pas masukkan kentang goreng...tunggu sampai meresap.\", \"Terakhir masukkan cabe iris dan pete yg sdh digoreng aduk sebentar kemudian matikan kompor.\", \"Sambal kentang udang pete siap dihidangkan...trm kasih.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2025, 2, 'Chesse spaghetti aglio olio with prawn', 'Hidangan seafood nikmat: Chesse spaghetti aglio olio with prawn untuk pecinta udang.', '[\"1 genggam spaghetti(lafonte)\", \"8-10 pcs udang windu\", \"1 buah jeruk nipis\", \"3 siung bawang putih (chopped)\", \"1 sdm butter/margarin\", \"Secukupnya garam, gula pasir juga kaldu bubuk\", \"1/2 sdt merica\", \"Sejumput Italian herbs\", \"Secukupnya bumbu tabur rasa keju\", \"Sedikit air\", \"Garnish\", \"Taburan parsley & oregano\"]', '[\"Buang kepala dan kulit udang kerat bagian punggung untuk membersihkan kotorannya cuci di air mengalir,tambahkan sedikit perasan jeruk nipis marinasi dengan garam dan merica,diamkan sejenak sambil menunggu rebus spaghetti hingga matang jangan lupa tambahkan sedikit minyak biar tidak lengket\", \"Cincang halus bawang putih lalu, masukkan Butter kedalam wajan/teflon lalu tumis bawang putih hingga harum lalu masukan udang masak hingga berubah warna\", \"Setelah udang berubah warna masukan spaghetti beri sedikit air tambahkan bumbu keju tabur, italian herbs, garam gula pasir, kaldu bubuk juga merica jangan lupa test rasa bila dirasa cukup lalu matikan api pindahkan kedalam piring saji\", \"Beri taburan cincang parsley\", \"Done,chesse spaghetti aglio olio with prawn ready to served\", \"Selamat mencoba 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2026, 4, 'Pempek Dos dengan kaldu udang (gurih lembut) 😍😋', 'Pempek Dos dengan kaldu udang (gurih lembut) 😍😋 dengan udang segar dan bumbu khas.', '[\"Bahan untuk biang :\", \"400 ml air kaldu udang (rebus air dengan secukupnya udang segar)\", \"200 gr terigu\", \"Secukupnya garam gula\", \"Kaldu bubuk (boleh skip)\", \"Bahan adonan pempek :\", \"3 btr telur kocok lepas\", \"5 siung bawang putih haluskan\", \"400 gr tepung tapioka\"]', '[\"Dalam wadah masukkan terigu, air kaldu udang, garam dan gula aduk rata.. nyalakan api, masak sambil di aduk aduk sampai menggumpal seperti bubur (api jangan terlalu besar bisa gosong), angkat..biarkan hangat\", \"Pindahkan biang yang sudah tidak panas kedalam baskom. Dalam keadaan hangat tambahkan bawang putih, telur kocok dan kaldu bubuk..aduk rata menggunakan sendok kayu masukkan tepung tapioka sedikit demi sedikit aduk sampai rata\", \"Adonan pempek dos siap di bentuk (saya bentuk pempek lenjer)\", \"Rebus pempek dalam air yg mendidih sampai matang...angkat tiriskan. Saya suka pempek yg spt ini langsung dimakan dengan cuko enakk bgt😋\", \"Yg digoreng juga enakkkk\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2027, 3, 'Udang tepung Sederhana', 'Cara membuat Udang tepung Sederhana yang enak dan praktis untuk keluarga.', '[\"1/2 kg udang\", \"1 buah jeruk nipis\", \"4 siung bawang putih\", \"1 sdm ketumbar\", \"1 tepung sajiku serba guna\", \"1/4 kg tepung biasa\", \"secukupnya garam\"]', '[\"Udang yg sdh dikupas kulitnya, peraskan jeruk nipis dan diamkan 10 mnt\", \"Haluskan bawang putih, ketumbar dan secukupnya garam.\", \"Kedua tepung diberi air secukupnya sampai agak cair dan campurkan halusan bumbu.\", \"Masukan udang kedalam tepung dan goreng.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2028, 4, 'Garang Asem Udang', 'Garang Asem Udang dengan udang segar dan bumbu khas.', '[\"600 gram udang jerbung, pilih yang besar. Cuci dan gunting sungutnya\", \"3 batang serai, memarkan\", \"6 lembar daun jeruk\", \"1 buah tomat merah, potong besar\", \"10 buah belimbing wuluh atau 2-3 buah tomat hijau, potong tebal 1 cm\", \"Optional: 5 mata asam Jawa, bakar\", \"10 buah cabai rawit merah utuh\", \"1 batang daun bawang, iris tipis\", \"secukupnya Garam\", \"1 sdm gula pasir\", \"2 buah jeruk nipis, ambil airnya\", \"Minyak goreng secukupnya (saya menggunakan minyak jagung atau canola)\", \"Bumbu yang dihaluskan:\", \"8 butir bawang merah\", \"5 siung bawang putih\", \"3 butir kemiri\", \"5 buah cabai rawit merah, bisa ditambah atau dikurangi\", \"1/2 sdt merica putih butiran\", \"Sejari kelingking kunyit, bakar\", \"1 sdt garam\"]', '[\"Panaskan sedikit minyak dan tumis bumbu halus hingga harum. Tambahkan daun bawang, serai dan daun jeruk. Tumis sebentar.\", \"- Tambahkan air secukupnya (kurleb 1,5 L) dan asam. Didihkan\", \"- Masukkan udang, tomat, belimbing wuluh/tomat hijau, cabai utuh kemudian bumbuhi dengan garam secukupnya dan gula.\", \"- Masak sebentar hingga mendidih kembali dan kuah meresap.\", \"- Terakhir tambahkan air jeruk nipis.\", \"- Rasakan bila kurang asin, manis atau asam bisa ditambah sekarang.\", \"Bila sudah pas matikan api dan sajikan panas bersama nasi putih hangat dan tempe goreng.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2029, 4, 'Cap Jay Udang', 'Resep praktis Cap Jay Udang yang bisa dicoba di rumah.', '[\"250 g udang\", \"1 ikat pokcay\", \"6 biji jagung kecil\", \"2 buah wortel\", \"1 buah bunga kol (ukuran kecil)\", \"Secukupnya kapri\", \"Secukupnya gubis\", \"3 siung bawang putih\", \"Saos tomat belibis\", \"Secukupnya garam\"]', '[\"Bersihkan sayur dan potong sesuai selera\", \"Bersihkan udang dan hilangkan kepalanya\", \"Geprek bawang putih dan tumis dengan garam\", \"Masukkan udang tumis sebentar\", \"Masukkan air secukupnya\", \"Masukkan saos dan sayur wortel, jagung, dan bunga kol\", \"Tunggu 5 sampai 10 menit\", \"Masukkan kapri, gubis dan pakcoy\", \"Tunggu sebentar, angkat dan hidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2030, 2, 'Shrimp Chilli Sauce', 'Nikmati kelezatan Shrimp Chilli Sauce dengan resep sederhana ini.', '[\"200 gram Udang\", \"2 siung Bawang putih\", \"Jahe\", \"Daun bawang\", \"3 x sendok makan Tepung ubi\", \"Saus sambal 1 x sendok makan\", \"Saus tomat 3 x sendok makan\"]', '[\"Cuci udang dan keringkan dengan paper towel\", \"Kasih garam dan merica\", \"Cincang bawang putih\", \"Cincang jahe\", \"Cincang daun bawang\", \"Untuk membuat saus. Campur saus sambal, saus tomat, gula, kecap asin, tepung ubi dan air\", \"Lumuri udang dengab tepung ubi\", \"Setelah udang berubah warna kemerahan, sisihkan udang ke pinggir. Masukkan bawang, jahe dan daun bawang dan tumis\", \"Setelah masak, campur udang dan masukkan saus\", \"Setelah saus mulai mengental, siap untuk dihidangkan\", \"Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2031, 4, 'Udang cabe bawang', 'Udang cabe bawang dengan udang segar dan bumbu khas.', '[\"secukupnya Udang\", \"Cabe cengek sesuai selera iris lurus aja\", \"Cabe merah keriting sesuai selera iris lurus\", \"15 siung bawang merah iris agak tebal\", \"1/2 bks terasi abc\", \"Gula\", \"Garam\", \"Minyak\", \"1 bh tomat potong dadu\"]', '[\"Goreng udang sebentar. Lalu tumis bumbu bumbu dengan minyak yang agak banyak\", \"Masukkan udang yang sudah digoreng. Tambahkan Gula Garam. Koreksi rasa\", \"Masak agak lama, hingga semua bumbu matang\", \"Siap dihidangkan dengan nasi panas\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(2032, 3, 'Capcay Udang', 'Sajian Capcay Udang yang praktis dan lezat untuk dinikmati bersama.', '[\"Sayur-sayuran untuk capcay (brokoli, wortel, buncis, sawi hijau, sawi putih, daun bawang) bisa di sesuaikan\", \"1 ons udang\", \"4 siung bawang putih\", \"1 sdm saus tiram\", \"1 sdt kecap inggris\", \"secukupnya kecap asin\", \"1 sdm tepung maizena\", \"1 ruas jahe\", \"1 buah jeruk nipis\", \"secukupnya garam\", \"secukupnya gula\", \"secukupnya minyak\"]', '[\"Bersihkan udang, dan berikan perasan jeruk nipis. Diamkan selama 15 menit\", \"Bersihkan dan potong-potong sayuran sesuai selera\", \"Cincang halus bawang putih dan jahe\", \"Siapkan minyak untuk menumis, tunggu sampai panas. Masukan bawang putih dan jahe. Tumis sampai harum\", \"Masukan sayuran yg sudah dipotong\", \"Tambahkan saus tiram, kecap inggris, kecap asin, garam dan gula\", \"Tambahkan gelas air, tunggu sampai matang\", \"Siapkan tepung maizena dan beri 2 sdm air, aduk sampai tercampur rata\", \"Masukan tepung maizena yang sudah di beri air sedikit demi sedikit hingga mendapat kekentalan yang pas.\", \"Tunggu sampai matang, dan capcay siap dihidangkan :))\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2033, 2, 'Peyek udang renyah', 'Cara membuat Peyek udang renyah yang enak dan praktis untuk keluarga.', '[\"250 gr udang kecil, buang kepala, cuci bersih\", \"150 gr tepung beras\", \"Bumbu halus:\", \"3 siung bawang putih\", \"3 buah kemiri\", \"1 sdm ketumbar\", \"secukupnya Garam, penyedap\", \"secukupnya Air\"]', '[\"Ulek bumbu halus.\", \"Siapkan tepung beras, masukan bumbu halus, beri sedikit demi sedikt air. Sampai aga encer. Masukan garam dan penyedap. Cek rasa. Jika sudah pas masukan udang yg telah dibersihkan.\", \"Cetak ditepi pnggorengn. Tipis aja ya biar renyah.\", \"Goreng sampai kuning kecoklatan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2034, 4, 'Gulai Udang Kol Kacang Panjang Labu pedas gurih', 'Sajian Gulai Udang Kol Kacang Panjang Labu pedas gurih yang praktis dan lezat untuk dinikmati bersama.', '[\"1/4 Udang lumayan besar (12 Potong)\", \"1/2 buah Kol\", \"1/2 buah Labu\", \"10 buah Kacang Panjang\", \"1 buah batang sereh geprek\", \"4 buah daun salam\", \"3 buah daun jeruk\", \"2 ruas jari lengkuas geprek\", \"3 sdm Air asam jawa\", \"1/2 butir Santan ( batok kelapa)\", \"Bumbu yang dihaluskan :\", \"20 buah cabe rawit\", \"4 siung bawang merah\", \"2 siung bawang putih\", \"1 buah kemiri\", \"1 sdt ketumbar\", \"1 ruas jari kunyit\", \"1 ruas jari jahe\", \"1 sdt merica bubuk\"]', '[\"Bersihkan udang. Saya lebih suka kepala tidak dibuang. Jadi belah punggung saja untuk buang kotorannya dan potong jari + bagian kepala yg tajam.\", \"Haluskan semua bumbu dan tumis sampai harum beserta bumbu lain\", \"Masukkan air 1 setengah gelas dan masukkan santan. Aduk trs agar santan tidak pecah.\", \"Masukkan udang dan labu. Setelah labu agak matang masukkan kacang panjang dan kol\", \"Beri garam, gula dan penyedap rasa sedikit dan air asam jawa. Cek rasa. Jika cukup, gulai udang kol kacang panjang labu pedas gurih siap di hidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2035, 2, 'Perkedel jagung cheddar (spesial udang dan lembut)', 'Hidangan seafood nikmat: Perkedel jagung cheddar (spesial udang dan lembut) untuk pecinta udang.', '[\"2 bh jagung manis uk jumbo, serut\", \"100 gr daging udang, cincang halus\", \"70 gr keju cheddar, parut\", \"6 sdm tepung terigu\", \"2 bh cabe merah\", \"1 btr telur\", \"200 ml air (secukupnya)\", \"4 siung bawang putih\", \"1/2 sdt baking powder\", \"1 sdt lada\", \"secukupnya Garam dan kaldu bubuk\", \"secukupnya Seledri, daun kucai, dan daun bawang , rajang halus\", \"Minyak utk menggoreng\"]', '[\"Pertama - tama, blender serutan jagung bersama air, telur, cabe merah, dan bawang putih hingga lumat (blender kasar atau halus sesuai selera saja). Lalu tuang ke wadah mangkuk.\", \"Kemudian campur adonan jagubg dg tepung terigu, baking powder, lada, garam, kaldu bubuk, keju parut, udang, seledr, kucai, dan daun bawang. Aduk rata. Jika terlalu kental bisa ditambahkan air, jika agak encer bisa ditambah tepung terigu.\", \"Lalu panaskan minyak, ambil adonan dg sendok besar, goreng hingga bagian sisi bawahnya kuning keemasan lalu balik. Goreng dg api yg cenderung sedang agar matang merata. Angkat lalu tiriskan\", \"Sajikan dg saus sambal botolan dan cabe rawit\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2036, 2, 'Nasi goreng udang', 'Sajian Nasi goreng udang yang praktis dan lezat untuk dinikmati bersama.', '[\"2 porsi nasi\", \"2 siung bawang putih, cincang kasar\", \"1 iris bulat bawang bombay, potong menjadi 4 bagian\", \"1 butir telur\", \"14 buah udang ukuran sedang, bersihkan\", \"Secukupnya sawi hijau, potong2\", \"3/4 sdm kaldu ayam instan\", \"2 sdm knorr liquid seasoning/ kecap maggi\", \"Secukupnya minyak goreng\"]', '[\"Panaskan minyak goreng, tumis bawang bombay dan bawang putih hingga harum, sisihkan ke pinggir wajan. Ceplok telor dibagian lain wajan, orak arik sampai matang. Masukkan udang, lalu sawi. Tumis sampai matang.\", \"Masukkan nasi, campur rata. Tambahkan kaldu ayam isntan, aduk rata. Terakhir tambahkan knorr liquid seasoning atau kecap maggi, aduk lagi, tes rasa. Siap disajikan klo rasa sdh pas 😘\", \"Ini kaldu ayam instan yg saya pakai.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2037, 2, 'Terung udang pedas', 'Resep Terung udang pedas ala rumahan yang dijamin menggugah selera.', '[\"500 gr terong lalap/udel\", \"250 gr udang (buang kepalanya)\", \"4 buah cabe besar\", \"10 buah cabe keriting\", \"10 buah cabe kecil\", \"1 sdt terasi\", \"4 buah tomat\", \"2 sdm tauco\", \"3 butir bawang merah\", \"2 siung bawang putih\", \"secukupnya Garam\", \"secukupnya Gula\", \"secukupnya Minyak goreng\", \"secukupnya Air\"]', '[\"Belah terong jadi 2.goreng sebentar.sisihkan\", \"Haluskan bumbu,tumis hingga harum.beri kembali sedikit air dan tumis hingga tanak.masukkan udang,aduk hingga berubah warna.masukkan terong dan air sedikit agar semua bahan tercampur.\", \"Tambahkan garam dan gula pasir.tes rasa.aduk sesekali hingga air habis.matikan api.siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2038, 3, 'Tumis udang brokoli minimalis', 'Resep Tumis udang brokoli minimalis yang lezat dan mudah dibuat di rumah.', '[\"1-2 siung bawang putih\", \"1 siung bawang merah\", \"1/4 sdt garam\", \"1 sdt gula (sesuai selera)\", \"1/4 sdt merica\", \"secukupnya Saus teriyaki\", \"secukupnya kecap manis\", \"Brokoli\", \"Udang kupas\", \"2 buah cabai rawit (sesuai selera)\", \"Minyak goreng\"]', '[\"Cincang bawang merah bawang putih dan cabai, potong brokoli sesuai selera, siapkan bahan-bahan lain\", \"Tumis bawang merah dan bawang putih serta cabai yg sudah dicincang sampai harum\", \"Masukkan udang, diamkan sampai berubah warna\", \"Tambahkan sedikit air\", \"Masukkan gula, garam, merica bubuk, cek rasa. Tambahkan dan atur sesuai selera\", \"Masukkan brokoli. Tunggu sampai tampak berubah warna, namun jangan sampe layu\", \"Tambahkan kecap manis dan saus teriyaki. Tunggu hingga kuah mengental\", \"Cek rasa dan sajikan bersama karbohidrat pilihan anda.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2039, 3, 'Pelas udang', 'Nikmati kelezatan Pelas udang dengan resep sederhana ini.', '[\"1 butir kelapa (jangan terlalu tua)\", \"150 gram udang\", \"2 butir telur\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"1 sendok teh ketumbar\", \"1 ruas temu kunci (agak besar)\", \"10 butir cabe rawit\", \"secukupnya Daun salam\", \"secukupnya Garam dan gula\", \"Daun pisang dan tusuk gigi untuk membungkus\"]', '[\"Haluskan bumbu kecuali cabai, lalu campur semua bahan menjadi satu.\", \"Ambil daun pisang untuk membungkus, sebelum adonan di masukan alasi terlebih dahuli dengan daun salam.\", \"Kemudian ambil dua sendok makan adonan, selipkan satu buah cabe rawit.\", \"Lalu kukus kurang lebih 15-20menit\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2040, 3, 'Tumis buncis wortel udang', 'Buat Tumis buncis wortel udang yang nikmat dengan langkah-langkah mudah ini.', '[\"1/4 gr udang\", \"Segenggam Buncis\", \"1 buah wortel\", \"2 Siung bawang putih\", \"4 siung bawang merah\", \"2 buah cabai merah\", \"5 buah cabai rawit\", \"secukupnya Masako ayam\", \"secukupnya Garam\", \"Sedikit gula\", \"50 ml Air\"]', '[\"Cuci semua bahan Iris bawang dan cabai sisihkan. Kemudian iris wortel dan buncis.\", \"Panaskan wajan, masukan minyak goreng secukupnya.. Tumis bumbu sampai harum.\", \"Masukan udang aduk sampai berubah warna. Kemudian masukan sayuran. Tambahkan gula garam dan masako. Kemudian tambahkan air aduk sampai rata.\", \"Diamkan beberapa menit sampai sayuran matang. Setelah matang, kemudian sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2041, 2, 'Udang Saus Asam Manis', 'Udang Saus Asam Manis - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 kg Udang\", \"Secukupnya Bawang Bombay\", \"Secukupnya Cabe merah\", \"5 sdm saus tomat\", \"3 sdm saus sambal\", \"1 sdm saus tiram\", \"Secukupnya garam\", \"Secukupnya gula\", \"Secukupnya penyedap rasa\", \"Secukupnya air\"]', '[\"Tumis bawang bombay dan cabe merah hingga harum\", \"Masukkan saus sambal, saus tomat dan saus tiram\", \"Aduk rata\", \"Masukkan udang nya\", \"Tumis dan aduk hingga tercampur rata\", \"Masukkan garam, gula dan penyedap rasa. Koreksi rasa\", \"Tambahkan air secukupnya lalu aduk kembali. Tunggu bumbu meresap sekitar ±5 menit\", \"Angkat lalu sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2042, 4, 'Batagor Udang', 'Hidangan seafood nikmat: Batagor Udang untuk pecinta udang.', '[\"6 ekor Udang\", \"3 sdm munjung tepung terigu\", \"3 sdm munjung tepung tapioka/kanji\", \"Daun bawang iris halus\", \"1 putih telur\", \"3 siung bawang putih\", \"2 kotak Tahu putih\", \"Lada\", \"Garam\", \"Kaldu sapi/ayam\", \"Sambal kacang instan\", \"Kecap\", \"Saos\"]', '[\"Blender udang dan bawang putih, campurkan dengan daun bawang, tepung terigu, tapioka putih telur aduk rata.. Tambahkan garam, lada bubuk, kaldu kira kira gurih...\", \"Potong tahu putih kecil kecil, tempelkan adonan tadi ke tahu yang telah dipotong potong, lalu goreng...\", \"Cairkan bumbu kacang instan, siramkan ke batagor yang telah digoreng... Tambah kecap/saos seuai selera.. Selesai...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2043, 3, 'Kwetiau Goreng Udang ala Bunda Les', 'Buat Kwetiau Goreng Udang ala Bunda Les yang nikmat dengan langkah-langkah mudah ini.', '[\"1 bks kwetiau (aq pake merk gudang panjang)\", \"3 siung bawang putih,geprek lalu cincang kasar\", \"1 butir telur,kocok lepas\", \"1 batang wortel,potong korek api\", \"Kol,iris halus\", \"10 ekor udang\", \"1 bks bumbu kobe nasi goreng pedas\", \"secukupnya Kecap\", \"Minyak goreng untuk menumis\", \"Sedikit lada halus\", \"Sedikit air\"]', '[\"Panaskan minyak goreng,tumis bawang putih hingga harum kemudian masukkan telur dan udang..aduk2 sampai telur matang dan udang berubah warna..\", \"Tuang sedikit air,masukkan wortel dan kol..tambahkan lada halus..masak sampai matang dan air menyusut..\", \"Masukkan kwetiau,tambahkan bumbu nasi goreng dan kecap..aduk2 sampai rata..koreksi rasa..jangan sampai kematengan ya..\", \"Angkat dan sajikan..yummy..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2044, 2, 'Peyek udang', 'Peyek udang - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1/4 kg udang\", \"1/4 kg tepung beras\", \"secukupnya Air santan\", \"Bumbu halus:\", \"4 siung bawang putih\", \"1 sendok mkn mrica\", \"4 biji kemiri\", \"secukupnya Garam,penyedap rasa\", \"Minyak tuk menggoreng\"]', '[\"Bersihkan udang.buang kepalanya\", \"Campur tepung beras dgn bumbu, penyedap rasa n santan sampai agak encer tp jangan terlalu encer.masukan udangnya.aduk\", \"Panaskan sedikit minyak. Goreng.ambil satu sendok besar peyek.goreng satu2.setangah matang saja.biarkan beberapa waktu kira2 10 menitan\", \"Panaskan minyak agak bnyk lalu goreng lagi sampai matang.kemerahan.angkat!selamat mencobaaa...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2045, 4, 'Sambal goreng udang pedas manis', 'Cara membuat Sambal goreng udang pedas manis yang enak dan praktis untuk keluarga.', '[\"250 gram Udang segar\", \"secukupnya Jeruk nipis\", \"Garam\", \"#Bumbu Halus\", \"5 biji Bawang merah\", \"3 biji Bawang putih\", \"secukupnya Saus tomat\", \"secukupnya Saos sambal\", \"Lada bubuk\", \"Secukupnya cuka\"]', '[\"Kupas udang buang kepalanya,cuci kasih garam dan perasan jeruk nipis...ratakan dan diamkan 10 menit...cuci lagi dan terakhir bilas dg air bersih tiriskan..Goreng...lalu sisihkan\", \"Cincang halus bawang merah...dan haluskan bawang putih...tumis sampe harum...masukan saos tomat saos pedas sedikit garam..sedikit gula pasir...dan secukupnya cuka...masukan udang...tumis tumis koreksi rasa...dan siap di hidangkan...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2046, 3, 'Udang Saos Tomat NC', 'Resep Udang Saos Tomat NC yang lezat dan mudah dibuat di rumah.', '[\"1/2 kg udang ukuran sedang\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"Saos tomat secupnya\", \"Minyak untuk menumis\", \"secukupnya Air\"]', '[\"Bersihkan udang tanpa mengupas kulitnya. Cuci hingga bersih.\", \"Haluskan bawang merah dan bawang putih.\", \"Tumis minyak, masukan bumbu halus. Masukkan udang dan saos tomat. Setelah itu tambahkan sedikit air.\", \"Tunggu hingga udang berubah warna dan mulai matang.\", \"Angkat dan sajikan. Taburi bawang goreng di atasnya sebagai pemanis.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2047, 3, 'Tumis Mercon Udang Terasi', 'Hidangan seafood nikmat: Tumis Mercon Udang Terasi untuk pecinta udang.', '[\"3 rawit setan iris tipis\", \"2 bawang merah iris tipis\", \"1 bawang putih iris tipis\", \"50 gr udang, cincang\", \"Terasi agak banyak (1/2 sdm kurleb)\", \"Secuil garam\", \"Secuil gula pasir\", \"3 sdm air\"]', '[\"Panaskan 2 sdm minyak goreng, tumis bawang merah + putih sampai harum, masukkan rawit tumis sampai rawit layu, masukkan udang cincang, masak sampai udang berubah warna.\", \"Masukkan terasi aduk sambil di penyet agar terasi hancur, beri garam secuil aja (krn trasi biasa nya udah asin), beri sedikit gula pasir. Beri sedikit air, tes rasa. Masak sampai air menyusut.\", \"Sajikan dg nasi hangat. 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2048, 2, 'Gimbal/Bakwan Udang', 'Gimbal/Bakwan Udang - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"7 sdm tepung terigu\", \"secukupnya Air\", \"1/4 sdt gula pasir\", \"secukupnya Udang\", \"1 genggam tauge\", \"3 buah wortel ukrn sedang\", \"secukupnya Cuka masak\", \"Minyak u/ menggoreng\", \"Haluskan:\", \"2 siung bawang putih\", \"1 sdt lada bubuk\", \"2 sdt garam\", \"5 butir kemiri\", \"Pelengkap: Cabai rawit\"]', '[\"Bersihkan udang,buang kepala,kotoran & kulitnya,sisakan ekor nya.Rendam sbntr dgn cuka masak,cuci kembali dgn air bersih,sisihkan.\", \"Cuci bersih tauge,sisihkan.\", \"Kupas wortwl,potong korek api wortel,sisihkan.\", \"Campurkan tauge,wortel,tepung terigu,gula pasir & bumbu halus.Beri air sedikit demi sedikit aduk rata & koreksi rasa.\", \"Panaskan minyak goreng,Ambil 1 sendok sayur adonan bakwan,beri 1 buah udang di atasnya goreng hingga kuning keemasan,lakukan hingga adonan habis,sajikan dgn cabai rawit.\", \"NOTED:\", \"~Jumlah garam & lada sesuaikan selera\", \"~Udang dpt dcuci dgn asam/air jeruk nipis\", \"~Udang dpt tdk dkupas\", \"~Dpt ditambh dgn 1 sdm tepung beras\", \"~Dpt ditambh dgn daun bawang\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2049, 4, 'Udang Asam Manis', 'Nikmati kelezatan Udang Asam Manis dengan resep sederhana ini.', '[\"500 gr udang (buang kepala n kulit luar)\", \"1 bh bawang bombay (iris halus)\", \"4 siung bawang putih (geprek, cacah halus)\", \"1/2 bh jeruk nipis (ambil airnya)\", \"1 sdm mentega\", \"1 sdm saus sambal\", \"1 sdm saus tomat\", \"1/2 sdr gula\", \"Secukupnya garam n merica\", \"25 ml air\"]', '[\"Cuci bersih udang, kasih air perasan jeruk nipis n garam, diamkan 5 mnt lalu cuci lg n tiriskan\", \"Tumis bawang bombay n bawang putih sampai layu n harum\", \"Masukkan udang, masak hingga berubah warna\", \"Kecilkan api lalu masukkan duo saus, gula garam merica n air, aduk rata n masak sebentar hingga air meletup letup\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2050, 4, 'Bihun Udang', 'Bihun Udang - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 Bungkus Bihun\", \"1/2 kg telor puyuh\", \"1/2 Udang\", \"4 buah Wortel\", \"secukupnya Buncis\", \"4 Siung bawang putih\", \"6 Siung bawang merah\", \"Cabe Rawit (sesuai selera)\", \"Garam\", \"Bumbu penyedap\"]', '[\"Bersihkan udang\", \"Kupas dan potong bawang putih, bawang merah & cabe\", \"Kupas dan potong kecil-kecil wortel & buncis\", \"Rebus bihun sampai matang\", \"Siapkan wajan dan panaskan minyak. kemudian masukkan bawang putih, bawang merah dan cabe secara bersama\", \"Masukkan wortel dan buncis. tambahkan sedikit air kemudian biarkan sampai setengah matang\", \"Masukkan udang dan telor puyuh beserta bumbu penyedap\", \"Masukkan Bihun dan aduk sampai bumbu meresap di bihunnya.\", \"Bihun udang siap di sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2051, 3, 'Udang Balado Tahu Petai', 'Sajian Udang Balado Tahu Petai yang praktis dan lezat untuk dinikmati bersama.', '[\"500 gr Udang ukuran sedang\", \"5 papan Petai\", \"1 bh Tahu ukuran sedang\", \"secukupnya Minyak dan Air\", \"Saos Tiram secukupnya (Optional bila suka)\", \"Bumbu Halus :\", \"6 biji Cabai Rawit\", \"3 biji Cabai Merah\", \"5 siung Bawang Merah\", \"3 siung Bawang Putih\", \"1 bh Tomat\", \"1 bungkus Terasi Udang (Saya pakai ABC)\", \"secukupnya Garam, Gula, Lada Bubuk, Bumbu Penyedap\"]', '[\"Bersihkan kepala dan ekor udang, cuci hingga bersih, tiriskan. Potong tahu seperti dadu, goreng setengah matang.\", \"Cuci petai lalu potong sesuai selera.\", \"Uleg atau blender bahan bumbu yg dihaluskan. Lalu panaskan minyak, tumis bumbu dan petai hingga harum.\", \"Masukkan udang dan tambahkan air, gula, garam, lada, dan bumbu penyedap secukupnya. Tambahkan saos tiram jika suka.\", \"Diamkan sejenak lalu masukkan tahu yang telah di goreng tadi. Icip rasa, jika sudah pas, masak hingga matang. Lalu sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2052, 2, 'Udang+Tahu Asam Manis', 'Resep Udang+Tahu Asam Manis yang lezat dan mudah dibuat di rumah.', '[\"250 gr udang (bersihkan)\", \"4 tahu\", \"1/2 Bawang Bombay\", \"1 bawang putih ukuran besar\", \"2 sdm saos tomat\", \"2 sdm saos pedas\", \"2 sdm saos tiram\", \"Secukupnya kecap manis\", \"Secukupnya kaldu (royko)\", \"Secukupnya air\"]', '[\"Pertama, tumis bawang bombay dan bawang putih oseng-oseng hingga wangi dan berubah warna.\", \"Masukin tahu + udang (sebelumnya saya crispy-kan dlu pake tepung roti goreng dan tiriskan) dan tambahkan sedikit air\", \"Masukan bahan-bahan seperti saos pedas+tomat+kecap+saos tiram kemudian aduk lalu tambahkan royko\", \"Cek rasa kemudian 1-2menit matikan kompor dan sajikan.\", \"Jadi deeeeh\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2053, 2, 'Udang masak suka2 gw', 'Resep praktis Udang masak suka2 gw yang bisa dicoba di rumah.', '[\"1/2 kg udang bersihkan\", \"1 bh tomat potong2\", \"2 siung bawang putih\", \"2 siung bawang merah\", \"2 bh cabai rawit merah (merah keriting) iris serong\", \"2 bh cabai rawit setan/belis iris serong\", \"2 lb daun salam\", \"1 cm lengkuas geprek\", \"1 ruas jahe geprek\", \"1/2 bh jeruk nipis\", \"2 sdm saus sambal (pakai saus tomat jg boleh)\", \"1 sdt kecap manis\", \"secukupnya Gula dan garam\", \"secukupnya Royco\", \"secukupnya Merica\", \"1/2 gelas air\", \"3 sdm campuran maizena + air (utk mengentalkan)\"]', '[\"Cuci udang dan kucuri jeruk nipis biar tdk amis, cuci kembali.\", \"Tumis duo bawang dan cabai, masukan lengkuas, salam, jahe, tumis sampai harum.\", \"Masukan udang.\", \"Beri bumbu gula garam, royco, merica, kecap manis, dan saus sambal/tomat.\", \"Beri air.\", \"Tumis2 sampai udang berubah warna.\", \"Beri campuran maizena dg sedikit air agar kuah mengental\", \"Masukan potongan tomat.\", \"Icipi rasa, bila sudah pas matikan api dan sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2054, 2, 'Tumis udang balado', 'Sajian Tumis udang balado yang praktis dan lezat untuk dinikmati bersama.', '[\"1/2 kg udang bersihkan\", \"1 buah tomat besar (sy pake 3 yg kecil2)\", \"2 siung bawang merah\", \"2 siung bawang putih\", \"2 biji kemiri\", \"1 batang serai\", \"secukupnya Garam\", \"secukupnya Minyak\"]', '[\"Bersihkan terlebih dahulu buang kepala\", \"Haluskan semua bumbu\", \"Panaskan minyak goreng dgn api sedang\", \"Tumis semua bumbu\", \"Koreksi rasa bumbu\", \"Setelah bumbuh sudah setengah matang masukan udang bersama serai\", \"Aduk2 tunggu sampai matang\", \"Angkat lalu sajikan dgn nasi hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2055, 2, 'Kaldu udang', 'Nikmati kelezatan Kaldu udang dengan resep sederhana ini.', '[\"70 gr kepala n kulit udang\", \"Bumbu:\", \"1 bawang putih, geprek n cincang\", \"1/4 sdt garam\", \"sejumput penyedap rasa\", \"sejumput lada bubuk\"]', '[\"Sangrai semua bahan, aduk terus sampai kering. Dinginkan lalu blender (ga akan halus karena masih mengandung air. tapi ga apa\\\")\", \"Sangrai kembali sampai benar\\\" kering n blender. Dinginkan n masukkan wadah tertutup.\", \"Setelah selesai, hasilnya 52 gr...lumayan buat simpanan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2056, 2, 'Capcay kuah udang sederhana', 'Hidangan seafood nikmat: Capcay kuah udang sederhana untuk pecinta udang.', '[\"Udang\", \"Bawang putih\", \"Bawang merah\", \"Cabe merah\", \"Kemiri\", \"Gula garam\", \"Penyedap rasa\", \"Daun bawang\", \"Kol\", \"Wortel\", \"Brokoli/kembang kol\", \"Kol\"]', '[\"Haluskan bawang putih bawang merah dan kemiri dan cabe nya\", \"Rebus udang hingga berubah warna\", \"Tumis bumbu halus hingga harum, masukan air kaldu udang dan tambah air secukupnya\", \"Masukan sayuran dan udang\", \"Tambahkan Gula Garam dan penyedap rasa..\", \"Cek rasa dan siap dsajikan..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2057, 4, 'Udang panggang teflon', 'Sajian Udang panggang teflon yang praktis dan lezat untuk dinikmati bersama.', '[\"15 bh udang (krna ini aku sisaan dr 1/2 kg)\", \"1 sdm saos sambal\", \"1/2 sdm kecap\", \"1/2 sdm saos tiram\", \"Secukupnya jeruk nipis (bisa diskip)\", \"Secukupnya garam\", \"Secukupnya mentega\"]', '[\"Cuci udang dan kupas kulit sesuai selera\", \"Diwadah lain siapkan saos sambal, kecap, saos tiram, aduk rata\", \"Marinate udang + bumbu yg sudah disiapkan dan tunggu kurang lebih 30menit (disimpan dikulkas)\", \"Panaskan teflon dengan mentega dan udang siap dipanggang\", \"Bisa disajikan dengan nasi, kalau aku disajikan dengan buncis yg di tumis pakai garlic..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2058, 3, 'Udang Pelangi', 'Hidangan seafood nikmat: Udang Pelangi untuk pecinta udang.', '[\"1/2 kg udang uk sedang\", \"4 cabai merah besar\", \"8 cabai rawit\", \"4 bawang putih\", \"4 bawang merah\", \"Jahe geprak\", \"1 1/2 saset Kecap manis\", \"Gula\", \"Garam\", \"Penyedap\", \"Sedikit tepung maizena\", \"7 batang buncis\"]', '[\"Buang kepala udang\", \"Iris tipis cabai, bawang merah, bawang putih, buncis, jahe geprak lalu tumis..\", \"Masukkan udang tumis.. Lalu tambah sedikit air\", \"Tambahkan kecap, gula, garam, penyedap, tepung maizena, tes rasa\", \"Siap hidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2059, 4, 'Balado udang', 'Buat Balado udang yang nikmat dengan langkah-langkah mudah ini.', '[\"500 gram udang (buang kulit, sisakan buntut kemudian lumuri jeruk nipis)\", \"1 cm laos\", \"2 lembar daun salam\", \"Minyak unuk menumis\", \"Bahan halus\", \"6 siung bawang merah\", \"4 siung mawang putih\", \"10 buah cabe rawit\", \"3 buah cabe keriting merah\", \"3 butir kemiri\", \"1 buah tomat merah\", \"secukupnya Garam dan gula\"]', '[\"Panaskan minyak dalam wajan\", \"Masukkan bumbu yang telah dihaluskan, tumis hingga wangi\", \"Masukkan laos dan daun salam serta garam dan gula. Aduk rata\", \"Masukkan udang, aduk hingga berubah warna. Setelah matang segera hidangkan beserta nasi hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2060, 4, 'Terong Udang SamBalado', 'Resep Terong Udang SamBalado ala rumahan yang dijamin menggugah selera.', '[\"200 gr udang segar\", \"3 buah terong ungu\", \"1 buah tomat merah\", \"1 batang daun bawang\", \"10-15 buah cabai merah keriting (sesuai selera)\", \"3-5 buah cabai rawit merah (sesuai selera)\", \"secukupnya Jeruk nipis\", \"6 siung bawang merah\", \"1 siung bawang putih\", \"secukupnya Garam\", \"secukupnya Gula\", \"secukupnya Air\", \"Minyak goreng\"]', '[\"Bersihkan udang, buang kepala dan kulitnya kemudian rendam 5 menit dengan perasan air jeruk nipis.\", \"Goreng udang dengan api sedang (tidak perlu lama) hanya untuk mengeluarkan aroma asli pada udang.\", \"Cuci dan potong terong ungu (bentuk potongan sesuai selera).\", \"Goreng terong sampai sedikit layu dan wangi.\", \"Haluskan bumbu: cabai, bawang merah dan bawang putih menggunakan blender atau menggunakan ulekan.\", \"Tumis bumbu yg sudah dihaluskan sampai matang dan harum, lalu masukkan udang dan terong yg sudah digoreng terlebih dahulu kemudian aduk beberapa kali sampai bumbu meresap.\", \"Tambahkan air secukupnya, gula pasir dan garam.\", \"Kemudian sebagai pemanis dan penyedap tambahkan tomat merah yg sudah dipotong dadu.\", \"Cicipi rasa, jika sudah pas masakan siap diangkat dan di hias menggunakan potongan daun bawang dan tomat sebagai garnish.\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2061, 2, 'Udang salad', 'Sajian Udang salad yang praktis dan lezat untuk dinikmati bersama.', '[\"Udang, kerat punggungnya, bersihkan, supaya cantik\", \"Lemon\", \"Mayonnaise, beli per kg bole, maestro\", \"Susu\"]', '[\"Rebus udang benar, tiriskan, taruh di piring\", \"Aduk mayoinnaise, lemon sikit dan susu 2 sdm ato takar rasanya\", \"Siram ke udang\", \"Dinginkan ke kulkas satu jam\", \"Salad udang siap di nikmati\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2062, 4, 'Udang Tepung Siram Saus Pedas Manis', 'Cara membuat Udang Tepung Siram Saus Pedas Manis yang enak dan praktis untuk keluarga.', '[\"350 gram udang windu, di kupas kulitnya\", \"250 gram tepung bumbu crispy\", \"3 sdm minyak goreng untuk menumis\", \"1 siung bawang bombay\", \"3 siung bawang putih\", \"5 siung bawang merah\", \"1/2 sdt lada bubuk\", \"1 sdt garam\", \"1 sdm gula\", \"5 sdm saus tomat\", \"5 buah cabai rawit (sesuai selera)\", \"1 buah cabai merah\", \"1 buah tomat\", \"250 ml air\", \"1 sdt kaldu bubuk\", \"2 sdm saus tiram\", \"2 buah tahu potong dadu, di goreng dengan tepung\"]', '[\"Udang yg sudah di kupas, bersihkan lalu lumuri dengan tepung bumbu dan balut sampai tertutup semua bagian udang. Lalu goreng ke dalam minyak panas sampai coklat ke emasan. Tiriskan\", \"Lumuri tahu dengan tepung, lalu goreng sampai coklat ke emasan. Tiriskan\", \"Haluskan bawang putih, bawang merah, cabai dan tomat.\", \"Siapkan wajan dan sedikit minyak untuk menumis, tumis bumbu yang sudah dihaluskan. Masukkan bawang bombay yang sudah di iris halus. Tumis sampai harum\", \"Masuk kan air dan semua bumbu: garam, gula, saus, kaldu. Aduk hingga mengental. Masukkan udang dan tahu yang sudah di goreng. Ke dalam saus\", \"Aduk udang dan tahu dalam saus. Siap sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2063, 3, 'Tumis udang coconut', 'Tumis udang coconut dengan udang segar dan bumbu khas.', '[\"1 genggam udang, kupas kulitnya\", \"1 genggam kelapa parut, sangrai\", \"secukupnya minyak\", \"secukupnya penyedap rasa\", \"bumbu halus :\", \"5 cabe rawit\", \"2 bawang merah\", \"1 bawang putih\", \"secukupnya garam\"]', '[\"Uleg semua bumbu halus, tumis sebentar lalu sisihkan\", \"Panaskan minyak, goreng udang hingga setengah matang\", \"Tambahkan bumbu yang telah di tumis tadi, dan juga kelapa sangrai, aduk hingga tercampur rata\", \"Tambahkan penyedap rasa, koreksi rasa, aduk kembali, tunggu sebentar. angkat lalu sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2064, 3, 'Dadar jagung udang', 'Nikmati kelezatan Dadar jagung udang dengan resep sederhana ini.', '[\"2 buah jagung\", \"1 ons Udang ukuran sedang,buang kulitnya\", \"2 sdm tepung terigu\", \"1 butir telur\", \"Daun bawang\", \"2 siung bawang merah\", \"1 siung bawang putih\", \"1 lembar daun jeruk purut\", \"1/2 sdt Garam\", \"1 sdt Gula\", \"secukupnya Masako\", \"Minyak goreng\"]', '[\"Jagung,bawang putih,bawang merah,daun jeruk,garam,gula,diulek jdi satu..#saya g pake blender soalnya terlalu halus dan berair jdi pake ulekan agar tekstur jagungnya agak kasar\", \"Daun bawang dirajang halus\", \"Kemudian masukan,daun bawang,telur,tepung,penyedap,dan udang\", \"Goreng adonan,sampai berwarna kuning kecoklatan,,,angkat dan tiriskan,dan siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2065, 4, 'Udang tofu siram saus jamur', 'Sajian Udang tofu siram saus jamur yang praktis dan lezat untuk dinikmati bersama.', '[\"1/4 kg udang kupas\", \"1 bh tofu\", \"1 ons jamur merang, belah 4 bagian\", \"1 bh bawang bombay, iris memanjang\", \"4 siung bawang putih, iris\", \"1 batang daun bawang, iris miring\", \"2 sdm saos tiram\", \"1 sdt minyak wijen\", \"Tepung terigu\", \"Tepung maizena\", \"Lada halus\", \"Garam\"]', '[\"Balurkan udang dan tofu yang telah di potong-potong dengan tepung terigu kemudian di goreng hingga matang, sisihkan\", \"Saos jamur: Tumis bawang bombay dan bawang putih hingga harum, kemudian masukan saos tiram dan minyak wijen, tambahkan air secukupnya\", \"Masukan jamur merang, garam, lada (koreksi rasa), masak hingga matang. Kamudian masukan irisan daun bawang.\", \"Larutkan tep maizena dengan air kemudian masukan ke dalam saus jamur yg telah matang, aduk hingga mengental.\", \"Siram/tuangkan saos jamur ke atas udang dan tofu yang telah di goreng.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2066, 3, 'Tumis udang saos tiram', 'Cara membuat Tumis udang saos tiram yang enak dan praktis untuk keluarga.', '[\"1/4 kg udang, buang kulitnya\", \"bumbu halus :\", \"2 siung bawang putih, iris-iris\", \"5 cabe hijau, iris-iris\", \"1/2 sdt lada bubuk\", \"1 batang daun bawang iris kasar\", \"1 sdm saos tiram\", \"1 sdm saos tomat\", \"1 sdt kecap manis\", \"1 sdt tepung maizena (larutkan dengan sdikit air)\", \"secukupnya kaldu bubuk (pakai royco aku)\", \"secukupnya air\", \"secukupnya minyak/margarin\"]', '[\"Tumis bawang putih dan cabe hingga harum, masukkan semua bahan yang tersisa kecuali udang dan larutan tepung maizena.\", \"Masukkan udang, tunggu hingga mendidih\", \"Tambahkan larutan tepung maizena sambil terus di aduk.\", \"Koreksi rasa, angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2067, 3, 'Udang Tumis Cabe', 'Resep Udang Tumis Cabe yang lezat dan mudah dibuat di rumah.', '[\"250 gr udang ukuran sedang (buang kepalanya dan bersihkan)\", \"1 sdm saus tiram\", \"1/2 sdt lada bubuk\", \"1/2 sdt gula pasir\", \"secukupnya garam\", \"secukupnya minyak\", \"bumbu iris :\", \"10 buah cabe ijo\", \"3 siung bawang merah\", \"2 siung bawang putih\"]', '[\"Tumis bumbu iris hingga harum, masukkan udang kupas lalu biarkan hingga matang (warnanya berubah)\", \"Masukkan garam, lada, gula dan saos tiram, aduk-aduk hingga mendidih\", \"Angkat lalu sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2068, 2, 'Udang goreng mendoan', 'Buat Udang goreng mendoan yang nikmat dengan langkah-langkah mudah ini.', '[\"1/4 udang, buang kulitnya\", \"5 sdm tepung terigu\", \"2 helai daun bawang, iris-iris\", \"2 helai daun jeruk, iris-iris\", \"Bumbu halus:\", \"1 sdm ketumbar\", \"1 sdm kemiri bubuk\", \"1/2 sdt kunyit bubuk\", \"2 siung bawang putih\", \"3 siung bawang merah\", \"Secukupnya garam\", \"Secukupnya penyedap rasa\", \"Secukupnya air\", \"secukupnya minyak goreng\"]', '[\"Haluskan semua bumbu kemudian letakkan di atas wadah, tambahkan tepung terigu, irisan daun bawang, daun jeruk dan air hingga menjadi adonan\", \"Masukkan udang satu persatu dalam adonan, lumuri semua bagiannya kemudian goreng dalam minyak panas, lakukan hingga bahan habis\", \"Angkat udang jika sudah berwarna kemerahan, tiriskan lalu sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2069, 3, 'Udang bumbu balado', 'Resep praktis Udang bumbu balado yang bisa dicoba di rumah.', '[\"1/4 kg udang, buang kulitnya\", \"2 helai daun bawang, iris-iris\", \"secukupnya minyak\", \"secukupnya air\", \"bumbu halus\", \"7 buah cabe rawit\", \"3 siung bawang merah\", \"2 siung bawang putih\", \"2 butir kemiri\", \"3 buah cabe hijau\", \"1 sdm bubuk balado\", \"secukupnya gula\", \"secukupnya garam\"]', '[\"Haluskan bumbu lalu tumis hingga harum, tambahkan sedikit air aduk-aduk\", \"Masukkan udang, aduk-aduk, biarkan bumbu hingga meresap, koreksi rasa\", \"Masukkan irisan daun bawang, aduk-aduk sebentar, lalu sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2070, 3, 'Udang panggang bumbu kecap', 'Cara membuat Udang panggang bumbu kecap yang enak dan praktis untuk keluarga.', '[\"secukupnya kecap manis\", \"secukupnya margarin\", \"1/4 kg udang, kupas kulitnya\", \"bumbu halus :\", \"3 bawang putih\", \"3 bawang merah\", \"1 sdm kacang goreng\"]', '[\"Haluskan bumbu halus, kemudian tambahkan kecap manis, aduk hingga rata\", \"Oleskan bumbu pada udang\", \"Cairkan margarin di atas teflon, kemudian panggang udang hingga coklat kemerahan\", \"Sajikan, bisa langsung di makan atau di tambahkan saos tomat untuk cocolannya\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2071, 3, 'Gulai udang mix tahu', 'Gulai udang mix tahu - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1/4 kg udang, kupas kulitnya\", \"3 potong tahu, potong-potong\", \"150 ml santan cair\", \"Secukupnya air\", \"Secukupnya minyak goreng\", \"1/2 sdm gula pasir\", \"1/2 sdt lengkuas bubuk\", \"1/2 sdt serai bubuk\", \"1/2 sdt daun salam bubuk\", \"2 lembar daun jeruk, iris-iris\", \"1/2 sdt kunyit bubuk\", \"1/2 sdt jahe bubuk\", \"1/2 sdt ketumbar bubuk\", \"secukupnya garam\", \"secukupnya minyak\", \"Bumbu halus :\", \"2 bawang putih\", \"3 bawang merah\", \"7 cabe merah rawit\", \"1 butir kemiri\"]', '[\"Uleg bumbu halus, kemudian tumis bersamaan dengan bumbu bubuk hingga harum\", \"Masukkan udang, lalu aduk-aduk hingga berwarna kemerahan\", \"Masukkan tahu, kemudian tambahkan santan hingga mendidih, koreksi rasa\", \"Angkat lalu sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2072, 3, 'Botok Udang Jamur', 'Resep praktis Botok Udang Jamur yang bisa dicoba di rumah.', '[\"250 gram Jamur\", \"Isi Botok:\", \"250 gram Udang\", \"1 Buah Tempe\", \"100 gram Pete Kecil (Lamtoro)\", \"1/2 Buah Kelapa parut (muda)\", \"Bumbu Halus:\", \"25 buah cabe rawit\", \"3 buah Cabe merah besar\", \"3 buah tomat\", \"5 siung Bawang merah\", \"5 siung bawang putih\", \"4 buah kemiri\", \"Secukupnya Ketumbar\", \"Secukupnya garam, gula\", \"Secukupnya penyedap\", \"3 ruas daun pisang\"]', '[\"Bersihkan udang (buang kepalanya), iris2 jamur lalu cuci hingga bersih, potong tempe sesuai selera\", \"Rebus jadi satu diantaranya adalah jamur, tempe, dan pete kecil.\", \"Uleg bumbu hingga halus beri garam, gula dan penyedap rasa secukupnya, koreksi rasa.\", \"Campur jadi satu (jamur, udang, pete, tempe, kelapa) aduk hingga merata.\", \"Bungkus dengan daun berlapis agar daun tidak sobek saat pembungkusan.\", \"Siapkan kukusan, dan dikukus -/+ 30 menit.\", \"Botok siap disajikan dengan nasi hangat 👍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2073, 4, 'Tumis kacang panjang tahu dan udang', 'Resep Tumis kacang panjang tahu dan udang yang lezat dan mudah dibuat di rumah.', '[\"🥗 Bahan utama:\", \"Kacang panjang (potong sesuai selera)\", \"Udang (kupas kulit, belah punggungnya, beri jeruk nipis)\", \"Tahu (potong dadu, goreng setengah matang)\", \"secukupnya Saus tiram\", \"secukupnya Kecap manis\", \"secukupnya Gula pasir\", \"secukupnya Garam\", \"Minyak goreng untuk menumis\", \"Bawang goreng untuk taburan\", \"secukupnya Air\", \"🥗 Bumbu tumis:\", \"Bawang merah (iris tipis)\", \"Bawang putih (iris tipis)\", \"Cabe rawit (iris serong)\", \"Cabe merah keriting (iris serong)\", \"Daun salam\", \"Tomat besar (potong dadu)\"]', '[\"Tumis semua bumbu sampai tomat layu dan harum\", \"Masukkan udang tumis sampai berubah warna\", \"Beri air secukupnya, setelah mendidih masukkan kacang panjang dan tahu\", \"Masukkan saos tiram, kecap manis, gula, dan garam, koreksi rasa\", \"Untuk kematangan sesuai selera ya, mo agak berkuah atau tidak, setelah dirasa cukup bisa diangkat, beri taburan bawang goreng dan dinikmati bersama nasi hangat, yummy...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2074, 4, 'Kangkung Udang Terasi Pedas', 'Hidangan seafood nikmat: Kangkung Udang Terasi Pedas untuk pecinta udang.', '[\"2 ikat kangkung\", \"Secukupnya udang\", \"1/2 buah bawang bombay\", \"Secukupnya kecap manis\", \"Secukupnya garam, kaldu bubuk\", \"Bumbu halus:\", \"2 siung bawang merah\", \"2 siung bawang putih\", \"4 buah cabe merah keriting\", \"1 buah cabe rawit\", \"1/2 bks Terasi\", \"Secukupnya gula merah, sisir\"]', '[\"Tumis bawang bombay sampai agak layu. Masukkan bumbu halus, tumis sampai harum\", \"Tambahkan udang, masak sampai berubah warna\", \"Beri air, bumbui kecap, kaldu, garam & gula merah. Aduk rata, cicipi.\", \"Masukkan kangkung, aduk rata. Tumis sebentar, sesuai selera\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2075, 2, 'Cemplung Udang', 'Cemplung Udang - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"2 genggam udang kupas bersih\", \"2 sdm tepung terigu\", \"1 sdm tepung kanji\", \"1 genggam kelapa parut\", \"1/2 sdm penyedap rasa\", \"secukupnya minyak\", \"secukupnya air\", \"bumbu halus :\", \"1/2 sdt lada bubuk\", \"2 siung bawang putih\", \"1/2 bgks ketumbar bubuk\", \"1 sdm bubuk cabe\"]', '[\"Haluskan bumbu kemudian campur dengan tepung kanji, tepung terigu, penyedap rasa, parutan kelapa, udang dan air hingga menjadi adonan\", \"Panaskan minyak, ambil sesendok demi sesendok lalu goreng, lakukan hingga habis.\", \"Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2076, 2, 'Udang tahu lada hitam', 'Resep praktis Udang tahu lada hitam yang bisa dicoba di rumah.', '[\"300 gram udang kupas\", \"5 buah tahu (potong sesuai selera)\", \"5 siung bawang putih\", \"3 siung bawang merah\", \"1 buah bawang bombay\", \"3 buah cabai merah\", \"Lada bubuk\", \"1 bks Saori lada hitam\", \"sedikit Air matang\", \"Minyak goreng sedikit untuk menumis\"]', '[\"Kupas udang dari kulit dan kotorannya hingga bersih\", \"Iris bawang putih, merah, bombay dan cabe sesuai selera\", \"Rebus tahu hingga matang, potong sesuai selera lalu goreng sebentar\", \"Tumis bumbu yang telah diiris hingga harum lalu masukkan udang, tumis hingga matang. Setelah itu masukkan tahu diaduk hingga merata\", \"Masukkan sedikit air, lada hitam bubuk dan saus lada hitam nya.\", \"Diaduk sampai mengental\", \"Udang tahu lada hitam siap untuk dihidangkan :)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2077, 2, 'Ikan teri udang', 'Cara membuat Ikan teri udang yang enak dan praktis untuk keluarga.', '[\"1 ons udang\", \"1 ons ikan teri\", \"2 siung bawang putih\", \"3 siung bawang merah\", \"5 biji cabe rawit\", \"1 biji cabe besar merah\", \"2 buah tomat\", \"secukupnya Penyedap\", \"1/2 sdt garam\", \"sesuai selera Kecap\"]', '[\"Kupas kulit udang terlebih dahulu\", \"Kupas bawang merah dan bawang putih\", \"Potong tipis bawang yang sudah dikupas tadi\", \"Potong menyerong tomat dan cabe\", \"Goreng terlebih dahulu ikan teri\", \"Tumis semua bumbu yang sudah disiapkan\", \"Setelah itu masukkan ikan teri dan udang yang sudah disiapkan tadi\", \"Masukan air secukupnya jangan terlalu banyak\", \"Tumis hingga berwarna\", \"Masukkan kecap dan penyedap secukupnya\", \"Tumis lagi sampai matang\", \"Setelah itu sajikan\", \"Selamat memasak ;)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2078, 4, 'Cah udang cumi', 'Resep Cah udang cumi ala rumahan yang dijamin menggugah selera.', '[\"200 gram cumi\", \"200 gram udang segar\", \"1 buah bawang bombay\", \"4 siung bawang putih\", \"10 buah cabai rawit\", \"7 buah cabai merah\", \"1 sdm saos tiram\", \"1 sdt minyak wijen\", \"Secukupnya gula dan garam\"]', '[\"Cuci bersih udang dan cumi, tiriskan\", \"Iris halus bawang bombay, cabai rawit dan cabai merah, cincang kasar bawang putih\", \"Panaskan minyak, lalu masukkan bawang putih dan bombay, masak hingga sedikit layu, lalu masukkan cumi dan udang, kemudian cabainya, tutup sebentar..\", \"Kemudian tambahkan saos tiram, minyak wijen, gula dan garam. Koreksi rasa,, masak hingga cumi lembut.. Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2079, 2, 'Udang pete sambel', 'Hidangan seafood nikmat: Udang pete sambel untuk pecinta udang.', '[\"500 gr udang\", \"4 papan petai\", \"100 gr cabai merah\", \"5 siung bawang merah\", \"1 siung bawang putih\", \"1 tomat merah besar iris tipis\", \"secukupnya Garam\"]', '[\"Bersihkan udang lumuri garam dan goreng hingga matang sisihkan\", \"Haluskan bawang merah, bawang putih dan cabe\", \"Tumis bumbu yang dihaluskan masukkan tomat dan pete masak hingga agak kering beri garam dan masukkan udang aduk hingga rata\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2080, 2, 'Tumis Sayur & Udang', 'Resep Tumis Sayur & Udang ala rumahan yang dijamin menggugah selera.', '[\"1 (1 bongkah) brokoli\", \"1 ikat Buncis\", \"2 buah Wortel\", \"8 potong Udang\", \"secukupnya Garam\", \"3 siung Bawang merah\", \"2 siung Bawang putih\", \"2 buah Cabai\"]', '[\"Rajang bawang merah, bawang putih, cabai, dan semua sayur\", \"Cuci dan potong udang\", \"Tumis 3 siung bawang merah, 2 siunh bawang putih dan cabai sampai harum\", \"Masukkan udang dan sayuran lainnya\", \"Beri garam dan koreksi rasa sambil di tumis\", \"Tambahkan air secukupnya (agar sayur mudah empuk), tutup dengan penutup panci. Api sedang.\", \"Setelah 5-10 menit, buka tutup panci, koreksi rasa dan cek sayurnya sudah edible belum wkwk. Kl sudah empuk rasa sudah pas, jadi deh!\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(2081, 3, 'Udang Balado Pete (Pedas Mantap)', 'Resep Udang Balado Pete (Pedas Mantap) yang lezat dan mudah dibuat di rumah.', '[\"1/2 Udang (Sedang)\", \"Bumbu :\", \"1/4 Cabai Merah\", \"8 Buah Cabai Rawit Setan\", \"8 Siung Bawang Merah\", \"3 Siung Bawang Putih\", \"Sedikit Kunyit\", \"Sedikit Jahe\", \"Sedikit Lengkuas\", \"Selembar Daun Jeruk\", \"Penyedap rasa (gula,garam,royco)\"]', '[\"Kupas kulit udang dari kepala sampai buntutnya. Cuci hingga bersih.\", \"Cuci semua bahan bahan.\", \"Haluskan/uleg semua bumbu.\", \"Tumis bumbu yg sudah dihaluskan. Masukan daun jeruk. Tambahkan penyedap rasa (gula,garam,royco)\", \"Jika sudah tercium aroma wangi, beri air matang segelas kecil. Diamkan beberapa saat.\", \"Masukan udang, dan aduk supaya bumbu tercampur rata. Diamkan beberapa saat\", \"Masukan pete jika sudah matang udang nya. Aduk aduk sebentar\", \"Selesai.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2082, 2, 'Balado kentang dan udang', 'Buat Balado kentang dan udang yang nikmat dengan langkah-langkah mudah ini.', '[\"1/2 kg kentang (potong dadu)\", \"1/4 kg udang ukurang sedang (kupas kulitnya)\", \"15 buah cabai merah keriting\", \"10 buah cabai rawit merah\", \"5 buah tomat (uk.kecil)\", \"1 lembar daun salam\", \"1 ruas lengkuas (geprek)\", \"1/2 sdt garam\", \"1/2 keping gula merah\", \"1/2 bks royco ayam\", \"Minyak untuk menggoreng\", \"secukupnya Air\"]', '[\"Kupas kentang kemudian potong dadu, siangin udang kemudian kupas kulitnya, buang kepalanya dan sisahkan buntutnya saja. Cuci bersih lumuri dengan garam dan cuka.\", \"Panaskan minyak dipenggorengan, goreng kentang yang sudah di potong dadu hingga kering tekstur nya. Jika sudah angkat dan tiriskan.\", \"Blender bawang merah, bawang putih, cabai rawit, cabai merah dan tomat hingga halus.\", \"Panaskan sedikit minyak di penggorengan. Tumis bumbu yg sudah dihaluskan,masukkan daun salam dan lengkuas yg sudah di geprek. Tambahkan gula, garam dan Royco Tumis hingga harum dan matang.\", \"Masukkan sedikit air aduk hingga rata, masukan udang dan kentang yang sudah di goreng. Masak hingga air mengering.\", \"Jika sudah angkat dan sajikan di piring.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2083, 3, 'Sempol Udang Bakar Madu', 'Resep Sempol Udang Bakar Madu ala rumahan yang dijamin menggugah selera.', '[\"15 tusuk sempol udang, gurat sisi2nya, rebus sebentar\", \"🍡 Bahan Marinasi:\", \"2 siung bawang putih (me: 1/2 sdt bawang putih bubuk)\", \"2 sdm saos tomat\", \"1 sdm saos sambal (me: skip)\", \"1 sdm kecap manis\", \"1 sdm madu\", \"1/2 sdt cabe bubuk (me: skip)\", \"secukupnya garam (me: kaldu jamur)\"]', '[\"Campur bahan marinasi. Rendam sempol dengan bahan marinasi selama 15 menit.\", \"Bakar sempol hingga di atas teflon yg telah dioles margarine hingga matang dan berkaramel.\", \"Sajikan hangat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2084, 2, 'Tumis Pedas Udang🍤Tahu', 'Nikmati kelezatan Tumis Pedas Udang🍤Tahu dengan resep sederhana ini.', '[\"1 ons udang\", \"3 buah tahu petak (potong dadu)\", \"Bumbu iris :\", \"3 buah cabe ijo\", \"6 buah cabe rawit\", \"1 siung bawang putih\", \"1 siung bawang merah\", \"1 batang daun bawang\", \"1 buah tomat uk.kecil\", \"7 buah cabe merah (giling halus)\", \"1 sdm perasan asam jawa\", \"2 sdt garam\", \"1 sdm gula pasir\", \"1/2 sdm kecap manis\", \"Secukupnya air\", \"1 sdm minyak utk menumis\"]', '[\"Cuci bersih udang.\", \"Potong dadu tahu lalu goreng sebentar.\", \"Siapkan bumbu iris dan cabe merah giling. Tumis bumbu iris hingga harum (kecuali tomat), lalu masukkan cabe giling tumis sebentar dan udang oseng2 hingga udang berubah warna, lalu masukkan air perasan asam jawa, gula, garam, kecap manis, beri sedikit air.\", \"Tambahkan tahu yg sdh digoreng td. Koreksi rasa. Setelah mendidih masukkan tomat, tunggu sebentar, matikan api.\", \"Tumis pedas udang tahu udah jd, pas buat lauk maksi plus nasi hangat mantaaabb👌😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2085, 4, 'Tumis Udang sehat', 'Tumis Udang sehat dengan udang segar dan bumbu khas.', '[\"8 ekor udang (buang kepala dan kulit)\", \"5 lembar sawi putih (iris dengan lebar kira2 1cm)\", \"3 lembar daun pokcay (iris-iris)\", \"1 buah wortel ukuran sedang (potong bulat)\", \"3 sium bawang putih (cincang halus)\", \"1 buah cabe hijau dan merah (iris serong)\", \"Saos tiram (setengah sendok teh)\", \"Secukupnya garam\"]', '[\"Goreng udang setengah matang lalu sisihkan\", \"Tumis bawang putih dan cabe yang telah diiris hingga harum\", \"Masukkan wortel dan batang daun sawi serta batang pokcay lalu tumis hingga setengah matang baru masukkan irisan daun dan udang agar matang merata\", \"Jika sudah layu masukkan saos tiram dan garam lalu tutup sebentar\", \"Icip rasa jika sudah pas dan matang tumis siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2086, 3, 'Tumis Timun Udang', 'Tumis Timun Udang - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"12 ekor udang\", \"1 buah timun\", \"1/4 bawang bombay\", \"1 biji cabai (bisa di skip)\", \"1 sdt Bawang putih halus\", \"Minyak goreng untuk menumis\", \"Bumbu udang\", \"1/8 garam\", \"Bubuk lada\", \"Sedikit tepung aci\", \"Bumbu\", \"2 sdm air\", \"1/2 sdt garam\", \"1 sdt saus tiram\", \"Sedikit minyak wijen\", \"Sedikit aci\"]', '[\"Daging udang buang usus, lap kering tambahi bumbu, diamkan 10 menit. Celup ke air mendidih.Angkat\", \"Timun potong memanjang, bawang bombay, cabai, semua potong\", \"Panaskan minyak, tumis bawang bombay hingga wangi. Masukkan bawang putih, masukkan timun, cabai, udang, bumbu aduk rata.Jadilah\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2087, 2, 'Udang Panggang Blackpepper (easy)', 'Resep Udang Panggang Blackpepper (easy) yang lezat dan mudah dibuat di rumah.', '[\"4 ekor udang windu besar\", \"Sedikit minyak untuk memanggang\", \"Bahan marinasi:\", \"3 siung bawang putih (haluskan)\", \"2 sdm mentega/butter (lelehkan)\", \"2 sdm air perasan lemon/jeruk nipis\", \"Secukupnya saus blackpepper (saori/lee kum kee\", \"sudah asin)\", \"secukupnya Garam (jika perlu)\"]', '[\"Bersihkan udang. Belah punggungnya sampai ke ekor hingga mekar.\", \"Lumuri udang dengan campuran bahan marinasi. Diamkan dalam kulkas selama min. 15-30 menit.\", \"Panaskan minyak di wajan teflon. Panggang udang sampai matang sambil dioles-oles dengan saus blackpepper.\", \"Hidangkan udang dengan side dish kesukaan Anda.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2088, 4, 'Pare tumis udang enak', 'Sajian Pare tumis udang enak yang praktis dan lezat untuk dinikmati bersama.', '[\"2 buah pare,iris tipis\", \"10 ekor udang sedang,buang kulit sisakan kepala dan ekor\", \"2 siung bawang putih,iris\", \"3 buah bawang merah,iris\", \"3 buah cabe rawit, buang bijinya bila tidak ingin terlalu pedas\", \"secukupnya Garam\", \"secukupnya Kecap manis\", \"secukupnya Kecap asin\", \"sedikit Lada\", \"bila suka Penyedap rasa\"]', '[\"Iris pare tipis, lumuri dengan garam lalu cuci bersih rebus sebentar angkat..tiriskan\", \"Kupas udang bersihkan kotorannya, sisakan ekor dan kepalanya buang sungutnya\", \"Iris bawang merah, bawang putih,dan cabe rawit sisikan\", \"Tumis bawang merah,bawang putih dan cabe masukan udang lalu tambahkan pare\", \"Masukan kecap manis..garam, lada, kecap asin, penyedap rasa aduk aduk beri sedikit air lalu aduk kembali coba rasakan\", \"Matikan api angkat sajikan\", \"Selamat menikmati dengan nasi hangat..👍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2089, 4, '002 Rempeyek udang sederhana', 'Nikmati kelezatan 002 Rempeyek udang sederhana dengan resep sederhana ini.', '[\"1/4 kg udang\", \"1/4 kg tepung beras\", \"5 lbr daun jeruk\", \"Bumbu halus\", \"5 siung bawang putih\", \"1 sdt ketumbar\", \"Penyedap rasa\", \"Garam\", \"Air\", \"Minyak goreng\"]', '[\"Cuci bersih udang, buang kepalanya, beri perasan jeruk nipis(opsional) sisihkan -karena udang ny cukup besar, saya belah dua\", \"-Rajang daun jeruk, sisihkan\", \"Siapkan bumbu halus, lalu buat campuran tepung\", \"Larutkan campuran tepung dan bumbu halus, sampai larutan dirasa cukup -saya buat agak cair, supaya adonan tidak tebal dan jadi renyah- tambahkan penyedap dan garam, lalu koreksi rasa\", \"Tambahkan daun jeruk, dan udang. Adonan siap di goreng. Goreng dalam minyak panas, dengan nyala kompor cukup besar\", \"Ini hasil pertama menggoreng, masih mengira2. Siap dihidangkan, simpan dalam toples kedap udara, biar tetap renyah.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2090, 3, 'Udang berpete', 'Resep praktis Udang berpete yang bisa dicoba di rumah.', '[\"1/4 udang\", \"4 potong tahu putih iris dadu goreng tiriskan\", \"1 buah pete\", \"Cabai merah ijo potong serong\", \"Bawang putih\", \"bawang merah\", \"bawang bombay\"]', '[\"Tumis semua bawang2 an\", \"Masukan udang goreng setengah zampai coklat.\", \"Masukan tahu.. bakso (potong kecil).. pete\", \"Tambah kecap manis.. saori.. saos sambel.. gula pasir.. cek rasa.. aduk2..\", \"Jika udah enak sajikan...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2091, 3, 'Udang pete pedas', 'Resep Udang pete pedas ala rumahan yang dijamin menggugah selera.', '[\"1/2 kg udang besar,buang kulit & kepala,kerat punggung,potong2,cuci\", \"8 siung bawang merah,iris halus\", \"4 siung bawang putih,iris halus\", \"2 cabe merah keriting,iris serong\", \"6 cabe hijau,iris serong (sesuai selera)\", \"1 ruas jari lengkuas,geprek\", \"1 ruas jahe,geprek\", \"2 btg sereh,geprek\", \"3 lbr daun salam\", \"1 papan pete,potong2\", \"secukupnya Garam\", \"secukupnya Kecap manis\"]', '[\"Tumis bawang merah dan bawang putih sampe harum,masukkan cabe2 an tumis kembali sampai harum. Masukkan daun salam,sere,jahe,lengkuas. Tumis sampe harum dan matang. Masukkan garam,aduk rata\", \"Masukkan udang,masak sampai udang berubah warna\", \"Tambahkan air secukupnya. Masak sampai air mendidih. Masukkan pete,aduk rata. Tambahkan kecap manis,koreksi rasa. Masak sampai air agak menyusut dan udang matang. Angkat dan sajikan. So nyumiiiiiii👍👍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2092, 4, 'Terong Udang', 'Hidangan seafood nikmat: Terong Udang untuk pecinta udang.', '[\"2 bawang putih\", \"2 bawang merah\", \"2 lombok merah\", \"Gula\", \"Garam\", \"Daun jeruk\", \"Bahan :\", \"Udang\", \"Terong\", \"secukupnya Air\"]', '[\"Haluskan bawang putih, bawang merah dan lombok\", \"Tumis bumbu halus sampai harum, lalu masukkan daun jeruk, gula, garam dan beri air, masukkan terong.\", \"Masak hingga terong lunak lalu masukkan udang rebus\", \"Masak hingga matang dan selamat menyajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2093, 2, 'Udang Tumis Bawang Putih', 'Nikmati kelezatan Udang Tumis Bawang Putih dengan resep sederhana ini.', '[\"Udang\", \"Butter\", \"Mentega\", \"Bawang putih\", \"Garam\", \"Lada hitam bubuk\", \"Rendaman untuk udang :\", \"Sprite\"]', '[\"Sebelum memasak udangnya, rendam udang nya terlebih dahulu dengan sprite selama 30 menit.\", \"Bahan bahan yang saya gunakan untuk memasak. Untuk bawang putih sesuai selera, boleh banyak boleh sedikit, dan di iris kecil kecil.\", \"Pertama tama, panaskan wajan, kalau sudah panas bisa masukan butter dan mentega. Untuk mentega saya pakai 1 sendok makan, saya lebih banyakin butter nya biar wangi.\", \"Setelah mentega dan butter sudah meleleh semua, langsung masukan bawang putih. tumis dengan api sedang sampai harum\", \"Setelah bawang putih harum, bisa masukan udang nya, garam dan lada hitam bubuk. Masak hingga semua udang matang, sebelum di sajikan bisa dicicipi apa bila ada rasa yang kurang.\", \"Dan sajikan 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2094, 2, 'Tumis kangkung udang', 'Nikmati kelezatan Tumis kangkung udang dengan resep sederhana ini.', '[\"1 ikat kangkung\", \"200 gr udang (bersihkan kulit&kepala)\", \"Bumbu halus :\", \"2 btr bawang merah\", \"3 btr bawang putih\", \"5 cabai rawit\", \"1 btr kemiri\", \"1 sdm saus tiram\", \"secukupnya Garam\", \"1 lembar daun salam\", \"secukupnya Minyak goreng\"]', '[\"Tumis bumbu halus sampai harum masukkan udang tunggu sampai sedikit empuk\", \"Masukkan kangkung yg sdh dipotong dan dicuci...aduk rata\", \"Tambahkan saus tiram dan garam tanpa tambahan air\", \"Tunggu sampai kangkung empuk lalu angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2095, 4, 'Balado Udang Tahu', 'Resep Balado Udang Tahu ala rumahan yang dijamin menggugah selera.', '[\"1/2 kg Udang\", \"5 biji Tahu putih\", \"20 biji Cabe merah\", \"5 siung Bawang merah\", \"4 siung Bawang putih\", \"2 siung Kemiri\", \"2 lembar Daun jeruk\", \"Lengkuas dikeprek\", \"Daun bawang potong2 besar\", \"Penyedap rasa, garam, gula, kecap manis\"]', '[\"Udang dibersihkan. Kalo saya buntutnya sama kulitnya saya kupas semua. Jadi sisa daging udangnya saja\", \"Tahu putih dipotong potong dadu lalu di goreng setengah mateng\", \"Cabe merah, bawang merah, bawang putih, kemiri diblander sampai halus. Tapi sblm diblander tambahkan minyak sayur sedikit dan air sedikit agar bahan2nya tidak seret saat diblander\", \"Siapkan wajan yg sudah dipanaskan tp jangan diberi minyak sayur dulu. Lalu masukan bumbu yg sudah di blander td. Aduk2 sampai bumbunya kering lalu masukan minyak sayur secukupnya\", \"Lalu masukan udang dan tahu lalu kasih garam, gula, kecap dan penyedap rasa secukupnya aduk2 lalu masukan daun bawang\", \"Koreksi rasa diamkan sebentar lalu sajikan😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2096, 4, 'Udang katsu', 'Udang katsu - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1/4 udang\", \"1/4 tepung roti\", \"1/8 terigu\", \"Bumbu halus:\", \"1 sdm ketumbar\", \"3 bawang putih\", \"Garam\"]', '[\"Haluskan bumbu halus, campur bersama terigu yang sudah dicairkan. Buat adonan terigu megental.\", \"Celupkan udang kedalam terigu cair, kemudian angkat dan baluri tepung roti.\", \"Masukan udang yang telah dibaluri tepung roti ke dalam freezer. Jika ingin disantap, goreng hangat2.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2097, 2, 'Sup bakso udang dan makaroni', 'Resep praktis Sup bakso udang dan makaroni yang bisa dicoba di rumah.', '[\"3 buah Wortel ukuran sedang\", \"Daun bawang\", \"Daun seledri\", \"100 gram Makaroni\", \"1 sdm Bubuk bawang putih\", \"secukupnya Penyedap rasa\", \"1 sdt Garam\", \"1 sdm Gula\", \"1 liter Air\", \"10 butir bakso udang\"]', '[\"Rebus air sampai mendidih masukkan makaroni\", \"Lalu masukan wortel yang sudah dipotong terlebih dahulu\", \"Masukan bakso udang dan daun bawang seledri\", \"Masukan garam, gula, penyedap rasa, dan bubuk bawang putih\", \"Cek rasa dan sayurnya. Siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2098, 2, 'Udang goreng nugget', 'Sajian Udang goreng nugget yang praktis dan lezat untuk dinikmati bersama.', '[\"Udang\", \"Kunyit\", \"Bawang putih\", \"Garam\", \"Tepumg terigu\", \"Telur ayam kocok\", \"Tepung roti\"]', '[\"Kucek halus bawang putih, kunyit dan garam beri air\", \"Goreng udang setengah matang. Tiriskan\", \"Balur udang dengan tepung terigu, dikepel\\\" byar rata\", \"Masukkan ke telur yang sudah dikocok\", \"Balurkan dengan tepung roti dikepel\\\" byar rata\", \"Masukkan kedalam freezeer 1 jam supaya padat\", \"Goreng hingga kecoklatan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2099, 4, 'Udang Bakar', 'Resep Udang Bakar yang lezat dan mudah dibuat di rumah.', '[\"1 kg udang ukuran agak besar\", \"1 buah jeruk nipis\", \"3 sdm tepung tapioka\", \"4 sdm kecap manis\", \"1 sdm saos sambal (tambahkan jika ingin pedas)\", \"Secukupnya garam, lada bubuk, kaldu bubuk rasa ayam (optional)\", \"8 siung bawang merah\", \"4 siung bawang putih\"]', '[\"Belah punggung udang, bersihkan tali hitamnya, cuci bersih\", \"Kucuri perasan air jeruk nipis, aduk rata. Diamkan 10 menit. Cuci bersih\", \"Beri 1 sdt garam. Remas2. Diamkan selama 15 menit. Tiriskan jika mengeluarkan air.\", \"Lumuri udang dengan tepung tapioka tipis2. Goreng sebentar saja dalam minyak panas, hanya sampai berubah warna. Angkat. Tiriskan\", \"Haluskan bawang merah dan bawang putih. Tumis di atas wajan sampai matang dan harum. Tambahkan kecap, saos sambal, garam, lada, dan kaldu bubuk. Aduk2 rata dengan api kecil. Koreksi rasa. Matikan api. Sisihkan\", \"Lumuri udang dengan bumbu tumisan tadi hingga rata. Tusuk2 dengan lidi/tusukan sate. Diamkan minimal 15 menit.\", \"Bakar di bara api atau teflon. Saya pakai fancy grill di atas kompor dengan api kecil. Tapi apapun alatnya, hasilnya tetap sama enaknya. Sajikan.\", \"Note : fungsi menggoreng udang sebentar yg dilumuri tepung tapioka adalah supaya udang lebih empuk dan tidak keras setelah dibakar\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2100, 3, 'Udang Goreng Oregano', 'Resep Udang Goreng Oregano ala rumahan yang dijamin menggugah selera.', '[\"Udang segar 20 buah, pakai yang agak kecil kalau mau lebih kriuk\", \"Ketumbar bubuk\", \"Lada Putih bubuk\", \"Kunyit bubuk\", \"Secukupnya Tepung terigu(Me : Segitiga biru)\", \"Kaldu bubuk (Me : Royco)\", \"Garam\", \"Oregano bubuk\"]', '[\"Cuci udang, bersihkan punggung udang, biarkan kulitnya dan ekornya agar kriuk\", \"Bumbui udang, beri sedikit air, garam secukupnya, lada putih sejumput, ketumbar bubuk secukupnya, kunyit bubuk secukupnya, diamkan kurang lebih 20 menit\", \"Siapkan baluran nya : Tepung terigu sekitar 20 sdm, ketumbar bubuk secukupnya, royco secukupnya, oregano bubuk secukupnya, aduk rata\", \"Balur udang dengan tepung yang sudah dibumbui hingga tertutup semua. Diamkan di kulkas kurang lebih setengah jam\", \"Goreng dengan minyak panas hingga kuning sedikit kecoklatan, terlihat kriuk, angkat, tiriskan\", \"Sajikan dengan nasi hangat, saus sambal dan mayonaise, hmm yummy..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2101, 2, 'Tumis brokoli udang makaroni', 'Nikmati kelezatan Tumis brokoli udang makaroni dengan resep sederhana ini.', '[\"100 gram brokoli\", \"50 gram makaroni\", \"Secukupnya udang (kupas)\", \"4 Siung bawang merah\", \"Secukupnya garam\", \"Secukupnya gula pasir\", \"Secukupnya merica\", \"Secukupnya air\"]', '[\"Cuci bersih brokoli, potong kecil-kecil (karena saya sekalian buat Mpasi) rendam dalam air garam selama 3menit. Angkat tiriskan.\", \"Rebus makaroni terlebih dahulu, sampai empuk. Angkat tiriskan.\", \"Cuci bersih udang yg telah di kupas potong kecil-kecil atau sesuai selera.\", \"Tumis bawang merah sampai harum. Tambahkan air sedikit saja. Kemudian tunggu mendidih. Lalu masukan udang terlebih dahulu sampai berwarna keorange orangean.\", \"Tambahkan brokoli dan makaroni. Lalu campurkan garam gula dan merica secukupnya. Diamkan sebentar sampai bumbu meresap.\", \"Cicipi rasa. Angkat dan sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2102, 3, 'Udang Saus Mentega with Brocoli', 'Cara membuat Udang Saus Mentega with Brocoli yang enak dan praktis untuk keluarga.', '[\"250 gram udang kupas bersih kalau aku\", \"1 buah bawang bombay kecil, iris\", \"1 siung bawang putih, cincang\", \"4 kuntum brokoli, iris, cuci bersih\", \"1/2 bungkus Saori saus mentega\", \"1 sdm Saori saus tiram\", \"1 sdm Saus tomat\", \"1 sdm kecap manis\", \"secukupnya Gula garam lada\", \"3 sdm mentega\"]', '[\"Panaskan mentega. Goreng udang hingga matang. Sisihkan.\", \"Goreng bawang putih cincang di sisa mentega tadi. Tunggu harum, masukkan brokoli. Tunggu agak layu, masukkan bawang bombay. Aduk2. Masukkan udang. Tambahkan sedikit air.\", \"Masukkan aneka saus, Gula Garam, dan lada. Aduk2 koreksi rasa. Siap dijakin.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2103, 4, 'Cah pakcoy udang saos tiram as', 'Buat Cah pakcoy udang saos tiram as yang nikmat dengan langkah-langkah mudah ini.', '[\"4 bonggol pakcoy\", \"1/4 udang segar\", \"1/2 bawang bombay\", \"2 saset saos tiram\", \"3 buah cabe hijau besar\", \"3 buah cabe merah keriting\", \"7 siung bawang merah\", \"2 siung bawang putih\", \"secukupnya garam\", \"5 buah cabe rawit merah\"]', '[\"Cuci udang dan pakcoy sampe bersih, udang buang bagian kepalanya saja, pakcoy potong sesuai selera, udang di kasih garam dan air jeruk nipis diamkan sebentar.\", \"Semua bumbu di iris, kemudian tumis dngn minyak panas, setelah harum masukan udang sampe berubah warna, kemudian pakcoy masukan, aduk rata, tambahkan saos tiram, kemudian aduk kembali...test rasa ya, klo asinnya kurang boleh tambah garam. SETELAH matang angkat dan siap di sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2104, 3, 'Shrimp salad', 'Resep Shrimp salad yang lezat dan mudah dibuat di rumah.', '[\"1/4 kg udang (buang kepala dan ekor)\", \"1 bh lemon\", \"margarin\", \"1 bh lettuce\", \"1 bh telur rebus\", \"1 bh jagung manis\", \"1 bh wortel (iris korek)\", \"1 bh bawang bombay\", \"mayonnaise (saya pakai maestro)\", \"(bisa ditambah kol ungu atau sayuran lainnya)\"]', '[\"Kupas dan cuci bersih udang kemudian lumurin dengan air perasan lemon agar tidak bau amis\", \"Panaskan teflon beri margarin dan minyak, kemudian masukkan udang, goreng hingga matang lalu sisihkan\", \"Rebus telur dan jagung manis hingga matang angkat lalu sisihkan\", \"Cuci bersih lettuce dan sobek-sobek agar tidak terlalu besar\", \"Iris seperti korek api wortel dan iris pula bawang bombay\", \"Campurkan semua bahan nya dengan mayonnaise aduk hingga rata lalu sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2105, 4, 'Pepes udang', 'Nikmati kelezatan Pepes udang dengan resep sederhana ini.', '[\"1/2 kg Udang\", \"9 siung Bawang merah\", \"10 siung Bawang putih\", \"2 bh Cabe besar merah\", \"2 bh Cabe hijau\", \"secukupnya Garam\", \"2 bh Tomat\", \"Kaldu bubuk secukupnyaa\", \"Gula secukupnyaa\", \"Lada bubuk secukupnyaa\", \"Daun pisang\"]', '[\"Bersihkan udang masukkan wadah\", \"Potong tipis bawang merah, bawang putih, camer, cajo. Stlah di potong tipis campur dengan udang\", \"Tambah kaldu bubuk, gula, garam, dan lada bubuk aduk sampai merata\", \"Potong dadu tomat\", \"Masukkan udang dalam daun pisang bungkus rapi dan cantik\", \"Kukus 15 menit\", \"Selamat mencoba 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2106, 2, 'Udang pedas manis', 'Resep Udang pedas manis yang lezat dan mudah dibuat di rumah.', '[\"udang\", \"3 siung bawang merah (iris)\", \"1/2 bawang bombay (iris)\", \"garam\", \"lada bubuk\", \"kecap\", \"penyedap\", \"bumbu uleg\", \"3 siung bawang putih\", \"5 cabe merah\", \"10 cabe setan\", \"2 butir kemiri\"]', '[\"Tumis bawang merah + bawang bombay sampai harum\", \"Masukan bumbu uleg, aduk2 sampai wangi\", \"Masukan udang kemudian aduk2, tambahkan garam, lada bubuk, penyedap\", \"Tambahkan sedikit kecap, masak hingga matang\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2107, 3, 'Sambal udang kecepe', 'Sambal udang kecepe - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 ons udang kecepe/baring\", \"20 buah cabe merah\", \"10 buah bawang merah\", \"2 buah bawang putih\", \"1 buah tomat merah\", \"Secukupnya garam\", \"Secukupnya gula\", \"Secukupnya krupuk ubi/opak\"]', '[\"Blender cabe merah, bawang putih, bawang merah dan tomat\", \"Goreng udang/ebi sampai matang\", \"Tumis bahan yg sudah dihaluskan..kemudian masukan gula dan garam..test rasa sambal\", \"Kemudian masukan udang yg sudah di goreng...tunggu hingga dingin\", \"Kemudian masukan opak..agar tetap renyah..\", \"Sajian siap disantap dengan kuah sup dan dadat telur..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2108, 3, 'Martabak mini tahu udang', 'Martabak mini tahu udang - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"10 lembar kulit lumpia\", \"2 buah tahu putih, potong kotak kecil\", \"3 butir telur ayam, kocok lepas\", \"5 batang daun bawang, ambil dan rajang daun nya\", \"1 mangkok kecil udang\", \"2 siung bawang putih, rajang halus\", \"1/2 sdt garam\", \"1/2 sdt merica bubuk\", \"Sejumput gula pasir\", \"10 lembar kulit lumpia\", \"2 buah tahu putih, potong kotak kecil\", \"3 butir telur ayam, kocok lepas\", \"5 batang daun bawang, ambil dan rajang daun nya\", \"1 mangkok kecil udang\", \"2 siung bawang putih, rajang halus\", \"1/2 sdt garam\", \"1/2 sdt merica bubuk\", \"Sejumput gula pasir\"]', '[\"Campur semua bahan aduk rata\", \"Panaskan minyak, siapkan kulit lumpia beri 2 sdm adonan martabak, lipat kotak goreng hingga matang kecoklatan. Lakukan hingga habis.\", \"Siap sajikan\", \"Panaskan minyak, siapkan kulit lumpia beri 2 sdm adonan martabak, lipat kotak goreng hingga matang kecoklatan. Lakukan hingga habis.\", \"Siap sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2109, 3, 'Udang pete tahu masak tauco', 'Buat Udang pete tahu masak tauco yang nikmat dengan langkah-langkah mudah ini.', '[\"1 buah tahu cina potong 2 lalu potong 5 jadi ada 10 potong tahu\", \"2 papan pete kupas\", \"1/4 kg udang kupas\", \"1 buah tomat diiris bagi 6\", \"1 buah cabe merah besar potong miring\", \"1 buah cabe hijau besar potong miring\", \"1 sendok makan tauco medan\", \"1 sendok makan saus tiram\", \"1 ruas jari jahe digeprek\", \"2 siung bawang putih iris\", \"2 siung bawang merah iris\", \"1/2 bagian bawang bombay iris\", \"1 sendok makan kecap manis\", \"1 sendok teh kecap ikan\", \"1/2 sendok teh minyak wijen\", \"Garam\", \"Gula\", \"Kaldu jamur\", \"Air\", \"Tepung maizena untuk pengental\", \"Minyak sayur untuk menumis\"]', '[\"Masukan ke dalam minyak sayur : minyak wijen, bawang putih, bawang bombay, bawang merah, jahe, cabe merah dan hijau.. Tumis hingga layu\", \"Masukkan udang tomat dan petai... Tumis sebentar hingga udang berubah warna\", \"Masukan air secukup nya..\", \"Lalu masukkan kecap ikan, saos tiram,kecap manis, tauco, gula, garam, kaldu...\", \"Test rasa\", \"Masukkan tahu\", \"Terakhir beri pengental dari tepung maizena...\", \"Jadi deh... Tinggal dimakan 😂😂 kalo mau pedas pakai cabe keriting aja ya... 😁😁\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2110, 2, 'Udang bakar simple', 'Sajian Udang bakar simple yang praktis dan lezat untuk dinikmati bersama.', '[\"Bahan\", \"8 ekor Udang sedang\", \"Bumbu oles\", \"Bawang merah goreng\", \"Bawang putih goreng\", \"2 sdm saos sambal\", \"1 sdm kecap manis\", \"1 sdt saos tiram\", \"Sjumput lada\", \"Penyedap rasa\", \"2 sdm Lelehan margarin\"]', '[\"Goreng bawang merah dan bawang putih..\", \"Haluskan bawang tadi campur smua bahan,bakar dan olesi udang,,siap sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2111, 2, 'Udang mangga saus bangkok', 'Resep Udang mangga saus bangkok yang lezat dan mudah dibuat di rumah.', '[\"1/4 udang kupas\", \"3 sdm saos bangkok pedas manis\", \"1 sdt minyak ikan\", \"1/2 sdt garam\", \"1 biji cabai rawit iris\", \"1 batang daun bawang\", \"3 siung bawang putih\", \"Mangga muda potong dadu secukupnya\", \"secukupnya Jeruk nipis\", \"1 batang seledri iris\", \"1/4 sdt lada putih\", \"1 sdt kecap asin\"]', '[\"Siapkan bawang putih, daun bawang, cabai rawit, seledri dan mangga muda yang sudah di iris\", \"Tumis bawang putih lalu masukan cabai dan udang\", \"Jika sudah setengah matang masukan mangga dan daun bawang lalu tambahkan saus bangkok, kecap asin, garam, minyak ikan dan lada juga berikan sedikit air\", \"Setelah matang berikan day perasan jeruk nipis dan masukan seledri lalu matikan apinya\", \"Aduk sampai semua tercampur rataaa\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2112, 3, 'Tom Yum Udang dan Kerang', 'Sajian Tom Yum Udang dan Kerang yang praktis dan lezat untuk dinikmati bersama.', '[\"500 gr Udang sedang buang kepalanya\", \"500 gr kerang hijau\", \"50 gr jamur champinon boleh lebih(sisa an bikin mie ayam jamur)\", \"4 batang serai potong2\", \"6 lembar daun jeruk\", \"6 butir bawang putih iris aja\", \"3 butir bawang merah iris juga\", \"cabe merah giling 3 sdm (sesuai selera)\", \"7 cabe rawit setan utuh\", \"6 jeruk nipis peras airnya\", \"secukupnya garam dan penyedap\", \"1 liter air buat bikin kaldu\", \"2 sdm kecap ikan\"]', '[\"Buat kerangnya bersihhkan kerang dan kemudian rebus di air garam dan tambahin sedikit jeruk nipis atau jahe biar ga amis. kemudian cuci dengan air dingin dan tiriskan\", \"Buat kaldu dari kepala udang dengan cara tumis kepala udang sampe matang trus tambahkan air 1 liter. rebus sampe mendidih. jangan lupa buang buih nya supaya kaldu bening\", \"Tumis bawang putih, bawang merah sampe harum yrus masukkan serai dan daun jeruk serta kecap ikan\", \"Masukkan tumisan ke dalam kaldu udang tambahkan cabai merah giling dan juga perasan air jeruk nipis\", \"Masukkan udang dan jamur kemudian tambahkan garam dan penyedap sampe rasanya pas. masukkan cabe rawit utuh\", \"Pas mau di sajikan tambahkan kerang hijau di mangkok lalu siram dengan tom yum udang. hidangkan dengan nasi panas\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2113, 4, 'Udang goreng terasi', 'Buat Udang goreng terasi yang nikmat dengan langkah-langkah mudah ini.', '[\"500 gram udang galah\", \"1 sdt munjung terasi sangrai\", \"1 sdt garam\", \"1 sdt air asam\", \"1/2 sdt air jeruk nipis\", \"secukupnya Minyak goreng\"]', '[\"Bersihkan udang galah, potong ujung kepala kemudian keluarkan kotorannya, bersihkan cangkang dan kumis kumisnya juga😁\", \"Masukkan terasi, garam, air asam dan jeruk nipis kemudian aduk hingga tercampur rata.\", \"Diamkan beberapa saat di dalam kulkas sebelum di goreng.\", \"Goreng dengan minyak panas dan api sedang.\", \"Siapppp di sajikaaan. Selamat mencoba😁\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2114, 3, 'Pepes tahu udang', 'Buat Pepes tahu udang yang nikmat dengan langkah-langkah mudah ini.', '[\"250 g udang\", \"1 papan tahu\", \"Kelapa muda parut dari 1/2butir kelapa\", \"7 siung bawang merah\", \"5 siung bawang putih\", \"5 biji cabe rawit\", \"1 sdt ketumbar\", \"1 ruas laos\", \"1 ruas kunyit\", \"1 ruas jahe\", \"1 ruas kencur\", \"5 lembar daun jeruk\", \"Ale\", \"2 buah cabe hijau besar\", \"Gula\", \"Garam\", \"Penyedap rasa\", \"Daun pisang\", \"Tusuk gigi\"]', '[\"Kupas udang dari kepala dan ekornya. Cuci bersih\", \"Iris2 cabe hijau dan ale\", \"Haluskan bawang merah, bawang putih, kunyit, jahe, kencur, laos, cabe dan daun jeruk. Daun jeruk ulek kasar saja.\", \"Campurkan parutan kelapa ke bumbu halus dan beri cabe hijau ale.\", \"Masukkan tahu dan remat2 sampai hancur.\", \"Beri gula, garam dan penyedap rasa.\", \"Urap sampai tercampur rata dan incip rasanya.\", \"Jika sudah pas, panaskan kukusan.\", \"Masukkan pepesan ke daun pisang dan tusuk dgn tusuk gigi.\", \"Lakukan sampai habis dan masukkan kedalam kukusan.\", \"Tunggu krglbh 45mnt.\", \"Pepes udang siap disantapp 😁\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2115, 2, 'Cah sawi udang', 'Cara membuat Cah sawi udang yang enak dan praktis untuk keluarga.', '[\"1 ikat sawi caisim, siangi, bersihkan dan potong potong\", \"100 gr udang kecil kupas\", \"8 buah cabe merah, iris\", \"5 siung bawang merah, iris\", \"1 siung bawang putih, iris\", \"1 sdt sambal bawang siap pakai (jika tidak ada ganti cabe rawit)\", \"75 ml air\", \"secukupnya Garam dan gula\", \"Minyak untuk menumis\"]', '[\"Panaskan minyak, tumis bawang merah dan putih hingga harum. Tambahkan cabe merah. Aduk hingga cabe layu.\", \"Masukkan air, udang, sambal bawang, garam dan gula. Aduk rata hingga udang berubah warna dan air mendidih.\", \"Masukkan sawi, aduk rata hingga sawi layu. Koreksi rasa. Sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2116, 4, 'Sempol udang mini', 'Resep Sempol udang mini yang lezat dan mudah dibuat di rumah.', '[\"1 plastik udang beli di tukang sayur (ga tau brp ukuranya)\", \"10 sdm tepung tapioka (pakai tepung sagu lebih baik)\", \"5 sdm tepung terigu\", \"2 bawang putih haluskan\", \"Seledri iris halus\", \"2 telur ayam\"]', '[\"Cuci udang. Buang kulitnya haluskam kalau saya di uleg.. Campur semua bahan dengan 1 (satu) telur sampai adonanya bisa di bentuk.. bisa d kasih sedikit air kalau masih blm bisa di bentuk.. kira2 aja. Jgn banyak2 airnya biar ga terlalu encer.\", \"Rebus air dalam panci sampai mendidih\", \"Adonan td di lilitkan ke lidi lalu masukan ke air yg mendidih td sampai habis.\", \"Setelah adonan yg di rebus td mengapung dan matang tiriskan.\", \"Celupkan adonan yg sudah di rebus td di telur (kalau saya telurnya di kasih air lg.. biar celupan telurnya jd banyak)\", \"Goreng adonan yg sudah di campur telur hingga warnanya kecoklatan.. cm mematangkan telurnya saja. Karna adonan sudah matang karna d rebus td. Angkat sajikan dgn saus botol\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2117, 4, 'Udang Telur Asin', 'Udang Telur Asin dengan udang segar dan bumbu khas.', '[\"1/2 kg udang\", \"6 butir telur asin ( ambil kuningnya dan lumatkan\", \"3 siung bawang putih (cincang halus)\", \"Daun bawang\", \"secukupnya Gula,garam,merica\", \"Tepung kriuk (untuk goreng udang)\", \"Minyak goreng/mentega\", \"Cabe rawit (iris tipis dan jumlahnya sesuai selera)\"]', '[\"Cuci bersih udang. Buang kepala dan sisakan ekor. Lumuri dengan tepung kriuk, goreng setengah matang. Sisihkan\", \"Tumis bawang putih cincang dengan minyak/mentega. Lalu masukkan cabe rawit.\", \"Masukkan telur asin yg sudah di lumatkan, sampai berbusa dan tambahkan gula garam merica. Tambahkan juga sedikit air.\", \"Masukkan udang kriuk, aduk rata. Masukkan irisan bawang daun. Matikan kompor\", \"Udang telur asin siap disantap\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2118, 4, 'Tumis pare udang pedas', 'Nikmati kelezatan Tumis pare udang pedas dengan resep sederhana ini.', '[\"Udang (buang kulitnya)\", \"Sayur pare(iris tipis2)\", \"Bawang merah (iris tipis)\", \"Bawang putih (geprek)\", \"Cabai merah keriting(iris tipis)\", \"Cabai besar warna hijau(iris tipis)\", \"Tomat (iris tipis)\", \"secukupnya Air\", \"Bumbu halus :\", \"Bawang merah\", \"Bawang putih\", \"Terasi dikit saja\", \"Cabai rawit\", \"Garam\", \"Gula\", \"Masako atau penyedap rasa lainnya\"]', '[\"Iris pare tipis2 lalu rendam dengan air garam kurang lebih 15menit buang air rendaman lalu cuci lagi dengan air bersih\", \"Kupas bersih udang dari kulitnya,cuci bersih setlah itu ksh masako, panaskan minyak dan goreng\", \"Setelah udang mateng warnanya berubah lalu angkat\", \"Panaskan minyak setelah mulai panas masukan irisan bawang merah dan putih sampai harum masukan bumbu halus tunggu sebentar lalu masukan udang yg sdh digoreng lalu masukan irisan tomat cabe merah keriting dan cabe hijau dan kasih air sedikit lalu masukan pare yg sudah direndam garam dan sudah dicuci bersih dan tunggu\", \"Setelah semua bahan tercampur dan airnya mulai mengering lalu koreksi rasa setelah itu siap disajikan. Selamat menikmati.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2119, 3, 'Udang goreng tepung simple', 'Nikmati kelezatan Udang goreng tepung simple dengan resep sederhana ini.', '[\"1/2 kg Udang\", \"Tepung bumbu sajiku\", \"1 btr telur\", \"Merica bubuk\", \"Ketumbar bubuk\", \"Masako\", \"Garam\", \"secukupnya Maizena\"]', '[\"Buka kulit udang dan kepalanya kemudian cuci hingga bersih, masukan ke dalam mangkok.\", \"Kemudian campur udang dengan telur,merica,ketumbar dan masako secukupnya. Aduk hingga rata\", \"Kemudian masukan tepung bumbu sebanyak yg di butuhkan di piring, campur maizena dan masako kemudian aduk rata\", \"Setelah itu masukan satu persatu udang dri telur ke tepung bumbu kemudian lumurin udang dgn tepung kemudian panaskan minyak dan goreng udang hingga matang dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2120, 2, 'Udang Goreng Garing', 'Cara membuat Udang Goreng Garing yang enak dan praktis untuk keluarga.', '[\"Bahan :\", \"500 gr Udang ukuran kecil\", \"1 sdm margarin\", \"1/4 sdt kaldu bubuk\", \"Minyak untuk menggoreng\"]', '[\"Cuci bersih udang buang kepala sisakan kulitnya.\", \"Panaskan minyak goreng, tambahkan margarin & sedikit kaldu bubuk.\", \"Goreng udang dengan minyak panas api kecil sampai garing, angkat & sajikan dengan sambel terasi.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2121, 2, 'Bakwan udang saos kecap', 'Sajian Bakwan udang saos kecap yang praktis dan lezat untuk dinikmati bersama.', '[\"300 gr udang yang sudah di kupas\", \"2 sdt bawang putih halus\", \"1 sdt garam halus\", \"Sejumput lada hitam\", \"Sejumput gula\", \"Kaldu penyedap bila suka(sy tdk pake)\", \"1 sdm terigu\", \"4 sdm sagu\", \"1 butir telur kocok sampai berbuih\", \"1/2 sdt baking powder\", \"Bahan saos :\", \"4 butir bawang putih cincang\", \"1 bawang bombay iris\", \"2 batang daun bawang iris\", \"1 batang seledri utuh\", \"1 sdm saos tiram\", \"4 sdm saos tomat\", \"6 sdm kecap manis\", \"1 sdm kecap asin\", \"Air secukup nya\"]', '[\"Giling kasar udang,campur kan bawang putih,garam,lada\", \"Masukan telur kocok, terigu, gula, sagu, baking powder. aduk hingga rata\", \"Goreng adonan dengan api kecil bentuk nya menggunakan sendok saja,adonan akan mengembang. Balik,angkat dan tiriskan minyak nya.sisihkan\", \"Timis bawang putih dan bombay,masukan daun bawang dan selidri tumis hingga wangi\", \"Tambahkan semua saos beri air secukupnya.cicipi rasa hingga sesuai selera\", \"Siram saos ke atas bakwan udang..segera ambil piring beserta nasi...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2122, 3, 'Mie goreng udang', 'Cara membuat Mie goreng udang yang enak dan praktis untuk keluarga.', '[\"1 bungkus mie kuda menjangan\", \"2 bungkus udang (harga @6.000)\", \"Bumbu :\", \"4 siung bawang putih\", \"4 siung bawang merah\", \"1 tangkai bawang prei\", \"secukupnya Ketumbar halus\", \"secukupnya Garam\", \"secukupnya Lada halus\", \"2 bh tomat\", \"Pelengkap : saos tiram, rajarasa, lada hitam bubuk, dan kecap\", \"secukupnya Minyak goreng\", \"secukupnya Air\"]', '[\"Cuci bersih udang, buang kulitnya\", \"Haluskan bumbu kecuali bawang prei\", \"Rebus mie tambahkan sedikit minyak goreng\", \"Tumis bumbu yg sudah dihaluskan, tambahkan bawang prei, masukkan udang tunggu beri sedikit air hinga asat\", \"Setelah asat campurkan mie yg sudah direbus\", \"Aduk hingga rata, tambahkan bumbu pelengkap\", \"Tes rasa sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2123, 4, 'Sambal Udang Cili Merah', 'Resep Sambal Udang Cili Merah ala rumahan yang dijamin menggugah selera.', '[\"200 gr udang, bersihkan\", \"2 lembar daun jeruk\", \"Kacang panjang secukupnya, potong sesuai selera\", \"secukupnya Garam dan gula\", \"Minyak untuk menumis\", \"Bumbu halus :\", \"5 biji cabe merah keriting (optional)\", \"3 siung bawang merah\", \"2 siung bawang putih\", \"secukupnya Terasi + air\"]', '[\"Panaskan minyak, tumis bumbu halus hingga wangi. Tambahkan daun jeruk Lalu masukkan udang, kacang panjang, garam dan gula Aduk sebentar. Cek rasa. Angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2124, 2, 'Udang bunga kol asam manis praktis.', 'Udang bunga kol asam manis praktis. - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"250 gr udang sedang\", \"1 buah bunga kol ukuran sedang\", \"1 buah bawang bombay ukuran kecil\", \"2 siung bawang putih\", \"3 siung bawang merah\", \"1 buah tomat ukuran kecil\", \"garam\", \"penyedap rasa\", \"gula pasir\", \"secukupnya air lemon\", \"saus sambal\", \"saus tomat\"]', '[\"Bersihkan udang lalu siram air lemon biar ga amis diamkan 5 menit\", \"Cuci bunga kol potong2 lalu rendam di air garam (buat menghilangkan kotoran atau binatang yg menempel)\", \"Iris semua bawang bawangan\", \"Tumis bawang sampai harum masukan udang sampai berwarna merah kemudian masukan bunga kol lalu masukan air 200cc, diamkan sampai meletup letup\", \"Tambahkan garam, penyedap dan gula cek rasa kalau sudah oke tambahkan saus sambal dan tomat sesuai selera aduk rata\", \"Kalau bunga kol sudah mulai matang masukan irisan tomat dan siap disajikan.. (untuk kuah jika ingin kesring bisa sampai airnya surut)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2125, 3, 'Gulai udang asem pedes tanpa santan', 'Resep Gulai udang asem pedes tanpa santan ala rumahan yang dijamin menggugah selera.', '[\"1/2 kg udang\", \"Bumbu halus\", \"1 ruas kunyit\", \"1 ruas jahe\", \"6 bawang merah\", \"3 butir kemiri\", \"2 bawang putih\", \"6 rawit merah\", \"3 daun jeruk\", \"6 buah asam kandis\", \"2 batang sereh digeprek\", \"1 ruas Laos digeprek\", \"3 buah belimbing wuluh diiris iris\", \"2 buah tomat hijau\", \"Ladaku, Masako ayam secukupny, garam\"]', '[\"Cuci udang bersih, buang kepala\", \"Sebelum bumbu dihaluskan, iris2 bawang putih, bawang merah kunyit, jahe, cabe rawit kemiri kemudian tumis sebentar dg minyak, kemudian haluskan\", \"Tumis bumbu halus, Laos sereh, daun jeruk smp harum kemudian kasih air secukupny\", \"Masukan udang, garam, lada bubuk, Masako secukupnya, belimbing tomat hijau dan asam kandis\", \"Tes rasa asem pedes dan asinny\", \"Masak smp udang matang dan bumbu meresap\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2126, 2, 'Tumis Udang Pare', 'Nikmati kelezatan Tumis Udang Pare dengan resep sederhana ini.', '[\"200 gr Udang, bersihkan\", \"1 buah pare ukuran sedang, iris2\", \"1 buah lombok besar, iris2\", \"1 sdt saus tiram\", \"2 sdt saus sambal\", \"secukupnya Air\", \"secukupnya Minyak\", \"secukupnya Garam, gula dan penyedap\", \"Bumbu Halus :\", \"4 siung bawang merah\", \"2 siung bawang putih\", \"2 cm kunyit\"]', '[\"Panaskan minyak, Tumis bumbu hingga wangi lalu masukkan pare yang sudah dipotong2. Aduk hingga bumbu dan pare tercampur rata.\", \"Selanjutnya masukkan udang, saus tiram, saus sambal, garam, gula serta penyedap rasa. Tambahkan air lalu Aduk dan Cek rasa.\", \"Terakhir tambahkan irisan lombok, Aduk sebentar lalu matikan apinya.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2127, 4, 'Udang sweet spicy 😁', 'Udang sweet spicy 😁 - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"250 gram udang segar buang kepala\", \"Jeruk nipis utk melumuri udang\", \"🍭Bumbu yg diulek halus :\", \"5 bawang merah\", \"1 bawang putih\", \"4 cabe merah keriting\", \"3 cabe rawit orens bisa lebih\", \"1 ruas kunyit,jahe,lengkuas\", \"secukupnya 🍭Garam,gula pasir,merica bubuk\", \"1/2 sdm kecap manis\", \"Daun salam\", \"Daun jeruk\", \"Secukupnya air\", \"Minyak goreng\"]', '[\"Cuci bersih udang,rendam dgn air jeruk nipis beberapa menit,lalu cuci bilas kembali,tiriskan\", \"Haluskan bumbu diatas\", \"Tumis bumbu halus hingga harum,masukan daun salam dan daun jeruk. Masukan udangnya,aduk hingga merata,tambahkan air,tambahkan merica bubuk,garam,gula pasir dan kecap manis. Masak hingga matang.\", \"Sajikan 😊🍤🍤\", \"Hr ini masaknya udang pedas manis dan tumis pokcoy wortel, mantap masyaallah 😊😍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(2128, 3, 'Cilok Udang', 'Sajian Cilok Udang yang praktis dan lezat untuk dinikmati bersama.', '[\"400 gr udang\", \"250 gr tepung kanji\", \"250 gr tepung terigu\", \"5 butir bawang putih\", \"2 butir bawang merah\", \"2 butir telur\", \"1/2 butir terasi (terasi kemasan kecil)\", \"Secukupnya Seledri\", \"Secukupnya Daun bawang\", \"Secukupnya Bawang merah goreng\", \"Secukupnya Merica\", \"Secukupnya garam\", \"Secukupnya royco\"]', '[\"Cuci bersih udang dan haluskan\", \"Campur dengan 2 butir telur\", \"Campur dengan tepung terigu dan kanji secara perlahan\", \"Campur seledri dan daun bawang cincang\", \"Tambahkan bawang goreng dan royco\", \"Tambahkan merica, bawang putih, bawang merah, dan terasi yang telah dihaluskan\", \"Uleni\", \"Bentuk adonan seperti pada pembuatan bakso\", \"Rebus pada air mendidih hingga setengah matang\", \"Kukus\", \"Selamat menikmati :)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2129, 4, 'Spaghetti Saus Udang Lada Hitam', 'Hidangan seafood nikmat: Spaghetti Saus Udang Lada Hitam untuk pecinta udang.', '[\"📌Udang goreng:\", \"500 gram udang kupas, cuci bersih (jika ukurannya besar potong menjadi ukuran 2cm)\", \"Bumbu udang goreng:\", \"2-3 buah Kemiri, haluskan\", \"2 sdt Ketumbar bubuk\", \"1/2 sdt Kunyit bubuk (bisa pakai kunyit rimpang, haluskan)\", \"secukupnya garam\", \"1 sdt bawang putih bubuk (atau 3 siung bawang putih, haluskan)\", \"3 sdm air\", \"Minyak untuk menggoreng\", \"📌150 gram Spaghetti\", \"📌Saus Lada Hitam:\", \"Minyak untuk menumis\", \"1 buah bawang bombay, iris\", \"1 buah paprika, potong dadu\", \"secukupnya Garam\", \"secukupnya Merica hitam\", \"secukupnya Gula pasir\", \"2 sdm kecap asin\", \"Bubuk thyme secubit (a pinch, opsional)\", \"1/2 sdt jahe bubuk\", \"2,5 gelas air\", \"1 sdt tepung maizena dilarutkan dalam 2 sdm air\"]', '[\"Goreng udang: campur semua bumbu kecuali minyak, balurkan dan rendam potongan udang kupas dalam campuran bumbu selama 15 menit. Goreng dalam minyak panas sampai matang. Sisihkan.\", \"Rebus spaghetti sampai al dente sesuai petunjuk pada kemasan. Sisihkan.\", \"Saus lada hitam: tumis bawang bombay sampai layu dan harum, masukkan potongan paprika, aduk sebentar lalu tambahkan garam, merica, gula pasir dan bubuk thyme, aduk rata. Tambahkan jahe dan kecap asin, aduk rata.\", \"Tambahkan air, masak sampai paprika empuk dan air menyusut setengahnya.\", \"Tambahkan larutan maizena dan aduk rata, masukkan udang goreng. Masak sekitar 5\' sampai kuah agak mengental dan agar bumbu meresap ke dalam udang. Saus sudah matang.\", \"Sajikan spaghetti dalam 2 porsi, siram saus ke atasnya, aduk rata. Spaghetti saus udang lada hitam siap disantap. Ba akhoin! 🍝\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2130, 3, 'Sambal Udang Tauco', 'Sambal Udang Tauco dengan udang segar dan bumbu khas.', '[\"250 gr udang kupas\", \"250 gr cabe rawit\", \"1 sdm tauco\", \"6 siung bawang merah\", \"3 siung bawang putih\", \"secukupnya Gula, Garam\"]', '[\"Potong-potong udang dan cabe rawit\", \"Haluskan bawang merah dan bawang putih\", \"Tumis udang hingga kemerahan, tambahkan bawang merah dan bawang putih yang sudah dihaluskan\", \"Masukkan tauco\", \"Tambahkan air, gula, dan garam secukupnya\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2131, 4, 'Brokoli Tahu Udang Lada Hitam', 'Resep Brokoli Tahu Udang Lada Hitam yang lezat dan mudah dibuat di rumah.', '[\"1 bungkus tahu sutra\", \"2 genggam brokoli\", \"1 genggam udang\", \"1 bawang bombay\", \"2 bawang putih\", \"secukupnya cabai rawit\", \"1 sdt maizena\", \"1 sdt lada hitam\", \"Secukupnya kaldu jamur, gula pasir, garam\", \"secukupnya air dan minyak goreng\"]', '[\"Goreng setengah matang tahu sutranya. Tumis irisan bombay dan bawang putih yang dicincang halus. Masukkan irisan cabai rawit.\", \"Masukkan udang sampai berubah warna, baru deh masukkan tahu lalu tambahkan air.\", \"Tuang larutan maizena, saus tiram, garam, lada hitam, kaldu jamur, gula. Jangan sering diaduk supaya tahu nggak mudah hancur. Terakhir masukkan brokoli. Jangan lupa cek rasanya ya. Selesai!\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2132, 4, 'Udang galah tepung asam manis', 'Resep praktis Udang galah tepung asam manis yang bisa dicoba di rumah.', '[\"250 gr udang galah\", \"Tepung bumbu sajiku\", \"1 bawang bombay\", \"3 siung bawang putih\", \"1 buah wortel,1 buah tomat\", \"3 cabe rawit + 2 cabe kriting\", \"secukupnya Saus sambal + saus tomat,saus tiram saori\", \"secukupnya Royco ayam\", \"1 sdm maizena,larutkan dengan sedikit air\", \"secukupnya Gula pasir dan garam\"]', '[\"Potong kepala udang,kupas kulit udang,sisakan ekornya,buang kotoran udang dengan cara belah bagian tengah belakang udang,cuci bersih,baluri dengan tepung bumbu,dan langsung goreng sampai udang habis,tiriskan\", \"Bawang putih digeprek dan dicacah,bawang bombay,tomat,cabe diiris,wortel dipotong\", \"Maizena dikasih sedikit air,aduk,sisihkan\", \"Tumis bawang putih,bawang bombay,wortel,cabe,tambahkan air,masukan royco, saus sambal,Saus tomat,saus tiram,gula dan garam secukupnya\", \"Selanjutnya masukan udang dan irisan tomat,aduk rata,koreksi rasa dulu yaaaa\", \"Terakhir masukan maizena yang telah dilarut dengan air,aduk rata sampai mengental,matikan api\", \"Tempatkan udang dipiring saji dan siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2133, 2, 'Udang 🍤Kuah 🍲special 🍜🍤', 'Hidangan seafood nikmat: Udang 🍤Kuah 🍲special 🍜🍤 untuk pecinta udang.', '[\"1/4 kg Udang kecil tanpa kepala lumuri jeruk nipis cuci bersih\", \"4 buah tahu putih potong goreng sampai berkulit\", \"2 batang Daun bawang potong\", \"1 buah bawang bombai potong\", \"5 siung bawang merah potong\", \"3 siung bawang putih potong\", \"4 cabe merah potong serong\", \"1/2 tomat merah potong\", \"1/2 tomat hijau potong\", \"2 sendok saus cabe\", \"1 sendok tepung maizena larutkan dg air\", \"Secukupnya minyak,gula garam penyedap\"]', '[\"Tumis bawang2an setelah layu masukkan cabai dan bawang bombai sampai layu.\", \"Masukkan tomat merah biarkan matang dan empuk bejek2 sampai hancur\", \"Tambahkan air,saus sambal,gula,garam,penyedap test rasa.\", \"Masukkan udang,daun bawang dan tomat hijau tambahkan maizena larut aduk2\", \"Tunggu mendidih diamkan 3mnt angkat dan sajikan...selamat mencoba..😊😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2134, 4, 'Sapo Tahu Ayam ala Mey👌', 'Sapo Tahu Ayam ala Mey👌 - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 bks Tofu\", \"5-10 bh filet ayam\", \"1 bh wortel, iris tipis menyerong\", \"5 bh jagung muda, iris tipis menyerong\", \"1/2 kuntum bunga kol, pisahkan jd kuntum2 kecil\", \"5 lbr pakcoy, iris 4-5 bag/lbr\", \"2 lbr daun kol, iris2\", \"2 sdm saos tiram\", \"3 sdm kecap asin\", \"1-2 sdm Royco ayam\", \"1,5 gls air\", \"Pengental : 1/2 gls air + 1 sdm sagu\", \"Bumbu halus :\", \"7 bh bamer\", \"4 bh baput\", \"1 sdt lada halus\", \"Minyak utk menumis\"]', '[\"Iris tofu, jgn terlalu tipis, nanti hancur, goreng..,sisihkan\", \"Siapkan sayur2annya, cuci, iris2, sisihkan (ups: pakcoynya hampir kelupaan)\", \"Tumis bumbu halus, dgn api kecil, hingga matang, masukkan filet ayam, aduk2 beri air, masak sampai mendidih\", \"Masukkan irisan wortel, jagung & brokoli, aduk tutup, biarkan sayur2an lunak & matang\", \"Beri saos tiram, kecap asin & Royco, aduk2\", \"Masukkan pakcoy & kol, aduk2, terakhir masukkan pengental, aduk rata, koreksi rasa\", \"Sayuran pindahkan kepiring/mangkok, tata tofu goreng diatasnya, siram dgn saosnya\", \"Sajikan\", \"Ini foto sapo tahu yg pertama sekali buat pagi tadi #dibuangsayang\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2135, 3, 'Perkedel Tahu Wortel Sederhana', 'Perkedel Tahu Wortel Sederhana - olahan tahu yang lezat dan bergizi.', '[\"1 bks tahu putih\", \"1 batang wortel (potong kecil-kecil)\", \"1/2 bks Masako ayam\", \"secukupnya Lada bubuk\", \"1 btr telur ayam (kocok)\", \"2 sdm terigu\", \"Minyak untuk menggoreng\"]', '[\"Hancurkan tahu dalam baskom\", \"Campurkan wortel yang telah di potong-potong, lada bubuk, masako, telur dan terigu\", \"Uleni hingga semua tercampur\", \"Ambil menggunakan sendok makan, masukkan ke dalam minyak panas, goreng hingga berwarna kecoklatan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2136, 3, 'Sundubu Jjigae (sup tahu pedas ala2 korea)', 'Cara membuat Sundubu Jjigae (sup tahu pedas ala2 korea) yang enak dan praktis untuk keluarga.', '[\"1 bungkus tahu putih, potong2 besar\", \"1/2 ons toge\", \"1/2 ons kol\", \"1-2 ons sawi putih\", \"1 tangkai daun bawang, iris serong agak tebal\", \"1/2 bulat bawang bombay, iris memanjang\", \"2-3 botol air\", \"2-3 sdm perasan jeruk nipis/limau/lemon\", \"1 telur, kocok lepas\", \"Bumbu halus :\", \"3 cabe merah besar\", \"3 cengek merah (ini pedesnya sedang)\", \"3 bawang merah\", \"1 bawang putih\", \"1 tomat sedang\"]', '[\"Haluskan bumbu (blender).\", \"Tumis bawang bombay sampai harum, lalu masukkan bumbu halus, beri air, tumis sampai bumbu matang\", \"Baru masukkan sayuran dan tahu, perasan jeruk, gula, kaldu ayam, garam, tes rasa.\", \"Kalo udah dirasa pas dan matang baru masukkan kocokan telur, aduk2 sampai telur matang, lalu matikan api. Langsung beri daun bawang atasnya. Selesai.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2137, 2, 'Nugget Tahu Ekonomis Anti Gagal', 'Resep Nugget Tahu Ekonomis Anti Gagal yang lezat dan mudah dibuat di rumah.', '[\"5 buah tahu(1kg an) sy: sekitar 700g\", \"1 butir telur\", \"4 siung bawang putih, haluskan\", \"1/2 bks ladaku\", \"Secukupnya garam(sy: garam di skip)\", \"2 bks royco sapi(sy: 1 bks)\", \"2 buah wortel,kupas kulitnya, lalu parut\", \"1 btg daun bawang, iris halus\", \"Bahan pelapis:\", \"Secukupnya telur, kocok lepas\", \"Secukupnya tepung roti/panir/bread crumb\"]', '[\"Cuci tahu dan tiriskan. Agar saat digoreng tidak rapuh atau nyemek.\", \"Haluskan tahu, lalu beri semua bumbu kecuali bahan pelapis. Aduk rata.(bisa koreksi rasa ketika telur belum ditambahkan, garam bisa disesuaikan karna setiap tahu ada yg asin dan tawar)\", \"Oles cetakan dengan minyak sayur. Masukkan adonan tahu lalu kukus selama 35 menit atau sampai matang. Tutup kukusan dilapisi serbet agar air tidak menetes.\", \"Setelah matang tunggu hingga dingin.\", \"Setelah dingin potong2. Siapkan bahan pelapis. Celupkan ke telur lalu ke tepung roti lakukan sampai habis. Nugget bisa langsung digoreng atau disimpan di frezzer. Sebaiknya menyimpan nugget tidak ditumpuk apabila ditumpuk alasi dengan kertas minyak/kertas roti agar tidak lengket.\", \"Goreng di api sedang. Lakukan satu balikan bila satu sisi sudah kering. Agar tidak menyerap banyak minyak.\", \"Sajikan hangat dengan saus sambal😄. Lebih enak lagi bila ditambah keju dan kornet😍. Next time dicoba pakai keduanya😊.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2138, 4, 'Tahu Petis musim ujan', 'Tahu Petis musim ujan - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 sdm petis\", \"2 bh cabe rawit,rajang\", \"2 bwg pth,rajang halus\", \"4 bwg mrh,rajang halus\", \"Secukupnya garam\", \"1/2 sdt maizena,larutkan dg 100 ml air\"]', '[\"Siapkan bahan2\", \"Goreng tahu smp matang..sementara itu kita rajang halus bumbu/diuleg jg boleh..\", \"Siapkan minyak dwajan ±3 sdm,masukkan bumbu & petis,aduk rata. Biarkan smp harum. Lalu masukkan larutan maizena,aduk lg.. Icip smp dpt rasa yg pas.. Sajikan dgn tahu goreng... Sedapp\", \"Drpd beli dluar,mending bkin sndiri yuk,rempong sdkit gpp demi kluarga trsayang..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2139, 4, 'Sayur tahu jengkol', 'Resep Sayur tahu jengkol ala rumahan yang dijamin menggugah selera.', '[\"10 buah tahu kuning\", \"1/4 jengkol\", \"2 bungkus Santan kara\", \"Garam\", \"Kaldu bubuk\", \"Gula putih\", \"Daun salam\", \"Bumbu halus :\", \"6 siung bawang merah\", \"5 siung bawang putih\", \"8 buah cabe merah besar\", \"5 butir kemiri\"]', '[\"Bersihkan jengkol dan rebus sampai empuk. Jika sudah dingin geprek jengkol agar bumbu meresap.\", \"Potong tahu bentuk segitiga dan goreng sampai matang. Klo saya cenderung agak kering kecoklatan.\", \"Tumis bumbu halus sampai wangi dan matang. Masukan daun salam, tahu dan jengkol lalu beri air. Biarkan sampai mendidih!!!\", \"Berikan santan kara dan garam, kaldu bubuk serta gula putih. Biarkan kuah agak menyusut agar bumbu meresap. Jangan lupa aduk aduk kuah agar santan tidak pecah. Terakhir tes rasa!!! Selamat mencoba.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2140, 4, 'Sapo Tahu No Seafood', 'Cara membuat Sapo Tahu No Seafood yang enak dan praktis untuk keluarga.', '[\"2 pcs Egg Tofu (potong2 ketebalan sesuai selera)\", \"2 bonggol Brokoli (sy uk.kecil2, siangi, potong perkuntum)\", \"1 bonggol Bunga Kol (sy uk.sedang, potong perkuntum)\", \"1 bonggol Sawi putih (sy uk.kecil, potong2)\", \"1-2 btg Wortel (iris bulat/serong terserah)\", \"Secukupnya Jamur Kancing (bisa pake jamur kuping, iris2 sesuai selera)\", \"1 helai Daun bawang iris2\", \"5 btr Bakso ayam iris2 (bisa pake bakso lain/seafood/daging ayam cincang)\", \"1 siung Bawang Bombay uk.sedang (potong wedges)\", \"5 siung Bawang putih geprek, cincang\", \"° Bumbu :\", \"1 sdm penuh Saus Tiram (sy Saori)\", \"1/2 sdt Garam (menyesuaikan selera)\", \"1/2 sdt Gula pasir (menyesuaikan selera)\", \"1/4 sdt Royco ayam (boleh gapake)\", \"1/4 sdt Lada bubuk\", \"1 sdm Kecap manis Bango (kalo sy wajib/rutinitas hihihi)\", \"Secukupnya Air Kaldu (sy pake kuah bakso hihi)\"]', '[\"Goreng garing/sampai berkulit si tofu yaa. Sisihkan dulu.\", \"Siapkan semua bahan. Sayuran dicuci semua. Bumbu2 juga dipersiapkan yaa. Kalo sy, wortel-brokoli-bunga kol-jamur kancing sy blansir sbentar (rendam air panas bentar, lalu ke air dingin spya lebih cpt ngolahny, warna sayurnya juga segerr) Yuk memasak..\", \"Panaskan margarin/minyak scukupny, tumis bawang putih dan bombay hingga layu dan harum\", \"Masukkan sawi putih (ngga sy blansir), daun bwang, tumis bentar.\", \"Masukkan jamur, aduk rata\", \"Tuang sesuai selera bbrp sendok sayur air kaldu/sy kuah bakso. Kurleb sy 2-3 sendok sayur. Didihkan. Msukkan sisa sayuran.\", \"Bumbui saus tiram, gula garam, lada, kecap, royco bila perlu. Sampai rasa pas. (Kalo sy sblumnya dah gurih kena kuah bakso, jd tinggal ngoreksi)\", \"Masukkan bakso iris, aduk rata\", \"Terakhir masukkan tofu. Aduk perlahan. Masak sampai cukup matang. Dah... Siap!\", \"Sapo tahunya siap dilahaaapp... Makan sapo nih enaknya sambil nikmatin hawa sejuk hujan ya moms. Mantap, anget2 gurih gitu hihi. Selamat makan :)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2141, 3, 'Tahu Bulat', 'Resep praktis Tahu Bulat yang bisa dicoba di rumah.', '[\"20 bh Tahu putih\", \"Minyak untuk menggoreng\", \"Bumbu halus :\", \"5 bh Bawang putih\", \"1/2 sdt Merica\", \"2 1/2 sdt Garam\", \"sesuai selera Kaldu bubuk\"]', '[\"Haluskan tahu dengan garpu.\", \"Saring tahu dengan kain berpori halus, peras pelan pelan hingga kadar airnya berkurang banyak. Cara menyaring tahu begini sebaiknya sedikit sedikit dan memerasnya jangan terlalu kuat.\", \"Setelah airnya di peras,campur tahu dengan bumbu halus, aduk rata. bentuk bulat.\", \"Panaskan minyak dengan api sedang. Masukan tahu bulat, goreng hingga kuning kecokelatan.Sajikan hangat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2142, 2, 'Tahu kuning lada garam', 'Resep Tahu kuning lada garam ala rumahan yang dijamin menggugah selera.', '[\"1 bj tahu kuning (sy pakai merk yongfu)\", \"1 bj cabe merah besar\", \"1 bj cabe rawit (krg tahan pedas)\", \"2 siung bawang putih, rajang\", \"1 siung bawang merah, potong tipis2\", \"Secukupnya garam, lada, kaldu jamur\"]', '[\"Panaskan minyak di teflon, goreng tahu hingga berubah warna. Stlh matang, tiriskan\", \"Lalu tuang minyak sedikit di teflon, tumis bawang putih dan bawang merah hingga harum. Stlh itu masukkan cabe. Masukkan tahu goreng, aduk rata. Lalu tambahkan garam, merica dan kaldu jamur. Tes rasa. Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2143, 3, 'Pepes Tahu kekinian', 'Pepes Tahu kekinian - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"2 tahu cina di hancurkan halus dengan garpu boleh menggunakan tahu putih apa saja tdk mesti tahu cina\", \"3 batang bawang daun diiris 1 ruas jari\", \"2 butir telor\", \"Daun salam dimasukkan ke dalam tiap adonan pepes ketika membungkus\", \"1 sdt gula pasir\", \"1.5 sdt garam\", \"1 sdt penyedap rasa jika suka\", \"Bumbu halus diblender:\", \"10 biji cabe rawit jawa\", \"1 terasi ABC\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"2 batang serai diiris tipis\", \"2 sdm minyak untuk menumis\"]', '[\"Hancurkan Tahu dengan garpu lalu masukkan telor dan daun bawang. Sisihkan\", \"Tumis bumbu halus lalu cicipi sampai rasa sesuai dengan lidah dan selera.. diamkan hingga dingin\", \"Campur bumbu matang lalu masukkan ke dalam tahu yg sudah dihaluskan masukkan gula aduk rata. Jika rasa sudah sesuai lalu siapkan daun yg sudah dipotong potong rapi siap dipakai untuk membuat pepes tahu\", \"Masukkan 1-2 sdm adonan tahu ke dalam daun masukkan daun salam 1 lembar lalu sematkan dengan rapi dengan tusuk gigi.. selasaikan adonan hingga habis\", \"Setelah air mendidih kukus pepes selama 30 mnt lalu setelah matang sajikan hangat dengan nasi serta makanan sampingan lainnya.\", \"Note: biasanya saya suka membuat bumbu dasar seperti resep diatas jadi jika saya ingin membuat olahan berbagai macam pepes saya tinggal menggunakan bumbu halus yg sudah ada,\", \"Jika ingin membuat pepes ayam tinggal tambahkan jahe yg sudah dihaluskan dan irisan daun jeruk serta irisan tomat jika suka.. tambahkan 2 sdt kecap ikan diadonan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2144, 4, 'Mung tahu\'', 'Mung tahu\' - olahan tahu yang lezat dan bergizi.', '[\"1 papan tahu sutera\", \"200 gr daging ayam\", \"Daun bawang\", \"B.putih\", \"2 sdm tepung maizena larutkan d air\", \"secukupnya Micin jamur, garam, gula, lada\"]', '[\"Tumis b.putih cincang, hingga harum. Masukan ayam lalu aduk\\\" sampai berubah warna\", \"Potong\\\"tahu sesuai selera, masukan bumbu\\\" seperti garam, gula, lada, masukan kedalam penggorengan, aduk\\\" kasih air sedikit masukan t.maizena tunggu sebentar masukN daun bawang, angkt\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2145, 3, 'Sapo Tahu Brokoli', 'Resep Sapo Tahu Brokoli yang lezat dan mudah dibuat di rumah.', '[\"1 bungkus tahu telur\", \"1 bonggol brokoli\", \"2 buah wortel (iris tipis)\", \"1/5 kol (lebih enak pakai sawi putih)\", \"1 buah cabai merah besar\", \"4 buah bakso sapi\", \"4 buah bakso ikan (optional)\", \"2 siung bawang putih\", \"1/2 bawang bombay\", \"1 ruas jahe (geprek)\", \"1 sachet saus tiram (Saori)\", \"1 sdm kecap asin\", \"1 sdt gula pasir\", \"1/2 sdt garam\", \"1 sdt lada bubuk\", \"1 sdm tepung maizena\", \"1 gelas air putih\", \"Minyak sayur\"]', '[\"Cuci sayur dan bahan lainnya, rendam brokoli dalam air panas selama 30 detik\", \"Cincang halus bawang putih, iris bawang bombay, bakso, wortel dan cabai merah\", \"Potong lalu goreng tahu telur, setelah matang tiriskan\", \"Tumis bawang putih, bawang bombay dan jahe sampai harum\", \"Masukkan irisan wortel, tumis sebentar lalu tambahkan 1 gelas air\", \"Setelah air mendidih dan wortel sedikit layu, masukkan saus tiram, kecap asin, gula, garam, lada\", \"Koreksi rasa dan masukkan sisa bahan (kol, cabai merah, brokoli) campur rata\", \"Diamkan kurang lebih 1 menit. Terakhir tambahkan larutan maizena\", \"Aduk sampai kuah mengental lalu sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2146, 2, 'Tahu isi Enak', 'Nikmati kelezatan Tahu isi Enak dengan resep sederhana ini.', '[\"5 bh tahu dibelah dua\", \"1 bh bengkuang\", \"1 bh wortel\", \"1/2 bombay iris halus\", \"4 siung bawang putih\", \"150 gr udang cincang\", \"tepung bumbu sajiku\", \"secukupnya Garam Gula merica\", \"Sambal cocolan:\", \"2 siung bawang putih\", \"1 bh cabe rawit merah\", \"1 sdt saos cabe abc\", \"2 sdm perasan air jeruk nipis/lemon\", \"1/2 sdt gula\", \"Sedikit air\"]', '[\"Tunis Bombay Dan bawang Putih sampai harum, Masukkan Udang kemudian wortel Dan bengkuang yang Sudah di iris halus. Masukkan bumbu penyedap garam Gula America secukupnya.\", \"Tambah kan air sedikit Dan masak sampai matang. Sisihkan.\", \"Belah 2 tahu Dan goreng 1/2 matang. Angkat. Sisihkan.\", \"Setelah tahu tidak terlalu panas. Belah tengah tahu untuk isian. Dan Isi tahu dengan tumisan wortel dan bengkuang tadi.\", \"Buat adonan basah tepung sajiku dengan sedikit air. (Jangan terlalu kental).\", \"Balur tahu Dalam adonan tepung kemudian goreng dengan minyak panas.\", \"Siap dihidangkan dengan sambal cocolan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2147, 2, 'Tahu cabe garam', 'Nikmati kelezatan Tahu cabe garam dengan resep sederhana ini.', '[\"3 potong tahu (iris kotak kecil)\", \"1 butir telur\", \"Secukupnya tepung bumbu serbaguna\", \"2 siung bawang merah\", \"3 siung bawang putih\", \"4 biji cabe rawit (sesuai selera)\", \"2 batang daun bawang (sy pke daun seledri krn cm itu yg ada 😅)\"]', '[\"Lumuri tahu dengan kocokan telur kemudian balurkan pada tepung, goreng hingga kuning keemasan lalu tiriskan.\", \"Tumis bawang putih, bawang merah dan cabe rawit hingga harum kemudian masukkan tahu yang telah digoreng.\", \"Masukkan daun seledri, tambahkan garam, gula dan penyedap, aduk rata.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2148, 4, 'Tahu Cabe Garam', 'Resep Tahu Cabe Garam yang lezat dan mudah dibuat di rumah.', '[\"2 buah tahu putih (potong persegi kecil)\", \"2 bks kecil tepung bumbu pedas serbaguna (mamaSuka)\", \"1/4 cup Air ES\", \"2 sdm terigu\", \"secukupnya Minyak goreng\", \"3 siung bawang putih (cincang)\", \"2 buah bawang merah (cincang)\", \"2 sdm irisan daun bawang\", \"2 sdt garam\", \"1 sdt kaldu bubuk\", \"1 sdt margarine untuk tumis\", \"10 buah cabai rawit merah (iris tipis)\", \"5 buah cabai rawit hijau (iris tipis)\"]', '[\"Larutkan 1 bks tepung bumbu+ 2 sdm terigu dengan 1/4cup air es (benar2 dingin)..\", \"Panaskan minyak sampai benar2 panas, & ukur agar tahu terendam (deep fry)..\", \"Tahu yg sudah di potong di celupkan ke larutan tepung, kemudian gulingkan ke tepung bumbu kering,.\", \"Goreng dengan api sedang sampai matang, sisihkan(pastikan minyak benar2 panas, agar tahu crispy)\", \"Goreng cabai-duo bawang & daun bawang sampai kekuningan.. angkat, tiriskan.. tumis dengan 1sdt margarine, tambahkan garam & kaldu bubuk.. matikan api.. masukkan tahu & tambahkan garam jika dirasa kurang.. aduk rata. sajikan hangat..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2149, 4, 'Tumis Broccoli Tahu Jepang dengan Saus Tiram', 'Sajian Tumis Broccoli Tahu Jepang dengan Saus Tiram yang praktis dan lezat untuk dinikmati bersama.', '[\"1 bonggol Brokoli ukuran besar (potong dan cuci)\", \"3 pcs Tahu Jepang (potong ketebalan 1.5 cm)\", \"2 pcs Jamur King Oyster (iris tebal)\", \"5 pcs Bakso Seafood (optional)\", \"5 siung Bawang Putih (cincang)\", \"1 ruas Jahe (kupas dan iris halus)\", \"Garam, lada, gula / vetsin untuk memperkuat rasa\", \"Oyster Sauce / Saus Tiram\", \"Kecap Hitam\", \"Tepung Maizena / Potato Starch (untuk pengental)\"]', '[\"Rebus brokoli selama 2-3 menit. Angkat dan sisihkan. Jangan terlalu lama merebut sayur, karena nanti sayurnya akan menjadi layu, dan vitaminnya akan terbuang.\", \"Panaskan wajan, tunggu sampai minyak benar2 panas. Baru goreng tahu sampai warnanya kecoklatan. Angkat dan sisihkan.\", \"Sisihkan di piring.\", \"Panaskan wajan kembali. Tumis daging / bakso sampai ada gosong2nya sedikit. Ingat kata chef Gordon Ramsay \\\"No Color, No Flavour\\\". Hehehe..\", \"Setelah itu masukkan bawang putih dan jahe. Tumis hingga harum.\", \"Masukkan air (saya pakai 300 ml). Tambahkan garam, lada, gula / vetsin, kecap asin hitam, dan saus tiram.\", \"Jika rasanya sudah pas. Tambahkan maizena / potato starch yg sudah dilarutkan dengan air. Aduk sampai konsistensinya kental. (Saya lebih suka memasak menggunakan Potato Starch. Karena saus menjadi tidsk mudah cair, dibandingkan dgn menggunakan maizena).\", \"Setelah itu baru masukkan jamur. Tunggu sampai mendidih sebentar. Sampai jamur matang. Angkat.\", \"Tuang saos diatas brokoli dan tahu jepang yg sudah disusun di piring. Sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2150, 2, 'Cah sawi hijau tahu putih', 'Resep praktis Cah sawi hijau tahu putih yang bisa dicoba di rumah.', '[\"1 ikat sawi hijau, aku beli 2 rb\", \"3 buah tahu putih potong kotak goreng 1/2 mateng\", \"3 buah bawang merah iris\", \"2 siung bawang putih cincang\", \"3 buah cabe m dan rawit m iris tipis\", \"Minyak g secukupnya untuk menumis\", \"1/4 sdt gula pasir\", \"Royco ayam\", \"1/2 sdt Saos tiram dan kecap asin\"]', '[\"Tumis bamer baput, dan cabe. Tambahkan sawi,tahu aduk rata. Masukan saos tiram, kecap asin dan royco gula pasir tambahkan air sedikit, tutup sbentar\", \"Aduk rata. Angkat, sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2151, 3, 'Bakso tahu goreng saus pedas', 'Bakso tahu goreng saus pedas - olahan tahu yang lezat dan bergizi.', '[\"Bahan bakso tahu\", \"8 buah tahu putih\", \"2 siung bawang putih\", \"1 butir telur\", \"1 sdt merica bubuk\", \"secukupnya Royco ayam\", \"secukupnya Garam\", \"secukupnya Gula\", \"3 sdm tepung terigu\", \"1 sdt baking powder\", \"Bahan saos pedas\", \"4 siung baput\", \"4 siung bamer\", \"1/2 bawang bombay\", \"5 buah cabe merah keriting\", \"15 bua cabe rawit\", \"4 sdm saos tomat\", \"4 sdm saos sambal\", \"1 buah cabe merah iris rencong\", \"1 buah bawang prei\", \"Garam\", \"1 sdm Kecap\", \"secukupnya Gula\", \"Minyak goreng\", \"secukupnya Air\"]', '[\"Hancurkan tahu,peras airnya hingga airnya habis\", \"Kemudian masukkan bawang putih halus,tepung telur,merica,gula pasir,royco cek rasa ya\", \"Kemudian bentuk bulat2 sesuai selera\", \"Panaskaninyak goreng bakso tahu hingga kecoklatan.angkat sisihkan\", \"Cara membuat saos. Haluskan cabeerah dan bawang putih beri garam sedikit hingga halus.\", \"Kemudian memarkan cabe rawit atau pecah pecah saja..\", \"Panaskan minyak tumis bawang bombay hingga layu masukkan bumbu halus,tumis hingga harum.\", \"Kemudian masukkan saos tomat,kecap,saos sambal sedikit air, masak hingga meletup letup masukkan gula cek rasa kemudian masukka bakso tahu irisan cabe merah,daun bawang masak hingga matang\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2152, 2, 'Tumis Tahu Bubuk', 'Kreasi tahu nikmat: Tumis Tahu Bubuk untuk variasi menu harian.', '[\"8 Tahu Kuning\", \"5 Siung Bawang Merah\", \"4 Siung Bawang Putih\", \"1 Buah Tomat\", \"5 Cabai Rawit\", \"Bawang Daun\", \"Secukupnya Garam\", \"Secukupnya Gula\", \"Secukupnya Lada Putih\"]', '[\"Tumbuk kasar tahu kuning. Sisihkan.\", \"Tumis bawang merah, bawang putih, cabai rawit dan tomat hingga harum.\", \"Masukan tahu yang sudah dihancurkan. Tambahkan garam, gula, lada putih, bawang daun dan sedikit air. Masak hingga air menyusut dan tahu matang. Sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2153, 2, 'Tahu Crispy', 'Nikmati kelezatan Tahu Crispy dengan resep sederhana ini.', '[\"bumbu halus\", \"2 siung bawang putih\", \"kunyit\", \"1/4 sdt ketumbar\", \"bahan tepung\", \"6 sdm tepung terigu\", \"1 sdm maizena\", \"secukupnya garam, lada, kaldu jamur\", \"secukupnya air\", \"1 btr telur ayam\", \"tahu potong2 dadu\"]', '[\"Tumbuk bumbu halus, beri air\", \"Potong tahu rendam dalam bumbu min 10mnt\", \"Campur bahan tepung\", \"Gulingkan tahu ke tepung lalu ke telur\", \"Goreng hingga kuning keemasan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2154, 2, 'Sayur bening BATA JAWO(bayem tahu jagung wortel)', 'Sayur bening BATA JAWO(bayem tahu jagung wortel) - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 ikat bayam petik daunnya\", \"1 buah jagung muda pipil\", \"1/2 bh tahu putih iris dadu\", \"1 bh wortel iris tipis\", \"2 siung bwg merah\", \"2 lembar daun salam\", \"secukupnya Gula\", \"secukupnya Garam\", \"secukupnya Air\", \"Penyedap(optional)\"]', '[\"Siapkan bahannya cuci bersih.iris tipis bawang merah.goreng tahu sebentar.\", \"Siapkan panci.masukkan bawang merah,air,wortel,jagung dan daun salam.tunggu sampai mendidih serta wortel dan jagung empuk\", \"Setelah empuk masukan garam,gula dan penyedap koreksi rasa\", \"Masukan tahu goreng dan bayam.masak sampai mendidih saja jangan sampai bayam overcook.angkat dan sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2155, 4, 'Tahu balado aku', 'Tahu balado aku - olahan tahu yang lezat dan bergizi.', '[\"Tahu kuning 10 (potong dadu)\", \"Minyak\", \"Sasa\", \"Royco\", \"Gula\", \"Garam\", \"\\\"Untuk pemakaian sasa n Royco sebaik nya jangan terlalu banyak.\", \"Salam\", \"Bumbu2 :\", \"10 Cabe keriting\", \"5 Cabe rawit\", \"10 Bawang merah\", \"4 Bawang putih\", \"1 Tomat\"]', '[\"Goreng tahu\", \"Halus kan semua bumbu...kemudian tumis sampai matang...masukan garam sasa gula dan salam\", \"Kemudian masukan tahu..aduk sampai rata dan bumbu meresap\", \"Setelah itu matikan kompor...jadi deh tahu balado nya\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2156, 2, 'Sop Tahu Sederhana', 'Resep Sop Tahu Sederhana ala rumahan yang dijamin menggugah selera.', '[\"Bahan isian:\", \"3 bh tahu putih potong dadu\", \"secukupnya Kol\", \"secukupnya Wortel\", \"2 bh sosis ayam potong² serong\", \"3 sdm makaroni rebus\", \"Seledri\", \"Daun bawang\", \"Bumbu halus:\", \"secukupnya Merica\", \"3 siung bawang putih\", \"2 siung bawang merah\", \"Gula\", \"Garam\", \"Kaldu ayam bubuk\", \"Bumbu sop²n:\", \"2 bh kapulaga\", \"1 bh cengkeh\", \"secukupnya Kayumanis\", \"1 bh bunga lawang\", \"Pelengkap:\", \"1 butir telur rebus diiris tipis\", \"sesuai selera Cabe rawit utuh\", \"Jeruk\", \"Bawang goreng\"]', '[\"Tumis bumbu halus dalam minyak panas secukupnya... Masukan wortel, sosis, tahu dan makaroni.. Kemudian angkat.\", \"Panaskan panci berisi air secukupnya. Kemudian masukan tumisan bumbu dan sayur tadi.. Masak hingga mendidih.\", \"Jika sudah mendidih tambahkan kol beserta rawit. Lalu matikan api, masukan seledri dan daun bawang. Tambahkan gula garam beserta kaldu ayam.\", \"Lalu...sajikan..dg nasi hangat jgn lupa pelengkapnyaaa yaaaa...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2157, 2, 'Tumis sawi, tahu cambah,', 'Cara membuat Tumis sawi, tahu cambah, yang enak dan praktis untuk keluarga.', '[\"Sawi putih 6lebar\", \"Cambah, tahu putih\", \"Tomat, bawang merah,putih cabe, sereh,\", \"Bumbu halus kemiri 3butir,jahe 4 iris, kencur 3 iris, air,\"]', '[\"Potong tahu putih kotak2, trus di goreng seteh mateng,\", \"Sawi putih potong, bawang putih merah, cabe, di iris, tomat,iris,sereh di keprok,\", \"Tumis bawang putih sudah di iris berseta sereh, udah harum masuk kan bumbu yg di halus kan, tumis hinga harum, masukan air secukup nya\", \"Masuk kan sawi putih, cambah, udah agak mpuk sayur baru masuk kan tahu,, sama tomat,,\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2158, 4, 'Tahu Crispy Cabe Garam', 'Kreasi tahu nikmat: Tahu Crispy Cabe Garam untuk variasi menu harian.', '[\"2 bh Tahu, potong dadu agak besar\", \"Tepung Bumbu Serbaguna\", \"1 bonggol Bawang Putih, cincang\", \"5 bh Cabe Rawit, potong2 (bs ditambah/dikurangi)\", \"1 batang Bawang prei, iris serong\", \"secukupnya Garam+Merica+Kaldu ayam bubuk (optional)\", \"1-2 sdm Butter/Margarin\"]', '[\"Balur tahu dg tepung bumbu, goreng sampe matang, sisihkan\", \"Tumis bawang putih (sisakan ±1sdm) pakai butter sampai garing kecokelatan, tiriskan. Api kecil sj, hati2 gosong\", \"Tumis sisa bawang putih sampe wangi, masuk cabe potong, tumis sebentar\", \"Beri garam+merica+penyedap, masukkan tahu goreng, aduk rata\", \"Matikan api, masuk bawang prei, aduk sebentar\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2159, 2, 'Perkedel Tahu', 'Resep Perkedel Tahu yang lezat dan mudah dibuat di rumah.', '[\"10 buah tahu sutra\", \"2 butir telur\", \"3 siung bawang merah\", \"2 siung bawang putih\", \"secukupnya ketumbar bubuk\", \"secukupnya daun bawang\", \"secukupnya garam\"]', '[\"Haluskan tahu sutra\", \"Iris halus bamer, baput, dan daun bawang\", \"Masukan telur, garam, ketumbar bubuk. koreksi rasa\", \"Goreng hingga matang warna kecoklatan\", \"Siap disajikan dengan nasi hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2160, 3, 'Tahu kuah kuning simple', 'Resep praktis Tahu kuah kuning simple yang bisa dicoba di rumah.', '[\"6 potoh tahu (belah 2)\", \"2 daun salam\", \"Garam, gula, penyedap rasa secukup nya\", \"Bumbu halus :\", \"6 buah bawang merah\", \"3 buah bawang putih\", \"5 Cabe merah\", \"2 buah kemiri\", \"secukupnya Kunyit, kencur\", \"1/2 Tomat\"]', '[\"Potong2 tahu, kemudian cuci.\", \"Tumis bumbu yang telah dihaluskan, jika sudah harum masukan air dan daun salam.\", \"Jika sudah mendidih masukkan tahu, beri garam, gula dan penyedap rasa.\", \"Tunggu hingga matang dan sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2161, 4, 'Martabak Tahu Kulit Lumpia', 'Kreasi tahu nikmat: Martabak Tahu Kulit Lumpia untuk variasi menu harian.', '[\"12 Lembar Kulit Lumpia\", \"4 Buah Tahu Putih\", \"2 Batang Daun Bawang (Iris Halus)\", \"1 Batang Daun Seledri (Iris Halus)\", \"3 Butir Telur\", \"1 Sdm Tepung Terigu + 2 Sdm Air (sebagai lem kulit lumpia)\", \"Secukupnya Minyak Goreng untuk menggoreng\", \"Bumbu Halus :\", \"3 Buah Bawang Merah\", \"2 Siung Bawang Putih\", \"1/2 Bungkus Lada/ Merica Bubuk\", \"Secukupnya Garam\", \"Secukupnya Gula\"]', '[\"Haluskan Tahu Putih, lalu campur semua bahan (kecuali kulit lumpia dan minyak), uji rasa sisihkan\", \"Ambil 1 lembar kulit lumpia, beri 1 Sdm Adonan tahu di tengahnya, lalu lipat (seperti amplop) lipat dengan rapi, lalu beri lem disetiap sisinya. (lakukan bertahap hingga kulit dan adonan habis)\", \"Panaskan minyak diatas wajan dengan api sedang cenderung kecil, goreng martabak hingga matang dan berubah warna, angkat dan tiriskan.\", \"Martabak Tahu Kulit Lumpia siap dihidangkan.\", \"Selamat mencoba guys, semoga bermanfaat 😁👌, salam Baking dari saya.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2162, 4, 'Tahu isi soun', 'Resep Tahu isi soun ala rumahan yang dijamin menggugah selera.', '[\"15 buah tahu mateng/isi\", \"1 bks soun\", \"1 batang daun bawang\", \"2 sdt royko ayam\", \"Minyak goreng\", \"Tepung bakwan\", \"10 sdm tepung beras\"]', '[\"Rendam soun di air hangat, iris tipis daun bawang, lalu tumis sebentar dgn minyak goreng tambah kan daun bawang, pake api kecil aja supaya soun tdk lengket di wajan. Isi tahu\", \"Buat adonan dgn tepung krna praktis tepung bakwan jd tdk usah tmbh garam lg. Celupkan tahu isi ke dlm adonan dan goreng dlm minyak sampai kecoklatan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2163, 2, 'Kikil tahu sambal', 'Kikil tahu sambal - olahan tahu yang lezat dan bergizi.', '[\"1/4 kikil\", \"3 buah tahu putih/ tahu kuning\", \"15 buah cabai merah\", \"1 siung kecil bawang putih\", \"4 siung bawang merah\", \"5 buah cabai hijau\", \"2 buah tomat\", \"secukupnya Garam\", \"secukupnya Air\", \"Minyak untuk menggoreng\"]', '[\"Rebus kikil terlebih dahulu\", \"Blender bawang merah 3 siung, bawang putih, cabai merah dan tomat\", \"Iris serong cabai hijau. Iris 1 siung bawang merah.\", \"Angkat kikil, potong dan sisihkan.\", \"Goreng tahu, angkat dan tiriskan.\", \"Panas kan minyak, masukan bawang merah yang sudah diiris, masukkan bumbu cabai yang sudah diblender, dan masukan cabai hijau yang sudah di iris. Masak selama 3 menit, lalu masukkan kikil, tambahkan air sedikit, dan garam secukupnya. Masak lagi hingga air habis, masukkan tahu, aduk.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2164, 2, 'Asinan tahu melotot', 'Asinan tahu melotot - olahan tahu yang lezat dan bergizi.', '[\"10 butir tahu putih uk kecil\", \"1 butir telur\", \"4 sdm terigu\", \"bumbu halus\", \"3 siung bawang putih\", \"secukupnya ketumbar,merica,garam,penyedap.sesuai selera\", \"bumbu asinan\", \"15 butir cabai rawit\", \"2 butir cabai merah kriting\", \"1 sdm gula putih\", \"1 siung bawang putih\", \"air panas\", \"5 buah asam\", \"secukupnya garam\"]', '[\"Haluskan tahu,masukan telur,terigu,bumbu halus.uleni merata.goreng\", \"Ulek semua bumbu kecuali asam.setelah halus masukan air panas rendaman asam.\", \"Siram saus di atas tahu.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2165, 2, 'Pepes Tahu Pedas', 'Sajian Pepes Tahu Pedas yang praktis dan lezat untuk dinikmati bersama.', '[\"1-2 kotak tahu\", \"🌸Bumbu Halus :\", \"7 buah Bawang Merah\", \"4 buah Bawang Putih\", \"5 buah cabe merah\", \"15 buah cabe kecil (selera)\", \"3 buah Kemiri\", \"2 cm terasi\", \"1 sdt gula merah\", \"1/2 sdt merica bubuk\", \"Secukupnya garam gula\", \"🌸Pelengkap:\", \"4 lembar daun jeruk (iris lembut)\", \"Secukupnya daun pisang\"]', '[\"Haluskan bumbu halus+ garam+ gula, lalu campur dengan irisan daun jeruk, Tes Rasa\", \"Siapkan daun pisang, potong2 tahu + beri bumbu halus secukupnya lalu bungkus dengan daun pisang\", \"Kukus selama kurang lebih 20 menit, Sajikan..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2166, 2, 'Tahu Aci ala\"', 'Resep Tahu Aci ala\" ala rumahan yang dijamin menggugah selera.', '[\"10 potong Tahu kuning (potong sesuai selera)\", \"200 gram Tepung sagu (aci)\", \"50 gram Tepung terigu\", \"Secukupnya daun bawang (iris)\", \"5 siung bawang putih (ulek)\", \"Secukupnya ketumbar bubuk\", \"Garam (penyedap rasa)\", \"Air mendidih (kira\\\" aja)\"]', '[\"Rebus air + bawang putih ulek\", \"Campur semua tepung + daun bawang iris dalam baskom\", \"Tuang air mendidih kdalam campuran tepung sedikit demi sedikit sampai adonan bisa dpulung lalu tambahkan ketahu yg sudah dptong\\\"\", \"Goreng hingga kuning keemasan\", \"Sajikan hangat + sambal kecap 😂\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2167, 3, 'Tahu sumpel/tahu isi sayuran', 'Resep Tahu sumpel/tahu isi sayuran ala rumahan yang dijamin menggugah selera.', '[\"20 pcs tahu coklat/goreng\", \"3 bungkus toge\", \"2 buah wortel\", \"Secukupnya daun bawang(potong2)\", \"Bumbu tumis untuk isi tahu :\", \"5 buah cabai rawit merah\", \"3 siung bawang putih\", \"2 siung bawang merah\", \"Lada bubuk\", \"Garam\", \"Penyedap rasa\", \"1/5 kg terigu\", \"Minyak untuk menggoreng\", \"Bumbu halus untuk adonan luar :\", \"3 siung bawang putih\", \"1 sdm ketumbar\", \"Kunyit(jangan terlalu banyak untuk warna kuning saja di adonanya)\"]', '[\"Kupas wortel lalu potong korek api.campurkan dengan toge lalu cuci bersih.\", \"Cuci tahu peras n keluarkan isinya.\", \"Potong cabai,bawang merah&bawang putih.\", \"Panaskan minyak jangan terlalu banyak hanya untuk menumis tunggu panas masukan bumbu,tumis sampai harum lalu masukan toge,wortel,isi dalam tahu,garam,penyedap&lada bubuk,aduk rata,test rasa sisihkan.\", \"Campur bumbu halus,terigu,daun bawang&air secukupnya.adonan jangan terlalu encer ya agar isiaan tahu tidak keluar2 pada saat di goreng.\", \"Isi tahu coklat/goreng dengan sayuran yg di tumis td masukan hingga full,lakukan sampai habis.\", \"Siapkan minyak agak banyak ya biar terendam tahunya.masukan tahu isi kedalam adonan lalu masukan ke dalan minyak panas lakukan sampai habis.\", \"Tahu sumpel/tahu isi sayuran siap di hidangkan😉😉😉\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2168, 3, 'Sayur nDeso (Sayur Tahu Cabe Ijo)', 'Resep praktis Sayur nDeso (Sayur Tahu Cabe Ijo) yang bisa dicoba di rumah.', '[\"8 potong tahu putih, rebus lalu potong2\", \"1 papan tempe, potong kecil2\", \"2 papan pete, kupas\", \"500 ml santan dari setengah butir kelapa\", \"1 liter air\", \"Bumbu tumis:\", \"6 bawang putih, iris tipis\", \"6 bawang merah, iris tipis\", \"1 bawang bombay, iris2\", \"10 cabe rawit, iris serong\", \"100 gr cabe ijo, iris serong\", \"4 lembar daun salam\", \"Bumbu:\", \"1 sdm garam\", \"1 sdm gula\", \"1/2 sachet royco\"]', '[\"Panaskan minyak, tumis bumbu tumisan sampai layu & wangi. Masukkan tahu, tempe & pete, aduk2 sampai tercampur rata. Masukkan air, masak sampai mendidih.\", \"Setelah mendidih, masukkan santan dan bumbu (gula garam royco), masak sampai matang sambil diaduk2, agar santan tidak pecah.\", \"Cicipi & koreksi rasa\", \"Sajikan bersama ikan asin / gorengan favorit. Aku pake ikan asin layur & bakwan jagung\", \"Bakwan jagungnya pake tepung bakwan jagung instan dari sajiku\", \"Ikan asin layurnya : cuci bersih ikan asin, baluri dengan tepung beras, goreng sampe coklat keemasan. Renyah banget deh, kriuk2 banget\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2169, 3, 'Martabak isi tahu pedas', 'Resep Martabak isi tahu pedas yang lezat dan mudah dibuat di rumah.', '[\"20 lembar kulit lumpia(beli jadi)\", \"1 buah tahu cina\", \"Secukupnya daun bawang(potong2)\", \"5 buah cabai rawit merah(potong2)\", \"Penyedap rasa\", \"1 butir telur(kocok,untuk merekatkan kulit lumpia)\", \"Garam\"]', '[\"Siapkan wadah,Cuci tahu lalu hancurkan menggunakan garpu,masukan cabai,daun bawang,garam&penyedap.test rasa.\", \"Siapkan kulit lumpia susun tahu yg sdh di hancurkan tadi di atasnya,lipat n rekatkan dengan telur,lakukan sampai adonan habis.\", \"Panaskan minyak lalu goreng hingga kecoklatan lakukan sampai habis.\", \"Martabak isi tahu pedas siap di sajikan😘😘😘\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2170, 3, 'Tahu mahkota / tahu bihun', 'Tahu mahkota / tahu bihun - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"4 buah tahu putih besar\", \"1 bungkus bihun jangun isi 2\", \"4 butir telur\", \"2 buah wortel ukuran sedang\", \"Daun bawang dan seledri secukup nya\", \"#Bumbu halus\", \"1 bawang bombay\", \"3 buah bawang putih\", \"Lada secukup nya\", \"Royco (bila mau)\", \"Garam + gula secukup nya\", \"#Bahan balutan\", \"Terigu cair kan dengan air kira2 bisa buat celupan\", \"Tepung panir\"]', '[\"Kukus tahu -+ 15 menit, angkat tiris kan\", \"Rendam bihun dengan air panas, sampai bihun lembut, tiris kan\", \"Potong2,wortel, daun bawang dan seledri\", \"Potong 2 bawang bombay dan bawang putih, tumis sampai harum\", \"Campur semua bahan jadi satu,beri lada\", \"Cetak2, kukus -+ 15 menit, dingin kan\", \"Celup ke bahan pencelup, panir kan, goreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2171, 3, 'Oseng Tahu Taoco', 'Oseng Tahu Taoco - olahan tahu yang lezat dan bergizi.', '[\"6 bj tahu yang kcl\", \"1/2 sdk mkn taoco\", \"4 Cabe merah,4 cabe ijo,bs ditambh rawit jk suka pedas,\", \"4 siung bawang merah\", \"2 siung bawang putih\", \"Kecap manis\"]', '[\"Cuci tahu lalu potong kotak2 jgn terlalu besar ya bunda,lalu goreng setengah matang.\", \"Potong bawang merah,bawang putih.\", \"Potong serong cabenya.\", \"Tumis bawang merah,putih smp layu n wangi,masuk cabenya dikit dulu,aduk bentar,lalu masuk taoco.\", \"Aduk lg lalu masuk tahu,aduk bentar,kecap manis,tmbh dikit air,lalu test rasa,klu kurang asin br tmbh garam.saya tanpa msg ya bunda.\", \"Klu rasa udah pas,dan air jgn terlalu bnyk,jd nya nyemek gitu.klu udah pas rasanya matikan api,dah siap untuk disajikan..untuk lauk pas dengan nasi anget.yuk coba ya bunda..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(2172, 3, 'Tahu Tepung Goreng', 'Resep praktis Tahu Tepung Goreng yang bisa dicoba di rumah.', '[\"1 bungkus tahu\", \"5 sdm tepung terigu\", \"1 siung bawang putih\", \"Kaldu rasa sapi dan garam (sesuai selera)\", \"Air mineral\"]', '[\"Potong-potong tahu dgn ukuran sesuai selera\", \"Geprek bawang putih lalu campurkan dengan tepung dan air mineral secukupnya\", \"Tambahkan kaldu rasa sapi dan garam, lalu aduk-aduk sampai merata\", \"Balur potongan tahu ke dalam adonan tepung, diamkan beberapa saat agar bumbunya sedikit meresap\", \"Goreng tahu ke dalam minyak panas. Daaaann tahu tepung goreng siap untuk di hidangkan 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2173, 3, 'Ote² tahu taoge', 'Cara membuat Ote² tahu taoge yang enak dan praktis untuk keluarga.', '[\"2 buah tahu\", \"1 genggam taoge\", \"1 butir telor\", \"1 bungkus tepung bumbu saj*ku\", \"1/2 sdt garam\"]', '[\"Hancurkan tahu dengan sendok lalu campur dengan telor, saj*ku Dan garam beri sedikit air aduk rata\", \"Goreng sampai kuning keemasan lalu angkat Dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2174, 4, 'Tahu Nagih', 'Buat Tahu Nagih yang nikmat dengan langkah-langkah mudah ini.', '[\"Tahu putih\", \"1 sendok Saos tiram\", \"1 sendok kecap asin\", \"1/2 buah bawang bombai\", \"secukupnya Gula\", \"secukupnya Garam\", \"1/2 gelas Air\", \"Bumbu halus :\", \"3 siung bawang merah\", \"5 siung bawang putih\", \"6 buah cabe rawit\", \"secukupnya Terasi\"]', '[\"Iris tahu kotak kecil kecil. Taburi sedikit garam. Goreng hingga agak kecoklatan.\", \"Iris memanjang bawang bombay. Tumis bersama sampai sedikit kering.\", \"Masukkan tahu ke tumisan bumbu. Aduk rata. Masukkan saos tiram, kecap asin, garam dan gula. Masukkan air sedikit demi sedikit agar tidak kering. Boleh di tambahkan kaldu ayam/sapi. Koreksi rasa\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2175, 2, 'Tahu Aci', 'Resep Tahu Aci ala rumahan yang dijamin menggugah selera.', '[\"2 buah tahu putih\", \"1/2 lingkaran Kol\", \"7 sdm tepung tapioka (aci)\", \"4 sdm tepung terigu\", \"Daun bawang\", \"Seledri\", \"1 sachet masako\", \"secukupnya Ladaku\", \"Sedikit garam\", \"secukupnya Air\"]', '[\"Potong dadu tahu atau sesuai selera lalu goreng hingga garing.dan rendam kol dengan air panas\", \"Campurkan tepung tapioka, terigu, irisan daun bawang dan seledri, masako,ladaku dn garam aduk rata.\", \"Didihkan air secukupnya lalu tuang kedalam campuran tepung, aduk perlahan hingga agak lembek(tidak terlalu kaku, atau encer)\", \"Lalu isi tahuyg telah dgoreng, dan kol yg sudah lagu dgn adonan.\", \"Kukus selama kurleb 15 menit.\", \"Tahu aci siap dcocol dgn saos sambal 😀\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2176, 4, 'Pepes Tahu Kemangi', 'Resep Pepes Tahu Kemangi yang lezat dan mudah dibuat di rumah.', '[\"20 bh tahu putih\", \"1 genggam daun kemangi, cuci, tiriskan\", \"secukupnya Garam\", \"1/2 sdt Kaldu bubuk (sy pakai masako)\", \"Daun pisang\", \"Tusuk gigi\", \"Secukupnya daun salam\", \"2 btg serai, putihnya saja, iris2\", \"Bumbu halus :\", \"10 siung bawang merah\", \"5 siung bawang putih\", \"5 bh cabe merah keriting\", \"5 bh cabe rawit merah\"]', '[\"Hancurkan tahu, aduk dengan garam, kaldu bubuk, bumbu halus dan daun kemangi. Koreksi rasa.\", \"Taruh campuran tahu ke daun pisang, beri daun salam dan serai. Bungkus dan sematkan dgn tusuk gigi\", \"Kukus tahu sekitar 40 menit\", \"Angkat dan panggang pepes ketika akan disantap\", \"Pepes tahu siap dinikmati\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2177, 2, 'Tahu telur beujeUkkkk (hancur)versi sundaan', 'Kreasi tahu nikmat: Tahu telur beujeUkkkk (hancur)versi sundaan untuk variasi menu harian.', '[\"1 o ptong tahu.mau yng putih/kuning tergantung selera yh kaka2\", \"2 butir telur.lebih bnyak lebih mantaaapppp\", \"Daun kemangi sekucupnya\", \"2 siung Bawang merah&putih.masing2\", \"Tomat serta cabe merah. juga sesuaikan sma selera masing2\", \"Gula putih.garam.dan penyedap rasa\", \"Minyak goreng\"]', '[\"Iris bawang2an nya.cabe juga tomat\", \"Pisahkan daun kemangi dari tangkai.cuci.sisihkan dlu\", \"Beujeuk2 /hancurkan tahu nya..bisa pke apapun boleh lah terserah.asal jngan di banting aja..heee\", \"Tumis bawang.msukan tahu yng sudah hancur.sambil di aduk2 masukan daun kemangi biar layu dan nyatu wanginya sma tahu.\", \"Tambahkan garam.penyedap rasa dan gula secukupnya\", \"Tambah air sdikit.biarkan mendidih.lalu msukkan telur.aduk sbentar.biarkan sampai matang.dan siap\", \"Untuk di sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2178, 2, 'Semur tahu kecap daun bawang', 'Cara membuat Semur tahu kecap daun bawang yang enak dan praktis untuk keluarga.', '[\"2 kotak tahu putih\", \"4 siung bawang merah\", \"2 siung bawang putih\", \"2 butir kemiri\", \"1 ruas jahe\", \"3 batang daun bawang\", \"3 lembar daun jeruk\", \"1 lembar daun salam\", \"Lengkuas\", \"3/4 sdt garam\", \"1/4 sdt merica bubuk\", \"1/4 sdt ketumbar bubuk\", \"1/4 sdt kunyit bubuk\", \"1 sdt gula pasir\", \"3 sdm kecap manis\", \"Sedikit royco\", \"Secukupnya air\", \"Secukupnya minyak goreng\"]', '[\"Cuci tahu potong potong lalu goreng. Haluskan bawang, kemiri, jahe.\", \"Tumis bumbu halus, setelah harum masukan daun bawang, daun salam, daun jeruk, lengkuas tumis lalu masukkan air. Setelah mendidih masukan tahu, garam, gula, merica, ketumbar, kecap, kunyit. Masak hingga bumbu meresap. Tes rasa ya bun..\", \"Ini lo bun.. semur tahu kecap daun bawang beraroma mie ayam.. Sudah siap..\", \"Selamat mencoba..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2179, 2, 'Martabak Tahu', 'Resep praktis Martabak Tahu yang bisa dicoba di rumah.', '[\"1 buah tahu cina putih\", \"1 buah wortel ukuran sedang\", \"30 lembar kulit lumpia\", \"1 batang daun bawang, tadi saya 3 lembar daun bawang yg hijaunya saja\", \"1 buah bawang merah iris\", \"1 buah bawang putih iris\", \"1/4 sdt lada\", \"1 sdt garam\", \"1/2 sdt gula pasir\", \"1/2 sdt masako sapi\", \"1 sdm tepung terigu\", \"Minyak sayur secukupnya untuk menumis\"]', '[\"Haluskan tahu putih cina\", \"Iris korek api wortel dan iris tipis daun bawang\", \"Tumis duo bawang sampai harum lalu masukan wortel dan kasih sedikit air untuk mematangkan wortel\", \"Setelah air saat, masukan tahu putih aduk rata\", \"Masukan garam, gula, masako, tepung dan daun bawang masak hingga matang, test rasa lalu sajikan\", \"Ini hasil akhirnya sisihkan dahulu sampai agak dingin baru siap kita masukan ke kulit lumpia\", \"Bungkus tahu seperti amplop, saya pake 2 lembar kulit karena suka kriuk2 kulitnya kalau 1 suka peyot kalau udah dingin dan kalau saya gak pernah ngerekatin pake tepung lg jadi begitu saya bungkus lsg goreng Insha Allah gak akan mencar\", \"Lalu gorenv martabak, Jd satu2 gini emg agak lama cuma garingnya jd pas dan gak akan gosong hehehe semua sama rata matangnya\", \"Siap disajikan dimakan pake kletusan rawit atau saos sama enaknyaaa\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2180, 2, 'Tahu Tumis Sawi Saori Deva', 'Tahu Tumis Sawi Saori Deva - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"3 Balok Tahu\", \"2 Ikat Sawi\", \"1 Sachet Saos Tiram (Saori)\", \"1 Sachet Royco (Sapi)\", \"5 buah Cabe rawit\", \"4 Siung Bawang Merah\", \"2 Siung Bawang Putih\", \"Secukupnya Garam\", \"Secukupnya Gula\", \"50 Ml Aer\"]', '[\"Potong2 bawang merah+putih (Serong), Cabe rawit+Tahu (Dadu), Sawi potong memnjang dan cuci bersih..\", \"Siapkn pngorengan dgn sedikit minyak sayur u/ menumis Bawang+Cabe smpai harum..\", \"Beri sedikit aer, masukn Tahu smpai aernya mndidih dan tahu matang\", \"Masukn Sawi lalu taburi Royco, Saori, Garam+Gula aduk2 smpai trcmpur semua.. (Sawi smpai Layu)\", \"Test rasa dan angkat.. Siap dSajikn\", \"Let\'s Cooking..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2181, 4, 'Kupat tahu (tanpa kupat)', 'Cara membuat Kupat tahu (tanpa kupat) yang enak dan praktis untuk keluarga.', '[\"2 potong tahu goreng, potong-potong\", \"2 potong tempe goreng, potong-potong\", \"2 genggam taoge, kukus\", \"3 lembar kol, iris tipis\", \"1/2 buah tomat, iris\", \"Secukupnya bawang merah goreng\", \"1/2 siung bawang putih\", \"1/2 lembar daun jeruk\", \"Secukupnya cabai\", \"Secukupnya gula jawa\", \"Secukupnya garam\", \"2 sdm sambal kacang kemasan (saya pakai bumbu gado-gado)\", \"1/2 gelas air\", \"Secukupnya kecap manis\"]', '[\"Haluskan bawang putih, cabai, daun jeruk, dan garam.\", \"Tambahkan gula jawa & sambal kacang, lalu haluskan kembali.\", \"Kemudian, tambahkan air & kecap. Aduk rata dan koreksi rasa.\", \"Tata tahu, tempe, kol, taoge dan tomat diatas piring.\", \"Siram dengan bumbu kupat tahu dan taburi bawang merah goreng.\", \"Kupat tahu sudah siaap.. Nyamm...nyaaam... 😄😄\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2182, 2, 'Sapo tahu saus telur asin', 'Resep Sapo tahu saus telur asin yang lezat dan mudah dibuat di rumah.', '[\"1 buah sapo tahu d potong 2 cm\", \"2 buah kuning telur asin di haluskan\", \"1 siung bawang putih di geprek dan cincang2 kecil2\", \"1 daunbawang d potong kecil\", \"1 sendok minyak untuk menumis\", \"5-6 sendok makan Mentaga\"]', '[\"Potong sapo tahu sebesar 2cm\", \"Goreng sapo tahu hingga kecoklatan. Lalu sisihkan\", \"Siapkan bahan2 untuk saus telur asin nya\", \"Tumis bawang putih lalu daun bawang dengan adkit mnyak dan sedikit mentega hingga harum\", \"Masukan kuning telur asin dan mentega hingga berbusa\", \"Jika saus telah berbusa. Masukan sapo tahu yang telah di goreng.\", \"Lalu siap di hidangkan. Taraaa...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2183, 3, 'Oseng Tahu Campur', 'Oseng Tahu Campur - olahan tahu yang lezat dan bergizi.', '[\"4 potong Tahu kuning (potong dadu kecil)\", \"Semangkuk Jamur Tiram suwir\", \"Semangkuk Tauge (bersihkan)\", \"10 bj Pentol Bakso (sy pentol uk kecil2)\", \"200 gr Daging ayam (sy bag.dada, sy iris dadu)\", \"1 btg Daun Bawang iris\", \"5 bj Cabe merah keriting iris serong\", \"8 bj Cabe rawit iris serong\", \"sesuai selera Gula, garam, lada bubuk, kaldu bubuk\", \"1-2 sdm Kecap manis Bango\", \"secukupnya Air\", \"° Bumbu uleg :\", \"4 siung Baput\", \"6 siung Bamer\", \"1 bj Kemiri\"]', '[\"Siapkan semua bahan, panaskan sckupnya minyak, tumis bumbu uleg dan cabe iris sampai harum dan layu. Masukkan daging ayam. Masak hingga berubah warna, beri air ssuai selera\", \"Masukkan tauge dan jamur. Bumbui gula, garam, lada, kaldu bubuk.\", \"Masukkan tahu, lalu pentol bakso. Terakhir daun bawang. Koreksi rasa. Bisa tambahkan kecap manis utk pemantap. Masak sampai tanak, sajikan :)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2184, 4, 'Tahu aci walik crispy ekonomis', 'Tahu aci walik crispy ekonomis - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"10 bh tahu goreng segitiga\", \"7 sdm tepung sagu\", \"3 sdm tepung terigu\", \"50 ml air panas\", \"Irisan daun bawang\", \"Secukupnya penyedap (royco)\", \"Bumbu halus:\", \"2 bh bawang putih\", \"2 bh bawang merah\", \"1 btr kemiri\", \"1/2 sdt lada\", \"1/2 sdt ketumbar\", \"1 sdt garam\", \"1 sdt ebi kering\"]', '[\"Saya pakai tahu coklat yang sudah gorengan jadi saya cuci dulu, sedikit diperas lalu tiriskan. Untuk bumbu halus sesuai selera ya boleh pakai yang instan.\", \"Belah satu sisi tahu dengan pisau lalu balik bagian dalam ke posisi luar. Sisihkan\", \"Campur jadi satu terigu,sagu,daun bawang,bumbu halus dan air. Aduk sampai tercampur rata. Adonan lembek. Kalau terlalu encer tambahkan tepungnya. Tes rasa.\", \"Isikan kedalam tahu. Goreng dengan minyak banyak hingga matang / sudah krispy kulit luarnya.\", \"Inilah penampakannya.. kreesss banget\", \"Kalo yang ini saya kukus tapi ga dibalik ya versi tahu aci\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2185, 2, 'Tumis sawi + tahu simple', 'Tumis sawi + tahu simple - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 sawi\", \"Tahu gembos (selera boleh banyak)\", \"1 sachet saori saos tiram\", \"3 bawang putih\", \"4 bawang merah\", \"1 tomat kecil\", \"1 cabe besar (potong miring)\", \"8 cabe rawit (selera kalo mau pedas)\", \"Penyedap rasa\", \"Garam\", \"Gula\", \"secukupnya Ladaku\", \"Minyak sedikit untuk menumis\"]', '[\"Cuci sawi dan potong selera, tahu juga di potong ya\", \"Iris tipis bawang putih, bawang merah, tomat, cabe besar, cabe rawit.\", \"Siapkan wajan dan beri sedikit minyak,masukkan irisan bumbu tumis hingga berbau harum lalu masukkan sawi dan tahu tambahkan saori saos tiram, penyedap rasa, garam, gula dan ladaku. Aduk hingga rata dan icip* rasanya tunggu beberapa menit sampai bumbu meresap. Siap di hidangkan👌\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2186, 3, 'Mangut Ikan Asap, Tahu, Telur puyuh #menuanak', 'Mangut Ikan Asap, Tahu, Telur puyuh #menuanak - olahan tahu yang lezat dan bergizi.', '[\"4 ikan asap\", \"10 butir telur puyuh kupas\", \"3 potong tahu, potong jd 2(sy kukus dl)\", \"1/2 sachet santan kara kecil\", \"2 sdm minyak goreng\", \"1 sdm garam\", \"1 sdt gula pasir\", \"1/2 sdt kaldu jamur\", \"Bumbu halus:\", \"4 baput, 3 bamer\", \"Seruas kencur\", \"Seiris kunir\", \"3 butir kemiri\", \"1/2 sdt terasi\", \"Bumbu tambahan :\", \"2 lembar daun salam\", \"Lengkuas 3cm, memarkan\", \"2 lembar daun jeruk\"]', '[\"Cuci bersih semua bahan masakan, haluskan baput, bamer, kunyit, terasi, kencur dan kemiri.\", \"Panaskan 3 sdm minyak goreng, tumis bumbu halus tambahkan bumbu pelengkap sampai harum, matang dan tidak berwarna pucat.\", \"Masukkan ikan asap, tumis sebentar lalu tambahkan air, tunggu hingga mendidih tambahkan garam gula dan kaldu jamur, koreksi rasa setelah sesuai selera tambahkan santan tahu dan telur.\", \"Masak dg api kecil kurleb 10mnt lg. Cek rasa dan siap disajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2187, 2, 'Bihun tahu kuah', 'Buat Bihun tahu kuah yang nikmat dengan langkah-langkah mudah ini.', '[\"1 bungkus bihun (me : bihun jagung)\", \"5 buah tahu potong kotak kecil\", \"Pakcoy\", \"Daun bawang\", \"Bumbu\", \"5 buah bawang putih\", \"Garam\", \"Merica\", \"Penyedap\", \"Tomat\", \"Cabe rawit\"]', '[\"Rebus bihun,tiriskan lalu sisihkan\", \"Potong potong pakcoy lalu rebus sebentar,sisihkan\", \"Haluskan bawang putih lalu tumis masukan ke dalam air yg sudah mendidih\", \"Masukan tahu yang sudah dipotong kotak kecil\", \"Lalu bumbui dengan garam,merica dan penyedap dan tambah tomat\", \"Koreksi rasa\", \"Masukan daun bawang yg sudah di iris tipis\", \"Matikan kompor.\", \"Masukan bihun ke dalam mangkok lalu tambah kuah tahu tadi,taburi cabe rawit dan tambah perasan jeruk nipis kalau mau. Pake kecap tambah enak loh\", \"Oh ia saya masukan pakcoy lgs ke dlm mangkok ya Bu 😉\", \"Anak saya suka,pastinya yg ga pake cabe rawit 😉😉nambah 2 x dia\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2188, 4, 'Batagor tahu bumbu kacang', 'Nikmati kelezatan Batagor tahu bumbu kacang dengan resep sederhana ini.', '[\"2 buah tahu (iris kotak kecil kecil)\", \"5 sdm tepung terigu\", \"8 sdm tepung tapioka\", \"1 butir telur\", \"4 siung bawang putih (haluskan)\", \"secukupnya Merica\", \"secukupnya Garam\", \"secukupnya Penyedap rasa\", \"1/2 sdt baking powder (larutkan dengan 100 ml air)\", \"Bahan bumbu kacang:\", \"1/4 kacang (goreng terlebih dahulu)\", \"3 siung bawang putih\", \"sesuai selera Cabai rawit\", \"Gula\", \"Garam\", \"Penyedap rasa\", \"Perasan jeruk nipis\", \"Kecap manis\", \"Air\"]', '[\"Potong tahu kotak kecil kecil. Sisihkan\", \"Campurkan semua bahan,tepung terigu,tapioka,bawang putih,garam,merica,telur dan larutan baking powder.\", \"Aduk sampai tercampur semua. Sisihkan sampai 30 menit\", \"Carbut bumbu kacang :\", \"Siapkan blender,masukkan kacang yg sudah di goreng ke dalam blender,bawang putih,cabai, dan semua bahan. Kecuali kecap dan jeruk nipis\", \"Setelah lembut,goreng dalam wajan,tambahkan air,kecap manis,perasan jeruk nipis.\", \"Koreksi rasa.\", \"Batagor tahu bumbu kacang siap di sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2189, 2, 'Tahu Orak Arik Cabe Garam', 'Cara membuat Tahu Orak Arik Cabe Garam yang enak dan praktis untuk keluarga.', '[\"10 buah tahu (hancurkan)\", \"1 telor (kocok lepas)\", \"5 buah cabe merah\", \"10 buah cabe rawit\", \"3 bamer, 1 baput\", \"Merica, garam sckpnya\"]', '[\"Tumis bamer, baput, smpai layu, masukan cabe merah dan rawit aduk kembali\", \"Tambahkan tahu yg sudah dihancurkan aduk rata... kemudian masukan kocokan telor aduk kembali sampai telor menyatu...\", \"Masukan garam, merica sambil cek rasa. Sudah pas.. tunggu 5menit. Sajikan....\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2190, 2, 'Bakwan Tahu Sayur Campur', 'Bakwan Tahu Sayur Campur - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"5 buah tahu\", \"Wortel\", \"Touge\", \"Daun Bawang\", \"Daun Sop\", \"3 siung bawang putih\", \"3 siung bawang merah\", \"1 butir telur\", \"Tepung Bumbu\", \"Minyak Goreng\", \"Masako\"]', '[\"Cuci bersih tahu lalu haluskan beri sedikit masako,garam aduk hingga rata...\", \"Haluskan bawang merah, bawang putih & gula secukup nya..\", \"Masukan bumbu yg telah d haluskan ke dalam tahu.. Masukan pula 1 butir telur.. Dan tepung Bumbu (kobe) aduk rata smpai sedikit mengental..\", \"Lalu masukan sayur2an tauge, Wortel, daun bawang, daun sop (yg sudah d iris)\", \"Panaskan minyak goreng.. Lalu bentuk tahu bulat2.. Lalu masukan Tahu..Goreng hinga kecoklatan.. Siap di hidangkan.. Selamat mencoba 😀\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2191, 3, 'Tumis caisin tahu', 'Tumis caisin tahu - olahan tahu yang lezat dan bergizi.', '[\"secukupnya Caisin/pakcoy\", \"Tahu putih\", \"1 bks royco ayam\", \"1 buah tomat\", \"1 buah cabe merah\", \"3 siung bwg merah\", \"2 siung bawang putih\"]', '[\"Iris bumbu dan potong sayuran\", \"Potong dadu kecil tahu lalu goreng\", \"Potong sayuran\", \"Tumis bumbu hingga harum,lalu masukkan sayuran,setelah sayuran aga layu masukkan tahu dan royco,beri air stgh gelas\", \"Aduk dan tunggu hingga matang\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2192, 4, 'Rolade Tahu Pedas', 'Sajian Rolade Tahu Pedas yang praktis dan lezat untuk dinikmati bersama.', '[\"1/2 Buah tahu cina ukuran besar\", \"2 Butir telur\", \"3 Siung bawang merah\", \"2 Siung bawah putih\", \"7 Buah cabe rawit\", \"1/4 Buah bawang bombay\", \"secukupnya Penyedap rasa\", \"secukupnya Garam\", \"10 Sdm tepung terigu\", \"Minyak untuk menggoreng\", \"Pelengkap:\", \"Telur Dadar\"]', '[\"Iris bawang merah, bawang putih, bawah bombay beserta cabe. Kemudian tumis hingga harum.\", \"Ulek hingga halus bawang dan cabe yang tadi ditumis. Tambahkan tahu, hancurkan tahu hingga halus juga. (Resep asli di blender, bukan di ulek)\", \"Tambahkan 1 buah telur dan penyedap rasa. Aduk hingga rata.\", \"Masukkan tepung terigu, aduk lagi hingga rata.\", \"Siapkan plastik wrap dan telur dadar. Letakan adonan tahu diatas telur dadar kemudian gulung menggunakan plastik wrap.\", \"Kukus rolade selama 15 menit. Selesaaaaiiii\", \"Jika rolade ingin di goreng, baluri potongan rolade dengan kocokan telur. Goreng hingga coklat keemasan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2193, 3, 'Tim Tahu', 'Cara membuat Tim Tahu yang enak dan praktis untuk keluarga.', '[\"1 kotak tahu putih besar\", \"sesuai selera cabai\", \"1 buah tomat\", \"200 gr jamur merang (potong kecil)\", \"1 batang petai (sesuai selera)\", \"5 siung bawang merah iris tipis\", \"2 butir telur\", \"1 batang daun bawang\", \"secukupnya garam dan kaldu jamur\"]', '[\"Campurkan semua bahan jadi 1 di sebuah mangkuk stainless.\", \"Lalu siapkan kuali dan isi air, letakan mangkuk stainless tersebut di dalam kuali.\", \"Masak hingga tahu matang\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2194, 3, 'Tahu Dangdut', 'Cara membuat Tahu Dangdut yang enak dan praktis untuk keluarga.', '[\"250 gr tahu putih, potong dadu\", \"8 bh cabe rawit hijau, diiris\\\" bulat\", \"3 sdm kecap manis\", \"1 sdm saus tiram\", \"1/2 sdt merica bubuk\", \"Garam, gula dan penyedap sckpnya\", \"1 sdt tepung maizena larutkan dgn sedikit air\", \"100 ml air\", \"Bumbu halus :\", \"2 bh cabe hijau besar\", \"2 bh cabe rawit hijau\", \"3 siung bawang putih\"]', '[\"Tumis bumbu halus hingga Wangi dan matang, tuang air, aduk\\\"\", \"Beri kecap manis, saus tiram, merica, garam, gula dan penyedap, aduk rata.\", \"Masukkan tahu dan cabe rawit iris, koreksi rasa, didihkan. Tuang larutan maizena, masak sebentar sampai mengental, angkat dan sajikan.\", \"Note : semua jenis cabenya jgn di skip ya, soale itu yg bikin enyakk,,,,😂 klo suka pedes banget bisa ditambah cabenya,,,,\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2195, 3, 'Sop Tahu Fantasi', 'Cara membuat Sop Tahu Fantasi yang enak dan praktis untuk keluarga.', '[\"300 gr tahu putih haluskan\", \"100 gr daging ayam cincang\", \"1 butir telur\", \"1 buah wortel, parut\", \"1 batang daun bawang\", \"2 buah bawang putih, haluskan\", \"1/4 sdt lada halus\", \"kaldu bubuk secukupnya (boleh diskip)\", \"10 btr telur puyuh mentah\"]', '[\"Campur semua bahan, kecuali telur puyuh. aduk rata\", \"Oleskan cetakan dengan minyak, isi cetakan sampai 3/4 penuh lobangi tengahnya isi dng telur puyuh. Kukus ± 20 menit.angkat\", \"Untuk kuah saya pakai bumbu siap pakai \\\"racik SOP\\\". tinggal seduh air sampai mendidih masukan bumbu racik sop. Beri daun bawang, sledri dan bawang goreng. Sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2196, 4, 'Sop Tahu Simple', 'Buat Sop Tahu Simple yang nikmat dengan langkah-langkah mudah ini.', '[\"4 kotak besar tahu putih\", \"1 plastik kecambah/taoge\", \"3 ikat sawi hijau\", \"3 siung bawang putih\", \"3 siung bawang merah\", \"secukupnya Garam\", \"secukupnya Lada\", \"secukupnya Kaldu bubuk ayam\", \"secukupnya Air\", \"Bawang goreng\"]', '[\"Potong tahu menjadi kotak-kotak kecil\", \"Iris tipis bawang putih dan bawang merah\", \"Rebus air hingga mendidih\", \"Masukkan duo bawang yg telah diiris sebelumnya\", \"Masukkan taoge kemudian sawi. Rebus hingga empuk\", \"Masukkan tahu\", \"Tambahkan garam dan lada. Cek rasa\", \"Masak hingga matang. Sajikan dengan taburan bawang goreng dan sambal kecap yg pedas.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2197, 2, 'Sayur Oseng Buncis Tahu', 'Kreasi tahu nikmat: Sayur Oseng Buncis Tahu untuk variasi menu harian.', '[\"Buncis\", \"Wortel\", \"Touge\", \"Garam\", \"Gula\", \"Masako\", \"3 siung bawang putih\", \"3 siung bawang merah\", \"Minyak Goreng\", \"1 buah Tahu pilihan\"]', '[\"Potong Potong sayuran (buncis dan wortel) dg bentuk sesuai selera.. Lalu cuci bersih sayuran (buncis,wortel,touge)\", \"Potong Potong bawang marah&bawang putih..\", \"Cuci bersih 1buah tahu.. Lalu haluskan dan di beri masako sedikit lalu aduk2 hingga rata..\", \"Panaskan minyak goreng.. Lalu tumis bawang merah & bawang putih hinga wangi.. Lalu masukan garam & gula sesuai selera aduk2 hingga rata..\", \"Lalu masukan wortel..buncis.. Beserta touge.. Beri sedikit air.. Aduk2 sampai bumbu merata, lalu masukan tahu yg telah d haluskan tadi aduk2 lagi hingga merata.. Ttup sayur biarkan sampai air mengering.. Siap di hidangkan 😃 selamat mencoba 😁\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2198, 4, 'Gulai pakis tahu ikanasin', 'Buat Gulai pakis tahu ikanasin yang nikmat dengan langkah-langkah mudah ini.', '[\"5 Tahu (tahunya seh yg gede)\", \"1 ikat pakis\", \"1 ons ikanasin\", \"Santan (aq seh beli kelapa parut meres sendiri)\", \"secukupnya Garam\", \"Bumbu halus: (sesuai selera seh)\", \"15 cabe merah\", \"5 cabe rawit\", \"3 siung bawang merah\", \"1 siung bawang putih\", \"3 cm kunyit\", \"1 cm jahe\", \"1 cm lengkuas\", \"Tambahan numisnya:\", \"1 daun salam\", \"1 daun kunyit\", \"3 daun jeruk (klo mau pake)\", \"1 serei (gepreknya)\"]', '[\"Haluskan bumbu halus tadi trus tumis campurkan tambahan tumisannya\", \"Masukan tumisan bumbu halus ke dalam panci terus peras kelapa parutnya (karna aq make kelapa parutnya)\", \"Didihkan sampe mendidih,tp sambil diaduk yaa santanny trus bisa sambilan potong tahu jdi 4 bagian, siapkan pakis, siapkan ikanasin\", \"Setelah mendidih masukan tahu, biarkan dlu trus masukan ikannasin lalu masukan pakisnya\", \"Setelah mau matang masukan garam secukupnya, biarkan sampe matang terus koreksi rasa deh\", \"Gulai pakis tahu ikanasin siap di sajikan😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2199, 2, 'Tahu rambutan', 'Resep praktis Tahu rambutan yang bisa dicoba di rumah.', '[\"300 gr tahu putih\", \"30 gr tepung terigu serbaguna\", \"3 siung bawang putih\", \"1/2 sdt garam\", \"1 sdt Gula pasir\", \"1/4 sdt merica /lada bubuk\", \"1/4 sdt royco ayam\", \"10 butir telur puyuh\", \"secukupnya Minyak goreng\"]', '[\"Bahannya: rebus dlu telur puyuhnya, dan haluskan bawang putih dan garam, sampai halus, masukkn lada bubuk,gula pasir, royco ayam aduk rata sisihkan. Dan haluskan tahu putih sampai halus.\", \"Remas2 mienya. Sisihkan. Tahu yg sdh di haluskan tambahkan bumbu yg sdh di haluskan tadi, aduk hingga rata tambahkan tepung terigu aduk rata. Dan siap di bikin. Cuci tangan 👐 bersih.ambil 2 sdm tahu pipihkan di tangan masukkn 1 butir telur puyuh kemudian tutup dan bulatkan, gulingkan ke dlm mie yg sdh di remas2 tadi. Lakukan hingga adonan habis.\", \"Seperti gambar. Besar/kecil sesuai selera.\", \"Siapkan wajan beri minyak goreng secukupnya tunggu minyak panas masukkn adonan beberapa biji. Goreng dng api kecil saja. Sambil di bolak balik biar matangnya rata. Kalau sdh matang angkat dan tiriskan.\", \"Siapkan piring saji, masukkn tahu rambutan nya, siap di nikmati. Cocol dng saus sambal 👍 enk.\", \"Selamat mencoba 😘\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2200, 2, 'Sup tahu pedas', 'Buat Sup tahu pedas yang nikmat dengan langkah-langkah mudah ini.', '[\"250 gr udang kupas\", \"4 buah tahu putih, potong ukuran besar\", \"3 lembar kol\", \"1 bungkus soun ukuran kecil, rendam air panas sebentar\", \"1 helai daun bawang, potong2\", \"1/2 buah tomat, potong2\", \"500 ml air\", \"Bumbu:\", \"3 siung bawang putih, geprek & iris tipis\", \"4 siung bawang merah, iris tipis\", \"1/2 buah bawang bombay, iris\", \"1 sdm bubuk cabai\", \"1 sdm kecap ikan\", \"Secukupnya garam\", \"Secukupnya gula\", \"1/2 sdt merica\", \"Secukupnya jeruk nipis\"]', '[\"Rebus air sampai mendidih dan masukkan semua bumbu kecuali jeruk nipis.\", \"Masukkan udang & tahu. Masak sampai matang.\", \"Kemudian, masukkan kol, daun bawang, tomat, & air perasan jeruk nipis. Aduk sebentar & koreksi rasa.\", \"Tuang kedalam mangkuk berisi soon.\", \"Dan... Hidangkan. Nyam.. Nyaaamm 😄\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2201, 3, 'Opor Ayam Tahu', 'Sajian Opor Ayam Tahu yang praktis dan lezat untuk dinikmati bersama.', '[\"1 kg ayam broiler, kukus\", \"5 buah tahu, potong 2 segitiga\", \"7 siung bawang merah\", \"5 siung bawang putih\", \"6 butir kemiri\", \"2 ruas lengkuas\", \"1 ruas kunyit\", \"2 lembar daun salam\", \"1 batang serai\", \"1/2 sdt lada bubuk\", \"1/2 sdt ketumbar bubuk\", \"secukupnya garam, gula dan kaldu jamur\", \"1 sachet santan instant\", \"minyak utk menumis\"]', '[\"Cuci bersih ayam, kemudian kukus hingga matang (tidak ada darahnya). Ini karena saya pakai ayam broiler, utk menghilangkan lemak-lemaknya\", \"Cuci bersih tahu, rebus sebentar, kemudian goreng hingga berkulit.\", \"Haluskan bumbu kecuali daun salam dan lengkuas. Tumis hingga harum dan bumbu matang. Tambahkan air sedikit supaya sari bumbu keluar. Beri lada bubuk dan ketumbar bubuk. Aduk rata.\", \"Masukkan ayam, tambahkan air hingga ayam terendam. Kira-kira air sudah agak menyusut, masukkan santan instant. Aduk rata agar santan tidak pecah\", \"Masukkan tahu, beri garam, gula dan sedikit kaldu jamur. Aduk rata. Angkat dan sajikan :)\", \"Note: pastikan menumis bumbu hingga benar-benar tanak supaya tidak ada \\\"aroma langu\\\" bumbu mentah...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2202, 2, 'Kothok Pindang Tahu', 'Resep Kothok Pindang Tahu ala rumahan yang dijamin menggugah selera.', '[\"Bahan :\", \"2 keranjang ikan pindang\", \"1 bungkus tahu kuning\", \"1 sachet santan kara\", \"Bumbu :\", \"7 siung bawang merah\", \"5 siung bawang putih\", \"7 buah cabai rawit\", \"2 buah cabai merah besar\", \"1 jempol jahe\", \"1 jempol kunyit\"]', '[\"Ikan pindang ambil dagingnya saja. Cuci bersih. Goreng. Tiriskan\", \"Potong dadu tahu kuning. Goreng. Tiriskan\", \"Iris tipis bawang merah, bawang putih dan cabai merah besar. Haluskan jahe dan kunyit. Tumis sampai harum.\", \"Masukkan cabai rawit utuh, ikan pindang dan tahu yg sudah digoreng. Tumis sebentar dan tambahkan 7 gelas air sampai semua terendam. Tunggu sampai mendidih\", \"Tambahkan santan, gula, garam dan merica. Tunggu lagi sampai mendidih. Tambahkan irisan daun pre. Cek rasa dan siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2203, 4, 'Tumis tahu kacang panjang', 'Resep Tumis tahu kacang panjang yang lezat dan mudah dibuat di rumah.', '[\"1 ikat kcg pnjag uk.kecil (mgkin skitran cm 5 kcg pjg diptong2)\", \"4 buah tahu putih (potong kotak)\", \"1 genggam kcambah besar\", \"7 siung bamer\", \"4 siung baput\", \"9 cabe rawit\", \"1 sdm saos tiram\", \"secukupnya Garam gula\"]', '[\"Goreng tahu sbentar, angkat sisihkan.\", \"Uleg bamer baput cabe, kemudian tumis smpe harum.\", \"Masukan kcg pnjang & kecambah oseng2 sbentar kmudian msukan tahu.\", \"Masukan garam gula dan saos tiram, icip rasa. Klu sdh pas angkat sjikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2204, 3, 'Bakwan tahu teri nasi', 'Resep Bakwan tahu teri nasi ala rumahan yang dijamin menggugah selera.', '[\"5 tahu putih (haluskan)\", \"2 butir telor\", \"1 bungkus tepung bakwan merek sajiku\", \"1 batang daun bawang\", \"1 bungkus teri nasi\"]', '[\"Tahu putih dicuci lalu haluskan sisihkan\", \"Masukkan tepung bakwan kedalam wadah mangkok serta masukkan tahu, telor, teri nasi, irisan daun bawang aduk rata\", \"Panaskan minyak lalu goreng bakwan secara satu persatu hingga kuning kecoklatan\", \"Setelah kuning kecoklatan angkat lalu sajikan kedalam piring\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2205, 2, 'Tahu Aci khas Slawi/Tegal', 'Resep Tahu Aci khas Slawi/Tegal ala rumahan yang dijamin menggugah selera.', '[\"10 buah tahu kuning\", \"10 sdm tepung sagu\", \"5 sdm tepung terigu\", \"2 batang daun bawang(iris tipis)\", \"Secukupnya air panas\", \"Bumbu halus :\", \"3 siung bawang putih\", \"1 sdt ketumbar\", \"Secukupnya garam\", \"Secukupnya penyedap(opsional)\"]', '[\"Potong tahu serong/diagonal,jd membelah 2. Keruk tengah sedikit, kalo saya di kerat piso trus coel keluar dikit2. (Nnti sisa kerokan tahunya bisa dicampur adonan)\", \"Campur semua tepung, bawang,isian sisa tahu dan bumbu halus, lalu tambahkan air panas sedikit demi sedikit hingga adonan bisa dipulung(jangan tllu cair)\", \"Panaskan minyak, lalu ambil adonan dengan garpu, lalu ratakan dengan punggung garpu. Goreng hingga kuning kecoklatan,lakukan hingga semua adonan habis, tiriskan. Sajikan dengan cocolan kecap+rawit,yummy\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2206, 3, 'Stik Tahu (Gorengan Sehat) dengan Bahan Seadanya', 'Buat Stik Tahu (Gorengan Sehat) dengan Bahan Seadanya yang nikmat dengan langkah-langkah mudah ini.', '[\"2-3 kotak tahu\", \"3 sdm tepung terigu\", \"2 sdm tepung beras kuning (tepung udang)\", \"5 sdm tepung kanji\", \"5 sdm tepung bumbu Sajiku serbaguna\", \"Garam / masako secukupnya (saya pakai garam)\", \"1/4 sdt lada instan (boleh skip)\", \"Saus sambal\", \"Mayonnais\"]', '[\"Langkah pertama, cuci tahu terlebih dahulu\", \"Kemudian potong tahu memanjang seperti memotong kentang. Hati-hati ya di bagian ini😀\", \"Siapkan tiga wadah yang berbeda. (Recommended pakai piring pelastik sedang)\", \"Di wadah pertama, masukkan tepung terigu dan tepung beras kuning. Kasih garam/masako secukupnya dan lada instan lalu aduk.\", \"Di wadah kedua, masukkan tepung kanji.\", \"Dan di wadah ketiga, masukkan tepung bumbu Sajiku serbaguna.\", \"Setelah intruksi di atas selesai, rabuki tahu satu per satu ke dalam wadah pertama, diikuti wadah kedua, lalu ke wadah ketiga. Lakukan ini dengan hati-hati.\", \"Setelah selesai, letakkan potongan tahu yang telah dirabuk di atas piring. Lakukan hal yang sama sampai tahu terakhir😀\", \"Untuk hasil yang maksimal, masukkan potongan tahu yang telah dirabuk ke dalam freezer selama beberapa menit.\", \"Siapkan wajan penggorengan dan minyak dalam jumlah banyak (seperti menggoreng kentang).\", \"Setelah minyak sudah panas, goreng tahu. Setengah matang yaaa. Kemudian tiriskan.\", \"Untuk menggoreng stik tahu ini, dibutuhkan 2x penggorengan agar tahu bisa garing dan kriuk kriuk\", \"Setelah ditiriskan, kembali goreng tahu sampai garing seperti menggoreng kerupuk. Ingat! Jangan sampai gosong😆\", \"Setelah dirasa matang, angkat kemudian tiriskan di atas kemarang atau kertas tissu. Tunggu beberapa saat sampai minyak dalam tahu benar benar hilang.\", \"Terakhir, letakkan tahu di atas piring. Siapkan lepek untuk tempat saus sambal dan mayonnais yaa 😀\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2207, 2, 'Tahu Goreng Pedas', 'Tahu Goreng Pedas - olahan tahu yang lezat dan bergizi.', '[\"10 buah tahu coklat, belah tengahnya & korek isi tahunya\", \"1 buah wortel, parut kasar\", \"1/4 juring kol, iris halus\", \"1 genggam tauge\", \"2 btg daun bawang, iris2\", \"3 siung bawang merah, iris2\", \"Bumbu halus :\", \"2 siung bawang putih\", \"5-7 buah cabe rawit merah\", \"Bahan pencelup :\", \"10 sdm tepung terigu\", \"1 sdt bawang putih bubuk\", \"1 sdt kunyit bubuk\", \"1 sdt ketumbar bubuk\", \"1/2 sdt lada bubuk\", \"1 butir telur ayam\", \"Secukupnya air\", \"Secukupnya gula pasir, garam & kaldu bubuk\", \"Secukupnya minyak goreng\"]', '[\"Adonan isian : Tumis bawang merah dg sedikit minyak sampai harum. Masukan bumbu halus, aduk rata. Masukan korekan isi tahu, sebagian daun bawang, wortel, kol & tauge. Tambahkan gula pasir, garam & kaldu bubuk. Beri sedikit saja air utk mematangkan sayuran. Koreksi rasa. Matikan api, angkat & dinginkan. Sisihkan\", \"Adonan tepung pencelup : Campurkan tepung terigu, bawang putih, kunyit, ketumbar & lada. Masukan jg garam, kaldu bubuk & air. Aduk rata sampai tdk ada terigu menggumpal (adonan tdk terlalu cair /kental). Koreksi rasa. Tambahkan telur & sisa daun bawang, aduk rata. Sisihkan\", \"Masukan isian kedalam tahu, sampai isian habis. Kalo bs pakai sarung tangan, supaya gak kecabean 😊\", \"Celupkan tahu ke adonan tepung. Goreng di minyak panas sampai kuning kecoklatan. Matikan api, angkat & tiriskan.\", \"Kalo masih kurang pedas, bs dicocol saos sambel/sambil ngeletus cabe rawit.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2208, 4, 'Tahu kuning kriuk', 'Tahu kuning kriuk - olahan tahu yang lezat dan bergizi.', '[\"2 plastik Tahu kuning(isi 5 1 plastiknya)\", \"1 sdm ketumbar\", \"4 siung bawang putih\", \"Secukupnya garam\", \"Penyedap rasa\"]', '[\"Cuci tahu lalu bagi 2 bagian.\", \"Ulek bawang putih & ketumbar,beri sedikit garam n penyedap cek rasa.\", \"Siapkan wadah,rendam tahu di dlm bumbu halus 5-10menit agar bumbu meresap.\", \"Panaskan minyak,goreng tahu hingga kecoklatan.\", \"Tahu kuning goreng siap di sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2209, 4, 'Oseng tahu goreng(coklat)with kol/kubis', 'Nikmati kelezatan Oseng tahu goreng(coklat)with kol/kubis dengan resep sederhana ini.', '[\"2 bungkus tahu goreng(coklat)\", \"1/2 kol/kubis uk kecil\", \"10 cabai rawit merah\", \"4 siung bawang putih\", \"4 siung bawang merah\", \"Lada bubuk\", \"Penyedap rasa\", \"Garam\", \"Kecap manis\", \"Gula merah\"]', '[\"Cuci tahu terlebih dahulu, lalu peras.Potong tahu menjadi 3 bagian.\", \"Panaskn minyak,goreng tahu hingga kering.\", \"Potong kol/kubis sesuai selera kalau saya sedang saja.cuci bersih,tiriskan.\", \"Potong cabai,bawang merah,bawang putih.\", \"Siapakan wajan beri minyak secukupnya,tumis bumbu tunggu sampai harum,masukan tahu beri 1 gelas belimbing air,sisir, garam, gula merah&lada bubuk,masukan kol tunggu sedikit mengering masukan kecal manis,test rasa.\", \"Oseng tahu goreng(coklat)withkol/kubis siap di sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2210, 3, 'Balado puyuh tahu dan kentang', 'Buat Balado puyuh tahu dan kentang yang nikmat dengan langkah-langkah mudah ini.', '[\"8 Bawang merah\", \"5 Bawang putih\", \"5 Cabai rawit merah\", \"6 Cabai keriting\", \"1 Lengkuas 3cm\", \"1 sdm Gula\", \"1/2 sdm Garam\", \"15 Telur puyuh\", \"3 Tahu kulit\", \"1 buah Kentang\"]', '[\"Rebus telur puyuh sampai matang\", \"Goreng kentang dan goreng tahu sampai setengah kering\", \"Bland bawang merah, putih, lengkuas, cabai rawit, cabai kriting\", \"Tiris tahu kentang dan telur.. oseng bumbu sampai wangi..\", \"Jika sudah wangi masukan telur, tahu, dan kentang..\", \"Masukan gula, garam, dan penyedap rasa\", \"Icipi sampai pas.\", \"Sajikn ™\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2211, 2, 'Tumis Buncis Tahu Pedas', 'Nikmati kelezatan Tumis Buncis Tahu Pedas dengan resep sederhana ini.', '[\"300 gr buncis\", \"1 buah tahu yg agak besar\", \"Bumbu halus:\", \"4 siung Bawang merah\", \"2 siung Bawang putih\", \"3 biji Cabe besar\", \"Cabe rawit 5 biji(penyuka pedas soalnya 😁)\", \"Laos geprek\", \"2 lembar Daun salam\", \"Garam\", \"Merica\", \"1 sdm Kecap manis\", \"sedikit Air\"]', '[\"Potong tahu kotak2 kecil.goreng sampai matang,tp kulit luarnya jangan sampai kering.angkat dan sisihkan\", \"Potong buncis kecil2 sesuai selera.haluskan bumbu dan tumis hingga harum dan matang.masukkan buncis,tumis sampai matang.beri sedikit air supaya tidak kering\", \"Masukkan tahu,aduk2 sampai rata.masak sebentar lalu angkat dan sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2212, 2, 'Sayur tahu kacang panjang labusiam', 'Sayur tahu kacang panjang labusiam - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"4 tahu kulit(coklat)\", \"2 labu kecil\", \"5 Kacang panjang\", \"4 cm lengkuas\", \"2 cm kunyit\", \"8 bawang merah\", \"6 bawang putih\", \"4 Cabai rawit\", \"6 cabai kriting\", \"2 cabai hijau besar\", \"1 sdm gula\", \"1/2 sdt garam\"]', '[\"Bland kunyit, lengkuas, bawang merah, bawang putih, cabai rawit, cabai keriting\", \"Tumis bumbu yang sudah di haluskan. Jika sudah wangi masukan air 250ml\", \"Iris tahu, kacang panjang, labu siam, cabai hijau besar.\", \"Jika bumbu sudah di campur air tunggu mendidih. Kalau sudah mendidih masukan tahu, labu siam, cabai hijau, kacang panjang.\", \"Masukan gula garam dan penyedap rasa sesuai selera\", \"Icipi sampai sesuai selera\", \"Sajikan ™\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2213, 4, 'Tahu bakso geprek', 'Cara membuat Tahu bakso geprek yang enak dan praktis untuk keluarga.', '[\"1 box Tahu bakso\", \"Cabe rawit (sesuai selera pedesnya)\", \"3 siung Bawang putih\", \"Tomat (optional)\", \"Garam\", \"Gula\", \"sedikit Lada\"]', '[\"Ulek langsung jadi 1 cabe + bawang + tomat (kasar aja jgn halus)\", \"Tambahkan garam, gula, lada secukupnya\", \"Geprek tahu / penyet penyet\", \"Level pedas mengikuti selera yaahh.. Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2214, 3, 'Tahu Walik', 'Tahu Walik - olahan tahu yang lezat dan bergizi.', '[\"20 biji tahu goreng\", \"150 gr ayam fillet (blender)\", \"4 sdm tepung terigu\", \"4 sdm tapioka\", \"3 siung bawang putih (dihaluskan)\", \"1 batang daun bawang\", \"secukupnya Garam, merica bubuk, kaldu bubuk\", \"secukupnya Air panas\"]', '[\"Campur daging ayam yg sdh diblender dgn bawang putih yg sdh dihaluskan, tambahkan irisan daun bawang, garam, merica bubuk, kaldu bubuk secukupnya\", \"Tambahkan tepung terigu, tapioka, air panas, kemudian aduk cepat hingga rata\", \"Ambil tahu kemudian sayat, lalu di balik sehingga bagjan dalam ada d luar, kemudian rendam sbntr di air yg d beri kaldu spy bagian dlm yg d balik terasa gurih\", \"Isi tahu dgn adonan, kemudian goreng dgn api kecil hingga krispy\", \"Sajikan dgn sambal kecap\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2215, 2, 'Oseng tahu jamur', 'Resep Oseng tahu jamur ala rumahan yang dijamin menggugah selera.', '[\"1/4 kg jamur\", \"4 biji tahu putih\", \"3 siung bawang merah\", \"4 siung bawang putih\", \"3 buah cabe merah\", \"7 buah cabe hijau\", \"secukupnya Gula jawa\", \"secukupnya Kecap\", \"secukupnya Penyedap\", \"secukupnya Garam\"]', '[\"Suir\\\" jamur &cuci bersih\", \"Potong kecil\\\" dan goreng tahu setengah matang\", \"Potong tipis bawang merah&putih,cabeerah/hijau\", \"Tumis bumbu tsb,lalu masukan jamur dan tahu\", \"Beri kecap,garam,penyedap rasa,gula jawa secukupnya sesuai selera,\", \"Tanda matang:jamur terlihat lunak/empuk🍴\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2216, 2, 'Tahu Telur Ikan Tuing Masak santan', 'Cara membuat Tahu Telur Ikan Tuing Masak santan yang enak dan praktis untuk keluarga.', '[\"1 kg telur ikan\", \"1 ruas lengkuas\", \"1 Santan kara ukuran kecil\", \"2 daun jeruk\", \"2 seray\", \"3 bawang putih\", \"3 belimbing sayur\", \"4 tahu\", \"10 telur puyuh yg telah direbus\"]', '[\"Cuci bersih telur,potong jike mereka bersatu,biar mudah di makannya.sisihkan\", \"Tumis bawang putih yg telah dilaluinya geprek,masukan daun jeruk,seray,biarkan wangi.\", \"Tambahkan air secukupnya,masukan tahu,jika tahu telah matang,masukan telur puyuh dan telur ikan Tuing,biarkan mendidih.\", \"Tambahkan garam,masako,gula,juga Santan kara,aduk hingga rata,jangan lupa tes rasa bunda😊\", \"Biarkan mendidih...terakhir masukan belimbing...siap disantap bunda.\", \"Untuk pendamping boleh tambahkan cabe rawit,sy nggak ngasi soalnya bocah blm bisa dgn rasa pedis😊😊😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2217, 4, 'Tahu saos padang', 'Resep Tahu saos padang ala rumahan yang dijamin menggugah selera.', '[\"1 bh tahu putih uk besar\", \"5 sdm saos tiram\", \"3 sdm saos sambal\", \"1 sdt merica\", \"secukupnya Air\", \"1 btg daun bawang (iris serong)\", \"secukupnya Garam & gula pasir\", \"5 lbr daun jeruk\", \"Bumbu yang dihaluskan :\", \"7 bh bawang merah\", \"4 bh bawang putih\", \"6 bh cabe merah kriting\", \"8 bh cabe rawit merah\", \"1 bh tomat\", \"2 ruas jahe\"]', '[\"Cuci bersih tahu, potong aga panjang.\", \"Goreng tahu sampai setengah matang. Sisihkan\", \"Tumis bumbu yg dihaluskan, masukkan saos tiram, saos sambal, garam, merica, gula, daun jeruk. Sampai bumbu harum.\", \"Tambahkan air, masukkan tahu, aduk rata diamkan sebentar agar bumbu meresap ke tahu.\", \"Masukkan daun bawang. Aduk sebentar lagi, cek rasa.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(2218, 4, 'Tahu Kriting Bawang', 'Nikmati kelezatan Tahu Kriting Bawang dengan resep sederhana ini.', '[\"1 bh tahu putih (tahu cina ukuran besar)\", \"7 sdm tepung terigu\", \"3 sdm tepung tapioka\", \"1/2 sdt lada bubuk\", \"4 siung bawang putih (cincang halus)\", \"3 bh cabe rawit merah (iris kecil)\", \"secukupnya Penyedap rasa lain\", \"secukupnya Garam\", \"secukupnya Air\"]', '[\"Potong dadu tahu putih ukuran sesuai selera (diusahakn jgn terlalu besar)\", \"Campurkan tepung terigu,tepung tapioka dan lada bubuk, pisah kan 3 sdm di tempat yg berbeda untuk bumbu kering\", \"Sisanya campur dengan air secukupnya (jgn terlalu kental dan encer)\", \"Jika adonan sudah selesai masukan tahu ke dalam bumbu basah lalu gulingkan di bumbu kering hingga selesai\", \"Goreng kering tahu sampai kriting, sisihkan\", \"Tumis bawang putih dengan sedikit minyak hingga berwarna kecoklatlan sisihkan, kemudian goreng cabe hingga kering\", \"Setelah selesai aduk bawang putih dan cabe yang sudah kering masukan tahu kriting\", \"Aduk aduk hingga bumbu rata kemudian taburkan sedikit garam\", \"Selesai tahu kriting bawang siap di hidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2219, 4, 'Tumis Labu Tahu Rebon', 'Nikmati kelezatan Tumis Labu Tahu Rebon dengan resep sederhana ini.', '[\"1 bh labu\", \"2 bh tahu ukuran kecil\", \"Secukupnya udang rebon\", \"1/2 bawang bombay\", \"2 siung bawang putih\", \"2 bh cabe keriting merah\", \"2 bh cabe keriting hijau\", \"2 bh cabe rawit merah\", \"Secukupnya Garam\", \"Secukupnya Gula\", \"Secukupnya Air\"]', '[\"Potong labu memanjang ukuran korek api, kemudian cuci bersih, Iris semua bumbu beserta tahu\", \"Goreng sebentar tahu supaya tidak mudah hancur, dan goreng udang rebon hingga kecoklatan kemudian sisihkan\", \"Tumis bumbu bumbu yang telah di iris hingga mengeluarkan aroma harum\", \"Setelah itu masukan sedikit air aduk aduk tambahkan labu yang sudah di iris tambahkan gula, garam dan bumbu penyedap rasa lain nya\", \"Aduk aduk hingga rata koreksi rasa, tutup sebentar supaya labu teksturnya lebih empuk\", \"Jika sudah matang tambahkan tahu dan udang rebon, aduk aduk\", \"Labu tahu rebon siap di hidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2220, 3, 'Tumis tahu crispy', 'Buat Tumis tahu crispy yang nikmat dengan langkah-langkah mudah ini.', '[\"Bahan-bahan\", \"5 kotak tahu putih ukuran sedang\", \"Daun seledri\", \"Bumbu halus\", \"6 buah cabe merah keriting\", \"3 buah cabe rawit\", \"1/2 sdm gula pasir\", \"3 siung bawang putih\", \"secukupnya Garam\", \"Tambahan\", \"1/2 bks bumbu kaldu rasa apa aj\", \"secukupnya Minyak goreng\"]', '[\"Potong tipis2 tahu putih lalu kemudian goreng sampe agak keras, sambil menggoreng uleg bumbu halusyang sudah disiapkan\", \"Iris kecil2 daun seledri\", \"Tumis bumbu halus sampe wangi kemudian masukan 1 sdm gula pasir lanjutkan menumis\", \"Tuangkan tahu yang sudah digoreng aduk aduk sampe rata tambahkan penyedap, koreksi rasa\", \"Terakhir taburkan daun seledri dan aduk lagi sampe daun seledri agak layu dan tumis tahu crispy sudah jadii\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2221, 3, 'Tumis Kikil Tahu', 'Resep praktis Tumis Kikil Tahu yang bisa dicoba di rumah.', '[\"1/4 kikil\", \"2 bh tahu goreng sebentar potong dadu\", \"Secukupnya Masako\", \"secukupnya Gula putih\", \"2 lbr daun jeruk\", \"1 bh tomat kecil\", \"2 bh cabe gendot\", \"Bumbu halus\", \"3 btr bawang merah\", \"2 btr bawang putih\", \"1 cabe merah\", \"1 cabe rawit\", \"Secukupnya garam\"]', '[\"Cuci dan rRebus kikil hingga empuk\", \"Tumis bumbu halus, masukan daun jeruk, cabe gendot dan tomat\", \"Masukan tahu dan kikil tambahkan air. Masukan masako, gula pasir. Cek rasa biarkan mendidih..... sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2222, 2, 'Prekedel Tahu Jagung', 'Kreasi tahu nikmat: Prekedel Tahu Jagung untuk variasi menu harian.', '[\"4 potong Tahu putih\", \"1 buah jagung manis\", \"1 butir telur\", \"1 sachet masako ayam\"]', '[\"Hancurkan Tahu hingga halus\", \"Iris jagung manis\", \"Campurkan Tahu,Jagung yang sudah di iris, masako, dan Telur\", \"Panaskan Minyak dan goreng hingga kekuningan dan Siap di sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2223, 2, 'Tumis Tahu Udang', 'Kreasi tahu nikmat: Tumis Tahu Udang untuk variasi menu harian.', '[\"1/4 kg udang\", \"10 buah tahu putih, potong kotak2 kecil, goreng sebentar\", \"20 buah cabe hijau, potong2\", \"4 butir bawang merah, iris\", \"2 siung bawang putih, iris\", \"Tomat\", \"Serai, ambil putih nya, geprek\", \"Lengkuas, geprek\", \"Jahe, geprek\", \"Daun salam\", \"Garam\", \"Gula merah\", \"Gula pasir\", \"Kecap\", \"Saos tiram\", \"Minyak untuk menumis\", \"Air secukup nya\"]', '[\"Tumis bawang merah dan bawang putih sampai harum\", \"Masukkan cabai hijau, serai, lengkuas, jahe, tomat, aduk rata\", \"Masukkan udang, aduk2 sampai berubah warna\", \"Masukkan tahu, tambahkan air, tunggu sampai mendidih\", \"Tambahkan garam, gula merah, kecap, saos tiram, aduk2\", \"Tambahkan gula pasir, tes rasa\", \"Siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2224, 2, 'Tahu gejrot', 'Resep Tahu gejrot ala rumahan yang dijamin menggugah selera.', '[\"5 buah tahu coklat yg kotak (biasanya pakai tahu sumedang)\", \"5 buah cabai rawit hijau (sesuai selera)\", \"1 siung bawang merah yg besar\", \"1 siung bawang putih yg besar\", \"Bahan kuah :\", \"1 sdm asam jawa\", \"1 keping gula merah (iris halus)\", \"Sejumput garam\", \"1 gelas besar air matang\"]', '[\"Pertama2 goreng sbntar tahu coklatnya, jgn sampai terlalu kering. Jika sudah, angkat.\", \"Giling cabai rawit, bawang merah n putih. Tidak usah terlalu halus yah,kasar saja.\", \"Buat kuahnya. Siapkan air secukupnya, masukkan ke panci kecil, rebus d atas api sedang, kemudian masukkan asam jawa dan irisan gula merah, jika gula sudah larut dan mendidih, angkat.\", \"Penyajian. Potong dadu tahu, letakkan di mangkuk, tambahkan cabai yg td sudah di giling beserta kuah asam manis nya. Aduk2 hingga rata. Tahu gejrot siap untuk dinikmati🤗\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2225, 3, 'Seafood kuah santan plus tahu dan kacang panjang', 'Cara membuat Seafood kuah santan plus tahu dan kacang panjang yang enak dan praktis untuk keluarga.', '[\"5 buah tahu coklat (potong dadu)\", \"5 buah kacang panjang (potong2)\", \"1/2 buah tomat (potong dadu)\", \"1 ekor ikan kembung (potong menjadi 3)\", \"1/4 kg udang\", \"1 sachet santan kara bubuk\", \"Bumbu halus :\", \"1 sdt ketumbar\", \"1 sdt lada\", \"3 butir kemiri\", \"1 ruas jari kunyit\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"Bahan pelengkap :\", \"1 batang sereh (geprek)\", \"3 iris lengkuas (geprek)\", \"4 lembar daun jeruk (disobek2)\", \"2 lembar daun salam\", \"secukupnya Air\", \"1 sdm gula pasir\", \"1 sdt garam\", \"Secukupnya penyedap rasa sapi\"]', '[\"Pertama2, tumis bumbu halus dengan minyak yg agak bnyak, kira2 6 sdm. Aduk rata hingga harum dan keemasan. Kemudian masukkan sereh, lengkuas,daun jeruk n salam. Aduk lagi.\", \"Kemudian masukkan ikan dan udang,aduk hingga berubah warna. Lalu tambahkan air.\", \"Masukkan kacang panjang dan tahu. Aduk2 hingga mendidih, jika sudah masukkan santan bubuk, lalu aduk lagi agar santan tidak pecah.\", \"Tambahkan garam,gula dan penyedap rasa.\", \"Jika semua sudah matang matikan kompor.\", \"Selamat mencoba 🤗🙌\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2226, 4, 'Tumis Kacang Panjang Tahu Tauco', 'Cara membuat Tumis Kacang Panjang Tahu Tauco yang enak dan praktis untuk keluarga.', '[\"2 ikat kacang panjang, potong2\", \"5 buah tahu coklat (tahu yg biasa untuk tahu isi)\", \"2 sdm Tauco\", \"Secukupnya garam, gula, penyedap\", \"2 sdm kecap manis\", \"1 sdm saori saus tiram\", \"1/2 sdt lada bubuk\", \"Bumbu iris :\", \"7 buah cabai rawit merah (sesuai selera)\", \"2 buat cabai merah\", \"1 ruas lengkuas\", \"1 buah tomat hijau ukuran sedang\", \"2 siung bawang putih\", \"3 siung bawang merah\"]', '[\"Potong2 kacang panjang dan tahu, lalu goreng tahu setengah garing. Angkat sisihkan.\", \"Tumis bawang putih dan bawang merah hingga harum, masukan lengkuas, cabai, kecap manis, saus tiram aduk rata. Masukan tomat nya aduk kembali.\", \"Masukan tauco aduk kembali beri air sedikit tambahkan, garam, gula, lada bubuk dan penyedap.\", \"Setelah mendidih masukan kacang panjang nya aduk hingga kacang panjang empuk, masukan tahu masak hingga air menyusut.\", \"Koreksi rasa, setelah pas angkat sajikan bersama nasi hangat dan peyek mantaapp mom 😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2227, 2, 'Sambal goreng kentang cornet tahu😊', 'Sajian Sambal goreng kentang cornet tahu😊 yang praktis dan lezat untuk dinikmati bersama.', '[\"5 bh tahu goreng (beli jadi di pasar)\", \"1 bh kornet kotak\", \"100 gr kentang\", \"Bumbu:\", \"5 siung bawang merah\", \"5 siung bawang putih\", \"3 bh cabe besar (bs dikurangi utk yg tdk suka pedas)\", \"4 bh cabe rawit\", \"1 bh tomat\", \"secukupnya Gula\", \"secukupnya Garam\", \"secukupnya Penyedap rasa\"]', '[\"Kentang dikupas, potong dadu kemudian digoreng smp matang. Tiriskan\", \"Rebus semua bahan bumbu kecuali tomat kurleb 3 menit. Tiriskan. Lalu ulek bahan bumbu tersebut smp 1/2 halus. Tambahkan tomat, ulek lg hingga halus.\", \"Tumis bumbu yg sdh dihaluskan dgn sedikit minyak ato mentega. Stlh wangi masukkan kornet terlebih dahulu. Tumis hingga kornet matang.\", \"Masukkan tahu goreng, kemudian kentang. Tambahkan air sedikit saja. Koreksi rasa. Jika sdh pas...angkat.\", \"Siap disajikan. 👍👍😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2228, 4, 'Tahu Kecap Sederhana', 'Kreasi tahu nikmat: Tahu Kecap Sederhana untuk variasi menu harian.', '[\"3 buah tahu kuning\", \"1 siung bawang putih d cincang\", \"1 Buah Bawang merah di iris\", \"1 btg daun bawang potong serong\", \"Kecap\", \"Kaldu jamur / Kaldu ayam\", \"Garam\", \"Gula\", \"Minyak goreng\", \"Yg suka pedas Silahkan tambah kan potongan Cabe rawit dn micin\"]', '[\"Cuci tahu sampe bersih..potong2 dadu lalu goreng sampe agak kering\", \"Tumis bawang merah dan putih sampe harum tambah kan air kasi kecap garam dan gula biar kan smpe mendidih masukan tahu dan aduk aduk sampe tercampur rata tambah kan bawang daun dan kaldu test rasa dan biar kan air agak meyusut...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2229, 4, 'Tahu isi sayuran', 'Tahu isi sayuran - olahan tahu yang lezat dan bergizi.', '[\"1 bks tahu coklat\", \"250 gr terigu\", \"5 buah wortel (potong korek)\", \"2 genggam toge\", \"secukupnya Kunyit\", \"10 siung bawang putih\", \"1 bks royko ayam\", \"Garam\", \"Sasa\"]', '[\"Cuci sayuran lalu tiriskan\", \"Ulek halus bawang putih dan kunyit lalu di bagi 2 bagian(separuh untuk tumisan separuh untuk adonan terigu)\", \"Tumis bumbu ulek,setelah harum masukkan sayuran,aduk,lalu tmbh royko,jika krg terasa boleh di tambah\", \"Masak tumisan sayur hingga matang\", \"Setelah sayuran matang masukkan ke dalam tahu\", \"Buat adonan terigu dgn sisa bumbu ulek tadi,tnbh air secukupnya,garam dan sasa\", \"Sembari memanaskan wajan masukan tahu sdkt saja ke dalam adonan lalu goreng hingga kecoklatan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2230, 2, 'Sate jamur tahu', 'Cara membuat Sate jamur tahu yang enak dan praktis untuk keluarga.', '[\"250 gr jamur tiram(cincang kasar)\", \"2 btr telur ukuran besar\", \"3 sdm tepung roti halus\", \"secukupnya Garam,kaldu jamur\", \"75 gr kacang tanah sangrai haluskan\", \"1 sdm tepung roti\", \"Secukupnya gula merah\", \"Secukupnya peresan jeruk purut/lemon\", \"Bumbu halus utk sate jamur :\", \"3 siung bawang merah\", \"1 siung bawang putih\", \"Bumbu halus utk saus kacang :\", \"3 siung bawang merah\", \"1 siung bawang putih\", \"3 cm kencur\", \"5 bh cabe merah\", \"6 bh cabe rawit/sesuai selera\", \"secukupnya air matang dingin\"]', '[\"Blender jamur+ telur+bumbu halus+garam secukupnya proses hingga halus(diblender perlahan ya !! Pencet tombol blender biarkan bbrp menit lalu matikan dulu buka tutupnya dan aduk2 sebentar tutup kembali lalu blender kembali,,, kl aku sampai 3x).angkat masukkan ke dlm wadah+tepung roti+bumbu halus+aduk rata.\", \"Olesi wadah atau cetakan dgn minyak masukkan adonan ratakan lalu kukus krg lbh 15 menit lalu angkat dinginkan.\", \"Lalu potong2 dan bentuk kotak2 serasi,tusuk dgn tusukan sate msg2 4 - 5 tiap tusuknya.\", \"Olesi panggangan dgn minyak atau margarine panggang sambil dibolak balik(krn sate jamur ini tdk mengandung lemak seperti ayam/daging makanya lengket,maka ktk akan dibalikan sodok dulu dgn spatula biar sate jamurnya tdk hancur dan tetep cantik),dan setiap akan manggang lg panggannya diolesi kembali ya !!\", \"Tumis bumbu halus utk saus kacang tumis hingga harum+air matang dan gula merah secukupnya masak2 sambil diaduk2+tepung roti aduk2 kembali,kecilkan apinya+garam dan kaldu jamur secukupnya jk dirasa terlalu kental boleh tambah air kembali jng lupa koreksi rasa ya !!\", \"Sajikan sate jamur tahu dgn saus kacang kucuri dgn perasan jeruk purut/lemon secukupnya.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2231, 3, 'Gadon tahu', 'Gadon tahu - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"4 pcs (300 g) tahu putih\", \"1 butir telur\", \"2 siung bawang putih\", \"3 siung bawang merah\", \"2 biji kemiri\", \"sesuai selera Cabe rawit\", \"1 buah cabe besar hijau\", \"1/4 sdt garam\", \"1/4 sdt gula\", \"Daun dan lidi untuk tuk membungkus\", \"1 lmbar daun jeruk (boleh skip)\"]', '[\"Haluskan kemiri, bawang putih dan bawang merah.\", \"Tumis bumbu halus dan daun jeruk\", \"Hancurkan tahu dan campurkan bumbu yang sudah ditumis, gula, garam, irisan cabe hijau dan telur.\", \"Masukkan 2sdm adonan dalam daun dan beri cabe rawit di atasnya. Tutup dengan lidi.\", \"Kukus 15-20 menit. Dan siap disajikan.\", \"Bisa dipanggang sesaat sebelum penyajian jika suka.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2232, 3, 'Sayur Tauge Tahu', 'Kreasi tahu nikmat: Sayur Tauge Tahu untuk variasi menu harian.', '[\"1/4 kg tauge\", \"5 buah tahu\", \"1 buah tomat\", \"Bawang daun\", \"1 siung bawang merah\", \"1 siung bawang putih\", \"Penyedap rasa\", \"Gula merah/putih\", \"Minyak goreng\", \"Air\"]', '[\"Bersihkan tauge dari daun muda dan akarnya. Cuci bersih semua bahan.\", \"Iris bawang merah, bawang putih, tumis sampai harum.\", \"Masukan air secukupnya, tauge yang telah dibersihkan. Rebus sampai empuk.\", \"Masukan tahu yang telah dipotong-potong (lebih baik bila tahu digoreng setengah matang terlebih dahulu)\", \"Masukan potongan daung bawang, tomat, penyedap rasa serta gula.\", \"Selalu tes rasa.\", \"Selesai :D\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2233, 4, 'Mie jagung tahu orek', 'Cara membuat Mie jagung tahu orek yang enak dan praktis untuk keluarga.', '[\"1 mie jagung\", \"1 buah tahu\", \"1 buah wortel\", \"Beberapa lembar sawi\", \"5 siung bawang merah\", \"5 siung bawang putih\", \"secukupnya Lada\", \"secukupnya Garam\", \"Penyedap rasa\"]', '[\"Haluskan tahu pakai garpu, potong wortel dadu², potong tipis² sawi\", \"Rajang bawang merah bawang putih\", \"Rebus mie jagung jangan sampai terlalu lembek, setelah itu tiriskan\", \"Siapkan minyak goreng di wajan\", \"Masukkan tahu, orek sampai kering lalu masukkan wortel dan sawi\", \"Lalu masukkan garam, lada dan penyedap. Orek sampai rata setelah itu tiriskan\", \"Siapkan minyak di wajan\", \"Masukkan potongan bawang merah bawang putih sampai harum, lalu masukkan mie jagung\", \"Lalu campurkan tahu dkk ke wajan, korek sampai matang dan tambahkan garam, lada, penyedap rasa, ratakan\", \"Siap sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2234, 2, 'Oseng kikil tahu', 'Oseng kikil tahu - olahan tahu yang lezat dan bergizi.', '[\"1/2 kg kikil yang sudah lembut dipotong kotak kotak\", \"2 buah tahu putih, potong kotak goreng berkulit\", \"Bumbu :\", \"10 cabe merah\", \"1/2 genggam rawit\", \"Segenggam bawang merah\", \"2 siung bawang putih\", \"Tambahan:\", \"1 jari Lengkuas, jahe geprek\", \"Daun salam, daun jeruk\", \"1 buah tomat segar\"]', '[\"Rebus kikil dalam air mendidih yang audah digarami dan diberi 3 helai daun salam, 5menit menggelegak, matikan api, tiriskan\", \"Goreng cabe bawang dalamnminyak panas 3menit aja, angkat, tiriskan, ulek kasar\", \"Goreng sebentar kikil dalam minyak panas, pinggir\\\"kan kikil, tumis bumbu ulek, tambahkan jahe lengkuas daun salam daun jeruk, dan tomat,\", \"Ulekan bekas ngulek di kungkurah pake air (apaaalah bahasa kungkurah itu ya, dikucek kucek gitu) airnya kucekannya tuang ke kuali.\", \"Kalau sudah wangi aduk semua bahan tambahkan tahu... Aduk, siap di sajikaaan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2235, 3, 'Bola-Bola Tahu Isi Sosis', 'Bola-Bola Tahu Isi Sosis - olahan tahu yang lezat dan bergizi.', '[\"2 buah tahu\", \"2 buah sosis (potong kecil)\", \"1 butir telur (kocok)\", \"250 gr tepung terigu\", \"5 siung bawang putih (haluskan)\", \"secukupnya Lada dan Garam\", \"secukupnya Bubuk cabai\", \"Mie kuning secukupnya (rebus setengah matang)\", \"secukupnya Minyak\"]', '[\"Haluskan tahu, lalu tambahkan telur, masukkan mie kuning, tepung terigu, bawang putih yg sudah dihaluskan, lada, garam, dan bubuk cabai secukupnya. Aduk hingga tercampur merata.\", \"(Ps: bisa ganti pakai tepung terigu serbaguna instan, langsung campur dengan tahu, telur, mie kuning dan bubuk cabai)\", \"Bentuk bulat adonan bola-bola tahu, masukkan sosis di bagian tengah. Bentuk bulat lagi.\", \"Panaskan minyak, goreng bola-bola tahu hingga matang berwarna kecokelatan. Tiriskan. Bola-bola tahu isi sosis siap dihidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2236, 3, 'Tahu Crispy Ekonomis', 'Resep Tahu Crispy Ekonomis ala rumahan yang dijamin menggugah selera.', '[\"Bahan - Bahan :\", \"1 bungkus tahu putih\", \"1 bungkus tepung sajiku serbaguna\", \"2 sendok tepung kanji\", \"4 sendok tepung terigu\", \"Kaldu sapi bubuk\"]', '[\"Potong-potong tahu putih berbentuk dadu\", \"Bikin adonan basah campurkan seperempat tepung sebaguna, 1 sendok tepung kanji, 1 sendok tepung serbaguna, sedikit kaldu sapi tambahkan air\", \"Lalu bikin adonan kering campur sisa tepung serbaguna semuanya, 1 sendok tepung kanji, 3 sendok tepung terigu, tambahkan kaldu bubuk\", \"Terakhir goreng dengan api kecil celupkan ke adonan basah lalu aduk rata diadonan kering terus goreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2237, 4, 'Tahu kecap pedas', 'Resep Tahu kecap pedas ala rumahan yang dijamin menggugah selera.', '[\"5 siung bawang putih\", \"3 siung bawang merah\", \"Sedikit kunyit\", \"10 cabe rawit\", \"Secukupnya lada\", \"Kecap Manis\", \"Gula\", \"Garam\", \"Penyedap rasa\", \"secukupnya Minyak goreng\", \"secukupnya Air\"]', '[\"Haluskan bahan-bahan seperti bawang merah, bawang putih, kunyit, cabe rawit dan lada.\", \"Goreng tahu setengah masak. Jangan terlalu masak nanti bumbunya tidak menyerap ke tahu\", \"Tumis bumbu yang sudah dihaluskan dengan sedikit minyak goreng sampai harum bumbunya keluar.\", \"Lalu tambahkan air secukupnya. Garam, gula dan penyedap rasa.\", \"Setelah itu masukkan tahu yang sudah digoreng setengah masak tadi. Koreksi rasa, setelah rasanya pas tambahkan kecap secukupnya.\", \"Setelah air sedikit menggurang matikan kompor dan tahu siap disajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2238, 2, 'Sayur tahu cabe kentang', 'Sajian Sayur tahu cabe kentang yang praktis dan lezat untuk dinikmati bersama.', '[\"sesuai selera Tahu yg sdh digoreng\", \"Cabe ijo iris serong 3 bh\", \"Bumbu :\", \"3 butir kemiri\", \"3 bh cabe keriting merah\", \"4 siung bawang merah\", \"3 siung bawang putih\", \"Secukupnya garam\", \"Secukupnya gula putih\", \"Secukupnya Penyedap rasa (optional)\", \"1/2 bks santan kara\", \"Air\", \"1 lbr daun salam + serai geprek\"]', '[\"Haluskan bumbu2, bawang merah, putih, kemiri boleh diulek ato blender ya moms\", \"Panaskan wajan yg telah diberi minyak goreng secukupnya\", \"Masukan bumbu halus hingga wangi tambahkan daun salam n serai lalu tambahkan air secukupnya\", \"Setelah mendidih masukan cabe hijo n tahu yg sdh digoreng tambahkan garam, gula n penyedap (optional) cek rasa\", \"Setelah dirasa pas, tambahkan santan kara aduk2 beberapa saat, lalu siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2239, 4, 'Tahu isi dadakan', 'Buat Tahu isi dadakan yang nikmat dengan langkah-langkah mudah ini.', '[\"Tahu kotak potong 6\", \"1/4 pot Sayur kol iris tipis\", \"2 pc wortel parut\", \"secukupnya Daun bawang dan seledri\", \"Bumbu halus\", \"2 siung bawang putih\", \"4 siung bawang merah\", \"1 sdt merica bubuk\", \"Bumbu lapisan\", \"5 sdm tepung terigu\", \"2 sdm tepung beras\", \"1 ruas kunyit\", \"2 siung bawang putih\", \"3 siung bawang merah\", \"1 sdt ketumbar bubuk\", \"Air secukupnya untuk melarutkan\", \"secukupnya Garam,merica,penyedap rasa\"]', '[\"Goreng tahu dengan minyak tg agak banyak agar dalemnya tahu kering\", \"Tumis bumbu halus dan sayur yg sudah di iris masukan seledri dan daun bawang beri garam merica penyedap rasa matang tiriskan\", \"Masukan isian ke tahu sampai selesai dgn cara menyobek bagian tengah tahu\", \"Larutkan tepung dan bumbu halus utk lapisan masukan tahu yg sudah diisi goreng dan tiriskan siap untuk di makan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2240, 4, 'Lontong tahu', 'Lontong tahu - olahan tahu yang lezat dan bergizi.', '[\"2 Lontong bungkus daun pisang\", \"1 Cabe rawit\", \"3 sdm kacang tanah goreng\", \"1 buah bawang putih\", \"secukupnya Gula merah\", \"secukupnya Garam\", \"secukupnya Air hangat\", \"2 buah tahu yang sudah digoreng\", \"secukupnya Kol\", \"secukupnya Bawang merah goreng\", \"secukupnya Kecap manis\"]', '[\"Uleg cabe, bawang putih, garam, kacang tanah, dan gula merah\", \"Setelah halus, tambahkan air hangat sedikit demi sedikit sambil diuleg\", \"Jika dirasa sudah cukup..cek rasa\", \"Potong potong lontongnya dan taruh didalam piring..\", \"Kemudian potong potong tahu. Serta kolnya iris tipis..lalu taruh di atas lontongnya\", \"Setelah itu, tuangkan sambalnya diatasnya.. dan beri kecap serta bawang merah goreng..\", \"Taraaaaa.. siap disajikan dan siap disantap..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2241, 4, 'Tahu Fantasi', 'Resep Tahu Fantasi ala rumahan yang dijamin menggugah selera.', '[\"400 gr tahu (5biji yg besar)\", \"1 buah wortel\", \"1 keping bihun\", \"1 tangkai daun bawang,seledri\", \"2 butir telur\", \"1 sct masako\", \"4 siung bawang putih,haluskan\", \"1/2 sdt garam\", \"1/2 sdt merica bubuk\", \"Lapisan:\", \"2 sdm tapioka\", \"2 sdm air\", \"2 butir telur\", \"Secukupnya garam,merica\"]', '[\"Seduh bihun hingga mengembang,tiriskan. Lumatkan tahu,serut wortel. Cincang daun seledri dan iris daun bawang.\", \"Campur semua bahan dgn bumbu lain, selain telur. Test rasa. Jika sudah pas,masukkan telur aduk rata.\", \"Olesi cetakan/loyang dgn minyak. Sy tambahkan baking paper karna pake loyang brownis. Tuang adonan,kukus hingga matang kurang lebih 30 menit. Jgn lupa lapisi tutup panci dgn kain bersih.\", \"Jika sudah matang,angkat dan dinginkan. Bila perlu masukkan dlm kulkas agar lebih mudah dipotong dan tidak hancur saat digoreng. Potong2 sesuai selera.\", \"Bahan pencelup: campur tapioka dgn air hingga larut kemudian masukkan telur,garam dan merica Kocok hingga rata.\", \"Celupkan tahu dlm bahan pencelup,goreng hingga matang. Tiriskan ato serap dgn tissue dapur. Lebih nikmat disajikan dgn cabai muda ato saos sambel.\", \"Selamat menikmati 😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2242, 2, 'Pepes tahu jamur', 'Pepes tahu jamur - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 kotak Tahu\", \"1 ons Jamur tiram\", \"1 butir Telor ayam\", \"Bumbu :\", \"4 siung bawang merah\", \"3 siung bawang putih\", \"3 biji Cabe / selera\", \"lidi Daun pisang buat bungkusnya dan\"]', '[\"Langkah membuat : hancurkan tahu.lalu siangin jamur tiram lalu cuci bersih campurkan bersama tahu..lalu haluskan bumbu yg di atas aduk rata bersama tahu dan jamur tambah kan telor aduk kembali beri garam micin roico aduk aduk sampai rata..lalu bungkus semat menggunakan lidi setelah selesai semua panggang menggunakan hapy call atau wajan yg sudah tidak di pakai.panggang pakai api kecil sambil di bolak balik sampai Mateng sempurna setelah matang angkat...dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2243, 2, 'Oseng tahu', 'Kreasi tahu nikmat: Oseng tahu untuk variasi menu harian.', '[\"1 buah tahu\", \"1 buah wortel\", \"secukupnya Sawi putih\", \"1 buah telor\", \"1 buah cabe merah besar (pedasnya sesuai selera)\", \"1 bawang bombai\", \"2 siung bawang putih\", \"4 siung bawang merah\", \"Ladaku\", \"Garam\", \"Saos tiram\", \"Saos raja rasa\", \"Kecap\"]', '[\"Iris bawang bombay, bawang merah, bawang putih, cabe kemudian tumis dgn sedikit minyak\", \"Masukkan wortel yg sudah di potong2, tunggu hingga wortel sedikit empuk\", \"Masukkan tahu yg sudah di potong2. Masak hingga tahu matang\", \"Masukkan sawi putih yg sudah si potong2, lalu tambahkan garam, saos tiram, saos raja rasa, ladaku secukupnya\", \"Masukkan telor, masak hingga matang, dan koreksi rasa.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2244, 4, 'Sambal goreng kentang, tahu+pete', 'Nikmati kelezatan Sambal goreng kentang, tahu+pete dengan resep sederhana ini.', '[\"1/4 kg kentang\", \"3 pipih tahu ukuran sedang\", \"5 biji pete\", \"5 cabe rawit\", \"3 cabe keriting\", \"5 bawang merah\", \"3 bawang putih\", \"2 lembar daun jeruk\", \"secukupnya Gula\", \"secukupnya Garam\", \"secukupnya Royco ayam\", \"secukupnya Kecap\", \"Bawang goreng secukupnya utk taburan\", \"Minyak goreng\"]', '[\"Potong dadu kentang dan tahu lalu goreng setengah matang dan tiriskan\", \"Haluskan bawang merah bawang putih, cabe rawit, dan cabe keritinng\", \"Panaskan minyak goreng utk menumis\", \"Masukan bumbu dan daun jeruk yg sudah di haluskan pada minyak yg telah di panaskan\", \"Setelah bumbu layu masukan pete dan tambahkan sedikit air, masukan juga guka, garam dan royco\", \"Masukan kentang dan tahu yg sudah d goreng setengah matang\", \"Tunggu sampai bumbu meresap, koreksi rasa dan siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2245, 3, 'Pentol tahu', 'Pentol tahu - olahan tahu yang lezat dan bergizi.', '[\"4 potong tahu\", \"300 g tepung terigu\", \"200 g tepung tapioka\", \"4 butir bawang putih\", \"1/2 sdt Lada bubuk\", \"1/2 sdt Garam\", \"1/2 bks penyedap rasa\", \"Minyak untuk menggoreng\", \"secukupnya Air hangat\"]', '[\"Potong tahu tipis2 kemudian goreng hingga kering\", \"Siapkan adonan isi,campurkan tepung terigu,tapioka garam,lada beserta bawang putih yg sdah dihaluskan\", \"Tambahkan air hangat sedikit demi sedikit\", \"Campur adonan hingga seperti adonan donat\", \"Belah bagian tahu kemudian isi dengan adonan tepung\", \"Kukus selama kurang lebih 20menit\", \"Setelah matang sajikan bersama saos agar lebih enak\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2246, 3, 'Triple T (Tahu-Teri-Tauco) Masak Pedas👄👌', 'Resep Triple T (Tahu-Teri-Tauco) Masak Pedas👄👌 yang lezat dan mudah dibuat di rumah.', '[\"3 buah tahu putih petak\", \"1 bungkus tauco\", \"1 genggang ikan teri\", \"Bumbu iris :\", \"2 siung bawang putih\", \"2 siung bawang merah\", \"4 buah cabe hijau\", \"10 buah cabe rawit\", \"1 batang daun bawang\", \"8 buah cabe merah (giling halus)\", \"1 sdm gula pasir/ sesuai selera\", \"100 ml air\", \"Secukupnya minyak utk menumis\"]', '[\"Cuci bersih tahu, potong dadu agak besar, lalu goreng sebentar, angkat dan tiriskan.\", \"Goreng ikan teri diminyak panas, angkat dan tiriskan.\", \"Tumis bumbu iris hingga harum, lalu masukan cabe giling, tumis sebentar. Masukkan ikan teri yg sdh digoreng td, tauco, gula dan beri air, lalu masukkan tahu goreng td, tunggu hingga mendidih dan bumbu meresap. Koreksi rasa, matikan api. Nb: sya tdk pake garam krn taucony sdh asin, dan byknya air sesuai selera.\", \"Triple T udh jd..enk disantap selagi hangat plus nasi hangat👌😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2247, 2, 'Kecambah Tahu Sari', 'Resep Kecambah Tahu Sari ala rumahan yang dijamin menggugah selera.', '[\"1 bungkus Tahu Sari (kuning). klau di daerah saya cuma 3 rb\", \"2 bungkus kecambah. klau da daerah saya 2 rb bun\", \"3 cabe hijau besar\", \"2 cabe rawit (ini bisa sesuai selera ya bun)\", \"2 siung bawang putih\", \"1/2 sdt gula pasir\", \"1/2 sdt garam atau sesuai selera\", \"1/2 bngkus magic lezat (bisa di cut bun)\", \"3 sdm minyak goreng utk menumis bumbu\"]', '[\"Cuci bersih kecambah lalu tiriskan, potong dadu tahu sari (atau sesuai selera)\", \"Iris cabai dan bawang putih, lalu tumis sampai harum\", \"Masukkan tahu sari, biarkan kurleb 3 mnitn bun. seasoning bun, msukkan gula, garam dan magic lezatny.\", \"Terakhir msukkan kcmbah, dan masak lgi kurleb 2 menitan.\", \"dan taara siap deh. jgn lupa tburi bawang goreng bun biar mkin endees.😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2248, 2, 'Tumis kacang panjang, tahu dan telur puyuh', 'Kreasi tahu nikmat: Tumis kacang panjang, tahu dan telur puyuh untuk variasi menu harian.', '[\"10 lonjor kacang panjang\", \"12 buah tahu pong\", \"10 butir telur puyuh (kupas)\", \"Bumbu :\", \"6 siung bawang merah\", \"3 siung bawang putih\", \"5 buah cabe merah\", \"Secukupnya garam dan gula\", \"Minyak untuk menumis\", \"2 sdm saos tiram\"]', '[\"Potong2 kacang panjang, cuci bersih.\", \"Iris bawang merah, bawang putih dan cabe, kemudian tumis sampai harum.\", \"Masukkan kacang panjang bolak-balik sampai layu baru masukkan telur puyuh dan tahu.\", \"Beri sedikit air, kemudian masukkan gula dan garam.\", \"Masak sampai meresap, kemudian masukkan saus tiram. Koreksi rasa....\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2249, 2, 'Tahu Cabe Garam Pk Daun Jeruk', 'Tahu Cabe Garam Pk Daun Jeruk - olahan tahu yang lezat dan bergizi.', '[\"10 biji tahu putih potong 4\", \"1 bungkus Tepung Sajiku\", \"2 sdt Tepung Maizena\", \"1 batang daun bawang\", \"10 lembar daun jeruk\", \"5 biji bawang putih\", \"7 biji cabe merah kecil\", \"secukupnya Garam\", \"secukupnya Minyak\", \"secukupnya Totole\"]', '[\"Potong dadu tahu putih menjadi 4 bagian..lalu lumuri dengan tepung sajiku dan tepung meizena (ingat tdk usah dikasih air tepungnya)\", \"Lalu goreng tahu hingga kecoklatan dan angkat tiriskan\", \"Cincang bawang putih,potong daun bawang,daun jeruk,cabe rawit..lalu tumis hingga harum dan layu\", \"Setelah itu masukkan tahu tadi..lalu kasih garam,totole secukupnya\", \"Setelah rata bumbu dg tahu nya..hidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2250, 2, 'Tahu isi sosis', 'Buat Tahu isi sosis yang nikmat dengan langkah-langkah mudah ini.', '[\"2 buah tahu putih besar kukus\", \"2 buah sosis potong kecil2\", \"2 siung bawang putih\", \"3 bawang merah goreng dan haluskan\", \"1 butir telur\", \"Daun bawang\", \"1 sdm Saos tiram\", \"1 sdt minyak wijen\", \"sesuai selera Lada, garam dan penyedap\", \"2 sdm tepung terigu\"]', '[\"Bismillah.\", \"Bahan: 2 buah tahu putih besar kukus(setelah dingin potong jadi 4, dari 1 potong potong lagi serong jadi 2) kerok tengahnya. Dan haluska\", \"Tahu yang dikerok haluskan tambah sosis telur, sagu dan bumbu aduk jadi satu masukkan ke lubag tahu padatkan goreng apabila adonan pecah bisa titambahkan telur kocok goreng dan sajikan\", \"Kalau mau dikukus juga bisa umm\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2251, 4, 'Tumis tahu sosis', 'Nikmati kelezatan Tumis tahu sosis dengan resep sederhana ini.', '[\"2 buah tahu putih\", \"2 buah sosis\", \"2 buah tomat\", \"1 buah bawang Bombay\", \"3 siung bawang putih\", \"8 buah cabe rawit\", \"3 buah cabe hijau\", \"1 sdm saus tomat\", \"1 sdm maizena larutkan dengan sedikit air\", \"secukupnya Garam gula penyedap\"]', '[\"Tahu dipotong dadu.goreng sampai setengah matang\", \"Iris tipis bawang Bombay dan bawang putih,cabe rawit dan cabe hijau.\", \"Tumis terlebih dahulu bawang Bombay dan bawang putih sampai harum.baru masukkan cabe.tumis lagi\", \"Tomat dipotong kotak2,tumis.tambahkan saus tomat\", \"Tambahkan sedikit air, masukkan tahu.aduk rata.\", \"Sosis dipotong bulat2, tambahkan ke tumisan.beri garam gula dan penyedap.tes rasa.aduk sampai mendidih dan air sedikit menyusut.\", \"Setelah mendidih tuang larutan maizena.aduk cepat,matikan api.sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2252, 2, 'Tahu Saus Tiram', 'Buat Tahu Saus Tiram yang nikmat dengan langkah-langkah mudah ini.', '[\"2 tahu putih\", \"1 batang daun bawang\", \"1 bawang putih\", \"2 bawang merah\", \"1 cabe rawit\", \"1 sdt kecap manis\", \"1 1/2 sdt saus tiram\", \"Secukupnya gula jawa\", \"Secukupnya garam\", \"Secukupnya penyedap (optional)\", \"Sedikit air\", \"Sedikit minyak untuk menumis\"]', '[\"Potong tahu sesuai selera 👉 goreng.\", \"Tumis bawang putih, bawang merah sampai harum.\", \"Masukkan sedikit air, cabe, tahu goreng, gula jawa, garam, kecap, saus tiram.\", \"Masukkan daun bawang. Cek rasa.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2253, 3, 'Tahu Goreng Sambel Kecap', 'Tahu Goreng Sambel Kecap - olahan tahu yang lezat dan bergizi.', '[\"1 tahu cina ukuran besar, potong dadu\", \"Minyak goreng\", \"Untuk Sambel Kecap:\", \"8 butir bawang merah diiris tipis\", \"2 butir bawang putih diiris tipis\", \"10 buah rawit hijau diiris\", \"Kecap manis\"]', '[\"Tahu cina dipotong dadu lalu goreng sampai kuning keemasan\", \"Goreng bahan2 sambel kecap dengan 1/2 sdm minyak sampai matang atau setengah matang, sesuai selera\", \"Tiriskan tambahkan kecap manis\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2254, 2, 'Tahu Isi KW DEBM', 'Kreasi tahu nikmat: Tahu Isi KW DEBM untuk variasi menu harian.', '[\"500 ml putih telur\", \"50 ml santan kental\", \"Secukupnya kaldu bubuk\", \"1 buah wortel ukuran kecil, parut\", \"1 batang daun bawang, iris\", \"1 butir telur utuh\", \"1 sachet agar2 plain\"]', '[\"Campurkan putih telur, santan kental dan kaldu bubuk, aduk sampai rata, lalu kukus sampai matang.\", \"Potong2 kotak2 putel kukus tsb seukuran tahu, sisihkan.\", \"Untuk isian, campurkan parutan wortel, irisan daun bawang, dan 1/2 sachet agar2 plain tambahkan kaldu bubuk dan sedikit air, aduk rata.\", \"Di tempat lain lagi, campur 1/2 sachet agar2 dengan sedikit air, lalu masukkan telur dan kocok lepas.\", \"Iris tahu kw dibagian tengah, lalu isi dengan adonan isi dibagian tengahnya.\", \"Celupkan ke dalam adonan telur dan agar2 yg telah dikocok lepas tadi.\", \"Goreng dalam minyak panas sampai golden brown.\", \"Balik sisi yg satunya, goreng sampai matang.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2255, 4, 'Tahu telur puyuh bumbu merah', 'Resep Tahu telur puyuh bumbu merah yang lezat dan mudah dibuat di rumah.', '[\"1/4 kg telor puyuh (rebus/goreng sesuai selera)\", \"1/2 papan tahu putih. Potong persegi. Goreng setengah mateng\", \"5 buah cabe merah besar (buang bijinya. Cuci. Rebus)\", \"8 siung bawang merah\", \"5 siung bawang putih\", \"Secukupnya jahe\", \"Secukupnya kunyit\", \"2 lembar daun jeruk\", \"2 lembar daun salam (saya skip soalnya pas nggak ada)\", \"Secukupnya gula merah\", \"Secukupnya garam\", \"Secukupnya penyedap rasa (boleh skip)\"]', '[\"Blender cabe merah rebus, bawang merah, bawang putih, jahe, kunyit sampai halus.\", \"Tumis bumbu halus bersama daun jeruk hingga matang. Masukkan tahu dan telor. Bumbui gula merah, garam, penyedap rasa. Tambahkan air secukupnya. Aduk rata. Tunggu hingga matang dan air menyusut. Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2256, 4, 'Tahu isi', 'Resep Tahu isi ala rumahan yang dijamin menggugah selera.', '[\"Tepung terigu\", \"Tepung beras\", \"Kubis\", \"Wortel\", \"Toge\", \"Garam\", \"Lada\", \"Penyedap\"]', '[\"Rendam tahu di hangat kasih garam dikit,belah tengahnya.selama 30mnt.\", \"Tumis bawang putih,lada yg sudah dihaluskan beri air sedikit masukan semua sayuran yang sudah diiris kecil.\", \"Isi tahu dengan isian sayur.\", \"Masukan tepung terigu,tepung beras sedikit,bawang putih garam penyedap yang dihaluskan,beri air aduk hingga tercampur rata.\", \"Masukan tahu isi ke adonan,pelan pelan saat membalurny supaya isian tahu tidak keluar ya.\", \"Siapkan minyak goreng,tahu di goreng.\", \"Angkat,tiriskan tahu siap di hidangkan.selamat mencoba😉\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2257, 3, 'Tahu kecap', 'Tahu kecap - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"10 buah Tahu coklat\", \"6 siung bawang merah\", \"3 siung bawang putih\", \"2 buah cabai besar\", \"5 buah cabai rawit\", \"1/2 buah tomat\", \"1 lembar daun salam\", \"Kecap\", \"Garam\", \"Daun bawang\"]', '[\"Iris bawang merah, bawang putih, cabai besar, cabai rawit, tomat. tumis dengan daun salam hingga layu serta harum\", \"Tambahkan air dan kecap kemudian masukkan tahu\", \"Masak hingga air sedikit lalu beri garam, penyedap rasa\", \"Tambahkan daun bawang yang diiris besar-besar, aduk sebentar lalu matikan api\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2258, 3, 'Tumis orek tahu', 'Resep Tumis orek tahu yang lezat dan mudah dibuat di rumah.', '[\"1 buah tahu gede\", \"secukupnya Kol\", \"Bumbu :\", \"4 siung bawang merah\", \"2 siung bawang putih\", \"10 biji rawit ijo\", \"5 biji rawit merah\", \"3 biji cabe merah\", \"1 batang daun bawang (iris tipis)\", \"1 sdt garam\", \"Penyedap\", \"1/2 bungkus royko ayam\"]', '[\"Cuci bersih tahu, lalj Hancurkan tahu dgn garpu\", \"Iris tipis bawang, iris serong cabe. Tumis tambahkan garam dll masukan tahu & kol jika sdh matang baru masukan daun bawang.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2259, 3, 'Tahu susu teriyaki', 'Cara membuat Tahu susu teriyaki yang enak dan praktis untuk keluarga.', '[\"1 sct saos teriyaki\", \"4 bh tahu susu, goreng\", \"4 bh baso, iris\", \"1 butit telur\", \"3 bawang putih\", \"1/2 sdm kecap asin\", \"2 sdm kecap manis\", \"Secukupnya gula garam\", \"Secukupnya air\"]', '[\"Tumis bawang putih, hingga harum. Masukkan telur, buat orak arik. Masukkan baso. Beri air sedikit\", \"Tambahkan saos teriyaki, tahu, kecap asin, kecap manis, beri bumbu, koreksi rasa. Masak hingga bakso matang. Taburi biji wijen jika suka. Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2260, 4, 'Perkedel Tahu Sayur Super Kilat', 'Perkedel Tahu Sayur Super Kilat - olahan tahu yang lezat dan bergizi.', '[\"4 buah tahu putih\", \"1 ons kubis\", \"1 buah wortel\", \"1 tangkai bawang pre\", \"1 helai seledri\", \"5 bamer\", \"3 baput\", \"1 mie burung dara di kremes (optional)\", \"1 saset tepung beras maybe 50gram\", \"1 sdm tepung bumbu ayam kremes\", \"1/2 sdt kaldu bubuk sy make rasa ayam\", \"secukupnya merica ketumbar gula garam minyak\"]', '[\"Hancurkan tahu, campur dg irisan wortel kubis daun pre seledri mie kremes tepung beras tepung bumbu ayam kremes baput bamer penyedap rasa garam gula merica dan ketumbar. aduk hingga tercampur rata test rasa.\", \"Kemudian panaskan minyak setelah minyak panas bentuk adonan bulat2 dan langsung goreng sampai kering. sajikan selagi hangat dg saus tomat atau saus pedas hehehe.. simple bukan? 😍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2261, 4, 'Sapo Tahu Simple', 'Buat Sapo Tahu Simple yang nikmat dengan langkah-langkah mudah ini.', '[\"100 gram Udang\", \"1 batang wortel, iris serong\", \"Tahu sutra, goreng stengah matang\", \"1 siung bawang putih, cincang halus\", \"1 buah bawang bombang, iris tipis\", \"1 sdm Saus tiram\", \"1 sdm Kecap inggris\", \"1 sdm Maizena\", \"Gula\", \"Garam\", \"secukupnya Air\"]', '[\"Tumis bawang bombay dan bawang putih sampai harum\", \"Masukkan udang, tumis sebentar\", \"Tambahkan saus tiram dan kecao inggris\", \"Masukkan wortel, tambahkan 1 cup air (atau lebih), diamkan sampai wortel cukup empuk\", \"Tambahkan maizena yg telah dilarutkan, aduk sebentar sampai mengental\", \"Masukkan tahu goreng\", \"Tambahkan gula dan garam\", \"Koreksi rasa\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2262, 2, 'Mangut tongkol tahu', 'Cara membuat Mangut tongkol tahu yang enak dan praktis untuk keluarga.', '[\"tongkol 2 ekor\", \"tahu 3 buah potong kotak2\", \"65 ml santan kara\", \"2 btg serai (geprek)\", \"3 cm lengkuas\", \"2 lembar daun jeruk\", \"2 cabe merah besar (iris)\", \"bumbu halus :\", \"3 siung bawang putih\", \"5 siung bawang merah\", \"7 biji cabe rawit\", \"2 biji kemiri\", \"1 ruas jahe\", \"1 ruas kunyit\", \"2 cm kencur\", \"1/4 biji pala\", \"1 sdt ketumbar\", \"secukupnya gula,garam\"]', '[\"Tumis bumbu halus,kemudian tambahka sereh,daun jeruk,lengkuas dan cabe merah...tumis hingga harum\", \"Tambahkan sedikit air\", \"Masukan tongkol yg sudah digoreng setengah mateng\", \"Setelah itu masukkan tahu yg sudah digoreng\", \"Tambahkan santan,masukkan gula garam...koreksi rasa\", \"masak hingga air menyusut...\", \"siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2263, 4, 'Tumis kikil tahu exsta pedas', 'Tumis kikil tahu exsta pedas - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 bungkus kikil matang\", \"2 byah tahu\", \"5 biji cabe ijo\", \"5 biji cabe merah\", \"15 biji cabe rawit\", \"5 biji bawang merah\", \"2 biji bawang putih\", \"I buah tomat\", \"secukupnya Kecap\", \"Garam\", \"Penyedap rasa\", \"Minyak\", \"Air\"]', '[\"Potong bawang merah bawang putih potong cabe serong tipis iris juga tomat secara serong\", \"Panaskan wajan kasih minya tumis bawang merah bawang putih setelah harum masukkan cabe tomat dan garam\", \"Setelah cabe layu masukkan kikil dan kecap kasih air tunggu sampai matang kasih penyedap rasa secukupnya cek rasa\", \"Tumis kikil tahu ekstra pedas siap dihidangkan cocok sekali dengan nasi yang masih hangat\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2264, 4, 'Sate tahu crispi', 'Sajian Sate tahu crispi yang praktis dan lezat untuk dinikmati bersama.', '[\"Tahu (potong dadu ukuran sedang)\", \"Bawang putih uleg halus\", \"Air secukupnya untuk merendam tahu\", \"1 sdm tepung terigu\", \"1/2 sdt kaldu bubuk non msg\", \"1/2 adm tepung maizena\", \"Secukupnya garam\", \"Secukupnya tepung panir\"]', '[\"1. Bersihkan tahu, lumuri dengan bawang putih uleg dan garam, diamkan 30 menit\", \"2. Siapkan tepung bumbu basah (tepung terigu, tepung maizena, kaldu ayam non msg, garam dan air) dengan kekentalan sedang\", \"3. Celupkan tahu ke bahan pencelup kemudian baluri ke tepung panir\", \"4. Goreng di minyak panas dengan api kecil\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(2265, 2, 'Sup Tahu Baso Ikan', 'Sup Tahu Baso Ikan - olahan tahu yang lezat dan bergizi.', '[\"1 buah tahu cina. Potong kotak2\", \"3 buah baso ikan. Belah 2\", \"2 siung bawang putih. Cincang kasar\", \"1 batang daun bawang. Iris2\", \"500 ml air matang\", \"2 sdm minyak sayur\", \"Bumbu :\", \"1/2 sdt kaldu jamur\", \"Sejumput garam, lada, gula\"]', '[\"Panaskan minyak di wajan. Tumis bawang putih sampai harum dan kecoklatan. Lalu masukan baso ikan, aduk2 sebentar. Masukan air dan tahu. Besarkan api, tunggu sampai mendidih.\", \"Setelah air mendidih, kecilkan api, beri bumbu2, aduk rata. Tes dan koreksi rasa. Terakhir masukan daun bawang, matikan api. Selesai.\", \"Sajikan hangat. Yummy!! 😘\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2266, 2, 'Oseng-oseng tumis tahu tauge simple', 'Sajian Oseng-oseng tumis tahu tauge simple yang praktis dan lezat untuk dinikmati bersama.', '[\"1 bungkus tahu putih kotak\", \"1 gengam tauge\", \"7 buah cabai\", \"3 siung bawang putih\", \"2 siung bawang merah\", \"1 buah bawang bombay\", \"3 buah rampai/ 1 bh tomat\", \"Secukupnya gula\", \"Secukupnya masako/garam\", \"Secukupnya lada bubuk\", \"Secukupnya kecap (me: bangau)\"]', '[\"Potong tahu kotak menjadi 4 (dadu). Haluskan bawang putih ambil tempat. Masukkan bawang yang telah dihaluskan tambah air dan rendam tahu. (Ini optional ya, tergantung suka atau tidak)\", \"Iris bawang merah, bawang putih, bawang bombay, cabai (iris menyerong), dan rampai (potong 2 bagian)\", \"Ambil wajan panaskan minyak sedikit saja, kalau sudah panas (jangan terlalu panas) masukkan bahan2 irisan oseng-oseng tambahkan 1 sendok gula dan masako secukupnya, oseng-oseng sampai harum\", \"Lalu masukkan tahu, tambah sedikit air. Oseng2, tambahkan lada bubuk secukupnya. biarkan sebentar sampai bumbu sedikit meresap, lalu ambil 1 gengam tauge, Masukan sedikit kecap (me: bangau). Oseng2 kembali. Cek rasa.\", \"Kalau dirasa sudah pas, angkat dan sajikan bersama nasi hangat❤️\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2267, 4, 'Tumis tahu tauge', 'Cara membuat Tumis tahu tauge yang enak dan praktis untuk keluarga.', '[\"4 tahu putih\", \"Secukupnya tauge\", \"Secukupnya wortel\", \"3 bawang merah\", \"2 bawang putih\", \"4 rawit merah\", \"Gula\", \"Garam\", \"Penyedap\"]', '[\"Cuci bersih tauge\", \"Rendam tahu diair panas/hangat lalu potong\", \"Cuci dan Potong wortel\", \"Potong bawang dan cabai\", \"Tumis bumbu smp harum,masukkan tahu aduk dan ttup sbntr\", \"Masukkan tauge dan wortel beri sdkt air\", \"Masukkan gula garam dan penyedap\", \"Tes rasa klo sdh ok angkat dan sajikan\", \"Simple👌\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2268, 4, 'Pepes Tahu Putih', 'Sajian Pepes Tahu Putih yang praktis dan lezat untuk dinikmati bersama.', '[\"kotak besar Tahu putih\", \"daun Kemangi\", \"Daun pisang utk membungkus\", \"bawang merah\", \"bawang putih\", \"cabe merah\", \"kemiri\", \"ketumbar\", \"kunyit\", \"lada bubuk\", \"daun salam\", \"daun sereh dipotong panjang2 (kira-kira 4cm)\", \"garam\"]', '[\"Haluskan tahu putih. Haluskan bumbu : bawang merah, bawang putih, kunyit, ketumbar, Kemiri, cabe merah, garam.\", \"Cuci bersih daun kemangi, daun salam dan sereh. Potong potong daun sereh. Campurkan tahu dengan bumbu yang sudah halus, campurkan daun kemangi.\", \"Siapkan daun pisang yang sudah dibersihkan. terlebih dulu ditaruh 1 lembar daun salam, letakan adonan pepes tahu,masukan cabai beserta potongan daun kemangi dan daun sereh didalamnya. Lipat dengan menggunakan daun pisang.\", \"Masukkan pepes tahu kedalam panci untuk mengukus. Kurang lebih 30 menit pepes tahu sudah matang. Bisa terlihat dari warna daun pisang yang sudah layu. Angkat pepes tahu Pepes tahu kemangi siap dinikmati\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2269, 3, 'Tahu crispy simple', 'Sajian Tahu crispy simple yang praktis dan lezat untuk dinikmati bersama.', '[\"1 bungkus tahu putih/kuning (kotak)\", \"1 bungkus tepung crispy sajiku\", \"2 siung bawang putih (haluskan)\", \"Secukupnya air\", \"secukupnya Lada\", \"secukupnya Masako\"]', '[\"Potong tahu kecil2 dadu, lalu ambil wadah haluskan bawang putih ambil air rendam tahu yang telah di potong tadi sekitar 10 menit sampai meresap.\", \"Ambil wadah lain, masukkan tepung terigu, secukupnya lada dan sedikit masako (ini optional) kalo udh merasa asin gakusah, tambahkan air secukupnya jangan terlalu encer nanti malahan tidak crispy.\", \"Aduk semua bahan, angkat tahu yang telah di rendam. Campurkan ke dalam tahu, aduk2. goreng tahu 1-1 jangan sekaligus nanti menempel.\", \"Setelah berwarna kecoklatan, angkat tahu masukkan kedalam tempat (kalau saya kasih kertas dulu biar minyaknya berkurang). Tahu siap disajikan! Makan dengan saus/mayo/boncabe hmm enak👍🏻❤️\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2270, 2, 'Tahu paprika teriyaki ala fe\'', 'Resep praktis Tahu paprika teriyaki ala fe\' yang bisa dicoba di rumah.', '[\"4 buah tahu cibuntu dipotong 6\", \"1 bungkus tepung Sajiku (kecil)\", \"1/2 buah paprika hijau potong2\", \"1/2 buah paprika merah potong2\", \"3 siung bawang putih geprek cincang halus\", \"1 buah bawang bombay cincang kasar\", \"1 buah tomat potong2\", \"1 lembar daun bawang potong2\", \"2 sendok makan saus teriyaki\", \"1 sendok makan kecap manis\", \"1/2 sendok teh garam\", \"1 sendok teh gula\", \"Sejumput merica bubuk\", \"1/2 gelas air\"]', '[\"Lumuri tahu potong dengan tepung sajiku lalu goreng hingga matang. Tiriskan.\", \"Tumis bawang bombay & bawang putih hingga harum. Masukkan paprika, garam, gula, merica, kecap, saus teriyaki, daun bawang, air. Tes rasa. Setelah mendidih masukkan tahu goreng. Aduk rata, masak hingga bumbu meresap & kuah kental.\", \"Matikan api. Siap disajikan hangat2 bersama nasi.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2271, 4, 'Tahu krispi saus telur asin', 'Resep Tahu krispi saus telur asin ala rumahan yang dijamin menggugah selera.', '[\"2-3 balok tahu\", \"1 bungkus tepung bumbu instan\", \"2 butir telur asin rebus\", \"5 siung bawang merah\", \"4 siung bawang putih\", \"3 biji cabe rawit\", \"secukupnya daun bawang\", \"sedikit garam dan penyedap\", \"minyak untuk menggoreng\", \"50 ml air\"]', '[\"Potong dadu tahu kemudian rendam dengan sedikit garam selama 5 menit. kemudian tiriskan. lalu goreng ke dalam minyak panas sampai krispi. cincang kasar daun bawang dan sisihkan.\", \"Hancurkan bawang merah, bawang putih dan cabe rawit sampai sedikit halus. tambahkan seujung sendok teh penyedap rasa.\", \"Kemudian haluskan telur asin yang telah direbus sampai halus. setelah itu tumis bumbu halus sampai wangi, setelah wangi masukkan adonan telur asin tumis sebentar lalu tambahkan sekitar 50ml air. masak sampai sedikit mengental.\", \"Setelah mengental, masukkan tahu krispi dan daun bawang ke dalam wajan. aduk lembut sampai tercampur rata. matikan api, sajikan dalam piring.\", \"Tahu krispi saus telur asin siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2272, 4, 'Semur Kentang, Tahu & Telur puyuh (KTT)', 'Resep Semur Kentang, Tahu & Telur puyuh (KTT) ala rumahan yang dijamin menggugah selera.', '[\"500 gram kentang(kupas, potong kotak, goreng matang)\", \"7 buah tahu putih (potong kotak, goreng matang)\", \"15 butir telur puyuh (rebus, kupas)\", \"2 sdm minyak goreng\", \"Bumbu yg dihaluskan :\", \"5 butir bawang merah\", \"3 siung bawang putih\", \"1 sdt merica bubuk\", \"2 sdt garam\", \"Bumbu tambahan :\", \"1 sdm gula pasir\", \"5 sdm kecap manis\", \"2 cm batang kayu manis\"]', '[\"Tumis bumbu halus hingga harum, tambahkan kecap manis, gula pasir & batang kayu manis. Aduk rata hingga gula & kecap terkaramelisasi, masukkan air kurleb 3 gelas. Masak sampai mendidih.\", \"Setelah mendidih masukkan berturut2 kentang goreng, tahu goreng & telur puyuh rebus. Aduk rata & masak hingga mendidih lg.\", \"Koreksi rasa, angkat & siap dihidangkan dg tambahan bawang merah goreng (aq skip krn lg kosong).\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2273, 4, 'Tahu Jeletot Jelutut', 'Buat Tahu Jeletot Jelutut yang nikmat dengan langkah-langkah mudah ini.', '[\"Bahan isian:\", \"15 tahu goreng ukuran kecil\", \"2 ons kubis (cuci bersih)\", \"2 btg worter (kupas cuci bersih)\", \"1 genggam kecambah (cuci bersih)\", \"29 buah cabai rawit\", \"Bumbu\", \"4 sium bawang putih\", \"6 siung bawang merah\", \"3 btr kemiri\", \"1 sdt garam\", \"1 sdt gula pasir\", \"1 sdt kaldu jamur\", \"Minyak secukupnya untk menumis\", \"Bahan pencelup\", \"200 grm tepung terigu\", \"3 sdm kanji\", \"3 siung bawang putih\", \"1/2 sdm garam\", \"1 sdt kaldu jamur\", \"3 btr kemiri\", \"1 btg daun bawang\", \"secukupnya Air matang\"]', '[\"Tahu yang sudah digoreng belah tengahnya,sisihkan\", \"Bahan isian : Sebua iris tipis\\\" dan sisihkan, haluskan bumbu. Panaskan minyak tumis semua jadi satu, rasakan. Sisihkan\", \"Bahan pencelup: haluskan bawang kemiri,masukkan dalm wadah campur jadi satu semua bahan, rasakan.\", \"Masukkan isian dalm tahu sampai selesai, dan masukkan pencelup\", \"Siapkan minyak goreng untuk menggoreng,api agak besar ya, bila sudah panas masukkan siap goreng smpai kekuningan. angkat tiriskan\", \"Sajikan, silahkan mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2274, 4, 'Tahu campur seger', 'Resep praktis Tahu campur seger yang bisa dicoba di rumah.', '[\"2 buah tahu cina\", \"1 ikat selada\", \"1 ons toge\", \"bawang goreng\", \"seledri\", \"1 buah timun\", \"bumbu kuah\", \"15 butir caabe rawit\", \"2 siung bawang putih\", \"Secukupnya asam jawa\", \"Secukupnya gula merah\", \"garam\", \"gula\"]', '[\"Ulek semua bumbu halus...masukkan ke dalam air 1 liter..\", \"Masukan gula dan garm...tes rasa..masak hingga mndidih dan agak pekat...matikn api\", \"Rebus toge sebentar aja, susun si piring,,tahu goreng,selada iris,,timun iris,,bawang goreng,seledri,,lalu siram dngn kuah,,,siap di nikmti\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2275, 3, 'Rica\"CEKER+TAHU', 'Resep praktis Rica\"CEKER+TAHU yang bisa dicoba di rumah.', '[\"1/4 kg ceker ayam\", \"1 bungkus tahu putih\", \"2 Ikat Kemangi\", \"\\\"Bumbu halus\\\"\", \"4 Bawang putih\", \"6 Bawang merah\", \"10 cabai warna orange\", \"4 cabai merah\", \"2 butir miri\", \"1 sdt garam\", \"1 sdt micin\", \"1 bungkus kecap bangau\", \"Jahe,lengkus geprek\", \"Daun salam\", \"Daun jeruk\", \"Gula putih sckupnya\"]', '[\"Cuci bersih ceker lalu rebus,,,potong dadu tahu putih lalu goreng\", \"Haluskan semua bumbu...lalu tumis bsrta daun salam,daun jeruk,jahe,lengkuas sampai harum\", \"Masukan ceker yg sdh drbus dan tahu tadi....lalu osreng smpai bumbu campur....kasih air 2-3gelas lalu masukan kecap koreksi rasanya....biarkan air sampai mnyusut lalu msukan kemangi sampai layu...osreng bntar lalu angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2276, 3, 'Tauge Tahu Tumis', 'Resep praktis Tauge Tahu Tumis yang bisa dicoba di rumah.', '[\"Bahan Bahan:\", \"200 gr tauge (me: buang akarnya)\", \"3 bh tahu\", \"2 siung bawang merah\", \"Secukupnya paprika merah (bs dganti dg cabe merah)\", \"Secukupnya paprika ijo (bs dganti dg cabe ijo)\", \"5 sdm kecap pedas (biasa yg ada biji cabenya itu)\", \"Secukupnya garam\", \"Secukupnya air\", \"Secukupnya minyak goreng\"]', '[\"Potong potong tahu (sesuai selera). Lalu goreng (bs dgoreng setengah matang atau kering, sesuai selera). Selesai d goreng, lalu sisihkan.\", \"Panaskan minyak goreng. Masukkan bawang merah yg sudah diiris. Aduk aduk sampai layu, masukkan tauge. Aduk aduk. Masukkan tahunyg sudah dgoreng tadi.\", \"Tambahkan kecap pedas & garam. Lalu masukkan air. Aduk aduk & koreksi rasa. Terakhir masukkan paprika merah & ijo. Sajikan ☺️\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2277, 4, 'Oseng tahu sirih sosis', 'Buat Oseng tahu sirih sosis yang nikmat dengan langkah-langkah mudah ini.', '[\"2 bks tahu sirih\", \"2 bks sosis\", \"2 bh cabe merah\", \"Cengek (jika suka pedas)\", \"3 bh bawang merah\", \"2 bh bawang putih\", \"1 bh tomat kecil\", \"1 sachet kecap bango\", \"1 sdm saos tiram\", \"Gula sckpnya\", \"Penyedap sckpnya\"]', '[\"Siapkan tahu yg sdh di cuci..siapkan jg bumbu yg sdh di rajang..\", \"Tumis bumbu sampe harum masukan tahu dan sosis aduk rata masukan kecap,saos tiram..masak sampe matang..angkat\", \"Tarra jadi deh..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2278, 4, 'Tahu walik isi aci', 'Nikmati kelezatan Tahu walik isi aci dengan resep sederhana ini.', '[\"1 bungkus tahu matang(biasanya 1 bungkus isi 10)\", \"5 sdm tepung kanji\", \"2 sdm tepung terigu\", \"2 batang daun bawang\", \"1 butir telur\", \"Secukupnya daun seledri\", \"Secukupnya penyedap (ak pake royko ayam)\", \"Garam,merica bubuk\", \"Secukupnya air\"]', '[\"Potong tahu menjadi 2 bagian,potongnya nyerong agar bentuknya segitiga\", \"Keruk isi tahu kemudian balik tahu\", \"Ulek isian tahu tadi supaya hasile halus...soalnya dulu pernah buat tanpa diuleg hasil isian kasar\", \"Iris lembut daun seledri dan daun bawang\", \"Masukan tepung kanji,terigu,isi tahu yg sdh diuleg irisan daun seledri dan bawang dan masukan semua bumbu\", \"Masukan telur kemudian kasih air sedikit sambil diaduk pake sendok\", \"Adonan jgn terlalu keras dan jangan terlalu lembek..dikira2 saja ngasih airnya\", \"Kemudian masukan adonan kedalam tahu\", \"Goreng tahu diminyak yg panas dan agak banyak supaya tahu terendam...jika sdh agak kecokatan kecilkan api supaya isian aci bisa matang\", \"Tahu walik enak dinikmati pake lalapan cabe hijau ataupun saos sambel\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2279, 3, 'Tahu santan simple', 'Tahu santan simple - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"1 papan Tahu malang\", \"1 sachet Santan kara\", \"4 siung Bawang merah  lalu cincang\", \"3 siung Bawang putih  lalu cincang\", \"5 biji Cabe rawit\", \"seruas Kunyit\", \"1 sdt Garem\", \"2 sdt Gula\", \"200 ml Air\"]', '[\"Tumis bawang merah dan bawang putih. Masukkan kunyit tunggu harum\", \"Masukkan air tambah santen kasi garem gula dan cabe rawit\", \"Masukkan tahu yg udah dipotong\", \"Tunggu sampe bumbu meresap koreksi rasa\", \"Selesaai. Alhamdulillah.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2280, 2, 'Sayur Bayam Tahu', 'Sayur Bayam Tahu - olahan tahu yang lezat dan bergizi.', '[\"1 ikat bayam\", \"2 buah tahu\", \"secukupnya Tauge\", \"Pipilan Jagung\", \"3 siung bawang merah, iris tipis\", \"2 siung bawang putih, iris tipis\", \"secukupnya Gula dan garam\", \"secukupnya Temukunci\"]', '[\"Bersihkan tauge, potong tahu, bersihkan bayam\", \"Didihkan air, tambahkan bawang merah, bawang putih dan temukunci\", \"Masukkan jagung pipil, tunggu hingga agak lunak lalu masukkan tahu.\", \"Masukkan tauge, tunggu beberapa menit. Tambahkan gula dan garam. Koreksi rasa\", \"Pastikan bayam dimasukkan terakhir dan tidak dimasak terlalu lama. Masakan siap dihidangkan :)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2281, 3, 'Tahu lada hitam simple', 'Resep praktis Tahu lada hitam simple yang bisa dicoba di rumah.', '[\"2 kotak tahu sutra\", \"2 siung bawang putih, geprek cincang\", \"1/2 bawang bombay cincang\", \"1 sachet saori lada hitam\", \"50 ml air\", \"secukupnya Minyak goreng\"]', '[\"Potong kotak tahu, goreng, sisihkan\", \"Tumis bawang putih dan bawang bombay sampai harum,masukkan tahu, saus lada hitam, air, masak dengan api kecil sampai bumbu meresap,sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2282, 4, 'Tahu Goreng isi Sayur', 'Resep praktis Tahu Goreng isi Sayur yang bisa dicoba di rumah.', '[\"2 buah tahu cina\", \"2 buah wortel\", \"1 batang besar daun bawang\", \"4 siung bawang merah\", \"2 siung bawang putih\", \"1/2 sdt merica\", \"secukupnya Garam\", \"1 butir telur\", \"Minyak untuk menggoreng\"]', '[\"Haluskan bawang merah dan bawang putih\", \"Hancurkan tahu didalam wadah sisihkan\", \"Iris kotak wortel (sesuai selera) dan daun bawang campurkan dengan tahu yg sudah di lumatkan.\", \"Campur bumbu halus,merica,wortel dan daun bawang garam kedalam tahu aduk rata\", \"Masukkan telur dan langsung aduk rata dengan adonan tahu yg dilumatkan beserta sayuran\", \"Tuang adonan ke dalam piring tahan panas dan kukus kurang lebih 15 menit\", \"Setelah di kukus angkat, diamkan sampai dingin potong potong tahu sesuai selera,goreng kedalam minyak panas dan sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2283, 3, 'Kikil tahu mercon😁', 'Nikmati kelezatan Kikil tahu mercon😁 dengan resep sederhana ini.', '[\"2 bks kikil rebus\", \"1 kotak tahu potong2 goreng\", \"1 ons cabe rawit campur\", \"5 buah cabe keriting\", \"4 siung bawang putih\", \"4 siung bawang merah\", \"2 butir kemiri\", \"1 lembar daun salam\", \"Gula garam penyedap\", \"secukupnya Kecap manis\"]', '[\"Uleg bawang kemiri n cabe kemudian tumis sampe wangi\", \"Masukan kikil beri segelas air biarkan air agak surut masukan tahu goreng beri daun salam aduk rata\", \"Beri gula garam penyedap n kecap manis tes rasa\", \"Siap disantap\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2284, 4, 'Tumis Tahu Brokoli', 'Resep Tumis Tahu Brokoli ala rumahan yang dijamin menggugah selera.', '[\"3 buah tahu putih (potong kecil)\", \"1 bonggol brokoli (potong kecil)\", \"5 buah cabe merah kriting (potong serong)\", \"6 siung bawang merah (iris, cincang halus)\", \"3 siung bawang putih (geprek lalu cingcang halus)\", \"1 sdm saus tiram\", \"1/2 sdt lada bubuk\", \"secukupnya Kecap\", \"secukupnya Gula\", \"secukupnya Garam\", \"secukupnya Air\"]', '[\"Rendam brokoli yang sudah dipotong dalam air yang diberi garam sekitar 5 menit. Setelah itu bilas dengan air biasa. Sisihkan.\", \"Rendam potongan tahu di air garam sekitar 5 menit, lalu goreng sampai agak berkulit tp jangan terlalu kering. Sisihkan.\", \"Tumis cabe, bawang merah dan bawang putih sampai harum dan agak kecoklatan.\", \"Masukkan sedikit air, lada, saus tiram, gula, garam, kecap. Koreksi rasa.\", \"Masukkan brokoli, tumis sebentar tapi jangan sampai terlalu layu.\", \"Masukkan tahu. Tambah sedikit air, koreksi rasa sekali lagi. Jika sudah pas, matikan kompor. Sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2285, 2, 'Sapo Tahu', 'Buat Sapo Tahu yang nikmat dengan langkah-langkah mudah ini.', '[\"1 bungkus tahu sutra/tahu telur, potong2, balur terigu & goreng\", \"100 gr udang kupas\", \"5 buah bakso ikan, iris2\", \"1 buah wortel besar, potong2\", \"1 ikat sawi hijau, potong2\", \"1 kantong (100 gr) jamur tiram, rendam air panas & tiriskan\", \"1 btg daun bawang, iris2\", \"1 siung bawang putih, geprek\", \"1 siung bawang bombay, iris2\", \"1 sdm saos tiram\", \"Sedikit minyak wijen\", \"Secukupnya gula pasir, garam, lada & kaldu bubuk\", \"Sedikit air\", \"Sedikit minyak utk menumis\"]', '[\"Tumis bawang putih & bawang bombay hingga harum & layu. Tambahkan udang, potongan bakso ikan & wortel, masak sampai wortel agak layu.\", \"Masukan potongan sawi & jamur tiram. Tambahkan jg saos tiram & minyak wijen. Beri sedikit air.\", \"Beri gula pasir, garam, lada & kaldu bubuk. Koreksi rasa. Terakhir sblm matikan api, masukan potongan daun bawang & tahu. Matikan api, angkat & sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2286, 4, 'Sayur Lodeh Tahu', 'Sayur Lodeh Tahu - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"6 biji tahu coklat\", \"Bumbu halus :\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"3 buah cabe rawit\", \"2 cm kunyit\", \"1 sdt ketumbar\", \"Bumbu pelengkap\", \"3 cm Lengkuas (geprek)\", \"3 lembar daun salam\", \"2 lembar daun jeruk\", \"1/2 sdt garam\", \"1/4 sdt gula\", \"1/4 sdt lada bubuk\", \"1/2 sdt masako rasa ayam\", \"1 bks santan kara\", \"secukupnya Air\"]', '[\"Tumis bumbu halus sampai harum, masukkan bumbu pelengkap dan santan. Aduk sampai rata\", \"Tambahkan air secukupnya, lalu masukkan tahu. Aduk perlahan agar santan tidak pecah\", \"Setelah mendidih, koreksi rasa dan lodeh tahu siap dihidangkan. Happy Cooking\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2287, 4, 'Perkedel tahu simpel', 'Resep Perkedel tahu simpel ala rumahan yang dijamin menggugah selera.', '[\"10 potong tahu putih, haluskan\", \"1 batang daun bawang iris tipis\", \"1 btr telur kocok\", \"secukupnya Garam\", \"secukupnya Gula pasir\", \"Bumbu halus:\", \"4 bh bawang merah\", \"3 bh bawang putih\", \"1/2 sdt merica\", \"Minyak untuk menggoreng\"]', '[\"Masukkan bumbu halus ke dalam tahu yang sudah dihaluskan. Tambahkan telur+daun bawang+garam+gula pasir. Aduk rata\", \"Siapkan wajan panaskan minyak goreng, setelah panas masukan adonan tahu dg cara dikepal2 dg dua tangan agar lebih padat lalu goreng. (Sambil dikepal2 lgsg goreng ya)\", \"Goreng sampai kecoklatan dg api sedang\", \"Silakan mencoba 🤗🤗🤗🤗\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2288, 2, 'Sayur Oyong Sopo tahu', 'Resep praktis Sayur Oyong Sopo tahu yang bisa dicoba di rumah.', '[\"3 buah sayur oyong, kupas, potong2\", \"4 ekor udang\", \"1 bungkus sopo tahu (rasa sayur), digoreng/tidak (sesuai selera)\", \"1 buah tomat ukuran kecil, potong2\", \"Secukupnya garam\", \"Bumbu halus\", \"3 siung bawang merah\", \"2 siung bawang putih\"]', '[\"Tumis bumbu yang udah dihaluskan, masukkan udang, setelah wangi, masukkan sayur oyong, aduk sebentar tambahkan air secukupnya\", \"Masukkan tomat yang udah dipotong2. aduk sebentar, lalu masukkan sopo tahu, masak hingga matang, angkat dan sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2289, 4, 'Tumis sayur asin cah baso dan tahu goreng', 'Resep Tumis sayur asin cah baso dan tahu goreng ala rumahan yang dijamin menggugah selera.', '[\"4 ikat sayur asin / sawi pait, iris2\", \"6 siung bawang putih, iris tipis\", \"10 buah bakso sapi, iris2\", \"5 buah tahu putih kotak kecil, belah 4, goreng stenga matang\", \"4 buah cabe merah, iris serong\", \"Secukupnya air dan minyak goreng\", \"Secukupnya garam dan penyedap\"]', '[\"Panaskan minyak, masukkan bawang putih dan cabe, tumis sampai harum. Tambahkan potongan bakso. Tumis sampai bakso agak matang. Baru masukkan irisan sayur asinnya. Beri garam dan penyedap. Aduk beberapa saat dan bumbu rata. Kemudian tambahkan air sesuai selera. Tunggu mendidih baru masukkan tahu yg sdh digoreng. Tunggu mendidih kembali atau sayur matang sesuai tekstur yg diinginkan (agak garing / agak layu). Tes rasa, jika sudah sesuai, angkat dan sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2290, 2, 'Tahu kemangi ungkep', 'Cara membuat Tahu kemangi ungkep yang enak dan praktis untuk keluarga.', '[\"10 bj tahu putih mentah\", \"2 siung bawang putih\", \"3 siung bawang merah\", \"3 bj cabe rawit\", \"1 btr telor\", \"1 bj tomat\", \"1 iket kemangi\", \"Masako\", \"Garam\", \"Trasi\"]', '[\"Rajang bumbu2\", \"Hancurkan tahu\", \"Campur semua bumbu jadi satu\", \"Masukkan kemangi\", \"Ungkep di wajan sampe air menyusut\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2291, 4, 'Sosis tahu homemade', 'Nikmati kelezatan Sosis tahu homemade dengan resep sederhana ini.', '[\"500 gr tahu putih,haluskan\", \"250 gr wortel,parut dg parutan keju\", \"3 butir telur size besar\", \"3 siung bawang putih,haluskan\", \"1 sdt lada bubuk\", \"secukupnya Garam\", \"secukupnya Penyedap\", \"4 sdm tepung terigu\"]', '[\"Campur jadi satu semua bahan dan aduk sampai tercampur rata.\", \"Tes rasa..kalo sudah sesuai selera lalu masukkan ke plastik ukuran buat es stik lalu ikat\", \"Lalu masukkan ke dalam kukusan yg sudah dipanaskan sebelumnya.kukus selama kurleb 20menit/sampai terasa kencang dg plastiknya\", \"Setelah matang angkat n biarkan dingin\", \"Setelah dingin buka plastiknya n jadi deh siap goreng..\", \"Untuk lebih pulennya lagi simpan dulu dalam lemari es sebelum digoreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2292, 4, 'Nugget Tahu Crispy', 'Resep praktis Nugget Tahu Crispy yang bisa dicoba di rumah.', '[\"30 potong tahu putih kecil\", \"1,5 ons tepung terigu\", \"3 siung bawang merah\", \"3 siung bawang putih\", \"1 butir telur\", \"Secukupnya garam\", \"Secukupnya penyedap\"]', '[\"Hancurkan tahu terlebih dahulu.\", \"Ulek bawang merah dan bawang putih sampai halus kemudian campurkan dengan tahu. Aduk rata.\", \"Tambahkan telur, tepung, garam dan penyedap. Aduk sampai rata.\", \"Tuang ke dalam cetakan.\", \"Kemudian kukus kurang lebih 25 menit.\", \"Kemudian angkat dan dinginkan.\", \"Iris sesuai selera.\", \"Kemudian buat adonan tepung terigu untuk celupan.\", \"Kemudian baluri dengan tepung roti sampai permukaannya tertutup rata.\", \"Goreng sampai kecoklatan. Angkat dan tiriskan.\", \"Nikmat disajikan saat hangat. Selamat mencoba =)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2293, 4, 'Tahu crispy pedas', 'Resep Tahu crispy pedas ala rumahan yang dijamin menggugah selera.', '[\"5 tahu putih,di potong dadu\", \"150 gram tepung bumbu\", \"30 gram tepung beras\", \"2 sdm bubuk cabe\", \"3 bawang putih\", \"secukupnya Garam\"]', '[\"Haluskan bawang putih dan garam beri air dikit campur dengan tahu sisihkan\", \"Campurkan tepung beras,tepung bumbu,cabe bubuk aduk rata,gulingkan tahu,goreng dengan minyak panas sampai ke coklatan siap di sajikan di cocol dengan saos sambal\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2294, 3, 'Tahu telur puyuh saos teriyaki #resep akhir bulan', 'Sajian Tahu telur puyuh saos teriyaki #resep akhir bulan yang praktis dan lezat untuk dinikmati bersama.', '[\"secukupnya Telur puyuh mentah\", \"Tahu putih mentah\", \"Baso sapi\", \"Bumbu:\", \"1 sdm Saos teriyaki\", \"4 siung Bawang merah\", \"3 siung Bawang putih\", \"secukupnya Garam dan gula\", \"1 sdm Royco ayam\", \"1 bh Bawang bombay\", \"2 sdm Kecap manis\"]', '[\"Rebus telur puyuh, kupas,dan goreng\", \"Tahu Potong2 dadu, goreng setengah matang\", \"Baso sapi, potong jadi dua, goreng\", \"Bawang merah, bawang putih, bawang bombay di iris tipis, lalu goreng\", \"Masukan baso, tahu, dn telur puyuh\", \"Tambahkan air secukupnya\", \"Masukan saos teriyaki, kecap manis, garam, gula,royco rasa ayam\", \"Masak smp meresap\", \"Sajikan hangat2...\", \"Selamat mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2295, 2, '004 orek tahu warna warni', 'Resep praktis 004 orek tahu warna warni yang bisa dicoba di rumah.', '[\"10 buah tahu kuning (uk. kecil)\", \"1 butir telur\", \"3 buah baso (uk. kecil) (optional)\", \"3 siung bawang merah\", \"3 siung bawang putih\", \"1 buah cabe merah besar\", \"1/2 buah tomat\", \"3 batang sawi\", \"Penyedap rasa\", \"Gula pasir\", \"Lada bubuk\", \"Minyak goreng\"]', '[\"Siapkan bahan². Baso saya potong kecil², supaya cepat matang. Telur di orek, lalu sisihkan\", \"Untuk tahu, saya haluskan pake tangan secukupnya, supaya tidak terlalu lembut.\", \"Tumis, bawang merah dan bawang putih terlebih dahulu, menyusul cabe merah, lalu tomat, setelah tercium wangi, masukkan baso, telur, lalu sawi.\", \"Setelah sawi layu, masukkan tahu. Tambahkan penyedap, lada bubuk dan gula pasir. Koreksi rasa. Setelah kadar air menyusut, siap di sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2296, 4, 'Tumis Tahu Udang Rebon', 'Tumis Tahu Udang Rebon - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"8 buah tahu\", \"1,5 sdm udang rebon\", \"4 siung bawang putih\", \"5 siung bawang merah\", \"1 buah bawang bombay kecil\", \"5 buah cabai rawit merah\", \"3 buah cabai hijau besar\", \"2 lembar daun salam\", \"1 sdm saus tiram\", \"150 ml air\", \"secukupnya Garam\", \"secukupnya Kaldu ayam\", \"secukupnya Gula merah\"]', '[\"Cuci bersih dan iris bawang merah, bawang putih, bawang bombay, cabai rawit, dan cabai hijau. Lalu potong tahu menjadi 6 bagian\", \"Rendam udang rebon dengan air hangat lalu tiriskan\", \"Tumis bawang merah, putih dan bombay sampai harum.\", \"Masukan udang rebon yang sudah ditiriskan. Masak hingga harum\", \"Masukan cabai rawit dan cabai hijau dan salam.\", \"Lalu masukan air biarkan hingga mendidih. Setelah itu masukan saus tiram, garam, kaldu, dan gula.\", \"Terakhir masukan tahu dan diamkan hingga sedikit saat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2297, 2, 'Sawi Tahu Kuah Sederhana', 'Resep praktis Sawi Tahu Kuah Sederhana yang bisa dicoba di rumah.', '[\"2 ikat Sawi hijau\", \"3 buah tahu putih\", \"3 gelas air\", \"Bumbu :\", \"7 buah cabe rawit\", \"2 siung bawang putih\", \"4 siung bawang merah\", \"2 buah tomat\", \"1/2 sendok garam halus\", \"1/2 bungkus penyedap rasa\", \"Secukupnya Minyak goreng\"]', '[\"Potong2 sawi hijau sesuai selera lalu cuci bersih, tiriskan.\", \"Potong tahu kecil2 memanjang, atau sesuai selera (jgn lupa cuci tahunya sebelum dipotong) 😀\", \"Iris bawang merah dan tomat sisihkan\", \"Tumbuk cabe rawit bersama garam sampai halus kemudian masukkan bawang putih lalu tumbuk kembali dan terakhir masukkan tomat yang sudab di iris tadi, sisihkan.\", \"Panaskan minyak, masukkan bawang merah, tumis sampai harum dan setengah kering, masukkan bumbu yg sudah di haluskan tadi, goreng sebentar lalu tuangkan air dan biarkan mendidih.\", \"Terakhir masukkan tahu dan sawi hijau biarkan hingga airnya mendidih kembali, masukkan penyedap rasa, aduk2 biarkan sebentar, lalu angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2298, 4, 'Toge Goreng Tahu', 'Cara membuat Toge Goreng Tahu yang enak dan praktis untuk keluarga.', '[\"1/2 kg toge\", \"5 buah tahu kuning\", \"2 kantong tauco seperti es mambo\", \"1 potong oncom\", \"1 batang daun bawang\", \"bumbu\", \"5 cabe merah\", \"10 cabe rawit merah\", \"20 cabe rawit hijau (tidak diulek)\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"3 lembar 2 salam\", \"Garam\", \"Penyedap rasa (saya ga pakai)\", \"Gula merah (sesuai selera)\", \"Gula putih (sesuai selera)\", \"secukupnya Kecap Bango\", \"Minyak goreng untuk menumis\", \"700 ml air\"]', '[\"Potong tahu dan goreng setengah mateng\", \"Ulek oncom dan tauco, taro di wadah\", \"Ulek cabe merah, cabe rawit merah, bawang merah, bawang putih. Lalu tumis sampai harum\", \"Setelah harum tuangkan ulekan oncom dan tauco, masukan cabe rawit hijau bulat, daun salam, garam, gula, penyedap, kecap, tahu goreng dan air\", \"Setelah mendidih dan kental masukan toge dan daun bawang sampai matang. Koreksi rasa\", \"Toge goreng tahu siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2299, 2, 'Perkedel tahu sederhana', 'Resep Perkedel tahu sederhana yang lezat dan mudah dibuat di rumah.', '[\"10 biji tahu putih ukuran sedang\", \"1 buah wortel\", \"1 btg daun bawang\", \"1 buah telor\", \"5 siung bawang putih\", \"1/4 sdt lada bubuk\", \"Secukupnya garam\", \"Penyedap rasa\", \"Minyak goreng\"]', '[\"Taruh tahu dlm wadah...kmudian remas2 smpe halus.\", \"Uleg bawang putih dan garam.\", \"Iris wortel kecil2..iris jg daun bawang..masukkan kedalam wadah yg berisi tahu..tambahkan bumbu..penyedap rasa..koreksi rasa lalu tmbahkan telor..\", \"Aduk2 kemudian bentuk bulat2 lalu pipihkan..\", \"Panaskan minyak...... Goreng smpe agk kecoklatan.. Angkat. Hidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2300, 3, '5.Tahu brokoli pedas manis', 'Resep praktis 5.Tahu brokoli pedas manis yang bisa dicoba di rumah.', '[\"1 bungkus tahu putih (isi 10)potong kecil rendam di air garam\", \"2 kepal brokoli (iris rendam di air garam)\", \"1 sdm saos tiram\", \"Secukupnya kecap manis, gula merah (sisir tipis)\", \"Secukupnya garam,lada bubuk\", \"Bawang goreng\", \"Bumbu :\", \"1/2 bombay (iris)\", \"3 siung bawang merah (iris tipis)\", \"3 siung bawang putih (geprek cacah)\", \"18 cabe rawit\", \"2 cabe merah dan hijau\", \"Daun salam + daun jeruk\"]', '[\"Goreng tahu yg sudah direndam air garam (jangan sampai kering).angkat sisihkan\", \"Tumis bahan bumbu yg sudah diiris sampai harum, tambahkan saus tiram,kecap manis, gula merah,lada bubuk,2sdm air. Aduk\", \"Masukkan tahu,brokoli dan garam aduk rata, kecilkan api. Biarkan sampai air hampir habis.\", \"Tes rasa.. Kalau sudah pas lalu pindahkan ke piring saji dan taburi bawang goreng, sajikan 😄😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2301, 4, 'Tahu tek Surabaya', 'Nikmati kelezatan Tahu tek Surabaya dengan resep sederhana ini.', '[\"Bahan saos\", \"4 siung bawang putih\", \"3 sdm petis\", \"6 cabai rawit pedas (sesuai selera)\", \"2 sdm gula merah\", \"Secukupnya terasi\", \"Secukupnya garam\", \"2 sdm air putih\", \"Bahan pelengkap\", \"Tahu pong\", \"Kol\", \"Gorengan (saya buat sendiri)\", \"Lontong\", \"Kerupuk\", \"Telur ceplok\"]', '[\"Ulek bawang putih hingga halus, lalu kemudian cabai, gula merah, garam, terasi dan petis ulek hingga bercampur menjadi satu jangan lupa tes rasa. Sudah pas tambahkan air lalu di aduk\", \"Sajikan dengan pelengkap yang sudah di sediakan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2302, 2, 'Bakwan tahu teri', 'Resep Bakwan tahu teri yang lezat dan mudah dibuat di rumah.', '[\"1 buah tahu uk sedang\", \"3 sdm teri medan\", \"1 butir telur\", \"Secukupnya tepung terigu\", \"1 siung bawang putih (haluskan)\", \"1/2 sdt lada bubuk\", \"1/4 sdt ketumbar bubuk\", \"Secukupnya garam\", \"Minyak untuk menggoreng\"]', '[\"Hancurkan tahu, campurkan dengang teri, tepung terigu, telur, dan semua bumbu kemudian aduk rata.\", \"Panaskan minyak, ambil 1 sdm adonan goreng dalam minyak panas sampai matang (kuning kecoklatan).\", \"Setelah matang, siap untuk disajikan..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2303, 2, 'Tahu bulat simple', 'Kreasi tahu nikmat: Tahu bulat simple untuk variasi menu harian.', '[\"Sepotong tahu\", \"1 butir telur\", \"1/2 sdm baking powder\", \"1/2 sdm baking soda\", \"1 sdt garam\", \"1 sdm penyedap\", \"1 buah sosis utk isian (potong kecil)\", \"Secukupnya minyak utk menggoreng\"]', '[\"Siapkan bahan2\", \"Peras tahu dgn kain hingga kering\", \"Masukkan tahu, telur, baking powder, baking soda, penyedap dan garam aduk rata\", \"Setelah itu bulat2kan bila perlu isi dgn sosis\", \"Goreng dgn minyak panas\", \"Setelah matang sajikan dgn saus 😉\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2304, 3, 'Tumis Toge Tahu', 'Tumis Toge Tahu - olahan tahu yang lezat dan bergizi.', '[\"1 ons Toge kira kira\", \"3 kotak Tahu putih kecil\", \"Bawang merah putih\", \"Cabe merah\", \"Gula pasir + Penyedap (me : indofood magic)\"]', '[\"Goreng tahu. sebentar saja tdk usah terlalu kering. asalkan berkulit saja\", \"Iris bawang merah bawang putih dan cabe\", \"Panaskan minyak. tumis bawang merah bawang putih.. tunggu layu masukan cabe merah tunggu sdkt layu.. masukan toge.. aduk aduk.. biarkan setengah matang masukan tahu gula dan penyedap.\", \"Tes rasa.. tdk perlu dikasih air. biar teksturnya krauk krauk gak lembek.\", \"Siap di sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2305, 3, 'Pepes Tahu', 'Buat Pepes Tahu yang nikmat dengan langkah-langkah mudah ini.', '[\"2 buah Tahu putih\", \"Lamtoro (pete cina)\", \"Daun bawang merah\", \"2 buah Tomat (harusnnya ijo, tp aku adanya yg merah 😊)\", \"Kelapa muda (aku pake 1/4)\", \"2 buah Bawang merah\", \"3 buah Bawang putih\", \"5 buah Cabe rawit\", \"4 buah Cabe merah besar\", \"Lengkuas\", \"Garam,gula,ketumbar,(royco sesuai selera)\", \"Daun pisang\"]', '[\"Potong daun bawang dan tomat, cuci bersih dengan lamtoro\", \"Haluskan kan tahu, lalu campur dengan bahan di atas campur juga kelapa parutnya. Aduk rata,\", \"Blender bawang merah, putih, cabai, lengkuas,garam, gula dan ketumbar bubuk.\", \"Tuang bumbu dengan bahan2, aduk sampai rata, cek rasa lalu bungkus dengan daun pisang.\", \"Kukus sekitar 5-8 menit. Dan pepes tahu siap di santap, 😊😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2306, 3, 'Gulai Daging Tahu', 'Resep Gulai Daging Tahu ala rumahan yang dijamin menggugah selera.', '[\"10 potong tahu putih di goreng\", \"1/2 kg daging\", \"500 ml santan kental\", \"4 lembar Daun Salam\", \"5 lembar Daun jeruk\", \"minyak goreng secukupnya untuk menumis\", \"secukupnya Garam\", \"penyedap rasa\", \"💥bumbu halus:\", \"5 buah cabe merah besar\", \"5 buah lombok keriting\", \"5 siung bawang putih\", \"7 siung bawang merah\", \"kunyit seruas jari\", \"jahe seruas jari\", \"1 sdt jintan\", \"1 sdt ketumbar\", \"1/2 sdt pala\", \"1/2 sdt lada\"]', '[\"Rebus daging hingga empuk dan air menyusut\", \"Haluskan bumbu dan tumis hingga harum\", \"Masukan bumbu ke dalam rebusan daging yg telah empuk\", \"Tambahkan air santan perasan ke dua dan masukan daun salam, daun jeruk. didihkan.\", \"Masukan santan pertama. aduk2 agar santan tidak pecah. tambahkan garam, gula, dan penyedap rasa.\", \"Koreksi rasa, masukan tahu goreng yg sudah di belah 2 membentuk segitiga. rebus sebentar. matikan api. gulai siap di sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2307, 2, 'Tahu Isi a.k.a Tahu Susur Endesss', 'Kreasi tahu nikmat: Tahu Isi a.k.a Tahu Susur Endesss untuk variasi menu harian.', '[\"20 buah tahu cokelat\", \"minyak secukupnya untuk menggoreng\", \"bahan pencelup :\", \"150 gram tepung terigu\", \"secukupnya merica bubuk\", \"secukupnya garam\", \"secukupnya air\", \"bahan isian :\", \"4 batang wortel, kupas kulit dan iris panjang tipis seperti korek api\", \"200 gram toge\", \"bumbu di haluskan :\", \"2 siung bawang putih\", \"1 sdt merica bubuk\", \"secukupnya garam\"]', '[\"Cuci bersih tahu dan belah sedikit tengahnya agar isian bisa masuk\", \"Tumis bumbu halus hingga harum, masukkan toge dan wortel. masak hingga setengah empuk, cek rasa, angkat\", \"Masukkan isiin sebanyak 1 sendok ke setiap tahu, padatkan agar tidak mudah jatuh adonan isian\", \"Semua bahan pencelup campurkan ke dalam mangkok. aduk rata. cairkan dengan air hingga mendapat kekentalan yang pas, lalu masukkan tahu, ratakan tahu dengan adonan sehingga semua tertutup bahan pencelup\", \"Panaskan minyak, goreng tahu hingga kuning keemasan. angkat dan tiriskan. selamat mencoba yaa :*\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2308, 2, 'Tumis buncis tahu', 'Buat Tumis buncis tahu yang nikmat dengan langkah-langkah mudah ini.', '[\"3 siung bawang merah\", \"2 siung bawang merah\", \"1 cm laos\", \"2 lembar daun salam\", \"2 sdm minyak goreng\", \"3 buah tahu putih (potong dadu)\", \"250 gram buncis muda\"]', '[\"Panaskan minyak, tumis bawang merah dan bawang putih yang sudah di potong halus.. tumis hingga harum, tambahkan laos dan daun salam.. aduk rata\", \"Masukkan buncis yang telah di potong miring beserta tahu.. aduk dan tambahkan sedikit air..\", \"Tambahkan gula dan garam sesuai selera.. aduk dan tunggu hingga buncis empuk.. kemudian angkat..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2309, 4, 'Martabak Tahu Seuhah (pedas)', 'Martabak Tahu Seuhah (pedas) - olahan tahu yang lezat dan bergizi.', '[\"6 buah tahu putih (peras buang airnya)\", \"5 butir telor ayam\", \"2 buah sosis\", \"Bawang daun\", \"Wortel\", \"Kulit lumpia\", \"Bumbu halus:\", \"Merica, bawang putih, bawang merah, cabe rawit, garam, masako\"]', '[\"Iris bawang daun, wortel, sosis kecil2\", \"Campur semua bahan, dan bumbu halus aduk rata\", \"Bungkus dg kulit lumpia\", \"Goreng hingga kekuningan. Sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2310, 4, 'Tumis taoge tahu', 'Resep Tumis taoge tahu yang lezat dan mudah dibuat di rumah.', '[\"1/2 kg Taoge Besar\", \"4 Biji Tahu\", \"1 biji Tomat\", \"6 Biji Bawang Merah di iris\", \"3 Biji Bawang Putih di iris\", \"2 Biji Cabe Merah\", \"1/2 Sdt Terasi\"]', '[\"Cuci bersih taoge dan tahu potong kotak kecil\", \"Goreng tahu setengah matang. Tiriskan\", \"Tumis bawang merah, bawang putih, cabai, terasi dan tomat sampai harum di minyak panas\", \"Masukan tahu dan toge ke dalam tumisan bumbu. Aduk rata.\", \"Tambahkan air secukupnya dan berikan garam dan penyedap secukupnya... Aduk rata\", \"Sajikan. Selamat mencoba 🙏\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2311, 2, 'Tahu Tauco', 'Tahu Tauco - olahan tahu yang lezat dan bergizi.', '[\"3 buah tahu putih besar belah segitiga\", \"1 bungkus tauco/ secukupnya\", \"4 siung bawang merah iris\", \"3 siung bawang hijau iris\", \"3 buah cabe ijo iris\", \"3 buah cabe merah iris\", \"2 lmbr daun salam\", \"1 sereh, geprek\", \"1 ruas lengkuas, geprek\", \"Kecap manis\", \"150 ml air\", \"secukupnya Gula, garam, penyedap rasa\"]', '[\"Tahu putih yg sdh dibelah segitiga goreng setengah matang, tiriskan\", \"Tumis duo bawang sampai harum, salam, sereh, lengkuas, kemudian masukkan duo cabe tumis setengah layu\", \"Masukkan tauco, beri air kemudian tahu aduk rata\", \"Kasih kecap, gula, garam, penyedap rasa aduk rata. Biarkan sampai air menyusut dan bumbu meresap\", \"Koreksi rasa lalu sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2312, 4, 'Tumis tahu dan tauge', 'Nikmati kelezatan Tumis tahu dan tauge dengan resep sederhana ini.', '[\"6 buah tahu putih(satu bgks)\", \"Tauge secukupnya,cuci bersih,sisihkan\", \"1 bgks saos tiram/teriyaki\", \"Cabe rawit dan cabe keriting secukupnya,iris tipis\", \"4 siung bawang merah,iris tipis\", \"2 siung bawang putih,iris tipis\", \"1/2 buah tomat,potong2\", \"secukupnya Gula dan garam\", \"secukupnya Minyak untuk menumis\"]', '[\"Goreng tahu terlebih dahulu,lalu potong kotak kecil2\", \"Tumis irisan bawang merah dan putih hingga harum kecoklatan\", \"Lalu masukan irisan cabe dan tomat,masukan saos tiram, gula dan garam.tumis hingga cabe layu\", \"Selanjutnya masukan tahu dan tauge\", \"Kasih sedikit air.test rasa.jgn terlalu matang y taugenya.done\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2313, 2, 'Tahu Isi Akhir Pekan Ala Anto', 'Kreasi tahu nikmat: Tahu Isi Akhir Pekan Ala Anto untuk variasi menu harian.', '[\"10 Buah Tahu Kuning (belah pisahkan isinya)\", \"1 Buah Wortel (Serut kasar)\", \"3 Batang Daun Bawang (Cincang Kasar)\", \"4 Lembar Kol (Iris Halus)\", \"1 Bungkus Bihun Jagung (rendam air panas tiriskan potong2)\", \"300 gr Tepung Terigu\", \"1 Sdm Tepung Serba Guna\", \"2 Sdm Tepung Beras\", \"Secukupnya Kaldu Ayam Bubuk\", \"Secukupnya Air\", \"Secukupnya Minyak Goreng untuk menggoreng\", \"Bumbu Halus :\", \"5 Siung Bawang Putih\", \"1/2 Sdt Merica Bubuk\", \"Secukupnya Garam\"]', '[\"Tumis Bumbu Halus, tumis hingga harum, lalu masukan wortel, kol dan daun bawang, setelah tercampur rata masukan bihun aduk rata kembali (Uji rasa) angkat dan sisihkan.\", \"Belah Tahu Kuning, ambil isinya (buat campuran next sayur Rebung santan kuning), Isi dengan isian yang di tumis tadi.\", \"Campur Semua tepung, beri kaldu ayam bubuk tuang sedikit demi sedikit air, aduk rata. Lalu masukan tahu yang telah diisi. Goreng tahu di minyak panas hingga matang dan berwarna kecokelatan, angkat dan tiriskan.\", \"Tahu Isi Akhir Pekan siap dihidangkan, bersama cabai atau saus sambal 😁👍\", \"Semoga bermanfaat guys 😁👌\", \"Selamat mencoba.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(2314, 4, 'Martabak tahu', 'Martabak tahu - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"8 buah tahu putih, cuci bersih dan haluskan\", \"1/4 buah kol, iris tipis\", \"1/2 buah wortel, potong dadu kecil\", \"1 Batang daun bawang, iris tipis\", \"1 butir telur\", \"1 sdt kaldu bubuk\", \"1 sdt lada bubuk\", \"Secukupnya garam\", \"20 lembar kulit lumpia\", \"Secukupnya minyak goreng\", \"Bumbu halus ::\", \"4 butir bawang merah\", \"2 siung bawang putih\", \"Adonan perekat ::\", \"3 sdm terigu + air hingga kental\"]', '[\"Siapkan wadah, campur tahu, kol, wortel, daun bawang, bumbu halus, telur, garam, kaldu bubuk, dan lada bubuk. Aduk hingga tercampur rata.\", \"Siapkan wadah, letakkan 1 - 1 1/2 sdm adonan tahu ke tengah kulit lumpia, lalu lipat dan rekatkan dengan adonan perekat. Lakukan hingga semua adonan habis.\", \"Panaskan minyak goreng, lalu masukkan satu per satu martabak tahu dan goreng hingga kuning keemasan. Angkat dan tiriskan. Sajikan hangat dengan saus sambal atau cabe rawit.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2315, 4, 'Tumis Tahu Kecap Legit', 'Tumis Tahu Kecap Legit - olahan tahu yang lezat dan bergizi.', '[\"1 papan tahu besar\", \"3 siung bawang merah\", \"3 siung bawang putih\", \"1 siung bawang bombay\", \"Cabe rawit, cabe hijau besar, cabe merah besar (sesuai selera)\", \"2 irisan tipis lengkuas\", \"3 lbr daun jeruk\", \"Saus tiram (salah satu bahan wajib)\", \"Kecap manis (saya pakai agak banyak)\", \"Kecap raja rasa (option, saya kasih sedikit)\", \"Gula merah (sedikit saja sbg pelengkap & supaya legit)\", \"Terasi (sedikit)\", \"Garam\", \"Royco\"]', '[\"Goreng tahu yg sudah dipotong-potong. Goreng sebentar saja (tidak sampai coklat di semua bagian agar bumbu & kecap bisa meresap nantinya). Angkat tiriskan.\", \"Iris bawang merah, bawang putih, bawang bombay, cabe rawit & cabe besar. Lalu tumis dgn daun jeruk & lengkuas. Setelah setengah matang masukkan gula merah, terasi (lembutkan), garam.\", \"Masukkan tahu yg sudah digoreng setengah matang.\", \"Tambahkan kecap manis, saus tiram, kecap raja rasa & royco. Masak & aduk hingga rata (jgn diberi air ya supaya legit). Cicip rasa lalu angkat & sajikan 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2316, 2, 'Oseng tahu dan sayuran', 'Resep Oseng tahu dan sayuran ala rumahan yang dijamin menggugah selera.', '[\"Tahu potong kotak\", \"1 sdm minyak utk menggoreng\", \"1 sdm minyak wijen\", \"Brokoli\", \"2 siung bawang putih, haluskan\", \"1 sdt jahe, haluskan\", \"1 sdt minyak wijen\", \"1/4 cup Kecap asin\", \"1 sdm cuka beras\", \"2 sdm gula pasir/madu / agave syrup\", \"Tepung jagung 2 sdm, di larutkan\", \"Biji wijen\"]', '[\"Panaskan minyak, beri minyak sayur dan minyak wijen, setelah panas goreng tahu, sisihkan setelah matang\", \"Panaskan wajan, masukan brokoli dan tambahkan 3 sdm kaldu sayuran, steam brokoli selama 5 menit. Sisihkan\", \"Panaskan wajan, masukan bawang putih, jahe dan minyak wijen, oseng sebentar kira2 2 menit lalu tambahkan kecap asin, cuka beras, madu/gula, tepung jagung yg sudah di larutkan. Tambahkan biji wijen dan masukan kembali tahu.\", \"Sajikan bersama nasi\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2317, 3, 'Oseng tahu \"simbah\" (sosis cambah)', 'Sajian Oseng tahu \"simbah\" (sosis cambah) yang praktis dan lezat untuk dinikmati bersama.', '[\"1 buah tahu putih\", \"1 buah sosis ayam\", \"secukupnya Cambah panjang\", \"Bumbu iris (males nguleg)😁 :\", \"6 buah cabai rawit\", \"5 siung bawang merah,\", \"4 siung bawang putih,\", \"bawang bombai,\", \"tomat\", \"Preseledri\", \"seperlunya Saori saus tiram dan merica bubuk\"]', '[\"Pertama td aku goreng tempe bumbunya biasa kayak ungkep udah pernah aku tulis diresep sebelumnya\", \"Karena bumbu masih aku buat goreng tahu yg udah dipotong dadu,sementara itu iris bumbu2\", \"Sementara sisihkan tahu lalu tumis bumbu2 seperti cabai bawang merah bawang putih bawang bombay tomat dan sosis.. setelah layu masukkan preseledri dan saos tiram\", \"Oseng2 tambahkan cambah lalu beri air sedikit.. masukkan merica bubuk penyadap rasa dan tahu\", \"Oseng kembali dan sesekali koreksi rasa,jika sudah pas matikan kompor dan siap untuk dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2318, 3, 'Tahu isi Sambal', 'Sajian Tahu isi Sambal yang praktis dan lezat untuk dinikmati bersama.', '[\"5 buah tahu kuning\", \"1/2 bks tepung bumbu serbaguna\", \"Secukupnya air\", \"Bahan Sambel:\", \"25 buah cabe rawit setan/jablay\", \"2 buah bawang merah\", \"2 siung bawang putih\", \"1/2 sdt gula pasir (kalo gak suka, bisa tak pakai)\", \"Secukupnya garam dan totole\", \"Secukupnya minyak goreng\"]', '[\"Belah tahu menjadi 2 bagian (karena saya lebih suka tipis, kalo suka tebel tidak usah dibagi 2), lalu belah lagi tengah nya tapi jangan sampai putus.\", \"Haluskan bahan untuk sambal, dan jangan lupa koreksi rasa.\", \"Beri isian sambal secukupnya kedalam tahu yg telah dibelah, ulangi sampai selesai.\", \"Buat adonan tepung jangan terlalu cair dan jangan juga terlalu kental.\", \"Panaskan secukupnya minyak goreng, lalu cemplungkan tahu ke dalam adonan tepung dan kemudian goreng sampai kuning kecoklatan, ulangi sampai selesai.\", \"Angkat dan sajikan.\", \"Tidak usah dicoel sambal pun sudah mantapss mom, bikin sambal nya yg enak aja yaaa hihii 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2319, 2, 'Tumis Tahu Sayur', 'Cara membuat Tumis Tahu Sayur yang enak dan praktis untuk keluarga.', '[\"1 tahu telur, potong2 dan goreng\", \"1 wortel, potong kotak\", \"1 ikat sawi, potong2\", \"1 batang daun bawang, iris miring\", \"2 siung bawang putih,keprek\", \"secukupnya Garam, gula, merica\", \"1 st saus tiram\", \"1 st minyak wijen\", \"1 sm minyak goreng\", \"2 sendok sayur air\"]', '[\"Tumis bawang putih hingga harum, masukkan wortel dan air\", \"Masukkan garam, gula, merica, dan saus tiram. Icipi rasanya\", \"Masukkan sawi dan dan bawang. Masak sampai sawi stengah matang.\", \"Tambahkan tahu, minyak wijen. Masak sebentar sampai air agak mengering. Angkat dan siap dihidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2320, 2, 'Tumis oyong tahu', 'Nikmati kelezatan Tumis oyong tahu dengan resep sederhana ini.', '[\"6 buah tahu goreng ukuran kecil\", \"1 buah oyong\", \"2 siung bawang merah\", \"1 siung bawang putih\", \"1 cabe hijau\", \"1 cabe merah\", \"1 sendok teri\", \"Secukupnya garam\", \"1 gelas air\"]', '[\"Potong potong tahu, cuci oyong lalu potong suka suka\", \"Iris semua bumbu, tumis bersama ikan teri sampai harum, masukkan oyong & tahu, aduk sampai setengah matang, masukkan garam & air, tutup kurleb 5 menit lalu angkat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2321, 2, 'Tahu petisan', 'Tahu petisan - olahan tahu yang lezat dan bergizi.', '[\"2 buah tahu ukuran sedang\", \"1/4 kg telur puyuh (sdh matang)\", \"Segenggam bawang daun, iris kecil-kecil\", \"1 batang serai\", \"Daun jeruk\", \"600 ml santan\", \"Bumbu yang dihaluskan\", \"Kunyit\", \"Jahe\", \"Kunci\", \"2 sdm Petis udang\"]', '[\"Potong tahu kecil kecil lalu goreng sampai matang. Sisihkan.\", \"Haluskan bumbu (saya uleg) jika sdh halus, baru dicampur petis udang.\", \"Panaskan minyak, tumis bumbu yg telah dihaluskan. Masukkan daun jeruk, sereh yang digeprek, bawang daun.\", \"Jika sudah harum, masukkan santan. Tunggu sampai baru meletup langsung masukkan tahu dan telur puyuh.\", \"Tambahkan garam dan gula. Koteksi rasa.\", \"Aduk sampai bumbu meresap ke tahu. Tips: Jangan sampai ditinggal ya pas nunggu santannya panas,biar gak pecah.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2322, 4, 'Cilok tahu goreng', 'Cara membuat Cilok tahu goreng yang enak dan praktis untuk keluarga.', '[\"2 potongTahu putih di kukus (haluskan)\", \"3 sdm Tepung terigu\", \"1 sdm tepung tapioka\", \"Bawang putih di haluskan dan daun seledri cincang halus\", \"secukupnya Royco\"]', '[\"Campur semua bahan dan ulenin trs sampai menjdi kalis biar bs di bentuk bulat2\", \"Masak air smp mendidih dan masukan adonan smp mengapung...angkat dan tiriskan\", \"Panaskan minyak dan goreng cilok dgn api kecil smp warna kekuningan....angkat dan sajikan anget2☺😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2323, 4, 'Tahu bulat crispy', 'Tahu bulat crispy - olahan tahu yang lezat dan bergizi.', '[\"5 tahu ukuran sedang\", \"2 siung bawang putih\", \"Secukupnya penyedap rasa\", \"1 sdt baking powder\"]', '[\"Cuci bersih tahu. Ini aq beli tahu pagi, aq masukin kulkas, sorenya airnya otomatis keluar sendiri. Jd gak aq peras lagi.\", \"Haluskan tahu. Campur dengan bawang putih yg dihaluskan, penyedap rasa dan baking powder.\", \"Bentuk bulat2, goreng di minyak yang panas.\", \"Tekstur nya crispy di luar, lembut di dalam. Lumer kayak tahu susu.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2324, 4, 'Tahu jungkir balik (tahu walik)', 'Buat Tahu jungkir balik (tahu walik) yang nikmat dengan langkah-langkah mudah ini.', '[\"1/4 kg ayam (pisahkan dari tulang nya)\", \"3 siung bawang putih\", \"secukupnya Pala\", \"Merica\", \"Garam\", \"Sedikit royco untuk penyedap\", \"Air mineral\", \"Tepung terigu\", \"Tepung tapioka\", \"Tahu yang sudah digoreng kotak\\\"\"]', '[\"Belah tahu seperti gambar di samping. Sisihkan\", \"Masukkan ayam, bawang putih, dan pala kedalam blender dan beri air secukupnya, tunggu hingga halus\", \"Tuang dalam baskom dan campurkan ayam yang sudah dihaluskan tadi dengan tepung terigu dan tepung tapioka 2:1 secukupnya hingga tidak terlalu encer. Lihat gambar disamping\", \"Tambahkan garam, merica, dan sedikit royco. Aduk rata dan cicipi hingga terasa pas di lidah😎\", \"Masukkan adonan pentol ke tahu yang dibalik\", \"Cara menekuk dengan benar :\", \"Balik tahu keluar, jadi bagian putih berada diluar. Bagian coklat didalam\", \"Beri adonan sedikit di bagian coklat\", \"Tekuk dari samping\", \"Tambahkan adonan lagi di atasnya (fungsi adonan pentol disini sbg lem)\", \"Tekuk menutupi adonan\", \"Ini bentuk setelah diisi. Ulangi bagian hingga adonan habis, apabila adonan tersisa banyak. Bisa di bulat\\\" dibentuk pentol dan di rebus😋😋. Atau bisa disimpan di freezer untuk.pemakaian berikutnya\", \"Goreng dengan api kecil agar matang hingga kedalam. Jangan sampai gosong😎\", \"Finally!! santap dengan saos pedas lebih maknyus😍\", \"Yuk re-cook 🤗🤗🤗😚 Dann upld disini 👇\", \"Selamat mencobaaa😚😚\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2325, 2, 'Rolade Daun Singkong dan Tahu', 'Sajian Rolade Daun Singkong dan Tahu yang praktis dan lezat untuk dinikmati bersama.', '[\"1 ikat daun singkong muda\", \"4 potong tahu kotak\", \"3 siung bawang putih\", \"1 sdt merica\", \"1 sdt garam\", \"1 butir telur ayam\", \"Bahan celup :\", \"3 sdm tepung terigu (sy pakai lemcana merah)\", \"1 sdm tepung beras\", \"1 sdt garam\", \"1 sdt merica\", \"1/2 sdt penyedap rasa (sy pakai Masako)\", \"secukupnya Air\", \"Minyak untuk menggoreng\"]', '[\"Bersihkan daun singkong yg sudah dipetik daun mudanya saja, rebus sebentar isi, tiriskan, peras hingga airnya hilang, lalu iris.\", \"Hancurkan tahu dengan garpu atau tangan, campurkan bahan2 tadi dan aduk merata dengan daun singkong yg sdh diiris.\", \"Bentuk bulat-bulat adonan tsb.\", \"Celupkan ke bahan pencelup yg sdh di aduk rata, lalu goreng dengan minyak panas\", \"Goreng sampai kuning kecoklatan, tiriskan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2326, 4, 'Soto Tahu Bening', 'Soto Tahu Bening - olahan tahu yang lezat dan bergizi.', '[\"2 tahu putih (potong dadu)\", \"Secukupnya garam\", \"Secukupnya kaldu bubuk\", \"Secukupnya gula pasir\", \"Secukupnya penyedap (optional)\", \"2 batang daun bawang\", \"1 tomat\", \"2 batang daun bawang\", \"1 daun salam\", \"2 daun jeruk\", \"1 ruas lengkuas\", \"1 serai\", \"1 jempol kunyit (geprek)\", \"Secukupnya air\", \"Bumbu halus;\", \"2 bawang putih\", \"4 bawang merah\", \"Secukupnya merica\", \"Secukupnya ketumbar\", \"Pelengkap:\", \"Secukupnya kol (rajang halus)\", \"Secukupnya tauge\", \"Secukupnya seledri\", \"Secukupnya kecap\", \"Secukupnya jeruk nipis\", \"Secukupnya cabe rebus\"]', '[\"Goreng tahu (sisihkan)\", \"Tumis bumbu halus dan kunyit geprek bersama daun salam, lengkuas, daun jeruk, sereh sampai harum.\", \"Masukkan secukupnya air, bumbui dengan garam, gula, kaldu bubuk, penyedap.\", \"Tunggu mendidih, masukkan tahu, tomat, daun bawang, seledri. Koreksi rasa.\", \"Sajikan dengan pelengkap.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2327, 3, 'Gulai Sotong isi tahu wortel', 'Gulai Sotong isi tahu wortel - olahan tahu yang lezat dan bergizi.', '[\"4 sotong ukuran besar\", \"3 buah tahu kecil (untuk isi sotong)\", \"1/2 batang wortel\", \"secukupnya Daun bawang\", \"1 santan kara kecil\", \"1 telor ayam\", \"secukupnya Gula pasir dan penyedap\", \"Bumbu Halus :\", \"6 siung bawang merah\", \"4 siung bawang putih\", \"1 kemiri\", \"2 ruas kunyit\", \"2 ruas jahe\", \"5 cabe merah\", \"Merica bubuk (sedikit saja)\", \"1/2 sdt ketumbar halus\", \"3 batang serai (keprek)\", \"3 ruas Laos (keprek)\", \"4 lembar daun jeruk (robek)\", \"2 lembar daun salam\"]', '[\"Cuci dan Bersihkan sotong dr kulitnya serta tinta.\", \"Potong wortel kecil kecil.. Daun bawang iris halus..\", \"Hancurkan tahu dgn sendok.. campurkan wortel daun bawang dan telor. aduk rata dan beri penyedap (me : masako ayam 1/2 sdt)\", \"Masukan adonan tahu ke dalam badan sotong 1/3 bagian saja. sematkan dgn tusuk gigi.\", \"Tumis bumbu halus hingga harum.. masukan santan yg sudah dicampur air 1gelas (kekentalan sesuai selera).\", \"Setelah mendidih masukan sotong. aduk aduk agar santan tdk pecah.\", \"Beri gula dan penyedap. Tes rasa. biarkan santan agak menyusut. angkat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2328, 4, 'Martabak Tahu Daging', 'Resep praktis Martabak Tahu Daging yang bisa dicoba di rumah.', '[\"Bahan:\", \"100 gr daging giling\", \"15 lembar kulit lumpia siap pakai (kali ini saya ga dobelin kulit lumpianya)\", \"1 buah bawang bombay ukuran kecil, cincang kasar\", \"3 siung bawang putih, cincang halus\", \"3 batang daun bawang, iris tipis\", \"2 butir telur\", \"1 buah tahu putih, haluskan\", \"1/2 sdt pala bubuk\", \"secukupnya Garam dan merica\", \"Kaldu bubuk secukupnya (optional)\"]', '[\"Tumis daging giling hingga berubah warna dan setengah matang\", \"Masukkan bawang bombay dan bawang putih, tambahkan pala bubuk, garam dan merica. Masak hingga harum dan daging matang. Dinginkan\", \"Setelah tumisan daging dingin, masukkan telur, tahu dan daun bawang. Tambahkan garam jika kurang asin\", \"Masukkan adonan ke dalam kulit lumpia dan lipat dengan metode lipat amplop.\", \"Goreng martabak hingga coklat keemasan\", \"Notes: Resep ini kira-kira untuk 15 buah martabak dan untuk membuat martabak ini harus langsung digoreng. Jadi setelah dibuat dan dilipat harus langsung digoreng, jika tidak, kulit lumpia akan rusak karena terkena isian dan menjadi basah\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2329, 3, 'Tumis Tahu Telur Puyuh', 'Resep praktis Tumis Tahu Telur Puyuh yang bisa dicoba di rumah.', '[\"4 kotak tahu\", \"15 butir telur puyuh (sesuai selera) yg sdh direbus\", \"3 siung bawang putih (iris tipis)\", \"4 siung bawang merah (iris tipis)\", \"1 buah cabe merah besar (iris miring)\", \"10 cabe rawit\", \"2 lembar daun salam\", \"1 buah serai geprek\", \"1 cm lengkuas geprek\", \"Secukupnya garam, gula\", \"2 sdm kecap manis\", \"2 sdm saus tiram\", \"100 ml air (secukupnya)\", \"secukupnya minyak (untuk menggoreng tahu & menumis)\"]', '[\"Iris tahu berbentuk kotak. Panaskan minyak, goreng tahu sebentar. Angkat, tiriskan.\", \"Tumis bawang putih, bawang merah dan cabe merah, cabe rawit, hingga harum. Tambahkan daun salam, serai, dan lengkuas.\", \"Tambahkan sedikit air, lalu masukkan tahu dan telur puyuh tambahkan garam, gula, saus tiram dan kecap. Cek rasa, lalu masak hingga meresap.\", \"Angkat, siap disajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2330, 4, 'Bakwan Tahu', 'Kreasi tahu nikmat: Bakwan Tahu untuk variasi menu harian.', '[\"10 pcs tahu putih ukuran sedang, haluskan dg sendok / tangan\", \"1 butir telor\", \"2 batang daun bawang\", \"1 batang daun sledri\", \"1 pcs wortel, serut kasar\", \"3 sdm tepung bakwan\", \"1 sdt garam\", \"1/2 sdt merica\"]', '[\"Campur semua bahan\", \"Bentuk bulatan2 kecil lalu goreng\", \"Siap dimakan sbg lauk\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2331, 3, 'Tahu walik super crispy', 'Tahu walik super crispy - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"10 buah tahu goreng\", \"secukupnya adonan pentol/siomay https://cookpad.com/id/resep/3356828-siomaydimsum-rambutan-goreng-1-adonan\", \"secukupnya minyak\"]', '[\"Siapkan tahu goreng, gunting sedikit salah satu sisinya kemudian buat spt kantong pada tahu lalu balik kantong tahu mnjadi yg putih diluar dan yang coklat didalam\", \"Isi kantong tahu dgn adonan pentol. goreng dgn minyak banyak dan panas, goreng hingga matang\", \"Sajikan dgn cocolan saos dsb\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2332, 2, 'Tahu campur rumahan', 'Buat Tahu campur rumahan yang nikmat dengan langkah-langkah mudah ini.', '[\"10 buah tahu\", \"Kacang tanah\", \"5 cabe rawit\", \"2 siung bawang putih\", \"Kol, seledri\", \"secukupnya Garam, gula merah, kecap\", \"Air hangat\", \"Bawang goreng\"]', '[\"Goreng tahu jgn garing banget\", \"Goreng kacang, bawang putih.\", \"Blender/uleg kacang, cabe rawit, bawang putih, garam, gula merah. Stelah halus tambah air hangat & kecap. Koreksi rasa.\", \"Tahu goreng di potong dadu, iris halus kol & seledri. Siram dg bumbu kacang aduk rata. Taburi bawang goreng. Sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2333, 4, 'Tahu Kulit Goreng Gurih', 'Resep Tahu Kulit Goreng Gurih yang lezat dan mudah dibuat di rumah.', '[\"8 buah tahu kulit, potong jadi 4\", \"1 siung bawang putih uk.sedang\", \"Secukupnya garam halus dan ketumbar bubuk\", \"15 ml air\", \"1 sdm tepung bumbu serbaguna\", \"Secukupnya minyak goreng\"]', '[\"Haluskan bawang putih, tambahkan garam, ketumbar bubuk & air. Aduk rata. Jangan lupa tes rasa..\", \"Tambahkan tahu kulit dan aduk rata diam kan sebentar. Tiriskan / peras.\", \"Masuk kan tahu kulit dlm stoples dan taburi dengan 1 sdm tepung bumbu serbaguna sampai rata dan kocok sampai tercampur rata..\", \"Goreng dlm minyak panas sampai matang.. Angkat, tiriskan dan sajikan hangat...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2334, 2, 'PIE Tahu Kacang', 'Buat PIE Tahu Kacang yang nikmat dengan langkah-langkah mudah ini.', '[\"2 kotak tahu\", \"60 gr bihun jagung\", \"2 sdm sambal pecel beli jd\", \"Secukupnya daun bawang/pre\", \"Secukupnya garam\", \"Secukupnya sambal pecel utk topping\"]', '[\"Rendam bihun dg air panas, smp empuk. Hancurkan tahu dg garpu.\", \"Campur dlm wadah, tahu, bihun, daun bawang, 2 sdm sambal pecel, garam. Aduk2 smp tercampur rata.\", \"Olesi cetakan pie dg minyak. Tuang adonan, smbl dipadatkan. Lakukan smp adonan habis. Kukus 15 menit.\", \"Biarkan dingin, keluarkan dr cetakan. Lalu goreng sebentar. Tanpa digorengpun sdh enak...\", \"Sajikan dg topping sambal pecel.\", \"Mudah dan enak bgt.. Salam.....\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2335, 2, 'Nasi uduk + sambel goreng ati ampela tahu bumbu bali', 'Cara membuat Nasi uduk + sambel goreng ati ampela tahu bumbu bali yang enak dan praktis untuk keluarga.', '[\"bahan nasi uduk :\", \"1/2 liter beras\", \"2 ruas lengkuas geprek\", \"2 lembar dau salam\", \"1 batang sere geprek\", \"1 santan kara kemasan kecil\", \"secukupnya garam\", \"bahan sambel goreng ati ampela tahu bumbu bali :\", \"5 pasang ati ampela\", \"5 buah tahu putih\", \"10 buah cabe merah kriting\", \"10 buah cabe rawit merah\", \"3 siung bawang merah\", \"1 siung bawang putih\", \"2 ruas lengkuas\", \"secukupnya gula merah\", \"secukupnya garam\", \"secukupnya kecap\"]', '[\"Potong dadu tahu lalu goreng, cuci bersih ati ampela ayam, rebus, cuci kembali potong dadu lalu goreng.sisihkan\", \"Haluskan semua bahan bumbu bali kecuali kecap, gula & daun jeruk. lalu tumis sampai harum masukan gula garam daun jeruk tumis sampai warna agak gelap.\", \"Masukan ati ampela dan tahu yg sudah digoreng, aduk2 sampai meresap. siap dihidangkan\", \"Cara membuat nasi uduk : cuci beras, masukan kedalam panci (sy menggunakan magiccom) masukan sere, daun salam, lengkuas,santan, garam dan air secukupnya. masak dalam magic com hingga matang,😘 siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2336, 2, 'Telur n Tahu Bumbu Balado', 'Kreasi tahu nikmat: Telur n Tahu Bumbu Balado untuk variasi menu harian.', '[\"6 butir telur rebus kupas sisihkan\", \"4 buah tahu putih, potong diagonal kerat2 sisihkan\", \"Bumbu halus:\", \"8 bh cabe merah keriting\", \"6 buah cabe rawit merah\", \"8 siung bawang merah\", \"4 siung bawang putih\", \"3 buah tomat merah\", \"Seruas lengkuas\", \"2 bh daun salam\", \"3 buah daun jeruk purut\", \"1 batang sereh memarkan\", \"1 sdm gula putih\", \"1 sdt garam halus\", \"bila suka Penyedap rasa\"]', '[\"Goreng telur yg sebelumnya tusuk2 putih telurnya dg garpu supaya tdk meletup2 saat digoreng.\", \"Tahu beri sedikit garam. Lalu goreng sebentar. Sisihkan.\", \"Tumis bumbu halus dg sedikit minyak. Masukkan bumbu2 daun. Aduk rata.\", \"Masukkan telur dan tahu. Beri garam, gula dan penyedap rasa. Tes rasa. Biarkan bumbu meresap dg api kecil. Angkat. Sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2337, 3, 'Angsio Tahu ala Indah', 'Sajian Angsio Tahu ala Indah yang praktis dan lezat untuk dinikmati bersama.', '[\"2 pak Tahu Telur, iris selebar 1cm\", \"1 batang wortel, iris serong\", \"3 buah bakso, iris tipis\", \"50 gram jamur kuping, iris kasar\", \"2 butir bawang putih, cincang kasar\", \"1/2 sdt garam\", \"1/4 sdt lada\", \"1/2 sdt gula\", \"2 sdm saus tiram\", \"100 ml air\", \"2 sdt tepung maizena, untuk mengentalkan\", \"3 sdm minyak, untuk menumis\"]', '[\"Goreng tahu sampai matang, angkat dan sisihkan\", \"Tumiskan bawang putih sampai harum, kemudian masukkan bakso, wortel dan jamur. Tumis sampai bakso matang\", \"Masukkan tahu beserta bumbu lainnya. Kemudian masukkan air. Tumis sekitar 3 menit.\", \"Masukkan tepung maizena yang sudah dilarutkan dengan air, kemudian tuang kedalam tumisan, aduk rata dan matikan. Angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2338, 2, 'Sapo Tahu Spesial', 'Kreasi tahu nikmat: Sapo Tahu Spesial untuk variasi menu harian.', '[\"100 gr daging sapi giling\", \"1 kuntum brokoli siangi\", \"1 biji sapo tahu iris bulet\", \"secukupnya jamur enoki\", \"1 biji bawang bombay iris tipis\", \"7 butir bawang putih cincang\", \"2 biji cabe besar iris tipis\", \"secukupnya garam, gula dan lada\", \"secukupnya saori saus teriyaki dan kecap manis\"]', '[\"Tumis bawang putih, bawang bombay, cabe besar, daging sapi dan enoki sampe layu.\", \"Lalu masukkan brokoli dan sapo tahu.\", \"Masukkan bumbu- bumbu (garam, gula,lada, saus teriyaki dan kecap manis)\", \"Aduk lalu tambah air sedikit, lalu cek rasa. tunggu beberapa saat hingga brokoli agak empuk\", \"Angkat dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2339, 4, 'Tumis sawi hijau toping tahu dan bakso', 'Nikmati kelezatan Tumis sawi hijau toping tahu dan bakso dengan resep sederhana ini.', '[\"2 ikat sawi hijau\", \"3 tahu (potong kotak2)\", \"3 bakso (potong2)\", \"2 cabe rawit julit\", \"2 bawang putih\", \"2 bawang merah\", \"seruas Lengkuas\", \"2 daun salam\", \"Secukupnya Gula garam\", \"1 sdm saus tiram\"]', '[\"Cuci bersih sawi, cabe, bawang merah bawang putih, tahu dan bakso kemudian potong2\", \"Tumis bawang merah, bawang putih sampai wangi masukan cabe lengkuas dan daun salamnya Gula Garam dan saus tiramnya (tesrasa)\", \"Kemudian masukan bakso dan tahu nya aduk2\", \"Masukan air, setelah air mendidih masukan sawi hijaunya aduk2 sampai sawi terlihat agak layu\", \"Matikan kompor\", \"Pindaahkan ke piring saji, klo saya jarang pindahin masakan ke piring saji hahhaa (jgn di ikutin yah)\", \"Udh itu aja, selamat masak selamat mencoba.. ga ada cerita perempuan ga bisa masak (masak simpel begini pasti bisa) hehee\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2340, 2, 'Soto Tahu', 'Resep Soto Tahu ala rumahan yang dijamin menggugah selera.', '[\"Tulang ayam campur dg sayapnya\", \"3-5 tahu kecil, dipotong dadu\", \"Kol dirajang kasar\", \"1 Daun bawang dirajang kadar\", \"2 tangkai Seledri dirajang kasar\", \"1 batang sereh yg besar\", \"1 daun jeruk yg agak lebar\", \"Lada bubuk\", \"Garam\", \"Penyedap\", \"🍄bumbu yg dihaluskan🍄\", \"4 siung bawang putih\", \"5 siung bawang merah\", \"5 butir kemiri\", \"Kunyit\", \"Jahe\", \"Minyak untuk menumis bumbu\"]', '[\"Masak tulang ayam sampai keluar minyak kaldunya\", \"Panaskan minyak, tumis bumbu sampai harum, lalu masukkan daun jeruk dan sereh, masak dan aduk trs sampai keluar minyak sedikit\", \"Jika sudah.. Masukkan bumbu ke dlm didihan tulang ayam td\", \"Aduk rata sampai agak mendidih, lalu masukkan tahu\", \"Bumbui dengan garam, lada bubuk, penyedap rasa ayam. Aduk kembali dan tunggu sampai mendidih lg\", \"Masukkan sayuran kol, seledri, daun bawang yg sdh dirajang\", \"Setelah mendidih kembali, matikan kompor dan siap dihidangkan😄\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2341, 2, 'Tahu Kecap Telur Puyuh', 'Tahu Kecap Telur Puyuh - olahan tahu yang lezat dan bergizi.', '[\"10 buah tahu goreng\", \"15 butir telur puyuh rebus\", \"80 gr udang\", \"6 cabai merah keriting\", \"5 cabai rawit merah\", \"3 siung bawang putih\", \"6 siung bawang merah\", \"1 buah tomat ukuran sedang\", \"1 batang bawang daun\", \"Kecap manis\", \"Kecap asin\", \"Saus tiram\", \"secukupnya Garam, gula, kaldu bubuk, merica bubuk\", \"Air\", \"Minyak goreng untuk menumis\"]', '[\"Iris duo bawang dan cabai\", \"Tumis duo bawang hingga harum, masukkan cabai, lalu masukkan tahu, udang, telur puyuh\", \"Beri air, tambahkan kecap manis, kecap asin, saus tiram\", \"Tambahkan garam, kaldu bubuk, gula, merica bubuk, koreksi rasa\", \"Masak, lalu masukkan tomat dan bawang daun yg sdh d iris sblm diangkat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2342, 3, 'Oseng-oseng Pokcoi & Tahu', 'Kreasi tahu nikmat: Oseng-oseng Pokcoi & Tahu untuk variasi menu harian.', '[\"2 ikat pokcoi\", \"1/4 tahu putih\", \"3 buah bawang putih\", \"Sedikit air\", \"secukupnya Masako, gula, lada\"]', '[\"Potong pokcoi sesuai selera,\", \"Potong tahu kotak-kotak kecil\", \"Memarkan bawang putih\", \"Goreng tahu setengah matang\", \"Panaskan minyak goreng sedikit, masukkan bawang putih tumis sampai harum baunya, lalu masukkan batang pokcoi, beri sedikit air, tumis sampai setengah matang, terus masukkan Masako, gula, lada oseng sebentar lalu masukkan daun pokcoi & tahu oseng2 sampai matang\", \"Masakan siap di hidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2343, 2, 'Tahu jaletot', 'Nikmati kelezatan Tahu jaletot dengan resep sederhana ini.', '[\"10 tahu coklat yang kosongan\", \"Cabe rawit(sesuai selera)\", \"Sayuran :\", \"Kol(iris tipis)\", \"Toge\", \"Daun bawang\", \"Seledri\", \"Dan wortel(potong korek api tipis)\", \"Garam, gula penyedap\", \"Bahan adonan:\", \"¹/4 Tepung terigu\", \"Yang dihaluskan:\", \"kunyit\", \"Ketumbar\", \"Bawang putih\", \"Kemiri\", \"Garam,gula dan penyedap\"]', '[\"Untuk adonan diatas dicampur semua.. Dan tes rasanya\", \"Lalu untuk isian campur semua bahan dan remas remas isiannya dan tes rasanya\", \"Setelah dirasa pas rasanya, mulailah mengisi isian tersebut kedalam tahu...\", \"Dan mulailah menggoreng\", \"Dan sajikan dipiring yng cantik ya bun\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2344, 4, 'Semur semuran tahu 😆', 'Cara membuat Semur semuran tahu 😆 yang enak dan praktis untuk keluarga.', '[\"10 buah tahu kulit coklat (cuci bersih)\", \"3 buah bawang merah (iris)\", \"2 buah bawang putih (iris)\", \"5 buah cabai rawit (iris serong)\", \"3 buah cabai merah (iris serong)\", \"secukupnya Lada bubuk\", \"Kecap manis\", \"secukupnya Garam\"]', '[\"Tumis bawang merah.bawang putih.dan cabai hingga layu dan harum beri sedikit air lalu masukan kecap manis juga lada aduk hingga rata\", \"Terakhir masukan tahu kedalam bumbu yg sudah di tumis masak hingga meresap. Tambahkan garam secukupnya\", \"Angkat. Hidangkan dgn nasi hangat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2345, 2, 'Sup Tahu Pedas', 'Nikmati kelezatan Sup Tahu Pedas dengan resep sederhana ini.', '[\"4 buah tahu putih/kuning\", \"125 gram fillet ayam potong dadu\", \"Telur puyuh rebus secukupnya,kupas\", \"1 buah bawang bombay iris tipis\", \"2 batang daun bawang potong2 pisahkan bagian putih dan hijau\", \"2 buah seledri potong2\", \"750 ml air\", \"2 lembar daun jeruk\", \"secukupnya Garam\", \"secukupnya Kaldu bubuk\", \"secukupnya Gula\", \"Bawang goreng untuk taburan\", \"2 sdm margarin untuk menumis\", \"Bumbu dihaluskan :\", \"8 butir bawang merah\", \"4 butir bawang putih\", \"2 butir kemiri\", \"1/2 sdt merica bubuk\", \"1 sdm ebi seduh air panas\", \"7 buah cabe kering/ sesuai selera\", \"2 buah tomat merah rebus dahulu\"]', '[\"Haluskan bumbu halus\", \"Panaskan margarin,tumis bawang bombay hingga harum\", \"Masukan bumbu halus,beri daun jeruk,tumis hingga harum\", \"Tuang air dalam panci,masukan bumbu yang sdah ditumis,biarkan hingga mendidih\", \"Masukan fillet ayam,telor puyuh,tahu yamg sudah dipotong dadu,batang daun bawang.beri gula,garam kaldu bubuk,koreksi rasa.Masak hingga bumbu meresap dan ayam empuk\", \"Masukan daun seledri,daun bawang yang bagian hijau,angkat sajikan bersama taburan bawang merah goreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2346, 4, 'Kupat Tahu Magelang', 'Kreasi tahu nikmat: Kupat Tahu Magelang untuk variasi menu harian.', '[\"Bahan Kuah:\", \"800 ml air\", \"3 siung bawang putih geprek\", \"3 lembar daun jeruk\", \"3 lembar daun salam\", \"1 ruas lengkuas geprek\", \"1 batang sereh geprek\", \"2 butir asam jawa\", \"25 gr gula jawa\", \"1 sdt gula pasir\", \"1/2 sdt garam\", \"1 sdt kecap asin\", \"2 sdm kecap manis\", \"Bahan Sambal Kacang:\", \"2 genggam kacang tanah goreng\", \"6 siung bawang putih\", \"6 buah cabai rawit merah (atau sesuai selera)\", \"Bahan isian:\", \"Kupat\", \"Tahu putih goreng\", \"Kubis rebus\", \"Tauge rebus\", \"Bakwan sayur\", \"Daun bawang atau seledri\", \"Bawang goreng\"]', '[\"Masukkan semua “bahan kuah” kedalam panci. Panaskan dengan api sedang. Aduk hingga mendidih. Matikan api. Tunggu agak dingin. Saring. Sisihkan.\", \"Uleg semua “bahan sambal kacang”. Letakkan di dalam wadah. Sisihkan.\", \"Dalam piring saji, tata semua bahan isian. Beri sekitar 1 sdm sambal kacang. Tuang dengan kuah sesuai selera. Sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2347, 3, 'Tahu Kuah Santan', 'Kreasi tahu nikmat: Tahu Kuah Santan untuk variasi menu harian.', '[\"5 butir tahu\", \"4 siung bawang merah\", \"3 siung bawang putih\", \"1 biji cabe merah\", \"5 biji cabe rawit\", \"1 bungkus santan kara\", \"2 biji kemiri\", \"Secukupnya daun bawang\", \"Secukupnya penyedap rasa\", \"Secukupnya kunyit\", \"1 sereh/serai\", \"Secukupnya daun jeruk\", \"1 (1/2 gelas) air\"]', '[\"Potong tahu menjadi dadu kecil\", \"Olek bawang merah, bawang putih, kemiri, dan kunyit\", \"Iris cabe merah, cabe rawit, dan daun bawang\", \"Tumis bumbu yang sudah dihaluskan tadi sampe harum\", \"Lalu masukkan irisan cabe merah, cabe rawit, daun jeruk serta sereh yang sudah digeprek aduk sampe rata\", \"Setelah itu baru masukkan air santan\", \"Lalu setelah itu masukkan tahu dan penyedap rasa serta daun bawang\", \"Tunggu sampe mendidih dan tahunya matang\", \"Tahu kuah santan siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2348, 2, 'Tahu goreng kriuk gurih ala lintang', 'Buat Tahu goreng kriuk gurih ala lintang yang nikmat dengan langkah-langkah mudah ini.', '[\"8 buah tahu cuci potong jd 2 sesuai selera\", \"100 grm tepung beras\", \"2 siung bawang putih\", \"1/2 sdt ketumbar (jika suka)\", \"Gula garam\", \"Sdikit kunyit (jika suka)\"]', '[\"Cuci tahu lalu potong2.\", \"Cuci bumbu lalu ulek halus..masukkan dlm wadah kmudian beri tepung beras dan air aduk2 sampai rata..adonan tepung beras dibuat yg agak encer..agar kriuk kriuk\", \"Masukkan tahu yg sdh dipotong2 ke dlm adonan..lalu goreng sampai matang dan kering\", \"Bahan sambal kacang: 2sdm kacang tanah 1/2siung bawang. 2cabe rawit cuci trs digoreng..smuax..kmudian ulek halus..beri gula garam sdkit..air dan 3sdm kecap manis aduk rata.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2349, 2, 'Cumi Asin Tahu Balado', 'Buat Cumi Asin Tahu Balado yang nikmat dengan langkah-langkah mudah ini.', '[\"1 bungkus cumi asin (rendam dengan air, lalu bersihkan isi nya)\", \"3 buah tahu putih (potong dadu)\", \"secukupnya Garam, gula, penyedap rasa\", \"-Bahan2 yang dihaluskan\", \"5 buah bawang merah\", \"2 buah bawang putih\", \"6 buah cabai merah kriting\", \"6 buah cabai rawit\", \"1 buah tomat\"]', '[\"Goreng terlebih dahulu cumi hingga kering, sisihkan\", \"Goreng tahu hingga setengah matang, sisihkan\", \"Tumis bumbu yg di haluskan, masukan gula, garam, penyedap rasa, aduk hingga rata\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2350, 2, 'Perkedel tahu ☺️', 'Cara membuat Perkedel tahu ☺️ yang enak dan praktis untuk keluarga.', '[\"4 kotak tahu ukuran sedang\", \"1 buah telur\", \"3 sdm terigu (optional)\", \"2 btang daun bawang\", \"secukupnya Garam\", \"Royco\", \"Sejumput ketumbar\", \"1 siung bawang putih\", \"Minyak untuk menggoreng\"]', '[\"Hancurin tahu smpe bner2 halus (q pake pengulekan)\", \"Haluskan bawang putih, gram, ketumbar\", \"Lalu kocok telur msukan ke tahu, campur bumbu halus, terigu, aduk hingga rata kasik royco secukupx, icipi dkit aj😊\", \"Pnaskan minyak goreng, cetak pake sendok lalu goreng,\", \"Slmat mncoba bunda👍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2351, 4, 'Tahu Tek Simple', 'Nikmati kelezatan Tahu Tek Simple dengan resep sederhana ini.', '[\"2 kotak tahu\", \"4 telur mentah\", \"3 siung bawang putih\", \"2 sdm petis berkualitas baik\", \"2 sdm selai kacang asli non gula atau tanpa tambahan lain\", \"jika suka Taoge buntut pendek,\", \"jika suka Bawang goreng,\", \"sesuai selera Cabai\", \"Secukupnya air matang, suhu ruangan\"]', '[\"Goreng tahu dan kocokan telur. Tahu digoreng hingga berkulit.\", \"Uleg bawang putih dan cabai sampai lembut\", \"Campurkan ulekan kedalam selai kacang, petis dan air matang. Aduk hingga merata.\", \"Potong-potong tahu dan telur.\", \"Tata taoge, potongan tahu dan telur diatas piring, siram dengan saus kacang-petis sesuai selera. Tambahkan bawang goreng jika suka.\", \"Siap dihidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2352, 3, 'Bakwan tahu', 'Sajian Bakwan tahu yang praktis dan lezat untuk dinikmati bersama.', '[\"2 buah tahu putih, hancurkan dgn garpu\", \"1 butir telur ayam, kocok lepas\", \"1 batang daun bawang, iris halus\", \"2 batang seledri, iris halus\", \"1 lembar daun kol, iris kasar\", \"3 sdm tepung bakwan sasa\", \"2 sdm air\", \"Sesuai selera penyedap rasa ayam\", \"secukupnya Minyak goreng\"]', '[\"Hancurkan dibaskom tahu dgn garpu kemudian masukan telur, daun bawang, seledri, daun kol, tepung bakwan sasa, penyedap rasa ayam aduk rata, tes rasa baru tambahkan air.\", \"Nyalakan kompor tuang minyak secukupnya kemajuan tunggu hingga minyak panas.\", \"Goreng adonan dgn bantuan sendok makan, goreng persendok. Goreng hingga kuning keemasan dgn api sedang, angkat, tiriskan.\", \"Siap dihidangkan. Hasil akhirnya cuma 8 buah bakwan tahu ya.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2353, 2, 'Kikil tahu cabe ijo masak kecap', 'Kikil tahu cabe ijo masak kecap - olahan tahu yang lezat dan bergizi.', '[\"250 gr kikil,cuci bersih,rebus, tiriskan,potong2 sesuai selera\", \"3 buah tahu putih, potong2 lalu goreng hingga berkulit\", \"Bumbu iris :\", \"5 buah bawang merah\", \"3 siung bawang putih\", \"3 buah cabe ijo besar, potong2 sesuai selera\", \"1 lembar daun salam\", \"1 ruas jari lengkuas, geprek\", \"2 lembar daun jeruk, buang tulang daunnya\", \"1 batang sereh, geprek\", \"4 sdm kecap manis\", \"1 sdm saos tiram\", \"1/4 sdt lada bubuk\", \"sesuai selera Garam, gula dan penyedap rasa sapi\", \"300 ml Air\"]', '[\"Cuci bersih semua bahan, sisihkan.\", \"Tumis bumbu iris yaitu bawang merah, bawang putih hingga harum lalu masukan daun salam, daun jeruk, lengkuas dan sereh aduk sebentar lalu beri air kurang lebih 300 ml biarkan mendidih.\", \"Setelah mendidih bumbui kecap manis, saos tiram, lada bubuk, garam, gula dan penyedap rasa sapi sesuai selera, aduk sebentar tes rasa.\", \"Jika sudah pas baru masukkan tahu, kikil dan cabe ijo besar, aduk terus sampai kikil dan tahu berubah warna dan air menyusut, matikan api, angkat.\", \"Pindah kemangkuk saji, siap disajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2354, 4, 'Tahu Goreng Mihun', 'Nikmati kelezatan Tahu Goreng Mihun dengan resep sederhana ini.', '[\"1 bungkus tahu\", \"Mihun yg sudah di rendam (di sesuaikan)\", \"5 siung bawang merah & bawang putih (haluskan)\", \"1/2 bungkus lada\", \"1 bungkus penyedap rasa (saya pakai masako ayam)\", \"1 buah wortel kecil potong dadu\", \"secukupnya Daun sop\", \"2 butir telur\", \"secukupnya Garam\", \"Saya memakai tambahan bakso tp tergantung selera masing2\"]', '[\"Haluskan tahu.\", \"Masukan mihun yg sudah di rendam, masukan secukupnya saja jgn sampai lebih banyak mihun drpada tahu dan aduk sampai rata.\", \"Masukan semua bahan, aduk menjadi satu.\", \"Setelah itu siapkan loyang untuk mengukus tahu, jgn lupa loyang di balurin minyak dulu supaya tahu tdk lengket setelah di angkat.\", \"Masukan adonan kedalam loyang, masukan loyang kedalam panci. Dan siap di kukus\", \"Setelah 30 menit angkat loyang dalam panci & diamkan sampai hangat.\", \"Terakhir keluarkan tahu dalam loyang, potong dadu & siap untuk di goreng hingga ke cokelatan, lalu tiriskan dan siap di sajikan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2355, 3, 'Sop Tahu Kukus Bening', 'Nikmati kelezatan Sop Tahu Kukus Bening dengan resep sederhana ini.', '[\"500 gr Tahu putih, hancurkan\", \"100 gr daging ayam cincang (saya 4 buah sosis cincang)\", \"1 buah wortel parut kasar\", \"3 batang daun bawang cincang\", \"Secukupnya merica,bawang putih bubuk, dan garam\", \"1 butir telur ayam yg besar\", \"Kuah ;\", \"1 Liter air minum\", \"Secukupnya bawang putih, merica bubuk, pala bubuk (saya pake nutmeg), garam\", \"Secukupnya bawang merah&bawang putih goreng\", \"Kaldu bubuk\", \"Tambahan;\", \"Secukupnya sayuran sesuai selera (saya pakai sawi mentah) dan wortel saya campur masak dikuah, bisa pakai daun selada\", \"Secukupnya bawang merah goreng untuk taburan\"]', '[\"Campur rata adonan tahu kemudian tata di cetakan kukusan (saya pakai kontainer kotak, lalu toping sosis&wortel ditata berjejer diatas nya). Kukus hingga matang kurang lebih 20 menit. Tunggu dingin dulu, apalagi Kalo mau dipotong pastikan benar2 dingin biar nggak hancur ☺️.\", \"Buat Kuah Kaldu. Campur kan wortel potong\", \"Penyajian ; Tata sayuran dan tahu yg telah dikukus, siram dengan kuah panas, taburi bawang merah goreng.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2356, 2, 'Batagor tahu siram saos pedas manis', 'Cara membuat Batagor tahu siram saos pedas manis yang enak dan praktis untuk keluarga.', '[\"5 sdm tepung terigu\", \"1 sdm tepung tapioka\", \"Secukupnya garam\", \"secukupnya Masako\", \"1/2 SDM margarin\", \"Tahu\", \"Untuk saos\", \"2 buah tomat\", \"1 buah bawang Bombay\", \"2 siung bawang putih\", \"Kecap\"]', '[\"Tahu iris kotak2 kecil\", \"Campur tepung terigu, tepung tapioka, garam,masako dan margarin\", \"Masukan tahu ke adonan goreng. Saya pkek margarin Krena bisa bikin tepungnya lebih kriuk\", \"Untuk saos iris2 bawang Bombay.\", \"Blender tomat cabe dan bawang putih\", \"Tumis bawang Bombay stelah hrum masukan bahan yg sudah di blender tambahkan garam gula dan Masako bila perlu jangan lupa kecapnya koreksi rasa\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2357, 4, 'Urap tahu', 'Kreasi tahu nikmat: Urap tahu untuk variasi menu harian.', '[\"5 biji tahu besar\", \"Seledri\", \"Segenggam toge\", \"Segenggam kacang tanah goreng\", \"Bumbu:\", \"1 mangkok kecil Kelapa parut kurleb\", \"2 siung bawang putih\", \"7 biji cabe rawit\", \"sedikit Garam dan gula pasir\", \"1 ruas kencur\"]', '[\"Goreng tahu lalu disobek-sobek kasar\", \"Iris seledri dan cuci toge\", \"Uleg bumbu dan campurkan dengan kelapa parut\", \"Lalu campurkan semuanya sampai merata. Cicipi.\", \"Sajikan dengan ditaburi kacang tanah goreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2358, 4, 'Tumis Sawi Tahu', 'Resep Tumis Sawi Tahu yang lezat dan mudah dibuat di rumah.', '[\"sawi\", \"wortel\", \"tahu\", \"tomat\", \"bawang merah\", \"bawang putih\", \"cabe hijau\", \"cabe rawit\", \"garam\", \"penyedap\", \"minyak\", \"telor\", \"salam\", \"laos\"]', '[\"Iris cabe dan bawang tipis,masukan irisan laos dan daun salam, tumis hingga harum. masukan telor acak hingga telor menjadi setengah matang.\", \"Masukan potongan tahu yg telah dipotong dadu, masukan jg sawi aduk dan tambahkan air secukupnya.\", \"Tambahkan penyedap, garam secukupnya. masukan tomat, aduk hingga tomat layu. lalu angkat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2359, 2, 'Tahu krispi', 'Tahu krispi - olahan tahu yang lezat dan bergizi.', '[\"Tahu\", \"Tepung kobe original\", \"Tepung terigu\", \"Minyak goreng\"]', '[\"Masukkan 5 sendok makan tepung kobe dan 2 sendok makan tepung terigu k dalam wadah yang bisa dtutup\", \"Potong tahu bentuk dadu ukuran 1x1 cm. Masukkan dalam tepung yang sudah tercampur\", \"Tutup wadah dan kocok2. Sampe semua bagian tahu tertutup tepung\", \"Panaskan minyak, pastikan semua tahu terendam, aduk2 dan goreng sampe kecoklatan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2360, 2, 'Pepes Tahu Sederhana', 'Resep Pepes Tahu Sederhana ala rumahan yang dijamin menggugah selera.', '[\"10 buah tahu kuning\", \"3 siung bawang merah\", \"3 siung bawah putih\", \"secukupnya Kemangi\", \"secukupnya Garam\"]', '[\"Hancurkan tahu dengan menggunakan garpu hingga cukup lembut.\", \"Masukkan bawang merah, bawang putih, kemangi dan garam. Aduk rata.\", \"Bungkus 1 sendok makan tahu dengan daun pisang.\", \"Kukus hingga matang.\", \"Pepes tahu siap disajikan dengan nasi hangat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(2361, 3, 'Tahu Tempe Bakar', 'Cara membuat Tahu Tempe Bakar yang enak dan praktis untuk keluarga.', '[\"Secukupnya Tahu Tempe\", \"Secukupnya Margarin+Bawang putih\", \"Bahan saus olesan:\", \"4 buah Cabe Merah\", \"4 buah Cabe Rawit Merah\", \"8 buah Cabe Rawit ijo\", \"1 sdt Merica Bubuk\", \"4 sdm Kecap Manis\", \"2 sdm Saus Tomat\", \"2 sdm Saus Cabe\", \"2 sdm Gula Merah\", \"Secukupnya Garam\"]', '[\"Oles tahu tempe dengan margarin yg sudah di campur bawang putih halus, lalu bakar setengah matang.\", \"Setelah itu oles dengan bumbu tadi yg sudah di haluskan, lalu bakar hingga matang.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2362, 4, 'Tahu cabe crispy', 'Cara membuat Tahu cabe crispy yang enak dan praktis untuk keluarga.', '[\"250 gram tahu kuning\", \"200 gram tepung terigu serbaguna\", \"4 buah cabe kriting(bisa pakai cabe rawit)\", \"2 batang daun bawang\", \"1 batang seledri\", \"2 siung bawang merah\", \"1 siung bawang putih\", \"secukupnya garam,gula, dan penyedap rasa\", \"minyak untuk menggoreng dan menumis\"]', '[\"Potong potong tahu menjadi kotak kotak kecil,lalu balurkan dengan tepung terigu\", \"Goreng tahu yang sudah dibaluri tepung terigu hingga matang,dan crispy, lalu sisihkan\", \"Tumis irisan bawang merah,putih hingga harum, lalu masukan cabe yang sudah diiris, kemudian masukan tahu crispy tadi,oseng oseng\", \"Lalu masukan irisan daun bawang,seledri, kemudian aduk, bubuhi bumbu garam,gula, dan penyedap rasa secukupnya, hati hati bubuhi bumbu sedikit sedikit saja,karena rasa tahunya sudah asin, jika bumbu sudah dirasa cukup,angkat dan sajikan\", \"Tahu cabe crispy siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2363, 3, 'Semur manis tahu tempe', 'Sajian Semur manis tahu tempe yang praktis dan lezat untuk dinikmati bersama.', '[\"1/2 papan tempe\", \"10 buah Tahu\", \"6 Bawang merah\", \"5 Bawang putih\", \"1 Kemiri sangrai\", \"Sedikit merica\", \"Gula merah\", \"Kecap\", \"Garam\"]', '[\"Potong2 tempe dan tahu kemudian goreng setengah matang\", \"Haluskan bawang merah, bawang putih, kemiri, merica, garam\", \"Tumis bumbu halus sampai harum\", \"Masukan tahu dan tempe\", \"Tambahkan gula merah, kecap dan garam sesuai selera, kemudian cek rasa\", \"Tunggu hingga bumbu meresap dan siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2364, 2, 'Oseng ampela tahu(ini sederhana bingit hihihi)', 'Nikmati kelezatan Oseng ampela tahu(ini sederhana bingit hihihi) dengan resep sederhana ini.', '[\"8 kotak tahu putih\", \"1/4 ampela utuh\", \"10 cabe\", \"4 siung bawang merah\", \"3 siung bawang putih\", \"Scukupx garam dn micin\"]', '[\"Rebus ampela smpe empuk ga ush dikasih bumnu\", \"Goreng setengah mtang tahu\", \"Ulek mentah bumbux, p\", \"Ptong2 ampela, goreng bumbu smpe matang lalu masukan tahu dan ampela ditmbh kecap juga enak bun\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2365, 2, 'Sayur Tahu Kacang Bumbu Kuning Pedassss', 'Sajian Sayur Tahu Kacang Bumbu Kuning Pedassss yang praktis dan lezat untuk dinikmati bersama.', '[\"1 ikat Kacang panjang\", \"1 potong Tahu\", \"Cabai hijau kecil\", \"Cabai merah\", \"Bawang merah\", \"Bawang putih\", \"Kemiri\", \"Kunyit\", \"Laos\", \"Daun Salam\", \"Garam\", \"Gula pasir\", \"1 sachet Royco Sapi\", \"Minyak Goreng\", \"Santan kelapa\"]', '[\"Potong potong kacang panjang dan potong dadu tahu.\", \"Rebus kacang panjang sampai setengah matang. Goreng tahu setengah matang\", \"Siapkan bumbu halus.\", \"Ulekk cabai merah, bawang merah,bawang putih, garam, kunyit dan kemiri\", \"Geprekk laoss\", \"Goreng minyakk, masukkan bumbu halus. Oseng sampai tercium baunya, masukkan laos dan daun salam. Tambah sedikit air\", \"Masukkan kacang panjang dan tahu. Masak sampai matang. Tambahkan air\", \"Masukkan santan kelapa. Aduk sampai tercampur.\", \"Tambahkan royco, sedikit garam dan sedikit gula pasir. Aduk\", \"Icipi rasa. Bila sudah matang matikan api.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2366, 4, 'Sop bakso tahu wortel buncis sederhana', 'Resep Sop bakso tahu wortel buncis sederhana ala rumahan yang dijamin menggugah selera.', '[\"10 biji bakso ukuran kecil\", \"2 buah wortel ukuran sedang kupas lalu potong sesuai selera\", \"3 buah tahu potong sesuai selera\", \"4 batang buncis potong sesuai selera\", \"4 siung bawang merah iris\", \"Secukupnya minyak untuk menumis\", \"secukupnya Air\", \"secukupnya Garam, penyedap rasa\"]', '[\"Bersihkan wortel, buncis, tahu yang sudah di potong\", \"Tumis irisan bawang merah sampai harum kemudian masukan air secukupnya\", \"Tambahkan garam, penyedap rasa aduk aduk tes rasa\", \"Masukan buncis,wortel masak sampai agak matang, masukan tahu bakso aduk sampai semua matang\", \"Sop siap di hidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2367, 2, 'Bola tahu rambutan', 'Resep Bola tahu rambutan ala rumahan yang dijamin menggugah selera.', '[\"3 buah tahu\", \"2-3 sendok makan tepung serbaguna sajiku\", \"secukupnya Lada\", \"Secukupnya garam\", \"Remukan mi (sy pake setengah keping mi telur)\"]', '[\"Hancurkan tahu hingga halus\", \"Campurkan tahu yang telah hancur dengan tepung, lada dan garam\", \"Bentuk bola-bola\", \"Gulirkan bola bola tahu dengan remukan mi\", \"Goreng hingga kecoklatan dan matang\", \"Sajikan dengan saus sambal\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2368, 4, 'Tumis Tahu Bakso', 'Sajian Tumis Tahu Bakso yang praktis dan lezat untuk dinikmati bersama.', '[\"5 bh tahu (potong kecil2)\", \"7 bh bakso (potong kecil)\", \"1 helai daun salam\", \"1 helai daun jeruk\", \"1 potong kecil jahe di keprek\", \"1 potong kecil lengkuas di keprek\", \"1 batang serei di keprek\", \"Secukupnya garam\", \"Bahan yang di rajang\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"5 bh cabe hijau panjang\", \"10 bh cabe rawit\"]', '[\"Goreng sebentar tahu\", \"Tumis bahan2 yang di rajang dan masukkan serei, lengkuas, jahe, daun jeruk dan daun salam tumis sampai harum lalu masukkan tahu dan baso aduk aduk dan beri garam dan beri sedikit air terus aduk sampai air mengering dan koreksi rasa\", \"Tumis tahu bakso siap disajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2369, 2, 'Sayur Tahu Sederhana', 'Sajian Sayur Tahu Sederhana yang praktis dan lezat untuk dinikmati bersama.', '[\"3 pcs Tahu Kuning\", \"3 pcs Wortel kecil\", \"1 siung besar Bawang merah\", \"1 Siung Bawang Putih\", \"sesuai selera Daun Bawang ()\", \"1 pcs Tomat\", \"1/2 sdt garam\", \"3/4 sdm gula  (sesuai selera)\", \"1/4 sdm Ladaku\", \"secukupnya Royco\", \"3 cangkir Air\", \"3 sdm minyak untuk tumis\"]', '[\"Cuci, Potong wortel dan tahu\", \"Iris bawang merah,putih, daun bawang, tomat. (Tumis)\", \"Didihkan Air lalu masukan sayuran setelah matang masukan tahu\", \"Masukan bumbu2 seperti garam gula royco, dan Tumisan yang tadi\", \"Cicipi Rasa dan Siap di sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2370, 3, 'Sup bola tahu (untuk anak)', 'Resep praktis Sup bola tahu (untuk anak) yang bisa dicoba di rumah.', '[\"2 buah tahu putih\", \"2 buah sosis sapi (cincang)\", \"1/4 wortel (parut dengan parutan keju)\", \"2 sdm tepung terigu\", \"1 biji telor\", \"sedikit garam (opsi)\", \"kuah :\", \"air\", \"kaldu bubuk\", \"seledri\", \"daun bawang\", \"1 siung bawang putih (cincang)\", \"garam\", \"(bisa ditambah lada tapi aku gak pakek)\"]', '[\"Hancurkan tahu, masukan tepung terigu campur sampai rata, lalu tambahkan sosis cincang, wortel parut, serta sedikit garam dan telor aduk, bentuk bulat²\", \"Rebus bola² tahu tadi (sampai mengapung, angkat) dan tiriskan\", \"Buat kuahnya, masak air dengan bawang putih cincang dan kaldu ayam sampai mendidih lalu masukan garam, seledri dan daun bawang\", \"Lalu masukan bola² tahu dan matikan api. jangan lupa tes rasa\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2371, 4, 'Perkedel tahu kuning daging crispy di luar lembut di dalam', 'Kreasi tahu nikmat: Perkedel tahu kuning daging crispy di luar lembut di dalam untuk variasi menu harian.', '[\"4 buah tahu kuning\", \"2 butir telur\", \"2 sdm daging parut di tumis hingga berubah warna\", \"3 sdm tepung tapioka\", \"1 sdm tepung terigu\", \"2 siung bawang putih yg di haluskan\", \"1 sdt bawang bombay\", \"1 sdt kaldu jamur\", \"secukupnya Merica bubuk\", \"secukupnya Daun bawang\", \"secukupnya Garam\", \"Minyak untuk menggoreng\"]', '[\"Haluskan tahu kuning, kemudian tambahkan daging yg sudah d tumis, telur, tepung terigu, tepung tapioka, bawang putih, daun bawang, kaldu jamur, merica bawang bombay, garam\", \"Aduk hingga tercampur rata kemudian bentuk bulat agak pipih\", \"Goreng hingga coklat keemasan\", \"Siap di hidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2372, 4, 'Makaroni schotel tahu kukus', 'Resep Makaroni schotel tahu kukus ala rumahan yang dijamin menggugah selera.', '[\"50 gr makaroni spiral\", \"1/2 tahu putih\", \"2 bh sosis\", \"1 btr telur ayam\", \"2 bh wortel cincang\", \"1 bh bawang bombay cincang\", \"3 bh bawang putih cincang\", \"1 bh daun bawang\", \"100 ml susu sapi murni\", \"1/2 sdt lada\", \"1/2 sdt saos tiram\", \"Secukupnya garam, gula\", \"Secukupnya penyedap rasa ro**co sapi\", \"Secukupnya keju chedar (sy pake keju mozzarella 😀)\", \"Minyak utk menumis\"]', '[\"Rebus makaroni sebentar, kasih minyak goreng biar tdk lengket\", \"Cincang wortel, daun bawang, bawang putih+ bombay, sosis jg.\", \"Tahu putih hancurkan, sisihkan\", \"Tumis bawang putih, bombay smp harum. Tmbhkan saos tiram, gula pasir, penyedap rasa. Masukkan wortel, daun bawang aduk rata. Kemudian masukkan tahu putih, aduk rata\", \"Masukkan makaroni, aduk2. Kemudian masukkan susu yg sdh dicampur telur dan lada. Aduk2, test rasa\", \"Ambil cetakan alumunium foil, masukkan kemudian taburi keju diatasnya\", \"Kukus kurleb 15 menit, hidangkan dengan saos sambal\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2373, 3, 'Telur puyuh tahu balado', 'Resep praktis Telur puyuh tahu balado yang bisa dicoba di rumah.', '[\"20 butir Telur puyuh , rebus, goreng sebentar sisihkan\", \"1 buah tahu cina potong kotak-kotak, goreng 1/2 matang sisihkan\", \"10 buah cabe keriting\", \"1 buah tomat ukuran sedang, potong kotak\", \"3 siung bawang putih\", \"5 siung bawang merah\", \"3 lembar daun jeruk\", \"1 batang sereh, geprek\", \"2 lembar daun salam\", \"1 SDM minyak wijen, skip bila tdk ada\", \"secukupnya Garam dan gula\"]', '[\"Haluskan bumbu, bawang putih, bawang merah, cabe, tumis dgn minyak wijen, jika sdh harum tambahkan sedikit air\", \"Masukkan tomat, daun jeruk, sereh, salam dan gula serta garam, koreksi rasa\", \"Jika bumbu sdh matang, masukkan telur puyuh dan tahu.., angkat dan sajikan moms 😋\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2374, 3, 'Tahu isi sayur', 'Tahu isi sayur - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"12 tahu kulit\", \"Isi tahu\", \"1 telur\", \"Daun bawang dan seledri\", \"sedikit Tepung maizena\", \"Bumbu\", \"3 bawang putih\", \"Merica\", \"secukupnya Garam\", \"Tepung terigu\", \"Tepung sajiku\"]', '[\"Tahu kulit di cuci dan di sobek tengahnya.\", \"Haluskan bumbu bawang garam merica.\", \"Potong potong daun bawang seledri. Lalu tambahkan telur tepung maizena. Kocok.\", \"Lalu masukkan adonan tadi kedalam tahu.\", \"Lalu untuk kulit luar tahu tepung terigu dan tepung sajiku. Tambahkan air sedikit.\", \"Masukkan tahu dalam adonan untuk luar tadi. Lalu goreng hingga kecoklatan. Dan bisa di sajikan. 😚😚😊👍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2375, 2, 'Pepes tahu', 'Nikmati kelezatan Pepes tahu dengan resep sederhana ini.', '[\"2 bh tahu cina/tahu putih\", \"Secukupnya kemangi\", \"1 bks masako ayam\", \"secukupnya Garam\", \"Daun salam\", \"Daun pisang utk membungkus\", \"Bumbu halus:\", \"10 cabe merah kriting+rawit\", \"5 siung bawang merah\", \"2 siung bawang putih\"]', '[\"Potong daun pisang n bersihkan\", \"Hancurkan tahu dg sendok/garpu\", \"Tumis bumbu halus smpe harum\", \"Campur bumbu dg tahu, kemangi, masako, gula pasir, garam n aduk rata\", \"Test rasa\", \"Ambil selembar daun pisang, tata daun salam n 2sdm tahunya lalu bungkus sematkan tusukgigi diujung2 bungkusan\", \"Lalukan sampe selesai lalu kukus-+30mnt\", \"Angkat dan bakar asal ja\", \"Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2376, 4, 'Tahu Goreng Tepung ala Dapur Fitri', 'Resep praktis Tahu Goreng Tepung ala Dapur Fitri yang bisa dicoba di rumah.', '[\"400 gram Tahu, potong kotak\", \"3 sdm Tepung bumbu\", \"secukupnya Air bersih\", \"5 sdm Tepung Shihlin (Tapioka kasar)\", \"5 sdm Tepung roti\", \"1/2 sdt Lada putih bubuk\", \"1/2 sdt Chicken powder\", \"Minyak untuk menggoreng\"]', '[\"Pertama tama, cairkan tepung bumbu bersama sedikit air lalu masukkan potongan tahu pada tepung kemudian balurkan pada campuran tepung roti dan tepung tapioka kasar yang sudah di bubuhi lada putih. Guling kan hinggan seluruh permukaan tahu tertutupi.\", \"Panaskan minyak lalu goreng tahu hingga matang sekitar 3 menit.\", \"Angkat dan sajikan bersama saos sambal atau cabe merah utuh.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2377, 2, '145. Sukiyaki Tahu Jamur Shimeji', 'Buat 145. Sukiyaki Tahu Jamur Shimeji yang nikmat dengan langkah-langkah mudah ini.', '[\"300 gr daging sapi, iris tipis\", \"1 bks Jamur Shimeji, cuci bersih\", \"5 bh Tahu Putih, belah 2 lalu potong 2lagi\", \"1 bh bawang bombay, iris\", \"3 btg daun bawang, iris sesuai selera\", \"iris /+1cm Jahe,\", \"2 sdm saos Teriyaki\", \"1 sdm saos Tiram\", \"1 sdm Kecap Manis\", \"Margarine untuk menumis\", \"Secukupnya garam dan lada bubuk\", \"100 ml air matang\"]', '[\"Panaskan margarine tumis bawang bombay sampai harum dan jahe lalu masukkan daging. Aduk2 daging sampai berubah warna.\", \"Tambahkan saus teriyaki, saus tiram aduk2. Lalu masukkan tahu dan jamur shimeji. Beri kecap manis. Tuang air aduk lagi. Bumbui dengan garam dan lada bubuk. Koreksi rasa. Biarkan sampai air menyusut. Masukkan daun bawang yg sudah di iris.\", \"Sajikan. Happy tummy😎\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2378, 4, 'Tahu Fantasi 🌻🌼', 'Buat Tahu Fantasi 🌻🌼 yang nikmat dengan langkah-langkah mudah ini.', '[\"10 tahu potong\", \"2 butir telur\", \"1 buah wortel besar\", \"Bihun isi 2 (dipakek satu aja)\", \"secukupnya Daun bawang\", \"4 siung bawang putih\", \"1/2 sdt merica bubuk\", \"1 sdt garam\", \"1 bungkus masakao\"]', '[\"Hancurkan tahu dengan menggunakan sendok\", \"Parut wortel menggunakan parutan keju/ bisa di iris kecil2 juga boleh\", \"Rebus bihun dan potong kecil2\", \"Masukkan parutan wortel dan bihun ke dalam tahu yang sudah dihaluskan\", \"Masukkan bawang putih yang sudah dihaluskan, garam, merica bubuk,daun bawang dan telur kemudian aduk rata. Sambil di aduk sambil di tes rasa yaa..😊\", \"Masuk kan adonan kedalam cetakan (saya pakek loyang segi empat)\", \"Kukus selama 15- 30 menit\", \"Biarkan dingin dan potong2 sesuai selera\", \"Sebelum digoreng celupkan potongan tahu ke dalam kocokan telur, lalu di guling2kan ke tepung panir\", \"Selamat mencoba..resepnya jadi banyak banget. Bisa disimpan di dalam kulkas sewaktu2 tinggal goyeng 😄\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2379, 4, 'Rolade tahu daun singkong', 'Cara membuat Rolade tahu daun singkong yang enak dan praktis untuk keluarga.', '[\"5 buah tahu putih\", \"1 ikat kecil daun singkong\", \"3 siung bawang putih\", \"secukupnya Lada dan pala\", \"Garam\", \"Penguat rasa (kalau suka)\", \"1 butir telur\"]', '[\"Daun singkong direbus,tiriskan\", \"Semua bumbu dihaluskan campur dengan tahu yang sudah dihaluskan pula\", \"Ambil selembar plastik,ratakan tahu yang telah berbumbu tadi kemudian atasnya diberi daun singkong yang telah direbus.\", \"Gulung dengan plastiknya\", \"Rapikan ujung ujungnya\", \"Dikukus kira kira 20 menit dengan api sedang\", \"Tiriskan,tunggu dingin\", \"Diiris jadi 7,masukkan ke kocokan telur(yang telah diberi sedikit garam atau penguat rasa) dan digoreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2380, 2, 'Pepes tahu gurih pake pete', 'Resep Pepes tahu gurih pake pete yang lezat dan mudah dibuat di rumah.', '[\"Tahu kepal 1 bungkus, telur bawang merah putih haluskan ketumbar dikit masako\"]', '[\"Siapkan wadah masukkan tahu, telur, bumbu di hancurkan tambahkan kemangi dan pete kalau mau bungkus daun yg sudah di bersihkan kukus sebentar atau mau di kukus aja juga gpp tp klau saya di kukus sbntar lalu bakar deh tggu bberpa menit hidangkan👌\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2381, 2, 'Perkedel tahu', 'Perkedel tahu - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"4 buah tahu putih\", \"2 batang daun bawang, iris tipis\", \"1 butir telur, kocok lepas\", \"Bumbu :\", \"2 siung bawang putih\", \"2 siung bawang merah\", \"7 biji merica\", \"secukupnya Ketumbar\", \"secukupnya Garam\", \"1/4 kelingking kunyit\", \"secukupnya Penyedap rasa\"]', '[\"Cuci bersih tahu putih lalu tumbuk kasar. Tambahkan irisan daung bawang kemudian aduk rata.\", \"Haluskan bawang merah, bawang putih, ketumbar, merica, dan garam. Campurkan bumbu halus ke dalam adonan tahu tadi. Tes rasa dan tambahkan penyedap rasa secukupnya sambil tetap di aduk-aduk agar tercampur.\", \"Masukkan kocokan telur ke dalam adonan aduk rata. Lalu bentuk adonan bulat pipih.\", \"Goreng adonan ke dalam minyak yang telah dipanaskan terlebih dahulu. Selamat mencoba..\", \"NB : enak sekali dimakan dengan nasi hangat dan sambal...\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2382, 2, 'Tahu bulat', 'Buat Tahu bulat yang nikmat dengan langkah-langkah mudah ini.', '[\"1 potong tahu\", \"Secukupnya penyedap rasa\", \"2 siung bawang putih\", \"3 siung bawang merah\", \"Secukupnya lada bubuk\", \"2 sdt baking powder\"]', '[\"Hancurkan tahu menggunakan garpu\", \"Peras tahu yang telah dihancurkan menggunakan kain bersih hingga kandungan airnya hilang\", \"Haluskan bawang merah + putih\", \"Tambahkan bumbu halus, baking powder, lada bubuk, penyedap rasa kedalam adonan tahu, lalu aduk hingga merata\", \"Masukkan telur dan aduk lagi hingga merata\", \"Bentuk bulat adonan tahu\", \"Simpan adonan dalam lemari es dalam wadah tertutup\", \"Saat akan menggoreng diamkan sampai suhu tahu = suhu ruangan\", \"Goreng hingga berwarna kecoklatan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2383, 2, 'Tahu Bakso', 'Resep Tahu Bakso ala rumahan yang dijamin menggugah selera.', '[\"500 gr daging ayam dada tanpa kulit\", \"Secukupnya tahu kulit\", \"200 tepung tapioka\", \"2 batang bawang daun\", \"5 bawang putih goreng\", \"1/2 sdt merica\", \"2 sendok garam\", \"1 sdt masako\", \"1 telur ayam\", \"1/2 sdt baking soda\", \"Secukupnya air es\"]', '[\"Bendera semua bahan dengan es batu kecuali daun bawang\", \"Jika sudah Alus masukkan daun bawang, koreksi rasanya dahalu\", \"Lubangi tahu masukkan adonan tahu bakso ke dalam tahu\", \"Kukus kurang lebih 1 jam sampai matang\", \"Dingin kan tahu bakso dan siap untuk di sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2384, 2, 'Egg Tofu / Tahu Telur', 'Cara membuat Egg Tofu / Tahu Telur yang enak dan praktis untuk keluarga.', '[\"3 buah tahu putih\", \"2 butir telur (harusnya 4)\", \"100 gr taoge\", \"1 buah tomat besar\", \"Bumbu kacang (saya pakai yg instan)\", \"Secukupnya lada + garam\", \"Minyak untuk menggoreng\"]', '[\"Cuci bersih tahu lalu potong (selera) kemudian goreng\", \"Sambil menunggu tahu matang, kocok lepas telur dengan menambhkan sedikit garam + lada (harusnya 4 butir telur biar tahunya terselimuti semua)\", \"Di teflon yg sama, siram tahu dengan kocokan telur, balik hingga matang kedua sisi, angkat dan sisihkan\", \"Rebus toge sebentar agar teksturnya masih setengah crunchy\", \"Tata diatas piring (tahu telur, toge, irisan tomat, bumbu kacang) saya lengkapi dengan emping / kerupuk melinjo\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2385, 2, 'Oseng tahu toge yummy', 'Buat Oseng tahu toge yummy yang nikmat dengan langkah-langkah mudah ini.', '[\"4 kotak tahu ukuran besar,lalu dipotong2 dadu\", \"1/4 ons toge panjang\", \"3 siung bawang putih,di cincang halus\", \"5 buah cabe rawit ukuran besar,rajang/ di iris\", \"Merica\", \"Garam\", \"Gula\", \"1 sdm saus tiram\", \"Minyak goreng secukupnya untk menumis\"]', '[\"Goreng tahu yg sdh dipotong2 dadu,kmudian tiriskn\", \"Tumis bawang putih dan cabe hingga harum,,,,masukkan toge,beri sedikit air dan tambahkan garam,gula,saus tiram,merica,,,aduk2\", \"Masukkan tahu,aduk sampai bumbu merata,,,,kemudian angkt dan sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2386, 4, 'Tumis Tahu Buncis', 'Tumis Tahu Buncis - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"5 bh Tahu Putih potong\", \"200 gr Buncis bersihkan potong2\", \"secukupnya Gula, garam\", \"50 ml Air\", \"iris Bumbu\", \"5 siung Bawang Merah\", \"3 siung Bawang Putih\", \"6 Cabe Rawit\", \"3 sdm Kecap Manis\", \"3 sdm Minyak Goreng\"]', '[\"Setelah di cuci goreng tahu hingga matang, tiriskan.\", \"Tumis bumbu iris hingga layu, masukkan Buncis hingga setengah matang tambahkan sisa bahan lainnya aduk rata, koreksi rasa. Angkat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2387, 2, 'Tahu jepang saos padang', 'Resep Tahu jepang saos padang ala rumahan yang dijamin menggugah selera.', '[\"2 bungkus Tofu\", \"1/4 kg Udang  di kupas\", \"Secukupnya Saos padang\", \"Secukupnya Saos tomat n cabe\", \"sesuai selera Cabai kecil di iris ()\", \"secukupnya Bawang bombai iris\", \"Secukupnya Bawang merah di iris\", \"Bumbu halus (\", \"5 biji cabai merah ,\", \"3 siung bawang putih\", \"Secukupnya lada , jahe\", \"Tepung maizena sdm larutkan\"]', '[\"Tumis smua bumbu,dan udang,masukan air smpai mendidih masukan tepung maizena,dan masukan tofu\", \"Hidangan siap di sajikan😉\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2388, 3, 'Tahu Cabe Garam Ala Rumahan', 'Resep Tahu Cabe Garam Ala Rumahan ala rumahan yang dijamin menggugah selera.', '[\"15 buah tahu putih, potong kotak-kotak kecil\", \"10 siung bawang merah, iris tipis\", \"8 siung bawang putih, iris tipis\", \"10 cabe merah, potong kasar\", \"5 cabe rawit, potong kasar\", \"7 lembar daun jeruk, iris tipis\", \"Secukupnya terigu\", \"Sesuai selera garam\"]', '[\"Lumuri tahu yang telah dipotong kotak kecil dengan terigu (tanpa air). Goreng. Sisihkan.\", \"Tumis bawang merah, bawang putih, cabe merah, dan cabe rawit hingga harum dan setengah layu.\", \"Masukkan tahu yg telah digoreng, daun jeruk, dan garam. Aduk hingga semua tercampur rata. Koreksi rasa. Sajikan hangat.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2389, 2, 'Toge Tahu Kecap', 'Sajian Toge Tahu Kecap yang praktis dan lezat untuk dinikmati bersama.', '[\"1 mangkuk toge segar\", \"4 bh tahu goreng (yg warna coklat)\", \"2 siung bawang putih\", \"1 bh bawang bombay ukuran kecil\", \"5 bh cabe keriting merah\", \"5 bh cabe keriting hijau\", \"3 bh cabe rawit merah\", \"1 sdm kecap manis\", \"secukupnya Garam\", \"secukupnya Gula\"]', '[\"Bersihkan toge kemudian iris semua bumbu-bumbu\", \"Setelah di iris maasukan bawang putih dan bawang bombay tumis hingga mengeluarkan aroma harum kecuali semua cabe\", \"Setelah harum tambahkan air secukupnya, semua cabe, kecap, garam, gula, dan penyedap rasa lain secukupnya aduk hingga rata\", \"Tuangkan toge beserta tahu kedalam bumbu\", \"Toge Tahu Kuah Kecap siap di hidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2390, 4, 'Martabak tahu #DariPengenJadiBisa', 'Buat Martabak tahu #DariPengenJadiBisa yang nikmat dengan langkah-langkah mudah ini.', '[\"Kulit lumpia\", \"1 butir putih telur untuk lem kulit\", \"1/2 kg minyak goreng\", \"Bahan isian :\", \"10 ptg tahu ukuran sedang (haluskan/ dibenyek2 dengan sendok)\", \"1 butir telur ayam\", \"2 batang seledri dan daun bawang (cincang)\", \"4 siung bawang putih giling\", \"3 siung bawang merah giling\", \"1/2 sdt merica bubuk (optional)\", \"1 sdt garam\", \"1 sdt kaldu bubuk\"]', '[\"Campurkan semua bahan isian\", \"Bungkus kedalam kulit lumpia sesuai keinginan, tutup dan lem menggunakan telur\", \"Goreng dengan api sedang hingga kecoklatan.\", \"Angkat dan tiriskan.\", \"Siap disajikan dengan saos atau kuah kecap pedas bersama acar 😍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2391, 4, 'Tahu Bulat Unyu', 'Kreasi tahu nikmat: Tahu Bulat Unyu untuk variasi menu harian.', '[\"20 potong tahu putih kecil\", \"1 butir telur\", \"2 sdt baking powder\", \"Secukupnya garam\", \"Secukupnya penyedap\", \"Secukupnya sambal untuk cocolan :P (Saya lbh suka pakai B*ncabe)\"]', '[\"Peras tahu sampai kandungan airnya seminimal mungkin.\", \"Jika sudah diperas, tambahkan baking powder, garam dan penyedap. Aduk sampai rata (langsung pakai tangan).\", \"Jika sudah rata, tambahkan telur. Aduk sampai rata kembali.\", \"Selanjutnya bisa langsung dibentuk bulat-bulat sesuai selera. Kalau saya lebih suka dibentuk kecil-kecil.\", \"Kalau sudah dibentuk bulat-bulat. Silakan simpan di dalam lemari es kurleb 1 jam dalam wadah tertutup.\", \"Sebelum digoreng diamkan dulu tahu bulat yang baru dikeluarkan dari lemari es hingga suhunya sama dengan suhu ruangan.\", \"Goreng sampai kecoklatan. Sajikan ketika masih hangat, dicocol sambal juga lebih nikmat. Kalau saya dicocol B*ncabe =) Selamat mencoba ;)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2392, 4, 'Martabak tahu, telur, kornet', 'Cara membuat Martabak tahu, telur, kornet yang enak dan praktis untuk keluarga.', '[\"Kulit lumpia jadian\", \"2 butir telur\", \"1 tahu putih besar,hancurkan\", \"1 kaleng kornet\", \"3 siung bawang merah\", \"2 siung bawang putih\", \"3 batang daun bawang iris\", \"secukupnya Garam, merica, penyedap rasa\", \"Bahan perekat:\", \"Campur 1 sdm terigu dgn sedikit air hingga mengental\"]', '[\"Tumis duo bawang, masukkan telur lalu orak arik\", \"Masukkan tahu dan kornet, aduk rata\", \"Beri garam, penyedap rasa dan merica aduk rata. Jgn lp koreksi rasa\", \"Terakhir masukkan daun bawang, aduk rata kembali. Matikan api dan biarkan sampai dingin\", \"Bila sdh dingin, ambil kulit lumpia lalu beri adonan secukupnya.\", \"Gulung atau bungkus sesuai selera. Dan rekatkan\", \"Lakukan sampai adonan habis\", \"Goreng dgn api kecil hingga coklat keemasan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2393, 4, 'Tumis Tahu Orak Arik kemangi', 'Cara membuat Tumis Tahu Orak Arik kemangi yang enak dan praktis untuk keluarga.', '[\"1 bks tahu\", \"2 ikat kemangi\", \"10 buah cabai rawit\", \"3 buah cabai merah keriting\", \"2 siung bawang putih\", \"1 buah tomat kecil\", \"secukupnya gula jawa\"]', '[\"Ulek tahu sampai halus\", \"Iris bawang merah,bawang putih,cabai & tomat (ga pake ulek biar simple)\", \"Potong daun kemangi lalu cuci\", \"Tumis semua bumbu yg sudah di iris\", \"Masukan daun kemangi oseng sebentar\", \"Lalu masukan tahu yg sudah di ulek\", \"Beri sedikit air, koreksi rasa\", \"Tunggu sampai air menyusut\", \"Tumis orak arik siap di hidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2394, 2, 'Bola-bola Tahu', 'Bola-bola Tahu - olahan tahu yang lezat dan bergizi.', '[\"1 bungkus Tahu Cibuntu (isi 10)\", \"1 buah wortel, potong dadu\", \"1 butir telur\", \"3 siung bawang putih, parut\", \"2 batang seledri, cincang\", \"3 sdm tepung terigu\", \"Secukupnya garam, lada bubuk dan kaldu jamur\"]', '[\"Cuci bersih tahu, rebus dan tiriskan. Lumatkan dengan garpu.\", \"Potong wortel bentuk dadu-dadu kecil, cincang daun seledri dan parut bawang putih. Masukkan ke wadah tempat tahu yang sudah dilumatkan. Aduk rata, kemudian masukkan telur dan terigu. Tambahkan garam, lada bubuk dan sedikit kaldu jamur.\", \"Simpan adonan dalam kulkas sekitar 30 menit agar nanti mudah dibentuk.\", \"Persiapan menggoreng: ambil adonan, bentuk seperti bola kemudian goreng hingga coklat keemasan.\", \"Sajikan hangat, bisa untuk lauk atau camilan :)\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2395, 4, 'Sayur tahu aku', 'Sajian Sayur tahu aku yang praktis dan lezat untuk dinikmati bersama.', '[\"Tahu kuning 10 (potong segitiga)\", \"2 Santan kara\", \"Salam\", \"Laos\", \"Garam\", \"Gula\", \"sasa\", \"Royco rasa sapi\", \"Minyak buat menumis\", \"Air secukup nya\", \"Bumbu2 :\", \"10 Cabe keriting\", \"5 Cabe rawit\", \"10 Bawang merah\", \"5 Bawang putih\", \"3 Kemiri\", \"Kunyit seruas jari\"]', '[\"Goreng tahu\", \"Halus kan semua bumbu kemudian tumis sampai matang...masukan garam gula sasa..tambahkan daun salam dan laos\", \"Kemudian masukan tahu...tambah kan air...biar kan sampai mendidih...\", \"Kemudian masukan santan kara...aduk perlahan sampai tahu meresap..tambah kan royco\", \"Setelah tahu meresap matikan kompor\", \"Jadi deh tahu sayur nya\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2396, 3, 'Tahu Jeletot 😋', 'Resep praktis Tahu Jeletot 😋 yang bisa dicoba di rumah.', '[\"10 pcs Tahu Pong\", \"Secukupnya Minyak Goreng\", \"Bahan Adonan\", \"Secukupnya Tepung Terigu\", \"Secukupnya Air\", \"Secukupnya Penyedap Rasa (Royco Ayam)\", \"Secukupnya Lada Bubuk (biar ada rasa pedas)\", \"Sesuai Selera Bahan Isi :\", \"3 buah Wortel (di iris kecil)\", \"Secukupnya Kol (di iris kecil)\", \"1 batang Daun Bawang (di iris kecil)\", \"Secukupnya Penyedap Rasa (Royco Ayam)\", \"15 buah Cabe Rawit Merah\", \"1 siung Bawang Putih\", \"Sedikit Garam\", \"Sedikit Air\"]', '[\"Buat bahan isinya dulu, Ulek Cabe rawit merah, bawang putih, dan Garam. Kemudian tumis hingga harum dan kasih sedikit air kemudian masukan wortel, Kol, Daun Bawang dan penyedap rasa, aduk hingga harum dan matang\", \"Iris Tengah Tahu Pong kemudian masukkan bahan yang sudah di tumis ke dalam tahu\", \"Untuk adonan pelengkapnya, campurkan semua bahan Adonan aduk hingga mengental lalu celupkan satu persatu tahu yang sudah di masukan isiannya, lalu di goreng\", \"Jika sudah matang, angkat dan sajikan di piring, makan selagi hangat lebih enak dan maknyosss 😋😁\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2397, 2, 'Simply Deliciously Tahu Gejrot', 'Buat Simply Deliciously Tahu Gejrot yang nikmat dengan langkah-langkah mudah ini.', '[\"10 keping tahu pong\", \"2 keping gula jawa (setengah kepingan besar)\", \"Asam jawa\", \"1 1/2 sendok makan cuka\", \"2 siung bawang putih\", \"secukupnya Cabai rawit hijau\", \"secukupnya Garam\"]', '[\"Potong-potong tahu pong\", \"Untuk membuat saus gejrot, larutkan cuka, gula Jawa dan asam jawa agak lama hingga agak legit/berkaramel\", \"Haluskan bawang putih, cabai rawit, dan garam\", \"Letakkan tahu pong yang sudah dipotong-potong, letakkan sambal halus di atasnya, lalu siram dengan saus gejrot\", \"Sajikan. Bisa diberi taburan bawang merah goreng untuk menambah cita rasa\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2398, 2, 'Tahu campur yamiii', 'Cara membuat Tahu campur yamiii yang enak dan praktis untuk keluarga.', '[\"3 buah tahu kotak putih goreng setengah matang pot dadu\", \"2 lbr kubis putih iris halus\", \"3 sdm tauge besar rendam air panas bentar tiriskan\", \"1/2 ketimun pot dadu kecil\", \"1 buah tomat merah pot tipis\", \"1 sdm bawang goreng\", \"2 sdm kecap manis\", \"Bahan yg dihlskan :\", \"5 buah cabe rawit\", \"1 buah cabe besar merah\", \"2 siung bawang merah\", \"2 sdm kacang tanah yg sdh di goreng\", \"1/2 sdt terasi matang, gula jawa, garam, royco\", \"1 siung bawang putih,air panas\"]', '[\"Goreng dulu cabe dan bawang merah seblm dihlskan\", \"Haluskan cabe, bawang merah yg sdh di goreng td bersama bawang putih mentah tambahkan kacang goreng, gula jawa, trasi,garam,royco tambahkan air panas 1/2 gelas icip rasa....sisihkan\", \"Siapkan ke dlm piring tahu yg sdh digoreng, diatasnya beri kubis iris, atasnya tauge matang, ketimun iris, tomat iris, siram atasnya dg bumbu yg sdh dihlskan tadi tambahkan kecap manis diatasnya n bawang goreng....hmmmm nikmat....yamiii....selamat mencoba...😄😄😄\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2399, 3, 'Tahu fantasi', 'Tahu fantasi - olahan tahu yang lezat dan bergizi.', '[\"5 tahu putih haluskan\", \"1 buah wortel serut\", \"1 keping bihun jagung\", \"1 tangkai daun bawang, sledri iris tipis\", \"1 butir telur\", \"1 sachet masako\", \"secukupnya Garam, merica\", \"2 siung bawang putih, haluskan\", \"Bahan lapisan:\", \"1 butir telur kocok\", \"2 sdm tepung tapioka\", \"secukupnya Garam merica\", \"2 sdm air\"]', '[\"Rendam bihun dalam air panas sampai lunak.tiriskan.potong kecil2\", \"Campur tahu yang sudah halus dengan wortel serut,bihun jagung,irisan daun bawang & sledri.aduk rata.\", \"Beri Masako,garam, merica, bawang halus.aduk rata.tes rasa.\", \"Tambahkan telur.aduk rata kembali\", \"Tuang adonan ke dalam cetakan kue talam.lakukan sampai habis.kukus adonan selama 15 menit.\", \"Setelah 15 menit angkat adonan.biarkan agak dingin keluarkan dari cetakan.biarkan Sampai benar2 dingin\", \"Campur adonan lapisan.lalu celupkan tahu ke adonan lapisan.goreng dalam minyak panas hingga kuning keemasan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2400, 4, 'Batagor tahu', 'Batagor tahu - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"2 kotak tahu putih\", \"1 telur ayam\", \"1/4 terigu\", \"5 siung bawang putih\", \"bawang daun\", \"1 bungkus bumbu pecel\", \"garam,marica\"]', '[\"Hancur kan tahu sampai lumet\", \"Kemudian halus bawang putih,garam dan marica d ulek atau d beleder\", \"Setelah d ulek / d blender campurkan dengan tahu,terigu,telor dan bawang daun sampai merata\", \"Panaskan minyak goreng lalu bentuk adonan dengan menggunakan sendok lalu goreng hingga warna ke emasan\", \"Setelah matang angkat dan tiriskan kan\", \"Bumbu pecel d tambahkan air panas biar encer jika kurang pedas tambah cabe yang sudah d ulek campurkan dengan bumbu pecel yang d campur air aduk hingga rata\", \"Setelah itu potong potong potong tahu yang d goreng lalu balur. Kan dengan bumbu pecel,batagor siap d sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2401, 3, 'Tumis tahu saus tiram', 'Tumis tahu saus tiram - olahan tahu yang lezat dan bergizi.', '[\"5 buah tahu coklat segitiga\", \"4 siung bawang merah\", \"2 siung bawang putih\", \"2 buah cabe hijau besar\", \"1/2 buah tomat buang bijinya\", \"1 sachet Saori saus tiram\", \"2 sdm Kecap manis\", \"5 sdm air matang\", \"secukupnya Gula Dan garam\"]', '[\"Cuci bersih tahu peras airnya lalu potong2\", \"Iris bawang merah, Bawang putih, cabe hijau Dan tomat\", \"Tumis bumbu yang telah diiris\", \"Masukkan tahu, saus tiram, Dan kecap manis\", \"Tambahkan air\", \"Tambahkan gula Dan garam secukupnya.\", \"Aduk2 cicipi bila rasa sdh pas diamkan sebentar hingga air agak surut\", \"Siap dihidangkan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2402, 2, 'Martabak GEHU (TOge taHU)', 'Kreasi tahu nikmat: Martabak GEHU (TOge taHU) untuk variasi menu harian.', '[\"1 buah tahu putih besar\", \"1 buah telur\", \"Daun bawang sucukupnya\", \"secukupnya Toge\", \"Cabe, bawang putih, & bawang merah dihaluskan untuk menumis\", \"15 buah Kulit lumpia siap pakai\"]', '[\"Hancurkan tahu putih dengan menggunakan garpu\", \"Panaskan minyak untuk menumis\", \"Masukkan bumbu menumis yang telah dihaluskan\", \"Tambahkan telur, lalu di urak arik\", \"Tambahkan tahu yang telah dihancurkan\", \"Masukkan toge dan daun bawang, lalu koreksi rasa\", \"Angkat dan taruh diwadah\", \"Siapkan 15 buah kulit lumpia\", \"Masukkan isiian tahu kekulit lumpia, lipat sesuai selera (boleh ditambahkan cabe jika suka pedas)\", \"Setelah dilipat, goreng diminyak panas\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2403, 4, 'Tahu siram jamurr', 'Tahu siram jamurr - olahan tahu yang lezat dan bergizi.', '[\"1 bungkus tahu belah jd 2 lalu potong jd 2 lg\", \"2 buah dada ayam fillet(potong kotak)\", \"1/4 udang cincang\", \"secukupnya Jamur kuping hitam\", \"potong dadu Jamur hokyo yg kering(direndam air panas)\", \"Bumbu tumis\", \"1/2 bulatan Bawang bombay\", \"3 buah bawang putih cincang\", \"2 batang daun bawang iris tipis\", \"3 buah cabe merah besar iris serong\", \"secukupnya Air\", \"2 sdm maizena larutkn dgn sedikit air\", \"Gula\", \"Garam\", \"Merica\", \"4 sdm Saus tiram\", \"Penyedap rasa ayam\", \"Minyak u / menggoreng dan menumis\"]', '[\"Goreng tahu terlebih dahulu hingga matang, sisihkan, dan tata diatas piring / mangkuk\", \"Tumis bawang bombay,bawang putih hingga harum, masukan daging ayam dan udang, aduk rata\", \"Kemudian masukan bawang daun dan cabai hingga layu\", \"Lalu masukan jamur kuping dan hokyo. Aduk rata,\", \"Masukan air secukupnya, dan tambahkan gula,garam,merica,penyedap rasa dan saus tiram\", \"Tes rasa dulu ya😀jika rasa udah pas. Masak jamur sampai empuk\", \"Kalo udah empuk, masukin lalrutan maizena,aduk rata\", \"Dan yg trakhir, siramkan tumisan jamur tadi di atas tahu yg sudah ditata dan digoreng.\", \"Selesai dehhh😁😁\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2404, 3, 'Tumis Toge Tahu Simple', 'Resep Tumis Toge Tahu Simple ala rumahan yang dijamin menggugah selera.', '[\"100 gram toge (buang akar, cuci bersih)\", \"2 buah tahu kuning (saya pake tahu bandung, gurihhhh...), cuci bersih, potong kecil\\\" sesuai selera\", \"1 siung bawang putih, iris tipis\", \"1 batang daun bawang, iris serong\", \"1/2 buah tomat, iris, buang bijinya\", \"4 butir cabe rawit setan, iris serong\", \"1/2 sdt garam\", \"1/2 std merica bubuk\", \"1/2 sdt gula pasir\", \"100 ml air matang\", \"2 sdm minyak goreng\"]', '[\"Siapkan bahan utama\", \"Siapkan bahan yg diiris\", \"Panaskan minyak\", \"Goreng tahu sebentar saja\", \"Masukkan bawang putih, tumis hingga bawang harum\", \"Masukan cabe rawit\", \"Masukan air\", \"Masukan garam, merica, gula\", \"Masukan toge, tumis sebentar\", \"Sesaat sebelum kompor dimatikan, masukan tomat dan daun bawang\", \"Tumis toge tahu simple siap disajikan..👌👌👌\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2405, 4, 'Martabak Tahu Kulit Pangsit', 'Cara membuat Martabak Tahu Kulit Pangsit yang enak dan praktis untuk keluarga.', '[\"1 buah Tahu cina besar\", \"1 sachet Kornet\", \"1 btr Telur\", \"Daun bawang, iris halus\", \"Kulit pangsit\", \"Penyedap rasa\", \"Garam\"]', '[\"Haluskan tahu dengan garpu, lalu masukkan kornet, telur, daun bawang, penyedap rasa dan garam. Aduk rata.\", \"Ambil selembar kulit pangsit, kemudian isi dengan 1 sendok adonan tahu, lipat. Goreng dengan minyak panas. Angkat dan sajikan dengan sambal botol.\", \"Tips : goreng dengan minyak panas, kalo sudah agak coklat baru balik, dan jangan terlalu banyak dibolak balik agar tidak makan minyak. Bisa juga dengan variasi isiian lainnya ya.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2406, 4, 'Nugget sayur tahu', 'Resep praktis Nugget sayur tahu yang bisa dicoba di rumah.', '[\"2 lembar kubis\", \"3 buah wortel\", \"100 gr kecambah\", \"1 buah tahu\", \"2 batang daun bawang\", \"2 siung bawang\", \"100 gr tepung kanji\", \"100 gr tepung terigu\", \"1 sachet penyedap rasa\", \"1/2 sdt garam\", \"2 butir telur\", \"300 gr tepung panir\"]', '[\"Potong tipis wortel, kubis, dan daun bawang\", \"Hancurkan tahu, peras airnya\", \"Kocok telur, masukkan tahu potongan sayur dan kecambah. Aduk rata\", \"Tambahkan garam, penyedap, tepung terigu dan tepung kanji\", \"Siapkan loyang, olesi margarin, beri kertas roti. Tuang adonan kira kira hingga tingginya 2 cm\", \"Kukus kurang lebih 20 menit.\", \"Diamkan hingga dingin (bisa di masukkan di freezer), aku naruhnya semalam. Bisa secepatbya asal udah dingin\", \"Potong bentuk stick. Kocok telur, dan siapkan tepung panir. Goreng\", \"Sajikan dengan saus tomat atau sambal kecap\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2407, 2, 'Tumis tahu yahuut 😂', 'Resep praktis Tumis tahu yahuut 😂 yang bisa dicoba di rumah.', '[\"5 buah tahu kuning\", \"5 lembar cesim\", \"2 siung bawang merah\", \"1 siung bawang putih\", \"1 cabe merah besar\", \"1 cabe ijo besar\", \"Secukupnya gula pasir,garam,saos teriyaki,ladaku\"]', '[\"Potong dadu tahu, dan goreng setengah matang lalu tiriskan\", \"Iris\\\" baper,bawang putih,cabe merah cabe hijau dan cesin\", \"Tumis bumbu yg sudah diiris lalu masukan cesin + tahu\", \"Tambahkan air sedikit, masukan saus teriyaki, garam, gula pasir dan ladaku\", \"Icip rasa kalau sudah pas lalu hidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2408, 4, 'Martabak Tahu sambel kacang', 'Buat Martabak Tahu sambel kacang yang nikmat dengan langkah-langkah mudah ini.', '[\"3 buah tahu kuning\", \"1 butir telor ayam\", \"1 bungkus bumbu pecel kacang sinti\", \"secukupnya Kulit lumpia\", \"secukupnya Bawah daun\", \"secukupnya Merica\", \"secukupnya Penyedap\"]', '[\"Cuci tahu lalu tiriskan\", \"Setelah di tiriskan tumbuk tahu hingg hancur\", \"Masukan telor aduk rata\", \"Masukan bawang daun yg sudah di iris dan semua bumbu penyedap secukupnya aduk merata\", \"Masukan adonan ke dalam kulit lumpia cetak menjadi persegi empat\", \"Goreng hingga kecoklatan\", \"Martabak tahu siap di nikmati\", \"Untuk sambalnya larutkan bumbu sinti dengan air panas secukupnya\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2409, 3, 'Tahu jeletot', 'Resep Tahu jeletot yang lezat dan mudah dibuat di rumah.', '[\"2 bungkus Tahu pong\", \"4 buah wortel\", \"200 gram toge\", \"10 buah cabe rawit merah potong halus\", \"1/2 sacseht bumbu ayam indofood\", \"1/2 sendok teh gula pasir dan garam\", \"Bahan tepung\", \"5 sendok tepung beras\", \"15 sendok tepung terigu\", \"1/2 sendok garam\", \"1/2 sacshet bumbu racik tempe indofood\"]', '[\"Minyak goreng sedikit untuk menumis masukan wortel dan toge lalu masukan bumbu ayam indofood, gula dan garam, cabe tumis hingga matang\", \"Tahu pong dibelah pinggir na kemudian isi dengan sayuran yang ditumis tadi\", \"Campur tepung beras, terigu, garam dan tepung racik tempe beri air secukupnya\", \"Masukan tahu ke adonan tepung lalu goreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
INSERT INTO `menus` (`menu_id`, `user_id`, `title`, `description`, `ingredients`, `instructions`, `image_url`, `status`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(2410, 2, 'Tahu Melotot 👀', 'Tahu Melotot 👀 - hidangan lezat yang cocok untuk berbagai kesempatan.', '[\"4 buah tahu putih\", \"Bahan Isian:\", \"3 buah tahu putih (hancurkan)\", \"1 buah wortel (potong kotak kecil)\", \"Bumbu Halus:\", \"2 buah cabe merah keriting\", \"10 buah cabe rawit / sesuai selera tingkat kepedasan\", \"2 siung bawang putih & 3 siung bawang merah\", \"Secukupnya garam dan gula pasir\", \"Bahan Lapisan Tepung:\", \"2 ons tepung terigu\", \"1 siung bawang putih\", \"1/2 ruas kunyit\", \"1/2 sdm garam / sesuai selera\", \"secukupnya Air putih\"]', '[\"Potong 4 tahu putih masing-masing menjadi 4 bagian, kemudian goreng. Setelah digoreng iris bagian tengahnya. Sisihkan\", \"Membuat isian:\", \"Haluskan semua bumbu halus, kemudian tumis hingga harum dan matang\", \"Beri sedikit air, lalu masukkan wortel yang sudah dipotong kotak-kotak kecil\", \"Setelah wortel matang, masukkan 3 buah tahu yg sudah dihancurkan. Tambahkan garam dan gula. Aduk hingga merata. Koreksi rasa. Sisihkan\", \"Masukkan isian ke dalam tahu yang sudah diiris bagian tengahnya\", \"Membuat adonan tepung:\", \"Haluskan kunyit dan bawang putih. Kemudian campurkan dengan tepung terigu dan garam. Tambahkan sedikit air hingga mengental, jangan terlalu encer\", \"Masukkan tahu yang sudah diberi isian ke dalam adonan tepung. Kemudian goreng hingga kuning keemasan\", \"Tahu melotot ready to serve now 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2411, 3, 'Sambal goreng tahu kulit', 'Sambal goreng tahu kulit - olahan tahu yang lezat dan bergizi.', '[\"1 bungkus tahu kulit\", \"Bumbu halus:\", \"3 cm jahe\", \"5 cm lengkuas\", \"3 siung bawang putih\", \"5 siung bawang merah\", \"7 buah cabai merah\", \"4 butir kemiri\", \"1 sct kecap manis\", \"Garam, penyedap\", \"Air\"]', '[\"Tahu kulit potong-potong sesuai selera.\", \"Panaskan minyak. Tumis bumbu halus sampai harum dan kecoklatan.\", \"Tambahkan 100 ml air. Tambahkan kecap, garam dan penyedap. Koreksi rasa.\", \"Masukkan tahu. Aduk rata. Masak sampai air meyusut. Angkat siiap disantap.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2412, 3, 'Tahu Aci Tegal', 'Cara membuat Tahu Aci Tegal yang enak dan praktis untuk keluarga.', '[\"8 tahu putih, iris diagonal\", \"2 batang daun bawang iris tipis\", \"2 sdm tepung terigu\", \"3 sdm tepung tapioka\", \"1 btr telur ayam, kocok lepas\", \"Secukupnya garam\", \"Secukupnya air panas\", \"Secukupnya penyedap\", \"Secukupnya minyak untuk menggoreng\", \"🌰Bumbu halus:\", \"3 siung bawang putih\", \"1 sdt merica bubuk\", \"1 sdt ketumbar\"]', '[\"Kerok sedikit bagian tengah tahu yg sudah dipotong melintang. Sisihkan\", \"Campurkan sisa kerok tahu dgn terigu, tepung tapioka, daun bawang, penyedap, garam,dan bumbu halus. Campur rata, lumatkan sedikit dengan air panas.\", \"Masukkan adonan isi ke dalam tahu yg sudah dikerok.\", \"Gulingkan dlm kocokan telur. Goreng sampai keemasan. Angkat, tiriskan.\", \"Jadii deehhh Tahu Aci Tegalnya 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2413, 4, 'Martabak Tahu Pedas', 'Resep Martabak Tahu Pedas yang lezat dan mudah dibuat di rumah.', '[\"1 buah tahu cina besar\", \"3 buah sosis ayam (iris kecil)\", \"2 butir telur\", \"30 lembar kulit lumpia\", \"Secukupnya daun bawang (iris)\", \"4 siung bawang merah (iris)\", \"1 sdt bubuk bawang putih\", \"3 sdm bon cabe (sesuai selera)\", \"1 blok bubuk kaldu ayam\"]', '[\"Hancurkan tahu menggunakan garpu.\", \"Masukkan semua bahan kecuali kulit lumpia.\", \"Cek rasa\", \"Taruh adonan diatas kulit lumpia. Lipat seperti amplop.\", \"Goreng di minyak panas dengan api sedang. Goreng hingga kecoklatan. Jika ingin gorengan tidak menyerap minyak. Saat menggoreng, martabak jangan dibolak balik. Cukup sekali balik saja.\", \"Sajikan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2414, 4, 'Pepes tahu makyuuuss', 'Sajian Pepes tahu makyuuuss yang praktis dan lezat untuk dinikmati bersama.', '[\"10 buah tahu/ bleh tahu apa saja\", \"2 butir Telor ayam\", \"2 ikat Daun kemangi\", \"10 lembar Daun salam\", \"Serai 2 batang potong2 y\", \"Dan daun pisang buat membungkus nya\", \"Bahan yg di haluskan:\", \"5 siung Bawang merah\", \"4 siung Bawang putih\", \"5 buah Cabe merah\", \"10 buah Cabe rawit\"]', '[\"Haluskan semua bumbu bisa di ulek /di Belender sperti, cabe merah, cabe rawit, bawang merah, bawang putih y\", \"Lalu lumat / hancurkan tahu dengan garpu y bun\", \"Masukan smua bumbu yg sudah di haluskan ke dalam wadah tahu, lalu aduk sampai menyatu dengan bumbu nya\", \"Lalu masukan jg telor, kemangi, daun salam jg serai yg sudah di potong2 tdi y\", \"Tambahkan garam jg penyedap rasanya, lalu bunda koreksi rasanya.. Sekiranya sudah pas dan cukup\", \"Lalu bungkus dengan daun pisang trus di Kukus dalam panci selama 30 menit y bun\", \"Setelah 30 menit matang, lalu bisa di panggang nya dengan wajan beri minyak 1 sendok teh...ulangi terus sampai selesai y bun\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2415, 2, 'Tumis Tahu Kecambah', 'Buat Tumis Tahu Kecambah yang nikmat dengan langkah-langkah mudah ini.', '[\"10 buah Tahu\", \"1/4 kg Kecambah\", \"4 buah Cabe hijau\", \"3 siung Bawang putih\", \"4 siung Bawang merah\", \"secukupnya Garam\", \"Air untuk kuah\", \"Penyedap rasa\"]', '[\"Potong dadu tahu\", \"Cincang cabai, bawang putih dan bawang merah\", \"Tumis bumbu\", \"Beri sedikit air agar tidak gosong\", \"Masukkan tahu dan kecambah\", \"Tambahkan garam dan penyedap rasa secukupnya\", \"Tes rasa\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2416, 2, 'Pokcoy Tahu Manis', 'Kreasi tahu nikmat: Pokcoy Tahu Manis untuk variasi menu harian.', '[\"2 ikat pokcoy... Pisahkan tiap lembarnya\", \"5 buah tahu, potong dadu\", \"Segenggam jamur kuping basah, iris sesuai selera\", \"1/2 buah paprika hijau, potong dadu\", \"1/2 buah paprika merah, potong dadu\", \"1/2 buah paprika kuning, potong dadu\", \"3 siung bawang putih, cincang\", \"3 buah cabai rawit, iris\\\"\", \"1 sdm saus tiram\", \"1 sdm kecap manis\", \"200 ml air\", \"Secukup nya garam\", \"Secukupnya gula\", \"Secukupnya lada bubuk\", \"1 sdm maizena larutkan dengan sedikit air\", \"Minyak goreng\"]', '[\"Didihkan air, rebus pokcoy sebentar aja ya... Tiriskan dan tata di piring\", \"Panaskan minyak... Lalu goreng tahu hingga berkulit. Sisihkan\", \"Panaskan lagi sedikit minyak lalu tumis bawang putih, paprika, tahu, dan jamur\", \"Masukkan saus tiram dan kecap manis.. Tambahkan air masak hingga air mendidih dan sedikit berkurang..\", \"Lalu masukkan larutan maizena.. Tambahkan garam gula dan lada... Koreksi rasa\", \"Setelah matang siramkan tumisan ke atas pokcoy...\", \"Dan siap di sajikan 😄\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2417, 3, 'Perkedel Tahu (renyah di luar, lembut di dalam)', 'Nikmati kelezatan Perkedel Tahu (renyah di luar, lembut di dalam) dengan resep sederhana ini.', '[\"3 bawang putih\", \"3 bawang merah\", \"1 sachet ladaku bubuk\", \"3 buah tahu (sesuai selera)\", \"secukupnya Garam\", \"secukupnya Gula\", \"Daun bawang (boleh pakai kucai)\", \"3 sdm Tepung sasa serbaguna hot and spicy\"]', '[\"Haluskan bawang putih, bawang merah, gula, garam\", \"Setelah halus, tambahkan tahu kemudian haluskan kembali\", \"Selanjutnya tambahkan 1 sachet ladaku dan iris kucai sesuai selera\", \"Tambahkan 3 sdm tepung sasa serbaguna, aduk hingga rata, terakhir di goreng deh kak\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2418, 3, 'Fuyung Hai Tahu', 'Kreasi tahu nikmat: Fuyung Hai Tahu untuk variasi menu harian.', '[\"1 buah tahu putih\", \"3 batang wortel kecil (serut)\", \"4 butir telor\", \"2 batang daun bawang\", \"secukupnya Gula\", \"secukupnya Lada\", \"secukupnya Garam\", \"Saus :\", \"2 buah bawang bombai\", \"Saus tomat\"]', '[\"Kocok lepas telor, beri garam dan lada. Masukkan tahu yang sudah dihancurkan dan wortel yang sudah diserut dan potongan daun bawang. Aduk rata.\", \"Ambil pan teflon atau snack maker beri sedikit margarine. Masukkan kira-kira 2 sendok makan adonan. Biarkan sebentar hingga matang lalu balik. Angkat.\", \"Kupas bawang bombai, potong dan tumis dengan sedikit margarine. Tambahkan air, saus tomat, gula, garam dan lada. Tes rasa. Angkat.\", \"Sajikan fuyung hai dan saus asam manisnya. Selamat makan 👌👍\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2419, 2, 'Rolade Tahu Simple', 'Resep Rolade Tahu Simple yang lezat dan mudah dibuat di rumah.', '[\"3 siung bawang merah\", \"2 siung bawang putih\", \"1 btr telur\", \"1 bh wortel cincang kotak2\", \"secukupnya Tahu\", \"secukupnya Minyak goreng\", \"100 gr terigu\", \"secukupnya Masako, gula garam\"]', '[\"Tumis bawang merah bawang putih\", \"Masukan ke blender tahu, bawang merah bawang putih yg di tumis, tmbahkan telur\", \"Blender sampai halus, tambahkan tepung trigu, masako, gula garam, plus campuran wortel cincang\", \"Taruh diwadah kukus sampai matang\", \"Apabila matang siap dihidangkan, bisa lgsg di makan atau di goreng\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2420, 4, 'Tahu bakso ga ribet', 'Resep Tahu bakso ga ribet yang lezat dan mudah dibuat di rumah.', '[\"1/4 kg daging ayam tanpa kulit dan tulang iris kecil2\", \"1 putih telur nya sj\", \"3 atw 4sdm  tepung tapioka\", \"Bawang putih dihaluskan\", \"Sdkit  merica dan kaldu jamur\", \"Sdkit  air es\", \"10 buah tahu berkulit belah satu sisi\"]', '[\"Masukan daging ayam yg diiris kecil ke chopper jg putih telur dan bumbu sdkit air es giling sampe halus\", \"Taruh adonan daging dlm wadah tambahkan tapioka aduk rata\", \"Siapkan tahu berkulit potong salah satu sisi kemudian tekan2 dlmnya baru isi adonan bakso lakukan sampe tahu habis\", \"Panaskan kukusan masukan tahu kukus sampai matang kurleb 20menit\", \"Tahu bs lgsg di makan atw digoreng terlebih dahulu tergantung selera..monggo😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2421, 4, 'Bola bola tahu telur puyuh simple', 'Sajian Bola bola tahu telur puyuh simple yang praktis dan lezat untuk dinikmati bersama.', '[\"10 pc telur puyuh\", \"4 pc tahu\", \"1 telur ayam\", \"Royco ayam\", \"Tepung roti atau panir\"]', '[\"Rebus telur puyuh smpai matang dan kupas kulitnya\", \"Tahu di ancurkan di campur royco ayam\", \"Bulat2 tahu isi dengan telur puyuh\", \"Lumuri dengan tepung roti\", \"Goreng hingga warna jd agak coklat\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2422, 2, 'Oseng\"jamur,kerang,tahu (jakerta)', 'Resep Oseng\"jamur,kerang,tahu (jakerta) yang lezat dan mudah dibuat di rumah.', '[\"1/2 kg jamur\", \"4 bj tahu besar\", \"1/4 kerang\", \"5 siung bawang putih\", \"4 btr bawang merah\", \"10 btr merica\", \"1 batang bawang daun\", \"1 ruas jari laos\", \"10 bji cabe kecil\", \"1 btr tomat\", \"secukupnya Kecap\", \"secukupnya Gula\", \"secukupnya Garam\"]', '[\"Goreng tahu\", \"Suwar suwir jamur\", \"Bersihkan kerang\", \"Siapkan bawang putih,bawang merah,merica,gula,garam, dan haluskan\", \"Potong\\\"bawang daun dan tumis bersama bumbu yg sdh dihaluskan\", \"Setelah berbau harum, masukkan jamur,tahu,kerang,irisan tomat,cabe kecil dan laos\", \"Beri gula,kecap dan garam secukupnya,setelah rasanya mantap sajikan untuk hidangan makan siang keluarga\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2423, 4, 'Lumpia isi tahu', 'Resep Lumpia isi tahu ala rumahan yang dijamin menggugah selera.', '[\"20 lbr Kulit lumpia\", \"1 buah tahu ukuran besar (tahu gede)\", \"2 batang daun bawang\", \"1 ikat daun seledri\", \"Secukupnya kol\", \"1 bks royko ayam\", \"secukupnya Garam, penyedap\", \"1 sdt lada bubuk\", \"10 biji rawit merah\", \"1 butir telur\", \"Putih telur untuk kulit lumpia\"]', '[\"Hancurkan tahu, iris kol daun bawang & seledri, lalu ulek cabe rawit campur semua bahan aduk rata\", \"Siapkan kulit lumpia lalu lipat dan rekatkan ujung nya oles dgn putih telur. lalu goreng sampai kecoklatan dan tiriskan\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2424, 4, 'Tahu Aci asik', 'Sajian Tahu Aci asik yang praktis dan lezat untuk dinikmati bersama.', '[\"14 biji tahu kuning\", \"2 siung Bawang putih\", \"1500 Daun bawang beli di pasar\", \"Garam\", \"sejumput Ketumbar\", \"Royco\", \"Minyak goreng\", \"1 biji wortel ukuran sedang\", \"3 sdm tepung beras\", \"2 sdm tepung sagu\"]', '[\"Cuci bersih tahu kuning..Langkah awal potong tahu menjadi 2 bagian berbentuk segituga.. lalu kerok bagian tengah tahu, usahakan tahu tidak terkoyak pinggirannya\", \"Uleg halus 2siung bawang putih ketumbar dan garam...lalu haluskan hasil Kerokan bagian tengahnya..campurkan dg bumbu halus..\", \"Setelah bumbu halus & tahu bagian tengah sudah tercampur, iris daun bawang dan beri parutan wortel\", \"Setelah langkah 3 maka tambahkan 3sdm tepung beras dan 2sdm tepung sagu.. lalu campurkan dg air sedikit.. (jangan terlalu encer ya.. nanti susah menempel di tahu)\", \"Setelah smua tercampur.. lalu taruh adonan (aci) kedalam tahu yg sudah di kerok tengahnya tadi... taruh di freezer kurang lebih 1jam agar menempel sempurna.. setelah itu bisa digoreng kapan saja..\", \"Panaskan minyak goreng dg api kecil.. masukkan tahu sesuai yg diinginkan,jangan dibolak balik biar tidak hancur... jika satu sisi sudah terlihat kecoklatan baru dibalik..\", \"Sajikan selagi hangat..\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2425, 4, 'Bola bola tahu isi sosis (simple)', 'Cara membuat Bola bola tahu isi sosis (simple) yang enak dan praktis untuk keluarga.', '[\"2 buah tahu putih\", \"seledri (iris halus)\", \"1 buah sosis sapi\", \"1 biji telor\", \"garam\", \"lada\", \"kaldu ayam\", \"serbuk roti\"]', '[\"Hancurkan tahu sampai halus, masukan garam, lada, kaldu ayam, seledri, dan telor\", \"Potong sosis (aku potong bulat)\", \"Bentuk tahu dan isi dengan sosis dan balurkan dengan serbuk roti\", \"Panaskan minyak dan goreng dengan api sedang\", \"Makan dengan sambel kecap rawit juga endesss banget hihii\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2426, 4, '348. Tumis Selada Air Tahu Wijen', 'Nikmati kelezatan 348. Tumis Selada Air Tahu Wijen dengan resep sederhana ini.', '[\"1 bh tahu cina, potong kotak 1.5x1.5, goreng\", \"200 grm/1 ikat selada air, potong-potong\", \"Bumbu-bumbu:\", \"3 siung bawang putih, cincang halus\", \"3 siung bawang merah, iris tipis\", \"1 bh kecil bawang bombay, iris tipis\", \"1 bh cabe merah, iris serong\", \"5 cabe rawit merah, iris kecil\", \"1 bh tomat, potong dadu besar\", \"1 sdm saus tiram\", \"1 sdm saus tomat\", \"1/2 sdt garam dapur\", \"1/2 sdt gula pasir\", \"1/2 sdt minyak wijen\", \"1/2 sdt wijen sangrai\", \"2 sdm minyak sayur untuk menumis bumbu\"]', '[\"Siapkan dan timbang bahan sesuai resep.\", \"Tumis bawang dan cabe sampai harum, masukkan tomat, selada air, dan semua sisa bumbu kecuali minyak wijen. Aduk rata.\", \"Tuang sedikit air, masak selada hingga layu.\", \"Masukkan tahu dan minyak wijen, aduk rata.\", \"Tes rasa, kalau sudah cukup taburkan wijen. Angkat.\", \"Dan ini hasilnya, Tumis Selada Air Tahu Wijen siap disajikan...😋\", \"Selamat mencoba!😊\", \"Happy cooking...😋😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2427, 4, 'Cah cesim tahu putih sosis', 'Cah cesim tahu putih sosis - olahan tahu yang lezat dan bergizi.', '[\"1 ikat caesim/sawi hijau\", \"2 kotak tahu putih\", \"2 sosis ayam\", \"3 bawang putih\", \"3 bawang merah\", \"Secukupnya gula\", \"1 sdm saos tiram\", \"1 sdm tepung maizenna\"]', '[\"Cuci bersih sawi dengan air mengalir kemudian potong2 sesuai selera. Potong dadu tahu putih, kemudian rendam cucu dengan air matang. Iris miring sosis.\", \"Potong atau geprek bawang putih dan iris bawang merah untuk menumis.\", \"Panaskan minyak di teflon, tumis bumbu yg sudah di iris hingga harum dan layu, kemudian masukan tahu,sosis lalu masukan saos tiram, lada, garam kemudian tes rasa.\", \"Masukan sawi hijau, dan masukan maizenna yg sudh dilarutkan dengan air setengah gelas. Kemudian aduk rata hingga mengental, kemudian tiriskan atau hidangkan.\", \"Selamat mencoba dan selamat makan. Happy cooking 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2428, 2, 'Tahu Thek Ramah Anak', 'Tahu Thek Ramah Anak - olahan tahu yang lezat dan bergizi.', '[\"2 telur ayam\", \"1 tahu putih, potong dadu\", \"2 siung bawang putih\", \"4 sdm kacang tanah goreng\", \"1/4 sdt garam\", \"1/4 sdt gula\", \"2 sdm kecap.manis\", \"Taoge dan mentimun\"]', '[\"Dadar telur seperti biasa, letakkan diatas piring\", \"Goreng potongan tahu, tiriskan, letakkan diatas dadaran telur\", \"Rebus taoge, tiriskan, taburkan diatas telur dadar dan tahu\", \"Bumbunya: haluskan kacang tanah matang, bawang putih, letakkan di mangkuk, tambahkan garam gula kecap dan air hangat sesuai selera\", \"Siramkan bumbu.kacang diatas sajian Tahu Thek tadi\", \"Selamat.mencoba\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2429, 3, 'Risoles tahu bakso', 'Cara membuat Risoles tahu bakso yang enak dan praktis untuk keluarga.', '[\"isi risoles :\", \"4 buah tahu putih\", \"6 buah bakso\", \"1/4 wortel\", \"1/2 bawang bombay\", \"1 helai daun bawang\", \"Adonan kulit risoles :\", \"100 gr tepung terigu serbaguna\", \"250 ml susu full cream milk\", \"1 SDM margarine / butter\", \"1 buah telor\", \"1/4 SDT garam\", \"100 gr tepung panir / breadcrumbs\"]', '[\"Siapin bahan isi risoles\", \"Siapin bahan untuk bikin kulit risoles.\", \"Rebus dulu tahu dan bakso\", \"Potong kecil2 daun bawang, bakso dan bawang bombay, tahu di geprek halus, wortel di parut. Mix well\", \"Di tumis pakai sedikit minyak, tambahin garam dan lada putih. Kemudian pindahkan ke wadah.\", \"Sekarang buat kulit risoles. Tuang tepung terigu, susu full cream, telor dan aduk pakai \\\"mixer\\\" biar rata.\", \"Kalo sudah halus mixing nya, cairkan margarine dan tambahkan garam ke dalam adonan. Mix well.\", \"Untuk bikin kulit risoles, pakai teflon frypan agar tidak nempel. Kalo pakai panci biasa oleskan minyak pakai kuas. Tuang adonan pakai centong dikit dikit. Dan biarkan mateng. Trus angkat. Jangn terlalu lama. Nanti gosong. 1 menit cukup.\", \"Semua bahan udah siap. Isi risoles dengan bahan yang sudah di tumis. Dan guling lipat. Kemudian celupkan dalam adonan basah (sisa dari adonan kulit risoles)\", \"Masukan risoles yg sudah di olesin adonan basah kedalam tepung panir. Kemudian goreng dalam minyak panas. Jgn lupa di bolak balik ya. Tiriskan.\", \"Risoles untuk jadi cicipan awal sudah jadi. Hehe.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2430, 3, 'Klotokan ikan asin mix tahu', 'Kreasi tahu nikmat: Klotokan ikan asin mix tahu untuk variasi menu harian.', '[\"2 ekor ikan asin klotok\", \"1 buah tahu\", \"2 bawang putih\", \"5 bawang merah\", \"5 cabe ijo\", \"Secukup nya camba alle\", \"1 tomat\", \"1 cabe merah\", \"10 cabe rawit\", \"1 laos\", \"Sedikit terasi\", \"Kecap manis\", \"Royco ayam\", \"Daun bawang secukup nya\"]', '[\"Iris tahu dan ikan asin menjadi kotak kotak\", \"Iris2 juga bumbu yg lain nya\", \"Goreng tahu terlebih dahulu setengah mateng\", \"Tumis bawang putih, bawang merah, tomat, laos, terasi hingga harum\", \"Masuk kan ikan asin, cabe ijo dan alle beri sedikit air\", \"Masukan tahu, cabe rawit, cabe merah. Kasih royco dan kecap manis aduk2 incipi rasa\", \"Kalau sudah pass baru masukan daun bawang\", \"Angkat lalu sajikan 😀😀\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2431, 4, 'Tumis tauge tahu', 'Sajian Tumis tauge tahu yang praktis dan lezat untuk dinikmati bersama.', '[\"5 buah tahu putih\", \"5 ons tauge\", \"5 siung bawang merah\", \"3 siung bawang putih\", \"5 biji cabai rawit merah (sesuai selera pedasnya)\", \"Secukupnya royco\", \"Secukupnya garam\", \"1/2 bungkus saori saus tiram\", \"Secukupnya air\", \"1 buah kemiri\"]', '[\"Potong-potong tahu dan goreng, sisihkan\", \"Iris bawang merah, cincang bawang putih, iris cabai.\", \"Uleg kemiri\", \"Tumis bawang merah, putih, kalau sudah harum masukkan cabai dan kemiri.\", \"Masukkan tahu, tauge, garam, royco, saori saus tiram.\", \"Tambahkan air secukupnya.\", \"Tes rasa, jangan biarkan tauge terlalu matang.\", \"Kalau sudah pas rasanya, angkat. Sajikan.\", \"Semoga bermanfaat 😊\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2432, 3, 'Oseng tahu cabe gendot ala fe\'', 'Resep praktis Oseng tahu cabe gendot ala fe\' yang bisa dicoba di rumah.', '[\"1 bungkus cabe gendot (isi sekitar 10 buah)\", \"3 buah tahu potong 4\", \"Bumbu halus :\", \"5 siung bawang merah\", \"4 siung bawang putih\", \"3 biji kemiri sangrai\", \"1/2 sendok teh garam\", \"1 sendok makan gula merah\", \"6 sendok makan kecap manis\", \"500 ml air\", \"1/2 sendok teh kaldu bubuk jika suka\"]', '[\"Cuci bersih cabe gendot. Jangan buang tangkainya. Belah ujungnya. Tumis bumbu halus hingga harum lalu beri air, gula merah, garam, kecap, kaldu bubuk instan. Koreksi rasa. Aduk hingga agak menyusut airnya.\", \"Masukkan cabe gendot & tahu. Rebus hingga mendidih & bumbu terserap. Jika air sudah berkurang, matikan kompor. Hidangkan.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07'),
(2433, 4, 'Tahu rumahan,sehat untuk buah hati😘', 'Kreasi tahu nikmat: Tahu rumahan,sehat untuk buah hati😘 untuk variasi menu harian.', '[\"4 butir telor\", \"bakso\", \"Wortel\", \"daun bawang\", \"Lada bubuk\", \"Penyedap rasa ayam\"]', '[\"Potong dadu wortel dan bakso(sesuai selera\", \"Iris daun bawang\", \"Buat dalam 1 tempat\", \"Masukan 4 butir telor\", \"Penyedap dan lada bubuk(sesuai selera\", \"Kocok lepas dalam 1 tempat sampai semua teraduk rata\", \"Beri 1 sendok makan minyak goreng,lalu aduk kembali\", \"Diamkan 3 menit\", \"Lalu kukus,bisa juga di rebus\", \"Setelah di kukus,lalu dinginkan yaa nanti dia mengembang\", \"Lebih baik di kukus agar mengembang secara sempurna\", \"Setelah dingin potong potong sesuai selera\", \"Lalu siap di goreng dan di sajikan\", \"Langsung di makan tanpa di goreng juga tidak masalah.\"]', 'https://asset.kompas.com/crops/MZ_KjUJ4rxuZmCX1-_Kk3XplKyU=/32x0:1000x645/1200x800/data/photo/2022/02/11/62062e047e908.jpg', 'approved', NULL, '2025-12-12 09:25:07', '2025-12-12 09:25:07');
